SET NAMES utf8mb4;\nINSERT INTO mezmur_sync_counter (id, current_version) VALUES (1, 0) ON DUPLICATE KEY UPDATE current_version=0;\n\nINSERT IGNORE INTO mezmur_categories (id, title_am, title_om, title_en, parent_id, sort_order) VALUES\n(1, 'የአምላክ ዝማሬያት', NULL, NULL, NULL, 1),\n(2, 'የእመቤታችን ዝማሬያት', NULL, NULL, NULL, 2),\n(3, 'የቅዱሳን መላእክት ዝማሬያት', NULL, NULL, NULL, 3),\n(4, 'የጻድቃንና የሰማዕታት ዝማሬያት', NULL, NULL, NULL, 4),\n(5, 'የንሰሐ ዝማሬያት', NULL, NULL, NULL, 5),\n(6, 'የሕፃናት ዝማሬያት', NULL, NULL, NULL, 6),\n(7, 'የበገና ዝማሬያት', NULL, NULL, NULL, 7),\n(8, 'የክብረ በዓላት ዝማሬያት', NULL, NULL, NULL, 8),\n(9, 'የበዓላት ዝማሬያት', NULL, NULL, NULL, 9),\n(10, 'የሰርግ ዝማሬያት', NULL, NULL, NULL, 10),\n(11, 'የሰንበት ት/ቤቱ ቁ1 አልበም ዝማሬያት ', NULL, NULL, NULL, 11),\n(12, NULL, 'Kan Goofta', NULL, NULL, 12),\n(13, NULL, 'Kan Durbee Maariyaami', NULL, NULL, 13),\n(14, NULL, 'Kan Ergamoota', NULL, NULL, 14),\n(15, NULL, 'Kan Qulqulloota', NULL, NULL, 15),\n(16, NULL, 'Kan Ayyaana', NULL, NULL, 16),\n(17, 'ህዳር ጽዮን (ህዳር 21) ዝማሬያት ', NULL, NULL, 8, 17),\n(18, 'አስተርዮ (ጥር 21) ዝማሬያት', NULL, NULL, 8, 18),\n(19, 'ሰኔ 21 ዝማሬያት', NULL, NULL, 8, 19),\n(20, 'አቡነ ተክለ ሃይማኖት (ነሐሴ 24) ዝማሬያት', NULL, NULL, 8, 20),\n(21, 'የአዲስ ዓመት ዝማሬያት', NULL, NULL, 9, 21),\n(22, 'የመስቀል ዝማሬያት', NULL, NULL, 9, 22),\n(23, 'የልደት ዝማሬያት', NULL, NULL, 9, 23),\n(24, 'የጥምቀት ዝማሬያት', NULL, NULL, 9, 24),\n(25, 'የሆሳዕና ዝማሬያት', NULL, NULL, 9, 25),\n(26, 'የትንሳዔ ዝማሬያት', NULL, NULL, 9, 26),\n(27, 'የጰራቅሊጦስ(በዓለ ሃምሳ) ዝማሬያት', NULL, NULL, 9, 27),\n(28, 'የደብረ ታቦር (ቡሄ) ዝማሬያት', NULL, NULL, 9, 28),\n(29, NULL, 'kan ciidhaa', NULL, NULL, 29),\n(30, NULL, 'kan fannoo gooftaa', NULL, 16, 30),\n(31, NULL, 'kan dhaloota', NULL, 16, 31),\n(32, NULL, 'kan cuuphaa', NULL, 16, 32),\n(33, NULL, 'kan hosa''inaa', NULL, 16, 33),\n(34, NULL, 'kan du''aa ka''umsaa', NULL, 16, 34),\n(35, NULL, 'kan ayyaana tabor', NULL, 16, 35),\n(36, NULL, 'kan ciidhaa', NULL, NULL, 36),\n(37, 'የበዓታ ለማርያም (ታህሳስ 3)', NULL, NULL, 8, 37),\n(38, 'የቅዱስ ሚካኤል ዝማሬያት', NULL, NULL, 8, 38),\n(39, 'የቅዱስ ገብርኤል ዝማሬያት', NULL, NULL, 8, 39),\n(40, 'የኪዳነ ምህረት ዝማሬያት', NULL, NULL, 8, 40),\n(41, 'የቅዱስ ሩፋኤል ዝማሬያት', NULL, NULL, 8, 41),\n(42, 'የቅዱስ ዮሐንስ መጥምቅ ዝማሬያት', NULL, NULL, 8, 42),\n(43, 'የቅዱስ እስጢፋኖስና የጽጌ ዝማሬያት', NULL, NULL, 8, 43),\n(44, 'የቅዱስ ቂርቆስ ዝማሬያት', NULL, NULL, 8, 44);\n\nINSERT INTO mezmurs (category_id, title, content, language, sort_order, sync_version) VALUES\n(1, 'በዘባነ ኪሩብ', 'በዘባነ ኪሩብ\n\nበዘባነ ኪሩብ ለሚቀመጠው\nበእሳት ድንጋዮች ቅጥሩን ላጠረው\nዘምሩ ለእግዚአብሔር ለጌታ ዘምሩ\nየተከበረ ነው በሰማይ በምድሩ (2)\n\nአዝ፦\nኢሳይያስ ሲያየው እጅግ አፈረ\nየተፈራ ነው የተከበረ\nየሰማይ ደጆች ተንቀጠቀጡ\nለቅዱስ ስሙ ክብርን ሲሰጡ\n\nአዝ፦\nያልተቀደሰ ለምጽ ያነደደው\nእንዴት ይችላል ሊያመሰግነው\nበል ፍቀድልኝ ፍቅር ነህና\nልግባ መቅደስህ ላቅርብ ምስጋና\n\nአዝ፦\nዙፋንህ ታየኝ ትምክህቴ ሆይ\nስትመሰገን በሰማይ ላይ\nሲያመሰግንህ ያልተደሰተ\nባይተዋር አልሁን አልውጣ ካንተ\n\nአዝ፦\nቅኔ የሞላበት ያን ሰገነት\nልቀላቀለው ተመኘው በእውነት\nልዘምርልህ ባይገባኝም\nዝም የሚል ልሳን አልሰጠኸኝም\n', 'am', 1, 0),\n(1, 'ያላንተ ጌታ', 'ያላንተ ጌታ\n\nያላንተ ጌታ ደስታ መች አለ\nያላንተ አምላኬ ህይወት መች አለ\nስምህን ጠርቶ የተማጸነ\nከእሳቱም ወጣ ከሞትም ዳነ\n\nአዝ፦\nእጆቼን ይዘህ አንተ እየመራ\nስንቱን አለፍኩት ስንቱን መከራ\nለካስ ሲያልፍ ቀን ሁሉም ይረሳል\nረሀብ ስደቱን ማን ያስታውሳል\n\nአዝ፦\nፅዋዬን ባርከህ ተትረፈረፈ\nየጠላቴም ጦር በላይ አለፈ\nበሺ ቃላቶች አፌን ሞልቼ\nልዘምርልህ ጉያህ ገብቼ\n\nአዝ፦\nገዳዬ ቢሮጥ በቀን በማታ\nእያለ አንድዬ እያለ ጌታ\nለሞት አልተኛም ይደነቅ አለም\nተክሎኛልና ለዘለአለም\n\nአዝ፦\nምስጋና ሆኖ ምግቤ መጠጤ\nተቀጣጠለ ፍቅርህ በውስጤ\nአላቀረቅር አልደፋ አንገቴን\nእሞላዋለው በእልልታ ቤቴን\n', 'am', 2, 0),\n(1, 'የሰማይም የምድርም ጌታ', 'የሰማይም የምድርም ጌታ\n\nየሰማይም የምድርም ጌታ\nበዝቶልናል እጅግ ስጦታ\nበጎነትህ ቸርነትህ\nእረድቶናል ክቡር ስምህ\n\nበማይዝሉ ጽኑ ክንዶችህ\nተደገፍን በቸርነትህ\nየፍቅር አባት ላመኑህ ጥላ\nክርስቶስ ነህ የእኛ ከለላ\n\nፍፁም ቆምን በንጹህ ደምህ\nተፈወስን በቅዱስ ቃልህ\nመዛል ድካም ከቶ አይነካንም\nኃይላችን ነው ሁሌም የአንተን ስም\n\nያጣው ሲጮኽ ፊትህ ተደፍቶ\nሲያማክርህ ምስጢሩን ገልጦ\nአባት ለልጁ እንደሚራራ\nአወጣህን ከሙታን ሥፍራ\n\nምስክር ነን ለዓለም ሁሉ\nስላዳነን በሕያው ቃሉ\nለውለታው ምላሽ ባይኖርም\nከምስጋና ከቶ አንቦዝንም\n', 'am', 3, 0),\n(1, 'ጉልበቴ ና ሀይሌ', ' ጉልበቴ ና ሀይሌ\n\nጉልበቴ ና ሀይሌ ያደረኩት\nህይወቴን አደራ የሰጠሁት\nለእግዚአብሔር ብቻ ነው ለጌታዬ\nከእርሱ ጋር መኖር ነው አላማዬ\n\nእንደ ሚስኪን ሆኖ ከእኔ ጋር የሚያድር\nአልብሶኛል ፍቅሩን በደሌን ሳይዘክር\nሳይነጥፍ አጠጣኝ ከምንጩ እየቀዳ\nተማረብኝ ነፍሴ ምህረቱን ወዳ\n\nየማይቆረቁረኝ እርሱ ነው ምቾቴ\nወዶ የቀረበኝ ሳይገባው ሀጥያቴ\nበቁስሌ ላይ ዘይት አፍስሶ የሚያክመኝ\nእግዚአብሔር ብቻ ነው ለእኔስ የሚሻለኝ\n\nታላላቅ ሸክሜን ሳይዝል የሚሸከም\nከአምላኬ በስተቀር በዙሪያዬ የለም\nየህይወት ዘር አድርጎ ደጅ ከተከለኝ\nእኔን ከእቅፍ የለም የሚለየኝ\n\nረሀብ ጥማት ከቶ በሌለበት\nመኖር ነው ምኞቴ በሰራልኝ እረፍት\nቅርጫፍ አድርጎ አጣበቀኝ ክንድ\nሰላሜ ነው ለኔ የውዴ መንገድ\n', 'am', 4, 0),\n(1, 'ቸርነትህ ነው ያደረሰኝ እስከዛሬ', 'ቸርነትህ ነው ያደረሰኝ እስከዛሬ\n\nቸርነትህ ነው ያደረሰኝ እስከዛሬ\nቸርነትህ ነው የጠበቀኝ እስከዛሬ\nላመስግንህ የኔ ጌታ በዝማሬ(2)\n\nመክሊቴንም ቀብሬ ባሳዝንህ\nመብራቴንም ይዤ ባልጠብቅህ\nበታላቅ ይቅርታ እንዳትረሳኝ\nበፍቅር ጎብኝተህ ከሞት አውጣኝ\nከቤትህ እርቄ መች ጠገብኩኝ\nበረሐብ በእርዛት ተቸገርኩኝ\nአምናለሁ አምላኬ እንድትምረኝ\nለይቅርታ መጣሁ ይቅር በለኝ\n\nአንዳች እንደሌለኝ አውቀዋለሁ\nባንተ ቸርነት ግን እመካለሁ\nየከበደው ሸክሜ ይቀለኛል\nይቅርታ ለባርያህ ይደርሰኛል\nበመቅደስህ ቆሜ ለመዘመር\nስራህን ለትውልድ ለመመስከር\nእኔ ማነኝ ብዬ አስባለሁ\nአምላክ ቸርነትህን አደንቃለሁ\n\nበሰው እጅ መመካት አቁሚያለሁ\nእረዳቴ አንተ ነህ አውቄያለሁ\nአንተ ከጠበከኝ በህይወቴ\nቅጥሬ አይደፈርም መድኃኒቴ\nየኔን ሰራ ተወው ተግባሬንም\nየመስቀሉን ነገር መርሳቴንም\nአዚሜን አንስተህ አንተን ልይህ\nእየሱስ ክርስቶስ አምላኬ ነህ\n', 'am', 5, 0),\n(1, 'አለብኝ ውለታ', ' አለብኝ ውለታ\n\nመክፈል የማልችለው አለብኝ ውለታ\nተነግሮ የማያልቅ አለብኝ ውለታ\nአምላክ ተመስገን የኔ ጌታ\nይችው ነች አቅሜ ለስጦታ\n\nበዘመኔ ሁሉ የደገፍከኝ በእጆችህ\nጌታ ዘርዝሬ አልጨርሰው ውለታህ\nምስኪን ባሪያህ ለውለታህ አሁን ምን እከፍላለሁ\nሌላ አትሻም አንተ የአቅሜን ይኸው አመሰግናለሁ\n\nስናቅ እንዳልነበር እኔ በሰዎች ተጥዬ\nከውድቀቴ አንስተህ ሰው አረከኝ ቸር ጌታዬ\nነፍሴ ለውለታህ በምስጋና ተሞልታለች\nጠዋት ማታ ስምህን እያነሳች ታመሰግናለች\n\nነፍሴ መሸሸጊያ አጥታ አንተ ስላየሀት\nከለምለም ውስጥ ወስደህ ጌታ አሳረፍካት\nየከበዳት ሸክም ቀሎ በአንተ እረፍት አገኘች\nይኸው በሰዎች ፊት የአንተን ክብር ትመሰክራለች\n\nአይቸኩልም እግዚአብሔር ለሱ አለው ጊዜ\nሲጠሩት ይሰማል ደግሞ ያወጣል ከትካዜ\nየጽድቅንም መንገድ እያሳየ ይመራናል\nወደ ህይወት መንገድ እረኛችን ወስዶ ያሳርፈናል\n', 'am', 6, 0),\n(1, 'ገና እንዘምራለን', ' ገና እንዘምራለን\n\nገና እንዘምራለን (4x)\nእንደ መላዕክቱ ብርሀንን ለብሰን ገና እንዘምራለን\n\nወላዲተ አምላክን ከፊት አስቀድመን\nበዳዊት በገና መሰንቆ ታጅበን\nለስላሴ ክብር ገና እንዘምራለን\n\nበምስጋና ስራ ከሰለጠኑት ጋር\nልብን የሚያስደስት መዝሙር እየዘመርን\nያልተሰማ ዜማ ያልታየ ምስጋና\nይፈልቃል አይቀርም ከእኛ ልቦና\nገና እንዘምራለን\n\nበትቢትም ሳይሆን በታላቅ ትህትና\nበልዩ ተመስጦ በፍቅር በልቦና\nስራችን ይሆናል ለአምላክ ምስጋና\nገና እንዘምራለን\n\nዳዊት በተመስጦ እርቃኑን ቢሆንም\nሜልኮል በዝማሬ ብትስቅበትም\nአምላክ ወደደ እንዲያመሰግነው\nበደስታ እንዳይዘምር ከልካዩ ሰው ማነው\nገና እንዘምራለን\n', 'am', 7, 0),\n(1, 'ታላቅ ነህ እግዚአብሔር', 'ታላቅ ነህ እግዚአብሔር\n\nታላቅ ነህ እግዚአብሔር ዘላለም ክብር\nአንተን የሚመስል የለም በምድር\nበመቆሚያ ስፍራ በማደሪያህ ሰማይ\nአንተ ብቻ ቅድስ ኤልሻዳይ አዶናይ\n\nከሰው አትቀበል ሁሉ የእጅህ ነው\nግዛትህም ሰፊ ዳርቻ የሌለው\nሁሉንም የሚችል እንዳንተ ማን አለ\nብትኮንን ብታፅድቅ የሚያግድህ የለ\n\nምድርን አለበስካት ዘር ሳትሰጥ አብቅለህ\nውብ አደረካት በእጅህ ልምላሜ አልብሰህ\nበጥበብ ስራ ፍጥረት ተማርከናል\nችሎታህ ታላቅ ነው ማንስ ይችልሀል\n\nታጥሮ የተከበረ ዙሪያህ በነበልባል\nከማደሪያህ ደፍሮ ማን መግባት ይቻላል\nአንዴ የሰራኸው ለዘላለም ሆኗል\nድንቅ ታምራትህ ፍጥረትህን አድኗል\n\nሳይደምን ዝናብን ከፍተህ የምትሰጥ\nሁልጊዜ አድራጊ ከቶ ማትለወጥ\nየዛሬህ ችሎታህ ነገ አይቀየርም\nዘወትር ሀያል ነህ ፍፁም የማትደክም\n', 'am', 8, 0),\n(1, 'ቀና ቀና እንድል ታደርጋለህ', 'ቀና ቀና እንድል ታደርጋለህ\n\nሀይሌን ጉልበቴን ታድሳለህ\nቀና ቀና እንድል ታደርጋለህ\nመድኃኔዓለም መዳኃኒቴ\nመሪ አንተ ነህ ለህይወቴ\n\nክንድህ ይዘርጋ ብሞት ልዳን\nባንተ ልሻገር ክፍ ዘመንን\nከሚያስጨንቀኝ አድነኝ\nካላንተ በቀር ማን አለኝ\n\nበሩ ይከፈት የሰርጉ\nጌታ አስቀምጠኝ ከማዕረጉ\nእድፌን ጣለው ከፊትህ\nከዚህ በላይ ነው ውለታህ\n\nላገለግልህ ፈቅጃለሁ\nእጄን ከፊትህ አንስቼ አለሁ\nአጥንቴም ይቁም ባንተ ፅንቶ\nመንፈስ ይቃኘኝ በላይ መጥቶ\n\nጤና መልካም ባንተ ነው\nከአለም ይህንን አላገኘው\nክብሬ ነህ አንተ መድኃኒቴ\nበቃልህ ዳነች ሰውነቴ\n', 'am', 9, 0),\n(1, 'ኦ ስሉስ ቅዱስ', 'ኦ ስሉስ ቅዱስ\nኦ ስሉስ ቅዱስ ተመስገን (2x)\nአለማትን የፈጠርክ እግዚአብሔር ተመስገን (2x)\n\nአዳም ሳይፈጠር በዙፈንህ ነበርክ\nበአንድነት ሶስትነት እየተመሰገንክ\nመላዕክትን ፈጥረህ ስምህን እንዲጠሩ\nበምስጋና ፅንተው ከአንተ ጋር ሊኖሩ (2x)\n\nየሰውን ልጅ ፈጥረክ ክብርህን እንዲወርስ\nአንተን በማመስገን ህይወቱ እንዲቀደስ\nእኛም እንድንጠራህ ባይገባን እንኳን\nለምስጋና ቆመን ደጅህ አንኳኳን (2x)\n\nየአለም ሁሉ ንጉስ የአለሙ ፈጣሪ\nፍጥረትን በሙሉ አውሎ አሳዳሪ\nስላሴን ላወድስ ስሉስ ቅዱስ ልበል\nበአለም ከመክበር በቤታቸው ልጣል (2x)\n\nዩርዳኖስን ልሁን ስላሴን ልያቸው\nበአንድነት ሶስትነት ቅድስ ልበላቸው\nትባረክ ትቀደስ ነብሴ በዝማሬ\nበአባቶቼ አምላክ በአብርሀም በሙሴ (2x)\n', 'am', 10, 0),\n(1, 'በደመናት ግሩም ነው', 'በደመናት ግሩም ነው\nበደመናት ግሩም ነው\nበሰማያት ምስጉን ነው\nበመላዕክት ስብሕ ነው\nበቅድሳን ድንቅ ነው\n\nበእሳት ሰርቷል ዙፋኑን\nበረዶ አርጓል መቃኑ\nተስማምተዋል ሁለቱም\nጥበበኛ ነው ብርቱ\nኪሩብ መላዕክ ዙፋኑ\nሱራፌል ነው ካህኑ\nይሰግዳሉ በፊቱ ዘላለም ነው መንግስቱ\n\nምድርን ያያል ከላይ\nይሸበራል ቀላይ\nይገለፃል ሞገድ\nበስልጣኑ ሲወርድ\nመባርክቱ ሲወጡ\nሰማያትን ሲገልጡ\nይገለፃል ግርማው በአርያም ያለው\n\nሰማይ የእርሱ መንበር\nመረገጫው ምድር\nከላይ ሆኖ ያበራል\nከታች ድንቅን ይሰራል\nየማይደክም ገባሪ\nለዘላለም ነዋሪ\nያለስስት ይሰጣል\nለሰው ቀንን ያወጣል\n', 'am', 11, 0),\n(1, 'አምነን ተነስተናል', 'አምነን ተነስተናል\nአምነን ተነስተናል ስምህን ይዘን\nፍቅርህን ማዳንህን ተስፋ እያደረግን\nአብረኸን ስትወጣ እናሸንፈለን\nቀኝ ስትረዳን ምድርን እንወርሳለን\n\nአብርሀም አመነ ፅደቀች ህይወቱ\nቃልን ሰምቶ ወጣ ከዘመድ ከሀብቱ\nጌትነትን አምሮ ታዞ ስለኖረ\nበነብስም በስጋ መንገድ ሰመረ\n\nማለፍ እንችላለን የእሳቱን ቅጥር\nያመነው ታማኝ ነው የማያሳፍር\nከዮርዳኖስ ማዶ ተረስተን አንቀርም\nቃል የገባልንን ሳንወርሰው አንሞትም\n\nነገስታት ድል ነሱ ከሰይፍ አመለጡ\nየአንበሳን አፍ ዘጉ ከእሳት ውስጥ ወጡ\nሁሉን ነገር ንቀው በስምህ መነኑ\nከበሩ ተሾሙ አንተን ስላመኑ\n\nጀልባችንን ቀስፈን ከመሀል ደርሰናል\nመረባችንን በቀኝ ጥለናል\nከንቱ ሆኖ እንዳይቀር ልፈት ድካማችን\nፍፃሜው እንዲያምር እርዳን አምላካችን\n', 'am', 12, 0),\n(1, 'ወዶናልና', 'ወዶናልና\nወዶናልና ዳግም አይጠላንም\nአይቶናልና መቼም አይረሳንም\nወረት የሌለው ታማኝ ቅዱስ ጌታ\nከእኛ ጋራ ነው ሁሌም ጠዋት ማታ\n\nከድቅድቅ አለም ከሚያስፈራ ስፍራ\nወደ ሚደነቅ ብርሀን እየጠራን\nህዝቦቹ ሳንሆን ህዝቦቹ አደረገን\nእስራኤል ዘነብስ እርስቱን አገኘ\n\nጥበበኞችን ለማሳፈር ብሎ\nስጋን ለበሰ ሁላችንን መስሎ\nበእግዚአብሔር ሞት ህይወትን አገኘ\nነፃነት ሰጠን እልል እልል እንበል\n\nብራብ ምግቤ ነው ብጠማ መጠጤ\nብታረዝ ልብሴ ብቸገር ምርኩዜ\nሀይሌ ብርታቴ መፅናኛዬ እርሱ ነው\nየጠላቶቼን ግንድ የሰባበረው\n\nጠላት ቢከበን ቀስቱን ሰይፉን ጥሎ\nሊያጠፈን ቢጥር ዳቢሎስን መስሎ\nዳዊት እረድቶት ጎልያድን የጣለው\nየእስራኤል አምላክ መሀላችን አለ\n', 'am', 13, 0),\n(1, 'ላገልግልህ ጌታ', 'ላገልግልህ ጌታ\nላገልግልህ ጌታ ዕድሜ ከሰጠኸኝ\nሀይልና ብርታትም ጉልበትም ከሆንከኝ\nየማልጠቅም ስሆን ለዚህ ከጠራኸኝ\nመንፈሳዊ ትጥቄት ጌታ ሆይ አፅናልኝ\n\nእንግዳ ስሆን እንደ አባቶቼ\nአንተን መረጥኩኝ ሁሉንም ትቼ\nያኔ ስጀምር ከእኔ ጋር አለክ (2x)\nአምናለው ጌታ ፍፃሜዬ ነህ (2x)\n\nበሰጠኸኝ መክሊት ሰርቼ\nእጥፍ ድርብን ዋጋ አግኝቼ\nምሳሌ አድርገን አምላክ አደራ (2x)\nመልካሙን ፍሬ በህይወቴ ላፍራ (2x)\n\nከፅሀይ በታች እርስት የለኝም\nየማየው ሁሉ ዘላቂ አይደለም\nአንተ ብቻ ነክ አክሊሌ ክብሬ (2x)\nይሔ ነው ትርፌ ቤትህ መኖሬ (2x)\n\nስጋዊ ሆኖ መውጣት መግባቴ\nወጥቼ እንዳልቀር ከሰማይ ቤቴ\nቅዱስ መንፈስህ አይለየኝ (2x)\nከሀይል ወደ ሀይል ያሸጋግረኝ (2x)\n', 'am', 14, 0),\n(1, 'በመጨረሻው እንነሳለን', 'በመጨረሻው እንነሳለን\n\nበመጨረሻው እንነሳለን ከሙታን\nጌታ ሲመጣ በአየር ሆነን እያየን\n\nብርሃን ሆኖ ለሚኖሩት ለክብር\nየሚናፍቅ ነው በልቦናቸው የሚኖር\nየስንዴ ቅንጣት ትንሳኤ ካላት በምድር\nተስፋ አለን እኛ በሰማይ አገር ልንኖር\n\nፀሓይ ሲጨልም ክዋክብትም ሲረግፉ\nምድርና ሞላዋ ለዘላለም ሲያልፉ\nበሰማይ ኃያላት ንውፅውፅታ ሲሰማ\nጌታ ይመጣል በመለኮት ግርማ\n\nእልፋ አእላፍት መላእክትም ሲታዩ\nብርሃን ሲሞላ በምድርና ሰማዩ\nየምድር ዳረቻ በንፋስ ኃይል ሲመታ\nከጭንቅ አድነን አማኑኤል የኛ ጌታ\n\nለሚታመኑ በሃይማኖት ለፀኑ\nይታያል በግልጥ የጌታችን ማዳኑ\nበምድር እያሉ ኃጢአትን ለሚሰሩ\nያስደንግጣል ያስፈራቸዋል ክብሩ\n\nጌታ በዚያ ቀን እንዳንጣል ከሲኦል\nቅዱስ ስምህን ይዘን ተማፅነናል\nበበደላችን እንዳትከፍለን አደራ\nእንደ መርገም ነው ጌታ ሆይ የኛ ሥራ\n', 'am', 15, 0),\n(1, 'በኪሩቤል ጀርባ', ' በኪሩቤል ጀርባ\nበኪሩቤል ጀርባ ታየ ተቀምጦ\nብርሃንን ለብሶ በግርማው ተገልጦ\nየሰማይ መላዕክት ስሙን ሲቀድሱ\nይባቤ ምስጋና ሞላ በመቅደሱ\n\nከሰማያት በላይ ከፍ ከፍ ብሏል\nበአርያም አዳራሽ ክብሩ ይገለጣል\nእሳት የታጠቁ መላዕክቱ ሁሉ\nሃሌ ሉያ ብለው ፊቱ ይሰግዳሉ\n\nዝናው ምድርን መልቷል ተነግሯል ስለርሱ\nሊሽረው የሚችል ከቶ ማነው እርሱን\nይገድላል ያድናል ይሽራል ያከብራል\nየወደደውን ሰው ምሮ ያሳርፋል\n\nምድርና ሰማይን የመላ ነው ግርማው\nእድሜን ይጨምራል ፈርቶ ላመለከው\nየጸና ግንብ ነው ስሙ ለዘላለም\nእንደ "መሬታውያን" ቀን አይቶም አይጥልም\n\nባለሥልጣን ንጉሥ ባለጸጋ ጌታ\nየርሱ ነው ዘወትር ምስጋና እና እልልታ\nእውነት ነው አውጁ ሳታፍሩ በስሙ\nይህን እያመነ ይመለስ ዓለም\n', 'am', 16, 0),\n(1, 'ምስጉን ነው', 'ምስጉን ነው\nምስጉን ነው የተመሰገነ\nባሪያውን እኔን ይቅር ያለ\nይመስገን ይመስገንልኝ\nጎጆዬን አምላክ ሞላልኝ\n\nአዝ፦\nእጅህ ሰፊ እንደሆነ አውቃለሁ ጌታዬ\nየጎደለው ሞልቷል ይድረስ ምስጋናዬ\nያጣሁትን ካንተ አግኝቻለሁ\nሁሉን ነገር ለበጎ ብያለሁ (፪)\n\nአዝ፦\nማቄን የቀደደው ደስታ አስታጠቀኝ\nባዶ የነበርኩኝ ደስታ ተሰጠኝ\nሰጪም ነሺም እግዚአብሔር ብቻ ነው\nየሰው ድርሻ በር ማንኳኳት ነው (፪)\n\nአዝ፦\nእገፋለሁ እንጂ እኔ አልጨነቅም\nመሠረቴ አንተ ነህ ከቶ አልናወጥም\nስትሰጠኝ የሚታየውን\nእንዳትነሳኝ የዘላለሙን (፪)\n\nአዝ፦\nቢሰጥ አያልቅበት ለጋስ ክቡር ጌታ\nሁሉን ከወነልኝ በልዩ ችሮታ\nድሆች ስንሆን ሁሉ አለንና\nአማላካችን ይድረሰው ምስጋና (፪)\n', 'am', 17, 0),\n(1, 'ስላሴ መታመኛዬ', 'ስላሴ መታመኛዬ\nስላሴ መታመኛዬ\nአምላኬ መጠለያዬ\nጉልበቴ ነክ ማሸነፍያዬ\nስላሴ መታመኛዬ\n\nጠፈሩም እርሱ ነው መሰረቱም እርሱ\nፍጥረታት በሙሉ ስሙን አወድሱ\nሱራፌልን ልብህ ከንፈሮቼን ዳሰኝ\nለምፄን ተመልክተህ አምላክ አትጣለኝ (2x)\n\nእንዴት ያለ አንደበት ስምህን ይጠራል\nግርማህን አይቼ ልቤ ተሰውሯል\nኦዝያን አለፈ ክፈቱ እጅግ በዝቶ\nአምላኬን አየሁት በዙፋኑ ፅንቶ (2x)\n\nአላዛር ያንተ ነው መንገድ የወደቀው\nከእጅህ አላመለጠም ነዌ ባለ ፅጋው\nነገስታትም ያንተ በስልጣን ያሉት\nለስምህ ይንበርከክ ይህ ሁሉ ፍጥረት (2x)\n\nበድቅድቅ ጨለማ ተስፈ በሌለበት\nብርሀን ሆኖ አየሁ የጌታዬ ምህረት\nሀይልን ማሸነፍም ፅናትንም ሰጠኝ\nጠላት እንዳይጥለኝ ፅጋህን አብዛልኝ (2x)\n', 'am', 18, 0),\n(1, 'ወይኩን ፍቃድከ', 'ወይኩን ፍቃድከ\nአንተ እንዳልከው ይሁን ይደረግልን\nእንደ ሀሳብ ምራን ጌታ ቃል ይምራን\nከፊታችን ቅደም ከመንገዳችን\nግባ በህይወታችን\n\nፍቅርና ምረት ቸርነት በዝቶ\nውለን እንገባለን ሳንናወጥ ከንቶ\nከሞት ጀርባ ቆመን በፍራት ስንርድ\nበቃል ገፀፅከው ፀጥ አለ ያሞገድ\n\nወይኩን ፍቃድከ ፍቃድከ እግዚአብሔር\nበከመ በሰማይ ከማሁ በምድር\n\nያዘጋጀህልን ያሰብክልን ለኛ\nእስከምንቀበል አርገን ቀናተኛ\nበፍቅር ሰብስበ ቤት የወሰድከን\nካራን እኝዳንገባ ከነአን መልሰን\n\nወይኩን ፍቃድከ ፍቃድከ እግዚአብሔር\nበከመ በሰማይ ከማሁ በምድር\n\nየኛ ሀሳብ ከንቱ ነው ያንተ ይሻለናል\nልባችን አንፅቶ ወንዝ ያሻግረናል\nእንደወደድክ አርገ እንዳሳብ ምራን\nመስቀሉን አሲዘ ሀይልን አላብሰን\n\nወይኩን ፍቃድከ ፍቃድከ እግዚአብሔር\nበከመ በሰማይ ከማሁ በምድር\n\nየመስቀሉ ፍቅር በኛላይ ያኖርከው\nመቼም አይረሳም ስለኛ የሆንከው\nበጠላት ተማርከን ሲኦል እንዳንገባ\nባንተ ላይ አረፈ የፍቅራችን መባ\n\nወይኩን ፍቃድከ ፍቃድከ እግዚአብሔር\nበከመ በሰማይ ከማሁ በምድር\n', 'am', 19, 0),\n(1, 'ቃልህን ሰምቼ', 'ቃልህን ሰምቼ\nቃልህን ሰምቼ ህይወትን እንዳገኝ\nጌታ ማስተዋልን ጥበብን ስጠኝ\nእንደ ሊድያ ልቤን ክፈትልኝ\n\nህይወት የሆነ ጣፋጭ ቃልህ\nይፈልቃል እና ከመቅደስህ\nበፍራት ሆኜ ስቆም ከፊትህ (2)\nመጥቻለው ጌታ ተናገር ልስማህ (2)\n\nአፊን ፊንያስ ቢያስመርሩህ\nቃልን ሚሰማ ነበር ከቤትህ\nየአለምን ጩኸት መስማት ሰልችቶኛል (2)\nሰላም የሞላበት ቃል ናፍቆኛል (2)\n\nአምላክ አደራ እንዳተወኝ\nሀጥያቴ በዝቶ እንዳጥለኝ\nአፈር ትቢያ ነኝ ከቶ የማልረባ (2)\nማስተዋል አድለኝ ሲኦል እንዳልገባ (2)\n\nቃልን የሚሰማ የታደለ ነው\nላንተ የተገዛ ልቦና ያለው\nየምንሰማው ቃል እንዳይፋረደን (2)\nለፍሬ እንድንበቃ ቸርነት ይርዳን\n', 'am', 20, 0),\n(1, 'በስመአብ ወወልድ', 'በስመአብ ወወልድ\nበስመአብ ወወልድ ወመንፈስ ቅዱስ\nሀሌ(2) ሉያ ስም ይቀደስ (2)\n\nብለን ስንጀምር ለአምላክ (2) ምስጋና\nእስከዝችም ሰአት አድርሶናልና\nጠብቆናልና\n\nአምላክ ሲወለድ ከድንግል በእንስሳት በረት\nፍቅሩን መሰረተ ለአለም ፍጥረታት (2)\n\nወልድ ሲጠመቅ በማይ (2) ዮርድያኖስ\nበአምሳለ እርግብ መጣ መንፈስ ቅዱስ (2)\n\nክብሩን አዋርዶ ሲመጣ ሰማያዊው አባት\nመቱት ደበደቡት በአውደ ጲላጦስ (2)\n\nየኛን ትንሳኤ ለማብሰር ወልድ አብ አንበሳ\nበተናገረው ቃል አልበረም ተነሳ\nበመንፈቀ ለሊት ክርስቶስ ተነሳ\n\nየአለም መድሀኒት አረገ (2) በእልልታ\nዲያብሎስ ታሰረ ሞትም ድል ተመታ (2)\n\nምን በሌለበት አድሎ (2) ለፍርድ\nምስኪን ባለ ፀጋ የማትል አንተ ነህ\n\nእመቤታችን ቅድስት ወላዲተ ቃል\nምስጋና ይድረስሽ እንበል እልል እልል\nሰላም ላንቺ ይሁን ማርያም ድንግል\n', 'am', 21, 0),\n(1, 'ምስጋና ላቅርብ ለስላሴ', 'ምስጋና ላቅርብ ለስላሴ\nምስጋና ላቅርብ ለስላሴ (2)\nበእጅህ በረከት ተባረከች ነፍሴ\nምስጋና ላቅርብ ለስላሴ\n\nካለመኖር ወደ መኖር\nያመጣኸኝ እግዚአብሔር\nከፍጥረታት አከበርከኝ\nበአምሳልህ እኔን ፈጠርከኝ\nበአርአያህ እኔን ፈጠርከኝ\n\nለፈጣሪ ለስላሴ\nሳተሰለች ትዘምር ነፍሴ\nስሙን ጠርታ እረክታለች\nእንደ መልካም ዛፍ ለምልማለች\n\nየምወጣው የምገባው\nሁሉን ነገር የማደርገው\nጀምሬም የምቋጨው\nእግዚአብሔርን ጠርቼ ነው\nስላሴንም ጠርቼ ነው\n\nስሉስ ቅዱስ ያስከብራሉ\nባመሟልም ያደርጋሉ\nበስላሴ ከብሬያለሁ\nልጅነትን አግኝቻለሁ\n', 'am', 22, 0),\n(1, 'ባለውለታዬ', 'ባለውለታዬ\nባለውለታዬ (2)\nካመድ ያነሳኸኝ ከትቢያ ተጥዬ\nተመስገን ጌታዬ\n\nአዝ፦\nበሩን ቢዘጋብኝ ስምዖን ጨክኖ\nዝቅ አደርጎ ቢያየኝ ከአይሁድ ጋር ሆኖ\nእንድቀርብ ወደ እርሱ አዘዘኝ ጌታዬ\nእግሩን አጥበዋለሁ ወድቄ በእንባዬ (2)\n\nአዝ፦\nየቀራጭ አለቃ ቢሆንም ስራዬ\nአንድ ወርድ ከዛፉ አዘዘኝ ጌታዬ\nመዓረጌን መሸከም እስኪያቅተኝ ድረስ\nቤቴ ተባረከ በኢየሱስ ክርስቶስ (2)\n\nአዝ፦\nድንጋይ የጨበጡ ፈራጆች ከበውኝ\nነውሬን ዘርዝረው ጌታ ፊት አያቆሙኝ\nፈረደችባቸው ኃጢአትም በእነርሱ\nበሠላም ሂድ ብሎ ምሮኛል ንጉሱ (2)\n\nአዝ፦\nየማምነውም አምላክ አውቀዋለሁ እኔ\nበሰራልኝ ሥራ በእድሜ በዘመኔ\nፍቅሩን ተሸክሟል የልቤ ትከሻ\nልለየው አልችልም እስከ መጨረሻ (2)\n', 'am', 23, 0),\n(1, 'አንተ ግን አንተ ነህ', 'አንተ ግን አንተ ነህ\nአንተ ግን አንተ ነህ በጸባዖት ያለህ (2)\nዘላለም የምትኖር ሁሉን አሳልፈህ\nየሁሉ ባለቤት አንተ ግን አንተነህ (2)\n\nአዝ፦\nደመናት ባይኖሩ ዝናብን ባይሰጡ\nጨረቃ እና ፀሀይ ብርሀን በያወጡ\nየፍጥረታት ፀባይ ሁሉም ቢቀያየር\nአንተ ግን አንተ ነህ ህያው እግዚአብሔር\n\nአዝ፦\nየምድር ሃያላት ትላንት የነበሩ\nበጉልበት በሥልጣን እጅግ የከበሩ\nቦታውን ለቀዋል በጊዜአቸው አልፈው\nአንተ ግን አንተ ነህ መንግስትህ ህያው ነው\n\nአዝ፦\nሁሉን ስትለውጥ የማትለወጥ\nእንደየሥራው የእጅን የምትሰጥ\nማለዳ ማለዳ አዲስ ነው ስምህ\nቀናት የማይቆጥሩህ አንተ ብቻ ነህ\n\nአዝ፦\nአመድ ሲሆኑ አየን የግሪክ አማልክት\nበወርቅ እና በብር በእጅ የተሠሩ\nዘመን የማይሽረህ እንዲህ እንደዋዛ\nአንተ ግን አንተ ነህ ፈጥረህ የምትገዛ\n', 'am', 24, 0),\n(1, 'አንደበቴም ያውጣ', 'አንደበቴም ያውጣ\nአንደበቴም ያውጣ የምስጋና ቅኔ\nየአምላኬን ማዳን አይቻለሁ በዓይኔ\nበገባዖን ሰማይ ፀሐይን ያቆመ\nዛሬም ጎብኝቶኛል እየደጋገመ\n\nአዝ፦\nወጥመድ ተሰበረ እኔም አመለጥኩኝ\nከሃጢያት ፍላፃ ከሞት አተረፈከኝ\nየአናብስቱን አፍ በሃይሉ የዘጋ\nየዳንኤል አምላክ ይኖራል ከእኛጋ\n\nአዝ፦\nበዳዊት ምስጋና በያሬድ ዝማሬ\nከቅዱሳን ጋር ልዘምር አብሬ\nእርሱን ሳመሰግን ሜልኮል ብትስቅብኝ\nለጌታዬ ክብር እዘምራለሁኝ\n\nአዝ፦\nአስፈሪው ነበልባል እሳቱ ቢነድም\nለጣኦት እንድሰግድ ነገስታት ቢያውጁም\nሁሉም ቢተወኝም ቢጠላኝም ዓለም\nፅናት ይሆነኛል ጌታ መድሃኔዓለም\n', 'am', 25, 0),\n(1, 'ሥላሴን አመስግኑ', 'ሥላሴን አመስግኑ\nሥላሴን አመስግኑ ሥላሴን አመስግኑ\nየምድር ፍጥረታት ዘምሩ እልል በሉ (2)\n\nአዝ፦\nበስመ አብ ወወልድ ወመንፈስ ቅዱስ\nምሥጋና ይገባል ከምንም በፊት\nዓለማትን ሁሉ ለፈጠረው ጌታ\nምሥጋና ይገባል ከጥዋት እስከ ማታ\n\nአዝ፦\nኪሩቤል ሱራፌል የሚያመሰግኑህ\nመላእክት በሰማይ ሚዘምሩልህ\nእኛም የአዳም ልጆች እንዘምራለን\nበሰማይ በምድር እንጠራሃለን\n\nአዝ፦\nብራብ በሥላሴ እጠግባለሁኝ\nብጠማም በአምላኬ እረካለሁኝ\nሥላሴ አምባዬ ክብሬም ናቸውና\nሁሌ ይመሩኛል በሕይወት ጐዳና\n', 'am', 26, 0),\n(1, 'እፁብ ድንቅ ነው ውለታው', 'እፁብ ድንቅ ነው ውለታው\nእፁብ ድንቅ ነው ውለታው\nእግዚአብሔር ለእኛ ያረገው\nከቶ አይጥለንም ለዘለዓለም\nእንደ አምላካችን ማንም የለም\n\nወድቀን ነበረ ተነስተናል ባህር አቁሞ አሻግሮናል\nድንቅ አደረገ ተአምር ሰራ\nእያንሳፈፈ ያን ተራራ\n\nየጠፋውን በግ የፈለገ እራሱን ባዶ አደረገ\nመስቀል ታቅፎ ክንዱ ዛለ\nምን ያልሆነልን ነገር አለ\n\nከአባትም በላይ አባት ነው\nየልጆቹ እምባ የሚገደው\nየጭንቀታችን ተካፋይ አዛኝ ጌታ ነው ሁሉን ቻይ\n\nዳግም እንድንቆም በህይወት\nጨክኖ ወደደን እስከ ሞት\nከእንግዲህ አንፈራም እንፀናለን\nለክፉ የማይሰጥ አባት አለን\n', 'am', 27, 0),\n(1, 'የሥላሴን መንበር', ' የሥላሴን መንበር\nየሥላሴን መንበር ቅዱሳን ከበውት\nኪሩቤል በደመና ዙፋኑን ይዘውት\nድንግልን ከመሐል ሚካኤልን ከፊት\nአእላፍ መላዕክት ሲሰግዱ በፍርሐት\nእዩት ተመልከቱት የሰማዩን ድምቀት (2)\n\nአዝ፦\nእያሸበሸቡ የሰማይ መላእክት\nካህናተ ሰማይ ሥሉስ ቅዱስ ሲሉት\nይህን ታላቅ ክብር ሊያዩ የታደሉ\nበጽድቅ ሥራቸው በምድር ይታያሉ (2)\n\nአዝ፦\nየቅዱሳን ሕብረት የቅዱሳን ሐገር\nሲያወድስ ይኖራል የሥላሴን መንበር\nጽድቅና ርህራሄ የተሞላ ሰማይ\nእግዚአብሔር ያድለን በትንሣኤ\n', 'am', 28, 0),\n(1, 'ስምህ በሁሉ ተመሰገነ', 'ስምህ በሁሉ ተመሰገነ\nስምህ በሁሉ ተመሰገነ\nከክብር በላይ ክብርህ ገነነ\nአንተን ማወደስ ያስደስተናል\nስምህን ማክበር ክብራችን ሆኖአል (2)\n\nአዝ፦\nአምላክ ተመስገን በሰማያት\nስምህ ይወደስ በፍጥረታት\nከህፃናት አፍ ምስጋና ይውጣ\nአንተን ማመስገን ይሁን የኛ ዕጣ (2)\n\nአዝ፦\nበምግብ እጦት ብንሰቃይም\nማህሌትህን አናቁአርጥም\nየመከራ ዶፍ ቢወርድብንም\nእንዘምራለን ለአምላካችን ስም (2)\n\nአዝ፦\nሰማዩ ዝናብ ደመና ቢያጣ\nፍቅርህ በእኛ ውስጥ አላቁአረጠም\nቸርነትህን እንጠብቃለን\nከአንተ ደጅ አምላክ የት እንሄዳለን (2)\n', 'am', 29, 0),\n(1, 'ኑ በእግዚአብሔር', 'ኑ በእግዚአብሔር\nኑ በእግዚአብሔር ደስ ይበለን (2)\nለታላቁ ክብር ለዚህ ላበቃን\nከሞት ወደ ሕይወት ያሸጋገረን\nኑ በእግዚአብሔር ኑ በድንግል\nደስ ይበለን (2)\n\nአዝ፦\nየሰማዩን መንግስት እርስቱን ለሰጠን\nከጨለማ አውጥቶ ብርሃንን ላሳየን\nለዚህ ድንቅ ውለታው ምስጋና ያንሰዋል\nበእርሱ ደስ ይበለን ክብር ይገባዋል\n\nአዝ፦\nከዓለት የፈለቀ ውሃ ጠጥተናል\nሰማያዊ መና አምላክ መግቦናል\nፍቅርህ የበዛ ነው ምን ልክፈልህ ጌታ\nስምህን ላመስግነው ከጠዋት እስከ ማታ\n\nአዝ፦\nበቃዴስ በረሃ ምንም በሌለበት\nበኤርትራ ባሕር ወጀብ በበዛበት\nለእርሱ መንገድ አለው ከቶ ምንተስኖት\nልባችሁ አይፍራ በፍጹም እመኑት\n\nአዝ፦\nበባርነት ሳለን በድቅድቅ ዓለም\nብርሃንን አገኘን በድንግል ማርያም\nያጣነውን ሰላም ዛሬ አገኘን\nእጅግ ደስ ይበለን በእመቤታችን\n\nአዝ፦\nየሐና የኢያቄም የእምነታቸወ ፍሬ\nበእግዚአብሔር ፈቃድ ተወለደች ዛሬ\nየኢያቄም ስእለቱ የሐና አምነት\nለምኚልን ለእኛ ኪዳነ ምሕረት\n', 'am', 30, 0),\n(1, 'አይኖቼ ማዳኑን', 'አይኖቼ ማዳኑን\nዓይኖቼ ማዳኑን አይተዋልና (2)\nይገባዋል (2) ክብርና ምስጋና\n\nአዝ፦\nከሰማይ ወረደ ሰውን በማፍቀር\nኃያሉ ጌታቸን ቸሩ እግዚአበሔር\nበቤተልሔም ዋሻ በዚያ በግርግም\nተወለደ ዛሬ መድኃኔዓለም\n\nአዝ፦\nየተነበዩለት ብዙ ነብያት\nከድንግል ተወልዶ አዳነን በእውነት\nከበደል ጉራንጉን አነሳን ከትቢያ\nበአንድነት እንዘምር እንበል ሃሌ ሎያ\n\nአዝ፦\nየተናቅን ሰንሆን እኛን ሊያከብር ወዶ\nበፍቅር አከበረን እራሱን አዋርዶ\nምን ዓይነት ፍቅር ነው ፍጹም ምህረት\nየአምላክ መወለድ በከብቶች በረት\n\nአዝ፦\nበንጽህና ጸንተሽ ቤተመቅደስ የኖርሽ\nበኀቱም ድንግልና መድኃኒትን ወለድሽ\nየዓለምን ኃጢአት የሚያስተሰርይ ጌታ\nተወልዷል ከድንግል የሰዎች አለኝታ\n', 'am', 31, 0),\n(1, 'ድንቅ አድርጎልኛል', 'ድንቅ አድርጎልኛል\nድንቅ አድርጎልኛል የሠራዊት ጌታ (2)\nአልረሳኝም አምላክ አነሳኝ ከትቢያ (2)\n\nድንቅ አድርጎልኛል በደሌን ሳይቆጥር\nድንቅ አድርጎልኛል ወደቤቱ ጠራኝ\nድንቅ አድርጎልኛል ረክሼ ሳለሁ\nድንቅ አድርጎልኛል ልጄ ሆይ ና አለኝ\nድንቅ አድርጎልኛል በዳግም ምጻቱ\nድንቅ አድርጎልኛል መንግስቱን ሊያወርሰኝ\n\nአዝ፦\nድንቅ አድርጎልኛል ከአንበሳ መንጋጋ\nድንቅ አድርጎልኛል ከጉድጓድ አወጣኝ\nድንቅ አድርጎልኛል በጠላቶቼ ፊት\nድንቅ አድርጎልኛል ግርማ ሞገስ ሰጠኝ\nድንቅ አድርጎልኛል ምን እመልሳለሁ\nድንቅ አድርጎልኛል እንዲ ለወደደኝ\n\nአዝ፦\nድንቅ አድርጎልኛል ጠላቶቼ ሁሉ\nድንቅ አድርጎልኛል ሲጓደዱብኝ\nድንቅ አድርጎልኛል ማን ይደርስለታል\nድንቅ አድርጎልኛል እያሉ ሲሉኝ\nድንቅ አድርጎልኛል ፈጥነህ ደረስክልኝ\nድንቅ አድርጎልኛል ከሞት አዳንከኝ\n', 'am', 32, 0),\n(1, 'እልል በሉ', 'እልል በሉ\nእልል በሉ በአንድነት ዘምሩ\nአመስግኑ ለክብሩ ዘምሩለት\nእንደ እግዚአብሔር ያለ ማንም የለም በሉ\n\nአዝ፦\nበኃጢያት ባርነት ስንኖር ተገዝተን\nከቤቱ ስንርቅ ትእዛዙን አፍርሰን\nአይቶ ዝም ላላለን ጠላቶቹ ስንሆን\nውለታው ብዙ ነው ክብር ለዕርሱ ይሁን (2)\n\nአዝ፦\nራሱን አዋርዶ እኛን አከበረን\nሥጋውና ደሙን ብሉ ጠጡ አለን\nመልካም እረኛ ነው የሚያሳጣን የለም\nምስጋና ይድረሰው ለመድሐኔአለም (2)\n\nአዝ፦\nሕይወቱን የሰዋ እንደ አምላክ ማን አለ\nለሰው ልች ብሎ በመስቀል የዋለ\nፍቅሩ አይለካ አያልቅም ቢወራ\nከሰማያትወርዶ ሆነ ከእኛ ጋራ (2)\n\nአዝ፦\nሥራውን እናድንቅ እንዲህ ለወደደን\nከማያልቀው ፍቅሩ በረከት ላደለን\nለማይነገረው ለአምላክ ስጦታ\nውዳሴን እናቅርብ እንዘምር በእልልታ (2)\n', 'am', 33, 0),\n(1, 'ሳይገባኝ አምላክ', 'ሳይገባኝ አምላክ\nሳይገባን አምላክ ሳይገባን\nሳይገባን ጌታ ሳይገባን\nለዚህ ያደረስከን እኛ ማን ነን (2)\n\nአዝ፦\nምን ያላረክልኝ አለ ጌታ ለእኔ\nምንም ባሳዝንህ በምግባሬ\nኃጢአቴን ተመልክተህ ቸል ያላልከኝ\nበሕይወቴ ብዙ ነገር ሰራኽልኝ\n\nአዝ፦\nውለታህ ብዙ ነው የአንተ ውለታውም የለው\nተናግሬ እኔስ አልጨርሰው\nውድቀቴንም ድክመቴንም እኔ አውቃለሁ\nየጠበቀኝ ቸርነትህ ምሕረት ነው\n\nአዝ፦\nለማይነገረው ፍቅርህ ግሩም ሥራ\nልጆችህን የምትጠብቅ ከመከራ\nምን እንመልሳለን ለአምላካችን\nከመዋረድ አድነኸን ላከበርከን\n', 'am', 34, 0),\n(1, 'አዳነኝ ጌታ አዳነኝ', ' አዳነኝ ጌታ አዳነኝ\nአዳነኝ ጌታ አዳነኝ\nፈወሰኝ ጌታ ፈወሰኝ\nእግዚአብሔር አዳነኝ\nሀጥያተኛውን ወደደኝ\n\nያልፍል ያላልኩት አልፎ አይቼ\nበእንባ ታጠብኩኝ ከድቅድቅ ወጥቼ\nእንግዲህ ላንተ ምስክር ሆኛለሁ\nስራህን ላለም ሁሌ እናገራለሁ (2x)\nክንድህ ብርቱ ነው ደካማን ለመርዳት\nታውቅበታለህ የዛለን ማበርታት\nአይኔን ከሰዎች ማረቄ ጠቅሞኛል\nደጅህ ወድቄ መኖር ተሽሎኛል\n\nየሀዘኔን ማቅ አውልቀክ ታልክልኝ\nሞቴን ስጠብቅ ዕድሜዬን ጨመርክልኝ\nከአልጋ ላይ አነሱኝ እጆችክ\nተፈውሻለሁ ዛሬም በምህረትህ (2x)\nቃልህ ፅኑ ነው ዳግም ይጠግናል\nጎባጣ አቅንቶ ሽባውን ተርትሯል\nህይወቴ ባንተ ዛሬ አዲስ ሆናለች\nበክብር መዝገብ በእጅ ተፅፋለች\n\nየሀሰትን ፍርድ ጌታ ቀለበስከው\nተፅናንቷል ባንተ የተደገፈ ሰው\nየግፍን ፅዋ አረከው በፊቱ\nበእጅ ላይ የለም ዛሬም ሰንሰለቱ (2x)\nበሀማ መስቀል ላይ መርዶኪዮስ የለም\nየናብቴ ደም በከንቱ አልቀረም\nየእውነት ዳኛ ጌታ ስትመጣ\nየሀሰት ሰው ግፈኛ ተቀጣ\n', 'am', 35, 0),\n(1, 'እውነተኛ ዳኛ', 'እውነተኛ ዳኛ\nእውነተኛ ዳኛ እግዚአብሔር ብቻ ነው\nአያዳላም ፍርድ ቅንና እውነት ነው\nየሚስኪኑን እንባ ፈጥኖ ያብስለታል\nመፅናናትን ሞልቶ በክብር ያኖረዋል\n\nይፈርዳል በጊዜው ለሁሉም እራርቶ\nቢዘገይም እንኳን ይመጣል እንባችንን አይቶ (2x)\n\nበባርነት ይዞ ህዝበ እስራኤልን\nአለቅም ቢል እንኳን ጨካኙ ፈርኦል\nበታላቅ ታምራት ደጅን አስጨነቀው\nእግዚአብሔር ፈረደ ህዝብን ሊታደገው\n\nናብቴም ቢሞትም በኤልዛቤር በትር\nአክአብ በደሀው እርስት ላይ ቢያድርም\nየአምላኩን ፍርድ ይዞ ኤልያስ ይመጣል\nለደሀ ደጉም ሰው እግዚአብሔር ይፈርዳል\n\nመርዶኪዮስ ባንተ ሞት ቢታወጅብህ\nበንጉስ ማህተም ፍርድ ቢፅናብህ\nሀሰት ያለበሰክ ከሳሽህ ይወድቃል\nነገር ተገልብጦ ሀማ ይሰቀላል\n\nፍትህ የጎደላት አለም ብትከበንም\nበግዞት ለመጣል ወደኛ ብትፈጥንም\nወደ ተበደሉት ሚዛኑ ያደላል\nየመገፈቱ ቀን በቃ ሲል ይፈታል\n', 'am', 36, 0),\n(1, 'ምስጋና አምልኮ ስግደት', 'ምስጋና አምልኮ ስግደት\nምስጋና አምልኮ ስግደት ውዳሴ\nይገባል በሉ ሰዎች ለቅድስት ስላሴ\n\nዘላለም ዓለም ቅዱስ ነህ\nአምሳያ ወደር የሌለህ\nመታመኛዬ ሆነኸኛል\nስላሴ በአንተ ደስ ይለኛል\n\nየታመነ ነው የተፈራ\nየፅድቅን ፅሐይ የሚያበራ\nአለሙን በርቷል በስላሴ\nትዘምርለን ለእርሱ ነፍሴ\n\nዘመናት በእጅ በመዳፋ\nሁሌም የእርሱ ነው ድል ሰይፋ\nየእሳት መድረኮች ያሉት ጌታ\nየማያልፍ ነው የማይረታ\n\nአብርሀም አምኖ ተሰደደ\nበእርጅና ወራት ልጅ ወለደ\nየተስፈውን ቃል ፈፅመለት\nሥላሴ በሉት በቀን በሌሊት\n', 'am', 37, 0),\n(1, 'ምስጋና እልልታ', 'ምስጋና እልልታ\nምስጋና እልልታ ወደ እርሱ አቀርባለሁ\nመድኃኒቴ አምላኬ መጠጊያዬ ነው\nእቀኛለሁ ለእርሱ ዝም አልልም እኔ\nመልካም ላረገልኝ በህይወት ዘመኔ\n\nሰላሙን ሰቶኛል በመንፈሱ ቃኝቶ\nበአለም ታሰረ ልቦናዬ ፈትቶ\nሜልኮል ሆይ ይግረምሽ ክብሩን አውጃለሁ\nበመዝሙር በዜማ ገና እበረታለው\n\nጠላቴ ውድቀቴን መረዶ ቢነግረኝም\nእኔስ በአምላኬ ማዳን ተስፈ አልቆርጥም\nከቶ እንደማትተወኝ ዛሬም ያምናል ልቤ\nይኸው አቀርባለሁ ምስጋናናን ደርሼ\n\nየአፌ መጋረጃ በቅኔ ቢከፈት\nዲዳ ያለኝ ሁሉ አየኝ በአድናቆት\nእርሱ ካሰማራኝ በዝማሬ ሹሞ\nወጀብ ሆይ ዝም በል አልደክምም ፈፅሞ\n\nሳይነሳኝ ሰቶኛል የህይወቴን መሻት\nደስታዬ እርሱ ነው ውለታውን ማውራት\nአምላክ ዘለፋዬን ከእኔ አርቋል\nወደ ቅፅሩ ልግባ በታላቅ ምስጋና\n', 'am', 38, 0),\n(1, 'እግዚአብሔር ሀያል ነው', 'እግዚአብሔር ሀያል ነው\nእግዚአብሔር ሀያል ነው የሚሳነው የለም\nበዙፋኑ ጸንቶ ይኖራል ዘላለም\nማእበሉን ከፍሎ ህዝቡን ያሻግራል\nለሰው የሚሳነው ለርሱ ግን ይቻላል\n\nማዳንና ጥበብ ሀይል በጁ ሆኖ\nለሰው የማይቻል ለርሱ ቀሊል ሆኖ\nፈጥኖ ይጎበኛል የምስኪኑን ጓዳ\nፈጽሞ አይዘገይም ጌታ ሲሰናዳ\n\nአንዱን እየሻረ አንዱን እየሾመ\nየተዋረደውን ክብር እየሸለመ\nከሁዋላ ያለውን ከፊት አሳልፎ\nበጎ ቀን ያመጣል ጨለማውን ገፎ\n\nእንደ ቁዋጥኝ ቢከብድ የሂወት ፈተና\nሰውን የሚያጽናና አምላክ አለንና\nደስ ያሰኛል እርሱ መከራን አጥፍቶ\nታግሶ የቆመ ማን አፈረ ከቶ\n\nየሚያስፈራ ጊዜ ቢመጣ ክፉ ቀን\nእናልፋለን እኛ እግዚአብሔርን ይዘን\nወራት ከብዶባችሁ ያጎነበሳችሁ\nታሪክ ሆኖ ያልፋል እግዚአብሔር ሲያያችሁ\n', 'am', 39, 0),\n(1, 'እናመሰግንሃለን', 'እናመሰግንሃለን\nእናመሰግንሃለን (፪)\nእንደ አባቶቻችን በማህሌት እንጠረሃለን\nእንደ ቅዱሳኖች ለክብርህ እንዘምራለን\n\nአዝ፦\nለአምላክ ውዳሴ ለፈጣሪ ክብር\nማለዳ ተነስተን ምስጋና ስንጀምር\nየአባቶች ዝማሬ ቅኔም አወድሱ\nሲሰማ ደስ ይላል ከቤተ መቅደሱ\n\nአዝ፦\nሥረአተ ሰማይ በምድር ተሰርቶ\nበአባቶች ልቦና የአምላክ ጥበብ ሞልቶ\nዝማሬ ፈለቀ ከታለቁ መቅደስ\nበጥዕሙ በዜማ ፈጣሪው ይወደስ\n\nአዝ፦\nድምፁ ቀሰቀሰን ከቅዱስ ተራራ\nየያሬድ ፅናፅል መሰንቆ በገና\nየፅዮን ደናግል ለዝማሬ ተነሱ\nስሉስ ቅዱስ በሉ ስሙን አወደሱ\n\nአዝ፦\nማህለቱ ሲቆሙ ካህናት መዝሙሩ\nቅዱሳን መላእክት አብሮ ሲዘምሩ\nፍፁም ተመስጠች ነፍሳችን በደስታ\nለምስጋና ስንቆም ከቅዱሳኑ ተርታ\n', 'am', 40, 0),\n(1, 'ሰረገላው እሳት', 'ሰረገላው እሳት\nሰረገላው እሳት ልብሱ ነበልባል ነው\nየታየን ሀይል የለም የሚሳነው\nክብሩን አይቶ የሚቆጣ ማነው ከሰው ወገን\nእናመልከዋለን ከመቅደሱ ገብተን\n\nፍጥረትን ያዛል በእጅ ነው ስልጣኑ\nሁልጊዜ አዲስ ነው አያልፍም ዘመኑ\nአለም በመዳፍ በእጅ ተወስኗል\nብቻውን ንጉስ ነው ሲወደስ ይኖራል\n\nአድማስ አይገድበው የማየት መጠኑን\nበዙፋኑ ሆኖ ይዳኛል አለሙን\nየሚሰወር የለም ከፊቱ የሚያመልጥ\nማን በቅቶ ያየዋል በግርማው ሲገለጥ\n\nበኛ ላይ ያበራል የአጥቢያ ኮከባችን\nብርሀን ያለበሰን የንጋት ጎሀችን\nበፅድቅ እየመገበ አስጠጋን ከቤቱ\nበላነው ጠጣነው ፍቅር ነው እሳቱ\n\nመባርቅት የእግሩ መረገጫዎች ናቸው\nማነው ከአማልክት የሚስተካከለው\nየሞገሱ ፅዳል መብረቁን ሞልቶቷል\nበሰማይ በምድርም ክብሩ ተዘርግቷል\n', 'am', 41, 0),\n(1, 'እግዚአብሔር ሆይ እርዳኝ', 'እግዚአብሔር ሆይ እርዳኝ\nእግዚአብሔር ሆይ እርዳኝ ቸርነት አድርገህ (፪x)\nእድሜ ለንስሀ እንደ ሕዝቅኤል ሰጥተህ\nጠማማውን ልቤ በቃልህ አቅንተህ\n\nአላውቀውም ብሎ ሲጠየቅ ያመፀው\nዶሮ እስኪጮህ ድረስ ፫ ጊዜ የካደው\nየጅረት ወንዝ ነው የሰጠኸው እንባ\nጴጥሮስ ተፀፅቶ ነስሀ እንዲገባ\n\nጽዋ እንዳይደርሰኝ የይሁዳ እድል\nልጅ ሆኖ ዉሎ ኃላ መኮበለል\nጴጥሮስ እድለኛው አልቅሶ ተማረ\nበትዕቢቱ ይሁዳ እንደወጣ ቀረ\n\nዘመኗን በዝሙት አቃጥላ\nበንስሀ ጠራት ጌታ በገሊላ\nታድሳ ተነሳች በእንባዋ ብዛት\nእግሩ ስር ተደፍታ ማርያም መቅደላዊት\n\nአመፀኛው ልቤ ዛሬም መች ይተኛል\nበሐጥያት በዝሙት በስርቆት ይሞኛል\nወደ ቀድሞ ግብሩ እንዳይመለስ\nፍቅርህ በእኔ ሰርጾ ኃጢአቴን ደምስስ\n\nበደላችሁን ሁሉ ሳታስብ ትተህ\nበምጽአት ሰዓት ከጽድቃን ቆጥረህ\nነጭ ልብስ ለብሰን ሆነን ካንተ ጋር\nበሩ ሳይዘጋ አስገባን አደራ\n', 'am', 42, 0),\n(1, 'አማኑኤል', 'አማኑኤል\nአማኑኤል (4x)\nከእኛ ጋር ሆነ እግዚአብሔር\nዳግም ሊወለድ ከሞይሞት ዘር\n\nዙሪያው አበራ በቤተልሔም\nጌታ ሲወለድ መድኃኒአለም\nብርሀን ይለብሳል ጥልቁ ጨለማ\nየምናመልከው ድምፅን ሲያሰማ\n\nያን የሞት ዘመን የጥፈት ጊዜ\nአሳልፈነው በሀዘን በትካዜ\nአሁን ታደስን በልጅ ደም\nደስታ ከቦናል ፍቅርና ሰላም\n\nህጉን ተላልፈን ከእጅ ስንወጣ\nስለወደደን ሊያድነን መጣ\nስጋ ደማችን ከእርሱ ተጣብቋል\nከኛ ጋራ ነው ማን ይችለናል\n\nእሩቅ አይደለም ቅርብ ነው ጌታ\nየሚጠብቀን በቀን በማታ\nሞገስ ሆኖልን ከፍ ብለናል\nእናምነዋለን ይዋጋልናል\n', 'am', 43, 0),\n(1, 'ህያውን ከሙታን', 'ህያውን ከሙታን\nህያውን ከሙታን መሀል ለምን ፈለጋችሁ\nእንደተናገረው በመቃብር የለም ተነስቷል ጌታችን (2x)\n\nየለም ከመቃብር አትፈልጎት\nዩሐንስ ጰጥሮስ አትሩጡ ላታገኙ\nውጡ ከመቃብር ጣሉና በፍታውን\nሒድ አውጅ ለአለም ትንሳኤውን (2x)\n\nሉቃስ ቁለዮጳ ተስፈቸው ይመለስ\nመቃብር ያደረው በትንሳኤው ክብር ሲነግስ\nወደ ኢየሩሳሌም ዳግም ተመለሱ\nሞትን አሸንፏል የተቤዠን ንጉስ (2x)\n\nመቅደላዊት ማርያም አትዘኚ\nሽቶውን ቀብተሽ መሻትሽን ባታገኚ\nእንደ ተናገረው ተነስቷል ከሙታን\nመግነዙን ፍቱ ሳይል ሞትን ድል አድርጓል (2x)\n', 'am', 44, 0),\n(1, 'ለበጎ ነው', 'ለበጎ ነው\nሁሉም የሆነው ለበጎ ነው\nሁሉም የሆነው ለመልካም\nበሰማይ በምድር አንተ ያልከው\nአምላኬ ስራህ ትክክል ነው\n\nሳቅና ለቅሶ ሀዘን በደስታ\nቢፈራረቁም ጠዋት ማታ\nበአንተ ሲሆን ደስ ይለኛል\nአሜን ይሁንልን ብለናል\n\nዉሀን ቢሞላ መርከባችን\nበእሾህ ቢታጠር ጎዳናችን\nአተውከንም እናምናለን\nጌታ ሆይ ባንተ እንተርፈለን\n\nማነስ መብዛቱን እናውቃለን\nየምንሞት ስንመስል ህያው ነን\nአስጨናቂውን ጥሎልናል\nአሁን የአምላካችን ሆነናል\n\nከሀገር ብንወጣ ብንሰደድ\nጉልበቴ ቢዝል በመንገድ\nአንተ ሰለ ሆንክ ሰው ሆኛለው\nለወንድሞቼ ተርፌአለሁ\n', 'am', 45, 0),\n(1, 'ፈተና ወጀብ', 'ፈተና ወጀብ\nፈተና ወጀብ ቢበዛ\nአይተናል ህዝብን ሲያበዛ\nበህይወት አንዴ ጠርቶናል\nእግዚአብሔር መች ይተወናል\n\nፍቅር ነው የናርዶስ ሽቶ\nወደደን ተሰቅሎ ሞቶ\nነጎድጓድ መብረቅ ቢሆንም\nበህይወት አለን አሁንም\n\nመኳንት ደጅን ክፈቱ\nየፀጋው ፈልቷል ዘይቱ\nተራግፏል ሸክማችን\nምህረቱ ሲፈስልን\n\nተፅናንቷ አርፏል ልባችን\nበእሳት ታጥሯል ቅጥራችን\nአንወድቅም አንሸነፍም\nይዞናል የአምላካችን ስም (2x)\n\nህይወት ነህ የፅድቅ ጥላ\nያምንሀል ቃል የተሞላ\nነህ አንተ ጣፈጭ ምግባችን\nእግዚአብሔር ቸሩ አምላካችን (2x)\n', 'am', 46, 0),\n(1, 'ነፍሴ ለአምላክ ዘምሪ', ' ነፍሴ ለአምላክ ዘምሪ\nዋጋ ተከፍሎሽ\nአምላክ ተሰቅሎልሻል\nነፃ ወተሻል ዛሬ\nነፍሴ ለአምላክ ዘምሪ\n\nማነው ያስታወሰሽ የደረሰልሽ\nእርግማን ቀጥቅጦ ሴጣን ሲገዛሽ\nተሰቅሎ ተገርፎ ከሞት ያዳነሽ\nመድኃኒአለም ነው ባለውለታሽ\n\nይደምቃል ይበራል ደግሞ ይደበዝዛል\nየቀረበሽ ወዳጅ ነገ ይርቅሻል\nእርሱ ግን ሀይልሽ ነው የመኖርሽ ትርጉም\nክብርና ጌጥሽ ሁሌም ያንቺ ሰላም\n\nዳግም አትበድይ ነፍሴ አምላክሽን\nአርነት ወጥተሻል በአለም ብርሀን\nታመኚ ለፍቅሩ ለዋለው ውለታ\nህይወቱን ሰቶሻል የሰራዊት ጌታ\n\nመውጊያው ተሰበረ ሞት ስልጣኑን አጣ\nከሲኦል ባርነት ፍጥረት ነፃ ወጣ\nዘምሪ ለጌታሽ ዘምሪ ለስሙ\nታጥበሽ ታትመሻል በከበረ ደሙ\n', 'am', 47, 0),\n(1, 'አምላክ ሰው ሆነ', ' አምላክ ሰው ሆነ\nአምላክ ሰው ሆነ ሰው አምላክ ሆነ (2)\nበድንግል ማርያም ተከናወነ\n\nየአብ ሙሽራ የወልድ እናቱ\nየመንፈስቅዱስ ፅርሀ ቤቱ\nበሰማይ ሆኖ አብ አፅናናሽ\nወልድም ለራሱ ቤት አደረገሽ\nመንፈስ ቅዱስ ነው (2) የፀለለሽ\n\nከሶስቱ አካል ወልድ አንዱ አካል\nመጣ ወረደ በገባው ቃል\nተፀንሶ ሳለ ወልድ ከእናቱ\nአልተነጠለም ከሶስትነቱ\nታምራት አርጓል ድዊ ፈውሷል\n\nይህን ድንቅ ምሲጢር በሉ ግሩም\nምስጋና አቅርቡ ለዘላለም\nበስነፍጥረት ይታወቃል\nየአለም ፈጣሪ እግዚአብሔር ቃል\nደስይበላቹ ደስ ይበለን በሉ እልል\n', 'am', 48, 0),\n(1, 'ደስ ይበለን', ' ደስ ይበለን\nደስ ይበለን በጣም ደስ ይበለን\nበረከቱን ለኛ ስላደለን\n\nበጨለማ ስኖር ደስ ይበለን\nበሀጥያት ተከበን\nየህይወት ብርሀን\nፍቅሩን አበራልን\nወደ ምስራቅ እንይ\nፀሀይ ወዳለበት\nጨለማ ልባችን\nጎህ እንዲቀድበት\n\nየፀሀይ እናቱ ደስ ይበለን\nማርያም እመቤቴ\nእለምንሻለው\nእስከ እለተሞቴ\nየልቤ ማረፍያ\nየዘለአለም ቤቴ\nአንቺ ነሽ ተስፋዬ\nእፀ መድሀኒቴ\n\nየግሸኗ ንግስት ደስ ይበለን\nየአምላክ እናቱ\nሆና ተሰጥታለች\nለሚመኩባት\nበልቼ ጠጥቼ\nየምረካብሽ\nጎጆ ማረፍያዬ\nማርያም አንቺ ነሽ\n\nፀአዳ እመቤቴ ደስ ይበለን\nሐመልማለ ሲና\nየሕዝቅኤል ደጃፍ\nየሙሴ ደመና\nየንጉስ ሙሽራ\nየዳዊት በገና\nየተዋበች እንቁ\nየደጎች አዝመራ\nበማህፀንሽ ፍሬ\nሕይወታችን በራ\n', 'am', 49, 0),\n(1, 'ደስ ይበለን ዛሬ', ' ደስ ይበለን ዛሬ\nደስ ይበለን ደስ ይበለን ዛሬ\nደስ ይበለን ደስ ይበለን በጣም\nየመከራው ለሊት ፈተናው ቢከብድም\nይኸው ለዚህ በቃን ይክበር መድሀኒያለም\n\nደስ ይበለን እንዳያልፉት የለም\nያዘመን ታለፈ\nእግዚአብሔር ልጆቹን ደርሶ እየደገፈ\nበቀን እና ለሊት\nአብሮን እየሰራ\nእንደፀሀይ ፀዳል ገፃችን አበራ\n\nደስ ይበለን ጥበበኛው ንጉስ\nባለ ፀጋው ጌታ\nእንደ ባለ ማእረግ አቆመን በተርታ\nያንሰዋል ምስጋና\nያንሰዋል ውዳሴ\nያስተማረን አምላክ የአብርሀሙ ስላሴ\n\nደስ ይበለን በትንሽ ትልቁ\nእየሰጋን ሳለ\nሁሉም ነገር ሆነ እግዚአብሔር እንዳለ\nቀሚስ አክሊላችን\nአምሮበታል ዛሬ\nምድር ታስተጋባ ታላቁን ዝማሬ\n\nደስ ይበለን ማን እንደ እግዚአብሔር\nማን እንደ አምላካችን\nበሀዘን በደስታ ለኛ መፅናኛችን\nክብር ለአንተ ይሁን\nየደመቀ እልልታ\nይህንን ቀን ባርከ ለሰጠከን ጌታ\n', 'am', 50, 0),\n(1, 'እቀኝለታለሁ', ' እቀኝለታለሁ\nእቀኝለታለሁ ዘምርለታለሁ\nበምስጋና ቃላት ስሙን እጠራለው\nያደረገልኝን ለአለም አወራለው\n\nበአንገቴ ላይ ውበት ሞገስ ጭኖብኝ\nበተራሮችም ራስ ከፍ ከፍ አድርጎኝ\nበዚች እውነት ይመስላል ማዳኑ ባወራ\nአቤት የእርሱ ፍቅር እፅብ ነው የሱ ስራ\n\nከገናናው ክብር ምህረቱን አይቼ\nእንደ ቦህር እግሮች ፅንተው እግሮቼ\nሞገድ ማዕበሉን ገስፆታል\nበቀን በሌሊት ይድረሰው ምስጋና\n\nከጨለማው አለም ከፊታች ጉዞ\nነጠቀኝ ከእሳት ውስጥ እጅና እግሬን ይዞ\nቅጥሩም ፈራረሰ በስሙ ሳይነካ\nወይ የእግዚአብሔር ስራ ይህም አለ ለካ\n\nበለመለመ መስክ በመልካሙ ስፍራ\nበአዕዋፍ ዝማሬ ህዝብን ይሰማል\nየዘላለም አባት እርሱ ነው አምላኬ\nእቀኝለታለሁ ፊቱ ተንበርክኬ\n', 'am', 51, 0),\n(1, 'ክብሬ ነው', 'ክብሬ ነው\nክብሬ ነው ክብርህን መናገሬ\nጽድቄ ነው ፍቅርህን መመስከሬ\nጌታዬ አምላኬ እልሀለው (2)\nስጠራ ሳመልክ እኖራለው (2)\n\nአይቼ የጅህን ታምራት\nሰምቼ የቃልህን ትምርት\nሆኛለው ምስክር ለአዳኝነት\nስጋን ተዋህደ ለኛ መገለጥ\n\nተከተልኩ ሁሉን ነገር ንቄ\nመድሀኒት መሆንክን አውቄ\nከመልካሟ ቤት ተጠልያለው\nየእጅህን በረከት ካንተ እጠግባለው\n\nእርፍ ይዤ ላላርስ ወደ ኋላ\nእያየው መረቤን ስትሞላ\nእመካብሀለው ባንተ መድህኔ\nአምላኬ ነህና የምትራራ ለኔ\nአባቴ ነህና የምትራራ ለኔ\n\nቸርነት ምረት ከበዛልኝ\nለስም ውዳሴ ቅኔ አለኝ\nክብሬና ሞገሴ አንተ ነህ ጌታ\nተመስገን (2) ጠዋት እና ማታ (2)\n', 'am', 52, 0),\n(1, 'በአምሳሉ', 'በአምሳሉ\nበአምሳሉ ለሰራኝ ለቅድስት ስላሴ\nበአራያው ለሰራኝ ለቅድስት ስላሴ\nእገዛለታለው በስጋም በነፍስ\n\nከድንዃኔ ገብቶ በቸርነት ያየኝ\nከሀገር ከወገን በዘመድ የለየኝ\nስሙን ሊያሸክመኝ ስሜን የቀየረው\nዘሬን እንደ አሸዋ ያበዛው እሱ ነው\nቅድስት ስላሴ\n\nስሙን እንድቀድስ ክብሩን እንድወርሰው\nእፍ ብሎብኛል የህይወት እስትን ፋስ\nከፍጥረቱ ሁሉ አርቆኛል ሰርቶ\nመንግስቱን እንድወርስ\n\nገና ሳልፈጠር ጀምሮ የሚያውቀኝ\nበበረከት አጦሮ ነገን የማያይልኝ\nበርሱ ነው መቆሜ በርሱነው መኖሬ\nትላንትን አልፌ መድረሴ ነው ዛሬ\nቅድስት ስላሴ\n\nበከሀሊነቱ ያመጣኝ ከምድር\nከፍጥረት ለይቶ የሰራኝ ለክብር\nየሚመሰገን ነው በአንድነት ሶስትነት\nእግዚአብሔር እርሱ ነው አምላከ አማልክት\nቅድስት ስላሴ\n', 'am', 53, 0),\n(1, 'ቸሩ ሆይ', ' ቸሩ ሆይ\nቸሩ ሆይ ቸሩ ሆይ ናና (፪)\nቸሩ ሆይ አማኑኤል ናና\nለኢትዮጲያ ቸሩ ሆይ ናና\nቸሩ ሆይ መድኃኔ አለም ናና\n\nቸሩ ሆይ ለአይነ ስውር መሪ\nምርኩዝ መመኪያ ነህ\nአንተን የሚመስል\nምንም ነገር የለም\nምህረትና ፍቅርህ\nወሰን ወደር የለው\nሳንወድህ ወደኸን\nፈልገህ ጠራኸን\n\nቸሩ ሆይ ሰምተህ እንዳልሰማህ\nአይተህ እንዳላየህ\nሁሉን ታልፈዋለህ\nፍቅራዊ አባት ነህ\nአማኑኤል ጌታ\nቸሩ ፈጣሪያችን\nውለታህ ብዙ ነው\nለኛ የዋልክልን\n\nቸሩ ሆይ በከብቶች ማደሪያ\nበዚያች ትንሽ ግርግም\nተወልዶ አዳነን\nጌታ መድኃኔ አለም\nእልል በሉ ሰዎች\nበአንድ ላይ ዘምሩ\nስብሀት ለእግዚአብሔር\nበአርያም በሉ\n', 'am', 54, 0),\n(1, 'ቅንነት', 'ቅንነት\nቅንነት የእግዚአብሄር ፊቱን ታየዋለች\nበእርሱም ስም ትመካለች\nሀጥያተኞችንም ታፀድቃለች\nቅንነት የእግዚአብሄር ፊቱን ታየዋለች\n\nአቤሜሌክ ሳራን ቢወስድም ቀምቶ\nለሀጥያት ቢቸኩል ለውበቷ ጓጉቶ\nየልቡ ቅንነት በእግዚአብሄር ፊት ታይቶ\nታርቋል ከአምላኩ ምህረትን አግኝቶ (2)\n\nተንኮል የሌለበት ልቡ ቅን የሆነ\nዳዊት ናትናኤልን ሙሴን የመሰለ\nይጠራዋል አምላክ ያነጋግረዋል\nበመንገዱ ሁሉ በፊቱ ይቀድማል (2)\n\nከይሁዳ እንራቅ እንሂድ ወደ ጴጥሮስ\nከዮሴፍ ጋር እንሁን እንሽሽ ከሄሮድስ\nከቃዪልም አቤል ከሳኦልም ዳዊት\nተመርጠዋልና በልብ ቅንነት (2)\n\nቅን ፍርድን ፍረዱ በመልክ አትፍረዱ\nእንዳለ ጌታችን ለአለም ለትውልዱ\nበእውነት እና በፍርድ ስራችንን እንስራ\nከፍርድ እንድናመልጥ ከጭንቅ ከመከራ (2)\n', 'am', 55, 0),\n(1, 'ዘፀአት ነው ለህዝቡ', ' ዘፀአት ነው ለህዝቡ\nዘፀአት ነው ለህዝቡ\nበደም ታስሯል ወጀቡ\nፅኑ ክብርን ያየነው\nኢየሱስን ይዘን ነው\nክርስቶስን ይዘን ነው\n\nየግብፅ ፈርኦን\nበግፍ ሲያስጨንቀን\nከቡዳ መዝራእት ሙሴ\nተነሳና ከራምሴ\nመንጋውን ይዞ ወጣ የቀና\nበሀቅለ ቃዲስ በሲና\nያ መንፈሳዊ መጠጥ\nያ መንፈሳዊ መብል\nክርስቶስ ነበረ እኛን የሚከተል\n\nበራፊድ እንዳንቀር\nተውልን ምስክር\nበኢያሱ ወልደ ነዌ\nእያዳነን ከአውሬ\nከነአን ሄደ በፊት አየመራ\nስሙ መድሀኒት ሆነን\nእስራኤል ዘነፍስ ነን\nድል አደረገው ጌታ\nእያሪኮ\n\nበፋርስ ነገስት ወድቆብን ባርነት\nበኤርሚያስ የነው በትር\nእየታየን በሚስጥር\nእንዳይበረታ ቅጥር አድርጎልን\nየእሳቱን ወጀብ አለፍን\nበምልክት በራዕይ ተብሎ በሰማይ\nማምለጫችን ሆነ በጎልጎታ ላይ\n\nከጠላታችን መዳፍ\nመከራ ቢወነጨፍ\nየጠበቀው መሲሕ ደርሷል\nሸክማችንም ተራግፏል\nየመቤዠት ቀን ቀርቦ ዘፀአት\nጠቅልለን ወጣን ከሞት\nበደሙ አጊጠናል እርስቱን እንወርሳለን\nበፅዮን ተራራ ለበጉ እየዘመርን\n', 'am', 56, 0),\n(1, 'ዝም አትበሉ', 'ዝም አትበሉ\nዝም አትበሉ እግዚአብሔር አመስግኑ\nቅዱስ (5) በሉ መላእክትን ሁሉ ምስጋናን ጀምሩ\nቅዱስ ቅዱሰ በሉ\n\nየሙሴ እህት ማርያም ከበሮውን አንሺ\nበምስጋና መዝሙር እስራኤልን ጥሪ\nአምላክን እናክብር እንዘምር በእልልታ\nከእኛ ጋር ይሆናል የሰራዊት ጌታ\n\nፍጥረታትም ጮሁ ሰማያት ዘመሩ\nስለ ቅድስናው ሁላቹም ዘምሩ\nዳዊት ሆይ ተነሳ ስለፅዮን ዘምር\nከበሮው ይመታ በገናው ይደርደር (2)\n\nወገኖች እንዘምር ለእግዚአብሔር ክብር\nውለታው ብዙ ነው ለኛ ያለው ፍቅር\nማዳኑን ያያችው ዘምሩ በእልልታ\nለጌታ ለእግዚአብሔር ለሰራዊት ጌታ (2)\n\nባህሩን አቋርጦ የሚያሻግራችው\nተራራውን ንዶ አቀለላችው\nበአውሎ ንፋስ መሀል መንገድ አለው ጌታ\nለንጉስ ክርስቶስ እንዘምር በእልልታ\n', 'am', 57, 0),\n(1, 'አምላክ እረዳኝ', 'አምላክ እረዳኝ\nአምላክ እረዳኝ ችግሬን አይቶ\nየለመንኩትን ጩኸቴን ሰምቶ\nከሰዎች እኩል ላደረገኝ\nአዲስ ምስጋና ተቀኘሁኝ\n\nብዙ መከራ በላዬ ፈሶ\nየህይወቴን ጣዕም ሁሉ አደፍርሶ\nቸሩ ጌታዬ አንተ አስቻልከኝ\nዛሬ ለመድረስ አበቃኸኝ\n\nየአፈሰስኩትን እንባ አብሶ\nየህይወቴን ጣዕም ሁሉ አደፍርሶ\nሳይንቀኝ አምላክ እኔን ጎበኘኝ\nከአእምሮ በላይ ደስታ ሆነልኝ\n\nብቻዬ መስሎኝ ሰግቼ ነበረ\nለካስ አምላኬ አለ ከእኔ ጋር\nየተናቁትን የሚደግፍ\nክንድ ብርቱ ነው መንግስቱ አያልፍ\n\nጎልያድ ንቆ ጉልበተኛውን\nተገዳደረ በማን አለብኝነት\nጉልበቱን አምኖ ግፍ የሰራው\nተበረከከ በአሸናፊው\n', 'am', 58, 0),\n(1, 'እግዚአብሔርን አመስግኑት', 'እግዚአብሔርን አመስግኑት\nእግዚአብሔር አመስግኑት\nስራው ግሩም ድንቅ ነው በሉት\nእግዚአብሔር አመስግኑ\nስራው ግሩም ድንቅ ነው በሉት\n\nሰማይን ያለ ምሶሶ\nምድርንም ያለመሰረት\nያፀናው እርሱ ነው\nስራህ ድንቅ ነው በሉ\n\nየባህርን ጥልቀት የመጠነ\nዳርቻዎቹንም የወሰነ\nእግዚአብሔር አመስግኑ\nስራህ ድንቅ ነው በሉ\n\nማእበል ንፋሱን የሚገስፅ\nፍጥረታት ለስሙ የሚታዘዝ\nትጉ እረኛ ድካም የሌለበት\nእግዚአብሔርን ስራ ድንቅ ነው በሉ\n\nንፁህ ባህሪይ ነው ሁሉን የሚገዛ\nየነገስታት ንጉስ አልፋና ኦሜጋ\nዘላለም እሱ የማይለወጥ\nእግዚአብሔር ስራ ድንቅ ነው በሉ\n\nጥበብን የሚገልጥ ጥበበኛ\nፍርድንም የሚያረግ እውነተኛ ዳኛ\nእንደሱ ያለ ከቶ አይገኝም\nእግዚአብሔር ግሩም ነው ዘለአለም\n', 'am', 59, 0),\n(1, 'ተመስገን እላለው', ' ተመስገን እላለው\nእግዚአብሔር ሆይ ተመስገን እላለው (2)\nለስምህ እዘምራለው\nለውለታህ ምን እከፍላለው\n\nበአማልክት መካከል እግዚአብሔር ሀያል ነው\nእርሱን የሚስተካከል ማነው የሚመስለው\nእግዚአብሔር በፅዮን ታላቅ ነገር ሰራ\nማነው የሚቆመው በፅዮን ተራራ\n\nየኤርትራን ባህር ከፍሎ ያሻገረ\nትህትናውን አይቶ በሙሴ ያደረ\nዛሬም ለሚሰሙት እግዚአብሔር ይሰማል\nየእሳቱን ባህር ከፍሎ ያሻግራል\n\nኑና ተመልከቱ እዩ ተደነቁ\nእግዚአብሔር ማዳኑን ምህረቱን እወቁ\nየታማኝ እረኛ በጎች ነን እና\nወደ በረት ግቡ ቁሙ ለምስጋና\n', 'am', 60, 0),\n(1, 'በመስቀል ተሰቅሎ', ' በመስቀል ተሰቅሎ\nበመስቀል ተሰቅሎ ፍቅሩን ለገለፀው\nምን ስጦታ አለ ለእርሱ የምንከፍለው\nምስጋና ነው እና ከኛ የሚፈልገው\nቸሩ አምላካችንን ተመስገን እንበለው\n\nአለም እስኪደነቅ ድንቅ አድርጎልናል\nእንዲህ ያለ ዋጋ ፀጋውን ሰቶናል\nትላንት ለእስራኤል ሞገስ የሆናቸው\nስሙን እናመስግን ዛሬም ከኛ ጋር ነው\n\nአፋችን ይመላ በታላቅ ምስጋና\nከሀጥያቱ ባህር ተሻግረናል እና\nክቡር ምስጉን አምላክ ቅዱስ እንበለው\nኢሳያስ በክብር በራእይ እንዳለው\n\nከቶ ለእግዚአብሔር ምን ይከፈለዋል\nሁሉም ለራሱ ነው ማን ምን ይለዋል\nአመስጋኝ ቢቀኝም ክብሩ ለራሱ ነው\nእርሱ በባህሪው ዘላለም ምስጉን ነው\n\nሙሴም ዝም አላለም ዳዊትም አልተኛም\nበጎቹ ዘመሩ ለመልካሙ እረኛ\nያሬድ ተመሰጠ ወደሰማይ አለም\nእኛም ከእነርሱ ጋር እንዘምር ዘለአለም\n', 'am', 61, 0),\n(1, 'እግዚአብሔርን ጠራውት በሀዘኔ ጊዜ', 'እግዚአብሔርን ጠራውት በሀዘኔ ጊዜ\nእግዚአብሔርን ጠራውት በሀዘኔ ግዜ\nእግዚአብሔር ጠራውት በችግሬ ግዜ\nአወጣኝ ከጭንቀት ከሀዘን ከትካዜ (2)\n\nየልመናዬን ድምፅ እርሱ ሰምቷል እና\nጆሮውን ወደኔ አዘንብሏል እና\nወደርሱ ስማፀን ደግሞም ስፀፀት {²}\nአላሳፈረኝም መጣ በምረት {²}\n\nእንደ ቃል መሄድ መራመድ አቅቶኝ\nየሀጥያቱ መንገድ ማእበሉ ገፍቶኝ\nወደርሱ ስማፀን ደግሞም ስፀፀት {²}\nአላሳፈረኝም መጣ በምህረት {²}\n\nኖህን እንዳዳንከው እኛንም አድነን\nከቀስቱ እንድናመልጥ ምልክትን ስጠን\nበትር ምርኩዝ እነርሱ ያፅናኑን {²}\nአንተ ከኔ ጋር ነህ አልፈራም ክፉውን {²}\n\nበበዛው ምረቱ ያለፈውን ትቶ\nበፍቅሩ ጎበኘኝ አልተወኝም ከቶ\nሊቀበለኝ ወዶ ፊቱን አበራልኝ {²}\nማን ይቃወመኛል እግዚአብሔር ካለልኝ {²}\n', 'am', 62, 0),\n(1, 'ከውለታ በላይ ነው', 'ከውለታ በላይ ነው\nከውለታ በላይ ነው ያንተ ውለታ\nከስጦታ በላይ ነው ያንተ ስጦታ\nስራህ አስገረመኝ ከፍ በል ጌታ\nእጄን በአፌ ጫንኩኝ ከፍ በል ጌታ\n\nእንዳላጠፈ ሰው ከቶ እንዳይበድል\nበሚያስደንቅ ፍቅር ሁሌ ታልፈኛለህ\nፀጋ ተትረፍርፎ በዛና ሰላሜ\nእጄን በአፌ ዙፋንህ ስር ቆሜ\n\nእግሮቼ ሲሮጡ ወደ ሞት ሸለቆ\nይቅርታህ መለሰኝ ከነበልባል ነጥቆ\nበጥበብ በትዕግስት ታሳድገኛለህ\nወይንህን ስጠብቅ መች ትሰለቻለህ\n\nቀና ብዬ ሳየው ሰማይ ማደሪያህን\nእጅግ አደንቃለሁ ግርማ ጌትነትክን\nዝቅ ስል ከቤቴ ስትሰራ አይሀለው\nከመገረም በቀር ሌላ ምን እላለው\n\nያልታሰበ ነገር አድርገህልኛል\nበጠላቶቼ ፊት አሞግሰህኛል\nመሰዋእትን ብሰዋ የከንፈሬን ፍሬ\nለስጦታህማ አልጠግብም ዘምሬ\n', 'am', 63, 0),\n(1, 'ሀይልን በሚሰጠኝ', 'ሀይልን በሚሰጠኝ\nሀይልን በሚሰጠኝ በክርስቶስ ሁሉን እችላለው (2)\nመከራ ቢገጥመኝ ለበጎ ነው ብዬ አልፋለው (2)\n\nበሰንሰለት አስረው በወይኒ ቢጥሉኝ\nመከራን አብዝተው እጅግ ቢያስጨንቁኝ\nለበጎ ነው ብዬ ተስፋ አርጌዋለው\nይሁን አንተ ያልከው እገዛልሀለው\n\nትላንትናም ዛሬም አንተ ያው አንተነህ\nፍቅርህ አይቀየር ወረትም የለብህ\nስምህን መጥራቴ ሞገሴ ሆኖኛል\nጠላቴ ቢፎክር መች ያስፈራራኛል\n\nበመከራ ፅናት ጉልበቴ ደከመ\nትካዜ ከብኛል ተስፋዬም ጨለመ\nነገር ቢሆን ባይሆን አንተን እንዳከብር\nአድለኝ በፀጋ ጌታዬ ያንተን ፍቅር\n\nከሀገር ወጥቼ በዱር መሰደዴ\nከባእዳን ሀገር ቆሜ በመሄዴ\nለበጎ ነው እና መቼ ይከፋኛል\nፈፅሞ እንዳልጠፋ እጅ ይይዘኛል\n', 'am', 64, 0),\n(1, 'አቤቱ እንዳንተ', 'አቤቱ እንዳንተ\nአቤቱ እንዳንተ ማነው\nበፍቅር ህይወቴን የባረከው\nእንደ ሳምራዊው ዘይቱን አፍስሶ\nአዳነኝ ጌታ ምህረቱን አስታውሶ\n\nመገፋቴን አይተ ለኔ ራራልኝ\nስድቤን አስወግደ ሞገስን ስጠኸኝ\nጥንት እንደሰማው አየው በአይኖቼ\nእቀኝለታለው ማደሪያ ገብቼ (3)\n\nከመሰውያ ስፍራ ብርቅም ከቤትህ\nመጣልኝ ፈለገኝ ይገርማል ምህረትህ\nወዴት ነው ያለከው ብለህ ጠርተከኛል\nግሩም ነው አምላኬ ማዳን ይደንቃል (3)\n\nበአይን አይተከኛል ከላይ ከሰማይ\nነፍሴን ታድገሀል የደሀ አደግ አባት\nከፊት እየመጣ መንገዴን መራከኝ\nጨለማዬ በርቷል አምላኬ ስለሆንክ (3)\n\nየህይወቴ መዝገብ ተገለጠ መፅሀፍ\nቀርቦኝ አይቻለው እኔን በመፃፉ\nምስክሩ እኔነኝ ፈፅሞ አላፍርም\nያደረገልኝን የውዴን ቸርነት (3)\n', 'am', 65, 0),\n(1, 'አለን አልጠፋንም', 'አለን አልጠፋንም\nአለን አልጠፋንም አልወደቅንም እኛ\nበቀንም በለሊት ልኡል ስላልተኛ\nነገም እኖራለን ስሙን ተከትለን\nዘመን ይቆጠራል ፊቱ ተሰልፈን\n\nብኖርም የርሱ ነን ብንሞትም የጌታ\nአዲስ ነገር የለም ትጥቅን የሚያስፈታ\nእደ አይኑ ብሌን ተግቶ ይጠብቀናል\nሁሉን በርሱ ጥለን ሀሳብ ቀሎልናል\n\nይጠፋሉ ሲሉ በሀሰት ትንቢታቸው\nበእግዚአብሔር አሰራር ቂም ቋጥሯል ልባቸው\nአበዛን አሰፋን በመልካም ፍቃዱ\nአይመረመርም የጌታ መንገዱ\n\nአይጠረጠርም የማዳኑ ጉልበት\nበድል እንመጣለን ክንዱን አምነንበት\nፈታኝ ጉድጓድ ገብቶ አፈር እስኪጫነው\nጊዜ አይፈጅበትም እየሱስ ጌታ ነው\n\nሞቶ ቆስሎ የፈወሰ\nበልባችን መሀል ፍቅሩን የቀነሰ\nአለቱን ሰንጥቆ አለፍን ያን ጨለማ\nበክብር እኖራለን በበጉ ከተማ\n', 'am', 66, 0),\n(1, 'ወደ ማደሪያው ገብቼ', 'ወደ ማደሪያው ገብቼ\nወደ ማደሪው ገብቼ ልስገድ ለእግዚአብሔር\nምስጋናን ላቅርብ ለስሙ ክብር\n\nአድርጎልኛል አመሰግናሀለው\nበአፀደ መቅደሱ እሰግድለታለው\nበፊቱ ለመቆም ማልጄ እነሳለው (፪)\n\nበመከራዬ ቀን ሆኖኛል መከታ\nቤቱ ተገንቼ በፍፁም ደስታ\nየከንፈሬን ፍሬ ልሰዋ በእልልታ (፪)\n\nአስር አውታር ባለው በበገና\nበመላዕክቱ ፊት ለማቅረብ ምስጋና\nየአፊንም ነገር ሰምተኸኛልና (፪)\n\nበስሙ ልበርከክ ለእርሱ እንደሚገባ\nስለቴን ልፈፅም ላቅርብለት መባ\nወደአደባባዪ በምስጋና ልግባ\n\nአሸበሽባለሁ ድምፄን አሰምቼ\nበቤተ መቅደሱ ለሊት ተገኝቼ\nእንደ ካህናቱ እጆቼን ዘርግቼ (፪)\n', 'am', 67, 0),\n(1, 'እፁብ ድንቅ ነው', 'እፁብ ድንቅ ነው\nእፁብ ድንቅ ነው አምላክ ወዶናል\nሕይወት የምትለምን እናት ሰቶናል\n\nየወደደን ጌታ አይጥለንም ዛሬ\nመድኃኒት ሆኖናል የመህፀንሽ ፍሬ\nእንወድሻለን ማርያም አዛኝት\nተስፋችን ነሽና የእኛ ትምክህት (፪)\n\nእኛን የማዳኑን ጥበብ ይደንቃል\nስጋን ነስቶ ከአንቺ ተወለደ የአብ ቃል\nአንቺም የአምላክ እናት ክብርት በመሆንሽ\nእመቤቴ ማርያም (፪) እጅግ ደስ ይበልሽ\n\nየፅድቃችን ሚዛን ቢመዘንም ቅሉ\nበጥላሽ ይበልጣል ድንግል ንዒ ቶሎ\nበእፍኝ ጥሬ ውሀ ጌታ ቃል ገባልሽ\nየዘከረ እንዲድን (፪) ድንግል ሆይ በስምሽ\n', 'am', 68, 0),\n(1, 'ዝናውን ሰምቼ', 'ዝናውን ሰምቼ\nዝናውን ሰምቼ ፈለኩት\nበሾላ ላይ ሆኜ አየሁት\nከአንተ ጋር ነኝ አለኝ መድኃኒቴ\nዛሬ መዳን ሆነኝ ለቤቴ\n\nየረከሰውን ቤቴን ጌታዬ ሳይንቀው\nጨለማውን ገፎ ብርሀን አለበሰው\nለገናናው ስሙ ለእርሱ ተንበርክኬ\nዛሬ ተለወጠ ጎስቋላው ታሪኬ\n\nእንደምን ወደደኝ ምን አግኝቶ ከእኔ\nሕይወቴ ያደፈ ነው የገባው ኩነኔ\nእርሱ ግን ጎበኘኝ በማዳን አዋጅ\nስሙን አተመብኝ አደረገኝ ልጁ\n\nካለኝ እኮሌታ ለድሃ እሰጣለሁ\nየበደልኩትን ሰው በእጥፉ እክሳለሁ\nያንተ ካደረከኝ ያንተው ነኝ ብያለሁ\nንገስብኝ አምላክ እገዛለሁ\n\nየአብርሃም አባት የእስራኤል መና\nየጠፋን ሲፈልግ ሊያድን መጥቷልና\nእኔንም ጎበኘኝ በማዳኑ ጥሪ\nወረታውን ከፋይ ነፍሴ ሆይ ዘምሪ\n', 'am', 69, 0),\n(1, 'ልመናዬን ስማኝ', 'ልመናዬን ስማኝ\nልመናዬን ስማኝ መድኃኒቴ (፪)\nአፌን ከፍተ ለምስጋና ቸሩ አባቴ\n\nከጨለማ ጉዞ መድኃኒቴ\nከአለም ሊለየኝ ቸሩ አባቴ\nእርሱ ፈቅዶ ወዶ መድኃኒቴ\nለቤቴ ካበቃኝ ቸሩ አባቴ\nለቸሩ አምላኬ መድኃኒቴ\nለፈጠረኝ ጌታ ቸሩ አባቴ\nእቀኝለታለው መድኃኒቴ\nሁሌ ጠዋት ማታ ቸሩ አባቴ\n\nመክበርን ያውቅበታል መድኃኒቴ\nምንም አይሳነውም ቸሩ አባቴ\nበእውነት ከጠየቅነው መድኃኒቴ\nሁሉም በእጁ ነው ቸሩ አባቴ\nያልሰጠን ምን አለ መድኃኒቴ\nለእኛ ያላረገው ቸሩ አባቴ\nፍቅሩን በመስቀል ላይ መድኃኒቴ\nበሞት የገለፀው ቸሩ አባቴ\n\nየነገስታት ንጉስ መድኃኒቴ\nየጌቶች ጌታ ቸሩ አባቴ\nተስፋዬ አንተ ነህ መድኃኒቴ\nየህይወቴ ዋልታ ቸሩ አባቴ\nልመና ፀሎቴን መድኃኒቴ\nየምትቀበለው ቸሩ አባቴ\nበእኔ ስራ አይደለም መድኃኒቴ\nበቸርነት ቸሩ አባቴ\n', 'am', 70, 0),\n(1, 'ብርሃን የለበሱ', 'ብርሃን የለበሱ\nብርሃን የለበሱ በሰማያት ያሉ\nእንደ እግዚአብሔር ከቶ ማንም የለም\n\nውኃችን በእልፍኙ የሰፈረ\nተራሮችን በሚዛን የመዘነ\nሰማይን በስንዝር የሚለካ\nዘመንን በዘመን የሚተካ (፪)\n\nከዓለም በፊት የነበረ\nፍጥረታትን ሁሉ የፈጠረ\nበምድር ክብነት የሚቀመጥ\nሁሉን ሲለወጥ የማይለወጥ (፪)\n\nከሀሊ ኩሉ ሁሉንም የሚያውቅ\nፈታዬ በፅድቅ ስራው ረቂቅ\nዓለምን የመላ ፈጥሮ የሚገዛ\nመዓቱ የራቀ ምህረቱ የበዛ (፪)\n\nዙፋኑ የፀና በሰማይ\nሁሉን የሚችለው አዶናይ\nየዘመኑ ፍፃሜ የሌለው\nአልፋ ኦሜጋ አምላክ ነው (፪)\n', 'am', 71, 0),\n(1, 'አማኑኤል ናና', 'አማኑኤል ናና\nአማኑኤል ናና መድኃኒዓለም ናና አማኑኤል ናና\nበቀኙ ለመቆም እንሻለንና አማኑኤል ናና\n\nእግዚአብሔር አምላክ አማኑኤል ናና\nበገሀድ ይመጣል መድኃኔዓለም ናና\nየሚያቃጥል እሳት አማኑኤል ናና\nበፊቱ ይነዳል መድኃኔዓለም ናና\nፍሬና ገለባ አማኑኤል ናና\nበስልጣኑ ይለያል መድኃኔዓለም ናና\n\nጌታ ስትመጣ አማኑኤል ናና\nበሚያስፈራ ግርማ መድኃኔዓለም ናና\nመላዕክት ሲነግዱ አማኑኤል ናና\nከሰማይ ከራማ መድኃኔዓለም ናና\nማነው የሚቆመው አማኑኤል ናና\nከፃድቃን ከተማ መድኃኔዓለም ናና\n\nላንተ የሚያስደስት አማኑኤል ናና\nምግባር ስላልሰራን መድኃኔዓለም ናና\nምን ትመልስ ይሁን አማኑኤል ናና\nነፍሴን ስትጠራ መድኃኔዓለም ናና\n\nኩናኔው በርትዕ ነህ አማኑኤል ናና\nፈታሄ በፅድቅ መድኃኔዓለም ናና\nባለፀጋ ደሃ ኤማኑኤል ናና\nብለህ የማትንቅ መድኃኔዓለም ናና\nቸርነትህ ይርዳኝ አማኑኤል ናና\nሲዖል እንዳልወድቅ መድኃኔዓለም ናና\n\nናፍቃኛለች አማኑኤል ናና\nመንግስተ ሰማያት መድኃኔዓለም ናና\nዘላለም በሙሉ አማኑኤል ናና\nሰላም ያለበት መድኃኔዓለም ናና\nከእመ ብርሃን ጋራ አማኑኤል ናና\nየምንኖርበት መድኃኔዓለም ናና\n', 'am', 72, 0),\n(1, 'ጌታ ሆይ ለስምህ', 'ጌታ ሆይ ለስምህ\nጌታ ሆይ ለስምህ እዘምራለሁ\nልዑል ሆይ ለክብርህ እልል እላለው\nበአንተ ደስ ይለኛል ሐሴት አደርጋለው (፪)\n\nየበዛ ምህረትህ በእኔ ላይ ተገልጧል\nየትላንቱ ስሜ በአንተ ተለውጧል\nሞገስ ስለሆንከኝ ከፊትህ ቆምያለሁ\nበአውደ ምህረትህ ስምክን እጠራለሁ\n\nያለቀውን ነገር የተቆረጠውን\nትቀጥለዋለህ ለአንተ አይሳንህም\nመቃብሩን ከፍተህ መግረዝ የምትፈታ\nየሞትም ጌታ ነህ የድሆች አለኝታ\n\nአንተ የመረጥከው ማነው የሚከሰው\nያከበርከውንስ ማነው የሚቃወመው\nበሰው ፊት የሚታይ ደምግባት ባይኖረኝ\nጸጋህ ይበቃኛል አዘምራለሁኝ\n\nእኔ ቀንቻለሁ አምላኬ ለክብርህ\nበልቦናዬ ውስጥ እስኪሳል መስቀልህ\nየተጋረደውን አዚሙን አንሳልኝ\nውለታውን አውቄ በአንተ ደስ እንዲለኝ\n', 'am', 73, 0),\n(1, 'ክርስቶስ ሆይ', 'ክርስቶስ ሆይ\nክርስቶስ ሆይ እጠረሃለው\nጌታዬ ሆይ እጠረሃለው\nኃጥዕ ልጅህ ወዳንተ እጮሃለው\nኃጥዕ ባሪያ ወደ አንተ እጮኻለሁ\n\nኖህን እንዳዳንከው እጠረሃለው\nከዚያ ከመከራ እጠረሃለው\nሎጥንም ያዳንከው እጠረሃለው\nከልጆቹ ጋራ እጠረሃለው\nምስኪን ልጅህ እኔንም አደራ\nነብሴ ትኑር ስምህን አክብራ\n\nበሞት ጥላ ሀገር እጠረሀለው\nብሔድም አልፈራም እጠረሀለው\nከህመም የዳንኩኝ እጠረሀለው\nስምህን ስጠራ እጠረሀለው\nበለመለመ መስክ ታሰማራኛለህ\nባለሁበት ትጠብሸኛለህ\n\nከዘመድ እርቄ እጠረሃለው\nበባዕድ ሀገር ስኖር እጠረሃለው\nናፍቆት ሲበረታ እጠረሃለው\nኑሮዬም ሲከብደኝ እጠረሃለው\nበእንባ ሆኞ አንተን እጠራለው\nአይዞ በለኝ በቃልህ እፅናናለው\n', 'am', 74, 0),\n(1, 'በጉዛችን እርዳን', 'በጉዛችን እርዳን\nቸርነትህ ብዙ ምህረት ብዙ\nበጉዛችን እርዳን ጠባብ ነው መንገዱ\nድንቅ ነዉ አምላክ ሆይ ፍቅር ለእኛ\n\nእስራኤል ወደቀ እስራኤል ተነሳ (፪)\nመንገዱ አልቀናውም አምላኩን ሲረሳ (፪)\nየያዕቆብ አምላክ እግዚአብሔር ይዞ (፪)\nምን እንዳተረፈ አውቆታል በጉዞ (፪)\n\nመንገዱ አይታክትም ጎዳናው የቀና (፪)\nእግዚአብሔር ከፊትም ከኃላም አለና (፪)\nእርሱ በሌለበት ቢመችም መንገዱ (፪)\nአቅጣጫው ወደ ሞት አይቀርም መውሰዱ (፪)\n\nበመንገዱ ዝለት ወድቀን መች ቀርተናል (፪)\nየያዕቆብ አምላክ ደግፎ አንስቶናል (፪)\nእግዚአብሔር ሲጠራን በቀደመው መንገድ (፪)\nጉዟችን ወዴት ነው በሞት ለመወሰድ (፪)\n\nአምላክ ሆይ ፍቅርህን በልባችን ሳለው (፪)\nአስከ ሞት በመስቀል የወደደን ማነው (፪)\nበበረሀው ፅናት ሲጠናብን ራቡ (፪)\nበረከት ሞላኃው ተረፈልን ምግቡ (፪)\n', 'am', 75, 0),\n(1, 'ላመስግንህ', ' ላመስግንህ\nላመስግን የኔ ጌታ ላመስግን\nልቀኝልህ የኔ ጌታ ልቀኝልህ\nሕይወቴ ነው ዝማሪዬ ትሩፋቴ\nየሰጠኸኝ እንዳከብርህ አንተ አባቴ (፪)\n\nከእኔ የሆነው የምሰጥህ ባይኖረኝም\nከሰጠኸኝ ያንተን መስጠት አይከብደኝም\nጥበቤ ነው የምስጋና መሠረቴ\nዝማሬዬን ያፈሰስከው በሕይወቴ\nአንደበቴን የቃኘኸው ለምስጋና\nይኸወ ውሰድ ቅኝትህን እንደገና (፪)\n\nቦዶ እኮነኝ የኔ ጌታ ምን ልቅዳልህ\nበእጄ ላይ አንዳች የለኝ የምሰጥህ\nላንተ ክብር የሚመጥን ሕይወት የለኝ\nዝማሬዬን በቸርነት ተቀበለኝ\n\nከምድር ላይ ከአፈር ስትፈጥረኝ\nከምስጋና የተለየ ምን ስራ አሉኝ\nቀንና ሌት በመቅደስህ እቆማለው\nአምላኬ ሆይ ሳወድስህ እኖራለው\n\nእዝራ ስጠኝ የከበረ መሰንቆህን\nዳዊት ስጠኝ የሚፈውስ በገናህን\nመዝሙር ቅኔ ተምሪያለው ከአባቶቼ\nእዘምራለው በአንተ ፍቅር ተነክቼ\n', 'am', 76, 0),\n(1, 'የተወደደ ቀን', 'የተወደደ ቀን\nየተወደደ ቀን የተወደደ አመት\nወደ አባቴ መቅደስ የተመለስኩበት\nአንባር ቀለበቴን የተሸለምኩበት\nየተወደደ አመት\n\nአዝ፦\nአምሽቶ የመጣ (አይገባም አትበሉ) (2)\nአባክኖ የመጣ (አይገባም አትበሉ) (2)\nፍቅር ስለሆነ (እግዚያብሄር ለሁሉ) (2)\nልጅ ቤቱን ይወርሳል (እንደተስፋ ቃሉ) (2)\n\nአዝ፦\nከናዝሬት መልካም ሰው (አይወጣም እያሉ) (2)\nፊሊጾስ ናትኤል (ይነጋገራሉ) (2)\nአድርጎታልና (ውሀውን ወይን) (2)\nዛሬም ለውጦታል (ወስዶታል ልቤን) (2)\n\nአዝ፦\nእኔነኝ አላማው (እኔነኝ ሀሳቡ) (2)\nአባቴ ደግ ነው (ለሚራራ ልቡ) (2)\nዘጠና ዘጠኙ (ታምነውት እያለ) (2)\nአንዱን ይፈልጋል (ወዴትነህ እያለ) (2)\n\nአዝ፦\nሁሉን አይቻለው (ሁሉን መርምራለው) (2)\nአለም ካንተ ሌላ (እንደሌለ አውቃለው) (2)\nእንደማይለወጥ (አባትነትህ) (2)\nጠፍቼ ስመጣ (አየሁት ልጅህ) (2)\n\nአዝ፦\nከቦንጋ መልካም ሰዉ (አይወጣም እያሉ) (2)\nአህዛብ መናፍቅ (ይዘባበታሉ) (2)\nሰብስቦናልና (ገብርኤል በምልጃው) (2)\nአያስጨንቀንም (የጠላት እርምጃዉ) (2)\n', 'am', 77, 0),\n(1, 'በዘመናት የሸመገለ', 'በዘመናት የሸመገለ\nበዘመናት የሸመገለ\nክብርን ሁሉ የጠቀለለ\nእንደ ጌታ ኧረ ማን አለ\nእንደ እግዚአብሔር ኧረ ማን አለ\n\nጥሎብኛል መጎናጸፊያ\nለይቶኛል ከስጋ ጥፍፊያ\nበሰው ሚዛን ክብርን ማይለካ\nእውነተኛ ጌታ ነው ለካ\n\nደመና ነው መንኮራኩሩ\nነበልባል ነው ዙፋን መንበሩ\nመሰወሪያው አይደረስም\nበማንም ሞት አይከሰስም\n\nቀን ዘመናት ሁሉ ሲያረጁ\nአዲሶቹ ዘምነው ሲጃጁ\nጌታ አዲስ ነው ሁሌ ማለዳ\nፍቅር ያዘንባል ከልቡ ጓዳ\n\nመካኒቱን በልጅ ባረከ\nኃይለኛውን አንበረከከ\nለምስጊኖች ስለሚራራ\nበኢየሱስ ልባችን ኮራ', 'am', 78, 0),\n(1, 'እውነት ስለሆነ', 'እውነት ስለሆነ\nእውነት ስለሆነ ኢየሱስ ክርስቶስ\nዋለ ባደባባይ ሲሰደብ ሲከሰስ\nየሀሰት ዳኝነት አምላክን ወቀሰው\nህይወት ሰጠን እንጂ ጥፋቱ ምንድነው (2)\n\nአዝ፦\nከቃሉ እብለትን ባያገኙበትም\nዝምታውን አይተው አላዘኑለትም\nባላወቁት መጠን ጠሉት ካለበደል\nጥፋቱ ምን ይሆን የሚያደርስ ከመስቀል (2)\n\nአዝ፦\nየልቡን ትህትና ፍቅሩን ሳያስተውሉ\nቸሩ ጌታችንን አቻኩለው ሰቀሉ\nእሩህሩሁን ጌታ ቸንክረው ሰቀሉት\nሞትን አስውግዶ ቢሰጣቸው ህይወት (2)\n\nአዝ፦\nስለ ቸርነቱ ስድብን ከፈሉት\nስለ ርህራሄው የሾህ አክሊል ሰጡት\nሀሞትና ከርቤ ሆምጣጤ ደባልቀው\nመራራ አስጎነጩት ጨክኖልባቸው (2)\n\nአዝ፦\nፈውስን ለሰጣቸው ልባቸውን ሞልተው\nአሉት ወንበዴ ነው ስቀለው ስቀለው\nከጁ በረከትን የተሻሙ ሁሉ\nይጮሁ ነበረ ይገደል እያሉ (2)', 'am', 79, 0),\n(1, 'የሚጠብቀኝ አይተኛም', 'የሚጠብቀኝ አይተኛም\nየሚጠብቀኝ አይተኛም (2)\nአያንቀላፋም (2)\n\nቤት ባይኖረኝም እደጅ ባድርም\nቀን እና ሌሊት ከእኔ አይርቅም\nድምጸ አራዊት የሌሊት ግርማ\nወደ እኔ አይቀርብም ድምጽህ ሲሰማ\n\nአዝ፦\nመሰናክልን ለእግሮቼ አይሰጥም\nይሰውረኛል በቀኙ ሰላም\nፀሐይም በቀን አይተኩሰኝም\nየአጋንንትም ኃይል አያስፈራኝም\n\nአዝ፦\nነፍሴን ጠበቃት ከጠላት ወጥመድ\nጌታዬ መራኝ በጽድቅ መንገድ\nመውጣት መግባቴን እየጠበቀ\nለዚህ አበቃኝ እርሱ ባወቀ\n\nአዝ፦\nየሰማዩን ጠል እታገሳለው\nሰው ከጨከነ ምን እሆናለው\nሌሊት በድብቅ ለሚጎበኙኝ\nለጻድቃኑ ክብር አምላክ ይስጥልኝ\n\nአዝ፦\nእንቅልፌን ባርኮ የሰጠኝ የጌታ\nበአለም ሀሳብ ሳልንገላታ\nየእለት ምግቤንም ላልነሳኝ ፍጹም\nምስጋና ላቅርብ እስከ ዘለዓለም\n', 'am', 80, 0),\n(1, 'በይስሐቅ ፈንታ', ' በይስሐቅ ፈንታ\nበይስሀቅ ፈንታ ኢየሱስ ታረደ (2)\nደሙን ከፈለና አዳምን ታደገ (2)\nተጨነቀ ጌታ ተሰቃየ ጌታ\nየእኔ መድኃኔዓለም የአዳም ልጅ አለኝታ\nእንደሚታረድ በግ ተነዳ ወደሞት\nንጹህ ኢየሱስ በደል የሌለበት\n\nአዝ፦\nእርሱ ተሸክሞ የአዳምን መከራ\nስቃይ ተቀበለ ደሙን እየተዘራ\nለሚገርፉት ሁሉ ምኅረትን ሲቸር\nእርሱ ግን ሲገረፍ ብዙ ተቸገረ\n\nአዝ፦\nየሰማነዉ ስም ማን ሰዉ እንኳ አምኗል\nየእግዚአብሔርስ ክንድ ለነማን ተገልጾል\nባየነዉስ ጊዜ ህመም ተሸክሞ\nስለበደላችን ተገርፎና ታሞ\n\nአዝ፦\nእጁ እየታሰረ ይስሐቅ ተፈታ\nኢየሱስ ቀረበ በሰዉ ልጆች ፈንታ\nንጹህ በግ ቀረበ በደል የሌለበት በደለኛ ሆኖ\nሊሰቀል ሊገደል መስቀል ተጭኖ\n\nአዝ፦\nተቆጠረ እንጂ እንደተቸገረ\nበደዌ በህመም ማቆ እንደኖረ\nአምላክ ለእኛ ብሎ ተናቀ በሰዎች\nእየተጸየፉት ተፉበት ብዙዎች\n\nአዝ፦\nበእዉነት ደዌያችንን እርሱ ተቀበለ\nበሰዉ ልጆች ፈንታ በእንጨት ተሰቀለ\nእኛ ግን ከሰስነዉ እንደ ወንጀለኛ\nበእኛ ሲሰቀል ሰማያዊው ዳኛ\n\nአዝ፦\nለሰዉ ልጆች ሕይወት የታሰበዉ ሰይፍ\nአይተናል ሰምተናል በኢየሱስ አንገት ሲያልፍ\nየመስቀሉ ስዕል ኧረ እንዴት ይገርማል\nእዩት ንጹሁ በግ በአርምሞ ይነዳል\n', 'am', 81, 0),\n(1, 'ማረኝ መመኪያዬ', ' ማረኝ መመኪያዬ\nማረኝ ማረኝ ማረኝ መመኪያዬ\nአርጅቻለሁ እኔ (በኃጥያት ጎስቁዬ) (2)\n\nከፊቴ ናትና ኃጥያቴ ሁል ጊዜ\nተውጫለሁ እኔስ (በሀዘን በትካዜ) (2)\nበፊትህ ክፋትን አድርጌያለሁ እኔ\nምንም ጽድቅ አልሠራው (በሕይወት ዘመኔ) (2)\n\nአዝ፦\nከፊትህ መቅበዝበዝ መሠደድ ፈለኩኝ\nኃጥያት ከሁዋላዬ (እያሳደደችኝ) (2)\nወዴት አሄዳለው መሸሸጊያም የለኝ\nምህረት መጠጊያ (ዋሻ ካልሆነችኝ) (2)\n\nአዝ፦\nየተሰባበረው አጥንቴ እንዲጠገን\nበምህረት እና (በቸርነት ዳሠኝ) (2)\nየቀና መንፈስን አድስ በልቤ ውስጥ\nነፍሴ በእሺታ (በደስታ ትለወጥ) (2)\n\nአዝ፦\nቅዱስ መንፈስህን ከኔ ላይ አትውሠድ\nበንስሐ ድኜ (በተስፋ እንድላመድ) (2)\nአቤቱ ንፁህ ልብ ፍጠርልኝና\nበደስታ ልስከር (በፍቅርህ ልፅናና) (2)\n', 'am', 82, 0),\n(1, 'በርተሚዮስ ነኝ', 'በርተሚዮስ ነኝ\nበርተሚዮስ ነኝ የአይነ ስውር ምስኪን\nከሩቅ የሰማሁት የጌታዬ ድምፁን\nከብዙ ሁካታ ጉርምርምታ መሃል\nየክርስቶስ ድምፁ በግልፅ ይሰማኛል (2)\n\nየልቦናዬ አይን ፈጽሞ ታውሯል\nአይኔን ፈውስልኝ በርተሚዮስ ይላል\nአብዝቼ እጮሃለሁ ጌታ ማረኝ ብዬ\nበውስጤ እየታየኝ ሲምረኝ ጌታዬ (2)\n\nአንተን አይሰማህም ይሉኛል ብዙዎች\nበሀጢያት ሰንሰለት ታስረሃል እቅተዎች\nስለዚህ አትልፋ ሲኦልን ጠብቃት\nእንደዚህ ቢሉኝም እጮሃለሁ ሳልታክት (2)\n\nየከበበውን ሰው ገለል በሉ እያለ\nበደሌን በደሙ ዋጋ እየከፈለ\nስለኔ የሞተው እየሱስ ይመጣል\nየልቦናዬን አይን ገልጦ ያሳየኛል (2)\n\nአብዝቼ እጮሃለሁ ጌታ ማረኝ ብዬ\nበግልጽ እየታየኝ ሲምረኝ ጌታዬ\nበውስጤ በደልስ ህይወቴ ዝላለች\nበአምላኬ ቸርነት ህይወት ካላገኘች (2)\n', 'am', 83, 0),\n(1, 'ሃሌ ሃሌ ሉያ', 'ሃሌ ሃሌ ሉያ\nየማይመረመር ክብርና ምስጋና\nበሰማይ ለእግዚአብሔር ይገባዋልና\nመላእክት ለቅጽበት መች ያቋርጣሉ\nያመሰግኑሃል ሃሌ ሉያ እያሉ\n\nሃሌ ሃሌ ሉያ ሃሌ ሃሌ ሉያ\nፍጥረታት ለእግዚአብሔር ያቅርቡ ምስጋና (2)\n\nአዝ፦\nጽርሀ ርያምን ዙፋን ያደረገ\nየእሳት መጋረጃ በእዛ የጋረደ\nበብርሃን ጸዳል መንበረ መንግሥትን\nፈጠረው እግዚአብሔር ግድግዳ እንዲሆን\n\nአዝ፦\nካህናተ ሰማይ መንበሩን ያጥናሉ\nቅዱስ ቅዱስ ቅዱስ ብለው ያመሰግናሉ\nየሥላሴ መንበር በምን ይመሰላል\nከግምት በላይ ነው ለማሰብ ያቅታል\n\nአዝ፦\nዙፋኑ በእሳት የተቀጸረ ነው\nበቤቶቹም ዙሪያ የውሃ መርገፍ አለው\nበሰማይ ውዱድ ዘባነ ኪሩቤል\nየሰማዩ ስራ እጅግ ያስገርማል\n\nአዝ፦\nበእሳት ነበልባል የተቀጸረችው\nከምድር እስከ ሰማይ የምትናፈቀው\nእየሩሳሌም ነች ፍጹም ሰማያዊ\nልዩ ህብር ያላት ዕንቁ ናት ሐምራዊ\n\nአዝ፦\nታቦት ዘዶር በዚያ ከመሀሏ አለ\nመልኳ የሚያንጸባርቅ ብርሃኗ ያየለ\nበእመቤታችን የምትመሰል ነች\nለቃሉ ማደሪያ በድንቅ የተሰራች\n\nአዝ፦\nኢዮርና ራማ ኤረርም በግርማ\nይባላሉ ከጥንት የመላዕክት ከተማ\nመላእክትም በዚያ እያሸበሸቡ\nይኖራሉ ለአምላክ ምስጋና ሲያቀርቡ\n', 'am', 84, 0),\n(1, 'ነፍሴ ሆይ', 'ነፍሴ ሆይ\nነፍሴ ሆይ (3) እግዚአብሔርን ባርኪ\nአጥንቶቼም ሁሉ (3) የተቀደሰ ስሙን\n\nአዝ፦\nበደስታ ዘምሪ በአዲስ ምስጋና\nጸጥታና ሰላም አድሎሻልና\nመሠንቆውን አንሺ ቅኔ ተቀኚለት\nለውጦሻልና በደስታ ዘይት\n\nአዝ፦\nሀሴትን አድርጊ ነፍሴ በእግዚአብሔር\nይሰጥሻልና በክብር ላይ ክብር\nደሴቶች ሲያወሩ በደስታ መንፈስ\nእየተወያዩ ስለ ሥሉስ ቅዱስ\n\nአዝ፦\nሰማያት ሲያወሩ ጽድቅን ሲወያዩ\nሲጠራው አድምጪ ቀላዩን ቀላዩ\nደመናው ጭጋጉ በዙሪያው ከበውት\nቅኔ ያቀርባሉ ለፍጥረታት አባት\n\nአዝ፦\nመብረቅም ይሰማል ሰማዩን ሰንጥቆ\nምስጋናውን ሊያቀርብ ጊዜውን ጠብቆ\nበፊቱ ይነዳል እሳትም በግርማው\nምድር ተናወጠች ነጎድጓዱን ሰማው\n', 'am', 86, 0),\n(1, 'የጴጥሮስን እንባ', 'የጴጥሮስን እንባ\nየጴጥሮስን እንባ ስጠኝ እልሀለሁ\nኃጢአቴን ልናዘዝ ፍቅርህን እያየሁ\nበሞት ጥላ ውስጥ እንኳን ብሄድ ጌታ ሆይ\nልቤን በፍቅር ውሃ እጠበው እባክህ (2)\n\nአዝ፦\nቸርነትህ በዝቶ ምህረት ቢያሰጠኝ\nእጆቼን ዘርግቼ እማጸናለሁኝ\nደምህ የፈሰሰው ለኔ ስለሆነ\nበኃጢአት ልትተወኝ ልብህ አልጨከነም (2)\n\nአዝ፦\nዓለማዊ ምግባር ልቤ ቢከተልም\nከዚህ ሁሉ ማዳን ጌታ አይሳንህም\nኃጢአት እየሰራሁኝ ባስቀይምህም\nበሂሶጵ እርጨኝ ጌታ እጠበኝ እባክህ (2)\n\nአዝ፦\nዲያቢሎስ ያመጣው ጸጸቴ ውድቀት ነው\nየይሁዳ ምሬት የሞት ነው ፍፃሜው\nይህንን መማረር እኔ አልፈልግም\nየውድቀት ጉዞ እንጂ ትንሳኤ የለውም (2)\n\nአዝ፦\nጴጥሮስ አባ ብሎ የተማጸነበት\nፍቅሩን በንስሀ ስቦ ያመጣበት\nፍጻሜው የሚያምር ንስሀ ስጠኝ\nየልቅሶ አምሐ የእንባን ህይወት ስጠኝ (2)\n', 'am', 87, 0),\n(1, 'በዕፀ መስቀሉ', ' በዕፀ መስቀሉ\nበዕፀ መስቀሉ የተከፈለልኝ\nየኢየሱስ ፍቅር ምንኛ ማረከኝ\nከፍቅርም በላይ ሆነና መሠጠኝ\nከመስቀል ሥር ሁኜ ፊቱን እያየሁኝ\n\nዓለምን በፍቅሩ ያሸነፈ ጌታ\nየጸብን ማዕበል በፍቅሩ የገታ\nሕይወቴን ጸጥ አድርጎ ይምራት በምልሐቱ\nእኔ ምን አለፍኝ አልደክምም በከንቱ\n\nአዝ፦\nደሙ ከወዙ ጋር ተዋሕዶ ሲወርድ\nበእኔ በደል ጌታዬ ቀረብልኝ ለፍርድ\nሀጥያቴን በጫንቃዉ ተሸክሞልኛል\nበደሌን ደምሥሶ ንፁሕ አድርጎኛል\n\nአዝ፦\nየቀራንዮ ግፍ በአንተ ላይ የሆነዉ\nሰይጣንን ጠርቆ ከመንገድ አወጣዉ\nእሾሕ አሜኬላዉ ተደምስሶልናል\nየንጹሕ በግ ደም አዳምን ታድጓል\n\nአዝ፦\nይኽንን ሥጋዬን ብሉ ይላችሁዋል\nይኽንን ደሜንም ጠጡ ይላችሁዋል\nከመስቀል ሥር ሆነን ደሙን እንቀበል\nሥጋዉን እንብላ ሠዉ ሆይ ችላ አንበል\n', 'am', 88, 0),\n(1, 'ለመዳኑ ህይወት', ' ለመዳኑ ህይወት\nለመዳኑ ህይወት ለጽድቁ ጠርቼህ\nከዓለም ለይቼ በፍቅሬ መርጬህ\nበረከትና ፍቅር ሰላሜን ወርውረህ\nልጄ የምወድህ እባክህ ወዴት ነህ\nይልሃል እግዚአብሔር እባክህ ወዴት ነህ\n\nከዓለም ጉያ ውስጥ ሽብር ከተሞላው\nከስንጥቅ አለት ውስጥ ጎድጓዳ ከሆነው\nየአራዊቱ ግርማ ያንበሶቹ ግሳት\nየዘንዶው ትርምስምስ የእባቦቹ ፉጨት\nየጨለማው ክብደት የፍጥረት ማዛጋት\nእንዲህ ያለ ስፍራ ተወርውረህ ነወይ\nቀናት ተቆጠሩ አይኖችህን ሳላይ\n\nአዝ፦\nከቅዳሴው ዕጣን ምስጋና ስቀበል\nጎላ ያለው ድምፅህ ተሰውሮብኛል\nበቅድስቱ በኩል በምትቆምበት በቅዳሴ ጊዜ\nአይኖቼ ስላጡህ ፈልገው ፈልገው ይዞኛል ትካዜ (2)\n\nአዝ፦\nልጄ ምን በደልኩህ ምን አጎደልኩብህ\nትተህኝ የሄድከው እንደዛ ስወድህ\nዘወትር ፊትህን ሳየው ደስ እያለኝ\nደስታዬን በሀዘን ምነው ለወጥክብኝ (2)\n', 'am', 89, 0),\n(1, 'ስራህ ብዙ', 'ስራህ ብዙ\nስራህ ብዙ መድኃኔዓለም (2)\nቸርነትህ ፍቅርህ ብዙ\nየኔ ጌታ ስራህ ብዙ\n\nአእዋፉ አናብርቱ ተሰብስበው\nበማለዳ ከእንቅልፋቸው ተቀሰቅስው\nይጮሃሉ ወደ ሰማይ ያዜማሉ\nስራህ ብዙ የኛ ጌታ ተመስገን ሊሉ\n\nአዝ፦\nየፍጥረታት ምስጋናቸው ወደ ሰማይ እየወጣ\nበረከትን ፍቅርን ስቦ እያመጣ\nስንባረክ በቸርነት ስንጎበኝ\nስራህ ብዙ መድኃኔዓለም እላለሁኝ\n\nአዝ፦\nምስጋና አለህ መድኃኔዓለም ከደመነፍስ\nከግዑዛን ፍጥረታትም ምስጋና አለህ\nቅዱስ ቅዱስ ቅዱስ አምላክ ልዩ ሲሉ\n', 'am', 90, 0),\n(1, 'አቤቱ ደግ ሰው', 'አቤቱ ደግ ሰው\nአቤቱ ደግ ሰው አልቋልና (2)\nከምድርም ፍቅር ጠፍቷልና (2)\nእንደ ቸርነትህ አድነን (2)\nበደላችንን አትቁጠር (2)\n\nአዝ፦\nየረድኤት አምላክ ፍቅር ስጠን (2)\nእንደ አሕዛቡ አታድርገን (2)\nክርስቲያን ነንና እንዋደድ (2)\nእባክህ አንውጣ ካንተ መንገድ (2)\n\nአዝ፦\nአቤቱ ንጹህ ልብ ፍጠርልን (2)\nሰውን የሚያስወድድ ካለ እንከን (2)\nእንደበታችንም እንዲናገር (2)\nስለ ሰላም ቋንቋ ስለ ፍቅር (2)\n\nአዝ፦\nበእግዚአብሔር ፍቃድ የሚመራ (2)\nከክፋት ደግነት የሚስራ (2)\nአንደበቱ ሁሉ የታረመ (2)\nለቃለ ወንጌሉ የደከመ (2)\n\nአዝ፦\nምግባርና እውነት የተሰጠው (2)\nእባክህን ስጠን ሁነኛ ሰው (2)\nአንተን የሚመስል በሕይወቱ (2)\nፍቅርና ትህትና የግል ሀብቱ (2)\n\nአዝ፦\nየማስመሰል ፍቅር እየበዛ (2)\nሰው እረክሷልና እንደዋዛ (2)\nፍጹም መዋደድን ስጠንና (2)\nአዲስ ሰው እንሁን እንደገና (2)\n\nአዝ፦\nደገኛ ሰው ማግኘት አስቸግሯል (2)\nእስከመጨረሻው ማን ይጸናል (2)\nምግባሩ ትክክል እውነተኛ (2)\nልቡ የሚጸየፍ ከዳተኛ (2)\n', 'am', 91, 0),\n(1, 'ለወዳጅህ ያኔ', ' ለወዳጅህ ያኔ\nለወዳጅህ ያኔ የተናገርከው ቃል\nበማዕከለ ምድር ስቃይ ስትቀበል\nእነኋት እናትህ ብለሕ የሸለምከው\nዮሐንስ መስቀሉን በመከተሉ ነው\n\nወደ ቤቱ ይዟት በዚያን ሰዐት ሄደ\nበጌታው መከራ ልቡ የነደደ\nከእናቱ ጓዳ አንጥፎ ጎዝጉዞ\nአገልግሏት ኖሯል በአምላኩ ታዞ\n\nጌታ የሚወደው የተባለለት ሰው\nማርያምን ሽልማት ጌታችን ከሰጠው\nይኄ ልጅሽ ነው ብሎ ዛሬ ሠጣት\nጌታ ቢፈቅድ ነው በእውነት ያለ ሐሰት\n\nወደ ቤትህ ትግባ በረድኤት በዓለም\nነፍስህ እድታገኝ ፀጥታና ሰላም\nከረድኤት ቤትህ ተራቁቶ እዳይገኝ\nድንግል ጓዳህ ትግባ ህይወትህን ትጎብኝ\n\nዮሐንስ መስቀሉን ስለተከተለ\nሳይለይ ከጌታው በሀዘን እንደዋለ\nልቡ ከኢየሱስ ጋር ቢወገር ቢሰቀል\nበፅናቱ ብዛት ማርያምን እናት ተሸልሟል\n\nምን ተነጋገርካት ዮሐንስ ፃድቁ\nምስጢራችሁ ለሰው መራቁ መርቀቁ\nበምን ቃል አፅናንታህ ተረጋጋህ አንተ\nነፍስህ በጌታ ፍቅር እንደዛ እየዋተተ\n', 'am', 92, 0),\n(1, 'ስምህ ለዘላለም ምስጉን ስለሆነ', ' ስምህ ለዘላለም ምስጉን ስለሆነ\nስምህ ለዘላለም ምስጉን ስለሆነ\nፍጥረት በአኮቴት ስቡህ ብሎ ዳነ\n\nስምህ ለዘላለም ምስጉን ነው ስቡህ\nመኸረን ለሰው ልጅ ምግብን የሰጠህ\nየተራበችው ነፍስ ከምድር በረከት\nበመገብካት ጊዜ ታመሰግናለች (2)\n\nምስጉን ነህ ምስጉን ነህ ስቡህ በሰማያት (2)\nየምትመሰገን በፍጥረት አንደበት (2)\n\nአዝ፦\nእንዳንተ ያለ ማን ነው ወቅት የሚያፈራርቅ\nምድርን በበረከት ሰማዩንም በጽድቅ\nተራሮች በአበባ ወንዞች የሚፈሱት\nስለጠገቡ ነው ከስጦታህ ብዛት (2)\n\nአዝ፦\nየሚያበራው ገጹ ፊቱ የሚያወዛው\nካንተ በሚቀዳው ከቸርነትህ ነው\nየምድር ልምላሜ የፍጥረታት ደስታ\nሲዘመር ይውላል ለለጋሹ ጌታ (2)\n', 'am', 93, 0),\n(1, 'ዛሬስ ተይዣለሁ', 'ዛሬስ ተይዣለሁ\nዛሬስ ተይዣያለው በፍቅርህ ስጦታ\nውለታህ ማርኮኛል የሰራዊት ጌታ\nከአመድ ያነሳኸኝ ከትቢያ ተጥዬ\nውለታህ ከበደኝ ማረከኝ ጌታዬ (2)\n\nያልሰጠኸኝ ነገር በዚህ ምድር የለም\nፍቅርህ ወሰን የለዉ ድንቅ ነዉ ዘላለም\nእኔነቴን ሳስብ ምንድነኝ እላለሁ\nፍቅርህን ሳስተዉል ሁልጊዜ አለቅሳለሁ (2)\n\nአዝ፦\nለብቻዬ ሆኜ አምላኬን ሣስበው\nከህሊና በላይ ውለታህ ብዙ ነው\nየተጣለውን ሰው ማንሳት ያውቅበታል\nምስኪንን ሲያጽናና ከሁሉም ይበልጣል (2)\n\nአዝ፦\nሰው ነህ ተብያለሁ አንተ ሰው ስላልከኝ\nማን ያስታውሰኛል አንተ ባታከብረኝ\nአትጣለኝ አንተ ሁሉም ያከብረኛል\nኃጢያቴን ባትቆጥር ለእኔ ይበቃኛል (2)\n', 'am', 94, 0),\n(1, 'ማኔ ቴቄል ፋሬስ', ' ማኔ ቴቄል ፋሬስ\nማኔ ቴቄል ፋሬስ (4)\nየሰዎች መሠረት እዩት ሲገረሰስ\nማኔ ቴቄል ፋሬስ (2)\n\nበእውነት መስፈሪያ ተመዝነህ ነበር\nየልብ ትዕቢት ግን አዘቀጥክ እንደ አፈር\nቆረጥከው ዘመንክን ቅጥፈቱ አጀበህ\nበለጋነት እድሜ ወደ ሞት ተጠራህ\n\nአዝ፦\nዳንኤል የታለ አሁን የሚገስጽ\nበመንፈሱ መብራት ወገንን የሚያንፅ\nአብነት የታለ በጸሎት የተጋ\nየሕሊናን ወጀብ በፍቅር የሚያረጋ\n\nአዝ፦\nአምላክ ያላነፀው የእምቧይ ካብ ተንዶ\nየትናንቱ ትልቅ ማምሻውን ተዋርዶ\nእንደ አበባ ፈክቶ ሲረግፍ እያየነው\nዛሬም ልቦናችን ለትዕቢት ጽኑ ነው\n\nአዝ፦\nቀይ ባሕር ሲሰጥም ያለፈው ፈርኦን\nዛሬም የአምላክን ሕዝብ አንለቅም ብለን\nእንደ ጠጣር አለት ጠንክሮ ልባችን\nደግሞ ተፈጥረናል ፈርኦን ነን ብለን\n', 'am', 95, 0),\n(1, 'ኢየሱስም አለ', 'ኢየሱስም አለ\nኢየሱስም አለ ሐዋርያትን ጠርቶ\nሥርዓት ሊያስተምራቸው ከሁሉ ለይቶ\nይህን የአዲስ ኪዳን የፍቅር ስጦታ\nታላቅ ሰንሰለት ነው እጅግ የበረታ\nሥጋዬንም ብሉ ደሜንም ጠጡት\nስለሚሰጣችሁ የእውነት ሕይወት\n\nሂዱና አዘጋጁ የፋሲካን መአድ\nይገባዋልና ንጹሕ በግ ሊታረድ\nደቀመዛሙርቱ ጴጥሮስና ዮሐንስ\nበፍጥነት ተጓዙ እከተማው ድረስ\nአዩና ማድጋ የተሸከመ ሰው\nከተማ ሲደርሱ ሄደው ተከትለው\nእጅግ ተደሰተ የቤቱ ባለቤት\nጌታው ባዳራሹ ስለተገኘለት\n\nአዝ፦\nሰዓቱ ሲደርስ የተወሰነለት\nከመአድ ሊቀመጥ ተገኘ ከዚያ ቤት\nየቤቱ ባለቤት እጅግ የታደለው\nስምዖን ነበረ ጌታን የጋበዘው\nእጅግ እመኝ ነበር ከመከራ በፊት\nከመአድ ልቀመጥ ከእናንተ ጋር በእውነት\nየእግዚአብሔር መንግሥት እስክትመጣ ድረስ\nከወይኑ አልጠጣም ከማዕዱም አልቀምስ\n\nአዝ፦\nህብስቱንም ቆርሶ ባርኮ አደላቸው\nስለእናንተ የሚሰጥ ሥጋዬ ይሄ ነው\nወይኑንም ባረከ አንስቶ ሰጣቸው\nስለናንተ የሚፈስ ደሜ ይህ ነው አላቸው\nይህን የሐዲስ ኪዳን የፍቅር ስጦታ\nታላቅ ሰንሰለት ነው እጅግ የበረታ\nስጋዬንም ብሉ ደሜንም ጠጡት\nስለሚሰጣችሁ የእውነት ሕይወት\nመዝሙርም ዘመሩ እጅግ የተዋበ\nጌታም እግር ሊያጥብ ውኃን አቀረበ\nጴጥሮስ ግን ፈጽሞ አታጥበኝም አለ\nትሁት ነበርና እየተቻኮለ\n\nአዝ፦\nእግርህን ካላጠብኩ ዛሬ በዚህ ምሽት\nእጣክፍል የለህም ከኔ ጋራ በእውነት\nእንዲህ ባለው ጊዜ ጴጥሮስ ደነገጠ\nመላ ሰውነቱን ለመታጠብ ሰጠ\nእኔ ጌታ ስሆን አምላክ የምከብር\nእግራችሁን ሳጥብ ስኖር ከናንተ ጋር\nይህንን ምሳሌ ተከተሉ በፍቅር\nየኔ ስጦታ ነው በትሕትና መኖር\n', 'am', 96, 0),\n(1, 'በሰው ዘንድ ቢሟጠጥ', ' በሰው ዘንድ ቢሟጠጥ\nበሰው ዘንድ ቢሟጠጥ ተስፋና ደስታ\nእኛስ ፈጣሪ አለን ሁሉን የሚረታ\nተስፋ እንደሌላቸው አንሆንም ከቶ\nክርስቶስ አለልን የሚያሳይ አብርቶ (2)\n\nያለቀሱ ሁሉ ይስቃሉ አይቀርም\nይለዋውጠዋል ጌታ መድኃኔዓለም\nማንም ያላሰበው ያልጠበቀውን ድል\nለኛ ለምስኪኖች ጌታ ይሰጠናል\nማንም ያልጠበቀውን ያልገመተውን ድል\nለኛ ለምስኪኖች ጌታ ይሰጠናል\n\nአዝ፦\nሰዎች ቢጠበቡ ገንዘብ ለመሰብሰብ\nይጠላለፋሉ ባልጠበቁት መረብ\nእግዚአብሔርን ይዘው በቅን ካልተጓዙ\nክፋትና ተንኮል ብዙ ነው መዘዙ\n\nአዝ፦\nድሆች አስለቅሶ ግፍ የሚሰበስብ\nምን ይመልስ ይሆን ጌታ ፊት ሲቀርብ\nለዚህች አጭር ዘመን የሚስገበገቡ\nአይረኩም አይጠግቡም ድሆች እያስራቡ\n\nአዝ፦\nየእህል ሽታ ጠፍቶ መሶቡም ቢራቆት\nተስፋችን ሙሉ ነው እኛስ በጌታ ፊት\nይህን ክፉ ዘመን ያሻግራል ጌታ\nከሠራን በኋላ በጸሎት እንበርታ\n', 'am', 97, 0),\n(1, 'እግዚአብሔር ሆይ እወድሃለው', 'እግዚአብሔር ሆይ እወድሃለው\nእግዚአብሄር ሆይ እወድሃለው\nስለ ስምህ እቃጠላለው\nፍቅርህ እኔን ይመስጠኛል\nእንደ እግዚአብሄር ከየት ይገኛል (2)\n\nአለም ሁሉ በጠላኝ ጊዜ\nስንገላታ ይዞኝ ትካዜ\nአንተ ከኔ አልተለየህም\nእግዚአብሔር ሆይ ወደር የለህም (2)\n\nአዝ፦\nሳዖል እኔን ሲያሳድደኝ\nጎልያድም ሲዝትብኝ\nግርማ ሆነህ ከፊቴ የቆምክ\nእግዚአብሔር ሆይ ስምህ ይባረክ (2)\n\nአዝ፦\nሞቷዋል ብለው ቀብረውኝ ሰዎች\nምስኪን ሁኜ ሳይኖረኝ አንዳች\nከመቃብር ቆፍሮ አወጣኝ\nአይዞህ ብሎ አምላክ አፅናናኝ (2)\n\nአዝ፦\nሐሳብህን በእግዚአብሔር ላይ ጣል\nለዘለዓለም ያበራልሃል\nታማኝ አባትህ እርሱ ነውና\nሰላም በረከት የእርሱ ነውና\n', 'am', 98, 0),\n(1, 'በየገዳማቱ', 'በየገዳማቱ\nበየገዳማቱ በየበረሃው ውስጥ\nስለተሰደዱት ፍቅርህን በመምረጥ\nየዓለም ውዳቂ ምናምንቴ ሆነው\nስለ ፍቅርህ ሲሉ ክብራቸውን ትተው\nእግዚአብሔር ሆይ ማረን (2)\n\nአዝ፦\nየዓለም ውዳቂ ጉድፍ በተባሉት\nበምድር እየኖሩ በጽድቅ ህይወት ባሉት\nዓለም አና አምሮቷን ትተው በመነኑት\nኢየሱስ ሆይ ማረን እግዚአብሔር ሆይ ማረን (2)\n\nአዝ፦\nህያዋን በሆኑት እስከ ዘለዓለም\nከኢየሱስ ጋራ ሞተው በመስቀል ዓለም\nዓለም የናቃቸው እነርሱም በናቁት\nአምላክ እራራልን አትጨክን በእውነት (2)\n', 'am', 99, 0),\n(1, 'ተወለደ ጌታ', ' ተወለደ ጌታ\nተወለደ ጌታ ተወለደ\nተወለደ አምላክ ተወለደ (2)\n\nአንዲት ብላቴና የአስራ አምስት ዓመት ልጅ\nጌታን ወለደችው በመላእክት አዋጅ\nበህቱም ድንግልና ተወለደ ጌታ\nዓለምን የሚያድን የሰዎች አለኝታ\n\nአዝ፦\nይህ ዓለም በቃሉ ከተፈጠረበት\nይበልጣል ልደቱ አምላክ ሰው የሆነበት\nእንደምን ይገርማል ይሄ ተዋሕዶ\nአየነው አምላክን እንደሰው ተወልዶ\n\nአዝ፦\nፍጹም ድንግልና ክብር የተመላች\nእንደምን አምላክን በማህፀን ያዘች\nዓለምን በቃሉ የፈጠረ ጌታ\nወለደችው ጌጠ የሔዋን አለኝታ\n\nአዝ፦\nአንቺ ብላቴና እናታችን ማርያም\nበምድር ተፈልጎ እንዳንቺ አልተገኘም\nበሀሳብ በግብር ንፁህ ስለሆነች\nየአምላክ ማደሪያ ድንግል ተመረጠች\n\nአዝ፦\nፍጹም ድንግልና ክብር የተመላች\nእንደምን አምላክን በማህፀን ያዘች\nዓለምን በቃሉ የፈጠረ ጌታ\nወለደቸው ድንግል የሔዋን አለኝታ\n', 'am', 100, 0),\n(1, 'ኃይልህ ሲገለጥ', 'ኃይልህ ሲገለጥ\nኃይልህ ሲገለጥ ከሰማይ (2)\nአቤት ማን ይቆም ይሆን ከፊትህ\nማን ይቆም ይሆን (2) ከፊትህ\nማን ይቆም ይሆን\n\nአቤት ቀንደ መለከት ሲነፋ\nአዋጅ ሲታወጅ በይፋ\nጻድቃን ሲጠሩ ለተድላ\nምን ይሆን የእኛ ተስፋ\n\nአዝ፦\nአቤት መላእክት ሰማዩን ሲያርሱት\nቀድመው ሲሰሙ መባርቅት\nያልታየና ያልተሰማ\nድምጽ ሲሰማ ከራማ\n\nአዝ፦\nአቤት ሰባቱ ነፋስ ተከፍተው\nምድርን ሲያውኳት ተቀዝፈው\nሲታዘዝ የባሕር ሞገድ\nምድሪቷን ሊከድናት ለፍርድ\n\nአዝ፦\nአቤት ሲጠሩ ጻድቃን ቅዱሳን\nመልካም የሰሩ ቡሩካን\nበምድር የሰሩ ትሩፋት\nሲያቀርቡ ለአምላክ ስብሐት\n\nአዝ፦\nአቤት ኃጥአን ግን ለፍርድ ሲጠሩ\nበጨለማ ዓለም ሊቀሩ\nየማይጠቅም ዋይታ ሆኖ\nመዋረድ ይሆናል አዝኖ\n\nአዝ፦\nአቤት ሲጠሩ ጻድቃን ቅዱሳን\nመልካም የሰሩ ቡሩካን\nበምድር የሰሩ ትሩፋት\nሲያሰሙ ለአምላክ ስብሐት\n', 'am', 101, 0),\n(1, 'ስለ ቸርነትህ', ' ስለ ቸርነትህ\nስለ ቸርነትህ ጌታ ተመስገን\nስለ ፍጹም ፍቅርህ አምላክ ተመስገን\n\nአዝ፦\nማነው የገመተ ከዛሬ መድረስን\nልብሱ ሳይነካ በእሳቱ ወላፈን\nባሕሩን አሻግሮ ማዕበል አቁሞ\nእርሱ ያውቅልናል ለመጪው ቀን ደግሞ\n\nአዝ፦\nሃሌ ሃሌ ሉያ መስዋዕት እናቅርብ\nጌታ ይፈልጋል የተሰበረ ልብ\nክርስቶስ ከሌለ ፍቅር ላይኖረው\nሰላም ሰላም يላል ፍጥረታዊው ሰው\nሰላም ሰላም ይላል የዘመኑ ሰው\n\nአዝ፦\nየኢየሱስ ነገር ለሚጠፉት ሁሉ\nየመስቀሉ ነገር ለሚጠፉት ሁሉ\nሞኝነት መስሏቸው ክህደት ተሞሉ\nየስንፍና አመል እያናወዛቸው\nመጾም መጸለዩ ይጎዳናል ብለው\nአምላክን ቢክዱ ፍቅርን ነፈጋቸው\n', 'am', 102, 0),\n(1, 'እግዚአብሔርን አየሁ', 'እግዚአብሔርን አየሁ\nእግዚአብሔርን አየሁ ወዮልኝ ፈራሁኝ\nከረጅም ተራራ ከፍ ካለው ዙፋን\nየልብሱ ዘርፍ ሞልቶ መቅደሱን ሸፍኖ\nእግዚአብሔርን አየሁ (ከሰማያት ሆኖ) (2)\n\nባሕር ሲመላለስ ብልጭልጭታ ሲሆን\nእደነቅ ነበረ በአምላክ ስነ-ጥበብ\nእሳት የለበሱ ሱራፌልን ባይም\nከእግዚአብሔር ግርማ (አይወዳደርም) (2)\n\nአዝ፦\nየንጋቱ ጮራ የአጥቢያ ኮከብም\nየእግዚአብሔርን ብርሃን ቅንጣት አያህሉም\nየሞት ደጆች ሲያዩት ይከፋፈታሉ\nየሲዖል አለቆች (ፈጥነው ይወድቃሉ) (2)\n\nአዝ፦\nቤቱንም ጢስ ሞላው ምድር ተናወጠ\nየእግዚአብሔር ክብር ሞገስ ተገለጠ\nጠፍቻለው አልኩኝ ክብሩን በማየቴ\nከንፈሬ ዕረክሶ (ስብ ነው አንደበቴ) (2)\n\nአዝ፦\nፍህሙን አመጣና መልዐኩ በጉጠት\nለምጻሙን እርኩሱን አፌን ዳሰሰበት\nከንፈርህን ነካው ይህ እሳት ኢሳያስ\nኃጥያትህ ተሽሯል (በድል ተመላለስ) (2)\n\nአዝ፦\nመልአኩ በጉጠት የያዘው በፍርሃት\nሥጋና ደሙ ነው ምሳሌው በእውነት\nነጻ እንድትወጣ በደልህ እንዲሰረዝ\nቀርበን እንቀበል ለአምላክ (እንታዘዝ) (2)\n\nአዝ፦\nእሳታዊው መልአክ እሳት እንዳይፈጀው\nእጅግ ተጠንቅቆ በጉጠት የያዘው\nእንደምን ይገርማል የሠው ልጅ ሲጎርሰው\nካህን የዳሰሰው (እሳቱን እኮ ነው) (2)\n', 'am', 103, 0),\n(1, 'ነገር ግን ያመንነው', 'ነገር ግን ያመንነው\nነገር ግን ያመንነው ያድነናል ብለው\nጸንተው ተሰለፉ ለኃይማኖታቸው\n\nሶስቱ ወጣቶችን ከእሳት ያወጣቸው\nኃይማኖት ነው እኝጂ ሌላ ምን ሊሆን ነው\nናቡከደነፆር በዱራ ሜዳ ላይ\nጣዖቱን አቁሟል እንድንሰግድ እንድናይ\n\nአዝ፦\nእምቢልታ ሲነፋ መለከት ሲሰማ\nበአንድነት እንዲሰግድ ሰው ሁሉ ተስማማ\nነገር ግን ትእዛዙን የማይቀበው\nከሚነደው እሳት ይጨመራል ወዲያው\n\nአዝ፦\nሰው ሁሉ ይንበርከክ ለወርቁ ለብሩ\nአምላክ ስለሆነ በአንድነት ያክብሩ\nለግዙፉ ሐውልት ያልሰገደ ቢኖር\nምህረት ሳያገኝ ወደ እሳት ይወርወር\n\nአዝ፦\nሲድራቅ ሚሳቅ እና አብደናጎም ሆነው\nሳይሰግዱ በድፍረት ቆመው አየናቸው\nንጉሡ ቢቆጣም አልተደናገጡም\nአሉ እንጂ በድፍረት ለጣዖት አንሰግድም\n\nአዝ፦\nበዚህ አንመስልህም አስፈላጊ አይደለም\nአምላካችን አለ ከእቶን የሚያድነው\nከእቶን ያድነናል ፍዱም እምነት አለን\nባያድነን እንኳን የእሱ ፈቃድ ይሁን\n\nአዝ፦\nናቡከደነፆር እጅግ ተናደደ\nእቶኑም ሰባት እጅ ከፍ ብሎ ነደደ\nከእሳት ቢከቷቸው ገብርኤል ተላከ\nአህዛብን በድንቅ እግዚአብሔር ማረከ\n\nአዝ፦\nበእሳት መካከል ሲመላለሱ አይቶ\nንጉሡ አደነቀ ከሥፍራው ተነስቶ\nየአማልክትንም ልጅ አየዋለሁ አለ\nእግዚአብሔር ይመስገን በክብር\n', 'am', 104, 0),\n(1, 'ጸንተን እንጠብቀው', 'ጸንተን እንጠብቀው\nከመላእክት ጋራ ሲገለጥ በሰማይ\nጸንተን እንጠብቀው ክብሩን ሁሉ እንድናይ\nበግርማ ሲመጣ በአስደንጋጭ ሁኔታ\nወዮልሽ ነፍሴ ሆይ ወየው የዛን ለታ\n\nኧኸ ምስጋና ይድረስ ሁልጊዜ ጠዋት ማታ\nሃሌ ሃሌ ሉያ የሠራዊት ጌታ (2)\n\nአዝ፦\nሰማይና ምድር ከፊቱ ሲሸሹ\nመግቢያ አጥቶ ይጮሃል ትልቁ ትንሹ\nጻድቃን ሲደሰቱ የኃጥአን ፋንታ\nሆኖ ጠበቃቸው ለቅሶና ዋይታ\n\nአዝ፦\nስለማይታወቅ አምላክ አመጣጥህ\nበመንፈስህ አፅናን ፀንተን እንጠብቅህ\nሰይጣን እንዳይገዛን በመንግሥትህ ቦታ\nእግዚኦ ከልለን ከለቅሶ ከዋይታ\n', 'am', 105, 0),\n(1, 'ቅያሜው ይቅርና', 'ቅያሜው ይቅርና\nቅያሜው ይቅርና አምላክ ሆይ ይታረቀን\nአንተ ስለራከን ሞት ነው የከበበን (2)\n\nእስከመቼ ድረስ ህዝብህ ተጎሳቁሎ\nበረከሰ መንፈስ ለእርኩሰት ተጥሎ\nምድር እያለቀሰች ደም እየሸተታት\nእባክህ አምላኬ ኢትዮጵያ ታረቃት\nእባክህ አምላኬ ሀገሬን ታረቃት\n\nአዝ፦\nየዘመኑ ጣኦት ገንዘብ እያሳተን\nይህ ደካማ ስጋ አምላክን አስተወን\nግብዝነት ሞልቶት ፈራሹ አካል\nበነፍስ በሽታ ህዝባችን ታሟል (2)\n\nአዝ፦\nክንፋችን ተመቶ መብረር አቅቶናል\nበመንፈስ በሽታ ህዝባችን ታውሯል\nእራዕይ የሌለው ተራ ሰው ስለሆንን\nእባክህ ጌታችን በፍጥነት ታረቀን (2)\n\nአዝ፦\nፀጋህ የተለየን ባዶነት የሞላን\nፍቅር የተነፈግን ሰላም የጎደለን\nሆነን ስለቀረን እግዚአብሔር ታረቀን\nፅድቅህን አድለን ፅድቅን ለተመኘን\n', 'am', 106, 0),\n(1, 'ከቶ ምን ይረባል', ' ከቶ ምን ይረባል\nከቶ ምን ይረባል ጭካኔን ማብዛት\nፈጥኖ ለሚጠፋው ለዚህ ዓለም ቤት\nበቋንቋ በጎሳ መከፋፈል ሞት ነው\nየእንጨት ዘር አይቀርም እንኳን ሰው እና ሰው (2)\n\nበጎሳ ሰልጥነው ድንበር የሚያበጁ\nበታሪክ አይተናል ለማንም አልበጁ\nያደለው ወገኔ ገነትን በምድር\nሁሉን አጨለምከው ተከፋፍለህ በዘር\n\nአዝ፦\nወፎች ይበራሉ አህጉር አቋርጠው\nክረምት እና በጋ ጊዜውን ጠብቀው\nየሰው ልጅ ብቻ ነው ድንበር የከለለው\nከእንስሳት አንሶ የሚተላለቀው\n\nአዝ፦\nእምቢ በል ወገኔ እንደ አባቶቻችን\nአትስማ በፍፁም ዘረኛው ሰይጣንን\nበሰውነት ሚዛን ከብረህ እንድትገኝ\nበጎሳ በዘመድ በጥቅም አትዳኝ\n\nአዝ፦\nሁሉም ወገንህ ነው የአዳም ልጅ ነው እና\nስልጡንሁን በፍቅር በቀናው ጎዳና\nየክፉዎች ስብከት ሞት ነው መጨረሻው\nለጊዜው ቢመስልህ ሐዘን ነው ፍፃሜው\n\nአዝ፦\nሃይማኖት ተንቃ ተንገዋላ ከአገር\nሊጠፋ ተቃርቧል ክቡሩ የሰው ዘር\nማፍለስ እና ማፍረስ ህዝብን ማጎሳቆል\nግፍ እና ጭካኔ የዘመኑ ብሂል\n', 'am', 107, 0),\n(1, 'አኮቴት ላንተ ይገባል', 'አኮቴት ላንተ ይገባል\nአኮቴት ላንተ ይገባል\nስብሃት ለአንተ ይገባል\nአምልኮ ላንተ ይገባል\nስግደትም ላንተ ይገባል\n\nቅድመ ዓለም የነበር በታላቅ ስልጣኑ\nለኩነተ ስጋ የመጣው በፍቅሩ\nደግሞም ይህን ዓለም የሚሳልፍ ጌታ\nኢየሱስ ክርስቶስ ሃያል የእኛ አለኝታ\n\nበስጋው ሲታመም ሲሞት በመስቀል\nበአብ ቀኝ የነበር በሰማይ ሳይጎል\nየአዳምን ባህሪይ ተዋህዶ ሲያከብር\nበዚህ ይገለጣል የጌታችን ፍቅር\n\nከቅድስት ስላሴ የማይለኝ ምክሩ\nጉድለት የለበትም ትክክል ነው ክብሩ\nየአብ ቃል ጥበቡ ክንዱ ስለሆነ\nዓለምን ፈጠረ አዳምን አድነ\n\nሊቃነ መላዕክት ሃይላቸው ነውና\nያመሰግኑታል በታላቅ ትህትና\nዘውዳቸው ክብራቸው ስለሆነ እርሱ\nይኖራሉ ወልድን ስሙን ሲያወድሱ\n', 'am', 108, 0),\n(1, 'በዘር አንድ የሆነኝ', 'በዘር አንድ የሆነኝ\nበዘር አንድ የሆነኝ ሌዋዊው ትቶኛል፤\nባዕዱ ሳምራዊ ከሞት አድኖኛል፤\nበቁስሌ ላይ ዘይት የሚያፈስ ፍቅረኛ፤\nየሰላም ሰው ስጠኝ ሁነኛ ጓደኛ (2)\n\nከማይጠፋው ትውልድ ስለ ተወለድን\nአይቀርም እመኑ በምድር ዘራችን\nከእግዚአብሔር ተወልደን ልጆች ተብለናል\nባሮች አይደለንም ነፃነት ወጥተናል (2)\n\nአዝ፦\nአንተን የሚመስል የዋህ ሰው\nወንጌልክን ነገረኝ ህይወቴን ለወጠው\nአለም የሰጠችኝ ሞት ነበረ ድሮ\nክርስቲያን አዳነኝ ወንጌልክን አስተምሮ (2)\n\nአዝ፦\nበሥጋ እና በደም የማልዛመደው\nበክርስቶስ ጥምቀት ዘሩ ከእኔ ጋር ነው\nጓደኛዬ እርሱ ነው ህይወት የሚሰጠኝ\nበቃሉ በፍቅሩ ተመስጫለሁኝ\nተለውጫለሁኝ\n\nአዝ፦\nልቡ ቅን የሆነ ጓደኛ መርጬ\nሰላሜ ልዩ ነው ዛሬስ ተለውጬ\nክርስቲያን መሆኑ በዚህ ያስታውቃል\nፍቅሩ ይለውጣል ስራው ይማርካል (2)\n\nአዝ፦\nከአለም ጉድጓድ ውስጥ ተጥዬ ወድቄ\nይሄው ሰላም ሆንኩኝ ከአምላኬ ታርቄ\nእውነት እና ፍቅር አስተማረኝና\nአዲስ አደረገኝ እኔን ክርስትና (2)\n', 'am', 109, 0),\n(1, 'ይበላሀላ', 'ይበላሀላ\nይበላሀላ (6) አንተንም አፈር ይበላሀላ\nእንደ ሞኝ ሰው እንደ ተላላ\n\nሞኜ ተላሌ (4) ይደላ መስሎህ ነገ እንደ ዛሬ\nንስሀን ትተህ ተበላህ አውሬ\nሞኜ ተላሌ (2)\n\nአዝ፦\nበላው አፈር (4) ያንን ወታደር ያንን ምሁር\nበላው አፈር በላው አፈር\n\nንስሀ ግባ የእናቴ ልጅ (2)\nየክተት ጥሪ ሳይታወጅ\nስራና ሰሪው ሳይቀናጅ\nንስሀ ግባ የእናቴ ልጅ\n\nአዝ፦\nንስሀን ትተህ የት ትሄዳለህ\nሲመለከቱህ ታሳዝናለህ\nንስሀን ትተህ የት ትሄዳለህ\n\nበላው አፈር (4) ያንን ገበሬ ያን ወታደር\nበላው አፈር (2)\n\nተሰብሰብ ዛሬ ወደ አምላክህ (2)\nእንድታመልጠው ሰይጣንን ፈጥነህ\nተሰብሰብ ዛሬ ወደ አምላክህ\n\nየሰላም አምላክ ሲጠራህ ስማ (2)\nበጠላት ነፍስህ እንዳትቀማ\nየሰላም አምላክ ሲጠራህ ስማ\n\nጾምና ፀሎት ምፅዋት ሆነህ (2)\nመድኃኒት ሆኖህ አለም ያዳነህ\nጾምና ፀሎት ምፅዋት ሆነህ\n', 'am', 110, 0),\n(1, 'በሕይወቴ በዘመኔ', 'በሕይወቴ በዘመኔ\nሕይወቴ ቢመራ ጌታ በቃልህ\nጣፋጭ ይሆን ነበር ሲያድሰኝ ፍቅርህ\nየአንተ ጸጋ ጌታ ስለበዛልኝ\nጨለማው ተገፎ ብርሃንህ መራኝ\n\nበሕይወቴ በዘመኔ\nደስ የሚለኝ ለኔ\nበወንጌል ማመኔ (2)\n\nወዴት እሄዳለሁ የእጅህ ጥበብ ሆኜ\nፍቅርህ እያደሰኝ ሞተህልኝ ድኜ\nምን አይነት መውደድ ነው ለኔ አንተ ያለህ\nምን ይከፈለዋል ለፍጹሙ ፍቅርህ\n\nአዝ፦\nምን አይነት መውደድ ነው አንተ ለኔ ያለህ\nምን ይከፈለዋል ለፍጹሙ ፍቅርህ\nደጅህ ላይ ተይዤ ደጅህ ላይ ልሙት\nቃልህን ልጠብቅ በፍጹም ፍርሃት\n\nበሕይወቴ በዘመኔ\nደስ የሚለኝ ለኔ\nበወንጌል ማመኔ (2)\n', 'am', 111, 0),\n(1, 'ኪርያላይሶን', 'ኪርያላይሶን\nኪርያላይሶን ኪርያላይሶን (3)\n\nኪርያላይሶን ኪርያላይሶን አማኑኤል ጌታ\nኪርያላይሶን ኪርያላይሶን በጥፊ ተመታ\nኪርያላይሶን ኪርያላይሶን ዓለምን ሊታደግ\nኪርያላይሶን ኪርያላይሶን ተነዳ እንደበግ\nኪርያላይሶን ኪርያላይሶን አዳምን ሊፈውስ\nኪርያላይሶን ኪርያላይሶን ቆመ ከጲላጦስ\n\nኪርያላይሶን ኪርያላይሶን ኪርያላይሶን\n\nኪርያላይሶን ኪርያላይሶን ኪርያላይሶን\nኪርያላይሶን ኪርያላይሶን እጁን ቸነከሩት\nኪርያላይሶን ኪርያላይሶን አጥንቱን ቆጠሩት\nኪርያላይሶን ኪርያላይሶን የሾህ አክሊል ደፍቶ\nኪርያላይሶን ኪርያላይሶን ገዳዩን እረቶ\nኪርያላይሶን ኪርያላይሶን የሁላችን በደል\nኪርያላይሶን ኪርያላይሶን ተሻረ በሱ ቁስል\n\nኪርያላይሶን ኪርያላይሶን ኪርያላይሶን\n\nኪርያላይሶን ኪርያላይሶን ኪርያላይሶን\nኪርያላይሶን ኪርያላይሶን እጣ ተታጣሉ\nኪርያላይሶን ኪርያላይሶን ልብሱን ተካፈሉት\nኪርያላይሶን ኪርያላይሶን ለፍርድ ተወሰደ\nኪርያላይሶን ኪርያላይሶን እንደበግ ታረደ\nኪርያላይሶን ኪርያላይሶን ለበሶ ከለሜዳ\nኪርያላይሶን ኪርያላይሶን ተከፈለ ዕዳ\n\nኪርያላይሶን ኪርያላይሶን ኪርያላይሶን\n\nኪርያላይሶን ኪርያላይሶን ኪርያላይሶን\nኪርያላይሶን ኪርያላይሶን ሆምጣጤ አጠጡት\nኪርያላይሶን ኪርያላይሶን በገመድ ጎተቱት\nኪርያላይሶን ኪርያላይሶን በወንበዴው ፈንታ\nኪርያላይሶን ኪርያላይሶን ተሰቀለ ጌታ\nኪርያላይሶን ኪርያላይሶን ሁሉም ዘበቱበት\nኪርያላይሶን ኪርያላይሶን ለዘላለም ህይወት\n\nኪርያላይሶን ኪርያላይሶን ኪርያላይሶን\n', 'am', 112, 0),\n(1, 'በእኩለ ለሊት', 'በእኩለ ለሊት\nበእኩለ ለሊት (4)\nጌታችን ተነስቷል (3)\nበእርግጥ ከመቃብር\n\nማርያም መግደላዊት እንደተለመደው\nማለዳ ተነሣች ሽቶውን ልትቀባው\nነገር ግን ድንጋዩ ተከፋፍቶ ነበር\nጌታችንም የለም በርግጥ ከመቃብር\n\nአዝ፦\nብርሃን የለበሱ መላእክትም መጥተው\nሕያውን ከሙታን የምትሺው ለምን ነው\nአሥቀድሞ በግልጽ እንደተናገረው\nተነስቷል ከሙታን ግሩማን ኃያል ነው\n\nአዝ፦\nጌታን ባየች ጊዜ ስላላወቀችው\nየአትክልት ጠባቂ መስሏት ጠየቀችው\nማርያም ባላት ጊዜ ጌታዋን ለየችው\nረቡኒ ብላ በደስታ ጠራችው\n\nአዝ፦\nበአበው በትንቢት እንደተነገረው\nእግዚአብሔር እንደ ኃይል ተነስቷል ልክ ነው\nበመዝሙር መጸሐፍት ትንቢቱ ታውጇል\nየእግዚአብሔር ክንዱ በእርግጥ ተነስቷል\n', 'am', 114, 0),\n(1, 'እዩና ዕመኑ ሠዎች', 'እዩና ዕመኑ ሠዎች\nእዩና ዕመኑ ሠዎች\nድንጋዩ ተፈነቃቅሏል\nኢየሱስ በእኩለ ሌሊት\nበሐይሉ ሞትን ድል ነስቷል (2)\n\nዕልልታ ለእዚህ ይገባል\nግርግርታ ለእዚህ ይገባል\nየሞት ሐይል ተዋርዷል ዛሬ\nሲዖልም ተመሰቃቅሏል (2)\n\nመላዕክቱ ነጭ ለብሰው\nምስራቹን አበሠሩ\nተነስቷል ኢየሱስ ብለው\nለዓለም እንዲናገሩ (2)\n\nእዩና ዕመኑ ሰዎች\nድንጋዩ ተፈነቃቅሏል\nኢየሱስ በእኩለ ሌሊት\nበሐይሉ ሞትን ድል ነስቷል (2)\n\nዕልልታ ለእዚህ ይገባል\nግርግርታ ለእዚህ ይገባል\nየሞት ሐይል ተዋርዳል ዛሬ\nሲዖልም ተመሰቃቅሏል (4)\n', 'am', 115, 0),\n(1, 'አንድ ቀን አለ', 'አንድ ቀን አለ\nአንድ ቀን አለ የሚያስፈራ\nለጻድቃን የሚያበራ (2)\nጌታ በዚያ ቀን ይመጣል\nበክብርም ይገለጻል (2)\n\nአብረው ከእርሱ ጋር ይመጣሉ\nቅዱሳን መላዕክት ሁሉ (2)\nጌታ በዚያ ቀን ይመጣል\nበዙፋኑ ይቀመጣል (2)\n\nየምሕረት አዋጅ ይታወጃል\nነፍስ ሁሉ ይጨነቃል (2)\nኃጥአን ሁሉ ያለቅሳሉ\nበግራው ይቆማሉ (2)\n\nቅዱስ ቃሉን ሰምተው ያመኑ\nየጸኑ በኪዳኑ (2)\nአብረው በቀኙ ይቆማሉ\nከኃዘን ይሠወራሉ (2)\n\nመሓሪው ጌታ ፈጣሪያችን\nይድረስህ ልመናችን (2)\nበዚያ ግሩም ቀን እባክህ\nአቁመን በቀኝህ (2)\n', 'am', 116, 0),\n(1, 'እናምናለን በአብ', 'እናምናለን በአብ\nእናምናለን በአብ እናምናለን በወልድ እናምናለን በመንፈስቅዱስ\nፍጹም ጥርጣሬ ሳይኖር አንድ እግዚአብሔር ብለን\n\nበስም በአካል በግብር ሦስትነትን አምነን\nበመለኮት አንድ አምላክ ብለን እናምናለን\n\nአዝ፦\nየሥላሴን ቸርነት የሥላሴን ጥበብ\nሕሊናችን ይረዳ ልቦናችን ይራብ\nኧኸ እንደ አምላክነቱ እንመነው\nከዕውቀት ሁሉ የሚበልጥ ነው\nኧኸ እንደ አምላክነቱ እንመነው\nከእውነት ሁሉ የሚበልጥ ነው\n', 'am', 117, 0),\n(1, 'ብሥራተ ገብርኤል', 'ብሥራተ ገብርኤል\nበአምስት ሺህ ከአምስት መቶ ዘመን\nጌታ መጥቶ እስኪለብስ ድረስ ሥጋን\nነቢያትም ስእንኳ ከአህዛብ እነ በለዓም ሳይቀሩ የሥጋዌ ተገልጦላቸው ምሥጢሩ\nበብዙ አምሳል እየመሰሉ ሲነግሩ\nበሱባኤም ዘመኑን ሁሉ ሲቆጥሩ\nእንዲህ አርገው ደጅ ሲጠኑ ነበሩ\nበመጋቢት በሃያ ዘጠኝ ዕለት\nአስቀድሞ በጀመረበት ፍጥረት\nከዘመኑ ለዕለት እንኳ ሳይተርፍ\nከሰዓቱ አንዲት ደቂቃ ሳያልፍ\nተስፋውንም አዳም ከሰማ በኋላ\nአምስት ሺህ ከአምስት መቶ ሲሞላ\nለመፈፀም የማለለትን መሃላ\nከድንግል ዘንድ መልአኩን ላከው ገሊላ\n\nድንግልም በልጃገረድ ሥርዓት\nበአጭር ታጥቃ ማድጋ ነጥቃ ከቤት\nወደ ወንዝ ውሃ ልትቀዳ ሄደች\nከዚያም ወርዳ የጠማው ውሻ አየች\nሲያባሩት ና ሂድ እያሉ ሴቶች\nምነው ለእርሱስ አታዝኑለትም አለች\nቸር ነችና ከፈጣሪዋ በታች\nመለሱላት እንዲህ እያሉ ሴቶች\nየሥራ ፈት ይመስላልና ትጥቅሽ ይኸውልሽ አጠጪው አንቺ ቀድተሽ\nድንግልም የእነሱን ነገር አድንቃ\nለፍጥረቱ ታዝናለችና አጥብቃ\nወርቅ ጫማ ከተረከዟ አውልቃ\nአጠጣችው ከማድጋዋ ፈልቃ\nእኒያም ሴቶች እንዲህ ስታደርግ ቢያዩዋት እንዳትቀጂ ውሃው ጉድጓድ ነው አዘቅት\nማድጋሽን ምን ልትሞይው ነው አሏት\nሃይማኖቷ ፍጹም ነው ፍጹም ነውና ከጥንት\nአለቻቸው እነዚያን ሴቶች እናንት\nአታስቡ ምን ትሞላው ነው ብላችሁ\nከወደታች ውሃ የሚገኝ መስሏችሁ\nይህን ውሻ ያጠጣው አምላክ የት ሄዶ\nይሞላዋል ከወደ ሰማይ አውርዶ\nስትጨርስ ይህን ተናግራ ወዲያው\nማድጋዋን በተአምራት ሞላው\n\nእኒያም ሴቶች እንዲህ ስታደርግ ቢያዩዋት\nበዚያ ወራት ጉባዔ አድርገው ለሁሉ ይወለዳል አምላክ ከድንግል እያሉ\nነቢያትም ይናገራሉ ትንቢት\nየአምላክ እናት አንቺ ትሆኚ አሏት\nእንዲህ ብለው ሲነጋገሩዋት ምጸት\nሳያውቁት ተናገሩላት ትንቢት\nድንግልም በሴቶች ሁሉ ልማድ\nበጀርባዋ ውሃዋን አዝላ ስትሄድ\nትጸንሻለሽ በድንግልና የሚል\nድምጽ ሰማች ከወደኋላ ድንግል\nተሰወራት ምን ይሆን ብላ ልትለይ\nወደኋላ መለስ ብላ ብታይ\nይሆናል ያው ጠላታችን ሰይጣን\nያሳታቸው አባትና እናቴን\nይህን ብላ ዝም ብላ ሄደች ቤቷን\nሸክሟን ስታወርድ ከቤት\nትጸንሻለሽ በድንግልና አላት\nይኄ ነገር እውነት ነገረኝ መሰለኝ\nያንኑ ቃል አሁን ደግሞ እዚህ ደገመኝ\nይህን ብላ ከመቅደስ ሄደች ተነስታ\nከዚያም ሄዳ የወርቅ ወንበሯን ዘርግታ\nስትፈትል ወርቅ እና ሐሩን አስማምታ\nመልአኩም ልብሱን ሲታጠቅ ሲፈታ\nደስ ይበልሽ ለአንቺ ይገባል ደስታ\nቡርክት ነሽ እያለ ሰጣት ሰላምታ\nድምጹን ሰምታ መልአኩን አይታ ለይታ\nእንዲህ ብላ መለሰችለት ድንግል\nምድር ብትል ያለ ዘር እህል ላብቅል\nሴትም ልጅ ያለ ወንድ ልውለድ ብትል\nይቻላል ወይ መቼስ ተደርጎ ያውቃል\nእኔ ድንግል ወንድ አጠገቤ አይደርስ\nይኄን ነገር የት አገኘኸው አንተስ\nመለሰላት እንዲህ እያለ ሳይዋሽ\nማርያም ሆይ አትፍሪ አንቺስ አይዞሽ\nያንቺማ ጽንስ እንደ ሴቶች ጽንስ መስሎሽ\nከአንቺ ባሕርይ አንዱ አካል ሥጋን ሲለብስ\nያድርብሻል አንዱ አካል መንፈስቅዱስ\nያጸናሻል አንደኛው አካል አብም\nበባሕሪሽ እንዳያገኝሽ ድካም\nእንዲህ አርገሽ ሳትፈልጊ ወንድን\nትወልጃለሽ ከሦስቱ ቅዱስ አንዱን\nእንኳን አንቺ ሙቀት ልምላሜ ያለሽ\nያረጀችው ኤልሳቤጥ እንኳን እህትሽ\nበእርጅናዋ እግዚአብሔር ሰጥቷት ልጅን\nካረገዘች ስድስት ወር ሆኗል ይኄንን ትጸንሻለሽ በድንግልና አንቺም\nለእግዚአብሔር የሚሳን ነገር የለም\nስትመልስ እንዲህ እያለች እርሷም\nእነሆ አለሁ የእግዚአብሔር ባሪያው አሁን\nእንደ ቃልህ ይደረግልኝ አሁን (2)\n', 'am', 118, 0),\n(1, 'ፈያታዊ ዘየማን', ' ፈያታዊ ዘየማን\nፈያታዊ ዘየማን አምላኩን ለመነ\nበቀኝ ያቆመው ዘንድ ጌታን ተማጸነ\nወንበዴ ብሆንም ሽፍታ ወንጀለኛ\nመምጣትህን አሰብኩ ለድህነት ወደኛ\n\nአልሰማሁም እኔ የነቢያትን ቃል\nአላወቅኩም በእርግጥ አብሮኝ እስኪሰቀል\nኢሳይያስ ሲናገር ዳዊት ሲመሰክር\nየመሲሁን መምጣት አልሰማሁም ነበር\n\nአዝ፦\nበመስቀል ላይ ሳለ አምላኬን ለየሁት\nትሁት ነበር ፍጹም በደል የሌለበት\nስለ በደላችን እኛ ተሰቅለናል\nእሱ ግን በማን ላይ ወንጀልን ፈጽሟል\n\nአዝ፦\nጨረቃ ደም ሆና ፀሐይዋ ስትጨልም\nከዋክብት ረግፈው ሰማይ ሲያጉረመርም\nአምላክ መሰቀሉን ተፈጥሮ ነግራኝ ነው\nበመንግሥትህ ጌታ አስበኝ የምለው\n\nአዝ፦\nአወይ ቀያፋ ሆይ አወይ ሀና ሆይ\nደስ ብሏችሁ ዋለ በጌታ ስቃይ\nተፈጥሮ ምስክር ሆኖ ሲያስተምራችሁ\nእንዴት አላመነም ደንዳናው ልባችሁ\n', 'am', 119, 0),\n(1, 'ተግታችሁ ጸልዩ', 'ተግታችሁ ጸልዩ\nየተጋ በአምልኮት አልተጎዳምና\nፍሬአለው ምን ጊዜም ይኄ ክርስትና\nማመስገንን አብዙ ጸልዩ ወደ አምላክ\nበዚህ ተለውጧል የሕዝቡ ይህ ታሪክ\n\nእግዚአብሔርን የምታምኑ ሰዎች\nበስንፍና ነገር እንዳትባክኑ\nተግታችሁ ጸልዩ በፍቅር ሆናችሁ\nፍሬውን በሕይወት ታገኙታላችሁ\n\nአዝ፦\nጳውሎስ ስለሮጠ ከሁሉም አብልጦ\nአክሊል ተቀዳጀ ከሰዎች ተመርጦ\nመክሊቱን አትርፎ ለጌታው ቢያስረክብ\nዐረፈ በገነት ከዚህ ዓለም ሀሳብ\n\nአዝ፦\nእርፍ ከጨበጡ በኋላ የለም\nከዚህ ዓለም ኃጢአት መከራው ቢያይልም\nፍሬው በስተኋላ ያስደስታልና\nውስጡ ግን ጉም ነው ይኄ ክርስትና\n\nአዝ፦\nዕለት ዕለት ፍቅርን ጽድቅን መጨመሩ\nበእግዚአብሔር ስራ በእውነት መኖሩ\nፈተናው ቢያይልም ቢጎመዝዝ እንኳ\nመትጋት ያስፈልጋል ፍሬው እስኪለካ\n', 'am', 120, 0),\n(1, 'አልዓዛር ይነሳ', 'አልዓዛር ይነሳ\nአልዓዛር ይነሳ መግንነዙን ፍቱለት\nበጽድቅ አደባባይ ይመላለስበት\nተስፋ ላለው ሕይወት ልቡ ይነቃቃ\nነብሱ እንዳትወሰድ በአጋንንት ተሰርቃ\n\nአዝ፦\nየበደል እስራት መግነዙን ፍቱለት\nሕይወትን ያገኛት ጽድቅን ይኑርበት\nሞት መሻሩን አውቆ ከሞት በላይ ይቁም\nበእግዚአብሔር ቸርነት ልቦናው ይታመን\n\nአዝ፦\nበደሉ ቢበዛ ልቦናው ቢከብድም\nከአምላኩ ቸርነት በሚዛን አይበልጥም\nኃጢአቱን ተናዞ ንስሐ እንዲገባ\nመጽአትን አሳዩት የፍቅርን እንባ\n\nአዝ፦\nየሚያስደንቅ ብርህን አይቶ ይመላለስ\nአዲሲቷን ምድር በንስሐ ይውረስ\nካህናት አጽናኑ ሕዝብን በፍቅር ቃል\nሞት እውነት አይደለም በቃሉ ተሽሯል\n\nአዝ፦\nበአምላክ ብርሃን ይመላለስ አይቶ\nንስሐ ይጠበው እንዲታይ አብርቶ\nንጹህ ልብስ አልብሱት ነብሱ ሀሴት ታድርግ\nእሱም ሕያው ይሁን በሰዎች መአረግ\n\nአዝ፦\nከመቃብር ይውጣ ጌታ የጠራው ነው\nከሕይወት እንጀራ ማን ነው የሚያግደው\nብርሃን ክርስቶስ ለሱ ተሰውቷል\nስጋው ለእርሱ እኮ ነው ማን ይመገበዋል\n\nአዝ፦\nብርሃን ክርስቶስ አልዓዛር ይለዋል\nመቃብሩን ሺሮ አዲስ ፍጥረት ሆኗል\nማን ነው ሙት የሚለው ከእንግዲህ በኋላ\nተጠርቷል በጌታ ወደ ፍጹም ተድላ\n', 'am', 121, 0),\n(1, 'እናምናለን', 'እናምናለን\nእናምናለን እናምናለን እኛስ\nምስጢረ ሥላሴን እናምናለን እኛስ (4)\n\nንግበር ሰብዐ ብለው ሥላሴ ሲፈጥሩን\nተምረናል እኛ ከዚህ ሶስትነትን\nበስም በአካል በግብር ሦስት እያልን ነው\nየምናምነው\nአንድ እግዚአብሔር እንጂ ሦስት አምላክ\nአንልም\nበአካል በስም በግብር በፍፁም ሦስት ነው\nሁለትም አይደለ አራተኛም የለው\n\nእናምናለን እናምናለን እኛስ\nምስጢረ ሥላሴን እናምናለን እኛስ (2)\n\nበባሕሪይ በአገዛዝ በመለኮት ክብር\nእናምናለን እኛ አንድ ነው እግዚአብሔር\nነውና እግዚአብሔር አንድም ሲሆን ሦስት\nእንደተገለጠው በአብርሃም ቤት\n\nእናምናለን እናምናለን እኛስ\nምስጢረ ሥጋዌን እናምናለን እኛስ (2)\n\nየሰውን ባሕሪይ ገንዘብ ያደረገው\nከሦስቱ አካል አንዱ ፍፁም ሰው የሆነው\nምስጢረ ስጋዌ ያለጥርጥር\nየማይመረመር ጥልቅ ነው ምስጢር\nፍፁም አምላክ ሆኖ ፍፁም ሰው የሆነው\nበተዋሃደው ሥጋ እኛን ለማዳን ነው\n\nእናምናለን እናምናለን እኛስ\nምስጢረ ጥምቀትን እናምናለን እኛስ (2)\n\nከመንፈስ ከውሃ ያልተወለደ ሰው\nበፍፁም አይድንም ጌታችን እንዳለው\nበባህረ ዮርዳኖስ በዮሐንስ እጅ\nተጠመቀ ጌታ ነፃነት ሊያውጅ\nዕዳ በደላችን የግዞት ማህተብ\nተደምስሷልና በጥምቀቱ ሰላም\n\nእናምናለን እናምናለን እኛስ\nምስጢረ ቁርባንን እናምናለን እኛስ (2)\n\nየዘላለም ህይወት አምላክ እንዲሰጠን\nእንብላ ስጋውን እንጠጣ ደሙን\nኢየሱስ በመስቀል ደሙን ያፈሰሰው\nበሥጋ ወደሙ እኛን ሊያከብረን ነው\n\nእናምናለን እናምናለን እኛስ\nትንሳኤ ሙታንን እናምናለን እኛስ (2)\n\nበመጨረሻው ቀን ጌታችን ሲመጣ\nመንግስተ ሰማያት ስትታይ ተገልጣ\nመለከት ሲነፋ ነጋሪት ሲመታ\nየሰው ልጅ ይነሳል መቃብር ተከፍታ\nሙታን አካል ገዝፈው ለፍርድ ይመጣሉ\nሀሉም በጌታ ፊት ይሰበሰባሉ\n', 'am', 122, 0),\n(1, 'እንዴት እንዲያጠፉት', 'እንዴት እንዲያጠፉት\nእንዴት እንዲያጠፉት ካህናት መከሩ\nያመነቱ ነበር ሕዝብን እየፈሩ\nሰይጣን በይሁዳ ገብቶ ነበርና\nአሳልፎ እንዲሰጥ ልቦናውም ጸና\n\nአዝ፦\nከመቅደስ አዛዦች ከካህናት ጋራ\nስለጌታ መሞት ባንድ ላይ አወራ\nካህናት በደስታ ይሁዳን አቀፉት\nአምላኩን እንዲያሲዝ ሰላሳ ብር ሰጡት\n\nአዝ፦\nሕዝብ በሌለበት በአሳቻ ስፍራ\nጌታን እንዲያሲዘው አደረገ ሴራ\nኧረ እንዴት ጨከነ ይሁዳ አንጀትህ\nጌታን ያስገደልከው እንደዚያ ሲወድህ\n\nአዝ፦\nበረከቱን ከጅህ ሥልጣኑን በራስህ\nሊሰጥህ አስቦ ኢየሱስ ሊያከብርህ\nሰማየዊ ሀብትን ሰማያዊ ፀጋ\nአድሎህ ነበረ አልፋና ኦሜጋ\n\nአዝ፦\nየቃየል መሰዋዕት የኤሳው ብኩርና\nጌታውን የሚሸጥ ከፍጡር ሆነና\nበሰላሳ ዲናር በሚጠፋው ብዕል\nእንዲህ ያለ ጌታ ኧረ እንዴት ይከዳል\n', 'am', 123, 0),\n(1, 'ያዕቆብ ከቤርሳቤ', 'ያዕቆብ ከቤርሳቤ\nያዕቆብ ከቤርሳቤ ወደ ካራው\nሲሂድ የለውም ነበረ አማካሪ ዘመድ\nፀሀይ ጠልቃ ነበረ ከዚያ እንደ ደረሰ\nከእራሱ በታች ድንጋይ ተንተራሰ\nህልምንም አለመ ታላቁን ራዕይ\nመሰላል ተተክሎ ከምድር እስከ ሰማይ\nስወጡ ሲወርዱ መዕላክእት በእርሷላይ\nእግዚአብሔርም ቆሞ ከላይ ከጫፏ ላይ\n\nአዝ፦\nየአባቶችን አምላክ እኔ እግዚአብሔር ነኝ\nይህን ለርስት እሰጥሀለሁኝ\nዘርህ እንደ አሸዋ በምድር\nይዘራል በአራቱም ማዕዘን\nህዝብክም ይሆናል\n\nአዝ፦\nአበው በምሳሌ እንደ ተናገሩት\nከምድር እስከ ሰማይ አምላክ የዘረጋት\nበላያ ተቀምጦ በግልጽ የተይባት\nየያዕቆብ መሰላል እመቤታችን ናት\n\nአዝ፦\nሰማይና ምድር የሚታረቁባት\nወልደ እጓለ እመ ህያው የተገለጠባት\nመላዕእክት በሰማይ በአንድ የዘመሩላት\nታላቋ መሰላል እመቤታችን ናት\n', 'am', 124, 0),\n(1, 'አማኑኤል ተመስገን', 'አማኑኤል ተመስገን\nአማን በአማን (4)\nአማኑኤል ተመስገን (2)\nለዚህ ፍቅርህ ምን ልክፈልህ (2)\n\nአዝ፦\nድብቁን ኃጢአት አንተ ብትገልጸው\nይቅር ብለኸኝ ባትሸፋፍነው\nእንደ ሰው በቀል ቢኖር ጌታ\nለኔ ኃጢአትስ የለውም ቦታ\n\nአዝ፦\nበየደቂቃው ኃጢአት ስሰራ\nስሰርቅ ስበድል አንተን ሳልፈራ\nአንተ ግን ፊትህ ምንም ቢቀየም\nበቁጣህ በትር አልገረፍከኝም\n\nአዝ፦\nምህረትህን ልከህ አድነኝ ዛሬ\nታክቶኛልና በኃጢአት መኖሬ\nአለም በኃጢአት እየሳበችኝ\nበጽድቅ ደስታ መኖር አቃተኝ\nአዝ፦\nየኃጢአት ጉዞ ጣፋጭ ቢመስልም\nውጤቱ መሮ ፍጹም አይጥምም\nእንደ በደሌ ስላልከፈልከኝ\nተመስገን እንጂ ሌላ ምን አለኝ\n', 'am', 125, 0),\n(1, 'አንተን ማገልገል', ' አንተን ማገልገል\nአንተን ማገልገል መባረክ ነው\nምርጫ ነው ዕጣ ነው\nክብር ነው እድል ነው\n\nገና በማለዳ ብላቴና ሳለሁ\nየሰማሁት ዜማ ዛሬም ከልቤ ነው\nየጸናጽሉ ድምጽ የሸተተኝ ዕጣን\nካንተ ጋር አስሮኛል በዝማሬ ኪዳን\n\nአፈር ትቢያ ስሆን ከሁሉ ያነስኩኝ\nእንዳገለግልህ በአንተ ተመረጥኩኝ\nየአንተ ስምና ክብር በአፌ ላይ አለፈ\nበባሪያህ ተጠቅመህ ስንት ሰው አረፈ\nዓለም ሳትወስድብኝ ያንተን ውድ ጸጋ\nለክብርህ እንደዘመርኩ እየመሸ ነጋ\nየዜማ ጠጠሬ ያለህ በወንጭፌ\nሺ ጠላት ቢከበኝ ምስጋና ነው ሰልፌ\n\nተከፍቼ አላውቅም እኔ በአንዳች ነገር\nስምህን አንግቤ ስሄድ አገር ለአገር\nሰላደረክልኝ ባዕዳን ሆነው ዘመድ\nሞገስ ክብር ሆንከኝ ባለፍኩበት መንገድ\nዘመኔ የደስታ የሐሴት ሆነልኝ\nስትረዳኝ ስላየሁ አቤኔዘር አልኩኝ\nስለ እጅህ ስጦታ አሜን ብዬሃለሁ\nየስምህ አወዳሽ የልጅ ልጅ አያለሁ\n', 'am', 126, 0),\n(1, 'ሀገራችን ሰማይ', 'ሀገራችን ሰማይ\nሀገራችን ሰማይ\nእናታችን ማርያም (2)\nለምን ፍቅር አጣን አለም የእኛ አይደለም\nለምን ሰላም አጣን አለም የእኛ አይደለም\n\nአዝ፦\nበልብ ያልታሰበች ስፍራ አዘጋጅቶልን\nበአይንም ያልታየች መንግስቱን ሰርቶልን\nቅዱስ ህዝብ አድርጎ ለእርስቱ የተለዩ\nየአንድ እግዚአብሔር ልጆች ለምን ተለያዩ (2)\n\nአዝ፦\nስለአንድ ዓላማ እረኛው ከጠራን\nያጵሎስ የኬፋ እንደምን ተባባልን\nየሐዋርያቱ የእኛ ተልእኮ\nአያቀናም ትውልድ ልዩነት ተሰብኮ\nአይቀናም ትውልዱ ልዩነት ተሰብኮ\n\nአዝ፦\nየያዕቆብ የኤሳው የበኩርናም ትግል\nያቆስል ነበረ የእርብቃን ማህፀን\nቅርንጫፉ ይበዛል ግንዱ ግን አንድ ነው\nስለሞተልን ነው እኛ የምንሰብከው (2)\n\nአዝ፦\nይልቅ በአንድ ሀሳብ በአንድ እንስማማ\nብጹህ እንድንሰኝ በእግዚአብሔር ከተማ\nበድንግል ማርያም ዙሪያ ተሰብስበን\nበጸጋ እንቀበል መንፈስ ቅዱስን (2)\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 127, 0),\n(1, 'ኢትዮጵያንና ህዝቦቿን', 'ኢትዮጵያንና ህዝቦቿን\nኢትዮጵያንና ህዝቦቿን (2)\nድንበር የሚጠብቁትን (2)\nጠብቅ እግዚአብሔር ሠራዊቷን (4)\n\nየደም መሬት አትሁን ደም አይፍሰስባት\nካንተ የመነጨ ሰላም ይስፈንባት\nአሽናፊ እንድትሆን ለስምህ ተገዝታ\nአይንህን ሳትመልስ እያት ጠዋት ማታ\n\nአዝ፦\nሰንሰለት ሲፀና ለመከራ ፈርቶ\nኢትዮጲያዊ መልኩን አይቀይርም ከቶ\nድንቁን ብርሃን ያያል ወቶ ከጨለማ\nበመንገዱ ሁሉ አዳኝ ቀኝ ቀድማ\n\nአዝ፦\nእጅግ የፈተናት ተነቅሎላት መርዙ\nከእግሮቿ በታች ጠላቶች ይገዙ\nደጅ ስትጠና እጆቿን ዘርግታ\nጠብቅ ሠራዊቿን ዱሩ እንዳይፈታ\n\nአዝ፦\nከራሳቸው ይልቅ ኢትዮጵያን ወደዱ\nደም ከፍለው ሊያቆዮት በዱር ተሰደዱ\nበሃሩር በውርጩ የሆኗትን አጥር\nበማይፋቅ ቀለም ፃፋቸው ለክብር\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 128, 0),\n(1, 'ይላል አንደበቴ', 'ይላል አንደበቴ\nይላል አንደበቴ እግዚአብሔር ቅዱስ ነው\nአይተወኝምና ወላጅ እንደሌለው\nትናንት የጠበቀኝ የነገም ተስፋዬ\nትልሃለች ነፍሴ ፍቅር ነህ ጌታዬ\n\nአዝ፦\nየትናንት ሕይወቴን ዞር ብዬ ሳየው\nማምለጫ የሌለው አጥሩም እሾህ ነው\nወደ እረፍቴ ወጣሁ ይድረስ ምስጋናዬ\nደጆች ቢዘጉብኝ በር ሆኖኝ ጌታዬ (2)\n\nአዝ፦\nበጥልቁ በረሃ ምግብ መጠጥ ሆኖኝ\nመንገዴን አቀናው እጄን በአፌ አስጫነኝ\nበእሳትና ውሃ መካከል አልፌ\nተመስገን እላለሁ ቅኔ ሞልቶት አፌ (2)\n\nአዝ፦\nየብቸኝነቴን ማዕበል ገስጿል\nለእኔ ብርሃን ሆኖ ለከሳሽ ጨልሟል\nቀስቱን እያጠፈ ታደገኝ ከስቃይ\nየጌታዬ ሃሳብ ፍቅር ነው በእኔ ላይ (2)\n\nአዝ፦\nትናንት ዛሬ ነገ ዘላለም ጠባቂ\nየልቤን ፍላጎት ሳልነግረው አዋቂ\nበባሕርይው ቅዱስ የሌለው አምሳያ\nስሙ ወደቤ ነው መልህቄን መጣያ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 129, 0),\n(1, 'በድንኳኔ እልልታ ሙሉ ነው', 'በድንኳኔ እልልታ ሙሉ ነው\nበድንኳኔ እልልታ ሙሉ ነው\nበድንኳኔ ዝማሬ ሙሉ ነው\nበማንነቴ ላይ እግዚአብሔር ታላቅ ነው\n\nአዝ፦\nፍላፃውን የጠላቴን ቁጣ\nመከተልኝ ወደ እኔ እየመጣ\nበራራልኝ በእርሱ በወዳጄ\nሰላም ሰፍኗል በጓዳ በደጄ\n\nአዝ፦\nየመንገዴን ጥርጊያውን አቅንቶ\nየሰለለ ጉልበቴን አፅንቶ\nከፊት ለፊት በድል ቀድሞልኛል\nበምስጋናው ከኋላ ስቦኛል\n\nአዝ፦\nስላልተወኝ አንዳች አጣህ ብሎ\nሙሉ ሰው ነኝ የለኝም ጎዶሎ\nበከፍታ ብኖር በዝቅታ\nደስተኛ ነኝ ሁልጊዜ በጌታ\n\nአዝ፦\nማማረርን ማጉረምረም ትቻለሁ\nአንደበቴን ቅኔ ሞልቻለሁ\nቢፈራረቅ ብርሃን ጨለማ\nከቶ አልወርድም ከምስጋና ማማ (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 130, 0),\n(1, 'ቅድስት ሥላሴ', 'ቅድስት ሥላሴ\nገፄን አማትቤ ልጀምር ውዳሴ\nበትምህርተ መስቀል በስመ ሥላሴ\nይርቃል ከጎኔ ጠላት ዲያብሎስ\nበስመ አብ ወወልድ ወመንፈስ ቅዱስ\n\nአዝ፦\nከትቢያ ከአፈር አንስቶ የሰራኝ\nበአፉም እስትንፋስ ሕይወትን ያደለኝ\nየሥላሴ ሥራ ድንቅ ነው ጥበቡ\nከአይምሮ በላይ ነው የእግዚአብሔር ሃሳቡ\n\nአዝ፦\nእክሕደከ ሰይጣን ጠላቴን ክጃለሁ\nለዚህም ምስክር ማርያም ናት ብያለሁ\nበቤተክርስቲያ ቆሜ በመቅደሱ\nለቅድስት ሥላሴ ዘመርኩ ለንጉሡ\n\nአዝ፦\nአልነበረም ዘመን እርሱ ያልነበረበት\nዳግመኛም አይኖርም እርሱ ማይኖርበት\nየሕይወቴ ጣዕም ክብሬ እና ሞገሴ\nየማይሾሙት ንጉስ ዘላለም ሥላሴ\n\nአዝ፦\nኪሩቤል ሱራፌል ኃይላት ሊቃናት\nመናብርት ስልጣናት ቆመው በአንድነት\nያለአንዳች ዝምታ ይሉታል በክብር\nቅዱስ ቅዱስ ቅዱስ እግዚአብሔር\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 132, 0),\n(1, 'እንዲህ በአራት ነጥብ', ' እንዲህ በአራት ነጥብ\nእንዲህ በአራት ነጥብ ሊዘጋ ምዕራፉ\nእግዚአብሔር ሊያሸንፍ የእርሱ ሆኖ ሰልፉ\nመልካም ለመናገር አፉ ባይታደል\nይህን እስኪያይ ጠላት ምን አለ ዝም ቢል (2)\n\nአዝ፦\nመልካሙን ደብቆ ክፉን እያሳየ\nይለኝ ነበር ጠላት እግዚአብሔር ዘገየ\nግን ሁሉን በጊዜው ውብ አድርጎ ሲሰራ\nአፍሮአል ለዘላላም ደንቆት የእርሱ ሥራ (2)\n\nአዝ፦\nበቃ ልጅ የለህም አትወልድም ሣራ\nላይሰማህ እግዚአብሔር ጮኸ ብትጣራ\nእያለ ጠላቴ መስሎት ያሸነፈ\nይስሃቅ ተወለደ ያ ቀንም አለፈ (2)\n\nአዝ፦\nፍፃሜዬን ሳያይ ገና ከጅምሩ\nጠላት በእሱ ግምት ብዙ መናገሩ\nአስብሎታል ቴቄል ተቀይሮ ስሙ\nየዘገየ መስሎ ጌታ በመቅደሙ (2)\n\nአዝ፦\nድንጋይ ያሸከመን ውሃ ተሸከመ\nለእኛ ቀን ወጣልን ለእርሱ ግን ጨለመ\nገዳይ ቢዘገይም ሟች በመገስገሱ\nፈረሰኛው ሞተ እስከነ ፈረሱ (2)\n\nአዝ፦\nቢመስለንም ሌሊቱ ፍፁም የማይነጋ\nተቆልፎ የሚቀር በሩ እንደተዘጋ\nእርሱን ተስፋ አድርገው ባመንክበት ፅና\nቀን አለው እግዚአብሔር ያደርግሃል ቀና (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 133, 0),\n(1, 'ያዳነኝን አውቀዋለው', ' ያዳነኝን አውቀዋለው\nያዳነኝን አውቀዋለው\nየሞተልኝ ኢየሱስ ነው\nስለሌለኝ የምከፍለው\nስጦታዬ ምስጋና ነው\n\nጨለማዬን አስወግዶ\nያበራልኝን አውቃለሁ\nሙሉ ሰው ነኝ ከእንግዲህስ\nስከተለው እኖራለሁ\nየብርሃንን ልዩ ውበት\nፊት ለፊቴ ቆሞ አየሁት\nፍቅሩ ማርኮኝ\nበመቅደሱ ሰገድኩለት አመለኩት\nላመስግነው ላመስግነው ላመስግነው\nፍቅሩ ማያልቅ ነው (2)\n\nአዝ፦\nአሳደረኝ በእቅፉ\nመጠውለጌን አለምልሞ\nበመስቀል ላይ ተሰቀለ\nዳንኩኝ እኔ እርሱ ታሞ\nበማይዝለው ክንዶቹ ላይ\nእኔን በክብር እያኖረ\nእንዲመቸኝ ዝቅ ብሎ\nበበረት ውስጥ እርሱ አደረ\nላመስግነው ላመስግነው ላመስግነው\nፍቅሩ ማያልቅ ነው (2)\n\nአዝ፦\nቅኔ ባፈስ ምን ይደንቃል\nደሙን በመስቀል አፍስሶ\nስለ ልጁ መዳን ብሎ\nነፍሱን ሳይቀር ለኔ ክሶ\nፍቅሬ ይዞት ከጸባኦት\nበትህትና መቶ ወርዶ\nተቀደስኩኝ በነጩ በግ\nቀራንዮ ጌታ ታርዶ\nላመስግነው ላመስግነው ላመስግነው\nፍቅሩ ማያልቅ ነው (2)\n\nአዝ፦\nአክሊለ ሶክ አጠለቀ\nግርማ ክብሩን ሁሉ ትቶ\nአሻገረኝ ወደ ክብሬ\nበቅዱስ ደም እኔን ዋጅቶ\nአጎንብሶ ቀና አረገኝ\nፊቴን በጽድቅ እያበራ\nእኖራለሁ ለዘለአለም\nካከበረኝ ጌታ ጋራ\nላመስግነው ላመስግነው ላመስግነው\nፍቅሩ ማያልቅ ነው (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 134, 0),\n(1, 'ሞገድ ሲመታኝ', 'ሞገድ ሲመታኝ\nሞገድ ሲመታኝ ማዕበሉ\nማን ያድነዋል ሁሉም ሲሉ\nበሰላም አለፍኩ በፀጥታ\nሁሉ ተችሎ ላንተ ጌታ (2)\n\nበአንተስ ቁስል ተፈወስኩኝ\nጌታ በፍቅር ተማረኩኝ\nሞቴን ሽረኸው ባንተ ሞት\nይህው አቆምከኝ በህይወት (2)\n\nአዝ፦\nደጅህ ስጠና ስማጸንህ\nመቼ ጨከነ ጌታ ልብህ\nእንደ ቀራጩ አጎነበስኩ\nምህረት ጸጋህ በእጅህ ለበስኩ (2)\n\nአዝ፦\nዘወትር እልል ብል ብዘምር\nስለገባኝ ነው ያንተ ፍቅር\nጌታ ብጠራው ስምህን\nለውጠኸው ነው ታሪኬን (2)\n\nአዝ፦\nአይኖቼ አያዩም ካንተ በቀር\nየምትወደድ የምትፈቀር\nዘመድ ወገኔ ሆነኸኛል\nእኔን የሚችል የት ይገኛል (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 135, 0),\n(1, 'አጌጥንበት ስምህን', 'አጌጥንበት ስምህን\nአጌጥንበት ስምህን\nተዋብንበት ፍቅርህን\nሞገሳችን ሆነሃል\nየጽድቅ ልብሳችን አማኑኤል (2)\n\nተዋህዶ የአዳምን ሥጋ\nአማኑኤል ሆነ ከእኛጋ\nበግርግም በቤተልሔም\nተወልዶ ሆነልን ሰላም\n\nአዝ፦\nብንጠግብ በልተን ጠጥተን\nብንገባ በሰላም ወጥተን\nልጆችን ወልደንም ብንስም\nጠርተን ነው ጌታ ያንተን ስም\n\nአዝ፦\nቢያምርብን ቢሞቀን ለብሰን\nብንረሳ ለቅሶና ሀዘን\nፍቅርህ ነው ዛሬን ያሳየን\nተመስገን እንልሃለን\n\nአዝ፦\nበባዕድ ሀገር ብንኖር\nቢገጥመን መከራ ችግር\nነጩን ልብስ ለብሰን ታይተናል\nመስቀሉን ከማህተቡ ጋር\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 136, 0),\n(1, 'ምስጋናው ይቀጥል', 'ምስጋናው ይቀጥል\nምስጋናው ይቀጥል ዝማሬው ይቀጥል\nእግዚአብሔር ስላለ ከያዘ የማይጥል\nበምናየው ነገር በምንሰማው ወሬ\nእንዳይቆም ምስጋና እንዳይቆም ዝማሬ\n\nየሰማዕታቱ ደም የፈሰሰው በምድር\nአይተናል ሲያስቀጥል የክርስትናን ዘር\nእንድናምን ብቻ መች ተጠራንና\nበእሳቱም መካከል ቅኔ አለን ምስጋና\n\nአዝ፦\nመች ማጥፋት ይቻላል እሳትን በእሳት\nአይቆምም ማህሌት ቅዳሴ ሰዓታት\nከሰማዩም በላይ ከሰማዩም በታች\nቤተ ክርስቲያን ዛሬም ነገም አለች\n\nአዝ፦\nየዓለም ጨው ሆነን በዓለም የበዛነው\nእየተደበደብን እየተገፋን ነው\nበገደሉን ጊዜ ቁጥራችን ይበዛል\nከሞትም በኋላ ህይወት ይቀጥላል\n\nአዝ፦\nየተስፋይቱን ምድር ተነሱ እንወርሳለን\nበመዝሙር በእልልታ ቅጥሩን እያፈረስን\nየሰላዮቹን ቃል ሰምታችሁ አትፍሩ\nበሃይማኖት ጽኑ በእምነታችሁ ቁሙ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 137, 0),\n(1, 'እንዲህ እናምናለን', 'እንዲህ እናምናለን\nእንዲህ እናምናለን እንታመናለን (2)\nአብ ወልድ መንፈስ ቅዱስ አንድ እግዚአብሔር\nብለን (2)\n\nየእግዚአብሔር አብ ፍቅሩ ይሰፋል ይረቃል\nልጁን እስኪሰጠን እንዲሁ ወዶናል\nበደብረ ታቦር ላይ እርሱን ስሙት ላለው\nበመዝሙር ለቃኘን ምስጋና ይድረሰው (2)\n\nአዝ፦\nአብርሃም ይስሐቅን አባት እንደሆነው\nአይደለም ልደቱ በአማን ልዩ ነው\nየተወለደ ነው ከቶ አልተፈጠረ\nከአባቱ ጋራ ቅድመ ዓለም የኖረ (2)\n\nአዝ፦\nሊያጽናናን የሚላክ ከአብ የሚወጣው\nበሃምሳኛው ዕለት ወደኛ የመጣው\nየራሱ የሆነ ፍጹም አካል ያለው\nጰራቅሊጦስ ጌታ እግዚአብሔር አምላክ ነው\nየራሱ የሆነ ፍጹም አካል ያለው\nጰራቅሊጦስ ጌታ እግዚአብሔር ቅዱስ ነው\n\nአዝ፦\nበእደ ዮሃንስ ሲጠመቅ በማይ\nወልደ አምላክ መሆኑ ስንሰማ ከላይ\nበአምሳለ እርግብ ወርዶ በእርሱ የኖረው\nለአካላዊው ቃል እስትንፋስ ሕይወት ነው (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 138, 0),\n(1, 'ኃያል ነው እግዚአብሔር', 'ኃያል ነው እግዚአብሔር\nኃያል ነው እግዚአብሔር\nኃያል ነው ቅዱሱ (2)\nአይቻለሁ በዓይኔ ሲቆም ማዕበሉ\nአይቻለሁ በዓይኔ ሲታዘዝ ነፋሱ\n\nአዝ፦\nሰረገላውን በእሳት ሠርቶታል\nበደመና ላይ ይረማመዳል\nበብርሃን ድንኳን በሰማይ ያለው\nእርሱ ነው ጌታ የምናመልከው (2)\n\nአዝ፦\nእውነት በፊቱ ፍትሕ በእጁ\nሲኦልም ገነት አሉ በደጁ\nሥልጣን የእርሱ ነው አለቅነት\nማን እንደ ጌታ ከአማልክት (2)\n\nአዝ፦\nታቦር ተራራ ተንቀጠቀጠ\nግርማው ሲገለጥ ሁሉ ቀለጠ\nድንቅን አድራጊ ተአምረኛ\nከማዳኑ ጋር ይምጣ ወደ እኛ (2)\n\nአዝ፦\nምድር ጠፈሩ ታዟል ለእርሱ\nእሳት ተፈትሎ ሆኗል ቀሚሱ\nየክብርህ ብርሃን ይብራ በልቤ\nአንተ ነህ ለእኔ ውድ ገንዘቤ (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 139, 0),\n(1, 'እርሱ ፍፁም ሊልቅ', 'እርሱ ፍፁም ሊልቅ\nእርሱ ፍፁም ሊልቅ እኔ ላንስ ይገባል\nከኔ ይልቅ ጌታ እጅግ ይበረታል\nእኔ ለንስሐ በውሃ አጠመቅኃቹሁ\nበእሳት ያጠምቃል ይመጣል ያልኳችሁ (2)\n\nጫማዉን ልሸከም ከቶ የማይገባኝ\nእኔን አስቀድሞ ለአገልግሎት ጠራኝ\nከኋላዬ የመጣው ነበረ ከፊቴ\nበስሙ ታምኑ ዘንድ እረሱ ነው ስብከቴ\n\nአዝ፦\nበምድረበዳ ላይ የጮኅኩለት ንጉሥ\nየሃያላን ሀያል ተገልጧል ኢየሱስ\nለኃጢአት ስርየት ይሰዋል ይሄ በግ\nለዓለም ሁሉ መዳን በቀራንዮ ሰርግ\n\nአዝ፦\nለንስሐ የሚሆን ፍሬ ዛሬ አድርጉ\nበሰርጉ ሊጠራን መጥቷልና በጉ\nከሚመጣው ቁጣ በእርሱ እድታመልጡ\nየእፉኝት ልጆች ከባቢሎን ውጡ\n\nአዝ፦\nየአብርሃም ልጆች ነን በማለት ላትድኑ\nየማዳኑን ሰዓት ቀኑን አታባክኑ\nለአብርሃም ልጆች ከድንጋይ ያስነሳል\nመንሹም በእጁ ነው አውድማው ይጠራል\n\nአዝ፦\nጠማማው ልብ ይቅና ጥርጊያው ይደላደል\nፍሬ የሌለው ዛፍ በቶን ሳይቃጠል\nምሳር በዛፎች ስር ዛሬም ተቀምጧል\nንስሐ ግቡ ነው የመጨረሻው ቃል\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 140, 0),\n(1, 'እንደ ዮሴፍ', 'እንደ ዮሴፍ\nእንደ ዮሴፍ እንደ ሰባ ሰገል በሆን (2)\nኢየሩሳሌም (3) በሆን አምላክ (ጌታ) ሲወለድ ባየን (2)\n\nአዝ፦\nየሰው ልጅ መከራ ዘመኑ ሲያበቃ\nከተስፋው ሳይዘገይ ሳይቆይ ለደቂቃ\nነቢያት በትንቢት እንደተናገሩ\nየአብ ቃል ወረደ ከሰማይ ሃገሩ (2)\n\nአዝ፦\nወርቅ ለመንግስቱ እጣን ለክህነቱ\nሰባ ሰገል ይዘው ከርቤውን ለሞቱ\nከማይጠፋ መዝገብ ለሚሽረው ጌታ\nሳጥኑን ከፈቱ ሊያቀርቡ ስጦታ (2)\n\nአዝ፦\nከምስራቅ ይወጣል የተባለው ኮከብ\nቀዳዶ ሊጥለው የጠላትን መረብ\nታናሿ ሙሽራ ድንግል ታቀፈችው\nመጋቢውን ጌታ ወተት አጠጣችው (ጡቷን አጠባችው) (2)\n\nአዝ፦\nዮሴፍ አረጋዊ እንዴት ቢታደል ነው\nበእርጅናው ዘመን ጠባቂ የሆነው\nድንግል እንደሆነች የሐዲስ ኪዳን መቅደስ\nክብሯን አላወቀ እስክትወልደው ድረስ (2)\n\nአዝ፦\nለተጨነቀች ነፍስ ማረፊያ ሊሆናት\nከድንግል ሲወለድ አልተገኘለት ቤት\nስብሐት ለእግዚአብሔር በሰማይ ብለናል\nከመላእክቱ ጋር መዝሙር ጀምረናል\nእኛም እንደ እረኞች ዝማሬን ይዘናል\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ እና ዘማሪ ቀሲስ ወንድወስን በላይ\n', 'am', 141, 0),\n(1, 'ወንድ ልጅ ተሠጠን', 'ወንድ ልጅ ተሠጠን\nወንድ ልጅ ተሠጠን ሕፃን ተወለደ\nበለቢሰ ሥጋ ኮነነ ዘመደ (2)\n\nአዝ፦\nከእኛ እንደ አንዱ ሆነ የተባለው አዳም\nይኸው ተወለደ ኪዳኑን አረሳም\nበሞት ጥላ ላለን ጨለማን አራቀ\nአማናዊው ፀሀይ ከድንግል ሠረቀ\n\nአዝ፦\nተመኝቶ ነበር ሙሴ ገፁን ሊያየው\nአይተህኝ አትቆምም ብሎ ከለከለው\nእርሱ ጀርባውን ሲያይ አዘልሽው በጀርባሽ\nከሁሉ መረጠሽ በልጁ ፊት በራሽ\n\nአዝ፦\nፊታቸውን ጋርደው መላእክት ሲቆሙ\nእናቱ ነሽና ክንድሽ ላይ ነው ፍሙ\nይህ እሳት ወረደ ቤተልሔም ግርግም\nበእጆችሽ ዳሰስነው አላቃጠለንም\n\nአዝ፦\nበአባቱ እቅፍ ያለው እስከሚተርከው\nአንድስ እንኳን የለም እግዚአብሔርን ያየው\nቢለንም ዮሐንስ በቃለ ወንጌሉ\nአየነው በአንች እቅፍ በተለየ አካሉ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 142, 0),\n(1, 'ዳዊት መዝሙረኛው', 'ዳዊት መዝሙረኛው\nየሳኦልን ካባ ያልተለማመደው\nበእረኝነት ልብሱ ጎልያድን ገጠመው\nግንባሩን ሲመታው ወድቋል በግንባሩ\nእግዚአብሔር ነበር የወንጭፍ ጠጠሩ\n\nአዝ፦\nነቢዩን ቢልከው ለበደሉ ቅጣት\nዳዊት ማቅ ለበሰ ዙፋኑን እረሳት\nበትቢያ ላይ ተኛ አመድ ነሰነሰ\nየራቀውን ጸጋ አልቅሶ አስመለሰ\nዳዊት መዝሙረኛው ሲበድል አልቃሻው\nእንደ ልቤ ብሎ እግዚአብሔር ጠራው (2)\n\nአዝ፦\nየወርቅ ልብስ ለብሶ ቢጨብጥም ጦር\nበቤተ መንግስቱ ቢኖርም በክብር\nእግዚአብሔር ቢቀባው አድርጎት ንጉሥ\nዳዊት መች ተገኘ ሕዝቡን ሲያስለቅስ\nዳዊት መዝሙረኛው ሲበድል አልቃሻው\nእንደ ልቤ ብሎ እግዚአብሔር ጠራው (2)\n\nአዝ፦\nየዓለምን ጥበብ ፍጹም ለማሳፈር\nከዓለም ሞኝ ነገር መረጠ እግዚአብሔር\nሰው በሃይማኖት እንጂ ከፊቱ የሚቆመው\nየዚህ ዓለም ጥበብ ያለ እምነት ከንቱ ነው\nዳዊት መዝሙረኛው ሲበድል አልቃሻው\nእንደ ልቤ ብሎ እግዚአብሔር ጠራው (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 143, 0),\n(1, 'አለ ለእኔ', 'አለ ለእኔ\nአለ ለእኔ የተሻለ ነገር (2)\nዛሬን ባዝን ለጊዜው ብቸገር\nአለ ለእኔ የተሻለ ነገር\n\nአዝ፦\nበእጄ የጨበጥኩት በድንገት ቢበተን\nዙሪያዬን ቢከበኝ ያላሰብኩት ሀዘን\nእንባዬ በደስታ መቀየሩ አይቀርም\nእተማመናለሁ በጌታዬ አላፍርም\n\nአዝ፦\nሀብቴን ልጄን ባጣ እርሱ እንደወደደ\nየእዮብ መከራ በእኔም ከወረደ\nእራቁቴን መጣሁ እንዲሁ እሄዳለው\nከዚህ የላቀውን ከእርሱ እጠብቃለው\n\nአዝ፦\nመከራው ቢከብደኝ ከዙፋን ወርጄ\nከርስቴ ብሰደደ በአቤሰሎም ልጄ\nቀኑ እሰከሚነጋ አልፈራም ጨለማ\nዳግም እለብሳለው የጺዮንን ግርማ\n\nአዝ፦\nአሳዳጄ ቢያይል ጉልበቱ ቢጸና\nተግዳሮቱ በዝቶ ወደ እኔ ቢያቀና\nየከበረው ድንጋይ አለ በወንጭፌ\nእቋቋመዋለው እርሱን ተደግፌ\n\nአዝ፦\nበናባው ተራራ ቢሆን መቃብሬ\nከነዓን ባልገባ ከህዝቡ ጋር አብሬ\nአለኝ በሰማይ ቤት እጅግ የከበረች\nበጆሮ ያልተሰማች በዓይንም ያልታየች\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 145, 0),\n(1, 'የሚጸልይ ሰው', 'የሚጸልይ ሰው\nየሚጸልይ ሰው አሸናፊ ነው ይሰማል ጸሎቱ\nለጸሎት የሚቆም አሸናፊ ነው ይሰማል ጸሎቱ\nአምላኩን ሲጣራ ይጠፋል እሳቱ\nጌታው ከእርሱ ጋር ነው ይሰምራል ስእለቱ\n\nድል የሚያደርግበት ኃይልን ይታጠቃል\nውኃ እየገደበ በጸሎት ያቆማል\nሰባት እጥፍ እሳት በፊቱ ቢነድ\nበረዶ ነው ለእግሩ እረግጦት ሲሄድ\n\nአዝ፦\nሺህ ጠላት ቢሰለፍ ቢጋረደ በፊቱ\nየብርቱዎችን ቀስት ይሰብራል ጸሎቱ\nአምኖ ለለመነ ሁሉ ይቻለዋል\nተራራውን ነቅሎ ባህር ላይ ይተክላል\n\nአዝ፦\nኃይሉ እያደረገ የጸሎትን ጉልበት\nወኀኒውን ይሰብራል ይቆርጣል ሰንሰለት\nበእሳት ሠረገላ በሰማይ ይበራል\nፀሐይ እያቆመ ዝናብን ያዘንባል\n\nአዝ፦\nተራራ ያከለው የችግራችን ቀን\nደልዳላ ይሆናል ፊቱ ከወደቀን\nለጸሎት ተነሱ ሰልፉን እንሰለፍ\nእንቁም በእንባ መከራችን ይለፍ\n\nሊቀ መዘምራን ዲያቆን ቴዎድሮሰ ዮሴፍ\n', 'am', 146, 0),\n(1, 'አለቀብኝ ብዬ', 'አለቀብኝ ብዬ\nአለቀብኝ ብዬ እጄ ባዶ ሆነ\nብዬ ሳዝን የሚሞላው አለ\nባዶ ጎተራዬን በፍሬ የሞላው\nእግዚአብሔር ከአባትም በላይ ነው\nእግዚአብሔር ከአባትም በላይ ነው\n\nየማይጥል የማይከዳ\nየሚያዝን የሚረዳ\nፍቅር ነው የማይጠላ\nእግዚአብሔር ነው ከሌላ (2)\n\nአዝ፦\nጉልበታም ነው ክንዱ ጽኑ\nድንቅ የሚያደርግ በየቀኑ\nይሸከማል ነጋ ጠባ\nአይቆረቁር የእርሱ ጀርባ (2)\n\nአዝ፦\nበእፈፍት ውሃ እየመራኝ\nበለምለም መስክ አሰማራኝ\nአልጨነቅ ለሚመጣው\nየኔ ጉዳይ ከሰማይ ነው (2)\n\nአዝ፦\nበእርሱ ሞልቷል ማስሮዬ\nአንዳች አይጎድል ማድጋዬ\nየእርሱ ቁጥር ቀኑ ሲደርስ\nያደርገዋል ሁሉን አዲስ (2)\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 147, 0),\n(1, 'ሆሣዕናችን ጌታ ኢየሱስ', 'ሆሣዕናችን ጌታ ኢየሱስ\nየሰላም ንጉስ በአህያ ላይ\nበእየሩሳሌም ታየ ጸሐይ\nደዌን ሊሸከም ሊያድለን ፈውስ\nሆሣዕናችን ጌታ ኢየሱስ\n\nዘንባባን ይዘው በእጃቸው\nቅኔን ሊዘራ ልሳናቸው\nየምስጋና አምላክ በእልልታ\nኢየሱሳሌም ገባ ጌታ\n\nአዝ፦\nጽዮን ከተማ ተደሰተች\nንጉስ ሲመጣ በዖይኗ እያየች\nድነትሽ ቀርቧል ሰላማሽ\nሐሴት አድርጊ በሕዝብሽ\n\nአዝ፦\nየኪሩቤልን ድንቅ ሥራ\nታየች አህያ ስትሰራ\nዙፋን ሁናለች ለንግሱ\nከውርንጫ ጋር በመቅደሱ\n\nአዝ፦\nከፊት ሲቀድሙ ሲከተሉ\nበምስጋና ቃል እልል ሲሉ\nአነጠፉለት ልብስን በምድር\nላንተ ይግባል ሲሉ ክብር\n\nአዝ፦\nድንጋይ ጀመረ ቅኔ መዝሙር\nእንደ መላዕክት ሲሰጥ ክብር\nከየት አግኘው አንደበትን\nብሎ የጮኸው አሁን አድን\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 148, 0),\n(1, 'ኢትዮጵያ ሠላምሽ ይብዛ', 'ኢትዮጵያ ሠላምሽ ይብዛ\nኢትዮጵያ ሠላምሽ ይብዛ\nተጠለይ በእግዚአብሔር ታዛ\nኢትዮጵያ ሠላምሽ ይብዛ\nተጠለይ በእግዚአብሔር ታዛ (2)\n\nከሚራራልን ፍቅር ከሆነው\nዘላቂ ሠላም ከእግዚአብሔር ነው\nይኽን እወቂ ይኽን ተረጂ\nበልብሽ ጉልበት ለእርሱ ሥገጂ\n\nአዝ፦\nበሠይፍ ያልቃሉ ሠይፍ የሚያነሱ\nየሚራራልን ሲፈርድ ንጉሡ\nበቀል የእርሱ ነው አይደለም የአንቺ\nበጸጋው ታጥረሽ በጸሎት በርቺ\n\nአዝ፦\nየውጣ ውረድ የጉስቁልናው\nበእግዚአብሔር ነው መከራ ማብቂያው\nሠላም ይሁን ሲል ይሆናል ሠላም\nየአሳየሽውን ፍቅር አይረሳም\n\nአዝ፦\nማራት ኢትዮጵያን ማራት ሐገሬን\nበእየሄድሁበት መጠሪያ ሥሜን\nይብቃት ሌሊቱ ይውጣላት ጸሐይ\nአሁን ይዘርጋ እጅኽ ከሠማይ\n\nአዝ፦\nእድትፈራርስ ጠላት ሸምቋል\nብርቱውን ጉልበት ከአፈር ደባልቋል\nይኽን ግፍ አስብ ዘንበል በልላት\nከአንተ በስተቀር መሄጃ የላት\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 149, 0),\n(1, 'በገና አንስተን', 'በገና አንስተን\nበገና አንስተን መሰንቆን\nእናመስግነው ስምህን\n(እንደ አንተ ጌታ ማንም የለም\nክበር ተመስገን ለዘላለም) (2)\n\nዓለም ሞኝነት ይመስለዋል\nለአንተ መንበርከክ ይከብደዋል\n(ፍቅርህን ቀምሰን ዝም አንልም\nእንዘምራለን ለዘላለም) (2)\n\nአዝ፦\nፈውስን ስትሰጠን ስትባርከን\nፍቅርህን ልከህ ስትጎበኘን\n(ጉልበት ይፀናል በአንተ ጸጋ\nማን ነው ሚከፍለው የአንተን ዋጋ) (2)\n\nአዝ፦\nስንዘምርልህ የሚስቁ\nብዙ ሜልኮሎች ዛሬም አሉ\n(ከኛ የሆነ ምንም የለም\nአምላክ ስለአንተ ዝም አንልም) (2)\n\nአዝ፦\nሞኝነት ለኔ መች ሆነና\nፊትህ ያቆመኝ ለምስጋና\n(እንድቀኝልህ ግድ የሚለኝ\nፍቅርህ ብቻ ነው የማርከኝ) (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 150, 0),\n(1, 'ምስጋናዬን', 'ምስጋናዬን\nምስጋናዬን ላምላኬ አቀርባለው\nበማደሪያው ገብቼ ሠግድለታለው\nኤልሻዳይ ነው ጌታ ሁሉን ቻይ\nይፈፀማል አምናለሁ የልቤን ጉዳይ (2)\n\nዘንባባዬን ይዤ እደህፃናቱ\nሆሣና ልበለው ሠግጄ በፈቱ\nምንም ባዶብሆን እውቀት ቢጎድለኝ\nለሥሙ ልዘምር ከልካይም የለኝ (2)\n\nአዝ፦\nአምላኬ በፈትህ ቃል አለብኝ እኔ\nቋንቋዬ መዝሙር ነው ያንተ እደመሆኔ\nባሚናዳ ደጃፍ በቅድመ ታቦቱ\nያየክብርህ ውደር ጠራኝ ማህሌቱ (2)\n\nአዝ፦\nየህይወት ትርጉሜ አንተነህ ደሥታዬ\nስምህን ማገልገል ክብሬነው ሥራዬ\nለታመነው ጌታ ምስክር የሆኑ\nከብረው ተመለሱ ለበረከት ሆኑ (2)\n\nአዝ፦\nመነሻዬ አንተነህ ጉልበቴና ክብሬ\nመድረሻዬም አንተ መደምደሚያ ቅጥሬ\nበፂሆን ተራራ ስትገለጥ ያኔ\nነጩን ልብሥ አልብሠህ አስነሳኸኝ ለቅኔ (2)\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 151, 0),\n(1, 'ሠላም ለኢትዮጵያ', 'ሠላም ለኢትዮጵያ\nሠላም ለኢትዮጵያ ሠላም ለሀገራችን (2)\nይላክልን (3) ቸሩ አምላካችን\n\nለአዓማት ሁሉ ኢትዮጵያ ተስፋ ነሽ\nአይደለሽም ብዙ በቁጥር አንዲት ነሽ\nዥንጉርጉርነቱን ነብር አይቀይርም\nኢትዮጵያዊ መልኩን ለውጥ አይችልም\n\nአዝ፦\nበታላቁ መዝገብ ስምሽ የሰፈረ\nየቆየው ድንበርሽ እንደተከበረ\nያኑርሽ ፈጣሪ አንቺን ከፍ አድርጎ\nመሃልሽን ገነት ዳሩን እሳት አድርጎ\n\nአዝ፦\nአንቺ ቅድስት እናት የአቤሜሌክ ሀገር\nየጊዮን መፍሰሻ የተመረጥሽ ምድር\nክብርና ሞገስሽ ይመለስልሻል\nቀድሞ ያከበረሽ መቼ ይተውሻል\n\nአዝ፦\nከምድር ነገሥታት አንዳች አትጓጊ\nኢትዮጵያ እጆችሽን ወደ እግዚአብሔር ዘርጊ\nምግብሽን የሚሰጥ አምላክሽ ታማኝ ነው\nሠላምሽ እግዚአብሔር እግዚአብሔር ብቻ ነው\n\nሊቀ መዘምራን ዲያቆን ቴዎድሮስ ዮሴፍ\n', 'am', 153, 0),\n(1, 'የኢዮብ መልሱ', 'የኢዮብ መልሱ\nእንደምነህ ቢሉት ዘመዶች ከድተውት\nሚስቱ ትታው ሄዳ ልጆች ሞተውበት\nዓይኖቹ በምሬት እንባ አላፈሰሱ\nእግዚአብሔር ይመስገን ነበር የኢዮብ መልሱ (2)\n\nበሕይወት ገጥሞት የበረታ ፅልመት\nበአንድ ቀን ሲነጠቅ ልጆችና ንብረት\nአካሉ በቁስል ተይዞ በፀና\nኢዮብ እንዴት ቻለ ለአምላኩ ምስጋና\n\nአዝ፦\nበሰጠበት መንደር ሲቆም ለልመና\nሚስቱ ሙት ስትለው ጌታን እርገሞ እና\nየስንፍናን ነገር አይሰማም ጆሮዬ\nይክሰኛል እርሱ ይችላል ጌታዬ\n\nአዝ፦\nቅን ነገር መናገር ለአፌ ከቸገረኝ\nአምላኬ እንዳያዝን ምነው ዝም በአልኩኝ\nልሳኔ እንዳይጠራ ሞት እና መከራ\nለምስጋና ቆሜ ነገን ዛሬ ልስራ\n\nአዝ፦\nእግዚአብሔር ይመስገን ቢጎድልም ቢሞላም\nለዓይኔ ሽፋሽፍት እንቅልፍ እንኳን ባጣም\nብዙ እንደነበረው ትናንትና ደጄ\nክፉውንም ደግሞ ይቀበላል እጄ\n\nሊቀ መዘምራን ቴድሮስ ዮሴፍ\n', 'am', 154, 0),\n(1, 'አቤቱ ባክህ አሁን አድን', 'አቤቱ ባክህ አሁን አድን\nአቤቱ ባክህ አሁን አድን\nአቤቱ ባክህ አሁን አቅና\nከፀሀይ መውጫ እስከመግቢያው ድረስ\nምድር ትከደን በምስጋና\n\nየተሰበረው እንዲጠገን\nድዊው እንዲርቅ ተፈውሶ\nአንተን እንዲያመልክ በህይወቱ\nከሀጢያት ከበደል ተመልሶ\nየባዘነውን ሰበሰብከው\nየጠፋውንስ መቼ ተውከው\nበቀል የማታቅ ቅዱስ ጌታ\nአንተ ብቻነህ ያከበርከው\n\nአዝ፦\nበጎች ቢሞሉም በበረት ውስጥ\nዘጠና ዘጠኝ ቢኑሩህም\nአንዱ እንደወጣ ይቅር ብለህ\nእኔን መፈለግ ቸል አላላልክም\nለእጆቼ አንባር ለግሬ ጫማ\nላካሌ አዲስ ልብስ አለበስከኝ\nእድፌን አፅድተህ አንፅተኸኝ\nእንዳመሰግን አደረከኝ\n\nአዝ፦\nህፅን አዋቂው ያመልክሀል\nከቤቱ ነቅሎ ደጅህ መቶ\nቅኔ መወድስ ተቀኘልህ\nይህው ለስምህ ክብርን ሰቶ\nመሻቱን ባቻ ተመልክተህ\nልቡን አንፅተህ ልፈውሰው\nጅማሬው ቢሆን ፍፃሜውን\nሁሉን አንተነህ ያደረከው\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 155, 0),\n(1, 'የትንሣኤው ጌታ', 'የትንሣኤው ጌታ\nየትንሣኤው ጌታ ሊያነሳን ተነሳ (2)\nሙስና መቃብርን በኃይሉ ድል ነሳ (2)\n\nነብሱን በስልጣኑ ከስጋው የለየው\nዳግመኛም በኃይሉ ሞት ድል አረገው\nሙታንን ያድን ዘንድ በፍቃዱ የሞተው\nከሙታን ተነስቷል እነሳለው ያለው\n\nአዝ፦\nእንደ ኃያሉ ሰው እንደ ተወው ስካር\nተነሳ ክርስቶስ ድል አርጎ መቃብር\nእሱም ጠላቶቹን ከኋላ መታቸው\nየዘላለም አሳር እነሆ ሰጣቸው\n\nአዝ፦\nእንደተናገረው በአፈ ነቢያት\nከሙታን ተነሳ አምላከ አማልክት\nወዶን ከሰማያት እንደ ወረደልን\nየሙታን በኩር ሆኖ ጌታ ተነሳልን\n\nአዝ፦\nእንደተናገረው ተነስቷል ክርስቶስ\nሞትን አሰናብቶ ችንካሩን ሰበረው\nከሙታን ተነስቶ በሶስተኛው ቀን\nእስራችን ተፈታ ሰላም ሆነልን\n\nአዝ፦\nበእምነት ገሰገሰች ማልዳ ከመቃብሩ\nእውነታው ቢከብዳት ባያስተኛት ፍቅሩ\nየአምላኮን መነሳት ሰምታ ከመላእክት\nአየች ትንሳኤውን ማርያም መቅደላዊት\n\nአዝ፦\nበእውነት አምነናል መቃብሩን አይተን\nነጭ የለበሱትን መላእክቱን ሰምተን\nእግዚአብሔር ሲነሳ ጠላት ተበትኗል\nበጌታ ትንሳኤ ትንሳኤያችን ሆኗል\n', 'am', 156, 0),\n(1, 'መድሀኒት ነህ አንተ', ' መድሀኒት ነህ አንተ\nመድሀኒት ነህና በስጋ በነብስ\nእንጠራሀለን ብለን ኢየሱስ\nጥዑመ ስም ያልነው ስለጣፈጠን ነው\nከስምሁሉ በላይ ስምህ ስዮም ነው\n\nአዝ፦\nከሰማያት በላይ እንድድንበት\nተሰጠን ይሄ ስም እንድናምንበት\nማይበሉን ያቆመ ባህር የከፈለው\nየአምላካችን ስሙ የፀና ግንብ ነው\n\nአዝ፦\nለፍርድ ቢያቆሙንም በሸንጓቸው ከሰው\nእንዳታስተምሩ በኢየሱስ ስም ብለው\nአይሁድን ሳንፈራ ሰበክነው በአዋጅ\nስለተገለጠ አለሙን ሊዋጅ\n\nአዝ፦\nከሰው ይልቅ ለአምላክ ይገባል መታዘዝ\nእንዴት እንኖራለን ቅዱሱን ስም ሳንይዝ\nሞት ነው ወይስ እረሐብ ስደት ወይ መከራ\nእኛን የሚያዘገይ ስሙን እንዳንጠራ\n\nአዝ፦\nሽባውን ተርትረን እውር ያበራነው\nጎባጣን አቅንተን ድንቅ ያደረግነው\nበእሱስም ሰብከንነው በእሱስም በእሱስም ተማፅን\nአልጫውን አለም በወንጌል ያጥፈጥን\n\nአዝ፦\nየሚመጣው ቢሆን ያለውም ቢሆን\nሊያቆመን አይችልም ከእርሱ ሊለየን\nከመከራ ስጋ ከመከራ ነብስ\nስሙ ነው መዳኒት ስሙኮ ነው ፈውስ\n\nሊቀ መዘምራን ዲያቆን ቴዎድሮስ ዮሴፍ\n', 'am', 158, 0),\n(1, 'እዘምራለው ለእግዚአብሔር', 'እዘምራለው ለእግዚአብሔር\nእዘምራለሁ ለእግዚአብሔር በፍፁም ደስታ\nላዳነኝ አምላክ ላቆመኝ ከሰዎች ተርታ (2)\n\nእንዳለፈ ውሃ መከራዬን ያስረሳኝ እርሱ ነው\nበእጆቹ ደግፎ ለምስጋና ያቆመኝ በፀጋው\nመጽናናቴ እያልኩ የምጠራው ውለታው ማርኮኝ ነው\nፍቅሩ አስደነቀኝ ምህረቱ ለኔ ያደረገው\n\nሃይል በድካሜ እንዲገለጥ ይህንን አድርገሃል\nወጀቡን ገስጸህ ማዕበሉን እኔን አድነሃል\nበጠላቴ ፊት በዘይቱ ራሴን ቀብቶኛል\nወደቀ ሲሉ ጠላቶቼ ኃይሌን አድሶታል\n\nበኃጥያት ብረክስም በምህረቱ እኔን አድኖኛል\nፈጽሞ እንዳልጠፋ በመዳፉ በእጆቹ ቀርፆኛል\nተስፋ ያረኩት ምንም የለም ጌታ ካንተ በቀር\nወጥመዴን ስበር ሰንሰለቴን የኃጥያቴን ቀንበር\n\nበሁሉ ላይ አንተ ጌታ እንደሆንክ አሁን አውቄያለሁ\nኃይልህ በድካሜ ተገለጠ ሁለን አልፌያለሁ\nይሁን ያልከውን በህይወቴ ፈጸምክ በፍቅርህ\nዳግመኛ በእጅህ ተሰራሁኝ በበጎ\n', 'am', 159, 0),\n(1, 'ለስንቱ እንጀራ ሆንክ', 'ለስንቱ እንጀራ ሆንክ\nለስንቱ እንጀራ ሆንክ ለስንቱ መጠጥ (2)\nኢየሱስ ስምህ ሲጣፍጥ\n\nየበላነው በለስ ገድሎን ሰለነበር\nየሕይወት እንጀራን ስንናፍቅ ነበር\nከሰማያት ወርደህ ታርደህ የበላንህ\nኢየሱስ ክርስቶስ ይጣፍጣል ስምህ\n\nአዝ፦\nየሕይወት ውሃ ምንጭ ከሆድህ ይፈልቃል\nሰማርያ ወርዶ ውሃ ማን ይቀዳል\nበልብ እየፈሰስክ ነፍስ የምታረካ\nቅዳልን ኢየሱስ ጔዳችንን እንካ\n\nአዝ፦\nከያዕቆብ ጉድጔድ ለዘመናት ጠጣን\nአመታት አለፉ እጅግ እየጠማን\nአይደለም ለእንስራ ለልብ የምትደርስ\nየወይኑ ዘለላ በነፍሳችን ፍሰስ\n\nአዝ፦\nበሲና የነበርክ የጉዟችን አለት\nበረሃው ቀዝቅዞ ረክተን አለፍንበት\nከጥልቅ እንደሚፈልቅ ከአለቱ ላይ ጠጣን\nስምህ እርካታ ነው ከእንግዲህ ላይጠማን\n\nአዝ፦\nሳምሪት ታመኝበት መቅጃ አትጠይቂው\nጉድጔዱም ጥልቅ ነው ብለሽ አትንገሪው\nየሕይወትሽ ውሃ መፍሰሻ ነው እርሱ\nለልብ የሚቀዳ እርሱ ነው ንጉሱ\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 160, 0),\n(1, 'ያለነው እንጸናለን', 'ያለነው እንጸናለን\nያለነው እንጸናለን /የሔዱት ይመጣሉ/ (2)\nከበረቱ ውጪ /ብዙ በጎች አሉ/ (2)\n\nቸርነቱን ቀምሰን ምህረቱን አይተናል\nባርነት ሽሮ ልጆቼ ብሎናል\nከዚህ ፍቅር ጌታ ወዴት እንሄዳለን\nግራ ቀኝ አንልም በቤቱ እንፀናለን\n\nአዝ፦\nጠላት እንደ ስንዴ ሊያበጥረን ቢዘምት\nእንሻገራለን ፈተናውን በእምነት\nኃይሉን ያለበሰን ኃይለኛውን አስሮ\nባውሎና በወጀብ ከኛጋር ነው አብሮ\n\nአዝ፦\nመንጋውን ሊያበዛ መራራ የጠጣው\nለጠፉት በጎች ነው ኢየሱስ የመጣው\nበረቱ እንዲሞላ በፍቅር ይጣራል\nጆሮ ያለው ይሽማ ወዴት ናችሁ ይላል\n\nአዝ፦\nኮብልሎ የሄደው ታናሽህ ሲመለስ\nመላእክትን ምሰል ታላቅ ይበልህ ደስ\nይታረድ ፍሪዳው አታጥቁር ፊትህን\nባክኖ እንኮን ቢመጣ ሳመው ወንድምህን\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 161, 0),\n(1, 'ጥቂት ነገር ይዤ', 'ጥቂት ነገር ይዤ\nጥቂት ነገር ይዤ ታላቁን እግዚአብሔር\nሳልጠራው አልውልም\nማን እንደ እርሱ ፍቅር ማን እንደ እርሱ ሠላም\nማን እንደ እርሱ ፍቅር ማን እንደ እርሱ ሠላም (2)\n\nደጋግሜ በሐጢዓት በበደል ብወድቅም\nእኔን ምሮ ምሮ ሠለቸኝ አያውቅም\nዕድል ይሠጠኛል አዲስ እያደረገ\nበፍቅር ድምጾቹ ሁሌ እየፈለገ\n\nአዝ፦\nየዓለም ሐብታት ሁሉ በአንድ ቢደመሩ\nበእውነት አይበልጡም ከጠብታ ፍቅሩ\nበእርሱ ደሥ ይለኛል በለስ ባታፈራ\nጉድለቴ ይሞላል የእርሱን ሥም ስጠራ\n\nአዝ፦\nባለ ጠግነትን እየከለከለ\nየሚያስፈልገኝን ለእኔ እያበቀለ\nይንከባከበኛል ሥለ እኔ ይዋጋል\nልጁን እያሠበ ይመሻል ይነጋል\n\nአዝ፦\nሢሰጥም ሢነሳ ትክክል ነውና\nዝም ልል አልችልም እሠዋለሁ ምሥጋና\nበክብሩ ዙፋን ፊት በዕምነት ቀርቤ\nዘንበል ብሎልኝ ተጠግኗል ልቤ\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 162, 0),\n(1, 'አዜምን የድሉን ዜማ', 'አዜምን የድሉን ዜማ\nአዜምን የድሉን ዜማ ነፍሳችን\nበክብር ቆማ በሰላም አለን\nበእርጋታ ሕይወትን በሰጠን ጌታ (2)\n\nየሞቱ መውጊያ ተሰብሮ\nጨለማ መርገም ተሽሮ\nያ ዘመን በጭንቅ ያቆየን\nአለፈ ጌታ ስላየን\n\nአዝ፦\nእንዲሁ ወዶን ንጉሱ\nጨው ሆኖን ጣፈጥን በርሱ\nሳይጎድል ከላይ ወረደ\nሊያድነን ስለፈቀደ\n\nአዝ፦\nየሁሉ መዳኃኒት ጌታ\nነውና ባለውለታ\nይድረሰው ምስጋና አምልኮ\nገዝቶናል በፍቅሩ ማርኮ\n\nአዝ፦\nባለ ድልሆንን በሰልፉ\nጠብቆን ጌታ ከቅፉ\nኃይል ሆኖ ኃይል ያለበሰን\nክርስቶስ ይክበር ይመስገን\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 163, 0),\n(1, 'ንገረኝ አባቴ', 'ንገረኝ አባቴ\nንገረኝ አባቴ የእምነቴን ሚስጥር\nየቀደመችውን የተዋህዶን ነገር\nእንዳድግ በጥበብ አስተምረኝ ቃሉን\nቅዱሳት መፅህፍት የመዘገቡትን\n\nየማታየውና የማይታየውን\nበባህር ውስጥ እና በየብሱጥ ያለውን\nሰማይና ምድርን በቃሉ የፈጠረ\nባንድነት ሦስትነት ስሙ የከበረ\n\nእግዚአብሔር አለ በአለሙ ሑሉ\nእኛን ያበጃጀ በአርያው በሐምሳሉ\n\nአዝ፦\nበኸለኛው ዘመን ስለ ሰው ልጅ ፍቅር\nእኛን ከፍ ያረገ ወርዶ ከመቃብር\nየተሰደደውን ሊመልስ ካገሩ\nነቢያት በትንቢት እንደመሰከሩ\n\nየአብ ቃሉ ክንዱ አልፋና ኦሜጋ\nወልድ ተዉደ ከማርያም በስጋ\n\nአዝ፦\nበስቅለት በሞቱ የሰውን ልጅ ዋጀ\nበትንሳኤው ብርሐን ሰላምን አወጀ\nሲኦል ተበርብሮ ገነት ተከፈተ\nመልአክት ዘመሩ አዳም ተደሰተ\n\nምርኮን ሁሉ ማርኮ አረገ በክብር\nዳግመኛም ይመጣል ሊወስደን ከርሱጋር\n\nአዝ፦\nንፅህት እና ቅዱስት በነብስም በስጋ\nየመለኮት ሐገር የተሞላች ፀጋ\nአንድናት አለችን አዲሲቶ ሔዋን\nልጆ በመስቀል ላይ በክብር የሰጠን\n\nየሰለጠነነው ስሞ በእግዚአብሔር\nምሳሌ የሌላት በሰማይ ምድር\n\nአዝ፦\nፅድቃን ሰማእታት ቅዱሳን መላእክት\nወንጌልን የዘሩ እንዲሁም ሐዋርያት\nበገባላቸው ቃል በምህረት ኪዳን\nእንማፀናለን ጥሪኝ ውሐን ሰተን\n\nየማስታረቅን ቃል ከአምላክ ተቀብለው\nእኛን ያግዘናል ምልጃ ፀሎታቸው\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 164, 0),\n(1, 'እጅግ ደስተኛነኝ', 'እጅግ ደስተኛነኝ\nእጅግ ደስተኛነኝ ጌታዬ ሆይ አንተ ስላለከኝ (2)\nስምክን እጠራሐው ሲጨንቀኝ ሲከፋኝ\nእፅናናለው ባንተ ሲጨንቀኝ ሲከፋኝ\n\nአዝ፦\nከህይወታ ዙሪያ ይገፋል ሀዘኔ\nደሰታን የምትተክል ስላለህ ከጎኔ\nበማሳዬም አንዳች ባይኖረኝም ከቶ\nአሳየኝ አምላኬ ጎተራዬን ሞልቶ (2)\n\nአዝ፦\nእርሱ ነው ኔታዬ ፀጋን ያለበሰኝ\nየወዜን እንጀራ ቀድሴ የሰጠኝ\nበረሀውን ምድር አለምልሞ ያድራል\nእረኛዬ ለኔ ብዙ ታምር ሰርቷል (2)\n\nአዝ፦\nያማረ ቀንበሬ የቀለለ ሸክም\nተግቶ የሚጠብቅ ባርያውን ሳይደክም\nጨለማን አሳዶ ሞላኝ በብርሃን\nሳይፀየፍ ገብቶ ከቆሸሸው ድንኮን (2)\n\nአዝ፦\nባረከኝ አምላኬ የከንፈሬን ፍሬ\nያስጨነቀኝንም አለፍኩኝ ሰብሬ\nወደደኝ እስከሞት ነፍሱን ለኔ ጥሎ\nአቀኖው መንገዳን እንቅፋታን ነቅሎ\n', 'am', 165, 0),\n(1, 'ሰብስበን እግዚአብሔር', 'ሰብስበን እግዚአብሔር\nሰብስበን እግዚአብሔር ዳግም ለምሥጋና\nየተዘጋብንን ክፈትልን እና\n\nሲኦል ተበትነን ገነት ሰበሰብከን\nባንድያ ልጅህ ሞት ህያው አደረከን\nከዚህ ሲነፅፀር አየሆነ ያለው\nቻይ ለሆነው ስምክ በጅጉ ቀላል ነው\n\nአዝ፦\nከትልቁ ችግር ያሻገርከን አምላክ\nዛሬም ለከበበን ቃልህን ብቻ ላክ\nቅርንጫፎችህን ከመቆረጥ ታደግ\nአንጠረጥርህም ትችላለህ ማረግ\n\nአዝ፦\nቤታችንን ዘግተን አለን በሰቀቀን\nበደጅህ በህብረት መቀመጥ ናፈቀን\nስለቸርነትህ ይነሳ ቅጣቱ\nበቃ በለን እና ይንጋልን ለሊቱ\n\nአዝ፦\nስጋችን ተቀምጦ ልባችን ሸፍቷል\nየሚገስፅ ቃልህ ልባችን ላይ ቀርቷል\nሳታጎል አጉድለን መቅደስህ ተዘጋ\nማረን አንተው ማረን አልፋና ኦሜጋ\n\nአዝ፦\nየፀና ግንብ ነው ስምህ መጠለያ\nየጥልቁን አሰራር ጠላትንም መውጊያ\nስለቅዱስ ስምህ ይለፍ ይህ ፈተና\nሰብስበን በቅፍህ በፉጨት ጥራና\n\nሊቀ መዘምራን ዲያቆን ቴዎድሮስ ዮሴፍ\n', 'am', 166, 0),\n(1, 'እኛ እንዘምራለን', 'እኛ እንዘምራለን\nእኛ እዘምራለን ጠላት ይጨነቃል\nየደስታቸው ምንጩ ከወዴት ነው ይላል\nየሰላም መፍሰሻ አንቺ ነሽ ደስታችን የመስቀል ሥር ሰነድ ማርያም እናታችን\n\nአዝ፦\nበልባችን ደስታ ፊታችን የበራው\nስለት ሰንሰለቱን ልጅሽ ሰብሮልን ነው\nሞት መሻገርያችን ድልድይ ከመከራው\nየምስራቅ ልጅ ፀሐይ የኛ ትንሣኤ ነው\n\nአዝ፦\nየመዳኒት መዝገብ የቁስላችን ጤና\nከርስቱ እንዳንጎድል በተስፋ እንድንፀና\nልጇን ደስታ ለሚል የደስታ ምንጭ ሆና\nኃዘን በሷ እርቋል ስላዘኑት አዝና\n\nአዝ፦\nየሊቀ ካህናቱ የክርስቶስ እናት\nእሱ ዝናብ ሲሆን እሷ ደመና ናት\nሲጠብቅ እረኛ ሲርበን በግ ያልነው\nአልፋና ኦሜጋ የድንግል ልጇ ነው\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 167, 0),\n(1, 'አትለፍ የተዋህዶን ድንበር', 'አትለፍ የተዋህዶን ድንበር\nአባቶችን ጠይቅ ይነግሩሀል\nየእምነትን ምስጢር ያስረዱሀል\nአትለፍ የተዋህዶን ድንበር\nበውጪ ተጥለህ እንዳትቀር\n\nየአብና የወልድ የመንፈስቅዱስ\nሶስትነቱን አምነን ፍፁም አንድነቱን\nቅዱሳት መፃህፍት እንደመሰከሩ\nየስላሴ አኗኗር ድንቅ ነው ምስጢሩ\nአትለፍ የተዋህዶን ድንበር\nበውጪ ተጥለህ እንዳትቀር\n\nየአምላኬን ሰው መሆን የስጋዌን ነገር\nየአለሙን ድህነት ተዋህዶ ትመስክር\nያለ መደባለቅ ያለ መቀላቀል\nስጋን መዋሀዱ ከማርያም ድንግል\nአትለፍ የተዋህዶን ድንበር\nበውጪ ተጥለህ እንዳትቀር\n\nየመቅደሷ ስርአት በውስጧ የሚታየው\nየተዋህዶ ነገር ምንጩ ከሰማይ ነው\nትርጉሙን ተረዱ ምስጢሩን ጠይቁ\nበኑፋቄ ገመድ እንዳትታነቁ\nአትለፍ የተዋህዶን ድንበር\nበውጪ ተጥለህ እንዳትቀር\n\nበፀበል በመስቀል በእምነት ሲታበሱ\nበውስጧ ይገኛል የእግዚአብሄር ፈውሱ\nየአለመጠራጠር በእምነት ቅረቡ\nየመለኮት ስራ ብዙ ነው ጥበቡ\nአትለፍ የተዋህዶን ድንበር\nበውጪ ተጥለህ እንዳትቀር\n\nአለሙን ሊያሳልፍ ይመጣል ዳግመኛ\nበፍርዱ ወንበር ፊት እንቆማለን እኛ\nበመለኮት ስልጣን በክብር ይገለፃል\nአማላጅ አይደለም ኢየሱስ ይፈርዳል\nአትለፍ የተዋህዶን ድንበር\nበውጪ ተጥለህ እንዳትቀር\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 168, 0),\n(1, 'ለጣኦት አንሰግድም ብለው', 'ለጣኦት አንሰግድም ብለው\nለጣዖት አንሰግድም ብለው\nሶስቱ ህፃናት እምቢ አሉ\nየምናመልከው አምላክ\nከእሣት ያወጣል እያሉ\n\nበንጉሱ ቁጣ ልባቸው ሳይርድ\nአንዳችም ሣይፈሩ በእሣቱ መንደድ\nበእምነት በርትተው መከራን ታገሱ\nየታመኑት ጌታ ፈረደ ለነሱ\n\nአዝ፦\nበመካከል ታየ ከእነሱ ጋር\nመላኩ ገብርኤል ታዞ ከእግዚአብሔር\nበእሳቱ መካከል ምስጋናን ጀመሩ\nስቡህኒ ብለው ለስሙ ዘመሩ\n\nአዝ፦\nየእሳቱን ነበልባል ውሀ እያደረገ\nየእግዚአብሔር መላክ ነብሳቱን ታደገ\nአንዳች ሳይነኩ ከእሳቱ ወጡ\nየእግዚአብሔርን ክብር ለዓለም ገለጡ\n\nአዝ፦\nተመላልሰው ታዩ በእሳቱ መሀል\nከራሳቸው ፀጉር አንዲቶአ ሳትጎል\nየከለዳውያን የእሳት ምድጃቸው\nህፃናቱን ትቶ እነሱን በላቸው\n\nሊቀ መዘምር ቴድሮስ ዮሴፍ\n', 'am', 169, 0),\n(1, 'ማስተዋል ስጥልን', 'ማስተዋል ስጥልን\nማስተዋል ስጥልን አይምሮን ስጥልን\nአከበርንህ ብለው ለጣሉት ክብርህን\n\nአለቱን ፈልፍላ መቅደስ ለተከለች\nሥጋው እና ደሙን ለሕይወት የሰጠች\nበ አምስቱ አዕማድ የጸናችው ቆማ\nየነፍስ እረፍት ነች ያለች አስቀድማ\n\nያላቸው ከሚመስል የአምልኮ መልክ\nሃይልህን ለካዱት ሀሰት በመስበክ\nየሰራሃት ቅፅርህ በፅኑ መሠረት\nከመንጋው ተለዩ በኑፋቄ ትምህርት\n\nማርያም ማርያም ብትል በሠርክ በማለዳ\nሰለሰጠችን ነው መድሃኒትን ወልዳ\nነገረ ቅዱሳን ቢሰበክ በአዋጅ\nመች ጋረዱን እና ገለጡልን እንጂ\n\nከሦስት ሺህ ዘመን ቀድማ ለታነጸች\nአምላክ ወልደ አምላክ መሆኑን ላመነች\nአይሆንም ኢየሱስ እንግዳ ዜናዋ\nእርሱ ነው ያስገኛት እርሱ ነው ሰሪዋ\n\nየሥጋን ነው እንጂ የነፍስን ሳያዩ\nየጸጋው ግምጃ ቤት እርቀው ተለዩ\nሃይማኖት እያለኝ ምግባር ለጎደለኝ\nለእኔም ማስተዋሉን አይምሮን ስጠኝ\n', 'am', 170, 0),\n(1, 'ለምጠራኝ ላንተ', 'ለምጠራኝ ላንተ\nለምጠራኝ ላንተ እንቢ እንዳልል እኔ\nማስተዋል አድለኝ በሂወት ዘመኔ\nመክረህ አስተምረህ ፍቅር የገለፅክልኝ\nየሰማውትን ቃል ለሂወት አርግልኝ\n\nለምጠራኝ ላንተ ሀጥያቴን በሙሉ\nባንተፊት ጥያለው\nለምጠራኝ ላንተ በደሌን ክፍቴን\nእኔ እናዘዛለው\nለምጠራኝ ላንተ የማዘነጋኝ ነህ\nበዘመኔ ሁሉ\nለምጠራኝ ላንተ ማረኝ ይቅር በለኝ\nይብቃኝ መበደሉ\n\nአዝ፦\nለምጠራኝ ላንተ ካፍህ የወጣው\nቃል ያረሰርሰኛል\nለምጠራኝ ላንተ ህግህን አድምጬ\nየሂወት ሆኖልኛል\nለምጠራኝ ላንተ እንዳአንበሳ አድብቷል\nያክፉ ጠላቴ\nለምጠራኝ ላንተ ከልቤ እንዳይነቅለው\nጠብቀኝ አባቴ\n\nአዝ፦\nለምጠራኝ ላንተ ወጀብ ቢያልብኝ\nቢከብደኝ ፈተና\nለምጠራኝ ላንተ አምላኬ ያንተ ምክር\nትፀናለች እና\nለምጠራኝ ላንተ ጌታውን የጠበቀ\nይከብራል ብለሀል\nለምጠራኝ ላንተ ነቅ የሌለው እምነት\nበልቤ ተክለሀል\n\nአዝ፦\nለምጠራኝ ላንተ ድምፅህን ሰምቼ\nልቤ እንዳይከብድብኝ\nለምጠራኝ ላንተ ያስተማርከኝ ሁሉ\nፍርድ እንዳይሆንብኝ\nለምጠራኝ ላንተ በሰጠኸኝ ፀጋ\nእጠነቀቃለው\nለምጠራኝ ላንተ ከቶ እንዳትወስድብኝ\nበንባ ደምድሚያለው\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 171, 0),\n(1, 'ለንግስናው ዙፋን', 'ለንግስናው ዙፋን\nለንግስናው ዙፋን መስቀል የመረጠው\nበትረ መንግስት እና የወርቅ ካባ የለው\nእርቃኑን ተሰቅሎ ተጠማው እያለ\nየናዝሪቱ ኢየሱስ እዳዬን ከፈለ (2)\n\nየእሾህ አክሊሉን ዘውድ አድርጎ በራሱ\nእጆቹን ዘርግቶ ሲጣራ ንጉሡ\nማንስ አስተዋለው ከትውልዱ መሃል\nአምላክ እንደሆነ የዋለው በመስቀል\n\nአዝ፦\nምድርን በአበባ የሚያስጌጥ በውበት\nበረከት የሚያድል ለፈጠረው ፍጥረት\nሐሞት እና ከርቤ ቢያቀርቡ ለጥሙ\nመራራው ጣፈጠ ተፈወሰ አለሙ\n\nአዝ፦\nበሸላቾች ፊት ዝም እንደሚል ጠቦት\nአፉን አልከፈተም አልዛተም ስገርፉት\nከዓመፀኞች ጋር እየተቆጠረ\nከቅዱሳኑ ጋር የኛን ስም ደመረ\n\nአዝ፦\nስቃትት ሲጨነቅ ተራቁቶ ብናየው\nደካማ እንዳይመስለን የጌቶች ጌታ ነው\nዛሬም በምስጋ ብርሃንን ለብሶ\nበፍርድ ወንድበር አለ በሰማያት ነግሶ\n\nሊቀ መዘምራን ዲያቆን ቴዎድሮስ ዮሴፍ\n', 'am', 172, 0),\n(1, 'ሰዎች ፈረዱብኝ', 'ሰዎች ፈረዱብኝ\nሰዎች ፈረዱብኝ\nአንተ ግን አዳንከኝ (2)\nአምላኬ ሆይ ተመስገንልኝ\nጌታዬ ሆይ ተመስገንልኝ\nሌላ ምን ቃል አለኝ\n\nሊያልፉኝ አልወደዱም ነውሬን ሊሰውሩ\nሰዎች ፈጠኑብኝ በደሌን ሊያወሩ\nአንተ ግን ሰብስበህ በፍቅር ሸፈንከኝ\nበመተላለፌ አዝነህ ሳትለየኝ\nይህ ፍቅርህ ሰበረኝ አጣበቀኝ ካንተ\nደጅህ ያመጣኛል ሁሌ እየጎተተ (2)\n\nአዝ፦\nመርከሴን አውጀው ሲያነሱብኝ ድንጋይ\nሰወረኝ ተዓምርህ ልጅ ሳልሰቃይ\nወደህ ስለማርከኝ ብዙዎች ተከዙ\nይህ አይደለም ብለው የኃጢአት ደሞዙ\nካንተ በላይ ጌታ ማን ሊያውቀኝ ይችላል\nየፍቅርህን ሚዛን ማንስ ያዛባዋል (2)\n\nአዝ፦\nማዳንህ ይደንቃል ለወደኩት ልጅህ\nምህረትህ ይደፋል ሁሌ በሚዛንህ\nእንደሰው አይታይ ፍርድህም ይለያል\nለባርያህ አርነት በምህረት ፈርደሃል\nፍቅር እየዘረዘርክ መንገዴን የጠረክ\nስለልጅህ ጽድቅን በምህረት የፈረድክ (2)\n\nአዝ፦\nእኔ አልፈርድብህም በሰላም ሂድ አልከኝ\nዳግም እንዳልበድል በፍቅር እያየኸኝ\nወደፍቅርህ ህጎች ነፍሴን አፈዛለሁ\nእንዲህ ከወደድከኝ ወዴት እሄዳለሁ\nአልለይም ካንተ ከፍቅር መድረኬ\nአመልካለሁ አንተን ፊትህ ተንበርክኬ (2)\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 173, 0),\n(1, 'አትቁረጡ ተስፋ', 'አትቁረጡ ተስፋ\nአትቁረጡ ተስፋ የእግዚአብሔር ልጆቹ (2)\nከናንተ አይለዩም የፍቅር አይኖቹ (2)\nምድርና መላዋ ናት እና የእግዚአብሔር\nበሰማያት አለ በቀላይ በባህር\n\nበጥልቁ እንኳን ቢሆን ከናንተ ጋራ ነው\nወገኖቼ አትስጉ ሰልፉ የእግዚአብሔር ነው\nጌታ አይረሳም እና የእጆቹን ስራ\nይኸው በልጆቹ አይተናል ሲስራ\n\nአዝ፦\nእንደ ጠላት ቢሆን እንደሱ ጉልበት\nማነበር የሚኖር ዛሬ በሂወት\nየሚያኖር ጌታ ነው የሚገልም ጌታ\nብርቱ እሱ ብቻ ነው በሀይል የበረታ\n\nአዝ፦\nበምስጋና ትጉ ፅኑ በፀሎት\nበስሙ ታመኑ ቁሙ በእምነት\nለናንተ የምትሆን እግዚአብሔር ቀን አለው\nአትቁረጡ ተስፋ ሁሉም አላፊ ነው\n\nአዝ፦\nብትሆኑም ከ ጉርጓድ እሱ የያቹዃል\nበማዳኑ ጥላ ይጎበኛቹዃል\nገና ያበዛቹዃል ከዚህም በላይ\nሁሉ ይቻለዋል ነውና አዶናይ\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 174, 0),\n(1, 'ሰው ሰውን ተራበ', 'ሰው ሰውን ተራበ\nሰው ሰውን ተራበ የልቡን ለመንገር\nዛሬ ተናፈቀ የተተወው ፍቅር\nክፋቱን ከተወው ወንድም ወንድሙ ላይ\nየእግዚአብሄር ይቅርታ ይመጣል ከሰማይ\n\nይቅር እንድላቹ ይቅር ተባባሉ\nብሎናል ጌታችን በማያልቀው ቃሉ\nይቅርታ ጠያቂ ይቅርታ ተቀባይ\nእንድሆን አድርገኝ ጥፋትን እንዳላይ\n\nአዝ፦\nወንድሜ በድሎኝ እያለው በእንባ\nተውለት ቢለኝም ሰባት ግዜ ሰባ\nእልከኛ ሆንኩኝ ይቅርታን ፈርቼ\nበአምላኬ ምህረት መኖሬን ዘንግቼ\n\nአዝ፦\nበእጄ ስንዴ ይዤ እንክርዳድ በልቤ\nጌታዬን ለማምለክ ከደጁ ቀርቤ\nበእጄ ካለው ይልቅ ልቦናዬን አይቶ\nተመለስ ታርቀህ ና አለኝ ቃል አውጥቶ\n\nአዝ፦\nከመባዬ በላይ እኔን ይፈልጋል\nየቃየል መስዋእት ለእርሱ ምን ያደርጋል\nክርክሬን ልተው ከወንድሜ ጋራ\nመንፈስህ ያሲዘኝ ጨለማዬ ይብራ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 175, 0),\n(1, 'እንደበደሌ አልከፈልከኝም', 'እንደበደሌ አልከፈልከኝም\nእንደበደሌ አልከፈልከኝ\nፍቅር ነህና እያለፍከኝ\nምን እከፍላለሁ ላንተ የሚሆን\nታውቀው የለም ወይ ችሎታዬን\n\nአዝ፦\nሰማይ ከምድር ከፍ እንደሚል\nታረገዋለህ የኔን በደል\nእንደምትወደኝ አዉቃለሁ እኔ\nባስመርርህም እድሜ ዘመኔ\n\nአዝ፦\nከሰው ሁሉ ጋር ብትፈራረድ\nየትኛዉ ይሆን ፀድቆ የሚሔድ\nያለምን ሃጢያት ደምህ ሸፈነው\nየተፈወስኩት እኔም በእርሱ ነው\n\nአዝ፦\nዘመኔ እንደ ሳር መሆኑን አስብ\nእድሜዬ ታጥሯል በጊዜ ገደብ\nመልካም ሰርቼ እንዲያልፍ ወራቴ\nበጎውን አብዛ በሰውነቴ\n\nአዝ፦\nየልጅነቴን አታስብብኝ\nመጨረሻዬን አሳምርልኝ\nበሩን አትዝጋው ያዳራሹን\nዘይቴን ልሙላ የመቅረዙን\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 176, 0),\n(1, 'አትንኩን', 'አትንኩን\nአትንኩን ስትነኩን ቁጥራችን ይበዛል (2)\nየቅዱስ ጊዮርጊስ የጳውሎስ ልጆች ነን (2)\n\nጥቂቶች ሆነን ተነስተን ነው\nእንዲሁ ምድርን የመላነው\nልጣል ከውሃ ከእሳት\nጽኑ ነው የያዝነው እምነት\n\nአትንኩን ስትነኩን ቁጥራችን ይበዛል (2)\nየተክለሃይማኖት የጴጥሮስ ልጆች ነን (2)\n\nድሆች ስንባል ባለጸጋ\nሁሉን የያዘ ነው ከእኛ ጋ\nብርቱውን ጎልያድ የጣለ\nበወንጭፋችን ጠጠር አለ\n\nአትንኩን ስትነኩን ቁጥራችን ይበዛል\nየክርስቶስ ሰምራ የአርሴማ ልጆች ነን\n\nበሕይወት በቃል አስተማረን\nአምላካችን ነው የነገረን\nየዚህ ዓለም ጨው ተብለናል\nአልጫውንም አጣፍጠናል\n\nአትንኩን ስትነኩን ቁጥራችን ይበዛል\nየቅዱስ መርቆሬዎስ የማርቆስ ልጆች ነን\n\nእንደ ደመና የከበቡን\nየእግዚአብሔርን ቃል የነገሩን\nስላሉን ብዙ ምስክሮች\nደካሞች ሲሉን ነን ኃይለኞች\n\nአትንኩን ስትነኩን ቁጥራችን ይበዛል\nየቅዱስ ጊዮርጊስ የጳውሎስ ልጆች ነን\nየተክለሃይማኖት የጴጥሮስ ልጆች ነን\n\nቤተክርቲያን እማማ\nዝናሽ በዓለም ይሰማ\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 177, 0),\n(1, 'መከራው ክርስትናዬን አጣፈጠው', 'መከራው ክርስትናዬን አጣፈጠው\nመከራው ክርስትናዬን አጣፈጠው\nስደቱ ማህተቤን አጠበቀው\nበሞት መንደር በሀዘን ውስጥ በመከራ\nአየውት እግዚአብሔርን ከኔ ጋራ\n\nክርስትያን ተብለን በክርስቶስ ስም የተጠራነው\nበጥልቁ ውስጥም በእግዚአብሔር እንድናምን ነው\nለጥቂት ግዜ ቢበረታብን ስደት ሀዘኑ\nአምላክ ግን መውጫ ያዘጋጃል በዚህ ተፅናኑ\n\nአዝ፦\nበስደት ሳለን ካፋችን ቢደርቅ የፅዮን ዜማ\nከወንዙ አጠገብ ቁጭ ብለን ሰለን ድምፁን ሳንሰማ\nበእግዚአብሔር ጊዜ ከባቢሎን ምድር እንለቃለን\nመሰንቆአችንን ከአርያም ዛፍ ላይ እናወርዳለን\n\nአዝ፦\nደካሞች ሲሉን በስሙ ያን ጊዜ እንበረታለን\nድሆች ስንባል ባለጠጎች እናደርጋለን\nበምድር ቅዱስ ህዝብ አድርጎ ለእርሱ ለየን\nጨለማው አልፎ በቸርነቱ ብርሀን አሳየን\n\nአዝ፦\nከፀጋ በላይ እንዳንፈተን ይከልለናል\nበቁስላችን ላይ የፈውስን ዘይት ያፈስልናል\nበጊዜም ቢሆን ያለ ጊዜውም በእርሱ እንፅና\nእንኳን ስደቱን ሞቱን ሊገታው ይችላልና\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 178, 0),\n(1, 'እሰይ ነጋ', 'እሰይ ነጋ\nእሰይ ነጋ እሰይ ነጋ ላመሰግንህ ነው\nአይኔን የከደንኩት አንተን አምኜ ነው (2)\n\nበበደሌ ሳትፈርድ ትጠብቀኛለህ\nከእኔ በላይ ለእኔ ታስብልኛለህ\nየማታንቀላፋው ትጉህ እረኛዬ\nብርሃኑን ያየሁት ባንተ ነው ጌታዬ\n\nአዝ፦\nቀናቶቼን ሰጠሁ ላንተው አሳልፌ\nበሰላም እተኛለሁ በክንድህ አርፌ\nተመስገን ማለትን በብርሃን ጨለማ\nታስተምረኛለህ በወፎቹ ዜማ\n\nአዝ፦\nትናንትናን ታልፎ ስላየሁ አዲስ ቀን\nከእንቅልፌ ስነቃ እላለሁ ተመስገን\nአንተ ባታነጋው የጨለመውን\nአልኖርም ነበረ ዛሬ ባልኩት ቀን\n\nአዝ፦\nሁሉም የሚሆነው እንደየ ስርዐቱ\nበአንተ ብቻ እኮ ነው መጨለም መንጋቱ\nስለ አደረክልኝ ምኔን ልክፈልህ\nተመስገን ብቻ ነው ሥላሴ ዋጋህ\n\nአዝ፦\nበብርሃን ተተካ አስፈሪው ጨለማ\nእንደኔማ ሳይሆን ምህረትህ ቀድማ\nየእኔ ያልኳት ዛሬ ነግታ የምትመሸው\nበጥበቤ አይደለም በበጎነትህ ነው\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 179, 0),\n(1, 'ለምን ጠላኸኝ ወንድሜ', 'ለምን ጠላኸኝ ወንድሜ\nለምን ጠላኸኝ ወንድሜ የአንድ አባት ልጆች እኮ ነን\nለምን ጠላኸኝ ወንድሜ የአንድ እናት ልጆች እኮ ነን\nብዙ ነዉ መንግስቱ አብረን እንወርሳለን\nሰፊ ነዉ ግዛቱ አብረን እንወርሳለን\n\nየተካፈልኩትን ንብረት አትፍቼ ብመለስ ዛሬ\nአባቴ ናፍቆኝ ብመጣ ልቤን አንገቴን ሰብሬ\nለሁላችንም ይበቃል ብዙ ነዉ የእርሱ መንግስት\nአይክፋህ እባክህ ወንድሜ ፍቅር ይበልጣል ከሀብት\n\nአዝ፦\nፊትህ በሀዘን አይጥቆር ድንጋዩን ጣለዉ ወንድሜ\nተቅበዝባዥ እንዳያደርግህ እጅህ ቆሽሾ በደሜ\nልብህን መልካም ብታደርግ የአንተም መስዋዕት ያርጋል\nጌታ ለሁሉም እኩል ነዉ መታዘዝ ንጉስ ያደርጋል\n\nአዝ፦\nብልጥ ስለሆንኩ አይደለም የተባረኩት በጌታ\nጽኑ መሻቴን አይቶ ነዉ በኩር ያደረገኝ ስመታ\nየበቀል ጦርክን ሸሽቼ በባዕድ ሀገር ብኖርም\nበልጅ በትዳር ባርኮኛል አብረን እንኑር በሰላም\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 180, 0),\n(1, 'ፈቃዴ ይህ ነው', 'ፈቃዴ ይህ ነው\nፈቃዴ ይህ ነው የሠውን ነገር ላልናገር (2)\nየእኔ ተሽፍኖ ከቆምኩኝ በክብር\nፈቃዴ ይህ ነው የሰውን ነገር ላልናገር\n\nአዝ፦\nህይወቴ በሙሉ በኃጢአት ተመልታ\nአምላኬ ከማረኝ በፍቅሩ ዝምታ\nየሰው በደል ላላይ በእውነት ምያለው\nእኔን ከታገሰኝ ፍቅር ተምሪያለው (2)\n\nአዝ፦\nባይኔ ፊት ተጋርዶ ያለውን ምሰሶ\nእያየ ካለፈኝ በምህረት ታግሶ\nየሰው ጉድፍ ላላይ በእውነት ምያለው\nእኔን ከታገሰኝ ፍቅር ተምሪያለው (2)\n\nአዝ፦\nአንተ ቀራጩ ሰው ያለህ አቀርቅረህ\nበምህረት ተመለስክ ከኔ ይልቅ ድነህ\nባንተ ላይ ስጠቁም የኔን ጸሎት ትቼ\nየመዳኑ ሰዓት አለፉ ቀኖቼ (2)\n\nአዝ፦\nተቆጥሮ የማያልቅ በደሌ ተከድኖ\nበሞትና በደም ሃጥያቴን ሸፍኖ\nሰው አርጎኝ በሰው ፊት አቁሞኝ ጌታዬ\nበማንም አልፈርድም ሀጥያተኛ ብዬ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 181, 0),\n(1, 'እኔ አንተ ቤት', 'እኔ አንተ ቤት\nእኔ አንተ ቤት እኔ አንተ ፊት\nየምቆም ሠው አይደለሁም\nግን ፍቅር ነህ ለዘለዓለም\nየሚመስልህ ማንም የለም (2)\n\nአዝ፦\nፀሎቴ ቢሆን ለወረት\nጎዶሎ ቢሆን የኔ እምነት\nባረከኝ እኔን ከሠማይ\nበደል ጥፋቴንም ሳታይ\nቀባኸኝ ጠርተኸኝ ከዱረ\nሠጠኸኝ ከፍ ያለ ወንበር\nሳይኖረኝ አንድም በጎነት\nባረከኝ በእጅህ በረከት\n\nአዝ፦\nቃልኪዳንህን አክባሪ\nታማኝ ነህ ሁሌም መሀሪ\nየማልከውንም መሀላ\nአትረሣም አትልም ችላ\nመካሪ ድንቅ መምህሬ\nላንተ ነው ዜማ መዝሙሬ\nፍቅር ነህ ከአባትም በላይ የሠማይ የምድር ሲሣይ\n\nአዝ፦\nመሻቴን ብቻ ስላየህ\nደካማ ልጅክን ጎበኘህ\nብቃቴ መቼ ሆነና\nያቆመኝ ላንተ ምስጋና\nአንኳኩ ስላልክ አንኳኳው\nጠይቁ ስላልክ ጠየኩኝ\nከፍተሃል በርህን ለኔ\nየታተምኩብህ መድህኔ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 182, 0),\n(1, 'አምላኬ ታሪኬን ለውጠው', 'አምላኬ ታሪኬን ለውጠው\nአምላኬ ታሪኬን ለውጠው (2)\nጌታዬ ታሪኬን ለውጠው (2)\nሠው አርገኝና ሠው ይግረመው (2)\n\nአዝ፦\nእስከ መቼ በበደል እስከመቼ በኃጥያት\nአስመሳይ ማንነቴ ነፍሴን እያስጨነቃት\nመሸከም ስላቃተኝ የበዛው እዳዬን\nበጽድቅ ልመላለስ ለውጠው መዓዛዬን (2)\n\nአዝ፦\nቃልህን ልኑረው በእድሜ በዘመኔ\nታስባለህ እና ከእኔ በላይ ለኔ\nየፍቅር ሰው ልሁን ደግሞም የይቅርታ\nየሚሳንህ የለም ታስችላለህ ጌታ (2)\n\nአዝ፦\nበስምህ ይዳሰስ የኃጥያት ለምፄ\nበቃልህ መዶሻ ይስተካከል ቅርፄ\nቀራጩን ለክብርህ ታንበረክካለህ\nሠው ታደርገውና ሠው ታስገርማለህ (2)\n\nአዝ፦\nፍሬ እንዳላፈራ በእሾህ መታነቄ\nአጥብቀህ ስጠራኝ አብዝቼ መራቄ\nበቃህ በለኝ ጌታ ልቤን አነሳሳው\nበመንፈስህ ቃኘኝ ኃጥያቴን ድል ልንሳው (2)\n\nአዝ፦\nየኋላዬን ትቼ ወደፌት ልዘርጋ\nዋጋ እንዳላሳጠው የደምህን ዋጋ\nእንዳሸንፍ እርዳኝ ስምህን ታጥቄ\nዳግም ባሪያ እንዳልሆን ልጅነትን ንቄ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 183, 0),\n(1, 'ጌታዬ ሆነ', 'ጌታዬ ሆነ\nጌታዬ ሆነ ደም ግባት አልባ\nጀርባዉ በጅራፍ ስለኔ ደማ\nየኔን መገርፍ እርሱ ተገርፎ\nክብር አለበሰኝ እርሱ ተገፎ (2)\n\nአዝ፦\nበሀሰት ሸንጎ ወጥመድ ተጠምዶ፣\nጌታ ተያዘ ህይወቴን ፈቅዶ\nክፉዎች ቢያዩት እንደ ወንበዴ\nለኔ ግን ሆኗል መዉጫ መንገዴ (2)\nታስረኃል ስለኔ ኢየሱስ መድኅኔ (2)\n\nአዝ፦\nሲዘብቱበት ምራቅ ሲተፉ\nየማይደፈር ደፍረው ሲዘልፉ\nበከበቡት ፊት ቃል ከለከለ\nእኔ እንድናገር እርሱ ዝም አለ (2)\nታርደኃል ስለኔ ኢየሱስ መድኅኔ (2)\n\nአዝ፦\nህይወት መንጭቷል ተወግቶ ጎኑን\nለከሳሾቹ ተርፏል ማዳኑ\nእጅ እግሩን ምስማር ሲቸነክረዉ\nየሞትን እሾህ ከኔ ነቀለዉ (2)\nተወጋ ስለኔ ኢየሱስ መድኃኔ (2)\n\nአዝ፦\nእርቃኑን ሆኖ ፈተለዉ ልብሴን\nአንዲሁ ወዶኝ ጠጣ ቆምጣጤ\nበምህረቱ ጥል ነብሴን አርክቶ\nአለመለመኝ አርሱ ተጠምቶ (2)\nተጠማ ስለኔ ኢየሱስ መድኃኔ (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 184, 0),\n(1, 'የሉም ከሳሾቼ', 'የሉም ከሳሾቼ\nየሉም ከሳሾቼ እነሱም ተከሰው (2)\nገመናዬን ሸፋኝ ከቶ እንዳንተ ማን ነው (2)\nአዝ፦\nገና ሳልፈፅመው ኃጥያቴን ለሚያውቀው\nይነግሩት ጀመረ እንዳላዋቂ ሰው\nወድቀው ተማፀኑት በሞት እንድመታ\nመስሏቸው ሞኝነት የፍቅሩ ዝምታ (2)\n\nአዝ፦\nእያለ ተጋድሞ ምሰሶው በአይናቸው\nየኔን ጉድፍ ማየት እንዴት ተቻላቸው\nበፈረዱበት ፍርድ እነሱም ወደቁ\nበኔ ላይ በመፍረድ ከቶ መች ፀደቁ (2)\n\nአዝ፦\nበሰፈረው መጠን ከሳሽ ይሰፈራል\nከቁጣው እሳት ፊት መች ማምለጥ ይቻላል\nየሁላችን ዋጋ በእጁ ላይ እያለን\nበመንግስቱ ስልጣን ማን ፈራጅ አረገን (2)\n\nአዝ፦\nመዝገቡ በእጁ ነው አይመረመርም\nሐጥያቴን እንዲያውቀው ነጋሪ አይፈልግም\nከሳሾቼ እመኑ ጌታዬ ምሮኛል\nእግዚአብሔር ሰው ነግሮት መቼ ፈርዶ ያውቃል (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 185, 0),\n(1, 'እጠበኝ ቆሽሻለሁ', 'እጠበኝ ቆሽሻለሁ\nእጠበኝ ቆሽሻለሁ አምላኬ በድያለሁ\nያለ እናት ያሳደከኝ ያለ አባት የጠበከኝ\nያን ሁሉ ዛሬ ረሳሁ እጠበኝ ቆሽሻለሁ (2)\n\nአዝ፦\nከድንኳንህ ስታስገባኝ ሞገስ ሰጥተህ\nየአፍኒንን ምግባር ይዤ አስቀየምኩህ\nቅብዓ ሜሮን ያተምክበት ልጅነቴ\nእንዳይጎድፍ ጠብቅልኝ ቸር አባቴ\n\nአዝ፦\nኃይል አኑረህ እንደ ሶምሶን በፀጉሬ\nጎልያድን አስጥለክኝ በጠጠሬ\nአቅም ቢያንስኝ በሥጋ ጦር ተሸንፌ\nደጅህ መጣሁ የእንባ መባ ባይኔ አቅፌ\n\nአዝ፦\nእንዳትረሳኝ በመዳፍህ ቀርፀኸኛል\nእንዳተወኝ ያለመጠን ወደኸኛል\nባትሰነዝር ልትቀጣኝ የሞት በትር\nየትግስትህ ስሌዳ ነው የኔ ክብር\n\nአዝ፦\nከከንፈሬ ጥበብ ፅፌ ቅኔ ቢፈስ\nበመታበይ አሳዘንኩት ያንተን መንፈስ\nፍቅር ግተህ በእቅፍህ ስር ያሳደከኝ\nእባክህን በበደሌ አትቅሰፈኝ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 186, 0),\n(1, 'እንደምትወደኝ አውቃለሁ', 'እንደምትወደኝ አውቃለሁ\nእንደምትወደኝ አውቃለሁ (2)\nሁሌም ስትጠራኝ እሠማለሁ\nየቅጠል ልብስን ብለብስም\nሞቴን አትፈልግም\nኧኧኧ ሞቴን አትፈልግም\n\nአዝ፦\nከቤተልሔም ጎልጎታ\nእስከ ቀራንዮ ኮረብታ\nእየተከተልክ ፈለከኝ\nከኃጥያት ቁስሌ ፈወስከኝ\nሞቴን አትፈልግም\n\nአዝ፦\nእረሳው ጌታ ሕግህን\nቀጥፌ በላው በለስን\nከገነት ቤቴ ተሰደድኩኝ\nከፍቅር እጅህ ተለየሁኝ\nእንደምትወደኝ አውቃለሁ\n\nአዝ፦\nተብለህልኝ ወንጀለኛ\nቆመህልኛል ከሃሰት ዳኛ\nአንተ ስትሞት ተሰቅለህ\nክብርን ጠገብኩኝ ከእጅህ\nእንደምትወደኝ አውቃለሁ\n\nአዝ፦\nአሁን የለብኝ ወቀሳ\nከፍለህልኛል ለኔ ካሳ\nመልሰኸኛል ወደ ቤቴ\nአክብረኸኛል ደጉ አባቴ\nእንደምትወደኝ አውቃለሁ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 187, 0),\n(1, 'መርከቧን የሚያውክ', 'መርከቧን የሚያውክ\nመርከቧን የሚያውክ ነፋስ መቷል\nአድኅነን ጌታ ሆይ ተጨንቀናል\nአድኅነን ክርስቶስ ተማጽነናል\n\nአዝ፦\nአንድ እግዚአብሔር ጥላ ተሰብስበው ሳሉ\nበቀለም በጎሳ ይከፋፈላሉ\nእጅግ ተናውጣለች ታንኳችን ተገፍታ\nአውጅልን ደርሰህ ታላቁን ፀጥታ (2)\n\nአዝ፦\nየጥፋት እርኩሰት በመርከቧ ነግሶ\nእረኛ ነኝ ይላል ተክሏው ለምድ ለብሶ\nቤተሰቤ ሁሉ ተጨንቋል በነፍሱ\nሞገዱን ገስጸው ፀጥ ይበል ነፋሱ (2)\n\nአዝ፦\nእኔ እበልጥ እኔ እበልጥ መባባሉ በዝቷል\nየትህትና መጉደል መርከቧን አውኳል\nስንጠፋ አይገድህም ብለን ስንጣራ\nአንተ ግን አንተ ነህ ዛሬም ለኛ እራራ (2)\n\nአዝ፦\nበቁጥር የበዙ ታንኳዎች እያሉ\nአንተ ባለህበት አይሏል መዕበሉ\nዘንበል በልልን ጌታ ዝም አትበለን\nበእምነት ከመዛል ከመስጠም አድህነን (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 188, 0),\n(1, 'አትንገሩት ያውቀኛል', 'አትንገሩት ያውቀኛል\nአትንገሩት ያውቀኛል (4)\nስራዬ በፊቱ መቼ ተሰውሯል\nአትንገሩት ያውቀኛል\n\nአዝ፦\nፊልጶስ ሳይጠራኝ ገና ሳልቆም ፊቱ\nከበለስ ስር ሳለው ያውቀኛል ከጥንቱ\nመካሪ አያሻውም ሁሉን ያውቃልና\nከሳሽ ሆይ ተመለስ ድንጋዩን ጣልና\n\nአዝ፦\nታናሹ ተቀባ ታላቆቹ ሳሉ\nለምን እንዲህ ሆነ ስህተት ነው አትበሉ\nለክብር የጠራኝ ከባህር ዳር ቆሞ\nሶስቴ እንደምክደው ያውቃል አስቀድሞ\n\nአዝ፦\nሀጢያተኟነቱን ሳያውቅ ገባ ቤቱ\nብላችሁ አትሙት በዝቶ ነው ምህረቱ\nየአባቴን ንብረት ባባክን ፈጽሜ\nእንዴት ልጅ ይሆናል አትበል ወንድሜ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 189, 0),\n(1, 'እግዚአብሔርን የምትወዱ', 'እግዚአብሔርን የምትወዱ\nእግዚአብሔርን የምትወዱ\nአምላኬ ነው የምትሉ\nክፋትን ጥሉ\n\nአዝ፦\nየታተማችሁ በቅዱስ ደሙ\nየተጠራችሁ በሕያው ስሙ\nከፀብ እራቁ ሽሹ ከክፋት\nፍቅንር ልበሱ ቁሙ በእውነት\n\nአዝ፦\nበቀልን ገንዘብ የምታደርጉ\nከወንድማችሁ የምትዋጉ\nየጠራን በዚህ ስለማይከብር\nእያመለክነው አንከራከር\n\nአዝ፦\nመገፋት እንጂ የኛ ግብራችን\nእንደተማርነው ከአምላካችን\nአትታወቁ ሰውን በመክሰስ\nበእግረ ስጋ በመመላለስ\n\nአዝ፦\nማህተብ ያሰረ ከአንገቱ ላይ\nየፍቅር ሰው ነው በምድሪቱ ላይ\nመስቀልን እንጂ ሾተል አይዝም\nየሚያጣፍጥ ነው አልጫን አለም\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 190, 0),\n(1, 'መስቀል ላይ', 'መስቀል ላይ\nመስቀል ላይ ያየሁት ፍቅር (2)\nይቀሰቅሰኛል ለስሙ እንድዘምር (2)\n\nአዝ፦\nፊቱን እየፀፉት እየተንገላታ (2)\nበጦር እየወጉት ይሰጣል ይቅርታ (2)\nእነርሱ እየጠሉት እርሱ ይወዳቸዋል (2)\nአስረው ሲጎትቱት ይከተላቸዋል (2)\n\nአዝ፦\nፃድቁን ሃጥእ ነው እውነትን ሃሰት (2)\nእያሉ ሲጮሁ ይሰቀል ይሙት (2)\nእየመረመረው ፍጡር ፈጣሪን (2)\nክርስቶስን አስሮ ፈታው በርባንን (2)\n\nአዝ፦\nጀርባውን ሲገርፉት በሚያቃጥል ጅራፍ\nበምህረት ያዛቸው በይቅርታው እቅፍ (2)\nጨክነው ሲያጠጡት መራራ ሃሞት (2)\nደሙ ውሃ ፈሰሰ ጎኑን ሲወጉት (2)\n\nአዝ፦\nግምጃን አለበሱት ቀሚሱን ገፈው (2)\nበራሱም አኖሩ እሾህ ጎንጉነው (2)\nየአይሁድ ንጉስ ሆይ እያሉ ዘበቱ (2)\nለህይወት ሆናቸው የክርስቶስ ሞቱ (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 191, 0),\n(1, 'የራሴን ፀጉር', 'የራሴን ፀጉር\nየራሴን ፀጉር ቁጥሩን ያውቀዋል\nየእጁ ስራነኝ መች ይረሳኛል\nየልቤ መሻት ዛሬ ባይሞላም\nእግዚአብሔር አለ አልጨነቅም\n\nአዝ፦\nስለምግብና ስለምለብሰው\nብዙ ብጨነቅ ጥቅሙ ምንድነው\nአበባን ለምድር ምግብን ለወፎች\nየሚሰጥ አባት አለኝ ሳይሰለች\n\nአዝ፦\nየማያምኑትን ስሙን ሳያውቁ\nየሚያገኙትን ሳይጨነቁ\nስለምን ልድከም በከንቱ መሻት\nእያለ ጌታ ያዳነኝ ከሞት\n\nአዝ፦\nየክፉዎች ሰልፍ ቢሰፍር በላዬ\nዝናሩን ታጥቆ ቢዝት ገዳዬ\nበሞት ጥላ ውስጥ ብጓዝ ብሔድም\nየሚጠብቀኝ አያንቀላፋም\n\nአዝ፦\nሀሳቤን ልጣል በእረኛዬ\nበሚያሰማራኝ ቸር ጠባቂዬ\nከበረከት ምንጭ አያሳጣኝም\nበግ ስለራሱ ተጨንቆ አያውቅም\n\nአዝ፦\nመንግስቱን ልሻት ልፈልግ ፅድቁን\nስለሚሰጠኝ ጌታ ሌላውን\nስለሚጨነቅ ነገ ለራሱ\nላመስግን ዛሬ ታምኜ በእርሱ\n\nሊቀ መዘምራን ቴድሮስ ዮሴፍ\n', 'am', 192, 0),\n(1, 'ከእኔ የበረታችሁ', 'ከእኔ የበረታችሁ\nከኔ የበረታችሁ (2)\nአስቡኝ በጸሎታችሁ (2)\n\nየትናንት ትጋቴ ባይኖር ከእኔ ጋራ\nእኔን ባታዩኝም በመልካሙ ስራ\nሸክሜን ተሸክሙ አትፍረዱ በእኔ\nነገ መውደቅ አለ የቆምከው ወገኔ\n\nአዝ፦\nከበሮ የያዝሺው የሙሴ እህት ማርያም፣\nኃጢእት ያደረገው ሙሴ ቢመስልሽ\nጥቁሪቱን አጋባ ወድቋል አትበዪ ልምጥ እንዳይወጣብሽ ፍርዳን ስአምላክ ተዬ\n\nአዝ፦\nከትእዛዛቱ አትወድቅም አንዲቱ\nየህግ ትንሽ የለም እኩል ነው ቅጣቱ\nቢመስልም በፊትህ ስራዬ የከፋ\nፍርዱን ተወውና ጸልይ እንዳልጠፋ\n\nአዝ፦\nአዋቂ ነው ጌታ ሁሉን ይመዝናል\nድካምን ሳይቆጥር በፀጋው ያቆማል\nብርቱ የሆናችሁ ለደካማው ትጉ\nለፍርድ እጅን ሳይሆን ርህራሄን ዘርጉ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 193, 0),\n(1, 'ፍቅር እንደዚህ ነው', 'ፍቅር እንደዚህ ነው\nፍቅር እንደዚህ ነው\nመዳናችን በነፃ ነው\nከኛ አንዳች ሳይ ጠብቅ\nአንስቶናል ከመውደቅ\n\nእግዚአብሔር ሳንወደው ስለወደደን\nማስተሰርያ እንዲሆን ልጁን ላከልን\nአየን በይቅርታ ተወዳጅ ባንሆንም\nፍቅር እንደዚህ ነው በደልን አይቆጥርም\n\nአዝ፦\nገንዘቡ ሊያደርገን ሊያነፅን ለራሱ\nስቃይ ተቀብሏል ተጨንቋል በነብሱ\nከአመፅ ሁሉ የተቤዠን ጌታ\nእራሱ ፍቅር ነው ማይ ጠብቅ ውለታ\n\nአዝ፦\nስናዝን አብሮን ነው ስንደሰት አብሮን\nብንቆረቁረውም መቼ ይሄዳል ጥሎን\nእንደሰው አይደለም ሁሌም ይታመናል\nፍቅር እንደዚ ነው በሁሉ ይፀናል\n\nአዝ፦\nከኛ ጋር ይሆናል ስንዋደድ እኛ\nበተገደለ ጥል አንኑር ዳግመኛ\nበጉርፍ በንፋስ አይነቃነቅም\nፍቅር እግዚአብሔር ነው ዘወትር አይወድቅም\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 194, 0),\n(1, 'ሀሳብክን ልከተል', 'ሀሳብክን ልከተል\nኃጢአት እንድሰራ /አለማመደና/ (2)\nበአንተ ፊት ከሰሰኝ /ጠላቴ እንደገና/ (2)\nሃይልህን አድለኝ ልውደድህ አብዝቼ\nሃሣብክን ልከተል የእሱን ሃሣብ ትቼ (2)\n\nከመቅበዝበዝ በቀር ምን አትርፌ አውቃለው\nየሳቅኩኝ ሲመስለኝ ዘውትር አለቅሳለው\nበማስመሰል ኑሮ ያለሁኝ ሲመስለኝ\nበቃልህ ስመዘን ባንተ ዘንድ ሞት ነኝ\n\nአዝ፦\nክፉን እያሳየ መልካም አስመስሎ\nሙሉ የነበርኩት አረገኝ ጎዶሎ\nየድርሻህን ውሰድ ብሎ የመከረ\nየእሪያዎች አሰር ያስበላኝ ጀመረ\n\nአዝ፦\nከምትሳሳልኝ ከአንተ ከወዳጄ\nጠላትህ ሆኛለሁ ዓለምን ወድጄ\nምኞቴን ስከተል ከአንተ ተለየሁኝ\nፍሬም አላፈራ ቅጠል ብቻ ሆንኩኝ\n\nአዝ፦\nከቦኝ የነበረው በስልጣን በዝና\nወዳጅ የመሰለኝ ጠላቴ ሆነና\nይካሰሳት ጀመር ነፍሴን ሊናጠቃት\nአድናት ክርስቶስ ወደኸው ሞትክና\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 195, 0),\n(1, 'የማደርገውን አላውቅም', 'የማደርገውን አላውቅም\nየማደርገውን አላውቅም ይቅር በለኝ አባቴ (2)\nቸንክሬሃለሁ በበደሌ ቸንክሬሃለሁ በኃጢአቴ (2)\n\nድምፄን ከፍ አድርጌ እያልኩኝ ተዋጀሁ\nየነገዴ ቋንቋ ወገን ፈልጋለሁ\nአልታረቅ አለኝ ቃልና ተግባሬ\nኃይልህን እክዳለሁ ኃይልህን መስክሬ (2)\n\nአዝ፦\nለኃጢአት ልሞት ነው የሞትክልኝ ለኔ\nጨለማዬን የሻርክ ጌታ ብርሃኔ\nእጠበኝ ቆሸሽኩኝ ሆንኩኝ እንደ እሬያ\nዘመን ጨምርልኝ ይቅርታህን ማያ (2)\n\nአዝ፦\nህመም የሚነቅዝ መድኃኒት አግኝቼ\nየተሰሎንቄ ድምፅ ማባበል ሰምቼ\nወደፊት ስትጠራኝ ሄድኩኝ ወደኃላ\nማረፍ አቅቶኛል በምህረትህ ጥላ (2)\n\nአዝ፦\nለእኔ ያሰብካትን ሃሳብህን ትቼ\nማዕረጌ ጥያለሁ ከእቅፍህ ወጥቼ\nበመስቀልህ ስራ ካወረሰከኝ ስፍራ\nእንድኖር አግዘኝ ሁሌ ከአንተ ጋራ (2)\n\nአዝ፦\nፍቅርን ስታጎርሰኝ እጅህን ነክሼ\nለፅድቅ አንፃኸኝ በበደል ፈርሼ\nህያው ነኝ ለኃጢአት ዳግም የሰቀልኩህ\nመራራዬን አጣፍጥ ጌታየማደርገውን ተማፀንኩህ (2)\n\nአዝ፦\nወዴት ነህ ስትለኝ በማፍርበት ቦታ\nእንዳልገኝ እርዳኝ ትችላለህ ጌታ\nትልቁም ትንሹም ማንም ወደ እኔ ሲያይ\nአንተ ተንፀባረቅ በማንነቴ ላይ (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 196, 0),\n(1, 'አማኑኤል ፍቅርህ ይማርካል', 'አማኑኤል ፍቅርህ ይማርካል\nአማኑኤል/ፍቅርህ ይማርካል/ (2)\nበመስቀል ተሰቅለህ መድኃኒት ሆነሃል\nአማኑኤል ፍቅርህ ይማርካል\n\nሳታቆስል በፍቅርህ ማረክኸን\nከፊት ቀድመህ በድል አስከተልከን\nበደለኞች እኛ ሆነን ሳለ\nአንተ ከፍለህ ክሳችን ተጣለ\nኪርያላይሶን ኪርያላይሶን (2)\n\nአዝ፦\nእንደሰማን እንዲሁ አይተናል\nማዳንህን ቀምሰን መስክረናል\nየእግዚአብሔር በግ ቆስለህ የፈወስከን\nወደ ድንቁ ብርሃን ያሻገርከን\nኪርያላይሶን ኪርያላይሶን (2)\n\nአዝ፦\nአጽናንተኸን ሞትን አስተከዝከው\nወደ ጥልቁ እንዲወርድ አዘዝከው\nበአንተ ፍቅር ምርኮ በዝቶልናል\nማማ ሆነህ ከፍ ከፍ ብለናል\nኪርያላይሶን ኪርያላይሶን (2)\n\nአዝ፦\nስንሸሽህ እየተከተልከን\nልጆች አርገህ በክብር አስጌጥከን\nተቅበዝባዡን ሰብስበሃልና\nከማደሪያህ ይፈልቃል ምስጋና\nኪርያላይሶን ኪርያላሶን (2)\n\nሊቀ መዘምራን ዲያቆን ቴዎድሮስ ዮሴፍ\n', 'am', 197, 0),\n(1, 'ወልድን ፍቅር ሳበው', 'ወልድን ፍቅር ሳበው\nወልድን ፍቅር ሳበው ከሰማይ አገሩ (2)\nእርሱ ደሃ ሆነ ልጆቹ እንዲከብሩ (2)\n\nየእግዚአብሔር በግ ተገለጠ\nለዘላለም ሞት ተዋጠ\nየእሱን ለእኛ የእኛን ለእርሱ\nክብር ይሁን ለንጉሡ (2)\n\nአዝ፦\nጻድቅ ፈራጅ ድንቅ ዳኛ\nክብሩን ጥሎ ግርግም ተኛ\nሳይጎልበት ሆነ ባዶ\nበፍጹም ፍቅር እኛን ወዶ (2)\n\nአዝ፦\nሁለተኛው አዳም መጣ\nየማይጠልቀው ፀሐይ ወጣ\nየዲያብሎስ ስራ ፈርሷል\nመንጋው ሁሉ ጽድቅን ለብሷል (2)\n\nአዝ፦\nስለ ሁሉ አንዱ ሞተ\nእንድንለብስ ተራቆተ\nበከፈለው የደም ዋጋ\nአዲስ ሆንን ባለ ጸጋ (2)\n\nሊቀ መዘምራን ዲያቆን ቴዎድሮስ ዮሴፍ\n', 'am', 198, 0),\n(1, 'ተስፋ ቆርጠን ነበር', 'ተስፋ ቆርጠን ነበር\nተስፋ ቆርጠን ነበር ኤማሁስ የሄድነው\nበግፍ ስለሞተ ይቤዠናል ያልነው\nስልሳውን ምእራፍ በሓዘን ተራመድን\nየሚያቃጥል ፍቅሩን/ሞቱን እያሰብን/ (2)\n\nበመንገዳችን ላይ አንድ እንግዳ መጥቶ\nጠየቀን በብርቱ መሃላችን ገብቶ\nዓለም የሰማውን ባያውቀው ደነቀን\nእውነቱን ገለጽነው በእምነት ተናገርን\n\nአዝ፦\nበስራና በቃል ብርቱ ነብይ ነበር\nበአይሁድ ተገድሎ አደረ መቃብር\nይህ ሁሉ ከሆነ ሶስተኛ ቀን ሆነው\nበምኩራባችን ላይ መምህሩን ካጣነው\n\nአዝ፦\nዛሬ በማለዳ አዲስ ነገር ሰማን\nበመቃብር የለም ተነስታል ጌታችን\nሴቶች አስገረሙን ስጋው የለም ሲሉ\nመላእክቱም ታዩ ህያው ነው እያሉ\n\nአዝ፦\nመጻህፍትን ገልጾ በሚነግረን ነገር\nልባችን በሚስጢር ይቀልጥብን ነበር\nአይናችን ተይዞ እኛ መች አወቅነው\nቀኑ መሽታል እና በቤት እደር አልነው\n\nአዝ፦\nእንጀራውን ቆርሶ በእጃችን ሲሰጠን\nባይናችን ላይ ያለው አዚሙ ለቀቀን\nእንዳላዋቂ ሰው ከኛ ጋራ ያለው\nየትንሳኤው ጌታ ለካስ ኢየሱስ ነው (3)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 199, 0),\n(1, 'እኔስ ብዬ ነበር', 'እኔስ ብዬ ነበር\nእኔስ ብዬ ነበር ተሰጠውኝ ለሞት\nእኔስ ብዬ ነበር ተላለፍኩኝ ለሞት\nበሚጠሎኝ መሃል የሚወደኝን አገኘውት (2)\n\nወንበዴ ነበርኩኝ በጄ ደም የመላ\nስቀማ ኖርያለው አንገትን ስቀላ\nሞት ይገባኝ ነበረ እንደኔማ በደል\nገነትን ወረስኩኝ አንተ ስትሰቀል (2)\n\nአዝ፦\nአትጩህ ይሉኛል ስምህን ስጠራ\nአልፈለጉም እና አይኔ እንዲበራ\nጥሩት ስትላቸው ይጠራሃል አሉኝ\nጌታዬ ስትወደኝ ሁሉም አከበሩኝ (2)\n\nአዝ፦\nአልባስጥሮስ ይዤ የእንባዬን መባ\nስምኦን ከለከለኝ ከቤቱ እንዳልገባ\nእርሱን በይቅርታ በፍቅር እንዳየህ\nተቀበልከኝ ጌታ ሸክሜን አቅልለህ (2)\n\nአዝ፦\nቸርነት ምህረትህ በዝቷል ይቅርታህ\nለፃድቃን አይደለም ለሀጥአን መጥተህ\nከበጎች መሐል ተለይታ ወጥታ\nአንድዋ እንኳ እንዳትጠፋ ፍቃድህ ነው ጌታ (2)\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 200, 0),\n(1, 'አድነኝ አምላኬ', 'አድነኝ አምላኬ\nአድነኝ አምላኬ አድነኝ\nአድነኝ ጌታዬ አድነኝ\nአልቋል ከምድር ላይ ደግ ሰው\nእንባዬን ከአይኔ ላይ አብሰው (2)\n\nፍቅር ከሰው ልጆች ቀዝቅዞ\nትዉልዱ በበደል ተይዞ\nወዳጅ በወዳጁ ጨከነ\nወዉደዱ የሽንገላ ሆነ (2)\n\nአዝ፦\nሆኖበት ክብሩ በነውሩ\nተጣሰ የፍቅር ድንበሩ\nደርቦ የማይሞቀዉ ሆነ\nደስታዉ ከእጁ ላይ ተነነ (2)\n\nአዝ፦\nለቃልህ መታዘዝ ዘነጋ\nተክዞ መሽቶ እየነጋ\nለክፉ አሳልፎ ሰጠ\nወንድሙን በነዋይ ለወጠ (2)\n\nአዝ፦\nትንኝን ያጠራል ከሰው ላይ\nበራሱ ምሶሶዉን ሳያያይ\nይሆናል የወንድሙ ፈራጅ\nተይዞ በእግዚአብሄር እጅ (2)\n\nአዝ፦\nተሰዶ ሲኖር በባእድ\nሲገባው ሁሉም ሊዋደድ\nአንዱበአንዱ ላይ ይነሳል\nአካሉን ቀኝ እጁን ይንቃል\nወንድሙን እህቱን ይንቃል\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 201, 0),\n(1, 'ብቻዬን ነኝ ብዬ አላውቅም', 'ብቻዬን ነኝ ብዬ አላውቅም\nብቻዬን ነኝ ብዬ አላውቅም\nያመንኩትን እኔ አለቅም\nእግዚአብሔር ነው ጠባቂዬ\nመነሻዬም መድረሻዬ\n\nበማዳኑ ተቀድሼ\nስሙ ሆኗል አዳራሼ\nነብሴ ሌላ አትምረጪ\nህይወት የለም ከርሱ ውጪ\nስላጣሁኝ አይሸሸኝም\nከኔጋር ነው ሳይ ኖረኝም\nየሚያኖረኝ በመንፈሱ\nብሬም እርሱ ወርቄም እርሱ\n\nአዝ፦\nበእሳት መሐል ሲሆን ጉዞ\nውሃ ሆኖ አቀዝቅዞ\nውሃ መሃል ለወደቀ\nእሳት ሆኖ እያሞቀ\nእጄን ይዞ የሚያሻግር\nማንም የለም እንደ እግዚአብሔር (2)\n\nአዝ፦\nመነሻዬ የኔ አልፋ\nኦሜጋዬ የኔ ተስፋ\nከሞት መዳፍ እያስጣለ\nበመንገዴም አብሮኝ አለ\n\nአዝ፦\nላከበረኝ በዝማሬ\nክብርን ሰጠው በከንፈሬ\nያለወረት ለታመነው\nበዘመኔ እገዛለው\nማይቋረጥ ውዳሴ አለኝ\nከእስትንፋሴ ለቀረበኝ\nእጅን ይዞ የሚያሻግር\nማንም የለም እንደ እግዚአብሔር\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 202, 0),\n(1, 'የመልካሞች መልካም', 'የመልካሞች መልካም\nየመልካሞች መልካም ካህን ለዘላለም\nበልቤ ላይ ንገስ የናዝሬቱ ኢየሱስ\n\nሴኬምን እንዳልናፍቅ ከህግህ እንዳልወጣ\nከፀጋ እንዳልጎድል ብኩርናን እንዳላጣ\nበፍቅር ንገስብኝ በልቤ ሾሜሃለው\nተማምኜ በስምህ ወጣለው እገባለው\n\nአዝ፦\nደምህን አፍስሰሃል ስለሃጢአቴ ስርየት\nስጋህንም ቆርሰሃል ለነፍሴ አርነት\nአንተ ነህ ሊቀካህን መስዋዕቱን የሰዋህ\nመስዋዕቱንም ተቀበልክ መስዋዕትም ሆነህ\n\nአዝ፦\nበህግህ እንድፀና ለልቤ ጥበብ ሁነው\nበሰላም እንዲቀና እግሬን በብርሃን ምራው\nካንተ የተቀበልኩትን ልስጥህ በልግስና\nትከለኝ በመቅደስህ እንድኖር በትህትና\n\nአዝ፦\nከቤተልሄም ግርግም ቀራንዮ ያየውህ\nፍቅርን ያነበብኩብህ የልብ ወዳጄኮ ነህ\nበለምለም የመራኸኝ በፅድቅ ያስማረከኝ\nመልካሙ እረኛዬ ሆይ ከተኩላው የከለልከኝ\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 203, 0),\n(1, 'ኢትዮጵያ እጅሽን ዘርጊ', 'ኢትዮጵያ እጅሽን ዘርጊ\nኢትዮጵያ እጅሽን ዘርጊ ወደ አምላክ ወደ አዶናይ\nህዝብሽን ከሞት የሚያድን ይዉጣልሽ የምህረት ፀሐይ\n\nህጻናት ወላጆች አጥተው በሜዳ ሲበታተኑ\nንስሮችሽ ወጣቶች አልቀው የአፈር ሲሳይ ሲሆኑ\nየሞት መልአክ ተልኮብሽ መሬትሽ አጥታ ፀጥታ\nቁጣዉን እንዲመልሰው ለምኚ ለሰማይ ጌታ\n\nታማሚው እያጣጣረ ጤነኛው ቆሞ ሲሰጋ\nአምላክሽ ይቅር ይበልሽ ይለፍሽ ይሄ መከራ\nአበዉን ይዘሽ ተነሺ ጸሎትሽን ቆመሽ አድርሺ\nያብርደው እሳት ንዳዱን በምልጃሽ በልመናሽ\n\nልጆችሽ ቅጣት ገብቷቸው እንዲያዩ ወደ አምላካቸው\nመከራው ትምህርት ሆኗቸው ይመለስ ታካች ልባቸው\nየበደልነውን ታግሶ ቁጣውን እርሱ መልሶ\nይማረን ይቅር ይበለን ጽኑ ምህረቱን አስታውሶ\n\nአህዛብ ተነጋገሩ አምላክሽ እረሳሽ ብለው\nልጆችሽ ሞት ሲፈጃቸው እያዩ እጅግ ተገርመው\nጉልበትሽ እንዳይሰበር ምርኩዝሽ እርሱ ነውና\nደዌ ቸነፈሩን ያርቅ አቅርቢ ፅኑ ልመና\n', 'am', 204, 0),\n(1, 'በፍቅር ላዚምህ', 'በፍቅር ላዚምህ\nበፍቅር ላዚምህ ፍቅር ነህ ጌታዬ\nበደም የገዛሀኝ ባለውለታዬ\nበቃዬል ጎዳና እንዳልጓዝ እርዳኝ\nበቀናው መንፈስህ ወደፅድቅህ ምራኝ\n\nበልቤ ትከሻ በቀል ተሸክሜ\nወንድሜን ጠልቼ ካንተ ፊት መቆሜ\nፃድቅ ቢያስመስለኝ በሰዎች እይታ\nጉዴን ስለምታውቅ እስራቴን ፍታ (2)\n\nአዝ፦\nዙሪያውን ተከቦ በእሾህ ጥላቻ\nስብከቴ መዝሙሬ ሆኗል የቃል ብቻ\nማረኝና ይብቃኝ ለሀጢአት መዝመቱ\nፍቅር የሌለው ሰው ነው የከንቱ ከንቱ (2)\n\nአዝ፦\nአሸንፈህልኝ እኔ ግን ተሸነፍኩ\nበጅ የማልነካውን ለሰው እያሸከምኩ\nበቃሌ ጠርቼ በግብሬ ረገምኩህ\nባስመሳይ ማንነት እየሸነገልኩህ (2)\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 205, 0),\n(1, 'የተሰቀለውን ኢየሱስን ሳየው', 'የተሰቀለውን ኢየሱስን ሳየው\nየተሰቀለውን ኢየሱስን ሳየው\nጎኑን የተዋጋው ክርስቶስን ሳየው\nሀሞት የጠጣውን መድኃኒቴን ሳየው\nአንድ ነገር ገባኝ ይህ ሁሉ ለኔ ነው (2)\n\nየሚነጠፉለት መላእክት በፊቱ\nምስጋናው አይጎድልም በቀንም በሌሊት\nሁሉ በመዳፉ አልፋና ኦሜጋ\nመጣ ወደ ምድር እኔኑ ፈለጋ\n\nሰለእኔ ተቆጥሮ እንደተረገመ\nጤናዬን ሊመልስ ቤዛዬ ታመመ\nለዛሬ ደስታዬ ለዛሬ መቆሜ\nሕይወት ከፍሎብታል ኢየሱስ ሰላሜ\n\nበጅራፍ ግርፍት ጀርባው የታረሰው\nስጋዬን ሊያቆም ነው ደሙ የፈሰሰው\nፍቅር የሳበችው ሰለፍቅር ብሎ\nአክሊል አቀናጀኝ ምራቅ ተቀብሎ\n\nያጠፉሁት እኔ ተከሳሹ እርሱ\nብርሃን ሊያለብሰኝ ተገፈፈ ልብሱ\nወገን እንደሌለው የሆነው ባይተዋር\nእኔ ሊደምር ነው የእርሱን ከሆኑት ጋር\n\nግልጽና ስውሩን ሁሉን አዋቂ ነው\nቢዘብቱበትም አይኑን በጨርቅ አስረው\nበመንፈስ ደኸየ የባሪያን መልክ ያዘ\nማዕረጌን ሊመልስ ለመስቀል ታዘዘ\n\nአብ አንድያ ልጁን ሰጥቶኛል ሳይራራ\nወልድ ሊታደገኝ ሆኗል ከእኔ ጋራ\nበመከራም ሆኖ ጌታን ያሳሰበው\nየእርሱ ስቃይ ሳይሆን የእኔ እረፍት ነው\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 206, 0),\n(1, 'ፍቅርን ከክርስቶስ', 'ፍቅርን ከክርስቶስ\nፍቅርን ከክርስቶስ ትህትናን ከማርያም\nያልተማረ አገልጋይ አይሆንም ምሳሌ\nይውረድ ከአትሮኖስ ላይ (2)\n\nስለሚያሳድዱት በርሱ ላልጸለየ\nበምንስ ተለየ\nየሚናገረውን በተግባር ካልኖረ\nምኑን አስተማረ\n\nአዝ፦\nየሚያምነውን ጌታ በህይወት ካልገለጠ\nመቼ ተመረጠ\nእየተበደለ ካላለ ይቅርታ\nአያውቀውም ጌታ\n\nአዝ፦\nልቡ ሳይሰበር ወንጌሉን ቢዘራ\nአንዳች አያፈራ\nከኔ ይልቅ ወንድሜ ካላለ ብርቱ ነው\nድካሙ ከንቱ ነው\n\nአዝ፦\nክፉን ተጠይፎ ካልቆመ ለእውነት\nስብከቱ ነው ሐሰት\nብርሃንን ሰብኮ በጨለማ ካለ\nራሱን አታለለ\n\nአዝ፦\nእርስ በርሷ መንግስት ከተከፋፈለች\nመቼ ትጸናለች\nአባቶች ታረቁ ብኩራናን ትታችሁ\nአንድ ይሁን መንጋችሁ\n\nበጸጋው ስጦታ ራሱን ከካበ\nየጌታው ባርያው ነኝ ብሎ ካላሰበ\nአምላክን ጸንሳ ጌታን የወለደች\nለፍፁም ትህትና ማርያም ምሳሌ ነች\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 207, 0),\n(1, 'ተግተን እንጸልይ', 'ተግተን እንጸልይ\nተግተን እንጸልይ ወደ ፈተና እንዳንገባ\nበሕይወታችን በመንደራችን እግዚአብሔር ይግባ\nበአባታችን ፊት በጸሎት ወድቀን ኃይል እንታጠቅ\nበጸጋ እንድንኖር የሚቃወመን ጠላትም ይድቀቅ\n\nበጦር ሰፈር ነን ያ ጠላታችን ሌጌዎን ታጥቋል\nመሳሪያ ሳንይዝ የወጣነውን ስንቶቹን ጥሏል\nዘይት አልቆብን የመቅረዛችን መብራት ደብዝዟል\nብርሃኑን ጥለን የጠላት ምሽግ በምን ይታያል\n\nአዝ፦\nያዘነብላል ጆሮውን ወደኛ ጠላት ይመታል\nወጥመዱን ሰብሮ ያመንንበትን ያሻግረናል\nያሰማራናል በለምለሙ መስክ በተስፋ ሞልቶ\nማን አፍሮ ያውቃል የእግዚአብሔርን ስሙንስ ጠርቶ\n\nአዝ፦\nየክብር ዘይት በቆሰለው ሰው ቀድተው ቢያፈሱት\nመድኃኒት ነው ለዓለም ኹሉ ዲናር ማይከፍሉት\nየፍቅር አባት ደጁን ስንመታ ይከፍትልናል\nመሻታችንን እየፈጸመ ይባርከናል\n\nሊቀ መዘምራን ቴድሮስ ዮሴፍ\n', 'am', 208, 0),\n(1, 'ድንጋይ ጣሉ', 'ድንጋይ ጣሉ\nድንጋይ ጣሉ ሰይፍን ጣሉ\nበፍቅር ቃል ሰላም በሉ\nኢትዮጵያዊ የሚያምርበት\nይቅር ሲል ነው የሚያምርበት\n\nዘር አጥንትን የማይቆጥር\nየሚኖር ነው ሁሌም በፍቅር\nየሚሰጥ ነው የሱን ትቶ\nለወገኖቹ አድልቶ\nወሰን ድንበር ማይገድበው\nኢትዮጵያዊ ማለት ይህ ነው\n\nአዝ፦\nየሚያዝን ነው ከሚያዝነውጋር\nደስ የሚለው ደስ ካለውጋር\nእግዚአብሔር የሚፈራ\nየምህረት ሰዉ የሚራራ\nወሰን ድንበር ማይከልለው\nኢትዮጵያዊ ማለት ይህ ነው\n\nአዝ፦\nየሚያበላ ካለው ቆርሶ\nካለቀሰው አብሮ አልቅሶ\nእርሱ መልኩን አይቀይርም\nካገር በፊት ቅድሚያ አይሰጥም\nወሰን ድንበር ማያግደው\nኢትዮጵያዊ ማለት ይህ ነው\n\nአዝ፦\nየሚቀበል ሁሌ እንግዳ\nሚያመሰግን በማለዳ\nየሚያምን ነው በአንድነት\nየማይከፋው በልዩነት\nወሰን ድንበር ማይከልለው\nኢትዮጵያዊ ማለት ይህ ነው\n\nአዝ፦\nሰይፍን መዘን የለም ሠላም\nየቃየል ግብር አይጠቅመንም\nባንድ ማህፀን ይቁም ግፊያ\nበርብቃ ምድር በኢትዮጵያ\nወሰን ድንበር ማይገድበው\nኢትዮጵያዊ ማለት ይህ ነው\n\nሊቀ መዘምራን ዲያቆን ቴድሮስ ዮሴፍ\n', 'am', 209, 0),\n(1, 'እግዚአብሔር መልካም ነው', 'እግዚአብሔር መልካም ነው\nእግዚአብሔር መልካም ነው\nበመከራ ቀንም መሸሽጊያ ነው (2)\n\nከገነት ሲሰደድ አዳም አባታችን\nሞት ነግሦብን ሳለ በእኛ በሁላችን\nቃል እንደገባለት ተወልዶ ሊያድነው\nበመከራ ጊዜ መሸሸጊያ ሆነው (2)\n\nአዝ፦\nአብርሃም ከካራን ከእናት ከአባቱ ቤት\nከነዓን ሲገባ ሲሰደድ በእምነት\nከተሰጠው ተስፋ አንዳች ሳይጎድልበት\nእንደ ምድር አሸዋ ዘሩን አበዛለት (2)\n\nአዝ፦\nበሃዘን በችግር በመከራ ጊዜ\nጭንቅን የሚያርቅ ነው የነፍስን ትካዜ\nየቀድመው እባብ ሰላሜን ሲነሳኝ\nእግዚአብሔር መልካም ነው ሃዘኔን አስረሳኝ\nየቀደመው እባብ ሰላሜን ሲነሳኝ\nከርስቶስ ኢየሱስ ሀዘኔን አስረሳኝ\n\nሊቀ መዘምራን ዲያቆን ቴዎድሮስ ዮሴፍ\n', 'am', 210, 0),\n(1, 'ቀራንዮ አየሁት', 'ቀራንዮ አየሁት\nቀራንዮ አየሁት ቀራንዮ አየሁት\nየተጠማሁት ጌታን አገኘሁት\nእረፍት ሆኖልኛል ሸክሜን ተሸክሞ\nሕይወቱን በሰጠኝ የኔን ሕይወት ታሞ\n\nቁስሉ ፈውሶኝ ጌታዬ\nንጹህ ደሙ ነው ዋጋዬ\nየኔ አይደለሁም የራሴ\nለዋጀኝ አለኝ ውዳሴ\n\nአዝ፦\nልብሴ ነው ለኔ እርቃኑ\nደስታን የሰጠኝ ማዳኑ\nየኔን መሰደድ ተሰዶ\nበክብር አስጌጠኝ ተዋርዶ\n\nአዝ፦\nየተቀበለው መከራ\nየኔን ጨለማ አበራ\nእንባየን ገድቦት ደሙ\nበልቤ ሞልቷል ሰላሙ\n\nአዝ፦\nፍቅር ያደከመው ኃይለኛ\nይጠብቀኛል ሳይተኛ\nቀድሞ እየወጣ በሰልፌ\nዛሬም አለሁኝ አትርፌ\n\nአዝ፦\nበምድረ በዳ መንጭቶ\nውሃ ሆነልኝ ተጠምቶ\nስፍራ አዘጋጄ በሰማይ\nጩኸቴን ጨኸ መስቀል ላይ\n\nአዝ፦\nሰርጓጉት ሸለቆ ሞልቷል\nአጥፊውም ሳይነካኝ አልፏል\nቀራንዮ ላይ ብቃቴን\nአግኝቸዋለሁ ንጋቴን\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 211, 0),\n(1, 'ሰው ከነድካሙ ይጠቅማል', 'ሰው ከነድካሙ ይጠቅማል\nሰው ከነድካሙ ይጠቅማል\nሰው ከነድካሙ ይጠቅማል (2)\nበከበርው ደሙ በዋጋ ተግዝቷል\nበእግዚአብሔር ምህረት በፍቅር ተከቧል\nሰው ከነድካሙ ይጠቅማል\n\nሰው ከነድካሙ ይጠቅማል (2)\nበከበርው ደሙ በዋጋ ተግዝቷል\nየበረቱትን ሲያይ ቢወድቅም ይነሳል\nሰው ከነድካሙ ይጠቅማል\n\nከሰፌው አዳራሽ ከአባቱ ኮብልሎ\nከወንድሙ ጋራ ድርሻውን ተካፍሎ\nአንድ ቀን ሲመለስ ወደ ልቦናው\nመሆንን ይመኛል አገልጋይ ባሪያው\nየሀሙስ ማታውን ቃሉን እረሳና\nአላውቀውም ቢለው ዶሮ ሳይጮህ ገና\nበለቅሶ ቢማጽን መበደሉ ገብቶት\nሰማዕትም ሆነ ደረሰ እስከሞት\n\nንጉሱ ሲያጠፋ ፈርቶ ለመገሰጽ\nኢሳያስ ወጣበት በከንፈሩ ላይ ለምጽ\nከንፈሩን ቢነካው መላእክ በጉጠቱ\nለምጡም ተወገደ በዛለት ትንቢቱ\n\nዛሬ ደግ ይሆናል ትናንት የጨከነው\nከእግሩ ስር ይወድቃል ለጊዜው ያመጸው\nዳዊት በአምላኩ ፊት ንስሃ ቢገባ\nተባለ እንደልቤ ባፈሰሰው እንባ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 212, 0),\n(1, 'እግዚአብሔር ትዝታዬ ነው', 'እግዚአብሔር ትዝታዬ ነው\nእግዚአብሔር ትዝታዬ ነው በልቤ ያኖርኩት\nእኖራለሁ በዘመኔ እየተደገፍኩት\nእወጣለሁ ከመከራ ስሙን ተሸክሜ\nጉልበት ይሆነኛል አልቀረም ደክሜ\n\nየማልረሳውን ቃል አኑሯል በልቤ\nአላፈረም ፊቴ ህጉን በማሰቤ\nየጽድቅን እስትንፋስ ዘርቷል በህይወቴ\nየክብሬ ምስጢር ነው የአገልጋይነቴ (2)\n\nአዝ፦\nትላንት የሚወዱኝ ዛሬ ጠልተውኛል\nእርሱ ግን በፍቅሩ ይከታተለኛል\nበጉያው ሸሽጎ አኖረኝ በክብር\nሳወራው እኖራለሁ ፍቅሩን ስዘረዝር (2)\n\nአዝ፦\nእንዴት እንዳነሳኝ አስታውሰዋለሁ\nያደረገልኝን መች እረሳዋለሁ\nበዝማሬ ሞልቶ ያበቃኝታ ለእልልታ\nእርሱ ነው ጌታዬ የውስጤ ትዝታ (2)\n\nአዝ፦\nሃዘን ከከበበው ከድቅድቅ ጨለማ\nመቼ ተሻገርኩኝ እያሪኮንማ\nሳምራዊው ደገኛ በዘይት ያከመኝ\nአስታውሰዋለሁ በአህያውን ሲጭነኝ (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 213, 0),\n(1, 'መሠረቷ ጉልላቷ እርሱ ነው', 'መሠረቷ ጉልላቷ እርሱ ነው\nመሠረቷ ጉልላቷ እርሱ ነው\nሙሽራዋ መስቀል ላይ የምተው\nዛሬም ነገም ህያው ነው ለዘላለም\nአትንገሩን አዲስ ጌታ የለም (2)\n\nአዝ፦\nየእንግዳው ትምርት የጠላት እንክርዳድ\nበመከሩ ጊዜ ይለያል ሲታጨድ\nጌታ ጌታ ያለው እንዲሁ በብልጠት\nአይወርስም ፈፅሞ የሰማዩን እርስት (2)\n\nአዝ፦\nእራስ ለሆነላት ሆናለች አካሉ\nትታዘዘዋለች ዘወትር ለቃሉ\nየፊት መጨማደድ ሣያገኛት ድካም\nታምና ትኖራለች እስኪመጣ ዳግም (2)\n\nአዝ፦\nየሠማይታቱ ደም የከፈሉት ዋጋ\nየመላክቱ ዜማ የሰማዩ ፀጋ\nየሀዋርያት ስብከት የነብያት ትንቢት\nይገኛል በውስጧ በፀጋው ግምጃ ቤት (2)\n\nአዝ፦\nጎዳናውን ጥሰን ብንጋዝ በ ሀሰት\nለ አንደበታችን አውጀን አርነት\nአይዘጋም ደጇ አይጠፋም መብራቷ\nኢየሱስ ነው ክብሯ ጌጥና ውበቷ (2)\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 214, 0),\n(1, 'ይህ አይገባትም', 'ይህ አይገባትም\nይህ አይገባትም አገር ለሰራችው (አገር ላቆመችው)\nድምጿን ስትቀንስ ዝም ያለች መስሏችሁ (2)\nየነኳት አልፈዋል እርሷ ግን ፀንታለች\nይህንን አልፋ ገና ትኖራለች\nይህ አይገባትም አገር ለሰራችው አገር ላቆመችው\n\nከአምላክ ተምራ ብዙ ብትታገስ\nጽኑ ናት ኦርቶዶክስ ዘላለም የማትፈርስ\nየማታውቁ እንደሆን መዝገቧን ግለጡ\nመቻል ልማዷ ነው በዓይኗ ግን አትምጡ\n\nአርዮስ እስጥሮስ መች አነቃነቋት\nግራኝ እና ዮዲት መች ቻሉ ሊያጠፏት\nስድባችሁን ችላ ብትመርቃችሁ\nበመንገዷ ላይ ግን አትቁሙ ገብታችሁ\n\nወደኃላ አታይም እርፍን ጨብጣለች\nበስጋ ደም ጥበብ መቼ ትመካለች\nከእርሷ ላይ ውረዱ እጃችሁን አንሱ\nእሳት ለማጥፋት እሳት አትለኩሱ\n\nነፍስን የሚታደግ ጉዞዋ ረጅም ነው\nከምድር ተጀምሮ ሰማይ ነው የሚያልቀው\nስለማትችሉ ይህን ልታስቆሙ\nተዋሕዶን ለማጥፋት በብዙ አትድከሙ\n\nሊቀ መዘምራን ቴዎድሮስ ዮሴፍ\n', 'am', 215, 0),\n(1, 'በቤተ መቅደስህ', 'በቤተ መቅደስህ\nበቤተ መቅደስህ ያሳደከኝ\nለአፌ ጥበብን ያስተማርከኝ\nየልጅነት አምላክ ወዴት አልህ\nበዚህ አለም አሳብ ክንዴ ዛለ\n\nያሸዋ ላይ ህንፃ ሆኗል ቤቴ\nያረገርጋል መሰረቴ\nጠላት ሰልጥኖብኝ ደክሚያለሁ\nዛሬ ብቻዬን ቀርቻለሁ\n\nአባካኝ ሆኛለሁ አመፀኛ\nለዚህ አለም ሀጢያት የማልተኛ\nነብሴ ተንገላታች በመከራ\nማን ያገናኛት ካንተ ጋራ\n\nሰላሜ ነህ አንተ ትዝታዬ\nፅፌ ያኖርኩህ በእንባዬ\nአለም ወስዳኛለች በዘፈኗ\nእባክህ ስራኝ እንደገና\n\nአመፀኞች ሁሉ ቤትህ ገቡ\nምህረት ፍቅርህን እያሰቡ\nእጅህን ዘርግተህ አቀፍካቸው\nባንተ ገለጠ ልቦናቸው\n', 'am', 216, 0),\n(1, 'ኦ እንዳንተ ያለ', 'ኦ እንዳንተ ያለ\nኦ እንዳንተ ያለ ወዳጅ አላገኘሁም እኔ\nኦ ውለታህን ሳስበው በእንባ ይሞላል አይኔ\n\nከእናቴም ልጆች በላይ አንተ ውድ ነህ ለኔ\nወዳጅ እና ዘመዴ ጌታ የክፉ ቀኔ\nምን አለኝ እና ልስጥህ የሚነገር ሚወራ\nእኔስ ተሸንፌያለሁ በእንባ ስምህን ልጥራ\n\nተሰድጄ ብወጣ ወተሀል ከእኔ ጋር\nትላንትናን አለፍኩት ጠላቴን እያራራ\nደግሞ የነገውን ቀን አንተ ታውቃለህ ጌታ\nወጥመዴን ስበር እና አፌን ሙለው በእልልታ\n\nበስረኞች መሀል ሆኜ ሰንሰለት ለብሻለው\nአለም እውነት የላትም ፍትህ ከአንተ እሻለው\nመቼ ታፅናናኛለህ ወዳጅ እና ዘመዴ\nአውጣኝ አውጣኝ ለሚልህ አንተ አታጣም ዘዴ\n\nመመላለስ አይደክምህ እኔን ማስታመም አንተ\nደክመህ አልፈህልኛል እጆቼን አበርትተህ\nሁሌ በሬ ላይ ቆመህ ደጃፌን የምትመታ\nግባ የክብር ንጉስ ብያለው ማራናታ\n', 'am', 217, 0),\n(1, 'አኑሮኛል ቸርነትህ', 'አኑሮኛል ቸርነትህ\nአኑሮኛል ቸርነትህ\nልክ የሌለው ደግነትህ\nእንደአንተ ያለ ከየት ይገኛል\nሁሉም ነገር ትዝ ይለኛል\n\nያች ፈዋሽ አዳኝ እጅህ\nዛሬም ለኔ ተዘርግታ\nበኃጢአት እርቄ እዳልጓዝ\nአስረህኛል በውለታ\nደሞስ ህይወት ምርጫ ቢሆን\nካንተ ወዴት ማን ይኬዳል\nአባቴ ፍቅር እኮ\nጌታዬ ፍቅር እኮ\nአለምን ያስክዳል\n\nሞቼ ነበር ተቀብሬ\nጌታ ወደኔ ባትመጣ\nአንተ ሞቴን ባትሞትልኝ\nወዴት ነበር የእኔ እጣ\nከንቱ ነበር ማንነቴ\nተሸናፊ ለዝች አለም\nግን አንተ የያዝከው\nአባቴ የያዝከው\nይኖራል ዘላለም\n\nመቅደስህን ተጠግቼ\nአይቻለሁ ብዙ ነገር\nበልቤ ውስጥ ያስቀመጥሁት\nእዲህ ለሰው ማይነገር\nግን የሆነው ሁሉም ሆኗል\nየለም ዛሬ ያራረፈ\nየመከራው እሳት\nየፈተናው እሳት ባንተ የታለፈ\n\nአይጠፋኝም ያፈገግታ\nልጄ ብለህ ያሳየኸኝ\nአመፀኛ መጥፎ ሆኜ\nበትከሻህ ላይ ያኖርከኝ\nእዲህም አይነት ወዳጅ አለ\nእየጠሉት የማፈቅር\nስሙም እየሱስ ነው\nየፅርቃችን ሚስጥር\n\nስነፈርቅ ሳለቅስብህ እሽ እያልከኝ\nሁሉም ሆነ የማይሆንለት ነገር የለም\nለካስ ባንተ የታመነ መቸኮሌ መጣደፌ\nአምላኬ ሆይ በከንቱ ነው\nመፈጸሙ ላይቀር\nጌታ አንተ ያልከው\n', 'am', 218, 0),\n(1, 'ስምሽን ለልጅ ልጅ', 'ስምሽን ለልጅ ልጅ\nስምሽን ለልጅ ልጅ እነግራለው\nእናቴ በምልጃሽ ሰው ሆኛለው\nእመቤቴ ስልሽ ነይልኝ ማዕበል ሳይነቅለኝ\n\nእመቤቴ ብዬ ስምሽን መጥራቴ\nቢራቆትብኝ ነው ባዶ ቢሆን ቤቴ\nአይኖቼን ከእንባ ከለቅሶ ከልክይ\nልብሽ ይራራልኝ ወደእኔ አዘንብይ\n\nባህሩም ቢሞላ አምናለው በልጅሽ\nአንገት አያስደፋም እናቴ ፀሎትሽ\nእመቤቴ ስልሽ እጆቼን ዘርግቼ\nቀስታቸውን ሁሉ ጣሉ ጠላቶቼ\n\nሰላም አለኝ አሁን ይህንን አውቃለው\nእጅግ ብዙ ነገር ካንቺ አጊንቻለው\nማድጋዬ ሞልቶ አለም ተመልክቷል\nምድረበዳው ልቤ በፀሎትሽ ረክቷል\n', 'am', 219, 0),\n(1, 'ሰላሜ ነህ ፀጥታዬ', 'ሰላሜ ነህ ፀጥታዬ\nሰላሜ ነህ ፀጥታዬ\nወደቤ ነህ ማረፊያዬ\nሁን ከእኔ ጋራ አሁን ከጎኔ\nፍቅር እኮ ነህ መድህኔ\n\nየአይሁድ ፉከራ\nየጠላት መከራ\nሁሉን ባንት አልፌአለው\nእንደምችል አምንሃለው\nደጆችህ ሁሉ ተዘግተው\nበፍርሃት ውስጥ ተቀምጠው\nተገኘ እየሱስ የአለሙ ንጉስ\n\nአንተን ትቼ ሰላም\nእውነት እውነት አይመስል\nየሰላም ሰጪ አንተ ነህ\nየሞት መውጊያን የሰበርክ\nደጆችህ ሁሉ ተዘግተው\nበፍርሃት ውስጥ ተቀምጠው\nተገኘ እየሱስ የአለሙ ንጉስ\n\nሸክም ከብዶኝ ሳነባ\nልቤ ወደ አለም ተሰባ\nቀንበር ከላዬ አውርደህ\nቀና አደረከኝ በፊትህ\nደጆችህ ሁሉ ተዘግተው\nበፍርሃት ውስጥ ተቀምጠው\nተገኘ እየሱስ የአለሙ ንጉስ\n\nከእኔ ጋር ነህ አምንሃለው\nአልታመንኩም አውቃለው\nየፍቅር አባት የምህረት\nየምትታደግ ከጠላት\nደጆችህ ሁሉ ተዘግተው\nበፍርሃት ውስጥ ተቀምጠው\nተገኘ እየሱስ የአለሙ ንጉስ\n', 'am', 220, 0),\n(1, 'የሰላሜ ሰው', 'የሰላሜ ሰው\nየሰላሜ ሰው ያልኩት እንጀራዬን የበላ\nየሰላሜ ሰው ያልኩት ወስዶ ከእጄ የበላ\nወዳጄ ይሁዳ የታል ቀረብኝ ወጀ ኋላ\n\nትላንት አብሮኝ ነበረ ጽዋዬ ሞልቶ ሳለ\nወዳጄ ብዬ ያልኩት ታዲያ ዛሬ የታለ\nየታል ወዳጄ የታል አምጡልኝ የልቤን ሰው\nፍቅሩ ቢጎድልብኝ ነው እንባዬን የማፈሰው\n\nበጭራሽ እንዳልከፋው ሲስቅ ሲጫወት ውሎ\nአመሻሹ ላይ ወጣ አቤት የቀን ጎዶሎ\nአቤት የቀን ክፋቱ ማን ይሄን ጠረጠረ\nወዳጄ ማነው ታድያ ገንዘብ ሰው ከቀየረ\n\nመሐላ ቃል ኪዳኑ ያ ሁሉ ብዙ ቃላት\nዛሬ ሁሉ ተረሳ ተዘነጋ እንደ ዘበት\nየታል መዋደዳችን የታል የጥንቱ ፍቅር\nቀና ማለት ይሻላል በድሎ ከማቀርቀር\n\nሠላሳ ዲናር ወስዶ ይሳምም ይንከሰኝ\nአፈር ስሆን እያለ አፈር የሚያስበላኝ\nእርሱን ሰው ይቅር በለው እርሱን ሰው ማርልኝ\nይቅር ማለት ሳውቅ ነው ይቅር የምትለኝ\n', 'am', 221, 0),\n(1, 'ክፉ አላየሁብህ', 'ክፉ አላየሁብህ\nክፉ አላየሁብህ\nፍቅር ብቻ ነው ንጹሕ ልብህ\nየጠበከኝ ጌታየ ክበርልኝ\nያሳደከኝ አምላኬ ክበርልኝ\n\nከእናቴ ማህጸን ገና ከመውጣቴ\nበእጅህ ተይዣለሁ ኢየሱስ አባቴ\nከጥፋት መጥቼ ስመለስ በቤትህ\nአሳድረህኛል በበዛው ምህረትህ\n\nንጉስ ቢታደገው ውሀ ላይ ቢጣል\nጌታየ ሀሳብህ አይከለከል\nከአፈር የተነሳ ከወደቀበት\nእርሱ ነው ምስክር ላንተ ቸርነት\n\nለእስራኤል ይቅርታ ምረቱን ያሰበ\nለቅዱሳን ሁሉ ክብሩን ያጠገበ\nበየዋህነቱ ከእኔ ጋር ይኖራል\nየፍቅር እጎጆውን በልቤ ይሰራል\n\nኢየሱስ ክርስቶስ ደጉ መምህሬ\nየልቤ ማረፊያ ጋሻየና ክብሬ\nሁልጊዜ ማለዳ መልካም ነህ መልካም\nተሸክሜዋለሁ ያንተን ማህተም\n', 'am', 222, 0),\n(1, 'አማኑኤል ስለኛ ዋጋ ከፍለሃል', 'አማኑኤል ስለኛ ዋጋ ከፍለሃል\nአማኑኤል ስለኛ ዋጋ ከፍለሃል\nበአንተ ቁስል እኛ ተፈውሰናል\n\nማዳንህ መጣልኝ ጽድቅህ ተገለጠ\nየእሳቱ ነበልባል ውብ ቃልህ ቆረጠ\nለዘመንህ አልፋ ኦሜጋ የሌለህ\nታምነህ ምትፈውስ\nጌታዬ አዳኝ ነህ\n\nያንተስ ይለያል ያንተስ\nየእኛ ቁስል ህመም\nየአንተ ቁስል ፈዋሽ\nከአንተ ወደየትም አንሄድም በጭራሽ\nየእፎይታ ዘመን ባወጅልክን ባንተ\nወደ ሐይወት መንገድ\nበሩ ተከፈተ\n\nእንደሌዋዊያን በመቅደም አይደለም\nበገዛ ደሙ ነው ያዳነው ይህን ዓለም\nየራቀ ተስፋችን በእጃችን የገባ\nበኢየሱስ ታበሰ የሰቆቃው እንባ\n\nግፍ ያላደረግ ግፍ ተደረገበት\nበተንኮል ተያዘ ተንኮል የሌለበት\nይህ ውሉ ለእኛ ነው\nስቃይ መጨነቁ\nነጭ ልብስ ሆነልን ለይቶን ከማቁ\n', 'am', 223, 0),\n(1, 'አዲስ አድርገኸኝ', 'አዲስ አድርገኸኝ\nአዲስ አደርገኸኝ ዛሬም አሮጌ ነኝ\nቃልና ተግባሬ አልስማማም ያለኝ\nጌታየ ፍቅርህ ይቀስቅሰኝ\n\nስለ ፍቅር ብሰብክ ሺ ቃላት ደርድሬ\nበቀንና ሌሊት ጥላቻ ነው ግብሬ\nእጅግ ተራርቋል ሀሳብህ ከሀሳቤ\nመንፈስህ አቃንቶኝ ላኑርህ በልቤ\nአንተ እየሰማኸኝ ባልሰማህም እኔ\nአላቋረጥከውም አልቆመም ዘመኔ\n\nየውሀ ጠብታ ድንጋይን ይሰብራል\nቃልህ ሲዘንብብኝ ልቤ ግን ጠንክሯል\nየሸክላው ባለቤት ስራኝ አፍርስና\nየምነበብ መልክት ልሁን እንደገና\nአንተ እየሰማኸኝ ባልሰማህም እኔ\nአላቋረጥከውም አልቆመም ዘመኔ\n\nመኖር ስላቃተኝ እንደሞትክለት ሰው\nብኩርናየን ጥየ ትርፌ መቅበዝበዝ ነው\nጌታ ሳትከፋ በመተላለፌ\nከእቅፍህ መልሰኝ እንድኖር አርፌ\nአንተ እየሰማኸኝ ባልሰማህም እኔ\nአላቋረጥከውም አልቆመም ዘመኔ\n\nበሾህ መሀልና መንገድ ዳር ወደቀ\nምርጡ የቃልህ ዘር እንዳያድግ ታነቀ\nስለምትወደኝ እስከ መጨረሻ\nምቹ ማሳ አርገኝ የለሰለሰ እርሻ\nአንተ እየሰማኸኝ ባልሰማህም እኔ\nአላቋረጥከውም አልቆመም ዘመኔ\n\nልቤ ቢራገምም አፌ እየመረቀ\nጠውልጌ እንዳልቀር ምረትህ ፈለቀ\nየሰጠኸኝ እድል ዳግም እንዳይባክን\nበየቀኑ አርመኝ አባቴ አደራህን\n', 'am', 224, 0),\n(1, 'ክበር ባለኝ ነገር', 'ክበር ባለኝ ነገር\nክበር ባለኝ ነገር\nየለም ከእኔ የምለው ሁሉ ከአንተ ነው\n\nአንተ ታይበት እኔ ልደበቅ\nበአገልግሎቴ ብቻህን ድመቅ\nመዝሙሬ ከአንተ ስብከቴ ከአንተ\nከእኔ አንዳች የለኝም የአንተን ለአንተ\n\nየዕውቀቴ ምንጭ ነህ አብርሆቴ\nየስኬቴ ቁልፍ ሞገሴ ቤቴ\nራቁቴን መጣሁ ራቁቴን እሄዳለው\nምን ተገኘና አንተን ተዋለው\nምንም ሳይኖረኝ ካለኸኝ አንተ\nባለፀጋ ነኝ ያልተራቆተ\nእንዳመንኩብህ በታች እያለሁ\nበላይም ሆኜ አመልክሀለው\n\nእንደታዘዝኩህ በልጅነቴ\nለክብር አቁመኝ በአዋቂነቴ\nበትዳር በልጅ ስትባርከኝ\nእንደ ትላንቱም ዛሬም የአንተው ነኝ\nሹመኛ ብሆን ገንዘብ ብቆጥር\nኩራት አይግባ በልቤ ቅጥር\nየነቀልክልኝ የኃጢአቴን መርዝ\nበእኔ ላይ እዘዝ ባለኝ ላይ እዘዝ\n', 'am', 225, 0),\n(1, 'ቅዱስ ሚካኤል', 'ቅዱስ ሚካኤል\nቅዱስ ሚካኤል ወዳጅ ነህ ለሁሉ\nዛሬም ቆመሀል በኪዳንህ ላሉ\n\nክንፍህን ዘርጋ ሚካኤል ቅደም ከፊቴ\nምራኝ መንገዱን እንዳይመሽ ልድረስ ካባቴ\nእንዴት ይገፋል ጎዳናው ካላንተ እርዳታ\nጥሜን ቁረጠው በበትርህ ጭንጫውን ምታው\n\nተጠመጠመ ጠላቴ በእሳት ሰንሰለት\nየጌታ መልአክ ሚካኤል በሰይፍ ወድቆበት\nየለም ከቦታው ስመለስ አጥቼዋለው\nየሚረዳኝን ተሹሞ አይቼዋለው\n\nከመቃብሩ ድንጋዩን አንከባለሀል\nስለረዳኸዉ ዳንኤል እጅግ ወዶሀል\nይነዋወፃል ባህሩ አንተ ስትመጣ\nእግዚአብሄር ይንገስ ዳቢሎስ መድረሻ ይጣ\n\nአለኝ ትዝታ በቤትህ ከልጅነቴ\nስትሳሳልኝ እያየው ፀንቷል ጉልበቴ\nልዘምር እንጂ ላመስግን ታላቁን ጌታ\nአንተን የሰጠኝ ጠባቂ በቀን በማታ\n', 'am', 226, 0),\n(1, 'ኃይሌም ዝማሬዬም', 'ኃይሌም ዝማሬዬም\nኃይሌም ዝማሬየ እርሱ ነው ዘላለም\nከብሮ ያስከበረኝ እንደ እግዚአብሔር የለም\nእንደ እግዚአብሔር የለም\nክብር ለሱ ይሁን ታላቅ ነው ዘላለም\n\nአቤቱ ጉልበቴ ሆይ አቤቱ መጽናናቴ\nታትመሀል በውስጤ ተስለሀል ከፊቴ\nአያውህ አሻግሬ በተራሮች ከፍታ\nጨለማየን ስትገፈው ሰንሰለቴን ስትፈታ\n\nዶኪሜ ነህ ኢየሱስ ዶኪሜ ነህ ጌታየ\nእግሮቼ ላይ ይፈሳል የማይቆመው እንባየ\nናፈቀችህ መንፈሴ እንደ ዋላ ተጠማሁ\nስምህን አውጄበት ይሸበራል ከተማው\n\nዲዳው አፉን ከፈተ ምርኮኛው ነጻ ወጣ\nምድር ባንተ አረፈች ለተገፉት ቀን ወጣ\nየእንባየ ምትክ ሆኖ ጽድቅህ መንደሬን መላ\nየረዳኝ የሚረዳኝ ማን አለ ካንተ ሌላ\n\nአቁሞኛል ግሳፄህ አቁሞኛል ፍቅርህ\nወዳጅ አበዛህልኝ ወዳጄ እያልኩህ\nጸጋ ሞልቶ ፈሰሰ የዝማሬ ማእበል\nደጅህ በመንጋ ሞላ ጌታየ ሆይ ምን ልበል\n', 'am', 227, 0),\n(1, 'ምስጋና', 'ምስጋና\nምስጋና በሰማይ በመድር\nውዳሴ በሰማይ በምድር\nሁሉን ቻይ ለሆነው እግዚአብሔር\nምስጋና\n\nከእርሱ በፊት ከእርሱ በኋላ ማንም የለም\nየወደደ በንጹህ ፍቅር ለዘላለም\nገና ብዙ እንሰራለን ከእሱ ጋራ\nምስክር ነን የተመካን የማንፈራ\n\nሰባራውን ይጠግናል በዘይቱ\nዘመናትን ያቀዳጃን በምህረት\nወድቆልናል ጥላታችን ላይነሳ\nአንበሳ ነው የሚያገሳ\n\nእረዴትን እየላከ ከመቅደሱ\nያዘኑትን እያጽናና መንፈሱ\nበልዕልና ይመለካል ይከበራል\nየማይሻር ንጉሳችን ነግሶ ይሆራል\n\nየተሻለ የበረታ ቅኔ ዜማ\nሁሉን በፍቅር ሳይጸየፍ የሚሰማ\nእስከሚያይቱ የሰቀሉት የወጉት\nይገለጣል እያበራ የእኛ አባ\n', 'am', 228, 0),\n(1, 'ሰረገላዎችህ የእሳት ናቸው', 'ሰረገላዎችህ የእሳት ናቸው\nየሌጌዎን ጭፍሮች ማይችሏቸው\nየገሀነም ደጆች ማይችሏቸው\nአንተ ብቻ ቅዱስ ኃያል ጌታ\nሳመልክህ እኖራለሁ ጠዋት ማታ\n\nበእሳት ሰረገላ ታጥሮአል መንደራችን\nጊያዝ ሆይ አትፍራ አለ ፈጣሪያችን\nየጠላትን ምሽግ በቃሉ ይቆርጣል\nከእኛ ጋራ ያለው ከነሱ ይበልጣል\n\nከቴማን ተራራ ከፋራን ሲወርድ\nጠላት ይጨነቃል በድምጹ ሞገድ\nጦረኛ አያበዛም ሞአብን ሲመታ\nበአህያ መንጋጋ ሺውን ጥሏል ጌታ\n\nየጥልቁን መሰረት በንፋስ አስሮታል\nከሰማያት በላይ ዙፋኑን ዘርግቷል\nዘንባባ ይዛችሁ ግቡ ከመቅደሱ\nበምስጋናው ስርዓት እንድትቀደሱ\n\nወደረኞቻችን ከቁጥር ቢበዙም\nእንደ ቃየል ልጆች ሾተል አንመዝም\nእንጀራን መግበን እንሰዳቸዋለን\nበቀል እና ፍርድን ለአምላካችን ትተን\n', 'am', 229, 0),\n(1, 'የግብፅን ከተሞች', 'የግብፅን ከተሞች\nየግብፅን ከተሞች ትተን ወተን\nበበረሀው ስንሄድ ምድርን ሞልተን\nጫማና ልብሳችን አላለቀም\nእርሱ እየቀደመ መድሐኒኒአለም\n\nታላቁን ቀይ ባህር ስንሻገር\nአስጨንቆን ነበር ብዙ ነገር\nግን ሁሉም ቀለለ ከፊታችን\nእርሱ እየቀደመ አምላካችን\n\nከአለት ላይ ውሀ ጠጥተናል\nየነሃሱም መባ ፈውሶናል\nየምድር ሰልፈኞች ቢነሱብን\nለሞት አሳልፎ መቼ ሰጠን\n\nእስራኤል በክብር ፊቱን ሞልቷል\nሰባቱም ደመና ጋርደውታል\nነፃ ስለወጣን ክሱ ታጥፎ\nማንስ ይነካዋል ክንድን አልፎ\n\nአለም ብትገፋን ብትጨክን\nአንተ ግን እንደሰው መቼ ጣልከን\nከኛጋር ተዋግተሕ ድል ለብሰናል\nየበፍታ ኤፎዶም አምሮብናል\n', 'am', 230, 0),\n(1, 'ሂዱ ንገሩ አውሩ ለአለም', 'ሂዱ ንገሩ አውሩ ለአለም\nሂዱ ንገሩ አውሩ ለአለም\nተነሥቷል በዚህ የለም መድኃኔ አለም\nሞት የማይችለው የበረታ ኃያል ነው የማይረታ\nማኅተሙን የፈታ የትንሳኤው ጌታ\n\nገዳዩ ሞት በእርሱ ድል መንሳት ተዋጠና\nሰንሰለቴን ቀንበሬን ተካው በበገና\nሞት ሆይ መውጊያህ የታል እያልን እምንዘምረው\nመስቀልህ ጦር ስምህ ጋሻችን ሆኖልን ነው\nዳንን የምንለው\n\nተሻግረናል ስላሻገርከን ለዘላለም\nበመቃብር ሞት ይይዘህ ዘንድ ከቶ አልቻለም\nኃይለኛውን በኃይል አስረኸው ላይፈታ\nመመርንልህ አሸናፊ ነህ የእኛ ጌታ\nከፍ በል በእልልታ\n\nማቶ ማዳን ለማን ተችሏል ካንተ በቀር\nጌትነትህ ስራህ ይኖራል ሲመሰከር\nወዳጄ ሆይ ውበትህ ውብ ነው የሚያበራ\nተጨነቀ ተንቀጠቀጠ ጥላት ፈራ\nዕጹብ ያንተ ስራ\n\nመስክሩለት የምስራች ነው ታላቅ ዜና\nመላዕክቱ ነጭ ለብሰዋል ድል ነውና\nከተማዋ አንዳች ሁናለች በሌሊቱ\nበዝማሬ ተንቀጠቀጠ ወኅኒ ቤቱ\nከበረውን ምቱ\n', 'am', 231, 0),\n(1, 'ሮሆቦት እያልን', 'ሮሆቦት እያልን\nሮሆቦት እያልን እንዘምር በእልልታ\nጌታ አብዝቶናል ውሎልናል ውለታ\nየዝማሬ ነው የምስጋና ሰዓቱ\nየእግዚአብሔር ልጆች ክንዳችሁን አበርቱ\n\nቃኝተንዋል በገና መሰንቆውን\nሳናቆርጥ በፊቱ ምስጋናውን\nበእጣኑ ጢስ ታጅቦአል ውዳሴያችን\nይሰማናል ያበዛን አምላካችን\n\nለአገልግሎት ስንወጣ ጥቂት ነበርን\nበረሀውን ስንጓዝ በዛ ዘመን\nለመለምን በፍቅሩ እንደዋዛ\nለዚህ ቀን አስቦናል ጌታ ለካ\n\nሁሉም ሆኖአል በጊዜው በፈቃዱ\nእንቅፋቱም ተነሥቶአል ከመንገዱ\nያነሳሳል ያበረታናል ገና\nዓለምን እንከድናል በምስጋና\n\nስናመሰግን ውለን እናድራለን\nያለ ድካም በፊቱ እንቆማለን\nእንኳን በምድር በሰማይ በበጉ ፊት\nዝማሬአችን ይሰማል እንደ ዳዊት\n', 'am', 233, 0),\n(1, 'ፀጋህ ይብዛልኝ', 'ፀጋህ ይብዛልኝ\nፀጋህ ይብዛልኝ ምህረትህ አይራቀኝ\nአማኑኤል ሆይ ስራ ደነቀኝ\nተመስገን ልበል ላቅርብ ምስጋና\nበአንተ ቸርነት ቆሚያለሁ እና\n\nፀጋህ በዝቶልኝ እዘምርልሃለሁ\nበምስጋና ላይ ምስጋና አበዛለሁ\nአለኝ ሺ ቃላት አለኝ ብዙ ቋንቋ\nአንተን መግለጫ ለዓለም የሚበቃ\n\nየተናገርከው የአሰብክልኝ ሆነ\nየልቤም መሻት ይህንን ነበረ\nአስተካከልከኝ ከኃያላን ጋራ\nአማኑኤል ሆይ እፁብ የአንተ ስራ\n\nበለምለሙ መስክ አሳድገህኛል\nያን የጭንቁን ቀን አሳልፈህኛል\nየምስጋና እርሻ ሆነልኝ ደጃፌ\nአባት ሆይ ስልህ ማርማር አለው አፌ\n\nበአዝን ብደሰት ብወድቅም ብነሳ\nእስከ አሁን አለሁ ከአንተ የተነሳ\nመረቤን ጥዬ ተስፋ አደርግሃለሁ\nእንደ ምትሞላው እተማመናለሁ\n', 'am', 234, 0),\n(1, 'አሜን እግዚአብሔር ከብሯልና', 'አሜን እግዚአብሔር ከብሯልና\nአሜን እግዚአብሔር ከብሯልና\nምድርን ሸፈናት በምስጋና\nአሜን እግዚአብሔር ከብሯልና\nምድርን ከደናት በምስጋና\n\nማሰማሪያዎቹ መንጎቹን ለበሱ\nበክብር ተሞልቷል ገናናው መቅደሱ\nእልል እልል በሉ ድምፃችሁ ይሰማ\nበእልልታ ወረስናት እያሪኮንማ\n\nሐቫናና ፋርፋ የሶርያ ወንዞች\nአልቻሉም በጭራሽ ማዳን ሕመምተኞች\nየእግዚአብሔር ሰው ኤልሳ ቃል ብቻ ተናገር\nንእማን እንዲመሰጥ በአምላካችን ፍቅር\n\nዘመን አያስረጁት አመታት ወራት\nዛሬም በሰማይ ነው አሸናፊነት\nየነገድ አለቆች ያመሰግኑታል\nየወርቁ መሰዊያ በእጣን ተሞልቷል\n\nሜዳና ተራራው በወንጌል ታረሰ\nዳቦት ተሰባብሮ እግዚአብሔር ነገሰ\nይሰበካል ገና የመንግስቱ ዜና\nየአምላካችን መምጫው ጊዜው ቀርቧልና\n', 'am', 235, 0),\n(1, 'ፃኡ ንኡሰ ክርስትያን', 'ፃኡ ንኡሰ ክርስትያን\nዝለዋል ክንዶቼ ሀጢአት አብዝቻለሁ\nየጌታዬን ፊቱን እንዴት አየዋለሁ\nፃኡ እየተባለ ሲታወጅ አዋጁ\nእንደምን ቆማለሁ ደፍሬ ከደጁ\n\nበቂም በግፍ መንፈስ ተይዟል\nእንዴት ፍፁም ሆኖ ልቤ በአንተ ይገዛል\nየጎሰቆለ ነ በሀጢሀት ሰውነቴ\nበምህረትህ ጎብኘኝ አማኑኤል አባቴ\n\nአልኖርኩም በቃልህ ግብ ፈትህ ቆማለሁ\nእጅግ ይደንቀኛል ድፍረቴን ሳስበው\nይቅርታሕ በዝቶልኝ ከቤትህ ብገባ\nመታጠብ አቃተኝ በንስሀ እንባ\n\nማረኝ በምህረትህ ጎብኘኝ በይቅርታ\nከመንጋህ አትለየኝ አምላኬ የኔ ጌታ\nየመቅደስህን ደውል እያስደነገጠኝ\nእድሜን ልንስህ ለህይወት ሰጠኝ\n', 'am', 236, 0),\n(1, 'ይኸው ተነሳ', 'ይኸው ተነሳ\nሐያል ነው እርሱ ዘላለማዊ የሁሉ ጌታ\nሞትን የዋጠው ድልን ያወጀ የማይረታ\nይኸው ተነሳ ደስ ይበለን\nብርሃንን አየን\n\nተነስቷል ጌታችን በእኩል ሌሊት\nሞትን ድል አድርጎ አለ በሰማያት\nየጨለማው ገዥ ስልጣኑ ተሻረ\nሞቶ የነበረው ክርስቶስ ከበረ\n\nየጠላት ሠራዊት ግብሩ ተገለጠ\nየእዳ ፅህፈታችን እንደሰም ቀለጠ\nሲኦል ባዶ ቀረ መዝጊያው ፈራረሰ\nሲነሳ አምላካችን ሀይላችን ታደሰ\n\nበታላቅ ምስጋና በግሩም ውዳሴ\nትንሳኤውን አይታ ተማርካለች ነፍሴ\nብርቱ ነው ጠንካራ የተነገረለት\nከእንግዲ በኋላ ምን ስልጣን አለው ሞት\n\nእኛም ከእርሱ ጋር ከሞት ነስተናል\nበቤተ መቅደሱ ብርሃንን ለብሰናል\nየአዳም ልጅ ሰንሰለት ቋጠሮው ተፈታ\nእጃችሁን አንሱ ዘምሩ በእልልታ\n', 'am', 237, 0),\n(1, 'ያላንተ ለኔ', 'ያላንተ ለኔ\nያላንተ ለኔ ማን ሊሆነኝ\nጌታ ሆይ ፍቅርህ ልቤን ነካኝ\nህግህ ነበረ ያፌ መፍቻ\nየማትቀየር አንተ ብቻ\n\nአስተምርበት በመርከቤ\nቃልህን ብቻ ያድምጥ ልቤ\nቀኑም ቢገፋ ወደ ማታ\nአሳው ታዘዘ ላንተ ጌታ\n\nውዴ ልበልህ ሽልማቴ\nቤቴም ያንተ ነው ሰውነቴ\nደለደልክልኝ ያንን ጋራ\nእንዳልሞት አርገኝ እንዳልፈራ\n\nፀፀተኝ ዛሬ ያኛው ወራት\nአንተን ሳላውቅህ የኖርኩበት\nፍቅር ነህ ለካ ማር ወለላ\nምን ህይወት አለ ካንተ ሌላ\n\nቀፃፍያችንን ቀፅፈህዋል\nያንን ጭንቁን ቀን አልፈነዋል\nነገም ያንተ ነው አዲሱ ቀን\nእንዘምራለን ስትናፍቀን\n', 'am', 238, 0),\n(1, 'ኢየሱስ ናዝራዊ', 'ኢየሱስ ናዝራዊ\nዘላለማዊ\nኢየሱስ ናዝራዊ\n\nበበረት የተኛው በግርግም\nአልፋና ኦሜጋ ዘላለም\nድንቅ መካር ሐያል ቸርአባት\nበይቅርታ ጎብኘን በምህረት\n\nዘላለማዊ\nኢየሱስ ናዝራዊ\n\nአንተን ተደግፌ በመኖሬ\nአልተጎደለብኝም እስከ ዛሬ\nፍቅር በዝቶብኛል የኔ ጌታ\nተመስገን ልበልህ ጠዋት ማታ\n\nዘላለማዊ\nኢየሱስ ናዝራዊ\n\nበምህረት እጆችህ ብትዳስሰኝ\nድካሜን አርቀህ ሰው አረከኝ\nዛሬ ድፍረት አለኝ ለምስጋና\nወደኸኛልና እንደገና\n\nዘላለማዊ\nኢየሱስ ናዝራዊ\n\nመፅናናት በአንተ አለ ፍቅር ሰላም\nምስካየ ህዙናን መድኃኒዓለም\nየአመኑብህ ዳኑ በተአምራት\nስራህ ይደንቀኛል ቀን ከሌሊት\n', 'am', 239, 0),\n(1, 'ሰው አትረሳም', 'ሰው አትረሳም\nሰው አትረሳም ከቶ አትጥልም መድሃኒያለም\nታምኛለሁ ባንተ ለዘላለም\n\nአስታዋሽ እረኛ ፈጥረህ የማትረሳ\nምስኪኑን ከጉድፍ ከአፈር ምታነሳ\nሰው የለንም ላሉ ሰው ሆነህ የታየህ\nእግዚአብሔር በእውነት ድንቅ ነህ\n\nሁሉም አለህና ባለጸጋው ጌታ\nማን ያፍራል ለምኖህ በጎውን ስጦታ\nበስምህ ያመኑትን ታድናቸዋለህ\nለፀኑት ሁልጊዜ መልስ አለህ\n\nእህት ወንድም ላጡ ደጋፊ አለኝታቸው\nወላጅ ለማያቁ አባት መፅናኛቸው\nየተዘነጉትን የማትዘነጋ\nአንተ ነህ አልፋና ኦሜጋ\n', 'am', 240, 0),\n(1, 'እመኑ በእርሱ', 'እመኑ በእርሱ\nእመኑ በእርሱ ድንቅ ያደርጋል ጌታ\nበረዶ አዝንቦ ጠላት እየመታ\nውቅያኖስ ጥልቁን ፈጥኖ እያተነነ\nነገር ለወጠ ሁሉ በርሱ ሆነ\n\nእመኑ በእርሱ ተራራው ነደደ\nእመኑ በእርሱ ሸለቆው ታወከ\nእመኑ በእርሱ ዝግባው ተሰባብሮ\nእመኑ በእርሱ አለቱ ደቀቀ\nእመኑ በእርሱ የአሕዛብ ጣዖታት\nእመኑ በእርሱ በፊቱ ረገፉ\nእመኑ በእርሱ በስሙ የታመኑ\nእመኑ በእርሱ ወጀቡን ቀዘፉ\n\nእመኑ በእርሱ የማይነጋ ሌሊት\nእመኑ በእርሱ ማያልፍ ቀን የለም\nእመኑ በእርሱ ሁሉ ይቻለዋል\nእመኑ በእርሱ ጌታ መድኃኔዓለም\nእመኑ በእርሱ ፍቅር ነው ዘለዓለም\nእመኑ በእርሱ ደግ አባት ለልጁ\nእመኑ በእርሱ ሁሌ ተዘርግታ\nእመኑ በእርሱ ትኖራለች እጁ\n\nእመኑ በእርሱ ሞገድ የማይሰብረው\nእመኑ በእርሱ ጽኑ መርክብ አለን\nእመኑ በእርሱ አንፈራም አንሰጋም\nእመኑ በእርሱ ከርሱ ጋር እያለን\nእመኑ በእርሱ ጠላት ተሸንፏል\nእመኑ በእርሱ ሰይጣን አፍሯል ዛሬ\nእመኑ በእርሱ ወህኒው ይነዋወጽ\nእመኑ በእርሱ በታላቅ ዝማሬ\n\nእመኑ በእርሱ ባዶ ነው አይሰራም\nእመኑ በእርሱ የጠላት ፉከራ\nእመኑ በእርሱ የማይተወን ጌታ\nእመኑ በእርሱ አለ ከኛ ጋራ\nእመኑ በእርሱ እጅግ አትረፍርፎ\nእመኑ በእርሱ ጸጋ ከበዛልን\nእመኑ በእርሱ በሞት ጀርባ ቆመን\nእመኑ በእርሱ ገና እዘምራለን\n', 'am', 241, 0),\n(1, 'ቀን አምጣ እባክህ', 'ቀን አምጣ እባክህ\nቀን አምጣ እባክህ ጌታዬ እባክህ ቀን አምጣ\nእባክህ ያሀዌ እባክህ ተው ፍረድ\nተው ፍረድ አይቀጥል አመፃው ድፍረቱ\nእባክህ ቀን አምጣ ተናገር አቤቱ\nእባክህ ቀን አምጣ ታረቀን አቤቱ\n\nልብ ያለው ልብ ይበል ዘመኑን ያስተውል እንደሚገባ\nማነው ያላለቀሰ ያላነባ\nመሻገሪያው በእሳት ከታጠረ\nሰው በጭንቀት ብዛት ከሰከረ\nየደሀው ደም መፋረጃ ካጣ\nከትላንቱም የባሰ ከመጣ\n\nየዋሂቱ እርግብ በዘንዶ ምላስ ላይ ጣለች ልጆቿን\nታዲያ ማን አየው ሊላት ጫጩቶቿን\nእኮ ማን አየሁ ሊላት ክፋዮቿን\nእረ ፍትህ ዳኛ ወዴት አለ\nከተማውስ ይሄን ጉድ ምን አለ\nለማይራራው አመፅ ለተሞላ\nፍርድ የለም ወይ አደራ ለበላ\n\nምነው ያለ ወትሮ ቀኑ ጨላለመ ፀና ደመናው\nታላቁ የፍርድ ቀን ገናና ነው\nታላቁ የፍርድ ቀን ሚያስፈራ ነው\nአኬልዳማ ምድር ቃልዋን ሰጠች\nየእግዚአብሔር ጣት ይህን አደረገች\nየአመፀኞች ቅጥራቸው ፈረሰ\nለተገፋት ነፃ አውጪው ደረሰ\nእግዚአብሔር ደረሰ\n', 'am', 242, 0),\n(1, 'የኔ ጌታ', 'የኔ ጌታ\nሰምቼህ አድምጬህ\nልቀመጥ በእርጋታ\nመንፈሴን አበርታ\n\nፈጥኖ ይስማማና ሐሳብህ ከሀሳቤ\nስጋት መከራዬ ይነቀል ከልቤ\nጭንቀትን ይነቅላል እርጋታን ይተክላል\nቃልህ ስልጣን አለው ያፈርሳል ይሰራል\nአይወድቅም አንተን የሰማ\nድምጽህን ልጂህ ልጠማ\nበቅዱስ መንፈስህ ይዋሀደኝ ቃልህ\nየኔ ጌታ\n\nችግሬ ታላቅ ነው አይበል ከንፈሬ\nታላቅነትህን ልንገር ለችግሬ\nጠላቴ ፊት ስቆም ፊትህ ተንበርክኬ\nየድል ነው ዘመኔ የድል ነው ታሪኬ\nአይወድቅም አንተን የሰማ\nድምጽህን ልጂህ ልጠማ\nበቅዱስ መንፈስህ ይዋሀደኝ ቃልህ\nየኔ ጌታ\n\nዝናብ ታመጣለህ ባይኖርም ደመና\nበረከትን ልጥገብ እሽ ልበልና\nያደረክላትን ልንገራት ለነፍሴ\nልጠማ ጧት ማታ ልሰማ በመንፈሴ\nአይወድቅም አንተን የሰማ\nድምጽህን ልጂህ ልጠማ\nበቅዱስ መንፈስህ ይዋሀደኝ ቃልህ\nየኔ ጌታ\n\nበፊትህ ምንድነው የሴረኞች ስራ\nቃልህ ጉልበት አለው ይኖዳል ተራራ\nበእርሱ መዶሻነት በደሌ ሲመታ\nጫጫታው ያልፍና ይሰፍናል ፀጥታ\nአይወድቅም አንተን የሰማ\nድምጽህን ልጂህ ልጠማ\nበቅዱስ መንፈስህ ይዋሀደኝ ቃልህ\nየኔ ጌታ\n\nአያፍረኝ አይፈራኝ ቃልህ መስታወቴ\nሁሌ ይነግረኛል ስለማንነቴ\nወዴት እንደወደኩ ወዴትስ እንዳለሁ\nሽንገላን በማያውቅ በቃልህ አውቃለሁ\nአይወድቅም አንተን የሰማ\nድምጽህን ልጂህ ልጠማ\nበቅዱስ መንፈስህ ይዋሀደኝ ቃልህ\nየኔ ጌታ\n', 'am', 243, 0),\n(1, 'ይደንቀኛል ዘላለም', 'ይደንቀኛል ዘላለም\nይደንቀኛል ዘላለም የሰለጠነ ስም ሰምቼ\nእኔ ወጣው ከእስራት ይህን ስም ጠርቼ\n\nእስኪ ሞት ይደንግጥ ይህንን ስም ልጥራ\nገዳዬን ላድነው ልውጣ ልሰማራ\nተው አታቅሉልብኝ አትግፏት እውነቴን\n\nማልጄ ልገስግስ ሰልፍ አለብኝ ዛሬ\nወንጨፌ እና ቀስቴ አንተ ነህ ጠጠሬ\nከሞት የዳንኩብህ ማምለጫ አለቴ\nሀይል አስታጣቂዬ ቅደምልኝ ፊቴ\n\nመውጊያው ተናወጠ ወለል አለ ደጁ\nነጻነት ነው ስሙ ጽድቅ ነው አዎጁ\nመታመን በዚህ ስም መደገፍ በጌታ\nእፎይታ ነው ትርፉ የማታ የማታ\n\nየጌታን ስም ጥሩ የጠሩ ድነዎል\nየቀደሙት ሁሉ በዚህ ስም ታምነዎል\nሰማይ እና ምድር ጸኑ ለዘላለም\nኢየሱስ ነው ሁሌም ቤዛዎ ለአለም\n', 'am', 244, 0),\n(1, 'እንደ ሰው ልማድ', 'እንደ ሰው ልማድ\nእንደ ሰው ልማድ አንዋጋም\nመንፈስ ነዉና ባላጋራችን\nእንደ አለም ጥበብ አንዘምትም\nሰይፍ አናነሳም ለክፋታችን\nየታለ ስሙ ያ ከፍታችን የታል ጸሎቱ መሰወሪያችን\nየታለ ቃሉ ደመ ቤታችን የታለ ኢየሱስ ፊት አዉራሪያችን\n\nጸሎታችን ብርቱ ክንድ ናት መዶሻ\nታላቁን ቅጥር ግንቡን ማፍረሻ\nየእግዚአብሔር ቃል ይሰራል ዛሬም\nሀይል አለዉ ጌታ ቅርብ ነው\nሰምቶ በእሳት የሚመልስ ነው\nአቤቱ ባንድ ልጅህ\nአቤቱ በምትወደዉ\nአቤቱ ባንድ ልጅህ\nአባት ሆይ በምትወደው\n\nስሙን ይዘን እንቃትታለን በፊቱ\nጸሎት ነው ያማኝ ጉልበቱ\nጎንበስ ጎንበስ እስኪ ዝቅ ዝቅ ለጌታ\nየእንባ ጠብታ ሞት እንዲታወክ\nእርስ እንዲፈታ\nአቤቱ ባንድ ልጅህ\nአቤቱ በምትወደዉ\nአቤቱ ባንድ ልጅህ\nአባት ሆይ በምትወደው\n\nይቅደምልን እግዚአብሔር ይዉጣ በሞገስ\nእኛ እንበርከክ እርሱ ቅጥር ያፍርስ\nልባችንን ከጆቻችን ጋር ወደ ላይ\nከፍ ወደሰማይ ከአዝማቻችን ጋር እንድንተያይ\nአቤቱ ባንድ ልጅህ\nአቤቱ በምትወደዉ\nአቤቱ ባንድ ልጅህ\nአባት ሆይ በምትወደው\n', 'am', 245, 0),\n(1, 'በመከራ ባዘን', 'በመከራ ባዘን\nበመከራ ባዘን ደስ ይለናል\nባንተ ፍቅር ማዕበሉን ቀጽፈናል\nስንጠራህ ስንልህ አምላካችን\nያ ተራራ ዘለለ ከፊታችን\n\nማሰሯችንን ይዘን በገለአን ተራራ\nበማያቆም ውዳሴ አንተን ስንጠራ\nየጠላታችን ድንኳን ምሶሶው ተሰበረ\nሀያል ክንድህ አርፎብን ታሪክ ተቀየረ\n\nእንደወደድከው ሆኖል ልብህ እንደፈቀደው\nመቼ ፍጻሜው ያምራል አንተ ያላየኸው\nበጎበኘሀን ጊዜ ከሸለቆ ወተናል\nከሚከተልህ አለት ውሀ ጠጥተናል\n\nበሙአብ ቢተከሉ የዝሙት ምሰሶዎች\nሳንደገፍባቸው ተርፈናል ብዙዎች\nበፈሮን ከወረዱ ጓጉንቸሮች ድነናል\nሞተ በሩን አምልጠን ከነአን ገብተናል\n\nየበረታውን ንዳድ በደመና ተሻግረን\nየሰደድክልን መልአክ በክንፉ ጋረደልን\nእርም ከሆነው ነክተን ብንደነግጥ በጋይ\nአካንን አስወግደን ተርፈናል ከስቃይ\n', 'am', 246, 0),\n(1, 'መሞት የለም', 'መሞት የለም\nመሞት የለም መሸነፍ\nአማኑኤል ባንተ ሰልፍ\nመሞት የለም መሸነፍ\nየኛ ጌታ ባንተ ሰልፍ\n\nፈረሰኛውና ፈረሶቹ\nሊያመልጡ አልቻሉም ከእጆቹ\nግብፃዊው ሲፎክር ሲያስፈራራ\nእኛስ ተሻግረናል ካንተ ጋራ\n\nሰባሪው ወጥተሀል ከፊታችን\nከእንግዲህ ሰላም ነው ጎዳናችን\nየአስማተኞቹ መርዝ ሀይሉን አጥቷል\nአንተን የያዘ ሰው መች ይሞታል\n\nሳኦል በዳዊት ላይ ጦር ቢያነሳ\nእግዚአብሔር ልጆቹን መች ሊረሳ\nከአስጨናቂው መዳፍ አስጥሎናልና\nህልም ይመስላል እንጂ አምልጠናል\n\nበብዙ መከራ ደስ ይለናል\nእንኳን ይህን እና ያንን አልፈናል\nለጦር ለሰንሰለት ቢሰጡንም\nአማኞች ተፅናኑ መሞት የለም\n', 'am', 247, 0),\n(1, 'ትላንትና ካንተ ጋር ዛሬ ደግሞ ከሌላ', 'ትላንትና ካንተ ጋር ዛሬ ደግሞ ከሌላ\nትላንትና ካንተ ጋር ዛሬ ደግሞ ከሌላ\nሰልችቶኛል አባቴ ሆይ ሁሌ መሄድ ወደኋላ\nሁሌ መጓዝ ወደኋላ\n\nሰዶምን አልተውኩም ወደኋላ አየዋት ደግሜ\nምንኛ ከንቱ ነኝ ሳልለወጥ ባለሁበት ቁሜ\nይነዳል ከተማው ይቃጠላል በቁጣው እሳት\nእጄን ይዘህ አውጣኝ ዞአር ሳልደርስ ጌታዬ እንዳልሞት\nጨው አልጫ ቢሆን በምን ይጣፍጣል\nአጣፍጠኝ በቃልህ ከደጅህ እንዳልወጣ\n\nዴማስን ሆኛለሁ ተሰሎንቄ አስራ ያስቀረችኝ\nስሸሽህ አግኝታ ከባህሩ ከጥልቁ የጣለችኝ\nወፎች ለቅመውታል ቅዱስ ቃልህ በውስጤ የታለ\nአዘገየኝ እንጂ ያጠላቴ እየሸነገለ\nመልሰኝ ልመለስ በለቅሶ በዕንባ\nአሳንባሪው ይትፋኝ ወደ ቤትህ ልግባ\n\nአለቀ ገንዘቤ የሰጠኸኝ አፍሰህ በችሮታህ\nእራሴን አገኘሁት አመሻሽ ላይ በተናቀ ቦታ\nጨልሟል ዞሪያዬ ምይዘውን ነገር አጥቻለሁ\nየድሮዋ አይደለሁም የኔ ጌታ ዛሬ ደክሜአለሁ\nመንገድ ለጠፋው ሰው ክንድህ ወዴት አለ\nምንድነው ምሬትህ እራሱን ለጣለ\n\nማለዳ ስነቃ ዘምሬልህ ሲመሽ ግን ሌላ ነኝ\nቃልህ ያልለወጠኝ ያልቀየረኝ ጌታዬ እኔ ማነኝ\nአይወስንም ልቤ ያመነታል ይሸሻል አጥብቆ\nዘላለም ላይደላኝ እስከመቼ ካንተ ተደብቆ\nእንድወስን እርዳኝ ይበርታ ጉልበቴ\nጠላት ጭኑን ይስፋ እቀፈኝ አባቴ\n', 'am', 248, 0),\n(1, 'በዘላለም ኪዳን', 'በዘላለም ኪዳን\nበዘላለም ኪዳን በደም ሰንሰለት\nይዘኸን ታስከትለናለህ በልዩ ፍቅር እስከ ሞት ድረስ ወደኸን\n\nየጨለመዉ ለሊት የከበበን መከራ\nያስጨነቀን ጠላት ከእንግዲህ ላያወራ\nየያዘን ላይዘን የደም ነዉ ኪዳናችን\nሁሉን የፈጸምከዉ ተባረክ አምላካችን\n\nእዉነትና መንገድ ሕይወት ነህ የማትጠፋ\nለፍቅርህ መኖሪያ ልባችንን ያሰፋ\nደጃችንን ዘግተን አሜን ነዉ በእንባ ሙላት\nየፍቅርህ ምርኮኞች አድርጎን ያንተ ምህረት\n\nበማግኘት በማጣት በደስታ በሃዘናችን\nየለንም ሌላ ቃል አንተዉ ነህ አዋጃችን\nአድኖናል ፀጋህ ጽድቃችን ሰማይ ነካ\nኢየሱስ ዉሃ ነዉ ትዉልዱን የሚያረካ\n\nአንተ የሕይወት እራስ የሕይወት ፍጻሜያችን\nየለመለምከዉ መስክ መሰማሪያዉ ቅጥራችን\nቤዛነትህ ሆኖ ኩነኔዉ የለም ዛሬ\nድነናል በፀጋህ አሜን በዝማሬ\n', 'am', 249, 0),\n(1, 'እረኛዬ ነህ', 'እረኛዬ ነህ\nእረኛዬ ነህ የነብሴ ቤዛዋ\nየቆሰልክላት አንተ የሞትክላት ባለ ውለታዋ\n\nልሰማራ ልውጣ እንጂ ተማምኜ\nአንተ አለህ ታዳጊና አዳኜ\nየአለም ሰልፏ ብዙ ነው በፍራቻ\nየኔ ሞገስ አጀቤ አንተ ብቻ\n\nበቁጣ ቀን ቤቴ በእሳት ሲታጠር\nአንተ ባትኖር እኔም የለሁም ነበር\nየማያልፈው አለፈ በህይወቴ\nጋርደህለኝ ከልለኸኝ አባቴ\n\nእንዳልደክም እንዳልሞት በመንፈሴ\nከቶ አትስጠኝ አሳልፈህ ለራሴ\nከፍ ያልክ ነህ ከፍ ያልከው በምስጋና\nሁሌም አዲስ ጉልበት የምታጸና\n\nጎደለልኝ የመከራው ሙላቱ\nባንተ ታዞ በጊዜው በሰአቱ\nየሳኦል ጦር አለፈ በራሴ ላይ\nእንደዘበት ከሞት ጋር ሳልገናኝ\n', 'am', 250, 0),\n(1, 'ታቦር አበራ', 'ታቦር አበራ\nታቦር አበራ ምድርን ከደናት ያደመና\nእንቅልፍ የለንም ታላቅ ነጎድጕድ ሆኗልና\nአነቃን ለምስጋና\n\nሙሴም የቀደመው ሰዉ ኤልያስ ኃይለኛው\nተገኝተዋል በታቦር ምስክርህ ሆነው\nእኛም ከገናናው ክብር ያባቱን ቃል ሰምተናል\nበረዶ ሆኗል ልብሱ እፁብ እፁብ ብለናል\n\nቃል ገብተህልኝ ነበር ልታሳየኝ ክብርህን\nንገስ ከሞት ገስግሰህ አይቸሃለሁ አሁን\nየሳት ፈረሶች አሉህ ታዋጊው የኔ ጌታ\nአርሙኒየም ደስ አለው ስሳራን ስለመታ\n\nእጠብቅሃለሁኝ በምታልፍበት ቆሜ\nመብራቶቼን አብርቼ ነጩን ልብስ ተሸልሜ\nየዳዊት ልጅ ሆይ ግባ ኢየሱስ ወደቤቴ\nብያለው እልሃለሁ ድናለች ሰውነቴ\n\nሁሉንም ብታከብር ሁሉንም ብትምረው\nማነው ቸርነትህን የሚከለክለው\nጠዋትም የተጠራ አምሽቶ የገባው\nሆነዋል ባለዋጋ ከበዛው ስጦታው\n\nየረዳኸው ይናገራል ያሰበከው በሕይወቱ\nአቤነዘር እያለ ይዘምር ባንደበቱ\nበደስታየም ቀን አለህ አይሃለሁ ከጎኔ\nከነጋር አልቅሰሃል አሳዝኖህ ሀዘኔ\n', 'am', 251, 0),\n(1, 'የባዘነች ነብሴ', 'የባዘነች ነብሴ\nየባዘነች ነብሴ እረፍት አግኝታለች\nበመድኃኔዓለም እረፍ አግኝታለች\nአምላክ በፈቀደው ቤቴ ሰላም ሰፍኗል\nህይወቴን ለማዳን ክርስቶስ ተነግቷል\n\nበአህዛብ መሀል የታራ ልጅ ሆኜ\nአይን እያለው ማያይ ጣኦት ተሸክሜ\nጨረቃና ንፋስ ሳመልክ መቼ ተውከኝ\nየዚህ ፀሀይ ጌታ አንተ አነጋገርከኝ\n\nበእየሩሳሌም ታምርክን ሰምቼ\nደምግባትክን ላየው ከዛፍ ላይ ወጥቼ\nውስጤን የምታቀው በስም የጠራኸኝ\nመዳን ሆኖልኛል ሰላሙን ሰጠኸኝ\n\nንዳድ የለቀቀሽ የጴጥሮስ አማት ላይ\nጣቢታ ተነሺ ዘምሪ ላዶናይ\nበጌታ ቸርነት ከለምፅ የነፃችው\nመስክሩ እንጂ ላለም አረ ወዴት ናቹ\n\nበስርቆት በወንጀል ቢቆሽሽ ህይወቴ\nለመስቀል አበቃኝ የገዛ ኃጢያቴ\nአስበኝ ስላልኩት በፍቅር አሰበኝ\nዛሬ ከእኔ ጋራ በገነት ነህ አለኝ\n', 'am', 252, 0),\n(1, 'የወደደኝ ጌታ', 'የወደደኝ ጌታ\nየወደደኝ ጌታ ምን አድርጌለት\nብዘምርለት ያንስበታል ይኸው\nከውድቀቴ አንስተህ ድካሜን ያገዝከኝ\nሰባራውን ድልድይ ገጥሞ ያሳለፍከኝ\n\nበእያሪኮ መንገድ ስለምን ቁጭ ብዬ\nብርሀን እጅግ ናፍቆኝ ከሰው ተገልዬ\nየብርሀን ጌታ ወደኔ መጣና\nአይኔን አበራልኝ በእጁ ዳሰሰና\n\nለብዙ ዘመናት አልጋላይ ተኝቼ\nየሚረዳኝ አጣሁ ጠሉኝ ዘመዶቼ\nየእኔ ጌታ አምላኬ ወደእኔ መጣ እና\nአልጋህን ተሸከም አለኝ ፈወሰ እና\n\nአስራ ሁለት አመት ደም እየፈሰሰኝ\nምራቅ እየተፉ ሁሉም ቢያንቀሽሹኝ\nየጌታዬን ልብሱን ጮፋን ብዳስሰው\nሀይልም ከሱ ወጣ ደሜን ቀጥ አረገው\n\nሰካራም ዘማዊ ወንበዴ ነበርኩኝ\nያመፀኞች መሪ ደም ያፈሰስኩኝ\nዛሬ ግን ታሪኬን ጌታ ቀይሮታል\nለሀያሉ ጌታ ምስጋና ይገባል\n', 'am', 253, 0),\n(1, 'ግሩም ድንቅ ነህ', 'ግሩም ድንቅ ነህ\nግሩም ድንቅ ነህ አምላኬ ግሩም ድንቅ ነህ አምላኬ\nግሩም ድንቅ ነህ ጌታዬ ግሩም ድንቅ ነህ\nሰው የጣለውን ከምድር ከፍ ታደርጋለህ\nየተረሳውን አምላኬ ታስታውሳለህ\n\nከቤተሰይዳ ያነሳል በአልጋ ያለውን\nመጠመቅ ሽቶ እረዳት ወገን ያጣውን\nከኃጢያተኛው ቤት ይገባል እራት ሊበላ\nበቀል አያውቅም ጌታዬ ከፍቅር ሌላ\nእንደ አምላካችን ማንም የለም\nእንደ እግዚአብሔር ማንም የለም\nእንደ ፈጣሪ ማንም የለም\nእንደ አማኑኤል ማንም የለም\n\nየበደለውን አይንቅም ያነሣል በእጁ\nፍፁም ይራራል በእውነት ጌታ ለልጁ\nከሳምራዊው ጋር ይውላል እንደ ጓደኛ\nሁሉን በፍቅር የሚስብ ታማኝ እረኛ\n\nሰው የናቀውን አንስቶ ሾሞ ያከብራል\nዘይት አፍስሶ ባርያውን በእጁ ይቀባል\nአክሊል ይደፋል አንስቶ ላጎነበሰው\nክብርና ጋሻ መከታ ዝናር ሊሆነው\n\nያዘነውን ሰው ያጽናናል ፍቅር እየዘራ\nያነሳለታል የጭንቁን ግዙፍ ተራራ\nዳግም አይኖርም በቤቱ የእስራት ቀንበር\nእርሱን ተማምኖ የቆመ ከመቅደሱ ስር\n', 'am', 254, 0),\n(1, 'ሰዎች ደስ ይበለን', 'ሰዎች ደስ ይበለን\nሰዎች ደስይበለን በአምላካችን\nከኃጢአት ባርነት ነፃ ላወጣን\nተነሱ እናመስግን ውለታው ብዙ ነው\nምን ይከፈለዋል ተመስገን ብቻ ነው\n\nበኃጢአት በሽታ ወድቄ ሳለሁኝ\nመድሃኒት ክርስቶስ ከውድቀቴ አነሳኝ\nስጦታው ብዙ ነው ለኔ የሰጠኝ\nተመስገን ብቻ ነው አምላክ ላንተ ያለኝ\n\nእንደ በርጤምዮስ እውር የነበርኩኝ\nዛሬ ግን በአምላኬ ድህነት አገኘሁኝ\nህጉም ለመንገዴ ብርሐን ሆኖኛል\nየእርሱ ስለሆንኩኝ ሠላምን ሰጥቶኛል\n\nበድንቅ አጠራርህ በፍቅር የጠራኽኝ\nከአጋንንት እሥራት ነፃ ያወጣኽኝ\nአልፋና ኦሜጋ ዘላለም የምትኖር\nኤልሻዳይ የሆንከው አማኑኤል ተመስገን\n\nየዕዳ ደብዳቤዬን ጌታዬ ቀደደው\nየማዳኑን ሥራ በአይኔ አይቻለው\nቸርነቱ አያልቅም ድንቅ የሆነ ጌታ\nስሙን እናመስግን እንዘምር በእልልታ\n', 'am', 255, 0),\n(1, 'አበረታኝ ፍቅርህ ጌታዬ', 'አበረታኝ ፍቅርህ ጌታዬ\nአበረታኝ ፍቅርህ ጌታዬ\nአበረታኝ ክንድህ አምላኬ\nበስምህ ድኛለሁ በፀጋህ\nበማደሪያህ ሆኜ ስጠራህ\n\nሰዶም ስትቃጠል መርገሟ ሲበዛ\nሊተወኝ አይሻም ልጁን እንደዋዛ\nህጉን በማሰቤ አምላክ ፈረደልኝ\nጎትቶ የሚያወጣ መልአክ ሰደደልኝ\n\nበገናን መደርደር አያቆምም ጣቴ\nየወንጭፌ ድንጋይ አንተነህ ጉልበቴ\nየሳኦልን ካባ አውልቀህ ጣልክልኝ\nየፍልስጤሙን ሰው ክንድህ ሰበረልኝ\n\nሶስት ጌዜ ስክድህ አላውቅህም ብዬ\nዶሮ ስለጮኸ ትዝ አልከኝ ጌታዬ\nወጣሁኝ በዕንባ ከአይሁድ እሳት ሥር\nከሐዲ ሳትለኝ አኖርከኝ በፍቅር\n\nሳምራዊ ናት ሳትል ክብርን የጠየከኝ\nእንደ አንተ ከአይሁድ ፍቅርን ማን አሳየኝ\nምስጢሬን በሙሉ ነገርከኝ ጌታዬ\nየፍቅር ውሃ ቀዳሁ እንሥራዬን ጥዬ\n', 'am', 256, 0),\n(1, 'ጌታ እኮ ነው', 'ጌታ እኮ ነው\nጌታ እኮ ነው ይህን ያደረገው\nአምላኬ ነው ለኔ የታመነው\nበዘመኔ ሁሉ ድንቅን የፈፀመው\nጌታ እኮ ነው ይህን ያደረገው\n\nየጠላቴን ሴራ ያፈራረሰልኝ\nከድንጋይ መወገር እኔን የታደገኝ\nየሞት አዋጅ ሽሮ ፅድቅን ያለበሰኝ\nአምላኬ ብቻ ነው እኔን ያባበለኝ\nጌታ እኮ ነው ኃጢያቴን የሻረው\nጌታ እኮ ነው በሰላም ሂድ ያለኝ\nጌታ እኮ ነው ልቤን ያረጋጋው\nጌታ እኮ ነው ስተክዝ የረዳኝ\n\nከወንበዴዎች የታደገ ፈጥኖ\nቁስሌን በዘይቱ ያበሰልኝ አዝኖ\nወዳጅ ሆኖ ቀርቦ ሃዘኔን ያስረሳኝ\nጌታዬ እርሱ ነው መጽናኛ የሆነኝ\nጌታ እኮ ነው በምህረቱ ያየኝ\nጌታ እኮ ነው ቁስሌን የፈወሰው\nጌታ እኮ ነው ከጠላት ያስጣለኝ\nጌታ እኮ ነው ሰላሜን ያወጀው\n\nባኡርን ተሻግሮ ወደኔ የመጣው\nየሙታንን ኑሮ በህይወት የቀየረው\nያሰረኝን ጠላት በስሙ ገስጾት\nነጻ አወጣኝ ጌታ ታሪኬን ለውጦ\nጌታ እኮ ነው የለወጠኝ\nጌታ እኮ ነው ልጁ ያደረገኝ\nጌታ እኮ ነው ጠላቴን የጣለው\nጌታ እኮ ነው በቤቱ ያኖረኝ\n\nበምስኪኑ ድንኳን ገብቶ የሚቀመጥ\nበሃዘን ለተዋጠው መፅናናት የሚሰጥ\nእጅግ ቸር ጌታ ነው ማዳኑን አይተናል\nስሙን አወድሱት እልልታ ይገባዋል\nጌታ እኮ ነው ከእስራት የፈታው\nጌታ እኮ ነው ጥልቁን ያሻገረን\nጌታ እኮ ነው በሰልፍ ያበረታን\nጌታ እኮ ነው ያከናወነልን\n', 'am', 257, 0),\n(1, 'አልጋ ላይ ላለው', 'አልጋ ላይ ላለው\nአልጋ ላይ ላለው ለታመመው\nፈዋሽ ሐኪም ነው ለቆሰለው\nመጸየፍ አያውቅ ርኅሩኅ ልቡ\nፈውስ አግኝተዋል ቤቱ የገቡ\n\nየምድርን ሲሳይ የእለት እንጀራ\nባርኮ ይሰጣል ስለሚራራ\nየተቆረጠን ተስፋን ቀጥሎ\nሕይወት ይሰጣል ከሞት አስጥሎ\n\nጸሎትን ሁሉ የምትሰማ\nመሸሸጊያችን የሆንከን ግርማ\nፍቅርህ ልዩ ነው ወደርም የለው\nይህንን አምላክ ከፍ እናድርገው\n\nካሰብነው በላይ የምታስብልን\nየሕይወት ውሃን የምታጠጣን\nበበረሃው ላይ ደመናን ጥለህ\nሕዝብህን ከሞት ትታደጋለህ\n', 'am', 258, 0),\n(1, 'ርግብ እና ዋኔን', 'ርግብ እና ዋኔን\nርግብ ዋኔን\nአብረው ዘመቱና ዋኔን\nርግብ ደህና ገባች ዋኔን\nዋኔን ገደሉና ዋኔን\n\nየሌሊቱ ዝናብ ዋኔን\nምንም አላለኝም ዋኔን\nቀን ጥሎኝ ነው እንጂ ዋኔን\nየደበደበኝ ዋኔን\nአዳልጦኝ ወደኩኝ ዋኔን\nትላንትና ቀትር ዋኔን\nእንዴት እደርሳለሁ ዋኔን\nመቼም መመሸቱ አይቀርም ዋኔን\n\nአየሁት በህልሜ\nሞት የተባለውን\nስጋ ተሸክሜ\nሰማሁት በዝና\nቀጠሮ አክባሪ ነውና\nሞት አይቀርምና\n\nማለዳ ላይ ጤዛ ዋኔን\nበቀትር ሀሩሩ ዋኔን\nምን መኖር ያስመኛል ዋኔን\nእንዲ ሆኖ አገሩ\nእይችልም ብላችሁ ዋኔን\nስትንቁ ሙያዬን ዋኔን\nነገ በመቅደሱ ዋኔን\nታያላቹ ሳጥን ዋኔን\n\nበእጃችሁ ያለው ደም ዋኔን\nውጦታል ጥቀርሻ ዋኔን\nዘርን ስትዘሩ ዋኔን\nገብታቹ ከእርሻ ዋኔን\nማለፍ የግድ ነው ዋኔን\nበከንቱ አትለፋ ዋኔን\nሞት አይፈራም እና ዋኔን\nሰውነት ቢሰፋ ዋኔን\n\nችግሬን ንገሩኝ ዋኔን\nውዳሴን ትታችሁ ዋኔን\nነገ ለመዋረድ ዋኔን\nቃል እንዳያጥራችሁ ዋኔን\nየዳዊቱን ንባብ ዋኔን\nስንቱ ሰው ረሳ ዋኔን\nተነሺውን ጥሎ ዋኔን\nወዳቂ እያነሳ ዋኔን\n', 'am', 259, 0),\n(1, 'በምን ደስ ላሰኝህ ጌታዬ ሆይ', 'በምን ደስ ላሰኝህ ጌታዬ ሆይ\nበምን ደስ ላሰኝህ ጌታዬ ሆይ\nበምን ደስ ላሰኝህ አምላኬ ሆይ\nአለምና መላው ያንተው አይደለም ወይ\nየፈጠርከው ሁሉ ያንተው አይደለም ወይ\n\nኪሩቤል ሱራፌል ቅዱስ ሥሉስ ያሉህ\nመላዕክት በራማ የሚያመሰኑህ\nድንቅ መካር ኃያል ኤልሻዳይ ነህና\nትንሽ ነኝ ምን ልስጥህ ምንስ አለኝና\n\nቅዱሱን መስዋዕት ልዑል ስለሚወድ\nምን ይዤ ልምጣና በአምላኬ ፊት ልስገድ\nወደ ላይ በሰማይ ወደ ታች በጥልቀት\nአምላኬ የት አለ የማትገኝበት\nጌታ ሆይ የት አለ የማትገኝበት\n\nበኪዳን በፀሎት ቅዳሴ ሰዓታት\nአንተ የሰጠኸኝ የመንፈስ ቅዱስ ሀብት\nመልሰን ወደ አንተ ብንሰጥ ምን አለ\nተወው ጉዳችንን ስስታችን ይኸው\n\nሀብትና ንብረቴስ ጉልበቴስ ምንድነው\nጤናዬ የሰጠኝ ከአንተ በቀር ማነው\nበሰጠኸኝ እድሜ በሕይወት ዘመኔ\nከገላዬስ ቢሆን የትኛው ነው የኔ\nከአካላቴስ ቢሆን የትኛው ነው የኔ\n', 'am', 260, 0),\n(1, 'ምናል ብታስተምረኝ', 'ምናል ብታስተምረኝ\nበክብር በሞገስ በመወደስ ፈንታ\nመቀመጥ እንድችል ከመዋረድ ተርታ\nስድብህን የሰማህ ያላንዳች ሁካታ\nለመቆም እንድችል ልቤ ሳይረታ\nምናል ብታስተምረኝ\nብታስችለኝ ጌታ\n\nለኔም አስተምረኝ ባላጠፉት ጥፋት\nበፀጋ መቀበል የአይሁድን ትፋት\nእንዴት እንደሚቻል ሳያጉረመርሙ\nንገረኝ ጌታዬ ይረዳኝ ትርጉሙ\nምናል ብታስተምረኝ\nብታስችለኝ ጌታ\n\nየመናቅን ጥበብ የውርደትን ዘዴ\nእባክህ አስረዳኝ አስተምረኝ አንዴ\nብኤል ዜቡል ተብለህ ያልተበሳጨኸው\nየሀጢያተኞች ወዳጅ መባል ያልጠላኸው\nጋኔን ይዞታልን የሰማህ በጸጋ\nለኔም አስተምረኝ\nበቂም አልወጋ\n\nአልወጋ እባክህ በመራርነት ጦር\nበቁጣ ጥላቻ ልቤ አትሰበር\nእንዴት ነበር ያኔ የይሁዳን እግር\nዝቅ ብለህ ያጠብከው ስታውቅ ሁሉን ነገር\nለኔም አስተምረኝ\nብዙ ሳልናገር\n\nበችንካር ተጣብቀህ ከመስቀሉ ጋራ\nየደምህ ነጠብጣብ ገና ሳያባራ\nአያውቁትምና የሚያደርጉትን\nይቅርታን የለመንክ ላጠጡህ አሞትን\nምናል ብታስተምረኝ\nእንዲህ ያለ ህይወትን\n\nአሁን ምን ቸገረህ ብትሰጠኝ ለአንድ አፍታ\nየትህትናን ቀሚስ የትዕግስትን ኩታ\nእያየህ አይደል ወይ ነፍሴ እንዲህ ተራቁታ\nየመሰደብን ዘውድ የመናቅን ካባ\nምናለ ብትኖር\nይህች ልቤ ደርባ\n\nትዕቢት ለተሞላው ላትንኩኝ ባይ ልቤ\nለክብሩ ለሚኖር ለኮርማው ሀሣቤ\nምናል ብትቀባው የትህትናን ሽቶ\nእንደዚህ ከሚኖር ሸቶ ተበላሽቶ\nኧረ እኔስ አልቻልኩም አቅቶኛል በጣም\nስድብንም መቀበል ሀሜትን ማጣጣም\nስተርከው እንጂ ስኖረው አቃተኝ\nይህን መራር ኑሮ አንተው ይዘህ ጋተኝ\n', 'am', 261, 0),\n(1, 'ናና ማኑኤል', 'ናና ማኑኤል\nናና አማኑኤል ና መድኃኒቴ\nጽድቅህን አልብሰኝ ይቅር መራቆቴ\nናና አማኑኤል ና መድኀኒቴ\nፍቅርህን አልብሰኝ ይቅር መራቆቴ\n\nየምሕረት አባት አማኑኤል\nየቸርነት ጌታ አማኑኤል\nፊትህ የተመላ አማኑኤል\nሁሌ በይቅርታ አማኑኤል\nካለው ፍቅር በላይ አማኑኤል\nአባት ለአንድ ልጁ አማኑኤል\nአምላክ ይወደናል አማኑኤል\nአይጥለንም ከእጁ አማኑኤል\n\nመድኃኒቴ ልበል አማኑኤል\nድኛለው በሞትህ አማኑኤል\nቁስሌ ተፈውሷል አማኑኤል\nበቁስልህ በሞትህ አማኑኤል\nስሸጥህ አቀፍከኝ አማኑኤል\nስወጋህ አይኔ በራ አማኑኤል\nበፍቅርህ አወጣኸኝ አማኑኤል\nከዚያ ከመከራ አማኑኤል\n\nአንተ ከኔ ጋር ነህ አማኑኤል\nአዎ ከኔ ጋራ አማኑኤል\nድል አርገህልኛል አማኑኤል\nየጭንቄን ተራራ አማኑኤል\nበጉባኤ መሀል አማኑኤል\nአፌ አንተን አወጀ አማኑኤል\nየከበረ ደምህ አማኑኤል\nነፍሴን ስለዋጀ አማኑኤል\n\nየድንግሏ ፍሬ አማኑኤል\nየበላቴናዋ አማኑኤል\nየቤቴ ምሰሶ አማኑኤል\nየነፍሴ ቤዛዋ አማኑኤል\nመሠረቴ አንተ ነህ አማኑኤል\nያሳደገኝ እጅህ አማኑኤል\nአተወኝም አንተ አማኑኤል\nስለሆንኩኝ ልጅህ አማኑኤል\n', 'am', 262, 0),\n(1, 'እንደኔ የማርከው ማንን ነው', 'እንደኔ የማርከው ማንን ነው\nእንደኔ የማርከው ማንን ነው\nእንደኔ ይቅር ያልከው ማንን ነው\nሀጢያቱ በዝቶበት\nበደሉ በዝቶበት\nየማርከው እንደኔ ከቶ ማነው\n\nበሞገስ አስጊጠህ በዜማ ቃኘኸኝ\nፊትህ ምታቆመኝ ጌታየ እኔ ማነኝ\nለኔ ያበዛኸው አቤት ደግነትህ\nምረኸኝ አያልቅም ምህረትህ\nአይተኸኝ በምህረት\nዛሬም አለሁኝ በህይወት\n\nየምስጋና መስዋት ማቅረቢያ መሰዊያ\nልቤ ንፁህ ባይሆን ፀጋየን አልቀማህ\nትቀበለኛለህ ምልተህ በጎደለ\nእኔን የወደደ እንዳንተ ማን አለ\nአይተኸኝ በምህረት\nዛሬም አለሁኝ በህይወት\n\nበምኞት ተስቤ ለሀጢያት ተሽጬ\nበመስቀልህ ስራ ከሞት ጣር አምልጬ\nአንተ እንዳዳነከው ሰው መሆን ቢያቅትም\nእኔ ተስፋ ብቆርጥ ተስፋ አትቆርጥብኝም\nአይተኸኝ በምህረት\nዛሬም አለሁኝ በህይወት\n\nየኖርኩበት ዘመን የቁጣ ልጅ ሆኜ\nምዕራፉ ተዘጋ ባንተ በአዳኜ\nከኔ ምንም ሳይኖር አንተ ሁሉን ሆነህ\nሰገነት ታየሁኝ ስለእኔ ተንቀህ\nአይተኸኝ በምህረት\nዛሬም አለሁኝ በህይወት\n\nእኔን ማረኝ ከምል ከፊትህ ወድቄ\nበሌላው ፈራጅ ነኝ እራሴን አፅድቄ\nመመልከት ባልችልም የዓይኔን ምሰሶ\nየሚያኖረኝ ፍቅርህ ነው ይን ሁሉ ታግሶ\nአይተኸኝ በምህረት\nዛሬም አለሁኝ በህይወት\n', 'am', 263, 0),\n(1, 'የትኛው ስራዬ', 'የትኛው ስራዬ\nየትኛው ስራዬ የትኛው ህይወቴ\nሞገስ ሆኖኝ እንጂ እግዚአብሔር አባቴ\n\nልጅዋን ትረሳ ዘንድ እናት እንኳን ብትስት\nአንተ ግን ወደድከኝ ላትረሳኝ በሞት\nበመዳፍህ ቀርፀህ ሁሌ ታየኛለህ\nመድሀኒቴ ኢየሱስ በደሌን እረስተህ\nቢምረኝ ነው ቢምረኝ በመቅደሱ ያቆመኝ\nቢያስበኝ ነው ቢያስበኝ በከፍታው ያኖረኝ\n\nየአብርሀምን ምግባር የዮሴፍን እምነት\nፅድቅን ባልኳለው ባላደርግ መቀነት\nማህተቡን ይዣለሁ የደሙን ጠብታ\nመድሀኒቴ ኢየሱስ አክብሮኛል ጌታ\nቢምረኝ ነው ቢምረኝ በመቅደሱ ያቆመኝ\nቢያስበኝ ነው ቢያስበኝ በከፍታው ያኖረኝ\n\nእንዳልፈው የረዳኝ የእሳቱን ባህር\nምን ምግባር ኖሮኝ ነው ከፅድቅ የሚቆጠር\nየልቤ ኩራት ነው የአይኔ ከፍታ\nመድሀኒቴ ኢየሱስ የሠራዊት ጌታ\nቢምረኝ ነው ቢምረኝ በመቅደሱ ያቆመኝ\nቢያስበኝ ነው ቢያስበኝ በከፍታው ያኖረኝ\n\nዘይቱ እንዴት ፈላ በራሴ ያፈሰስከው\nዙፋን ልታወርሰኝ ልቤን የመረጥከው\nየኔ የተወደደው ከኤልያብ ደም ግባት\nመድሀኒቴ ኢየሱስ ሆነኸኝ ነው ውበት\nቢምረኝ ነው ቢምረኝ በመቅደሱ ያቆመኝ\nቢያስበኝ ነው ቢያስበኝ በከፍታው ያኖረኝ\n', 'am', 264, 0),\n(1, 'ሁሉም ያልፋል', 'ሁሉም ያልፋል\nሁሉም ያልፋል እግዚአብሔር ያሳልፋል\nልጆቹን መቼ ይረሳል\n\nብርሃን ይመጣል ጨለመው ተገፎ\nደስታ ይሆናል መከራው አልፎ\nየምስራች ቃል ይሞላል በአፋችን\nሀዘናችን ጠፍቶ ይፈካል ፊታችን\n\nበትር ነው ምርኩዝ ነው እሱን ላመኑበት\nባህር ውቅያኖሱን ከፍለው የሚያልፉበት\nበእሳት መካከል በግፍ ለተጣሉ\nውሃ እየሆናቸው በድል ይወጣሉ\n\nማስተዋል ጥሩ ነው ትዕዛዛቱን ማክበር\nያኖራል በሕይወት በሰማይ በምድር\nየማያልፍ ቀን የለም ታሪክ የማይሆን\nበአምላክ አንድ ቀን ነው አንድ ሺ ዘመን\n\nይቅርታ እንዲሰጠን በደልን ሳይቆጥር\nማረን እንበለው ስለሆነ ፍቅር\nነገ ቀን ሲመጣ ብርሀኑ ሲያበራ\nፊታችን እንዳይዞር ወደ ክፉ ስራ\n', 'am', 265, 0),\n(1, 'ያየህብኝን ያላሳየህብኝ', 'ያየህብኝን ያላሳየህብኝ\n\nያየህብኝን ያላሳየህብኝ\nደግሞም በደሌን የረሳህልኝ\nአስገረመኝ ለኔ ያለህ\nአስደመመኝ ለኔ ያለህ\nብበድልህ ብበድልህ\nእየቻለኝ ያ ትከሻህ\n\nእጄን ባፌ ያስጫነኝ አስገረመኝ ደጉ ልብህ\nፊትህ አይጠቁር በሀጥያቴ እንዳላየህ ታልፈዋለህ\nሳታሳጣኝ በሰው መሀል የኔ ከዳኝ የልቤ ጥግ\nአላነፅኩም ካየህልኝ ከከፍታ ከዚያ ማይርቅ\n\nበርሱ ምህረት ከድቅድቁ ከወጣሁኝ ከጨለማ\nለይሁዳ ክፉ ወሬ ልቤ አይሰጋ ላለም ዜማ\nበነበልባል ሲያቃጥለኝ የስምዖን አንደበቱ\nየሳት ልሳን ሆነኽልኝ ባንተ አለፈ ያ ክረምቱ\n\nከበለስ ስር የሰራሁት አለም ተፍቶ ያቃለለው\nእረሳሁት ትቼዋለሁ እንዳንት ያለ ከቶ ማነው\nሰው ሲሸሸኝ የቀረብከኝ አንተ እኮ ነህ መድሀኒቴ\nአይንህ አይቶኝ መች አለፍከኝ አነሳኸኝ ቸር አባቴ\n\nመክሮ ሲታክተው ውጣ ብሎ እየጣለ\nስንቱ አለፈ በመከራ ሰው ወገኑን ስላልቻለ\nየኔ ጌታ ፍቅሩ ችሎኝ ለፊው ክንዱ አሻገረኝ\nለውለታው ከእንባ በላይ የሚያረካው ምን ቃል አለ\n', 'am', 266, 0),\n(1, 'እኔ ደካማውን', 'እኔ ደካማውን\nእኔን ደካማውን ቀኝህ እያገዘኝ\nእኔን ኃጢአተኛውን ክንድህ እየረዳኝ\nሳትቆጥረው በደሌን ከፊትህ አቆምከኝ\nገበናዬን ከድነህ በከፍታ አዋልከኝ\n\nቀኝህ ባታግዘኝ ባትረዳኝ መድኅኔ\nማነው ሰው እያለ ይቆም ነበር ጎኔ\nመታያ ሆነኸኝ ከፍ ያለ ሰገነት\nሁሌም እደምቃለሁ በእጅህ በረከት\n\nየደማስቆ ብርሃን ሕይወቴን ቀይሮት\nግብሬ መሰደድ ነው ለስምህም መሞት\nአዳፋው ቀጸላ ዛሬ መች ታሰበ\nቤቴ ደምቆ ዋለ ፍቅር እያነበበ\nእልፍ እየበደልኩ በእልፍ ምሕረት\nፊቴን እያዞርኩ ሳይጠላኝ ያንተ ፊት\nአብዝቼ ስርቅህ አጥብቀህ ቀረብከኝ\nየማፍቀርህ ጥጉ መውደድህ አኖረኝ\n\nከበደል በማይርቅ በሥጋ ምኞቱ\nጽድቅን እየሸሸው ብውል ከጥፉቱ\nአቤት የኔ ጌታ አቤት ያንተ ጸጋ\nሁሌም ያኖረኛል ሌቱን እያነጋ\nእልፍ እየበደልኩ በእልፍ ምሕረት\nፊቴን እያዞርኩ ሳይጠላኝ ያንተ ፊት\nአብዝቼ ስርቅህ አጥብቀህ ቀረብከኝ\nየማፍቀርህ ጥጉ መውደድህ አኖረኝ\n', 'am', 267, 0),\n(1, 'በእኔ ቢጠቁር ሰማይ', 'በእኔ ቢጠቁር ሰማይ\nበእኔ ቢጠቁርም ሰማይ\nበእኔ ቢጠልቅም ፀሐይ\nበነፋሳት የማይጠፋ ፋኖሴ\nኢየሱስ ነው የመኖር እስትንፋሴ\n\nእርሱን ታምኜ እወጣለሁ\nእርሱን ታምኜ እገባለሁ\nድብቅ ሰራዊት አለው ለእኔ\nየሚጠብቀኝ በዘመኔ\nእግዚአብሔር ለእኔ ብርሃኔ ነው\nየሚያስደነግጠኝ የሚያስፈራኝ ማነው\n\nሰው አልባ ሁኜ በስደት\nወዳጄ የሆንከኝ የእኔ አባት\nክርስቶስ ለእኔ ሕይወቴ ነው\nእርሱን ታምኜ እኖራለሁ\nየለም የሚያስፈራኝ በዘመኔ\nብርሃን ነውና እግዚአብሔር ለእኔ\n\nመች ይሰጠኛል ለጠላት\nአይሰለጥንም በእኔ ሞት\nየሚጠብቀኝ ጌታ ነው\nየትኛው ጠላት ሊደፍረው\nበቤቴ መቃን ላይ ደም ይታያል\nእኔን ከእግዚአብሔር ከቶ ማን ይለያል\n\nይኸው አቆመኝ በመቅደሱ\nእየጠበቀ በመንፈሱ\nእኔን ሊያከብር ራሱን ሰጥቶ\nግዝቶኛል ጌታ ሞቴን ሙቶ\nይገዛ ለስሙ ስጋ መንፈሴ\nበእርሱ ነውና ለዛሬ መድረሴ\n', 'am', 268, 0),\n(1, 'ዝቅ ብየ ላመስግነው', 'ዝቅ ብየ ላመስግነው\nዝቅ ብየ ላመስግነው\nጉልበቴ ነው ላወድሰው\nየፍቅሩ እሳት ልቤን ነክቷል\nየድል ዜማ በአፌ ሞልቷል\n\nምን አገኘ ሰው ይለኛል\nላያኖረኝ ይጨነቃል\nመኖሪያየ በሰማይ\nአባት አለኝ ኤልሻዳይ\nአባትና ንጉስ\nጌታ ቅዱስ ለነብስ\nህይወቴ ነው ክርስቶስ\n\nተራመድኩኝ በጉልበቴ\nስላቆመኝ ደጉ አባቴ\nእሩቅ አይደል ቅርቤ ላለው\nምስጋናየ ለእርሱ ይድረሰው\nአባትና ንጉስ\nጌታ ቅዱስ ለነብስ\nህይወቴ ነው ክርስቶስ\n\nየከበረ የተፈራ\nምረት ያለው የሚራራ\nያገኘኝን አይቻለሁ\nሞት አያየኝ ፊቱ እያለሁ\nአባትና ንጉስ\nጌታ ቅዱስ ለነብስ\nህይወቴ ነው ክርስቶስ\n\nርህራሄው ስላኖረኝ\nከሰው ድንኳን\nየኔስ ጌታ ያስደንቃል\nበልቤ ላይ ቤቱን ተሰርቷል\nአባትና ንጉስ\nጌታ ቅዱስ ለነብስ\nህይወቴ ነው ክርስቶስ\n', 'am', 269, 0),\n(1, 'ይተካል', 'ይተካል\nይተካል እግዚአብሔር አገልጋይ ለቤቱ\nከዛሬው የሚልቅ የማይዝል ጉልበቱ\nአይሰስትምና ፀጋን በማካፈል\nብርቱውን ያስነሳል ከትውልዱ መሃል\n\nየሙሴ በረከት ደርሶዋል ለኢያሱ\nአምላክ በቃ ብሎ ሊጠራው ወደርሱ\nኢያሱን አቆመው በበረታ ጸጋ\nየነገሥታት ንጉሥ አልፋና ኦሜጋ\n\nመጎናጸፊያውን ለኤልሳ ትቶለት\nኤሊያስ ቢሄድም ቢነጠቅ በእሳት\nእጥፍ ድርብ ጸጋ ከሁሉ የሚልቅ\nአምላክ ስለሰጠው ፈጽሟል ድንቃድንቅ\n\nከእኔ ብቻ በቀር ማነው ያለው ሌላ\nትጉን ለአገልግሎት ዝናሩ ያልላላ\nእንዲህ አትበሉ እግዚአብሔር ዘገየ\nይሾማል ለቤቱ ጠላት ዓይኑ እያየ\n\nቀድሰን ዘምረን ወንጌሉን መስክረን\nወደ ሰማዩ ቤት ደሞ እንሄዳለን\nእግዚአብሔር ያስነሣል ዳግም እንደገና\nዘመኑ የዋጀ እጅጉን የጸና\n', 'am', 270, 0),\n(1, 'ተመስገን', 'ተመስገን\nተመስገን\nለምስጋና ስላሰባሰብከን\nእግዚአብሔር ተመስገን\n\nሁሉን ስሰጠን ያለ ዋጋ ነው\nግን ምንዘምረው ተደርጎልን ነው\nበነፃ አይደለም የምናዜምልህ\nተቀብለን ነው ወስደን ነው ከእጅህ\nተመስገን ነው የአንተ እጅ ሲሰጥ\nተመስገን ነው ሰቶ እንዳልነበር ነው\nተመስገን ነው የዃላን አይሰፍርም\nተመስገን ነው ወስዶ ነበር አይልም\n\nለሁሉም ፀሐይ ቀን የምታወጣ\nድሃን አትንቅም ገንዘብ ስላጣ\nባይኖረው እንኳን በአንተ ይኖራል\nቆርሰህ ስሰጠው ተመስገን ይላል\nተመስገን ነው ክብርህ አይጓደል\nተመስገን ነው በሰማይ በምድር\nተመስገን ነው የድሃ አደጉ አባት\nተመስገን ነው ደጉ እግዚአብሔር\n\nውጊያን ለራስህ ለእኛ ድል ሰተህ\nከክብር ሰገነት ታኖረናለህ\nጠላት እያየ ዘይት የምትቀባ\nፅኑ ግንብ ነህ መጠጊያ አንባ\nተመስገን ነው በመልካምነትህ\nተመስገን ነው ያላሰብከው ማነው\nተመስገን ነው ከአንተ ያገኘነው\nተመስገን ነው ቆጥረን አንጨርሰው\n\nበስደት ሀገር ወተን እርቀን\nአንተን ለመማር ሰበሰብከን\nየእኛ የምንለው ባይኖረን እኛ\nአንተ አለኸን ብርቱ መፅናኛ\nተመስገን ነው በማለዳ አውጥተህ\nተመስገን ነው ሰርክ የምትመልስ\nተመስገን ነው መልካም እረኛነህ\nተመስገን ነው ኢየሱስ ክርስቶስ\n\nበጌታ ድጋፍ የቆመ ሰው\nምድር ገፍትራ ጠልፋ አትጥለው\nየሺውን ታሪክ በቀን ይሰራል\nሁሉን በሚችል ሁሉን ይችላል\nተመስገን ነው ሌላ ምን ይባላል\nተመስገን ነው ለአንተ ምን ይሰጣል\nተመስገን ነው ሁሉን አሳለፍከው\nተመስገን ነው አዲስ አደረከው\n', 'am', 271, 0),\n(1, 'አጋጣሚ አይደለም', 'አጋጣሚ አይደለም\nአጋጣሚ አይደለም መትረፌ መዳኔ\nየጌታ ተአምር ነው እረ ይገርማል የእኔ\nሞት እንቅልፍ ሆነልኝ ጭንቀቴ ቀለለ\nየረዳኝ ጌታ ነው ውዴ እየተከተለ\n\nማን ነው በዛ በረሃ\nያበላኝ መና ያጠጣኝ ውሃ\nማን ነው የደገፈኝ\nጥልቁን ሸለቆ ያሻገረኝ\nአንተ ነህ ለእኔ እናት አባቴ\nንጹህ ወዳጄ ስጋ እና አጥንቴ\nአይኔ አይነቀል ከዙፋንህ\nፊት አያዞርም ፍቅር አይንህ\n\nወሮኝ ድቅድቅ ጨለማ\nተስፋዬ መቅኖ ልቤ ሲደማ\nአይቶኝ ሲፈስ እንባዬ\nደመና ጠቅሶ መጣ ጌታዬ\nፀሀይ ነው እና የብርሃን አምዴ\nኢየሱስ ለእኔ ህይወት መንገዴ\nአልተሸነፍኩም ውዴ አግዞኛል\nመቃብር ደፎኖ ህይወት ሰጥቶኛል\n\nሲለይ ነፍሴ ከስጋ\nበጨለማ ቀን በክፉ አደጋ\nዳንኩኝ ሞት እያየኝ\nየንሰሃ እድሜ ጨመረልኝ\nበጽድቄ አይደለም የተረፍኩት\nበእሱ ፍቅር ነው በእሱ ምህረት\nብቻዬን ሆኘ ሁሌ የማለቅሰው\nእየበደልኩት ስላዳነኝ ነው\n\nሞት ሆይ መውጊያ የታለ\nብሎ ጥሎኃል እየታገለ\nሲኦል ድል መግዛትህ\nባዶ ቀርተሃል ተበዝብዘህ\nበእራሱ መንግስት ፈጥሮኝ በዓላማ\nየልጁን ህይወት ማንም አይቀማ\nመቃብር ያርፋል በአገልግሎቴ\nተከፍቶልኛል ደጁ የአባቴ\n', 'am', 272, 0),\n(1, 'በልዕልና', 'በልዕልና\nበልዕልና ያለ በልዕልና\nዓለቴ የነፍሴ ዋስትና\nአንተ ነህ ጉልበቴ መታመኛዬ\nእግዚአብሔር ኃይሌ መከታዬ\n\nበለመለመ መስክ የምታሰማራኝ\nከእረፍቱ ውኃ የምታጠጣኝ\nእርካታዬ መኖርያ አገሬ\nታመሰግናለች ነፍሴ በዝማሬ\n\nየምታመንብህ መደገፈያዬ\nከጠላቴ ቀስት መሸሸጊያዬ\nያለኸልኝ የማላጣህ ዕድሌ\nልዘምር ልቀኝ ላመስግንህ ሁሌ\n\nሰማይ ነው ዙፋንህ መረገጫህ ምድር\nየደስታዬ ምንጭ ምስጉን ክብር\nዝም አልልም ዘወትር አዜማለሁ\nባንተ ተማምኜ መች አፍሬ አውቃለሁ\n\nበለመለመ መስክ የምታሰማራኝ\nከእረፍቱ ውኃ የምታጠጣኝ\nእርካታዬ መኖርያ አገሬ\nታመሰግናለች ነፍሴ በዝማሬ\n', 'am', 273, 0),\n(1, 'መሸሸጊያዬ ነው', 'መሸሸጊያዬ ነው\nመሸሸጊያዬ ነው ያደረገልኝን ተመልከቱ\nከእንባ ሸለቆ ይህው ወጣው በምህረቱ\nየእግዚአብሔር ልጅ ሆነን ሞገስ\nተመስገን በሉ ይክበር ይንገስ\nየድንግል ማርያም ልጅ ሆነን ሞገስ\n\nብቻዬን ነኝ ብዬ እንባዬን አልዘራም\nማምለጫ ግንቤ ነው ጌታዬ የአንተ ስም\nማለፍ ሆኖልኛል በስንጥቅ አለት\nአንተ ስላለህኝ ጌታ የኔ አባት\n\nይስሃቅ ከእናቱ ሞት በብርቱ ተፅናና\nለኔ ያለህ እድል ሰናይት ናትና\nእንደ እናት አጉራሽ ነህ ደግሞም ፅኑ አፍቃሪ\nክንድህ ነው ለቤቴ የመንገዴ መሪ\n\nአማርሬ አላውቅም በሆነብኝ ሁሉ\nእግዚአብሔር ወዳጄ ታማኝ ነው ለቃሉ\nነገን አይቶልኛል የድሌን ከፍታ\nስሙ ይንገስልኝ የሰራዊት ጌታ\n\nመንገድ የወደቀ ድጋፍ ያጣውን ሰው\nያላንተ ወዳጄ ተስፋ ማን ሊሆነው\nየደካማው ምርኩዝ የደሃ አደግ አባት\nጣትህ ስትዳሰሰኝ ተነሳው ከውደቀት\n', 'am', 274, 0),\n(1, 'እንደ ምሕረትህ', 'እንደ ምሕረትህ\nእንደ ምህረትህ ብዛት ማረኝ\nመተላለፌን ደምስስልኝ\nአንተን ብቻ በደልኩኝ\nትእዛዝህን ተላለፍኩኝ\n\nእጅግ በዛ የኔ ኃጢያት ከፀጉሬ\nበመቅደስ እጮሀለሁ አቀርቅሬ\nአትቅጸፈኝ በመአትህ አትገስፀኝ\nጌታዬ ሆይ የማዳንህን ደስታ ስጠኝ\n\nእንደማውቅህ በአደባባይ ምን ብናገር\nስራዬ ግን ይህን እውነት አይመሰከር\nከእልፍኝህ ብሄድ ርቄ ከአንተ ፍቅር\nሁሉን ከሰርኩ አላተረፍኩ አንዳች ነገር\n\nማን እንደኔ ከትውልዱ የበደለ\nመኃሪ አምላክ ከአንተ በቀር ወዴት አለ\nየዳዊት ልጅ ማረኝ ብዬ እጮሀለሁ\nእያነባሁ በጉልበቴ እሰግዳለሁ\n\nበመዳፈር እንደ አፍኒንና እንደ ፊንሀስ\nሰውነቴን አቆሸሽኩኝ ያንተን መቅደስ\nአሳልፈህ እንዳትሰጠኝ ለኃጢአቴ\nእንደ ቀድሞ ልጄ በለኝ ደጉ አባቴ\n', 'am', 275, 0),\n(1, 'አማኑኤል ተወለደ', 'አማኑኤል ተወለደ\nአማኑኤል ተወለደ\nዓለም ነጻ ወጣ ጠላት ተዋረደ\nምድር ነፃ ወጣች ጠላት ተዋረደ\n\nከራድዮን ጌታ ስሙ ድንቅ መካር\nበከብቶቹ ስፍራ ታይቶናል በፍቅር\nዓለምን ማረከ በበረት ተኝቶ\nድንገት በብርሃን የሰውን ልጅ ሞልቶ\n\nበጨርቅ ተጠቅልሎ እንስሳት ሲያሞቁት\nተገኝቷል ኢየሱስ በከብቶቹ በረት\nእንደ ተርሴስ ንጉሥ ይዘናል አመሃ\nስላየን ተወልዶ የሕይወታችን ውሃ\n\nከዋክብትን የሚቆጥረው አማኑኤል ሊቆጠር\nወርዷል ቤተልሔም ከእናቱ ጋር ሊያድር\nያ ደገኛ ትንቢት ታይቶናል ማዳኑ\nየመጎብኘት ዕለት መጥቶልናል ቀኑ\n\nእስከ ቤተልሔም መርቶናል ኮከቡ\nዛሬም እንዲሰበክ የፈውስ ረሃቡ\nታዖስ ተገለፀ አዳኙ ማስያስ\nበርስታቸን ቆመን ልንል ሥሉስ ቅዱስ\n\nማያት አፍላጋቱን በእፍኙ የሰፈረ\nየሰው ሥጋ ለብሶ በማርያም አደረ\nክብር ለእግዚአብሔር በአርያም ሆነ\nሰላምም ለሰው ልጅ በምድር ተወሰነ\n', 'am', 276, 0),\n(1, 'እንደምን በረታች', 'እንደምን በረታች\nእንደምን በረታች ዳነች ሰዉነቴ\nብትወደኝ እኮ ነው አቤት መድኋኒቴ\nይህቺን ዓመት ደግሞ አንተ ብትተውኝ\nወዳጄ መዉደድህ ፍቅርህ አስለቀሰኝ\n\nየአህዛብን ፈቃድ ያደረኩበት ቀን\nእንደምን ይቆጠር ገብቶ ከእኔ ዘመን\nካወኩህ ጀምሮ ይቆጠር እድሜዬ\nሳላውቅህ የኖርኩት የእኔ አይደል ጌታዬ\n\nየትዕግስትህ መጠን ስፋቱ ጥልቅ ነው\nሁሌም እያጠፋሁ ቃልህ የፍቅር ነው\nረቡኒ ተናገር ላድምጥ በዝምታ\nእስራቴ ይዉለቅ ስትናገር ጌታ\n\nበእኔ ዉስጥ ምሰሶ እያለ ተጋርዶ\nአይኔ ያያል የሰው የበደልን ነዶ\nአልታዘዝ ብዬ ልቤን ሳትታዘብ\nሰዉ እየከሰስኩም አደረከኝ ገንዘብ\n\nሰው ፊትን እያየ ሞገስን ሲያበዛ\nሚዛንህ ልብ ነው የዓለሙ ቤዛ\nከአገር የሰፋዉን የእኔን እዳ ምረህ\nለትንሽ ስጨክን ይቅር አለኝ ልብህ\n', 'am', 277, 0),\n(1, 'ከኃጢያተኛው ድንኳን', 'ከኃጢያተኛው ድንኳን\nከኃጢያተኛው ድንኳን ቅዱሱ ቆመሀል\nልጄ የት ናት ብለህ እኔን ፈልገሀል\nአንተ ስላለኸኝ ቀሏል መከራየ\nለኔ ያደረከው ብዙ ነው ጌታየ\n\nእንኳንስ አርገኸኝ ጌታየ ሙሉ ሰው\nእንዲሁም ይህን ነው ልቤ ሚናፍቀው\nየዘመናት ሸክም ቀረ ጉስቁልና\nየጠፋውን ልቤን አግኝተሀልና\n\nባገኘኸኝ ጊዜ ሸፍናኝ በለሷ\nከፊትህ ያነበብኩት ፈጽሞ አይረሳ\nከዚህ የበለጠ ታያለህ ምትለኝ\nአይንህ ይናገራል እንደማትረሳ\n\nምን አለኝ ብለህ ነው ደጃፌን ምትመታ\nእኔ ደካማ ነኝ አንተ ቅዱስ ጌታ\nከእንግዲህ አላርስም ምንጣፌን በእንባ\nመንጦላይቴን ከፍተህ ወደ ቤቴ ግባ\n\nእኔ እኮ አውቅሀለሁ ሁሉን ስታፈቅር\nየአናብስቱን ጉድጓድ የሞት አዋጅ ስትሺር\nእንዲህ እያለ ነው የሚቀኘው ውስጤ\nኢየሱስ ክርስቶስ ምግቤና መጠጤ\n', 'am', 278, 0),\n(1, 'ዘመን ተሰጠን', 'ዘመን ተሰጠን\nዘመን ተሰጠን ለምስጋና\nዘመን ተሰጠን ለውዳሴ\nተመስገን ስላሴ\n\nቸርነትህ ሰጠን ዘመን ለፍስሀ\nይቺም እድሜ ለእርቅ ነች ለንስሀ\nጥበባችን መቼ ሆነ እውቀታችን\nምህረትህ በዝቶልን ነው መቆማችን\nከሰጠኸን አዲስ አመት\nከሰጠኸን አዲስ እለት\nእንዘምራለን በደስታ በአኮቴት\n\nየለውም ጫፍ የለው ድንበር ያንተ ምህረት\nበእድሜያችን ጨመርክልን ይችን እለት\nተደነቅን ተገረምን ባንተ ፀጋ\nቀንና ሌት ሲፈራረቅ ክረምት በጋ\nከሰጠኸን አዲስ አመት\nከሰጠኸን አዲስ እለት\nእንዘምራለን በደስታ በአኮቴት\n\nምድር ረክታ በዝናቡ በሰማይ ጠል\nበአበባ ደምቃ ታየች በሀመልማል\nበድሜያችን ላይ ከጨመርከው ይህን አመት\nየንስሀ ይሁንልን የመፀፀት\nከሰጠኸን አዲስ አመት\nከሰጠኸን አዲስ እለት\nእንዘምራለን በደስታ በአኮቴት\n\nየእርቅ ይሁን ዘመናችን የይቅርታ\nሰላም ትሁን ሀገራችን ፍቅር ተመልታ\nመለያየት መጠላላት የሌለበት\nአድርግልን ጌታችን ሆይ ይህን አመት\nከሰጠኸን አዲስ አመት\nከሰጠኸን አዲስ እለት\nእንዘምራለን በደስታ በአኮቴት\n', 'am', 279, 0),\n(1, 'መስቀል ክብሬ ነው', 'መስቀል ክብሬ ነው\nምልክቴ ነው ከቀስት ማምለጫዬ\nመስቀል ክብሬ ነው ከክፉ መውጫዬ\n\nየእባቡ ራስ የሚቀጠቀጥበት\nበመስቀል ቤዛነት መርገም ተሻረበት\nሰው በእጸ መስቀል ከእግዚአብሔር ታረቀ\nየምሕረት ቀን ወጣ መከራው ራቀ\nኦ በመስቀል ጠላት ተቸገረ\nኦ በመስቀል ጨለማው ተሻረ\nኦ በመስቀል ደሙን አፈሰሰ\nኦ በመስቀል ሥጋውን ቆረሰ\n\nፊቴን ሰውነቴን በእርሱ አማትባለው\nበልቤ አትሜ በአንገቴ አስረዋለው\nአይሁድ በሚክዱት እኔ ግን አምኜ\nእግሩ ለቆመበት እሰግዳለሁ ድኜ\nኦ በመስቀል እስረኛ ተፈታ\nኦ በመስቀል ከሳሹ ተረታ\nኦ በመስቀል ሞትን ገደለልን\nኦ በመስቀል በሩን ከፈተልን\n\nየቤዛ ክርስቶስ የክብሩ ዙፋን ነው\nበእምነት የሚያጸና በስሙ ላመነው\nየቅድስና የሕይወት ማሕተም\nመስቀል ትምክህት ነው እስከ ዘለዓለም\nኦ በመስቀል ፍቅሩን ገለጸልን\nኦ በመስቀል ነፍሱን ለእኛ ሠጠን\nኦ በመስቀል እንባችን ታበሰ\nኦ በመስቀል ጸጋ ተለበሰ\n', 'am', 280, 0),\n(1, 'በቸርነት በይቅርታው አሰበን', 'በቸርነት በይቅርታው አሰበን\nበቸርነት በይቅርታው አሰበን\nበፍቅሩና በምሕረቱ ጎበኘን\nአምላካችን በሞቱ ወደደን\nአምላካችን በሞቱ ወደደን\n\nተነጥቆ ሰላም እረፍታችን\nላያድን ላይፈውስ ጽድቃችን\nተጥለን ስንኖር በሞት\nበደምህ ወጣን አርነት\nበደምህ ወጣን ነጻነት\n\nየጭንቀት የመከራ ዓመት\nተረሳ በኢየሱስ ሞት\nበፍጹም ፍቅሩ ወደደን\nበሞቱ ከሞት አዳነን\nበሞቱ ከሞት አዳነን\n\nህዝቡን ሲያስጨንቅ የነበረ\nየጠላት ቅጥሩ ተሰበረ\nማልቀስ ቀረልን መቅበዝበዝ\nገነት ገብተናል በእርሱ ወዝ\nገነትን ወረስን በእርሱ ወዝ\n\nሰማይና ምድር ተስማሙ\nታጥበዋልና በደሙ\nነፃነት አዋጅ ተሰማ\nአዜምን የጽድቅን ዜማ\nዘመርን የጽድቅ ዜማ\n', 'am', 281, 0),\n(1, 'መልካም ስም ይኑረኝ', 'መልካም ስም ይኑረኝ\nጌታ ሆይ በብዙ ስውጠኝ\nከመልካም ሽቱ መልካም ስም ይኑረኝ\n\nሞት ሞታለብሰውና ያቺን ዛፍ ነቅፌ\nያንተን ስም ያስጎመዠኝ እርሱ ይሁን ትርፌ\nአንተን ብቻ እንዳይ ዓይኔን ኳሰው እምነት\nአስረህ አስቀምጠኝ በፍቅር ሰንሰለት\n\nወንድሙን ሚያታልል ተረከዝ የሚይዝ\nየያዕቆብ ካባው አይታይ በኔ ወዝ\nይኑረኝ መልካም ስም ልትታገለኝ ና\nእስራኤል ሆይ በለኝ ስሜን ስውጥና\n\nበደማስቆ መንገድ አይለቅ ዘመኔ\nከሰማይ ብርሃን ያንጸባርቅ ወደኔ\nየእውነት ለውጠኝ ትችላለህ አንተ\nእንዴት ክፋ ላውጣ አንተ ለኔ ሞተህ\n\nስሜን ባገኘውም ሄጄ ጎልጎታ\nአሁንም እንዲያው ነኝ ለውጥ የለኝም ጌታ\nከሚቃጠለው ስብ ይከፋል ስም ሽታው\nአማኝ መባል ብቻ ምንድን ነው የሚጠቅመው\n', 'am', 282, 0),\n(1, 'እንደምታኖረኝ ሳስብ', 'እንደምታኖረኝ ሳስብ\n\nእንደምታኖረኝ ሳስብ\nማዳንህን ተርቤ\nዘምር አመስግን አለኝ\nየወደደህ ልቤ\n\nበቤተልሔም ርሃብ\nብሄድ ብሰደድ ሞዓብ\nበጉድለት ብገባም ቤቴ\nአልተለየኸኝ አባቴ\nየዘላለም መኖሪያ ነህ የዘላለም\nአንተን ያለ አልተረሳም አልተጣስም\n\nወዳጅነት ዋጋ አቶ\nጊዜውን ልቤ ፈርቶ\nለካስ እኔ የምኖረው\nወዳጄ ሆይ በአንተ ነው\nየዘላለም መኖሪያ ነህ የዘላለም\nአንተን ያለ አልተረሳም አልተጣስም\n\nሕይወቴ እጅግ ቢመር\nቢከፋኝ የሰው ነገር\nየጨለማውን መንጋ\nተሻገርኩ በአንተ ጸጋ\nየዘላለም መኖሪያ ነህ የዘላለም\nአንተን ያለ አልተረሳም አልተጣስም\n\nቢሸጡኝ ወንድሞቼ\nቢያርቁኝ ከሳሾቼ\nበሐሰት ሸንጎ ብታሰር\nታነሳኛለህ በክብር\n', 'am', 283, 0),\n(1, 'ቀራንዮ', 'ቀራንዮ\nቀራንዮ ቀራንዮ ጎልጎታ\nበአንቺ ምድር የዓለም ጌታ\nተጨነቀ ተሰቃየ ተንገላታ\n\nበማዕለ ምድር ዙፋን መስቀል ተክሎ\nልብስን አለበሰን እርቃኑን ተሰቅሎ\nቁስላችን ተሻረ በመከራ ቆስሎ\n\nየአማረ ልብስ የለው ደም ሆኗል ቀሚሱ\nየወርቅ ካባ የለው እርቃኑን ነው እርሱ\nበፍቅር ይገዛል ተሰቅሎ ንጉሡ\n\nየስልጣኑን በትር በእጁ የያዘው\nሳዶር እና አላዶር የበትር ሚስማር ነው\nእየቸነከሩት አላማው ፍቅር ነው\n\nሞታችንን ወስዶ ሕይወትን ሸለመ\nሕሙማንን ሊያድን ለፍቅር ታመመ\nከውድቀት ሊያነሳን ወደቀ ደከመ\nስለኛ ብለህ ተንገላታህ\n', 'am', 284, 0),\n(1, 'ምን ሊለውጠው', 'ምን ሊለውጠው\nምን ሊለውጠው ያንተን ውለታ\nምን ሊቀይረው ያንተን ስጦታ\nለዘለአለም ታትሞ የሚኖር\nማን ይስተካከላል ጌታ ያንተን ፍቅር\n\nጎብጬ ስኖር በሀዘን\nእዘራው ነበር እንባዬን\nሩህሩህ አምላኬ ደረስክና\nሰው አደረከኝ እንደገና\n\nሲሸሸኝ ሁሉም ሲርቀኝ\nሳትፀየፈኝ ቀረብከኝ\nዘይት ያፈሰስከው በቁስሌ ላይ\nወዳጄስ ማነው ከአንተ በላይ\n\nአዳም ወዴት ነህ እያልከኝ\nበፍቅር ድምፅህ ፈለከኝ\nአልብሰኸኛል ነጩን ልብስ\nእወድሀለው እየሱስ\nአከብርሀለው ክርስቶስ\n\nአልመለስም ወደ ኋላ\nአያይም አይኔ ከአንተ ሌላ\nአልፈራም የጠላትን ዛቻ\nአድነኸኛል አንተ ብቻ\nሞተህልኛል አንተ ብቻ\n', 'am', 285, 0),\n(1, 'ተናገር አለኝ', 'ተናገር አለኝ\nተናገር አለኝ መስክር\nተናገር አለኝ ዘምር\nለቀራንዮ ውለታ\nአርምሞ የለም ዝምታ\nለመድኃኔዓለም ውለታ\nአርምሞ የለም ዝምታ\n\nሰው አድርጎኝ ሞቶ በደሙ\nኑሮዬን ባርኮት ሕመሙ\nሰላም አውጥቶ ካስገባ\nልያዝ ለክብሩ ዘንባባ\nሆሳዕና ልበል መድኃኒት\nከፍ በልልኝ የኔ አባት\nተጠምተኸ እኔ ረካሁ\nስራህ ግሩም ነው ደነቀኝ\n\nእጆቹን እዩት በእምነት\nቆሰለ ሊሰጠኝ ሕይወት\nበዚያ ታትሞ ውበቴ\nእየሱስ ለኔ ብርታቴ\nከማንም በላይ ከምንም\nለኔ ልዩ ነው ዘላለም\nሕይወቴን ለእርሱ አስማርኬ\nእኔስ በረታሁ በአምላኬ\n\nየእሾህ አክሊሉ በራሱ\nለእኔ ቤዛ ነው ሞገሱ\nሞቴን ገድሎታል አባቴ\nሰላሜ እርሱ ነው እረፍቴ\nሰው የመሆኔ ምስጢሩ\nየማይለወጥ ነው ፍቅሩ\nየገባኝ እውነት በምድር ላይ\nፍቅር ነው ጌታ ኤልሻዳይ\n\nክብሩን ለማወጅ ተነሳሁ\nሲያድነኝ ከሞት እያየሁ\nገመና ሸፋኝ ኪዳኔ\nተራበ ውዴ መድኃኔ\nይሄ ነው የቆመኝ በፊቱ\nወሰን የሌለው ምሕረቱ\nለዚህ ደግነት ውለታ\nምን ይከፈላል ለጌታ\n', 'am', 286, 0),\n(1, 'ማረን አምላካችን', 'ማረን አምላካችን\nአንተ የሰላም ንጉስ መልካሙ እረኛ\nእግዚአብሔር ብቻ ነው እውነተኛ ዳኛ\nእንባችንን አብስ ይብቃ ሀዘናችን\nእጃችንን ሰጠን ማረን አምላካችን\n\nየኢትዮጵያን ትንሳኤ ዘመናት ናፍቀናል\nክንዳችንን ሳይሆን ስምህን አምነናል\nበወደድከው ግዜ ሰላም እንደሚሆን\nየቀደመው እባብ ይቀጥቀጥልን\n\nእውነት ነው ጌታችን በዝቷል በደላችን\nአክሊላችን ወድቋል ተገፏል ፀጋችን\nበእርኩሰት ስንጠፋ ተላልፈን ህግህን\nበአባታዊ ፍቅርህ ማረን ልጆችህን\n\nአንድስንኳ የለም ፅድቅን የሚያወራ\nየገዛ ክንድህ ነው ተአምር የሚሰራ\nእንዳንጠፋፋ እንዳንነቃቀስ\nየእጅህ ስራ ሁሉ በስምህ ይፈወስ\n', 'am', 287, 0),\n(1, 'ታላቅ መሆን የፈለገ', 'ታላቅ መሆን የፈለገ\nታላቅ መሆን የፈለገ እንደ ታናሽ ይሁን\nእራሱን ከፍ በማድረግ እንዳያጣ ክብሩን\n\nከፊት እኔ ልቅደም አትበል እኔ ብቻ\nዋጋን እንዳታጣ ሮጠህ በጥላቻ\nኢያሱን ተክቷል ሙሴ በአገልግሎት\nእውነተኛ መሪ እውነተኛ አባት\nከሰማይ ወርዶ የሐዋርያትን እግር ያጠበው\nለእኛ አርአያና ትምህርት ምሳሌ ሊሆን ነው\n\nአንድ ሲሆን ጌታ ጸጋው አይቆጠር\nክብሩን እንመስክር በሰላም በፍቅር\nዲያብሎስ ተዋርዶ ከጥልቅ የተጣለው\nከእኔ በላይ ሌላ የለም ስላለ ነው\nከሰማይ ወርዶ የሐዋርያትን እግር ያጠበው\nለእኛ አርአያና ትምህርት ምሳሌ ሊሆን ነው\n\nእግዚአብሔር ሲሰጠ ለወንድምህ ጸጋ\nልክ አይደለም አትበል እንዳታጣ ዋጋ\nማታ የመጣውም አገልጋይ ነውና\nከእኔ ተስተካክሏል በማለት አትቅና\nከሰማይ ወርዶ የሐዋርያትን እግር ያጠበው\nለእኛ አርአያና ትምህርት ምሳሌ ሊሆን ነው\n\nእንደ ሕጻናት ስንሆን የማንሻ ክብርን\nበደስታ ያወርሰናል ክርስቶስ መንግስቱን\nጠቢብና አስተዋይ ልባም የሚባለው\nወንድሙን የሚያስብ የሚያስበልጥ ሰው ነው\nከሰማይ ወርዶ የሐዋርያትን እግር ያጠበው\nለእኛ አርአያና ትምህርት ምሳሌ ሊሆን ነው\n', 'am', 288, 0),\n(1, 'እግዚአብሔር የወደቁትን ያነሳል', 'እግዚአብሔር የወደቁትን ያነሳል\nእግዚአብሔር የወደቁትን ያነሳል\nየተረሱትን ያስታውሳል\nየተናቁትን ያከብራል\n\nአንተ በክብር ላይ ክብርን ስትጨምር\nእረኛው ይሾማል በንጉሱ ወንበር\nጌታ ትወዳለህ የተናቁትን\nአንተ ልብን እንጂ አታይም ፊትን\n\nሳሙኤልን ልከህ ጠርተህ ትቀባለህ\nየአንበሶቹንም አፍ አንተ ትዘጋለህ\nበጌርጌሴኖን በመቃብር ስፍራ\nአየሁ ጌታዬ ለሰዎች ስትራራ\n\nጠላታችን ደርሶ ቢያስጨንቀንም\nትሞታለህ ብሎ ቢዝትብንም\nበሃሰት ቢጥለን ከመከራ ቤት\nበእግዚአብሔር ቸርነት ወጣን ከእስራት\n\nይደግፋል ክንድህ የተናቁትን\nከሰው በታች ሆኖ የሚኖሩትን\nደስታም ትሰጣለህ ሃዘን አርቀህ\nአይቀርም አልቅሶ አንተን ያመነህ\n', 'am', 289, 0),\n(1, 'ይቅር ስላልከኝ ነው', 'ይቅር ስላልከኝ ነው\nይቅር ስላልከኝ ነው የእኔ መቆም፣\nደግሞ እንዳልፈርድ እርዳኝ በሰዎች ድካም።\n\nለዛሬ መድረሴ አይደል በጽድቄ፣\nእያነሣኸኝ ነው ዓይተህ ወድቄ፣\nበፈረድኩበት ፍርድ እንዳይፈረድ፣\nአልሁን ፈሪሳዊ ወንድሜን ልውደድ።\nጉድፉን አልይ የወንድሜን በደል፣\nአለ በእኔ ላይ ምሰሶን የሚያህል።\n\nባታለብሰኝ ኖሮ ነውሬን ሸፍነህ፣\nባታቆመኝ ኖሮ በደሌን ከድነህ፣\nበጠፋ ነበር ስም አጠራሬ፣\nድካሜ ብዙ ነው እንደ ራስ ጠጉሬ።\nጉድፉን አልይ የወንድሜን በደል፣\nአለ በእኔ ላይ ምሰሶን የሚያህል።\n\nበምሕረትህ ብዛት ከቤትህ ልግባ፣\nዘወትር ላቅርብልህ የእንባዬን መባ፣\nየውስጤን ማንነት ለአንተ ልግለጥ፣\nለሰው አሳልፈህ ለማትሠጥ።\nጉድፉን አልይ የወንድሜን በደል፣\nአለ በእኔ ላይ ምሰሶን የሚያህል።\n\nዕለት ዕለት ግብሬ ኃጢአቴ መሥራት ነው፣\nአንተ ዕለት ዕለት እኔን መማር ነው፣\nየበደለን መተው የአንተ ነውና፣\nበወንድሜ መማር ቆሜ አልቅና።\nጉድፉን አልይ የወንድሜን በደል፣\nአለ በእኔ ላይ ምሰሶን የሚያህል።\n', 'am', 290, 0),\n(1, 'እንዳላጠፋ ሰው', 'እንዳላጠፋ ሰው\nእንዳላጠፋ ሰው በሰው ፊት ምታየው\nጌታዬ ባንተ ነው ገመናዬ የተሸፈነው\n\nቀራንዮ ቆመህ በመስቀሉ ዙፋን\nበሰው ፊት ዓለሙን ስታድን\nእርቃንህን ስትሆን ነውሬ ተሸፈነ\nበቆሰልከው ቁስል ለኔ መዳን ሆነ\n\nሃጢያትን የምትከድን ነህ ከባቴ አበሳ\nየናዝሬቱ መልካም የይሁዳ አንበሳ\nማለዳ ማለዳ ሃጢያቴን ብትቆጥር\nዛሬ እንዴት እቆም ነበር\n\nከሳሾቼ አፈሩ ድንጋይን የያዙ\nአንተ ስትምረኝ ሄዱ እየተከዙ\nበሰላም ሸኘኸኝ አድነኸኝ ከሞት\nበፍቅርህ ሸፍነህ ያለፈውን ሃጢያት\n\nአልፀዱም እጆቼ ከበደል ከጥፋት\nአንደበቴ አብዝቷል ሽንገላና ሃሰት\nእንዳላየህ አለፍክ አንዳች እንዳልሰማ\nቃላት አይገልፀውም ለኔ ያለህማ\n', 'am', 291, 0),\n(1, 'ወረት የሌለው', 'ወረት የሌለው\nወረት የሌለው መውደድ\nወረት የሌለው ፍቅር\nአንተ ጋር ብቻ ነው\nያለው እግዚአብሔር\n\nዘመን የማይዘው ጊዜ የማይገድበው\nያንተ ፍቅር ብቻ ቀን በቀን አዲስ ነው\nከዴማስ ጋር ስሄድ ትቼው የአንተን መንገድ\nከቶ መች ቀነሰ ለእኔ ያለህ መውደድ\n\nበአመጽ ብጠፋም ከመንጋህ መካከል\nይመሻል ይነጋል እኔን ስትከተል\nእንደወጣ ይቅር ብለህ መቼ ተውከኝ\nሴኬም ድረስ ወርደህ ልጅህን ፈለከኝ\n\nበዝናዬም ዘመን ባለጸጋ እያለሁ\nቤቴ በወዳጆች ቀን በቀን ሙሉ ነው\nእንደ ጤዛ ሲረግፍ ሃብትና ንብረቴ\nያላንተ ማን ነበር በፈረሰው ቤቴ\n\nየታመንኩባቸው ወዳጆች ሲከዱኝ\nሕመሜ ስር ሆነው ደጋግመው ሲወጉኝ\nላንተ ጊዜ ባጣም ለኔ ጊዜ አለህ\nገፋህ ክፉ ቀኔን ከኔ ጋራ አብረህ\n', 'am', 292, 0),\n(1, 'ያከበርከኝ', 'ያከበርከኝ\nያከበርከኝ እኔ ማነኝ\nያስከበርከኝ እኔ ማነኝ\nውለታህ በዛ አባቴ ውለታህ በዛ\nሞገስ ከበባት ቅጥሬ ሆንከኝ መዓዛ\n\nማዕበሉ አለፈ ባንተ ያለኝ አላሳልፍ\nስኬቴን ጻፈው ጣትህ የመኖሬን መጽሐፍ\nቃልህ ባያዘው ጭንቄን ባያደላድለው\nዓለም ትለኝ ነበር እኔን መድረሻ የሌለው\n\nቀን አየች ነፍሴ ባንተ ከመሶብህ በልታ\nከእሳት ማዕበል ነጥቀህ አኖርካት በከፍታ\nቀን በቀን ቅኔን ይዤ በፊትህ የምጓደደው\nሚዛንህ ጸጋ ሞልቶት በፍቅርህ ከብሬ ነው\n\nበወኅኒ ብርሃን ሞላ ሰንሰለቱ ቀለጠ\nበድካሜ እየራራ ሞት በሞትህ ተዋጠ\nስላንተ ማን አወቀ ጠንቅቆስ ማን ተረዳ\nእኔ ግን ቀምሼ ነው የምለው ማራናታ\n\nመፍረድ የማይሰለቻት ምድሪቱ ከሳሽ ሆና\nሲገርማት ውሎ ያድራል ስሰለፍ ለበገና\nየዘንዶው ጥርሱ ሲፏጭ ጉድጓድ እየተማሰ\nበምሥጋናዬ ብቻ ኑሮዬ ተዳበሰ\n\nያህዌን ያለ ሲወድቅ ማን አለ የከሰረ\nአያይም ዓይኔ ጉድለት ይኖራል እየዘመረ\nኑሃሚን እንዳየችህ በእንባ ማዕበል ሆና\nማግኘት ይመጣል ፈጥኖ አላዝንም በፈተና\n', 'am', 294, 0),\n(1, 'በማይነገር ስጦታ', 'በማይነገር ስጦታ\nበማይነገር ስጦታ በማይከፈል ውለታ\nለዘላለም አዳንከኝ\nእግዚአብሔር ተመስገንልኝ\n\nስኖር በሞት ጥላ ነፍሴ ከክብር ጎላ\nኪዳንህን አሰበህ መጣህ ወደ ልጅህ\nቃል የለኝም የሚችል ያንተን ሃይል የሚገልጥ\nአወራለው ለትውልዱ እንደዳነ ሞተህ አንዱ\n\nካቀረቀርኩበት ከሃጢያት ሸለፈት\nገዛኸኝ በዋጋ አስፈሪው ሌት ነጋ\nአሁን ባንተ ነፃ ነኝ ፍፁም ሸክሜ ቀሎልኝ\nማዳንህን አውጃለው ቀና አርገኸኝ ቀን ስላየው\n\nቀረ በሃዘኔ ሰላለህ መድህኔ\nአፈረ ጠላቴ ባንተ መድሃኒቴ\nምን እላለው ምን አለኝ ፍቅርህ ከቃል ገዝፎብኝ\nበሁኔታ ማትለካ አንተ ብቻ ምታስነካ\n', 'am', 295, 0),\n(1, 'እንግዲህ ምን ልበል', 'እንግዲህ ምን ልበል\nእንግዲህ ምን ልበል\nእንግዲህ ምን ላውራ\nእጄን በአፌ አስጫነኝ\nየአማኑኤል ስራ\n\nበሞት ጥላ ምድር ያሳለፈኝ መርቶ\nደግሞም ዛሬ አነሣኝ በልጁ ሞት ጠርቶ\nክብሬን ለማይረባ ነገር አልለውጥም\nከአመድ ስላነሳኝ ክብሩ ለዘለዓለም\n\nየሺሖርን ውኃ ለምን እጠጣለሁ\nፊቴን የማዞረው ምን አግኝቼበት ነው\nሁልጊዜ እየራራ ሳይዘነጋኝ ላፍታ\nእኔ የዓይኑ ስስት እርሱ የኔ ርካታ\n\nስለምን ሆምጣጣ ፍሬ አፈራ ብለህ\nእኔ አልተነቀልኩም ስለፍጹም ፍቅርህ\nቢቀላ እንዳለላ ነጣ እንደባዘቶ\nየተከፋው ልቤ ሄደ ተደስቶ\n\nከወዜ ላይ ቀለብ ምናልባት ቢሰፍሩ\nወራቶቼ እንባን መከራን ቢያዘሩ\nልቤን ያስነከሰው ያ ቀን አለፈና\nየበፍታዬን ኤፋድ ለበስኩ እንደገና\n', 'am', 296, 0),\n(1, 'ምን ብትወደኝ ነው', 'ምን ብትወደኝ ነው\nምን ብትወደኝ ነው ምን ብታስበኝ\nአዲስ ዘመንን ቀን ያሳየኸኝ\nኦ አምላኬ ዘመንን ካየሁ ከተሻገርኩኝ\nኦ ጌታዬ እዘምራለሁ ስቡህ እያልኩኝ\n\nጠዋትም የለኝ ካንተ በቀር ማለዳዬ ነህ\nማምሻዬም አንተ አልሻገርም አንተ ካልፈቀድህ\nማዕበል ወጀቡን አሳልፈህ ጨለማውን አብርተህ\nበአዲስ ዘመን ጌታዬ ስራኝና\nላገልግልህ በዜማዬ እንደገና\n\nአልፍ እንድትሆን አንተ የባረካት ከመሬት ወድቃ\nትላንትናዬን ወዜን ባርከኸው ለዚህ ብበቃ\nባጌጠችው የምድር መሀል ሆኜ\nእቀኛለሁ ስለአዳኜ\nበአዲስ ዘመን ጌታዬ ስራኝና\nላገልግልህ በዜማዬ እንደገና\n\nፍሬ ፈልገህ መጣህ ወደኔ በብርሀን ጸዳል\nፀሐይ አውጥተህ ልትባርከው ጌታ ፈቅደሀል\nያንተ ወንዞች ውሃ ከተሞሉ\nተራራዎችም ምስጋናህን ያመጣሉ\nበአዲስ ዘመን ጌታዬ ስራኝና\nላገልግልህ በዜማዬ እንደገና\n\nማለፍ በክንድህ አዲስ ዘመንን ላንተ መዋጀት\nግዛው ዘመኔን ውረስ አምላኬ የኔን ማንነት\nአዝማናቱ ስራህን እያሳየ\nልሁንልህ ከዓለም የተለየ\nበአዲስ ዘመን ጌታዬ ስራኝና\nላገልግልህ በዜማዬ እንደገና\n\nቀንን ብቆጥር ዘመን ባሰላ ካልተለወጥኩኝ\nከጸጋህ ዙፋን በዕምነት ቀርቤ ካልተፈወስኩኝ\nምን ሊረባኝ ካንተ ጋር ካላረጀሁ\nያለቃልህ በዘመን እንዲያው ባውጀው\nበአዲስ ዘመን ጌታዬ ስራኝና\nላገልግልህ በዜማዬ እንደገና\n', 'am', 297, 0),\n(1, 'እኔ አላዝንም', 'እኔ አላዝንም\nእኔ አላዝንም አንተ እያለኸኝ አልከፋም\nእናት አባት ዘመዴ አንተ ነህ የኔ ተስፋ\n\nለሚወድህ ለሚያገለግልህ\nለጠራኸው ጌታዬ እንደሃሳብህ\nቢያስጨንቅም ነገር ለበጎ ነው\nቢያስተክዝም ፍጻሜው መልካም ነው\nአሜን ይሁን አንተ የወሰንከው ለእኔ የፈቀድከው\n\nከእናንተ በላይ የምታጽናናኝ\nከአባት በላይ አቅፈህ የምትስመኝ\nየወለድከኝ በጽኑ መከራ\nያሳደከኝ በመስቀልህ ስራ\nስላለኸኝ ኢየሱስ ሰላሜ ተጽናናሁ ደግሜ\n\nአላነባም ሰው የለኝም ብዬ\nየሻትከውን ስትሰራው ጌታዬ\nየኔም ጉዞ ወዳንተ ነውና\nመሰብሰቤ ከቶ አይቀርምና\nላመስግንህ ስለሆነው ሁሉ እግዚአብሔር ኃያሉ\n\nያጣሁትን በእጥፍ ትተካለህ\nሸለቆዬን ደስታ ትሞላለህ\nየፍቅርህ እጅህ ከዓይኔ በታች አርፏል\nእያበሰ እንባዬን አንጥፏል\nዘምራለሁ ይኸው እንደገና ሁሉም አልፏልና\n', 'am', 298, 0),\n(1, 'የለውም ደም ግባት', 'የለውም ደም ግባት\nየለውም ደም ግባት\nአይተን እንድንወደው\nበሰው የተናቀ\nሆነ የሕማም ሰው\n\nበወዳጆቹ ቤት የቆሰለው\nቁስል ይታያል በእጆቹ\nበገነት መካከል የተመላለሱት ደምተዋል እግሮቹ\nንጉስ ሆይ እያሉ ይዘብቱ ነበር የእሾህ አክሊል ደፍተው\nሁሉን የሚያየውን የአማኑኤልን ዓይኑን በጨርቅ አስረው\nበሚሸልቱት ፊት እንደማይናገር\nእንደ የዋሁ በግ ዝም አለ እግዚአብሔር\n\nለማህበረ አይሁድ አሳልፎ ሊሰጥ ጌታውን በብር\nህዝቡ በሌለበት ምቹ ጊዜ ይሁዳ ይፈልግ ነበር\nወርቅ ወይም ብር ነሐስ አትያዙ ብሎ እንዳላስተማረው\nጨካኙ ይሁዳ የዘላለም ምግቡን በገንዘብ ቀየረው\n\nሊቀ ካሕናቱ በካህናቱ\nፊት ቀረበ ለፍርድ\nንጹህ መስዋዕት ሆኖ መስዋዕት ተቀበለ ሞትን ሊያስወግድ\nፍቅር የአምላክን ልጅ ከዙፋኑ ስቦት እስከ ሞት ደረሰ\nወራሽ እንድንሆን ስጋውን ቆረሰ ደሙን አፈሰሰ\n\nሁሉን የሚመግብ ሁሉን የሚያረካ ለሁሉ የሚያዝነው\nበወንበዴ መሐል በመስቀል ላይ ሆኖ ተጠማሁ አላቸው\nሐሞት ለመብሉ ሆምጣጤ ለጥሙ አይሁድ አቀረቡ\nየተጨነቀች ነፍስ የተራቆተች ነፍስ ነበር ጥም ርሃቡ\n', 'am', 299, 0),\n(1, 'አላሰበብኝም ኃጢአቴን', 'አላሰበብኝም ኃጢአቴን\nአላሰበብኝም ኃጢአቴን\nአልቆጠረብኝም በደሌን\nበምህረት ዓይኖቹ ሁሌ ያየኛል\nጌታ በፍቅር ልቡ ይወደኛል\n\nትቼው ወጥቼ ይመቸኝ ብዬ\nበኋላ ሳዝን ሳለቅስ ቁጭ ብዬ\nበደሌን አይቶ ሳይፀየፈኝ\nልጄ ነው ብሎ በፍቅር አቀፈኝ\n\nስደክም ስዝል ስኖር በኃጢአት\nከእርያ ጋር ስመኝ መብላት\nለእግሮቼ ጫማ ለእጆቼ ኀምባር\nአደረገልኝ ድንቅ ነገር\n\nአዘኔን ሽሮ ሆነኝ ደስታ\nከአፌ ሞላ ሳቅና እልልታ\nቸር ሰው ውዳጅ ነው ሁሉን አፍቃሪ\nእንደርሱ ማነው ይቅርባይ ማሪ\n\nሁሉን አየሁት ሁሉን መዘንኩት\nየነፍሴን ቤዛ ጌታን ወደድኩት\nይራራልኛል ከቶ አይጥለኝም\nከርሱ የሚበልጥ አባት የለኝም\n', 'am', 300, 0),\n(1, 'በእንባዬ የማመልክህ', 'በእንባዬ የማመልክህ\nበእንባዬ የማመልክህ ጌታዬ\nከክፉ ቀን መወጫ አንባዬ\nኀዘኔን በደስታ ለውጠው\nአንተን በመታመን ልለፈው\n\nበእናቴ ማህፀን እያለሁኝ ገና\nየተደገፍኩብህ አምላኬ ነህና\nአውጣኝ ከመከራ እያልኩኝ ቀን ሌሊት\nምንጣፌን ዘወትር በአንባዬ አራስኩት\n\nየምትታመነው ሁልጊዜ ምትጠራው\nእያሉ ሲወቅሱኝ አምላክህ ወዴት ነው\nለአፌ ምግብ ሆነኝ የማነባው እንባ\nእባክህ አምላኬ ወደ ረፍቴ ልግባ\n\nእስክትጎበኘኝ ከሰማዩ መቅደስ\nማዳንህን እስካይ እንባዬ እስኪታበስ\nሳታቋርጥ እንባን ታፈሳለች ዐይኔ\nእንደቀድሞ ይሁን ይታደስ ዘመኔ\n\nከአንደበቴ ጠፍቷል የጽዮን ዝማሬ\nበባቢሎን ምርኮ ሳለው አቀርቅሬ\nበዚያ የማረኩን ፈጥነን እንድንዘምር\nእንዴት ይቻለናል በባዕዳን ምድር\n', 'am', 301, 0),\n(1, 'እንዴት ብለህ ተገኘህ', 'እንዴት ብለህ ተገኘህ\nእንዴት (2) ብለህ ተገኘህ እኔ ቤት (2)\nእንዴት አልሰለቸህ መተኛት ከበረት (2) እንዴት\n\nአበሰሩን መላእክቱ ተወለደ ሂዱ እያሉ\nግርግም መሃል ተጠቅልሏል የምስራች ለዓለም ሁሉ\nተነስቼ ገሰገስኩኝ ከበጎች ጋር ከበረት\nየማይንቀኝ መድሃኒቴን አይኔ አየችው በሌሊት\nቀና ስል ከሰማይ ኮከብ ይመራኛል\nየፍቅህ መዓዛ ልቤን ይጠራኛል\nእንደ አጭሩ ቀራጭ ሾላ ላይ ብወጣ\nከቤቴ ሊገባ መምህሩ መጣ እንዴት\n\nፈሪሳዊው ሲጸየፈኝ አመንዝራ ቀራጭ ብሎ\nአልፎኝ ሲሄድ ያ ሌዋዊ ተጸይፎ ተነጥሎ\nአግሬን ሲያጥብ ተመልከቱ በኔ ምትክ ሲሰቀል\nይሄን ብርቱ ፍቅር እዩ ዓለም ሁሉ ጉድ ይበል\nቀና ስል ከሰማይ ኮከብ ይመራኛል\nየፍቅህ መዓዛ ልቤን ይጠራኛል\nእንደ አጭሩ ቀራጭ ሾላ ላይ ብወጣ\nከቤቴ ሊገባ መምህሩ መጣ እንዴት\n\nእኔ ማን ነኝ የምትገባ ከጣሪያዬ ከቤቴ ስር\nእሰማለሁ እድናለሁ ጌታዬ ሆይ ቃል ተናገር\nአቴርሳታ የኔ ገዢ የኑሮዬ የመንገዴ\nየማይቀሙኝ በጎ እድሌ እኔ ባንተ መወደዴ\nቀና ስል ከሰማይ ኮከብ ይመራኛል\nየፍቅህ መዓዛ ልቤን ይጠራኛል\nእንደ አጭሩ ቀራጭ ሾላ ላይ ብወጣ\nከቤቴ ሊገባ መምህሩ መጣ እንዴት\n\nቀሲስ አሸናፊ ገ/ማርያም\n', 'am', 302, 0),\n(1, 'አቤቱ ጉልበቴ ሆይ እወድሃለሁ', 'አቤቱ ጉልበቴ ሆይ እወድሃለሁ\nአቤቱ ጉልበቴ ሆይ እወድሃለሁ (2)\nአንተ ካሻገርከኝ ሁሉን አልፋለሁ (2)\n\nአዝ፦\nክንድህን እንዳላየሁ ኃይልህን እንዳላየሁ\nሲመሽና ሲነጋ ዘወትር እጨነቃለሁ\nአንተ ግን ለሰላሜ ለእረፍቴ ቆመሃል\nያዘነውን ልቤን ውስጤን አሳርፈሃል\n\nአዝ፦\nሁልጊዜ ጠያቄ ነኝ መልስ የለኝም ጌታዬ\nአንተ ግን መፍትሄ ነህ ስደክም ለብቻዬ\nአይዞህ ስትል ስማውኝ ቃልህ ሲናገረኝ\nዘወትር አምላኬ ነህ የማትተወኝ\n\nአዝ፦\nየብርቱዎች አምላክ ነህ አውቃለሁ የእኔ ጌታ\nለደካማው አንተ ነህ ኃይሉን ምታበረታ\nየተሸከመኝ ክንድህ ዝሎ አያውቅም ፍፅም\nየማምለጫ አለት ነህ ለነፍሴ ዘላለም\n\nአዝ፦\nበፈረሰው ግድግዳ ሙሉ ሆነህ ቆመሃል\nባለቀስኩኝ ጊዜ ጉልበቴን አግኝተሃል\nልናገረው በሰው ፊት ሌላ ምን እከፍላለሁ\nአይነ ስውር ነበርኩኝ ዛሬ ግን አይቻለሁ\n\nቀሲስ አሸናፊ ገ/ማርያም\n', 'am', 303, 0),\n(1, 'ከዳን እስከ ቤርሳቤህ', 'ከዳን እስከ ቤርሳቤህ\nከዳን እስከ ቤርሳቤህ ዛሬ ሞልቷል ምስጋናህ\nተነሳ ልቤ ዘምር ለጌታ ለእግዚአብሔር (3)\n\nበገና ተነስ እንዚራ\nማዳኑን እንድናወራ\nምትቀድሙ ምትከተሉ\nሁላችሁ ሆሣዕና በሉ (2)\n\nእግዚአብሔር ዘመን ከሰጠ\nይዘምር የተለወጠ\nእልልታ ይሁን ለስሙ\nለዋጀን በወርቀ ደሙ (2)\n\nየክብሬ የቤቴ ጌታ\nለነፍሴ ባለውለታ\nኤፉድ ነው በፍታ ነው ልብሴ\nዘማሪ ነኝ ለንጉሴ (2)\n\nሰገነት ላይ የወጣችሁ\nዝምታን የመረጣችሁ\nካፋችሁ ኩራት አይውጣ\nእርሱ ነው ቀን የሚያወጣ (2)\n\nቀሲስ አሸናፊ ገ/ማርያም\n', 'am', 304, 0),\n(1, 'እንደ እግዚአብሔር ያለ', 'እንደ እግዚአብሔር ያለ\nእንደ እግዚአብሔር ያለ ማንም የለምና (2)\nእልል በሉ ቁሙ ለምስጋና (2)\n\nባህር ተከፈለ እስኪታይ መሬቱ\nፈርኦን ወደቀ አልሰራም ትምክህቱ\nደካሞቹም ጸንተው ተራመዱ\nሐይለኞችም ይኸው ተዋረዱ\n\nአዝ፦\nየኢያሪኮ ቅጥር የማይደፈረው\nይኸው ፈራረሰ የሰው እጅ ሳይነካው\nሐይለኞቹም ቢበረታቱብን\nእንጸናለን በእርሱ ተደግፈን\n\nአዝ፦\nየተወረወረው የጠላታችን ጦር\nሜዳ ላይ ወደቀ ጋሻ ሆኖ እግዚአብሔር\nለስላሴ ይድረስ ምስጋናችን\nተሸነፈ አዳኝ ጠላታችን\n\nአዝ፦\nባህር ላይ ሲራመድ ሞገስ አለው እርሱ\nበግርማው ሲነሳ ጸጥ ይላል ነፋሱ\nየድንግል ልጅ እኛ የምናመልከው\nከሐሊ ነው የለም የሚሳነው\n', 'am', 305, 0),\n(1, 'በዝምታ', 'በዝምታ\nበዝምታ መልስ አለ ከጌታ (3)\n\nአዝ፦\nለእግዚአብሔር ነግሮ ለሰው ዝም የሚል\nተሸክሞ ኖሮ እርጥቡን መስቀል\nስለ እራሱ ትቶ እውነት የሚያወራ\nይሻገራል ገደል ይወጣል ተራራ [2]\n\nአዝ፦\nይወቁልኝ ብሎ ስሙኝ ስሙኝ ያለ\nንፋስ ተደገፈ ጉምን ተከተለ\nሰዉ በራሱ ጥላ እንደማይጠለል\nከሰማይ ካልሆነ ምስክር የታል [2]\n\nአዝ፦\nዳንኤል ዝም አለ ፍርድን ሲቀበል\nአልተከራከረም ለአንበሶች ሲጣል\nለእግዚአብሔር ሲናገር ተረፈ ከሞት\nስንፍና ስሕተት አልተገኘበት [2]\n\nአዝ፦\nየእግዚአብሔር ልጅ ያለው ምስክር አለው\nመንፈሱ ነዉና የሚናገረው\nሸንጎ ቢያቆሟችሁ ልባችሁ ይበርታ\nስለ እናንተ ሆኖ ይናገራል ጌታ [2]\n\nዘማሪ ቀሲስ አሸናፊ ገ/ማርያም\n', 'am', 306, 0),\n(1, 'ብቻውን የሆነውን ሰው', 'ብቻውን የሆነውን ሰው\nብቻውን የሆነውነውን ሰው፣\nረዳት የሌለውን ሰው፣\nእንደ አንተ ማን ነው ያገዘው፣\nኑሮዬ ምስክርህ ነው፣\nእንደ አንተ ማን ነው ያገዘው፣\nዘመኔ ምስክርህ ነው።\n\nበእግዚአብሔር የተወደደ፣\nበእግዚአብሔር የተወደደ፣\nይዲድያ እኔ ነኝ፣\nቸርነቱ የሚያኖረኝ፣\nሰጥቶ ሰጥቶ አያልቅበት፣\nቸርነቱ አይጎድልበት፣\nየእኔ የዋህ የእኔ ጌታ በትግስቱ አጌጥኩበት።\n\nጊዜን ዐይቶ የማይከዳኝ፣\nይሽሩን ብሎ የሚጠራኝ፣\nበሸለቆ ታገለኝ፣\nሰውነቴ ዳነችልኝ፣\nአንድ አድርጎ ከቤት አውጥቶ፣\nእልፍ አድርጎ የመለሰኝ፣\nበመዝሙሬ በስብከቴ በእልልታዬ ክበርልኝ።\n\nጥበበኞች ኃያላን ሳሉ፣\nባለ ጠጎች ክብር የተመሉ፣\nገብቶ ሳየው ከበረቴ፣\nቃል አጠረኝ ለአንደበቴ፣\nወድሃለሁ በልቤ መዝገብ፣\nእኖራለሁ ቃልህን ስመገብ፣\nአድራሻዬ መስቀልህ፣\nዘማሪ ነኝ ስለ ክብርህ።\n\nበቀሲስ አሸናፊ ገብረ ማርያም\n', 'am', 307, 0),\n(1, 'እኔ ግን በምህረትህ ብዛት', 'እኔ ግን በምህረትህ ብዛት\nእኔ ግን በምሕረትህ ብዛት\nእኔ ግን በይቅርታህ ብዛት\nወደ ቤትህ እገባለሁ\nአመልክሃለው እዘምርልሃለሁ\n\nበሕይወቴ ዘመን አንዲት ነገር ሻትኩኝ\nበቤትህ ተጥዬ መኖሬን መረጥኩኝ\nከኃጢአት ድንኳን የአንተን ደጅ ይሻላል\nእረፍቴ ጌታዬ እቅፍህ ይሞቃል\n\nየክብርህን ሥፍራ ማደርያ ወደድኩት\nመቅደስህ ቀደሰኝ ዙፋኔን ጠላሁት\nከዚህች ለምለም ስፍራ ወዴት እወጣለሁ\nየተሰበረ ልብ ይዤልህ እመጣለሁ\n\nበመከራዬ ቀን የተናገርኩትን\nከደጅህ መጥቼ ከንፈሮቼ ያሉትን\nስዕለቴን ልፈፅም ማልጄ እነሣለሁ\nየአምልኮ መስዋዕቴን እሰዋልሃለው\n\nእንደ ሰብአ ሰገል ይዤ ወርቅ ዕጣኔን\nአምሃ አኮቴት መባዬን ከርቤዬን\nልቤን አየሰዋሁ እሰግድልሃለው\nኦሜጋ አልፋ ነህ እቀኝልሀለው\n', 'am', 309, 0),\n(1, 'ኑ ለምስጋና', 'ኑ ለምስጋና\nኑ ለምስጋና እንተባበር ኑ አንድ እንሁን በሱባኤ\nኑ በመቅደሱ እናምልከው እንመስርት አንዲት ጉባኤ\n\nከያሬድ ጋር እናወድስ ከዳዊት ጋር በገናን እንምታ\nኑ ለሰዓታት እንነሳ ከጊዮርጊስ ጋር እንበርታ\nከተክልዬ ጋራ እንስበክ ከላሊበ ጋር እንገንባ\nከህርያቆስ ጋር እንቀድስ ከአቡዬ ጋር ሱባኤ እንግባ\n\nከሳባ ጋራ ጥበብ እናምጣ ከአሮንም ጋራ ጸሃይ እናቁም\nከአረጋዊ ጋራ እንጸልይ ከአንባቆም ጋር እንመስክር\nከሰላማ ጋራ እንተርጉም ከኤስጥሮስ ጋራ እንመርምር\nከገላሌዎስ ጋራ እንቀኝ ከአትናቴዎስ ጋራ እናስተምር\n\nነጻ በምታወጣ በኢየሩሳሌም ከተማ\nከጽዮን ልጆች ጋራ መዝሙራችን እንዲሰማ\nአንድ ሆነን በቀኝ እንድንቆም ከበኩራት ማህበር ጋራ\nአንድ ሆነን ዛሬ እናገልግል አንድ ሆነን ዛሬ እንስራ\n', 'am', 315, 0),\n(1, 'ጥበብ እርሱ ነው', 'ጥበብ እርሱ ነው\nጥበብ እርሱ ነው ኢየሱስ ክርስቶስ አምላካችን\nጥበብ እርሱ ነው ኢየሱስ ክርስቶስ መድኃኒታችን\nጥበብ እርሱ ነው መድኃኒታችን\nጥበብ እርሱ ነው አምላካችን\n\nከከዋክብት ይልቅ ደምቆ የሚያበራ\nጽኑ ከሀሊ ነው ስሙ የተፈራ\nለሕይወት ለመድኀኒት ራሱን የገለጠ\nጥበብ ኢየሱስ ነው ነፍሱን ለእኛ የሰጠ\nጥበብ ክርስቶስ ነው ነፍሱን ለእኛ የሰጠ\n\nሁሉን የሚያነጻ ሁሉን የሚቀድስ\nሁሉን የሚያከብር ሁሉን የሚፈውስ\nአዋቂ የሚያደርግ የጥበብ መነሻ\nኢየሱስ ክርስቶስ የጥበብ መድረሻ\n\nበሥጋ ከእኛ ጋር የተዛመደን\nመንግስተ ሰማይን ያዘጋጀልን\nየተፈጠርንበት ኃይልና ጥበብ\nቃሉ ነው ኢየሱስ ለእግዚአብሔር አብ\n\nእርሱ ተቀዳሚ ተከታይ የለበት\nበአርያም የሚኖር በላይ በጸባኦት\nጥበብ ግን እርሱ ነው በመስቀል የዋለው\nሥጋን የቆረሰ ደሙን ያፈሰሰው\n', 'am', 319, 0),\n(1, 'ጌታ ተነስቷል', 'ጌታ ተነስቷል\nጌታ ተነስቷል እልል እልል በሉ\nአምላክ ተነስቷል የምስራች በሉ\nሙስና መቃብር በኃይሉ አጥፍቶ\nሁላችን አየነው ክርስቶስ ተነስቶ\n\nአዳምን ለማዳን ቃልኪዳን ገብቶለት\nዘመኑን ጠብቆ ካሳ ሊከፍልለት\nከሰማያት ወርዶ የተሰቀለው\nሞትን በሞት ሽሮ ይኸው አየነው\n\nደቀ መዛሙርቱ እጅጉን ተጨንቀው\nበጌታቸው መሞት በኀዘን ተመተው\nበተዘጋ ደጃፍ ተሰብስበው ሳለ\nእጆቹን ዘርግቶ ሰላም ለእናንተ አለ\n\nማርያም መግደላዊት እየገሰገሰች\nበለሊት ተነስታ ወደ አምላኳ ሄደች\nአይሁድ አንገላተው የሰቀሉት ጌታ\nተነስቶ አግኝታው ተመላች በደስታ\n', 'am', 320, 0),\n(1, 'ተይ ተመከሪ', 'ተይ ተመከሪ\nተይ ተመከሪ ነፍሴ ሆይ ተይ ተመከሪ\nበዓለም መድኃኒት ነፍሴ ሆይ\nበእግዚአብሔር ታመኚ\n\nለሥጋ መገዛት ነፍሴ ሆይ ምነው ቢቀርብሽ\nውርደት ፍጻሜው ነፍሴ ሆይ የሚያከናንብሽ\nመልካም የሆነውን ነፍሴ ሆይ ጽድቅን ተከተይ\nክርስቶስን መስለሽ ነፍሴ ሆይ ቸርነትን ስሪ\nሞትን ማን ይመርጣል ነፍሴ ሆይ ሕይወትን በመጥላት\nከእንግዲህ መራቅ ነው ነፍሴ ሆይ ከስርቆት ከዝሙት\nጸጋ እንዲበዛልሽ ነፍሴ ሆይ የቃሉ በረከት\nከቤቱ አትጥፊ ነፍሴ ሆይ ፍቅር ከሞላበት\n\nላንቺ ነበር ጌታ ነፍሴ ሆይ ደሙን ያፈሰሰው\nተሰቅሎ ሞቶ ነው ነፍሴ ሆይ ፍቅሩን የገለፀው\nበፍቅሩ ለሳበኝ ነፍሴ ሆይ ላፈቀረኝ ጌታ\nምስጋና አቀርባለሁ ነፍሴ ሆይ ዘወትር ጠዋት ማታ\nብወድቅ ምርኩዝ ድጋፍ ነፍሴ ሆይ ጋሻ ይሆነኛል\nለፍርድ አይቸኩልም ነፍሴ ሆይ በፍቅሩ ያየኛል\nማን እንደርሱ አለ ነፍሴ ሆይ ውለታው የበዛ\nመሃሪ ይቅር ባይ ነው ነፍሴ ሆይ የሕይወቴ ቤዛ\n', 'am', 321, 0),\n(1, 'አንተ ቸር እረኛ ነህ', 'አንተ ቸር እረኛ ነህ\nአንተ ቸር እረኛ ነህ ላመነብህ ጌታ\nአምላክ አይረሳኝም ያረከው ውለታ\nደግ ስለሆንክ ወደድከኝ አከበርከኝ\nፍቅር ስለሆንክ ወደድከኝ አከበርከኝ\n\nባለመታዘዝ የወይንህን ቦታ ባበላሽብህ\nደነቀኝ ጌታ ይቆረጥ ብለህ አለመፍረድህ\nእድሜ ሰተኸኝ በቸርነት አብረቀረኩኝ\nከርከዴን ድንጋይ የከበረ እንቁ መሰልኩኝ\n\nምስጊኑን ባሪያ በበረከትህ አትረፈረፍከው\nባዶውን ጓዳ እጅህ ሲነካው ዛሬ ሙሉ ነው\nአላፍርም አንተን ተጠግቼ አይጎልብኝም\nአንተን ስጠራህ የኔ ጌታ አትጥለኝም\n\nየሰጠኸኝን ጸጋ እርክሸ ባሳዝንህም\nለኔ ፍርዳን ልትሰዋልኝ ቸል አላልከኝም\nልቤን የቀየርክ እንድመለስ ወደ አባቴ ቤት\nክበር በቤቴ ለዘላለም ነግሰህ ኑርበት\n\nበስደት ስኖር በባእድ ሀገር እጅግ አዝኜ\nጸናሁ በእምነት እየደገፍከኝ አንተን አምኜ\nጋጣየ ሞልቷል ጎተራየ ስለባረከኝ\nየአብርሃም አምላክ አልተውከኝም እኔን አሰብከኝ\n', 'am', 322, 0),\n(1, 'ሥላሴ', 'ሥላሴ\nዓለማት በእግዚአብሔር ቃል ተዘጋጁ\nፍጥረታት በሥላሴ ተፈጠሩ\nከፍጥረታት መካከል ያማከረው የለም\nከሆነው አንዳች ያለእርሱ አልሆነም\nክብር ለሥላሴ ለአብ እና ለወልድ ለመንፈስቅዱስ\nበሰማይ በምድር ምስጋናው ይፍሰስ\n\nይሁን ሲል ሲናገር ሰማይ ተዘረጋ\nበአፉ ቃል በውሃ ላይ ረጋ\nብርሃንን ፈጥሮ ዓለሙን ያበራው\nጨለማንም ሰርቶ ሌሊት ብሎ ጠራው\n\nበውኖች መካከል ጠፈር አደረገ\nከፈላቸውና ሕጉን ደነገገ\nየምድሪቱን ውሃ በአንድ ሰበሰበው\nመከማቻውንም ስሙን ባህር አለው\n\nምድር ዘር እንድትሰጥ አንዲት ቃል አወጣ\nአየናት ለምልማ በአበቦች አጊጣ\nቀን አና ለሊት እግዚአብሔር ለየው\nዓለሙን ሥላሴ ፈጠረ አሳመረው\n\nየሰውን ልጅ ከአፈር ከምድር አነሣው\nበመልኩ በአርአያው በምሳሌው ሰራው\nህያው አደረገው በእጁ ሰራውና\nየራሱን እስትንፋስ እፍ አለበትና\n', 'am', 323, 0),\n(1, 'ፍቅርህ ማረከኝ', 'ፍቅርህ ማረከኝ\nፍቅርህ ማረከኝ በህይወቴ በዘመኔ\nእግዚአብሔር ለኔ መድኃኒቴ\nፍቅርህ ማረከኝ በህይወቴ በዘመኔ\n\nተገዝቻለው በወርቅ ደምህ\nአለምን ትቼ ላገለግልህ\nሞትህ ህይወቴ ለኔ ሆኖኛል\nባንተ መከራ ሸክሜ ርቋል\nበክብር ቆሜ እዘምራለሁ\nእንደ አቅሜ አገንሃለሁ\n\nምድርና ሰማይ እልል ይበሉ\nምስጋና ላንተ ይድረስ እያሉ\nመሳይ የለህም ለቅድስና\nአቀርባለሁኝ ላንተ ምስጋና\nጣቴ በገናን ይደረድራል\nበቀን በሌሊት ያመሰግናል\n\nክብርህን አይተው ጠላቶች ፈሩ\nበጌትነትህ ወድቀው ተገዙ\nእንዲህ ነህ አምላክ እንዲህ ነህ ጌታ\nሁሉን በፍቅር የምትረታ\nበአንተ ተመካን በፈጣሪያችን\nአዳኝ በሆንከው በንጉሳችነን\n', 'am', 324, 0),\n(1, 'ተወለደ ሩኅሩኅ ጌታ', 'ተወለደ ሩኅሩኅ ጌታ\nተወለደ ሩኅሩኅ ጌታ\nመድኃኔዓለም የዓለም መከታ\nአማኑኤል የኛ መከታ\n\nተወለደ የዓለም ፈጣሪ\nተወለደ ቸሩ አባት\nተወለደ እኛን ሊያድነን\nተወለደ ከኃጢያት ሞት\nተወለደ እርሱም እንደኛ\nተወለደ እንደ ህፃን\nተወለደ ድንቅ ነው ፍቅሩ\nተወለደ መድኃኔዓለም\n\nተወለደ ፍቅር ቢስበው\nተወለደ የሠው ልጆች\nተወለደ መጣ ከሠማይ\nተወለደ ወልደ እግዚአብሔር\nተወለደ ከእመቤታችን\nተወለደ ተወለደልን\nተወለደ በቤተልሔም\nተወለደ በከብቶች ግርግም\n\nተወለደ የምስራቅ ሠዎች\nተወለደ መጡ ሊሠግዱ\nተወለደ ስጦታን ይዘው\nተወለደ እንደ ሥርዓቱ\nተወለደ ወርቅ አመጡለት\nተወለደ ስለ መንግስቱ\nተወለደ ዕጣን ለክብሩ\nተወለደ ከርቤን ለሞቱ\n', 'am', 325, 0),\n(1, 'ሥላሴ መታመኛዬ', 'ሥላሴ መታመኛዬ\nሥላሴ መታመኛዬ\nአምላኬ መጠለያዬ\nጉልበቴ ነህ ማሸነፊያዬ\nሥላሴ መታመኛዬ\n\nጠፈሩም እርሱ መሠረቱም እርሱ\nፍጥረታት በሙሉ ስሙን አወድሱ\nሱራፌልን ልክህ ከንፈሮቼን ዳሰኝ\nለምፄን ተመልክተህ አምላክ አትጣለኝ\nለምፄን ተመልክተህ ጌታዬ አትጣለኝ\n\nእንዴት ያለ አንደበት ስምህን ይጠራል\nግርማህን አይቼ ልቤ ተሸብሯል\nኦዝያን አለፈ ክፋቱ እጅግ በዝቶ\nአምላኬን አየሁት በዙፋኑ ጸንቶ\n\nአልአዛር የአንተ ነው መንገድ የወደቀው\nከእጅ ያላመለጠ ነዌ ባለፀጋው\nነገሥታትም የአንተ በሥልጣን ያሉት\nለስምህ ይንበርክከ ይህ ሁሉ ፍጥረረት\n\nበድቅድቅ ጨለማ ተስፋ በሌለበት\nብርሃን ሆኖ አየሁት የጌታዬን ምሕረት\nኃይልን ማሸነፍን ጽናትንም ስጠኝ\nጠላት እንዳይጥለኝ ጸጋህን አልብሰኝ\n', 'am', 326, 0),\n(1, 'አንተ እንደጠራሀኝ', 'አንተ እንደጠራሀኝ\nአንተ እንደጠራኸኝ ከምርጦችህ ልሁን\nአምላክ ለዘለአለም ልፈፅም ፍቃድክን\n\nበሲኦል የሚያመሰግንህ የለምና\nከሞት ልዳን ልጽና በምስጋና\n\nልቤ አንተን እያለ በሲኦል አትተወኝ\nበረቀቀ ጥበብ ከሞት መንደር አውጣኝ\n\nበመንፈስ ጀምሬ በብርታት\nበሥጋ እንዳለፈፅም እርዳኝ የኔ አባት\n', 'am', 327, 0),\n(1, 'በዓለት ላይ ነውና', 'በዓለት ላይ ነውና\nበዓለት ላይ ነውና ያቆማት አጽንቶ\nበደሙ ነውና የቀደሳት ዋጅቶ\nይጠብቃልና ጠባቂዋ ተግቶ\nየገሀነም ደጆች አይችሏትም ከቶ\n\nመንጋዋን ሊበትን ተኩላ ቢበረታ\nማዕበሉ መርከቧን ፍጹም ቢያንገላታ\nየተቃወሟትን ሁሉን ድልነስታለች\nዛሬም እንደ ፀሐይ ይኸው ታበራለች\n\nየቄርሎስ እናት ናት የዲዮስቆሮስ\nየአኖሬዎስ እና የነ ፊሊጶስ\nየወለተ ጴጥሮс የክርስቶስ ሰምራ\nየጴጥሮስ እናት ናት የነ መስቀል ክብራ\n\nኑፋቄ ቢነሳ ክህደቱ ቢነፍስ\nዙሪያዋን ቢከቧት ቅጥሯን ለማፍረስ\nየጸና ነውና በደም ተመስርቶ\nትረታለች እንጂ አትረታም ከቶ\n\nአእላፍ መላእክት ዙሪያ ከበዋታል\nአእላፍ ቅዱሳን የጸልዩላታል\nእኛ ማናቃቸው እርሱ የሚያውቃቸው\nለእርሷ የሚሰሩ እጅግ ብዙ ናቸው\n', 'am', 328, 0),\n(1, 'አስፈሪው ነበልባልና', 'አስፈሪው ነበልባልና\nአስፈሪው ነበልባል ሁሉንም አልፌ\nይኸው በአምላኬ ቆምኩኝ ተደግፌ\nምስጋና አቀረባለው ሁሉን ቻይ ለሆነው\nእንድዘምርለት ልቤን ለከፈተው\n\nለሰው ያልነገኩት በውስጤ የቀረ\nያሳለፍኩት ስቃይ መከራ ነበረ\nወዳንተ አልቅሼ ፈታሕልኝ አምላክ\nአይተህ ቸል ያላልከኝ በባርያሕ አልጨከንክ\n\nአምላክህ የት አለ ሲሉኝ ጠላቶቼ\nአጥምደው ይዘውኝ እጃቸው ገብቼ\nሐዘን ነፍሴን ከቧት መድረሻው ጠፍቶኝ\nፈጥነሕ ደረስክና ከሞት አዳንከኝ\n\nከእንግዲህ ወዲህ እኔ ተስፋ አልቆርጥም\nስራህን አይቼ ከቶ አልናወጥም\nወድቄ እንደማልቀር አስተምረኸኛል\nወጥመዱን ሰባብረሕ ለዚሕ አብቅተኸኛል\n', 'am', 330, 0),\n(1, 'እኔስ እዘምራለሁ ለስላሴ', 'እኔስ እዘምራለሁ ለስላሴ\nእኔስ እዘምራለሁ ለስላሴ\nፈጥሮኛልና በሥጋ በነፍሴ\nእኔስ እዘምራለሁ ለሥላሴ\n\nሥሉስ ቅዱስ ተብለህ የምትመሰገን\nሰውን ከመከራ ከሞት የምታድን\nነፍሴ ትገዛልህ ትንበርከክልህ\nቅዱስ ፈጣሪዋን አንተን ታምልክህ\n\nበመሀርነትህ ጠብቀህ ያኖርከኝ\nበማዳን ችሎታህ ለዚህ ያደረስከኝ\nለአንተ ለአምላኬ ምስጋና አቀርባለሁ\nስምህን ለዓለም ሁሌም እጠራለሁ\n\nአብርሃም ለአምላኩ በቀና ብታዘዝ\nሥላሴ ገቡና ቤቱን ባረኩለት\nሣራንም ጎበኛት በእርጅናዋ ጊዜ\nይስሐቅን ሰጧት ለዘለዓለም ሥላሴ', 'am', 331, 0),\n(1, 'ሥላሴ ልበልህ', 'ሥላሴ ልበልህ\nሥላሴ ልበልህ\nአምላኬ መጠለያዬነህ\nፀባኦት ምስጋና ይፈሳል\nመላዕክት ያመሰግኑሐል\n\nሰማይ ዙፋንህ ነው መረገጫ ምድር\nሲያወድስ ይኖራል ፍጥረት ያአንተን ክብር\nኪሩቤል ሱራፌል ዙፋንህን ይዘው\nስራቸው ቀን ከሌሊት አንተን ማመስገን ነው\n\nነገደ መላዕክት ምስጋና ያፈሳሉ\nዙፋንህን ከበው ለክብርህ ይሰግዳሉ\nከፊት የሚቆሙት ፊታቸውን ጋርደው\nሥሉስ ቅዱስ ብለው ሊዘምሩልህ ነው\n\nውኆችን በእፍኝህ ሰፍረህ መዝነሃል\nሰማይና ምድር ይሁን ስትል ሆኗል\nየሆነውን ሁሉ ያለአንተ አልሆነም\nአምላኬ ሥላሴ መንግስትህ ዘለዓለም\n\nካህናተ ሰማይ ያመሰግኑሃል\nየምድር ጠቢባን ይዘምሩልሃል\nአምልኮና ስግደት ለአንተ ገንዘብህ ነው\nአንተን ማወደሱ የፍጥረት ስራው ነው\n', 'am', 332, 0),\n(1, 'አይሰለቸኝም ከቶ', 'አይሰለቸኝም ከቶ\nአይሰለቸኝም ከቶ ውዳሴ መዝሙር ቅኔ፣\nብዙ ነው ያደረገልኝ እግዚአብሔር በዘመኔ።\n\nቸርነትና ፍቅሩን ያላራቀ ከባሪያው\nበለመለመ ስፍራ ልጆቹን የሚያሠማራው\nታላቅ ነው የእኛ ንጉሥ ታላቅ ነው የእኛ ጌታ\nመጽሐፉን የዘረጋ ማሕተሙን የፈታ።\n\nአንገቱን ፍጹም ደፍቶ ቀና እንድል አድርጎኛል\nእየቃተተ ሞቶ በሕይወት አቁሞኛል\nአልችልም የእርሱን ፍቅር መዘርዘርና ማውራት\nውለታውን ለመግለጥ የለኝም ብርቱ ቃላት።\n\nየአንተ ክንድ የማይንደው ተራራ ጋራ የለም\nወጥቻለው ከጥልቁ ታላቅ ነህ ዘለዓለም\nየተከፈተ ደጃፍ ሠጥተኸኛል ከፊቴ\nተመስገን ክበርልኝ ንገሥልኝ አባቴ።\n\nለይተህ የጠራኸኝ ያበዛህልኝ ጸጋ\nትዝታዬ ነህ ጌታ ሲመሽና ሲነጋ\nወዳጅ እና ዘመዴ ብዬ ስጠራህ ልኑር\nኢየሱስ የእግዚአብሔር ልጅ ለወጠኝ የአንተ ፍቅር።\n\nበዘማሪ ዕዝራ ኃይለ ሚካኤል\n', 'am', 333, 0),\n(1, 'ማራኪው እየማረከ', 'ማራኪው እየማረከ\nማራኪው እየማረከ\nባራኪው እየባረከ\nበፍቅሩ ስንቱን ረታ\nሰባሪው የድሉ ጌታ\n\nየሞቴን ወጥመድ ሰባብሮ\nበድምፁ ጥልቁን በርብሮ\nሰደደኝ ማህተብ አትሞ\nየአርነት ግርማ ሸልሞ\n\nሰገባው ያዘንባል ፍቅር\nከአማልክት የለውም ወደር\nተሳስሯል ደሙ ከደሜ\nበሞቱ ሰፍኗል ሰላሜ\n\nምስጉን ነው የተባረከ\nበፍጥረት የተመለከ\nመተኪያ የለው አምሳያ\nለክብሩ እንበል ሀሌሉያ\n\nየጓዳ የእልፍኝ ልቅት\nአንተ ነህ ክብሬ ሰገነት\nከቦኛል በመላዕክቱ\nነጥቆኛል ስቦ ከእሳቱ\n', 'am', 334, 0),\n(1, 'ተናገር ባርያህ ይሰማል', 'ተናገር ባርያህ ይሰማል\nተናገር ባርያህ ይሰማል\nሳሙኤል በለኝ ድምፅህ ይገርማል\nታናሽ ነኝ የማልበረታ\nእስቲ ተናገር ላድምጥህ ጌታ (2)\n\nበሚያስፈራው በመቅደስህ\nልኑር ጌታ በመንፈስህ\nደካማ ነኝ ብላቴና\nባንተ ልቁም ባንተ ልፅና\nአያሳድደኝ ጠላት አልውጣ ካንተ\nከእቅፍህ ልግባ ሳበኝ እፍኙን ከፋተህ\n\nፈቅደህ ወደህ ጠርተኸኛል\nቸርነትህ አቁሞኛል\nፋቅርህ አስሮ ያኑረኝ\nብትወደኝ ነው ብትምረኝ\nሰላሜ በዝቷል ባንተ በእረኛዬ\nመቼም አልጠፋም በሞት ካለጌታዬ (2)\n\nአፍኒ ፊናስ ወንድሞቼ\nያሳዘኑ ታላቆቼ\nቀሰቀስከኝ ከመኝታ\nበእስራኤል ላይ ልበረታ\nእንዴት አድርጌው ልቻል ይህንን ሸክሞ\nየታሪክ ጠባሳ ነው እስከ ዘለአለም (2)\n\nበድንኳኑ በማደርያ\nሳውጅ ልኑር ያንተን ስራ\nቅድስና ይብዛልኝ\nበመንግስትህ አስበኝ\nከዳን እስከ ቤርሳቤህ ለስምህ ልቅና\nየእስራኤል ቅዱስ አንተ ታላቅ ነህና (2)\n', 'am', 335, 0),\n(1, 'እርሱ ግን ከሁሉ በላይ ነው', 'እርሱ ግን ከሁሉ በላይ ነው\nእርሱ ግን ከሁሉ በላይ ነው\nሞትና መቃብር ያልያዘው\n\nስለ ፍቅሬ ቢያቃስት ለክብሬ\nፍቅር ያስጎነበሰው ምስኪን የህማም ሰው\nተዋጊው ተዋጊው ሞትን ድል አድራጊው\nየታገሰ አንበሳ ይቅርታን ያገሳ\nእንደሚታረድ በግ ዝም ቢል ሊታረድ\n\nእርሱ ግን...\n\nእውነት ሀሰት ከሶት ጦር ደሙን አፍስሶት\nየጅራፉ ላንቃ ጀርባውን ቢያነቃ\nውሀ ባለ አፍላጋት መራራ ሀሞት ቢጋት\nለፍቅር ቢጠማም በችንካር ቢደማም\n\nእርሱ ግን...\n\nአባቱ ጨክኖ የላከው ለአድህኖ\nከጎኑ ሰሌዳ ፍቅርን እያስረዳ\nየኤልያስ ሰሪ የሙሴ ፈጣሪ\nየእግዚአብሄር ልጅ ሳለ የዮሴፍ ተባለ\n\nእርሱ ግን...\n\nጨረር ፈንጣቂ እጁ ቆስለው በወዳጁ\nእሳት ሳለ ልብሱ ቢገፈፍ ቀሚሱ\nበብርሀን ፊቱ ምራቅ መተፋቱ\nውሀ ላይ ሂያጅ እግሩ ቢቃጠል በሀሩሩ\n', 'am', 336, 0),\n(1, 'በሰማይ ለእግዚአብሔር ምስጋና', 'በሰማይ ለእግዚአብሔር ምስጋና\nበሰማይ ለእግዚአብሔር ምስጋና\nበምድርም ለሰው ልጅ ሰላም (2)\nተወልዷልና መድኃኔዓለም (2)\n\nየሞቱ ዘመን ማብቂያው ሲቃረብ\nመቋጫው ሲደርስ አስፈሪው ዘመን\nከድንግል ማርያም ጌታ ተወለደ\nየጠብ ግድግዳ በክንዱ ተናደ\n\nሰላም ታውጇል ነፃነት ሕይወት\nተወልዷልና የዓለም መድኃኒት\nየሰማይ ዜማ ተሰማ በምድር\nበአፈ መላእክት ለእግዚአብሔር\n\nቃል አልረሳም የምህረት ኪዳኑን\nየማዳኑን ቀን ከአፉ የወጣውን\nመሃላው ጽኑ ፀፀት የሌለበት\nላዳነን አምላክ እልል እንበልለት\n\nአጽናኙን ድምጹን ሰማን በኤፍራታ\nበዱር አየነው የፍጥረትን ጌታ\nበሚቆምበት በሚያድርበት ስፍራ\nእንሰግዳለን በጽዮን ተራራ\n', 'am', 337, 0),\n(1, 'ፍቅር ነህ ዘላለም', 'ፍቅር ነህ ዘላለም\nፍቅር ነህ ዘላለም እንዳንተ የለም (2)\nከሀሊ ነህ ጌታ የማትረታ (2)\n\nእጅግ ፈጠኑ ሰረገሎቹ\nየሳት ፈላፃ ይዟል በእጆቹ\nአይሸነፍም አይወድቅም ከቶ\nዛሬም ይኖራል መቅደሱን ሞልቶ\n\nያጉረመርማል ጠቁሯል ሰማዩ\nአለቆች ሸሹ ክብሩን እያዩ\nየሚያስተጋባ መብረቅ ነው ድምፁ\nየሲኦል ደጆች ተነዋወፁ\n\nአይንህ እንዳየ አትፈርድም አንተ\nምርኮ አብዝተሀል ተሰቅለህ ሞተህ\nእንዴት ወደድከኝ ብዬ አልልህም\nፍቅር ነህና ለዘለአለም\n\nበተዘጋው ቤት መግባት ታውቃለህ\nፍጥረት መነነ አንተን እያለ\nየደስታ ምንጬ የእልልታ ቤቴ\nዘይት ደፍቶ አብርቷል ፊቴ\n', 'am', 338, 0),\n(1, 'ባለ ድል ያረገን', 'ባለ ድል ያረገን\nባለ ድል ያረገን ስሙ ነው\nባለ ድል ያረገን ክንዱ ነው\nይሰራል በእኛ ላይ መንፈሱ\nከፍ ይላል በዘመን ንጉሱ (2)\n\nትከሻችን ጥሎ ቀንበር\nሞገስ ተጭኖበት ክብር\nየመስቀሉን ኒሻን አርገን\nየደሙን ሀብል አጥልቀን\nበቀዩ ምንጣፍ ላይ በእምነት\nተራምደን ገብተናል ገነት\nድል ነስቶ ድል አልብሶናል\nኢየሱስ ማዕረግ ሆኖናል\n\nሊገለጥ ያለውን ክብር\nአይተነው በእምነት መነጽር\nጨክነን እንሰብከዋለን\nሁሉንም በአስቻለን ችለን\nአለን የከበረ መዝገብ\nከነፍስ የምናምነዉ ከልብ\nመንፈሱ በእኛ ሲሰራ\nአዜምን በጦሩ ስፍራ\n\nገልጦልን የእውቀቱን ሽታ\nበእምነት ካዘመተን ጌታ\nየለም ወደኋላ ማለት\nሰባሪው ወጥቶልን ከፊት\nየምንሞት ስንመስል ህያው\nፀጋው የበዛልን ደስታው\nአንዳችን የሌለን ስንሆን\nሁሉ የእኛ ሆኗል ባርኮን\n\nዘማሪ ዲ/ን ዕዝራ ኃይለ ሚካኤል\n', 'am', 339, 0),\n(1, 'ለባህሪህ ይብዛ ምስጋና', 'ለባህሪህ ይብዛ ምስጋና\nለባህሪህ ይብዛ ምስጋና\nቢሆን ባይሆን ጌታ ነህና (አዝ)\n\nበሁኔታ የማይገደብ\nእልልታዬ ለክብርህ ይዝነብ\nበነገሬ እንዴት ልዳኝህ\nሳልሠራ አይቶኛል ዓይንህ\nተጠንተዋል በአንተ ቀኖቼ\nልረፍብህ ሁሉን ሰጥቼ\n\nአልመጣሁም ፍጠረኝ ብዬ\nእኔ ሸክላ አንተ ሰሪዬ\nአንጥረኛው እንዳሻህ አርገኝ\nእንኳን ኑሬ ሳልኖር የአንተ ነኝ (አዝ)\n\nማን ነበረ ያኔ ከአንተ ጋር\nሰማይ ምድር ሁሉን ስትፈጥር\nዘላለምን አልፎ ነዋሪ\nሞት የለበት ያንተ ባህሪ\nስላረገው ስለእጅህ ሥራ\nባትጠግብም ነፍሴ ዘምራ\nእንዳዜምኩኝ ለበረከት\nላመስግንህ በጌትነት (አዝ)\n\nሲሞላልኝ ይዤ ሽብሸባ\nሲጎድልብኝ መታጠብ በእንባ\nማጉረምረምን ይንጠፍ ልሳኔ\nአንተን ያክብር ቀሪው ዘመኔ\nሁሉን ባጣ አንተ ካለኸኝ\nሙሉ ሰው ነኝ ያልጎደለብኝ\nበባዶየም አንተን ልመንህ\nፈጥሮ መስጠት የማይሳንህ (አዝ)\n\nበሰማያት በዙፋን ሆነህ\nበበረት በግርግም ወርደህ\nእሳት ከቦህ በኪሩብ ጀርባ\nበውርንጫ ሁነህ ስትገባ\nበዝቶልሀል ቅኔ ሽብሸባ\nበባህሪህ ብሩክ ነህና\nድንጋይ እንኳን ሰብሮ ዝምታ\nፍጥረት ሁሉ ታጥኗል በእልልታ\n\nታርደሀልና ይገባሃል (2)\nሙተሀልና ይገባሃል (2)\nአምላክ ነህና ይገባሃል (2)\nንጉሥ ነህና ይገባሃል (2)\n\nዘማሪ እዝራ ኃይለ ሚካኤል\n', 'am', 340, 0),\n(1, 'ይናፍቃል ልቤ በብዙ', 'ይናፍቃል ልቤ በብዙ\nይናፍቃል ልቤ በብዙ\nሊታዘዝህ ሊገዛልህ ሊያገለግልህ\n\nኃጢአትም እንደ ህልም\nውስጤን ሲገዛኝ\nበፍቅርህ ስታየኝ አነባለሁኝ\nበውስጤ ይፈሳል ፍቅርህ እንደዘይት\nእንዴት ልርሳው ቸርነትክን ከተለወጥኩብህ\n\nለፍርድ አትቸኩልም በልጆችህ ላይ ልቦናዬን ማርከኸዋል ከምንም በላይ\nየእኔ አይደለምና የምድር ሰውነቴ\nላገልግልህ ባሪያህ ሆኜ ቸር ነህ መዳኒቴ\n\nአመፅን ለመስራት ስፈጥን ከመንገድ ከአጠገቤ አይሃለሁ እብደቴን ስታግድ እንደምን ወደድከኝ ምን እከፍልሃለሁ\nከሰው ምንም የማትወስድ\nመሆንክን አውቃለሁ\n\nእንግዳ ነህ ለእኔ አዲስ ነህ ለቤቴ\nትልቁ ዘመዴ ለብቸኝነቴ\nዳር ሆነህ አታየኝ ሀዘን ሲገርፈኝ\nለጥያቄዎቼ ሁሉ መልስ የምትሆነኝ\n\n', 'am', 341, 0),\n(1, 'ዘወረደ', 'ዘወረደ\nበእርሱ ፍቃድ በአባቱ ፍቃድ\nበመንፈስ ቅዱስ ፍቃድ\nከሰማያት ወረደ\nከድንግል ማርያም ተወለደ\n\nዓለሙን እንዲሁ ወደደና\nከሰማያት በላይ ወረደና\nበአጭር ቁመት በጠባብ ደረት\nተወሰነ አምላከ አማልክት\nከሰማያት የወረደው\nፍቅር ስቦት የመጣዉ\nወልደ አብ ወልደ ማርያም\nኢየሱስ ፈራጅ ነዉ\n\nቅድመ ዓለም ተወልዶ ያለ እናት\nድህረ ዓለምም ያለ አባት\nየእግዚአብሔር ልጅ በእርግጥም ሰው ሆነ\nሁሉ በእርሱ ይኸው ተከናወነ\nከሰማያት የወረደው\nፍቅር ስቦት የመጣዉ\nወልደ አብ ወልደ ማርያም\nክርስቶስ አምላክ ነዉ\n\nየማይታይ ታየ በምድር\nረቂቁ ገዘፈ ስለፍቅር\nሥጋን ተዋህዶ ሆነልን ፈውስ\nአማኑኤል የነገስታት ንጉሥ\nከሰማያት የወረደው\nፍቅር ስቦት የመጣዉ\nወልደ አብ ወልደ ማርያም\nእግዚአብሔር እርሱ ነዉ\n', 'am', 342, 0),\n(1, 'ሰንበተ ክርስቲያን', 'ሰንበተ ክርስቲያን\nበኩር ናት የበዓላት\nኑ ከፍ ከፍ እናድርጋት\nበእሷ ደስ ይበለን\nበሰንበተ ክርስቲያን\n\nበዝማሬ እንበርታ በገናውን እንያዝና\nመልካም ስራ የሚሰራባት\nሰንበት ቅድስት ናት እና\nከጨለማ ብርሀን ከመገዛት ነፃነት\nእግዚአብሔር ይህን ሰጠን\nደስ ይበለን በሰንበት\n\nለአብርሃም ተገልጣለች\nለሙሴም በደብረ ሲና\nበነቢያት የታወቀች\nሰንበት ዳራዊት ናት እና\nበሳምንቱ ሰለጠነች\nተሰበከች በሐዋርያት\nሃሌ ሉያ ዕለተ ሰንበት\nተሰጠችን ልናርፍባት\n\nበእልልታ እንሞላ እንደ ነቢዩ አሳፍር\nበከበረች የሰንበት ቀን ኑ ለቅኔ እንሰለፍ\nበመቅደሱ ናቸው እና ቅዱስነትና ግርማ\nውዳሴያችን ይሰማልን\nከምድር እስከ እዮር እራማ\n\nእግዚአብሔር አብ የባረካት\nእግዚአብሔር ወልድ የቀደሳት\nከእለታት ሁሉ መርጦ\nመንፈስ ቅዱስ ከፍ ያደረጋት\nበእርሷ ሀሴት እናድርግ\nእናክብራት እንድንከብር\nየደጀሰላሙ ታዛ በመቅደሱ እንሰብሰብ\n', 'am', 343, 0),\n(1, 'ምኩራብ', 'ምኩራብ\nቤትህ ቅዱስ ነው መቅደስህ\n\nለዘለዓለም መርጬዋለው\nበረድኤቴ እገለጣለው\nልቤ እና አይኔ በዚያ ነውና\nእሰማለሁኝ ጸሎት ምስጋና\n\nአዝ፦\nቤትህን ከበው ገንዘብ ለዋጮች\nየሚሸጡበት በግ እና ርግቦች\nእንዲገለበጥ መደባቸው\nየቤቱ ጌታ አንተ ጎብኘው\n\nአዝ፦\nየቤትህ ቅናት በላኝ እንደ እሳት\nክፋት ጥላቻ ሲበረቱባት\nየአህዛብ ዛቻው የአህዛብ ፈረስ\nአስተናገደች የክብር መቅደስ\n\nአዝ፦\nለፍሮድ ተነሳ ዝም አትበል ጌታ\nእንዲፈራርስ የሻጭ ገበታ\nመለያየቱ በልጧል ከትላንት\nዛሬም አምላክ ሆይ ቤትህን ጎብኛት\n', 'am', 344, 0),\n(1, 'ኒቆዲሞስ', 'ኒቆዲሞስ\nኒቆዲሞስ ኒቆዲሞስ ክቡር (2)\nሌቱን በብርሃን የሚማር መምህር (2)\n\nአዝ፦\nበጨለማው ግርማ ኮከብ የደመቀ\nበመከራው ፅናት ይህን ዓለም ናቀ\nመምህር ሆኖ ሳለ ከመማር ያልራቀ\nየትዕቢትን ጅረት በትህትና ተዋርዶ አደረቀ\nረቢ ሰገደ በመንፈቀ ሌሊት ለረቢ\nአኮኑ አፅባይት እምነ አፅባይት የአቢ\nረቢ ሰገደ በመንፈቀ ሌሊት ለረቢ\n\nአዝ፦\nፍርሃትን በሚጥል ፍፁም ፍቅር ያደረ\nከመስቀል አውርዶ ጌታውን ቀበረ\nየመግነዙን በፍታ በሽቶ አከበረ\nከመቅደሱ አንቀፅ ላይረሳ አምድ ሆኖ ታጠረ\nረቢ ሰገደ በመንፈቀ ሌሊት ለረቢ\nአኮኑ አፅባይት እምነ አፅባይት የአቢ\nረቢ ሰገደ በመንፈቀ ሌሊት ለረቢ\n\nአዝ፦\nለሊትም ለሊት ዕውቀትን ነገረች\nህጉን ለሚያስበው ምክር አለኝ እያለች\nከጨለማ ሀጢያት ነግታ ብርሃን ከአየች\nእንደ ኒቆዲሞስ ነፍስህም ተምራ ተመለሰች\nረቢ ሰገደ በመንፈቀ ሌሊት ለረቢ\nአኮኑ አፅባይት እምነ አፅባይት የአቢ\nረቢ ሰገደ በመንፈቀ ሌሊት ለረቢ\n', 'am', 345, 0),\n(1, 'አንተን ተደግፌ', 'አንተን ተደግፌ\nአንተን ተደግፌ አልፏል ትላንትና\nነገንም አያለዉ አባቴ ነህና\nጌታዬና አምላኬ በሕይወቴም በሞቴ\nአበርታኝ በሃይሌ ልጽና ባይማኖቴ (2)\n\nገና ሳልፈጠር ዛሬን አይተህልኝ\nየሕይወቴን ቀመር አንተ ሰፈርክልኝ\nእኔ እንዳልኩት ሳይሆን ይሁን አንተ ያልከዉ\nመዳፍህን ይዤ ሁሉንም አልፋለዉ\nየትካዜው እለት ባንተ አልፎኛል\nበመንገዴ ቀድመ ብርሃን ወቶልኛል\nባንተ ተማምኜ በፀናው አለት\nትልቁን ተሻገርኩኝ ወጣውኝ ከሞት\n\nየባርያህን ሰላም የምቶደዉ ንጉሥ\nሁሉን እየለወጥክ ታደርጋለህ አዲስ\nወዳንተ የመጣ በክንድህ ያረፈ\nበሕይወት መጽሐፍ ለክብር ተጻፈ\nከኔ በላይ ለኔ ታስብልኛለህ\nከጥላዬ በላይ ለልቤ ቅርብ ነህ\nለዚ ያደረሰኝ አይደለም ብርታቴ\nባንተ ተወስኟል መውጣቴ መግባቴ\n', 'am', 346, 0),\n(1, 'አትፈርስም', 'አትፈርስም\nአትፈርስም አትጠፋም በጠላት(2)\nኢየሱስ ነው በደሙ የመሰረታት\nኢየሱስ ነው ተዋህዶን ያነፃት\n\nየሚደክሙ በከንቱም የሚለፉ\nየሚታትሩ ተዋህዶን ሊያጠፉ\nአይሳካም ምኞታቸው አይሰምርም\nቃል ስላላት በጠላት እጅ አትወድቅም\n\nአዝ፦\nከሰማይ ነው አይደለም ከምድር\nጠባቂዋ ለዘላለም በፍቅር\nየማይፈርስ የጸና ስም ስላላት\nምን ብትለፉ አትችሉም ልታጠፏት\n\nአዝ፦\nየሶስት ሺ ዓመት ታሪክ ያላት\nየቀደሙት የተጋደሉላት\nቀን ከሌሊት ለፀሎት የምትተጋ\nስሙ አይኖርም ከእርሷ ጋር የሚዋጋ\n\nአዝ፦\nየእውቀት እና የጥበባት መፍሰሻ\nየከበረች አዲስ ክብር የማትሻ\nጠላት ቢጮህ እንዳሻው ቢፎክር\nሙሽራዋ ሞሽሯታል በክብር\n\nአዝ፦\nእንኳን ዛሬ ትናንት ያልፈረሰች\nበቀለማት አብርታ የታየች\nብዙ ብዙ እጅግ ብዙ ብትለፉ\nተዋህዶን በጭራሽ አታጠፉ\n', 'am', 347, 0),\n(1, 'መልካሙን የማይብህ', 'መልካሙን የማይብህ\nመልካሙን የማይብህ፣\nክፉውን የማልፍብህ፣\nፍቅር እኮ ነህ ጌታዬ፣\nአምላኬ ዋስትናዬ።\n\nታናሽ ነኝ የማልጠቅም ብላቴና፣\nልብ እንጂ ጌታ ፊትን መች ታይና፣\nቀባኸኝ አከበርከኝ መረጥከኝ፣\nበፊትህ ለምስጋና አቆምከኝ።\n\nበማንም አልመካም አልደገፍ፣\nስላልው ተመችቶኝ ያንተ እቅፍ፣\nለነፍሴም ለሥጋዬም ታስባለህ፣\nጠላቴን በእጄ ላይ ትጥላለህ።\n\nበቤትህ በመቅደስህ ያስጠለልከኝ፣\nለሕይወት ለበረከት የተከልከኝ፣\nሰላሜን ጽኑ ቅጥሬን አግኝቻለሁ፣\nጌታዬ ከአንተ በቀር መች ዓያለሁ።\n\nተለየሁ ከኃጢአት ከሞት ሥፍራ፣\nጌታዬ ተማርኬ በአንተ ሥራ፣\nስላየሁ በእጆችህ ላይ ሕይወት፣\nአልውጣ ከመዳፍህ እንዳልሞት።\n', 'am', 348, 0),\n(1, 'ልግባ ወይ ልመለስ', 'ልግባ ወይ ልመለስ\nከቤቱ እየኖርኩ ንስሐ ሳልገባ\nሽፍታው ተመልሶ ቀድሞኝ ገነት ገባ (2)\n\nዛሬ ነገ እያልኩኝ ሁሌም ሳመነታ\nከሠርጉ ቤት ገባ የተጠራው ማታ (2)\n\nቅዳሴው ሲቀደስ ውስጤ ይጨነቃል\nበደሌ እየታየኝ አላስቆም ብሎኛል\nጻኡ ሲል ዲያቆኑ ሲናገር አዋጅ\nኃጢአቴ እየገፋ ወሰደኝ ከደጅ\n\nልግባ ወይ ልመለስ ኃጢአቴ ይታየኛል (2)\nመቼ ነው ምቀርበው መቼ ነው\nመቼ ነው ጌታዬ ፊትህን የማየው\n\nአዝ፦\nጠባ ለኪዳኑ የሚቀድመኝ የለም\nአካሌ ቆመ እንጂ ልቤ ሄዷል ዓለም\nእያንጎዳጎደ በየስፍራው ሄዶ\nሕይወት አመለጠኝ ልቤ ዓለሙን ወዶ\n\nአዝ፦\nዘሪው እየዘራ እንቅልፍ እንቅልፍ አለኝ\nፍሬ እንዳላፈራ እሾሁ አነቀኝ\nእግዚአብሔር ሲናገር ልቤ ያዳምጣል\nከበሩ ስወጣ ወፎች ይለቅሙታል\n\nአዝ፦\nስራዬ በሙሉ ሁል ጊዜ ለታይታ\nሰልጥኖብኝ ዓለም እኔን እያምታታ\nሕይወቴን ልንገርህ ጌታዬ ስማኝ\nባርያህ እንዳልጠፋ አንተ ሰው አርገኝ\n\nቀሲስ እንግዳወርቅ በቀለ\n', 'am', 349, 0),\n(1, 'የሁሉ አይን', 'የሁሉ አይን\nየሁሉ አይን አንተን ተስፋ አድርጎል\nምህረት ቸርነት ይጠባበቃል\nሸክሙ ከብዶል አቅልልን\nያላንተ ጌታ ሌላ ማን አለን\n\nያለው ይመስላል ለብሰው ሲያዩት\nላይ ታች እያለ ይዞት ጭንቀት\nየልጆቹ እንቧ ጭወት ሰልችቶት\nልመና ገባ ሙሁሩ ድንገት\n\nከዛሬ ነገ ይሻላል ስንል\nእየባሰ ሔደ አለመታደል\nአምነ ረሀብ ይሄ ይሰከናት\nብለዎል እና ደቀ መዛሚርት\n\nአሳይተሀኝ ጌታ አታንሳን\nበደል አለብን ይቅር በለን\nበወርቅ ብር ላይ ተቀምጠን\nእንራባለን ፍቅር አተን\n\nእንጨት ለቃሚ ባልቴት ነበረች\nበሰራሀት ድህነት እያለች\nበአክአብ ምክንያት ረሀብ ሆኗል\nወደ ሞት ልንወርድ ተዘጋጅተናል\n', 'am', 350, 0),\n(1, 'ስለወደደኝ', 'ስለወደደኝ\nስለወደደኝ አዳነኝ\nበቸርነቱ ፈወሰኝ\nአቆመኝ ስለ ክብሩ\nከሞት ነጥቆኛል ፍቅሩ\n\nአዝ፦\nዘርግቶልኛል እጁን ለህማም\nአፍቅሮኛል እስከ ዘለዓለም\nስታወክም ነው ጸጥታዬ\nየወደደኝ ቸሩ ጌታዬ\n\nአዝ፦\nበሞት ጫንቃ ላይ ተረማመድኩኝ\nሰንሰለቴ ተፈቶ ዳንኩኝ\nበዝማሬ አፌ ሰልጥኖ\nአርፏል ልቤ በእርሱ ተማምኖ\n\nአዝ፦\nወርዶ ሳምራዊው ከአህያው ላይ\nዘይትን ቀባኝ በቁስሎቼ ላይ\nደግፎኛል በንጹህ ፍቅር\nከፍሎልኛል ሁለቱን ዲናር\n\nበዘማሪ ገብረዮሐንስ ገብረጻዲቅ\n', 'am', 351, 0),\n(1, 'በሰማያት ላይ ከፍ ከፍ በል', 'በሰማያት ላይ ከፍ ከፍ በል\nበሰማያት ላይ ከፍ ክፍ በል\nክብርህም በምድር ይነገራል\nዘመን የሚዋጅ አለን ምስጋና\nመድኃኔዓለም ስምህ ገናና (2)\n\nእልፍ አእላፍ መላእክት\nቢቆሙ ካንተ ፊት\nአያርፉም ይተጋሉ\nስሉስ ቅዱስ አረያሉ\nያለና የሚኖር አንተ ነህ እግዚአብሔር\n\nሊቃናት ይጮኻሉ\nበጉ ድል ነሳ እያሉ\nየወርቅ ጽና የያዙ\nምስጋናህን አበዙ\nያለና የሚኖር አንተ ነህ እግዚአብሔር\n\nበደምህ የታተሙ\nሀይልህን ተሸከሙ\nየቅኔ ኡደት ሆነ\nክብርህ በአለም ገነነ\nያለና የሚኖር አንተ ነህ እግዚአብሔር\n\nበዙፋንህ ስር ካሉት\nከሰባቱ መናፍስት\nከታመነው ምስክር\nአዲስ ውዳሴ መዝሙር\nያለና የሚኖር አንተ ነህ እግዚአብሔር\n', 'am', 352, 0),\n(1, 'ኢየሱስ ልበል', 'ኢየሱስ ልበል\nኢየሱስ ልበል ኢየሱስ እርሱ ነው ኅይወቴ\nየምኖርበት ተስፋ እርሱ ነው እረፍቴ\nያለ ጌታ ብኖርማ እንዴት እኆናለሁ\nስለስሙ ብነቀፍም ነፍሴን እሰጣለሁ\n\nበአይሁድ መንደር ስሄድ የቤቱ ቅናት በላኝ\nኢየሱስ የሚሉትን ስሙን አትጥራ ቢሉኝ\nእንቢ ብያለሁ ያለ ፍቅሩ አልመላለስም\nያበራልኝ ይታየኛል እኔ አላፍርበትም\nበሙሴ ወንበር ሳሉ ፀሃፍቱን ሳነጋግር\nበኅጋቸው ኮነኑኝ ለጌታዬ ስዘምር\nከሰዎች ይልቅ ክርስቶስን መስማት ስላለብኝ\nበመከራ ተከብቤ አዳኜን ፈለኩኝ\n\nአላስደነገጠኝም የቄሳር ቀጭን ትእዛዝ\nበምኩራብ ተፈልጌ በመሰዊያው ፊት ብያዝ\nልቤ አይክድም የተገዛው ለእውነት ነውና\nምንም አይኖር የሚያቆመኝ ከአምላኬ ምስጋና\nኢየሱስ በታምር ሁሎጅሉን እየከወነ\nበግንበኞች ከተማ ታላቅ ፍርሃት ሆነ\nበጥቂቱ እየበዛ ቃሉ እያደረገ\nበፈታ አንደበቴ ምርኮውን ፈለገ\n\nዘማሪ ገ/ዮሐንስ ገ/ፃዲቅ\n', 'am', 353, 0),\n(1, 'የማይሸረሸር አለቴ', 'የማይሸረሸር አለቴ\nየማይሸረሸር አለቴ\nየማይናጋ መሰረቴ\nኢየሱስ ክርስቶስ ሞገሴ\nአንተነህ የፅድቅ ልብሴ\n\nአዝ፦\nቀራንዮ ላይ የቆመ\nበፍቅር የተተለመ\nከፊቴ ተነሰነሰ\nደምህ ህይወቴን ወረሰ (2)\nእፎይ ልበል ልዘምር\nሆነህኛል ጌታ ክብር (2)\n\nአዝ፦\nየሲና ምድር ህብስቴ\nየተከተልከኝ አለቴ\nመርገሜን ሰብሮ አለፈ\nሰላምህ ዉስጤ ጎረፈ (2)\nእፎይ ልበል ልዘምር\nሆነህኛል ጌታ ክብር (2)\n\nአዝ፦\nየማትደፈር ክልሌ\nየድል አርማዬ አክሊሌ\nዓለምን ማሸነፊያዬ\nአንተ ነህ ክንዴ ጌታዬ (2)\nእፎይ ልበል ልዘምር\nሆነህኛል ጌታ ክብር (2)\n\nአዝ፦\nመዳፎችህን አይቼ\nበእንባ እረጠቡ ጉንጮቼ\nትዝታዬ ነዉ ዘወትር\nየጅህ ወለላ ያ ፍቅር\nትዝታየ ነዉ ዘወትር\nመስቀል ላይ ያየሁት ፍቅር\nእፎይ ልበል ልዘምር\nሆነህኛል ጌታ ክብር (2)\n\nዘማሪ ገብረዮሐንስ ገብረጻድቅ\n', 'am', 354, 0),\n(1, 'ድል አለ በስምህ', 'ድል አለ በስምህ\nድል አለ በስምህ\nድል አለ በቃልህ (2)\nተራራው ይናዳል አማኑኤል ስልህ\nባህር ይከፈላል መድሀኔዓለም ስልህ\n\nቃዴስን ታላቁን በርሀ\nአለፍነው ሳንጠማ ውሀ\nፈርኦንን ከባህር የጣለው\nጌታዬ የጸና ስምህ ነው\nአምላኬ የጸና ስምህ ነው\n\nአዝ፦\nበእልልታ ቢፈርስ እያረኮ\nጠላትም ቢወድቅ ተማርኮ\nቢሰጠን ለእኛ ከተማው\nየሆነው ሁሉ ካንተ ነው (2)\n\nአዝ፦\nከክፋት ሁሉ ብናመልጥ\nየማረ ውሀ ቢጣፍጥ\nብንበላ መና ከሰማይ\nስለ ሆንክ ነው አ ዶናይ\nስለ ሆንክ ነው ሁሉን ቻይ\n\nአዝ፦\nየቆምነው ዛሬ በህይወት\nሰምህን አድርገን ነው ጉልበት\nከሜዳ ተጠርተን ብንነግስ\nሆነኸን ነው ክብርና ሞገስ\n', 'am', 355, 0),\n(1, 'ምስጋና በመቅደስህ', 'ምስጋና በመቅደስህ\nምስጋና በመቅደስህ\nዝማሬ ማደሪያህ\nልሰዋ ጠዋት ማታ\nክብሬ ነህ የኔ ጌታ\n\nሰገነት አይመቸኝ\nካባየም ክብር አይሆነኝ\nሁሉንም ንቄዋለሁ\nያንተን ቤት መርጫለሁ\n\nያረጃል የአለም ዝና\nጥበብም ሆኖ መና\nአንተ ግን ያው አንተ ነህ\nበሁሉ ትጸናለህ\n\nከሰማይ በአይንህ ታየሁ\nበፍቅርህ ተጎበኘሁ\nበባህሪ ባለ ጸጋ\nፈወስከኝ በደም ዋጋ\n\nቃልህን ነብሴ ሰምታ\nተዋበች በእልልታ\nወደ እግርህ መረገጫ\nመስገዴ አለው ብልጫ\n', 'am', 356, 0),\n(1, 'እውነት ነው', 'እውነት ነው\nእውነት ነው አዎ እውነት ነው\nመንገድ ነው አዎ መንገድ ነው\nህይወት ነው በእርግጥ ህይወት ነው\nኢየሱስ የጌቶች ጌታ ነው\n\nአዝ፦\nወደ እግዚአብሔር አብ የምንደርስበት\nአንድያ ልጁን የምናምንበት\nየህይወት መንገድ እርሱ ብቻ ነው\nየባሕርይ አምላክ ብለን ስናምነው\n\nአዝ፦\nበማርያም ስጋ የተገለጠው\nወልድን ስናውቅ ነው አብን ያወቅነው\nአብ በእርሱ እንዳለ እርሱም በአብ አለ\nበኃይል በሥልጣን የተካከለ\n\nአዝ፦\nሥጋዉን ቆርሶ ደሙን አፍስሶ\nህይወት የሰጠን በደልን ክሶ\nእኛም ዳሰስነው በላን ጠጣነው\nበዝግ ቤት ሳለን ገብቶ ያየነው\n\nአዝ፦\nፈቅዶ ቢወሰን በአጭር ቁመት\nረቂቁን ቢገዝፍ በጠባብ ደረት\nመንሹ በእጁ ነው ሁሉን ያጠራል\nበዓለም ሊፈርድ ዳግም ይመጣል\n\nዘማሪ ገብረዮሐንስ ገብረፃዲቅ\n', 'am', 357, 0),\n(1, 'እግዚአብሔር ተዋጊ ነው', 'እግዚአብሔር ተዋጊ ነው\nእግዚአብሔር ተዋጊ ነው\nስሙም እግዚአብሔር ነው (2)\nጉልበቴም ዝማሬዬም እርሱ ነው (2)\n\nበክብር ከፍ ከፍ ብሏል\nኃያሉን ከባህር ጥሏል\nለሕዝቡ መድኃኒት ሆነ\nከሳሹን ከላይ ከደነ\n\nአዝ፦\nምስጉን ነው የተመሰገነ\nልጆቹን ከሞት ያደነ\nፈርኦን ከጥልቁ ሰጥሟል\nበክንዱ ኃይልን አድርጓል\n\nአዝ፦\nታወጀ የምህረት ዘመን\nከድንግል አምላክ ሰው ሲሆን\nሲገለጥ የዓለም መዳኒት\nተሻገርን ገባን ከገነት\n\nአዝ፦\nመለኮት ሥጋን ተዋሐደ\nዲያብሎስ ሲዖል ወረደ\nተዋጊው እግዚአብሔር ቀድሟል\nየሞት ኃይል በሞት ተሽሯል\n\nዘማሪ ገ/ዮሐንስ ገ/ጻድቅ\n', 'am', 358, 0),\n(1, 'ናታኒም ነኝ', 'ናታኒም ነኝ\nናታኒም ነኝ በአገልግሎቴ\nአይከፋኝም ታናሽነቴ\nእጠርጋለሁ ደጅህን ጌታ\nዝቅ ብዬ ላንተ ውለታ (2)\n\nአዝ፦\nከነገደ ሌዊ ባልሆንም\nባልሾምም እንደ አሮን\nየዜማ ጣም ባልይዝ በገና\nላመስግንህ በትህትና\nደጅ ሆኜ ካንተ በር\nተስፋ አድርጌ ስዘምር\nቆጥረህልኝ እንደዋጋ\nአከበርከኝ ባንተ ፀጋ\n\nአዝ፦\nከእረኝነት ከታናሽ ስፍራ\nለንግስና ምንም ብጠራ\nከቀንዲሉ ቀርቧል ሀሳቤ\nብቀኝልህ ተነጥፎ ልቤ\nደጅ ሆኜ ካንተ በር\nተስፋ አድርጌ ስዘምር\nቆጥረህልኝ እንደዋጋ\nአከበርከኝ ባንተ ዋጋ\n\nአዝ፦\nሳይከብድብኝ የአለም ዝና\nተንበርክኬ ልስጥህ ምስጋና\nምክንያት አለኝ ለማዘንበሌ\nናታኒም ነኝ ይቺ ናት ቃሌ\nደጅ ሆኜ ካንተ በር\nተስፋ አድርጌ ስዘምር\nቆጥረህልኝ እንደዋጋ\nአከበርከኝ ባንተ ፀጋ\n\nአዝ፦\nእንኳን ልቆም በፍታ ለብሼ\nአፍርሀለሁ እኔ አጎንብሼ\nየትምክህት ካባዬን ጥዬ\nከመቅደስህ ልግባ ጌታዬ\nደጅ ሆኜ ካንተ በር\nተስፋ አድርጌ ስዘምር\nቆጥረህልኝ እንደ ዋጋ\nአከበርከኝ ባንተ ፀጋ\n', 'am', 359, 0),\n(1, 'ከማህፀን እስከ ሽምግልና', 'ከማህፀን እስከ ሽምግልና\nከማህፀን እስከ ሽምግልና\nሚጠብቀኝ ምህረትህ ነውና\nበምስጋና ወደ ቤትህ ልግባ\nልሰዋልህ የከንፈሬን መባ (2)\n\nበኑሮ መስመር በሕይወት ጎዳና\nዕድል ፈንታየን የምታቀና\nስፈራ በትር ስዝል ምርኩዜ\nተቀኘሁልህ ባሰብከው ጊዜ\n\nዘውዴ ልበልህ መከበሪያየ\nማዕረጌ ነህ መታፈሪያየ\nስምህን ይዤ ምን ጎሎብኛል\nባንተ ስላለሁ ሁሉ ተርፎኛል\n\nሳትሳቀቅም ተሸክመኸኝ\nስንት ሸለቆ ጌታ አሳለፍከኝ\nአልቆምም ነበር በራሴ ጉልበት\nአንተ ባትሆነኝ ጽኑ ሰገነት\n\nይህ ሁሉ ክብር ይህ ሁሉ ዝና\nያላንተ ፈቃድ መች ይሆንና\nይሁን ይደረግ ጌታየ ያልከው\nእኔስ ያለኝ ቃል አሜን ብቻ ነው\n', 'am', 361, 0),\n(1, 'በሚፈርደው ፈረዱበት', 'በሚፈርደው ፈረዱበት\nበሚፈርደው ፈረዱበት\nበሚምረው ጨከኑበት\nበቁጣ ጎተቱት ቀይ ግምጃ አለበሱት\n\nአዳምን የፈጠረ እጅ በመስቀል ቀኖት ተቸነከረ\nቅዱሱ የእግዚአብሔር ልጅ ከወንበዴ ጋር ተቆጠረ\nህይወት እፍ ያለውን አፍ ጨክነው ሀሞት አጠጡት\nበሞቱ ሞትን ይሽር ዘንድ ጌታን በመስቀል ሰቀሉት\n\nይህን ያህል ትህትና ይህን ያህል ትዕግስት\nይህን ያህል ሰው ማፍቀር ይህን ያህል ምህረት\nዝም አለ አማኑኤል በግፍ ለሚሰቅሉት\n\nአዝ፦\nበመፍራትና በመራድ መላዕክት ፊቱ ለሚሰግዱለት\nየአለሙን ሁሉ ጌታ በአደባባይ ላይ አቆሙት\nለሱራፌል የክብር ዘውድ ያቀዳጃቸውን ጌታ\nፍቅር ያነበብንበት ፊቱን በክፉ ባርያ ተመታ\n\nአዝ፦\nፅድቅና የፀና ሰላም የሀጥያት ስርየት በሰጠን\nእንደ ክፉ ሰው ተቆጥሮ በእሾህ አክሊል አጌጠ\nለኪሩቤል የግርማን ልብስ የሚያለብሳቸውን እርሱን\nእርቃኑን ይሰቀል ብለው እጣ ተጣጣሉበት ልብሱን\n\nአዝ፦\nበኢየሱስ መንገላታት አለም እንዲድን ከፍዳ\nቅዱሱ ደምና ውሀ ከአምላካችን ጎን ተቀዳ\nሰላም ለእናንተ ሲለን እጅና እግሩን አየን\nሙስና መቃብር ጠፋ ይኸው በአዲሱ ኪዳን\n\nዘማሪ ገብረ-ዮሐንስ ገብረ-ጻድቅ\n', 'am', 362, 0),\n(1, 'አምላኬ መቅደስህን እወደዋለሁ', 'አምላኬ መቅደስህን እወደዋለሁ\nአምላኬ መቅደስህን እወደዋለሁ\nበውስጡ ለመኖር እናፍቃለሁ\nሰላምህ እንድሆን በቤት በደጄ\n(ወደ ማደሪያህ ልምጣ ማልጄ) x2\n\nእንድሰለጥን በመላእክት ዜማ\nየህይወትን ቃል ከአፍህ ልስማ\nእንዲቀል ሸክሜ ከትከሻዬ\nወደ ዙፋንህ ልምጣ ጌታዬ\n\nመልካም በሚሏት በመቅደስህ\nሳመልክህ ልኑር ስማጸንህ\n\nአዝ፦\nተመለሠልኝ ደስታ ሠላሜ\nቤትህ መጥቼ በመሳለሜ\nስጋዬም ዳነ ታደሰች ነፍሴ\nወደ ማደሪያህ በመገስገሴ\n\nአዝ፦\nየተማርኩባት የመላዕክት ቅኔ\nየተባረከው እድሜ ዘመኔ\nየተለወጠው ሞቴ በህይወት\nእናፍቃለሁ የእግዚአብሔርን ቤት\n\nአዝ፦\nየሰማይ ዜማ የሚሰማባት\nሰዎች ከሀዘን የሚጽናኑባት\nየጸሎት ስፍራ የአምልኮ ቦታ\nቤተክርስቲያን ውዷ ስጦታ\n\nዘማሪ ገብረዮሐንስ ገብረፃድቅ\n', 'am', 363, 0),\n(1, 'በዋጋ ገዝተኸኛልና', 'በዋጋ ገዝተኸኛልና\nበዋጋ ገዝተኸኛልና\nስለኔ ደም ከፍለሃልና\nልሳኔ ያውጃል ክብርህን\nአረሳም ጌታ ውለታህን\n\nሕይወት ሰላሜን ትቼ\nየማይታይ አይቼ\nላንተ ብሰጥ ጀርባዬን\nልተዋወቅ ጠላቴን\nየጠበቀኝ ውጊያ ነው\nየተረፈኝ ፀፀት ነው\nየሻረልኝ ቁስለቴን\nተሰቅሇህ ነው አባቴ\n\nአዝ፦\nእጓዛለሁ በምናብ\nወደሰላሜ ወደብ\nእጄን በአፌ እጭናለሁ\nዛሬም እፁብ እላለሁ\nለክብርህ መሠለፌ\nበለመለሙ ማረፌ\nዋጋ ከፍለህ ነው ጌታ\nያኖርከኝ በፀጥታ\n\nአዝ፦\nከውሃና ከመንፈስ\nተወልጄ ከመቅደስ\nልጅህ ሆንኩኝ ዳግመኛ\nየመስቀልህ ሙርከኛ\nባንተ ሰለመዳኔ\nምስክርህ ነኝ እኔ\nላይታጠፍ ምላሴ\nእቀኛለሁ በነፍሴ\n', 'am', 364, 0),\n(1, 'ለአብርሀም እንደማለ', 'ለአብርሀም እንደማለ\nለአብርሀም እንደማለ\nለይስሀቅ እንደተናገረ\nለያዕቆብ እንደመሰከረ\nህዝብን ከሞት አሻገረ\n\nየማለውን መሀላ ሳይረሳ ጌታ\nህዝብን በጽኑ ደዌ በሞት ሳይመታ\nለአባቶች እንደማለላቸው\nቃሉን ፈጸመ በቃልኪዳናቸው (2)\n\nእግዚአብሔር በሙሴ እጅ ባህርን ከፈለ\nከፈርኦን ሰራዊት ህዝብን ከለለ\nእግዚአብሔር ከኖህ ፈጸመ መሀላ\nምድር እንዳትጠፋ ከእንግዲህ በኃላ (2)\n\nበጥላ በልብሳቸው ደዌን ፈወሱ\nምስክሮቹ ሆነው ተመላለሱ\nጌታ ስላለ ከቅዱሳን ጋር\nስልጣን ሰጣቸው ከሰማይ በምድር (2)\n\nእንደደመና ሰፍረው በዙሪያችን\nስላሉን ምስክሮች ለነብሳችን\nእንድንማጸን በህያው ስማቸው\nአሉ በቀኙ ስላከበራቸው (2)\n', 'am', 366, 0),\n(1, 'ሞትን ዘለፈዉ', 'ሞትን ዘለፈዉ\nሞትን ዘለፈዉ ማሰሪያዉን ቆረጠ ማነዉ በፍቅሩ ያልተለወጠ\nአዳነን ገዛን በደሙ(2)\nምስጋና ይሁን ለስሙ(2)\n\nአዝ፦\nወረደ በአባቱ ፍቃድ\nየእንባችን ጅረት እንዲያደርቅ\nየሞትን ክንዱን ሰብሮልን\nህይወትን ለብሰን ዘመርን\nአቤቱ እንወድሃለን ምስጋና\nለአንተ እንሰጣለን እልልታ ዉዳሴ ቀናይ\nዘልዓለም ለአንተ አዶናይ(2)\n\nአዝ፦\nሰስኦልን በእግሩ እረገጠ\nበደሙ ጠላትን ገለጠ\nዝማሬዉ አሁን ያድል ነዉ\nለአዳኙ የምንሰዋዉ\nአቤቱ እንወድሃለን...\n\nአዝ፦\nሊያድነን እሱ ታመመ\nሲቆስል ሁሉን አከመ\nሰላምን በምድር መላ\nተሰቅሎ ሆነልን ተድላ\nአቤቱ እንወድሃለን...\n\nአዝ፦\nወለደን ከማይጠፋ ዘር\nአዲስ ሰዉ ሆነን በእግዚአብሔር\nክሳችን በእሱ ተቀዳ\nአለብን የዉለታ ዕዳ\nአቤቱ እንወድሃለን\nምስጋና ለአንተ እንሰጣለን\nእልልታ ዉዳሴ ቀናይ\nዘላዓለም ለአንተ አዶናይ(2)\n\nዘማሪ ገ/ዮሐንስ\n', 'am', 367, 0),\n(1, 'ሁሉን በሁሉ የሚገዛ', 'ሁሉን በሁሉ የሚገዛ\nሁሉን በሁሉ የሚገዛ ሁሉን በሁሉ የሚሰራ\nእርሱ ነው እግዚአብሔር በግርማው የተፈራ\nእርሱ ነው እግዚአብሔር በግርማው የተፈራ\n\nሰማይና ምድር የዘረጋ\nሁሉንም በቃሉ ያረጋ\nባለ ፀጋ ነው የማይሾሙት\nበመዳፉ ነው ሞትና ህይወት\nባለ ሥልጣን ነው የማይሾሙት\nበመዳፉ ነው ሞትና ህይወት\n\nባህርን ከፍሎ ያሻገረ\nየሞትን ቅጥር የሰበረ\nነብሱን የሰጠ ለወዳጆቹ\nምህረት ይቅርታን አየን ከእጆቹ\n\nእስከ ሞት ድረስ የታገሰ\nያዳምን ቁስል የፈወሰ\nየገዛ ዓለማትን ፈጥሮ\nነፃ ያወጣን ሲኦልን ሰብሮ\n\nፀሐይ ጨረቃን ያዘጋጀ\nየብስና ባህርን ያበጃጀ\nበሥልጣን ያለ በኃይል በብርታት\nማነው የሚመስለው እሱን ከአማልክት\n', 'am', 368, 0),\n(1, 'እኛን ከወደደበት', 'እኛን ከወደደበት\nእኛን ከወደደበት ከጥልቅ ፍቅሩ የተነሳ\nበደላችን ተሻረ ኃዘናችን ተረሳ (2)\n\nአዝ፦\nጽድቃችን ሆኖ እንደመርገም\nነፍሳችን ዝላ በሞት ሸክም\nስለወደደን ጌታ ፈቅዶ\nይኸው አዳነን እንዲህ ወርዶ\n\nአዝ፦\nከጥልቁ ጉድጓድ ተጥለን\nጽኑ መከራ ውስጥ ሳለን\nክርስቶስ በስጋ ተገልጦ\nሕይወትን ሰጠን ሞትን ውጦ\n\nአዝ፦\nታስሮ ወረደ በፍቅር\nመዳፉን ሰጠ ለችንካር\nየባዘንነውን ሰበሰበን\nርቀን ነበር አቀረበን\n\nአዝ፦\nቁጥር የለውም ለዘመኑ\nድንበር የለውም ለማዳኑ\nይኸው ሞትን አሰናበተ\nሰማይ በደሙ ተከፈተ\n\nዘማሪ ገ/ዮሐንስ ገ/ጻድቅ\n', 'am', 369, 0),\n(1, 'አብ የተከለው አይነቀልም', 'አብ የተከለው አይነቀልም\nአብ የተከለው አይነቀልም\nያድጋል በጸጋ ለዘለአለም\nየወይን ግንዱን የተደገፈ\nያልፋል ሁሉንም እያሸነፈ (2)\n\nእረኛው ሲመታ መንጋው ሲበታተን\nእስከ ሞት ታምነናል እንደገና ሲያየን\nእፍ ያለብን መንፈስ ሀይልን አስታጥቆናል\nእየተገደልን ህያዋን ሆነናል\nበእሳት ላንቃ ያልጠፋነው\nበጌታ ቃል ስሰብከን ነው (2)\n\nአዝ፦\nበደርቤን ልስጥራን ዞረን በቤሪያ\nሰላሙን አወጀን ብለን ሀሌ ሉያ\nስደት ሲከተለን በሀይማኖት ፀንተን\nየገባንን እውነት ለአለም አዳረስሁ\nበመገፋትህ ያተረፍነው\nመክበርና መባረክ ነው (2)\n\nአዝ፦\nለአህዛብ ተሰብኮ ተገልጧል ማዳኑ\nኢየሱስ ህይወት ነው በስሙ ላመኑ\nበእስር ቤት ተዘግቶ ወንጌል አይከደን\nሰንሰለቱ እስኪወልቅ እርሱን እንሰብካለን\nየዝምታ ቀን የለንም\nሳንመሰክር አንኖርም (2)\n\nአዝ፦\nበክርስቶስ ጥበብ ያለች ክርስትና\nየገሀነም ደጆች አይችሏትምና\nሁሉን ነገር አልፈን ዛሬ ቀና ያልነው\nለማታልፈው መንግስት ስለተከለን ነው\nያሻገረን ክንደ ብርቱ (2)\nአስተምሮናል በህይወቱ\nመልሶናል ወደ እረፍቱ\n\nዘማሪ ገብረዮሐንስ ገብረፃድቅ ', 'am', 371, 0),\n(1, 'ማዳንህን ጽድቅህን እረፍትህን', 'ማዳንህን ጽድቅህን እረፍትህን\nማዳንህን ጽድቅህን እረፍትህን\nሰላምና ጸጋ በረከትህን\nዐይቻለሁ ለሕዝብህ ያደረከውን\nአሰናብተኝ በሰላም ባሪያህን\n\nእጠባበቅ ነበር የእስራኤልን መጽናናት\nብርሃን እስኪመጣ እስኪገለጥ እውነት\nይሄን ሁሉ ዓየሁ ቆሜ በመቅደስህ\nዘመኔ ታድሶ ጌታ ስታቀፍህ\n\nኑሮዬን ስገፋ ከአልጋ ተጣብቄ\nእስከምትመጣ ትንቢቱን ጠብቄ\nበእርጅና ዘመኔ አደረከኝ ጎልማሳ\nበክንዶቼ ይዤህ ዘለልኩ እንደ እምቦሳ\n\nአሁን እንደ ቃልህ ባሪያህን አሰናብት\nከቅዱሳን ጋራ እንድኖር በገነት\nከቶ አልበልጥምና እኔ ከአባቶቼ\nበጽድቅ ላንቀላፋ ከእቅፍህ ገብቼ\n', 'am', 372, 0),\n(1, 'በምስጋና', 'በምስጋና\nበምስጋና ተማርኳል ልባችን\nበውዳሴ ረካች ነፍሳችን\nስለወደድህ ስላፈቀርከን\nስለክብርህ እንዘምራለን።\n\nለዘለዓለም የማትረሳን የማትተወን\nቸርነትህን ምሕረትህን ያደረክልን\nእንሰዋለን የምስጋናን መስዋእት\nበቀንና በለሊት።\n\nየሠራኸውን በጎነት ስናስብ\nበመገረም በመደነቅ አልን እጹብ\nለአንተ ክብር ቅኔና ውዳሴ\nእንደ አሮን እንደ ሙሴ።\n\nተቀኘንልህ በመሰንቆ በበገና\nሕዝብህ ቆሞ ለውዳሴ ለምስጋና\nዐይቷልና ቀራንዮ ፍቅርህን\nሊያከብር ወጣ ስምህን።\n\nበሥራህም ተገርመናል ተደንቀናል\nንጹህ ፍቅርህን ቀራኒዮ ላይ ዐይተናል\nስናመልክህ እኖራለን እስከሞት\nአግኝተናል በአንተ ሕይወት።\n\nበዘማሪ ገብረ ዮሐንስ ገብረ ጻድቅ\n', 'am', 373, 0),\n(1, 'እየሰፋ እየበዛ ፍቅሩ', 'እየሰፋ እየበዛ ፍቅሩ\nእየሰፋ እየበዛ ፍቅሩ\nከልሎናል ከሰይፍ ከጦሩ\nተጠልለን በማይዝል መዳፍ\nስንት መአት ስንት ለሊት አለፉ\n\nአዝ፦\nሳይፈርድብን እንደ በደላችን\nሳያጠፋን ፈጥኖ በኃጢያታችን\nበምህረቱ ብዛት ጎበኘን\nበማያልቀው ፍቅሩ እያየን\n\nአዝ፦\nስንጠይቀው አብዝቶ እየሰጠ\nስናንኳኳ በር እየከፈተ\nይሰማናል እርሱ ደግ ነው\nላይከለክል ጌታ ሰጪ ነው\n\nአዝ፦\nበቃ ሲባል ይሄው አስቀጠለየ\nየኃጢያታችን ሸክም እያቀለለ\nበንስሃ አድስ አድርጎናል\nስንመለስ ተቀብሎናል\n\nአዝ፦\nአልተወንም ስለ ቅዱስ ስሙ\nጠብቆናል በፅኑ ሰላሙ\nበርህራሄው ብዛት የተነሳ\nየመከራው ዘመን ተረሳ\n\nዘማሪ ገብረ ዮሐንስ ', 'am', 374, 0),\n(1, 'የጠራ ይድናል', 'የጠራ ይድናል\nስብሐት ለአብ ስብሐት ለወልድ\nስብሐት ለመንፈስ ቅዱስ\nለአብ እና ለወልድ ለመንፈስ ቅዱስም\nምስጋና ለማቅረብ ከቶ አንወሰንም\nዛሬም ወደፊትም ደግሞም ዘላለም\n\nከዚህ ማራኪው ከአሸናፊው አለም\nየጠራ ይድናል የፈጣሪውን ስም\nበእውነት ያለ ሀሰት ያለ ጥርጥር\n\nከቶ መድኃኒቱን የሚጠላ የለም\nኑሮችን እንዲያምር አንድነታችንም\nሊኖረን ይገባል ፍቅርና ሰላም\n\nያልከውን አስበህ እናንተ ሁላችሁ\nሁለት ሶስት ሆናቹ በስሜ ካላችሁ\nእኔም እገኛለው ከመካከላችሁ\n', 'am', 375, 0),\n(1, 'የአምላክ ቸርነቱ', 'የአምላክ ቸርነቱ\nእስከለዓለም ምሕረቱ\nአያልቅም ብዙ ነው የአምላክ ቸርነቱ\n\nከማርያም የነሳው ያ ቅዱስ ስጋው\nቀራንዮ ሲውል የሚያሳዝነው\n\nበፈጠረው ፍጥረት እጅግ ተሰቃይቶ\nነፍሳትን አወጣ ከሲኦል ጎትቶ\n\nየሰው ልጅ ሁል ጊዜ\n\nየሰው ልጅ ሁል ጊዜ በጣም ደስ ቢለው\nደሞ የጭንቁን ቀን ማሰብ ተገቢ ነው\n\nምንም ቢደሰቱም ቢበዛም ምቾት\nአይቀርም በኃላ መወሰድ መሞት\n\nችግር ቢደራረብ ሀዘን ቢከበን\nከክርስቶስ ፍቅር ማንም አይለየን\n\nሳናውቀው ዳቢሎስ እንዳይነጣጥለን\nነቅተን እንጠብቅ የእምነት ሰይፍ ይዘን\n', 'am', 376, 0),\n(1, 'ኑ እንቅርብ', 'ኑ እንቅርብ\nኑ እንቅረብ መጠራት ሳይመጣ\nሥጋውን እንብላ ደሙንም እንጠጣ\nየቀራንዮ በግ የአምላክ ሥጋው\nተሰውቶልናል እንመገበው\n\nእድፉን ኃጢአታችን በንሰሐ አንጽተን\nእንቀበል አምነን በልጅነታችን\n\nመቅረብ ወደጌታ በእውነት የሚገባው\nበስተርጅና አይደለም በወጣትነት ነው\nጨረቃና ፀሐይ ደም የለበሱለት\nከዋክብተ ብርሃን የተነጠፉበት\nይኸው ተፈተተ እሳተ መለኮት\n\nቅድስት እናታችን ቤተክርስቲያን\nትጋብዘናለች ሥጋና ደሙን\nየአማኑኤል ሥጋ ይኸው ተዘጋጀ\nለግብዣው ተጠራን አዋጁ ታወጀ\n\nመጥቁ ተደወለ እንቅረብ በእልልታ\nበኋላ አይረባንም ዋይታና ጫጫታ\nይህችን ዕድል ፈጥነን እንጠቀምባት\nዓለምን አልያዝንም ብዙ ልንቆይባት\n\nአሁኑን ቅረቡ ታውጆአል አዋጁ\nየይለፍ ደብዳቤ ስንቅን አዘጋጁ\nይህ ዓለም ጠፊ ነው በሀብት አትመኩ\nብሏል አምላካችን ተስፋችሁን እንኩ\n', 'am', 377, 0),\n(1, 'ጌታ ሆይ', 'ጌታ ሆይ\nጌታ ሆይ አይሁድ አማጽያን ሰቀሉህ ወይ\nየአለም መዳኒት የአለም ሲሳይ ሰቀሉህ ወይ\n\nየአዳም በደል አደረሰህ አንተን ለመስቀል\nየሔዋን ስህተት አበቃህ ለሞት ቸሩ አባት\n\nንጹህ ክርስቶስ ሆንክ በደለኛ ብለህ ስለእኛ\nመስቀል አሸክመው አስረው ገረፋህ እያዳፋህ\n\nግብዞች እንደራሳቸው መስሎቸው\nምራቅ እየተፋ በፊትህ ቀለዱ አንተን ሊጎዱ\n\nእጅ እና እግርህ በችንካር ተመታ የአለም ጌታ\nየሾህ አክሊል ደፋህ ጎንህም ተወጋ አልፋ ኦሜጋ\n\nበመስቀል ላይ ተጠማሁ ስትል ታላቅ በደል\nሐሞት እና ከርቤ ሰጡህ ቀላቅለው ጠጣ ብለው\n\nይቅር ባይ ግልፅ በደላችን ሁሉን ስታይ\nአንተው ይቅር በለን በኛ ሳትከፋ እንዳትጠፋ\n', 'am', 378, 0),\n(1, 'አንቺ ቤተልሔም', 'አንቺ ቤተልሔም\nየአለም መዳኒት የተወለደብሽ\nአንቺ ቤተልሔም የተቀደስሽ ነሽ\nየአማልክት አምላክ ንጉሰ ነገስት\nኃያላን በሙሉ የሚሰግዱለት\nበጨርቅ ተጠቅልሎ ተኛ ከበረት\n\nአዋቂዎች ሁሉ በቅን ሀሳባቸው\nወደ አንቺ ተጎዙ ኮከብ ሲመራቸው\n\nለተከታይ ትውልድ ምሳሌ በመሖን\nሰግደው ገበሩለት ወርቅ እጣን ከርቤውን\n\nየሚያድለው ጌታ ዕውቀት ለህጻናት\nየሚመሠገነው በአፈ መላእክት\nከእንስሳት ጋራ ከበረት\n\nበስጋ ተገልጦ ረቂቅ ምስጢሩ\nሰውና መላዕክት በአንድነት ዘመሩ\n', 'am', 379, 0),\n(1, 'የሕይወት እንጀራ', 'የሕይወት እንጀራ\nሞተሀል እና ስለ እኔ ምንም ሳይኖርብህ ጥፋት\nተከሰህ ተወቅሰህ በጲላጦስ ፊት\nእየሱስ አምላክ ምሕረት ስብሀት ለከ\n\nስለእኛ ብለህ በሜዳ ሆሳዕና ዓለም ክርስቶስ\nልብስህን ገፈፋህ ትንቢቱ ሲደርስ\nተራቆተ የድሆች ልብስ ስብሀት ለከ\n\nያንተ መንገላታት ሁልጊዜ ያሳዝነኛል ሲወራ\nበመስቀል ላይ ሆነህ ያየሀው መከራ\nኢየሱስ የህይወት እንጀራ ስብሀት ለከ\n\nጎንህ ሲወጋ በጦር የተናገርከው ነገር\nየመለስክላቸው ኧረ ምን ነበር\nኢየሱስ አምላክ ምህረት ስብኃት ለከ\n\nስላላወቁህ አንተን የአለም መዳኒት መሖንክን\nመቱት በጭካኔ ብርሀን ፊትህን\nአፌዙበት በጌታችን ስብኃት ለከ\n', 'am', 380, 0),\n(1, 'አልቀረም ተነሳ', 'አልቀረም ተነሳ\nተገርፎ ተሰቅሎ የሞተው አንበሳ\nተገንዞ በጨርቅ ተቀብሮ እንደእሬሳ\nበሰው ልጅ ተይዞ አልቀረም ተነሳ\n\nእናምናለን ትንሳዬህን\nበስልጣንህ መነሳትህን\nአርአያ ነው እና ለሁላችን\n\nአፈር ቢረበረብ ሳጥን ቢደረደር\nድንጋይ በድንጋይ ላይ ደጋግሞ ቢነባበር\nምድር አልቻለችም አምላክን ለመቅበር\n\nአምላክ ስትነሳ ፈርሶ መቃብሩ\nሴቶች ትንሳኤህን ደፍረው ተናገሩ\nአሰንሞታለን ብለው ማንንም ሳይፈሩ\n\nእንግዲህ አልፈራም ሞት እና ኩነኔ\nአምላክ ከሞተልኝ ተሰቅሎ ስለእኔ\nተጀምስሶልና የሞት ስልጣኔ\n', 'am', 381, 0),\n(1, 'እንደ ቸርነትህ', 'እንደ ቸርነትህ\nእንደ ቸርነትህ አቤቱ ማረኝ\nእንደምህረትህ ይቅርታን ስጠኝ\nከኃጢአቴም አንጻኝ ከብዙ በደሌ\nለዚያች ክፉ ኃጢአት እንዳልሖናት ሎሌ\nእኔም አመፃዬን በደሌን ሳውቀው\nከቶ የሚያድነኝ ቸርነትህ ነው\nአንተን ብቻ በደለኩ ክፉም አደረግሁ\nአሁን ይቅር በለኝ ከፊትህ ወደቅሁ\nከፊትህ ወድቄ ስለምን አንተን\nመውደቄን ተመልከት አምላከ ብርሀን\n', 'am', 382, 0),\n(1, 'አይደለም ምድራዊ', 'አይደለም ምድራዊ\nይህ ቁርባን ክብር ነው ፍጹም ሰማያዊ\nእንዳይመስለን ተራ አይደለም ምድራዊ\n\nዋ ምን አፍ ነው የሚቀበለው\nዋ ምን ጥርስ ነው የሚያላምጠው\nዋ ምን ሆድ ነው የሚሸከመው\nነበልባል ያለበት የሚያቃጥል ነው\nበንጽህና ሆኖ ላልተቀበለው\nየሚያፍገመግም የሚጎዳ ነው\n\nአምላካችን ሆይ አንተ ይቅር ባይ\nእንደቸርነትህ በደልን አትይ\nአሜን አሜን ብለን ተቀብለናል\nበድፍረትም ሳይሆን በፍርሀት ቀርበናል\n\nማህበር ይገባናል በንጽህና ሆነን\nደፍረን አናቅለው እንዳያቃጥለን\nእንደምታዮት ይህ ቁርባን ፈራጅ ነው\nእንደሌላ ሳይሆን የተቀደሰ ነው\n\nሱራፌል ኪሩቤል ፀርተው መንበር\nለመያዝ ያልቻሉት ፈርተውት በክብር\nእኛ ተመግበነው አገኘን ድኀነት\nለነብስም ለስጋም ሆነልን ህይወት\n', 'am', 383, 0),\n(1, 'በረከት ላክላት', 'በረከት ላክላት\nሃሌ ሃሌ ሉያ ሃሌ ሃሌ ሉያ\nህዝቦቹን ባርክላት ለኢትዮጵያ\n\nበዘር በሀይማኖት እንዳይለያዩ\nአንድነት ስጣቸው እንዳይለያዩ\nምድሯ እንድትለመልም እንድትሖን ሰላም\nልጆቿን ባርክላት መድኃኔአለም\n\nእጆቿን ዘርግታ ቆማ ስትጸልይ\nበረከት ላክላት ሆነህ ከሰማይ\nትሰግድልሀለች ወገቧን አጥብቃ\nቆይታለች እስካሁን ማተቧን ጠብቃ\n\nአትርሳት ጧት ማታ እርሷ እንዳትከፋ\nጥላቻ ይወገድ ጦርነትን አጥፋ\nበረድኤትህ ጎብኛት ረሀብ ይወገድ\nበሽታ እና ችግር ይገታ መሰደድ\n', 'am', 384, 0),\n(1, 'አልፋ እና ኦሜጋ', 'አልፋ እና ኦሜጋ\nአልፋ እና ኦሜጋ ፈጣሪ የሖንክ\nበከሀዲዎች እጅ ተይዘህ ቀረብክ\n\nተገፋህ ተደፋህ በጥፊ ተመታህ\nእየደበደብህ ክርስቶስ ሆይ አሉህ\nጽድቅን ስለሰራህ በወንጀል ከሰሱህ\nለአዳም ቤዛ ሆነህ ብዙ ተንገላታህ\n\nቅዱሳን እጆችህ የፍጥኝ ታስረው\nእንደበግ ተጎትተህ ብትምራቸው\nየትም ቦታ ያለህ ሁሉን የምታውቅ\nፊትህን ሸፈኑ ለመመጻደቅ\n\nበአውደ ምኩናን ከጲላጦስ ዘንድ\nአሳልፈው ሰጡህ አጋልጠው ለፍርድ\nከሀና ቀያፋ ከመሳፍንቱ ደጅ\nከነሄሮድስ ዘንድ አቀረብህ በአዋጅ\n\nግርፋት ሕማሙ አልበቃም ብሎህ\nበመስቀል ላይ ልትውል ተፈረደብህ\nሳዶር ና አላዶር ዳናት እና አዴራ\nተፈልገው መጡ ለችንካር በተራ\nአምስቱ ችንካሮች ቅንዋት መስቀል\nወገኖች መጡ ሥጋህን ለማቁሰል\n\nየሰላም ባለቤት ደረትህ ተወጋ\nሊያያዝ በችንካር እጅህ ተዘረጋ\nምራቅ ተፋብህ ራስክን ሊጎዱ\nግፈኞች አይሁዶች ባንተ ላይ ቀለዱ\n', 'am', 385, 0),\n(1, 'የእጆችህ ስራ ነን', 'የእጆችህ ስራ ነን\nአምላክ አትተወን የእጆችህ ስራ ነን\nበየቀኑ ወዳንተ እንጮሀለን\nዝቅ ብለን እንለምንሀለን\n\nቀድሞ አባቶቻችን በአንተ ስላመኑ\nታድናቸው ነበር ቆመው ሲለምኑ\n\nአሁን ከመንበርህ ከደጅህ ወድቀናል\nእንደቸርነትህ አድነን ብለናል\nአንተው አሳልፈው ይህን ክፉ ጊዜ\nእባክህን ስጠን የንስሀ ጊዜ\n\nይቅር ባይ ነህ እና ሕዝብህን ተመልከት\nእጅግ በዝቶልናል የተዘጋው ቤት\nዘንባባ ይዘናል እባክህ ዛሬም ና\nዓለም ተበክሏል አንተው ስጠው ጤና\n', 'am', 386, 0),\n(1, 'ክርስቶስ ሲመጣ', 'ክርስቶስ ሲመጣ\nአቤት የዚያን ጊዜ ክርስቶስ ሲመጣ\nትንሹም ትልቁም መድረሻውን ሲያጣ\n\nከምስራቅ ከምዕራብ ከሰሜን ከደቡብ\nአየናት ሲላኩ መዓአትን ለማዝነብ\n\nሰማያትና ምድር ባንድ ሲዋሀዱ\nየት ይሆን መድረሻው የት ይሆን መንገዱ\n\nጻድቃን በቀኝ በኩል ኃጣንም በግራ\nሲነፋ መለከት ሲደለቅ እንዚራ\nምድር ቀውጢ ስትሆን አፅም ሲሰበሰብ\nሀፍረት ይይዘዋል ሰው ለፍርድ ሲቀርብ\n\nጩሀት ይበረታል የማይጠቅም ለቅሶ\nእንደቁራ ጠቁሮ ጽልመትን ተላብሶ\nገነትን ሲያገኙ ጻድቃን በስራቸው\nኃጥአን ወደ ሲኦል ተፈረደባቸው\n', 'am', 387, 0),\n(1, 'ተነሺ ኢትዮጲያ', 'ተነሺ ኢትዮጲያ\nተነሽ ኢትዮጲያ\nእንበል ሀሌሉያ\n\nበያሬድ ማህሌት ተነሺ ኢትዮጲያ\nበጣም ተደነቂ ተነሺ ኢትዮጲያ\nመሠረት አንቺ ነሽ ተነሺ ኢትዮጲያ\nለዜማ ፈለግ ተነሺ ኢትዮጲያ\n\nሃሌሉያ እያለ ዓለምን የቃኘ\nያሬድ ታሪክሽ ነው በረከት ያገኘ\nዕዝል እና ግዕዙን አራራዮን ቃኝቶ\nለልጆችሽ ሰጠ በመንፈስ ተመርቶ\n\nድፋት እና ጭረት ምልክት ምሳሌ\nጭረት ና ደረት ታጅበው በሃሌ\nየሚንቆረቆሩት አንብርና ርክርክ\nጽናጽል ከበሮው ተውበው በመድረክ\n\nድምቀትሽ በሱ ነው ድጓ ሲታወጅ\nአንዴም አይጠገብ በተዋህዶ ደጅ\n\nበያሬድ ዝማሬ መቋምያ ጽናጽል\nበዜማ ተመስሏል ንጉስ ገበረ መስቀል\nጽዋትወ ዜማ ሀብትሽ ነው ኢትዮጲያ\nስበኪ ወንጌልን እያልሽ ሀሌ ሉያ\n', 'am', 388, 0),\n(1, 'ዓለም ወረተኛ', 'ዓለም ወረተኛ\nዓለም አታላይ ነሽ ዓለም ወረተኛ\nያንቺ ዝምድና ይቅርብኛ ዓለም ወረተኛ\n\nዓለም ከንቱ ለኔ ዓለም ከንቱ ለኔ\nአንቺ ስከተል ቀኑ መሸ አለቀ ዘመኔ\n\nዓለም ያንቺ መውደድ ዓለም ያንቺ ፍቅር\nአይዘልቅም እና ይቅር ይቅር ዓለም ያንቺ ፍቅር\n\nመዝሙር በመሰንቆ መዝሙር በበገና\nየነብስ ምግብ ልዮ ቃና መዝሙር በበገና\n\nጾም ጸሎት ስግደት\nየነብስ የስጋ መድሀኒት\nጾም ጸሎት ስግደት\n', 'am', 389, 0),\n(1, 'አድፈዋል እጆቼ', 'አድፈዋል እጆቼ\nአድፈዋል እጆቼ አቤት\nኃጢአት ሰርተዋል\nአድፈዋል እግሮቼ አቤት\nተመላልሰው\nየሰማዮ እሳት ይቆያቸዋል\n\nኧረ በምን ላንጻው አካሌን በሙሉ\nህሊናዬን ነሳኝ የሰራውት ሁሉ\nእንደ ሀኪም ሆኜ ውስጤን ስመረምር\nተሸክሜ አየሁኝ የኃጢአትን ክምር\n\nምግባር የጎደለኝ ግብዝ ነኝ ደካማ\nበምህረት ጎብኘኝ አውጣኝ ከጨለማ\nየዚያን የፍርድ ቀን ሳስታውሰው እኔ\nወዴት እገባለው እላለውኝ እኔ\n\nዓለም አሸነፈኝ አንተን እረስቼ\nትካዜው በዛብኝ አለቀሱ አይኖቼ\nመንታ መንገድ ቆሜ እባዝናለሁ\nምህረትህን አሳየኝ እማጸናለሁ\n', 'am', 390, 0),\n(1, 'በመስቀል ላይ ዋለ', 'በመስቀል ላይ ዋለ\nበአደባባይ ተሰቀለ\nበአርብ ቀን በመስቀል ላይ ዋለ\nቀኑ ጨለመ ጨረቃም ደም ሆነ\n\nከጲላጦስ ከሄሮድስ ሲከሰከስ ሲወድቅ\nተንገላታ ተገረፈ ተራቆተ ተገፈፈ\nዘበቱበት ግብዞች ተሳለቁ አይሁዶች\nበሰላሳ ብር ተሸጠ ለክፋዎች ተለወጠ\n\nተቸንክሮ ተሰቀለ ጭካኔያቸው አመረረ\nስለት ባለው ጦር ተወጋ\nየዓለም ክብር የዓለም ጸጋ\n\nለአመጸኞች ተወላቸው\nሲበድሉት አዝኖላቸው\nበፍቃዱ ነፍሱን ሰጠ\nበዚያች ሰአት ተለወጠ\n', 'am', 391, 0),\n(1, 'በአንተ ተሻገርኳት', 'በአንተ ተሻገርኳት\nበአንተ ተሻገርኳት ጭንቋን ቀን አለፍኳት\nያሳለፍኳትን ቀን በጭንቀት በመከራ\nአምላክ አትመልሳት ያቺን ቀን አደራ\n\nበኃጢአት ወድቄ ስጋዬ ጎስቁሎ\nጭራሹን ሳልጠፋ አዳንከኝ በቶሎ\n\nበደስታዬ ጊዜ የነበረኝ አብሮኝ\nመከራ ሲመጣ ፊቱን አዞረብኝ\n\nየዘላለም አምላክ ቸርነትህ ባይኖር\nቢሆንማ እንደሰው ጠፍተን ቀርተን ነበር\n\nመቀበል ደግ ነው ፈተናውን በጸጋ\nመጨረሻው ያምራል አለው ትልቅ ጸጋ\n', 'am', 392, 0),\n(1, 'ፍርድህን አቃና', 'ፍርድህን አቃና\nጣትህን በሰው ላይ ፈጥነህ ከምትቃጣ\nየራስህን ጉድፍ ቅድም ከአይንህ አውጣ\n\nበሌላው የምትፈርድ ማነህ አንተ እያሉ\nሰለስቱ ጣቶች አንተን ያሳያሉ\n\nየማትፈልገውን በአንተ እንዲደረግ\nአንተም በሌላው ላይ ፈጽመህ አታድርግ\n\nህግን ተከትለህ ፍርድህን አቃና\nበሰፈሩት ቁና መሠፈር አለና\n\nሰውን አበላልጠህ ፍርድ እንዳታዛባ\nመልበስ ይገባሀል የጥበብን ካባ\n\nየጥበብን ካባ ሁሉም ከለበሰ\nፍቅር በአለም ላይ ሰላምም ነገሰ\n\nጠላትህን ውደድ ነውና የሚለው\nእሱ ቢበድልህ አንተ ይቅር በለው\n', 'am', 393, 0),\n(1, 'ከንቱ ነኝ', 'ከንቱ ነኝ\nከንቱ ነኝ የከንቱ ከንቱ ነኝ\nዋስትና መከታ እግዚአብሔር ካልሆነኝ\nተስፋ የሚሖነኝ ሕይወት የሚሰጠኝ\nእግዚአብሔር ብቻ ነው የሚያስተማምነኝ\nአምላኬ ብቻ ነው የሚያስተማምነኝ\n\nእኔ ንጉስ ነበርኩ በክብር ያጌጥኩኝ\nሁሉንም በምድር ላይ በጥበብ አጌጥኩኝ\nየዚህ አለም ደስታ ምንም አላዋጣኝ\nበመጨረሻ ግን በሞት ተወሰድኩኝ\n\nከፀሀይቱ በታች አዲስ ነገር የለም\nሰዋች ይደክማሉ እስከ ዘለአለም\nጥበብን ፍለጋ ደክሜ ነበር\nሁሉም ከንቱ ሆኖ በመቃብር ቀረ\n\nከእኔ አስቀድመው የከበረ ሁሉ\nአፈር ተጭኖቸው ከመቃብር አሉ\nእብደት እና እውቀት ሁሉን አወኳችሁ\nምንም ቋሚ የለም ሁሉም ከንቱ ናቸው\n\nልቤን የሰጠሁት ተስፋ የጣልኩበት\nአልጨበጥ ብሎኝ አለሁኝ በጭንቀት\nየጥበብም ብዛት ለትካዜ ሰጠኝ\nእኔ በዚህ ምድር እጅግ ጎስቋላ ነኝ\n\nልቤንም ፈተንኩት በደስታ ብዛት\nየዚህ አለም ጣዕሙን ልቤን አቀመስኩት\nሳቅም በልቤ ውስጥ ይፍለቀለቅ ነበር\nሁሉም ከንቱ ሆነ ገብቶ ከመቃብር\n', 'am', 395, 0),\n(1, 'የማህጸን ፀብ', 'የማህጸን ፀብ\nርብቃ ጸነሰች መካኒቱ መንታ\nወገን እንዲበዛ ህዝብ እንዲበረታ\nገና ከማህጸን ነበር ሲገፋፋ\nቂም እና በቀል ለወገን ሲያተርፋ\n\nርብቃ ተናዳ በማህጸንዋ ጸብ\nሚስጥሩን ጠየቀች ወደ አምላክ በመቅረብ\nእግዚአብሔር አላት በአምላካዊ ቃል\nሕዝብ እና አህዛብ በሆድሽ ውስጥ አሉ\n\nገና በማህጸን ሳሉ ይጣላሉ\nህዝብም በህዝብ ላይ እጅግ ያይላሉ\nታላቅ ለታናሽ ሲገዛ ይኖራል\nይህ ትንቢት አይቀርም በአለም ይፈጸማል\n\nርብቃ አዘነች የመንቶቹ እናት\nየሆዷ ፍሬዎች ሲከፋፈሉባት\nእንደዚ ከሆነ ይህ ምኔ ለኔ ነው\nከማህፀን ሳሉ ሰላም ከሌላቸው\n\nየዛሬዋ ርብቃ ቤተክርስትያን ሆይ\nየማህፀንሽ ፍሬ ዛሬ እንዳይለያይ\nደርሶ በሚጠፋ በመብል ተታለን\nከኛ እንዳይወሰድ ልዮ ብኩርናችን\n\nኤሳው በምስር ወጥ ትንሽ ያደረገሽ\nየያዕቆብ ስስቱ ነጥቆ የወሰደሽ\nታላቋ ብኩርና ቤተ ክርስትያን ነሽ\nለቅድስት ኢትዮጲያ በግልጽ የተሰጠሽ\n\nስለዚህ ተስማማን በቀናች ሀይማኖት\nፍቅር አና ሰላም ወንድሞች እንመስርት\nአዲስ ትምህርት ይቅር የጥንቱን እንያዝ\nይበጀናል እና የመጣው ሲያያዝ\n', 'am', 396, 0),\n(1, 'ፍጹማን እንድትሆኑ', 'ፍጹማን እንድትሆኑ\nፍጹማን እንድትሆኑ ትዕዛዙን ፈጽሙ\nከእናንተ ጋር እንዲሆን የአምላክ ሰላሙ\nስለ ክፋ ምኞት ከአለም አምልጥችሁ\nከመለኮት ባህርይ ተከፋይ ሆናቹ\n\nከከበረው ተስፋው ከበጎ ስጦታው\nሰዎች እንሳተፍ ፍጹም አናመንታ\nስለዚህም ምክንያት ትጋትን አሳዩ\nየዘለአለም ተስፋን በእምነት እንድታዩ\n\nበእምነትም በጎነት ጨምሩ አብዝታችሁ\nሰማያዊ እንዲሆን በምድር ሕይወታችው\nእራስን በመግዛት መጽናናት ጨምሮ\nእግዚአብሔርን በመምሰል መዋደድን አብዙ\n\nየነገሮች ሁሉ ፍጻሜ የሆነው\nከሁሉ የሚበልጠው የእውነት ፍቅር ነው\nበቤተክርስትያን ስራ ፈት እንዳንሆን\nእነዚህ ፍሬዎች በምላት ይኑሩን\n', 'am', 398, 0),\n(1, 'ያ ደሃ ተጣራ', 'ያ ደሃ ተጣራ\nያ ደሃ ተጣራ እግዚአብሔርም ሰማው\nደርሶ ስላንኳኳው ከጸባኦት እንባው\nአምላክ በቸርነት በምህረት ጎበኘው\nባለቀሰ ጊዜ ግራ የገባው ሰው\nመሻትህ ብቻ ነው የሚፈለግብህ\nእግዚአብሔርን ጥራ እመን ትድናለህ\n\nንገረው ችግርህን የውስጥህን ብሶት\nይሽረዋልና አስፈሪውን ህይወት\nግራ የተጋባው የተከፋው ገጽህ\nይበራል በጸሎት አምላክህን ጠርተህ\nመሻትህ ብቻ ነው የሚፈለግብህ\nእግዚአብሔርን ጥራ እመን ትድናለህ\n\nለወገን ለዘመድ ያስቸገረው መላ\nሲቀል ታየዋለህ ካነባህ በኋላ\nሳቅና ንዴትህ ይቀራል ይሻራል\nበእርሱ ፈንታ ልብህ በሰላም ይሞላል\nመሻትህ ብቻ ነው የሚፈለግብህ\nእግዚአብሔርን ጥራ እመን ትድናለህ\n\nበከንቱ መጨነቅ ራስን መጥላቱ\nነውና የአጋንንት መግቢያ ምልክቱ\nሀዘን በህሊናህ በፈሰሰ ጊዜ\nንገረው ለአምላክህ የሆድክን ትካዜ\nመሻትህ ብቻ ነው የሚፈለግብህ\nእግዚአብሔርን ጥራ እመን ትድናለህ\n', 'am', 399, 0),\n(1, 'እመን ትድናለህ', 'እመን ትድናለህ\nእመን እንጂ በእቅፉ ነህ\nአይተውህም ትድናለህ\nጠብቆቱ የማይደክም\nየሚወድህ አባት አለህ\n\nጴጥሮስ እንዲራመድ በውሃ ላይ ጠራው\nውሃውም ታዘዘ በቃሉ ለጌታ\nእምነቱ ብትጎድል ጴጥሮስ በድካሙ\nወደ ጌታው ጮኸ ፈርቶ በመስጠሙ\n\nሁሉን የማዝ ነኝ መቶ አለቃው እኔ\nብላቴናው ታሞ ተኝቷል ከቤቴ\nጌታዬ ሳትገባ ከቤቴ ጣራ ስር\nይፈወሳል ልጄ ቃል ብቻ ተናገር\n\nእድናለሁ ሳልሞት ጨርቅህን ብዳስስ\nብላ ስላመነች በእምነት በመንፈስ\nነውሯን ሸፍነህ ደሟን አቆምክላት\nእምነትሽ አዳነሽ በሠላም ሂጂ አልካት\n', 'am', 400, 0),\n(1, 'ፈራሁ', 'ፈራሁ\nቀኑ ከረፈደ ከመሸብኝ መጣሁ\nደጃፍህ ላይ ቆምኩኝ እንዳልገባ ፈራሁ\nበደሌን ሳትመዝን ግቢ ብትልኝም\nሀጥያቴ ከበደኝ አላራመደኝም\n\nየሰው እድሜ አጭር ነው ጥቂት ነው\nእንዴት ነው ሳላውቅህ ዘመኔ ያለቀው\nጉብዝናዬን አለም ሲቃ ተጫወተብኝ\nእንዴት ብዬ ልርገጥ ደጅህን በድፍረት\nፈራሁኝ ልግባ ወይ አልግባ\nእንዴት ይመዝናል ያንተ ደም በኔ እንባ\n\nእኔ ፈራሁ እንጂ አንተ እኮ አታስፈራም\nመምጣቴ ነው ደስታህ ፍቅርህ አይታማም\nሽምቅቅ አለች ነፍሴ መስቀልህን ሳየው\nበደሌን አሰብኩት ደምህን እያየሁ\nፈራሁኝ ልግባ ወይ አልግባ\nእንዴት ይመዝናል ያንተ ደም በኔ እንባ\n\nበንፅህና ፊት እንዴት እቆማለሁ\nእንደ መላእክቱ በምን ጋርዳለሁ\nእራሴን መሸፈኛ ክንፍ የለኝም እኔ\nይታያል ሀጥያቴ የበደል እርቃኔ\nፈራሁኝ ልግባ ወይ አልግባ\nእንዴት ይመዝናል ያንተ ደም በኔ እንባ\n\nጠዋት እና ማታ ለመጣህ አንድ ነው\nአምሽቶም ለገባ እኩል ትከፍላለህ\nአብርሃም ወይ ይስሃቅ በድንኳንም ቢያድሩ\nበአንተ መንግስት ግን ከወንበዴ አይቀድሙም\nፈራሁኝ ልግባ ወይ አልግባ\nእንዴት ይመዝናል ያንተ ደም በኔ እንባ\n', 'am', 401, 0),\n(1, 'ቃልሽ ተቀየረ', 'ቃልሽ ተቀየረ\nቃልሽ ተቀየረ አንቺ እየሩሳሌም\nሆሳዕና እንዳላልሽ ክብር በአርያም\nስቀለው ስቀለው ብለሽ መጮህሽ\nያልሰጠሽ ምን አለ ያጎደለብሽ\n\nደም ግባቱ ጠፍቶ የአብ አንድ ልጅ\nሲገርፉት አመሹ በቀያፋ ደጅ\nአፉን አልከፈተም መልስንም ለመስጠት\nየውኃውን አምላክ ሃሞት ሲያጠጡት\n\nመቆም እስኪያቅተው ሰውነቱ ዝሎ\nመከራውን አየ ስለኛ ኃጢያት ብሎ\nየአማልክት አምላክ ተንገላታ እንደሰው\nየጠፋው አዳምን ቤቱ ሊመልሰው\n\nበሸላቾቹ ፊት ዝም እንደሚል በግ\nዝምታን መረጠ መልካምን ለማድረግ\nለሰው ያለው ፍቅር ወሰን አልነበረው\nእርሱ እየሸሸው በፍቅር ተከተለው\n', 'am', 402, 0),\n(1, 'ገበናዬን ሸፍኝልኝ', 'ገበናዬን ሸፍኝልኝ\nገበናዬን አደራ ሸፍኝልኝ ማርያም\nበጭንቅ ቀን በመከራ ጊዜ\nእንዳትረሽኝ በትካዜ\n\nጭንቀቴን ስነግርሽ አንቺን ቀርቤ\nመፍትሄ አግኝቷል ያዘነው ልቤ\nተስፋ አሳጥቶ ያደከመኝን\nተቆርጦ አየሁት ያሰቃየኝን\nእንደ ደመና ተገፎ ከአየሁ\nለክብርሽ ሙላት እዘምራለሁ\n\nጠላት ሊያጠፋኝ ቢነሳብኝ\nማዕበል አንስቶት ቢረብሸኝ\nየሰላሜን ሰው እጠራሻለሁ\nከኔ ጋር ከሆንሽ እረጋጋለው\n\nባልንጀሮቼ መክረው ሲርቁኝ\nተስፋ የለውም ብለው ሲተውኝ\nአንቺ አልተውሽኝም ልዮነሽና\nገመናን መክደን ታውቂያለሽና\nምህረትሽ ከቦ ለዚህ ከበቃሁ\nበምስጋና ቃል ድምጼን አጸናሁ\n\nማርያም በስምሽ ጭንቁን ቀን ልለፍ\nእንዳልወስድ በመከራ ጎርፍ\nከኃጢአት አለም ጣዕም ከሌለው\nነፃ አውጪኝና ነውሬን ሸፍኚው\n\nለእኔ አይገባም ያደረግሽልኝ\nብዙ ምስጢሬኝ የሸፈንሽልኝ\nየውስጥ ገመና ጉዴን ታውቂያለሽ\nአልተጋለጥኩም ትከድኚዋለሽ\nጎስቋላ ኑሮ ተዋበ አጌጠ\nመራራው ህይወት ባንቺ ጣፈጠ\n\nመስሎኝ ነበር የማያልፍ\nአየሁት ጭንቀቴ ሲገፈፍ\nለዳዊት ፅዮን ለሕዝቅኤል በር\nልወድቅ ልነሳ ለማርያም ክብር\n', 'am', 403, 0),\n(1, 'አመሰግናለሁ', 'አመሰግናለሁ\nየልቤን መሻት ስለሞላህ አመሰግናለሁ\nሁሌ በሥራህ እገረማለሁ\nማዳንህን ካየሁ የእጅህን ስራ\nከኔ ጋር ከሆንክ በስምህ ልኩራ\n\nአለኝ ያልኩትን ባጣሁት ጊዜ\nተስፋ ቆርጬ በዝቶ ትካዜ\nበሌላ መንገድ ትተካዋለህ\nተመስገንልኝ ትሞላዋለህ\n\nደስታው አይሻር አይለወጥ\nመራራ ነሮን የሚያጣፍጥ\nከአፈር አንስቶ ሕይወት ሰቶኛል\nጌታ ለነፍሴ ሰላም ሆኗታል\n\nኢያሱ ስምህን በዘውድ ጽፎ\nከነአን ገባ ቃዴስን አልፎ\nዮርዳኖስ ቆመ ታዞ ለክብሩ\nድንቅ ስራውን ኑ ተናገሩ\n\nባህር ሞገዱን በሥልጣን አዞ\nበፍቅርህ እጁ እጆቼን ይዞ\nከዘመን ዘመን አሸጋግሮኛል\nክብር ለስሙ ለአምላክ ይሆናል\n', 'am', 404, 0),\n(1, 'ትጉህ የማያንቀላፋ', 'ትጉህ የማያንቀላፋ\nትጉህ የማያንቀላፋ መልካም እረኛ\nለደካሞች የሚራራ የጽድቅ መገኛ\nማዕበል ሞገድ የማይገፋው መርከብ\nለአለም የማያበራ እውነተኛ ኮከብ\n\nጌታችን የማያይ ቢመስል የማይረሳ\nየባህሩ ቁጣ ጸጥ ይላል ሲነሳ\nሁከት እና ጭንቀት ቢሞላ ታንኳችን\nበእምነት እንቀዝፋለን ጌታ ነው መሪያችን\n\nምስካየ ህዙናን ክርስቶስን ይዞ\nማን ነው የሰመጠ በባህር ተጉዞ\nባላመነው ልቤ ፍርሃት ሲነግስ\nእምነት ጨምርልኝ የነፍሴ ንጉሥ\n\nውሀው ቢነዋወጥ ቢያፎጭም ከፊቴ\nሰማያን ያጸና አለ መድኃኒቴ\nባህሩ ቢሰፋ ብታንስም መርከቤ\nየተፈራው ንጉስ አለ ካጠገቤ\n', 'am', 405, 0),\n(1, 'እርሱ ያለው ላይቀር', 'እርሱ ያለው ላይቀር\nእርሱ ያለው ላይቀር መጨነቄ ለምንድነው\nማዘን መተከዜስ ለምንድ ነው\n\nዛሬን ደርሻለው የነገን አላውቅም\nአንተ ታውቃለህ እኔ አልጨነቅም\nእንደ ፍቃድህ ምራኝ እንደ ሀሳብህ አኑረኝ\n\nዕቅዴ ብዙ ነው እኔማ በልቤ\nፍቃድህ ከሌለ አይሞላም ሀሳቤ\nበዛሬው አልመካም የነገን አላውቅም\n\nችግሬን ሳስበው ተስፋ እቆርጣለሁ\nለበጎ እንደሆነ እዘነጋዎለሁ\nበእጆችህ ጌታ ልረፍ\nየመከራው ዘመን ይረፍ\n\nተረስቼ ነበር ካልጋዬ ላይ ውዬ\nእንደሰዎች ሀሳብ ሞተሀል ተብዬ\nአንተ ነህና ተስፋዬ\nህይወትን ምራት ጌታዬ\n', 'am', 406, 0),\n(1, 'ኦ ስሉስ ቅዱስ', 'ኦ ስሉስ ቅዱስ\nኦ ስሉስ ቅዱስ ተመስገን\nዓለማትን የፈጠረ እግዚአብሔር ተመስገን\n\nአዳም ሳይፈጠር በዙፋን ነበርክ\nባንድነት ሶስትነት እየተመሰገንክ\nመላዕክትን ፈጥረህ ስምህን ሊጠሩ\nበምስጋና ቆመው ካንተ ጋር ሊኖሩ\n\nየሰውን ልጅ ፈጥረህ ክብርህን እንዲወርስ\nአንተን በማወደስ ህይወቱ እንዲቀደስ\nእኛም ልንጠራህ ባይገባን እንኳን\nለምስጋና ቆመን ደጅህን አንኳኳን\n\nየዓለም ሁሉ ንጉሥ ያለሙ ፈጣሪ\nፍጥረትን በሙሉ አውሎ አሳዳሪ\nሥላሴን ላወድስ ቅዱስ ስሉስ ልበል\nበአለም ከመክበር በቤታቹ ልጣል\n\nዮርዳኖስን ልሁን ስላሴን ልያቸው\nበአንድነት ሶስትነት ቅዱስ ልበላቸው\nትባረክ ትቀደስ ነብሴ በስላሴ\nባባቶቼ አምላክ በአብርሀም በሙሴ\n', 'am', 407, 0),\n(1, 'ሥራው ድንቅ ነው', 'ሥራው ድንቅ ነው\nእግዚአብሔር ሥራው ድንቅ ነው\nለእኔ ያደረገው ብዙ ነው\nእግዚአብሔር ሥራው ድንቅ ነው\nለእኔ ያረገልኝ ብዙ ነው\n\nረዳቴ እርሱ ነው ከሰማያት\nእግዚአብሔር ጠባቂ ለእኔ ህይወት\nብርሃኑን በፊቴ የሚያበራ\nአምላኬ ድንቅ ነው የእርሱ ሥራ\n\nበመንገዴ ሁሉ የሚመራኝ\nስነሳም ስወድቅም የሚያስበኝ\nማንም አልመጣልኝ ከወገኔ\nከሁሉም ይበልጣል እርሱ ለእኔ\n\nየዕዳዬን ደብዳቤ ውድቅ አድርጎ\nህይወቴን መራልኝ ወደ በጎ\nኧረ እንደእግዚአብሔር ማን ይሆናል\nእርሱን ለሚፈሩት ይታመናል\n\nአንድ ቀን አስቤ ተጨንቄ\nለመኖር አልቻሉኩም ተጠንቅቄ\nሁሉን ነገር ለእርሱ ትቸዋለሁ\nበምህረቱ ጥላ እኖራለሁ\n', 'am', 408, 0),\n(1, 'ኃይሉን እንድትለብሱ', 'ኃይሉን እንድትለብሱ\nኃይሉን እንድትለብሱ\nክብሩን እንድታዩ\nበኢየሩሳሌም በመቅደሱ ቆዩ\n\nበማርያም ቤት በኢየሩሳሌም\nሲጠብቁ ኃይልን ከአርያም\nመንፈስ ቅዱስ ከሰማያት መጥቶ\nክብር ሆናቸው ዕውቀት ጥበብ ሰጥቶ\n\nመላእክቱ በሰረገላቸው\nአጥረዋታል በእሳት ሰይፋቸው\nቃል ኪዳኗን ደጆቿን አትርሱ\nበበጉ ደም እንድትቀደሱ\n\nፈሪዎቹ ደፋሮች ሆነዋል\nቋንቋ ጥበብ ፀጋን አግኝተዋል\nየፀኑባት የሞቱላት ሁሉ\nዛሬ በክብር በገነት ውስጥ አሉ\n\nበክርስቶስ ደም ላይ ተመሥርታ\nበልጆቿ ሰማዕትነት ፀንታ\nትኖራለች በክብር በዝና\nመሠረቷ የፀና ነውና\n', 'am', 409, 0),\n(1, 'ዘምር ዘምር አለኝ', 'ዘምር ዘምር አለኝ\nዘምር ዘምр አለኝ ልቤ ተነሳሳ\nየአምላኬን ቸርነት እንዴት ብዬ ልርሳ\nያደረገልኝን እንዴት ብዬ ልርሳ\n\nየሚቃጠለው ስብ በፊትህ ምንድነው\nሰማይና ምድር ሁሉ ገንዘብህ ነው\nያለኝን ሰብስቤ ባኖረው ከፊትህ\nዋጋ አይሆንም ጌታ ስለቸርነትህ\n\nይበዛም ይሰፋል የእግዚአብሔር ምስጋና\nአይቆምም በዘመን ማዕበል ነውና\nአንኳን ድንጋይ ቀርቶ ጋራው ቢናድብኝ\nየከንፈሬን ፍሬ ማንም አይወስድብኝ\n\nየጳውሎስ የሲላስ መከራ ቢፀና\nአልተውም ቅኔውን የአምላክን ምስጋና\nሊያስጥለኝ አይችልም እስር ስንሰለቴን\nአለብኝ ውለታ የሰማዩ አባቴን\n\nየተደረገለት ብዙ የተቀበለ\nየኖራል በፍቅሩ እየተቃጠለ\nክብሬን ሁሉ ትቼ ልዘምርልህ\nይህ ነው ችሎታዬ ለአንተ የምሰጥህ\n', 'am', 410, 0),\n(1, 'አሜን እላለሁ', 'አሜን እላለሁ\nአሜን እላለሁ ተመስገን\nቢበዛልኝ ቢጎለኝ\nብደስትም ባዝን\n\nእግዚአብሔር ያልከው ከቶ አይቀርምና\nእቀበለዋለሁ ሁሉን በምስጋና\nበሀዘን ሽለቆ ህይወትም እንዳለ\nይሄን ታላቅ ጥበብ ልቤ ተቀበለ\n\nሀሳብህን ከቶ ማን ይከለክላል\nይሁን ያልከው ሁሉ በጊዜው ይሆናል\nመሻቴ ቢሆንም ሁሌ እንዲመቸኝ\nችግርን ማለፍን አንተ አስተምረኝ\n\nያለኝን ስነጠቅ በፅኑ ሳዝን\nመመኪያዬ ሲወድቅ አየሁት ጌታን\nያጉረመረምኩበት ወራቴን ጠላሁ\nእጄን በአፌ ጭኜ አሜን እላለሁ\n', 'am', 411, 0),\n(1, 'ጠላት ተሸነፈ', 'ጠላት ተሸነፈ\nጠላት ተሸነፈ ኢየሱስ ነገሠ\nየኃያላን ኃያል ክብርን ተላበሰ\nእልል እልል እንበል ከበሮውን ምቱ\nለወደደን ጌታ ላዳነን በሞቱ\n\nእንደ መልከጼዴቅ ክህነቱ ዘለዓለም\nበጉን የፈለገ መጠቶ በዚች ዓለም\nእጅግ ትሁት ጌታ የታዘዘ ለሞት\nይህ ነው ንጉሣችን እኛ የምናምንበት\n\nአናጢዎች ጣሉት ይሄን ክቡር ድንጋይ\nመጋጠሚያ ሆነ ለምድር ለሰማይ\nመሠረት ሆኖልን በእርሱ ላይ ቆመናል\nማዕበል ወጀቡን መርቶ አሳልፎናል\n\nአበባው አሸተ አለፈ ክረምቱ\nአዲስ ቀን አመጣ ጌታችን በሞቱ\nደመ ማህተሙን ሰጥቶናል በፀጋው\nየገነትን መግቢያ ማነው የሚዘጋው\n\nከአብ የወረደ ፈትል ልብሳችን ነው\nማንም አይራቆት እርሱ ከሸፈነው\nምዑዘ ባህሪ ልባችንን ገዛ\nተሰቀለ ሞተ እኛን እንዲያበዛ\n', 'am', 412, 0),\n(1, 'በምድር ላይ ለኔ ማንም የለኝ', 'በምድር ላይ ለኔ ማንም የለኝ\nበምድር ላይ ለኔ ማንም የለኝ\nሀዘን ጭንቀቴን የሚካፈለኝ\nኪዳነምህረት እመቤት\nተስፋ ሁኚልኝ መድኃኒት\n\nቁስለኛ ብሆን ህመምተኛ\nዓለም ብትለኝ በሽተኛ\nመጣሁ ከደጅዋ ሸክሜን ይዤ\nደጓ እመቤቴን ተመርኩዤ\n\nቀን ለጣለው ሰው ትደርሻለሽ\nእንባን ከዓይኖቹ ታብሻለሽ\nበይ ስሚኝና ልመለስ\nለልቤ ጩኸት ስጭኝ መልስ\n\nወርቅ ሽቶዬ ነጭ ልብሴ\nእንዳያድነኝ አውቄአለሁ\nበስደት ሀገር መኖሪያዬ\nአንቺ ብቻ ነሽ መፅናኛዬ\n\nጊዜ ጥሎታል የሰውን ክብር\nበሥጋ መሃል ጠፍቶ ፍቅር\nጣዕምሽ የኖራል ተጠብቆ\nመች ታልፊዋለሽ ሰውን ወድቆ\n', 'am', 413, 0),\n(1, 'እግሬን ለመናወጥ', 'እግሬን ለመናወጥ\nእግሬን ለመናወጥ አልሰጠህምና\nከፍ በል አምላኬ ይድረስህ ምስጋና\n\nአይኖቼን ወደተራራ አነሳለሁ\nከፍ ያለው ታላቅ ዙፋኑን አየዋለሁ\nረዳቴ አንተነህ\nለዘለዓለም የምመካብህ\n\nጠባቂዬ እረኛዬ ነው የማይተኛ\nታላቅ ነው ፍጹም የሌለው ወደረኛ\nበቀንና በሌሊት\nሰላም እኖራለሁ በእርሱ ምህረት\n\nመግባቴን መውጣቱን ሁሉ ይጠብቃል\nየውስጤን የልቤን ምታት መርምሮ ያውቃል\nሰጥቶኛል ሳልለምን ቀድሞ\nአሳልፎኛል ባህር አቁሞ\n\nየህይወቴ የስትንፋሴ ባለቤት\nኑሮዬን ትርጉም የሰጠ በእውነት\nከሰማይ ከላይ ያየኛል\nደግነት ፍቅሩ ይጠብቀኛል\n', 'am', 415, 0),\n(1, 'አምኛለሁ ባንተ', 'አምኛለሁ ባንተ\nአምኛለሁ ባንተ አልነዋወጥም\nተስፋዬ ነህና ዛሬም ዘወትርም\n\nለደከመው ሰው በክንድህ ጉልበት ሰተህ\nብርታት የሆንከኝ አምላኬ አንተ እኮ ነህ\nፍጹም አትረሳም ዘወትር የእጅህን ሥራ\nበአደባባይህ ስለአንተ ዘወትር ላውራ\n\nመታመኛዬ እግዚአብሔር የቤቴ ፅናት\nቅጥሬ አንባዬ ማምለጫ ከጠላት ጥፋት\nስምህን ጠርቶ ያፈረ ከቶ ማን አለ\nአምላኬ ስልህ አረፍኩኝ ሸክሜ ቀለለ\n\nእጅግ ቢገዝፉ ተራሮች ከፊቴ ቆመው\nፍፁም ቢያስፈራ ቢያስጨንቅ ጥልቁ ጨለማው\nአንተን ይዣለሁ መንገዴ ብርሃን ይሆናል\nእንቅፋት ሁሉ ከፊቴ ይንከባለላል\n', 'am', 416, 0),\n(1, 'ስለ እናትህ ብለህ', 'ስለ እናትህ ብለህ\nስለእናትህ ብለህ ማረኝ እልሀለሁ\nእኔ እንደሥራዬ እንዴት እሆናለሁ\n\nከሳሼ ይበዛል በሥጋ ድካሜ\nማንአለኝ ያለአንተ የሚያቀለው ሽክሜ\nከቶ እንደማይሰማ ዝም ትለኛለህ\nበትርህ አይደለም ይገዛኛል ፍቅርህ\n\nበድዬ የሚያየኝ ሰው ይፈርድብኛል\nድንጋዩን አንስቶ ይጋበዝብኛል\nበጠለቀ ትዕግስት ድህነቴን የምትወድ\nማረኝ እልሃለሁ ተከትዬህ ልሂድ\n\nልታድነኝ ወደህ ምህረትህ ሲበዛ\nበዕፀ በስቀሉ ላይ ድግስ እንደበዛ\nራስህን ለሞት አሳልፈህ ሰጠህ\nእንዳልጠፋ ልጅህ አልኩኝ ስለእናትህ\n', 'am', 417, 0),\n(1, 'ሁሉ ተሳክቶልን', 'ሁሉ ተሳክቶልን\nሁሉ ተሳክቶልን ጌታ ሆይ አይተናል\nጠፍተዋል ተብለን በአንተ ኃይል በዝተናል\nየምህረት ጌታ ነህ ከቶ አትለወጥም\nድንቅን የምትሠራ አምላክ መድኃኔዓለም\nድንቅን የምታደርግ አምላክ መድኃኔዓለም\n\nየሞት አዋጅ ሽሮ416 የሚታደግ ነፍሴን\nጉልበቴን አፅንቶ የሚያሳርፍ ልቤን\nኃይል ይወጣል ከርሱ የሚያቀል ሽክሜን\nልጁ እሆናለሁ ለውጦት ታሪኬን\n\nየእግዜአብሔርን ሥራ ማዳኑን መስክሩ\nአልዓዛር ይነሳል ይፈታል ከፈኑ\nበደረቁ አጥንቶች ሕይወት የሚዘራ\nማን ነው የሚመስለው በማዳኑ ሥራ\n\nወንጭፍ ጠጠሩንም ጣልነው በስምህ\nምርኮውም በዛልን አገዘን ክንድህ\nጉልበቱን ተማምኖ ቢፎክርም ጠላት\nከእግራችን ሥር ጣልከው የዘለዓለም አባት\n\nመገፋቴን አይቶ አቅሜ የደከመ\nኃይሉን አሳያቸው እኔን እያከመ\nባህርን እንደግንብ ማቆም የሚቻለው\nኤለሻዳይ የሆነው ጌታ እርሱ ብቻ ነው\n', 'am', 418, 0),\n(1, 'አምላከ እስራኤል', 'አምላከ እስራኤል\nአምላከ እስራኤል ክበርልኝ\nበዘለዓለም ፍቅር የወደድከኝ\nክንድህ ዘወትር ያበረታኛል\nእንዳንተ ያለ ከየት ይገኛል\n\nክብርህን ሳየው እጅግ እጠግባለሁ\nበረከት ሆነህ ጓዳዬን ሞላኸው\nየአምላኬ ሥራ ሁሌም ይደንቀኛል\nእንዳንተ ያለ ከወዴት ይገኛል\n\nውለታህ ብዙ ተነግሮ አያልቅም\nኃጢአተኛ ነው ብለህ ሰው አትንቅም\nጠላት ሊወግረኝ ድንጋይን ቢያነሳ\nአንተ ሆንክልኝ ከባቴ አበሳ\n\nበደልን ከድኖ ሞገስን የሚሰጥ\nከተኩላ መሐል ልጆቹን የሚመርጥ\nማን እንደጌታ ርህሩህ አለና\nእስኪ ለስሙ ላቅርብ ምስጋና\n\nምህረትህ በዝቷል ለእኔ ያደረከው\nየኃጢአቴን ቅርፊት ከእኔ አስወገድከው\nላመስግን አንተን ባለውለታዬን\nአትረፍርፎታል በረከት ጓዳዬን\n', 'am', 419, 0),\n(1, 'ሰላምህ በዛልኝ', 'ሰላምህ በዛልኝ\nሰላምህ በዛልኝ እንደ ወንዝ ፈሰሰ\nበረሃው ህይወቴ በፍቅርህ ራሰ\nሞቴን ክብሬ አድርጌ የኖርኩበት ህይወት\n\nበአንተ ተቆረጠ ስትጠራኝ በምህረት\nአይኖቼ ተከፍተው ሥራህን ስላዩ\nከጥፋቱ ስፍራ በፀጋህ ተለዩ\n\nመከታ ድጋፌ አንተ በመሆንህ\nተመስገን አለሁኝ ሳልጠፋ ከቤትህ\nበቃ ተዘግተዋል የሞት ደጆች ለኔ\nዘወትር ስላለህ ቤዛዬ ከጎኔ\n\nሰላሳና ስልሳ መቶ እንዳፈራ\nእኔም ተመረጥኩኝ ከልጆችህ ጋራ\nለምን ዝም እላለሁ ማዳንህን ላውራ\nበደሌ ተረስቶ ለዚህ ክብር ስጠራ\n\nደግሞም አለኝ ገና ሌላ ታላቅ ክብር\nበሰማያዊው ቤት ለዘለዓለም መኖር\nከቅዱሳኑ ጋር በዚያ እንድደመር\nየደሙ ዋጋ ነኝ አልፈራም ስናገር\n', 'am', 421, 0),\n(1, 'ኦርቶዶክስ ተዋህዶ', 'ኦርቶዶክስ ተዋህዶ\nኦርቶዶክስ ተዋህዶ ሃይማኖቴ\nብኩርናዬ ናት በረከቴ\nርስቴም ናት እንደ ናቡቴ\n\nነብዩ ኤርምያስ የመሰከረላት\nመልካሚቱ መንገድ ጻድቃን የሄዱባት\nኦርቶዶክስ ተዋህዶ ርትዕት ሃይማኖት\n\nየያዕቆብ ብኩርና ኤሳው ያቃለላት\nየናቡቴ ርስት ንጉሥ የተመኛት\nለአክሊል ያበቃችው የጳውሎስ እምነት\n\nየሐዋርያት ስብከት የወንጌል ምስጢር\nየሊቃውንት ትምህርት የያሬድ መዝሙር\nየቅዱሳን ገድል ፍኖተ እግዚአብሔር\n\nምስጢርን የምትገልጽ ፀጋን የምታለብስ\nከእሳት የምታድን ተራራ የምታፈልስ\nሙት የምታስነሳ ድውይ የምትፈውስ\n\nየእግዚአብሔር ስጦታ ጌጤ ሽልማቴ\nየገነት መግቢያዬ መክበሪያዬ ሃብቴ\nኦርቶዶክስ ተዋሕዶ አንዲት ሃይማኖቴ\n', 'am', 422, 0),\n(1, 'በስመ ክርስቲያን', 'በስመ ክርስቲያን\nመስቀል አልተሸከምሁ ቃልህን አክብሬ\nአሕዛብ አልተባልሁ ወይም እንደ ግብሬ\nበስመ ክርስቲያን አለሁ እስከዛሬ\n\nከስም በላይ ስምን ብታሸክመኝም\nበክርስቶስ ስምህ ክርስቲያን ብሰኝም\nመች ተስተካከለ ግብሬ እንደስሜ\nአላስደሰትኩህም ሕግህን ፈጽሜ\n\nበሕግህ መኖርን ነፍሴ ስትወድ\nወጥመድ ሆኖባታል የሥጋ ፈቃድ\nእራሴን እንድክድ መስቀል እንድሸከም\nልቤን አበርታልኝ ርዳኝ መድኃኔዓለም\n\nየጨለማን ሥራ ከእኔ አርቅልኝ\nሕግህ ለመንገዴ ብርሃን ትሁነኝ\nየሕይወትን መንገድ ምራኝ በወንጌልህ\nክርስቲያን አድርገኝ ባርከኝ በመስቀልህ\n\nስም አያድነኝም መልካም ካልሠራሁ\nክርስቲያን ተብዬ ክርስቲያን ካልሆንኩ\nለበጐ እንድተጋ መፈፀም እንድችል\nአምላኬ ክፈለኝ ከቅዱሳን ዕድል\n', 'am', 423, 0),\n(1, 'ምድርን በኃይሉ', 'ምድርን በኃይሉ\nምድርን በኃይሉ ለፈጠረ\nበላይ ጠፈሩን ለዘረጋ\nሃሌ ሃሌ ሉያ ለእግዚአብሔር\nለአለና ለሚኖር ለአልፋና ዖሜጋ\n\nሰማያትን በማስተዋሉ ዘረጋቸውና\nከዋክብትን በላይ በጥበብ አፀናቸው\nፍጥረታቱ ለንጉሣችን እልል በሉ\nአዋቂ ነው ሁሌ የሚገኝ እንደቃሉ\n\nደመናትን ጠቅሶ ይጠራል በጊዜያቱ\nዝናቡንም ያንጠባጥባል ለምድሪቱ\nነፋሳትን ከመዝገቦቹ እያወጣ\nይገፋዋል ውሃው ምድሪቱን እንዲያጠጣ\n\nድምጹን ሰምቶ ምድርና ሰማይ ይታወካል\nጉልበት ሁሉ ለስሙክብር ተንበርክኳል\nበደመናት በላይ በሰማይ ይራመዳል\nበኪሩቤል በአርያም ጠፈር ይገለፃል\n\nልጆቹ ነን አባታችን ነው እናምናለን\nበመቅደሱ ክብሩን እያየን እንጠግባለን\nአንቀርም በምድር ተዘርተን ሠራዊቱ\nይጠራናል በደብረ ፅዮን በመንግሥቱ\n', 'am', 424, 0),\n(1, 'በዘለዓለም ፍቅሩ', 'በዘለዓለም ፍቅሩ\nበዘለዓለም ፍቅሩ እንዲሁ ወዶናል\nበቅዱስ ፈቃዱ ተቀብሎናል\n\nኃጢአታችንንም አስወገደ\nደካማውን ጉልበት አራመደ\nኃይልን አለበሰን ከሰማይ\nጌታችን ድንቅ ነው ኤልሻዳይ\n\nምህረትን አገኘ ደሀ አደጉ\nወደ ላይም ወጣ ከማዕረጉ\nእንደ ለምለም ዝግባ አድምቆናል\nተክሎናል በቤቱ አጽድቆናል\n\nኣበሳችንንም አስወገደ\nደካማውን ጉልበት አራመደ\nኃይልን አለበስን ከሰማይ\nጌታችን ድንቅ ነው ኤልሻዳይ\n\nሰው ወዳጅ ነህ አንተ ሰው ወዳጅ\nፍቅርህ አይለወጥ አያረጅ\nቃል ገባን እንግዲህ ለዘለዓለም\nከአንተ የሚለየን ማንም የለም\n', 'am', 425, 0),\n(1, 'አንተ ስለሆንክ ነው', 'አንተ ስለሆንክ ነው\nአንተ ስለሆንክ ነው ጌታ ስለሆንክ ነው\nእንደእኔ ድካምማ የማይፈርድብኝ ማነው\n\nእንኳን ቆሽሼ አይቶ ከበረዶም ብነጣ\nአውቃለሁ ፈጣሪዬ ሰው የሚለውን አያጣ\nከነብዙ ችግሬ በቤትህ የምኖረው\nአውቃለሁ ፈጣሪዬ አንተ ስለሆንክ ነው\n\nዓለም በሞቴ ፈርዶ መቃብሬ ሲቆፈር\nእተርፋለሁ አላልኩም ተስፋ ቆርጬ ነበር\nከከሳሾቼ ቀድመህ አንተ ወተሃልና\nክሴን ከንቱ አደረከው አቆምከኝ እንደገና\n\nየሞት ድንጋይ ተጭኖኝ ጨለማ ውጦኝ ሳለ\nከጥልቁ ድምፁን ሰማሁ ሲያለቅስ የታል እያለ\nይሸታል ቢሉት እንኳን እጅግ ወዶኛልና\nአልዓዛር ብሎ ጠራኝ ሞቴን አይሻምና\n\nየቀራጮች አለቃ ኃጢአተኛ ተብዬ\nእኖር ነበረ ቀድሞ ከሰዎች ተገልዬ\nዛሬ ግን ተጐበኘሁ በምህረት በይቅርታ\nከእኔ ጋር እራት በላ የማይዘነጋኝ ጌታ\n\nአልጠረጠርኩም ይሄን አላሰብኩትም ከቶ\nቀረሁ ብዬ ነበር ታሪኬ ተበላሽቶ\nበሚያስደንቅ ይቅርታ ከአልጋ ተነስቼ\nይኼው እዘምራለሁ በጸጋ ተሞልቼ\n', 'am', 426, 0),\n(1, 'ሥራህን ላውራ', 'ሥራህን ላውራ\nበምን ቋንቋ በምን አንደበት\nሥራህን ላውራ የአንተን ቸርነት\nእጹብ ድንቅ ነው ፍቅርህ ጌታዬ\nታትሞ ቀርቷል በልቦናዬ\n\nአስተምረህ ሰው አርገኸኛል\nበሀዘኔም ጊዜ አጽናንተኸኛል\nስደነቃቀፍ ቀድመህ ያገዝከኝ\nየአብርሃም አምላክ ተመስገንልኝ\n\nብዙ ነገር ብዙ አይቻለሁ\nእንዳላወራው ዕድሉ ያንተ ነው\nቀን ሲከፋ ሲጨክን ሁሉም\nለካስ አምላኬ አንተ አትጥልም\n\nመልካም አባት ቸር እረኛ ነህ\nሌሊትና ቀን እንቅልፍ የሌለህ\nከአንበሣው አፍ ከጥልቁ አውጥተህ\nይኸው አቆምከኝ ምስጋን ሞልተህ\n', 'am', 427, 0),\n(1, 'ከፍቅርህ እርቄ', 'ከፍቅርህ እርቄ\nከፍቅርህ እርቄ መኖር መች ጠቅሞኛል\nከደጅህ ተጥዬ ብኖር ይሻለኛል\nአንተነህ አምላክ ትምክህቴ\nአንተነህ ጌታ ተስፋዬና ቤዛ ለህይወቴ\n\nእንደ ሉቃስ ሆኜ እንደቀለዮጳ\nበእምነት መሠረት ውስጤን ሳልገነባ\nበኢማሁስ መንገድ ተገልጠህልኛል\nየሠማዩን እውነት አገናኝተኸኛል\n\nአጥንቶቼ ይበርቱ ጨምረው ትጋቴን\nወደ ኢየሩሣሌም መልስልኝ እግሬን\nሰቃዮች ቢኖሩም ከጽድቁ ከተማህ\nዛሬም ትሠራለህ አልቆመም ማዳንህ\n\nበማደሪያህ ዘወትር ብኖር እመርጣለሁ\nአምላኬ ከፍቅርህ የሚለየኝ ማነው\nቤዛዬ አንተ ነህ ምንጊዜም ረዳቴ\nየማትረሣኝ ጌታ አዛኝ መድኃኒቴ\n\nእጅግ ብዙ ነገር ስላለ ያልገባኝ\nበህይወት ዘመኔ የምታስተምረኝ\nበቤትህ አኑረኝ ፀንቼ በዓላማ\nምክር ተግሣጽህን ጆሮዬ እየሰማ\n', 'am', 428, 0),\n(1, 'አላፍርበትም', 'አላፍርበትም\nአላፍርበትም ያመንኩትን አውቀዋለሁ\nሁሌ ለስሙ እዘምራለሁ\n\nከቶ ቢነዛ የዓለም ወሬ የሀሰት ወሬ\nአትተወኝም መድህኔ ክብሬ\nዓለም የራሱን ምንም ቢወድ\nአላፍርበትም የአንተን መንገድ\n\nየጠላት ጩኸት ምን ቢበረታ\nቸል የማይለኝ አለ የኔ ጌታ\nሔሮድስ ዘወትር እጁን ቢጭን\nኃይሉ ውድቅ ነው በአምላካችን\n\nየእሳት ነበልባል ቢታይ ከፊቴ\nየአንበሳ ጉድጓድ ቢሆንም ቤቴ\nየሚጠብቀኝ አያንቀላፋ\nይለውጠዋል ነገን በተስፋ\n\nታናሽ ነው ብሎ ጠላት ቢንቅ\nከፍ ከፍ ያለው በእኔ ቢስቅ\nሁሉን የሚችል ጌታ ሲነሳ\nያስወግደዋል የእኔን አበሳ\n', 'am', 429, 0),\n(1, 'ክብርህን አይቼ', 'ክብርህን አይቼ\nክብርህን አይቼ እጠግባለሁ\nሥራህን አይቼ አደንቃለሁ\nአምላኬ ለእኔ ያለህ ብዙ ነው\nጌታዬ ለእኔ ያለህ ብዙ ነው\n\nሸለቆውን ትቼ ተራራ ስወጣ\nክብርህ ከዙፋንህ አበራልኝ ጌታ\nዝናህን ሰምቼ እኔስ ፈራሁኝ\nክርክሬ አበቃ አንተን አወኩኝ\n\nከዘመናት በፊት ያሰብክልኝ ሆነ\nበበጎ ፈቃድህ ሁሉም ተከወነ\nዛሬ ሙሉ ሰው ነኝ በአንተ ተደግፌ\nበብዙ በረከት ተሞልቷል መዳፌ\n\nክብርህን ያላየ ክብር የሌለው ሰው ነው\nአንተን ያላወቀ ያላተረፈ ነው\nርሃብተኛ ነው ከአንተ ጋር ያልሄደ\nብዙ ሀብት እያለው ከታች የወረደ\n\nከሰማያት በላይ መኖሪያ ሠርተሃል\nመጥተህ ልትወስደኝ ጌታ ቃል ገብተሃል\nእኔም ናፍቄያለው አምላኬ ክንድህን\nከእናት እቅፍ በላይ የሚመቸኝን\n', 'am', 430, 0),\n(1, 'አባት ሆነኝ', 'አባት ሆነኝ\nአምላክ ለእኔ አባት ሆነኝ\nልጄ ብሎ አከበረኝ\nከበለስ በታች እርሱ ያውቀኛል\nፍቅሩን በሞት ገለጾልኛል\n\nበኃጢአት ሳለሁ አልናቀኝም\nቅጠል ለብሼ አለተወኝም\nዘመንን ቆጥሮ ወደእኔ መጣ\nከኃጢአት ባህር ልጁን ሊያወጣ\n\nየማይረሳ ፍቅር አቅምሶኛል\nአንገቱን ደፍቶ ቀና አድርጐኛል\nከእንግዲህ በቃ ርስት አገኘሁ\nባርነት ቀርቶ ልጁ ሆኛለሁ\n\nበእቅፎቹ ውስጥ አሳድጐኛል\nእንጀራን ከእጁ መግቦኛል\nየአባቴን አምላክ አውቀዋለሁ\nዘለዓለም ስሙን እባርካለሁ\n\nያደረገልኝ አይነገርም\nበመሰክርም እውነት አይመስልም\nከአእምሮ በላይ ሆኖብኛል\nምስጋና ለእርሱ ያንስብኛል\n\nብዙ ታያለህ ብሎኛልና\nከዚህ የሚበልጥ አያለሁ\nእጠብቃለሁ አምላኬን\nአላቋርጥም ምስጋናዬን\n', 'am', 431, 0),\n(1, 'ምህረት ስጠኝ', 'ምህረት ስጠኝ\nአምላኬ ሆይ ምህረት ስጠኝ\nጌታዬ ሆይ ይቅር በለኝ\nይቻልሃል ልትምረኝ\nምስኪን ልጅህ ነኝ አትተወኝ\n\nባለመታዘዜ ድምፅህ አስፈራኝ\nየኃጢአቴ ደመወዝ ሞት ነው የሆነብኝ\nየድህነት ቃልህን ተስፋህን ስጠኝ\nከጨለማ ልውጣ እጅህን ዘርጋልኝ\n\nሀዘኔ ከበደ ለቅሶዬም በዝቷል\nጊዜዬ የሚያልፈው በትካዜ ሆኗል\nእባክህ ጌታዬ ደስ ይበለኝ ልጅህ\nአንተ እንዳዳንከኝ ልመስክርልህ\n\nእኔን ይቅር ማለት ልማድህ ነውና\nእንባዬን አብስው ወደ እኔ እይና\nበፀፀት ከፊትህ ወድቄአለሁና\nደግፈህ አንሳኝ ዳግም እንደገና\n', 'am', 432, 0),\n(1, 'በተከበበ ከተማ', 'በተከበበ ከተማ\nበተከበበ ከተማ ድንቅ የሚያደርግ\nምህረትን ሠርቶ እኔን የሚታደግ\nስሙ ለኔ ጋሻ ሆኖልኛል\nከድብቅ ጦር ነፍሴን ታድጓታል\n\nበዘመኔ ድንቅህን አየሁት\nቸር ጌታ ነህ እጅግ ከጠበኩት\nየቱ ግብሬ ማረከህ ጌታዬ\nልጄ ያልከኝ ሆነህ እረኛዬ\n\nበማለዳ ህይወቴን ባርከሀል\nስትምረኝ ጠላቴ አይቶሀል\nለወገኔ መደነቂያ ሆንኩኝ\nበአንተ ሥራ ከሰው ተቆጠርኩኝ\n\nዓለም ባይረዳህ አምላኬ ነህ ለኔ\nበደም የዋጀኸኝ ጌታ መድህኔ\nሞኝነት ይመስላል ላንተ መንበርከክ\nፍቅርህ ለብቻ ነው ሰውን ሲማርክ\n', 'am', 433, 0),\n(1, 'መድኃኒቴ', 'መድኃኒቴ\nመድኃኒቴ ክብሬ አምላኬ\nእሰግድለታለሁ ፊቱ ተንበርክኬ\nያንስበታል ይህ ለውለታው\nምህረቱን ተናግሬ መቼም አልጨርሰው\n\nየፍቅሩ ሚዛን ኃጢአቴን ደፋው\nበብዙ ማረኝ ግሩም ነው ሥራው\nሰዎች በእኔ ላይ ቢነሱ በሐሰት\nመልስ የሆነኝ ያዳነኝ ከሞት\n\nበመከራዬ ፈጥኖ የሰማኝ\nማዳኑን ልኮ እኔን ያፅናናኝ\nእንባዬን በእጁ ያበሰ እርሱ ነው\nእናመስግነው ሥራው ድንቅ ነው\n\nከጥፋት ውሃ ከአስፈሪው ማዕበል\nከሁሉ ይበልጣል ጌታ ሆይ ያንተ ሀይል\nቃልህን ብቻ ልከህ ትሠራለህ\nጌታ እግዚአብሔር ግሩም ነው ማዳንህ\n', 'am', 434, 0),\n(1, 'አዲስ ሰው ሆንኩኝ', 'አዲስ ሰው ሆንኩኝ\nአዲስ ሰው ሆንኩኝ አዲስ ፍጥረት\nዳግም ላይገዛኝ ሰይጣን ወይ ሞት\nበኃያል ፍቅሩ ልጁ አድርጐኛል\nእንደሚወደኝ መስክሮልኛል\n\nከማይጠፋ ዘር ተወልጃለሁ\nድንቅ የሆነ ሀብት ከእርሱ አግኝቼአለሁ\nዘለአለማዊ ህይወትን ስጠኝ\nይመስገን ጌታ ከፍ ያደረገኝ\n\nአልቅሼ ሳልቀር እንባዬ ፈሶ\nፍቅሩን አሳየኝ ስጋውን ቆርሶ\nእስከዚህ ድረስ ለካስ ወዶኛል\nህይወት ሊሰጠኝ ተሰቅሎለኛል\n\nአምላክ ሰው ሆነ እኛን ለማዳን\nሞትን በመሻር ህይወትን ሊሰጠን\nአምላክ የሆነው ሰውም ሆነና\nየገነትን ቦታ ሰጠን እንደገና\n', 'am', 435, 0),\n(1, 'ከዓለም በፊት የነበረ', 'ከዓለም በፊት የነበረ\nከዓለም በፊት የነበረው\nበመንግሥቱ አሁንም ያለው\nለዘለዓለም የሚኖረው\nህያው አምላክ እግዚአብሔር ነው\n\nሰማይና ምድርን ብርሃንን ጨለማን\nጨረቃና ፀሐይ ደግሞም ከዋክብትን\nውቅያኖስ ባህሩን በቃሉ ያፀናው\nየፍጡራን ጌታ እርሱ ኤልሻዳይ ነው\n\nፍጥረትን ሁሉ በየግብሩ ፈጥሮ\nሰውን እንደመልኩ በደንብ አሳምሮ\nየፈጠረው እርሱ ድንቅ አምላክ ነውና\nለዚህ ግሩም ጌታ እናቅርብ ምስጋና\n\nበመላዕክት ከብሮ የሚመሰገነው\nአሸናፊ እግዚአብሔር ቅዱስ የሚባለው\nቅድመ ዓለም እርሱ ቀዳሚ የሌለው\nየፍጥረትን ገዢ ኑ እናመስግነው\n\nየፈጠረው አዳም ትዕዛዝን ቢያፈርስም\nሃይማኖትን ጥሶ በለስን ቢበላም\nወደ ቀድሞ ክብሩ ገነት የመለሰው\nየድንግል ማርያም ልጅ እርሱ ክርስቶስ ነው\n', 'am', 436, 0),\n(1, 'እኔስ በእግዚአብሔር ደስ ይለኛል', 'እኔስ በእግዚአብሔር ደስ ይለኛል\nእኔስ በእግዚአብሔር ደስ ይለኛል\nሀዘኔን ያስረሳኛል ጭንቀቴን ያስረሳኛል\n\nቸር እረኛዬ ያፅናናኛል\nበጊዜው ሀዘን መጐስቆልን\nየዚህ ዓለም ሰው አይቶት ፊቴን\nዛሬ ቢሸሸኝ ቢከዳኝም\nጌታ አምላኬ ግን አልተወከኝም\n\nፈተና በዝቶ ቢከበኝም\nተራራ መስሎ ቢታየኝም\nመከራ ችግር አስወግደህ\nትረዳኛለህና ሁሉን ጋርደህ\n\nአንተን ጠርቼ ምን አጣሁኝ\nሀሳቤ ሁሉ ሞልቶ አየሁኝ\nያለኝ ይኼ ነው መድኃኒዓለም\nክበር ተመስገን ለዘለዓለም\n', 'am', 437, 0),\n(1, 'የምታመንበት እኔ ሰው የለኝም', 'የምታመንበት እኔ ሰው የለኝም\nየምታመንበት እኔ ሰው የለኝም\nጌታ ከአንተ ሌላ ረዳት የለኝም\nአንተ ግን አምላኬ መታመኛዬ ነህ\nአለም ዘለዓለም ትጠብቀኛለህ\n\nየዚህ ዓለም ሰው ግን በዘመድ ይመካል\nሁሉም አላፊ ነው ይህን ዘንግቷል\nከአንተ ሌላ ለኔ ታማኝ አምላክ የለም\nለፈጠርከው አዛኝ ጌታ እንዳንተ የለም\n\nወድቄ መንገድ ላይ ቆስዬ እየታየሁ\nሳምራዊውን ሆኖ የሚያነሳኝ አጣሁ\nከደጁ ተኝቼ ተርቤ እያየኝ\nነዌ ባለፀጋው ፍርፊሪ ነሳኝ\n\nበአልጋ ቁራኛ ዘመናት ገፍቼ\nተነሳሁ በአምላኬ ሥርየትን አግኝቼ\nሕግህ በርሃን ነው ውስጤን ያሳየኛል\nበቤትህ እንድኖር መንገድ ይመራኛል\n\nለደሀ አደግ አባት ለተገፉ ዳኛ\nእግዜአብሔር ብቻ ነህ ፈራጅ እውነተኛ\n', 'am', 438, 0),\n(1, 'ያስጨነቀኝን አስጨነቀልኝ', 'ያስጨነቀኝን አስጨነቀልኝ\nያስጨነቀኝን አስጨነቀልኝ\nያሳዘነኘን አሳዘነልኝ\nበጠላቴ ራስ ላይ አቁመኸኛል\nተመስገን ጌታ ሆይ ክብር ይገባሀል\n\nበሀሰት ተነስቶ ሳኦል ቢያሳድደኝ\nከእኔ ጋር ተሰደህ ከእጁ አዳንከኝ\nየጠላቴን ጀርባ አሳይተኸኛል\nከሰቀቀን ኑሮ ማዳንህ ፈትቶኛል\n\nእራሴን ለማዳን ጥበብ ባይኖረኝም\nእኔኑ ሊረዳ ፍቅርህ አልራቀኝም\nየክፋቱን መንፈስ አዝሎ ለመጣብኝ\nሁሉን የሚችለው ክንድህ መለሰልኝ\n\nሊጥለኝ ያሰበም አልሠራም ዕቅዱ\nከቶ አልሰጠኸኝም በሀሰት ለሄዱ\nሀሰት ንግሥት ሆና ብትሸፈን አውነት\nእንዳለነበር ሆኗል አንተ የፈቀድክ ዕለት\n\nጠላቴም ሳይጥለኝ እንዳዘነ ሄዷል ተውህ ብ\nፍቅርህም በቤቴ ከኔ ጋር አድሯል አበባ በሚ\nየዛተብኝ ሁሉ ሳይሰምርለት ቀርቶ\nአልጐደለብኝም ወጥቻለሁ ከቶ\n', 'am', 439, 0),\n(1, 'ሰው ሁሉ አገለለኝ', 'ሰው ሁሉ አገለለኝ\nበደዌ ተይዞ ሆዴ እየባባ\nሰው ሁሉ አገለለኝ ሆንኩኝ ወንድም አልባ\nወገን አታግሉኝ ቅረቡ ወደኔ\nፍርሃቴ ይራቅ ይቀረፍ ከጐኔ\n\nወገን አታግሉኝ አታድርጉኝ ብቸኛ\nሕዝቤ ሁሉ ሽሽኝ አድርጐኝ ኃጢአተኛ\nካለ እናት አባት ሜዳ ቀርቼ\nየሚያስታምምኝ ወገኔን አጥቼ\n\nከስቼ ጠቁሬ ሰው ሁሉ ቢያየኝ\nእንደሌሊት አውሬ ወንድሜ ሸሸኝ\nመረበሽ መራዴ ይጥፋልኝ ከልቤ\nተገለልኩኝ ከቤቴ ጸልዬ ለአምላኬ\n\nህመምተኛ ሆንኩኝ ኑልኝ ወገኖቼ\nመናገር አልችልም ኃጢአቴን አብዝቼ\nበአስከፊው በሽታ አንደበት አጥቼ\nእንዲህ የምሆነው ኧረ እስከመቼ\n\nሚዛንህ ዛሬ ነው እንዲለኝ ፈጣሪ\nወላዲተ አምላክ ድንግል ለእኔ ራሪ\nየምህረት እጅህን ዘርጋልኝ ጌታዬ\nበሰማዩ ቤትህ እንዲሆን ኑሮዬ\n', 'am', 440, 0),\n(1, 'ሊነጋ ሲል ይጨልማል', 'ሊነጋ ሲል ይጨልማል\nሊነጋ ሲል ይጨልማል\nጨልሞ አይቀር ዳግም ይነጋል\nተስፋ አትቁረጥ አምላክ ያውቃል\n\nለማሸነፍ ኑሮን በዓለም\nስትሯሯጥ ስትደክም\nሁሉ አይሞላም ጐዶሎ ነው\nየዓለም ጣጣ ብዙ ነው\n\nመገፋትን መወርወርን\nመጠላትን ክፉም ስምን\nደርሶበታል ሁሉን ያውቃል\nሁሉን የሚያውቅ ጌታ ያዝንልሀል\n\nአይዞህ ኑሮ እስኪያልፍ ያለፋል\nየስቃይ ቀን ሌሊቱ ይረዝማል\nድሮ ብለህ ታወራለህ\nቀን ያልፍና ትፅናናለህ\n\nፍፁም ሀዘን ለደስታህ\nማጣትህም ለማግኘትህ\nዋዜማ ነውለስቃይህ\nአምላክህ ቀርቧል ሊጎበኝህ\n', 'am', 442, 0),\n(1, 'እግዚአብሔር ከብሯል', 'እግዚአብሔር ከብሯል\nከብሯል እግዚአብሔር ከብሯል\nስሙ በክብር ገኗል\nውዳሴ መዝሙር ለእርሱ ይገባል\n\nበአምሳልህ ፈጥረህ ፍጹም ወደኸናል\nየመለኮት ባህሪይ ተካፋይ ሆነናል\nየልባችን ዙፋን ፈቅዶ ተዘርግቷል\nንገሥበት አምላክ ስምህ በእኛ ከብሯል\n\nየጅረት የወንዙ የፏፏቴው ግርማ\nየፀሐይዋ ቀመር ቀንና ጨለማ\nበሁሉ ላይ አንተ ሰልጥነሃልና\nእንሰዋልሃለን ውዳሴ ምስጋና\n\nሲኦልና ገነት ምድርና ሰማይ\nበእጅህ መካከል በመዳፍህ ላይ\nለፍትሀዊነትህ ያዘጋጀሃቸው\nበእነዚህ ውስጥ ያሉት ሁሉም ከአንተ ናቸው\n\nሁሉን አድርገሃል በገዛ ፈቃድህ\nፍጥረትን ስትፈጥር ማንም አልመከረህ\nእጣ ፈንታቸውም በአንተ ይወሰናል\nየእጅህ ሥራ ናቸው ማንስ ምን ይልሀል\n', 'am', 443, 0),\n(1, 'ሃሌ ሉያ (ለምስጋና)', 'ሃሌ ሉያ (ለምስጋና)\nሃሌ ሉያ ቅዱሳኑ አመስግኑት\nበዝማሬም በገናውን ደርድሩለት\nለእኛ ተሰውቶ ለርስቱ መርጦናል\nበልጅነት ፀጋም ወራሾች ሆነናል\n\nከሰማያት ወርዶ እኛኑ ፍለጋ\nፍዳችንን ፍቆ ጎበኘን በፀጋ\nበረቀቀ ጥበብ ሁሉን አደላድሎ\nበፍቅሩ አከበረን ለእኛ ሲል ተሰቅሎ\n\nገነት ተዘግታብን ሲኦል አልቀረንም\nጠላት እንደዛተ ተገዝተን አልኖርንም\nእውነተኛው ፈራጅ መድኃኒት መጣና\nከጨለማ ጉድጓድ አወጣን በጤና\n\nተርበን እንዳንቀር ሥጋውን ሰጥቶናል\nበዘለዓለም መጠጥ በደሙ አርክቶናል\nመልካችን በኃጢአት ቢጨልም ፊታችን\nሥጋህና ደምህ ፅድቅን አበራልን\n\nምድር ሰውነትም ተረግማ አልቀረችም\nነቃቅለህ ጣልክላት አሽክላውን አረም\nሀዘናችን ጠፍቶ ደስታችንም በዛ\nእነዘምር በእልልታ ለአለሙ ቤዛ\n', 'am', 444, 0),\n(1, 'አምላኬ ለአንተ', 'አምላኬ ለአንተ\nአምላኬ ለአንተ ንጉሤ ለአንተ\nመመኪያዬ አለኝታዬ ለአንተ\nእሰግዳለሁ በልቤ ጉልበት\nእዘምራለሁ በሰጠኸኝ አንደበት\n\nህይወቴን ላበርክት አምላክ ለአንተ ፍቅር\nአፌንም ከፍቼ ለስምህ ልዘምር\nየሌሊቱ ግርማ ፅልመት ሳያስፈራኝ\nፍቅርህ አገብሮኝ መቅደስህ አቆመኝ\n\nበማዳንህ ጥበብ ህይወቴን ከልዬ\nበተስፋ እኖራለሁ ነፍሴን በእጅህ ጥዬ\nአፈሳለሁ እንባ ከቤትህ ገብቼ\nስቀኝልህ ለአንተ እጆቼን ዘርግቼ\n\nእንባዬን አብሰው በማዳንህ ሥራ\nእንግዲህ ከደጅህ አታጥፋኝ አደራ\nጌትነት ምስጋና ነውና ገንዘብህ\nአንተ ቅዱስ ጌታ ነፍሴ ታመስግንህ\n\nከግብፅ ባርነት ከሲኦል መከራ\nበበትረ መስቀልህ ወጣሁ በአንተ ሥራ\nንሴብሆ ብዬ ላንሳ ከበሮውን\nእንደ ሙሴ እህት ላቅርብ ምስጋናህን\n', 'am', 445, 0),\n(1, 'እግዚአብሔር ዕድል ፈንታዬ ነው', 'እግዚአብሔር ዕድል ፈንታዬ ነው\nእግዚአብሔር ዕድል ፈንታዬ ነው ወደር የሌለው\nእግዚአብሔር ዕድል ፈንታዬ ነው ወደር የሌለው\n\nሰዎች ሲሸሹኝ ታምሜ\nለሞት ስቃረብ ደክሜ\nአምላኬ ብቻ ወደደኝ\nአቅፎ አስታሞ ፈወሰኝ\n\nምንጭ ነው መጀመሪያዬ\nመነሻ መድረሻዬ\nየፈጠረኝ አይረሳኝም\nእኔን ለክፉ አይሰጠኝም\n\nየእናት አባት ውርስ ይጠፋል\nምድራዊ ድንኳን ይፈርሳል\nእርሱ የሰጠኝ ይበልጣል\nከእኔ ጋር ፀንቶ ይኖራል\n\nኃጢአቴን ትቶት በደሌን\nበደሙ አጥቦልኝ አካሌን\nአባት ሆኖኛል ህይወቴ\nራስ መሠረት ለቤቴ\n\nውለታ አይቆጥርም ሲሰጥ\nየሰውን ህይወት ሲለውጥ\nመቆም መኖሬ በእርሱ ነው\nዕድል ፈንታዬ ጌታ ነው\n', 'am', 446, 0),\n(1, 'በጌርጌሴኖን ያልተወኝ', 'በጌርጌሴኖን ያልተወኝ\nበጌርጌሴኖን ያልተወኝ\nቸር ጌታዬ ይመስገንልኝ\nፍቅሩ ድንቅ ነው ለፍጥረቱ\nአያልቅምና ሰላም ምህረቱ\n\nታርዤ ስኖር ልብሶቼን ጥዬ\nበቀን በሌሊት ሲፈስ እንባዬ\nድንግት መጣና ልጄ ሆይ አለኝ\nከሙታን መሀል ከእብደት አዳነኝ\n\nወዳጅም የለኝ ከአምላኬ ሌላ\nክሴን እሚፀየፍ ሞቴን የሚጠላ\nአየሁት ቆሞ በፍቅር ፊቴ\nድካሜን አጋዥ ሆኖ ረዳቴ\n\nጉዳተኛ ነኝ ፅኑ ደካማ\nየማልደመጥ የማልስማ\nእርሱ ግን ቀርቦ ቢጐበኘኝ\nውዳሴ አምልኮ አቀረብኩኝ\n\nድቅድቅ ጨለማው የዘንዶው ፉጨት\nእያስጨነቀኝ ሳዝን ስቃትት\nእንባዬን አባሽ ሆንከኝ መፅናኛ\nነፍስን መለስካት መልካሙ እረኛ\n', 'am', 447, 0),\n(1, 'እንደተወደደ', 'እንደተወደደ\nእንደተወደደ ይኖራል ዘለዓለም\nእንደተፈቀረ ይኖራል ዘለዓለም\nበመድርም በሰማይ የሚመስለው የለም\nእንደ ፈጣሪያችን ጌታ ማንም የለም\n\nሁሌም ተዘርግታ ትኖራለች እጁ\nየማይሆነው የለም ጌታ ለወዳጁ\nየኢዮብን አካል ዳግመኛ ሠርቶታል\nአልዓዛር ቢሞትም ከጥልቁ አውጥቶታል\n\nበርትቷል እሥራኤል ኃይል አግኝቷል ዛሬ\nበፅዮን ተራራ ቆሟል ለዝማሬ\nማሰማሪያዎቹ በመንጋ ተሞልተዋል\nቀንደ መለከቱ ለሁሉም ተሰምቷል\n\nከማርና ወተት ይጣፍጣል ስሙ\nበትህትናው ብቻ ተማርኳል ዓለሙ\nየማይፈለገው የለም እርሱን የማይሻ\nየፀና ምግብ ነው ስሙ የእምነት ጋሻ\n\nከሁሉም በላይ ነው ታላቅ ባለ ዝና\nየማይቆም ምስጋና ፊቱ ይፈሳልና\nቀለጠች መንፈሴ በፍቅሩ ትኩሳት\nክንዶቼ በረቱ ሳሸበሽብለት\n', 'am', 448, 0),\n(1, 'ኮብላዩ ነቢይ', 'ኮብላዩ ነቢይ\n\nስለወደድከኝ አዳንከኝ አንተ\nከአሳ ነባሪው ሆድ ከጥልቁ አውጥተህ\nኮብላዮ ነብይ መባል ይብቃኝ\nአንተን ወዳጄ ለክብር አበቃኝ\n\nጌታዬ የአንተን ቤት እቅፍህን ትቼ\nሰላሜን አጣሁኝ ከአንተ ተለይቼ\nየማላወራው ብዙ ደርሶብኛል\nአምላኬ ይብቃኝ ቤትህ ይሻለኛል\n\nወደተርሴስ ስጓዝ ከፊትህ ኮብልዬ\nለአንተ ለጌታዬ አልታዘዝ ብዬ\nመንገዴን ሁሉ በንፋስ አጠርከው\nድንቅ ነህ በእውነት ሆኗል አንተ ያልከው\n\nእንደ ንስር ሆኜ ወደላይ ብወጣ\nወደ ጥልቁም ብወርድ ላመልጥ ብቃጣ\nአልቻልኩም ፍጹም አሸንፈኸኛል\nመክረህ ገስህ ያንተ አድርገኸኛል\n', 'am', 449, 0),\n(1, 'በወደደን በርሱ', 'በወደደን በርሱ\nበወደደን በእርሱ ከአሸናፊዎች እንበልጣለን\nባህሩን እሳቱን እናቋርጣለን\nማዕበል ወጀቡን እንሻገራለን\n\nእርሱ የመረጠውን ማን ያዋርደዋል\nጌታ የመረቀው እንዴት ይረገማል\nልጆቹ ከተባልን ማን ይቃወመናል\nፍላፃና ቀስቱ ከእግራችን ሥር ወድቋል\n\nቀድሶ ሊያኖረን ወዷል የኛ ጌታ\nአስፍቶ ሰጥቶናል ፀጋውን በደስታ\nእንዳፀደቃቸው የቀደሙትን\nለእኛም ኪዳን ሰጠን ቤቱ ሊያኖረን\n\nእንደ እግዚአብሔር ሃሳብ የተጠሩ ሁሉ\nከበጐ ስጦታው ጠግበው ይኖራሉ\nእባብና ጊንጡን እረግጠው ኖረዋል\nበኃይልና ብርታት ወገባቸው ፀንቷል\n\nየታመነ ተስፋ ሰጥቶናል በቃሉ\nበእምነት እንጨብጠው ልጆቹ በሙሉ\nማድረግ አያቅተው ተራራውን ሜዳ\nእግዚአብሔር አምኖ ማንም አልተጐዳ\n', 'am', 450, 0),\n(1, 'የሚመስለው የለም', 'የሚመስለው የለም\nእግዚአብሔር ከዓለም በፊት ንጉሥ ነው\nየሚመስለው የለም የሚተካከለው\nእግዚአብሔር ከዓለም በፊት ንጉሥ ነው\n\nዓለምን ሳይፈጥር ብቻውን የነበረ\nበባህሪው ምስጉን ነው ፍጹም የከበረ\nከረቂቅ ከጥልቁ ከየብስ ከቀላያት\nእርሱ ቀዳሚ ነው መጋቢ ፍጥረታት\n\nዛሬ የሚታዩት ገና ሳይታዩ\nለይኩን እያለ ሁሉን ከመፍጠሩ\nየምስጋና መስዋዕት ሳይጠፋ ከፊቱ\nሲወደስ የኖረ በክብረ መንግሥቱ\n\nበሦስቱ ዓለማት ሳይፈጥር መላእክትን\nበሰማይ ሳያስጌጥ ፀሐይ ከዋክብትን\nእግዚአብሔር ነበረ በላይ በንግስናው\nውዳሴ ዝማሬ ፍጹም ሳይለየው\n\nደመናት ሳይወጡ ከመዛግባታቸው\nመባርቅት ሳይፈጥኑ ለአገልግሎታቸው\nበአንድነት ሦስትነት በከሀሊነቱ\nእግዚአብሔር ነበረ በምሉዕነቱ\n', 'am', 451, 0),\n(1, 'በምህረትህ ተቀበለን', 'በምህረትህ ተቀበለን\nአምላካችን ይቅር በለን\nበምህረትህ ተቀበለን\nበደላችን ቢበዛም\nከአንተ ሌላ ማንም የለን\n\nየሥጋ ፍላጐት ቀንበሩ ከብዶን\nከሕግህ ሲያወጣን ክፋት ሊያሰራን\nለሰይጣን ተገዝተን ወድቀን እንዳንቀር\nአምላክ ሆይ ጠብቀን በረድኤት ከልለን\n\nከአንተ ተለይተን ምን ህይወት ሊኖረን\nሀዘን መከራ ነው ለኛ የሚተርፈን\nየዓለም ፍቅር ስቦን ከቤትህ ቢያወጣን\nበምህረት እጆችህ ወደአንተ መልሰን\n\nበቤትህ እንድንኖር ፀንተን በሃይማኖት\nፈጣሪያችን እርዳን ጨምርልን እምነት\nማዕበል ተነስቶ በጣም አስግቶናል\nየማዳን ጥሪህን አምላክ ሆይ ናፍቀናል\n', 'am', 452, 0),\n(1, 'የሚኖር በግርማ', 'የሚኖር በግርማ\nየሚኖር በግርማ በታላቅ ምስጋና\nእግዚአብሔር ይመስገን ክብሬ የእርሱ ነውና\nከፀሐይ መውጫ እስከመግቢያ ድረስ\nስሙ ብሩክ ይሁን ይክበር ሥሉስ ቅዱስ\nየፀና ግንብ ነው ስሙ ላመኑበት\nየሕይወት ውኃ ምንጭ የጉዞአችን አለት\n\nሰማያትን ከድኗል ክብሩ የአምላካችን\nእግዚአብሔር ታላቅ ነው ቅዱስ አባታችን\nልቤ በእርሱ ፀና ባዳኙ ጌታዬ\nሳመልከው እኖራለሁ እንደችሎታዬ\n\nጽድቁ ለዘለዓለም ይኖራል ሲያበራ\nልጆቹ ባሉበት በጽዮን ተራራ\nእኔን ብትጠራኝ ብገባ ከሠርጉ\nይናፍቃል ልቤ እንድቀኝ ለበጉ\n\nትድግናው ለሕዝቡ መቼ ተቋረጠ\nለጋስ ነው ጌታችን አብዝቶ የሰጠ\nበፀጋ ላይ ፀጋ የተቀበለን እኛ\nምስክር ሆነናል ለስሙ ዳግመኛ\n', 'am', 453, 0),\n(1, 'ካንተ በቀር እኔ', 'ካንተ በቀር እኔ\nካንተ በቀር እኔ በጎነት የለኝ\nመልካም እንድሠራ ኃይል ካልሆንከኝ\n\nመልካም የምሆነው ጽድቅ የሚኖረኝ\nቀና ሰው ሆኛለሁ አንተ ስትረዳኝ\nአንተ የሕይወት ውኃ ፍሰስ በሕይውቴ\nእለመልማለሁ ይጠፋል ድርቀቴ\n\nአብርሃም ሲሰማህ በእምነት ስከተል\nአባቱን ሲተወው ተስፋዬ ነህ ሲል\nኃይልህን አልብስኸው ከወርቅ የሚያመጣ\nለኔም ኃይል ስጠኝ ተከትየ ልምጣ\n\nዛሬም የኔ ጌታ ልኑር ከአንተ ጋራ\nአበርታው ጉልበቴን ጽድቅን እንድሠራ\nእኔማ በራሴ ሁሌ ባዶ ነኝ\nአንተ ብቻ እኮ ነህ ሙሉ ያደረከኝ\n', 'am', 454, 0),\n(1, 'ደጉ ሳምራዊ', 'ደጉ ሳምራዊ\nአንተ ደጉ ሳምራዊ እለፍ በመንገዴ\nበኢያሪኮ ላይ ጥሎኛል ወንባዴ\nነፍሴ ወደ ጽኑ ሞት ተቃርባለችና\nየዓለም መድሀኒት እየሱስ ቶሎና\n\nበሞትና ሕይወት መካከል ወደቅኩኝ\nየሚያነሳኝ አጣሁ በብርቱ ቃተትኩኝ\nሰማሁኝ ከርቀት የአንድ ካህን ኮቴ\nያነሳኛል የሚል ነበረ ምኞቴ\nደሜን ተመልክቶ እጅግ ተፀየፈ\nፈቀቅ ብሎ ሄደ ሳይረዳኝ አለፈ\n\nአንድ ሊዋዊ ሰው በዚያ መንገድ መጣ\nአንሳኝ ብላ ጮኸች ልቤ ሀዘን ተውጣ\nወደኔ ሲጠጋ ኮቴውን ሰምቼ\nአንሳኝ ብዬ ማለድኩ እጆቼን አንስቼ\nፈቀቅ ብሎ ሄደ በሞት መሃል ሆኜ\nልቤ ብላ ነበር መጣልኝ አዳኜ\n\nአንድ ሳምራዊ ግን አየኝ ቀረበና\nከአህያው ወረደ በፍቅር በትህትና\nቁስሌን ጠረገና ባህያው ላይ ጫነኝ\nአነሳኝ ደግፎ በዘይቱ አጠበኝ\nሁለት ዲናር ከፍሎ ለእንግዶች ጠባቂ\nጌታዬ ታደጋት ነፍሴን ከነጣቂ\n', 'am', 455, 0),\n(1, 'ለድሆች ወንጌልን', 'ለድሆች ወንጌልን\nለድሆች ወንጌልን ሊሰብክ የተቀባ\nከሰንበት በአንዲቱ ወደ ምኩራብ ገባ\nጥቅልሉን ዘርግቶ ህዝቡ መሐል ቆሟል\nትንቢተ ኢሳይያስ ደርሷል ተፈፅሟል\n\nበእምነት ሲጠብቁት ነቢያቱ ሁሉ\nወርዶ ያድነናል ይወለዳል ሲሉ\nደረሰ ትንቢቱ ጊዜው ተፈፀመ\nይህን ሊነግራቸው ህዝቡ መሐል ቆመ\n\nህግና ትንቢቱን ምኩራብ ሸመነችው\nቤተክርስቲያን አርጋ ስለለበሰችው\nየማዕዘን ድንጋይ ሲቀመጥ በመቅደስ\nምዕመን ተገነባ በአዲስ ኪዳን መንፈስ\n\nእኔ አስነሳዋለሁ አፍርሱ ይህን መቅደስ\nአንዱ ጦብ ሳይጎድል ቅጽሩ ሳይበሰብስ\nመፍረስ መነሳቱ ለህንፃው አይደለም\nሞቱ ትንሳኤው ነው የሚያበራው ለአለም\n\nወንጌሉ ሲሰበክ ሲነገር ቃል በቃል\nመለኮት በስጋ ሲገለጥ ይደንቃል\nወእመ ኃይል ውስተ ኃይል ነኃውር ፍኖተ\nእስመ መምህረ ህግ ይሁብ በረከተ\n', 'am', 456, 0),\n(1, 'የሰው ዘመኑ እየሸሸ', 'የሰው ዘመኑ እየሸሸ\nየሰው ዘመኑ እየሸሸ\nቀን እንዲሄድ አውቆ እየመሸ\nበፅድቁ መንገድ በጉዞ ላይ\nያደርጋል ጠላት እንዲዘገይ\n\nበጣም ፈጣን ነው ሰው ዘመኑ\nቀንሶ ሚያድር በየቀኑ\nእውነት ነው ጠላት ይህን ያውቃል በየሰበቡ ያዘገያል\nበእሾህ መሀል እንዳለ ዘር\nአድጎ በፍሬ ማይቆጠር\nታንቆ የቀረ በዚህ አለም\nእንደኔ ሰነፍ ማንም የለም\n\nበወደቀው ሰው ራሴን ለካሁ\nመመዘኛዬን ቃሉን ረሳሁ\nስለ በደሌ ከመፀፀት\nተፅናና ልቤ በወደቁት\nችላ ባይ ሆኜ ነገ ዛሬ\nአለሁ በቅጠል ያለፍሬ\nበአለም ጨክኜ እንድቆርጥ\nእባክህ ጌታ ልቤን ለውጥ\n\nለፀሎት መትጋት ማስቀደሱ\nሁሌ መገኘት በመቅደሱ\nነበር ተብሎ ከተወራ\nበቅጠል ቀርቷል ሳያፈራ\nወደኋላ እርፍ ይዞ ከታረሰ\nፅድቁን በርኩሰት ከጨረሰ\nነውና ሰይጣን ያዘገየው\nየርሱ አሟሟት የከፋ ነው\n\nበመንፈስ ሆነው የቀደሙ\nበስጋ ስራ ደመደሙ\nየህይወት ቃልን የቀመሱ\nለአመፅ ለሀጥያት ይኸው ባሱ\nቆሚያለሁ ሚለው እንዳይወድቅ\nያለትህትና የለም ፅድቅ\nባርያ ነኝ ይበል የማልጠቅም\nታምኖ ይሰማራ በአምላክ ስም\n', 'am', 458, 0),\n(1, 'ማን አለን', 'ማን አለን\nማን አለን ጌታ ሆይ ካንተበቀር\nበሰማይ ሆነ በዚህ ምድር\nማን አለን ካንተበቀር\n\nዛሬ ወዳጅ ነገ ጠላት\nይለወጣል የሰው ህይወት\nያመናቸው ገፍተው ጣሉን\nአንተ ብቻ አትለየን\n\nህይወታችን መልኩ ወይሞ\nመንገዳችን በእሾህ ተከቦ\nጠላት በዝቶ ስንሰቃይ\nታገልክልን አንተ ኤልሻዳይ\n\nባይደላንም የምድር ኑሮ\nብናሰማ ለቅሶና እሮሮ\nባይሳካ ውጥናችን ባንተ\nያምራል ፍፃሜችን\n\nእንኳን ጨርሶ ሳንለምነው\nአፍሮ አይገባም ባዶ እጃችን\nስቦማውጣት እስኪያቅተን\nበዓሳ ሞላው መረባችን\n', 'am', 459, 0),\n(1, 'በምን እፅናናለሁ', 'በምን እፅናናለሁ\nበምን እፅናናለሁ ከሌለኸኝ\nበምን ልበረታ ካላገዝከኝ\nአንተ ስላለህ ነው መድኃኒቴ\nቆሜ መታየቴ\n\nሸክም ለከበደ ማረፊያ ነህ\nእጅግ የቀለለ ቀንበር ያለህ\nፍቅርህ ነው የሚያሰማራኝ\nበለምለም መስክ ያቆመኝ\nቸር አምላክ የእውነት ዳኛ\nአማኑኤል የኔ መታመኛ\n\nጨለማን አላውቅም በጉዞዬ\nበህይወቴ ሁሉ ነህ መሪዬ\nተጓዝኩኝ ሌቱን በብርሀን\nባንተ አየሁኝ መሻገርን\nቸር አምላክ የእውነት ዳኛ\nአማኑኤል የኔ መታመኛ\n\nማቀርቀሬን ሰበርክ አልኩኝ ቀና\nበርትቼ ተራመድኩ እንደገና\nቃልህ ኃይሌ የሚያጸናኝ\nበአለት ላይ የተከልከኝ\nቸር አምላክ የእውነት ዳኛ\nአማኑኤል የኔ መታመኛ\n\nእንባዬ ታበሰ ስታፅናናኝ\nግን የሆነው ሆኗል ስትረዳኝ\nበጠላቴ ፊት ሞገስ ሆንከኝ\nለባህሪያህ ድል ሰጠኸኝ\nቸር አምላክ የእውነት ዳኛ\nአማኑኤል የኔ መታመኛ\n', 'am', 460, 0),\n(1, 'በንፁህ ደሙ', 'በንፁህ ደሙ\nበንፁህ ደሙ ያዳነን\nከወደቅንበት ያነሳን\nብዙ ነው የእርሱ ውለታ\nእንዘምራለን ለጌታ\n\nቀና ብለናል በክብር\nአንገቱን ደፍቶ በፍቅር\nስለ እኛ ብዙ ሆነልን\nየብርሀን አክሊል ደፋን\nየዓለም መድኃኒት ጌታ ነው\nጠላታችንን ያሰረው\n\nእርቃኑን ሆኖ ሸለመን\nእየደከመ አቆመን\nእርሱ በመስቀል ሲሞት\nእኛ ተፃፍን በሕይወት\nየዓለም መድኃኒት ጌታ ነው\nጠላታችንን ያሰረው\n\nእስከ ሺህ ትውልድ ይምራል\nፍቅር ነውና ይራራል\nአይዝልም የእርሱ ትከሻ\nመጨረሻ ነው መድረሻ\nየዓለም መድኃኒት ጌታ ነው\nጠላታችንን ያሰረው\n\nበደም ያጌጠ ልብስ አለን\nከአማልክት ማንም አይመስለው\nትውልዱ ማዳኑን ይስማ\nነግሷል በፅዩን ከተማ\nየዓለም መድኃኒት ጌታ ነው\nጠላታችንን ያሰረው\n', 'am', 461, 0),\n(1, 'ለስብከተ ወንጌል', 'ለስብከተ ወንጌል\nለስብከተ ወንጌል ለጽድቅ አገልግሎት\nለአዲስ ኪዳን ስራ ለምስክርነት\nመድሐኒአለም መርጦ ጽናት ያለበሰ\nየእምነት አርበኛ ማርቆስ አንተ ነህ\n\nሐዋርያው ሰማእት አንተ የወንጌል ሰው\nትምርተ ወንጌልን ለዓለም ያወራኸው\nወልድ ዋህድ ብለኽ ዞረኽ ስትመሰክር\nመከራን ተቀበልክ ስለጌታ ፍቅር\n\nአንተ ኮከበ ግብጽ ማርቆስ አንበሳ\nትንሳኤውን ስትሰብክ ለነፍስኽ ሳትሳሳ\nየግብጽ ጣኦታት በሙሉ ረገፋ\nአማልክቶቻቸው በቃልኽ ረገፉ\n', 'am', 462, 0),\n(1, 'በጎ ስጦታዬ', 'በጎ ስጦታዬ\nበጎ ስጦታዬ ፍፁም በረከቴ\nካጠገቤ አትራቂ ድንግል እመቤቴ\n\nአልታክትም እኔ ሁሌ እጠራሻለሁ\nየሀዘኔን መርሻ አንቺን አግኝቻለሁ\nእንዴት አልፈው ነበር ያን ሁሉ መከራ\nከጎኔ ባቆሚ ድንግል ከኔ ጋራ\n\nቢታጠር መንገዴ ቅጥር ቢበዛበት\nይበረታል እግሬ አንቺ ካለሽበት\nየእሳቱ ግርማ ቢበዛ ፎጨቱ\nልቤን አሳረፍኩት ባንቺ ባዛኝቱ\n\nየቀደመው እባብ አውሬው አያድነኝ\nፍፃሜዬ እንዲያምር ድንግል ለምኝልኝ\nየቆምኩ ሲመስለኝ ተንገዳግጃለሁ\nየዛሬውን እንጂ የነገን መች አየሁ\n\nዛሬ ተመልሼ አየሁት ደግሜ\nምንም አላተረፍኩ በዚች ዓለም እድሜ\nልጅሽን አምኜ አንቺን እይዛለው\nየላላው ጉልበቴን አበረታዋለሁ\n\nጎዶሎዬ ሞልቷል ቤቴ ሰላም ለብሷል\nየጭንቅ አማላጄ አንቺን ተጠግቷል\nጠላቴ ቢፀፍም የእዳዬን ጦማር\nአልሞትም በጭራሽ ሳለው ካንቺ ጋራ\n', 'am', 465, 0),\n(1, 'በእፀ መስቀል ላይ', 'በእፀ መስቀል ላይ\nበእፀ መስቀል ላይ በዚያ አደባባይ\nአምላክ ሆይ ጌታ ሆይ ተንገላታህ ወይ\nአምላክ ሆይ ጌታ ሆይ መከራ አየህ ወይ\n\nመስቀል አስይዘው ኪርያላይሶ\nወደ ጎልጎታ ኪርያላይሶ\nሲገራፉ ሲዳፉ ኪርያላይሶ\nስትንገላታ ኪርያላይሶ\n\nያንን አቀበት ኪርያላይሶ\nያንን ዳገት ኪርያላይሶ\nጀርባህ ተገርፎ ኪርያላይሶ\nስትቃትት ኪርያላይሶ\n\nአንተን እያዩ ኪርያላይሶ\nሴቶች ሲያለቅሱ ኪርያላይሶ\nእናቶች ቀርበው ኪርያላይሶ\nራስክን ዳበሱ ኪርያላይሶ\n\nመስቀል አስይዘው ኪርያላይሶ\nእንዲያ ሲያዳፉህ ኪርያላይሶ\nየቀሬናው ሰው ኪርያላይሶ\nስምኦን አገዘህ ኪርያላይሶ\n', 'am', 476, 0),\n(1, 'ደም ግባት የለውም', 'ደም ግባት የለውም\nተቅበዝብዘን ነበር ነፍሳችን ቆዝማ\nእንጠፋ ነበረ በሲኦል ጨለማ\nሁሉም አዘንብሎ ለጥፋት ሲቃረብ\nአወጣን እየሱስ ከዲያብሎስ መረብ\n\nተጨነቀ ጌታ ተሰቃየ ጌታ\nበመስቀል ሞተ ሞትን ጠላትን ሊረታ\nእንደሚታረድ በግ በሸላቾቹ ፊት\nዝምታን መረጠ እንዲያሲያገላቱት\n\nአፉን አልከፈተም ሲሰድቡት ሲከሱት\nሐሞትና ከርቤ ቀላቅለው ሲያጠጡት\nአለም ጭካኔዋን ብታፈራርቅም\nከይቅርታ ሌላ አልመለሰላትም\n\nደዌ ማይስማማው በስጋው ታመመ\nየዓለምን ጠቢባን በዚህ አስገረመ\nሞቱ ግርፋቱ ሲያስቡት ይገርማል\nዓለም የፈጠረ በፍጡራን ታስሯል\n\nምን አይነት መውደድ ነው ምን አይነት ትዕግስት\nሰውን ያፈቀረ የፍጥረት አባት\nምን አይነት ርህራሄ ምን አይነት ይቅርታ\nበመስቀል ተሰዋ የፍጥረታት ጌታ\nበመስቀል ተሰዋ በፍጥረታት ፋንታ\n\nደም ግባት የለውም ሰለኛ ተገርፏል\nይህንን ህማሙን ማንሰውኮ አምኖዋል\nበእውነት ደዌያችን እርሱ ተቀበለ\nእርቃኑን ተሰቅሎ ቀራኒዮ ዋለ!\n', 'am', 477, 0),\n(1, 'ጌታ ብርሃኔና', 'ጌታ ብርሃኔና\nጌታ ብርሃኔና መድሃኒቴ ነው\nየሚያስደነግጠኝ የሚያስፈራኝ ማነው\n\nአያሳስበኝም የሳኦል ጥላቻ\nልቤ አይደነግጥም በጎልያድ ዛቻ\nየምታመንበት ስሙ ጋሻዬ ነው\nሀይልና ብርታቴ ጌታ ጉልበቴ ነው\n\nሞገስ ይሆነኛል በነገስታቱ ፊት\nእመሰክራለሁ ስሙን ያለፍርሀት\nአያስጨንቀኝም ሞትና መከራ\nሁሉን የሚችለው አለ ከኔ ጋራ\n\nጻድቃንን በገዳም የሚያበረታቸው\nሰማዕታትን በደም እንዲህ ያጸናቸው\nአሁንም ይሰራል የብርሃን ጌታ\nስሙን ተሸክሞ በእምነት ለበረታ\n\nከስም ሁሉ በላይ የሚበልጥ ስም ይዟል\nየማመልከው አምላክ ከሁሉም ይበልጣል\nምንስ እሆናለሁ ስሙን ተደግፌ\nበኢየሱስ ክርስቶስ ጥላ ስር አርፌ\n', 'am', 478, 0),\n(1, 'አቤቱ የሆነብንን', 'አቤቱ የሆነብንን\nአቤቱ የሆነብንን አስብ እግዚአብሔር\n\nቅኔ ማህሌቱ በደምህ ረሰረሰ\nመቅደስ ተቃጥሎ መሰውያዉ ፈረሰ\nጮሁ ደናግላን ደም እንባ አለቀሱ\nበቅድሱ ስፍራ ታርዷልና ቄሱ\n\nሰላም መስሎን ነበር መዉጣት መግባታችን\nለካስ በሾህ ታጥሯል ዙርያው ጎዳናችን\nየፅዮን መንገዶች በዕንባ ተሞልተዋል\nየሚያምሩት ግንቦችዋ በሌሊት ፈርሰዋል\n\nየቁጣህን በትር ማን ይቋቋመዋል\nየኃይልህን ጽናት ማንስ ይችለዋል\nየሽማግሌው ፊት አልታፈረምና\nከፊት ቀና እንበል እንዴት እንፅናና\n\nእንደ ዘካርያስ እንደ እግዚአብሔር ወዳጅ\nወደቁ ብዙዎች ገቡና ካንተ ደጅ\nህፃን አዛዎንቶች ጎበዦቹ ሁሉ\nተሰዉ ለፍቅር አንክድም እያሉ\n', 'am', 480, 0),\n(1, 'አማኑኤል ይቅር ባይ ነው ፍቅር', 'አማኑኤል ይቅር ባይ ነው ፍቅር\nአማኑኤል ይቅር ባይ ነው ፍቅር\nምህረት ከቦት በሰማያት ሚኖር\nእያመመው አባቱን እየጠራ\nአይቻለሁ ለሚገድሉት ሲራራ\n\nአይምረኝም አትበሉ ጨካኝ ንጉስ አይደለም\nደሙ ብቻ ያነጻናል ከኃጢአታችን ዘለዓለም\nእንደሞላ ጅረት ፈሶ ምድራችንን አጥለቅልቋል\nየእርሱ ምህረት ኃያል ሆኖት ስንቱ ከሞት አፈትልኳል\n\nየጨለመው እየነጋ የተሻለ ቀን ይመጣል\nበፍቅሩ ጦር ሳይወጋ ማን ከሞት ፊት ሮጦ ያመልጣል\nያን ክፉ ቀን በድል አልፈን እንደዋርካ የሰፋነው\nነውርን ሁሉ በሚከድን በሞተልን በኢየሱስ ነው\n\nየእርሱን ፍቅር የሚያሸንፍ አንዳች ኃጢአት የለምና\nወደ ጌታ ለመመለስ አንዳች እንኳን እንዳትፈራ\nሃገራችን በሰማይ ነው የሚወድቅ የለም የሚረሳ\nሰማያትን እንወርሳለን በበጉ ደም የተነሳ\n\nወዳጅ አለን አንድ ብቻ በሰማይም በምድር\nስሙ ኢየሱስ የተባለ ሰውን ሁሉ የሚያፈቅር\nከመቃብር በላይ ሆኖ ፍቅሩ ዓለምን አስገረመ\nይህን ሁሉ ጎስቋል ሰው በትከሻው ተሸከመ', 'am', 481, 0),\n(1, 'ከክርስቶስ ፍቅር', 'ከክርስቶስ ፍቅር\nከክርስቶስ ፍቅር የሚለየን ማን ነው፣\nመከራ ችግር ስቃይ ወይስ መራቆት ነው።\n\nአንፈራም አንሰጋም አንጠራጠርም፣\nእግዚአብሔር ከእኛ ጋራ ይኖራል\nለዘለዓለም።\n\nየሰማይ ቤታችን ዐማኑኤል የሠራው፣\nግንቡ ንጹህ ውሃ መሠረቱ ደም ነው።\n\nሳይነጋ ተራምደን እንግባ በጠዋት፣\nበደሙ መስርቶ ከሠራልን ቤት።\n\nከቶ የትይገኛል እንዲህ ያለ ቤት፣\nየውሃ ግድግዳ የደም መሠረት።\n\nየውሃ ግድግዳ የደም መሰረት፣\nይኸው እዚህ አለ የዐማኑኤል ቤት።\n', 'am', 483, 0),\n(1, 'መኑ ውእቱ ዝንቱ', 'መኑ ውእቱ ዝንቱ\nመኑ ውእቱ ዝንቱ ንጉሠ ስብሐት\nመኑ ውእቱ ዝንቱ አምላከ ምሕረት\nይባእ ንጉሠ ስብሐት ይባእ አምላከ ምሕረት\n\nሆሣዕና በሉ መድኃኒት ነው እርሱ\nለበሽተኞች ፈውስ አድሏል ቀሚሱ\nደጁን ክፈቱለት ቀኑ ነው የጌታ\nመኳንንት ተነሱ በሆታ በእልልታ\n\nለዓለም የምንሰብከው የመዳናችን ቀን\nፍቅሩ እስከ ሞት ነው ለእኛ እስከ መውረድ\nየጥሉ ግድግዳ ፈርሷል እንዳይቆም\nሰውና መላእክት አብሮ እንዲያዜም\n\nበልባችን መቅደስ ነግሶ የሚኖረው\nለነፍሳችን ዋጋ ካሳ የከፈለው\nየድንግል ማርያም ልጅ አልፋና ኦሜጋ\nያን ጨለማ አጥፍቶ ለእኛ ሲል አነጋ\n\nፍቅር አገብሮት ሞቷል በትህትና\nያመናችሁ ሁሉ ቁሙ በምሥጋና\nከምንነግረው በላይ ከተወራለት\nቃላት አይገልፀውም የእርሱን ጌትነት\n', 'am', 485, 0),\n(1, 'የኔ መሃሪ', 'የኔ መሃሪ\nየኔ መሃሪ ሁሉን መርሻዬ\nእንደ ሕልም አልፏል\nትላንትናዬ ባንተ ጌታዬ\n\nአዳፋው ልብሴ ከነፃ\nከእዳ ከፈታኝ በነፃ\nለፅድቁ ባርያ ሆኛለው\nሳገለግለው እኖራለሁ\n\nየእንባ ዘለላን ያቀፈው\nአይኔም እልልታ ተረፈው\nደልዳዩ መዳፍ ደርሶልኝ\nተራራው ሜዳ ሆነልኝ\n\nአይኖቼን ከጉድ ጋርዶልኝ\nክንዶቼን በጁ ይዞልኝ\nከእግሬ በታች ነው ወጀቡ\nአሁን ታይቶኛል ወደቡ\n\nሰላም ይነፍሳል ዙሪያዬ\nእረፍት ሆኖልኝ ጌታዬ\nየባረከኝን ባርኬ\nተለወጠልኝ ታሪኬ\n\nብርሃንህ ገፏል ድቅድቁን\nበልቤ ተክሏል ሰንደቁን\nተቆጣጥሮኛል መውደዱ\nመንገዴ ሆኖአል መንገዱ\n\nያበቃው ነገር ቀጥሏል\nጭንቄ በሞቱ ተሰቅሏል\nየኢየሱስ ሁኜ ምን አጣው\nሁሉን በስሙ ተወጣሁ\n\nእንደኔ ማንን ታግሷል\nይቅርታ ፍቅሩን አልብሷል\nማይገባኝን አድርጎ\nያሳለፈኝን ሸሽጎ\n\nመልካም ነው ለኔስ መልካም\nፀጋው ያገዘኝ ስደክም\nሞትኩኝ ስል ምህረት ደርቦ\nአቆመኝ በሕይወት አስውቦ\n', 'am', 486, 0),\n(1, 'ልቤ ያውቀዋል', 'ልቤ ያውቀዋል\nልቤ ያውቀዋል ያደረክልኝ ነገር\nየሰራህልኝን ስራ\nመድኃኔዓለም አወጣህኝ ከመከራ\nበቃል ጉልበት አይወራ\n\nመስቀል ተሸክመህ በደም ርሰህ\nእኔን በመከራ ዳግም ወልደህ\nበክብር ተሻገርኩ ክሰህልኝ\nበህይወት አቆምከኝ ወድቀህልኝ\n\nየበደሌን ጋራ አቀበቱን\nየባርነት ሰነድ እዳ ክሱን\nአጥፍተህው ጌታ መድሀን ሆነ\nእርቃኔ በእርቃንህ ተሸፈነ\n\nበፍቅርህ መአዛ እርክቷል ልቤ\nበማይቆም መውደድህ ተከብቤ\nየህይወቴ ወደብ መስቀልህ ነው\nወጀብ እና ንፍስ የማይነቅለው\n\nየእሾህ አክሊል ደፍተህ ኤልሻዳይ\nእፎይ አለ ልቤ ከስቃይ\nሆኖልኛል መዳን አንተ ታመህ\nነፃ ወጣሁ ሸክሜን አንተ ተሸክመህ\n\nዙፍንህን አስተወህ የኔ ፍቅር\nከሰማይ ሀገርህ መጣ በምድር\nታየህ ስትፈልገኝ ልጄ ብለህ\nፈራጅና አስዳቂ አምላኬ ነህ\n', 'am', 487, 0),\n(1, 'ዘጠኝ ሰዓት ሲሆን', 'ዘጠኝ ሰዓት ሲሆን\nዘጠኝ ሰዓት ሲሆን አባት ሆይ\nበመስቀል ሆነህ አባት ሆይ\nድምጽህን በማሰማት አባት ሆይ\nነፍስህን ሰጠህ አባት ሆይ\n\nከዋክብተ ሰማይ በሙሉ ረገፉ\nጨረቃና ፀሐይ ደምን አጎረፉ\nብርሃናት ጨለሙ ጠፍተው ተለያዩ\nሥጋህን በመስቀል ተገልጦ ስላዩ\n\nጌታችን ክርስቶስ በመስቀል ላይ ሳለ\nአሰምቶ ጮኸ ተጠማሁ እያለ\nማርና ወተትን ለሚመግበው\nሐሞት አመጡለት ይቅመሰው ብለው\n\nአካሉ ሲወጋ ውኃ ደም ፈሰሰ\nበምድር ተረጭቶ ዓለምን ቀደሰ\nየእሥራኤል ሴቶች ዋይ ዋይ ሲሉልህ\nለእነርሱ አዘንክ እንጂ ለአንተስ አላሰብክም\n\nእናትህ ስታለቅስ በመስቃል ሥር ሆና\nዮሐንስን ሰጠህ ጠብቆ እንዲያፅናና\nመላእክትም ታዩ አጋንንትም ሸሹ\nየአይሁድ ሠራዊት ፈርተው ተረበሹ\n', 'am', 488, 0),\n(1, 'ሞት ነው ረሃብ', 'ሞት ነው ረሃብ\nሞት ነው ረሃብ ከክርስቶስ ፍቅር የሚለየኝ\nኃይሉ በእኛ ላይ አድሮ እንበረታለን\nፀጋው በእኛ ላይ አድሮ እንበረታለን\n\nከአንተ ርቀው ሸሽተው እየሔዱ\nጠፋባቸው የጽድቅ መንገዱ\nበስጋዊ ጥበብ ሲፍልጉህ\nበመታለል ስንቶች አንተን አጡህ\n\nበተዋህዶ የከበረው ጌታ\nመድሃኔአለም ሆነልን መከታ\nስንደክም ምኞት ሲፈትነን\nኃይልን ሰጥተህ በእጆችህ ደግፈን\n\nየአለም ሰይፍ በእኛ ላይ ተስሏል\nስጋችንን ሊቆርጠው አድብቷል\nኃይልን ስጠን እንድናሸንፈው\nፀጋህ ለእኛ የእምነት ጋሻችን ነው\n\nሐዋርያት ፀጋ በዝቶላቸው\nስለፍቅርህ ፈሰሰ ደማቸው\nዛሬማ ለእኛ ፀጋህን አብዛልን\nእንዳክም ፈተና ሲገጥመን\n\nጋሻ ሆነህ እንድትመክትልን\nቸር አምላክ ሆይ ወደ አንተ እንጮሀለን\nቢገጥመን ችግር ወይ መከራ\nአትለየን ጌታ ከኛ ጋራ\n', 'am', 490, 0),\n(1, 'አንተ ነህ ተስፋዬ', 'አንተ ነህ ተስፋዬ\nአንተ ነህ አንተ ነህ ተስፋዬ\nአንተ ነህ አምላኬ ተስፋዬ\nመጣል የማታውቀው ቅዱስ ጌታየ\nወረት የማታውቀው ቅዱስ ጌታየ\nአንተ ነህ አንተ ነህ ተስፋየ\n\nያደፈ ነውና መጎናጸፊያየ\nእንዴት አስገባኸኝ ከቤትህ ጌታየ\nያለ ምክንያት መውደድ ትችልበታለህ\nምን አይነት አምላክ ነህ በሰማያት ያለህ\n\nሰንጋዮች በውሀ ቢኖር መኖሪያቸው\nነገር ግን በነርሱ ህይወት የለባቸው\nአንተን እየፈሩ ከቤትህ ከኖሩት\nከሚድኑት አርገኝ ከሚለመልሙት\n\nአለቱን ሰንጥቀህ ውሀ ታወጣህ\nደረቁንም በትር ታለመልማለህ\nበተዘጋው ገብተህ ገብተህ ሰላም ትሰጣለህ\nበል ልቤን ስበረው ትችለበታሀ\n', 'am', 491, 0),\n(1, 'አድርገህልኛልና', 'አድርገህልኛልና\nአድርገህልኛልና በቸርነትህ አመሰግንሀለው\nአለም ለአለም አማኑኤል እገዛልሀለው መድሀኒአለም\n\nቀኑ ጨልሞብኝ ዙርያው ገደል ሆኖ\nየችግር አረንቋ ፊቴ ተደቅኖ\nረዳት ያጣሁኝ በመሰለኝ ጊዜ\nፈጽሞ አራክልኝ የልቤን ትካዜ\n\nአምላክ ሆይ ጉልበቴ ሀይሌ መመኪያዬ\nጠላት ማሳፈሪያ የእምነት ጋሻዬ\nእንደ ማትተወኝ አሁን አውቄያለሁ\nካለኝ ነገር ይልቅ በአንተ ታምኛለሁ\n\nጥቂቷን አብዝተህ የምትመግብ ጌታ\nየምመልስልህ ባላገኝ ስጦታ\nበቀንም በሌሊት ሁሌ የሚያበራ\nመንክረ ባህሪ እፁብ ያንተ ስራ\n\nአምላክ ሆይ ምስጋና ላንተ ይገባል\nለምስኪኗ ጎጆ በረከት ሰተሀል\nደሀ ነኝ አልልም ሀብቴ አንተ ነህና\nማሰሮዬ ሞልቷል ላይግል እንደገና\n', 'am', 492, 0),\n(1, 'አንተ ብቻ ንጉስ', 'አንተ ብቻ ንጉስ\nአንተ ብቻ ንጉስ አንተ ብቻ ዳኛ\nተመስገን ኢየሱስ የነብሴ መጽናኛ\n\nሰለ ፍቅር ሁሌ ባነባ\nላፈስልህ የቅኔ መባ\nላንተ ቅኔ አይሆንም ካሳ\nእስከ ሽበት ስምክን ባነሳ\nላንተ ቅኔ አይሆንም ካሳ\nእስከ እድሜ ልኬ ስምክን ባነሳ\n\nያሰተማረከኝ የውዴን ፊደል\nየተከልከው የልቤን ወደል\nእያነቃኝ አመልክሃለሁ\nካንተ ወዲያ ማንን አውቃለሁ\n\nሰውነቴ ከግፍ እንዲጸዳ\nህሊናዬን አንተን ቢረዳ\nተጸየፈ የሰውን ምርኩዝ\nስታበራ በልቤ መቅረዝ\n\nከእንቅብ በታች እጄን አፀናሁ\nበተራራ እግሬን አፀናሁ\nመገዛቴ ለፍቅር ቀንበር\nሰው አረገኝ አንስቶ ከአፈር\n', 'am', 493, 0),\n(1, 'የተሻለ ነገር', 'የተሻለ ነገር\nየተሻለ ነገር አስበህልኝ ነው\nፈተናው የበዛው\nነገ መልካሙን ቀን አያለሁ\nበዚህም አምናለሁ\n\nሰው ነኝ መቼም እቸኩላለሁ\nየሀሳቤን ቶሎ እሻለሁ\nአዳዴማ በቃ እረስቶኛል\nእላለሁኝ እኔን ትቶኛል\nአንተ ግን ስጦታህ ብዙ ነው\nታደርግልኛለህ በጊዜው\nአንተኮ አትፈልግም ውድቀቴን\nሁል ጊዜ በጭንቀት ማንባቴን\n\nአንዱን ችግር ሳልሻገረው\nይደረባል ገዝፎ ሌላኛው\nየሕይወትን ውጣ ውረድ\nአይቻለሁ ስንቱን መንገድ\nጨለማው ቢረዝም ሌሊቱ\nአይኔ አይቀርም ብርሃን ማየቱ\nእሩቅ የመሰለው ይቀርባል\nሰላም ወደ ቤቴ ይገባል\n\nፈተናዬ ቢበዛብኝም\nየሀዘኔ ማብቂያው ቢርቅ\nአምላክ ባንተ ታሪክ ይሆናል\nየደስታ ቀን ለኔም ይመጣል\nአንተ አትሳሳትም በስራህ\nፍፁምና መልካም አባት ነህ\nእስከሚሆን ድረስ ተራዬ\nእጠብቅሃለሁ ጌታዬ\n\nአለፈኮ ዘመኔ እያልኩኝ\nበማጉረምረም ይሄው አለሁኝ\nፅናት ጎሎት ልቤ ቢያማርም\nያሰብክልኝ ያልከው አይቀርም\nአንተ ግን ስጦታህ ብዙ ነው\nታደርግልኛለህ በጊዜው\nአንተኮ አትፈልግም ውድቀቴን\nሁል ጊዜ በጭንቀት ማንባቴን\n', 'am', 494, 0),\n(1, 'መልካም ነህ ብልህ', 'መልካም ነህ ብልህ\nመልካም ነህ ብልህ ይሄም ያንስብሃል\nታላቅ ነህ ብልህ ይሄም ያንስብሃል\nቅዱስ ነህ ብልህ ይሄም ያንስብሃል\nልዩ ነህ ብልህ ይሄም ያንስብሃል\nአንደበቴም በሺህ ቃላት\nማዳንህን ቢናገር\nመች ይበቃል መች ይበቃል\nእንደው ልብን ያስደንቃል\n\nበቀልና ፍርድን በእጅህ ጨብጠህ\nየሚበላ የእሳት ነበልባል ሆነህ\nታላቅ ታጋሽ ምህረትህ ለትውልድ\nትደንቃለህ ጌታ የሰውን ልጅ ስትወድ\nእጀምራለሁ መዝሙር ቅኔ ለመድረስ\nበቃላቴ የአንተን ስራ ልጨርስ\nተፈጸመ ብዬ ብዕሬን ሳስቀምጥ\nይቀጥላል በአዲስ ስራ መገለጥ\n\nእረኛ ነህ የምትሞት ስለመንጋው\nሳምራዊ ነህ የምታዝን ለተወጋው\nበር አንት ነህ መማጸኛ ከተማችን\nምስክር ነህ የእግዚአብሔር ልጅ ለነፍሳችን\nአትክልተኛ መስሎ ባየው ቀና ብዬ\nማርያም ሲለኝ አየዋለሁ ከኋላዬ\nየለም ብዬ ተወኝ ብዬ ሳማርር\nሲናገረኝ እሰማለሁ በፍቅር\n\nዓለት ሆነ አላውቅህም ያለህ ኬፋ\nማን እንዳንተ የሚታገስ ሳያጠፋ\nአሳዳጁ ሰይፍህን ጣል ተመለሰ\nአላማ አለው ጌታ ኢየሱስ በአንተ ነፍስ\nተጥያለሁ ተረሳሁኝ አትበሉ\nደሙ ሲወርድ እዩት እንጅ ከመስቀሉ\nየመቅደሱ መጋረጃ ተከፈተ\nሰላም ግቡ አንዱ ለእኛ ስለሞተ\n', 'am', 496, 0),\n(1, 'አላውቅህም ብዬ', 'አላውቅህም ብዬ\nአላውቅህም ብዬ በሰው ፊት የምክድህ\nለጠላት አንስቼ አሳልፌ የምሰጥህ\nእኔ እሆንን ጌታ ሆይ እኔ እሆንን\nእኔ እሆንን አምላክ ሆይ እኔ እሆንን\n\nይሁዳ ነኝ ወይስ ጴጥሮስ ሀሙስ ማታ እኔ ማነኝ\nየዛሬን መቆሜን እንጂ አላውቅም መጨረሻዬን\nእወድሀለው ብዬ የዛሬን እናገራለሁ\nአላውቅህም እንዳልልህ ስለነገ ግን እፈራለሁ\n\nስንት የአጥቢያ ኮከቦች ላንተ ዘምረውልህ ወደቁ\nበሰማይ መቅደስህ አጥነው በትዕቢት ረግፈው አለቁ\nእፈራለሁ እኔም ለራሴ መንገዴን ንገረኝ ጌታ\nጠዋት በዘመርኩበት አፍ እንዳልሳደብ በማታ\n\nሳጥናኤል መልዐክ ነበረ ይሁዳም ሐዋርያ\nንስጥሮስም ጳጳስ ነበር አርዮስም ባለሙያ\nእነዚህ ሁሉ ከወጡ ከአምላካቸው ጉያ\nደካማ ለሆንኩትማ የት ይሆን የኔ መገኛ\n\nታናሹን ጅማሪዬን አንተው ታላቅም አድርግልኝ\nነበረች ከመባል ፈተና አንተው በፍቅርህ አድነኝ\nያስጀመርከኝ አምላኬ ሆይ እንግዲ መንገዴን አደራ\nበፊትህ ቆሜ ለማመስገን አብቃኝ ከቅዱሳን ጋራ\n', 'am', 497, 0),\n(1, 'እግዚአብሔር', 'እግዚአብሔር\nእግዚአብሔር ብርሀኔና መድሀኒቴ ነው\nየሚያስደነግጠኝ የሚያስፈራኝ ማን ነው\nአምላኬ መመኪያየ ነው\n\nሁሉ ቢከዳኝ አንዱን ይዠዋለሁ\nነብሱን ለሰጠኝ ነብሴን እሰጣለሁ\nልቤ ብርቱ ነው ስሄድ በውሀው ላይ\nየሚረዳኝ ክንድ ነውና ከሰማይ\n\nከብዙ ብረት ጠጠር ይመዝናል\nድልን ለበስኩኝ ልቤ በእርሱ ጸና\nየታመንኩበት ጽኑ ግንብ የሆነኝ\nያሻግረኛል እንደተሸከመኝ\n\nበነገስታት ፊት በሸንጎ ብቆምም\nስሙን ከማወጅ በፍጹም አልሰንፍም\nምናገረውን እርሱ እያስታወቀኝ\nግፊያው ቢበዛም ዛሬም በቤቱ ነኝ\n\nስላስቀደምኩኝ ሰባሪውን ጌታ\nየጠላቴ ጦር ሰልፈኛው ተመታ\nየቀስቱን ጉልበት መክቶልኝ ስሙ\nፈጠኑ እግሮቼ ስራውን ሊያሰሙ\n', 'am', 499, 0),\n(1, 'ወንበዴ ነበርኩኝ', 'ወንበዴ ነበርኩኝ\nወንበዴ ነበርኩኝ ሀገር ያሰለቸሁ\nበመስቀል ላይ ሆኖ ታሪኬን ለወጠዉ\nአስበኝ ስላልኩት በኋላ ስትመጣ\nገነትን ለማየት\nየመጀመሪያው ሰው ሆንኩኝ ባለእጣ\n\nአቤት ፍቅሩ የእግዚአብሔር\nግሩም ፍቅሩ የእግዚአብሔር\nኃያል ፍቅሩ የእግዚአብሔር\n\nአስበኝ ስላልኩት አሰበኝ ጌታዬ\nወንበዴ ነበርኩኝ ስርቆት ነው ሙያዬ\nበመስቀል ላይ ሆኖ ሕዝቡን ያስብ ነበር\nእኔስ አላየሁም\nእኔስ አላየሁም እንዲህ ያለ ፍቅር\n\nአልታይም ብዬ ኃጥያትን ስሰራ\nተመለስ ይለኛል ስሜን እየጠራ\nእንዳልሞትበት ነው በኃጥያት ታስሬ\nፍቅሩን አልዘልቀውም\nፍቅሩን አልዘልቀውም እንደዚህ ዘርዝሬ\n\nመከራ ሲገጥመኝ መጥቶ ያጽናናኛል\nበሃዘኔ ጊዜ እግዚአብሔርም ያዝናል\nዓይኑ ከእኔ አይርቅም ጥበቃው አይጠፋም\nስሙን እጠራለሁ\nስሙን እጠራለሁ በጌታዬ አላፍርም\n', 'am', 501, 0),\n(1, 'ውለታህ ነው እንጂ', 'ውለታህ ነው እንጂ\nውለታህ ነው እንጂ ሁሌ የሚያስለቅሰኝ\nእኔማ በኑሮ ምንም አልጎደለኝ\nመቼ አሳነስክብኝ ሕይወቴን ባረከው\nግብሬን ቸል ብለህ ቆጠርከኝ እንደሰው\n\nውስብስብ ያለብኝ ጽድቅና ኩነኔ\nለቃልህ ማልመች ደካማ ነኝ እኔ\nስላጣሁ አይደለም ወይንም ታርዤ\nፍቅርህ ቢገርመኝ ነው ምታየው ተክዤ\nእንደቃልህ ልገኝ አልቻልኩም ልጸና\nግን ታኖረኛለህ በሰላም በጤና ይድረስህ ምስጋና\n\nብዙ ሰዎች ሳሉ ህግህን ያወቁ\nስለአንተ የተጉት በአጭር የታጠቁ\nእኔ ማን ስለሆንኩ ምን ታምር ሰርቼ\nበክብር ያኖርከኝ ከህግ ሸሽቼ\nእንደቃልህ ልገኝ አልቻልኩም ልጸና\nግን ታኖረኛለህ በሰላም በጤና ይድረስህ ምስጋና\n\nበመኖገድህ ልሄድ ደፋ ቀና ብዬ\nአልቃና አለኝ ይህ ምስኪን ስጋዬ\nስወድቅ ስነሳ ልቤ እየደማ\nማለቅሰው ለዚህ ነው መዳኔን ስሰማ\nእንደቃልህ ልገኝ አልቻልኩም ልጸና\nግን ታኖረኛለህ በሰላም በጤና ይድረስህ ምስጋና\n\nጾም እኔን አያውቀኝ በጸሎት አልተጋሁ\nየበሰለ ፍሬ የጣመ እየበላሁ\nእንዲሁ ምህረትህ ሁሌ ይከተለኛል\nይህ ፍቅርህ ደግሞ እኔን ሰርክ ያስለቅሰኛል\nእንደቃልህ ልገኝ አልቻልኩም ልጸና\nግን ታኖረኛለህ በሰላም በጤና ይድረስህ ምስጋና\n', 'am', 502, 0),\n(1, 'አስምርልኝ መስዋዕቴን', 'አስምርልኝ መስዋዕቴን\nአስምርልኝ መስዋዕቴን\nተቀበለኝ ምስጋናዬን\nአምላከ አቤል እግዚአብሔር\nተቀበለኝ ምስጋናዬን\n\nባይገባኝ ቅዱስ ስምህን መጥራት\nእንደሃጥያቴ እንደበደሌ ብዛት\nፍቀድልኝ ልሰዋ ምስጋናህን\nልመስክረው ጽድቅና ማዳንህን\nበጥበቤ አደለም በብቃቴ\nለምስጋና ስምክን መጥራቴ\n\nየምስጋና ቅኔ ልሰጥ ሰጠኀኝ\nየዜማ ቃል በጄ አሰለጠንከኝ\nእለት እለት ቸርነትህ ደንቆኛል\nለምስጋና ፍቅርህ ያበረታኛል\nበጥበቤ አደለም በብቃቴ\nለምስጋና ስምክን መጥራቴ\n\nኮልታፋ ነው ያልበቃ አንደበቴ\nደካማ ነው ያልበረታ ጉልበቴ\nስለስምህ ዘወትር እቀናለው\nለዘላለም ጌታዬ እልሃለው\nበጥበቤ አደለም በብቃቴ\nለምስጋና ስምክን መጥራቴ\n\nምስጉን ጌታ ስምህን ላመስግን\nስለምትወድ ንጹህ መስዋዕትን\nበከበረው በያሬዳዊው ዜማ\nተቀበለው ምስጋናዬን በራማ\nበጥበቤ አደለም በብቃቴ\nለምስጋና ስምክን መጥራቴ\n', 'am', 503, 0),\n(1, 'ልቤ አቤት በል', 'ልቤ አቤት በል\nልቤ አቤት በል እንጂ አምላኬ ሲጣራ\nኃጢአትን ተውና መልካም ምግባር ሥራ\nበደሌን አውቄ ይቅርታን ልጠይቅ\nሁሉን ቻይ ነህና ፍጥረትህን የማትንቅ\n\nአለቅሳለው ዘወትር አነባለው\nአውቃለው አምላኬ ብዙ በድያለው\nለቅሶና ጩኸቴን ተቀበለኝ\nጎስቋላ ሆኛለው ኃጢአት ያደከመኝ\n\nመንገድ ተላልፌ ፈጣሪ አስቀየምኩ\nበሚጠፋ ንብረት አምላኬን ለወጥኩ\nአሁን ግን አምኜ ብዙ እንደበደልኩ\nምሕረትን እንዳገኝ ይቅርታን ለመንኩ\n\nየኃጢአት መጋረጃ ፊቴን ሸፍኖታል\nኃይሌ ከኔ ርቆ መቆም ተስኖኛል\nነሽና በፊቱ ክብር ሞገስ ያለሽ\nድንግል ልመናዬን አድርሺ ከልጅሽ\n\nጉልበት አንተ ሁነኝ መተማመኛዬ\nበደሌን አጥፋልኝ ሁን አስተማሪዬ\nከበደል እንድርቅ እጅህን ዘርጋና\nዳግም እንዳልበድል አጽናኝ በምስጋና\n', 'am', 504, 0),\n(1, 'ምነው ወዳጄ ምነው', 'ምነው ወዳጄ ምነው\nክበር ተመስጌን የኛ ጌታ\nከጠዋት አንስቶ እስከ ማታ\nአብ ልጁን ሰቅሎ ግብር ጠርቷል\nበመድሃኒአለም አዳም ድኗል\n\nየእየሩስአሌም ገዳም ቄስ\nአማን ሲል ያድራል ሲቀድስ\nምን አሳሰበው ለእኛ ሰው?\nአለም በቃኝ ላለው!\nምነው ወዳጄ ምነው?\n\nአርብ እሮብ ፆሞ ሲያስቀድስ\nከደጀሰላም ሲመለስ\nብጠራው ዝም አለኝ ወይ ፍርጃዬ\nአቤት አቤቱ ጌታዬ\nምነው?\n\nአምላክ ግብር ሰርቶ ያበላል ይላሉ\nበምድር ቀሪ የለም ሁሉም ይጠራሉ\nአምላኬ ግብርህን እንዳታሳንሰው\nእምቢ ብሎ አይቀርም አንተ የጠራሃው ሰው\nና ምነው?\n\nቁጠሩ ቢሏቸው የሳምንቱን ቀናት\nስድስቱን ጠሩና እሮብን ገደፏት\nና ምነው\n', 'am', 505, 0),\n(1, 'አምላክ ሆይ ወደኛ ባትመጣ', 'አምላክ ሆይ ወደኛ ባትመጣ\nአምላክ ሆይ ወደኛ ባትመጣ ለብሰህ የማርያምን ሥጋ\nባክኖ የነበረው የአዳም ዘር ውጤቱ ነበር የሚያሰጋ\n\nበዚያ ዓመት በዚያች ወር በዚያች ቀን ድኅነትን ለሰው ልጅ ስትሰጥ\nምን የበዛ ነበር ትህትናህ ትዕግስትህ የማይለወጥ\n\nየሾህ አክሊል ደፍተው በራስህ ጎንህን ሲወጉህ በጦር\nአንተ ግን ለእነርሱ ከአባትህ ምህረትን ትለምን ነበር\n\nግን መቼ አወቁህ እነሱ በኃጢያት ደንዝዞ ልባቸው\nመድኃኒታቸውን ገረፉህ ሰቀሉህ አንተም ሞትክላቸው\n\nዳግም ስትመጣ ለፍርድ ከዓለም ፍጻሜ በኋላ\nኧረ እዴት ዕድለኞች ናቸው በፊትህ የሚያገኙ ተድላ\n\nበዚያች በደብረ ዘይት ቦታ ደስታና ለቅሶ ሲፈልቅ\nከቶ ከየት ይሆን ዕጣዬ ያንጊዜ የእኔ አወዳደቅ\n\nየጸጸት እሮሮ በፊትህ እንዳያቃጥለኝ እኔን\nእርዳኝ ፈጣሪዬ ካሁኑ አድሰው የዛገው ልቤን\n', 'am', 506, 0),\n(1, 'እንደበደሌማ', 'እንደበደሌማ\nእንደበደሌማ እንደኔ ክፋት እንደበደሌማ እንደኔ ሃጢያት\nአልተውከኝም ጌታ የምህረት አባት\n\nሃጢያቴን ሳስተቆጥር በደሌን ሳትመረምር\nአነሳህኝ ካፈር ለክብርሀ እንደዘምር\nለኔ ያደረከው ውለታህ ብዙ ነው\nእድሜ ዘላለሜን ስምን ላወድሰው\n\nምህረትህ ፅንፍ የለው ይቅርታህ ፍፃሜ\nደርቄ ሳትቆርጠኝ ሰተህኛል እድሜ\nበቀሪው ዘመኔ በፍቅር ላገልግልህ\nየእኔን ዘመን ትቼ ላንተ ልኑርልህ\n\nአምስት እንጀራና አሳ ባይኖረኝም\nበረከት ፀጋህን ጌታዬ አትነሳኝም\nየፍቅርህን ጣዕም ከልቤ አሳድረው\nቃልህን ልከተል ትዛዝን ልኑረው\n\nህግና ትዛዝህ ከልቤ ተፍቋል\nበአለም ሀሳቦች ወንጌል ተሰርቆል\nየልጅ ሙከራዬን እንደ ትልቅ ቆጥረህ\nለዚህ አበቃህኝ በደሎቼን ምረህ\n\nየደምህን ማህተብ ሳልይዝ ለምባክን\nማስተዋል አድለኝ ባንተ ለምጨቅክን\nልቤን አንኳኳና ግባ ወደ ቤቴ\nእየሱስ ሰላሜ መድህኔ እረፍቴ\n\nበሀጢያት ስዳክር በአመፃ ስራ\nፊትህን ሳላፍር በቅዱሱ ስፍራ\nከደጅህ ብርቅም በሀጢያት ወድቄ\nበይቅርታ ምህረት ቆምኩኝ ከመውደቄ\n', 'am', 507, 0),\n(1, 'ይቅርታ', 'ይቅርታ\nይቅርታ ይቅርታ ልበልህ ይቅርታ\nኤሎሄ ኤሎሄ ልበልህ የኔ ጌታ\nእስካሁን አለሁኝ በፍቅርህ ዝምታ\nእስካሁን አለሁኝ በፍቅርህ ዝምታ\n\nአለፈኝ በከንቱ ዘመኔ በዋዛ\nበዚህ አለም ፍቅር ጌታዬ በምኞት ደንዝዛ\nጀንበሯ ዘቅዝቃ ቀኑ እየመሸ ነው\nአንቃኝ ሙሽራዬ ጌታዬ መቅረዜ ባዶ ነው\nኦ እግዚኦ ማረኝ አምላኬ\nእለምንሃለሁ ፊትህ ተንበርክኬ\n\nጥሪውን ሳልሰማ ጆሮዬን ደፍኜ\nለምጠፋው አለም ተሸነፍኩ በፍቅሯ መንኜ\nብዙ ዘመን ርቄ አምላኬ ጠፍቻለሁና\nከመንጋህ ቀላቅለኝ ይቅር በለኝና\nኦ እግዚኦ ማረኝ አምላኬ\nእለምንሃለሁ ፊትህ ተንበርክኬ\n\nስለክፉ ፈንታ ለልጅህ በጎን አድረገህ\nአጥብቄ ስሸሽህ ፈለከኝ አጥብቀህ\nየማይበርደው ፍቅርህ አባቴ ዛሬም ይሞቀኛል\nእንዲህ ያለወዳጅ አምላኬ ከወዴት ይገኛል\nኦ እግዚኦ ማረኝ አምላኬ\nእለምንሃለሁ ፊትህ ተንበርክኬ\n\nበትርህ ፍቅር ነው ልብን የሚመታ\nስበድልህ ለኖርኩት ቁጣህም ዝምታ\nአሁን ተቀበለኝ በፍቅርህ ማረከኸኛልና\nአባቴ ልበልህ ፍቀድልኝና\nኦ እግዚኦ ማረኝ አምላኬ\nእለምንሃለሁ ፊትህ ተንበርክኬ\n', 'am', 508, 0),\n(1, 'ሰው የለኝም ያለ በሰው የተረሳ', 'ሰው የለኝም ያለ በሰው የተረሳ\nየዳነው መፃጉ ያዳነውን ረሳ\n\nበአምስቱ እርከኖች በአዕማደ ምስጢራት\nቤተ ሳይዳ ላለች ከመቅደስ ላኖርካት\nበበደል ለምናዝ ምህረትን ፍለጋ\nበንስሐ ማረን ካራተ ዝንጋኤ ከሐጥያት አልጋ\n\nበጠበሉ ደጃፍ ለፀኑት የሚላክ\nለቅድሶተ ማይ የሚወርደው መላክ\nበመንገድ ጠብቆ ሞትን የሚያሳልፍ\nዛሬም ይድረስልን ቀድመው ከገቡት ጋር ነብሳችን እንድታርፍ\n\nአልጋው ተሸክሞት ደክሞ ለሚጨነቅ\nአልጋን አሸክመህ ህመም የምታርቅ\nደዌያችንን ነስተህ ቁስልን የምትፈውስ\nየመፃጉ እረዳት የነብሳት መጠጊያ መድሀኒት ክርስቶስ\n\nየባሰና ያየው ቃሉን ያልጠበቀ\nእጁን ሰዶ ጸፍቶ ከደዌው ታረቀ\nሰንበትን የሻረ ከሚሉት እንዳንውል\nለትንሳኤው ደስታ የሰንበትን ጌታ አርብን እንከተል\n', 'am', 509, 0),\n(1, 'አንዱ ስለሁላችን ሞተ', 'አንዱ ስለሁላችን ሞተ\nአንዱ ስለሁላችን ሞተ\nበሞቱ ሞታችን ተሻረ ቀረ\nክብር ሊያለብሰን ተራቆተ\n\nወደደን ያለልክ አየን በፍቅር\nራሱን አሳልፎ ሰጠ እስከ መቃብር\nምንአይነት ትህትና ነዉ ህሊናን ይገዛል\nስለሰዎች ፍቅር ተላልፎ ተሰጥቷል\nእንዲህ ያለ ፍቅር እንዲህ ያለ መዉደድ\nለማንም የለዉም ካንተ በቀር ወልድ\n\nበጅራፍ አለቀ ጀርባዉ በግራፋት\nአጥንቱ እስከታይ በክፉዎች ክፋት\nአየነዉ እርቃኑን በደም ተሸፍኖ\nማንም ያልሆነዉን ስለኛ ሆኖ\nእንዲህ ያለ ፍቅር እንዲህ ያለ መዉደድ\nለማንም የለዉም ካንተ በቀር ወልድ\n\nአለም ብትመርጥም በርባን ሽፍታዉን\nይሰቀል እያለች ብርሀኗን\nእሱ ግን በፍቃዱ ተሰቷል ለህማም\nከሰይጣን ማሰሪያ ሊፈታን ዘላለም\nእንዲህ ያለ ፍቅር እንዲህ ያለ መዉደድ\nለማንም የለዉም ካንተ በቀር ወልድ\n\nበምስሉም እንደሰዉ ስለኛ ተገኝቶ\nራሱን አዋረደ የማይሞተው ሞቶ\nታዘዘ ለህይወት ተነዳ ወደ ሞት\nዝምታን መረጠ በገዳዮቹ ፊት\nእንዲህ ያለ ፍቅር እንዲህ ያለ መዉደድ\nለማንም የለዉም ካንተ በቀር ወልድ\n', 'am', 510, 0),\n(1, 'የልብሱን ጫፍ ብነካው', 'የልብሱን ጫፍ ብነካው\nየልብሱን ጫፍ ብነካው\nአዳኝ ጌታዬን ብነካው\nቀጥ ይላል ደሜም አማናለሁ\nፈዋሼ እርሱ ብቻ ነው\n\nባለመድሀኒቶች አሉ ባሉኝ ስፍራ\nላልፈወስ ባዘንኩ ገንዘቤን ስዘራ\nአጣሁ ጥበበኛ የሚያውቅ ህመሜን\nአሁን ግን አየሁት ከርቀት አዳኜን\nአታቁሙኝ እኔን ልንካው መድሀኒቴን\nልቁም ተፈውሼ ቀሚሱን ዳስሼ\n\nአስራ ሁለት አመት ኖርኩኝ ተገልዬ\nእያነባሁ መረጥኩ ስደት ከገላዬ\nአሁን ከስሙ ጋር የሚቀላቅለኝ\nእየሱስ ክርስቶስ መድሃኒቴ ታየኝ\nአልፋለሁ ወደሱ ሰልፉን ሰባብሬ\nቀሚሱን ነክቼ እድናለው ዛሬ\n\nአስራ ሁለት አመት ደም ስለፈሰሰኝ\nመራመድ አቃተኝ አቅም እያነሰኝ\nአሁን ጌታዬን ሳይ ጉልበቴ በረታ\nተዘመናት ጭንቄን ህልሜን የሚፈታ\nአታቁሙኝ እኔን ልንካው መድሃኒቴን\nልቁም ተፈውሼ ቀሚሱን ዳስሼ\n\nጎበዝ የተባሉ ሰዎችን አልፌ\nቆምኩኝ እንደገና ስሙን ተደግፌ\nቀሚሱን ስነካው ደሜም ወድያው ቆመ\nሀይል ወቶኛል ብሎ ባርያውን አከመ\nሁሉ ቢፀየፈኝ እርሱ ግን አቀፈኝ\nበስስት እያየኝ በሰላም ሂጂ አለኝ\n', 'am', 511, 0),\n(1, 'እርዳኝ ዝም አትበል', 'እርዳኝ ዝም አትበል\nእርዳኝ ዝም አትበል የሠራዊት ጌታ\nተስፋ እንደሌለው ሰው ልቤ አያመንታ\nአንተን ለማገልገል የነበረኝ ብርታት\nዛሬስ ተስኖኛል አቅቶኛል መትጋት\n\nጨንቆኝ እጣራለሁ ጸጋ አጥታ ሕይወቴ\nእባክህ አርመኝ እርዳኝ መድኃኒቴ\nልቤ ድንጋይ ሆነ ቃልህ አልሰበረው\nየእጅህን ሥራ ጌታዬ አስተካክለው\n\nየክርስትናን ሕግ ሥርዓቱን አፍርሼ\nአለቅሳለሁ ጌታ በኃጢአት ተከስሼ\nሰላምና ፍቅር ነበር ክርስትና\nእኔ ግን ተናወጽኩ አልጸናሁም ገና\n\nሥራዬና ቃልህ አልገናኝ አሉኝ\nበጠማማው ልቤ አንተን አሳዘንኩኝ\nጽኑ መሠረት ነህ የሕይወት አለት\nሕይወት የሰጠኸኝ ደርሰህ እስከ ሞት\n\nበለመለመ መስክ በእረፍት ውሃ ዘንድ\nየምታሰማራ በጎችህን የምትወድ\nይቅር በለኝና እግዚአብሔር አምላኬ\nለሚያድነው ስምህ ልኑር ተንበርክኬ\n', 'am', 512, 0),\n(1, 'ቸር እሩሩህ', 'ቸር እሩሩህ\nቸር እሩሩህ ምህረትህ የበዛ\nመጠን በሌለው ፍቅር ስለሆንከኝ ቤዛ\nላመስግንህ እንጂ ምን እከፍልሀለው\nጌታ መድኃኒዓለም ሳመልክህ ኖራለው\n\nየልመናዬን ቃል ሰምተህኛልና\nአደግድጌ ፊትህ ልቁም ለምስጋና\nስንቱን አለፍኩ ባንተ ስምህን ጠርቼ\nመድኃኒዓለም ያዝከኝ እንዳልቀር ጠፍቼ\n\nብርሀንን አየው በእጆችህ ዳሰህኝ\nአልጋዬን ተሸከምኩ መዳኃኒትም ሆንከኝ\nመድኃኒዓለም ልበል ልጥራህ ደጋግሜ\nስለፈወስከኝ ነው የተፈታሁ ህልሜ\n\nበደሌን ደመሰስክ በደምህ ጠብታ\nዝቅ አልክልኝ ለኔ ልቶነኝ ከፍታ\nበፍቅርህ ካኖርከኝ ላትረሳኝ ዘላለም\nእያመሰገንኩኝ ዘመኔ ይፈፀም\n\nስምህ የነብስ ምግብ ላደበት ሲጠራ\nጠላት ልቡ ይርዳል ማዳንህ ሲወራ\nየሰጠህኝ ፀጋ ሀይልን አስታጥቆኛል\nጦር ሰይፍን ሳንመርጥ እያሪኮ ፈርሷል\n', 'am', 513, 0),\n(1, 'ዝም አይልም አምላክ', 'ዝም አይልም አምላክ\nዝም አይልም ጌታ\nበገሃድ ይመጣል በኃይል በችሎታ\nኃጥአንን በፍርዱ በቁጣው ሊቀጣ\nበቀኙ ለቆሙት ብርሃኑን ሊያወጣ\n\nሰማይና ምድር እንጂ\nቃሉ አያልፍም የሰው ልጅ\nእያየነው የሄደው ቃል\nዳግም ለፍርድ ይመለሳል\nዝም አይልም የኛ ጌታ\nበኃይል ይመጣል በችሎታ\n\nየሚናገር ሽንገላ ሀሰት\nዲዳ ይሆናል ከንቱ አንደበት\nበፍርዱ ቀን በፍጻሜ\nለንሰሀ የለም እድሜ\nዝም አይልም የኛ ጌታ\nበኃይል ይመጣል በችሎታ\n\nበቀኝ ያሉ ጻድቃን ሁሉ\nሃሌ ሉያ ስቡሕ ሲሉ\nኃጥአኑ ወደ ግራ\nይጣላሉ ለመከራ\nዝም አይልም የኛ ጌታ\nበኃይል ይመጣል በችሎታ\n\nጩኸት ሲሆን ታላቅ ለቅሶ\nየማይጠቅም ተመልሶ\nበሚያስፈራው በፍርዱ ቀን\nከሳት አውጣን ከሰቀቀን\nዝም አይልም የኛ ጌታ\nበኃይል ይመጣል በችሎታ\n', 'am', 515, 0),\n(1, 'ይለመነናል', 'ይለመነናል\nይለመነናል አምላክ አብርሐም\nይታደገናል መድኀኔዓለም\nለፍጥረት ሁሉ እጁን የዘረጋ\nቸር እረኛ ነው አልፋና ኦሜጋ\n\nአብርሐም ይሰሐቅን ያዕቆብን አስበህ\nየማልክላቸውን ቃለኪዳን አስታውሰህ\nደካማ ለሆነው ሥጋ ስልጥኖብን\nአትመለስ ጌታ የምህረት ዓይንህን\nከሰማያት ሰማይ ይድረስ ጩኸታችን\nእንዘን እናልቅስ ስለ በደላችን\n\nባይመለከተን አምላከ አብርሐም\nበምሕረት ዓይኖቹ መድሃኔዓለም\nባይዘረጋልን አምላከ አብርሐም\nየፍቅር እጆቹን መድኃኔዓለም\nሕዝበ እሰራኤል ሁሉ ለአምላክ ዘምሩ\nአደኖናልና በሚያስደንቅ ፍቅሩ\n\nምንም እንኳን ክህደት ቅጥፈት ቢበረታ\nስለ አብርሐም ብለህ አልተወከንም ጌታ\nለቅዱሳን ያለህ ቃል ኪዳን ሲጸና\nቀስተ ደመናህን አይተነዋልና\nየእሰራኤል አምላክ የማታንቀላፋ\nበፍቅርህ ታደገን በሞት ሳንጠፋ\n\nቃልዳኑ ግሩም አምላከ አብርሐም\nምሕረቱ የበዛ መድኃኔዓለም\nርስት ጉልታችን አምላከ አብርሐም\nየህይወታችን ቤዛ መድኃኔዓለም\nሳይጸየፍ ጌታ ያደፈ ኃጢአቴን\nከማጥ ውስጥ አወጣኝ ታደጋት ሕይወቴን\n', 'am', 516, 0),\n(1, 'ያከብርዋ ለሰንበት', 'ያከብርዋ ለሰንበት\nያከብርዋ ለሰንበት መላእክት\nበሰማያት ጻድቃን በውሰተ ገነት\nወኲሉ ፍጥረት አሣት ወአናብርት\nእለ ውሰተ ደይን ያዕረፉ ባቲ\nእስመ ባቲ አዕረፈ እምኲሉ ግብሩ\n\nያከብሯታል ሰንበትን\nመላእክት በሰማያት ጻድቃን በገነት\nፍጥረታት በሙሉ አሳዎች እና አንበሪዎች\nበመቃብር ያሉ ያከብሯታል\nአምላክ በእርሷ እንዳረፈ ከሥራ ኹሉ\n\nሰማይና ምድር ቀላያት አብርህት\nሰውና እንስሳ ቅዱሳን መላዕክት\nፈጥሮ ያረፈበትን ቅዱሱን ሰንበትን\nሁላችንም እናክብር ሆነን በአንድነት\n\nአንዱን ቀን እረፍ ስድስቱን ቀን ስራና\nአምላክህን አክብር አብዛለት ምስጋና\nለስጋዊ ደስታ ለማይጠቅም ትርፍ\nህጉን አትጣስ ሰንበትን ዕረፍ\n\nበያሬድ ዝማሬ በዳዊት በገና\nበዕዝራ መሰንቆ በታላቅ ምስጋና\nጭንቁን አውጁለት አለም እንዲሰማ\nሰንበትን በማክበር ደስ በሚል ዜማ\n', 'am', 519, 0),\n(1, 'በኢየሩሳሌም በበጎች በር', 'በኢየሩሳሌም በበጎች በር\nበኢየሩሳሌም በበጎች በር\nበቤተሳይዳ እኖር ነበር\nማን ያድነኛል እያልኩኝ\nአልጋህን ይዘክ ሂድ አለኝ\nማን ያድነኛል እያልኩኝ\nአምላኬ መቶ ፈወሰኝ\n\nበአልጋ ላይ ከዋልኩ ሰንብቻለው\nሰውነቴ አልቆ መንምኝለሁ\nውሃውን ሲያማታው ቅዳሜ\nቀድመውኝ ዳኑ እኔ ቆሜ\nአይዞህ የሚለኝ የሚያጽናናኝ\nደጋፉም የለኝ ብቸኛ ነኝ\n\nሰላሳ ስምንት አመት ሙሉ\nተሳለቁብኝ መፃጉ እያሉ\nእዘንልኝ አድነኝ\nሙሉ ጤነኛ አድርገኝ\n\nልትድን ትወዳለህ ሲለኝ\nእውነት እውነትም አልመሰለኝ\nአዎን እወዳለው ስለው ጌታ\nፈወሰኝ አምላክ የኔ አለኝታ\n\nስማኝ አምላኬ እጮሃለው\nኅጢአቴ በዝቶ አለቅሳለውሁ\nበመብል ጠፍቷል ልጅነቴ\nባርያህ አድርገኝ ውድ አባቴ\n\nእንደ እኔ ታማሚ የሆናችሁ\nአምላኬ ጌታ ያድናችሁ\nእንደ እኔ ድዊ የሆናችሁ\nየጌታዬ እናት ታማልዳችሁ\n', 'am', 520, 0),\n(1, 'በከመ ምህረትከ', 'በከመ ምህረትከ\nከአስሩ አንዱ ድንገት ቢጠፋባት\nድሪሟን ፍለጋ ሴቲቱ ተነሳች\nቤቷን ስታፀዳ አብርታ መብራቷን\nከቆሻሻ መሃል አየችው ድሪሟን\nያድሪም እኔ ነኝ በቃልህ ማልገኝ\nበቤትህ ውስጥ ሆኜ በቤትህ ማታውቀኝ\nከቆሻሻ መሃል ከምታገኛቸው\nአገልጋዮች መሃል እኔነኝ ዋነኛው\n\nበከመ ምህረትከ አምላክነ ወአኮ በከመ አበሳነ\n\nየሰበከውን ቃል በህይወቱ ነዋሪ\nየጠፋው ርሱ ነው ሞልቷል ተናጋሪ\nበክፉ ስራዬ በኔ ተነቅፈሃል\nየስም ብቻ አገልጋይ መች ያስደስትሃል\nቅርብ ነው አንደበቴ ልቤ ግን የሸሸ\nማንነቴ ባዶ በቃልህ ያልታሸ\nዛሬ አስተካክለኝ ልታነፅ በቃልህ\nበእኔ አይሰደቡ ቅን አገልጋዮችህ\n\nሀገሪቱ ረስታ መጎብኘቷ ወራት\nእንባህን አፍስሰህ ለሷ አለቀስክላት\nዛሬ ብትመጣ በልቤ ከተማ\nአዝነህ ታለቅሳለህ በእኔ ምግባርማ\nበመቅደስህ መሃል ድፍረቴ የበዛ\nልቤ ለአለም እንጂ ለአንተ ያልተገዛ\nየስም ብቻ አገልጋይ መሆኔን ታውቃለህ\nድሮስ ከእኔ አይነቱ ምንስ ታገኛለህ\n\nየቃኤል መሠዋዕት ከመቅደስህ ገብቶ አንድነት ተረስቶ ሁሉ ተለያይቶ\nእንክርዳዱን መሠዋዕት ቁራ በትኖታል\nፍቅር አልባ መሠዋዕት መች ያስደስተሃል\nይቁም በመቅደስህ መሸጥ መለወጡ\nአፊንና ፊንሃስ ከመቅደስህ ይውጡ\nሳሙኤልን መሠል ቅን አገልጋዮችህ\nበመቅደስህ ይብዙ ተናገር ይበሉህ\n', 'am', 521, 0),\n(1, 'ቅድስት', 'ቅድስት\nጾምን ቀድሱ ለንስሐ ቅኑ\nጉባኤን አውጁ አምላክን ለምኑ\n\nየሥራዎች ሁሉ መጀመሪያ ናት\nመንፈሳዊት ዓመት የጸሎትም እናት\nመጽሐፍ እንዳዘዘ ክርስቲያኖች ስሙ\nየአርምሞን እህት ጾምን አስቀድሙ\n\nድልድይ መሻገሪያ ወደ ርስት አገር\nየፍቅር መግለጫ የትሕትና መምህር\nየዕንባ መለኪያ የነፍስ ሐሴት ጌጧ\nትሩፋት በጎ ግብር ይኖራሉ ውስጧ\n\nሥጋችንን ለነፍስ የምናስገዛባት\nቅዱሳንን በግብር የምንመስልባት\nየነፍሳችን ምግብ ምክንያት ለጽሙና\nለሥብረተ ክሳድ ለቅጥነተ ህሊና\n\nጾም እንዲሁም ጸሎት የክርስቲያን ትጥቁ\nብርቅ አይሆንበትም ዓለም ማሸብረቁ\nክርስቶስ ድል አርጎ ድል አድርጉ አለን\nበጾም እና ጸሎት አርዓያ ሆነልን\n', 'am', 522, 0),\n(1, 'ተስፋ ያልቆረጥኩት', 'ተስፋ ያልቆረጥኩት\nተስፋ ያልቆረጥኩት ጌታዬ በአንተ ነው\nአምናለሁ በእኔ ላይ ማዳንህ ድንቅ ነው\nእተማመናለሁ እንደማትተወኝ\nሰው የለኝም ላልኩት ድጋፍ ጉልበት ሁነኝ\nሰው የለኝም ላልኩት አንተው ተስፋ ሁነኝ\n\nብዙ ቁስል አለ ለሰው የማልነግረው\nበሀዘን የሞላኝ ልቤን የሰበረው\nአለኝ የማወራው ከአንተ ጋራ ብቻ\nበውስጤ ያኖርኩት በሰዎች ፍራቻ\n\nይዘብትብኛል ችግሬን የሰማ\nይሳለቃል ሲያየኝ ቆሜ በጨለማ\nአምላኩ የት አለ እንዳይሉ አድነኝ\nነፍሴን ተስፋ ሙላት የጠፋሁ ልጅህ ነኝ\n\nመድረሻ የሌለው ከንቱ መጻተኛ\nወገን ዘመድ ያጣ ሆኖ ስደተኛ\nተስፋ የሚያደርግህ አንተን ብቻ እኮ ነው\nምስካየ ኅዙናን ስደት የቀመስከው\n\nየዳዊት ልጅ ማረኝ በሀዘን ልቤ ደምቷል\nዝም በል የሚለኝ ሰው በመንገዱ ሞልቷል\nሕዝቡን ገለል አርገህ ናልኝ የእኔ ጌታ\nተስፋ እንደሌለው ሰው እንዳልንገላታ\n', 'am', 523, 0),\n(1, 'ስንት ቀን ፈጀብህ', 'ስንት ቀን ፈጀብህ\nለአዳም ኪዳን ሰጠህ\nእንደምትወለድ ወደ ምድር ወርደህ\nእንዴት ነበር ያኔ..?\nወደ እኛ ስትመጣ መላእክትን ትተህ?\n\nየሔዋን እርግማን\nየባሏም የውርስ ኃጢአት መዘገን\nእንዲያ አሳሰበህና\nመጣህልን ሁሉን አደረግህ በፅሙና\n\nእንዴት ነበር ያኔ..?\nያችን ንጹሕ ለመፈለግ የወሰደብህ ጊዜ\nአድርገህ የሰጠኸንን ፈውስ በበድልን ጊዜ\nግን ምን ያህል ነው ልፋትህ?\nድንግልን ስትፈልግ የፈጀብህ?\n\nከሰማያት ስትወርድ አጀቡህ መላእክት?\nዓለሙስ ተናወፀ በይባቤ በስብሐት?\nያ ምቀኛ ዲያቢሎስ ግን ምን አለ?\nወደ እኛ ስትመጣ አለ አይደል ኮበለለ?\nነው ሥጋ ለብሶ ጉድ ሠራኝ አለ?\n\nእንዴት ነው እርቀቱ\nየሰማይ ምጥቀቱ\nየምድርስ ሥፋት\nከሷ እስክታርፍባት?\nግን ጌታ...?ሰማያት ምን አሉ\nትትሀቸው መጠህ ባንተ አጉረመረሙ?\nፍጥረታትስ ቢሆን ማሕሌት አቆሙ?\n\nምሥጢረኛው ጌታ\nመንገድህ በየት ነው ወደ እኛ ስትመጣ?\nቤተ ልሔም ስትደርስ\nማን አገለገልህ?ምን አለች ምድሪቱስ\nእያቄም ወሐናን እንዴት መረጥሃቸው\nአንተ እንድትወለድ ምክንያትህ ናቸው\n\nሰማዩ ሰፊ ነው\nምድርንም ታውቃለህ\nእንዴት እንድትሰፋ ሆና መረገጫህ\nግን እና ጌታ ሆይ ምኑ ነው የቻለህ?\nየድንግል ማሕጸን እሳት መሸከሙ\nምድርም መልኮት በእሷ ላይ መቆሙ\n\nእንዴት ነበር ያኔ\nበቤተ ልሔም ውስጥ\nአንተን የሚያሞቅ ከእንስሶች ስትሰጥ?\n\nዮሴፍ ምን አለ\nአንተን በማየቱ እርጅናው ታጎለ?\nአንተን የጠበቀህ አዳምስ በግርማህ ምን አለ?\n\nእንዴት ነው ስጦታው\nየሰብአ ሰገሉ ወርቅ እጣን አምኃው\nየእረኞቹ ደስታ\nየመላእክት ብሥራት የልደትህማታ\n\nእንዴት ነበር ያኔ\nየልደትህ ማታ\nየዝማሬው ለታ\nየእናትህ ደስታ\nየፍጥረት እልልታ\nሚዳቋ ስትዘል ከኢትዮጵያ አይታ\nግን ጌታ እረቂቁ አምላክ\nበየትስ መጠህ ነው ከኛ የተወለድክ\n', 'am', 525, 0),\n(1, 'እግዚአብሔር ይመስገን እላለሁ ዘወትር', 'እግዚአብሔር ይመስገን እላለሁ ዘወትር\nእግዚአብሔር ይመስገን እላለሁ ዘወትር\nሲከፋም ስደስት ሳለው በዚ ምድር\n\nየዚህ ዓለም ደስታ እንከን የሞላበት\nስከፋ ይከስማል ይበዛል ስደሰት\nየአምላኬ ፍቅር ግን ዘወትር አንድ ነው\nየቀን መለዋወጥ እርሱን አይቀይረው\n\nእኔ የአንተ ልሁን ሁሉም አለኝ እና\nአፅናኝ በማደሪያህ ልኑር በምስጋና\nበእቅፍህ መኖሬ ማትረፊያ ሆኖኛል\nባዶ ቢሆን እጄ ፀጋህ ይበቃኛል\n\nበረከቴ አንተ ነህ አጣው ብዬ አላዝንም\nበማድጋው መጉደል እኔ ተስፋ አልቆርጥም\nንፋሳት ባይነፍሱ ባላይም ደመና\nዝናብ ትሰጣለህ ቸር አባትህ ነህና\n\nስምህን ዘወትር በእምነት እጠራለሁ\nበዘመኔ ሁሉ ስትረዳኝ ስላየሁ\nአዘኔን አፅናንቶ ልቤን ያበረታው\nየቅዱሳን አምላክ ምስጋና ይድረሰው\n', 'am', 526, 0),\n(1, 'ሞተሃልና ስለኔ', 'ሞተሃልና ስለኔ\nሞተሃልና ስለኔ ምንም ሳይኖርብህ ጥፋት\nተከሰህ ተወቅሰህ በጲላጦስ ፊት\nኢየሱስ አምላከ ምህረት ስብሐት ለከ\n\nያንተን መንገላታት ሁል ግዜ ያሳዝነኛል ሲወራ\nበመስቀል ላይ ሆነህ ያየከው መከራ\nኢየሱስ የህይወት እንጀራ ስብሐት ለከ\n\nስላላወቁህ አንተን የአለም መድሃኒት መሆንክን\nመቱት በጭካኔ ብርሃን ፊትህን\nአፌዙብህ ጌታችንን ስብሐት ለከ\n\nይቻለው ነበር ማጥፋት ክፉ አድራጊዎችን ያንዕለት\nግን እሱ ለእነርሱ ለመነ ድህነትን\nኢየሱስ አምላከ ምህረት ስብሐት ለከ\n\nመሃሪ ጌታ አሁንም እንደቸርነትህ ብዛት\nየእኛን በደል ሁሉ ሳትመለከት\nአድነን ከዳግም ሞት ስብሐት ለከ\n\nበደምህ አድነን እኛን ከክፉ መከራ አውጣን\nኃጥያታችንን አስተሰርይልን\nኢየሱስ መድሃኒታችን ስብሐት ለከ\n', 'am', 527, 0),\n(1, 'የአብርሃም አምላክ', 'የአብርሃም አምላክ\nየአብርሃም አምላክ የይስሐቅም ቤዛ\nወገኖቹን ሁሉ በራሱ ደም ገዛ\n\nየሐስት ምስክር አቁመው ከሰሱት\nበሞት እንዲቀጣ ሁሉም ፈረዱበት\n\nጲላጦስ ገረፈው በሰንሰለት አስሮ\nከሮማዊው መንግሥት እንዲኖር ተፋቅሮ\n\nድንግል አልቻለችም እንባዋን ልትገታ\nእያየች በመስቀል ልጇ ሲንገላታ\n\nበብርሃን ዙፋን ላይ የቆሙት እግሮቹ\nበችንካር ላይ ቆመው ምንም ሳይሰለቹ\n\nየብርሃን አክሊልን ለሰማእት ያደለ\nየሾክ አክሊል ደፍቶ ቀራንዮ ዋለ\n', 'am', 528, 0),\n(1, 'እንዴት ወጣሁ ብዬ', 'እንዴት ወጣሁ ብዬ\nእንዴት ወጣሁ ብዬ ከቶ አልደነቅም\nአምንሀለሁና ትተኸኝ አታውቅም\nያ ሁሉም አለፈ ቀረ ወደ ኋላ\nማልቀስ ማንባት ይብቃኝ ከእንግዲ በኋላ።\n\nከእንግዲህ አይመጣም ያ ቀን ተመልሶ\nላያዳግም ሄዷል እንባዬን አፍስሶ\nበመስቀል ላይ ሆነህ ችንካርህ ታይቶኛል\nያ ሁሉ መከራ በአንተ አልፎልኛል።\n\nእንደምን ተነሣ አልዓዛር አትበሉ\nይችላል እግዚአብሔር ይችላል ኃያሉ\nታሪክ ሆኖ አልፏል ያኔ ያስጨነቀን\nስንቱን ተሻግረናል ጌታ እየጠበቀን።\n\nከዓሣ አንበሪው መዳፍ ከጥልቁ ወጥቼ\nዘምርለታለሁ ዳግም ተሠርቼ\nየሽቱዬን ብልቃጥ ሰበርኩት በፊቱ\nበጽድቅ እንዲያስበኝ ጌታ በምሕረቱ።\n\nቁስሌን ቆሰልክልኝ ጥሜንም ተጠማህ\nመቼ ገባኝና የመስቀሉ አላማ\nለካስ ስለፍቅር የማይሆኑት የለም\nአሳየኸኝ ጌታ ታላቅ ነህ ዘለዓለም።\n', 'am', 529, 0),\n(1, 'አርማጌዶን ነው ዘመኑ', 'አርማጌዶን ነው ዘመኑ\nአርማጌዶን ነው ዘመኑ\nየጌታ መምጫ ደረሰ ቀኑ\nምልክቱደው ተፈጽሟል\nፍቅር ቀዝቅዞ ሰላም ጠፍቷል\n\nበቤተ-መቅደስ ውስጥ ያላቹ\nበበረሀ አለ ጌታ ቢሏቹ\nእንዳት ወጡ ሀሰት ነዉ\nክርስቶስ እየሱስ እዚነዉ\n\nብዙ ታምራት ያሳያሉ\nየበግ ለምድ ለብሰው ይታያሉ\nተኩላወች ናቸው ውስጣቸው\nትንቢት ይፈፀም ግድ ነው\n\nሰባኪው ያኔ አስተውል\nጌታ ተናግሮል በወንጌል\nመንፈስን ሁሉ አትመኑ\nመመራመር ከቶም ማስተማር\n\nፀሀይ ጨብጦ ቢያሳያችሁ\nጨረቃን ይዞ ቢታያቹ\nለፌ ወለፌ አትበሉ\nእመኑ በሱ በሀይማኖት ኑሩ\n', 'am', 530, 0),\n(1, 'ሐጥያት በደሌን ትቼ', 'ሐጥያት በደሌን ትቼ\nሐጥያት በደሌን ትቼ\nበፍቅር ወደርሱ መጥቼ\nበእንባዬ እግሮቹን ባጠብኩት\nብቻ ጌታዬን በካስኩት\n\nነፍሴን እያሳደፍኩ በበደል ስኖር\nለካ ሳፈርስ ነበር ሕንፃ እግዚአብሔር\nአሁን ግን አንጽድቶኝ በልቤ በገባ\nእሰዋለታለሁ የእንባዬን መባ\n\nድካሜን ሳይቆጥር ጌታዬ ከጠራኝ\nወደኋላ አላይም ከእንግዲህ ምን አለኝ\nመቅጫዬን ትቼ እከተለዋለሁ\nከእርሱ ጋራ ውዬ ከእርሱ ጋር አድራለሁ\n\nምሬሀለሁ ብሎ ካበዛልኝ ፀጋ\nእለዋለሁ ቅዱስ ሲመሽም ሲነጋ\nፍቅሩ በልቤላይ ስሙ በአንደበቴ\nዘወትር አይጠፋም እርሱ ነው ጉልበቴ\n\nልጄ ብሎ ጠራኝ እጆቹን ዘርግቶ\nእርሱን ማሳዘኔን በደሌን እረስቶ\nበፍታን አለበሰኝ ፍሪዳን አረደ\nየፈጠረኝ ጌታ መዳኔን ወደደ\n', 'am', 531, 0),\n(1, 'ኑ በእግዚአብሔር ደስ ይበለን', 'ኑ በእግዚአብሔር ደስ ይበለን\nኑ በእግዚአብሔር ደስ ይበለን\nለታላቁ ክብር ለዚህ ያበቃን\nከሞት ወደ ህይወት ላሸጋገረን\n\nየሰማዩን መንግስት እርስቱን ለሰጠን\nከጨለማው አውጡቶ ብርሃን ያሳየን\nለዚህ ድንቅ ውለታ ምስጋና ያንሰዋል\nበእርሱ ደስ ይበለን ክብር ይገባዋል\n\nከአለት የፈለቀ ውሃ ጠጥተናል\nሰማያዊ መና አምላክ መግቦናል\nፍቅር የበዛ ነው ምን ልክፈል ጌታ\nስምህን ላመስግነው ከጥዋት እስከ ማታ\n\nበቃዲስ በረሃ ምንም በሌለበት\nበኤርትራ ባሕር ወጀብ የበዛበት\nለእርሱ መንገድ ዓለው ከቶ ምንተስኖት\nልባቹ አይፍራ በፍጹም እመኑት\n\nበባርነት ሳለን በድቅድቅ ዓለም\nብርሃንን አገኘን በድንግል ማርያም\nያጣነው ሰላም ዛሬ አገኘን\nእጅግ ደስ ይበለን በእመቤታችን\n\nየሃናና የእያቄብ የእምነታቸው ፍሬ\nበእግዚአብሔር ፍቃድ ተወለደች ዛሬ\nየእያቄብ ስለቱ የሃና እምነት\nለምኝልን ለኛም ኪዳነምህረት\n', 'am', 532, 0),\n(1, 'እውነተኛ ሰላም', 'እውነተኛ ሰላም\nእውነተኛ ሰላም ያለው ከቤትህ ነው\nእርዳኝ አልናወጽ እለምንሀለሁ\n\nሀጢያቴን ሳስበው ልቤ ይጨነቃል\nከአንተ መለየቴ ነፍሴን አድክሟታል\nወደ አንተ መልሰኝ እኔ እመለሳለው\nእውነተኛ ሰላም ያለው ከቤትህ ነው\n\nለቅዳሴ ፆሎት ዘውትር እንዳልተጋሁ\nበአደባባይ ቆሜ ስምህን እንዳልጠራሁ\nተሰነካክዬ ወድቄ አለሁና\nእርዳኝ አማኑኤል በሀይማኖት ልፅና\n\nአይኔ እንባን ያምንጭ ላልቅስ ስለ ሀጢያቴ\nየንስሀ ትሁን ቀሪዋ ህይወቴ\nበመዳኔ ሰአት በዛሬዋ ለት\nፍቅርህን አስቤ መጣሁ ከአንተ ፊት\nጌታ ሆይ ፀፀቴን እንባዬን ተቀበል\nአባትሽ ነኝ በለኝ እኔም ልጅ ነኝ ልበል\nዘይት ሳላዘጋጅ ድንገት መተህብኝ\nበርህን በመዝጋት ከደጅ አታስቀረኝ\n', 'am', 533, 0),\n(1, 'ጌታዬ መታመኛዬ', 'ጌታዬ መታመኛዬ\nጌታዬ መታመኛዬ ጌታዬ\n\nያስጨናቂዎቼን አይቶ ፉከራ\nበሞት እንዳልተኛ ዓይኖቼን አበራ\nኧረ እሱስ መድኃኒቴ ነው ኧረ እሱስ\nኢየሱስ መድኃኒቴ ነው ኢየሱስ\nምን ልክፈለው ምንን ልስጠው ውለታው ከአዕምሮ በላይ ነው\n\nከኃያላን መሃል ኃያል አደረገኝ\nከብርቱዎች መሃል ብርታት አስታጠቀኝ\nከአሸናፊዎች ሁሉ በላይ አደረገኝ\nየጠላቴን አንገት ጌታ አስረገጠኝ\n\nበሞት ጥላ ብሄድ ክፉን አልፈራም\nከእኔ ጋራ ያለው ለጠላቴ አይራራም\nስጠራው ፈጥኖ እየመጣ\nከፊቴ ቀድሞ እየወጣ\nእርሱ በእኔ በእርሱ አይረታም\nጠላቶቼን ሁሉ አሳፍሯል\n', 'am', 534, 0),\n(1, 'አቤቱ እንማልዳለን', ' አቤቱ እንማልዳለን\nበአንድነት ፀንተን እንኖር ዘንድ\nአቤቱ እንማልዳለን\nበሃይማኖት ተግተን እንቆም ዘንድ\nአቤቱ እንጸልያለን\n\nበመከራ ትዕግስት ፍጻሜ እንዲሰጠን\nከቅዱሳኑ ጋር በገነት ያኑረን\nእርሱን ደስ ካሰኙ ከቅዱሳን ጋራ\nበቅን አገልግሎት ምግባር እንድንሰራ\nአቤቱ እንማልዳለን\n\nአዝ፦\nስለ ዲያቆናቱ ስለ ቀሳውስቱ\nእንጸልያለን ስለ ጳጳሳቱ\nያለ ነውር ሆነው ፍጹም ንፅህና\nምግባር እንዲደረጅ እምነት እንዲጸና\nአቤቱ እንማልዳለን\n\nአዝ፦\nኢትዮጵያን ጠብቃት ከረሃብ ጦርነት\nገበሬውም እንዲያርስ በብዙ በረከት\nረዳት የሚጦር ድጋፍ ለሌላቸው\nእንማልዳለን ባልቴት ሽማግሌው\nአቤቱ እንማልዳለን\n\nአዝ፦\nየዕለት ምግባችንን አምላክ እንዲሰጠን\nስለ ረሃብተኞች እንጠራሃለን\nበግፍ ለታሰሩ ለሚያዝኑ ምስኪናን\nዘወትር ሳንታክት እንማልድሃለን\nአቤቱ እንጸልያለን\n\nአዝ፦\nስለ ተሰደዱ በባህር በረሃ\nከማይገኝበት ምግብና ውሃ\nበምርኮ በስቃይ ለሚንገላቱቱ\nእንማልድሃለን አምላክ ሆይ በብርቱ\nአቤቱ አንጸልያለን\n\nአዝ፦\nስለ ድውያኑ ለታመሙ ሰዎች\nቤተ ክርስቲያንም ትማልድሃለች\nስለ ዝናብና ስለ ውሃ ሙላት\nበልክ እንዲያደርገው ንፋሱን በእውነት\nአቤቱ እንማልዳለን\n', 'am', 535, 0),\n(1, 'ክንድህን እጠፍ', 'ክንድህን እጠፍ\nክንድህን እጠፍ የሚልህ ማን ነው\nማዳንህን ተው የሚልህ ማን ነው\nቢከፋቸውም አሳዳጆቼ\nእስካሁን አለው በአንተ ጸንቼ (2)\n\nማለፌ ሲቀር ህይወት ሲመላ\nሲያልፍ ከላዬ የሞቴ ጥላ\nለምን አዘኑ ሰዶቃውያኑ\nስለከፋቸው ላይቀር ማዳኑ\n\nአዝ፦\nበባህሩ ዳር ህመሜን ትቼ\nአልጋዬን ባዝል ድኜ በርትቼ\nበሰንበት ዳነ ማረው ብላችሁ\nያዳነህ ይሙት ለምን አላችሁ\n\nአዝ፦\nስምዖን ዞር በል ይከፈት በሩ\nይብቃኝ ሲምረኝ ማንጎራጎሩ\nኃጢአቴን ፈቅዶ ጌታ ከተወው\nምንህ ተጎዳ በእንባዬ ባጥበው\n\nአዝ፦\nበግንባሬ ላይ ዓይኔን ቢሰራ\nቢደባልቀኝ ከሚያዩት ጋራ\nፊታቸው በሀዘን ለምን ጠቆረ\nሁሉኑ ቻይ ጌታ ስለከበረ\n\nአዝ፦\nአትዝጉት ደጁን እንመላለስ\nየተወደደው በእኛ ላይ ይንገስ\nየምናቀርበው ለጌትነቱ\nየከበረውን ይዘናል ሽቱ\n', 'am', 536, 0),\n(1, 'ትላንትናን ድልድይ', 'ትላንትናን ድልድይ\nትላንትናን ድልድይ ሆነህ ካሳለፍከን\nዛሬን ተቀብለህ በሰላም ካዎልከን\nስለምታሳየን ነገንም በተስፋ\nተመስገን እንበልህ አምላክ ክብርህ ይስፉ\n\nሰላምና ደስታ ወይ ሀዘን ፈተና\nትላንት ታሪክ ሆኖ ይኸው አልፏልና\nያለፈው ቀን አለፎ ዛሬ ደርሷልና\nተመስገን ጌታችን ስለ ትላንትና\n\nዛሬን የሰጠኸን ፍሬ እንድናፈራ\nበእርሻ ውስጥ አቁመን ጌታ ሆይ አደራ\nየእጆቻችን መቅረዝ ዘይት እንዳይጎድለው\nለታካች ልባችን ትጋት አስተምረው\n\nነገን እናያለን በተስፋ ተሞልተን\nእንቅፋቱን ልናልፍ በአንተ ተመርኩዘን\nተስፋን የተመላ ነገ አለ ፊታችን\nእንበረታለን ዛሬ በሩጫችን\n', 'am', 537, 0),\n(1, 'አንተን ፈልጌ መጣሁ', 'አንተን ፈልጌ መጣሁ\nአንተን ፈልጌ መጣሁ\nእደጅ አታውጣኝ የእኔ ጌታ\nአንተን ፈልጌ መጣሁ\n\nቅዱሣን በቤትህ በፍቅር ቢኖሩ\nበሥጋ እና በነፍስ በሥምህ ከበሩ\nበቤትህ ተተክለው ለምልመው ጸደቁ\nበትሩፋት በዕምነት ለመንግሥትህ በቁ\n\nእኔም የአንተ ባርያ ሽቼ ቅድስና\nበቤትህ መጽደቅን እለምናለሁና\nዕንባ እና ጸሎቴን ቃሌን ተቀብለህ\nከቤትህ አታውጣኝ በበረከት ተክለህ\nፍቅርህም ተገልጧል ዕርቦ በቤቴ\nአንተን ስለ ያዝሁኝ ሠምራለች ሕይወቴ\nእንደ ምትወደኝ ዛሬም አውቀዋለሁ\nበረከት በእጄ ሞልቶ እያየሁ ነው\n\nበቤትህ ውስጥ ካለው ታላቁን ድግሥ\nዕለት ዕለት በዕምነት ኑሬ እንድቋደሥ\nበሔጾጵም እርጨኝ እነጻማለሁ\nእኔ እንደ በረዶ ሁኜ እቀርባለሁ\n', 'am', 538, 0),\n(1, 'የቅዱሳን በአት', 'የቅዱሳን በአት\nልቦናን የሚመስጥ መአዛ እጣኗ\nህሊናን ይገዛል ዝማሬ ድጓ\n\nየቅዱሳን በአት የፀሎት ዋሻቸው\nቤተክርስትያን ናት አንባ መጠጊያቸው\n\nየመላክ ዝማሬ የአእዋፍ ዝማሬ\nየሚለቀምባት የትሩፋት ፍሬ\n\nይዘምሩባታል ባንድነት ተግባብተው\nየሌዋዊ በትር ፅናፅን ከበሮ\n\nወልዳዋን አለም የናቋት በቅድሚያ\nየእምነት አርበኞች ያገኟት በፍልሚያ\n\nየገድላቸው ታምር መቦቅበቂያ መቅረዝ\nየሰማታት አክሊል የስራቸው ደሞዝ\n\nመውደቂያዬ ይሁን ከመቃብራቸው\nይፈውሳል እና ተረፈ አፅማቸው\n\nከሀጥያት ድንኳን መውጣቴ ነው ዛሬ\nየቅዱሳን በአት ልትሆነው ሀገሬ\n', 'am', 539, 0),\n(1, 'ተጠማችህ ነፍሴ', 'ተጠማችህ ነፍሴ\nተጠማችህ ነፍሴ ናፍቃህ እንደዋላ\nየለንም ዋስትና መድህን ካንተ ሌላ\nየሕይወት ውሃዬ ፍሰስ በልቤ ላይ\nኢየሱስ ድምጽህን አሰማን ከሰማይ\n\nከበዛው እንጀራ ከገበታው በላይ\nበዓሳ ከሞላው ከመረቡ ሲሳይ\nአንተህ ነህ እርሃቤ የነፍሴ ፍሪዳ\nበጽድቅ የሸለምከኝ ለብሰህ ከለሜዳ\n\nዙፋን ክብር ይወድቃል ይሰበራል ደርቡ\nየዚህ አለም ደስታ ለቅሶ ነው ወደቡ\nየልቤ መቃተት ከአንተ ጋር መኖር ነው\nበሰማዩ ቤቴ በደም በሰራህው\n\nሁሉንም አጥቼ አንድ አንተን ላገኝህ\nዋናዬ ነህና ብዙ ማተርፍብህ\nካንተ ተለይቼ ከምራመድ ቆሜ\nእነሳለሁ ብሞት ስምክን ተሸክሜ\n\nየእሾህ ዘውድ የደፋ የፍቅር ንጉሴ\nየአገልግሎቴ ራስ ሽልማት ሞገሴ\nአሜን ጌታ ኢየሱስ ናልኝ እልሃለሁ\nገና በሰማያት እዘምርልሃለሁ\n', 'am', 540, 0),\n(1, 'አጥቷል ጎድሎበታል', 'አጥቷል ጎድሎበታል\nአጥቷል ጎድሎበታል ብለህ ሳትንቀኝ\nለዚህ ያደረስከኝ ጌታዬ እኔ ማን ነኝ\nይሞላል አይቀርም ባንተ ሸለቆዬ\nጠብቃለሁና ቀንህን ጌታዬ\n\nሃዘን ጽልመት ክፉ ዘመን ቢገጥመኝም እንኳ\nያልፋል ሁሉም ታሪክ ሆኖ በፊትህ ሲለካ\nማን አፈረ ማን ጎደለ አንተን የጠበቀ\nጸና ልቤ በእግዚአብሔር ይህን እያወቀ\n\nበዓለም ስፍራ ባይኖረኝም ብሆንም ጎስቋላ\nአምላኬ ሆይ ካንተ በቀር አልሄድ ወደ ሌላ\nጌታዬ ሆይ በፍለጋህ ወጣሁ ከመቃብር\nስመሰክር እኖራለሁ ሥራህን ስናገር\n\nቀን ለክተህ ጊዜን አይተህ ሰውን የማትከዳ\nያለወረት ትመጣለህ እኔን ልትረዳ\nከነ ኤልያብ ወንድሞቼ ባልስተካከልም\nማማ ሆነህ ከፍ አረከኝ አንተ ሰው አትጥልም\n\nእንደ እናት ልጅ እንዳልቆጥርህ ከዚም ትበልጣለህ\nካንተ በቀር ያፈቀረኝ በምድር ስለሌለ\nስለ ሥምህ መነቀፌ ክብሬ ነው ማዕረጌ\nበምን መንገድ ላስደስትህ እንደምን አድርጌ\n', 'am', 541, 0),\n(1, 'ያለፈው ዘመኔ', 'ያለፈው ዘመኔ\nያለፈው ዘመኔ ይብቃ\nጌታ ሆይ አድርገኝ ምርጥ እቃ\nአልውጣ ከፍቅር እጅህ\nላመስግንህ ልኑር ከደጅህ\n\nያለፈው ዘመኔን ሳስብ በእውነት እጅግ አፍራለው\nድርሻዬንም ካንተ ወስጄ ብዙ አባክኛለው\nይሞላል ልቤ በጸጸት ድካሜን አስተውልና\nምህረትህ ያበረተኛል ትላንትን እረሳውና (2)\n\nደጃፍን አልፌ ልግባ ከፊትህ ይፍሰስ እንባዬ\nበልቤ ጉልበት ልንበርከክ እግርህን ልጠብ በእንባዬ\nመሀሪው በፍቅርህ ብዛት ቀና አድርገኝ ደግፈኝና\nመልካም በሚሟላት መቅደስህ ለስምህ ላቅርብ ምስጋና (2)\n\nከካራን በእምነት ልውጣ እና አስገባኝ ወደ ከነዓን\nጌታ ሆይ አንተን ልከተል ልርሳ እና ተሰሎንቄን\nሀጥያት የምረታበት አድለኝ ቅዱስ መንፈስ\nሀይልህን አብዛልኝና በቃልህ ልንቃ ልታደስ (2)\n\nከእንግዲህ ዞሬ አላይም ሀጥያት ዳግም ለምኔ\nአምላኬ በፍቅርህ ማርከኝ በቤትህ ይለቅ ዘመኔ\nህግህም ለእግሬ መብራት ለመንገዴ ብርሀን ነው\nየዘላለም ህይወት ካለህ ካንተ የት እሔዳለው (2)\n', 'am', 542, 0),\n(1, 'ዝናው በዓለም የተወራ', ' ዝናው በዓለም የተወራ\nዝናው በዓለም የተወራ\nክብሩ በምድር የተፈራ\nምን ይሳነዋል ከቶ ለሱ\nእልል በሉለት በቤተ መቅደሱ(፪)\n\nካህናቶቹ ጽድቅ የለበሱ\nበደብረ ጽዮን በራ መቅደሱ\nወደ እርሱ መጥቶ ሁሉ ተፈወሰ\nስሙን የያዘ ቀንቶት ተመለሰ [፪]\n\n     አዝ\nመንጦላይቱን በሳት የሰራ\nየአርያም ፀሐይ ለዓለም አበራ\nቸር አምላካችን ስንለው ሰምቶ\nይታደገናል እጁን ዘርግቶ [፪]\n\n     አዝ\nለሚቃወሙን ክንዱን ገለጠ\nእኛን ለማዳን ሞትን መረጠ\nከድሃ ሰው ጋር ትሁት ይሆናል \nኃይለኞቹንም ያንበረክካል [፪]\n\n     አዝ\nእግዚአብሔር ማን ነው ብለው ቢያሙት\nእነ ፈርኦን ቢያቃልሉት \nእረኛው ሙሴን ከኮሬብ ጠርቶ\nአደቀቃቸው ክንዱን ዘርግቶ [፪]', 'am', 543, 0),\n(2, 'አንቺን የያዘ ሰው', 'አንቺን የያዘ ሰው\nአንቺን የያዘ ሰው ምን ይጎድልበታል\nበምልጃሽ በረከት ቤቱ ሞልቶለታል\nዘር መከር ባይኖረው ጎተራው ባይሞላ\nሁሉም ይሸፈናል በረድኤትሽ ጥላ\n\nበረከትሽ ብዙ የደናግል ገንዘብ\nየምስኪናን እናት የሩሩኻን ቀለብ\nለሁሉም መጋቢ ጸጋሽ የማይጎድል\nስምሽ ጥዑም ምግብ ከረሃብ የሚያስጥል\n\nአንቺ ብትመጪ ከምስኪኗ ቤቴ\nእንደ መጥምቁ እናት በዛልኝ ኀሴት\nየአዲስ ኪዳን ቁርባን ወንበር ጠረንጴዛ\nጽድቅን አሸተተን የኅይወትሽን መአዛ\n\nልቤ ተጠራጥሮ ኪዳንሽን ካልከዳ\nልመናም አልወርድም አልይዝም አቁፋዳ\nኁሉን እየመላሽ መመገብ ታውቂያለሽ\nቢዝቁት የማያልቅ ጸጋና ኀብት አለሽ\n\nየእግዚአብሔር ማረፊያ ኮሬባዊት ዋሻ\nየኅይወት ውሃ ምንጭ የኅግ መፍሰሻ\nነበልባል ተዋህዶ ሙሴ አንቺን አይቷል\nጫማውን አውልቆ በፊትሽ ተደፍቷል', 'am', 1, 0),\n(2, 'ስድቤን አርቀሽ', 'ስድቤን አርቀሽ\nስድቤን አርቀሽ ነውሬን ሸፈንሽው\nእመ አምላክ በአንች መቸም አላፍርም\nስምሽን ጠርቸ እጽናናለሁ\nሀዘኔን በአንች እረሳለሁ\n\nነውር አለብኝ ብዙ ስድብ\nአንጀት የሚልጥ ልብ የሚያቆስል\nስሜን ለውጠው ቢያንቋሽሹኝ\nበሀዘን በለቅሶ ድንግል መጣሁኝ\nእንደሀና ሁኜ በቤተ መቅደስ\nበመረረ ሀዘን ነው እኔ እማለቅስ\nፍረጅልኝ እና ልመለስ ከቤቴ\nሀዘኔን በደስታ ለውጭው እናቴ\nበግራም በቀኜ ጠላት ቢከበኝ\nአብዝቸ እጮሀለሁ እናቴ ስሚኝ\n\nመከራው በዝቶ ግራ ገብቶኛል\nድምጽሽን ልስማ ያረጋጋኛል\nየሰው ህይወቱ ብርቱ ሰልፍ ነው\nደስታ እና ሀዘን የማይለየው\nበእጃችን ወድቋል ሲሉ ጠላቶቸ\nአመለጥኳቸው ስምሽን ጠርቸ\nሰው የዘራውን ያንኑ ያጭዳል\nበቆፈረው ጉድጓድ እራሱ ይገባል\nእናቴ እመቤቴ ብየ ስጠራሽ\nከመከራ ሁሉ ታወጭያለሽ\n\nበምርኮ ሳለሁ በሰው ሀገር\nግፍ ውለውብኝ ስኖር በእስር\nምልጃሽ ደርሶልኝ ተፈትቻለሁ\nበታምራትሽ እኔ ድኛለሁ\nቃልሽን ሰምቶ ፅንሱ ሰገደ\nብላለች ኤልሳቤጥ ነውሬ ተወገደ\nየጌታየ እናት እኔን አሰበችኝ\nታሪኬን ቀይራ ይሄው ባረከችኝ\nየእመቤቴ ከሆንኩ ማን ይቃወመኛል\nወጀቡም ማዕበሉም ይታዘዝልኛል\n\nወይን እኮ አልቋል የዶኪማስ ቤት\nድንግል አማልጅው ነይ የኛ እመቤት\nስምሽ ሲጠራ በየቦታው\nይሞላልናል የጎደለው\nግራ የገባው የቸገረው\nድንግልን ይጥራት እንድትረዳው\nሳዝን ስተክዝ የምታጽናና\nእናት አለችኝ ርህርህተ ልቦና\nእናቴ እመቤቴ ብየ ስጠራሽ\nከመከራ ሁሉ ታወጭኛለሽ', 'am', 2, 0),\n(2, 'የያሬድ ዉብ ዜማ', 'የያሬድ ዉብ ዜማ\nየያሬድ ዉብ ዜማ ድንግል እመቤቴ\nስጦታዬ ነሺ በምን አንደበቴ\nእንዴትስ ባለ ቃል ማርያም ልበልሽ\n\nምድርና ሰማዩ ተአምርሺን ይንገሩ\nፍጥረታት በሙሉ ስለ አንቺ ይመስክሩ\nተነግሮ የማያልቅ ድንቅ ነው ስራሽ\nድንግል ሆይ እናቴ አምሳያም የለሺ\nማርያም ድንግል እረዳቴ\nየምትደርሺልኝ ነይ ስልሽ በጭንቀተ\nታምርሺንም በአይነ አይቻለሁ\nጽዮን ሆይ ስልሽ ድንግል ሆይ እጠግባለሁ\n\nየእግዚአብሄር ጥበቡ በአንቺ ተገለጠ\nየአዳም ዘር በሙሉ ከሞት አመለጠ\nየመዳን ምክንያት ማርያም አንቺ ነሽ\nለፍጥረቱ ሁሉ መሰላል የሆንሺ\nነገን ባላውቅ እኔን ቢያስፈራኚ\nአንቺ ካለሺኝ በፍጹም አልወድቅም\nበፊትሺም እንድቆም ለምስጋና\nማርያም ልበልሽ በትህትና\n\nትውልዱ በሙሉ ለምስጋና ይቁም\nባንቺ ስለሆነ የቀረለት መርገም\nአዳም ከነልጁ በሰማይ በምድር\nማርያም ማርያም ይበል ተአምርሺን ይናገር\nጨለማው ከፊቴ ተገፈፈ\nማርያም በምልጃሽ ልቤ አረፈ\nከጎኔ ነይ ስልሺ እጽናናለሁ\nእሳት ገደሉን ሁሉንም አልፈዋለው', 'am', 3, 0),\n(2, 'ማርያም አርጋለች', 'ማርያም አርጋለች\nማርያም አርጋለች ወደ ገነት\nየሰማይ መላእክት እያረጋጓት\nእርሷም እንደ ልጇ ተነስታለች\n\nየአባቷን ዳዊት ትንቢት ልትፈፅም\nወርቁን ተጎናፅፋ በቀኙ ልትቆም\nወደ አምላክ ማደሪያ ወደ ሰማያት\nአረገለች በእልልታ ድንግል የእኛ እናት\nአርጋለች ማርያም ተነስታለች\n\nሰማያት ይከፈት ደመናም ይዘርጋ\nዝምታም አይኖርም እመ አምላክ አርጋ\nአንደበት ይከፈት ማርያምን ያመስግን\nከዘላለም ጥፋት በምልጃዋ እንድንድን\nአርጋለች ማርያም ተነስታለች\n\nየአምላክ ማደሪያ ቅዱስ ሥጋሽ\nአምላክን ያቀፉት እነዚያ እጆችሽ\nሙስና መቃብር ይዞ አላስቀራቸው\nተነስተዋል በክብር በእምነት አየናቸው\nአርጋለች ማርያም ተነስታለች\n\nሐዋርያት አበው እንኳን ደስ አላችሁ\nበክብር አረገች ማርያም ሞገሳችሁ\nወደ ዓለምም ውጡ ሰበኑዋን ይዛችሁ\nየድንግል እርገቷን ንገሩ ተግታችሁ\nአርጋለች ማርያም ተነስታለች', 'am', 4, 0),\n(2, 'አለፍኩት ድንግል', 'አለፍኩት ድንግል\nአለፍኩት ድንግል ማእበሉን\nአለፍኩት ድንግል ውጣ ውረዱን\nምርኩዜ ስለሆንሽ ስጠራ ስምሽን\n\nአለፍኩት ድንግል በእመቤቴ ምልጃ\nአለፍኩት ድንግል ወንዙን ስሻገር\nአለፍኩት ድንግል ያባረረኝ ጠላት\nአለፍኩት ድንግል ቀረ ሰምጦ ባህር\nአለፍኩት ድንግል ከበሮውን ላንሳ\nአለፍኩት ድንግል እንደ ሙሴ እህት\nአለፍኩት ድንግል ምስጋና ልሰዋ\nአለፍኩት ድንግል ለአለም እመቤት\n\nአለፍኩት ድንግል ወንድሞች ቢሸጡኝ\nአለፍኩት ድንግል አሳልፈውኝ\nአለፍኩት ድንግል በባእድ ከተማ\nአለፍኩት ድንግል ድንግል ሾመችኝ\nአለፍኩት ድንግል በቅን የማመልከው\nአለፍኩት ድንግል ልጅሽ ክርስቶስ\nአለፍኩት ድንግል ምልጃሽን አፅድቆ\nአለፍኩት ድንግል ሰቶኛል ሞገስ\n\nአለፍኩት ድንግል በስምጥ ሸለቆ\nአለፍኩት ድንግል ሆኜ ባታቂኝ\nአለፍኩት ድንግል የምደገፍበት\nአለፍኩት ድንግል አንዳች ሳይኖረኝ\nአለፍኩት ድንግል ባንቺ ተርፊያለው\nአለፍኩት ድንግል ምርኩዝ ሆነሽኝ\n\nአለፍኩት ድንግል ሰው የለኝምና\nአለፍኩት ድንግል ድንግል አትራቂኝ\nአለፍኩት ድንግል አንቺ ነሽ እናቴ\nአለፍኩት ድንግል የማሰለቺኝ\nአለፍኩት ድንግል ውለታዋ ብዙ\nአለፍኩት ድንግል የድንግል ማርያም\nአለፍኩት ድንግል እርሶን ለኔ የሰጠ\nአለፍኩት ድንግል ይክበር ዘላለም', 'am', 5, 0),\n(2, 'የፍቅር እናት', 'የፍቅር እናት\nየፍቅር እናት የሰላም\nይናፍቀኛል ስምሽ ሳልጠራው ስቀር ማርያም\n\nበሂወቴ ውስጥ በኑሮዬ\nቅደሚ ከፊት ከሀኅላዬ\nተደላደለ ልቤ\nአንቺ አለሽና ካጠገቤ\n\nምኞቴም ይስመር ትልቅ ህልሜ\nልለፍ ወደፊት ተቋቁሜ\nየጌታዬ እናት ነሽ\nሀይልን ያረጋል ፀሎትሽ\n\nእንዴት ቀራለው ከመንገድ\nአደራ እናቴ አስቢኝ\nከሚያስጨንቀኝ ጠላት\nለሚያሳድደኝ አትስጪኝ\n\nትላንትም ዛሬም አመስጋኝ ነኝ\nየለም ለነገየሚያስፈራኝ\nሜዳይሆናል ተራራ\nልጅሽ ስላለ ከኔ ጋራ', 'am', 6, 0),\n(2, 'ለተጠማ ውሻ', 'ለተጠማ ውሻ\nለተጠማ ውሻ ውሀ ያጠጣ ልብ\nእንዴት እሩሩ ነው የሚያሰኝ ነው እፁብ\nለኛማ ልጆቿ ለምንለምናት\nጥርጥር የለውም ድንግል አማላጅ ናት\n\nድንግል አማላጅናት የሁላችን ተስፈ\nህይወት የምትለምን በሞት እንዳንጠፋ\nአዛኝት እመ አምላክ አትረሳንም እሷ\nፍቅርና ሰላም ምህረት ነው ድግሷ\n\nድንግል አወለቀች የወርቅ ጫማዋን\nለተጠማ ውሻ ልትሰጥ ውሀውን\nታምሯኝ ሰምተናል ደግሞም እናምናለን\nልቧ እንዲራራልን እንለምናለን\n\nድንግል ለምኚልን ሀጥያታችን በዝቷል\nልብሽ እንኳን ለኛ ለውሻ እራርቷል\nደግነትሽ ብዙ ፍቅር ርህራሔ\nየጌታ ማደሪያ ፅኑ ነው እምነትሽ', 'am', 7, 0);\n\nINSERT INTO mezmurs (category_id, title, content, language, sort_order, sync_version) VALUES\n(2, 'እመቤቴ ምርኩዝ እረዳቴ', 'እመቤቴ ምርኩዝ እረዳቴ\nእመቤቴ ምርኩዝ እረዳቴ\nየክፍ ቀን መሸሸጊያ ቤቴ\nሆድ ሲብሰኝ ደጅሽ መጥቼ\nእፅናናለሁኝ ስምሽን ጠርቼ\n\nኑሮዬ ሲያስቸግረኝ አንቺን ስማፅንሽ\nሙሉ ነው ጓዳዬ መቼ አፍሬ አውቃለሁ\nያንቺን ስም ሳነሳ ሀዘን ከእኔ ሮቆ\nጠፈልኝ አበሳ\n\nሀዘኔ ሲበዛ መች ብቸኛ ሆንኩኝ\nከጎጆዬ ገብተሽ በአንቺ ተፅናናሁኝ\nየሚስኪኖች ተስፋ ምንም ለሌላቸው\nየነዳያን ሁሉ አንቺ ነሽ ተስፋቸው\n\nየእናት ልመና ፊት አይመልስም\nአንቺን የጠራ ሰው ዘላለም አያፍርም\nበሔድኩበት ሒጂ በምጓዝበት\nበኑሮ ዘመኔ ሁኚኝ ረዳቴ', 'am', 8, 0),\n(2, 'ውበት ነሽ', 'ውበት ነሽ\nውበት ነሽ ለቤቴ ለኑሮዬ ፋና\nድንግል ሆይ አትለይኝ ብቻዬን ነኝና\n\nበሃዘን ጠቋቁራ ተከፍታለች ገፄ\nአጎንብሻአለሁኝ አፍሬ በለምፄ\nወልቋል ከራሴ ላይ የብርሃን ልብሴ\nሃብቴ አንቺ ብቻ ነሽ ያለሽኝ ሞገሴ\n\nለአምላኬ የማቀርበው አጣሁ በጎ ስራ\nነፍሴ ተጨነቀች በምግባሬ መራ\nጥላሸቱ በዝቶ ተዳፍኖኗል ጎጆዬ\nብርሃን የለውም ካልበራ ሻማዬ\n\nየምታመንበት አንዳች ነገር የለኝ\nበነፍስም በስጋ ሁሉ የጎደለኝ\nእጠባበቃለሁ የእጅሽን በረከት\nእቤቴ ላይ አርፎ እስክባረክበት\n\nየጓዳዬ ክብር የቅጥሬ ድምቀት ነሽ\nዓይኔን የምትሞይው በመቅረዜ በርተሽ\nየፅልመት ጭላንጭል ጠፍቷል የለም ዛሬ\nየብርሃን እናት ስላለች በበሬ', 'am', 9, 0),\n(2, 'ስምሽን ቢጠሩ የማትጠገቢ', 'ስምሽን ቢጠሩ የማትጠገቢ\nስምሽን ቢጠሩ የማትጠገቢ\nየመንገድ ስንቄ ነሽ የነፋሴ መጋቢ\nምስጋናሽ ይብዛልኝ ወደቤቴ ግቤ\n\nጻድቃን የወረሱሸወ የእግዚአብሔር ከተማ\nየመንኩሳን ሰፈር የሞላብሽ ግርማ\nቡራኬሽ ይድረሰኝ እናቴ ይህ ፍቅርሽ\nነፋሴን በምስጋና ላንቺው ላድርስልሽ\n\nየአለም አርነት ጽህፈት ያለብሽ\nየህይወት ፊደሌ ጽድቅ የተማርኩብሽ\nቢያነቡሽ አታልቂ ሚስጥርሽ የሰፋ\nስምሽ ማራኪ ነው ከልብ የማይጠፋ\n\nበሰው አገር ስኖር ሰው ጠፋቶ ከጎኔ\nባልጀራ ሆነሽ የለሊት ብርሀኔ\nተስፋዬን አብዝተሽ ጥሜን አስታገሽው\nበብዙ በረከት ህይወቴ ሞላሽው\n\nፋፁም እሩሩህ ነሽ ስምሽ ጣህም ያለው\nአዘኔ ሲበዛ ባንቺ እጽናናለው\nየአለም እርጋታ የሰላም ውጥን ነሽ\nጊዜ ለጣለው ሰው አይጨክንም ልብሽ', 'am', 10, 0),\n(2, 'የሲሎንዲስ ጥበብ', 'የሲሎንዲስ ጥበብ\nየሲሎንዲስ ጥበብ እወድሻለሁኝ\nየናሆም መድኃኒት እወድሻለሁኝ\nማርያም አከብርሻለሁ\nማርያም እወድሻለሁ\n\nተጨንቄለኁ ልንገርሽ\nሚስጥሪኛዬ እናቴ ነሽ\nሰው ያልሰማውን ብርቱ ምስጢር\nድንግል ሆይ ላንቺ ላማክር\nለቁስለኛውም መድኃኒቱ\nየአደም ዘር ሁሉ ነሽ ህይወቱ\nመፍትሄ አለ በእጅሽ ተንበርክኬ ልማፀንሽ\n\nሳልናገረው ይገባሻል\nየውስጤ ሁሉ ይታይሻል\nድረሽ እናቴ ተራጅኝ\nያላንቺ ለኔ ማን አለኝ\nደስታዬ ደስታ የሚሆነው\nበሀዘኔም የምፅናናው\nአንቺ ከኔ ጋር ስለሆንሽ\nተፅናንንቻለሁ በስምሽ\n\nወንድሞቼ እንኳን ቢሸጡኝ\nሰው ሁሉ ጠላት ቢሆነኝ\nበእማምላክ ሀይል ከብሬለሁ\nበጠላቴ ላይ ሰልጥኛለሁ\nየረሱኝ ሁሉ ያስቡኛል\nየተጣሉኝም ያከብሩኛል\nአንቺ አንግሰሽኝ አልወድቅም\nእቆማለሁኝ ዘለዓለም\n\nመንገዴ ረዝሞ ደክሜብሽ\nመከራው በዝቴ ታምሜብሽ\nወድቄ ሳዝን ድረሽልኝ\nለባሪያሽ ሀይሉን እንድትሰጭኝ\nፍቅርሽ በውስጤ ተንሰራፋ\nበእናትነትሽ ልቤ ሰፋ\nየሚለያየን ማንም የለም\nማርያም ልበልሽ ለዘለዓለም', 'am', 11, 0),\n(2, 'ቢያበሉኝ ቢያጠጡኝ', 'ቢያበሉኝ ቢያጠጡኝ\nቢያበሉኝ ቢያጠጡኝ\nፈትፍተው ቢያጎርሱኝ\nያሻህን ውሰድ ሁሉ ያንተ ነው ቢሉ\nእኔስ እንደ ስሟ የጣፈጠ አጣሁኝ\n\nየዚህ አለም ነገር ባዶ ሆኖብኛል\nዛሬ የበላሁት ነገ ይርበኛል\nመራራ ህይወቴ ጣፈጭ የሚሆነው\nእመቤቴ ስሚኝ ባንቺ ጨውነት ነው\nአዛኝቷ ስሚኝ ባንቺ ጨውነት ነው\n\nአንቺ የሌለሽበት ማዕዴ ባዶ ነው\nስምሽን ካልጠራሁ ጣፈጭ መራራ ነው\nበእጄ ከጨበጥኩት የመሶብ እንጀራ\nማርያም የሚለው ስም ጣፈጭ ነው ሲበላ\n\nተስፈ ያደረገ አንቺ በህይወቱ\nስለሆንሽለት ነው የተማሪ ራቱ\nእኔም እልሻለሁ የኑሮ ጣዕሜ\nከሞት ወደ ህይወት መሸጋገሪያዬ', 'am', 12, 0),\n(2, 'ዕርስታችን ነሽ', 'ዕርስታችን ነሽ\nዕርስታችን ነሽ እንወርስሻለን\nከምድርሽ ወይን እንለቅማለን\nይትረፈረፈል ፅዋችን ሞልቶ\nአንቺን ይዘናል አናፍርም ከቶ\n\nየእንጀራ ምድር የፍቅር ሀገር\nየለንም ወገን ካንቺ በስተቀር\nከአከአብ መሬት የማንቀይርሽ\nደጅሽ ቆመናል ባርኪን በእጆችሽ\n\nዳዊት አባትሽ እንዳለ ብረሳሽ ቀኝ ትርሳኝ\nበልቤ ላይ ነግሰሻል ምልጃሽ የጠበቀኝ\n\nወደ ምድራችን መርቶን ስንገባ\nአንቺን አገኘን ታላቋን መባ\nየህይወት ውሀ ፈልቋል ከሆድሽ\nእንዳንጠማ ዳግም ልጆችሽ\n\nነዶ በዛልን የስንዴ ዘላ\nወይኑን ብንጨምቀው ፅዋችን ሞላ\nመሆንሽን አውቀን የበረከት ምድር\nአንጠፈም ድንግል ከመቅደስሽ ስር\n\nአሁን በደስታ ስፍራ ይዘናል\nመስቀል ላይ ሆኖ ጌታ መርጦናል\nከዚህች እርስት ሚነቅለን የለም\nአትሞበታል የደሙን ማዕተም', 'am', 13, 0),\n(2, 'ድንግል ተወለደች', 'ድንግል ተወለደች\nድንግል ተወለደች እመቤታችን\nከዳዊት ዘር ወጣች ተስፋ ስንቃችን\nየቴክታ ጰጥሪቃ ህልማቸው ተፈታ\nከድቅድቅ ጨለማ ጨረቃዋ ወታ\n\nከሴም ከያዕቆብ ከብሩካን ሀገር\nከቅድስ ተራራ ወጣች የሀሮን ዘር\nየፅድቅ ሀመልማሏ ዳዊት ቤት በቀለች\nአዳምን የሚያድን በረከት አዘለች\n\nዝናብ ያየንባት የፅድቅ ደመና\nድንግል ተወለደች ከህያቄብ ከሀና\nከእሴይ በትር ስር ወጥቷል አበባ\nበድንግል ተፈታ የሔዋን መርገሟ\n\nምድር ተደሰተች ቀረባት ሰማዩ\nሊያበቃ ነው የአዳም ስቃዩ\nበድንግል መወለድ ሆነ ተድላ ደስታ\nዮም ፍስሀ ኮነ በማርያም ልደታ\n\nድንግል ስትወለድ ሊባኖስ አበራ\nበደስታ ተሞላ ታላቁ ተራራ\nቀስተ ደመና ናት ሰማያዊ ንስር\nገና እንዘምራለን ስለ ድንግል ክብር', 'am', 14, 0),\n(2, 'ኪዳነ ምህረት እናቴ', 'ኪዳነ ምህረት እናቴ\nኪዳነ ምህረት እናቴ\nፈጥነሽ ደራሽ ነሽ በሐዘኔ\nየከበበኝ ጭንቀት ተወግዷል\nፍቅርሽ እመ አምላክ እኔን ማርኳል\nየችግሬ ደራሽ የጭንቀቴ\nነይ እናቴ ነይ እናቴ\n\nእናቴ ባንች ሰው ሆኛለሁ\nከሞት አፋፍ ላይ ተርፌያለሁ\nስምሽን ስጠራ ቀን ሌሊት\nትሆኝኛለሽ መድሀኒት\n\nአለኝ የምልሽ ፍፁም ሀብቴ\nከሊባኖስ ነይ መድሀኒቴ\nያደራ ልጅ ነኝ ያንች ልጅ\nተሰጥቻለሁ በአዋጅ\n\nክብርሽ ልዩ ነው እመቤቴ\nተነግሮ አያለቅም በአንደበቴ\nበክርስቶስ ቀኝ ትቆሜያለሽ\nፍጥረትን ሁሉ ታስምሪያለሽ\n\nኑሮ ሲመረኝ ሳመነታ\nወደአንቺ መጣሁ ጧት ማታ\nበስዕልሽ ፊት አልቅሻለሁ\nመልሱን በቶሎ አግኝቻለሁ', 'am', 15, 0),\n(2, 'ስምሽን ለልጅ ልጅ', 'ስምሽን ለልጅ ልጅ\nስምሽን ለልጅ ልጅ እነግራለው\nእናቴ በምልጃሽ ስው ሁኛለው\nእመቤቴ ስልሽ ነይልኝ\nማዕበል ሳይነቅለኝ\n\nእመቤቴ ብዬ ስምሽን መጥራቴ\nቢራቆትብኝ ነው ባዶ ቢሆን ቤቴ\nአይኖቼን ከእንባ ከለቅሳ ከልክይ\nልብሽ ይራራልኝ ወደ እኔ አዘንብዪ\n\nባሕሩም ቢሞላ አምናለሁ በልጅሽ\nአንገት አያስደፋም እናቴ ፀሎትሽ\nስምሽን ስጠራ እጆቼን ዘርግቼ\nቀስታቸውን ሁሉ ጣሉ ጠላቶቼ\n\nሰላም አለኝ አሁን ይህንን አውቃለው\nእጅግ ብዙ ነገር በእንች አግንኝቻለው\nማድጋዬ ሞልቶ አለም ተመልክቷል\nምድረ በዳው ልቤ በፀሎትሽ ረክቷል', 'am', 16, 0),\n(2, 'ጽርሃ አርያም', 'ጽርሃ አርያም\nጽርሃ አርያም ጽርሃ አርያም\nክብርሽ ገናና ነው ለዘላለም\n\nበመላዕክት ዓለም በሶስቱ ከተማ\nበኤረር በኢዮር እንዲሁም በራማ\nውዳሴ ቀረበ ለሰማይ ንግስት\nየአምላክን እናት በክብር አየናት\n\nበበረሃ ያሉ ዓለምን የናቁ\nውዳሴሽን ደግመው ስምሽን የሰነቁ\nአንቺን ስንጠራ ጠላት ገለል ይላል\nማርያም በግርማሽ ከሳሻችን ያፍራል\n\nከእግሮቿ በታች ጨረቃን ተጫምታ\nየክብርን አክሊል በራሶቿ ላይ ደፍታ\nበቅዱሳን ሁሉ ትመሰገናለች\nዓለም የዳነባት ድንግል ማርያም ነች\n\nብርሃንን ለብሳ በንጽህና አጊጣ\nፍጥረትን ስትባርክ በክብር ተገልጣ\nነፍሳት ተቀደሱ በእምነት ከበዋት\nከበሮን አንስተን እንዘምርላት', 'am', 17, 0),\n(2, 'ስለረዳሽኝ እመቤቴ', 'ስለረዳሽኝ እመቤቴ\nስለረዳሽኝ እመቤቴ አወድስሻለሁ\nከኔጋር ስለሆንሽ እመቤቴ አወድስሻለሁ\nምስጋናሽን ይዤ ጠዋት ማታ ፊትሽ እቆማለሁ\nምስጋናሽን ይዤ እመቤቴ ፊትሽ እቆማለሁ\n\nሀዘን ትካዜዬ ባንቺ ተወግዷል\nልመና ፀሎቴ ሀሳቤ ተሟልቷል\nያጣሁትን ሁሉ አግኝቼብሻለሁ\nበእናትነትሽ ዘወትር እመልካለሁ\n\nባንቺ ደስ ይለኛል ያርፋል ልቦናዬ\nሰዓሊ ለነ ብዬ ተቃና ጉዞዬ\nአልፈራም እንግዲህ ገደል እንቅፋቱን\nይዘሽኛልና ድንግል አዛኝቱ\n\nየተስፋ መብራቴ አትጠፊም ከፊቴ\nመድኃኒቴ አንቺ ነሽ ለብቸኝነቴ\nይች አለም ብትከፋ ፊቷን ብትመልስ\nጨክነሽ አታውቂም እናቴ በኔስ\n\nምስክር አልሻም ከእንግዲህ በኃላ\nነብሴ ትጮሀለች አማላጄ ብላ\nአወድስሻለሁ እናቴ እመቤቴ\nበኑሮዬ ሁሉ እስከለተ ሞቴ', 'am', 18, 0),\n(2, 'ደጅሽ ላይ ቆሜ', 'ደጅሽ ላይ ቆሜ\nደጅሽ ላይ ቆሜ ስለምንሽ\nባርኪኝ እናቴ ማርያም ስልሽ\nተደላደለልኝ ህይወቴ\nባንቺ በእናቴ እመቤቴ\n\nአንቺ በመሆንሽ የህይወቴ ፋና\nአልፈራም ጨለማ ብርሀን አለኝና\nአልጠፈም ዘላለም ስምሽ ከአንደበቴ\nአለ በደሜ ውስጥ ፍቅርሽ በህይወቴ\nአልቀርም ደጅሽ ለዘላለም\nከአንቺ የሚለየኝ ማንም የለም\n\nእጅግ የተከፈ ደካማ ሰው አለ\nመቅደስሽ የቆመ አማልጂኝ እያለ\nይቁምይኸ ሀዘን የሰበረ\nካንቺ በቀር ወገን መጠጊያ የሌለው\nያንሳው ኪዳንህ በውድቀቱ\nያርግ በእጅሽ ያ ፅሎቱ\n\nፅልመት የለበሰ ፈታኝ አደከመኝ\nየምቋቋምበት ጉልበት አስፈለገኝ\nበርትቼ እንድ ፅና ሳትጎዳ ነብሴ\nሁኚኝ እናቴ ሆይ ግርማዬ ሞገሴ\nይውደቅ ከእጄ ላይ ሰንሰለቴ', 'am', 19, 0),\n(2, 'በታምርኪ', 'በታምርኪ\nበታምርኪ ተፈስሀ ኩሉ ዓለም\nበታምርኪ እግዝዕትነ ማርያም እግዝዕትነ\nተአምርሽ ሲነበብ እግዝዕትነ\nየሰራሽው ስራ እግዝዕትነ\nአጋንንት አይቀርብም እግዝዕትነ\nየተአምርሽ ነገር እግዝዕትነ\nየሰማ ያሰማ እግዝዕትነ\nመንግስቱን ይወርሳል እግዝዕትነ\nከቅዱሳን ጋራ እግዝዕትነ\n\nስሞ መታረቂያ እግዚዕትነ\nየፍቅር እናት እግዚዕትነ\nየወልድ ማደሪያ እግዚዕትነ\nአዛኝ ርህሪት እግዚዕትነ\nአመቤቴ ማርያም እግዚዕትነ\nየሰማይ ንግስት እግዚዕትነ\n\nየእመቤታችን እግዝዕትነ\nተአምሩን እናክብር እግዝዕትነ\nይሰጠናል እግዝዕትነ\nፍቅር እና ሰላም እግዝዕትነ\nበተአምርሽ ደስ አለው ዓለሙ በሙሉ\nበተበተአምርሽ እመቤታችን ማርያም እመቤታችን\nእመቤታችን ማርያም እመቤታችን', 'am', 20, 0),\n(2, 'መራራው ህይወቴ', 'መራራው ህይወቴ\nመራራው ህይወቴ ጣፈጠ በማርያም\nማዘን ስደት ይቅር እስከ ዘለአለም\nተፈውሷልና በመቤታች\nየመሪባውሀ ተባረከልን\nበእግዝትነ ማርያም እንድናለን\n\nሀገሪቱ መልካም ኑሮዋ መራራ\nበስደት አለቀ ወገኔ በተራ\nሽማግሌ እንዲጡር ህፃናት እንድያድጉ\nኤልሳን የሚተካ አባት ስው ፈልጉ\nማስሮ አምጡ ጨውን ጨምራችሁ\nሞት እንዳይነግስ በመካከላችሁ\nማርን እንበል ሄሎሄ ብለን\nእንዋደድ እንዲስምርልን\nትውልድ ሁሉ ብፅኢት የሚሉሽ\nኢትዮጵያ እንባዋን አብሽ\n\nታለቅሳለች እና እማማ ኢትዮጵያ\nየወላዶች መካን አርገዋት ልጆቿ\nአለሙም ንብረቱም ሁሉም ይልፋልና\nይበቃናል እንበል በቀና ልቦና\nየህፃናት ድምፅ ተስማ በራማ\nስለሆነች ምድሪቱ አኬልዳማ\nየዘገየ ቢመስል እግዚአብሔር\nቀድሞ ይፈርዳል ሳሉ በምድር\nየአቤል ደም ፀባኦት ደረስ\nቃየልስ ወዴት ገስገስ\nለአዛኝቷ ሁሉ ይሆናልና\nንገሯት በፀኑ ልመና\n\nእኔ የኬፋ ነኝ ላጰሉስ አትበሉ\nየተለያየ መንግስት አይፀናም እንድሉ\nየኢትዮጵያ ልጆች አንድነን ሁላችን\nልዩነት እናጥፋ ከመካከላችን\nስንዴ መሀል እንክረዳድ አንዝራ\nተደምስሷል የዲያቢሎስ ሴራ\nባስጨናቂዎች እጂ አትጣለን\nፈረድልን እናነባለን\nለልጁ አባት ይገደዋልና\nአምላክ ሆይ ተመልከተን ናና\nስለ ማርያም ብለን ለምነን\nአልፈናል ያን ክፋ ዘመን\n\nሀገርን አይተውም ያላዳች ፃዲቅ\nስውሩም ይታያል አይሆንም ድብቅ\nየአባቶቼ እርስት ስሟም ቶን ቶን\nገበዟ ጊዮርጊስ ነው አስራት የድንግል\nዳሯ እሳት መሀሏ ገነት\nለኛም ይስጠን ፍቅር አንድነት\nየተሳቱ ቅዱሳን መሽሻ\nኖላዊሄር ጠባቂሽ ነው ጋሻ\nትውልድ ሁሉ ብፅኢት የሚሉሽ\nኢትዮጵያን እንባዋን አብሽ\nሀገሬን እንባዋን አብሽ\nኢትዮጵያን እንባዋን አብሽ', 'am', 21, 0),\n(2, 'መሐረኒ ድንግል', 'መሐረኒ ድንግል\nመሐረኒ ድንግል ወተሰዓለኒ በበዘመኑ\nለእመ መሀርከኒ አንቲ ዘይኩነኒ መኑ\nኩነኔ ስጋ ወነብስ ወልድ ኪያ ኮኑ\n\nይጠሩሻል ካህናቱ\nንዒ ይሉሻል በሳዕታቱ\nለለመነሽ የማትቀሪ\nበልቤ ውስጥ ፅንተሽ ኑሪ\nየስጋና የነብስ ፈራጅ ልጅሽ አይደለም ሆይ\n\nየሐዲስ ኪዳን ኪሩብ የሆንሽ\nለምኚልን ከአንድ ልጅሽ\nርግብየ ሰናይትየ\nነይ ወደኔ ህይወትየ\nኩነኔ ስጋ ወ ነፍስ\n\nመሐሪኝ ድንግል ማርያም\nይቅር በይኝ በየዘመኑ\nድንግል ሆይ ከማርሽኝ\nእናቴ ሆይ ከማርሽኝ\nድንግል ሆይ ከማርሽኝ\nልጅሽም አይኮንነኝም\n\nበአለም መኖር ሰልችቶኛል\nመልካም መስራት አቅቶኛል\nእጄን ይዘሽ ድንግል ምሪኝ\nአዛኝቷ አትለይኝ\nየስጋና የነፍስ ፈራጅ ልጅሽ አይደለም ሆይ\n\nእበላለውዐብዬ ማርያም\nእመካለው ባንቺ አላፍርም\nካንቺ ወዴት እሔዳለሁ\nስምሽን ልጥራው እፅናናለው\nኩነኒ ስጋ ወነብስ ወልድ ኪያ ኮኑ', 'am', 22, 0),\n(2, 'ወደ ቀድሞ ነገር', 'ወደ ቀድሞ ነገር\nወደቀድሞ ነገር እንመለስ\nየአምላክን እናት እናወድስ\nከፍቅሯ ርቃችው ለምትኖሩ\nማርያም ፊደል ናት ኑ ተማሩ\n\nቃል ተፅፎባታል የመዳኛ ፊደል\nጥበብ የምትሞላ ጨለማን የሚነቅል\nለቃል ስጋ መሆን ምክንያት ስለሆነች\nቀርባቹ ተማሩ ማርያም ፊደል ነች\n\nአዲሱ ቃልኪዳን ከላይ የተፃፈው\nበገሊላ ናዝሬት ገብርኤል ያበሰረው\nበማርያም እቅፍ ላይ ታገኙታላቹ\nየምስጢር መዝገቡን አንብቡት ገልጣቹ\n\nያዘለችው ወንጌል ቃሉ ይፈውሳል\nአምኖ ላነበበ ነፍስ ያለመልማል\nበጀርባዋ ያለው እግዚአብሔር ነው እና\nአቅርቡ ለማርያም ውዳሴ ምስጋና\n\nብዝዎች ተማሩ ስሟን እየጠሩ\nበአባታቸው መንግስት እንደፀሀይ በሩ\nክብር ልልና ዋን ገብርኤል ነግሮናል\nካወደሷት ጋራ ለክብሯ ቆመናል', 'am', 23, 0),\n(2, 'ሐረገ ወይን ነሽ ድንግል', 'ሐረገ ወይን ነሽ ድንግል\nሐረገ ወይን ነሽ ድንግል የወልድ እናቱ\nብጽዕት ይሉሻል እመ አምላክ አንቺን ትውልድ ሁሉ\nሥምሽ ልዩ ነው ለእኛ ቤዛዊተ ኲሉ\n\nየያዕቆብ መሰላል የሙሴ በትር\nየእሣትን ባሕር የምታሻግር\nእመ ብዙሐን ናት የተሰጠች ለእኛ\nጥላ ከለላ ናት ከጥፋት መዳኛ\n\nፍቅር ሠላም የተገለጠባት\nሐገረ እግዚአብሔር ድንግል እመቤት ናት\nየታጠረች ተክል የተዘጋች ደጃፍ\nለድንግል ምስጋና ይድረስ ከአጥናፍ አጥናፍ\n\nእጹብ ድንቅ ነገር ለእኛ ተሰጥቶናል\nሕይወት የምትለምን እናት አግኝተናል\nእስከ ቀራንዮ ከጸና ጉዞአችን\nድንግል ትገኛለች የአደራ እናታችን', 'am', 24, 0),\n(2, 'ኪዳነ ምሕረት ለእኔ መመኪያዬ', 'ኪዳነ ምሕረት ለእኔ መመኪያዬ\nኪዳነ ምሕረት ለእኔ መመኪያዬ\nለችግሬ ደራሽ ነሽ መጠለያዬ\nሕይወቴ ጎስቁሎ በነፍሴ ብዝልም\nበምልጃሽ ታምኜ በኪዳንሽ ልቁም\n\nእጅግ ምስኪን ሆኜ ለሠዎች ብታይም\nሞልቶ የተረፈ ጥሪት ባይኖረኝም\nአንቺ ካለሽልኝ ጓዳዬ ሙሉ ነው\nአፍሮ አያውቅምና የተማጸነሽ ሠው\n\nዲያቢሎስ ዕቅዱን በልቤ ቢያገባ\nተገፍቼ ቢያይ በሠናኦር ካባ\nየአዳም ደሞዙ እንዳይከፈለኝ\nበሞት እንዳልጠፋ ድንግል ተለመኚኝ\n\nወገን የለኝ ዘመድ ፍጹም ከአንቺ በቀር\nእኔን የሚረዳኝ በዓለም ሥቸገር\nአይዞኽ በይኝ እና ደግፊኝ እናቴ\nየጸጋ ልብስ ሁኚኝ ሲራቆት ሕይወቴ\n\nነፍሴን እንድትቀደስ ከርኩስነት አምልጣ\nከሴኬም ልሰደድ ወደ ቤቴል ልውጣ\nመሪዛን ልበልሽ ድንግል መሸሺያዬ\nኢዮአታም ልጅሽ መጣሁ አንቺን ብዬ', 'am', 25, 0),\n(2, 'ድንግል በድንግልና', 'ድንግል በድንግልና\nድንግል በድንግልና ፀንሳ በድንግልና ትወልዳለች\nስሙንም አማኑኤል ትለዋለች\n\nገና ሳይነገር ዘመኑ ሳይገባ\nገረድ መሆን ሻተች ትንቢቱን አንብባ\nልታያት ናፈቀች ያቺን ቅድስት እናት\nለክብሩዋ ተገዝታ ውኃ ልትቀዳላት\nባሪያ ልሁን አለች ዝቅ አድርጋ እራስዋን\nመች አወቀችና እናቱ መሆኑዋን\nጥቂት ለሚሻ ሰው ያውቃል ብዙ መስጠት\nበማህፀንዋ መቅደስ ሲቀደስ ኖረበት\n\nሐር ወርቁን ስትፈትል ከቤተ መቅደሱ\nማደሪያው እንድትሆን መረጣት ንጉሱ\nበህሊናው ተስላ የነበረች መና\nመሰላል ሆነችው ለአዳም ድህነት እርከብ\nበጎ መዓዛዋን ውበትዋን ወደደ\nበማህፀንዋ ሊያድር እግዚአብሔር ወረደ\nከኪሩቤል ይልቅ ጀርባዋ ተመቸው\nንፅይት ናትና የማትቆረቁረው\n\nየተዘጋች መቅደስ ከቶ ማትከፈት\nታትማ የኖረች የክብሩ ሰገነት\nማንም አይከፍታትም ጥበብ አላትና\nየእስራኤል ቅዱስ ገብቶባታልና\nበረቀቀው ጥበብ ድንግል ተደነቀች\nበሆድዋ ቅዳሴን እያስተናገደች\nጎንበስ አለች ማርያም ውዳሴ ልትሰማ\nከቅኔያት አገር ከሆድዋ ከተማ\n\nድንግል በድንግልና ፀንሳ በድንግልና ትወልዳለች\nስሙንም አማኑኤል ትለዋለች', 'am', 26, 0),\n(2, 'ድንግል ፈጣሪዋን', 'ድንግል ፈጣሪዋን\nድንግል ፈጣሪዋን ወለደችው\nበመጠቅለያም ጠቀለለችው\nየለምና ስፍራ የእንግዶች ማረፊያ\nግርግም አስተኛችው በከብቶች ማደሪያ\n\nጨነቃት ጠበባት በዳዊት ከተማ\nየጌታ መወለድ ታምሩ ሲሰማ\nወረደ መላኩ ምስራች ሊያወራ\nየህፃኑ ክብር በምድር አበራ\nይህ ሚስጢር ግሩም ነው ከቶ ማይነገር\nማርያምም በልቧ ትጠብቀው ነበር\n\nሰባሰገል መጡ ከሩቅ ምስራቅ ሀገር\nወርቅ እጣን ከርቤውን ለእርሱ ለመገበር\nበእናቱ እቅፍ አገኙት ህፃኑን\nለአለም ተናገሩ ንጉስ መወለድን\nይህ ሚስጢር ግሩም ነው ከቶ ማይነገር\nማርያምም በልቧ ትጠብቀው ነበር\n\nየይሁዳ ምድር ምስጋናን ተሞላች\nንጉስ መቷልና ከናዝሬት ገሊላ\nታምሩን ትናገር ቤተልሔም ታውራ\nየህፃኑ ክብር በምድር አበራ\nየማይታይ ታየ ተዳሰሰ እንደሰው\nበጠባብ ደረት አዳምን\nገረማት ጥበብ ታናሿ ሙሽራ\nተዋህዷልና ቃል ከስጋ ጋራ', 'am', 27, 0),\n(2, 'ቋንቋዬ ነሽ ድንግል', 'ቋንቋዬ ነሽ ድንግል\nቋንቋዬ ነሽ ድንግል መግባቢያዬ\nመልስ የማገኝብሽ ከጌታዬ\nበአንቺ ቀርቤአለሁ ከአምላኬ ፊት\nቤቴ ሞልቶልኛል በበረከት\n\nበምን ስራዬ ነው ከፊቱ የቆምኩት\nመቼ በቅቼ ነው ስሙን የጠራሁት\nአስታራቂ እናት አንቺን ስለሰጠኝ\nስለ ቃልኪዳንሽ አቤት ልጄ አለኝ\n\nቅድስና ሕይወት ከእኔ ተሰውሮ\nበውሸት በሃሜት አንደበቴ ታስሮ\nበእመ አምላክ ምልጃ አዲስ ሰው ሆኛለሁ\nእንደ መላእክቱ ይኸው እዘምራለሁ\n\nስለ እመ አምላክ ብሎ ያፈረ የለም\nባንቺ ያልከበረ ሰው አይገኝም\nእንደ ባለማዕረግ እኔም ሰው መባሌ\nአንቺን አግኝቼ ነው ድንግል መሰላሌ\n\nሰላም ለኪ ብዬ ስጀምር ጸሎቴን\nሐሴት ይመለዋል መላው ሰውነቴን\nእንደ ቅዱስ ኤፍሬም በምስጋናሽ ልጽና\nበእጆችሽ ያለው አምላኬ ነውና', 'am', 29, 0),\n(2, 'እንደ ኤልሳቤጥ', 'እንደ ኤልሳቤጥ\nእንደ ኤልሳቤጥ ላመስግንሽ\nፊትሽ ወድቄ ልሳለምሽ\nየጌታዬ እናት የእኛ እመቤት\nአዛኝነትሽ ከልብ ፍጹም የምህረት\n\nእርህራሄሽ ያስደንቀኛል\nስለኃጢያቴ ምልጃሽ ይቀድማል\nየሰላምታሽ ድምጽ ደስ ያሰኘኛል\nከትካዜዬም ያሳርፈኛል\n\nድምፅሽ ሲሰማኝ ልቤ ይረካል\nሐዘኔ ቀርቶ ፊቴ ይፈካል\nበእናትነት አንቺን የሰጠን\nቸሩ አምላካችን ይክበር ይመስገን\n\nየሁሉ እመቤት የሁሉ አፅናኝ\nየአበው መድኃኒት ከአምላክ አገናኝ\nዛሬም በልቤ ደስታ ጨምረሽ\nእንደ ኤልሳቤጥ ሰላም ልበልሽ\n\nከሴቶች መካከል መርጦ ቀድሶሻል\nትውልድ ሁሉ ብጽዕት ይሉሻል\nበልዩ ውዳሴ ያመሰግኑሻል\nድንግል እናታችን በቀኙ ቆመሻል\n\nየሰላምታሽን ድምፅ ልቤ ሲሰማ\nነፍሴ ደስ አላት ቀለለ ሸክሟ\nድንግል ላከብርሽ ስንበረከክ\nእጅሽ ይዘረጋ ለመባረክ', 'am', 30, 0),\n(2, 'ዮም ፍስሐ ኮነ', 'ዮም ፍስሐ ኮነ\nዮም ፍስሐ ኮነ በእንተ ልደታ ለማርያም\nበባርነት ሳለን ፍስሐ ኮነ\nሀጢአት ባለም ነግሳ ፍስሐ ኮነ\nበድንግል መወለድ ፍስሐ ኮነ\nቀረልን አበሳ ፍስሐ ኮነ\n\nእግዚአብሄር መረጠሽ ፍስሐ ኮነ\nልትሆኝ እናቱ ፍስሐ ኮነ\nይኸው ተፈፀመ ፍስሐ ከነ\nየዳዊት ትንቢቱ ፍስሐ ኮነ\n\nየሰው ልጆች ተስፋ ፍስሐ ኮነ\nየአዳም ህይወት ፍስሐ ኮነ\nየኢያቄም የሀና ፍስሐ ኮነ\nፍሬ በረከት ፍስሐ ኮነ\nምክንያተ ድሂን ፍስሐ ኮነ\nኪዳነ ምህረት ፍስሐ ኮነ\nድንግል ተወለደች ፍስሐ ኮነ\nየጌታየ እናት ፍስሐ ኮነ\n\nበሄዋን ምክንያት ፍስሐ ኮነ\nያጣነውን ሰላም ፍስሐ ኮነ\nዛሬ አገኘነው ፍስሐ ከነ\nበድንግል ማርያም ፍስሐ ኮነ\nየምስራች እንበል ፍስሐ ኮነ\nሀዘናችን ይጥፋ ፍስሐ ኮነ\nተወልዳለች እና ፍስሐ ኮነ\nየዓለም ሁሉ ተስፋ ፍስሐ ኮነ', 'am', 31, 0),\n(2, 'ትህትናሽ ግሩም ነው', 'ትህትናሽ ግሩም ነው\nትህትናሽ ግሩም ነው ደግነትሽም\nእናቱ ሆነሻል ለመድኃኔዓለም\n\nንፅሕት ስለሆንሽ እመቤቴ እመቤቴ\nእንከን የሌለብሽ እመቤቴ እመቤቴ\nየፍጥረታት ጌታ እመቤቴ እመቤቴ\nባንቺ አደረብሽ እመቤቴ እመቤቴ\nየድንግል መመረጥ እመቤቴ እመቤቴ\nዜናው አስገረመን እመቤቴ እመቤቴ\nእሳቱን ታቅፈች እመቤቴ እመቤቴ\nየማይቻለውን እመቤቴ እመቤቴ\n\nምርኩዜ ልበልሽ እመቤቴ እመቤቴ\nጥላ ከለላዬ እመቤቴ እመቤቴ\nጋሻዬ ነሽ አንቺ እመቤቴ እመቤቴ\nለእኔ መመኪያዬ እመቤቴ\nበዓለም እዳልጠፋ እመቤቴ እመቤቴ\nሕይወቴ መሮብኝ እመቤቴ እመቤቴ\nእንደ ወይን አጣፍጪው እመቤቴ እመቤቴ\nድንግል ድረሽልኝ እመቤቴ እመቤቴ\n\nየምሥራቅ ደጃፍ ነሽ እመቤቴ እመቤቴ\nየሁላችን ደስታ እመቤቴ እመቤቴ\nእሙ ለጸሐይ ፅድቅ እመቤቴ እመቤቴ\nየሁሉ ጠበቃ እመቤቴ እመቤቴ\nድንግል የድል አክሊል እመቤቴ እመቤቴ\nድንግል የፅድቅ ሥራ እመቤቴ እመቤቴ\nድንግል መሰላል ነሽ እመቤቴ እመቤቴ\nየተዋህዶ ተስፋ እመቤቴ እመቤቴ', 'am', 32, 0),\n(2, 'እመ አምላክ ሙሽራ ነሽ', 'እመ አምላክ ሙሽራ ነሽ\nእመአምላክ ሙሽራ ነሽ\nለቃል ማደሪያ ለመሆን የበቃሽ\n\n12 ዓመት ቤተ መቅደስ የኖርሽ\nየመመረጥ ጸጋ ከጌታ ያገኘሽ\n\nበአብሣሪው መልአክ እጹብ ድንቅ ዜና\nከሰማይ መጣልሽ አቋርጦ ደመና\nበ6ኛው ወር ተልኮ ገብርኤል\nቤተመቅደስ ገባ ሊያበስራት ለድንግል\n\nበልዩ ሰላምታ ሰላም ለኪ አለሽ\nየክርስቶስ እናት በጣም ደስ ይበልሽ\nመላእክት በሰማይ ያመሰግኑሻል\nክብር ለአምላክ እናት ይድረሳት ይሉሻል\n\nበማሕፀንሽ ቢያድር የሠራዊት ጌታ\nለመሆን ተመረጥሽ የአምላክ ቅድስት ቦታ\nየፈጣሪ እናት መሆንሽን ተረድቶ\nሰላም ላንቺ ይሁን አለሽ እጅ ነሥቶ', 'am', 33, 0),\n(2, 'ሰላም ለኪ እያለ', 'ሰላም ለኪ እያለ\nሰላም ለኪ እያለ\nሐርና ወርቁን ስታስማማ\nየገብርኤል ድምፅ ተሰማ\nተሰማ የመልአኩ ድምፅ ተሰማ\nተሰማ የገብርኤል ድምጽ ተሰማ\n\nውሃ ስትቀጂ ክንፉን እያማታ\nሊያበስርሽ የመጣው በታላቅ ደስታ\nከሞገስሽ ብዛት ሲታጠቅ ሲፈታ\nአቅርቦልሽ ነበር የክብር ሰላምታ\n\nየምሥራቹን ቃል ምስጢር ተሸክሞ\nገብርኤል ተላከ ሊያረጋጋት ደግሞ\nእርጋታን ተሞልታ ነገሩን መርምራ\nየመልአኩን ብሥራት ሰማችው በተራ\n\nይደሰታል እንጂ መንፈሴ በአምላኬ\nበምስጋና ሳድር ዘወትር ተንበርክኬ\nሃሳቤ ለቅፅበት ሌላ መች ያስባል\nለእኔ ልጅን መውለድ እንዴት ይቻለኛል\n\nከአንቺ የሚወለደው ልዑል ነው ክቡር\nየተመስገነ በሰማይ በምድር\nምስጢሩ ኃያል ነው ይረቃል ይሰፋል\nከአንቺ በቀር ይኼን ማን ይሸከመዋል\n\nእጹብ ነው ድንቅ ነው አንቺን የፈጠረ\nአንቺን በመውደዱ ሰውን አከበረ\nዓለም ይባረካል በማሕፀንሽ ፍሬ\nክብርሽን አልዘልቅም ዘርዝሬ ዘርዝሬ', 'am', 34, 0),\n(2, 'በሐጢያት ያደፈ', 'በሐጢያት ያደፈ\nበሐጢያት ያደፈ ሆኗል ሰውነቴ\nአብቂኝ ለንስሀ አማልጅኝ እናቴ\n\nበሐጢያቴ ብዛት ልቤ ሲታወር\nተብትቦ ሳይጥለኝ የሐጢያቴ ድር\nበጣጥሰሽ ጣይልኝ የሐጢያቴን ወጥመድ\nድንግል ሆይ አስታርቂኝ አርቂኝ ከዚህ ጉድ\n\nመቆም አቅቶኛል በደሌ በዝቶብኝ\nእማፀንሻለሁ ልመናዬን ስሚኝ\nሐጢያቴን መሸከም እኔ አልቻልኩምና\nእናቴ ሆይ ስሚኝ ድንግል በፅሞና\n\nነገ ዛሬ እያልኩኝ ቀጠሮ ሳበዛ\nዘመኔ ሲፈፀም ሁሉም እንደዋዛ\nየመዳን ቀን አሁን እንደሆነ ዛሬ\nአስታውሽኝ እናቴ እንዳላጣ ፍሬ', 'am', 35, 0),\n(2, 'አስታርቂኝ', 'አስታርቂኝ\nአስታርቂኝ ድንግል ማርያም\nከልጅሽ ከመድኃኔዓለም\n\nአስታርቂኝ ኃጢአትን ሰርቼ\nአስታርቂኝ ጫካ ውስጥ ቆሜአለው\nአስታርቂኝ ሥራዬ አሳፍሮኝ\nአስታርቂኝ ዘወትር አነባለው\nአስታርቂኝ ልጄ አዳም ብሎ\nአስታርቂኝ አምላኬ ሲጠራ\nአስታርቂኝ እነሆኝ ለማለት\nአስታርቂኝ አንደበቴ ፈራ\n\nአስታርቂኝ ሀብትን ተካፍዬ\nአስታርቂኝ ከገዛ አባቴ\nአስታርቂኝ ከቤቴ ኮበለልኩ\nአስታርቂኝ ይሻለኛል ብዬ\nአስታርቂኝ ገፍቼ ወጥቼ\nአስታርቂኝ የቤቴን ገበታ\nአስታርቂኝ ልበላ ተመኘሁ\nአስታርቂኝ የእንስሳት ገፈራ\n\nአስታርቂኝ ወደ አባቴ ልሂድ\nአስታርቂኝ አሁን ተነሥቼ\nአስታርቂኝ ይቅርታ ልጠይቅ\nአስታርቂኝ እግሩ ስር ወድቄ\nአስታርቂኝ ልጅነቴ ቀርቶ\nአስታርቂኝ አድርገኝ ባርያህ\nአስታርቂኝ ከሞያተኞችህ\nአስታርቂኝ እንደ አንዱ ቆጥረህ\n\nአስታርቂኝ ገና ሩቅ ሳለው\nአስታርቂኝ አባቴ አይቶኝ\nአስታርቂኝ ወደእኔ ሮጦ\nአስታርቂኝ አቅፎ ነው የሳመኝ\nአስታርቂኝ ጠፍቶ የነበረው\nአስታርቂኝ ተገኘልኝ አለ\nአስታርቂኝ ሞቶ የነበረው\nአስታርቂኝ ደግሞ ሕያው ሆነ', 'am', 36, 0),\n(2, 'ለምኚ', 'ለምኚ\nለምኚ ድንግል ለምኚ\nለኃጥአን አይደለም ለጻድቃን\n\nታላቅ ስጦታዬ አዛኝ ሩህሩ ነሽ\nየጌታዬ እናት ጸጋን የተሞላሽ\nየአምላክ ማደሪያ ለምነሽ አስምሪኝ\nአማናዊት ጽዮን ከእኔ አትለይኝ\n\nሐዘንሽ ሐዘኔ ለእኔ ይሁን ድንግል\nየተንከራተትሽው በሀገረ እሥራኤል\nትዕግሥትሽን ሳየው ልቤ ይመሠጣል\nየሐዘን እንባ ጎርፍ ዓይኔን ይሞላዋል\n\nበቀራንዮ እንባ በዚያ የፍቅር ቦታ\nበእግረመስቀሉ ስር ከክርስቶስ ጌታ\nለእኛ ተሰጥተሻል እናት እንድትሆኚን\nልጆችሽ ነንና ምልጃሽ አይለየን\n\nእደበቴን ጌታ ለምሥጋና ፍታ\nደስ ይበልሽ ብዬ ላሰማ ሰላምታ\nአንደበቴን ጌታ በምስጋና ሙላው\nደስ ይበልሽ ብዬ እኔም ላመስግናት', 'am', 37, 0),\n(2, 'የቀደሙት አባቶች ምሳሌ', 'የቀደሙት አባቶች ምሳሌ\nየቀደሙት አባቶች ምሳሌ ያጡልሽ\nቢበዛላቸው ነው በልባቸው ፍቅርሽ\nእኛም እንጮሃለን በኤፍሬም ውዳሴ\nበሕረያቆብ ፅኑ በቅዳሴ\n\nታቅፈናል በክንድሽ ለዘላለም ልጆችሽ ነንና\nዘመርን በደስታ ሰለ ፍቅርሽ አንስተን በገና\nሃመልማለ ሲና ታምራዊ ደስታን ያየንብሽ\nደስ አለት ነፍሳችን ተደግፋ ቆማ በኪዳሽ\n\nበቀንና ለሊት በምስጋና እንጠራሻለን\nቆመናል ማሕሌት ከመቅደስሽ በፍቅርሽ ተማርከን\nበረከትሽ ናፍቆን እጃችንን አነሳን ወደ አንቼ\nበእናትነትሽ ልጆችሽን ድንግል ተመልከቼ\n\nየእውቀት በር ነሽ ፌደላችን የምንማርብሽ\nየአባው ውዳሴ ሞገሳቸው ዘውትር የሚያነሱሽ\nፅድቅን ተምረናል ከሕይወትሽ ግሩም ትሕትና\nአጌተናል ከአንቼ በረከትን የሰማዩን መና\n\nየሕይወታችን ሰላም ምርኩዝችን የደስታ ምንጭ ነሽ\nየማትጠፊ ፋና የገነት በር መሰላል አንቼ ነሽ\nበሥምሽ ተማፅነን የጎደለን አንዳች የለም እና\nላንለይ ከዳጅሽ ተሰበሰብን ቆምን ለምስጋና', 'am', 38, 0),\n(2, 'አዘክሪ ድንግል', 'አዘክሪ ድንግል\nአዘክሪ ድንግል አዘክሪ\nለልጅሽ አሳስቢ አዘክሪ\nለኃጥአን አኮ ለጻድቃን\n\nከአንቺ መወለዱን - አዘክሪ\nበቤተለልሔም - አዘክሪ\nበጨርቅ መጠቅለሉን - አዘክሪ\nመኝታው ግርግም - አዘክሪ\nለኃጥአን አኮ ለጻድቃን\n\nበዚያ በብርድ ወራት - አዘክሪ\nየገበሩለትን - አዘክሪ\nየሃድግና የላም - አዘክሪ\nእስትንፋሳቸው - አዘክሪ\nለኃጥአን አኮ ለጻድቃን\n\nበግብጽ በረሃ - አዘክሪ\nመሰደድሽን - አዘክሪ\nየአሸዋውን ግለት - አዘክሪ\nረሃብና ጥሙን', 'am', 39, 0),\n(2, 'ዘወትር ቢከፈኝ', 'ዘወትር ቢከፈኝ\nዘወትር ቢከፈኝ ደጅሽ መጥቼ\nእፅናናለሁ ያላንቺ የለኝም ብሶቴን የምነግረው\nእዘኚልኝ እራርተሽ ስሚኝ ስማፀንሽ\nድንግል ክብሬ ነሽ ለኔ የሀዘኔ ደረሽ\n\nአስጨናቂው አለም በፊቴ ድቅን ሲልብኝ\nየመከራው ወጀብ አይሎ ዙሪያዬን ሲከበኝ\nመውጫ ቀዳዳውን አጥቼ ስባዝን ስቸገር\nእጄን ይዘሽ ምሪኝ እናቴ ካንቺ ጋራ ልኑር\n\nሀዘን ያጎበጠው ኑሮዬ በፍርሀት ተሞልቶ\nለማንስ ልንገረው የልቤን እኔስ እጅግ ከብዷኛል\nፅናት ያጣው ልቤን አበርቺው በፅጋሽ ጎብኚና\nከኔ ዘንድ አርቂው ብሶቴን ከፊቴ ቁሚና\n\nየምቆጥረው ነገር ዙሪያዬ ወገንም የለኝም\nለችግራ ደርሶ ከጎኔ አለሁ የሚለኝ\nይኼን ክፍ ጊዜ አሻግሪኝ ድልድይ ሁኚና\nበእጆችሽ ይደገፍ ጉልበቴ ልቁም ልበርታና\n\nየሞት ሆኗል የኔስ መንገዴ የበዛ ፈተና\nቀና ብዬ ማየት አልቻልኩም ስብራቴ የፅና\nእንደምን ይፈውስ ህመሜ ከሰው ፊት ያራቀኝ\nበጨለመው ቤቴ ገቢና ይሙላ የጎደለኝ', 'am', 40, 0),\n(2, 'ምን ይሆን ውለታሽ', 'ምን ይሆን ውለታሽ\nምን ይሆን ውለታሽ ድንግል የምከፍልሽ\nላንቺ በመንገሬ ተፈታ ችግሬ\nየደካሞች ምርኩዝ የኃጥአን ተስፋ\nፈጥነሽ ትደርሻለሽ የሰው ልጅ ሲከፋ\nምን በግዞት ቢሆን ጨለማ ቢወርሰው\nእንዳዘነ አይቀርም አንቺን የያዘ ሰው\n\nድንግል ሆይ በምልጃሽ አስቢኝ አሁንም\nደካማ ነኝና መሳሳቴ አይቀርም\nቅዱሳን ስምሽን ምግባቸው አርገው\nይኖራሉ ባንቺ በሀሴት ጠግበው\n\nአትርሺኝ እመአምላክ ቤዛዊት ኩሉ\nላንቺ ሰጥቻለሁ ሕይወቴን በሙሉ\nውዳሴ ማርያምን አልነጥልም ከአፌ\nበእሱ አይቼዋለሁ ፈተናን ማለፌ\n\nየዘነጋሽ ሁሉ ሲቸገር ቢጠራሽ\nአትይውም ችላ አላውቀውም ብለሽ\nላመስግንሽ ድንግል ወገቤን ታጥቄ\nሕይወት አግኝቻለሁ አንቺን በማወቄ', 'am', 41, 0),\n(2, 'የድንግል ማርያምን ክብሯን እንመስክር', 'የድንግል ማርያምን ክብሯን እንመስክር\nየድንግል ማርያምን ክብሯን እንመስክር\nውዳሴዋን እናድርስ ለስሟም እንዘምር\n\nየሰማይ መላዕክት የሚያመሰግኗት\nምዕልተ ውዳሴ የአማኑኤल እናት\nእመቤታችን ሆይ እንወድሻለን\nበምስጋናሽ ቃልም እንጠግባለን\n\nካህናት በማህሌት ያመስግኗታል\nነይ ነይ እያሉ ዘወትር ይጠሯታል\nክብሯ የገባቸው ሊያዩዋት ይመኛሉ\nውዳሴዋን ሰምተው በፍቅር ያለቅሳሉ\n\nአማናዊት መርከብ ነፍሳት የዳኑባት\nየወርቅ መሰላል ጌታን ያየንባት\nየተዋህዶ ምስጢር የተፈጸመባት\nሰማያዊት መቅደስ ድንግል ማርያም ናት\n\nየውዳሴዋን ቃል የሚሰማ ሁሉ\nነፍሱ ትጽናናለች ይፈወሳል ቁስሉ\nአምኖ የተጠጋት ፍቅሯ የማረከው\nየሚያመሰግናት የታደለ ሰው ነው', 'am', 42, 0),\n(2, 'የነቢያት ዜናቸው ማርያም', 'የነቢያት ዜናቸው ማርያም\nየነቢያት ዜናቸው ንጽህይት ነሽ\nየህያዋን እናት ነሽ\nማርያም ደስይበልሽ\n\nየልበስሽ መዓዛ ደስይበልሽ\nየሊባኖስ ሽቶ ደስይበልሽ\nእቴ ሙሽራዬ ደስይበልሽ\nየኃጥአን አለኝታ ደስይበልሽ\n\nጸጋን የተመላሽ ደስይበልሽ\nየዓለም መኩሪያ ደስይበልሽ\nየእግዚአብሔር ከተማ ደስይበልሽ\nየሽቱ መኖሪያ ደስይበልሽ\n\nአንቺ የገነት ምንጭ ደስይበልሽ\nየህይወት ጉድጓድ ደስይበልሽ\nዛሬም ለዘለዓለም ደስይበልሽ\nመጠጊያዬ ነሽ ደስይበልሽ', 'am', 43, 0),\n(2, 'ፅላት ዘሙሴ እፅ ጳጦስ', 'ፅላት ዘሙሴ እፅ ጳጦስ\nፅላት ዘሙሴ እፅ ጳጦስ ዘሲና\nፅናፅን ፅናፅል ፅናፅል የሀሮን ካህን\n\nአልፌ አለሁና እመቤቴ ያን ሁሉ መከራ\nከእኔ ጋር ስለሆንሽ እመቤቴ ስምሽን ስጠራ\nበዚያ በጭንቅ ቀን ድንግል ስምሽን ስጠራ\nማን ያድነኝ ነበረ ድንግል ስምሽን ባልጠራ\nበሞትና በህይወት ድንግል መካከል ብሆንም\nተአምርሽ አነሳኝ ድንግል ማርያም አልተውሽኝም\n\nእጅግ የከበደ ነበረ ያገኘኝ ፈተና\nታሪክ ሆኖ ቀረ እመቤቴ ባንቺ ዳንኩኝና\nዙሪያ የሚያሰፈራ ድንግል ፅኑ ነው ገድሉ\nበዚህ የወደቁ ድንግል እንዴት ይተርፈሉ\nስምሽን ድጋፍ ሆኖ ድንግል ከስር ተነጠፈ\nበሚያስደንቅ ሚስጢር ድንግል ህይወቴ ተረፈ', 'am', 44, 0),\n(2, 'ፀጋን የተመላሽ ሆይ', 'ፀጋን የተመላሽ ሆይ\nፀጋን የተመላሽ ሆይ ክብር ላንቺ ይገባል\nየአሸናፊ የእግዚአብሔር እናት ሆነሻል\nከሴቶች ሁሉ ተለይተሽ አንቺ ተመርጠሻል\n\nሰላም ልበልሽ የጌታዬ እናት\nጽድቅ ያየንብሽ ምክንያተ ድህነት\nልባችን ያውጣ በጎ ነገር\nለአለም እንመስክር ያንቺን ግብር\n\nየምስራቅ ፀሐይ ኩራቴ ነሽ\nእጅግ ልዩ ነው ደግነትሽ\nልቀኝ ለክብርሽ እንደ ያሬድ\nየአበው ተስፋ ሰላም ወዳድ\n\nየድል አክሊል ሰላማዊት\nህብስተ መና ምግበ ህይወት\nከልቤ ሆኜ እስቲ ላድንቅሽ\nእንደ አባ ኤፍሬም በዝቶልኝ ፍቅርሽ\n\nየመስቀሉ ስር ስጦታ ነሽ\nለአለም መጽናኛ የተመረጥሽ\nየሚያቃልሉ ክብርሽን ንቀው\nይማልዳሉ ከፊትሽ ወድቀው', 'am', 45, 0),\n(2, 'የጌታዬ እናት', 'የጌታዬ እናት\nየጌታዬ እናት ማርያም\nየበረከት ምንጭ የሰላም\nመከራ በዝቶ ተጨንቀናል\nድንግል ነይልኝ ተማፅነናል\n\nቀባሪ ሲያጡ አዛውንቱ\nሜዳ ሲወድቁ ህፃናቱ\nእሳት ሰደድ እንዲቆሙ\nአማልጅን ድንግል ማርያም\n\nየራቀው ሰላም እንዲቀርበን\nፍቅር አንድነት እንዲከበን\nከልጅሽ ጋራ ነይልኝ\nኑሮአችን መልካም እንዲሆን\n\nውሀ የሌለው ምንጭ ሆነናል\nመሬት ታቅፈን ዘር አተናል\nየኢትዮጵያ እናት እመቤቴ\nሁሉን ባርኪልን በረድኤት\n\nድፍረት ጭካኔ አመፅ ሞልቷል\nበጎ ደግ ሰው ከአለም ጠፍቷል\nማን መልካም ነገር ያሳየናል\nወደ ማደሪያሽ አቅንተናል', 'am', 46, 0),\n(2, 'አክሊላችን ነሽ', 'አክሊላችን ነሽ\nአክሊላችን ነሽ ህይወታችን\nትምክህታችን መፅናኛችን\nስምሽን ጠርተን ከሞት ድነናል\nምልጃሽ እረድቶን ቀና ብለናል\n\nፍሬ የሞላብሽ መልካሟ ተክል\nመፈወሻችን የህይወት ጠበል\nበምልጃሽ ፋና አይናችን በርቶ\nክብርሽን አየን በብርሀን ፋክቶ\n\nጨው የሞላብሽ አዲስ ማሰሮ\nአለም ጣፈጠ ምሬት ተሽሮ\nተለውጠናል አዲስ ሆነናል\nድንግል ለክብርሽ እጅ ነስተናል\n\nመሰረቶችሽ የተቀደሱ\nክብርና ግርማን ፅድቅ የለበሱ\nእንከን የሌለሽ ንፁህ ተራራ\nበልጅሽ ፅዳል አለሙ በራ\n\nውዳሴሽ በዛ በአፋችን\nፍቅርሽ ታተመ በልባችን\nማርያም ማርያም ነው አዲስ ምስጋና\nለንጉስ እናት ይገባልና', 'am', 47, 0),\n(2, 'በጎ ስጦታዬ', 'በጎ ስጦታዬ\nበጎ ስጦታዬ ፍፁም በረከቴ\nካጠገቤ አትራቂ ድንግል እመቤቴ\n\nአልታክትም እኔ ሁሌ እጠራሻለሁ\nየሀዘኔን መርሻ አንቺን አግኝቻለሁ\nእንዴት አልፈው ነበር ያን ሁሉ መከራ\nከጎኔ ባቆሚ ድንግል ከኔ ጋራ\n\nቢታጠር መንገዴ ቅጥር ቢበዛበት\nይበረታል እግሬ አንቺ ካለሽበት\nየእሳቱ ግርማ ቢበዛ ፎጨቱ\nልቤን አሳረፍኩት ባንቺ ባዛኝቱ\n\nየቀደመው እባብ አውሬው አያድነኝ\nፍፃሜዬ እንዲያምር ድንግል ለምኝልኝ\nየቆምኩ ሲመስለኝ ተንገዳግጃለሁ\nየዛሬውን እንጂ የነገን መች አየሁ\n\nዛሬ ተመልሼ አየሁት ደግሜ\nምንም አላተረፍኩ በዚች ዓለም እድሜ\nልጅሽን አምኜ አንቺን እይዛለው\nየላላው ጉልበቴን አበረታዋለሁ\n\nጎዶሎዬ ሞልቷል ቤቴ ሰላም ለብሷል\nየጭንቅ አማላጄ አንቺን ተጠግቷል\nጠላቴ ቢፀፍም የእዳዬን ጦማር\nአልሞትም በጭራሽ ሳለው ካንቺ ጋራ', 'am', 48, 0),\n(2, 'ፅዮንን መርጧታል', 'ፅዮንን መርጧታል\nፅዮንን መርጧታል ይህንን አዉቃለዉ\nእናቱ ናትና ብፅዕት እላታለዉ\n\nከሴቶች ሁሉ የተለየች ናት\nበድንቅ ጥበብ ቃል ተዋሃዳት\nአለም እንዲድን ምክንያት ሆና\nእንዴት አላቀርብ ለሷ ምስጋና\nየናቁሽ ሁሉ ወደ እግርሽ ጫማ ይሰግዳሉ\nአማልጂኝ ድንግል ማርያም እያሉ\n\nየሰላም ንጉስ ስለወደዳት\nርግቤ ሆይ ልበል ልዘምርላት\nቅዱሱ መንፈስ በልቤ ላይ ነዉ\nእያነሳሳኝ ማርያም እላለሁ\nየናቁሽ ሁሉ ወደ እግርሽ ጫማ ይሰግዳሉ\nአማልጂኝ ድንግል ማርያም እያሉ\n\nየገነት መግቢያ ተከፍቷል በሩ\nብፁዓን ናቸዉ ስሟን ሚጠሩ\nከንዑዳን ጋር በመሰለፌ\nክብርት ሆናለች ቅኔ መፅሃፌ\nየናቁሽ ሁሉ ወደ እግርሽ ጫማ ይሰግዳሉ\nአማልጂኝ ድንግል ማርያም እያሉ\n\nዉዳሴን ሰማሁ ከራማ ሃገር\nድምጿ አፅናናኝ በኤፍሬም መንደር\nበትህትና ዉስጤን ሸልሜ\nአከብራታለሁ በዜማ ቆሜ\nየናቁሽ ሁሉ ወደ እግርሽ ጫማ ይሰግዳሉ\nአማልጂኝ ድንግል ማርያም እያሉ', 'am', 49, 0),\n(2, 'እረፍቴ እልሻለሁ', 'እረፍቴ እልሻለሁ\nእረፍቴ እልሻለሁ የደስታዬ መፍሰሻ\nሰላሜ ነሽ ድንግል የጭንቄ ማስታወሻ\n\nምሬት በሞላኝ ጊዜ የፍደላት ጠግቤ\nአስቦ እናትነትሽን ተፅናንቷል ባንቺ ልቤ\nነፍሴ በሰላም አትርቅ በጎነትሽን አልርሳ\nአይዛል አይደክም ልቤ ስለ ፍቅርሽ ቢነሳ\n\nመታደረቀ ዛሬ ከምልጃሽ ዛፍ አርፌ\nጭንጫው ጥርሴን አይነካኝ ታድሶልኛል ከንፈሬ\nፅሎቴ ከልካይ የለው ዘልቆ ገብቷል ከእልፍኙ\nደመናው ተገላልጧል ድንግል ቆመሽ በቀኙ\n\nከድንግል ታንኳ በላይ ብንሰራ ብርቱ ንጥቅያ\nለሚፈጥነው ዘመኔ አኑሪለት ማሰሪያ\nበማይራራው ህመሜ ሀሰትን አደርጋለሁ\nእጅሽን ስትዘረጊ እረፍቴን አየዋለው\n\nአይመጣም በፍፁም ቀድሞ ለቅሶዬ እንደ ራዕይ\nየተሰማኝ ተሰምቶኝ ተመልሷል እንባዬ\nአመዳዊ ተገልጦ አጥርቷል ሰውነቴ\nሰማያዊቷ ሰማይ ክብርሽ ሞልቷል አይኖቼ', 'am', 50, 0),\n(2, '7ቱ መንጦላይት', '7ቱ መንጦላይት\nሰባቱ መንጦላይት ወዴት ተጋረዱ\nሰባቱ መብራቶች ወዴት ተሰናዱ\nታናሽ ሙሽራ ነሽ የ15 አመት\nባንቺላይ ሲፈፀምእንግዳ ስርአት\n\nአንዴ እየታጠቀ አንዴም እየፈታ\nገብርኤል ሲያበስርሽ በፍፁም ሰላምታ\nይኩነኒ ብለሽ ስትቀበይዉ\nመለኮት እንዴት የው የተዋሀደዉ\nይህን ባሰብኩኝ ቁጥር ልቤ ይመሰጣል\nከዚህ በላይ ፍቅርስ እንዴት ይገለጣል\n\nሁሉን የሚወስን ባንቺ ተወሰነ\nከሶስቱ አካል አንዱ ቃልም ሰጋ ሆነ\nስፋት እና ጥበት ሰማይ እናምድር\nባንቺ ተገናኙ ገባሪ እና ግብር\n\nእንዴት ቢመርጥሽ ነው እንዴት ቢያከብርሽ\nትናንትናን ዛሬን ያገናኘብሽ\nብዛት ና ወሰን ግዝፈትና ርቀት\nባንቺ ተዋሀዱ ፈጣሪ እና ፍጥረት\n\nሚስጢር ሊመረምር ይመጣል ህሊና\nያልፋል ይሻገራል ከሰማይ ደመና\nነገር ግን አይችልም ምንም ቢገሰግስ\nከመሰወሪያው ዘንድ ከልጅሽም ቢደርስ\nስለዚህ አቅቶት ደክሞት ይመለሳል\nመልካም ውዳሴሽን በአድናቆት ያደርሳል', 'am', 51, 0),\n(2, 'ስምሽን ስጠራው', 'ስምሽን ስጠራው\nስምሽን ስጠራው ድንግል ማርያም\nለአንደበቴ ማር ነው ለልቤ ሰላም\nስምሽን ስጠራው ማርያም\n\nትውልድ ነኝ እና ልጅሽ የፈጠረኝ\nድንግል እመቤቴ ላንቺ ምስጋና አለኝ\nበፍቃደ እግዚአብሔር በአባቶቼ ፀጋ\nሰአሊለነ እላለው ሲመሽም ሲነጋ\n\nበጠየቅሽው ግዜ ወይኑን እንዲመላው\nአክብሮሻል እና በቃና ገሊላ\nየሰላም እናት ሆይ ሰላም ልበልሽ\nዘመኔም ይፈፀም ሳመሰግንሽ\n\nበሰላምታ ድምፅሽ መንፈስ ተመልቼ\nአደግድጌ ልቁም እጆቼን ዘርግቼ\nበአፌቃል ጮሄ ልመስክር በብርቱ\nቅድስት ድንግል ማርያም የእግዚአብሔር እናቱ\n\nከሰማይ ሲገኝ ነው ማወደስ\nሲገለጥ ሲፈቀድ ከመንፈስ ቅዱስ\nማርያም ህይወቴ ነሽ ምክንያት ለመድኔ\nብዙነው ሚስጥሩ አንቺን ማመስገኔ', 'am', 52, 0),\n(2, 'ነይ ነይ', 'ነይ ነይ\nነይ ነይ የሁሉ እናት ማርያም\nበመካከላችን ተገኝ ተሽ እንድትባርኪን\nይኸው ጠርተንሻል በአንድነት ሆነን\n\nየቅድስና አክሊል ማርያም\nየደባምች በጉር ማርያም\nለተዋህዶ ልጆች ማርያም\nየመድን ራስ ቁር ማርያም\nየብርሀን ደመና ማርያም\nየቅዱሳን ደብር ማርያም\n\nአዳም አባታችን ማርያም\nበደብረ ቅዱስ ሳለ\nይመባ\nገነትን እያየ\nያመሰግኑሻል\nውድስቴ አንቺ እያላት\n\nየምስጋና መቅደስ ማርያም\nአውደ ምህረታችን ማርያም\nለአለም ያበራሽ ማርያም\nመቅረዘ ብርሀን ማርያም\nይኸው ተገኝቷል እና ማርያም\nበስምሽ አንድ ሆነን ማርያም', 'am', 53, 0),\n(2, 'በባቢሎን ወንዞች', 'በባቢሎን ወንዞች\nበባቢሎን ወንዞች አጠገብ ተቀምጠን\nፅዩንን ባሰብናት ጊዜ አለቀስን\n\nመሰንቆአችንን በዛፍ ላይ ሰቀልን\nላንዘምር ምለናል በዚያ ለማረከን\nየፅዬን ዝማሬ አይሆንም ለዳጎን\nአይሰማም በዚያ ቋንቋችን ለአዞጦን\n\nአይርድም ልባችን በፈርኦኖች ጬኸት\nሀይላችን ይበዛል የፈረደልን ስለት\nውሀችንን ገዝተን በዋጋ ብንጠጣ\nእናምናለን በርሱ ልጆቹን አይረሳም\n\nተሽረን አንቀርም ከበገናችን ላይ\nይሰማል ቅኔ አችን ፅዩን አደባባይ\nቁርበታችን ጠቁሮ ወንዛችን ቢጠፋ\nእንለመልማለን አለን ፅኑ ተስፋ\n\nዘመናችን ያድሳል በምህረቱ\nአይቀርም አንድ ቀን የባቢሎን ውድቀት\nየሰለጠኑብን ድንገት ይጣላሉ\nይሰጣናል ለኛ የክብር አክሊሉ', 'am', 54, 0),\n(2, 'ወሰኑስ', 'ወሰኑስ\nወሰኑሰ ለያእቆብ\nየአምላክን ይመስላል ወሰኑስ\nድንግል ውበትሽ ወሰኑስ\nሁለንተናሽ ውበት ወሰኑስ\nነውር የሌለብሽ ወሰኑስ\nድንግል የዳዊት ልጅ ወሰኑስ\nየአባትሽን ቤት እርሺ ወሰኑስ\nበአለሙ ንጉስ ወሰኑስ\nታይቷል ውበትሽ ወሰኑስ\n\nስደተኛው ያእቆብ ወሰኑሰ\nበመንገድ ተኝቶ ወሰኑሰ\nእጅጉን ተፅናና ወሰኑሰ\nድንግል አንቺን አይቶ ወሰኑሰ\nለኔ ለሀጥያተኛ ወሰኑሰ\nመድሀኒቴ ነሽ ወሰኑሰ\nነገ ሌላ ሁኝልኝ ወሰኑሰ\nጠላቴ እንዲሸሽ ወሰኑሰ\n\nከገደል አፋፍ ላይ ወሰኑሰ\nጎስቋላ ህይወቴ ወሰኑሰ\nድልድል ሁኚ አንቺ ወሰኑሰ\nአሻግሪያት እናቴ ወሰኑሰ\nነፍሴን አሳርፊያት ወሰኑሰ\nበምልጃሽ ቁጥር ወሰኑሰ\nቃልኪዳንሽ ከቧት ወሰኑሰ\nዘላለም ትኑር ወሰኑሰ', 'am', 55, 0),\n(2, 'ያዕቆብ ከቤርሳቤህ', 'ያዕቆብ ከቤርሳቤህ\nያዕቆብ ከቤርሳቤህ ወደ ካራን ሲሔድ\nየለውም ነበረ አማካሪ ዘመን\nፅሀይ ጠልቃ ነበር ከዛ እንደደረሰ\nከእራሱም በታች ድንጋይ ተንተራሰ\n\nህልምንም አለመ ታላቁን እራይ\nመሰላል ተተክሎ ከምድር እስከ ሰማይ\nሲወጡ ሲወርድ መላዕክት በእሷ ላይ\nእግዚአብሔር እንቆሙ ከእላይ ከጫፏ ላይ\n\nየአባቶቼ አምላክ እኔ እግዚአብሔር ነኝ\nይህንን ለእርስትክ እሰጥሀለው\nዘር እንደ አሸዋ በምድር ይበዛል\nበአራቱም ማዕዘን ህዝብህም ይሆናል\n\nአበው በምሳሌ እንደ ተናገሩት\nከምድር እስከ ሰማይ አምላክ የዘረጋት\nበላይዋ ተቀምጦ በግልፅ የታየባት\nየያዕቆብ እራእይ እመቤታችን ናት\n\nሰማይና ምድር የሚታረቁባት\nወልደ ጓለምያ የተወለደባት\nመላዕክት በሰማይ በአንድ የዘመሩባት\nታላቋ መሰላል እመቤታችን ናት', 'am', 56, 0),\n(2, 'ኪዳነ ምህረት', 'ኪዳነ ምህረት\nኪዳነ ምህረት\nአውጪኝ ከመከራ ከዚህ አለም ሁከት\nደካማ ስለሆንኩ ቅደሚልኝ ከፊት\n\nበለሱን በእጁ ቀጥፎ ስለበላ\nአዳም አባታችን ከአምላኩ ተጣላ\nአሸጋግሮ ያየሽ የድህነቱ ተስፋ\nአንቺ ነሽ ትምክህቱ አዳም እንዳይጠፋ\n\nበሞት ቢቀየርም የነበረው ህይወት\nድኖብሻል በአንቺ ኪዳነ ምህረት\nበመፀሀፍ አይን አልኖረም ተጻፍኖ\nተሻገረ ሞትን ባንቺ ተሸፍኖ\n\nትምክህቱ አንቺ ነሽ የንፅህና ልብሱ\nየሕይወት ፅዋ ክብሩና ሞገሱ\nየዳመነው ተስፋ ተንጠልጥሎ አልቀረም\nምህረቱ ዘንቦ ፍጥረት አልሰጠውም\n\nበጎ ስራው ነው ጻድቁ የሚድነው\nወደ አንቺ የሚጠጋው እንደኔ ያለው ኃጥኡ ነዉ\nየሞተማ ማነው እድናለው ብዬ\nበአንቺ ሲሸፈን ነው የከፍው ስራዬ', 'am', 57, 0),\n(2, 'ማርኮኛልና', 'ማርኮኛልና\nማርኮኛልና ክብርሽ\nላንቺ ልገዛ ላመስግንሽ\n\nማርኮኛልና ክብርሽ የተዋህዶ ምስጢር\nማርኮኛልና ክብርሽ ባንቺ ተፈፀመ\nማርኮኛልና ክብርሽ ልጅሽ መድኃኔ ዓለም\nማርኮኛልና ክብርሽ ዓለሙን አዳነ\n\nማርኮኛልና ክብርሽ እስከ ዘለዓለም\nማርኮኛልና ክብርሽ እመ አምላክ እላለው\nማርኮኛልና ክብርሽ ስምሽን መጥራቴ\nማርኮኛልና ክብርሽ እጅል እረካለው\n\nማርኮኛልና ክብርሽ መነሳት መውደቄ\nማርኮኛልና ክብርሽ በቤቱ መፅናቴ\nማርኮኛልና ክብርሽ በአንቺ ስለሆነ\nማርኮኛልና ክብርሽ ነይ ነይ እመቤት\n\nማርኮኛልና ክብርሽ ታምርሽን አይቼ\nማርኮኛልና ክብርሽ ሁልጊዜ እደነቃለው\nማርኮኛልና ክብርሽ ቃላቶች ያጥሩኛል\nማርኮኛልና ክብርሽ እኔ ምን እላለው\n\nማርኮኛልና ክብርሽ እመቤቴ ማርያም\nማርኮኛልና ክብርሽ አንባ መጠጊያዬ\nማርኮኛልና ክብርሽ ሰላሜ ነሽ ድንግል\nማርኮኛልና ክብርሽ በችግር መውጫዬ', 'am', 58, 0),\n(2, 'ወደ ምስራቅ እዩ', 'ወደ ምስራቅ እዩ\nወደምስራቅ እዩ ወደ ፀሀይ መውጫ\nድንግልን ክበቧት እንበል ሀሌ ሉያ\nየአምላክ እናት ለአዛኝት እልል እንበልእንዘምርላት\n\nወገኖች ተነሱ እናታችን መጣች\nስሟን ስንጠራ መቼ ትቀራለች\nየተከዘን ልታፅናና ነይ ስናላት ትመጣለች እና\n\nየፅጌው ማህሌት በፀሎት ሲጀመር\nማርያም ትመጣለች ቀደመና በአየር\nንኢ ስንል በሰአታት\nልትባርከን ትመጣለች በእውነት\n\nፍልሰታ ሲጀመርቃልኪዳን ገብታለች\nየለሊት ውዳሴ ንኢን ትሰማለች\nከሰአታቱ በበረከት\nልጎበኘን ትመጣለች በእውነት\n\nበፍፁም ቸርነት እንዲምረን ጌታ\nበአማላጅነትሽ ሁኝልን መከታ\nእናታችን አለኝታችን\nእንድናለን ድንግል አንቺን የዘን', 'am', 59, 0),\n(2, 'የድህነታችን ፊደል', 'የድህነታችን ፊደል\nየድህነታችን ፊደል\nበክብር የተፃፈባት\nማርያም የቃል ማደሪያ\nእንቁ መዝገባችን ናት\n\nሰማያዊ ጠል ረቦባታል\nከጥማታችን አርክቶናል\nበስደት ሆነን በክፍ ቀን\nማርያም ብለናል እንዳይጨንቀን\n\nየብስራት ቀንበር ይዛ በአፏ\nየሰላሟ ርግብ ታየ ክንፏ\nበልዩ ክብር በእርሷ ፅጋ\nቀስተ ደመና ተዘረጋ\n\nየርህራሔ መገኛ ናት\nከመስቀሉ ስር ያገኘናት\nፊቷ ጠውልጓል በእንባዋ\nማዘል ይችላል ትከሻዋ\n\nየብዙ ብዙ የሚሆኑት\nዙፈኑን በክብር የከደኑት\nበመላዕክቱ ታጅባለች\nየመዳናችን ምልክት ነች', 'am', 60, 0),\n(2, 'በምን በምን', 'በምን በምን\nበምን በምን እንመስላት ድንግል ማርያምን\nምሳሌ የላትም የላትም ክብሯን የሚመጥን\n\nየሙሴ ፅላት ነሽ የምህረት ቃልኪዳን\nየያእቆብ መሰላል የአብርሀም ድንኳን\nየብርሀን መውጫ የኖህ ድንቅ መርከብ\nየመላእክት እህት የእሩሩሀን እርግብ\n\nየሰለሞን አክሊል የአሮን በትር\nየእዝራ መሰንቆ የጌድዮን ፀምር\nድንግል እመቤትናት የፃድቃኖች በር\nሆና ተገኝ ታለች የአምላክ ማህደር\n\nየቅዱሳን እናት የአምላክ ንግስት\nችላ ተሸከመች መለኮተ እሳትን\nብርሀን ትሁነን ጨለማን ገላልጣ\nአማልዳ ታስምረን ከዚህ አለም ጣጣ\n\nከማር ይጣፍጣል የድንግል መአዛ\nአምላክን አቅፋለች በ2 እጇ ይዛ\nአለም ሁሉ የዳነው በልጅሽ ነው እና\nእናታችን ፅዮን ይድረስሽ ምስጋና', 'am', 61, 0),\n(2, 'ቅኔ ከአፌ ፈሰሰ', 'ቅኔ ከአፌ ፈሰሰ\nቅኔ ከአፌ ፈሰሰ\nየአንቺን ስም እያወደሰ\nማርያም ማርያም እያልኩኝ\nሰልፉን በድል አለፍኩኝ\n\nህይወት በሞት ተደምድሞ\nስጋ በነብሴ ተሹሞ\nጠላት በሴራው ሳይጥለኝ\nድንግል ምልጃሽ ነው ያዳነኝ\n\nነጋ የክፉ ጨለማ\nጥልቁ ስምሽን ሲሰማ\nመቼም ጠርቼሽ አላፍርም\nፅንቷል ኪዳንሽ ዘላለም\n\nጎድሎ አያውቅም መዳፌ\nላንቺ ቅኔ ተሰልፌ\nትርፌ በረከቴ ነሽ\nአምሳል ወደር የሌለሽ\n\nዛሬስ የሚያስፈራኝ የለም\nከቦኝ የልጅሽ ሰላም\nትምክህት ጋሻ ሆነሽኛል\nግርማሽ ዙሪያዬን ከቦኛል', 'am', 62, 0),\n(2, 'ማርያም በልጅሽ', 'ማርያም በልጅሽ\nማርያም በልጅሽ ከሞት ድነናል\nከድቅድቅ ጨለማ ብርሀን ሆነናል\nበገባልን ኪዳን ህይወት አጊተናል\n\nየአዳም ተስፋ ማርያም\nየኖህ ቃልኪዳን ማርያም\nየሴም ቡራኬ ማርያም\nየአብርሀም ድንኳን ማርያም\nሁሌ እንጠራሻለን እያልን እናቴ\nየኪሩቤል አምሳል ድንግል እመቤቴ\n\nየአብርሀም ማረፍያ ማርያም\nንፅይት ሙሽራ ማርያም\nበቀን በለሊት ማርያም\nጠብቂኝ አደራ ማርያም\nሞገሴነሽ ክብሬ የነፍሴ አለኝታ\nእናቴ እልሻለው ዘውትር ጠዋት ማታ\n\nየጌድዮን ፀምር ማርያም\nየአሮን በትር ማርያም\nንግስተ ሰማይ ማርያም\nሀገረ እግዚአብሔር ማርያም\nምስጢረኛዬ ነሽ ሁሉን የምታቂ\nሀጥያቴም በዛ ከኔ አትራቂ\n\nየሽቶ ሙዳይ ማርያም\nየሳሙኤል ማርያም\nየፃድቃን ሞገስ ማርያም\nየፅድቅ አክሊል ማርያም\nየሀዘኔ መፅናኛ ድንግል ትምክህቴ\nህይወቴ እንዲለወጥ ባርኪኝ እመቤቴ', 'am', 63, 0),\n(2, 'ቀስተ ደመናዬ', 'ቀስተ ደመናዬ\nኪዳነ ምህረት ቀስተ ደመናዬ\nከሞት ወደ ህይወት መሸጋገሪያዬ\nከቶ አልተውሽም ከእንግዲህ በኃላ\nእረፍት አግኝቻለሁ በኪዳንሽ ጥላ\n\nበሞት ትከሻ ላይ ተረማምጃለሁ\nፍቅርሽን አንግቤ ቤትሽ እኖራለሁ\nጠላት የማይደፍረው ኪዳንሽ ቅፅሬ ነው\nአየሁ ገዳዬን ወድቆልኝ ፍላፃ\nተፅናናሁ ድንግል በቃልኪዳንሽ\nይኸው ቆሜ አለሁ በምልጃሽ\n\nስምሽ በእግዚአብሔር ዘንድ የሰለጠ ነነው\nብርታት ሞገስ ሆነኝ ለኔ ለደካማ\nቆምኩኝ ሰገነት ላይ አንቺን ተደግፌ\nተስፈዬ ነሽ ድንግል የኑሮ ምራፌ\n\nየእግዚአብሔር ሀገር ሆይ እረቂቅ ከተማ\nቃልኪዳንሽ በምድር ከዳር ዳር ተሰማ\nያ የጥፋት ውሀ እልቂት የራቀብሽ\nየምህረት ቃልኪዳን ቀስተደመና ነሽ', 'am', 64, 0),\n(2, 'ማርያም', 'ማርያም\nማርያም እኖድሻለን\nስለወለድሽ የህይወት ምግብን\nማርያም እኖድሻለን\n\nድክመቴን አትይው ማርያም\nበሀጥያት መውደቄን ማርያም\nተስፋዬ አንቺ ነሽ ማርያም\nእስከ እለተ ሞቴ ማርያም\nላልከዳሽ ምያለው ማርያም\nከስርሽ ላልጠፋ ማርያም\nገፀ በረከቴ ማርያም\nየህይወቴ ዋስትና ማርያም\n\nየምእመናን ውበት ማርያም\nዘውድ አክሊላቸዉ ማርያም\nድንግል አንቺ እኮ ነሽ ማርያም\nየመንገድ ስቃቸው ማርያም\nምስክር ነኝ ላንቺ ማርያም\nእንደ ነብያቱ ማርያም\nስጦታ መሆንሽን ማርያም\nለአዳም ልጆች ሁሉ ማርያም\n\nሞገስ እና ፀጋ ማርያም\nበጌታ ፊት ያለሽ ማርያም\nከሰይጣን መሸሻ ማርያም\nዋስ ጠበቃችን ነሽ ማርያም\nእንዴት ነበር ያኔ ማርያም\nጌታን ስትወልጂው ማርያም\nየእረኞቹ ደስታ ማርያም\nየመላክት ዝማሬ ማርያም', 'am', 65, 0),\n(2, 'ልዩ ነው ክብርሽ', 'ልዩ ነው ክብርሽ\nወላዲተ አምላክ ማርያም ድንግል\nልዩ ነው ክብርሽ ከፍጥረት መሀል\n\nበቃሉአለማትን ሳይፈጥራቸው ገና\nታስበሽ የነበርሽ በእግዚአብሔር ህሊና\nከሀና ማህፀን ከእያቄብ አብራክ\nእናቱ እንድቶኚ የመረጠሽ አምላክ\n\nከመላእክት በክብር አንቺ ትበልጫለሽ\nከሰዎች ልጆችም የለም የሚመስልሽ\nበእግዚአብሔር ዘንድ ስምሽ የገነነ\nአልተገኘም ድንግል እንዳንቺ የከበረ\n\nነውር የሌለብሽ ንፅይት ሙሽራ\nየመመኪያችን ዘውድ ርህርይተ ህሊና\nእናት እና ድንግል ወላዲተ ቃል\nየማትለወጪ የሀይማኖት በትር', 'am', 66, 0),\n(2, 'አላፍርም እኔ በማርያም', 'አላፍርም እኔ በማርያም\nአላፍርም እኔ በማርያም\nስሟን ስጠራ እፅናናለሁ\nየሀዘኔ መርሻ ብያታለሁ\n\nስሟን ስጠራ በሀዘኔ ጊዜ\nአፅናንታኛለች ይዞ ትካዜ\nየመከራ ቀን የጭንቀቴ ደራሽ\nእንዳቺ የለም እመቤቴ ነሽ\n\nማርያም ማርያም በሉ ምዕመናን ሁሉ\nማርያም ማርያም በለን እንድናለን\n\nአደጋጣዮች ደርሰው በድንገት\nስም አጠራሬን ሁሉም ጠልቶት\nመታወቂያዬ አንቺ ነሽና\nስዕልሽን ሲያዩ ጠፉ እንደገና\n\nያሰብኩት ሁሉ ብጀምር ቀርቶ\nአጋጥጣለሁ ዘመኑ በዝቶ\nፍፃሜን እንዳይ ድንግል እርጂኝ\nደጅሽ ወድቄ ተማፅኛለሁ', 'am', 67, 0),\n(2, 'ማህደረ መለኮት', 'ማህደረ መለኮት\nማህደረ መለኮት የአምላክ እናት እመቤት\nስምሽን ጠርቶ ያፈረ ማነው\nየአምላክ እናት ስራሽ ግሩም ነው\n\nማህደረ መለኮት ደጅሽላይ ቆሜ ስለምን\nማህደረ መለኮት እመ ብርሀን ነይ ድንግል\nማህደረ መለኮት ስዘምርልሽ ደስ ይለኛል\nማህደረ መለኮት ከልጅሽ ፀጋ ይሰጠኛል\n\nማህደረ መለኮት አሸብሽቡላት ለድንግል\nማህደረ መለኮት ፍቅሯ ያላችው በእውነት\nማህደረ መለኮት ትመጣለች ልትባርከን\nማህደረ መለኮት ድንግል ሆይ ባርኪን ስንላት\nማህደረ መለኮት አፌም ይከፈት ለዝማሬ\nማህደረ መለኮት ለአምላክ እናት ለእመቤቴ\n\nማህደረ መለኮት ትምክት ናት ድንግል የሁሉም\nማህደረ መለኮት ፀአዳ እርግብ የሰላም\nማህደረ መለኮት ምን ብዬ ልጥራ ላመስግንሽ\nማህደረ መለኮት በምን ምሳሌ ልመስልሽ\nማህደረ መለኮት በፍጥረት ሁሉ ነሽ የከበርሽ\nማህደረ መለኮት በንፅህና የተሸለምሽ', 'am', 68, 0),\n(2, 'ሐረገ ወይን', 'ሐረገ ወይን\nሐረገወይን የወይንዘለላ\nእመቤቴ የፍጥረት አለኝታ\n\nዝማሬው ነሽ ድንግል ለአባ ጊዮርጊስ\nነይ ነይ እያለ የሚቀኝልሽ\nመሶበወርቅ ድንግል መናን የተሸከምሽ\nየሰማታት እናት አምሳያ የሌለሽ\n\nውስጤን ታቂዋለሽ ችግሬን ጭንቀቴን\nየልቤን መታወክ የውስጠ ሀዘኔን\nአረጋጊኝ ድንግል የሰላም እናት ነሽ\nደስታን የምትሞይ ችግርን አርቀሽ\n\nአዛኝነትሽን አይተናል በውሻ\nጫማሽን አውልቀሽ ውሀ ስታጠጪው\nእመቤቴ ማርያም ለኔም እዘኝልኝ\nበደለኛ ህይወቴ ከአምላኬ እንዳይለየኝ', 'am', 69, 0),\n(2, 'ማዕረጌ ነሽ', 'ማዕረጌ ነሽ\nማዕረጌ ነሽ ዘላለም\nየደስታ ቤቴ የሰላም\nበጎነት ሀብትሽ ትህትና\nምህረት ገንዘብሽ ነፅህና\n\nስምሽ ስንቄ ነው አልዝልም\nፍቅርሽ አስሮኛል አልወድቅም\nድምፅሽ ተሰምቶኝ በማህፀን\nበደስታ ዘልኩ በሀሴት\n\nለክብርሽ ቀንቶ ጎልበቴ ታጠፈ በፍቅር በአክብሮት\nበረሀ ቢሆን ህይወቴ ጥላዬ አለችኝ እናቴ\nንጓድ አይንካኝ ማለት ተከልያለው እቤቱ\n\nበበትሬ ላይ ታትመሽ በስምሽ ፀንቷል መንበሬ\nግርማና ሞገስ ሆንሽኝ በእልልታ ሞልቷል ከንፈሬ\nአንቺን እንደምን አላስብ እንደን አንቺን ልርሳ\nቀኜ ነሽ ብርቱ ጉልበቴ እጄ ለክብርሽ ይነሳ\n\nበታቦት ፍሬሽ አብርቶ ግርማሽ ከቦኛል በፀጋ\nመንገዱ ታየኝ በግላጭ ችቦዬ አንቺን ስጠጋ\nበእጅሽ ታስሬ ተሻገርኩ የሞትን ባህር ቀዝፊ\nፈሶ እንደ ጅረት ረሳሁት ከዚያ መከራ ተርፌ\n\nለሞት መስቀል መንጠልጠል ለህይወት ሆኗል ለክብር\nልቤ በትዕቢት ተገዝቶ ትህትና አውቆ ከአንቺ ቤት\nየፍቅርሽ መብረቅ አግኝቶኝ ለፈረሰው ሙት አካሌ\nየጥፋቱ ዳና አይግረፈኝ በክንድሽ አርፏል መጣሴ', 'am', 71, 0),\n(2, 'በሀዘኔ ደራሽ ነሽ', 'በሀዘኔ ደራሽ ነሽ\nበሀዘኔ ደራሽ ነሽ በጭንቀቴ\nበችግሬ ደራሽ ነሽ\nየአምላክ እናት የጌታዬ እናት\nድንግል እመቤቴ ወላዲተ ቃል\n\nመልካሚቷ ርግብ ድንግል እመቤቴ\nማርያም እናቴ ነሽ ድንግል እመቤቴ\nከፍጥረታት ሁሉ ድንግል እመቤቴ\nገናና ነው ክብርሽ ድንግል እመቤቴ\nየሐዘኔ መፅናኛ ድንግል እመቤቴ\nእንባዬን አባሽ ነሽ ድንግል እመቤቴ\n\nዋሻ መጠለያ ድንግል እመቤቴ\nየዘላለም ቤቴ ድንግል እመቤቴ\nመንገድ ስሄድ ስንቄ ድንግል እመቤቴ\nመጠጤ ነሽ ምግቤ ድንግል እመቤቴ\nእመአምላክ ስጠራሽ ድንግል እመቤቴ\nይጠፋል እረሃቤ ድንግል እመቤቴ\n\nየእናትነትሽን ድንግል እመቤቴ\nፍቅርሽን አየሁት ድንግል እመቤቴ\nጎጆዬን ስትሞይው ድንግል እመቤቴ\nቦዶ የሆነውን ድንግል እመቤቴ\nአንቺ ያለሽልኝ ድንግል እመቤቴ\nምን እሆናለሁኝ ድንግል እመቤቴ', 'am', 72, 0),\n(2, 'እመ አምላክ ልበልሽ', 'እመ አምላክ ልበልሽ\nእመ አምላክ ልበልሽ ስምሽን ልጥራ\nከእቅፍሽ ተለየሁ በሰራሁት ስራ\nእንዴትስ ላርቀው በምንስ አቅሜ\nደግፊኝ እንዳልወድቅ ከብዷልና ሸክሜ\n\nአላፊው በሆነው በሞት አለም ወጥመድ ተጠምጄ\nእርቃኔን ቀረሁኝ የልጅነት ክብሬን አዋርጄ\nየበቀለብኝን ክፋ አረም ነቅለሽ ከልቤ ላይ\nየርህራሄሽን ጠል እንዲያርሰኝ ይዝነምልኝ ከላይ\n\nእረፍት የሚያሳጣኝ ታላቅ በደል በውስጤ ስላለ\nነፍሴ ተጨነቀች ግራ ገባኝ ሰውነቴ ዛለ\nየቁም በድን ሆኜ እስከመቼ እኔስ እኖራለሁ\nመአዛሽ ያድሰኝ እፎይ ልበል ስቃዬን አርቂው\n\nታውቂዋለሽና የኔን ምግባር እንደሌለኝ\nቂም በቀል በማያውቅ የዋህ ልብሽ ፍፁም እራሪልኝ\nታሳርጊልኝ ዘንድ ልመናዬን ወደ አንቺ እጮሀለሁ\nፈፅሞ እንዳልጠፋ በሄድኩበት ምልጃሽን እሻለሁ\n\nቢጠራኝ አብዝቴ ቸሩ ልጅሽ ሸሸሁኝ ከቤቱ\nእንዲሁ ስባዝን ስቀዘበዝ ደከምኩኝ በከንቱ\nመልካም ባይኖረኝ ባቀረቅር ማንነቴ ጎጽፎ\nያከበረኝ ፀሎትሽን ክፉ ግብሬን እንደ ቤዛ አርግዕ', 'am', 73, 0),\n(2, 'በችግር ጊዜ', 'በችግር ጊዜ\nበችግር ጊዜ የምትደርስልን\nስንማፀናት የምትራራልን\nአኛም ደስ ይበለን በእመቤታችን\nእግዚአብሔር ይመስገን የእርሷ ያረገን\n\nሰማያዊ መና ጌታን የተሸከምሽ\nንፁህ የወርቅ መሶብ ድንግል አንቺ እኮነሽ\nስዕልሽ ፊት ቆሜ በአይኔ ሳስተውልሽ\nእንባዬ ፈሰሰ ከልቤ ውስጥ ገብተሽ\n\nበሰርግ ብቻ አይደለም ከልጅሽ የነበርሽ\nበዚያ በመከራ መስቀሉ ሥር ነበርሽ\nከንቺን ከመስቀሉ ማን ይነጣጥላል\nአምላክ ከአንቺ ጋር ነው ማን ይቃወመናል\n\nፀሐይን እንደ ልብስ የተጎናፀፍሽው\nአስራ ሁለት ኮከብ አክሊል የደፋሽው\nየሰማይ ጨረቃን በእግርሽ መርገጥሽን\nእኛም እናምናለን ድንግል ሆይ ክብርሽን\n\nምስጋና ለልጅሽ ሞገስም ላንቺ ነው\nአማላጅነትሽን መፅሐፍ የነገረው\nተአምርሽ ሲነበብ መልክሽ ሲታደል\nትባርኪናለሽ በኪዳን መሀል\n\nሚካኤል በቀኝ ገብርኤል በግራ\nእልፍ አእላፍ መላእክት ሆነው ካንቺ ጋራ\nእያሸበሸብ ይዘምሩልሻል\nእፁብ እፁብ ብለው ድንግል ያከብሩሻል', 'am', 74, 0),\n(2, 'እንድናለን እኛስ እንድናለን', 'እንድናለን እኛስ እንድናለን\nእንድናለን እኛስ እንድናለን\nእንድናለን ድንግል አንቺን ይዘን\n\nበፍፁም ቸርነት እንድናለን\nሰለወደደን እንድናለን\nእንዳንጠፉበት እንድናለን\nድንግልን ሰጠን እንድናለን\n\nየልባችን ደስታ እንድናለን\nአኛስ አግኝተናል እንድናለን\nበአማልጅነቷ እንድናለን\nፈጣሪ ምሮናል እንድናለን\n\nምርኩዝ አንቺን ይዘን እንድናለን\nስንቃችን ሰንቀን እንድናለን\nበድንግል መሪነት እንድናለን\nፃድቅን እንወርሳለን እንድናለን\n\nየምታማልደን እንድናለን\nድንግልን ሰቶናል እንድናለን\nየእሳቱን ባህር እንድናለን\nበእርሷ ተሻግረናል እንድናለን', 'am', 75, 0),\n(2, 'ነይ ነይ ማርያም ነይ ነይ', 'ነይ ነይ ማርያም ነይ ነይ\nነይ ነይ ማርያም ነይ ነይ\nድንግል ሆይ ነይ ነይ\nያንን የእሳት ባህር ከቶ እንዳላይ\n\nበሀመረ ኖህ የተመረጥሽ\nበአሮን በትር የተመሰልሽ\nየምስራቋ በር ቶሎ ድረሺ\n\nበተራራማው በኤፍሬም ሀገር\nእንግዳ የሆንሽ ለቤተ ዶኪማስ\nነይልኝ ወደ እኔ ካንቺ ጋራ ልኑር\n\nዓለም ከብዶብሽ ተጨንቂያለሁ\nሐዘን በዝቶብኝ ብቸኛ ሆኛለው\nኸረ ነይ ድንግል ወይ አጠራሻለው\n\nጥበብ አንቺ ነሽ ለሲሎንዲስ\nነይ ብሎ የሚጠራሽ ሶላማጢስ\nአትጥፌ ድንግል ሆይ በእጅሽ ልዳሰስ\n\nሚስጢር የገለጥሽ ለአባ ሕርያቆስ\nፈጥነሽ ያማለድሽኝ በቤተ ዶኪማስ\nነይልኝ እናቴ ነይልኘ እናቴ ልቤ ይፈወስ\n\nድንግል ቀርባለች ጨኸቴን ሰምታ\nየኃጢያቴ ገመድ እስሩ ተፈታ\nአባብራታለው ልጄን በእልታ', 'am', 76, 0),\n(2, 'ሀገረ እግዚአብሔር', 'ሀገረ እግዚአብሔር\nነኪር ንገሩ በእንቲ አኪ\nሀገረ እግዚአብሔር ማርያም\nየቀረቧትህ አትርቅም ድንግል እመ ብርሀን\n\nልጀምር ምስጋና ለድንግል ውዳሴ\nበዕርሷ ቃል ኪዳን ነው የቆመችው ነፍሴ\nሀገረ እግዚአብሔር የፃድቃን ከተማ\nነፍሴ ተመሰጠች ውዳሴሽ ሲሰማ\n\nንፁህ መሶበ ወርቅ እንከን የሌለብሽ\nማህደረ መለኮት እመቤታችን ናት\nሙሴ ከሩቅ ያያት ሐመልማለ ሲና\nኑ እንዘምርላት ተስፋችን ናትና\n\nፈጥና የምትደርስ በመከራ ጊዜ\nአድናን ረዳችኝ ከሃዘን ከትካዜ\nየዋሂት እርግብ የሰላም ምልክት\nየሁላችን ተስፋ ኪዳነ ምህረት\n\nየሮማን ፅጌ ነሽ መአዛሽ ያማረ\nሀገረ እግዚአብሔር መልክሽ የከበረ\nወደ አንቺ እያንጋጠጥን እንለምንሻለን\nሩህሩህ አዛኝ እናት ካላንቺ ማን አለኝ', 'am', 77, 0),\n(2, 'በጎ መአዛ', 'በጎ መአዛ\nበጎ መአዛ ሽቶዬ ነሽ\nበሰው ሁሉ ፊት ዘመርኩልሽ\nባንቺ ጣፈጠ አልጫነቴ\n\nምስላዬ የለሽ ነይ እመቤቴ\nዘመዴ ነሽ ነይ እመቤቴ\nያን ክፉ ዘመን ነይ እመቤቴ\nያለፍኩብሽ ነይ እመቤቴ\nበፍቅርሽ አሳት ነይ እመቤቴ\nልቤ ነደደ ነይ እመቤቴ\nእናትነትሽን ነይ እመቤቴ\nስለወደደ ነይ እመቤቴ\n\nየሰዎች ጉልበቱ ነይ እመቤቴ\nምን ይረባኛል ነይ እመቤቴ\nሰረገላዬ ነይ እመቤቴ\nመች ያድነኛል ነይ እመቤቴ\nከተሰወረ ነይ እመቤቴ\nክፉ መከራ ነይ እመቤቴ\nእፅናለሁኝ ነይ እመቤቴ\nአንቺን ሰጠራ ነይ እመቤቴ\n\nለስንፍናዬ ነይ እመቤቴ\nመቼ ልክ አለው ነይ እመቤቴ\nስለበደሌ ነይ እመቤቴ\nእተክዛለው ነይ እመቤቴ\nላነጋገሬ ነይ እመቤቴ\nማጣፈጫ ነሽ ነይ እመቤቴ\nተሰምቻለው ነይ እመቤቴ\nድንግል ሆይ ስልሽ ነይ እመቤቴ\n\nለመንገዴ ስንቅ ነይ እመቤቴ\nየረሃቤ መርሻ ነይ እመቤቴ\nለታመመ ሰው ነይ እመቤቴ\nነሽ መፈወሻ ነይ እመቤቴ\nየተማፀነሽ ነይ እመቤቴ\nበስምሽ አምኖ ነይ እመቤቴ\nማን አፍሮ ያውቃል ነይ እመቤቴ\nፊትሽ ለምኖ ነይ እመቤቴ', 'am', 78, 0),\n(2, 'እስኪ ላመስግንሽ', 'እስኪ ላመስግንሽ\nእስኪ ላመስግን ከቶ ሳላቋርጥ\nይላቃል ከንፈሬ ክብርሽ እንዲገለጥ\nእናቴ ሆይ ስልሽ አዝነሽ አነሳሽኝ\nምን ልበል ስላንቺ ቃላት እያጠረኝ\n\nቤተ መንግስት ነሽ የመሲህ እናት\nእለምንሻለው በቀን በሌሊት\nየሚስጢር መኖሪያ ሰፊ መጋረጃ\nአርፌ ኖሪያለው ድንግል ባንቺ ምልጃ\n\nመናዬ እልሻለው የአምላክ ስጦታ\nሳልበላ ሳልጠማ ሞላሺኝ እርካታ\nየምስራቋ ፀሀይ በራ ጨለማዬ\nሞገዱን አለፍኩት ባንቺ ተጠልዬ\n\nሰው ወገኑን ጠልቶ በር በዘጋበት\nየህይወቴ መንገድ ሆነብኝ አቀበት\nበአንቺ አማላጅነት ሁሉ ተከናውኖ\nስንቱን አልፌዋለሁ እንዳልሆነ ሆኖ\n\nቢልሆር ቢሰለፍ ሊያጠፋኝ በቁጣ\nየሚያስደነግደኝ\nጥላሽ በእኔ አልፎል ክፋውን አልፋያለው\nድንግል ሆይ ከፊትሽ እጅ ነሳሻለው\n\nመጠጊያ ኮረብታ ድንግል እናቴ ነሽ\nከታች ተነስቼ ከፍ ከፍ ያልኩብሽ\nምህላዬ ይሰማ ስላንቺ ልጅሽ\nሰላሙን አልብሶ ያቆመኝ ደጅሽ', 'am', 79, 0),\n(2, 'የጭንቅ ቀን ደራሼ', 'የጭንቅ ቀን ደራሼ\nእመቤቴ መድኃኒቴ ለክፋ ቀኔ\nውለታሽን አረሳውም እውነት በእውነት እኔ\nየጭንቅ ቀን ደራሼ የችግሬ\nእመ አምላክ አደራ የጭንቅ ቀን ደራሼ\n\nነግሰሻል በልቤ ሁሌ አዜምልሻለሁ\nስምሽን ሳነሳ ጭንቄን እረሳለሁ\nፍቅርሽን በልቼ ሸክሜ ቀለለ\nያንደበቴ ጠረን ማርያም ማርያም አለ\n\nእህቴ ሙሽራዬ ነይ ከሊባኖስ\nረሀቤ እንዲታገስ እንድትሆኚኝ ፈውስ\nምግብና መጠጤ የምረካብሽ\nተስፋዬ ሙሉ ነው በእናትነትሽ\n\nክብሬ ነሽ አክሊሌ የጭንቅ ቀን ዋሴ\nተጽፈሽ ቀርተሻል ከመሀል ምላሴ\nውለታሽ አለብኝ ምን ልበል ስላንቺ\nየልጅነት ክብር አይቻለው ባንቺ', 'am', 80, 0),\n(2, 'አልቻልኩም እመ አምላክ', 'አልቻልኩም እመ አምላክ\nአልቻልኩም እመ አምላክ ሥቃዬ በረታ\nየመከራዬ ሌሊት እንደ ምን ሊረታ\nሣለቅስ አነጋለሁ ሣነባ እውላለሁ\nየሚያጽናናኝ የለም ብቸኛ ሁኛለሁ\n\nበማይራራው ሕመም ሠላም በሌለው\nመጽናናት አጥቼ ዕንባን አፈሳለሁ\nየመከራዬን ሌሊት እየረገምኳቸው\nብርሃን አይኑሩበት ጨልሙ አልኳቸው\nቀንበሬን አንሽልኝ ይቅለልልኝ ሸክሜ\nበምልጃሽ ልፈወስ ልዳን ከሕመሜ\n\nደግፊኝ እናቴ እንዳልንገዳገድ\nበዕምነት እንድጓዘው የልጅሽን መንገድ\nገና ነው ጉዞዬ ብዙ ይቀረኛል\nከፊቴ ካልቀደምሽ እንዴት ያልቅልኛል\nየመንገዴ ፋና የሩቅ ዓላማዬ\nከእኔ ጋር ከሌለሽ ከንቱ ነው ጉዞዬ\n\nበፊትሽ ዘለዓለም ሐሴትን እንዳደርግ\nከእቅፍሽ ሳልወጣ በቤትሽ ልደግ\nሚዛን እንዳይደፋ ጥላሽ ይከልለኝ\nነፍሴን ከሚከቧት ጠላቶች ያድነኝ\nሣይነዋወጡ እግሮቼ እንዲጸኑ\nበምልጃሽ ይብራልኝ እንዳይጨልም ቀኑ', 'am', 81, 0),\n(2, 'ምስለ ሚካኤል ወገብርኤል', 'ምስለ ሚካኤል ወገብርኤል\nምስለ ሚካኤል ወገብርኤል\nንዒ ሠናይትየ ማርያም\nንዒ እመአምላክ ንዒ ማርያም\n\nካህናቶቹ በማህሌቱ\nንዒ ይሉሻል በሰዓታቱ\nወለተ ኢያቄም ወሀና\nሠላም እናግኝ ነይና\n\nየሊባኖሷ ሙሽራ\nፀሀይ ፈንጣቂ የሚያበራ\nኅብስትን ጋግረሽ ያበላሽ\nያማረውን ሰው ያለበስሽ\n\nየአባ ጊዮርጊስ ምወድሱ\nእሙ ለጌታ ለንጉሱ\nንግስት ወልዕልት የእልፍኙ\nአየንሽ ቆመሽ በቀኙ\n\nበቤተመቅደስ በግርማ\nማደግሽ ዝናው ተሰማ\nግብርሽ ገንዘብሽ ትህትና\nለአንቺ ይገባል ምስጋና', 'am', 82, 0),\n(2, 'ሰላምታ ይገባሻል', 'ሰላምታ ይገባሻል\nእመቤታችን ላንቺ ሰላምታ ይገባሻል\nከሴቶች ሁሉ ተመርጠሻል\n\nሀር እና ወርቁን እያስማማች ስትፈትል\nተዘጋጀላት የመመረጥ ሀይል\n\nእያረጋጋት የሰማይ መላዕክት\nቤተ መቅደስ ኖረች 12 አመት\n\nመንፈስ ቅዱስ እንደመረጣት አውቆ\nሰገደላት ዘካርያስ ታጥቆ', 'am', 83, 0),\n(2, 'ድንግል ሆይ', 'ድንግል ሆይ\nድንግል ሆይ ስላንቺ ነው እና መሐሪ\nአማልጂን ከአንድ ልጅሽ ከፈጣሪ\n\nስሙን እንዳልጠራ አንደበትም የለኝ\nፊቱንም እንዳላይ ስራዬ አስቸገረኝ\nታውቆኛል ጥፋቴ ብዙ እንደበደልኩኝ\nትዕዛዙን እንደሻርኩ ህጉን እንደጣስኩኝ\n\nበፊቱ እንዳላፍር የተጠራሁ ለታ\nእለምነዋለው ካሁኑ ይቅርታ\n\nአንተ ክብር መልአክ ልደቱን አብሳሪ\nአማልደኝ ከጌታዬ ከፈጣሪ\nጻድቃን ሰማዕት እናንተ ሁላችሁ\nአማልዱኝ ካምላኬ ካምላካሁ', 'am', 84, 0),\n(2, 'የሕይወት መሠላል', 'የሕይወት መሠላል\nየሲና ሐመልማል የሙሴ ጽላት\nየሲሎንዲስ ጥበብ እጸ መድኃኒት\nአሁን በምን በምን እንመስልሻለን\nእጹብ ድንቅ እያልን እናወድስሻለን\nያረጁ ፍጥረታት የታደሱብሽ\nየህይወት መሠላል ማርያም አንቺ ነሽ\nየነብያት ትንቢት የልባችን ተስፋ\nበአንቺ መመክያነት ማህበራችን ይስፋ\nተዋህዶ ይስፋ', 'am', 85, 0),\n(2, 'ዕዳ አለብን', 'ዕዳ አለብን\nየእመቤታችን አማላጅነቶን\nክብሯን የቀነስን የአወረድን\nዕዳ አለብን ከፈጣሪያችን\n\nየተሰጠ ሙሉ ስልጣን\nክብር ያገኘች በቃልኪዳን\nስሟን የጠራ እንደሚድን\nመጽሀፍ ሲነገረን\n\nቤዛዊት ኩሉ የተባለች\nበነ ቅዱስ ኤፍሬም የተመሰገነች\nበነ አባ ጊዮርጊስ ውዳሴን ያገኘች\nበመናፍቃን ዘንድ ምነው ተዘነጋች\n\nከሴቶች ሁሉ ልዮ ነሽ እያልን\nበሁለቱም ወገን በፍጹም ድንግል\nየብርሀን እናቱ ማርያም ስትባል\nበድካማዎች ወንድ እንዴት ትቃለል\n\nቃና ዘገሊላ ከልጅዎ ጋር ሳለች\nእሠርግ ቤት ገብታ ድንግል አማልዳለች\nእንኳንስ እመአምላክ ቤዛዊተ ኩሉ\nጻድቃን ሰማዕታት በእውቀት ያማልዳሉ', 'am', 86, 0),\n(2, 'ወላዲተ ቃል', 'ወላዲተ ቃል\nአሟሟትሽ በጥር ነሐሴ መቃብር\nያንቺ ለብቻ ነው ትንሳዬሽ ሲነገር\nስጋሽ በምድር ላይ የት አለ እንደፍጡር\nአርጓል ወደ ሰማይ ከክርስቶስ መንበር\n\nሥጋሽም ሲያሳርጉ መላዕክት በሰማይ\nቶማስ በደመና ሲመጣ መንገድ ላይ\nመግነዝ ተረከበ ለሐዎርያት ሲሳይ\n\nትንሣዬሽን ሽተው ግራ ሲገባቸው\nሐዎርያት ጾመው ተገለጥሽላቸው\nተቀብራ አልቀረችም በምድር ከደጅዎ\nወደላይ አረገች እሷም እንደልጅዋ\n\nለማየት ሲጓጉ የድንግል ትንሳኤ\nእርገቷን አወቁ በብዙ ሱባዔ\nእኛም እንጸልይ ደጃችንን እንዝጋ\nከወላዲተ አምላክ እንድናገኝ ዋጋ', 'am', 87, 0),\n(2, 'ስማጸን በስምሽ', 'ስማጸን በስምሽ\nድንግል ማርያም ብዬ ስማጸን በስምሽ\nበቅድመ እግዚአብሔር ልመናዬን ስማኝ\n\nእኔ ደካማ ነኝ ሀጥያቴ የበዛ\nእኔ ጎስቃላ ነኝ በደሌ የበዛ\nጊዜዬን ያባከንኩ በከንቱ በዋዛ\nጊዜዬን ያሳለፍኩ በከንቱ በዋዛ\n\nእመብርሀን ስልሽ ፈጥነሽ ድረሽልኝ\nልመናዬን ሰምተሽ ቆመሽ ለምኝልኝ\nኃጢአቴ ቢበዛም ይዣለው አንቺን\nአስምረሻልና በላዔ ሰብን\n\nአንገቴን ቢያስደፋኝ በዝቶብኝ ኃጢአቴ\nምልጃሽን ፈለኩኝ ድንግል ሆይ እናቴ\nያን ክፋ ጨለማ እንዳላይ አደራ\nድንግል ሆይ ከልይኝ ከዳቢሎስ ጭፍራ\n\nእመብርሀን እያልኩ ቆሜ ከደጅሽ\nበብርሃን እጆችሽ እንባዬን አበሽ\nዓለም አታላይ ነች ወደሷ ተሳብኩኝ\nታማልጂኝ ብዬ አንቺኑ ተራብኩኝ', 'am', 88, 0),\n(2, 'የእርቅ ሰነድ ነሽ', 'የእርቅ ሰነድ ነሽ\nየእርቅ ሰነድ ነሽ በሰማይ የታየሽ\nቀስተ ደመናዎ ድንግል ሆይ አንቺ ነሽ\nከኖኃ ውኃ ጥፋት ከቁጣው ብኃላ\nአምላክ ስላደረገ ቃልኪዳን መሃላ\n\nየሰው ልጅ ጥፋት በምድር ሲበዛ\nትዕዛዙን ሲቃወም ሲሽሩ እንደዋዛ\nየቁጣው ሕፃናት ኔፍሊም ሲወለዱ\nመጠለያ መርከብ አንቺ ሆነሽ ዘመዱ\n\nከብዙዎች መሃል ኖህ ብቻ ተገኘ\nበደል የሚጠላ ጽድቅን የተመኘ\nየእግዚአብሔር ልጆች በአህዛብ ሲቀኑ\nበሃይማኖት ጸንተው አንቺን ያሉ ዱኑ\n\nጥንድ ጥንድ አንበሳ ተባዕት አንስት\nበአንቺ ተጠለሉ መአቱን በመፍራት\nኖህና ልጆቹን የልጆቹን ሚስቶች\nመርከቧን ከልላ ከመአት አዳነች\n\nእኛም ከመአቱ የምንጠለለው\nድንግል ሆይ ስምሽን መርከብ አድርገን ነው\nበእውነት ያለ ሀሰት ስምሽን ስጠራ\nይታያል እግዚአብሔር ልቦናው ሲራራ\n\nከሰማይ መአቱ በወረደ ጊዜ\nአንቺ ነሽ ማደርያው የፍጥረት ትካዜ\nአርባ ቀን ከለሊት ለዘነበው ዝናብ\nየሰው ልጅ ተረፈ ሆነሽለት መርከብ\n\nህይወት ለአብነት የቀረው ለአብነት\nነውና እመቤቴ በአንቺ መርከብነት\nየኖህ ቃልኪዳኑ መሸሸግያ አንቺ ነሽ\nምስጋና ይድረሰው ለአማኑኤል ልጅሽ', 'am', 89, 0),\n(2, 'አምስቱን ሀዘናት', 'አምስቱን ሀዘናት\nአምስቱን ሀዘናት ሳስብ የእናቴን\nእኔም አለቅሳለው መላ ዘመኔን\n\nጌታን በመውለዶ ድንግል ደስ ሲላት\nበነብስሽ ሰይፍ ያልፋል ቢል አሳዘናት\nድንግል የዚያን ጊዜ አምርራ አለቀሰች\nየልጆን መከራ ዘዉትር እያሰበች\n\nቤተ መቅደስ ሄደው ጠዎት ለጸሎት\nጌታን ባጡት ጊዜ ብዙ ፈለጉት\nአምርራ ስታለቅስ እጅጉን ተጨንቃ\nበሶስት ቀን ተገኘ ሲጠየቅ ሲሰማ\n\nእጅ እግሩን አሳስረው በጲላጦስ ፊት\nአጥንቱ እስኪታይ ብዙ ፈለጉት\nየልጆን መከራ ቆማ እዛ ስታይ\nወየው ልጄ አለች በዛበት ስቃይ\n\nበወንበዴዎች መኃል እራቁትን አርገው\nሰቀሉት አርብ ለተ እሮብ ለት ወስነው\nየዝናብን ጌታ ውሀ ከለከሉት\nሆምጣጤ አመጡና እንካ ጠጣ አሉት\n\nበሞቱ ሞት ሽሮ እኛን ሊያድነን\nወደ አዲስ መቃብር ወረደ በክብር\nበሰላመ ገብርኤል አባት ሆይ አያለ\nአምስቱን ሀዘናት አስቦ የፀለየ\nየሰራውም ሀጢአት ይሰረያል አለ', 'am', 91, 0),\n(2, 'አዘነች ድንግል አለቀሰች', 'አዘነች ድንግል አለቀሰች\nአዘነች ድንግል አለቀሰች ፍጹም አምርራ\nበአንድ ልጇ ምክንያት ደርሶባት መከራ\n\nበመንጻቱ ወር በዓርባኛው ቀን\nሥምዖን አረጋዊ ታቀፈ እና ጌታን\nትንቢት ተናገረ ተገልጾለት ሞቱ\nበነፍስሽ ሠይፍ ያልፋል አንቺም እናቲቱ\nይኽንን መከራ ሲሠማ ጆሮዋ\nአምርራ አለቀሰች አልቆም አለ ዕንባዋ\n\nበአሥራ ሁለት ዓመቱ ለማክበር በዓል\nበኢየሩሳሌም ቢገኝ አማኑኤል\nሲጠይቅ ሲሠማ በቤተ መቅደሱ\nየኦሪት ካኅናት ሲደነቁ በእርሱ\nእስከ ሦስት ቀን ድረስ ብትልጣው ፈልጋ\nልቧ ተሠበረ በሐዘን አለንጋ\n\nጠዋት በማለዳ በጲላጦስ ደጅ\nሲጸናበት አይታ የጨካኞች እጅ\nርቃኑን አድርገው ያለ አንዳች ጥፋት\nከግንድ ጋር አስረው ጀርባውን ሲገርፉት\nእንዴትስ አታለቅስ እንዴት አታነባ\nሲገርፉት ሲያዳፉት ልጇን እንደ ሌባ\n\nየዓለሙን ፈጣሪ የዓለሙን ዳኛ\nንጹሑን ጌታ መሥሏቸው ቀማኛ\nእጁን እና እግሮቹን በችንካር ወጥረው\nበወንበዴ መሐል ሠቅለውን ብታየው\nድንግል አለቀሰች አልቻለች መጽናናት\nዕንባዋ ወረደ እንደ ክረምት ጅረት\n\nዮሴፍ ኒቆዲሞስ በአንድ ሲማከሩ\nቅዱሥ ሐያል ብለድ ገንዘው ሊቀብሩ\nበአዲስ መቃብር በአሥራ አንደኛው ሠዓት\nሥጋውን አኑረው በድንጋይ ቢዘጉት\nእያለች ዐነባች አንድ ልጄ እኮ ነው\nከእርሱ የሚቀድም ተከታይ የሌለው', 'am', 93, 0),\n(2, 'ገበናዬን ሸፍኝልኝ', 'ገበናዬን ሸፍኝልኝ\nገበናዬን አደራ ሸፍኝልኝ ማርያም\nበጭንቅ ቀን በመከራ ጊዜ\nእንዳትረሽኝ በትካዜ\n\nጭንቀቴን ስነግርሽ አንቺን ቀርቤ\nመፍትሄ አግኝቷል ያዘነው ልቤ\nተስፋ አሳጥቶ ያደከመኝን\nተቆርጦ አየሁት ያሰቃየኝን\nእንደ ደመና ተገፎ ከአየሁ\nለክብርሽ ሙላት እዘምራለሁ\n\nጠላት ሊያጠፋኝ ቢነሳብኝ\nማዕበል አንስቶት ቢረብሸኝ\nየሰላሜን ሰው እጠራሻለሁ\nከኔ ጋር ከሆንሽ እረጋጋለው\n\nባልንጀሮቼ መክረው ሲርቁኝ\nተስፋ የለውም ብለው ሲተውኝ\nአንቺ አልተውሽኝም ልዮነሽና\nገመናን መክደን ታውቂያለሽና\nምህረትሽ ከቦ ለዚህ ከበቃሁ\nበምስጋና ቃል ድምጼን አጸናሁ\n\nማርያም በስምሽ ጭንቁን ቀን ልለፍ\nእንዳልወስድ በመከራ ጎርፍ\nከኃጢአት አለም ጣዕም ከሌለው\nነፃ አውጪኝና ነውሬን ሸፍኚው\n\nለእኔ አይገባም ያደረግሽልኝ\nብዙ ምስጢሬኝ የሸፈንሽልኝ\nየውስጥ ገመና ጉዴን ታውቂያለሽ\nአልተጋለጥኩም ትከድኚዋለሽ\nጎስቋላ ኑሮ ተዋበ አጌጠ\nመራራው ህይወት ባንቺ ጣፈጠ\n\nመስሎኝ ነበር የማያልፍ\nአየሁት ጭንቀቴ ሲገፈፍ\nለዳዊት ፅዮን ለሕዝቅኤል በር\nልወድቅ ልነሳ ለማርያም ክብር', 'am', 95, 0),\n(2, 'በምድር ላይ ለኔ ማንም የለኝ', 'በምድር ላይ ለኔ ማንም የለኝ\nበምድር ላይ ለኔ ማንም የለኝ\nሀዘን ጭንቀቴን የሚካፈለኝ\nኪዳነምህረት እመቤት\nተስፋ ሁኚልኝ መድኃኒት\n\nቁስለኛ ብሆን ህመምተኛ\nዓለም ብትለኝ በሽተኛ\nመጣሁ ከደጅዋ ሸክሜን ይዤ\nደጓ እመቤቴን ተመርኩዤ\n\nቀን ለጣለው ሰው ትደርሻለሽ\nእንባን ከዓይኖቹ ታብሻለሽ\nበይ ስሚኝና ልመለስ\nለልቤ ጩኸት ስጭኝ መልስ\n\nወርቅ ሽቶዬ ነጭ ልብሴ\nእንዳያድነኝ አውቄአለሁ\nበስደት ሀገር መኖሪያዬ\nአንቺ ብቻ ነሽ መፅናኛዬ\n\nጊዜ ጥሎታል የሰውን ክብር\nበሥጋ መሃል ጠፍቶ ፍቅር\nጣዕምሽ የኖራል ተጠብቆ\nመች ታልፊዋለሽ ሰውን ወድቆ', 'am', 99, 0),\n(2, 'የአማኑኤል እናት', 'የአማኑኤል እናት\nየጌታዬ እናት እመቤቴ\nየአማኑኤል እናት ረዳቴ\nህይወቴን ጠብቂያት ድንግል እመቤቴ\n\nየቀደሙት ሁሉ የዳኑብሽ\nየጥፋት መዳኛ መርከቤ ነሽ\nእኔም እንደአባቶች እጣራለሁ\nሰዓሊ ለነ ቅድስት እልሻለሁ\n\nየሲና ቁጥቋጦ መገለጫ\nየአምላክ ዙፋኑ መቀመጫ\nጌታን ያየሁብሽ መስታወቴ\nሳነሳሽ እኖራለሁ በህይወቴ\n\nሰላም ባጣች ዓለም ለመኖር\nመጠጊያ የሆነኝ የአንቺ ክብር\nአንቺን በወድደዴ ጠላት አፍሮ\nልቦናው ይመለስ ተመክሮ\n\nሀዘኔ በዝቶብኝ አለቅሳለሁ\nከፊትሽ ወድቄ አነባለሁ\nልመናዬን ስሚኝ እመቤቴ\nበደስታ ልመለስ ወደቤቴ', 'am', 100, 0),\n(2, 'ከእኔ ጋር ሁኚ', 'ከእኔ ጋር ሁኚ\nከእኔ ጋር ሁኚ እመቤቴ\nሰላም እንድሆን በህይወቴ\n\nእውነተኛ ነውየመረጠሽ\nበንጽህና የጠበቀሽ\nቶ ሰላም ከእርሱ አለ የሚመነጭ\nአንቺ እርጂኝና እኔም ልጐንጭ\n\nብሶተኛ ነኝ የሰለቸኝ\nየኑሮ ጣዕም የጠፋብኝ\nአንቺን ጠርቼ ልቁምና በዮ ዘለለ\nበህይወት ልኑር እንደገና\n\nአንቺን ጠርቼ አልወደድኩም\nከአንቺ ጋር ሆኜ አላዘንኩም\nዛሬም ወድቄ እጮሃለሁ\nአንሺኝ እናቴ እልሻለሁ\n\nየሀዘን እንባ ዓይኔ ቋጥሮ\nበከንቱ ምኞት ተወጥሮ\nእንዳለጠፋብሽ ተማርሬ\nበአንቺ ልመለስ ተመክሬ', 'am', 101, 0),\n(2, 'አንቺን ይዤ', 'አንቺን ይዤ\nአንቺን ይዤ ምን እሆናለሁ\nስምሽን ጠረቼ መች አፍራለሁ\nአመቤቴ እጠራሻለሁ\nድንግል ማርያም ነይ እላለሁ\n\nከወደኩበት ባንቺ እነሳለው\nተስፋ ቢስ ሆኜ መች እቀራለሁ\nእመቤቴ ነይ እጠራሻለሁ\nድንግል ማርያም ነይ እጠራሻለሁ\n\nበልጅሽ ፈቃድ ባንቺ ልመና\nእፈወሳለሁ ድውይ ነኝና\nእመቤቴ ነይ እጠራሻለሁ\nእመብርሃን ነይ እጠራሻለሁ\n\nዛሬስ ረከስኩ ጥፋቴ በዝቶ\nአንቺን ካልቀረብኩ አልድንም ከቶ\nእመቤቴ ነይ እጠራሻለሁ\nድንግል ማርያም ነይ እጠራሻለሁ\n\nየምህረት ኪዳን አምላክ የሰጠሽ\nእመብርሃን መፅናኛዬ ነሽ\nእመቤቴ ነይ እጥራሻለሁ\nኪዳነምህረት ነይ እጠራሻለሁ', 'am', 102, 0),\n(2, 'መታመኛዬ ነሽ', 'መታመኛዬ ነሽ\nመታመኛዬ ነሽ የነፍሴ መንገዷ\nየአማኑኤል እናት ምስለ ፍቅር ወልዷ\nትምበረከካለች ህይወቴ ለክብርሽ\nለዘለዓለም ህይወት ሙሉ ተስፋዬነሽ\n\nጻድቃኔ ገዳም ደጅሽ በመድረሴ\nየምልጃሽ በረከት ደረሳት ለነፍሴ\nዘንዶው የነደፋት ቁስሏ ተፈወስ\nእስኪ ላመሥግንሽ የልቤ ደረሰ\n\nምግባር የጐደላት ከርታታ ህይወቴ\nበአንቺ ፀንታ ቆመች ድንግል እመቤቴ\nጓዳዬ ማጀቴ ጐጆዬ ሲታመስ\nሰላምን አገኘው ከገዳምሽ ስደርስ\n\nመመካት ባትችልም በሠራቸው ሥራ\nአትሰጋም ህይወቴ ፅዮን ናት ሀገሯ\nእንደመልከ ፄዴቅ አድሜዬን አርዝማ\nድንግል አፅናናችኝ ጐልጐታ ቆማ\n\nበጐልጐታ እንባሽ የታጠበች ነፍሴ\nለዝማሬ ቆመች በኤፍሬም ውዳሴ\nሲኦልን ሳልፈራ ስምሽን ተማጽኜ\nሙሉ ደስታ አገኘሁ አንቺን ተማምኜ', 'am', 103, 0),\n(2, 'እኔስ አልፈራም', 'እኔስ አልፈራም\nእኔስ አልፈራም ድንግልን ይዤ\nበህይወቴ ቢያልፍ ጭንቀት ትካዜ\nየምመካበት ስሟ አጽናኝ ነው\nእየወደድኳት እጠራታለሁ\n\nእናቴ ስላት ልጄ እያለችኝ\nበሀዘን በደስታዬ ቅርቤ የሆነችኝ\nየማይጠፋ ነው የማይቀበር\nየአደራ እናቴ ለእኔ ያላት ፍቅር\n\nቀስቱ ታጥፎልኝ ከእግሬ ሥር ወድቋል\nምልጃዋ ረድቶኝ ስሜ ታድሷል\nበጨለማ ዓለም የእኔ ብርሃኔ\nትረዳኛለች በዕድማ ዘመኔ\n\nየተረሳውን ታስታውሻለሽ\nስሟን ለጠሩ መደገፊያ ነሽ\nጩኸቴን ሰምታ አትጨክንም\nበዘንዶ አፍ ውስጥ አትተወኝም\n\nየመስቀሉ ስር ድንቅ ስጦታ\nየልቦና እረፍት በቀን በማታ\nድንግል ዋሴ ናት መሸሸጊያዬ\nጦር መመከቻ ጽኑ ጋሻዬ', 'am', 104, 0),\n(2, 'ሰዓሊለነ', 'ሰዓሊለነ\nበጸሎትሽ በምልጃሽ\nእናምናለን ልጆችሽ\nአስታርቂን አማልጅን ከፊቱ ቆመሽ\nሰዓሊለነ ማርያም ምህረተ ወልድኪ\nየሀሙጸነ እመ አርያም\n\nሚዛን እንዳይደሩ ቀላል ምግባራችን\nትርጉም አልባ ሆኗል ውስጥ እኛነታችን\nድንግል አስተምሪን ያንቺን ንጽህና\nልባችን ይመለስ በአንቺ እንባ ልመና\n\nተደበላልቆብን ንግግር ቋንቋችን\nባቢሎን ሆነናል ከፍቶ ታሪካችን\nእንደሐዋርያቱ አንድ ልብ ያድርገን\nከልጅሽ አሳስቢ ፍቅር እንዲሰጠን\n\nየአመነብሽ ጠርተው በስምሽ ድነዋል\nበፍርድ አደባባይ ምህረት አግኝተዋል\nለእኔም እናቴ ነሽ ሃብቴና ርስ\nጣሪያና ግድግዳ ለፈረሰው ቤቴ', 'am', 105, 0),\n(2, 'ታምረ ማርያም', 'ታምረ ማርያም\nታምረ ማርያምን እንስማ ቆመን\nወንዶች በማደግደግ ሴቶች ተሸፍነን\nሦስት ጊዜ እንስገድ ለአምላከ እናት ክብር\n\nድንግል ከመቀደስሽ ልጆችሽ ገብተን\nንዒ ንዒ ስንል ጭንቀት ጠፋልን\nህይወታችን ቢከብድም በክፋት በደል\nበአንቺ አማላጅነት ሸክማችን ቀሏል\n\nየቅዱስ ደቅስዮስ እመቤት ነይልን\nፀጋና በረከት ሰጪን ለሁላችን\nበአራቱ መዓዘን አለቆች አድርገሽ\nልጆችሽን ሁሉ መሾም ትችያለች\n\nነፍሳችንን ሹሚያት ሥጋችንን ትግዛ\nእንዳትኖር በከንቱ በዋዛ ፈዛዛ\nልመናና ክብርሽ ይደር በሁላችን\nታምርሽን ቆመን በእምነት ስለሰማን\n\nልመናዋ ክብሯ በዕውነት ያድርብናል\nበምድርም በሰማይ ፀጋን ያሰጠናል', 'am', 106, 0),\n(2, 'ዮም ፍሰሀ коነህ', 'ዮም ፍሰሀ коነህ\nዮም ፍሰሀ ኮነህ\nበእንተ ልደታ ለማርያም\nእንሆ ሆነህ ደስታ\nበእመቤታችን በማርያም ልደታ\n\nድንግል ተወለደች ፈሰሀ ኮነ\nእመቤታችን\nከዳዊት ዘር ወጣች\nተስፋ ስንቃችንን\nምድር ተደሰተች\nቀረባት ሰማዩ\nሊያመቃ ነዉና\nየአዳም ስቃዩ\n\nድንግል ስትወለድ ፍሰሀ ኮነህ\nሊባኖስ አበራ\nበደስታ ተሞላ\nታላቁ ተራራ\nየሀና የኢያቄም\nህልማቸው ተፈታ\nከድቅድቅ ጨለማ\nጨረቃዋ ወታ\n\nየተክታ ጨረቃ ፍሰሀ ኮነ\nፀሀየን ወለደች\nየጽድቅ ሀመልማላ\nዳዊት ቤት በቀለች\nዝናብ ያየንባት\nየጽድቅ ደመና\nድንግል ተወለደች\nከኢያቃም ከሀና', 'am', 107, 0),\n(2, 'አፍሬ አላውቅም', 'አፍሬ አላውቅም\nአፍሬ አላውቅም ላንቺ ነግሬ\nቤቴ ሙሉ ነው ፅኑ ነው ቅጥሬ\nኪዳነምህረት ዘውትር የምለው\nውለታሽ በዝቶ ፍቅርሽ ገዝቶኝ\n\nችግር ይሸሻል አንቺን ስጠራ\nመከራ ይቀላል ካንቺ ሳወራ\nንዒ ንዒ ስል ምትደርሺ ፈጥነሽ\nአለው የምትይኝ የልቤን አውቀሽ\nምስጢሬን በምስጢር የምነግርሽ\nኪዳነምህረት ሰሚዬ ነሽ\n\nከጎጆዬ ገብተሽ ጣፈጠ ህይወቴ\nሰላሜ በዛልኝ ፀና ጉልበቴ\nእንደ ወይን ጣፈጠ መናኛው አልፎ\nበህይወት መፅሃፍ ስሜ ትፅፎ\nምስጢሬን በምስጢር የምነግርሽ\nኪዳነምህረት ሰሚዬ ነሽ\n\nየኔ መታወቂያ ሰንደቅ አርማዬ\nየምማፀንብሽ ነሽ ከተማዬ\nመች ጠግቤ አውቃለው አንቺን አወድሼ\nእኔም በአብይ ቃል ልጥራሽ መላልሼ\nምስጢሬን በምስጢር የምነግርሽ\nኪዳነምህረት ሰሚዬ ነሽ\n\nበደስታ እሞላለው ብመጣም አዝኜ\nኪዳነምህረት አልኩ በስስት ሆኜ\nቁስሌን ፈውሰሻል መድሃኒትን ወልደሽ\nእናት ሆነሺኛል ለኔ ተሰጥተሽ\nምስጢሬን በምስጢር የምነግርሽ\nኪዳነምህረት ሰሚዬ ነሽ', 'am', 108, 0),\n(2, 'ይቤላ መልአክ ለማርያም', 'ይቤላ መልአክ ለማርያም\nይቤላ መልአክ ለማርያም\nትወልዲ ወልደ ንጉሥ በቤተልሔም\n\nከጌታ ተልኮ ቅዱስ ገብርኤል\nሰላምታ አቅርቦላት ለማርያም ድንግል\nትወልጃለሽ አላት ቀዳሚውን ቃል\n\nማኅደረ መለኮት ማርያም ውድስት\nየሕዝብ ሁሉ እናት እኅተ መላእክት\nእሙ ለብርሃን ደብተራ ፍጽምት\n\nወገበዋቲሃኒ ሐመልማለ ወርቅ\nትበርሂ እምፀሐይ ኆኅተ ምሥራቅ\nሰላም ለኪ ድንግል በአልባሰ ወርቅ\n\nወላዲተ አምላክ ማርያም ንጽሕት\nወትትሌአሊ እምአድባር ስብሕት ወቡርክት\nኦ ምልእተ ጸጋ እግዚአብሔር ምስሌኪ\nቡርክት አንቲ እምአንስት ድንግል በኅሊናኪ', 'am', 110, 0),\n(2, 'እቴ ሙሽራዬ', 'እቴ ሙሽራዬ\nእቴ ሙሽራዬ ሰለሞን ያለሽ\nእኔም ልበልሽ እናቴ\nእማምላክ ግቢ ከቤቴ\nማርያም ግቢ ከቤቴ\n\nሁሉም ሰው ለራሱ ወንበር ሲዘረጋ\nየክብርን ሽልማት ለራሱ ሲያስጠጋ\nድንግል እንደ ባሪያ ውሃ ተሸክመሽ\nጌታን በትህትና ታገለግያለሽ\nነይ በደመና\nእመቤታችን ርህርይተ ህሊና\n\nወርቀዘቦ ለብሰው በቤቱ ከሞሉት\nበሀር እና በእንቁ ከተንቆጠቆጡት\nበሠው ፊት ያማሩ ብዙ ሆነው ሳለ\nጌታ ግን ወደደሽ እናቴ ነሽ አለ\nነይ በደመና\nእመቤታችን ርህርይተ ህሊና\n\nአሳድጎሽ ሳለ መልአኩ መግቦ\nተሸልመሽ ሳለ በዝቶልሽ ተውቦ\nእጅግበትህትና ስላገለገልሽው\nእንደ ኪሩብ መላክ ጌታን ተቀበልሽው\nነይ በደመና\nእመቤታችን ርህርይተ ህሊና\n\nየባሪያውን ውርደት ተመልክቶልእና\nየወለድሽው ንጉስ ይድረሰው ምስጋና\nከልብ የወጣ እንጂ ከንቱ ሆኖ አይደለም\nንፅይት እንላለን እኛም ለዘላለም', 'am', 111, 0),\n(2, 'ሰላም ሰላም ለኪ', 'ሰላም ሰላም ለኪ\nሰላም ሰላም ለኪ ማርያም ሰላም ለኪ\n\nየሕይወት መሠረት ሰላም ለኪ\nየፍጥረት አለኝታ ሰላም ለኪ\nድንግል አደራሽን ሰላም ለኪ\nሁኝልን መከታ ሰላም ለኪ\n\nበላዔ ሰብእ ዳነ ሰላም ለኪ\nብዙ ነፍስ አጥፍቶ ሰላም ለኪ\nየአንቺን ስም ለጠራ ሰላም ለኪ\nጥርኝ ውኃ ሰጥቶ ሰላም ለኪ\n\nተማጽነንብሻል ሰላ ለኪ\nበአማላጅነትሽ ሰላም ለኪ\nድንግል ሆይ አደራ ሰላም ለኪ\nአማልጅን ከልጅሽ ሰላም ለኪ\n\nእኛም ብንከተል ሰላም ለኪ\nበጎ ምግባርን ሰላም ለኪ\nበሰላም በጤና ሰላም ለኪ\nእንኖራለን ሰላም ለኪ', 'am', 112, 0),\n(2, 'ለምኚ ለምኚ', 'ለምኚ ለምኚ\nለምኚ ድንግል ለምኚ\nለኃጥአን አኮ ለጻድቃን\n\nታላቅ ስጦታዬ\nአዛኝ ሩህሩህ ነሽ\nየጌታዬ እናት\nጸጋን የተሞላሽ\nየአምላክ ማደሪያ\nለምነሽ አስምሪኝ\nአማናዊት ጽዮን\nከእኔ አትለዪኝ\n\nሐዘንሽ ሐዘኔ\nለኔ ይሁን ድንግል\nየተንከራተትሽው\nበሃገረ እስራኤል\nትዕግስትሽን ሳየው\nልቤ ይመሰጣል\nየሐዘን እንባ ጎርፍ\nዓይኔን ይላዋል\n\nበቀራንዮ አንባ\nበዚያ የፍቅር ቦታ\nበእግረ መስቀሉ ስር\nከክርስቶስ ጌታ\nለእኛ ተሰጥተሸል\nእናት እንድትሆኚ\nልጆችሽ ነንና\nምልጃሽ አይለየን\n\nአንደበቴን ጌታ\nበምስጋና ሙላው\nደስ ይበልሽ ብዬ\nእኔም ላመስግናት', 'am', 113, 0),\n(2, 'ምስጢረኛዬ ነሽ', 'ምስጢረኛዬ ነሽ\nአውቀዋለሁ ደጅሽን የእረፍት ቦታዬን\nጽኑ ሰላም ጸጥታ ማግኛዬን\nየት እሄዳለው አልልም ሲከፋኝ\nኪዳነ ምህረት አንቺ እያለሽልኝ\n\nከአጸደ መቅደስሽ ከስዕልሽ ስር\nእረፍቴ በዚያ ነው በቅዱሱ ደብር\nከተራራው አናት ከደጅሽ መጥቼ\nሰምሮልኛል ስምሽን ጠርቼ\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ\n\nየሮማን አበባ መዓዛሽ ተወዳጅ\nበረከትን ልቅሰም ሳልለይ ካንቺ ደጅ\nአስራትሽ አድርጊኝ ጠቅልይኝ እናቴ\nታብብልኝ ትፍካልኝ ሕይወቴ\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ\n\nአጠገቤ ጎኔ በዙሪያዬ እንዳለሽ\nእንደርሱ ነው ልቤ እማ የሚያወራሽ\nአልቅሼ ሲቀለኝ ነግሬሽ የውስጤን\nአትዘገይም ስትሠሪልኝ ቤቴን\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ\n\nየእንጦጦዋ እናቴ እምዬ የምልሽ\nኪዳንኪ ደጓ የልብን ሰሚ ነሽ\nበሄድኩበት አለሽ ተከትለሽኛል\nስላለሽኝ ሰላም ይሰማኛል\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ', 'am', 114, 0),\n(2, 'የአፍ መፍቻ ቋንቋዬ', 'የአፍ መፍቻ ቋንቋዬ\nከአፌ አይጠፋም ስምሽ\nከልቤ አይጎድልም ፍቅርሽ\nየአፍ መፍቻ ቋንቋዬ ድንግልሆይ ከለላዬ\n\nመሪዬ ነሽ በመንገድ፣\nየማልፍብሽ ከወጥመድ፣\nወጥቻለሁ ካንች ጋራ፣\nእንዳልደክም እንዳልፈራ።\n\nአይቀርበኝም ያ ጠላቴ\nስለሆንሽኝ ምልክቴ\nአንችን ይዤ ተሻገርኩኝ\nማርያም ብዬ በድል ቆምኩኝ\n\nተሞልቼ በመንፈስ\nማርያም ብዬ ሳወድስ\nእዜማለሁ በምስጋና\nማን ሊያቆመው ያንችን ዝና\n\nበልቤ ላይ አለ ፍቅርሽ\nበአንደበቴም ላይ ጣዕምሽ\nአንችን መውሰድ እኔ አልፈራም\nእናቴ ነሽ ለዘላለም\n\nተቀበልኩሽ ስጦታየ\nይዤሽ ገባሁ ከጎጆዬ\nተጽናናሁኝ ከሃዘኔ\nአልለይም በዘመኔ', 'am', 118, 0),\n(2, 'ቅኔ ነሽ', 'ቅኔ ነሽ\nልጠራ ልሰየም ድንግል በስምሽ\nተሰጠኝ በመስቀል እናቴ አድርጎሽ\nግቢ ወደ ቤቴ ወደ ጎሰቆለው\nሃዘን በበዛበት ባይተዋር በሆነው\nግብሬ ክፉ ስራ መንገዴ የግፍ\nፅልመት ያጨለመኝ ከድካም አላርፍ\nአንቺ ስትሰጪኝ ከመስቀል ግርጌ\nእንዴት ላመስግንሽ እንዴትስ አድርጌ\nቅኔ ነሽ የማይቆም ዝማሬ\nያፈልቃል ማወደስ ከንፈሬ\nሞገስ ነሽ ለምስኪናን ሁሉ\nማርያም ምሊተ ኩሉ\n\nአቡጊዳዬ ነሽ ጽድቅ የተማርኩብሽ\nየፊደል ገበታ ጌታን ያወኩብሽ\nየህይወት መገኛ ቤተልሄም ለህብስቱ\nተቀዳ ከሆድሽ ህይወት ለፍጥረቱ\nርግብዬ ንኢ ሰናይትየ\nልቤ አያርፍ ልጅሽን ካላየ\nመገኛ የሰላሜ ረፍቱ\nላመነሽ ቅጥር ነሽ ርስቱ\n\nምዕልይተ ጸጋ የንጉስ ሙሽራ\nለተጠማ ውሻ ልብሽ የሚራራ\nሸልሞ ከሰጠኝ አንቺን ለእናትነት\nበሰሽ ልጠራ እንድታወቅበት\nጣፋጭ ነሽ ከማር ከወለላ\nምስጋናሽ በአንደበቴ ይሙላ\nለንጉስ ኪሩብ ለመንግስቱ\nማረፊያ ድንግል ለፍጥረቱ', 'am', 119, 0),\n(2, 'አንቺን ብቻ ቤተልሔም', 'አንቺን ብቻ ቤተልሔም\nአንቺን ብቻ ቤተልሔም\nአንቺን ብቻ በዚያ ግርግም\nዮሀንስነ በገሊላ በኤፍራታ አላየንም\nአንቺን ብቻ ቀራንዮ አንቺን በኮረብታ\nዮሴፍንም አላየንም ሊጣስትራ ጎልጎታ\n\nገና በማለዳ በናዝሬቷ መቅደስ\nገብርኤል በስራት ይዞ ከገሊላ ሲደርስ\nያን ዜና ስሰሚ ደነገጥሽ በብርቱ\nአንቺ ብቻ ነበርሽ ብላቴናይቱ\n\nሕፃኑን ስትወልጅ ግርግም የነበሩ\nየሉም በመከራው ቀራንዮን ፈሩ\nበልደቱ እንጂ የታሉ በሞቱ\nአብረሹ ነበርሽ አንቺ ብቻ እናቱ\n\nየግብፅ በረሀ አብረውሽ የወጡ\nበቀያፋ ግቢ እንደምን አልመጡ\nእርሱ ለሚገረፍ እነሱ እያፈሩ\nአንቺን ብቻ ትተው በመንደር ነበሩ\n\nሐሙስ ዕለት ፋሲካን ሲበሉ ያመሹ\nአርብ ዕለት ተነሥተው ከቶ ወዴት ሸሹ\nቃል ገብተው ነበር ላይክዱት መሀላ\nድንግል ካንቺ በቀር ማን ነበር ሌላ\n\nበሠላሳ ዘመን በሥጋ ወራቱ\nመች ነበሩ ከቶ ደቀመዛሙርቱ\nየእጆቹን ታምራት ቀን ከሌሊት እያየሽ\nበቃሉ በርታት ፊት አንቺ ነበርሽ\n\nቤተልሄም ያሉ ቀራንዮ የሉም\nቀራንዮም ያሉ ግርግም አልነበሩም\nበሆነበት ዘመን በመስቀል ሞቱ\nአብረሹ ነበርሽ አንቺ ብቻ እናቱ', 'am', 120, 0),\n(2, 'እኔ የማርያም ነኝ', 'እኔ የማርያም ነኝ\nበእስራቴ አላፍርም እኔ የማርያም ነኝ\nእሮማም አይደለው ፈፁም ክርስቲያን ነኝ\nከእመቤቴ ፍቅር የሚለየኝ ማነው\nመከራ ነው ችግር ወይስ እስራት ነው\n\nአንተ መዝሙረኛ ነብዩ ዳዊት\nእንድታሸበሽብ ከታቦቱ ፊት\nሚልኮን በትንቅህ ሰገነት ላይ ሆና\nእግዚአብሔር አይቷታል ሳትናገር ገና\nእኔስ ለእመቤቴ እዘምራለሁ\nፍቅሯ በደሜ ውስጥ እንዳለ አውቃለሁ\nስሟን ለምን ጠራ ተብዬ ስጠየቅ\nአድምጡልኝ መልሴን ድንግልን እኔ አለቅ\nበአማን በአማን እረዳቴ ናት እመቤታችን\n\nየኤልዛቤት ጭፍሮች መተው ይዘውኝ\nጭው ያለ በረሀ እስር ቤት ጣሉኝ\nሰለ እስራቴ ጌታዬ አውቆልኛል\nሁሉን ተመልክቶ ተበቀሎልኛል\nከዝምታ የተነሳ እንደ ዲዳ ሆንኩኝ\nለበጎ ነገር እንኳን ዝምም ያለኩኝ\nበእኩለ ሌሊት ሊያስፈራሩኝ መተው\nሰሀሊ ለነ ስላት ብርታትን አገኘው\n\nረበናል ዛሬም መስክረው አሰት\nወደፍርድ ወሰዱኝ ከማላውቅበት\nከሳሾቼም ቀርበው ሲከራከሩኝ\nእውነተኛው ዳኛ አሰናበተኝ\nየምስጋና ዘውድን ጌታ ደፍቶልኛል\nለድንግል ውዳሴ ላቀርብ ፈቅዶልኛል\nበአለሟ እናት እና ለቅድስ ሥላሴ\nእስከመጨረሻው ታምስግናት ነፍሴ', 'am', 122, 0),\n(2, 'ጎሳ ልብየ', 'ጎሳ ልብየ\nጎሳ ልብየ ቃለ ሰናየ\nወአነ አይድ ቅዳሴሃ ለማርያም\n\nእኔስ የማርያምን ውዳሴዋን እናገራለው\nእንደ አባቴ ዳዊት በበገና እዘምራለው\nቀን ከሌሊት ሳልል ለምስጋና እተጋለሁ\nየኃጢያቴ ቁስል እንዲ ፈወስ አጮሃለሁ\nምርኩዜ ነሽና እመቤቴ ባንቺ እመካለው\n\nኦ እመቤቴ በእውነት እንወድሻለን\nየእውተኛ መብል ክርስቶስን ወለድሽልን\nምክንያተ ድኂን ድንግልማርያም የአምላክ መገኛ\nባማላጅነትሽ በመታመን እንጮሃለን እኛ\nምህረትን አሰጪን ኪዳነምህረት የዓለም መዳኛ\n\nስለቸርነትሽ እመቤቴ ለእኔ እናቴነሽ\nስለንግስትነትሽም እመቤቴ ነሽ\nዝናባት ሳያጠጡት አየራትም ሳያሳድጉት\nሰማያዊ እንጀራ የሰጠሽን ቤተልሔማዊት\nቅድስተ ቅዱሳን የኖኅ መርከብ የአምላክ እናት\n\nቃና ዘገሊላ በሠርጉ ቤት በዛ ተገኝተሽ ሳለሽ\nውሃውን ወደወይን ባንቺ ምልጃ እንዳስለወጥሽ\nዛሬም የኔ ህይወት ወይኑ አልቆ ባዶ ሆኗልና\nአንቺ የአምላክ እናት ንፅህት ቅድስት ርኀርይተ ሕሊና\nህይወቴን አንጽተሽ ቀድሰሽው ሙይው በምስጋና', 'am', 124, 0),\n(2, 'ዮሐንስን ይዛ', 'ዮሐንስን ይዛ\nዮሐንስን ይዛ ወደ ቀራንዮ\nድንግል ማርያም ሄደች እያለች ወዮ\nሥለ ልጇ ሐዘን ሥለ መከራዋ\nያስገርም ነበረ የፈሰሰው ዕንባዋ\n\nዮሐንስ ቢደንቀው የሐዘኗ ጽናት\nአነሳት ደግፎ በብርቱ ሊያጽናናት\nድንግልም አለችው ልጄ አሳዘነኝ\nእሕት ወንድም የለው ላልቅስለት ተወኝ\nከሁሉም ይበልጣል ያስደፋል አንገትን የማርያም ሐዘን\n\nመቅደላዊት ማርያም ሶሎሜ ዮሐና\nማርያምን አይዋት ጸንቶባት ሐዘኗ\nበልቅሶዋ ጣዕም ተነክቶ ልባቸው\nዕንባን አፈሰሱ ውለታው ገብቷቸው\nከሁሉም ይበልጣል ያስደፋል አንገትን የማርያም ሐዘን\n\nራሔል አልቅሳለች ላላቀፈቻቸው\nድንግል ግን ብታለቅስ አዝላው ተሰዳ ነው\nያዕቆብም አልቅሷል በሌላ የሠው ደም\nማርያም ግን ብታለቅስ ፈሷል የልጇ ደም\nከሁሉም ይበልጣል ያስደፋል አንገትን የማርያም ሐዘን\n\nጠብቶ ስለአደገ የድንግልና ጡቷን\nመቆም አልቻለችም ስታይ መጠማቱን\nበደም ተሸፍኖ ብታየው ውበቱን\nለይልኝ አለችው ከሥጋዋ ነፍሷን\nከሁሉም ይበልጣል ያስደፋል አንገትን የማርያም ሐዘን', 'am', 125, 0),\n(2, 'እመቤቴ ዛሬም ባርኪኝ', 'እመቤቴ ዛሬም ባርኪኝ\nአንድ እርምጃ ሳልራመድ አንችን ይዤ ተነሳው\nእመቤቴ ዛሬም ባርኪኝ ውዳሴሽን አበዛለሁ\nየአምላኬ እናት ዛሬም ባርኪኝ ውዳሴሽን አበዛለሁ\n\nምልጃሽ እየደገፈኝ በጌታ ፊት ስትቆሚ\nፀሎቴን እያሳረግሽ ልመናዬን ስትሰሚ\nከጎኔ ሳትለዪ ተቆጠሩ ዘመናት\nይኸው ለዚህ ደረስኩኝ ከእናትም በላይ ሆነሽ እናት\n\nበጎጆዬ ስላለሽ መጉደልን አላውቅም\nያንደበቴ ቋንቋ ነው እናቴ ያንቺ ስም\nሰንደቄ እና አርማዬ የኔ መታወቂያ ነሽ\nከእግረ መስቀሉ ሥር ቀራንዮ ላይ ያገኘሁሽ\n\nፈውስን የቀዳሁብሽ የበረከት አዘቅት\nለዚህ ቀን የደረስኩት ሆነሽኝ ነው ብርታት\nስንቱን አለፍኩት ባንቺ ወጣው ስንቱን ተራራ\nመከታ ጋሻዬ ነሽ የከሳሾች ቀስት እንዳልፈራ\n\nጌታዬን ከእቅፍሽ ፍቅርን ከመቅደስሽ\nትህትናን ተምሬያለሁ ፊደሌ ስለሆንሽ\nከቶ ነግቶ አይመሽም ለውዳሴሽ ሳልቆም\nብዙ ነው ሚስጥራችን የኔ እና ያንቺ ማርያም', 'am', 126, 0),\n(2, 'ሲነግሩሽ ሰሚ ነሽ', 'ሲነግሩሽ ሰሚ ነሽ\nያለሽ ልዩ ፀጋ ያለሽ ልዩ ክብር\nየሁሉ እመቤት በሠማይ በምድር\nአቁራሪተ መዓት ምዕራገ ፀሎት\nሲነግሩሽ ሰሚነሽ ኪዳነ ምህረት\n\nበመከራ ላለ ሁኚለት መፅናኛ\nዕንባውን አብሺው አይዘን ዳግመኛ\nጉድለቱን ሙይለት በፈረሰው ቆመሽ\nስለምታስምሪው በልዩ ኪዳንሽ\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው\nእናቴ የሚልሽ አምላክሽ ልጅሽ ነው\n\nይበጠስ ከእጁ የወህኒው ሰንሰለት\nየሞቱ ደብዳቤ ይቀየር በህይወት\nአዲስ ተስፋ ሞልተሽ አዲስ ሰው አድርጊው\nመቅበዝበዙን ይርሳ ድንግል አረጋጊው\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው\nእናቴ የሚልሽ አምላክሽ ልጅሽ ነው\n\nበእንባ የመጣው ይመለስ በደስታ\nመጠማቱ ይቅር ይሞላ በእርካታ\nስዕለቱ ሰምሮለት ይቁም ለምስጋና\nየአብራኩን ክፋይ አሳቅፊዉና\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው\nእናቴ የሚልሽ አምላክሽ ልጅሽ ነው\n\nተይዞ ለሚኖር በአልጋ ቁራኛ\nእርቺው እመቤቴ የደዌውን ዳኛ\nመንገርס ላንቺው ነው መማፀን ወደ አንቺ\nተስፋን ለምትቀጥይ እልምን ለምትሰ\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው\nእናቴ የሚልሽ አምላክሽ ልጅሽ ነው', 'am', 128, 0),\n(2, 'ነይ ሶልያና', 'ነይ ሶልያና\nነይ ሶልያና ተጫምተሽ ደመና፣\nነይ አዛኝቱ እመ ትህትና،\nአግዢኝ እናቴ،\nይሙላልኝ ጉድለቴ،\nአቅርቢኝ ከፊቱ،\nይማረኝ ምሕረቱ።\n\nእኔ የማላውቀው ብዙ ነው ጉድለቴ،\nጥሪት አልቆብኛል ባዶ ነው ሌማቴ،\nምርኩዝ ያደረኩት ድንገት ተቀየረ،\nየእኔ ያልኩት ሁሉ የወረት ነበረ።\nደግፊኝ ልቁም،\nአግዢኝ ማርያም،\nአሳስቢ ስለ እኔ،\nይቅለል ሃዘኔ።\n\nበሃዘን ተከብቤ ሰላም ርቆኛል،\nወገን ዘመድ ሁኚኝ እናቴ ከፍቶኛል،\nየሚያጽናናኝ የለም አይዞሽ ባይ ከጎኔ،\nእመ አምላክ አብሺው እንባዬን ከዓይኔ።\nደግፊኝ ልቁም،\nአግዢኝ ማርያም،\nአሳስቢ ስለ እኔ،\nይቅለል ሃዘኔ።\n\nዙሪያዬን ያጠረው በእሾህ አሜኬላ،\nጠላቴ እንዳይውጠኝ ሁኚልኝ ከለላ،\nእኔ ኃጢአተኛ ነኝ የለኝ መልካም ምግባር،\nልጅሽ ፊት አልቆምም በደሌ ቢቆጠር።\nደግፊኝ ልቁም،\nአግዢኝ ማርያም،\nአሳስቢ ስለ እኔ،\nይቅለል ሃዘኔ።\n\nሸክሙ ከብዶብኝ ቀሏል ማንነቴ،\nአሳስቢልኝ ማርያም የእንባ ነው ራቴ،\nከስደት መልሺኝ አልሁን ወገን አልባ،\nከናፈቀኝ ደጅሽ መባን ይዤ ልግባ።\nደግፊኝ ልቁም،\nአግዢኝ ማርያም،\nአሳስቢ ስለ እኔ،\nይቅለል ሃዘኔ።', 'am', 130, 0),\n(2, 'ማርያም ብዬ', 'ማርያም ብዬ\nማርያም ብዬ እዘምራለሁ\nእንደ አባቶቼ እጠራታለሁ\nበያሬድ ዜማ በአዲሱ ቅኔ\nእዘምራለሁ በዕድሜ ዘመኔ\n\nበእሳት መታጠቂያ ታጥቋል ባለ ቅኔው\nመንፈስ ይማርካል ማህሌተ ገንቦው\nበወርቅ ጽና ላይ አርጓል ፀሎቴ\nበአማኑኤል እናቴ ባንቺው በእመቤቴ\n\nበክብር ደመና ተሞልቷል መቅደሱ\nድንግል ያአንቺ ምልጃ ስቦናል ወደ እርሱ\nሆነሽ ተገኝተሻል ሁለተኛ ሰማይ\nጌታ በአንቺ መጣ የፅድቃችን ፀሐይ\n\nአልጠግም ስጠራሽ ማርነሽ ለከንፈሬ\nሰዓሊለነ እያልኩኝ አለሁ እስከዛሬ\nፀጋሽ ቤቴ ሞልቶ ተትረፈረፈልኝ\nሀዘንና ለቅሶ ከኃላ ቀረልኝ\n\nየባላጋራዬ ምሽጉ ፈረሰ\nየመስቀል ሥር ክብሬ እምባዬ ታበሰ\nአልፈራም ከእንግዲህ አለችኝ መከታ\nቁስሌን የምትፈውስ እስሬን የምትፈታ', 'am', 131, 0),\n(2, 'ማርያም ማርያም', 'ማርያም ማርያም\nማርያም ማርያም ልበል\nእረፍቴ ሆይ በስምሽ ልጠለል\nየቃል እናት ያድናል ቃልሽ\nታምር ይሰራል ስምሽ\n\nማር ልበል በምድር ያም ልበል በሰማይ\nየማይጠግቡት መና የማይጨርሱት ሲሳይ\nመንፈስ ቅዱስ ቃኝቶ ሰርቶ በሚስጥሩ\nአፌ ላይ ጣፈጠኝ ስምሽ አጠራሩ\n\nመዳኒት ታቅፈሽ የአለሙን ጌታ\nከቤተልሄም ደጅ እስከ ጎለጎታ\nየዓለሙን ህምም የዓለሙን በሽታ\nታክሚው ነበረ ድንግል በዝምታ\n\nበምን እንመስልሽ የለሽም ምሳሌ\nአንጠግብም ብንጠራሽ ብንዘምርልሽ ሁሌ\nምስክር አያሻም ያንቺ ልእልና\nየአለሙን ንጉሥ ወልደሺዋልና\n\nየወርቅ ማእጠንት እሳት የታቀፍሽ\nየአዲስ ኪዳን ኪሩብ ማርያም አንቺ ነሽ\nየአርያም እጣን ነሽ መአዛሽ ያማረ\nዘላለም አይወድቅም አንቺን ያከበረ', 'am', 132, 0),\n(2, 'አልረሳውም ያንን ዕለት', 'አልረሳውም ያንን ዕለት\nአልረሳውም ያንን ዕለት\nአልዘነጋው ያን ደግነት\nእናቴ ሆይ ምልሽ ኪዳነ ምሕረት\nእምዬ ሆይ ምልሽ ኪዳነ ምሕረት\nስላለኝ ነው ምክንያት\n\nለሠው ተናግሬ ያልተረዳኝ ሰው\nዕንባዬ በምሬት ከዓይኔ የሚፈሰው\nየቤቴን ገመና ሁሉን ስነግርሽ\nአዛኝ እህት ነሽና እራራልኝ ልብሽ\nአረሳው መቼም የአንቺን ደግነት\nውለታ አለብኝ ኪዳነ ምሕረት\n\nልቤ በሐዘን ጠቁሮ ውስጤ እየደማ\nበቅረዜ ሲጨልም ስጓዝ በጨለማ\nበራፌን ዘግቼ ዝምብዬ አለቅሳለሁ\nአይኔን አቀርቅሬ እናቴ እልሻለሁ\nዘንበል አልሽልኝ ሠምተሽ ፆሎቴን\nአልተጸየፍሽም ብቸኝነቴን\n\nእናት የለኝ ብዬ ከቶም አልከፋ\nእኔስ አይቻለሁ ስትሞይኝ በተስፋ\nምድራዋዊ እናቴ ለጊዜው ነው ፍቅሯ\nያንቺስ ግን ልዩ ነው እረ ስንቱን ላውራ\nማርያም ማርያም ብል አልሠለችሽ\nበልቤ ጽላት ስለ ታተምሽ\n\nሲረበኝ መጥተሻል ሲጠመኝ ደርሰሻል\nለጎደለው ቤቴ በረከት ሆነሻል\nጭንቄም ቀለለልኝ ሐዘኔም ራቀ\nያስጨነቀኝ ጠላት ራሱ ተጨነቀ\nመዳኒት ወልደሽ ዳኩኝ ከመሜ\nይኸው ዘመርኩኝ በምልጃሽ ቆሜ', 'am', 133, 0),\n(2, 'ውዳሴ ማርያም እጮኻለሁ', 'ውዳሴ ማርያም እጮኻለሁ\nውዳሴ ማርያምእጮኻለሁ\nድንግል እናቴን እጣራለሁ:\nእንደ አባ ኤፍሬም ነይ ባርኪኝ\nወድሰኒ ልጄ በይኝ:\n\n“ውዳሴ ማርያም” በሰርክ ጸሎት ላይ\n”ውዳሴ ማርያም” ዜማ ስናደርስ:\n“ውዳሴ ማርያም” ድንግል ትመጣለች\n“ውዳሴ ማርያም” በቤተ መቅደስ:\n“ውዳሴ ማርያም”የብርሃን ምንጣፍ\n“ውዳሴ ማርያም” ከፊቷ ተነጥፏል:\n“ውዳሴ ማርያም” ቅዱስ ኤፍሬም ታጥቆ\n“ውዳሴ ማርያም” ያመሰግናታል\n\n“ውዳሴ ማርያም” አባ ሕርያቆስ\n“ውዳሴ ማርያም” ምስጋና ያደርሳል:\n“ውዳሴ ማርያም” የቅዳሴው ዜማ\n“ውዳሴ ማርያም” ልብን ይመስጣል:\n“ውዳሴ ማርያም” በጎ ነገር ልቤ\n“ውዳሴ ማርያም” አወጣ እያለ\n“ውዳሴ ማርያም” ዳዊት በገናውን\n“ውዳሴ ማርያም” እየደረደረ\n\n“ውዳሴ ማርያም” የንጽሕናችን\n“ውዳሴ ማርያም” መሰረት ነሽና\n“ውዳሴ ማርያም” አንቺን ለማመስገን\n“ውዳሴ ማርያም” ልቦናዬ ይብራ\n“ውዳሴ ማርያም” ተፈስሒ ድንግል\n“ውዳሴ ማርያም” ኦ ቤተ ልሔም\n“ውዳሴ ማርያም” ካንቺ ተወለደ\n“ውዳሴ ማርያም” መድኃኒዓለም\n\n“ውዳሴ ማርያም” ቅዱሳኑ ሁሉ\n“ውዳሴ ማርያም” ዙሪያሽን ከበዋል\n“ውዳሴ ማርያም” ቅዱስ ጊዮርጊስም\n“ውዳሴ ማርያም” ንዒ ድንግል ይላል\n“ውዳሴ ማርያም” በወርቅ ዙፋን ላይ\n“ውዳሴ ማርያም” ተቀምጠሽ ሳይሽ\n“ውዳሴ ማርያም” ልቤ ተሰወረ\n“ውዳሴ ማርያም” ድንግል በግርማሽ', 'am', 134, 0),\n(2, 'ለማርያም', 'ለማርያም\nለማርያም\nእንዘምራለን ለዘለዓለም\n\nየተዘጋች ደጅ ለዘለዓለም\nህዝቅኤል ብሏል ለዘለዓለም\nንፅሕት ናት በእውነት ለዘለዓለም\nበፍጹም ድንግል ለዘለዓለም\nአብነት አድርገን ለዘለዓለም\nአኛም እርሱን ለዘለዓለም\nበፍፁም ፍቅር እንዘምራለን\n\nየዋህይት ርግብ ለዘለዓለም\nሰላም አብሳሪ ለዘለዓለም\nለጨለማ ሕይወቴ ለዘለዓለም\nብርሃንን አብሪ ለዘለዓለም\nእማጸንሻለሁ ለዘለዓለም\nድንግል ለነፍሴ ለዘለዓለም\nአደራ ቅድስት አንቺ ነሽ ዋሴ\n\nእጅግ የበዛ ነው ለዘለዓለም\nያለኝ ፍቅር ለዘለዓለም\nአይወሰንም ለዘለዓለም\nአይነገርም ለዘለዓለም\nበእርሷ ደስ ይለኛል ለዘለዓለም\nሐሴት አደርጋለሁ ለዘለዓለም\nስሟን እየጠራሁ እዘምራለሁ\n\nነይ ነይ ስላት ለዘለዓለም\nቀንና ሌሊት ለዘለዓለም\nአትለየኝም ለዘለዓለም\nለእኔስ ቅርቤናት ለዘለዓለም\nእፁብ እፁብ ብለው ለዘለዓለም\nአመሰገኗት ለዘለዓለም\nክብሯን ሊገልፁት ቢያጥራቸው ቃላት', 'am', 135, 0),\n(2, 'በጎ መዓዛ ሽቶዬ ነሽ', 'በጎ መዓዛ ሽቶዬ ነሽ\nበጎ መዓዛ ሽቶዬ ነሽ\nበሰው ሁሉ ፊት ዘመርኩልሽ\nበአንቺ ጣፈጠ አልጫነቴ\nእጠራሻለሁ ነይ እመቤቴ\n\nምሳሌ የሌለሽ ነይ እመቤቴ\nዘመዴ ነሽ ነይ እመቤቴ\nያን ክፉ ዘመንን ነይ እመቤቴ\nያለፍኩብሽ ነይ እመቤቴ\nበፍቅርሽ እሳት ነይ እመቤቴ\nልቤ ነደደ ነይ እመቤቴ\nእናትነትሽን ነይ እመቤቴ\nስለወደደ ነይ እመቤቴ\n\nየሰውስ ውበት ነይ እመቤቴ\nምን ይረባኛል ነይ እመቤቴ\nሰረገላዬስ ነይ እመቤቴ\nመች ያድነኛል ነይ እመቤቴ\nከተሠወረ ነይ እመቤቴ\nክፉ መከራ ነይ እመቤቴ\nእድናለሁኝ ነይ እመቤቴ\nአንችን ስጠራ ነይ እመቤቴ\n\nለስንፍናዬስ ነይ እመቤቴ\nመቼ ልክ አለው ነይ እመቤቴ\nስለ በደሌ ነይ እመቤቴ\nእተክዛለው ነይ እመቤቴ\nለአነጋገሬ ነይ እመቤቴ\nማጣፈጫ ነሽ ነይ እመቤቴ\nተሰምቻለው ነይ እመቤቴ\nድንግል ሆይ ስልሽ ነይ እመቤቴ\n\nየመንገዴ ስንቅ ነይ እመቤቴ\nየራቤ መርሻ ነይ እመቤቴ\nለታመመ ሰው ነይ እመቤቴ\nነሽ መፈወሻ ነይ እመቤቴ\nየተማጸነ ነይ እመቤቴ\nበስምሽ አምኖ ነይ እመቤቴ\nማን አፍሮ ያውቃል ነይ እመቤቴ\nፊትሽ ለምኖ ነይ እመቤቴ', 'am', 136, 0),\n(2, 'ድንግል የዚያን ጊዜ', 'ድንግል የዚያን ጊዜ\nድንግል የዚያን ጊዜ ሐዘንሽ በረታ\nበመስቀል ላይ ሆኖ ልጅሽ ሲንገለታ\n\nየግፍ ግፍ ደርሶበት የዛን ጊዜ ተጠማሁ ሲልሽ\nለውሻ ያጠጣሽ በወርቅ ጫማሽ\n\nሴቶች ሲያባርሩት የዚያን ጊዜ እራርቶ ሆድሽ\nለፍጡር በማዘን ውኃ ያጠጣሽ\n\nተጠማሁ እያለ የዚያን ጊዜ ሲናገር ልጅሽ\nታዲያ እንደምን ቻለ ወላድ አንጀትሽ\n\nእንደዚያ ስታለቅሽ የዚያን ጊዜ ሐዘን ሲውጥሽ\nእነማን ነበሩ ያስተዛዘኑሽ\n\nስታለቅሽ በማየት የዚያን ጊዜ እራርቶ ልጅሽ\nዮሐንስን አጽናኝ እንደልጅ ሰጠሸ', 'am', 137, 0),\n(2, 'ምክንያት ስላለኝ ነው', 'ምክንያት ስላለኝ ነው\nምክንያት ስላለኝ ነው የምዘምርልሽ\nምክንያት ስላለኝ ነው ቅኔ የምቀኝልሽ\nአሁንም ይብዛልኝ ፍቅርሽ\nከዚህ በላይ እንዳመሰግንሽ\n\nአውቃለሁ ከደጅሽ ምን እንዳገኘሁኝ\nአስታውሰዋለሁ ሸክሜን እንደጣልኩኝ\nየለመንኩሽ ሁሉ መቼ ከንቱ ቀረ\nሰይጣን ተመለሰ እንዳቀረቀረ\nጠላት ቢከፋውም ለአንቺ በመቆሜ\nአደገድጋለሁ ደግሜ ደግሜ\n\nልቤ አርፏል በአንቺ በእናቴ አማላጄ\nእንቅፋት እሾሁ አይበቅልም በደጄ\nበሚጣፍጥ ዜማ በኤፍሬም ውዳሴ\nሳሸበሽብልሽ ትረካለች ነፍሴ\nጠላት ቢከፋውም ለአንቺ በመቆሜ\nአደገድጋለሁ ደግሜ ደግሜ\n\nውለታ ያለበት የማይከፈል\nሲመሽም ሲነጋም ያመሰግናል\nማርያም ማርያም ይላል ምድርና ሰማዩ\nበልጅሽ መከራ አልፎለት ገዳዩ\nጠላት ቢከፋውም ለአንቺ በመቆሜ\nአደገድጋለሁ ደግሜ ደግሜ', 'am', 138, 0),\n(2, 'አብሰራ ገብርኤል', 'አብሰራ ገብርኤል\nአብሰራ ገብርኤል ለማርያም\nወይቤላ ትወልዲ ወልድ\nሚካኤል መላዕክ በክነፍ ፆራ\nመንጦላዕት ደመና ሰወራ\nንፅህት በድንግልና አልባቲ ሙስና\nተወልደ ወልድ እምኔሐ\n\nገብርኤል ማርያም አበሰራት\nወንድ ልጅም ትወልጃለሺ አላት\nሚካኤል መላዕክ በክንፋ ከለላት\nየሰማይ መጋረጃውን ሸፈናት\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና\n\nአዳም በጥፋቱ ከገነት ሲባረር\nበሚካኤል ክንፎች ቀድሞ አይቶሽ ነበር\nሔዋንን ሲጠራት ሕይወቴ ነሽ አላት\nእንደሚድን አውቆ ድንግል በአንች ምክንያት\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና\n\nእግዚአብሔር የላከው የከበረው መላዕክ\nድንግል ሆይ ለክብርሽ ዐየን ሲንበረከክ\nበፍቅር በትህትና በፍፁም ሰላምታ\nየጌታ ሰው መሆን የነገረሽ በደስታ\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና\n\nደስተኛዬቷ ሆይ ደስ ይበልሽ ድንግል\nየአብ ቃል ክርስቶስ ሥጋሽን ይለብሳል\nአንቺም ትይዋለሽ ስሙን ኢየሱስ\nመድኋኒት ነውና ለሥጋ ወነፍስ\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና\n\nአንደ ኒቆዲሞስ ሳትከራከሪ\nአንደ ዘኬርያስ ሳትጠራጠሪ\nይሁነኒ ብለሽ ቃልን ተቀበልሽ\nከፍጥረት ማነው አንቺ የሚመስልሽ\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልና', 'am', 139, 0),\n(2, 'ቅዳሴ ማርያም አዜማለው', 'ቅዳሴ ማርያም አዜማለው\nቅዳሴ ማርያም አዜማለው\nውዳሴሽንም አደርሳለው\nመልክሽን ስደግም ለፍልሰታ\nተገለጪልኝ ጠዋት ማታ\n\nበምን ስራዬ ነው ማይሽ\nምኞቴ ነው ስለምወድሽ\nፍቅርሽ ጠርቶኝ ለምስጋና\nተሰለፍኩኝ እንደገና\nልቤ አንቺን ፈልጎይዞራል\nአየራትን ሰንጥቆ ይበራል\nአሳራፊው በምልጃሽ ማርያም\nያላንቺ የሚሆን የለም\n\nበኔ ሀይማኖት ባንቺ ጸሎት\nፈውስ አገኘው ከመለኮት\nበልቤ አይን እያየውሽ\nበሀሳቤም አገኘውሽ\nታቦት ነሽ የመንፈስ ቅዱስ\nነሽና ያርያም እህት\nየምንጠጣሽ ንፁህ የምንጭ ውሃ\nሀብታችን ገንዘብ ነሽ ለደሀ\n\nቀርቢያለው በንስሀ\nእዘኝልኝ አዛኝቷ\nአለም ጠልፋ እንዳትጥለኝ\nጥበቃሽም አይለየኝ\nአይጠፋም ከሰው ልጅ ስተት\nምክንያት ነሽ ለአለሙ ድህነት\nአክሚልኝ የልቤን ሀዘን\nእማምላክ እመብርሀን\n\nናዛዚቱ ለዮሴፍ\nምስጋና አለሽ ከአእላፍ\nስምሽ ስልጡን በእግዚአብሔር ዘንድ\nከአለም አንስት መርጦሻል ወልድ\nየሰማይ የሰማይ ደጅነሽ\nያእቆብ በሎዛ ነው ያየሽ\nመመኪያችን የፅድቃችን አንባ\nአሳስቢ ገነት እንድንገባ', 'am', 140, 0),\n(2, 'ወዳንቺ የመጣው', 'ወዳንቺ የመጣው\nወዳንቺ የመጣው በብሩህ ደመና\nከሦስቱ አካል አንዱ ክርስቶስ ነውና\nየጠፋ በግ አዳም ታደሰ በጌታ\nባንቺ ተፈጸመ የሰው ልጆች ደስታ\n\nበደይን የተጣለች ሄዋን ተደሰተች\nየደስታ መፍለቂያ አንቺን ስላገኘች\nየበረከት ፍፌ ከአንቺ ተገኘልን\nየወይን ቦታ ነሽ ድንግል እናታችን\n\nወልድም ባህሪይሽን ባህርይ አድርጎት\nለፍጥረታት ጌታ መዓዛሽ ተስማምቶት\nከአንቺ ይወለድ ዘንድ ፍጹም ሊላላክሽ\nበጥቂት አደገ ተልኮና ታዞሽ\n\nከድንግልና ጋር አንድ የሆነ ሀሊብ\nበሩካቤ ሳይሆን በብስራት እንደ ንብ\nከሆድ መጥበብ ጋር የመለኮት ስፋት\nአንቺ ሆነሽ ሳለ ታናሿ ሙሽሪት\n\nበፍጡት ህሊና የማይመረመር\nዕጹን ነው ድንቅ ነው የመጽነሷ ነገር\nእሳተ ነበልባል በሆድሽ ውስጥ ሲያድር\nነደ ነበልባሉ አልፈጀሽም ነበር', 'am', 141, 0),\n(2, 'ኪዳነምህረት እናቴ', 'ኪዳነምህረት እናቴ\nኪዳነምህረት እናቴ\nሚስጥረኛየ ጓዳየ\nየጎደለኝን ታውቂያለሽ\nካፌ ሳይወጣ ሳልነግርሽ\n\nአልፏል መናኛው ኑሮ\nምልጃሽ ውሀውን ቀይሮ\nመልካሙ ወይን ደረሰ\nእንባየ ባንቺ ታበሰ\n\nልዘምር ልቁም ከፊትሽ\nልምጣ ልንበርከክ ለክብርሽ\nብርቅ ከሀገር ከቤቴ\nከቶ አረሳሽም እናቴ\n\nአልልም መቼ ነው ቀኑ\nየኔ መጎብኛ ዘመኑ\nእንዲሚፈፀም አምናለሁ\nሁሉን በጊዜው አያለሁ\n\nየልቤን ችግር ላዋይሽ\nከስእልሽ ፋት ቆሜ\nእንባዬ ቀድሞኝ ዝም አልኩኝ\nሳልነግርሽ ስለምታውቂ', 'am', 142, 0),\n(2, 'ተዘራ ቅኔ', 'ተዘራ ቅኔ\nተዘራ ቅኔ ለማርያም ተመሰከረ\nተዘራ ቅኔ ለድንግል ሁሉም ዘመረ\nያልተባለላት ምን አለና ያልተነገረ\n\nከሰላም ፈሳሽ ያረሰርሳል\nበቅፏ ያለው ልብ ይፈውሳል\nማነው በልጇ ያልተባረከ\nዝናሩን ፈቶ ያልተማረከ\n\nምድርን ከደነ ከቁጥር በዛ\nየፀጺዮን ዜማ አለምን ገዛ\nመላእክት ወርደው በሷ ከተሙ\nበማህፀንዋ ቅኔን ሊያሰሙ\n\nከአበው አንደበት ጥበብ ተቀዳ\nውዳሴው ሲዘንም ከመዝሙር ጓዳ\nከሰገነት ላይ ንጉሱ ወርዶ\nሞገስ ሆነችው ቢጠራት ማልዶ\n\nያዘነው ያርፋል ስሟን ሲሰማ\nይፅናናባታል በጭንቅ የደማ\nያለም መክበሪያ ብፅዕይት ፅዋ\nዳግማዊት ሰማይ ታየን በርሃኗዋ', 'am', 143, 0),\n(2, 'የልቤ ዜማ ነሽና', 'የልቤ ዜማ ነሽና\nየልቤ ዜማ ነሽና\nሰላም ነው ያንቺ ምስጋና\nሞገሴ ነው ስምሽ ለኔ\nስላለሽ ማርያም ከጎኔ\n\nበመገፍት ብኖር እምነቴን አፀናለሁ\nበጣቶችሽ ተይዤ አዲሱ ቀን አያለሁ\nስማፀን ደጅሽ መጥቼ\nተመለሰኩ ተረጋግቼ\nእንደምን አንቺን እረሳለሁ\nበምልጃሽ ተፈውሻለሁ\n\nየጠላቶቼን አራስ የሚቀጠቅጠው\nየአብራክሽን ፍሬ ተስፍዬን አበራው\nየድኅነት ምክንያት አርጎሻል\nለአዳም ዘር ትምክህት ሆነሻል\nየልቤ ብርሃን ፍና\nአዛኝት ባንቺ ልፅናና\n\nየአፌን እንጉርጉሮ ምስጋናዬ ወርሶታል\nእግሬ ከእረግረግ ወጥቶ በሰገነት ተተክሏል\nሐዜኔን የምሻገረው\nስምሽን እየጠራሁ ነው\nአገኘው ደስታ ሰላም\nጠርቼ ብዬ ማርያም\n\nበአብረቅራቂው ፍቅር በዓለሙ ውስጥ ስኖር\nለሙውጣት ዳክራለሁ ማርያም ማርያም እላለሁ\nሰምተሻል ልመናዬን\nወጣሁኝ ያኑን ጥልቁን\nእሳቱን ባንቺ አልፌአለሁ\nበምልጃሽ ደግፌ አለው', 'am', 144, 0),\n(2, 'ማርያም ደስ ይበልሽ', 'ማርያም ደስ ይበልሽ\nማርያም ማርያም ማርያም\nደስ ይበልሽ በገብርኤል ሰላምታ\nበአንቺ ስላደረ የዓለም ሁሉ ጌታ\n\nየአምላክ ቸርነቱ ፈቃዱ ሲሆን\nጨለማው ተገፎ ሲወጣ ብርሃን\nመድኃኒት ሲመጣ ሰይጣን እንደ አፈረ\nየዜናው አብሳሪ ገብርኤል ነበረ\n\nድንግል ተቀምጣ በቤተ መቅደስ\nሐርና ወርቁን አስማምታ ስትፈትል ንግሥት\nገብርኤል ገብርኤል ዜናዌ ሐዲስ\nየአምላክን መወለድ ስጋ በመልበስ\n\nገብርኤል ሲያበስራት ድንግል ስትሰማ\nአምላክ በርሷ አደረ የመለኮት ግርማ\nእውነተኛ መልአክ መሆኑን ስላየች\nይሁንልኝ ብላ ቃሉን ተቀበለች', 'am', 145, 0),\n(2, 'የመስቀሉ ፍቅር ሲገባን', 'የመስቀሉ ፍቅር ሲገባን\nየመስቀሉ ፍቅር ሲገባን\nእመቤታችንን እንወዳታለን\nየመስቀሉ ፍቅር የገባቸው\nእመቤታችን አለች ከጎናቸው\n\nአባ ሕርያቆስ አባታችን\nየመስቀሉ ነገር ቢገባው\nልቤ አፈለቀ አለ መልካም ነገር\nከእመቤቴ ጋራ ሲነጋገር\nከድንግል ማርያም ጋር ሲነጋገር\n\nነይ ነይ እምዬ ማርያም\nነይ ነይ ቤዛዊት አለም\nአንድ ወልዳ ስሙን አበዛችው\nአንዱ ሃገር ስትሄድ መድሃኒአለም አለችው\nአንዱ ሃገር ስትሄድ ኢየሱስ አለችው\nአንዱ ሃገር ስትሄድ ክርስቶስ አለችው\n\nለመናኒው ፀሎት ልዩ እጣን\nየዋሻው ሻማ ነሽ እመብሃን\nመአዛሽ ሸተተኝ ከግሸን\nትናፍቂኛለሽ ምን ልሁን\n\nዳዊት በመዝሙሩ ያነሳሻል\nየያዕቆብ ድንኳን ነሽ ይልሻል\nየእግዚአብሔር ሃገር የሚሉሽ\nእመቤቴ ማርያም አንቺ ነሽ\n\nቤተልሔም ስሄድ አይሻለሁ\nቀራኒዮ ስሄድ አይሻለሁ\nፍጹም አትለይም ከልጅሽ\nየአንቺስ ልዩ ነው ፍቅርሽ', 'am', 146, 0),\n(2, 'ሰላሜ ነሽ ድንግል', 'ሰላሜ ነሽ ድንግል\nሰላሜ ነሽ ድንግል ዋስትናዬ\nውበቴ ነሽ ማርያም አለኝታዬ\nየጭንቀቴ ደራሽ የህመሜ\nተፈታልኝ ባንቺ ፅኑ ህልሜ\n\nወገን ዘመድ ያልኩት ሁሉ ራቀኝ\nሃዘን ፅልመት ችግር ገዝፎ ታየኝ\nብራብ ምግቤ ሆነሽልኝ አይቻለው\nሰላም ባጣም ባንቺ እፅናናለው\nፍቅርን ወልደሽ ሰላምን አገኘው\nድንግል በምልጃሽ ተፈውሻለው\n\nየሰላም ምንጭ የነፃነት አርማ\nክብር የምትሰጭ ሞገስ ታላቅ ግርማ\nአንቺን ተስፋአድርጌ ወጥቻለው\nቀንና ለሊት ነይ እልሻለው\nላንቺ ልንበርከክ አይዛል ጉልበቴ\nውዳሴሽ ይብዛ ከአንደበቴ\n\nሱላማጢስ ስልሽ እረካለው\nበህይወቴ ሰላም አግንቻለው\nእንደ ሰው ልጅ ቀን እያየሽ የማትርቂኝ\nየአማኑኤል እናት ዛሬም ባርኪኝ\nተባርኬዋለው ድንግል በፍቅርሽ\nእሄሁ ቆሜያለው ልዘምርልሽ', 'am', 147, 0),\n(2, 'ስደትሽን ሳስብ', 'ስደትሽን ሳስብ\nስደትሽን ሳስብ ስለአንቺ ልገፋ\nለካስ ስደት አለ ቀን በሰው ሲከፋ\nወስዶ ሳያስቀርሽ ወንዝና ጅረቱ\nምሳሌ ሆነሻል ድንግል ለፍጥረቱ\n\nእንዳልቅበዘበዝ ሁኚ ከአጠገቤ\nድንግል ሆይ ስራሽን መዝግቦታል ልቤ\nበምሕረት ይለፈኝ በፍጹም ይቅርታ\nእሺ ባዩ ልጅሽ የታቀፍሽው ልጅሽ\n\nሱላማጢስ ብሎ ሰለሞን ጠራሽ\nየሰላም መገኛው አንቺ ስለሆንሽ\nእንበረከካለሁ እሰግዳለሁ ለአንቺ\nጠላት እንዳይጥለኝ ጉልበቴን አበርቺ\n\nየኮቲባ ቁጣ ዛቻና ክፋቷ\nአስተናግዳዋለች ምድር አፏን ከፍታ\nበአንቺ ላይ ያመጹት በቁጣው ጠፍተዋል\nከጥቅልሉ መዝገብ ከሱ ተሽረዋል\n\nለተጠሙት ነፍሳት ያጠጣቸው ጌታ\nከጀርባሽ ላይ ሆኖ በዱር ተንገላታ\nየግብጽን ጣዖታት በግርማው መታቸው\nኢየሱስ ክርስቶስ ያለቆች ጌታቸው', 'am', 148, 0),\n(2, 'ማሪኝና ልሂድ', 'ማሪኝና ልሂድ\nማሪኝና ልሂድ ወደ ቤቴ ልግባ\nይበቃሻል በይኝ የማነባው እንባ\nደጅሽ ላይ ከወደቅኩ አለፉ ዘመናት\nፈውስን ተጠምቼ አቃተኝ መጽናናት\n\nቆዩ ከተዘጉ የቤቴ መቃኖች\nእጅግ እራቁብኝ የመዳኔ ቀኖች\nዛሬስ ይበቃኛል ልነሳ ካልጋዬ\nበምልጃ ጸሎትሽ በሽታዬን ጥዬ\nአይነቀል እግሬ ዘላለም ከደጅሽ\nተመላለሽ ብሎ ካልዳሰሰኝ እጅሽ\n\nወገን ዘመድ የለኝ የሚረዳኝ ቀርቦ\nልቤ ተሰበረ በሐዘን ተከቦ\nእንኳን የሚደግፍ ሚሰማኝም ጠፋ\nአሳይኝ በዓይኔ ይህምች ቀን አልፋ\nያሰብኩት እስኪሆን አይኔ አያቀላፋ\nምሕረት ከሞላበት ከደጅሽ አልጥፋ\n\nየሚያድንሽ የለም እያሉ ብዙዎች\nተግተው ቆጠሩብኝ የሞቴን ቀናቶች\nበሐዘን አጎብሼ እንባዬን እረጫለው\nድንግል ካልዳሰስሽ መቼ ቀና እላለው\nኖራለው በተስፋ አንቺን ተጠግቼ\nአልቀርም ዘላለም የተገፋሁ ሆኜ\n\nየእግሮቼን ሰንሰለት ላውልቅ ተፈውሼ\nአዲሱን ሰውነት በምልጃሽ ለብሼ\nአትድንም ባሉኝ ፊት ልቁም በምስጋና\nህመሜን መሸፈን ይቻልሻልና\nማቃሰቴ ቆሞ ልሞላ ዝማሬ\nድንግል በጸሎትሽ ታጥሮልኝ ድንበሬ', 'am', 149, 0),\n(2, 'ዛሬም አለሽ በልቤ', 'ዛሬም አለሽ በልቤ\nዛሬም አለሽ በልቤ\nድንግል ሆይ ወለታሽ አይጠፋም ከሀሰቤ\n\nእንደ ሀጥያቴ ብዛት እንዴ በደሌማ\nየጥልቁ ሰንሰለት ሲይንሰኝ ነው ጨለማ\nግን ያንች ሆንኩኝና ሁሉንም አለፈኩኝ\nያንን የሞት ባህር በምልጃሽ ቀዝፈኩኝ\n\nአርፏል ልቤ በአንቺ በአዛኝቷ ማርያም\nውስጤ እያፈሰሰ ፍቅርና ሠለም\nህመሜም ቢያስረሳኝ የወዳሴሽ ቃና\nእመቤቴ እላለሁ ዛሬም እንደገና\n\nእናታችን ፅዮን ሰው ሁሉ ይልሻል\nዳዊት በበገና ያመሰግንሻል\nየአሴቦን ነግሥታት ለክብርሽ ዘማሩ\nየማትፈርሽ መቅደስ የእግዚአብሔር ሀገሩ\n\nእጅግ ብዙ ነገር አድርገሽልኛል\nይቅር ባይ ልጅሽ በፍቅር አይቶኛል\nእኔስ እኖራሉሁ ድንግል በአንች ጥላ\nጨለማን አላይም ከእንግድህ በኃላ', 'am', 150, 0),\n(2, 'ማርያም ድንግል ለባሲተ ሞገስ', 'ማርያም ድንግል ለባሲተ ሞገስ\nማርያም ድንግል ለባሲተ ሞገስ\nልጅሽ ስለሆነ መድኃኒት ለነፍስ\nከጠፋበት ቦታ ልቤን ይመልስ\n\nግርማ ያለሽ ድንግል ስምሽ ተወደደ\nዓለሙ በሙሉ ለክብርሽ ሰገደ\nጉድፍ ቢሞላበት በይፀዳም ሕይወቴ\nከእቅፍሽ አታውጪኝ ድንግል እመቤቴ\n\nትውልድ ይጠራሻል ብፅዕት እያለ\nድንግል የት ይገኛል አንቺን የመሰለ\nየጨነቀው ሁሉ ሰአሊ ለነ ብሎ\nመልስ ያገኝብሻል ልቡን ላንቺ ጥሎ\n\nየዚህ ዓለም ገዢ ወጥመድ ሳይጥለኝ\nየስጋ ፈተና ሳይጠላልፈኝ\nየሰላሙን መረብ ወደኔ ጣይና\nለልጅሽ ልገዛ ዛሬም እንደገና', 'am', 151, 0),\n(2, 'ሰላም ለኪ እያለ', 'ሰላም ለኪ እያለ\nሰላም ለኪ እያለ\nሐርና ወርቁን ስταስማማ\nየገብርኤል ድምፅ ተሰማ\nተሰማ የመልአኩ ድምፅ ተሰማ\nተሰማ የገብርኤል ድምጽ ተሰማ\n\nውሃ ስትቀጂ ክንፉን እያማታ\nሊያበስርሽ የመጣው በታላቅ ደስታ\nከሞገስሽ ብዛት ሲታጠቅ ሲፈታ\nአቅርቦልሽ ነበር የክብር ሰላምታ\n\nየምሥራቹን ቃል ምስጢር ተሸክሞ\nገብርኤል ተላከ ሊያረጋጋት ደግሞ\nእርጋታን ተሞልታ ነገሩን መርምራ\nየመልአኩን ብሥራት ሰማችው በተራ\n\nይደሰታል እንጂ መንፈሴ በአምላኬ\nበምስጋና ሳድር ዘወትር ተንበርክኬ\nሃሳቤ ለቅፅበት ሌላ መች ያስባል\nለእኔ ልጅን መውለድ እንዴት ይቻለኛል\n\nከአንቺ የሚወለደው ልዑል ነው ክቡር\nየተመሰገነ በሰማይ በምድር\nምስጢሩ ኃያል ነው ይረቃል ይሰፋል\nከአንቺ በቀር ይኼን ማን ይሸከመዋል\n\nእጹብ ነው ድንቅ ነው አንቺን የፈጠረ\nአንቺን በመውደዱ ሰውን አከበረ\nዓለም ይባረካል በማሕፀንሽ ፍሬ\nክብርሽን አልዘልቅም ዘርዝሬ ዘርዝሬ', 'am', 152, 0),\n(2, 'ቋንቋዬ ነሽ ድንግል', 'ቋንቋዬ ነሽ ድንግል\nቋንቋዬ ነሽ ድንግል መግባቢያዬ\nመልስ የማገኝብሽ ከጌታዬ\nበአንቺ ቀርቤአለሁ ከአምላኬ ፊት\nቤቴ ሞልቶልኛል በበረከት\n\nበምን ስራዬ ነው በፊቱ የቆምኩኝ\nመቼ በቅቼ ነው ስሙን የጠራሁኝ\nአስታራቂ እናት አንቺን ስለሰጠኝ\nስለ ቃልኪዳንሽ አቤት ልጄ አለኝ\n\nቅድስና ሕይወት ከኔ ተሰውሮ\nበውሸት በሐሜት አንደበቴ ታጥሮ\nበእመ አምላክ ምልጃ አዲስ ሰው ሆኛለሁ\nእንደ መላእክቱ ይኸው እዘምራለሁ\n\nስለ እመ አምላክ ብሎ ያፈረ የለም\nበአንቺ ያልከበረ ሰው አይገኝም\nእንደ ባለ ማዕረግ እኔም ሰው መባሌ\nአንቺን አግኝቼ ነው ድንግል መሰላሌ\n\nሰላም ለኪ ብዬ ስጀምር ጸሎቴን\nሐሴት ይሞላዋል መላ ሰውነቴን\nእንደ ቅዱስ ኤፍሬም በምስጋናሽ ልጽና\nበእጆችሽ ያለው አምላኬ ነውና', 'am', 153, 0),\n(2, 'ጽርሐ አርያም', 'ጽርሐ አርያም\nጽርሐ አርያም\nክብርሽ ገናና ነው ለዘለአለም\n\nበመላእክት ዓለም በሶስቱ ከተማ\nበኤረር በኢዮር እንዲሁም በራማ\nውዳሴ ቀረበ ለሰማይ ንግስት\nየአምላክን እናት በክብር አየናት\n\nበበረሀ ያሉ አለምን የናቁ\nውዳሴሽን ደግመው ስምሽን የሰነቁ\nአንቺን ስንጠራ ጠላት ገለል ይላል\nማርያም በግርማሽ ከሳሻችን ያፍራል\n\nከእግሮቿ በታች ጨረቃን ተጫምታ\nየክብርን አክሊል በራሶቿ ደፍታ\nበቅዱሳን ሁሉ ትመሰገናለች\nአለም የዳነባት ድንግል ማርያም ነች\n\nብርሃንን ለብሳ በንጽህና አጊጣ\nፍጥረትን ስትባርክ በክብር ተገልጣ\nነፍሳት ተቀደሱ በእምነት ከበዋት\nከበሮን አንስተን እንዘምርላት', 'am', 154, 0),\n(2, 'የአርምሞ እናት', 'የአርምሞ እናት\nየአንደበት የብዕሯን ሀይል በፀጋዋ ብንመዝነው\nየእርሷን ስብከት የእርሷን ጦማር የሚችል የቱ ነው\nየአምላክ እናት የአርምሞ እናት\nዝምታዋ ግን ድንቅ ነው\n\nከሀያ ሁለቱ ፍጥረት ሰባቱን በአርምሞ\nየፈጠረ ልጇ በቀራንዮ ደግሞ\nበሸላቾቹ ፊት ዝም እንደሚል ጠቦት\nበአርምሞ አዳነን በሞቱ ገድሎ ሞት\n\nግብሯም እንደ ልጇ መልኳም እነደ አምላኳ\nሁሉንም በልቧ መጠበቅ ታሪኳ\nበሚልቅ ዝምታ ከአርሳኒ ከአጋቶን\nቃልን ከለከለች የቃል እናት ስትሆን\n\nየነብያቱን ነው ፀሎቱን ብታደርስ\nአሰምታም ብትጮህ ማርያም በመቅደስ\nከነገረኝ በቀር ገብርኤल በብሥራት\nምንም አላውቅ ምትል እመ ትኅትና ናት\n\nባትጽፍ ከእርሷ እቅፍ አንድ ልጇ ወንጌል\nባርምሞ ብትፀና እርሷ ግን ናት ፊደል\nቃል የተፃፈባት ጽሌ ናት ሰሌዳ\nህይወቷን አንብበን ልጇን እንረዳ', 'am', 155, 0),\n(2, 'አረሳሽም አልከዳሽም', 'አረሳሽም አልከዳሽም\nአረሳሽም አልከዳሽም ዝማሬሽን አላቆምም\nበልቤ ሰሌዳ በንፅህና ተፅፈሻልና\n\nስለሚገባቸው ለቅኖች ምስጋና\nብፅዕት ቅድስት መባል ይገባሻልና\nየአባ ሕርያቆስ ጥዑመ ቅዳሴ\nበልቤ ተፅፏል የኤፍሬም ውዳሴ\n\nማርያም ማርያም ስልሽ የአዩኝ በትዝብት\nለጨለመባቸው ቢሆንም ግርምት\nአይጠፋኝም ላፍታ ድንግል ሆይ መልክሽ\nእንባዬ ይፈሳል ዝወትር ሳስብሽ\n\nሰላም እልሻለሁ በገብርኤል ሰላምታ\nይወገድ በምልጃሽ የአፌ ዝምታ\nአሸበሽባለው እጆቼን ዘርግቼ\nእንደቀደሙት ልክ እንደ አባቶቼ', 'am', 156, 0),\n(2, 'የልቤን ሁሉ', 'የልቤን ሁሉ\nየልቤን ሁሉ ለማን ላማክር\nእመቤቴ ሆይ ከአንቺ በቀር\nየደካማው ሰው መጠጊያ እኮነሽ\nሃዘን ጭንቀቴን የምረሳብሽ\n\nቅዱሳን አበው አንቺን መረጡ\nከሲኦል ዓለም ስላመለጡ\nፃድቅ በስራው ያኔ ሲድን\nእጠራሻለሁ ድንግል አንቺን\n\nየጭንቄ ደራሽ አክኪሌ ነሽ\nቂም በቀል አያውቅ የዋህ ልብሽ\nልቤ ለፍቅርሽ ሰፊ ስፍራ አለው\nበአዘ ንኩኝ ሠዓት እጠራሻለው\n\nዋሴ ነሽ ለእኔ ድንግል እናቴ\nስምሽ ጠበቀኝ ከልጅነ ቴ\nሁልጊዜ ለእኔ በጎ ያረግሽልኝ\nምን ልበል ላንቺ ቃላትም የለኝ\n\nለአዘንኩኝ ለእኔ ደስታዬ ነሽ\nያረጋጋሽኝ ፈጥነሽ ደርሰሽ\nስምሽ ሃጥአንን የሚቀድስ\nከሞት ወደ ህይወት የሚመልስ\n\nየመንገዴ ስንቅ የርሃቤ መርሻ\nለታመመ ሰው ነሽ መፈወሻ\nየተማጸነ በስምሽ አምኖ\nማን አፍሮ ያውቃል አንቺን ለምኖ', 'am', 157, 0),\n(2, 'የአፍ መፍቻ ቋንቋዬ', 'የአፍ መፍቻ ቋንቋዬ\nከአፌ አይጠፋም ስምሽ\nከልቤ አይጎድልም ፍቅርሽ\nየአፍ መፍቻ ቋንቋዬ ድንግልሆይ ከለላዬ\n\nመሪዬ ነሽ በመንገድ፣\nየማልፍብሽ ከወጥመድ،\nወጥቻለሁ ካንች ጋራ،\nእንዳልደክም እንዳልፈራ።\n\nአይቀርበኝም ያ ጠላቴ\nስለሆንሽኝ ምልክቴ\nአንችን ይዤ ተሻገርኩኝ\nማርያም ብዬ በድል ቆምኩኝ\n\nተሞልቼ በመንፈስ\nማርያም ብዬ ሳወድስ\nእዜማለሁ በምስጋና\nማን ሊያቆመው ያንችን ዝና\n\nበልቤ ላይ አለ ፍቅርሽ\nበአንደበቴም ላይ ጣዕምሽ\nአንችን መውሰድ እኔ አልፈራም\nእናቴ ነሽ ለዘላለም\n\nተቀበልኩሽ ስጦታየ\nይዤሽ ገባሁ ከጎጆዬ\nተጽናናሁኝ ከሃዘኔ\nአልለይም በዘመኔ', 'am', 158, 0),\n(2, 'ስምሽን ስጠራው', 'ስምሽን ስጠራው\nስምሽን ስጠራው ድንግል\nስምሽን ስጠራው ማርያም\nላንደበቴ ማር ነው ለልቤ ሰላም\nስምሽን ስጠራው ማርያም\n\nትውልድ ነኝና ልጅሽ የፈጠረኝ\nድንግል እመቤቴ ላንቺ ምስጋና አለኝ\nበፈቃደ እግዚአብሔር ባባቶቼ ፀጋ\nሳዓሊ ለነ እላለው ሲመሽም ሲነጋ\n\nበጠየቅሽው ጊዜ ወይኑን እንዲመላ\nአክብሮሻልና በቃና ገሊላ\nየሰላም እናት ሆይ ሰላም ልበልሽ\nዘመኔ ይፈፀም ሳመሰግንሽ\n\nበሰላምታ ድምፅሽ መንፈስ ተመልቼ\nአደግድጌ ልቁም እጆቼን ዘርግቼ\nበአብይ ቃል ጮሄ ልመስክር በብርቱ\nቅድስት ድንግል ማርያም የእግዚአብሔር እናቱ\n\nከሰማይ ሲገኝ ነው አንችን ማወደስ\nሲገለጥ ሲፈቀድ ከመንፈስ ቅዱስ\nማርያም ህይወቴ ነሽ ምክንያት ለመዳኔ\nብዙ ነው ምስጢሩ አንችን ማመስገኔ', 'am', 160, 0),\n(2, 'አክሊሌ ነሽ ማርያም', 'አክሊሌ ነሽ ማርያም\nአክሊሌ ነሽ ማርያም ሞገሴ ነሽ\nአክሊሌ ነሽ ማርያም ሞገሴ ነሽ\n\nዮሴፍም ይናገር በስደት ተፅናንቷል\nበቁምም በህልሙ መሰላሉን አይቷል\nየበገናው ምስጢር ምን እንደነበረ\nፅዮን ሆይ እያለ ዳዊት መሰከረ\n\nትውልድ እንዲጠቀም ስምሽን አንስቶ\nእነኋት ብሎናል ጌታ ተሰውቶ\nየፍቅር ስጦታ የድሆች እናት\nየክብር አክሊል ናት ዘውድ ሽልማት\n\nሙሴ በበረሀ ምን ተገለጸልህ\nሀመልማል በእሳት ሳይቃጠል አይተህ\nነብያት ተነሱ ትንቢት ተፈፅሟል\nቃል ከሰማይ ወርዶ ሥጋን ተዋህዷል\n\nለአለም ሞኝነት ነው በስምሽ ማመኑ\nተዐምርሽን መስማቱ ውዳሴን መድገሙ\nእኔስ ምስክር ነኝ ዛሬም ለዘላለም\nማርያምን ሳይጠሩ ከቶ መጽደቅ የለም', 'am', 161, 0),\n(2, 'ኪዳነ ምሕረት', 'ኪዳነ ምሕረት\nየእግዚአብሔር ምሕረት ከሰማይ ፈሰሰ\nክብሩን ለሰበኩት ላመኑት ደረሰ\nኪዳነምሕረት ኪዳንኪ ኮነ\nየያዘሽ ተሻግሯል በምልጃሽ ያመነ\n\nየአዳምን ኪዳን በቀኑ የፈጸመ\nበቀስተ ደመና ለኖኅ የፈረመ\nምድርን ላያጠፋት የገባላትን ቃል\nድንግል የአንቺ ፍሬ ዘላለም አስቧል\nለአንቺ በተሰጠሽ ኪዳነምሕረት\nዓለሙን አሻግሯል ከሞት ወደ ሕይወት\n\nከመረጣቸው ጋር ኪዳኑን አድርጓል\nበአብርሃም በዘሩም ያለውን አጽንቷል\nእነኋት እናት የመስቀል ስጦታ\nየኛ ነው ኪዳኑ የሞቱ ትውስታ\nኪዳንሽ የሚያድን ኪዳነምሕረት\nከሞት ፊት ያመልጣል የተማመነበት\n\nፍጹም ስላልነበር የብሉዩ ኪዳን\nበደሙ ፈርሞ ሰጠን አዲስ ኪዳን\nየዚህ ስምምነት ቃል የተፃፈብሽ\nየምስጢር መዝገቡ ሕያው ነው ኪዳንሽ\nበደሙ የተፃፈ ውል አለን በእጃችን\nበኪዳነምሕረት በአንቺ በእናታችን', 'am', 162, 0),\n(2, 'ለነፍሴ ነፍሷ ነሽ', 'ለነፍሴ ነፍሷ ነሽ\nለነፍሴ ነፍሷ ነሽ ለመንገዴ ፋና\nእንዳልጠፋ አምናለሁ የአንቺ ልጅ ነኝና\n\nየፃድቃን እናቶች እጅግ ብዙ ናቸው\nከብሉይ ከሃዲስ ብንዘረዝራቸው\nአንቺ ግን አንዲት ነሽ የለሽም ጭማሪ\nትኖሪያለሽ እንጂ ትውልድ ስታስምሪ\n\nያንቺን ሥም ተማጽኖ ያንቺን ሥም ቀድሶ\nአንቺን አመስግኖ አንቺን አወድሶ\nየተጠቀመ እንጂ በረከት አግኝቶ\nአልታየም እስካሁን የተጎዳ ከቶ\n\nጎርጎርዮስና ሊቁ ዮሐንስ\nአትናቴዎስና ሊቁ ባስልዮስ\nአባ ኤፍሬምና አባ ጊዮርጊስ\nተጠቅመዋል በአንቺ በሥጋም በነፍስ\n\nአባትህን ጠይቅ ስለሚለን ቃሉ\nብንጠይቃቸው ቅዱሳኑን ሁሉ\nስላንቺ ነገሩን ክብር ተዓምራትሽን\nለሰው ዘር በሙሉ አማላጅ መሆንሽን\n\nገብርኤል ከሰማይ ኤልሳቤጥ ከምድር\nበአንድ መሠከሩ ስለ ድንግል ክብር\nሰዓሊ ለነ ብሎ ተማጽኖ በአንቺ ስም\nየተጠቀመ እንጂ የተጎዳ የለም', 'am', 163, 0),\n(2, 'የሲሎንዲስ ጥበብ', 'የሲሎንዲስ ጥበብ\nየሲሎንዲስ ጥበብ እወድሻለሁ\nየናሆም መድሐኒት እወድሻለሁ\nማርያም አከብርሻለሁ\nማርያም እወድሻለሁ\n\nተጨንቄአለሁ ልንገርሽ\nምሥጥረኛዬ እናቴ ነሽ\nሠው የአልሠማውን ብርቱ ምሥጢር\nድንግል ሆይ ለአንቺ ለአማክር\nለቁሥለኛውም መድሐኒቱ\nለአዳም ዘር ሁሉ ነሽ ሕይወቱ\nመፍትሔ አለ በእጅሽ\nተንበርክኬ ልማጸንሽ\n\nሳልናገረው ይገባሻል\nየውሥጤ ሁሉ ይታይሻል\nድርሽ እናቴ ተረጅኝ\nያለ አንቺ ለእኔ ማን አለኝ\nደሥታዬ ደሥታ የሚሆነው\nበሐዘኔም የምጽናናው\nአንቺ ከእኔ ጋር ስለ ሆንሽ\nተጽናንቻለሁ በሥምሽ\n\nወንድሞቼ እንኳን ቢሸጡኝ\nሠው ሁሉ ጠላት ቢሆነኝ\nበእመ አምላክ ሐይል ከብሬአለሁ\nበጠላት ላይ ሠልጥኛለሁ\nየረሱኝ ሁሉ የአስቡኛል\nየተጣሉኝም የአከብሩኛል\nአንቺ አንግሠሽኝ አልወድቅም\nእቆማለሁኝ ዘለዓለም\n\nመንገዴ ረዝሞ ደክሜብሽ\nመከራው በዝቶ ታምሜብሽ\nወድቄ ሳዝን ድረሽልኝ\nለባርያሽ ሐይሉን እንድትሠጪኝ\nፍቅርሽ በውስጤ ተንሠራፋ\nበእናትነትሽ ልቤ ሠፋ\nየሚለያየን ማንም የለም\nማርያም ልበልሽ ለዘለዓለም', 'am', 165, 0),\n(2, 'ማርያም እንወድሻለን', 'ማርያም እንወድሻለን\nማርያም እንወድሻለን\nስለወለድሽ የሕይወት ምግብን\nማርያም እንወድሻለን\n\nድክመቴን አትይ ማርያም\nበኃጢአት መወደቄን ማርያም\nተስፋዬ አንቺ ነሽ ማርያም\nእስከለተ ሞቴ ማርያም\nላልከዳሽ ምያለሁ ማርያም\nከስርሽ ላልጠፋ ማርያም\nገፀ በረከቴ ማርያም\nየሕይወቴ ዋስትና ማርያም\n\nየምእመናን ውበት ማርያም\nዘውድ አክሊላቸው ማርያም\nድንግል አንቺ እኮ ነሽ ማርያም\nየመንገድ ስንቃቸው ማርያም\nምስክር ነኝ ለአንቺ ማርያም\nእንደነብያቱ ማርያም\nስጦታ መሆንሽን ማርያም\nለአዳም ልጆች ሁሉ ማርያም\n\nሞገስና ፀጋ ማርያም\nበጌታ ፊት ያለሽ ማርያም\nከሰይጣን መሸሻ ማርያም\nዋስ ጠበቃችን ነሽ ማርያም\nእንዴት ነበር ያኔ ማርያም\nጌታን ስትወልጂ ማርያም\nየእረኞቹ ደስታ ማርያም\nየመላእክት ዝማሬ ማርያም', 'am', 166, 0),\n(2, 'አወድሰኝ ኤፍሬም', 'አወድሰኝ ኤፍሬም\nአወድሰኝ ኤፍሬም ብላ ጠየቀችው ድንግል እናታችን\nባርክኒ ብሎ ወገቡን ታጠቀ ኤፍሬም አባታችን\nየልጄ በረከት ይደርብህ ብላው ጀመረ ምሥጋና\nወደ ብርሐን ድንኳን ወደ ተከበረው ደራሲው ገባና\n\nልቡ ያዘነ አዳምን ሊያድን ጌታ ወደደ\nዳግሚት ሰማይ ማደሪያው ልትሆን እርሱ ፈቀደ\nየሠማይ ምስጢር በማህጸንሽ ተከናወነ\nከዘሩ ቀርተሽ በንጽሕናሽ የሰው ዘር ዳነ\nሠዓሊ ለነ ሠዓሊ ለነ\nአዕምሮውን ልቡን ሳይብን አሳድሪብን\nጸጋውን ክብሩን እንዳይነሳን ለምኝልን\n\nበሔዋን ምክንያት በለስዋን በልተን ገነት ቢዘጋ\nበአንቺ እናትነት ዳግም ተዛመድን ከአምላካችንጋ\nትውልድ ሁሉ ሥምሽን በክብር አመሰገነ\nየሲዖል ቀንበር በላያችን ላይ ስላልተጫነ\nሠዓሊ ለነ ሠዓሊ ለነ\nአዕምሮውን ልቡን ሳይብን አሳድሪብን\nጸጋውን ክብሩን እንዳይነሳን ለምኝልን\n\nየዕዳ ደብዳቤ ተቀዳደደ የባርነቱ\nአዳም ሔዋንም ከእስራታቸው ወጡ ተፈቱ\nየሲዖል ጽልመት በልጅሽ ጠፍቶ ብርሐን ሆነ\nረፍት አገኘን የምሕረት ዓመት በአንቺ ዘመነ\nሠዓሊ ለነ ሠዓሊ ለነ\nአዕምሮውን ልቡን ሳይብን አሳድሪብን\nጸጋውን ክብሩን እንዳይነሳን ለምኝልን\n\nሙሴ በሲና ሳትቃጠይ ያየሽ ሐመልማል\nእግዚአብሔር መርጦሽ በማሕጸንሽ ዙፋኑን ተክሏል\nየዲያብሎስን ጥበብ እንዲያፈርስ አምላክ ሰው ሆነ\nበልጅሽ መሞት መዳናችንም ተከናወነ\nሠዓሊ ለነ ሠዓሊ ለነ\nአዕምሮውን ልቡን ሳይብን አሳድሪብን\nጸጋውን ክብሩን እንዳይነሳን ለምኝልን', 'am', 167, 0),\n(2, 'እመቤቴ የአምላክ እናት', 'እመቤቴ የአምላክ እናት\nእመቤቴ የአምላክ እናት\nላመስግንሽ ቀን ከሌሊት\nለልጅሽም ክብር ውዳሴ\nታቀርባለች ዘውትር ነፍሴ\n\nልቤ ተነሳሳ ተቀኘ ለክብርሽ\nበፍጹም ልቦና ሊያመሰግንሽ\nጽዮን መጠጊያ ነሽ የአብርሀም ድንኳን\nየታጠረች ተክል እመ ብዙሀን\n\nየለመለመች መስክ አምላክ የመረጣት\nየጽላቱ ኪዳን ታቦቱ ድንግል ናት\nየሰማይ የምድር ንግስ ናትና\nክብር ይገባታል ዘውትር ጠዋት ማታ\n\nአደራሽን ማርያም የሁሉ እናት\nበምልጃሽ አስቢኝ ሗላ ስራቆት\nያንን የሳት ባህር አሻግሪኝ ድንግል ሆይ\nእንዳልወድቅ እንዳልሞት ከቶ እንዳላይ ስቃይ', 'am', 168, 0),\n(2, 'ስምሽን ጠርቼ', 'ስምሽን ጠርቼ\nስምሽን ጠርቼ መቼ አፍራለሁ\nማርያም ብዬ መች እወድቃለሁ\nየምጽናናበት ስምሽ ነውና\nድንግል ሆይ ላቅርብ ላንቺ ምስጋና።\n\nጨለማ ውጦኝ በጠላት ሀገር\nለዘመናትም ስረገጥ ስኖር\nዲያብሎ스 ማርኮ ሲያሰቃየኝ\nየዓለሙን መድኅን ወለድሽልኝ\nከአባቶቼ ርስት ከሀገር ወጥቼ\nበአሕዛብ ሀገር ስኖር ተሽጬ\nደርሰሽ አጽናንተሽ አከበርሽኝ\nብቸኝነቴን አስረሳሽኝ።\n\nድንኳኑ ሞልቶ ሰዉ ታድሞ\nአስተናባሪው በጭንቀት ቆሞ\nምን አቀርባለው ብዬ ስቸገር\nምልጃሽ ደርሶልኝ ዳንኩኝ ከማፈር\nያሰብኩት አሳብ ደመና ሆኖ\nቢበተንብኝ እንደ ጉም ተኖ\nይሆናል ያልኩት ሳይሆን ቢቀርም\nበእመአምላክ እኔስ ተስፋ አልቆርጥም።\n\nእናት አባቴ ባያስታውሱኝ\nይህቺ ዓለም ንቃ ገፍታ ብተወኝ\nአንቺ ካለሽኝ ምን እሆናለሁ\nዐውሎ ነፋሱን ባሕሩን አልፋለሁ\nጠላቴ ደርሶ ቢያንገላታኝ\nመከራ አብዝቶ ቢያሰቃየኝ\nአላቋርጥም ያንቺን ምስጋና\nውለታሽ ድንግል አለብኝና\n\nክፉዎች ደርሰው ቢዝቱብኝ\nአንቺን መውደዴን አያስተውኝ\nበአሕዛብ መሐል ስምሽን ስጠራ\nመከታ ሁኚኝ እናቴ አደራ\nጠላቴ ደርሶ ቢያንገላታኝ\nመከራ አብዝቶ ቢያስጨንቀኝ\nአላቋርጥም ያንቺን ምስጋና\nውለታሽ ድንግል አለብኝና', 'am', 169, 0),\n(2, 'ዮም ፍሰሀ коነህ', 'ዮም ፍሰሀ коነህ\nዮም ፍሰሀ ኮነህ በእንተ ልደታ ለማርያም\nእንሆ ሆነህ ደስታ በእመቤታችን በማርያም ልደታ\n\nድንግል ተወለደች ፈሰሀ ኮነ\nእመቤታችን ከዳዊት ዘር ወጣች\nተስፋ ስንቃችንን ምድር ተደሰተች\nቀረባት ሰማዩ ሊያመቃ ነዉና\nየአዳም ስቃዩ\n\nድንግል ስትወለድ ፍሰሀ ኮነህ\nሊባኖስ አበራ በደስታ ተሞላ\nታላቁ ተራራ የሀና የኢያቄም\nህልማቸው ተፈታ ከድቅድቅ ጨለማ\nጨረቃዋ ወታ\n\nየተክታ ጨረቃ ፍሰሀ ኮነ\nፀሀየን ወለደች የጽድቅ ሀመልማላ\nዳዊት ቤት በቀለች ዝናብ ያየንባት\nየጽድቅ ደመና ድንግል ተወለደች\nከኢያቃም ከሀና', 'am', 172, 0),\n(2, 'ይቤላ መልአክ ለማርያም', 'ይቤላ መልአክ ለማርያም\nይቤላ መልአክ ለማርያም\nትወልዲ ወልደ ንጉሥ በቤተልሔም\n\nይቤላ መልአክ ከጌታ ተልኮ\nይቤላ መልአክ ቅዱስ ገብርኤል\nይቤላ መልአክ ሰላምታ አቅርቦላት\nይቤላ መልአክ ለማርያም ድንግል\nይቤላ መልአክ ትወልጃለሽ አላት\nይቤላ መልአክ ቀዳሚውን ቃል\n\nይቤላ መልአክ ማኅደረ መለኮት\nይቤላ መልአክ ማርያም ውድስት\nይቤላ መልአክ የሕዝብ ሁሉ እናት\nይቤላ መልአክ እኅተ መላእክት\nይቤላ መልአክ እሙ ለብርሃን\nይቤላ መልአክ ደብተራ ፍጽምት\n\nይቤላ መልአክ ወገበዋቲሃኒ\nይቤላ መልአክ ሐመልማለ ወርቅ\nይቤላ መልአክ ትበርሂ እምፀሐይ\nይቤላ መልአክ ኆኅተ ምሥራቅ\nይቤላ መልአክ ሰላም ለኪ ድንግል\nይቤላ መልአክ በአልባሰ ወርቅ\n\nይቤላ መልአክ ወላዲተ አምላክ\nይቤላ መልአክ ማርያም ንጽሕት\nይቤላ መልአክ ወትትሌአሊ እምአድባር\nይቤላ መልአክ ስብሕት ወቡርክት\nይቤላ መልአክ ኦ ምልእተ ጸጋ\nይቤላ መልአክ እግዚአብሔር ምስሌኪ\nይቤላ መልአክ ቡርክት አንቲ እምአንስት\nይቤላ መልአክ ድንግል በኅሊናኪ', 'am', 175, 0),\n(2, 'ለምኚ ለምኚ', 'ለምኚ ለምኚ\nለምኚ ድንግል ለምኚ\nለኃጥአን አኮ ለጻድቃን\n\nለምኚ ታላቅ ስጦታዬ\nለምኚ አዛኝ ሩህሩህ ነሽ\nለምኚ የጌታዬ እናት\nለምኚ ጸጋን የተሞላሽ\nለምኚ የአምላክ ማደሪያ\nለምኚ ለምነሽ አስምሪኝ\nለምኚ አማናዊት ጽዮን\nለምኚ ከእኔ አትለዪኝ\n\nለምኚ ሐዘንሽ ሐዘኔ\nለምኚ ለኔ ይሁን ድንግል\nለምኚ የተንከራተትሽው\nለምኚ በሃገረ እስራኤል\nለምኚ ትዕግስትሽን ሳየው\nለምኚ ልቤ ይመሰጣል\nለምኚ የሐዘን እንባ ጎርፍ\nለምኚ ዓይኔን ይላዋል\n\nለምኚ በቀራንዮ አንባ\nለምኚ በዚያ የፍቅር ቦታ\nለምኚ በእግረ መስቀሉ ስር\nለምኚ ከክርስቶስ ጌታ\nለምኚ ለእኛ ተሰጥተሸል\nለምኚ እናት እንድትሆኚ\nለምኚ ልጆችሽ ነንና\nለምኚ ምልጃሽ አይለየን\n\nለምኚ አንደበቴን ጌታ\nለምኚ በምስጋና ሙላው\nለምኚ ደስ ይበልሽ ብዬ\nለምኚ እኔም ላመስግናት', 'am', 178, 0),\n(2, 'አብሰራ ገብርኤል', 'አብሰራ ገብርኤል\nአብሰራ ገብርኤል ለማርያም\nወይቤላ ትወልዲ ወልድ\nሚካኤል መላዕክ በክነፍ ፆራ\nመንጦላዕት ደመና ሰወራ\nንፅህት በድንግልና አልባቲ ሙስና\nተወልደ ወልድ እምኔሐ\n\nገብርኤል ማርያም አበሰራት\nወንድ ልጅም ትወልጃለሺ አላት\nሚካኤል መላዕክ በክንፋ ከለላት\nየሰማይ መጋረጃውን ሸፈናት\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና\n\nአዳም በጥፋቱ ከገነት ሲባረር\nበሚካኤል ክንፎች ቀድሞ አይቶሽ ነበር\nሔዋንን ሲጠራት ሕይወቴ ነሽ አላት\nእንደሚድን አውቆ ድንግል በአንች ምክንያት\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና\n\nእግዚአብሔር የላከው የከበረው መላዕክ\nድንግል ሆይ ለክብርሽ ዐየን ሲንበረከክ\nበፍቅር በትህትና በፍፁም ሰላምታ\nየጌታ ሰው መሆን የነገረሽ በደስታ\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና\n\nደስተኛዬቷ ሆይ ደስ ይበልሽ ድንግል\nየአብ ቃል ክርስቶስ ሥጋሽን ይለብሳል\nአንቺም ትይዋለሽ ስሙን ኢየሱስ\nመድኋኒት ነውና ለሥጋ ወነፍስ\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና\n\nአንደ ኒቆዲሞስ ሳትከራከሪ\nአንደ ዘኬርያስ ሳትጠራጠሪ\nይሁነኒ ብለሽ ቃልን ተቀበልሽ\nከፍጥረት ማነው አንቺ የሚመስልሽ\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልና', 'am', 204, 0),\n(2, 'ቅዳሴ ማርያም አዜማለው', 'ቅዳሴ ማርያም አዜማለው\nቅዳሴ ማርያም አዜማለው\nውዳሴሽንም አደርሳለው\nመልክሽን ስደግም ለፍልሰታ\nተገለጪልኝ ጠዋት ማታ\n\nበምን ስራዬ ነው ማይሽ\nምኞቴ ነው ስለምወድሽ\nፍቅርሽ ጠርቶኝ ለምስጋና\nተሰለፍኩኝ እንደገና\nልቤ አንቺን ፈልጎይዞራል\nአየራትን ሰንጥቆ ይበራል\nአሳራፊው በምልጃሽ ማርያም\nያላንቺ የሚሆን የለም\n\nበኔ ሀይማኖት ባንቺ ጸሎት\nፈውስ አገኘው ከመለኮት\nበልቤ አይን እያየውሽ\nበሀሳቤም አገኘውሽ\nታቦት ነሽ የመንፈስ ቅዱስ\nነሽና ያርያም እህት\nየምንጠጣሽ ንፁህ የምንጭ ውሃ\nሀብታችን ገንዘብ ነሽ ለደሀ\n\nቀርቢያለው በንስሀ\nእዘኝልኝ አዛኝቷ\nአለም ጠልፋ እንዳትጥለኝ\nጥበቃሽም አይለየኝ\nአይጠፋም ከሰው ልጅ ስተት\nምክንያት ነሽ ለአለሙ ድህነት\nአክሚልኝ የልቤን ሀዘን\nእማምላክ እመብርሀን\n\nናዛዚቱ ለዮሴፍ\nምስጋና አለሽ ከአእላፍ\nስምሽ ስልጡን በእግዚአብሔር ዘንድ\nከአለም አንስት መርጦሻል ወልድ\nየሰማይ የሰማይ ደጅነሽ\nያእቆብ በሎዛ ነው ያየሽ\nመመኪያችን የፅድቃችን አንባ\nአሳስቢ ገነት እንድንገባ', 'am', 205, 0),\n(2, 'ኪዳነምህረት እናቴ', 'ኪዳነምህረት እናቴ\nኪዳነምህረት እናቴ\nሚስጥረኛየ ጓዳየ\nየጎደለኝን ታውቂያለሽ\nካፌ ሳይወጣ ሳልነግርሽ\n\nአልፏል መናኛው ኑሮ\nምልጃሽ ውሀውን ቀይሮ\nመልካሙ ወይን ደረሰ\nእንባየ ባንቺ ታበሰ\n\nልዘምር ልቁም ከፊትሽ\nልምጣ ልንበርከክ ለክብርሽ\nብርቅ ከሀገር ከቤቴ\nከቶ አረሳሽም እናቴ\n\nአልልም መቼ ነው ቀኑ\nየኔ መጎብኛ ዘመኑ\nእንዲሚፈፀም አምናለሁ\nሁሉን በጊዜው አያለሁ\n\nየልቤን ችግር ላዋይሽ\nከስእልሽ ፋት ቆሜ\nእንባዬ ቀድሞኝ ዝም አልኩኝ\nሳልነግርሽ ስለምታውቂ', 'am', 207, 0),\n(2, 'ሰላም ለኪ እያለ', 'ሰላም ለኪ እያለ\nሰላም ለኪ እያለ\nሐርና ወርቁን ስταስማማ\nየገብርኤል ድምፅ ተሰማ\nተሰማ የመልአኩ ድምፅ ተሰማ\nተሰማ የገብርኤል ድምጽ ተሰማ\n\nውሃ ስትቀጂ ክንፉን እያማታ\nሊያበስርሽ የመጣው በታላቅ ደስታ\nከሞገስሽ ብዛት ሲታጠቅ ሲፈታ\nአቅርቦልሽ ነበር የክብር ሰላምታ\n\nየምሥራቹን ቃል ምስጢር ተሸክሞ\nገብርኤል ተላከ ሊያረጋጋት ደግሞ\nእርጋታን ተሞልታ ነገሩን መርምራ\nየመልአኩን ብሥራት ሰማችው በተራ\n\nይደሰታል እንጂ መንፈሴ በአምላኬ\nበምስጋና ሳድር ዘወትር ተንበርክኬ\nሃሳቤ ለቅፅበት ሌላ መች ያስባል\nለእኔ ልጅን መውለድ እንዴት ይቻለኛል\n\nከአንቺ የሚወለደው ልዑል ነው ክቡር\nየተመሰገነ በሰማይ በምድር\nምስጢሩ ኃያል ነው ይረቃል ይሰፋል\nከአንቺ በቀር ይኼን ማን ይሸከመዋል\n\nእጹብ ነው ድንቅ ነው አንቺን የፈጠረ\nአንቺን በመውደዱ ሰውን አከበረ\nዓለም ይባረካል በማሕፀንሽ ፍሬ\nክብርሽን አልዘልቅም ዘርዝሬ ዘርዝሬ', 'am', 217, 0),\n(2, 'የአርምሞ እናት', 'የአርምሞ እናት\nየአንደበት የብዕሯን ሀይል በፀጋዋ ብንመዝነው\nየእርሷን ስብከት የእርሷን ጦማር የሚችል የቱ ነው\nየአምላክ እናት የአርምሞ እናት\nዝምታዋ ግን ድንቅ ነው\n\nከሀያ ሁለቱ ፍጥረት ሰባቱን በአርምሞ\nየፈጠረ ልጇ በቀራንዮ ደግሞ\nበሸላቾቹ ፊት ዝም እንደሚል ጠቦት\nበአርምሞ አዳነን በሞቱ ገድሎ ሞት\n\nግብሯም እንደ ልጇ መልኳም እነደ አምላኳ\nሁሉንም በልቧ መጠበቅ ታሪኳ\nበሚልቅ ዝምታ ከአርሳኒ ከአጋቶን\nቃልን ከለከለች የቃል እናት ስትሆን\n\nየነብያቱን ነው ፀሎቱን ብታደርስ\nአሰምታም ብትጮህ ማርያም በመቅደስ\nከነገረኝ በቀር ገብርኤल በብሥራት\nምንም አላውቅ ምትል እመ ትኅትና ናት\n\nባትጽፍ ከእርሷ እቅፍ አንድ ልጇ ወንጌል\nባርምሞ ብትፀና እርሷ ግን ናት ፊደል\nቃል የተፃፈባት ጽሌ ናት ሰሌዳ\nህይወቷን አንብበን ልጇን እንረዳ', 'am', 220, 0),\n(2, 'አረሳሽም አልከዳሽም', 'አረሳሽም አልከዳሽም\nአረሳሽም አልከዳሽም ዝማሬሽን አላቆምም\nበልቤ ሰሌዳ በንፅህና ተፅፈሻልና\n\nስለሚገባቸው ለቅኖች ምስጋና\nብፅዕት ቅድስት መባል ይገባሻልና\nየአባ ሕርያቆስ ጥዑመ ቅዳሴ\nበልቤ ተፅፏል የኤፍሬም ውዳሴ\n\nማርያም ማርያም ስልሽ የአዩኝ በትዝብት\nለጨለመባቸው ቢሆንም ግርምት\nአይጠፋኝም ላፍታ ድንግል ሆይ መልክሽ\nእንባዬ ይፈሳል ዝወትር ሳስብሽ\n\nሰላም እልሻለሁ በገብርኤል ሰላምታ\nይወገድ በምልጃሽ የአፌ ዝምታ\nአሸበሽባለው እጆቼን ዘርግቼ\nእንደቀደሙት ልክ እንደ አባቶቼ', 'am', 221, 0),\n(2, 'የልቤን ሁሉ', 'የልቤን ሁሉ\nየልቤን ሁሉ ለማን ላማክር\nእመቤቴ ሆይ ከአንቺ በቀር\nየደካማው ሰው መጠጊያ እኮነሽ\nሃዘን ጭንቀቴን የምረሳብሽ\n\nቅዱሳን አበው አንቺን መረጡ\nከሲኦል ዓለም ስላመለጡ\nፃድቅ በስራው ያኔ ሲድን\nእጠራሻለሁ ድንግል አንቺን\n\nየጭንቄ ደራሽ አክኪሌ ነሽ\nቂም በቀል አያውቅ የዋህ ልብሽ\nልቤ ለፍቅርሽ ሰፊ ስፍራ አለው\nበአዘ ንኩኝ ሠዓት እጠራሻለው\n\nዋሴ ነሽ ለእኔ ድንግል እናቴ\nስምሽ ጠበቀኝ ከልጅነ ቴ\nሁልጊዜ ለእኔ በጎ ያረግሽልኝ\nምን ልበል ላንቺ ቃላትም የለኝ\n\nለአዘንኩኝ ለእኔ ደስታዬ ነሽ\nያረጋጋሽኝ ፈጥነሽ ደርሰሽ\nስምሽ ሃጥአንን የሚቀድስ\nከሞት ወደ ህይወት የሚመልስ\n\nየመንገዴ ስንቅ የርሃቤ መርሻ\nለታመመ ሰው ነሽ መፈወሻ\nየተማጸነ በስምሽ አምኖ\nማን አፍሮ ያውቃል አንቺን ለምኖ', 'am', 222, 0),\n(2, 'የአፍ መፍቻ ቋንቋዬ', 'የአፍ መፍቻ ቋንቋዬ\nከአፌ አይጠፋም ስምሽ\nከልቤ አይጎድልም ፍቅርሽ\nየአፍ መፍቻ ቋንቋዬ ድንግልሆይ ከለላዬ\n\nመሪዬ ነሽ በመንገድ፣\nየማልፍብሽ ከወጥመድ،\nወጥቻለሁ ካንች ጋራ،\nእንዳልደክም እንዳልፈራ።\n\nአይቀርበኝም ያ ጠላቴ\nስለሆንሽኝ ምልክቴ\nአንችን ይዤ ተሻገርኩኝ\nማርያም ብዬ በድል ቆምኩኝ\n\nተሞልቼ በመንፈስ\nማርያም ብዬ ሳወድስ\nእዜማለሁ በምስጋና\nማን ሊያቆመው ያንችን ዝና\n\nበልቤ ላይ አለ ፍቅርሽ\nበአንደበቴም ላይ ጣዕምሽ\nአንችን መውሰድ እኔ አልፈራም\nእናቴ ነሽ ለዘላለም\n\nተቀበልኩሽ ስጦታየ\nይዤሽ ገባሁ ከጎጆዬ\nተጽናናሁኝ ከሃዘኔ\nአልለይም በዘመኔ', 'am', 223, 0),\n(2, 'ለኔስ ልዩ ነሽ', 'ለኔስ ልዩ ነሽ\nለኔስ ልዩ ነሽ ድንግል ማርያም\nለኔስ ልዩ ነሽ እመብርሃን\nፈልጌ ላንቺ ምሥጋና አላገኘሁም\n\nልቤ ሲያበቅል የኃጢአት አረም\nውስጤ ሲሸፍት አልተወችኝም\nከቤተ መቅደስ እጇን ዘርግታ\nትጠራኛለች የኔ መከታ\n\nየሆዴን ሐዘን የልቤን ምሥጢር\nእነግርሻለሁ አንድም ሳይቀር\nየምትሸሽጊ የሕዝብን ኃጢአት\nለእኔስ ልዩ ነሽ ድንግል አዛኚት\n\nጣዕሙ ልዩ ነው ካንቺ ጋር መኖር\nድንግልን ይዤ መቼም አላፍር\nወደ ጽድቅ ሕይወት ትወስደኛለች\nድንግል ማርያም እናቴ እኮ ነች\n\nበሐዘን ስሰበር ማንን እጠራለሁ\nውስጤ ሲደማ ለማን እነግራለሁ\nከኃጢአት እድፍ ንጹሕ መሆኛዬ\nአንቺ ነሽ ለኔ የኔስ መጽናኛዬ\n\nየኃጢአት ቁስል ያላንቺ አይደግም\nልቤ ሳይፈቅድ በሕይወት አልኖር\nከልጅሽ ሌላ መድኅን የለኝም\nከጸሎት በቀር ፍጹም አልድንም', 'am', 224, 0),\n(2, 'የብርሃን እናት ነሽና', 'የብርሃን እናት ነሽና\nየብርሃን እናት ነሽና\nየብርሃን እናት\nለምኝልን ድንግል ለምኝልን\n\nጸጋንና ክብርን የተሞላሽ\nከሴቶች መካከል የተመረጥሽ\nለቃሉ ማደሪያ ዙፋኑ ሆነሽ\nበደመና መንበር የተመሰልሽ\n\nየሽቶ ማኖሪያ የተቀደስሽ\nመዐዛሽ ያማረ ሽቶ ያለሽ\nውዳሴሽ ብዙ ነው እናታችን\nስምሽን እያሰብን ነው መፅናኛችን\n\nበሀሳብ በክብር ፍፁም ሆነሽ\nምንኛ ብሩህ ነው ድንግል ልብሽ\nአንቺን የሚመስል የለምና\nይሰማል ምልጃሽ ያንቺ ልመና\n\nየብርሃን መውጫ ምስራቅ ሆነሽ\nሰውን ለለወጠ መድኅን ልጅሽ\nምስጋናሽ አያልቅም ለዘላለም\nማህሌት ነሽና በአርያም\n\nመላእክት ፍጥረትሽን ያደንቃሉ\nጌታን በመውለድሽ ይመካሉ\nሰመይና ምድርን ሳይወስኑት\nባንቺ ተወሰነ በእውነት', 'am', 225, 0),\n(2, 'መዘንጋት ባለበት', 'መዘንጋት ባለበት\nመዘንጋት ባለበት በታናሽ ህሊና\nመዘመር ልጀምር ለድንግል ምስጋና\nእኔስ በውዳሴሽ ባህር እዋኛለው\nገናንነትሽን ክብርሽን እያሰብኩ\n\nየትትናሽ ነገር ቢወሳ አያልቅም\nታነቢያለሽ እና ለዚ ክፉ አለም\nድንግል ሆይ ለሀጣን ታስቢያለሽ እና\nልቦናዬ ባንቺ በምልጃሽ ተፅናና\n\nማርያም ሆይ ስለዚህ እንወድሻለን\nአንቺን ተማጽነናል እንድታማልጂን\nዘወትር እጆችሽ ተዘርግተዋል እና\nስለበደለኞች ሊያቀርቡ ልመና\n\nእሳታውያኑ ሱራፌል ኪሩቤል\nሊነኩት ያልቻሉት የሳቱን ነበልባል\nአንቺግን ታቀፍሽው ሳምሽው በከንፈርሽ\nከፍጥረት ለይቶ ፍፁም ስላጸናሽ\n\nማርያም ሆይ ስለዚህ እንወድሻለን\nአንቺን ተማጽነናል እንድታማልጂን\nዘወትር እጆችሽ ተዘርግተዋል እና\nስለበደለኞች ሊያቀርቡ ልመና', 'am', 226, 0),\n(2, 'አዝላው ወረደች', 'አዝላው ወረደች\nአዝላው ወረደች ወደ ግብፅ\nስደተኛዋ የአምላክ እናት\nይህ ዓለም ለእርሷ መች ተገባት\n\nዓለም በምኗ ታስተናግዳት\nየፍቅር ምንጯ ተሟጦባት\nእነ ኮቲባን እየላከች\nየአምላክን እናት ተሳደበች\nእነ ሄሮድስን እየላከች\nህፃኑን ልትገድል አሳደደች\n\nየክብርን ጌታ ተሸክማ\nውርደት ለበሰች እንደ ሸማ\nየሀብቱን ጌታ በጀርባ አዝላ\nሰው ተዘከራት ተቸግራ\n\nበቃሉ ትዕዛዝ ምድርን ሠርቶ\nተንከራተተ ማደሪያ አጥቶ\nጌታ ሲወለድ የምሥራች\nበረት ሰጠችው ዓለም ታካች\n\nግና መላእክት በሰማያት\nሃሌ ሉያ አሉ በፍርሃት\nወልድን በአብ ቀኝ ከላይ አይተው\nደግሞም በምድር ከድንግል ክንድ\nከላይም ሳይጎድል ተመልክተው', 'am', 230, 0),\n(2, 'በድንግል ትህትና', 'በድንግል ትህትና\nበድንግል ትህትና በዓለም ተደነቀ\nእዉነተኛ መጠጥ ከሆዷ ፈለቀ\nሰዉ የሚድንበት ሮማንና ገዉዝ\nከሆዷ ፈለቀ እንደ ምንጭ እንደ ወንዝ\n\nፀጋን ስላደላት የመዉለድ ስጦታ\nበፍቅር ሳበችው የፍጥረትን ጌታ\nሰማያዊዉ አካል ከእርሷ ሥጋን ነሳ\nፀሐይ ስለወጣ ቀረልን አበሳ\n\nእስኪ ተመልከቱት ይህንን ደስታ ይህን ታላቅ ነገር\nወልድን በመዉለዷ በፀጋ ስንከብር\nታላላቅ አንስት እናቶች ቢባሉም\nአምላክን በመዉለድ እርሷን አያህሉም\nአምላክን በመዉለድ ድንግልን አይቀድሙም\n\nእግዚአብሔር ምድርን አየና በሞላ\nማርያምን አገኛት ከቤተ-መቅደሱ ከደጁ ተጥላ\nከመላዕክቱ ጋር እየተጫወተች\nየሰማዩን መና እየተመገበች', 'am', 231, 0),\n(2, 'እመቤቴ ማርያም', 'እመቤቴ ማርያም\nእመቤቴ ማርያም እለምንሻለው\nበለቅሶ በዋይታ ፊትሽ ወድቄአለው\nእመቤቴ ስሚኝ ተማጽኜሻለው\n\nሐዘኔን ጭንቀቴን ለማን እነግራለው\nችግሬን ጉዳቴን ለማን አዋያለው\nእመቤቴ ስሚኝ ተማጽኜሻለው\n\nሐዘኑ በዛብኝ መከራው ከበደኝ\nእንደምን ልቻለው እኔስ ብቻዬን ነኝ\nየአማኑኤል እናት ፈጥነሽ ድረሽልኝ\n\nበጣም ተንገዳገድኩ ልወድቅ ነው እኔ\nእመ አምላክ ደግፊኝ ቁሚልኝ ከጎኔ\nምንም አጋር የለኝ ከአንቺ በቀር ለእኔ', 'am', 232, 0),\n(2, 'ወደ ምስራቅ እዩ', 'ወደ ምስራቅ እዩ\nወደ ምስራቅ እዩ ወደ ፀሐይ መውጫ\nድንግልን ክበቧት እንበል ሃሌ ሉያ\nለአምላክ እናት ለአዛኚት\nእልል እንበል እንዘምርላት\n\nወገኖች ተነሱ እናታችን መጣች\nስሟን ስንጠራ መቼ ትቀራለች\nየተከዘን ልታፅናና\nነይ ስንላት ትመጣለችና\n\nየጽጌው ማኃሌት መዝሙሩ ሲጀመር\nማርያም ትመጣለች በደመና በአየር\nንዒ ስንል በሳዕታት\nልትባርከን ትመጣለች በእውነት\n\nፍልሰታ ሲጀመር ቃል ኪዳን ገብታለች\nየሌሊት ውዳሴን ንዒን ትሰማለች\nህጻናቱን በበረከት\nልትጎበኝ ትመጣለች በእውነት\n\nበፍፁም ቸርነት እንዲምረን ጌታ\nበአማላጅነትሽ ሁኚልን መከታ\nእናታችን አለኝታችን\nእንድናለን ድንግል አንቺን ይዘን', 'am', 233, 0),\n(2, 'የእርቅ ሰነድ ነሽ', 'የእርቅ ሰነድ ነሽ\nየእርቅ ሰነድ ነሽ በሰማይ የታየሽ\nቀስተ ደመናዋ ድንግል ሆይ አንቺ ነሽ\nከኖኅ ውሃ ጥፋት ከቁጣው በኋላ\nአምላክ ስላረገ ቃል ኪዳን መሐላ\n\nየሰው ልጆች ጥፋት በምድር ሲበዛ\nትእዛዙን ሲቃወም ሲሽር እንደዋዛ\nየቍጣው ሕፃናት ኔፍሌም ሲወለዱ\nመጠለያው መርከብ አንቺ ሆንሽ ዘመዱ\n\nከብዙዎች መሃል ኖኅ ብቻ ተገኘ\nበደል የሚጠላ ጽድቅን የተመኘ\nየእግዚአብሔር ልጆች በአሕዛብ ሲቀኑ\nበሃይማኖት ጸንተው አንቺን ያሉ ዳኑ\n\nጥንድ ጥንድ እንስሳት ተባዕትና አንስት\nበአንቺ ተጠለሉ መዓቱን በመፍራት\nኖኅና ልጆቹ የልጆቹንም ሚስቶች\nመርከቧ ከልላ ከመዓት አዳነች\n\nእኛም ከመዓቱ የምናመልጠው\nድንግል ሆይ ስምሽን መርከብ አድርገን ነው\nበእውነት ያለ ሐሰት ሰምሽን ስንጠራ\nይታያል እግዚዚአብሔር ልቦናው ሲራራ\n\nከሰማይ መዓቱ በወረደ ጊዜ\nአንቺ ነሽ ማደሪያ የፍጥረት ትካዜ\nአርባ ቀን ከሌሊት ከዘነበው ዝናብ\nየሰው ልጅ ተረፈ ሆነሽለት መርከብ\n\nሕይወት ለአብነት የቀረው ለአብነት\nነውና እመቤቴ በአንቺ መርከብነት\nየኖኅ ቃል ኪዳኑ መጠለያ አንቺ ነሽ\nምስጋና ይድረሰው ለአማኑኤል ልጅሽ', 'am', 234, 0),\n(2, 'በብርሃን ጸዳል', 'በብርሃን ጸዳል\nበብርሃን ጸዳል ተከባ እመቤቴ\nበደመና ዙፋን ተቀምጣ ከፊቴ\nየፅጌውን ዜማ ስንዘምር በደስታ\nበምስጋናሽ መጠጥ ሲሰማኝ እርካታ\n\nእንባዬ ሲቀዳ ናፍቆትሽ መስጦኝ\nከደስታ በላይ አንቺን ስላየሁኝ\nምኞቴ ተሳክቶ ፊትሽን አይቼው\nየሌሊቱ ህልሜ የቀን ምኞቴ ነው\n\nእሩሩ ነሽና ይህ ህልሜ ተሳክቶ\nአመስግኜሽ ድንግል ህልናዬ ረክቶ\nልጅሽ ልሁን ድንግል ከስርሽ አልጥፋ\nአንቺን በማመስገን ህሊናዬ ይትጋ\n\nልጅሽ ልሁን ድንግል ከስርሽ አልጥፋ\nአንቺን በማመስገን ህሊናዬ ይርካ\nየምስጋናሽ ብዕር ብራናሽ ልሁን\nስምሽ ይፃፍብኝ በልዩ ህብር', 'am', 235, 0),\n(2, 'ተወዳጅ ልጅሽን', 'ተወዳጅ ልጅሽን\nተወዳጅ ልጅሽን ህማሙን ስታይ\nማሰብ ይሳነኛል የአንቺን ስቃይ\nበእሾህ አክሊል ጉንጉን የቆሰለ ራሱን\nበብዙ ግርፋት የታመመ አካሉ\n\nበዕፅ መስቀሉ የወረደ ደሙ\nየቀራንዮ ግፍ እጅግ ማስገረሙ\nደጉ ልጅሽ ታስሮ የፍጥኝ ሲሰቃይ\nተሰክቶ ቀረ ዓይንሽ ወደ ሰማይ\n\nስለመሰቀሉ አይሁድ ሲደሰቱ\nሲስቁ ሲያሾፉ ቁማር ሲጫወቱ\nሲዘባበቱበት አይንሽ በማየቱ\nህሊናሽ ተገርፏል በሀዘን በብርቱ\n\nብላቴናይቱ የዳዊት ልጅ ማርያም\nስለደረሰብሽ ቢነገር አያልቅም\nተጠማው ቢላቸው መፃፃ አስጎነጩት\nመርገም አስወግዶ ቢሰጣቸው ሕይወት\n\nለመጠጡ እንዲሆን መፃፃ ከሐሞት\nሰፍነግን ጨምረው በዘንግ አስጎነጩት\nዳዊት በትንቢቱ እንደተነበየው\nበምግቤ መራራን ጨመሩ እንዳለው\n\nይኄ ሁሉ ሲሆን ድንግል ተመልክታ\nመፅናናት ተሳናት በሐዘን ተነክታ\nኤሎሄ ኤሎሄ ጌታ ባለ ጊዜ\nእጅግ ኃያል ነበር የማርያም ትካዜ', 'am', 236, 0),\n(2, 'አሳስቢልን', 'አሳስቢልን\nየተወደደ ስምሽ ማርያም\nእንዳንቺ ንፁሕ በዓለም የለም\nአሳስቢልን እንዲምረን መድኃኔዓለም\n\nበንፅሕናሽ በመመረጥሽ\nድንግል በእውነት እፁብ ድንቅ ነሽ\nአሳስቢልን እንዲምረን መድኃኔዓለም\n\nፍጥረታት አንቺን ይማፀኑሻል\nከሲዖል ዓለም አውጪን ይሉሻል\nአሳስቢልን እንዲምረን መድኃኔዓለም\n\nአስራትሽን ኢትዮጵያን\nጠብቂልን ድንግል ሕዝቧን\nአሳስቢልን እንዲምረን መድኃኔዓለም', 'am', 237, 0),\n(2, 'የአብ ቃል አክብሮሽ', 'የአብ ቃል አክብሮሽ\nየአብ ቃል አክብሮሽ እናት ያደረገሽ\nእግዚአብሔር በቃሉ ፍፁም ያከበረሽ\nየምንመካብሽ መሰላላችን ነሽ\n\nቅድስና ለአንቺ ፅድቅም ለአንቺ ሆኖ\nዓለምን የፈጠረ በአንቺ ተወስኖ\nየገነት ፍሬነሽ ሕይወት ያፈራሽ\nአንቺን ለመረጠ አንቺን ላነጻሽ\nምስጋና ይድረሰው ለቸሩ አምላክሽ\n\nአዳም የኖረብሽ የኤዶም ገነት ነሽ\nየኤፌሶን ወንዝ ወርቅ የሚፈልቅብሽ\nየጊዮን ማዕበል ኢትዮጵያን የከበብሽ\nዮርዳኖስን ሆነሽ አህዛብን ፈወስሽ\nበልጁ ቃልነት አብም አከበረሽ\n\nጸአዳሽን ወዶ ወልድ ዋህድ ዋጀሽ\nአብም በሰማያት በህሊናው ጻፈሽ\nመንፈስ ቅዱስ መጥቶ አንቺን አከበረሽ\nእመካብሻለሁ እመቤቴ ስልሽ\n\nወልድ በመውደዱ ካንቺ መወለዱን\nንጹህ ሆኖ አግኝቶት ቅዱሱን ስጋሽን\nለቃሉ ማደሪያ ፅላትና ታቦት\nበብሩህ ደመና ተመስለሽለት\nከስጋሽ ተከፍሎ ከደምሽ ደም ወስዶ\nከነፍስሽም ነፍስን ፍጹም ተዋህዶ', 'am', 238, 0),\n(2, 'ማርያም ሃዘነ ልቦና', 'ማርያም ሃዘነ ልቦና\nማርያም ሃዘነ ልቡና ታቀልል\nሃዘነ ልቦና ታቀልል\n\nሕይወታችን አንቺን ባየች ቁጥር ትፈካለች\nብሩህ ፋና የመዳን መሰላል አርማችን ነሽ\nላዘነ መጽናኛ ለደከሙ ብርታት\nላለቀሱ ሁሉ ሰላምና እውነት\nምን ልበልሽ ድንግል የእኛ ሕይወት\n\nርስትሽን ኢትዮጵያን አስቢያት በጸሎትሽ\nታለቅሳለች ሰላምን ብታጣ ሳትታክት\nበአንች መተማመን ስምሽን መጥራቷ\nስለማታፍር ነው በጥንቱ ጸሎት\nማርያም የአንቺ ስም ነው መጽናኛዋ\n\nብንከፋ አንችን ባየንን ቁጥር ተጽናናን\nከጥላሽ ስር ሰላምና ፍቅር አገኘን\nለተጎዱ ሁሉ ጽድቅ ለተጠሙ\nለታረዙ ሰዎች ፍቅርን ለተራቡ\nበዕንባሽ ጠብታ ይጠግባሉ', 'am', 239, 0),\n(2, 'እናቴ እመቤቴ', 'እናቴ እመቤቴ\nእናቴ እመቤቴ የማጠፊው ከአፌ\nበረከቴ አንቺ ነሽ የመስቀል ስር ትርፌ\nአምላኬ ሸልሞኝ ለዘለላም ያዝኩሽ\nጌታን የማይብሽ ብሌኔ አደረኩሽ\n\nበልቤ ላይ ይፍሰስ የፍቅርሽ ጸዳሉ\nየሚጣፍጥ ስምሽ መድኃኒት ለሁሉ\nተወዳጁ ልጅሽ ጸጋዉን ያብዛልኝ\nእድሜዬ እስኪፈፀም ለክብርሽ እንድቀኝ\n\nነፍሴ እንዳትጎዳ እንዳትቀር ባክና\nብርታት ሆኖልኛል የስምሽ ምስጋና\nእኖራለሁ ገና ንዒ ንዒ ስልሽ\nክብሬ ነሽ ጌጤ ነሽ ከአፌ ማልነጥልሽ\n\nሲነጋም ጠራሁሽ ሲመሽም ጠራሁሽ\nስዕልሽ ፊት ቆሜ ሰዐሊ ለነ እያልኩሽ\nአሜን የምልብሽ መነጋገሪያዬ\nየአማኑኤል እናት አንቺ ነሽ ቋንቋዬ\n\nመች በሥጋ ጥበብ ሰው ላንቺ ይቀኛል\nከአምላክ ካልተላከ ከፊትሽ ይቆማል\nአንቺን ማመስገኔ አንቺን ማወደሴ\nበልቡ ያሰበሽ ፈቅዶ ነው ሥላሴ\n\nብዙ ተቀብዬ ጥቂት አልዘምርም\nለእናትነት ፍቅርሽ ከቶ ዝም አልልም\nእኔን በዕደ ፍቅርሽ የምትባርኪ\nኦ ምልእተ ፀጋ ድንግል ሰላም ለኪ', 'am', 240, 0),\n(2, 'አይናችን ነሽ ማርያም', 'አይናችን ነሽ ማርያም\nአይናችን ነሽ ማርያም አንቺን አይንኩብን\nየተዋህዶ ልጆች እንወድሻለን\nግቢ ከቤታችን በረከታችን ነሽ\nበሃሴት ቆመናል ደስታን ስለወለድሽ\n\nየቀደመው እባብ እጅግ ተበሳጨ\nባሸዋ ላይ ቆመ መርዙን እየረጨ\nከልጅሽ ምስክር ሊያስቀር ከዘሮችሽ\nእጅጉን ይተጋል ሊለየን ከጉያሽ\n\nገብተሻል ላትወጪ አንዴ ከልባችን\nጌታን ያየንብሽ ስለሆንሽ አይናችን\nየራቀው ቀርቦልን የረቀቀው ጎልቶ\nያየነው ባንች ነው የጠፋው ተገኝቶ\n\nወይኑን ያፈራሽው የወይን ሐረግ ድንግል\nምግብን የሰጠሸን በቀራኒዮ መስቀል\nምልክታችን ነሽ የኛ መታወቂያ\nየምንተርፍብሽ ከጥፋት ገበያ\n\nየህይወት መገኛ የደስታ መፍሰሻ\nፀዋሪተ ፍሬ የሃዘናችን መርሻ\nግቢ ከቤታችን በረከታችን ነሽ\nየጎደለው ሁሉ ይሞላል በምልጃሽ\n\nከሃገር ብንርቅ ከልፍኝ ከጓዳችን\nስንቅነሽ ለመንገድ ምርኩዝ ለጉዟችን\nባደርንበት አድረሽ በሄድንበት ሂጂ\nለፃድቃን አይደለም ለሃጣን አማልጂ', 'am', 241, 0),\n(2, 'ይኩነኒ', 'ይኩነኒ\nይኩነኒ በከመ ትቤለኒ\nአለች የእኛ እናት በትሕትና\nበሥጋም በነፍስም ንጽሕት ናትና\nአለች የእኛ እናት በትሕትና\nድንግል በክልኤ ንጽሕት ናትና\n\nየአዳም ቃልኪዳን መፈጸሚያው ሲደርስ\nላከው ገብርኤልን ወደ ቤተ መቅደስ\nበእግዚአብሔር ኅሊና ተስላ የነበረች\nከሠማይ የመጣ ቃሉን ተቀበለች\nዳግሚት ሠማይ አርያም ሆነች\nይደረግ ብላ በትሕትና ተቀበለች\n\nማርያም ሆይ አትፍሪ ብሎ እያረጋጋት\nከአንቺ የሚወለደው መድኃኒት ነው አላት\nወንድ ሥለማላውቅ ይህ እንዴት ይሆናል\nብላ ጠየቀችው ድንግልም ደንቋታል\nከሴቶች መሐል አንቺ ልዩ ነሽ\nበሕግ ሣይሆን በድንግልና ትወልጃለሽ\n\nሕይወት ሊቀዳባት አድሯል በማሕጸንዋ\nአይኖርም ከእንግዲህ የሔዋን መርገሟ\nበአዲሱ ኪዳን አዲስ ብስራታችን\nምክንያተ ድኅነት አለች እናታችን\nቃልሕ ይፈፀም ይደረግ ብላ\nተአምር ተሰማ ኢየሩሳሌም ናዝሬት ገሊላ\n\nእጅግ አስገረመን የገብርኤል ዜና\nየእነ ዘካርያስ ከቶ አይደለምና\nየተመረጠችው የደረሰው ብሥራት\nዓለምን ከመሞት ከመርገሟ ዋጃት\nከሴቶች መሐል አንቺ ልዩ ነሽ\nበሕግ ሳይሆን በድንግልና ትጸንሻለሽ', 'am', 242, 0),\n(2, 'ለልደትሽ ምስጋና ይገባል', 'ለልደትሽ ምስጋና ይገባል\nለልደትሽ ምስጋና ይገባል\nለዓለም መዳን ምክንያት ተወልደሻል\nልደትሽም ለእኛ ልደት ነው\nባንቺ እኮ ነው ፀሐይ ያገኘነው\n\nበሊባኖስ ሰማን አዲስ ዜና\nንጽሕት ዘር ተወልዳለችና\nየዓለም ስቃይ ሰቆቃ ሊያበቃ\nተወለደች እንደ ጸሐይ ደምቃ\n\nለዚህ ክብር ይገባል እልልታ\nበልደትሽ አይሆንም ዝምታ\nየአንቺ ልደት ለዓለም ደስታ ነው\nአንቺ ምሥራቅ ልጅሽም ፀሐይ ነው\n\nብርሃን ሆነ በሊባኖስ ዛሬ\nበልደትሽ በመላእክት ዝማሬ\nአይቋረጥ ምስጋና ከአፋችን\nበሊባኖስ ይሰማ ዜማችን\n\nስለክብርሽ ክብር አለን እኛ\nከሊባኖስ ነይልን ወደ እኛ\nበአብ ኅሊና ቀድሞውን የታሰብሽ\nትውልድ ሁሉ ብጽዕት የሚልሽ', 'am', 243, 0),\n(2, 'ድንግል ፈጣሪዋን ወለደችው', 'ድንግል ፈጣሪዋን ወለደችው\nድንግል ፈጣሪዋን ወለደችው\nበመጠቅለያም ጠቀለለችው\nየለምና ስፍራ ለእግዶች ማረፊያ\nግርግም አስተኛችው በከብቶች ማደሪያ\n\nጨነቃት ጠበባት የዳዊት ከተማ\nየጌታ መወለድ ታምሩ ሲሰማ\nወረደ መላአኩ ምስራች ሊያወራ\nየህፃኑ ክብር በምድር አበራ\nይህ ሚስጢር ግሩም ነው ከቶ ማይነገር\nማርያምም በልቧ ትጠብቀው ነበር\n\nሰባሰገል መጡ ከሩቅ ምስራቅ ሀገር\nወርቅ እጣን ከርቤዉን ለርሱ ለመገበር\nበእናቱም እቅፍ አገኙት ህፃኑን\nለዓለም ተናገሩ ንጉስ መወለዱን\nይህ ሚስጢር ግሩም ነው ከቶ ማይነገር\nማርያምም በልቧ ትጠብቀዉ ነበር\n\nየይሁዳ ምድር ምስጋናን ተሞላ\nንጉስ መቷል እና ከናዝሬት ገሊላ\nተዐምሩን ትናገር ቤተልሔም ታውራ\nዝማሬ ሲውጣት ተረስቶ ቆጠራ\nይህ ሚስጢር ግሩም ነው ከቶ ማይነገር\nማርያምም በልቧ ትጠብቀው ነበር\n\nየማይታይ ታየ ተዳሰሰ እንደሰው\nበጠባቡ ደረት ማንን እንመስለው\nገረማት ጥበቡ ታናሿን ሙሽራ\nተዋህዷል እና ቃል ከሥጋ ጋራ\nይህ ሚሰጢር ግሩም ነው\nማርያምም በልቧ ትጠብቀው ነበር', 'am', 244, 0),\n(2, 'ጌታዬ ከሰጠኝ', 'ጌታዬ ከሰጠኝ\nጌታዬ ከሰጠኝ አልፈራም ልወስድሽ\nየሀዘኔ መርሻ ማርያም እናቴ ነሽ\n\nእናት አግኝቻለሁ ከመስቀሉ እግርጌ\nስሟን እየጠራሁ ከፍ እንዲል ማዕረጌ\nምርኩዝ ድጋፍ ሆኖኝ ድንግል ሆይ ፀሎትሽ\nበእፎይታ ሞልቶኛል የሰላምታ ድምፅሽ\nፍፁም ላይረሳኝ ዘልቆ በደም ስሬ\nይቀሰቅሰኛል ፍቅርሽ ለዝማሬ\n\nበልጅሽ መከራ ቀራንዮ ያለሽ\nአትዘነጊኝም ዛሬም ከእኔ ጋር ነሽ\nመታወክ መጨነቅ ከቤቴ እንዲነቀል\nየበረከቴን ቁልፍ ሰጥቶኛል ከመስቀል\nከጣራዬ በታች መነጨ ደስታ\nለጠቆረዉ ፊቴ እመቤቴ አብርታ\n\nበራስ ቅል ተራራ በነፍስሽ ሰይፍ አልፎ\nካሳ ሆነኝ ፍቅርሽ በልቤ ተፅፎ\nእነኋት እናትህ ሲለኝ በርትቻለሁ\nበልጅነት ክብር ከፊትሽ ቆሜአለሁ\nየመስቀል ስጦታ እነኋት እናቴ\nማንንም ሳልፈራ ወሰድኳት ከቤቴ\n\nበመስቀል ላይ ሆኖ ልጅሽ እራራልኝ\nበእናትነት ፍቅርሽ ቤቴን ሸለመልኝ\nበሚያጽናናዉ ቃሉ መሰበሬን ክሶ\nበልቤ ተከለ አጽናኟን ምሰሶ\nሞኝነት አይደለም ነገረ መስቀሉ\nእጅግ ማትረፊያ ነዉ አንቺን መቀበሉ', 'am', 245, 0),\n(2, 'እናት አለኝ', 'እናት አለኝ\nእናት አለኝ የምታብስ እንባ\nአያታለሁ ስወጣ ስገባ\nኪዳነምሕረት አምባ መጠጊያ ናት\n\nሔዋን ሰጥታኝ ከበለሱ ፍሬ\nእራቁቴን ብቆምም አፍሬ\nልብሴን ይዘሽ ወደኔ መጥተሻል\nደጓ እናቴ ቤቴን አድምቀሻል\nኪዳነምሕረት አምባ መጠጊያ ናት\n\nለዘላለም ንፅሕት በመሆኗ\nከእኔ ጋር ነው ሕያው ቃልኪዳኗ\nደስተኛ ነኝ ሐዘኔን አልፌ\nአፅናኝ ሆናኝ የመስቀል ስር ትርፌ\nኪዳነምሕረት አምባ መጠጊያ ናት\n\nከጥፋት ውሃ ማረፊያዬ\nመርከቤ ነሽ ከሞት ማምለጫዬ\nየአምላክ እናት ምልጃሽ ሆኖኝ ክብሬ\nበሕይወት አለሁ ጥልቁን ተሻግሬ\nኪዳነምሕረት አምባ መጠጊያ ናት\n\nበእናትነት ሕይወቴን ጎብኝታ\nልቤ አረፈ ተነቅሎ በሽታ\nሰንሰለቴ ከእግሬ ተቆረጠ\nመራራዬ በልጅሽ ጣፈጠ\nኪዳነምሕረት አምባ መጠጊያ ናት', 'am', 246, 0),\n(2, 'በማህፀን ቅኔ', 'በማህፀን ቅኔ\nበማህፀን ቅኔ ለማርያም ተሰማ\nበተራራማው ሀገር በኤፍሬም ከተማ\nዩሀንስ ይናገር በረሀ ያደገው\nድንግል ስትናገር ምን እንዳዘለለው\n\nየእናቱ ማህፀን የቅኔ እርስት ሆነች\nድንግል የአምላክ እናት ፊቱ ስለቆመች\nበሀሴት ዘለለ ዘመረ በደስታ\nከድንግል ሲወጣ ታላቁ ሰላምታ\n\nበድንግል ማህፀን ስላየ ጌታውን\nከመወለድ ቀድሞ ሰማነው መዝሙሩን\nትንቢቱ ሲፈፀም በሆዱ ሲናገር\nሰገደ ላምላኩ የስድስት ወር ፅንስ\n\nጀመረ ስብከቱን ገና ሳይወለድ\nተፈጥሮ መች ቻለ ነብዩን ለማገድ\nአፉ ተከፈተ በታለቅ ምስጋና\nበናቱ ማህፀን ድምፅን አሰማና\n\nየዩሀንስ እናት አሰልሳቤት ገረማት\nልጃዋ በማህፀን ቅኔ ሲቀኝባት\nድምፅን ከፍ አረገች ዓለም እንዲሰማ\nሞላት መንፈስ ቅዱስ በመዝሙር በዜማ', 'am', 247, 0),\n(2, 'ልቦናዬ ያውጣ', 'ልቦናዬ ያውጣ\nልቦናዬ ያውጣ ውዳሴ ለክብርሽ\nሰላም ለኪ ድንግል ጸጋን የሞላብሽ\nየእግዚአብሔር ከተማ የመለኮት ሃገር\nስለ አንቺ የሚነገር አለን ድንቅ ነገር\n\nየነቢያት ድንግል የአበው ምሳሌ\nእናቴ እልሻለሁ ቢበዛም በደሌ\nከቅዱሳን ሁሉ የአንቺ ክብር ይበልጣል\nአምላክን ልጄ ነው ማንስ ብሎት ያውቃል\n\nሔዋን ባትታዘዝ ለእግዚአብሔር ቃል\nሞትና መርገሙ በዓለሙ ገብቷል\nየመላኩን ብሥራት በእምነት ብትሰሚ\nሞገስን ተቀበልሽ በቀኙ እንድትቆሚ\n\nፍቅርሽ ጉልበት አለው ባህሩን ያሻግራል\nልመናሽ ጽኑ ነው ግዳጅ ይፈፅማል\nስለዚህ ድንግል ሆይ እንወድሻለን\nስምሽን ለልጅ ልጅ እንዘክራለን\n\nቀድሞም አልነበረም ወደፊትም አይኖር\nከፍጥረታት ሁሉ በሰማይ በምድር\nከእግዚአብሔር በታች ዛሬም ተሞሽራ\nድንግል ትታያለች ከከበሩት ከብራ', 'am', 248, 0),\n(2, 'የፀሐይ መውጫ', 'የፀሐይ መውጫ\nየፀሐይ መውጫ ምስራቅ ነሽ\nድንግል የእኛ እናት በብርሃን የተከበብሽ\nማርያም የእኛ እናት በብርሃን የተከበብሽ\n\nተአምረኛ ነው ክርስቶስ ሁሉን በጥበብ ያረገው\nብርሃን ተክሎ በላይሽ በማህፀንሽ ያደረው\nአይመረመር ጥበቡ እጹብ እጹብ ብለናል\nያስደነቀንን አምላክ በዝማሬ ከብበናል\n\nጨለማው ተሰዶ ይቅር ፀሐይ ከሆድሽ ሲወጣ\nአለፈ የጭንቁ ዘመን ምድር በብርሃን ተውጣ\nከድቅድቁ ወጥተናል በወለድሽልን ፀሐይ\nአያልፍም ብርሃኑ ኤልሻዳይ ነው አዶናይ\n\nአንቺ የምስራቅ ደጃፍ ሕዝቅኤል በራዕይ ያየሽ\nየመዳናችን ምዕራፍ የፅድቃችን ምክንያት ነሽ\nሕይወት ፈሰሰ መቅደስሽ እየቀዳን ጠጣነው\nልጅሽ ሲዳስሰን ነው በልምላሜ ያደግነው\n\nየማይጠፋ ፋኖስ ነው በመቅረዛችን ያበራ\nከአንቺ የተወለደው በጎቹን በጽድቅ የመራ\nየአንፀባራቂው አለት አምዱ ተተክሎልናል\nየሌሊቱንም ግርማ ያለፍርሃት አልፈናል', 'am', 249, 0),\n(2, 'ናርዶስ ቀጺመታት', 'ናርዶስ ቀጺመታት\nናርዶስ ቀጺመታት አሉ በልብሶችሽ መሀል\nየገነት ሽቶ ነሽ ማርያም ድንግል\n\nየተከበርሽ ነሽ አንቺ ከፍጥረት\nመዓዛሽን ወድዷል ጌታ ፀባኦት\nጠላት እንዳይከሰኝ ከጎኔ ሁኝና\nነውሬን ሸፍኝው እናቴ ነሽና\n\nገሊላዊት ድንግል የገነት ፈሣሽ\nየቆሠለችውን ሕይወቴን ፈውሽ\nሰአሊ ነለ ቅድስት በቀን በሌሊት\nለአፌ ጥበብ ነሽ ቅኔ ማኅሌት\n\nሁልጊዜ ድኅነትን የምንለምንሽ\nበእግዚአብሔር ፊት ሞገስን ያገኘሽ\nክርስቲያኖች ሁሉ ተስፋ የሚያደርጉሽ\nለዓለም የሚበቃ ምልጃ ቃል ኪዳንሽ', 'am', 250, 0),\n(2, 'ወደቀድሞ ነገር እንመለስ', 'ወደቀድሞ ነገር እንመለስ\nወደ ቀድሞ ነገር እንመለስ\nየአምላክን እናት እናወድስ\nከፍቅሯ እርቃችሁ የምትኖሩ\nማርያም ፊደል ናት ኑ ተማሩ\n\nቃል ተጽፎባታል የመዳኛ ፊደል\nጥበብ የሚሞላ ጨለማን የሚሰቅል\nለቃል ሥጋ መሆን ምክንያት ስለሆነች\nቀርባችሁ ተማሩ ማርያም ፊደል ነች\n\nአዲሱ ቃል ኪዳን ከላይ የተፃፈው\nበገሊላ ናዝሬት ገብርኤል ያበሰረው\nበማርያም እቅፍ ላይታገኙታላችሁ\nየምሥጢር መዝገቡን አንብቡ ገልጣችሁ\n\nያዘለችው ወንጌል ቃሉ ይፈውሳል\nአምኖ ላነበበው ነፍስ ያለመልማል\nበጀርባዋ ያለው እግዚአብሔር ነውና\nአቅርቡ ለማርያም ውዳሴ ምስጋና\n\nብዙዎች ተማሩ ስሟን እየጠሩ\nበአባታቸው መንግስት እንደፀሐይ በሩ\nክብር ልዕልናዋን ገብርኤል ነግሮናል\nካወደሷት ጋራ ለክብሯ ቆመናል', 'am', 252, 0),\n(2, 'አይሸሸግ እውነቱ', 'አይሸሸግ እውነቱ\nአይሸሸግ እውነቱ ማርያም ብጸት ናት\nከእግዚአብሔር ያልተላከ አይችልም ሊያወድሳት\n\nገብርኤል በከፍታ ከራማ ታላቅ ቤቱ\nገሊላ የተገኘው ወደ ማርያም እህቱ\nከእግዚአብሔር መላኩን ተረዳን በሚስጥር\nለስሟ ክብርንሰቶ ሰምተነዋል ሲየበስር\n\nበዘካርያስ ቤት አቀረብሽ ምስጋና\nየባርያውን ውርደት ተመልክቷልና\nፍጥረት ብፅይት ካለሽ ሆኖ ባንድ ቃሉ\nላንቺ ያልዘመረ እንዴት ትውልድ ይባል\n\nቢያከብርሽ ገብርኤል በታላቅ ትህትና\nልልናሽ በልጦበት ከርሱ ቅድስና\nከልቡ አመንጭቶ መች ሆነ ማክበሩ\nእግዚአብሔር ልኮት ነው ለንቺ መዘመሩ\n\nአንዳች አይጎልብኝ አንቺን አወድሼ\nዝማሬን ባበዛው ያለኝንጨርሼ\nእንኳን ለማርያም ለአዶናይ እናት\nምስጋናን ሰቷታል ላቤጌያ ዳዊት', 'am', 253, 0),\n(2, 'ወላዲተ አምላክ ማርያም ድንግል', 'ወላዲተ አምላክ ማርያም ድንግል\nወላዲተ አምላክ ማርያም ድንግል\nልዩ ነው ክብርሽ ከፍጥረት መሐል\n\nበቃሉ ዓለማትን ሳይፈጥራቸው ገና\nታስበሽ የነበርሽ በእግዚአብሔር ሕሊና\nበሃና ማሕፀን ከኢያቄም አብራክ\nእናቱ እንድትሆኝ የመረጠሽ አምላክ\n\nከመላዕክት በክብር አንቺ ትበልጫለሽ\nከሰዎች ልጆች የለም የሚመስልሽ\nበእግዚአብሔር ዘንድ ስምሽ የገነነ\nአልተገኘም ድንግል እንዳች የከበረ\n\nነውር የሌለብሽ ንጽዕት ሙሽራ\nየመመኪያችን ዘውድ እርተ ሕሊና\nእናት እና ድንግል ወላዲተ ቃል\nየማትለወጪ የሐይማኖት በትር', 'am', 254, 0),\n(2, 'በገነት በነበረች', 'በገነት በነበረች\nበገነት በነበረች በዕፀ ህይወት ፈንታ\nበምድር ተተከለች ልትሆነው ለአዳም ደስታ\nፍሬዋም ጥዑም ምግብ መድኃኒት ነው ለዓለሙ\nየበሉት አይራቡ የጠጡት አይጠሙም\n\nሳታገኝ ውሃ ሳይተክሏት በምድር\nፍሬን ያፈራች የካህኑ በትር\nአይመረምረው የሰው ህሊና\nየፅንሷን ነገር በድንግል\n\nሔዋን ከገነት ብትበላ ፍሬ\nምድሩ ቢጥላት የጠላት ወሬ\nየህይወት ፍሬ ታየች አፍርታ\nአዲስቷ ምድር ድንግል ኤፍራታ\n\nእሾህ አፈራች ምድር አሜኬላ\nበወዝ በላቡ አዳም ሊበላ\nእርግማን ጠፋ ተሻረ መርገም\nንፅህት ደመና ሲሰጠን ዝናብ\n\nፍሬውን አቅፋ ታየች አበባ\nክረምት አለፈ ዘመንም ጠባ\nየዜማው ጊዜ እነሆ ደርሷል\nበድንግል ፍሬ ሀዘን ተረስቷል', 'am', 255, 0),\n(2, 'ለድንግል ይገባል', 'ለድንግል ይገባል\nለድንግል ይገባል ውዳሴ ምስጋና\nእሳተ መለኮት ታቅፋለችና\n\nየአዳም ዘር ሲመታ በሞት ቅጣት በትር\nየሚመረጥ ጠፍቶ መርገም ውጧት ምድር\nጌታ ከፀባኦት የአንቺን ዘር አስቀረ\nድንግል የኛ ታሪክ ባንቺ ዛሬ ተቀየረ\n\nነይ እንልሻለን በአበው ትምክህት\nልባችን ይፅናና ድንግል የእኛ እመቤት\nየኤፍሬም ውዳሴ የአባ ሕርያቆስ\nጥዑም ዜማዬ ነሽ ለኔ ስምሽን ላወድስ\n\nካንቺ ጋር ሳወራ በልጅነት ሞገስ\nየኃጢአቴ ቁስል በምልጃሽ ሲፈወስ\nልቤ ቅኔ አውጥቶ ምስጋናን ጀመረ\nየልጅሽን ስራ ዛሬም እየመሰከረ', 'am', 257, 0),\n(2, 'ለጥያቄዬ መልስ ስላጣሁ', 'ለጥያቄዬ መልስ ስላጣሁ\nለጥያቄዬ መልስ ስላጣሁ\nመጣሁ ከደጅሽ ሱባዔ ገባሁ\nማን አፍሮ ያውቃል ባንቺ ለምኖ\nበኪዳንኪ ተማህጽኖ\n\nየነፍሴ እረፍቷ ታዛ መጠጊያ\nካንቺ ተገኝቷል የሞቴ መውጊያ\nበሰላምታሽ ድምጽ ተባርኳል ቤቴ\nየጌታዬ እናት ለኔም እናቴ\nማርያም ኩኒ ለሕይወትየ ጸወኖ\nእስመ ተማኅፀንኩ አንሰ ተማኅፅኖ\nለሥዕልኪ ስዕለ አድኅኖ እሰግድ ለኪ\n\nቀንን ስናፍቅ በለሊት ሆኜ\nአላተረፍኩም በሰው ታምኜ\nቁልፉ ልጅሽ ነው ለቋጠሮዬ\nአሳስበሽልኝ አልፏል ስቃዬ\nኪዳነ ምሕረት ኩኒ ለልቡናየ ብርሃኖ\nእስመ ተማኅፀንኩ አንሰ ተማኅጽኖ\nለስእልኪ ስዕለ አድኅኖ እሰግድ ለኪ\n\nጉልበቴ ዝሎ ቀልዬ ሳለሁ\nበኪዳን ጥላሽ ተስፋ አግኝቻለሁ\nደጅሽ መጥቼ ኃይሌ ታደሰ\nያሳዳጆቼ ምክር ፈረሰ\nወላዲተ አምላክ ኩኒ ለእርቃንየ ክዳኖ\nእስመ ተማህጸንኩ አንሰ ተማህጽኖ\nለሥዕልኪ ስዕለ አድህኖ እሰግድ ለኪ\n\nየዝናቡ ምንጭ ፈጣን ደመና\nከሴቶች ሁሉ ክብርሽ ገናና\nአንድያ ልጅሽ ወይን አድርጎኛል\nከትናንት ይልቅ ዛሬ ባርኮኛል', 'am', 258, 0),\n(2, 'ማርያም ማርያም ብዬ', 'ማርያም ማርያም ብዬ\nማርያም ማርያም ብዬ ስምሽን ልጥራው\nአይደክመኝም እኔ ብደጋግመው\nአሁንም ጠራሁሽ አላስችልህ ቢለኝ\nአውቀዋለሁ ስምሽን እናቴ ስትወልደኝ\n\nገና በማህጸን በእናቴ የምጥ ቀን\nደጋግሜ ሰማሁ ሲጠሩ ስምሽን\nበሰከንዳት እድሜ የማውቃት አንዲት ቃል\nልቤ ላይ ያለው ስም ማרያም ማርያም ይላል\n\nሔዋን ምጧ ቀሎ ልጆቿን ታቀፈች\nበአማላጅነትሽ እናቴም ታመነች\nበተወለድኩበት በመጀመሪያው ቀን\nስምሽን እየሰማሁ ወጣሁ ከማህጸን\n\nከቃልኪዳን ስም ጋር አደግኩኝ አብሬ\nምልጃሽ ሳይለየኝ አለሁ እስከ ዛሬ\nየህይወቴን ፊደል ካንቺ ላይ ቆጠርኩኝ\nበልጅሽ አምኜ ዳግም ተወለድኩኝ\n\nየክፉ ቀን ስንቄ ያዘልኩሽ በልቤ\nየህይወቴ ምግብ የእንጀራ መሶቤ\nእንደ ትላንትናው ዛሬም እጠራሻለሁ\nየመስቀል ስር ክብሬን እንዴት እረሳለሁ\nየመስቀል ስር ክብሬን እንዴት እተዋለሁ', 'am', 259, 0),\n(2, 'ሰላም አርጊው', 'ሰላም አርጊው\nሰላም አርጊው ማርያም ስጭን የእጅሽን\nአንድ መንጋ ሆነን በዛ ቋንቋችን\nናፍቀናል ልጆችሽ ፍቅር አንድነትን\n\nበስንዴው መሀል እንክርዳዱን\nጠላት ዘራና ክፍፍሉን\nየፍቅር ቋንቋ ቀዘቀዘ\nአንድነታችን ደበዘዘ\nእንወድሻለን ማርያም\n\nያስጎነበሰን ሽክም ይቅለል\nበልጅሽ ምህረት ቀና እንበል\nሰላም እንዲሰፍን በምድሪቱ\nንጉሱን ማልጂው ንግስቲቱ\nእንወድሻለን ማርያም\n\nየሽምገላ ቃል ከእኛ አይውጣ\nያክፉ ዘመን እንዳይመጣ\nበመለያየት ተመስርቶ\nየፀና መንግስት የለም ከቶ\nእንወድሻለን ማርያም\n\nበረከት አዞል አምላካችን\nህብረት ባለበት መኖራችን\nክፍፍል ይቅር አሳስቢልን\nበቃል ኪዳንሽ አስጠልይን\nእንወድሻለን ማርያም\n\nክፋትን ተክለን በልባችን\nመልክ ብቻ ነው አምልኳችን\nወድቀን እንዳንቀር እንዳንጠፋ\nፍቅርን ሳይብን የአዳም ተስፋ\nእንወድሻለን ማርያም', 'am', 261, 0),\n(2, 'እናቱ ታውቅ ነበር', 'እናቱ ታውቅ ነበር\nእናቱ ታውቅ ነበረ መድኃኒት መሆኑን\nኢየሱስ አለችው ስታወጣ ስሙን\n\nመልዓኩ ገብርኤል ከእግዚአብሔር ተልኮ\nሲታጠቅ ሲፈታ ፊትሽ ተንበርክኮ\nትይዋለሽ አለሽ ልጅሽን ኢየሱስ\nመድኃኒት ነውና ሁሉን የሚፈውስ\n\nከስጋዋ ስጋ ነስቶ ከነፍሷ ነፍስ\nበተዋህዶ ሚስጢር የኛን ስጋ ቢለብስ\nአማኑኤል ተባለ ቢዛመድ ከሰው\nቅዱስ እግዚአብሔር ከኛ ጋር ነው\n\nብላ ሰየመችው መድኃኒአለም\nሰውን ወዷልና እስከዘለዓለም\nልጄ ወዳጄ ሆይ ስትለው ነበር\nእርሱም ለእናቱ ታዟል በፍቅር\n\nየትንቢቱን መጽሐፍ እያነበበች\nሀር ወርቁን አስማምታ እየፈተለች\nዙፋኑ መሆኑን አውቃ ነበርና\nገለጸች እራሷን በፍጹም ትህትና\n\nጨለማን የሚያርቅ ብርሃን ወለዳለች\nእርሷም የብርሃን እናቱ ተባለች\nአምላክን በክንዷ ብትታቀፈው\nወላዲተ አምላክ የእርሷ ስም ነው', 'am', 262, 0),\n(2, 'ጌታን ያቀፋት እጆችሽ', 'ጌታን ያቀፋት እጆችሽ\nጌታን ያቀፋት እጆችሽ\nእኔንም በፍቅር አቀፋ\nድንግል ማርያም በምልጃሽ\nክፋ ቀናቶች አስፋ\nየእግዚአብሔር እናት የሆንሽው\nለእኔም ሆነሻል እናቴ\nማርያም ስምሽ ሞገሴ ነው\nውዳሴሽ ጽነ ጉልበቴ\n\nመች ዘምሬልሽ ጠገብኩኝ\nመች ረካሁ አመስግኜ\nስምሽን በለበስኩት\nእንደ አባቶቼ ሆኜ\nልጅሽ የመረጣቸው\nያከበሩሽ ከብረዋል\nበሰማይና በምድር\nየልጅሽ ወዳጅ ሆነዋል\n\nዓይኔ በእንባ ይመላል\nይዘላል ልቤ በደስታ\nየጌታዬ እናት ብዬ\nሳቀርብ ኣንቺ ሰላምታ\nባረገኝ እንደ መልአኩ\nለእኔም አክናፍን በሰጠኝ\nከፊትሽ እንዳደገድግ\nአምላክ ወዳንቺ በላከኝ\n\nየመማጸኛ ጽናዬ\nየጸሎቴ ሙዳይ ነሽ\nየምስጋናዬን መስዋዕት\nስአምላክ የማቀርበብሽ\nየቤትሽ ተክል ነኝና\nእንዳልጠወልግ በከንቱ\nየሕይወት ውኃን አጠጪኝ\nድንግል አማላጂቱ\n\nበቃልኪዳንሽ ታምኜ\nኃጢአቴን እከሳለሁ\nበተወደደው ልጅሽ ፊት\nራሴን እጥላለሁ\nየምስጋና መሰንቆ ነሽ\nየቅዳሴውም እንዚራ\nየዓለሙ ንጉሥ ነውና\nእግዚአብሔር ከአንቺ ጋራ', 'am', 263, 0),\n(2, 'ምሬሀለው በለኝ', 'ምሬሀለው በለኝ\nምሬሀለው በለኝ ስለ ድንግል ማርያም\nመሀሪው መዳኒአለም ይቅር ባይ እንዳንተ የለም\n\nበሀጥያት ድንኳን ውስጥ ይብቃ መቀመጤ\nየቀናውን መንፋስ አድሰው በውስጤ\nየምህረት አይኖችህ ይዩኝ በይቅርታ\nስለ ድንግል ማርያም እስራቴን ፍታ\n\nቸል በማለቴ የደምህን ዋጋ\nተመልሼ ገባሁ ከጥፋት መንጋጋ\nሰላሜ ደፍርሶ ተቅበዝባዥ ሆኛለው\nስለ እናት ብለህ ማረኝ እልሀለው\nስለ ድንግል ማርያም ማረኝ እልሀለው\n\nበከንቱ መሻቴን ስጋ ነብሴን ቀብሮ\nአቅም አጥቻለው አጥንቴ ተሰብሮ\nከበረዶ ይልቅ ነጭ እንድታደርገኝ\nስለ ድንግል ማርያም ከሀጥያቴ ጠበኝ\n\nከንፋሮቼን ከፍተህ ልቁም ለምስጋና\nአንተን የጋረደኝ ጣሪያዬ ይነሳና\nአልብሰኝ ፅድቅህን ይቅር መራቆቴ\nስለድንግል ማርያም መልሰኝ ከቤቴ', 'am', 264, 0),\n(2, 'ያለሽ ልዩ ፀጋ', 'ያለሽ ልዩ ፀጋ\nያለሽ ልዩ ፀጋ ያለሽ ልዪ ክብር\nየሁሉ እመቤት በሰማይ በምድር\nአኩራሪተ መዐልት ምራገ ፀሎት\nሲነግሩሽ ሰሚነሽ ኪዳነምህረት\n\nበመከራ ላለው ሁኝለት መፅናኛ\nዕንባውን አብሺው አይዘን ዳግመኛ\nጉድለቱን ሙይለት በፈረሰው ቆመሽ\nስለምታስምሪ በልዩ ኪዳንሽ\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው\nእናቴ የሚልሽ አምላክሽ ልጅሽ ነው\n\nይበጠሰ ከእጁ የወህኒው ሰንሰለት\nየሞቱ ደብዳቤ ይቀየር በህይወት\nአዲስ ተስፋ ሞልተሽ አዲስ ሰው አድርጊው\nመቅበዝበዙ ይርሳ ድንግል አረጋጊው\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው\n\nበዕንባ የመጣው ይመለስ በደስታ\nመጠማቱ ይቅር ይሞላ በእርካታ\nስለቱ ሰምሮለት ይቁም ለምስጋና\nየአብራኩን ክፋይ አሳቅፊውና\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው\n\nተይዞ ለሚኖር በአልጋ ቁራኛ\nአንቺው እመቤቴ የዴውም ዳኛ\nመንገርስ ላንቺ ነው መማፀን ወዳንቺ\nተስፋን ለምትቀጥይ ህልምን ለምትፈቺ\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው', 'am', 265, 0),\n(2, 'ፍቅሯ የበዛለት', 'ፍቅሯ የበዛለት\nፍቅሯ የበዛለት ለክብሯ ይቆማል\nውድስት አንቲ እያለ ይዘምራላታል\n\nበመንፍስ ቅዱስ ሀይል እንደ ቅድስት ሀና\nእቀኝልሻለሁ በያሬድ ምስጋና\nበስጋሽ ድንግል ነሽ ድንግል በህሊና\nእሳቱን የወሰንሽ እጸ ደብር ሲና\nፍቅሯ የበዛለት ያመሰግናታል\nውድስት አንቲ እያለ ይዘምራላታል\n\nየሰላምታ ቃልሽ ይፍሰስ በጆሮየ\nጽናት ሀይል ሁኖኛል ድምጽሽ ለኑሮየ\nየመንፈስ ቅዱስ ጣት ካልቃኘው ደጋግሞ\nማንስ ይቻለዋል ሊወድስሽ ቁሞ\nፍቅሯ የበዛለት ያመሰግናታል\nውድስት አንቲ እያለ ይዘምራላታል\n\nጓዳየን ጎብኝልኝ የወይኑን ማድጋ\nአንች ታውቂውያለሽ ችግሬን በጸጋ\nቀና ብየ ልሂድ ይብቃ ማጎንበሴ\nሰአሊ ለነ ቅድስት በቅድመ ስላሴ\nፍቅሯ የበዛለት ያመሰግናታል\nውድስት አንቲ እያለ ይዘምራላታል', 'am', 266, 0),\n(2, 'ትዝ አለኝ በላይሰብ', 'ትዝ አለኝ በላይሰብ\nትዝ አለኝ በላይሰብ ሰምቼ ታምርሽን\nድንግል እሰጣለሁ ለጠራ ስምሽን\nእመጸውታለሁ ለጠራ ስምሽን\n\nከሰው ተገለለ ብዙ ነፍስ አጥፍቶ\nበምልጃሽ ተማረ ጥርኝ ውኃ ሰቶ\nስምሽ ጉልበት አለው ጨካኙን ያራራል\nስለ እማምላክ ብሎ ድኃው ጠግቦ ያድራል\n\nለሲኦል የታጨች ነፍሱ ለፍርድ ቆማ\nበላይሰብ ዳነ አንች ሆንሽው ግርማ\nይህን ያላወቁ ክብርሽን የናቁ\nይስገዱ ለስምሽ ከእግርሽ ስር ይውደቁ\n\nየንጉስ ከተማ አምላክ የኖረብሽ\nነፍሴ ትጠግባለች ማርያም ማርያም ስልሽ\nስምሽ አያሳፍር አንገት አያስደፋ\nአንችን ለሸለመኝ አምላክ ክብሩ ይስፋ\n\nአልጠራጠርም ምልጃሽ ይረዳኛል\nካቀረቀርኩበት ቀና ያደርገኛል\nአምላክን ያቀፉ ብሩካን እጆችሽ\nእኔንም ይዳብሱኝ ቆሜያለሁ ከደጂሽ', 'am', 267, 0),\n(2, 'መታደል ነው', 'መታደል ነው\nድንግል ምን መታደል ነው ማርያም ሆይ ጸጋሽ በዛ،\nወልደሽ ጡት ያጠባሽው እጹብ የዓለሙን ቤዛ።\n\nየሚያስገርም ጥበብ ነው እጅግ የሚደንቅ،\nከሕሊና በላይ ነው ከአእምሮ የሚረቅ،\nታላቁን መገለጥ ነው የምናወራው،\nየእግዚአብሔር ልጅ የሰው ልጅ መሆኑ እንዴት ነው።\n\nእንዴት ሆኖ አረ እንዴት ተከናወነ،\nበየቱ መንገዱ አምላክ ሰው ሰው አምላክ ሆነ،\nበማሕጸንሽ ያደረው ቡሩክ ነው ቅዱስ،\nይገባዋል አምልኮ ስግደት በመንፈስ።\n\nዐማኑኤል እግዚአብሔር ከእኛ ጋር ሆነ،\nየዓለም ቤዛው ክርስቶስ በአንቺ አደረ،\nየአዳኛችን የበጉ ታላቅ አዳራሽ،\nሰላም ለአንቺ ድንግል ሆይ ጸጋ የተመላሽ።', 'am', 269, 0),\n(2, 'ማር ማር አለው', 'ማር ማር አለው\nማር ማር አለው ከንፈሬን ማርያም እላለው\nዛሬም የልቤ እኮ ነሽ ደጓ እናቴ እመቤቴ\n\nየት አለና ያሁሉ ድካሜ ዛሬ\nእናቴ ሆይ ሞገስ ላንቺ ፀንቷል እግሬ\nለደካማው ለተገፋው ድጋፍ ሆነሽ\nእስከ ዛሬ እስከዚህ ቀን በልቤ አለሽ\n\nይበረታል ሰነፍ ልቤ ሲሰማሽ\nለስንቱ ሰው መጽናኛ ነው ውብ ድምፅሽ\nፈነደቀች ኤልሳቤጥም በደስታ\nየአንድዬ እናት የሰላምታሽን ድምጽ ሰምታ\n\nአልከዳሽም አልተውሽም ለዘለዓለም\nቀኜ ትክዳኝ ከዚህ በላይ ኪዳን የለም\nሰው ከእናቱ ከምቾቱ ጉያ ሸሽቶ\nመች ይጠግባል ከሰው ሌማት እሕል በልቶ\n\nደመናዬ ረሰረስኩኝ በዝናብሽ\nየሕይወት ውሃ ሆኖልኛል ፍቅን ልጅሽ\nከልቤ ጋር ልጫወተው እስኪ ላውራ\nበጭንቄ ቀን ወዳጄ ነሽ በመከራ', 'am', 270, 0),\n(2, 'ድንግል እናቴ', 'ድንግል እናቴ\nድንግል እናቴ ነይ ድረሽልኝ\nወገን የለኝም ቀርቦ የሚያፅናናኝ\nካጠገቤ ሁኚ እና አለሁ በይኚ\n\nይቆይልኛል ያልኩት ከእጄ ላይ አልቆ\nበሀዘን በሰቆቃ ጉልበቴ ደቆ\nበረከት አልባ ሆኜ እንዳልከፋ\nድረሽልኝ እናቴ ነይ የእኔ ተስፋ\n\nብቸኝነት ክፉ ነው አንገት ያስደፋል\nጭንቀትን አባብሶ ለክፉ ይሰጣል\nአንቺ ከጎኔ ካለሽ አልሸነፍም\nለዚህ ዓለም ሞኝነት እጄን አልሰጥም\n\nእንኳን ለደካማው ሰው ለእኔ ለባሪያሽ\nለዓለም ይተርፋል ፀሎት ልመናሽ\nበዚያ በፍርድ ሰዓት ጥላ ሁኚኝ\nክፉ ግብሬን መዝኖ እንዳያቀለኝ\n\nእረፍዶብኛል ጉዞው የሠርጉ ቤት\nሙሽራው ሊገባ ነው ሳልይዝ መብራት\nአፍጥኚኝ እናት ዓለም ለመልካም ሥራ\nየእሳት ሲሳይ እንዳልሆን ድንግል አደራ', 'am', 271, 0),\n(2, 'እመቤቴ ሆይ', 'እመቤቴ ሆይ\nእመቤቴ ሆይ ሀብቴ ነሽና\nሳመሰግንሽ ዲያቢሎስ ቢቀና\nገና አለኝ ገና ሌላ ምስጋና\nገና አለኝ ላንቺ አዲስ ምስጋና\n\nድልድይ ሆነሽን ተሻግረናል እኛ\nአንወስድም አንሞትም ዳግመኛ\nእናት አለችን በላይ በሰማይ\nአማላጃችን እሙ ለአዶናይ\n\nግዮን ከቦታል የርስትሽን ሀገር\nጣፋጭ ታምርሽ ይኖራል ሲዘከር\nዋሻው ያበራል ሜዳ ሳር ቅጠሉ\nመነኮሳቱ ንኢ ንኢ ሲሉ\n\nተፍገመገመ ራደ ጠላታችን\nየልጅሽ ሞገድ ሰፍኖ በላያችን\nሞገዱም ይጩህ ዲያቢሎስም ያውራ\nከእሳቱ አንወድቅም ሳለን ካንቺ ጋራ\n\nቤትሽ አድገናል ባማረው እልፍኝሽ\nየንጉሡ እናት እመ ብዙኃን ነሽ\nየራማው መልዐክ ክንፎቹን ዘርግቷል\nወደ ገሊላ ምስጋናሽ ተሰምቷል', 'am', 272, 0),\n(2, 'ቀስተ ደመና', 'ቀስተ ደመና\nቀስተ ደመና የኖህ ቃል ኪዳን መተማመኛ\nቃል ገብቷል በአንቺ እንዳያጠፋን በሞት ዳግመኛ\nመድሀኒት ወልደሽ ለጠፋው አለም ደስታ የሆነሽ\nሰንደቃችን ነሽ ለአለም ምንጠቁምሽ\n\nጌታ ምልክት ይሰጣችኋል\nየድንግል ፍሬም ያድናችኋል\nየአዳም ታሪክ ተገለበጠ\nሞት በልጅሽ ሞት ስለተዋጠ\n\nአሰልፎናል ለክብርሽ ዜማ\nየመማፀኛ የደል ከተማ\nሞልቶ ይፈሳል ፀጋ ምልጃሽ\nከብራችን በዝቷል ስናከብርሽ\n\nመላክ ነገረን ታላቁን ነገር\nእንደ ምትወልጂው ያለ ወንድ ዘር\nጌታ በልቡ ስለ ሳለሽ\nየሁሉ ፋጥረት ብፅይት አለሽ', 'am', 273, 0),\n(2, 'የፅድቅ በር ነሽ', 'የፅድቅ በር ነሽ\nየፅድቅ በር ነሽ የሙሴ ፅላት\nአክሊለ ሰማዕታት ምህረቃ ፀሎት\nየጌታ እናት ንፁህ አክሊላችን\nሐመልማለ ሲና እመቤታችን\n\nእመቤታችን ለእኛ ምርኩዝ ነሽ ከለላ ሆንሽን\nየእሳት ሙዳይ እሳትን ታቀፍሻል\nበብርሃን ተከበሽ ወርቅ ለብሰሽ\nከሴቶች ሁሉ አብ መረጠሽ\n\nእመቤታችን ድንግል ሆይ ልጆችሽ ዘወትር ይጠሩሻል\nስምሽን ለልጅ ልጅ ያሳስቡልሻል\nበተሰጠሽ ፀጋ በአማላጅነትሽ\nምህረትን አሰጪን ከመሃሪው ልጅሽ\n\nእመቤታችን ያልታረሰች እርሻ ዘር ያልተዘራባት\nየህይወትን ፍሬ ሰጠችን የእኛ እናት\nየታረደው መሲ እናቱን ወደዳት\nበቀኙ ቆማለች ድንግል እመቤት ናት\n\nእመቤታችን የእውነት ደመና ዝናብ የታየባት\nወዳናለች ድንግል የታተመች ገነት\nክብርት ለሆነችው ኑ እንዘምርላት\nደስ ይበልሽ እንበል የብርሃን እናት', 'am', 274, 0),\n(2, 'አትለይኝ', 'አትለይኝ\nአትለይኝ ማንም የለኝም\nከጎኔ ቁሚ ብቻዬን ነኝ\n\nአይቀርም መፈተን መከራን መቅመሱ\nለዚህ ዓለም ጣጣ መተከዝ ማልቀሱ\nአምናለሁ እናቴ እንደማትለይኝ\nከአጠገቤ ሆነሽ እንደምት አፅናኚኝ\n\nእሾህ አሜኬላ ቋያ ነው መንገዱ\nቁሚልኝ እናቴ የልጅሽ ነው ፍርዱ\nአንዴ ሲሞላልኝ ደግሞሞ ሲጎልብኝ\nወዳንቺ እሮጣለሁ እንድታባብይኝ\n\nሲኖረኝ የሳመኝ ሳጣ ነከሰኝ\nየልቤ ያልኩት ሰው ጀርባውን ሰጠኝ\nየቱ ነው ድጋፌ ማንስ ይታመናል\nየልቤን ልንገርሽ ሰውስ ከፍቶብኛል\n\nየጭንቄ መርሻ ነሽ የብቸኝነቴ\nእጽናናለሁ ሳይሽ ድንግል እመቤቴ\nቢበዛም በደሌ ቢከፋም ስራዬ\nበአማላጅነትሽ ሞልቷል ማድጋዬ\n\nነፃነቴ ነሽ ሰላም ፀጥታዬ\nየነፍሴ እረፍት ነሽ የሁለንተናዬ\nረስርሷል ውስጤ በፍቅርሽ ዝናም\nአትወጪም ከውስጤ እስከ ዘላለም', 'am', 275, 0),\n(2, 'ለውዳሴሽ ልትጋ', 'ለውዳሴሽ ልትጋ\nለውዳሴሽ ልትጋ ስምሽ ግርማ ያለው\nእመቤቴ ስልሽ እውላለው\n\nከልቤ አቀርባለሁ ምስጋናን ለስምሽ\nመለመኛዬ ነሽ ፅኑ ቃልኪዳንሽ\nበሰላምታ ድምፅሽ ያልፅና ማን አለ\nፅንሱ በማህፅን በደስታ ዘለለ\n\nማርና ወተት ነው የስምሽ ስያሜ\nእመቤቴ ስልሽ ይቀላል ሸክሜ\nቅኔ ማህሌቱ ሰአታት መዝሙር\nያመሰግኑሻል ምድርና ጠፈሩ\n\nእናቱ ነሽና አንቺ ለኢየሱስ\nአድሮብሽ ይኖራል የእግዚአብሔር መንፈስ\nሳሊነነ ብዬ ይህው ቀኑን ጀምራለው\nልጅሽን አምኜ ነገን እኖራለሁ\n\nነይ ነይ እልሻለሁ እንደ ካህናቱ\nበሳእታት ፅሎት ቆሜ በሌሊቱ\nዝም አልልም እኔ አወድስሻለሁ\nየአለምን መከራ እረሳብሻለሁ', 'am', 276, 0),\n(2, 'አክሊለ ፅጌ', 'አክሊለ ፅጌ\nክበር በጌራ ወርቅ አክሊለፅጌ\nአክሊለ ፅጌ ማርያም\n\nስሟ ማርያም ነው አክሊለ ፅጌ\nየጌታ እናት አክሊለ ፅጌ\nእናት አባቷ አክሊለ ፅጌ\nያወጡላት አክሊለ ፅጌ\nከምድር ማር አክሊለ ፅጌ\nከሰማይ ያም አክሊለ ፅጌ\nብለው ሰየሟት አክሊለ ፅጌ\nድንግል ማርያምን አክሊለ ፅጌ\n\nየስሟ ጣእም አክሊለ ፅጌ\nከማር ይበልጣል አክሊለ ፅጌ\nእንደሷ ያለ ከየት ይገኛል አክሊለ ፅጌ\nየፍቅር መዝገብ አክሊለ ፅጌ\nነቅ የሌለባት አክሊለ ፅጌ\nለክብሯ ወደር አክሊለ ፅጌ\nማን አግኝቶላት አክሊለ ፅጌ\n\nየከበረ ዘውድ አክሊለ ፅጌ\nየወርቅ ሙዳይ አክሊለ ፅጌ\nየሽቶ ብልቃጥ አክሊለ ፅጌ\nየነፍሴ ሲሳይ አክሊለ ፅጌ\nከጥፋት ውሀ አክሊለ ፅጌ\nኖህ የዳነብሽ አክሊለ ፅጌ\nየሰላም መርከብ አክሊለ ፅጌ\nቤቱ አንቺ ነሽ አክሊለ ፅጌ\n\nበቤተመቅደስ አክሊለ ፅጌ\nስትኖር ተመርጣ አክሊለ ፅጌ\nምግቧን ይዞላት አክሊለ ፅጌ\nፋኑኤል መጣ አክሊለ ፅጌ\n15 አመት አክሊለ ፅጌ\nሲሆናት ድንግል አክሊለ ፅጌ\nበገብርኤል ብስራት አክሊለ ፅጌ\nተፀነሰ ቃል አክሊለ ፅጌ', 'am', 277, 0),\n(2, 'አዛኝት ማርያም', 'አዛኝት ማርያም\nአዛኝት ማርያም በረድኤት ነይ\nሰዋስወ ወርቅ እመ አዶናይ\nእናትነትን ከድንግልና\nአስተባብራለች ፍጽምት ናትና\n\nአምላክ ወሰብዕ ተብሎ ልጇ እንደሚጠራ\nድንግል ወእም አላት እናቱ ናትና\nምሳሌ አጣሁላት ለድንግል ማርያም\nፈጽሞ በማድነቅ እናርምም ዝም እንበል\n\nየብርሃን ድባብ ይኸው ተዘረጋ\nድንግልም መጥታለች ከአንድ ልጇ ጋራ\nነገደ መላዕክት በግራ በቀኝ\nታላቅ ምስጢር አየሁ ተመስጦም ያዘኝ\n\nጸጋ በረከትሽ በእኔ ላይ ይውረድ\nእንዳመሰግንሽ እንደ ሊቁ ያሬድ\nበአንቺ ተጠቅመዋል ካህናቱ ሁሉ\nበሰዓታት ጸሎት ንዒ ንዒ እያሉ\n\nርኅርኂት እመቤት አዛኝት ለፍጥረት\nጻድቃን ከአንቺ አዩ ፍጹም ደግነትን\nየእንጀራ ቤት ድንግል ፀዋሪተ ፍሬ\nተአምርሽን ልናገር አልችልም ዘርዝሬ', 'am', 278, 0),\n(2, 'ጎሳ ልብየ', 'ጎሳ ልብየ\nጎሳ ልብየ ቃለ ሰናየ\nወአነ አይድ ቅዳሴሃ ለማርያም\n\nእኔስ የማርያምን ውዳሴዋን እናገራለው\nእንደ አባቴ ዳዊት በበገና እዘምራለው\nቀን ከሌሊት ሳልል ለምስጋና እተጋለሁ\nየኃጢያቴ ቁስል እንዲ ፈወስ አጮሃለሁ\nምርኩዜ ነሽና እመቤቴ ባንቺ እመካለው\n\nኦ እመቤቴ በእውነት እንወድሻለን\nየእውተኛ መብል ክርስቶስን ወለድሽልን\nምክንያተ ድኂን ድንግልማርያም የአምላክ መገኛ\nባማላጅነትሽ በመታመን እንጮሃለን እኛ\nምህረትን አሰጪን ኪዳነምህረት የዓለም መዳኛ\n\nስለቸርነትሽ እመቤቴ ለእኔ እናቴነሽ\nስለንግስትነትሽም እመቤቴ ነሽ\nዝናባት ሳያጠጡት አየራትም ሳያሳድጉት\nሰማያዊ እንጀራ የሰጠሽን ቤተልሔማዊት\nቅድስተ ቅዱሳን የኖኅ መርከብ የአምላክ እናት\n\nቃና ዘገሊላ በሠርጉ ቤት በዛ ተገኝተሽ ሳለሽ\nውሃውን ወደወይን ባንቺ ምልጃ እንዳስለወጥሽ\nዛሬም የኔ ህይወት ወይኑ አልቆ ባዶ ሆኗልና\nአንቺ የአምላክ እናት ንፅህት ቅድስት ርኀርይተ ሕሊና\nህይወቴን አንጽተሽ ቀድሰሽው ሙይው በምስጋና', 'am', 280, 0),\n(2, 'እኔ የማርያም ነኝ', 'እኔ የማርያም ነኝ\nበእስራቴ አላፍርም እኔ የማርያም ነኝ\nእሮማም አይደለው ፈፁም ክርስቲያን ነኝ\nከእመቤቴ ፍቅር የሚለየኝ ማነው\nመከራ ነው ችግር ወይስ እስራት ነው\n\nአንተ መዝሙረኛ ነብዩ ዳዊት\nእንድታሸበሽብ ከታቦቱ ፊት\nሚልኮን በትንቅህ ሰገነት ላይ ሆና\nእግዚአብሔር አይቷታል ሳትናገር ገና\nእኔስ ለእመቤቴ እዘምራለሁ\nፍቅሯ በደሜ ውስጥ እንዳለ አውቃለሁ\nስሟን ለምን ጠራ ተብዬ ስጠየቅ\nአድምጡልኝ መልሴን ድንግልን እኔ አለቅ\nበአማን በአማን እረዳቴ ናት እመቤታችን\n\nየኤልዛቤት ጭፍሮች መተው ይዘውኝ\nጭው ያለ በረሀ እስር ቤት ጣሉኝ\nሰለ እስራቴ ጌታዬ አውቆልኛል\nሁሉን ተመልክቶ ተበቀሎልኛል\nከዝምታ የተነሳ እንደ ዲዳ ሆንኩኝ\nለበጎ ነገር እንኳን ዝምም ያለኩኝ\nበእኩለ ሌሊት ሊያስፈራሩኝ መተው\nሰሀሊ ለነ ስላት ብርታትን አገኘው\n\nረበናል ዛሬም መስክረው አሰት\nወደፍርድ ወሰዱኝ ከማላውቅበት\nከሳሾቼም ቀርበው ሲከራከሩኝ\nእውነተኛው ዳኛ አሰናበተኝ\nየምስጋና ዘውድን ጌታ ደፍቶልኛል\nለድንግል ውዳሴ ላቀርብ ፈቅዶልኛል\nበአለሟ እናት እና ለቅድስ ሥላሴ\nእስከመጨረሻው ታምስግናት ነፍሴ', 'am', 281, 0),\n(2, 'ሶልያና', 'ሶልያና\nየኤፍሬም ውዳሴ ማርያም ድንግል\nሞገሴና ክብሬ በሰማይ በምድር\nእኔስ አቀርባለሁ አዲሱን ምስጋና\nሶልያና ብዬ ድንግል ሶልያና።\n\nእንደ ገብርኤል ላመሰግንሽ\nመጥቻለሁ ማርያም ልቆም ከፊትሽ\nእንደምትባርኪኝ አውቃለሁ ማርያም\nከአንቺ ጋር ስላለ መድኃኔዓለም።\nፊደል ናት ማርያም ፊደል ናት\nሁላችን በእርሷ የተማርንባት።\n\nየኤልሳቤጥ ልጅ ነኝ ግቢልኝ ከቤቴ\nድምጽሽን ሲሰማ ይጸናል ጉልበቴ\nዮሐንስም አውቆሽ በማኅጸን ሰግዷል\nአንቺ የምትሰጪው ዓለም ያስደንቃል።\nፊደል ናት ማርያም ፊደል ናት\nሁላችን በእርሷ የተማርንባት።\n\nበዋዛ ፈዛዛ የኖርሽ አይደለሽም\nበቤተመቅደስ ነው አስተዳደግሽም\nኢያቄም ወሐና ወለዱ ሰማይ\nድንግል ተዘጋጀች ለአስርቆ ፀሐይ።\nፊደል ናት ማርያም ፊደል ናት\nሁላችን በእርሷ የተማርንባት።\n\nውዳሴሽን ሲያደርስ አባ ጽጌ ድንግል\nከፍ ከፍ እያለ በሰማይ ይበራል\nምስጋናሽ በዝቶልኝ ለእኔም ለባሪያሽ\nበአበው አጠራር ሶልያና አልኩሽ።\nፊደል ናት ማርያም ፊደል ናት\nሁላችን በእርሷ የተማርንባት።', 'am', 282, 0),\n(2, 'መራራው ሕይወቴ', 'መራራው ሕይወቴ\nመራራው ሕይወቴ ጣፈጠ በማርያም\nሐዘን ስደት ይቅር እስከ ዘለዓለም\nተፈውሷል እና በእመቤታችን\nየመሪባ ውሃ ተባረከልን\nበእግዝእትነ ማርያም እንልሀለን\n\nሀገሪትዋ መልካም ኑሮዋ መራራ\nበስደት አለቀ ወገኔ በተራ\nሽማግሌ እንዲጦር ህፃናት እንዲያድጉ\nኤልሳን የሚተካ አባት ሰው ፈልጉ\nማሰሮ አምጡ ጨውን ጨምራቹ\nሞት እንዳይነግስ በመካከላቹ\nማረን እንበል ኤሎሄ ብለን\nእንዋደድ እንዲሰምርልን\nትውልድ ሁሉ ብጽዕት የሚሉሽ\nኢትዮጵያን እንባዋን አብሺ\n\nታለቅሳለች እና እማማ ኢትዮጵያ\nየወላዶች መካን አርገዋት ልጆቿ\nዓለሙም ንብረቱም ሁሉም ያልፋልና\nይበቃናል እንበል በቀና ልቦና\nየፃናት ድምጽ ተሰማ በራማ\nስለሆነች ምድሪቱ አኬልዳማ\nየዘገየ ቢመስል እግዚአብሔር\nቀድሞ ይፈርዳል ሳሉ በምድር\nየአቤል ደም ፀባዎት ደረሰ\nቃኤልስ ወዴት ገሰገሰ\nላዛኝትዋ ሁሉ ይሆናልና\nንገሯዋት በጽኑ ልመና\n\nእኔ የኬፋነኝ ያጵሎስ አትበሉ\nየተለያየ መንግስት አይጸናም እንዲሉ\nየኢትዮጵያ ልጆች አንድ ነን ሁላችን\nልዩነት እናጥፋ ከመካከላችን\nስንዴ መሀል እንክርዳድ አንዝራ\nተደምስሶል የዳቢሎስ ሴራ\nባስጨናቂወች እጅ አትጣለን\nፍረድልን እናነባለን\nለልጁ አባት ይገደዋልና\nአምላክ ሆይ ተመልከተን ናና\nስለማርያም ብለን ለምነን\nአልፈናል ያን ክፉ ዘመን\n\nሀገርን አይተውም ያላንዳች ጻድቅ\nስውሩም ይታያል አይሆንም ድብቅ\nየአባቶቼ እርስት ስምዋም ቶኔቶር\nገበዝዋ ጊዮርጊስ ነው አስራት የድንግል\nዳሯዋን እሳት መሀልዋን ገነት\nለኛም ይስጠን ፍቅር አንድ ነት\nየተሳቱ ቅዱሳን መሸሻ\nኖላዊ ሄር ጠባቂሽ ነው ጋሻ\nትውልድ ሁሉ ብጽት የሚሉሽ\nኢትዮጵያን እንባዋን አብሺ', 'am', 283, 0),\n(2, 'አዘክሪ ድንግል', 'አዘክሪ ድንግል\nአዘክሪ ድንግል አዘክሪ\nለልጅሽ አሳስቢ አዘክሪ\nለኃጥአን አኮ ለጻድቃን\n\nካንቺ መወለዱን አዘክሪ\nበቤተልሔም አዘክሪ\nበጨርቅ መጠቅለሉን አዘክሪ\nመኝታው ግርግም አዘክሪ\nለኃጥአን አኮ ለጻድቃን\n\nበዚያ በብርድ ወራት አዘክሪ\nየገበሩለትን አዘክሪ\nየአድግና የላም አዘክሪ\nእስትንፋሣቸውን አዘክሪ\nለኃጥአን አኮ ለጻድቃን\n\nበግብጽ በረሃ አዘክሪ\nመሠደድሽን አዘክሪ\nየአሸዋውን ግለት አዘክሪ\nርሃቡና ጥሙን አዘክሪ\nለኃጥአን አኮ ለጻድቃን\n\nበመቃብሩ ዘንድ አዘክሪ\nባነባሽው እንባ አዘክሪ\nአሳስቢ ድንግል ሆይ አዘክሪ\nገነት እንድንገባ አዘክሪ\nለኃጥአን አኮ ለጻድቃን', 'am', 284, 0),\n(2, 'ስላረገችልኝ ለእናቴ', 'ስላረገችልኝ ለእናቴ\nስላረገችልኝ ለእናቴ\nምን እክፈላታለሁ ለእመቤቴ\nከችግር ከሀዘን ያወጣችኝን\nመጣችሁ እዩልኝ አዛኝታን\n\nነጻነቴ እኮ ነሽ ክብርና ሞገሴ\nእመቤቴ ብዬ አልጠግብም ለራሴ\nኖህ የተረፈብሽ አማናዊት መርከብ\nለኔም ሆነሺኛል ለህይወቴ ወገብ\nርግብየ ንኢ ድንግል ባርኪኝ በመስቀል\n\nበጨለማ ላሉ ብርሀን ወጣላቸው\nጥላ የጣለው ሞት ተገፈፈላቸው\nአንቺ ቤተልሄም የዳዊት ከተማ\nይቅር ባይ ክርስቶስ ድምጹን ባንቺ አሰማ\nርግብየ ንዒ ድንግል ባርኪኝ በመስቀል\n\nየሰላም አርማ ነሽ ቀስተ ደመናዬ\nከኢየሱስ ክርስቶስ ሆንሽ አስታራቂዬ\nህይወቴ ታደሰ ቤቴም በአንቺ ሞላ\nየነቢያት ሀገር ሆነሽኝ ከላላ\nርግብየ ንዒ ድንግል ባርኪኝ በመስቀል\n\nአማላጂቱ ሆይ እማልድሻለሁ\nበስጋም በነፍስም ያንቺ ነኝ ብያለሁ\nከሞት ወደ ህይወት መሻገሪያ ድልድይ\nካንቺ ነው የተገኘው የማይጠልቀው ጸሀይ\nርግብየ ንዒ ድንግል ባርኪኝ በመስቀል', 'am', 285, 0),\n(2, 'የማርያም ነህ ይሉኛል', 'የማርያም ነህ ይሉኛል\nልቡ ያዘነና የተከዘ ይፅናናል\nይለብሳል ባንቺ የታረዘ\nስምሽን ጠርቼ መች አፍራለው\nእመአምላክ ብዬ እጣራለው\nኪዳነ ምህረት እልሻለው\n\nወዳጅ መስሎ ነው ያጠቃኝ\nከሲኦል ረግረግ የጣለኝ\nበስጋ ከይሲ ተሰውሮ\nአበካከነኝ ልቤን ሰብሮ\nየጠገነልኝ ስብራቴን\nከሩቅ አየሁት መዳኒቴን\nየወለደችው ቤተልሔም\nተኝቶ አየሁት ከግርግም\n\nሰባ ስምንት ነፍስ የበላው\nስምሽን ሰምቶ ነው የዳነው\nጥላሽ ቢያጠላ ከሚዛኑ\nመዳን ሆነለት ሆና ቀኑ\nበደቀመዝሙር ስም ያጠጣ\nያገኛል ክብር ጌታ ሲመጣ\nበእናታችን ስም የዘከረ\nበሰማይ ይሆናል የከበረ\n\nበማጣቴ እና በስደቴ\nአንቺው ግቢበት በሕይወቴ\nእየጠራው ስምሽን\nሞትን ተሻገርኩ መከራን\nእሱ የማርያም ነው ይሉኛል\nማን ነገራቸው አውቀውኛል\nእናቱ ማርያም የእግዚአብሔር\nመታወቂያዬ የኔ ክብር', 'am', 286, 0),\n(2, 'ገሊላ እትዊ', 'ገሊላ እትዊ\nእመቤቴ እስከ መቼ በባዕድ ሀገር ትኖሪያለሽ\nገሊላ ግቢ አገርሽ ገሊላ ግቢ\n\nገሊላ እትዊ ሃገረኪ ገሊላ እትዊ\n\nእመቤቴ ማርያም ገሊላ እትዊ\nስደቱ ይበቃሻል ገሊላ እትዊ\nሄሮድስ ሞቷል ብሎ ገሊላ እትዊ\nገብርኤል ነግሮሻል ገሊላ እትዊ\nበእሳት ሠረገላ ገሊላ እትዊ\nዑራኤል ይመራሻል ገሊላ እትዊ\n\nየዝናቡ ጌታ ገሊላ እትዊ\nእናት ሆነሽ ሳለ ገሊላ እትዊ\nሰይጣን በሰው አድሮ ገሊላ እትዊ\nእያስከለከለ ገሊላ እትዊ\nውሃ ጥም ጸንቶብሽ ገሊላ እትዊ\nአፍሽ ደርቆ ዋለ ገሊላ እትዊ\nይበቃል እናቴ ገሊላ እትዊ\nእረሃብ ጥማትሽ ገሊላ እትዊ\nሂጂ ወደ ገሊላ ገሊላ እትዊ\nወደ ዘመዶችሽ ገሊላ እትዊ\n\nየሰማዕታት አክሊል ገሊላ እትዊ\nየጻድቃን እናት ገሊላ እትዊ\nባርከሽ ሰጠሻቸው ገሊላ እትዊ\nመከራን ስደት ገሊላ እትዊ\nእኛም ይታደለን ገሊላ እትዊ\nየአንቺው በረከት ገሊላ እትዊ\n\nገጽሽ ብሩህ መልካም ገሊላ እትዊ\nልክ እንደ ፀሐይ ገሊላ እትዊ\nእግዝእትነ ማርያም ገሊላ እትዊ\nእሙ ለአዶናይ ገሊላ እትዊ\nአይገባም ለአንቺ ገሊላ እትዊ\nመከራና ስቃይ ገሊላ እትዊ', 'am', 287, 0),\n(2, 'ታብሷል እንባዬ', 'ታብሷል እንባዬ\nታብሷል እንባዬ،\nሸሽቷል መከራዬ،\nማርያም ማርያም እያልኩ،\nኸረ ስንቱን አለፍኩ።\n\nእኔስ መስሎኝ ነበር የማይገፋ ቀኑ،\nነፍሴን ያስጨነቃት የሃዘን ወላፈኑ،\nማልቀስ ብቻ ሆኖ ዘወትር ሥራዬ،\nአናግርሻለሁ ሆኜ ለብቻዬ።\nድንግል ደረሽልኝ،\nሕልሜን ፈታሽልኝ،\nአልኩኝ ቀና ቀና،\nያም ቀን አለፈና።\n\nመቆሸሼን ዐይቶ ከሳሼ ቢከሰኝ،\nእመ አምላክ ግን ምልጃሽ አዲስ አደረገኝ،\nነጩን አለበስሽኝ ወርቃማውን በፍታ،\nእንዴት ዘነጋለሁ የአንቺንስ ውለታ።\nበቀኙ ባትቆሚ،\nጸሎቴን ባትሰሚ،\nአይቀናም ጉዞዬ،\nጽልመት ነው ተስፋዬ።\n\nእንደ እናት አባብለሽ አሳድገሺኛል،\nኑሮዬ ሲጨልም ብርሃን ሆነሺኛል،\nየተማመንኩበት ሲሸሸኝ ወዳጄ،\nአንቺ ግን ተገኘሽ በጓዳ በደጄ።\nአፈራች በለሴ،\nተደሰተች ነፍሴ،\nለምን ላቀርቅር،\nአሁን ልዘምር።\n\nትናንት ያዩኝ ሁሉ ዛሬ ይገረማሉ،\nእንዴት በእግሩ ቆመ እየተባባሉ،\nለሰው የማይቻል ለልጅሽ ተችሏል،\nእንዳያልፉት የለም ሁሉም ነገር አልፏል።\nከቤቴ የማትጠፊ،\nችግሬን የምትቀርፊ،\nእንዳንቺ ማን አለ،\nጭንቀቴን የጣለ።', 'am', 288, 0),\n(2, 'እንደ ትላንትናው', 'እንደ ትላንትናው\nእንደ ትላንትናው\nከአፌ ላይ አይጠፋም የስምሽ ምስጋና\nእንደ ልጅነቴ\nበፍቅር ያነሳሻል ዛሬም አንደበቴ\nበቅዱሱ ስፍራ በአውደምህረት\nስጠራሽ አድጌ ኪዳነምህረት\n\nገና ልጅ ሳለው ነበር ሳወድስሽ\nአፌን የፈታሁት ዘምሬ ለክብርሽ\nብወድሽ ባነሳሽ መቼ ቀን ጠግቤ\nይኸው ለዚህ ደረስኩ አትሜሽ በልቤ\nየአፌ ዜማ ነሽ ጥበብ ለከንፈሬ\nኪዳነምህረት ነው አሁንም መዝሙሬ\n\nየእናትን ውለታ ያውቃል የቀመሰ\nበእቅፏ ያደገ ለክብር የደረሰ\nእኔም አውቀዋለሁ ያንቺን ደግነት\nከቃላት በላይ ነው ያጥራል አንደበት\nየተደረገልኝ አለ ብዙ ነገር\nለዚህ ነው እናቴ ማነሳሽ በፍቅር\n\nአይኖቼ በናፍቆት በስስት ያዩሻል\nልሳኔ በፍቅር ደጋግሞ ያነሳሻል\nከመቅደስሽ ቆሜ የውስጤን ነገርኩሽ\nህልሜን ስትፈቺ እናቴ አየሁሽ\nእውነትም አዛኝ ነሽ ለተማፀነሽ\nግራ ለገባው ሰው ቅርብ ነው ምልጃሽ', 'am', 289, 0),\n(2, 'እምባዬን አብሽልኝ', 'እምባዬን አብሽልኝ\nእምባዬን አብሽልኝ ስሚኝ ጸሎቴን\nየልቤን ስነግርሽ ያስጨነቀኝን\nማን አለ እንዳንቺ እኔን የሚያፅናና\nቀና ልበል ድንግል ምልጃሽ ይርዳኝና\n\nከልቤ ቃል እስኪወጣ መከራዬን አምቄያለው\nባንደበቴ በለሆሳስ በአርምሞ አወራለው\nንግግሬ ካንቺ ጋር ነው ልጅሽ ይስማ ልመናዬን\nመጨነቄን ተመልከቺ አርቂልኝ ፈተናዬን\n\nበእልፍኜ ተከትቼ ስማከርሽ የከረምኩት\nከለቅሶዬ ተፅናንቼ ደስታን ይሁን ያተረፍኩት\nማቅ ለብሼ እታያለው መጨነቄ በዝቷልና\nቤቴን ሙይው በበረከት ላመስግንሽ ልበርታና\n\nመሬት ስጭር በትካዜ የተፈታ ቀኔን እስካይ\nየብሶቴን ማቃለያ ማንጠረገ ከፊቴ ላይ\nወሰን አልፎ ሲዘረጋ የሃዘኔ መጋረጃ\nበእቅፍሽ አሳርፊኝ ቀና ልበል ባንቺ ምልጃ\n\nከማለዳ እስከ ማታ በሰቆቃ ተሰብሬ\nየፈለገኝ ያገኘኛል ከደጅሽ ላይ አቀርቅሬ\nግራ ቀኜ ገደልና የተዘጋ ጨለማ ነው\nተስፋ ስጪኝ እዘኝልኝ ይህን ዘመን ላሳልፈው', 'am', 290, 0),\n(2, 'ኪዳነምህረት ለኔ', 'ኪዳነምህረት ለኔ\nኪዳነምህረት ለኔ መመኪያዬ\nለችግሬ ደራሽ ነሽ መጠለያዬ\nህይወቴ ጎስቁሎ በነብሴ ብዝልም\nበምልጃሽ ታምኜ በኪዳንሽ ልቁም\n\nእጅግ ምስኪን ሆኜ ለሰዎች ብታይም\nሞልቶ የተረፈ ጥሪት ባይኖረኝም\nአንቺ ካለሽልኝ ጓዳዬ ሙሉ ነው\nአፍሮ አያውቅምና የተማፀነሽ ሰው\n\nዳቢሎስ እቅዱን በልቤ ቢያገባ\nተገፍቼ ባጊጥ በሰናዖር ካባ\nየሐጥያን ደሞዙ እንዳይከፈለኝ\nበሞት እንዳልጠፋ ድንግል ተለመኚኝ\n\nወገን የለኝ ዘመድ ፍፁም ካንቺ በቀር\nእኔን የሚረዳ በዓለም ስቸገር\nአይዞ በዪኝና ደግፊኝ እናቴ\nየጸጋ ልብስ ሁኚኝ ሲራቆት ህይወቴ\n\nነብሴ እንድትቀደስ ከርኩሰት አምልጣ\nከሴኬም ልሰደድ ወደ ቤቴ ልውጣ\nገሪዛን ልበልሽ ድንግል መሸሻዬ\nእዮአታም ልጅሽ መጣሁ አንቺን ብዬ', 'am', 292, 0),\n(2, 'ክነፈ ርግብ', 'ክነፈ ርግብ\nክነፈ ርግብ በብሩር ዘግቡር\nወገበዋቲሃኒ አንቲ ሀመልማለወርቅ\nአንቲ ምስራቅ ወወልድኪ ፀሀይ ፅድቅ\nአማን በአማን እይሀልቅ ኪዳነኪ ወላዲተ አምላክ\n\nዘመርን በትህትና ይገባሻልና\nሆነሻል ከለላ የፅድቃችን ጥላ\nማርያም ፊደላችን ፅዮን ማንበብያችን\nየሁሉ መማርያ የአምላክ ማደርያ\n\nጌታሽን ወልደሻል አዝለሽ ተሰደሻል\nፍቅርሽ ገደብ የለው ከቶ እዳንቺ ሚነው\nየእግዚአብሄር ከተማ የተመላሽ ግርማ\nስምሽ ይጣፍጣል ከፍጥረት ይልቃል\n\nበዱር በገደሉ የኖሩ በቃሉ\nሆነሻል ስንቃቸው አንባ መጠጊያቸው\nበእንተ ማርያም ብሎ የጠራሽ ለምኖ\nያጣ የለምና ይድረስሽ ምስጋና\n\nምክንያት አለን እኛ ተሰተሻል ለኛ\nሁሌም በልባችን አለሽ እናታችን\nየምትሆኚ ተስፋ አዝኖ ለተከፋ\nቀርቦ ለለመነሽ አፅናኝ እናት ነሽ', 'am', 293, 0),\n(2, 'ኦ አማላጂቱ', 'ኦ አማላጂቱ\nኦ አማላጂቱ\nየልዑል ዙፋን እናቱ\nብፅዕት እልሻለሁ\nእሰግድልሻለሁ\nብፅዕት እልሻለሁ\nእናቴ በምልጃሽ ስንቱን አልፌያለሁ\n\nአንቺ ያስቀደመ መች ይሰናከላል\nምልጃሽ የረዳው ሰው ክብርሽን ያወራል\nለኔም አንቺኮ ነሽ መተማመኛዬ\nዋስ ጠበቃዬ ነሽ ጥላ ከለላዬ\n\nየአበው ማህሌት የዘወትር ውዳሴ\nአንቺን ሳመሰግን ትረካለች ነፍሴ\nአይነጥፍም ምስጋናሽ ለዘላለም ከፌ\nለክብርሽ ተጋለሁ ከፊት ተሰልፌ\n\nአልጠራጠርም በአማላጅነትሽ\nአይቻለሁና ወይኑን አስሞልተሽ\nአማላጄ አንቺ ፈራጄ ልጅሽ\nስንቱን አስምረሻል ከፊቱ ቆመሽ', 'am', 294, 0),\n(2, 'እንወዳታለን', 'እንወዳታለን\nየጨለማው ዘመን ማብቂያ ምልክት ናት\nለዚህ ነው ማርያምን እጅግ የምንወዳት\nአይቀንስም ክብሯ ዓለም ምንም አለ\nቢያመሰግናት እንዴት በታደለ\n\nበመገረም ተይዞ ዓለም በጨለማ\nድኅነት እየራበው ጽድቅ እየተጠማ\nከቁስል ለመዳን የመድኃኒቱ እናት\nየሕይወት ውሃ ምንጩን መች አመሰገናት\nእኛ ግን ክብር አለን እኛ ግን ፍቅር አለን\nዓለም ምንም ይበል እንወዳታለን\n\nበደሙ አክሞናል የእርሷ የሆድ ፍሬ\nዓለም ክብሯ ርቆት ይጠይቃል ዛሬ\nታላቁ እውነታ ምሥጢሩ ይሄ ነው\nአምላክን ያየነው በእርሷ እናትነት ነው\nእኛ ግን ክብር አለን እኛ ግን ፍቅር አለን\nዓለም ምንም ይበል እንወዳታለን\n\nለእናቶች ቀን ሠጥቶ ዓለሙ ሲዘክር\nእንዴት ይቃወማል የእርሷን ምስጋና ክብር\nእግዚአብሔር ማስተዋል ጥበቡን ገልጦለት\nየድንግሊቱን ፍቅር በልቡ ይሳልለት\nእኛ ግን ክብር አለን እኛ ግን ፍቅር አለን\nዓለም ምንም ይበል እንወዳታለን\n\nበቀኙ ምትቆም ማርያም ንግስቲቱ\nለክብሯ መዘመር ምኑ ነው ስሕተቱ\nከቅዱስ ከገብርኤል እንደ ሰማነው ቃል\nመልካሙን ምስጋና ልባችን ያፈልቃል\nእኛ ግን ክብር አለን እኛ ግን ፍቅር አለን\nዓለም ምንም ይበል እንወዳታለን', 'am', 295, 0),\n(2, 'የአብርሃም ድንኳን ነሽ', 'የአብርሃም ድንኳን ነሽ\nየአብርሃም ድንኳን ነሽ\nየያዕቆብ መሰላል ነሽ\nማርያም ሰላም ልብለሽ\nምስጋናን ላቅርብልሽ\nማርያም ሰለም ልብልሽ ውዳሴን ላቅርብልሽ።\n\nህቱም ድንግልና ፍፁም ትህተና\nበስጋም በነፍስም ፍፅምት ነሽና\nውብተሽ አይቶ እናቱ አደረግሽ\nየሲና ሀመልማል በመን እንመስልሽ\nሰለም ለኪ ሰላም ለኪ ልበል ለክበርሽ\nደግሜ ደግሜ ላመስግንሽ ደግሜ ለአወድስሽ\n\nእርሱ ከመረጠሽ አሱ ካፀናሽ\nእንዴት ይቻለ ለኔ ላርግሽ የተስፋ ፍፃሜ\nሁኚ ከኔ ጋራ እንሻገራዋለው የአለምን መከራ\nሰላም ለኪ ልበል ለክብርሽ\nደግሜ ላመስግንሽ ደግሜ ላወድስሽ\n\nድንግል ፍቀጂልኝ ላወድስ ስምሽን\nፀጋ ከበዛልኝ ልመስክር ክብርሽን\nያገለግልሽ ዘንድ ልቦናዬ ሻተ\nበፍቅር ሞልተሽው ሰለ ተደሰተ\nሰላም ለኪ ልበል ለክብርሽ\nደግሜ ላመስግንሽ ደግሜ ላወድስሽ', 'am', 296, 0),\n(2, 'በእናቴ እቅፍ', 'በእናቴ እቅፍ\nበእናቴ እቅፍ ልጅ ሆኜ ገና\nአየሁ ፍቅርሽ እመ ትትና\nተራዬ ደርሶ አድጌ ዛሬ\nእኔም ጠራሁሽ ይዤ ዝማሬ\n\nአይረሳኝም ከልቤ አይጠፋም\nያኔ ያየሁት የፍቅርሽ ተስፋ\nባለ ግርማዋ ውቧ እመቤቴ\nፀጋሽ በዝቶብኝ ያበራል ፊቴ\n\nተራራማውን የኤፍሬም አገር\nሰላምታሽ ሰምቷል የልቤን መንበር\nያዘልለኛል ጉልበቴን ፈትቶ\nያዜማል አፌ ድምፅሽን ሰምቶ\n\nመዳፍሽ ከአይኔ መቼ ዞር ይላል\nእንባዬን ሲያብስ ያድራል ይውላል\nመአዛሽ አለ ሆኖኝ ትዝታ\nየእናትነትሽ ፍቅር ውለታ\n\nልሳኔን ቃኝተሽ የዜማ ሰው ነኝ\nየአለም ዘፈኗ የማይሸፍነኝ\nየልጅነቴ መክሊቴ አንቺው ነሽ\nየፀጋን ፍሬ የማተርፍብሽ', 'am', 297, 0),\n(2, 'የሐዲስ ኪዳን ኪሩብ', 'የሐዲስ ኪዳን ኪሩብ\nየሐዲስ ኪዳን ኪሩብ ዙፋነ መለኮት\nየልዑል ማደርያ ድንግል የእኛ እመቤት\nዓለም የዳነበት ይህን ታላቅ ምሥጢር\nበአንቺ ፈጽሞታል ሰይጣንን ሊያሳፍር።\n\nአምላክ የወደደው ለተዋህዶ ሥጋሽ\nኧረ እንዴት ታላቅ ነው ድንግል ሆይ ንጽሕናሽ\nበሀልዮ በነቢብ እንዲሁም በገቢር\nኃጢአት ሳይነካሽ ኖረሻል በክብር።\nይደንቃል ይረቃል ባንቺ የተደረገው\nየማን አእምሮ ነው የሚመረምረው\nእፁብ ድንቅ ነው ብቻ እንበለው።\n\nብርሃነ መለኮት ያኔ ሲዋሐድሽ\nየእሳት መጋረጃ መች ተጋረደልሽ\nየፍጥረታት ንጉሥ በአንቺ ተሰውሮ\nአዲስ አደረገን እንደገና ፈጥሮ።\nይደንቃል ይረቃል ባንቺ የተደረገው\nየማን አእምሮ ነው የሚመረምረው\nእፁብ ድንቅ ነው ብቻ እንበለው።\n\nሱራፌል ኪሩቤል ማየት የማይችሉት\nድንግል ወሰነችው ታቀፈችው በእውነት\nየሰማይ መላእክት በአንድ ዘመሩላት\nየዓለምን ፈጣሪ ታቅፋ ስለአዩአት።\nይደንቃል ይረቃል ባንቺ የተደረገው\nየማን አእምሮ ነው የሚመረምረው\nእፁብ ድንቅ ነው ብቻ እንበለው።\n\nእስኪ እንዴት ነበረ የዝማሬው ሥርዓት\nበማኅፀንሽ ውስጥ የቅኔው መሥዋዕት\nቅዳሴ መላእክት ሲደረግ በሆድሽ\nእንዴት አድርገው ነው የሰሙት ጆሮችሽ።\nይደንቃል ይረቃል ባንቺ የተደረገው\nየማን አእምሮ ነው የሚመረምረው\nእፁብ ድንቅ ነው ብቻ እንበለው።', 'am', 298, 0),\n(2, 'አክሊላችን ነሽ', 'አክሊላችን ነሽ\nአክሊላችን ነሽ ውበታችን\nትምክህታችን መፅናኛችን\nስምሽን ጠርተን ከሞት ድነናል\nምልጃሽ ረድቶን ቀና ብለናል\n\nፍሬ የሞላብሽ መልካሟ ተክል\nመፈወሻችን የሕይወት ጠበል\nበምልጃሽ ፋና ዓይናችን በርቶ\nክብርሽን አየን በብርሃን ፈክቶ\n\nጨው የሞላብሽ አዲስ ማሰሮ\nአለም ጣፈጠ ምሬት ተሽሮ\nተለውጠናል አዲስ ሆነናል\nድንግል ለክብርሽ እጅ ነስተናል\n\nመሰረቶችሽ የተቀደሱ\nክብርና ግርማ ጽድቅ የለበሱ\nእንከን የሌለሽ ንፁህ ተራራ\nበልጅሽ ፀዳል አለሙ በራ\n\nውዳሴሽ በዛ በአፋችን\nፍቅርሽ ታተመ በልባችን\nማርያም ማርያም ነው አዲስ ምስጋና\nለንጉስ እናት ይገባልና', 'am', 299, 0),\n(2, 'ሀረገ ወይን', 'ሀረገ ወይን\nሀረገ ወይን ሀረገወይን\n\nሰለሞን በብዕሩ የተጠበበብሽ\nመደምደሚያ እርግቤ ውበቴነሽ አለ\nበምናቡ ያየሽ ያዕቆብ በሎዛ\nነይ ነይ ድንግል መልካሟ መአዛ\n\nአስቀድሞ አባትሽ ቅኔ ተቀኘልሽ\nበገናን ደርድሮ ጽዮን ሆይ እያለ\nህይወት ተነበበ በመዳፍሽ ላይ\nምትክም የለሽ በምድር በሰማይ\n\nየማር ወለላነሽ ሀረገወይናችን\nምክኒያተ ድህን የመዳን ተስፋችን\nየሲና ሐመልማል ቀናኒሞስ ሽቶ\nእግዚአብሔር መርጦሻል ከአለም ለይቶ\n\nምስጋና ለጌታ ምስጋና ለስሙ\nከሐጥያት ባርነት ላነፃን በደሙ\nአምልኮ ውዳሴ ይሁን ላንተ ብቻ\nእኔስ ያንተአምሳያ አላገኝም አቻ\n\nמሰንቆውም ይውረድ ከተሰቀለበት\nለአምላክ ዘምሩ ላለው በሰማያት\nቅዱሳን መላእክት በዙሪያው ከበው\nይቀኙ ለክብሩ አዲስ ቅኔ ታጥቀው', 'am', 300, 0),\n(2, 'ቸሪቱ አማላጅቱ ሆይ', 'ቸሪቱ አማላጅቱ ሆይ\nቸሪቱ አማላጅቱ ሆይ\nእናቱ ነሽና ለአዶናይ\nበሥላሴ ፊት ስልጣን ያለሽ\nየባህሪያችን መመኪያ ነሽ\n\nተጥሎ አዝኖ የኖረው\nበልጅሽ ነው ቀና ያለው\nንጉሱን ስትወልጂ በበረት\nተፈታ አዳም ከእስራት\nዘጸውዓ ስምኪ\nወዘገብረ ተስካርኪ\nብሎ ቃልኪዳን ሰጠሽ\nፍጥረትን እንዲምርብሽ\n\nከሚያስብ ከማይዘነጋ\nፍጥረቱን ከሚያረጋጋ\nስላለሽ በእግዚአብሔር ቀኝ\nለኃጥአን ድንግል ለምኝ\nዘጸውዓ ስምኪ\nወዘገብረ ተስካርኪ\nብሎ ቃልኪዳን ሰጠሽ\nፍጥረትን እንዲምርብሽ\n\nከሰማይ ሰማያት ወርዶ\nመለኮት ሥጋን ተዋህዶ\nአየነው በጠባብ ደረት\nወሰንሽው በአጭር ቁመት\nዘጸውዓ ስምኪ\nወዘገብረ ተስካርኪ\nብሎ ቃልኪዳን ሰጠሽ\nፍጥረትን እንዲምርብሽ\n\nሰነድ ነሽ መታረቂያችን\nከተማም መማፀኛችን\nበሰማይ በምድርም ያሉ\nለክብርሽ ቅኔ ይቀኛሉ\nዘጸውዓ ስምኪ\nወዘገብረ ተስካርኪ\nብሎ ቃልኪዳን ሰጠሽ\nፍጥረትን እንዲምርብሽ', 'am', 301, 0),\n(2, 'አንቺ የወርቅ መቅጃ', 'አንቺ የወርቅ መቅጃ\nአንቺ የወርቅ መቅጃ ነሽ\nእኔ የተጠማሁ ነኝ\nልጅሽ የሕይወት ውሃ\nከጥሜ የሚያረካኝ\nእኔ ተሻጋሪ ነኝ\nማርያም ሆነሽኝ ድልድይ\nልጅሽ አሻጋሪ ነው\nከርስቴ የሚያስገባኝ\n\nእኔ እርቃኔን ነኝ ከጸጋው እርቄ\nበክፉ ግብር በኃጥያት ወድቄ\nማርያም አንቺ ነሽ የሸማኔ እቃ\nልጅሽ ልብስ ነው ለሁሉ የሚበቃ\n\nአንቺ መርከቤ እኔም ነጋዴ\nልጅሽ ዕንቁዬ ትርፌ ዘመዴ\nለእኔ ለድሃው ማከማቻዬ\nየከበር ጌጥ ልጅሽ ቤዛዬ\n\nእኔ ተጓዥ አንቺ መቅዘፊያ\nልጅሽ ወደብ ነው የህይወት ማረፊያ\nአንቺ ፊደል ነሽ እኔ ተማሪ\nልጅሽ ወንጌል ነው ቸር አስተማሪ', 'am', 302, 0),\n(2, 'በቤተልሄም', 'በቤተልሄም\nበቤተልሄም ድንግል ወለደች\nአማኑዔልን ታቅፋ ታየች\nእረኞች ተቀኙ መላዕክት ዘመሩ\nስብሀት ለእግዚአብሔር በሠማይ በምድሩ\n\nየያዕቆብ ኮከብ ከሩቁ ያየነው\nበኤፍራታ ዋሻ በዱር አገኘነው\nድንቅ መካንሀያል ወንድ ልጅ ተሠጠን\nበከብቶቹ ግርግም ተወልዷል ሊያነፃን\nድንግል ያጠባችው\nማርያም ያዘለችው\nሁሉ በእርሱ የሆነ እግዚአብሔር ነው\n\nያረምና ሠባ የቴርሠሥ ነገስታት\nከሩቅ ምስራቅ መጡ ወድቀው ሊሰግዱለት\nአንቺ ቤተልሄም የይሁዳ ምድር\nእልልታሽ ተሰማ የዳዊት ሀገር\nድንግል ያጠባችው\n\nማርያምን ለመውሰድ ዮሴፍ ሆይ አትፍራ\nከመንፈስ ቅዱስ ነው ይሄ ድንቅ ስራ\nያለዘራ በዕሲ ጌታን የወለደች\nየያቄም ልጅ ፅዮን እመብርሀን ነች\nድንግል ያጠባችው\n\nበስጋና በደም ስለተካፈለ\nፍፁም አምላክና ፍፁም ሰው ተባለ\nወልደ-ማርያም ነው ወልደ-እግዚአብሔር\nለአለም የሠጠህ ሠላምና ፍቅር\nድንግል ያጠባችው', 'am', 303, 0),\n(2, 'የአንደበቴ ጣፍጭ ውዳሴ', 'የአንደበቴ ጣፍጭ ውዳሴ\nያንደበቴ ጣፋጭ ውዳሴ\nምፅናናብሽ ታዛለ ነፍሴ\nከመቅደስሽ ፍቅር ተምሬ\nማርያም ማርያም ይላል ከንፈሬ\nልመናዬን ሰምተሻል\nበረድኤት ቀርበሻል\nበፍቅርሽ ተሸልሜ\nአረፍኩኝ ከሸክሜ\n\nቃሌ ነው በተሰማ\nተማፅኖዬን ሳሰማ\nበዙፋኑ ቀኝ ሆነሽ\nድንግል ታስምሪናለሽ\n\nማግኝት ማጣት አይደለም\nልመናዬ በአለም\nአድይኝ ማስተዋሉን\nእንድረዳው መስቀሉን\n\nአይመራኝም በትሬ\nድንግል ቆመሽ ከበሬ\nምርኩዜ ብዬሻለው\nአንቺን እደገፋለው', 'am', 304, 0),\n(2, 'እኔም ትውልድ ነኝ', 'እኔም ትውልድ ነኝ\nእኔም ትውልድ ነኝ ብፅዕት እልሻለሁ\nእንደ አባቶቼ ስምሽን አከብራለሁ\nአይደለም ከአለም ከስጋና ከደም\nበመንፈስቅዱስ ነው ያወኩት ያንቺን ስም\nስለዚህ ማርያም ሆይ ከፍ አደርግሻለሁ\nየፍጥረቱን ጌታ በእቅፍሽ ስላየሁ\n\nበዘላለም ኪዳን እግዚአብሔር በሰጠሽ\nከጥፋቱ ውሃ ትውልዱን አስጠለልሽ\nእስከ አድማስ ጥግ ብደረስ ክብርሽን ልገልጥ\nየሚስተካከልሸ የለም ከፍጥረት\n\nበሀጢእት ደክሜ ብሆም ኮልታፋ\nድንግል ሆይ ምልጃሽን አድርጌአለሁ ተስፋ\nምስጋናሽ በዝቶልኝ ከጧት እስከ ማታ\nተፈስሒ ልበል በገብርኤል ሰላምታ\n\nስለተቀበልኩኝ ስምሽን ከአባቶቼ\nለአለም እነግራለሁ ክብርሽን አብዝቼ\nይኸው እንደሰማሁ በአይኔም አየሁሽ\nመንገዴን ስትመሪ ከፊቴ ቀድመሽ', 'am', 305, 0),\n(2, 'ከከዋክብት በላይ ደምቃ', 'ከከዋክብት በላይ ደምቃ\nከከዋክብት በላይ ደምቃ\nከፍጥረታት ሁሉ ልቃ\nአየናት በንጉሱ ቀኝ\nማሪያምን በእግዚአብሔር እልፍኝ\n\nአላትና ሞገስ አላትና ግርማ\nአማናዊት ጺዮን የእግዚአብሔር ከተማ\nአምላክን በሆዷ ስላስተናገደች\nከፈጣሪ በታች ከፍጡር በላይ ነች\n\nአንች የገነት ምንጭ የውሀ ጉድጓድ\nየመልከ ግርማ አለሽ ውብ የሚወደድ\nየታተመች ፍሳሽ የተዘጋች በር\nማንም ያልገባባት ከእግዚአብሔር በቀር\n\nትውልድ በፊትሽ ይማልልልሻል\nንጉሰ ነገስት አዳኙን ወልደሻል\nታቦትእዶር ድንግል ስላለች እናቱ\nተላልፎ አይሰጥም አዳም ለጠላቱ\n\nልክ እንደ ጨረቃ ደምቃ እምትታይ\nእንደ ማለዳ ብርሀን የምትጎበኝ\nበንፅህናዋ ወልድን ማረከችው\nበቶም ድንግልና ፀንሳ ወለደችው', 'am', 306, 0),\n(2, 'ተአብዮ ነፍስየ', 'ተአብዮ ነፍስየ\nተአብዮ ነፍስየ ለእግዚአብሔር\nሰአሊለነ ማርያም ኀበወልድኪ ኄር መድኃኔዓለም\n\nየአብ ሙሽራ ነሽ የወልድም እናቱ\nለመንፈስ ቅዱስ ነሽ ጽራሃዊቱ\nበፊትሽ ሰገዱ ቅዱሳን መላእክት\nለምኝልን ማርያም ከቸሩ ልጅሽ ከመድኃኔዓለም\n\nከዋክብት ብርሃናት ሳይታይ ደመና\nታስበሽ ኖረሻል በአምላክ ህሊና\nገብርኤል ነገረሽ የክብርሽን ዜና\nለምኝልን ማርያም ከቸሩ ልጅሽ ከመድኃኔዓለም\n\nየወርቅ ታቦት ነሽ በሰማይ ያለሽ\nየፅድቅ ንግስት ነሽ የተመሰገንሽ\nበእናትነትሽ ተመካ ልብሽ\nለምኝልን ማርያም ከቸሩ ልጅሽ ከመድኃኔዓለም\n\nየአለሙን ጌታ በእቅፍሽ አየነው\nበመሀፀንሽ አድሮ ቃል ስጋ የሆነው\nእግዚአብሔር ስላንቺ ምስጋናው ብዙ ነው\nለምኝልን ማርያም ከቸሩ ልጅሽ ከመድኃኔዓለም\n\nየዳዊት ልጅ ማርያም ትምክህታችን\nየአማኑኤል እናት መሰብሰቢያችን\nየእግዚአብሔር ከተማ መማፀኛችን\nለምኝልን ማርያም ከቸሩ ልጅሽ ከመድኃኔዓለም\n\nድንግል በክሊሄም በነፍስም በስጋ\nጎዶሎ ይምላል አንቺን የተጠጋ\nክርስቶስ ወልደሽ ክሳችን ተዘጋ\nለምኝልን ማርያም ከቸሩ ልጅሽ ከመድኃኔዓለም\n\nበፊትሽ ልማፀን ቆምኩኝ ከደጅሽ\nልመናዬ ሁሉ ይግባ ከጆሮሽ\nለሚጠራሽማ ማርያም ቅርብ ነሽ\nለምኝልን ማርያም ከቸሩ ልጅሽ ከመድሐኒአለም', 'am', 307, 0),\n(2, 'አየኋት ባይኔ አሻግሬ', 'አየኋት ባይኔ አሻግሬ\nአየኋት ባይኔ አሻግሬ\nየያሬድን ውብ ዝማሬ\nተቀኘው እንደ አባቶቼ\nእጄን ለክብሯ ዘርገቼ\n\nድካም እና እንቅልፍ እንደምን ሊረታኝ\nድንጋይ ብንተራስ ፍቅርሽ አያስተኛኝ\nአይኔ ቢከደን አለሽ በምናቤ\nአልተከለልሽም ነግሰሻል በልቤ\n\nመረማመጃ የሎዛ መሠላል\nየዜማ ቤቴ የመቅደስ ጽናጽል\nየሰማይ ንጉስ በበላይሽ አለ\nድንኳን አድርጎ አንቺን የተከለ\n\nስምሽ በሁሉ ስለተወደደ\nድንግል ለክብርሽ ፍጥረት አረገደ\nካላመኑት ዘንድ ቢሆንም ዝምታ\nከገብርኤል ነው የስምሽ ሠላምታ\n\nሳደርስ ውዳሴ መፃፋን ገልጬ\nተመለከትኩሽ አይኔ እምባ እየረጨ\nበገናን ዳዊት መሰንቆንም እዝራ\nሰጡኝ ላነሳሽ በክብሩ ተራራ', 'am', 308, 0),\n(2, 'ታትመሻል', 'ታትመሻል\nታትመሻል በሰው ልቦና\nየደካሞች ምርኩዝ ነሽና\nላመስግንሽ በአዲስ ዝማሬ\nእመቤቴ ገና ነው ፍቅሬ\n\nየተፅናናንብሽ የድሆች ማረፊያ\nነፋስ ውቅያኖሱን ወጀቡን መቅዘፊያ\nወርሰናል ስምሽን ከወርቁ መዝገብ ላይ\nወለድሽልን ድንግል የሕይወትን ፀሐይ\n\nፅዮን ብለናል ነሽ መማፀኛችን\nሞትን አናይም ካለሽ እናታችን\n\nቀስተ ደመናዬ ሁነሽ ምልክቴ\nአለሁ እስከዛሬ ባንቺው በእመቤቴ\nልጅሽን አምኜ ምን ይጎልብኛል\nያስጨነቀኝ ሁሉ ይታዘዝልኛል\n\nተከቧል ተራራው በብሩህ ደመና\nየአብ ልጅ ክርስቶስ ባንቺ ወርዷልና\nይባቤ ምስጋና አፋችን ይመላ\nመቅደስ አላየሁም ድንግል ካንቺ ሌላ\n\nየከሳሼን ጉልበት ፅናቱን ሰብረሻል\nየአዳም ልጅ ከሲኦል ከሞት ወጥቶብሻል\nጣፈጣት ለነፍሴ የማህጸንሽ ፍሬ\nስጠራሽ እኖራለሁ በያሬድ ዝማሬ', 'am', 309, 0),\n(2, 'ለክብርሽ አለኝ ምስጋና', 'ለክብርሽ አለኝ ምስጋና\nለክብርሽ አለኝ ምስጋና\nከትውልድ አንዱ ነኝና\nሳልታክት የምዘምረው\nኪዳንሽ ስለረዳኝ ነው\n\nበሔዋን መተላለፍ መች ቀረው ምድረበዳ\nበልጅሽ ቤዛ መሆን አመለጥኩኝ ከፍዳ\nአልቀረም ከንቱ ሆኖ ነቢያት ትንቢታቸው\nተፈጽሟል ድንግል ሆይ መሰላል ሆነሻቸው\n\nየህይወት ውሃ ጠጣው ከማህጸንሽ መንጭቶ\nከድካም አሳረፈኝ መዳፎቹን ዘርግቶ\nበላይ በሰማያት ጫፍ ለከበርሽው እናቴ\nፀጋሽን ሊመሰክር ተፈቷል አንደበቴ\n\nወደ እኔ ስትመጪ ዘለልኩኝ በደስታ\nነፍሴን በሃሴት ሞላው የአንደበትሽ ሰላምታ\nአንቺ ከእኔ ጋር ካለሽ በአንዳች አልሰጋም\nቃል አለና በሆድሽ የሚሰጠኝ ሰላም\n\nማርያም ማርያም ስላልኩኝ አትሸበር ጠላቴ\nገና ከፍ ያደርጋታል ዜማዬና ቅኝቴ\nበኤልሳቤት ውዳሴ በገብርኤል ሰላምታ\nአንደበቴን ሳልሰስት አከብራታለው ገና', 'am', 310, 0),\n(2, 'የነገስታት ንጉስ', 'የነገስታት ንጉስ\nየነገስታት ንጉስ ፈጣሪን ወልደሽ\nእንዴትስ መመስገን ማርያም ይነስሽ\nዓለም ለማመስገን እውነቱ ቢከብደው\nእኛ ግን ስላንቺ ምንለው ብዙ ነው\n\nከሰማይ የመጣ የሚደነቅ ክብር\nሰማን ከገብርኤል ለአንቺ ሲነገር\nእውነቱን ለማወቅ አለም ምን ጋረደው\nየህይወቱን ምግብ ከማን ነው ያገኘው\nእኛ ስለገባን ፀጋና ክብርሽ\nእጅጉን አብዝተን ማርያም ወደድንሽ\nስለዚህ ማርያም ሆይ እንወድሻለን\n\nማንም ሰው ለእናቱ ክብር እንደሚሻ\nላንቺ ያለን ፍቅር የለው መጨረሻ\nስንዘምር ስንጠራሽ ዓለም ብዙ ቢለን\nየገባንን እውነት እንዲያይ ወደድን\nእኛ ስለገባን ፀጋና ክብርሽ\nእጅጉን አብዝተን ማርያም ወደድንሽ\nስለዚህ ማርያም ሆይ እንወድሻለን\n\nዝም የሚል አንደበት የለንም ለክብርሽ\nበደማችን ስርጾአል ስምሽና ፍቅርሽ\nፀሐይን ስላየ ዓለም ደስ ካለው\nአንቺን ለማመስገን ስለምን ከበደው\nእኛ ስለገባን ፀጋና ክብርሽ\nእጅጉን አብዝተን ማርያም ወደድንሽ\nስለዚህ ማርያም ሆይ እንወድሻለን\n\nከቶ በሰው ልማድ ፍፁም ያላየነው\nእናት ሆኖ ድንግል አንቺን ነው ያየነው\nገና ብዙ ብዙ ብዙ ቃላት አለን\nአንቺን ከማመስገን ማነው የሚያስተወን\nእኛ ስለገባን ፀጋና ክብርሽ\nእጅጉን አብዝተን ማርያም ወደድንሽ\nስለዚህ ማርያም ሆይ እንወድሻለን', 'am', 312, 0),\n(2, 'ምልክቴ ነሽ', 'ምልክቴ ነሽ\nምልክቴ ነሽ ድንግል ለህይወቴ\nበአንቺ ተፈታሁ ከእስራቴ\nቀና ብያለሁ አሁን ልጅሽ\nፀጋሽ ጎብኝቶኝ ቃልኪዳንሽ\n\nተስፋ ያረኩት አልተበተነም\nእንባዬ መሬት ከቶ አልወደቀም\nለበጎ ሆነ ማልቀስ ማንባቴ\nሰላም ሰፈነ በእልፍኝ በቤቴ\n\nቅኔ ነጠኩኝ የአባ ጊዮርጊስን\nማህሌት ቆምኩኝ የሕርያቆስን\nየያሬድ ዜማ ሞላ በልቤ\nየለም ወጀቡ ቀርባኝ መርከቤ\n\nወገቤን ታጠኩ ጭንቀቴን ጥየ\nዛሬስ በደስታ ይፍሰስ እንባየ\nየሀዘን ልብሴን ድንግል ቀይራ\nየደበዘዘው ህይወቴ በራ\n\nአራራይ ዜማ ዛሬ ተማርኩኝ\nፍቅሯ አሸነፈኝ እጄን ሰጠሁኝ\nቅኔ በልቤ ተመላለሰ\nየድንግል ክብር ውስጤ ነገሰ\n\nየዘረጋሁት እጄ ተሞላ\nማርያም ሆናልኝ ጥላ ከለላ\nየውስጤ ፀሎት ዛሬ ሌላ ነው\nየድንግል ክብር ምልጃው ቀየረው\n\nዛሬ ጎጆየ አንጸባረቀች\nያማረ ስንፔር ዕንቁ መሰለች\nቀንዴ ከፍ ከፍ አለልኝና\nሰዋሁ ለድንግል ይህን ምስጋና', 'am', 313, 0),\n(2, 'በቃለ ስብሐት', 'በቃለ ስብሐት\nበቃለ ስብሐት\nማርያም በቃለ ስብሐት\n\nባአባቶችሽ ፈንታ ልጆች ተወልደናል\nምስጋናን ከቅዱስ ገብርኤል ተምረናል\nውዳሴሽ ቅዳሴሽ ዘውትር በአፋችን ነው\nበመአልት በሌሊት የማናስታጉለው\n\nሰራዊተ መላእክት ያመሰግኑሻል\nየቅዱሳን ሕብረት አንቺን ይከቡሻል\nየለም የሚፈፅም ክብርሽን ተናግሮ\nአይችልም አንደበት ጸጋሽን ዘርዝሮ\n\nአንውልም አናድርም ስምሽን ሳንጠራ\nበደስታም በስደት ሆነን በመከራ\nየተፈወስንብሽ ከኃጢአት ቁስል\nለዘላለም ንጽሕት ለዘላለም ድንግል\n\nሰላም ለኪ ድንግል ጣዕመ ዝማሬአችን\nከአምላካችን ጋር መግባቢያ ቋንቋችን\nየያዕቆብ መሰላል የመድኃኒት ሙዳይ\nምስጋና ይድረስሽ እሙ ላዶናይ', 'am', 314, 0),\n(2, 'ከሊባኖስ', 'ከሊባኖስ\nሐና እና ኢያቄም ወለዱ ሰማይ\nአዲሷም ሰማይ አስገኘች ፀሐይ\nምስራቀ ምስራቃት የአምላክ መገኛ\nከሊባኖስ ድንግል ነይ ወደኛ\n\nተጨነቀ አዳም በመከራ\nበእርግማን ቀን ለቅሶ እየዘራ\nበልጅሽ ሞት ዓለም ተቀደሰ\nየፍጥረቱ ዕንባ በመስቀል ታበሰ\n\nየሕያዋን እናታቸው ሆነሽ\nለቀደመች ሔዋን ጠበቃ ሆንሽ\nደስተኛዋ ደስ ይበልሽ ማርያም\nከአንቺ ወጣ የዓለሙ ሰላም\n\nጽኑ ገመድ በአንቺ ተቆረጠ\nየፍዳ ዓመት ይኸው ተለወጠ\nበሐና ልጅ በኢያቄም ፍሬ\nደስታ ሆነ ቅኔ እና ዝማሬ\n\nበወለዱሽ በሐና በኢያቄም\nተማጽነናል ድንግል ማርያም\nከአዳኝ ወጥመድ ከክፉ ጠላት\nልጆችሽን ጠብቂን ከጥፋት\nኢትዮጵያን ጠብቂያት ከጥፋት', 'am', 315, 0),\n(2, 'ብፅዕት ናት', 'ብፅዕት ናት\nየእግዚአብሔርን ቃል ይሁን ብላ\nየተቀበለች በገሊላ\nያመነች ብፅዕት ናት ያመነች\nድንግል ማርያም ድንቅ ነች\n\nበገነት በዲያብሎስ ምክር\nትዕዛዙን ሔዋን ባታከብር\nማርያም የዓለሙ ቤዛ\nአየናት ቃሉን ታዝዛ\n\nይደረግ ይሁን ብሉ ያለ\nከእርሷ ታዛዥ የታለ\nመላኩ ሲያበስራት በክብር\nባርያው ነኝ አለች ለእግዚአብሔር\n\nፍሬዋን ብትሰጠን ቆርጣ\nበእኛ ላይ እርግማን መጣ\nማርያም ግን ፌሬ ወልዳልን\nቀንበሩ ተሰበረልን\n\nየቀደመች እናታችን\nሔዋን ባትሰማ ቃሉን\nየእግዚአብሔር ቃል ያመነች\nዳግማዊት ሔዋን ማርያም ነች', 'am', 316, 0),\n(2, 'አደራሽን ማርያም', 'አደራሽን ማርያም\nአደራሽን ማርያም አደራ እመቤቴ\nየመስቀሉን ፍቅር ሳይው በህይወቴ\nይፋቅ በጣቶችሽ የጥፋቱ ስሜ\nካንቺ ጋራ ልኑር በቀረኝ እድሜዬ\n\nልኑር ክርስትናን ማውራት ይብቃኝና\nወደፊት ልራመድ አንቺ አበርችኝና\nበፀሀይሽ ብርሀን በመቅረዝሽ ፋና\nይቃና መንገዴ የእምነቴ ጎዳና\n\nከቀራኒዮ መልስ ሆነሽኛል ተስፋ\nልጅሽ ሆኜ ልኑር ከደጅሽ ሳልጠፋ\nካንቺ ወቶ መራብ አይሁን በህይወቴ\nከእቅፍሽ አታውጭኝ ድንግል እመቤቴ\n\nልታወቅ በስምሽ በዓለም ተረስቼ\nበሰገነት ላውራሽ ለክብርሽ ቀንቼ\nማይረጌ ነሽና በድል ሰብክሻለው\nበማህፀንሽ ፍሬ ከሞት ወጥቻለው\n\nበጎስቋላው ልቤ በክብር ተፃፊ\nየስቃዬን ባህር በምልጃሽ ቅዘፊ\nወዳንቺ ላንጋጥጥ ሀዛኔ እንዲጠፋ\nቀስተ ደመናዬ የመዳኔ ተስፋ', 'am', 317, 0),\n(2, 'ኪዳነ ምሕረት የረፍቴ እናት', 'ኪዳነ ምሕረት የረፍቴ እናት\nኪዳነ ምህረት የዕረፍቴ እናት\nሰላም ሆነ ባንች አማላጅነት\nንፅህት ድንኳን በእምነት ያጌጥኩብሽ\nሰላም ሆነ በአማኑኤል ልጅሽ\n\nየብርሀን ዝናር ባይኖረኝም\nበንጉስ ፊት ተሸልም ብቆም\nበልጅሽ ነው ውበቴ ማማሩ\nበምልጃሽ ነው ስሜ መቀየሩ\nበልቤ ላይ ተነበበ ልጅሽ\nአሁን ስሜ ተጠርቷል በልጅሽ\nከታች በምድር እስከሰማይ ድረስ\nድርሻየ ነው ስምሽን ማወደስ\n\nየከበረ ሁነሽ ንግግሬ\nቅኔ አነሳሁ ለክብርሽ ዘማሬ\nእንደ ዝግባ ከፍ ብየ ብታይ\nወጥቶልኝ ነው በሰማይ ፀሀይ\nስለ ምልጃሽ ዘይቱ ፈሰሰ\nአንቺን ይዤ ሙሽራው ደረሰ\nቀንዲሌ ነሽ ድንግል አዛኝቱ\nበልጅሽ ነው የነፍሴ ፅናቱ\n\nከኤልያብ ቢደምቅ ደም ግባቴ\nማን ሊመርጠኝ ያላንች እናቴ\nተዋብኩብሽ ገፄ በአንች አበራ\nአንደበቴ ስምሽን ሲጠራ\nእንደ ሙሴ እንደ አሮን በትር\nማምለጫየ ከፈርዖን ቀንበር\nከእንግዲማ እኔ እንዴት አዝናለሁ\nአማላጀ አንችን ይዠሻለሁ', 'am', 318, 0),\n(2, 'እንወድሻለን ኪዳነምህረት', 'እንወድሻለን ኪዳነምህረት\nለእግዚአብሔር ታቦቱ መቅደሱ\nቀርበናል ባንቺ ወደ ንጉሡ\nየክብራችን ጌጥ ሽልማት\nእንወድሻለን ኪዳነምህረት\n\nበጨለማው ላላ ብርሀንን አየ\nለርስቱ ተካፋይ እንዲሆን ተለየ\nወደ ቀድሞ ክብሩ ሊመለስ ዳግመኛ\nአንቺ ነበርሽ ተስፋው ለአዳም መዳኛ\n\nያንሁሉ ዘመናት የፈሰሰው ደም\nአለምን ከእስራት ሊፈታ አልቻለም\nወደ ሚሻል ኪዳን በደም ሊያሻግረን\nደምሽን ተዋሕዶ መድሃኒዓለም ዋጀን\n\nአለን ብዙ ምክንያት አንችን ምንወድበት\nአለም ያልተረዳው ያላወቀው እውነት\nያወቀ የተረዳ የመዳኑን ምስጢር\nአያፍርም ክብርሽን ቆሞ ለመናገር\n\nአውቃለሁ እግዚአብሔር የሰጠሽን ክብር\nላመስግንሽ እኔም ሳልቀንስ ሳልጨምር\nሚባርክሽ ብሩክ ነውና እናቴ\nኪዳነምህረት ንገሽ እመቤቴ', 'am', 319, 0),\n(2, 'ከመስቀሉ ስር ነው', 'ከመስቀሉ ስር ነው\nከመስቀሉ ስር ነው አድራሻዬ\nእናቴን ልቀበል ከጌታዬ\nሀዘኔን እንድረሳው ጭንቀቴን\nአማኑኤል ሰጠኝ መጽናኛዬን\n\nእርሷ ባለችበት ጌታ ደግሞ አለ\nየእናቱን ምልጃ እየተቀበለ\nበክንዶቿ ታቅፎ ታዝሏል በጀርባዋ\nእርሱ ይታረቃል ስለ ልመናዋ\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል\n\nቀራንዬ የሄደ መስቀሉ ስር ያለ\nከማይቀበሉት ካይሁድ የተለየ\nታላቃን ስጦታ ከርሱ ይቀበላል\nማርያም ንፅይት ድንግል ሳአሊለነ ይላል\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል\n\nበተጋድሎ አይደለም በብዙ ትሩፋት\nበብርታት አይደለም በእውቀትም ብዛት\nምታስፈልገኝን የሰጠኝ ጌታ ነው\nክብሯን መናገሬ ለራሴም ክብር ነው\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል\n\nእናታችን ጽዮን ሰው ሁሉ ይላታል\nልኡል መስርቷታል ሰው ተወልዶባታል\nጌታዬ ኢየሱስን አምላኬ ነው ያላለ\nእናቱ እንድትሆነው እርሱ መች ታደለ\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል', 'am', 322, 0),\n(3, 'ድረስ ሚካኤል', 'ድረስ ሚካኤል\nድረስ ሚካኤል አፅናኝ\nድረስ ሚካኤል አፅናኝ\nተስፋ እንዳል ቆርጥ እርዳኝ\nየቤትህ አገልጋይ ባለሟል ነኝ\n\nድረስ ሚካኤል በግራም በቀኝ\nድረስ ሚካኤል ፈታኜ መብዛቱ\nድረስ ሚካኤል ስምህን ስጠራ\nድረስ ሚካኤል ሁሉም ሆነ ከንቱ\nድረስ ሚካኤል ብንገዳገድ እንኳን\nድረስ ሚካኤል የሚደግፈኝ\nድረስ ሚካኤል የማከብረው መልአከ\nድረስ ሚካኤል ጎኔ ቆመልኝ\n\nድረስ ሚካኤል የግብፅ አስማተኞች\nድረስ ሚካኤል በፊቴ ሲቆሙ\nድረስ ሚካኤል አድነኝ ሚካኤል\nድረስ ሚካኤል ስልህ ተገረሙ\nድረስ ሚካኤል እንደ አፎሚያ\nድረስ ሚካኤል ስዕልህን ባሳያቸው\nድረስ ሚካኤል በዙሪያዬ የቆሙት\nድረስ ሚካኤል ዳግም አጣኋቸው\n\nድረስ ሚካኤል ተመኖርያው ስፍራ\nድረስ ሚካኤል ከእዮር ከራማ\nድረስ ሚካኤል በረረ መጣልኝ\nድረስ ሚካኤል ሀዘኔን ሲሰማ\nድረስ ሚካኤል ምስጋና ይድረሰው\nድረስ ሚካኤል የአምላክ ባለሟል\nድረስ ሚካኤል ከደንቃራ ነገር\nድረስ ሚካኤል ሰወረኝ እኔን', 'am', 1, 0),\n(3, 'ሊረዳኝ መጣ ሀያል ሚካኤል', 'ሊረዳኝ መጣ ሀያል ሚካኤል\nሊረዳኝ መጣ ሀያል ሚካኤል\nይጠብቀኛል ሀያል ቅዱስ ሚካኤል\n\nየሙሴ ጠባቂ ሀያል ሚካኤል\nመንገድ የመራኸው ሀያል ቅዱስ ሚካኤል\nየኤርትራን ባህር ሀያል ሚካኤል\nከፍለኸ ያሻገርከው ሀያል ቅዱስ ሚካኤል\n\nክብርህ ከመላእክት ሀያል ሚካኤል\nከፍ ከፍ ያለ ነው ሀያል ቅዱስ ሚካኤል\nታላቁ አለቃ ሀያል ሚካኤል\nከቶ እንዳተ ማነው ሀያል ቅዱስ ሚካኤል\n\nበሐጢያት በረሀ ሀያል ሚካኤል\nመጠለያ ሆነን ሀያል ቅዱስ ሚካኤል\nጠላት በመንገድ ላይ ሀያል ሚካኤል\nእንዳያሳፍረን ሀያል ቅዱስ ሚካኤል', 'am', 2, 0),\n(3, 'በሰማይ ሰልፍ ሆነ', 'በሰማይ ሰልፍ ሆነ\nበሰማይ ሰልፍ ሆነ በመላእክት ስፍራ\nሚካኤል ተዋጋ ከሳጥናኤል ጋራ\nየቀደመውን እባብ ዘንዶውን ተጣለ\nክብርን ተመኝቶ አምላክ ነኝ ስላለ\n\nየክደቱን መዝገብ በፊቱ ገልብጦ\nአጠፋው በክንዱ ሚካኤል አቅልጦ\nአምላክ ነኝ ያለበት አደበቴ ተዘጋ\nየአምላክ ስም አለበት ጦር ስለተወጋ\n\nከሰማይ ተሰማ የውጊያ ግርግታ\nቅዱስ ሚካኤል ነው ዘንዶውን ስመታ\nሳጥናኤል ተጥሎ ሰላም ነግሷልና\nለሚካኤል አምላክ ይድረሰው ምስጋና\n\nከዙፋኑ ወርዷል ከሳሽ ክብሩ የለም\nከሚካኤል ጋራ መቋቋም አልቻለም\nበክደት ፈራርሶ የነበረው ስልጣን\nጨለማንም ለብሶ ወቷል ከብርሃን\n\nየእግዚአብሔር ስም ያለው በጥር ተሸክሞ\nለሰው የሚማልድ በአምላኩ ፊት ቆሞ\nከዙፋኑ ጣለው ዘንዶውን አሰረው\nየመላእክት አለቃ ሚካኤል ክብረው', 'am', 3, 0),\n(3, 'ገብርኤል ገብርኤል ስለው ሰምቶ', 'ገብርኤል ገብርኤል ስለው ሰምቶ\nገብርኤል ገብርኤል ስለው ሰምቶ\nመጣ ወደኔ ፈጥኖ\nሰንሰለቴን በጠሰው የአንበሶቹን አፍ ዘግቶ\n\nገብርኤል ስጋዬ ሳይረግፍ በአንበሶቹ ጥፍር\nገብርኤል ታድጎኛል ምልጃው የመላኩ ፍቅር\nገብርኤል በረሓብ ለነደዱ ኣናብስት ሲጥሉኝ\nገብርኤል አንተ አለኽኝና ክንፎችህ ከለሉኝ\n\nገብርኤል ከአፎቱ ሲመዘዝ የጠላቴ ሰይፍ\nገብርኤል አጽንቶ ይዦኛል ፍሬዬ ሳይረግፍ\nገብርኤል አደገድጋለሁ አለኝና ፍቅሩ\nገብርኤል በእሳት ክንፍ ታጥረዋል የደጄ ድንበሩ\n\nገብርኤል አለው ልዩ ስልጣን ከአምላክ የተሰጠው\nገብርኤል ይመጣል ወደኛ እሳቱን ሊያጠፋው\nገብርኤል እኛም እናምናለን ሰምተናል አይተናል\nገብርኤል የመላእክት አለቃ ከአምላክ ያማልዳል\n\nገብርኤል ስጋዬ ሳይረግፍ በአንበሶቹ ጥፍር\nገብርኤል ታድጎኛል ምልጃው የመላኩ ፍቅር\nገብርኤል በረሃብ ለነደዱ አናብስት ሲጥሉኝ\nገብርኤል አንተ አለኽኝና ክንፍችህ ከለሉኝ', 'am', 4, 0),\n(3, 'ባሕራንኒ ይቤ', 'ባሕራንኒ ይቤ\nባሕራንኒ ይቤ\nባሕራንኒ ይቤ እሆ ዘነገደ ባህር\nርኢክዎ ለሚካኤል ወሰዕንኩ ጠይቆቶ ዘይብ ባሕራንኒ ይቤ\nባሕራንኒ ባሕራንኒ ይቤ ባሕራንኒ\n\nየሞቱን ደብዳቤ ባሕራንኒ\nሚካኤል አጥፍቶ ባሕራንኒ\nባሕራን አዳነው ባሕራንኒ\nበሠርግ ተክቶ ባሕራንኒ\nሠዳዴ ሳጥናኤል ባሕራንኒ\nሊቀመላእክት ባሕራንኒ\nእኛንም አድነን ባሕራንኒ\nከሲዖል እስራት ባሕራንኒ\n\nከሊቀ ነቢያት ባሕራንኒ\nከነሙሴ ጋራ ባሕራንኒ\nሕዝበ እስራኤልን ባሕራንኒ\nሚካኤል ሲመራ ባሕራንኒ\nቀን ደመና ጥሎ ባሕራንኒ\nሌሊት እያበራ ባሕራንኒ\nተሻገሩ ኤርትራን ባሕራንኒ\nሁሉም በየተራ ባሕራንኒ', 'am', 5, 0),\n(3, 'ገብርኤል ነው አምላክ የሾመው', 'ገብርኤል ነው አምላክ የሾመው\nገብርኤል ነው አምላክ የሾመው\nገብርኤል ነው አምላክ የሾመው\nአናንያን አዛሪያን ሚሳኤልን ከእሳት ያደው\n\nናቡከደነፆር አንተን በግልፅ አይቶ\nለእግዚአብሔር ሰገደ ያንን ምስል ትቶ\nሃሰት እንደሆን ይመስክሩ ሶስቱ\nከዚያች ከባቢሎን የወጡ ከእሳቱ\nከዚያች ከባቢሎን የወጡ ከእሳቱ\n\nከአለም በላይ ከቅዱሱ ቦታ\nየሰውን ልጅ መረጥክ ልትረዳ ጠዋት ማታ\nአንጌቤናይቷ ቅድስትዬን ይዤ ልውጣ\nትመስክር ስላንተ ከነልጇ ትምጣ\nትመስክር ስላንተ ከነልጇ ትምጣ\n\nልመስክር ስላንተ ነህና ህይወቴ\nገብርኤል ሰመረ ስለቴ\nገብርኤል ሰመረ ስለቴ\nያአናብስትን አፍ የዘገሀው መላክት\nገብርኤል አንተ ነህ በኛ ሁሉ የታመንክ\nገብርኤል አንተ ነህ በኛ ሁሉ የታመንክ', 'am', 6, 0),\n(3, 'የአፎምያ እረዳት ነህ', 'የአፎምያ እረዳት ነህ\nየአፎምያ እረዳት ነህ ሚካኤል\nቅሩበ እግዚአብሔር የልዑል\nፈጥነህ ድረስልኝ\nስንጠራ ሚካኤል\n\nፊት ለፊታችን አምላክ ሰደደህ\nአቅናልን መንገድን ጠርገህ\nየቤልሆርን ምክር አፍርሰክ\nከልጆችክ ጋር ከነአን ደርሰክ\n\nከኛ ጋር ነበርክ አርባውን ዘመን\nእንጠረሀለን ሚካኤል ብለን\nበቃዴስ ክንፍ ተዘርግቶልናል\nደመናው ባንተ ተጋረደልን\nአብረህ እንድትሆን ጌታ የላከህ\nአንተ ሚካኤል ታዳጊያችን ነክ\n\nሙሴ ሲለየን ደጉ አባታችን\nሚካኤል ነበርክ ከላይ መሪያችን\nየባርነቱ ጉዞ እስኪያበቃ\nእጅግ እረዳን የኛ ጠበቃ\n\nሳጥናኤል መክሮን የሀሰት ምክር\nሊወስደን ሻተ ሙሴ መቃብር\nስለ ማይጠቅመን አንተ ሰበርከው\nምክሩን በታትነክ አስጎነበስከው', 'am', 7, 0),\n(3, 'እልፍ አእላፋት', 'እልፍ አእላፋት\nእልፍ አእላፋት ወት እልፊት\nቅዱሳን ንፁሀን መላእክት\nቁሙ ላገልግሎት ፀንተው በአንድነት\nቅዱስ ቅዱስ ቅዱስ አምላክ በማለት\n\nእዬር ራማ ኤረር የመላእክት ሀገር\nየሐይማኖት የፍቅር የምልዕክት ክብር\nእውነት የታየባት የመላዕክት ሀገር\n\nእንፅና ሲል ገብርኤል ባለንበት ቦታ\nበሳጥናኤል ነገድ ነበረ ሁካታ\nግማሹ እየካደ ቀሪው ሲያመነታ\n\nየሳጥናኤል ምኞት እንደ አበባ እረግፎ\nሚካኤል ተሾመ በእምነት ተደግፎ\nሳጥናኤል ወደቀ ፀጋው ተገፎ\n\nቅዱሳን መላዕክት በእምነት የፀናችሁ\nበታላቅ አክብሮት ሰላም ልበላችሁ\nስግደት ዘበ ፀጋ እንሰግድላችሁ', 'am', 8, 0),\n(3, 'ሚካኤል ሐመልማለ ወርቅ', 'ሚካኤል ሐመልማለ ወርቅ\nሚካኤል ሐመልማለ ወርቅ\nልብሱ ዘመብረቅ\nአመልማለ ወርቅ የወርቅ ልምላሜ\nአመልማለ ወርቅ የወርቅ ልምላሜ\nናናና ስለምንህ ቆሜ\n\nገብርኤል ሊቀ መላዕክት\nገብርኤል ሊቀ መላዕክት\nሰለስቱ ደቂቅን ያወጣ ከእሳት\nሰለስቱ ደቂቅን ናብ ከደነፃር ተቆጣ\nእሳቱ ነደደ ነበልባሉ ወጣ\nሃያሉ ገብርኤል ሊያድናቸው መጣ\nለሰለስቱ ደቂቅ ለባርኮ ለእግዚአብሔር\nሰብኡኒ ውእቱ ልዑልኒ ውእቱ ብለው\nምስጋናን አቀረብ ከእሳቱ ላይ ሆነው\n\nሩፋኤል ሊቀ መላዕክት\nሩፋኤል ሊቀ መላዕክት\nአሳ አንባሬውን ወጋው በኩየት\nአሳ አንባሪው ይቀትልዋ በበትረ መስቀል\nፈጥኖ ደረሰና መላከ ሰላም\nአፀናት በደሴት ቤተ ክርስቲያንን\n\nኡራኤል ሊቀ መላዕክት\nኡራኤል ሊቀ መላዕክት\nለዕዝራ ያጠጣ ፅዋ ህይወት\nበአለም ፈተና በስቃይ ኩነኔ\nስባዝን ስጨነቅ ሲንከራተት አይኔ\nኡራኤል የኔ ሀይል ቁምልኝ ከጎኔ\nራጉኤል ሊቀመላእክት\nራጉኤል ሊቀመላእክት\nዕመ በላይነ ወረደ\nዕመ በላይነ ወረደ\nመላከ ብርሀናት አሶሳዊ ፋና\nራጎኤል ናናና ራጎኤል ናናና ራጎኤል ናናና\nአማላጅ ነህና', 'am', 9, 0),\n(3, 'ምድር በራች ሚካኤል ሲመጣ', 'ምድር በራች ሚካኤል ሲመጣ\nምድር በራች ሚካኤል ሲመጣ\nገናና ነው አሰሙት እልልታ\nሚካኤል ሚካኤል የአምላክ ባለሟል\n\nክንፉን ሲዘረጋ ውሀ ተናወጠ\nበክብር ሲገለጥ ነገር ተለወጠ\nበፍቅሩ ተዳሰው ድውያን ዘለሉ\nየሚካኤል አምላክ ይባረክ እያሉ\n\nብርሀን የሚተፉት ግሩማን አይኖቹ\nበፍቅር ያዩናል ዘውትር ሳይሰለቹ\nሲቀድም ሲመራ ተከፍሏል ባህሩ\nከርሱ ጋር የወጡ ሞትን ተሻገሩ\n\nአለሁ ብዙ ዘመን ዝናህን ስሰማ\nበፋርስም አንተው ነህ በግብፅም ከተማ\nወጥቼ አልቀረሁም ከአገር ተሰድጄ\nዳግም አርፌአለሁ ባንተ በወዳጄ\n\nየዳቢሎስ ዙፋን ተገልብጧል በእርሱ\nጠላት ሚደቅበት መብረቅ ነው ቀሚሱ\nቆሟል ዙፋኑ ፊት ምህረት እየጠና\nያደረገው ተአምር መቼ ተነካና\n\nክንፉን ሲዘረጋ ውሀ ተናወጠ\nበክብር ሲገለጥ ነገር ተለወጠ\nበፍቅሩ ተዳሰው ድውያን ዘለሉ\nየሚካኤል አምላክ ያባረክ እያሉ', 'am', 10, 0),\n(3, 'ሚካኤል ነው', 'ሚካኤል ነው\nበበረሀ በሀሩሩ\nበሚያስፈራው በባህሩ\nእስራኤልን የታደገ\nበክንፎቹ የጋረደው ሚካኤል ነው\n\nሚካኤል ነው አፅናኝ ደጋፊዬ\nሚካኤል ነው በድር በበረሀ\nሚካኤል ነው ነፍሴ ያረካልኝ\nሚካኤል ነው ከአለቱ ውሀ\nየፊቴ ፈገግታ የውስጤ ፍስሀ\nከአምላክ የተሰጠኝ በረከት አምሀ\n\nሚካኤል ነው መብረቅ ያወረደው\nሚካኤል ነው ጠላት ድል የነሳው\nሚካኤል ነው የባህራን ወዳጅ\nሚካኤል ነው ሀዘኑን ያስረሳው\nቤቱን የሰራለት በእግሮቹ ያቆመው\nእንደ እናት እንደ አባት ደግሶ የረዳው\n\nሚካኤል ነው ያሳደገኝ መላዕክ\nሚካኤል ነው በፍቅር የመራኝ\nሚካኤል ነው ስደክም የያዘኝ\nሚካኤል ነው ስወድቅ ያነሳኝ\nበነገሬ ሁሉ የቀደመልኝ\nሚካኤል እሱ ነው ከጥልቅ ያወጣኝ\n\nሚካኤል ነው ክሴን የቀደደው\nሚካኤል ነው የበደሌን እዳ\nሚካኤል ነው በአማላጅነቱ\nሚካኤል ነው ያዳነኝ ከፍዳ\nበመንገዴ ሁሉ እኔን እየረዳ\nፍቅሩን ፅፎት አልፏል በልቤ ሰለዳ', 'am', 11, 0),\n(3, 'ዛሬ ነግሬው', 'ዛሬ ነግሬው\nዛሬ ነግሬው ሳያሳድር\nመልስ የሆነልኝ ሚካኤል\nአወድስሻለው በዝማሬ\nሞገስ ሆኖልኛል እስከ ዛሬ\n\nማን እንደእግዚአብሔር ነው የዎህነት ግብሩ\nተገልጾል ከቤቴ የሚካኤል ክብሩ\nከመላዕክት ወገን እኔን ይረዳኝ ዘንድ\nተልኳል ሚካኤል ሊያድነኝ ከወጥመድ\n\nሰይፍህ መዘህ ቁሚ ሚካኤል ተገለጥ\nከፊቴ የቆመው ጠላቴ ይደንግጥ\nችግር የሚገባህ ልመናን የምትሰማ\nአለህ ከልጆች የመወደድ ግርማ\n\nከፊቴ ሺ መድቋል ከኃላዬ መቶ\nሚካኤል ሲመጣ ድምጹን አሰምቶ\nጉዞዬ ሳይከፋ ሳይጠፋ መውጪያዬ\nነደ እሳት ሚካኤል ሆነኝ ከለላዬ\n\nሰባውን ዘመናት እግዚአብሔር ሲቆጣ\nሚካኤል ደረሰ ሊያማልደን መጣ\nነበልባል እሳት ልብሱ ብርሀናዊ\nሚካኤል ወዳጄ ፍሰሀ ዜናዊ', 'am', 12, 0),\n(3, 'ቅዱሳን', 'ቅዱሳን\nቅዱሳን መላእክት ቆሙ ለምስጋና\nእንዳንተ ያለ የለም እና\nቅዱሳን መላእክት ቆሙ ለምስጋና\n\nክብር ሀያል ድንቅ ጌታ\nበክብር ያለ በደስታ\nበታላቅ ቃል ይጮሀሉ\nአሸናፊነህ እያሉ\nአርምሞ ስርአት በሌለበት\nከበው ቆመዋል ከፀባኦት\nበፊት ሰግደው በትትና\nሀሌ ሉያ አሉ ለምስጋና\nየመላ በምድር በሰማይ\nለአምላክ ለጌታ ለአዶናይ\nፈጥረህ ሁሉን የምትገዛ\nለስምህ ውዳሴ ይብዛ\n\nጌታ ባለ በቅድምና\nምግብ ሆኗቸው ምስጋና\nስምህ በክንፎቻቸው ነው\nአንተን ማክበር ግብራቸው ነው\n\nንፁ ንፁ ክብር ልዩ\nብለው ፍቅርህን እያዩ\nስብአት ላንተ በአርያም\nአሉ በምድር ሰላም', 'am', 13, 0),\n(3, 'ቅዱስ ሚካኤል ፈጥኖ ደረሰልኝ', 'ቅዱስ ሚካኤል ፈጥኖ ደረሰልኝ\nቅዱስ ሚካኤል ፈጥኖ ደረሰልኝ\nኦ ከሳሼን ረግጦ አዋረደልኝ\nክንፉን ቀጥ አድርጐ ዙሪያየን ሰፈረ\nየጠላቴን መንገድ ወጥመድ ሰባበረ\nየጠላቴን መንገድ ወጥመድ ሰባበረ\n\nሌጌዎን መከረኝ በሐሰት እንድቆም\nሊያሳየኝ ፈልጐ የሙሴን መቃብር\nአይጠቅመኝምና ሰወረዉ ሚካኤል\nፈርቶ ተመልሷል ተዋርዶ ሳጥናኤል\nፈርቶ ተመልሷል ተዋርዶ ሳጥናኤል\n\nጽድቅን አስተማረኝ ሀጢአትን ሳበዛ\nነፍሴ እንዳትኮነን በበረት ተይዛ\nወደ ህይወት መንገድ ይዞ እየመሪኝ\nየመዳኔን አሪስ ጌታን አሳየኝ\nየመዳኔን አሪስ ጌታን አሳየኝ\n\nከታናሽነቴ ተግቶ የጠበቀኝ\nከአጋንንት እስራት ሞልጃ የታደገኝ\nዛሬም አለ ጐኔ በጐልማሳነቴ\nየልቤ ብርሀን ነው ሚካኤል አባቴ\nየልቤ ብርሀን ነው ሚካኤል አባቴ\n\nፀጋዬ እንዳይጐድል ጠላት እንዳይረግመኝ\nተራዳኢው መልአክ ከፊቴ ቆመልኝ\nበአህያ አንደበት ነቢዩን ገሰፀው\nእብደቱን አግቶ ከመንገድ መለሰው\nእብደቱን አግቶ ከመንገድ መለሰው', 'am', 14, 0),\n(3, 'ሊቀ መላዕክት', 'ሊቀ መላዕክት\nሊቀ መላእክት ከእግዚአብሔር ታዞ\nገብርኤል መጣ ምህረቱን ይዞ\nድህነትን ሊሰጥ ለሰው ልጅ ሁሉ\nዘምሩለት እልል በሉ ስሙንም ጥሩ ገብርኤል በሉ\n\nአናፍርም ስሙንም ጠርተነው ገብርኤል\nፈጣን ነው ታምሩ ሲያደርስልን\nበኃያልነቱ ድንቅ ይሰራል\nየከሳሻችን ምክር ይደረምሳል\n\nብርቱ ነው ጉልበቱ የተሰጠው\nልጆቹን ሊጠብቅ የተሾመው\nእሳት ውሀ አድርጎ ይለውጣል\nያመነበት ሳይሞት ተጎብኝቷል\n\nፀሐይ ይጋርዳል በደመና\nጎበኘን በምልጃው ሰማንና\nአጥሯል በነበልባሉ ዙሪያችንን\nየሚደፍረው የለም ቅጥራችንን\n\nበቀንና ሌሊት ወዶ መራን\nየሚያረጋጋንን ድምፁን ሰማን\nጠላት እንዳይከተል መራራ ዘር\nሳይተወን ተጓዘ ባዕድ ሀገር', 'am', 15, 0),\n(3, 'ዑራኤል ከበረ', 'ዑራኤል ከበረ\nኡራኤል ከበረ እሰይ እሰይ\nሊቀ መላእክት የአምላክ አገልጋይ\nሊቀ መላእክት የአምላክ አገልጋይ\n\nከእመቤታችን ጋር ዑራኤል\nአብረህ የተሰደድክ\nወደ ኢትዮጵያ\nይዘህ የመጣህ\nየጌታ ባለሟል\nኡራኤል አንተነ\n\nየጌታ ባለሟል ዑራኤል\nታማኝወታደር\nታማኝወታደር\nይኸው አማልዶኛል\nከቸሩ እግዚአብሔር\n\nበአንድ ሀሳብ ተስማሙ ዑራኤል\nለአንድ ልቦናቸው\nለአንድ ልቦናቸው\nፍቅርና ምረትን\nእርሱ ያብዛላቸው\n\nአልፈልግም ሀኪም ዑራኤል\nአልፈልግም ሀኪም ዑራኤል\nምን ያረግልኛል\nምን ያረግልኛል\nበኡራኤል ፀበል\nልቦናዬ በርቷል', 'am', 16, 0),\n(3, 'እሩሩ መልአክ', 'እሩሩ መልአክ\nእሩሩ መልአክ ነህና ለሁሉ የምትራራ\nእሩሩ መልአክ ነህና ለሁሉ የምትራራ\nገብርኤል አዛኙ አንተ አውጣኝ ከመከራ\n\nየሚያሳድዱኝን ገብርኤል ሲቆም ከፊቴ\nጋሻ ይሆነኛል ጠባቂ አባቴ\nእሳት ነበልባል ሀይለ መለኮት\nስም ሲጠራ ፈጥነ ትመጣለ\n\nበራማ የምትኖር ገብርኤል የመላክት አለቃ\nአብሳሪመላክ ነህ ለኛዋስ ጠባቂ\nቂርቆስ እና እናቱን አንተ አዳንካቸው\nከእግዚአብሔር ተልከ ከሞት ሰወርካቸው\n\nለነ ሚሳኤልገብርኤል ለነ ሀናንያ\nእረዳት ሆንካቸው ለነ አዛርያ\nለኛ መድሀኒት ነህ በእምነት ለለመነ\nሁሉም ተደርጎልህ ለአማላጅነት', 'am', 17, 0),\n(3, 'ዑራኤል ደረሰ', 'ዑራኤል ደረሰ\nዑራኤል ደረሰ መጣ እረዳቴ\nዑራኤል ደረሰ መጣ እረዳቴ\nያሰብኩት ተሳካ ደረሰ ስለቴ\nያሰብኩት ተሳካ ደረሰ ስለቴ\n\nኡራኤል ደረሰ በአለም ፈተና\nጀዌ ፀንቶ ብኝ\nየጠፋችውን ነፍሴን\nሰላም ሊሰጠን\nየአምላክ ባለሟል\nየምረት አባት\nእረፍትን ሰቶኛል\nመራዬ ድነት\n\nኡራኤል ደረሰ ታላቅ ስልጣን ያለህ\nበጌታ መንበር ፊት\nአድነኝ ኡራኤል\nጎብኘኝ በበረከት\nበስምህ ተማፅኖ\nበታምራትህ\nምረት ታሰጣለህ\nመላከ ሰላም\n\nኡራኤል ደረሰ የሀጥያት ቀንበር\nሲከብደኝ ስጨነቅ\nምኞት ሲበዛብኝ\nፈተና ሲያሳምመኝ\nበጨለማ እንዳልወድቅ\nየመላክት አለቃ\nአንተው ብርታት ሁነኝ', 'am', 18, 0),\n(3, 'ተስፋ ስቆርጥ', 'ተስፋ ስቆርጥ\nተስፋ ስቆርጥ እንድን ፀና\nቅዱስ ሚካኤል ድረስ ቶሎና\nቅዱስ ሚካኤል ድረስ ቶሎና\nድረስል ፈጥነህ ድረስልን\nድረስል ፈጥነህ ድረስልን\n\nከራማ ከኢዮር ከኤረር ከተማ\nሚካኤል ይደርሳል ጭንቀቴን ሲሰማ\nታዘህ ከጌታዬ መንገዴን ስትመራ\nባስመርርህ ታገስ ሚካኤል አደራ\n\nጨለማ አጋንንት አይቀርበንም ከቶ\nሚካኤል ሲጠራ ይበተናል ፈርቶ\nበቀኝ የሚቆም ከሱራፌል ጋራ\nሊያድነኝ ፈጠነ ኤኔን ከመከራ\n\nኃይሉ በእኔ ሆነ ጎልያድ ወደቀ\nየጠላት ፋከራ ከእግሬ ስር ደቀቀ\nሚካኤል ሲረዳኝ አይቻለሁና\nእኔን የታደገኝ ይድረሰው ምስጋና', 'am', 19, 0),\n(3, 'እረድተሃልና', 'እረድተሃልና\nእረድተሃልና ባህራንን ሚካኤል\nበብቁሃልና ቴዎብስታን ሚካኤል\nአስታርቀን አማልደን ሚካኤል\n\nከሰማያት ስትወርድ ሚካኤል\nለሰው ልጆች ልትራራ ሚካኤል\nከክብርህ ያተሳ ሚካኤል\nመላው ምድር አበራ ሚካኤል\nበመከራዬ ጊዜ ሚካኤል\nፈጥነህ የደረስክልኝ ሚካኤል\nአምላከ ተክልዬ ሚካኤል\nቅየገላገልከኝ ሚካኤል\n\nአልተረዳሁትም ሚካኤል\nበእጄ ያለውን ሚካኤል\nየሞቴን ደብዳቤ ሚካኤል\nየሸሸኩትን ሚካኤል\nልጨብጥ ስጣደፍ ሚካኤል\nየሰይፍን ስለት ሚካኤል\nየመላእክት አለቃ ሚካኤል\nአዳነኝ ከሞት ሚካኤል\n\nገና ህፃን ሳለው ሚካኤል\nአሳድገኸኛል ሚካኤል\nበብዙ ፈተና ሚካኤል\nአንተ አድነኸኛል ሚካኤል\nአሁንም ጠብቀኝ ሚካኤል\nቸል አትበለኝ ሚካኤል\nአባቴ ሚካኤል ሚካኤል\nልጄ ሆይ በለኝ ሚካኤል', 'am', 20, 0),\n(3, 'ኦ ቅዱስ ሚካኤልs', 'ኦ ቅዱስ ሚካኤልs\nሚካኤል በአምላኩ በእግዚአብሔር ፊት ቆሟል\nለተጨነቀች ነፍስ ምህረት ይለምናል\nጨለማው እንዲሸሽ እንዲሆን ብርሃን\nኦ ቅዱስ ሚካኤል ሰዓለነ እንበል\nኦ ቅዱስ ሚካኤል ሰዓለነ እንበል\n\nእረቂቁ መላዕክ መብረቅ ተጎናጽፏል\nለሰማይ ሰራዊት አለቃቸው ሆኗል\nየምክሩ አበጋዝ ስሙ የተፈራ\nእሱ ነው ሚካኤል ለሕዝቡ የሚራራ\nእሱ ነው ሚካኤል ለሕዝቡ የሚራራ\n\nእግዚአብሔር ኃይሉን የሚገልፅበት\nፀሎት የሚያሳርግ የሚያሰጥ ምህረት\nስለ ትህትናው ከአምላክ የተሾመው\nቅሩበ እግዚአብሔር ቅዱስ ሚካኤል ነው\nቅሩበ እግዚአብሔር ቅዱስ ሚካኤል ነው\n\nእርህሩ ነው እና የነፍሳችን ወዳጅ\nለፍጥረቱ ሁሉ የታመነ አማላጅ\nከቅጥረ ፀሎቱ ነፍሳችን ትጠጋ\nተግቶ እንዲጠብቀን ሲመሽም ሲነጋ\nተግቶ እንዲጠብቀን ሲመሽም ሲነጋ\n\nየነፀብራቅ ዝናር ሚካኤል ታጠቀ\nበቅድመ እግዚአብሔር ሕዝቡን አስታረቀ\nበእሳታዊው አክናፍ ከክፉ ጋረደ\nልጆቹን ሊባርክ ሚካኤል ወረደ\nልጆቹን ሊባርክ ሚካኤል ወረደ', 'am', 21, 0),\n(3, 'ብዙ ልጆች አሉት', 'ብዙ ልጆች አሉት\nብዙ ልጆች አሉት ለሥሙ ምሥክር\nበዙሪያው ያሉትን አብቅቷል ለክብር\nስለ ፍጹም ምልጃው ለእኔ ግን ይለያል\nመልዓኩ ሚካኤል ስለው ደስ ይለኛል\n\nከመላዕክት ክብሩ ከፍ ከፍ ብሎ\nበአምላኬ ተሾመ ዘንዶውንም ጥሎ\nአሳዳጊዬነው ሆኖ እናት አባቴ\nሚካኤል በአለበት ይሸሻል ጠላቴ\n\nከሚታየው ሁሉ ልቤ ከሚፈራው\nካላየሁት ነገር ጠላት ከሰወረው\nያድነኛል ፈጥኖ በመንገዴ ወቶ\nሚካኤል ሀያሉ ክንፎቹን ዘርግቶ\n\nበባሕራን ታሪክ በነተላፊኖስ\nበአፎምያ መትረፍ በነ ዱራታኦስ\nበነብዩ ዳንኤል መች ይፈጸምና\nየሚካኤል ስራ ይቀጥላል ገና\n\nበጉዞ የረዳችሁ በባሕር በየብሱ\nፈጥኖ ደርሶላችሁ ዕንባን ስታፈሱ\nስለታችሁ ሰምሯል ቁሙ ለዝማሬ\nበሚካኤል ምልጃ የቆማችሁ ዛሬ\n\nክብር ለሚገባው ክብርን እንሰጣለን\nንጉሥ ለወደደው አንሰግድለታለን\nእንኳን ለሚካኤል ለሚቆም ጌታ ፊት\nክብርን እንሰጥ የለ ለምድር ሹማምንት', 'am', 22, 0),\n(3, 'መና አውርዶ', 'መና አውርዶ\nመና አውርዶ እሳት አብርዶ\nሚካኤል መራን ደመና ጋርዶ\n\nነፀብራቃዊዉ ሚካኤል\nአምደ ብርሃን ሚካኤል\nነፃ ያወጣ ሚካኤል\nህዝበ እስራኤልን ሚካኤል\nሌሊቱን ብርሃን እያደረክ\nምራን እኛንም ወደ አምላክ\n\nእሩሩ መላዕክ ሚካኤል\nያፎምያ አባት ሚካኤል\nፈጥነህ የምደርስ ሚካኤል\nበጭንቀት ላሉ ሚካኤል\nጠላት ዳቢሎስ እንዳይጥለን\nቅዱስ ሚካኤል አትለየን\n\nየሚቃወሙን ሚካኤል\nበእሱ እራቁልን ሚካኤል\nጠላቶቻችን ሚካኤል\nተሸነፉልን ሚካኤል\nየማንችለውን እያስቻለን\nለዚህ አበቃን እየረዳን\n\nወደ ሞት ሲሄድ ሚካኤል\nደብዳቤ ይዞ ሚካኤል\nደጉ ባህራን ሚካኤል\nከንጉስ ታዞ ሚካኤል\nቅዱስ ሚካኤል በረድሄት\nሞቱን በህይወት ለወጠለት', 'am', 23, 0),\n(3, 'በሲና በረሀ', 'በሲና በረሀ\nበሲና በረሀ ያወረደው መና\nየእስራኤል መሪ በአምለ ደ\nመና የመላክት አለቃ ሚካኤል ነውና\n\nየምረት መላክ ቅዱስ ሚካኤል\nየምረት መላክ ቅዱስ ሚካኤል\nፈጥኖ ይደርሳል ያማልደናል\nበስጋም በነፍስ ይታደገናል\nበስጋም በነፍስ ይታደገናል\n\nደኔልን ካናብስት በህራንን ከሞት\nቅድስት አፎሚያን ቀሰይጣን ያዳ\nንካት እኛንም አድነነ መለአከምረት\nየምረት መላክ ቅዱስ ሚካኤል\nየምረት መላክ ቅዱስ ሚካኤል\nፈጥኖ ይደርሳል ያማልደናል\nበስጋም በነፍስ ይታደገናል\nበስጋም በነፍስ ይታደገናል\n\nክብሩ ታላቅነው ድንቅ ነው ስሙ\nማን እደግዛብሄር መላከምክሩ\nሚካኤል የድናል ድንቅነው ታምሩ\nየምረት መላክ ቅዱስ ሚካኤል\nየምረት መላክ ቅዱስ ሚካኤል\nፈጥኖ ይደርሳል ያማልደናል\nበስጋም በነፍስ ይታደገናል\nበስጋም በነፍስ ይታደገናል\n\nተራዳይነቱን መፀሀፍ መስክራል\nስለህዝቡ ልጆች ሚካኤል ይቆማል\nምረትን የሚያሰጥ ኪዳን ተቀብሎል\nየምረት መላክ ቅዱስ ሚካኤል\nየምረት መላክ ቅዱስ ሚካኤል\nፈጥኖ ይደርሳል ያማልደናል\nበስጋም በነፍስ ይታደገናል\nበስጋም በነፍስ ይታደገናል\n\nበመታሰብያው ቀን ይነበብ ድርሳኑ\nዝክሩን እናዘከር ይከበር በአሉ\nሚካኤል ያድናል ምንጃው ቃልኪዳኑ\nየምረት መላክ ቅዱስ ሚካኤል\nየምረት መላክ ቅዱስ ሚካኤል\nፈጥኖ ይደርሳል ያማልደናል\nበስጋም በነፍስ ይታደገናል\nበስጋም በነፍስ ይታደገናል', 'am', 24, 0),\n(3, 'ሚካኤል ይላል አንደበቴ', 'ሚካኤል ይላል አንደበቴ\nሚካኤል ይላል አንደበቴ\nሚካኤል ይላል አንደበቴ\nስለፀና በስሙ ጉልበቴ\nታሪክ ሰርትዋል ያኔ በህይወቴ\n\nገና ህፃን ሳለው ታናሽ ብላቴና\nጠላቴ ብያበዛ የህይወቴን ፈተና\nበባህር በየብሱ ተበታተነልኝ\nከኔ ጋራ ያለው ለሞት አይሰጠኝም\n\nሞቴን የሰረዘ ህይወትን የፃፈ\nበክንፎቹ ጥላ ልጁን ያሰረፈ\nበልቤ ሰሌዳ ስሙን አትሚያለው\nበሄድኩበት ሁሉ ሚከኤል እላለው\n\nበባህዳን ሀገር ሞገስ የሆነኝ\nከፊቴ እየወጣ ሰልፉን የመራኝ\nቀስቱን እያጠፈ ከፊቴ እየጣለ\nበቆፈረው ጉርጓድ ገዳዩን ገደለ\n\nታሪክ ተቀየረ እንባይ ታበሰ\nፈርኦን ወደቀ ሀሞቱ ፈሰሰ\nያስተምረኝ ጀመር በገናን አሲዞ\nታላቁን ቀይ በህር በድል አሳልፎ', 'am', 25, 0),\n(3, 'ሚካኤል ይለይብኛል', 'ሚካኤል ይለይብኛል\nጠብቆ አሳድጎ ከልጅነቴ\nአባት እየሆነኝ ሚካኤል አባቴ\nይለይብኛል ሚካኤል ይለይብኛል\nበክንፉ ሸፍኖ በቤቱ አሳድጎኛል\nበክንፉ ሸፍኖ በቤቱ አሳድጎኛል\n\nአያምርብኝ ብዘነጋው ታሪኬን\nሚካኤል ነው ያስጌጠልኝ ህይወቴን\nአረሳብኝ እርሱ አትርሳብኝ ያልኩትን\nለካስ ሰምቶኝ ኖሯል የልጅነት ጸሎቴን\n\nሚካኤል ያን ሁሉ ዘመን የታገሰኝ\nሚካኤል ፍሬ ጠብቆ ያልቆረጠኝ\nሚካኤል የከፍታዬ መሰላል\nሚካኤል መነሻዬ ሆነሀል\n\nእንዳይከፋኝ እንዳልደፋ አንገቴን\nእንዳላለቅስ እንዳለፈስ እንባዬን\nእንዳይርቀኝ ደስታ በመንፈሴ እንዳልዝል\nካጠገቤ አይርቅም ያሳደገኝ ሚካኤል\n\nሚካኤል ቀኔም ቀን አይሆን ሳልጠራህ\nሚካኤል ና ድረስልኝ ሳልልህ\nሚካኤል እንዳስጀመርከኝ ጅማሬዬን\nሚካኤል አሳምረው ፍፃሜዬን\n\nውድቅ አረገው የጠላቴ ክፉ እቅድ\nአራመደኝ በከፍታዬ መንገድ\nሊያስቀረኝ አልቻለም ሊጎትተኝ ባላጋራ\nተጥሎ ስላለ በእግዚአብሔር ድንቅ ስራ\n\nሚካኤል እሳታዊ ነው ነበልባል\nሚካኤል ጠላቴ ፊትህ ይቀልጣል\nሚካኤል ለኔ አይኔ ነው መከታዬ\nሚካኤል የዘለዓለም ጠባቂዬ', 'am', 26, 0),\n(3, 'መልአከ ራማ', 'መልአከ ራማ\nገብርኤል ገብርኤል ሀያል መልአከ ራማ\nገብርኤል ገብርኤል ሀያል መልአከ ራማ\nንዓ ንዓ ድምፅህን ልስማ\nንዓ ንዓ ድምፅህን ልስማ\n\nበምርኮ ሳለው በባቢሎን\nምን ይሆን ብዬ ስፈራ ነገን\nእየበረረ መጣ ገብርኤል\nደስታን ሊያሰማኝ ታዞ ከልዑል\n\nናቡከደነፆር ቢቆጣ\nአዲስ የሞት አዋጅ ቢያወጣ\nስዘምር አየኝ ሳወድስ\nነበልባሉንም አድርጓልኝ መቅደስ\n\nየመጥምቁን ልደት መስካሪ\nየአምላክን ሰው መሆን አብሳሪ\nየምስራች መልአክ የደስታ\nከአምላክ ፊት የምትቆም ጠዋትና ማታ\n\nዳንኤልም ፀና በቃልህ\nቀርበህ ስትዳስሰው በእጆችህ\nጥበብ አድለኝ ማስተዋል\nመጋቢ ሀዲስ ቅዱስ ገብርኤል', 'am', 27, 0),\n(3, 'አብሠራ ገብርኤል', 'አብሠራ ገብርኤል\nአብሠራ ገብርኤል ለማርያም\nወይቤላ ትወልዲ ወልድ\nወይቤላ ትወልዲ ወልድ\n\nሚካኤል መልዐክ በክነፍ ፆራ\nመንጦላዕት ደመና ሠወራ\nንፅህት በድንግልና አልባቲ ሙስና\nተወልደ ወልድ እምኔሐ\n\n(ትርጉም:\nገብርኤል ማርያምን አበሰራት\nወንድ ልጅም ትወልጃለሺ አላት\nሚካኤል መልዐክ በክንፉ ከለላት\nየሰማይ መጋረጃዉ ሸፈናት\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና)\n\nአዳም በጥፋቱ ከገነት ሲባረር\nበሚካኤል ክንፎች ቀድሞ አይቶሽ ነበር\nሔዋንን ሲጠራት ሕይወቴ ነሽ አላት\nእንደሚድን አውቆ ድንግል በአንች ምክንያት\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና\n\nእግዚአብሔር የላከው የከበረው መልዐክ\nድንግል ሆይ ለክብርሽ ዐየን ሲንበረከክ\nበፍቅር በትህትና በፍፁም ሰላምታ\nየጌታ ሰው መሆን የነገረሽ በደስታ\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና\n\nደስተኛዬቷ ሆይ ደስ ይበልሽ ድንግል\nየአብ ቃል ክርስቶስ ሥጋሽን ይለብሳል\nአንቺም ትይዋለሽ ስሙን እየሱስ\nመድኃኒት ነውና ለሥጋ ወነፍስ\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና\n\nአንደ ኒቆዲሞስ ሳትከራከሪ\nአንደ ዘካርያስ ሳትጠራጠሪ\nይሁነኒ ብለሽ ቃልን ተቀበልሽ\nከፍጥረቱ ማነው አንቺ የሚመስልሽ\nንፅህት ናትና በድንግልና\nጥፋት የለባትምና ወንድ ልጅም ወልዳልናለችና', 'am', 28, 0),\n(3, 'ሀያል ነህ አንተ', 'ሀያል ነህ አንተ\nሀያል ነህ አንተ ሀያል\nደጉ መልአክ ገብርኤል\nይውደቅ ይሸነፍ ጠላት\nአንተ ተራዳን በእውነት።\n\nበዱራ ሜዳ ላይ ገብርኤል\nጣኦት ተዘጋጅቶ ገብርኤል\nሊያመልኩት ወደዱ ገብርኤል\nአዲስ አዋጅ ወጥቶ ገብርኤል\nሲድራቅ እና ሚሳቅ አብደናጎ ፀኑ፤\nጣኦቱን እረግጠው በእግዚያብሄር አመኑ።\n\nተቆጣ ንጉሱ ገብርኤል\nበሶስቱ ህፃናት ገብርኤል\nጨምሯቸው አለ ገብርኤል\nወደ እቶን እሳት ገብርኤል\nከሰማይ ተልኮ ወረደ መላኩ፤\nከሞት አዳናቸው በሳት ሳይነኩ።\n\nከእቶኑ ስር ሆነው ገብርኤል\nዝማሬ ተሞሉ ገብርኤል\nገፍተው የጣሏቸው ገብርኤል\nበእሳቱ ሲበሉ ገብርኤል\nአልተቃጠለችም የራሳቸው ፀጉር፤\nአዩ መኩአንንቱ የእግዚአብሄርን ክብር።\n\nናቡከደነፆር ገብርኤል\nእጁን ባፉ ጫነ ገብርኤል\nሰለስቱ ደቂቅን ገብርኤል\nከእሳት ስለአዳነ ገብርኤል\nይክበር ጌታ አለ የላከ መላኩን፤\nሊአመልከው ወደደ ስላየ ማዳኑን', 'am', 29, 0),\n(3, 'ገብርኤል ኃያል', 'ገብርኤል ኃያል\nገብርኤል ኃያል መልዐከ ሰላም መልዐከ ብስራት\nየምታወጣ የእግዚአብሔርን ህዝብ ከሚነድ እሳት\nፍቅርህ ተስሉዋል በልባችን\nፊትህ ቆመናል ባርከን ብለን\n\nየፅናታቸው ዝናው ሲሰማ\nከዚያች ቢያብሎን ከሞት ከተማ\nህፃናት ሳሉ በራ እምነታቸው\nቁመህ ተገኘህ መሀከላቸው\n\nውሀው ሲዘልል ቢያስደነግጥም\nበጋኖቹም ውስጥ ቢነዋወጥም\nፀንተው ዘመሩ ልጅና እናቱ\nአንተ ስትደርስ ከዚያ ከሳቱ\n\nቂርቆስም ፀና ሞትን ሳይፈራ\nአንተ ስላለህ ከነርሱ ጋራ\nአትፍሪ አላት ስለምን ትፍራ\nአምነው ድል ነሱት ያንን መከራ\n\nእኔም አምናለው አድነኝ ብዬ\nቆመህ አማልደኝ ከቸር ጌታዬ\nክፉውን ዘመን የማልፍበት\nፅናትን ስጠኝ ድል ልንሳበት', 'am', 30, 0),\n(3, 'ገብርኤል', 'ገብርኤል\n\nገብርኤል\nገብርኤል\nገብርኤል መልአከ ራማ\nገብርኤል መልአከ ራማ\nስንጠራህ ፈጥነህ ድረስ\nድምጽህን እንስማ\n\nትንቢቱ ሲፈጸም ዘመኑ ሲያበቃ\nከቀናት ሳትዘግይ ሳይጎድል ደቂቃ\nወደ ድንግል መጥተህ ደስታን አበሰርክ\nየአምላክን ሰውን መሆን ለአለሙ ሰበክ\nየአምላክን ሰውን መሆን ለአለሙ ሰበክ\n\nከውኃ እና ከሳት ከሞት አመለጡ\nበእሳቱ መካከል ለጥፋት ቢሰጡ\nአንተ ባለህበት በየትኛውም ስፍራ\nምንም ቦታ የለውም ሞትና መከራ\nምንም ቦታ የለውም ሞትና መከራ\n\nየመንገድ መሪ ፈውስ ነህ ለህመሜ\nገብርኤል ስትመጣ በዛልኝ ሰላሜ\nደስታን አብሳሪ ተሸክመህ ዜና\nዛሬም ለአገራችን ምስራች ይዘህ ና\nዛሬም ለአገራችን ምስራች ይዘህ ና\n\nአንጌቤናይቱ ቅድስት እየሉጣ\nስለአንተ ትመስክር እስከ ልጇ ትምጣ\nእሳተ ነህ ገብርኤል ነባልባልባ አስወጋጅ\nየአምላክ መወለድ ለአለም ምታውጅ\nየአምላክ መወለድ ለአለም ምታውጅ', 'am', 31, 0),\n(3, 'ናና ሚካኤል ናና', 'ናና ሚካኤል ናና\nናና ሚካኤል ናና\nናና ሚካኤል ናና\nአዝኛለሁ እና በአንተ ልጽናና\nናና ሚካኤል ናና\n\nየረዳህ አፎምያን ሚካኤል ናና\nሰይጣን ሲፈትናት ሚካኤል ናና\nአንተነህ ያዳንከው ሚካኤል ናና\nባሕራንን ከሞት ሚካኤል ናና\nለእነርሱ እንደመጣህ ሚካኤል ናና\nእኔንም ተራዳኝ ሚካኤል ናና\nሚካኤል ደግፈህ ሚካኤል ናና\nለመንግሥቱ አብቃኝ ሚካኤል ናና\nናና ሚካኤል ናና\nናና ሚካኤል ናና\nአዝኛለሁ እና በአንተ ልጽናና\n\nናና ገብርኤል ናና\nናና ገብርኤል ናና\nአዝኛለሁ እና በአንተ ልጽናና\nናና ገብርኤል ናና\n\nዘመኑ ሲፈፀም ገብርኤል ናና\nአምላክ መምጫው ሲደርስ ገብርኤል ናና\nገብርኤል አንተ ነህ ገብርኤል ናና\nያልካት ደስ ይበልሽ ገብርኤል ናና\nድምጽህን አሰማኝ ገብርኤል ናና\nነፍሴ ጽድቅን ትልበስ ገብርኤል ናና\nአዝኛለሁ እና በአንተ ልጽናና\nናና ገብርኤል ናና\n\nናና ዑራኤል ናና\nናና ዑራኤል ናና\nአዝኛለሁ እና በአንተ ልጽናና\nናና ዑራኤል ናና\n\nቆመህ ጽዋ ይዘህ ዑራኤል ናና\nለእዝራ ሱቱኤል ዑራኤል ናና\nጥበብ አጠጥተህ ዑራኤል ናና\nዕውቀት ስታድል ዑራኤል ናና\nተገለጠ ክብርህ ዑራኤል ናና\nመልአኩ ዑራኤል ዑራኤል ናና\nድኜ በፀበልህ ዑራኤል ናና\nበአውደ ምህረትህ ላይ ዑራኤል ናና\nእኔም ዘመርኩልህ ዑራኤል ናና\nአዝኛለሁ እና በአንተ ልጽናና\nናና ዑራኤል ናና', 'am', 32, 0),\n(3, 'መራሔ ብርሐን', 'መራሔ ብርሐን\n\nመራሔ ብርሐን ረድዔትኽ የበዛ\nወደ ግብጽ ሥትሄድ ድንግል ልጅዋን ይዛ\nአብረኽ የተራዳኽ መልዓከ ልዑል\nየእግዚአብሔር አገልጋይ ቅዱሥ ዑራኤል\n\nአበው ሠብዓ ሠገል ዑራዔል\nከምሥራቅ ሲመጡ ዑራዔል\nኮኮቡን የመራኽ ዑራዔል\nዓምሐ እንዲሠጡ ዑራዔል\nሕይወቴን አቅናልኝ ዑራዔል\nከሐጢዓት አውጣና ዑራዔል\nበብርሐን ምራኝ አጽድቅ ጎዳና\n\nፈጥነኽ የምትደርስ ዑራዔል\nሥምኽን ለጠራ ዑራዔል\nጽዋዕ ልቦና ዑራዔል\nያጠጣኽ ለዕዝራ ዑራዔል\nጥበብ መንፈሣዊ ዑራዔል\nበውስጤ እንዲዘራ ዑራዔል\nብርሐናዊው መልዓክ ልቦናዬን አብራ\n\nለሔኖክ የገለጥኽ ዑራዔል\nየረቀቀን ምሥጢር ዑራዔል\nበገጸ ሠማይ ላይ ዑራዔል\nየፊደላት ቁጥር ዑራዔል\nማሥተዋል አግኝቼ ዑራዔል\nበፍቅር እንድሞላ ዑራዔል\nምልጃኽ አይለየኝ ይሁነኝ ከለላ\n\nአምላክ ሥለ ሠው ልጅ ዑራዔል\nቀራንዮ ሢሰዋ ዑራዔል\nደመ መለኮቱ ዑራዔል\nበብርሐን ጽዋ ዑራዔል\nተቀብለኽ ረጭተኽ ዑራዔል\nዓለምን የቀደስኽ ዑራኤል', 'am', 33, 0),\n(3, 'ገብርኤል መልዓክ', 'ገብርኤል መልዓክ\nገብርኤል መልዓክ ተጨንቃለች ነፍሴ\nበል ማልደኽ አሥታርቀኝ በቅመ ሥላሴ\nገብርኤል መልዓክ ተጨንቃለች ነፍሴ\nበል አማልደኽ አሥታርቀኝ በቅድመ ሥላሴ\n\nገብርኤል መልዓክ ከእሣት የሚያወጣ\nገብርኤል መልዓክ ዕምነት ባይኖረኝ\nገብርኤል መልዓክ የጌታ ባርያ ነኝ\nገብርኤል መልዓክ ፈጥነኽ አድነኝ\nገብርኤል መልዓክ ፈታኜ ብዙ ነው\nገብርኤል መልአክ የነፍሴ ጠላት\nገብርኤል መልዓክ ክንፍኽ ይሸፍነኝ\nገብርኤል መልዓክ በቀን በሌሊት\n\nገብርኤል መልዓክ ማን አፍሮ ይሄዳል\nገብርኤል መልዓክ አምኖ በሥላሴ\nገብርኤል መልዓክ አምላኬ እግዚአብሔር ነው\nገብርኤል መልዓክ ዋሥ ሁናት ለነፍሴ\nገብርኤል መልዓክ በጥቂት በበዙ\nገብርኤል መልዓክ ማዳን ይቻልሃል\nገብርኤል መልዓክ የተፍለቀለቀን\nገብርኤል መልዓክ ውሐን አብርደሃል\n\nገብርኤል መልዓክ ኢየሉጣም ትምጣ\nገብርኤል መልዓክ ማዳንኽን ታውራ\nገብርኤል መልዓክ ቂርቆስም ይናገር\nገብርኤል መልዓክ የአንተን ድንቅ ሥራ\nገብርኤል መልዓክ ነገሥታት ተገርመው\nገብርኤል መልዓክ አፋቸውን ያዙ\nገብርኤል መልዓክ ገብርኤል አንተ ነኽ\nገብርኤል መልዓክ ተዐምራተ ብዙ', 'am', 34, 0),\n(3, 'ስለቴን ሰማ ፈጥኖ ከራማ', 'ስለቴን ሰማ ፈጥኖ ከራማ\nስለቴን ሰማ ፈጥኖ ከራማ\nየአምላክ ባለሞል ቅዱስ ገብርኤል\n\nቅዱስ ገብርኤል መጣከሰማይ\nቅዱስ ገብርኤል እኔን ሊራዳ\nቅዱስ ገብርኤል ከነበልባሉ\nቅዱስ ገብርኤል ክንዱን ከነዳ\nቅዱስ ገብርኤል እሳት ሳይነካው\nቅዱስ ገብርኤል ፅናፊላችን\nቅዱስ ገብርኤል መላኩ ቆመ\nቅዱስ ገብርኤል ከመሀላችን\n\nቅዱስ ገብርኤል ተመችቶናል\nቅዱስ ገብርኤል ማበል እሳቱ\nቅዱስ ገብርኤል ቅኔን ተቀኘን\nቅዱስ ገብርኤል ቆመን በፊቱ\nቅዱስ ገብርኤል ከቁጥር በዛን\nቅዱስ ገብርኤል ሰፋን በጌታ\nቅዱስ ገብርኤል በሞት ውስጥ ሆነን\nቅዱስ ገብርኤል ዘመርን ለጌታ\n\nቅዱስ ገብርኤል ንጉስ ቢያቆምም\nቅዱስ ገብርኤል ከዱራ መሀል\nቅዱስ ገብርኤል ሰማይ ተከፍቶ\nቅዱስ ገብርኤል እሳት ቢነድም\nቅዱስ ገብርኤል ከቶም አናስብ\nቅዱስ ገብርኤል በሰው ልጅ ስራ\nቅዱስ ገብርኤል ያማልክት አምላክ\nቅዱስ ገብርኤል ነው ከኛጋራ\n\nቅዱስ ገብርኤል ህፃኑ ቂርቆስ\nቅዱስ ገብርኤል ከናቱ ጋራ\nቅዱስ ገብርኤል ቢደርስባቸው\nቅዱስ ገብርኤል ፅኑ መከራ\nቅዱስ ገብርኤል በእግዚአብሔር ማዳን\nቅዱስ ገብርኤል ስለታመኑ\nቅዱስ ገብርኤል ገብርኤል ተልኮ\nቅዱስ ገብርኤል ከሳቱ ዳኑ', 'am', 35, 0),\n(3, 'ምድር አበራች', 'ምድር አበራች\nከመልአኩ ክብር የተነሳ ምድር አበራች\nከመልአኩ ክብር የተነሳ ምድር አበራች\nፀጋውና ክብሩ ሆኗት የምስራች\nሃያል ሃያል ከመላእክት ክብሩ የገነነ\nሊረዳኝ የመጣው ቅዱስ ሚካኤል ነው\n\nሲደግፈኝ ክንዱ በዘመኔ\nምልጃው ሲጠብቀኝ እያለፈ ቀኔ\nእየመራኝ በብርሃኑ ፋና\nሚካኤል መንገዴን አቀና\nዐይኑ ዘርግብ ዐይኑ\nኦ ሚካኤል ታየ በብርሃኑ\nሲማልድ ሲማጸን በፊቱ\nእግዚአብሔር አየን በምህረቱ\n\nእያጽናናኝ ፍጹም ከድካሜ\nስጠራው ተፈወስኩ ዳንኩኝ ከህመሜ\nሊመግበኝ ለተራብኩት መና\nደረሰልኝ ሚካኤል ገናና\nዐይኑ ዘርግብ ዐይኑ\nኦ ሚካኤል ታየ በብርሃኑ\nሲማልድ ሲማጸን በፊቱ\nእግዚአብሔር አየን በምህረቱ\n\nያሻገረኝ መልአክ ሚካኤል ነው\nበምልጃው ይደርሳል ቀርቦ ለለመነው\nለነፍሴ ከለላ ሆኖላት\nአተረፈኝ ከዕደ ረበናት\nዐይኑ ዘርግብ ዐይኑ\nኦ ሚካኤል ታየ በብርሃኑ\nሲማልድ ሲማጸን በፊቱ\nእግዚአብሔር አየን በምህረቱ', 'am', 36, 0),\n(3, 'ዑራኤል አባት', 'ዑራኤል አባት\nሊቀ መልአክ ዑራኤል አባት\nፀበልህም ያድናል በእውነት\nበምልጃህም ያመኑ በሙሉ ባንተ ይድናሉ\n\nዑራኤል መልአክ ማዳንህን ሰምቼ\nዑራኤል መልአክ ስምህን ጠርቻለው\nዑራኤል መልአክ አላሳፈርከኝም\nዑራኤል መልአክ በአንተ ኮርቻለው\nዑራኤል መልአክ መንገዴ በአንተ ነው\nዑራኤል መልአክ የኔ መታመኛ\nእኔንም ጠብቀኝ ከኃጢአት ቁራኛ\n\nዑራኤል መልአክ ያንተ ድንቅ ሥራ\nዑራኤል መልአክ አይመረመርም\nዑራኤል መልአክ ድንቅ ነው ምህረትህ\nዑራኤል መልአክ ማዳንህ ዘላለም\nዑራኤል መልአክ ቸርነትህ ብዙ\nዑራኤል መልአክ ምልጃህም ፈጣን ነው\nፀጋህን ላክልን ለእኛ ለምናምነው\n\nዑራኤል መልአክ ለዕዝራ ሱቱኤል\nዑራኤል መልአክ ጥበብ እንዳጠጣህ\nዑራኤል መልአክ በጽዋህ ብርሃንህ\nዑራኤል መልአክ ደምን እንደረጨህ\nዑራኤል መልአክ ሠላምን ልታስገኝ\nዑራኤል መልአክ ዓለምን መዞርህ\nማዳንህ ተገልጿል በቅዱስ ጠበልህ', 'am', 37, 0),\n(3, 'ኦ_ሚካኤል', 'ኦ_ሚካኤል\nኦ ሚካኤል\nኦ ሚካኤል ሊቀ መላዕክት\nበኃጢአት እንዳንወድቅ እንዳንሞት\nፈጥነህ ተራዳን አጽናን በእውነት\n\nለያዕቆብ ነገድ ሚካኤል\nለእስራኤል ሚካኤል\nጠባቂያቸው ነህ ሚካኤል\nመልዓከ ኃይል ሚካኤል\nፍቅርን አድለን ምሕረት\nቅዱስ ሚካኤል የኛ አባት\nቅዱስ ሚካኤል የኛ አባት\n\nነጸብራቃዊ ሚካኤል\nተክህኖ ልብስ ሚካኤል\nሐመልማለ ወርቅ ሚካኤል\nዓይኑ ዘርግብ ሚካኤል\nፍቅርን አድለን ምሕረት\nቅዱስ ሚካኤል የኛ አባት\nቅዱስ ሚካኤል የኛ አባት\n\nበስዕልህ ፊት ሚካኤል\nእሰግዳለሁ ሚካኤል\nፈጥነህ አነጋግረኝ ሚካኤል\nአለሁ በለኝ ሚካኤል\nፍቅርን አድለን ምሕረት\nቅዱስ ሚካኤል የኛ አባት\nቅዱስ ሚካኤል የኛ አባት\n\nበክንፍህ ጥላ ሚካኤል\nተከልለናል ሚካኤል\nቅዱስ ሚካኤል ሚካኤል\nክፉን አልፈናል ሚካኤል\nፍቅርን አድለን ምሕረት\nቅዱስ ሚካኤል የኛ አባት\nቅዱስ ሚካኤል የኛ አባት\n\nቅሩበ እግዚአብሔር ሚካኤል\nታማኝ ባለሟል ሚካኤል\nደራሽ ሲጠሩህ ሚካኤል\nለታመኑህ ኃይል ሚካኤል\nፍቅርን አድለን ምሕረት\nቅዱስ ሚካኤል የኛ አባት\nቅዱስ ሚካኤል የኛ አባት', 'am', 38, 0),\n(3, 'ልጁ ነኝ', 'ልጁ ነኝ\nልጁ ነኝ የሚካኤል ልጁ\nበቤቱ ያደኩኝ በደጁ\nየልቤ ብዬ የምጠራው\nሚካኤል ለኔ አባቴ ነው\nየልቤ ብዬ የምጠራው\nሚካኤል አዎ አባቴ ነው\nበክንፎቹ እኔን በእጁ ሰይፍ ይዟል\nሚካኤል ሊረዳኝ ቆሟል\nእንዳስፈሪ እንደ ንጉሥ ሰራዊት\nበቀኜ ነው በቀንና በሌሊት\nሚካኤል አባቴ ለዚህ እኮ ነው መመካቴ\nሚካኤል አባቴ ጋሻ ክብሬ ነው ማለቴ\nሚካኤል አባቴ ጎኔ ቆመህ እንዳቆምከኝ\nሚካኤል አባቴ እኔ ለዓለም ምስክር ነኝ\n\nልናገር ላውራ ላዚም ልዘምር\nከፍ አርጌ ልመስክር\nመች ይረሳል ልጅነቴ ያሳደገኝ\nእቅፍ አርጎ በክንፎቹ የከለለኝ\nሚካኤል አባቴ እስከዛሬ ያላልኩትን\nሚካኤል አባቴ በልቤ ውስጥ ያኖርኩትን\nሚካኤል አባቴ ዛሬ ላውራው በአደባባይ\nሚካኤል አባቴ እረድቶኛል ከአባት በላይ\nከተኛሁበት ከእንቅልፌ አንቅቶ\nነጻ አወጣኝ እስሬን ፈቶ\nበጨለማ በወኅኒው ቤት በእስር\nአብሮኝ ነበር ጠባቂዬ ሚካኤል\nሚካኤል አባቴ በክፋ ቀን ያለ ጎኔ\nሚካኤል አባቴ ያልተለየኝ በድካሜ\nሚካኤል አባቴ ሰው የሚወድ የማይንቅ\nሚካኤል አባቴ በጌታ ፊት የሚያስታርቅ\n\nብርቱና ኃያል ጽኑ ነው ስሙ\nሚካኤል ሞገስ የሆነው\nምን ይሆናል ሚካኤልን የያዘ ሰው\nምግቡ መና ደመና ነው ሚጋርደው\nሚካኤል አባቴ የአባቶቼ መንገድ መሪ\nሚካኤል አባቴ በእኔም ሕይወት ተዓምር ሰሪ\nሚካኤል አባቴ በመንገዴ ቀድሞ ፊቴ\nሚካኤል አባቴ ይስበኛል ወደ ርስቴ', 'am', 39, 0),\n(3, 'ቅዱስ ሚካኤል ወዳጅ ነህ', 'ቅዱስ ሚካኤል ወዳጅ ነህ\nቅዱስ ሚካኤል ወዳጅ ነህ ለሁሉ\nዛሬም ቆመሀል በኪዳንህ ላሉ\n\nክንፍህን ዘርጋ ሚካኤል ቅደም ከፊቴ\nምራኝ መንገዱን እንዳይመሽ ልድረስ ካባቴ\nእንዴት ይገፋል ጎዳናው ካላንተ እርዳታ\nጥሜን ቁረጠው በበትርህ ጭንጫውን ምታው\n\nተጠመጠመ ጠላቴ በእሳት ሰንሰለት\nየጌታ መልአክ ሚካኤል በሰይፍ ወድቆበት\nየለም ከቦታው ስመለስ አጥቼዋለው\nየሚረዳኝን ተሹሞ አይቼዋለው\n\nከመቃብሩ ድንጋዩን አንከባለሀል\nስለረዳኸዉ ዳንኤል እጅግ ወዶሀል\nይነዋወፃል ባህሩ አንተ ስትመጣ\nእግዚአብሄር ይንገስ ዳቢሎስ መድረሻ ይጣ\n\nአለኝ ትዝታ በቤትህ ከልጅነቴ\nስትሳሳልኝ እያየው ፀንቷል ጉልበቴ\nልዘምር እንጂ ላመስግን ታላቁን ጌታ\nአንተን የሰጠኝ ጠባቂ በቀን በማታ', 'am', 40, 0),\n(3, 'የኛ አባት ሚካኤል', 'የኛ አባት ሚካኤል\nሲያርፍ ያመሰግናል ሲያመሰግን ያርፋል\nሲያርፍ ያመሰግናል ሲያመሰግን ያርፋል\nየኛ አባት ሚካኤል\nየኛ አባት ሚካኤል ምሕረት ይለምናል\n\nበቅድመ ሥላሴ በጉልበቱ ሰግዶ\nምስጋናን ያቀርባል የውዳሴን ነዶ\nምሕረትን ይዞ ከአምላክ ዘንድ ተላከ\nለማኑሄ ድርሳን ምስራች ሰበከ\n\nችግርን አልፋለሁ ይረሳል ሀዘኔ\nበሕይወቴ ሠልፎች ስላለ ከጎኔ\nከአምላኬ ተልኮ የታደገኝ ከሞት\nመርቶ ያደርሰኛል ከሠማዩ መንግስት\n\nየአምላክ ስም በላዩ ስላለ ታትሞ\nከፊቴ ይወጣል በመንገዴ ቀድሞ\nያድናል ሚካኤል ጭንቀትን አርቆ\nየወህኒውም መዝጊያ ይከፈታል አውቆ\n\nልጄ ነህ ብሎኛል አባቴ እለዋለሁ\nለአምላኬ ዘመርኩኝ ሲዘምር ስላየሁ\nአይደክምም ልሳኑ አያውቅም ዝምታ\nምስጋና ምግቡ ነው ዘውትር ጠዋት ማታ\n\nስለህዝቡ ልጆች የሚነሳው መልዓክ\nአንተነህ ሚካኤል የመረጠህ አምላክ\nዝማሬ ጸሎቴ አይሁንብኝ ከንቱ\nከእጣኑ ጢስ ጋር ይውጣልኝ በፊቱ', 'am', 41, 0),\n(3, 'ሚካኤል ስዩም', 'ሚካኤል ስዩም\nሚካኤል ስዩም\nሚካኤል ስዩም\nሚካኤል ስዩም ሊቀ መላእክት\nመዝገበ ርህራሄ\nመዝገበ ርህራሄ\nመዝገበ ርህራሄ ወየዋህ\n\nየደሀ አደጉን ልጅ ስለተቀበልከኝ\nበአውደ ምህረትህ በፍቅር አሳደከኝ\nከመቅደስ ተክለህ መገብከኝ ህይወት\nአዘጋጅተኸኛል ለሰማይ መንግስትህ\n\nበከንቱ እንዳልደክም ነብሴ እንዳትዝል\nትመግበኝ ነበር የህወትን ቃል\nወጣሁኝ ከአለም ተሰሎንቄን ረሣሁ\nመጠማቴ ቀረ የህይወት ውሀ ጠጣሁ\n\nመዳንን እንድወርስ ሞትን እንዳላይ\nትረዳኝ ነበረ ከኔ ሣትለይ\nበመንገዴ ሁሉ ከፊቴ ቀደምክ\nአማኑኤል ብዬ ጌታን እንዳመልክ\n\nምልጃህን ታምኜ ስኖር በመቅደስህ\nታሻግረኝ ነበር እጆቼን ይዘህ\nበጎልማሣ ነቴ ነህና ከጎኔ\nጉልበቴም አንተው ነህ በእርጅና ዘመኔ', 'am', 42, 0),\n(3, 'ሚካኤል ወረደ', 'ሚካኤል ወረደ\nሚካኤል ወረደ እኛም ከቤት ወጣን\nበአውደ ምህረቱ ቆሟል ሊባርከን\nበፊቱ ተቀኘን ቅኔን ስለክብሩ\nወጣት አዛውንቱ ህጻናት ዘምሩ\n\nሚካኤል ደምቀን እየኖርን በግብጽ አሸንክታብ\nሚካኤል ሞልቶልን አያውቅም የልባችን ሀሳብ\nሚካኤል ያስጎነበሰንን ነውር አንከባሎ\nሚካኤል ጠራን ለዝማሬ ከተኩላው አስጥሎ\n\nሚካኤል እጃችን ተባርኮ ለምለም ጎዘጎዘ\nሚካኤል ልባችን ለፍቅር ለሰላም ታዘዘ\nሚካኤል የድሃ አደጉን ልጅ በፍቅር የሚያሳድግ\nሚካኤል ከክፉ መከራ ከሞት የሚታደግ\n\nሚካኤል ከፊታችን የለም ጥቁር መጋረጃ\nሚካኤል ጎዳናው ቀናልን ቀድሞ የርሱ ምልጃ\nሚካኤል በኃጢያት ተይዘን ከደጁ ብንመጣ\nሚካኤል ኑ ልጆቼ ብሎ ሊቀበለን ወጣ\n\nሚካኤል ተግተን ስንጠብቀው ዘርግተን ምንጣፉን\nሚካኤል ወደኛ ፈጠነ ሊመራልን ሰልፉን\nሚካኤል ኃይልን አልብሶናል ከእግዚአብሔር ተልኮ\nሚካኤል በአናብስቱ ጉድጓድ መጽናናትን ሰብኮ\n\nሚካኤል ምልጃው ስለረዳን ነጋልን ሌሊቱ\nሚካኤል በረሃ አልቀረንም ተጠምተን በከንቱ\nሚካኤል አዲስ ሰው ሆነናል ዘንዶው ተሸንፎ\nሚካኤል የእግዚአብሔርን ፍቅር በልባችን ጽፎ', 'am', 43, 0),\n(3, 'መልአኩ ዑራኤል', 'መልአኩ ዑራኤል\nየሕይወትን ጽዋ ለዕዝራ ሱቱኤል\nያጠጣው እርሱ ነው መልአኩ ዑራኤል\nመራኝ ከፊት ቀድሞ ጠበቀኝ በጉዞ\nበዙርያዬ ሰፍሯል ምህረትን ይዞ\nበዙርያዬ ሰፍሯል ምህረትን ይዞ\n\nበዚያ መጠበቂያ በበጎች በር ያለው\nይነዋወጥ ነበር ዑራኤል ስትነካው\nቀድሞ የተገኘ ይጠፋል ሕመሙ\nበአንተ ላይ አለና የእግዚአብሔር ስሙ\n\nከነበልባል ከእሳት ከነፋስ ተፈጥሮህ\nከጥፋት ያድናል ልመና ጸሎትህ\nየሰማይ ሰራዊት አንተን አከበሩ\nየክርስቶስን ደም ስትረጨው በምድሩ\n\nዑራኤል ረዳኢ መልአክ ብርሃናዊ\nየሰማይ коከብ ነህ ብሩህ ምስራቃዊ\nሰብአ ሰገል መጡ ብርሃንህን አይተው\nእስከ ቤተ_ልሔም መንገድ መራሃቸው\n\nከነበልባል ከእሳት ከነፋስ ተፈጥሮህ\nከጥፋት ያድናል ልመና ጸሎትህ\nየሰማይ ሰራዊት አንተን አከበሩ\nየክርስቶስን ደም ስትረጨው በምድሩ', 'am', 44, 0),\n(3, 'ባለንበት እንቁም', 'ባለንበት እንቁም\nባለንበት እንቁም በእምነት በተስፋ\nገብርኤል ይመጣል እሳቱን ሊያጠፋ\nየስሙ ትርጓሜ ሠው የሆነ አምላክ ነው\nደስታን ያበሰረን ገብርኤል እሱ ነው\n\nገብርኤል በፊትህ እንቁም ለዝማሬ\nበምልጃህ ታግዘን ደርሰናል ለዛሬ\nበሰማዩ መቅደስ በመሰዊያው ስፍራ\nአሳርግ ፀሎቱን ከእጣኑ ጋራ\n\nበሚፈሩት መሀል ገብርኤል ከተመ\nህዝቡን እያዳነ ድንቅ እየፈፀመ\nቀምሳችሁ እወቁ ቸር ነው እግዚአብሔር\nመልአኩን ልኮ ጠላት የሚያሳፍ\n\nሰላም ሰላም ለከ ገብርኤል ብለናል\nከሳቱ ነበልባል ከሞቱ ተርፈናል\nየሚፈላው ውሀ ቢሰማ እንደመብረቅ\nበእምነት ፀንተናል ስፍራውን ሳንለቅ\n\nበመከራም ሳለን ባዘን በትካዜ\nበዳናችን ሲደርስ በእግዚአብሔር ጊዜ\nልደቱን ነገርከን የጌታን መወለድ\nያምላክን ሰው መሆን ያለ ስጋ ፍቃድ', 'am', 45, 0),\n(3, 'ለጣኦት አንሰግድም ብለው', 'ለጣኦት አንሰግድም ብለው\nለጣዖት አንሰግድም ብለው\nሶስቱ ህፃናት እምቢ አሉ\nየምናመልከው አምላክ\nከእሣት ያወጣል እያሉ\n\nበንጉሱ ቁጣ ልባቸው ሳይርድ\nአንዳችም ሣይፈሩ በእሣቱ መንደድ\nበእምነት በርትተው መከራን ታገሱ\nየታመኑት ጌታ ፈረደ ለነሱ\n\nበመካከል ታየ ከእነሱ ጋር\nመላኩ ገብርኤል ታዞ ከእግዚአብሔር\nበእሳቱ መካከል ምስጋናን ጀመሩ\nስቡህኒ ብለው ለስሙ ዘመሩ\n\nየእሳቱን ነበልባል ውሀ እያደረገ\nየእግዚአብሔር መላክ ነብሳቱን ታደገ\nአንዳች ሳይነኩ ከእሳቱ ወጡ\nየእግዚአብሔርን ክብር ለዓለም ገለጡ\n\nተመላልሰው ታዩ በእሳቱ መሀል\nከራሳቸው ፀጉር አንዲቶአ ሳትጎል\nየከለዳውያን የእሳት ምድጃቸው\nህፃናቱን ትቶ እነሱን በላቸው', 'am', 46, 0),\n(3, 'ሚካኤል ስለው', 'ሚካኤል ስለው\nሚካኤል ስለው ስሙን ስጠራ\nየአምላኬ ብርሃን በላዬ በራ\nአዛኝ በእውነት ፍጹም አዛኝ\nየሚጠብቀኝ የሚያጽናናኝ።\n\nከአለቆች ጋር ሕዝቡን የመራ\nየሚመላለስ በእሳት ተራራ\nባሕሩም ሸሸ ከማደሪያው\nየጌታ መልአክ ሲያናውጸው።\nዘንዶውን አሸንፏል\nስሙን በክብር ጽፏል።\n\nከባዱ ጋራ ሜዳ ሆኖኛል\nየወኅኒው መዝጊያ ተከፍቶልኛል\nአልናወጽም ከቶም አልፈራ\nየጌታ መልአክ ነው ከእኔ ጋራ\nዘንዶውን አሸንፏል\nስሙን በክብር ጽፏል።\n\nትእቢተኛውን አሸንፎታል\nዲያቢሎስ አሁን ዝናሩን ፈቷል\nታላቅ ጸጥታ በሰማይ ሆነ\nእግዚአብሔር ብቻ ስሙ ገነነ።\nዘንዶውን አሸንፏል\nስሙን በክብር ጽፏል።\n\nሚካኤል ሲቆም ፈጥኖ ደራሹ\nየሚቃወሙን አጥብቀው ሸሹ\nታላቁ መልአክ ከፊት ቀደመ\nታሪክ ተሠራ እንባችን ቆመ።\nዘንዶውን አሸንፏል\nስሙን በክብር ጽፏል።', 'am', 47, 0),\n(3, 'መላከ ብስራት ገብርኤል', 'መላከ ብስራት ገብርኤል\nመላከ ብስራት ገብርኤል\nጠፋ ነበልባሉ በበትረ መስቀል\nዛሬም አትለየን ገብርኤል ሀያል\nለሞት ስንጣል እንዳንጠፋ\nፈጥነህ አረጋጋን ሁነን ተስፋ\nምህረትህ ፍቅርህ ረድኤትህ አይራቀን\nብርሀናዊው መልአክ ገብርኤል ጠብቀን\n\nበፈተና ቀን እንድንፅና\nቅዱስ ገብርኤል ወደኛ ና\nበሩቅ ሀገር ሳለን ሀዘን እንዳይጎዳን\nበቃለህ አፅናናን ገብርኤል ሆይ እርዳን\nየአንበሶችን አፍ የዘጋህ\nየራማው መላክ ድንቅ ነህ\nየእግዚአብሔር ልጆች የምታፅናናቸው\nገብርኤል አንተ ነህ ፅኑ ጠባቂያቸው\n\nየሰማዩን ሰልፉ የምትመራ\nገፅህ እንደ ፀሐይ የሚያበራ\nለሚጠሩህ ሁሉ ፈጥነህ ትደርሳለህ\nተነግሮ የማያልቅ ብዙ ታምር አለህ', 'am', 48, 0),\n(3, 'አረጋጊው መልአክ', 'አረጋጊው መልአክ\nአረጋጊው መልአክ የመላእክትን ዓለም\nገብርኤል አንተ ነህ አብሳሪ ለማርያም\nመተህ አረጋጋን ሰላምን ተናገር\nእንጽና በእምነት እንኑር በፍቅር\nእንጽና በእምነት እንኑር በፍቅር\n\nባለንበት እንቁም እንፅና በእምነት\nእስከምናውቅ ድረስ የፍጥረቱን አባት\nብለህ ስትናገር ገብርኤል በአርያም\nበቃልህ ጸንተዋል እስከ ለዘለዓለም\n\nየዱራውን ሜዳ ያንን የሞት መንደር\nከሰማያት ወርደህ ሞላኸው በመዝሙር\nመጠፋፋት ይብቃ ይብዛ ሰላማችን\nገብርኤል አትለይ ቁም ከመኃላችን\n\nበገሊላ መንደር ተልከህ ከእግዚአብሔር\nደስታ ይገባሻል ውዳሴ እና ክብር\nብለህ በትህትና የምስራች አልካት\nለድንግል ማርያም ደስታን አበሰርካት\n\nቂርቆስ ኢየሉጣ ለአምላክ ቢታመኑም\nበሚፍለቀለቀው ቢጣሉ ከጋኑም\nገብርኤል ስትደርስ ውኃው ቀዘቀዘ\nሞትን ያሸንፋል ለአምላክ የታዘዘ', 'am', 49, 0),\n(3, 'የእግዚአብሔር መልአክ', 'የእግዚአብሔር መልአክ\nየእግዚአብሔር መልአክ ስሙ ድንቅ ነው\nለጾርዐ ሰው ለማኑሄ እንደነገረው\nበመሰዊያው ነበልባሉ ውስጥ አረገ\nኃያሉ ሚካኤል ድንቅን አደረገ\nኃያሉ ሚካኤል ድንቅን አደረገ\n\nከዳን ወገን የሆነ በእግዚአብሔር ያመነ\nማኑሄ የሚባል ሰው የጌታ መልአክ ታየው\nሚስቱ መካን ነበረች ልጅንም ያልወለደች\nሚካኤል ተገልጦላት በዘር ፍሬ ባረካት\nየእግዚአብሔር መላዕክ ስሙ ድንቅ ነው\nበኦፍራ አድባር ለጌዴዎን የተገለጠው\nእስራኤልን ከምድር ረሀብ ታደገ\nኃያሉ ሚካኤል ድንቅን አደረገ\nኃያሉ ሚካኤል ድንቅን አደረገ\n\nአንተ ጽኑ ሃያል ሰው እግዚአብሔር ካንተ ጋር ነው\nክንድህን ላበረታ ተልኪያለው ከጌታ\nአይዞህ ጌዴዎን ያለው ቁርባኑን ያሸተተው\nከኛ ጋር ነው ሚካኤል ሰልፋችንን ይመራል\nየእግዚአብሔር መልአክ ስሙ ድንቅ ነው\nበኦርና አውድማ ሰይፍን ይዞ ቆሞ የታየው\nዳዊት በመንቀጥቀጥ ፊቱን ፈለገ\nኃያሉ ሚካኤል ድንቅን አደረገ\nኃያሉ ሚካኤል ድንቅን አደረገ\n\nበሶስት ቀን ቸነፈር እንዳትጠፋ ምድር\nሰባ ሺ ሰዎች ወድቀው መልአክ በቃህ አለው\nለምህረት ይመጣሉ ለመአት ይላካሉ\nሰይፉን በአፎቱ ከቷል ሚካኤል ለህዝቡ ቆሟል\nየእግዚአብሔር መላዕክ ስሙ ድንቅ ነው\nስምኦን ጴጥሮስን ከወይኒ ቤት ገብቶ ያወጣው\nየእጆቹን ሰንሰለት ፈቶ አረገ\nኃያሉ ሚካኤል ድንቅን አደረገ\nኃያሉ ሚካኤል ድንቅን አደረገ\n\nበጠባቂዎች መሃል ኬፋን ከእንቅልፉ አንቅቷል\nየተዘጋውን ደጃፍ አልተሳነውም ማለፍ\nሚካኤል እየመራው ጴጥሮስ እግሩ የቀናው\nአውቆታል ልቡ በርቶ ዘለለ ስሙን ጠርቶ', 'am', 50, 0),\n(3, 'የታመንክ የነፍስ ወዳጅ', 'የታመንክ የነፍስ ወዳጅ\nየታመንክ የነፍስ ወዳጅ\nየምሕረት አማላጅ\nአንተ ነህ ገብርኤል\nየምትቆም በቅድመ እግዚአብሔር\n\nነበልባሉን ውሃ አረከው\nሰንሰለቱን በጣጠስከው\nየነደደው እሳት ጠፍቷል\nከእኛ ጋራ ገብርኤል ቆሟል\nመላእክቱን በሰማይ ገብርኤል\nእንዳረጋጋክ ገብርኤል\nየአምላክን ሰው መሆን ገብርኤል\nለድንግል ነገርክ ገብርኤል\n\nየአናብስቱን አፍ ዘጋኸው\nውህኒውን አናወጽከው\nበሕይወት መንገድ የምትመራ\nለእግዚአብሔር ሕዝብ የምትራራ\nመላእክቱን በሰማይ ገብርኤል\nእንዳረጋጋክ ገብርኤል\nየአምላክን ሰው መሆን ገብርኤል\nለድንግል ነገርክ ገብርኤል\n\nፀሎት ይዞ የሚወጣ\nምሕረት ይዞ የሚመጣ\nዘወትር የሚያይ የአምላኩን ፊት\nቅዱስ ገብርኤል ሊቀ መላእክት\nመላእክቱን በሰማይ ገብርኤል\nእንዳረጋጋክ ገብርኤል\nየአምላክን ሰው መሆን ገብርኤል\nለድንግል ነገርክ ገብርኤል\n\nበመዓልት እና በሌሊት\nየሚያድነን ከእሳት\nዙሪያችንን የሚሰፍር\nየሚያማልድ ከእግዚአብሔር\nመላእክቱን በሰማይ ገብርኤል\nእንዳረጋጋክ ገብርኤል\nየአምላክን ሰው መሆን ገብርኤል\nለድንግል ነገርክ ገብርኤል', 'am', 51, 0),\n(3, 'አበርታኝ ገብርኤል', 'አበርታኝ ገብርኤል\nአንተ የልቤ ወዳጅ ከአንተ ጋር አለኝ ጉዳይ\nአንተ የእኔ ድጋፍ ከአንተ ጋር አለኝ ጉዳይ\nአበርታኝ ገብርኤል በምድር በሰማይ\nምሥራች አሰማኝ ናልኝ ከአርያም ላይ።\n\nሐዋርያ ልደት ጽድቅን ምታሰማ\nከጥንት ጀምሮ የሆንክ የኔ ግርማ\nስወጣ አይሃለሁ ሆነህ ከፍታዬ\nክንፍህ ተዘርግቶ ለምሕረት በላዬ።\n\nገብርኤል ፀሀይ ወጣ በማለዳ\nማዕረግ ልትሆነኝ እኔን ልትረዳ\nየእሳቱ ወላፈን ኃይሉ ቀዘቀዘ\nኩራት አለው ልቤ በአንተ እየታገዘ።\n\nመልአከ አድኅኖ ተልከህ ከጌታ\nየመከራዬ ክንድ ጉልበቱ ተመታ\nከእንግዲህ ሚያሰጋኝ ማነው በሕይወቴ\nእያለኝ ማምለጫ ገብርኤል አባቴ።\n\nማንም የማይፈታው የሕይወት ቋጠሮ\nሰም ወርቅ የሆነብኝ የነፍስ እንጉርጉሮ\nብዙ የምነግርህ በውስጤ አለና\nነፍሴን ልታዳምጥ ገብርኤል ቶሎ ና።', 'am', 52, 0),\n(3, 'ማር ሚካኤል', ' ማር ሚካኤል\nማር ሚካኤል ልበል ማር ሚካኤል ልበልህ(2)\nባርከህ አሳደከኝ በቅኔ በዜማ\nመዝሙር አልሰስትም አባቴ ለአንተማ\n\nጅማሬዬ ታናሽ ያልበቃሁ ብሆንም\nእንድፀና አውቃለሁ ከፊቴ ስትቀድም\nፍፄሜዬ እንዲያምር እንዲዋብ በቤትህ\nአበርታኝ ልበርታ አፅናኝ ልፅና ልጅህ \nባህሩን ክፈለው በደረቅ እንዳልፈው\nእንዳልፈራ አበርታኝ እጄን በእጅህ ያዘው\n\nከእንቅልፍ ያነቃኛል የደጅህ ደወል\nበሌሊት መጥቼ ቤትህ እንድውል\nበሄድኩበት ሁሉ ካፌ አትነጠልም\nየማር ወለላ ነው ሚካኤል ያንተ ስም \nማር ሚካኤል ስልህ ማር ማር አለ አፌ\nውልድህ እውነት ነው በምልጃህ ተርፌ\n\nበሞቱ ቀጠሮ ሰርግ የደገስክለት\nምን አለ ባህራን ስታተርፈው ከሞት\nዛሬም ታምርህን ትድግናህን አይተው\nብዙዎች ይሉሀል ሚካኤል ሙት አንሳው\nረዳኤ ምንዱባን በስደት ደጋፊ\nከክፉ ከልለህ በድል አሳላፊ\n\nአለቱን ከፍለኸው በበትረ መስቀል\nከጭንጫው ሰጠኸኝ ማርና ፀበል\nቀድሞ ለእስራኤል ያኔ እንዳደረከው\nያኔ የሰማነውን ዛሬ ሆኖ አየነው\nየብርሀኑን አምድ ፋና ተከትለን\nከቅዱሳን ስፍራ ዛጅርማኤል ደርሰን\n\nከእንቅልፍ ያነቃኛል የደጅህ ደወል\nበሌሊት መጥቼ ቤትህ እንድውል\nበሄድኩበት ሁሉ ካፌ አትነጠልም\nየማር ወለላ ነው ሚካኤል ያንተ ስም \nማር ሚካኤል ስልህ ማር ማር አለ አፌ\nውልድህ እውነት ነው በምልጃህ ተርፌ', 'am', 53, 0),\n(4, 'አብነ ሐራ ምስራቃዊ', 'አብነ ሐራ ምስራቃዊ\nአብነ ሐራ ምስራቃዊ\nየሀይማኖት ዕምድ ኦርቶዶክሳዊ\nበፅድቅ ጥላ ጠብቀን\nበረድኤት ና ጎብኘን\n\nገዳማዊ ነው መሰረትህ\nብህትውና ነው ትሩፈትህ\nገድልህ ብዙ ነው ስንቱን ላውራ\nአብነ ሐራ ያንተ ስራ\n\nለገድል ለፅናት የበቃህባት\nኢትዮጵያ ሀገርክን ፃድቁ አስባት\nበሐራ ድንግል ባንተ ልመና\nይታደጋታል ኢትዮጵያን ገና\n\nየድር አራዊት ይፈሩሀል\nበቅድስናህ ይገዙልሀል\nብጣል ከጉድጓድ እኔ አልፈራም\nከኔ ጋር አለ አብነ ሐራ', 'am', 1, 0),\n(4, 'የእውነት አማላጅ', 'የእውነት አማላጅ\nየእውነት አማላጅ ቅድስ ዮሐንስ\nተልከህ የመጣህ በመንፈስ ቅድስ\nመተናል ከደጅህ ተጨንቀን ተጠበን\nስለ ቃልኪዳንህ ፈጥነህ አድነን\n\nጌታችን አላቸው ሀዋርያትን\nሒዳችሁ ንገሩ ያያችሁትን\nእውራን ያያሉ ሙታን ይነሳሉ\nበአማላጅነትህ ያመኑ በሙሉ\n\nተስፈዬ ተሟጦ አድንም ተብዬ\nሞቴን ስጠባበቅ ከቤቴ ቁጭ ብዬ\nፈውስን አገኘውኝ ከቤትህ ስመጣ\nእምነት ተቀብቼ ፅበሉን ስጠጣ\n\nገና ከማህፅን የጀመርከው ታምር\nዳግም ስትወለድ የተፈታው ሚስጥር\nአሁንም እፁብ ነው ድንቅ ነው በአለም\nበእምነት በፅበሉ ያልዳነ ሰው የለም\n\nበሀዘን በስቃይ ከደጅህ ላይ መቶ\nእንባን ያፈሰሰ ከፊትህ ተደፍቶ\nየስቃይ ቀንበሮ ወድቆ ተሰባብሮ\nይሔዳል በሰላም ዝናውን መስክሮ', 'am', 2, 0),\n(4, 'አብነ ሀራ', 'አብነ ሀራ\nአብነ ሀራ ድንግል አባታችን\n\nየፃድቅ ሰው ፅሎት ሀይልን ታደርጋለች\nሀጥያትን አጥፍታ ፅጋን ታሰጣለች\nአብነ ሐራ ድንግል በዚህ ታድለዋል\nፅበላቸው ዛሬ መድኃኒት ሆኖናል\n\nገድላቸው ይነገር የፃድቁ ዜና\nአህያ ረዳቸው ብርሀን ነውና\nያየነውንና የሰማነውን\nእንመሰክራለን የፃድቁን ክብር\n\nቃልኪዳኑ ልዩ የሐራ ድንግል\nየመቃብሩ አፈር ፋዋሽ ነው ቁስል\nድካቸውን ልሶ ስስና ነብር\nሳይጣሉ ኖሩ በፃድቁ ስር', 'am', 3, 0),\n(4, 'ተክለሃይማኖት', 'ተክለሃይማኖት\nልጅህ ስለሆንኩኝ የሥላሴ ፍጥረት\nተክለሃይማኖት ስጠኝ የእጅህን በረከት\nጥቂት ይበቃኛል ባዶዬን ልሙላበት\n\nቤተ ሰሊሆም ነች የስምህ መጠሪያ\nፈለቀች ትምህርትህ ከወንጌል ገበያ\nምንጭ ሆኖ ፈሰሰ እኛም እረካን\nየአምላክህን ዝና በገድልህ አይን\n\nእልፍ አእላፍ ሁነዉ በዝተው ቢያሰፉ\nየጥፋትን ጉድጓድ አጋንንት ቢያሰፉ\nቅድስ መስቀልህን ይዘህ ትነሳለህ\nለነፍሴ ዋስ ሆነህ ትቆምለታለህ\n\nተክለሃይማኖት እኔን በምልጃህ አስበኝ\nረድኤት በረከትህ ከእኔ እንዳይለየኝ\nታሪኬን ቀይረው ጎዶሎዬን ሞልተህ\nመራራ ሕይወቴን በወንጌል አጣፍጠህ\n\nዛሬም ተዓምራትህ በዓለም ይሰማል\nቁስለኛው አካሌ በፀበልህ ድኖአል\nጸሎትህ ፈውስ ሆኖኝ ከሞት ተርፌአለሁ\nበሄድኩበት ሁሉ ተክልዬ እልሃለሁ', 'am', 4, 0),\n(4, 'አትታደስም', 'አትታደስም\nየአበው ሀይማኖት አትታደስም\nየሰማዕታት እምነት አትቀየርም\nአይሆንም አትታደሰም\nኦርቶዶክስ ሀይማኖት ናት ለዘላለም\nየገሀነም ደጆች ከቶ አይችሏትም\nመሰረቷ ክርስቶስ ነው ለዘለአለም\n\nእለ እስክንድሪዮስ ሲሰማ ምን ይላል ዛሬ\nተክለ ሀይማኖት ሲሰማ ምን ይላል ዛሬ\nአትናቲዮስ ሲሰማ ምን ይላል ዛሬ\nአባ ጊዮርጊስም ሲሰማ ምን ይላል ዛሬ\nእናውቀዋለን የእውነቱን ጌታ\nከእናቱ እቅፍ ገና ሳይመጣ\nድንገት ደራሾች አማላጅ ሲሉ\nፈራጅ ነው ብለን እንሰብካለን\n\nአባ ሕርያቅስ ሲሰማ ምን ይላል ዛሬ\nቅድስ ላሊበላ ሲሰማ ምን ይላል ዛሬ\nቅድስ ያሬድ ሲሰማ ምን ይላል ዛሬ\nቅድስ ኤፍሬም ሲሰማ ምን ይላል ዛሬ\nድንግል ማርያምን ስሟን ሳይጠሩ\nየመላዕክቱን ታምራት ሳይናገሩ\nየቅድሳኑን ክብር ሲገፍ\nበጠላት ወጥመድ ገብተው አረፉ\n\nዲዮስቆሮስም ሲሰማ ምን ይላል ዛሬ\nአርሴማ ቅድስት ስትማ ምን ትበል ዛሬ\nቅድስ ቄርሎስም ሲሰማ ምን ትበል ዛሬ\nክርስቶስ ሰምራ ምን ትበል ዛሬ\nየጠላት መንጋ ጦርነት ቢያስነሳ\nመሰረት ሊንድ ጠላት ቢያስነሳ\nአይቀየርም የኢየሱስ ደም ነው\n\nዮሐንስ አፈወርቅ ሲሰማ ምን ይላል ዛሬ\nሰማዕቱ ጊዮርጊስ ሲሰማ ምን ይላል ዛሬ\nይማረነ ክርስቶስ ሲሰማ ምን ይላል ዛሬ\nአባ ሳሙኤል ሲሰማ ምን ይላል ዛሬ\nየአርዮስ ልጆች ዛሬም ቢነሱ\nእንክርዳድ ሆነው ደጅን ቢወርሱ\nያሳነሳለታል ሰው እንደገና\nየወላድ መካን መች ሆነችና', 'am', 5, 0),\n(4, 'ተክለሃይማኖት ፀሐይ', 'ተክለሃይማኖት ፀሐይ\nተክለሃይማኖት ፀሐይ የአምላክ አገልጋይ\nፀሐይ የአምላክ አገልጋይ\n\nየኢትዮጲያን ምድር የባረካት\nአስተማሪዋ የሆንክላት\nይህንን አውቃ ትዘምራለች\nተክለሃይማኖት ትጠራሃለች\n\nአልጫው ጣፍጧል በጸሎትህ\nብርሃን በርቷል ለልጆችህ\nበቃልኪዳንህ ፍጥረት ጸደቀ\nተአምራትህም በዓለም ታወቀ\n\nምስክርህን አምላክ ያከብራል\nየነኩህንም እርሱ ይጣላል\nፍርፋሪህን ልቤ ናፈቀች\nያንተን በረከት ስለወደደች\n\nበእግዚአርያ በፀጋዘአብ ተማጽኛለሁ\nልቤን ለእጅህ ሰጥቼሃለሁ\nከአንተ ጋር ልኑር ለዘላለም\nየሚለያየን ማንም የለም', 'am', 6, 0),\n(4, 'ፈጥነህ ቅረበን ጊዮርጊስ', 'ፈጥነህ ቅረበን ጊዮርጊስ\nፈጥነህ ቅረበን ጊዮርጊስ\nለአምላክህ የታመንህ እስሰማዕቱ\nአክሊልን አገኘህ ፍጡኑ እረድኤት\n\nመከራን ታገሰ በወጣትነቱ\nስለ ጌታ ፍቅር ጊዮርጊስ ሰማዕቱ\nየእረገጥክባቸዉ የእግሮችህ ፋና\nይመሰክራሉ ጊዮርጊስ ያአንተን ዝና\n\nበመከራዉ ፀና ሩጫዉን ፈፀመ\nየህይወትን አክሊል ጊዮርጊስ ተሸለመ\nስጋዉን ለመጋዝ ነብሱን ለአምላክ ሰቶ\nተጋሎ አሸነፈ በእምነቱ ፀንቶ\n\nስለ ጌታ ፍቅር ጊዮርጊስ መቼ አፈረ\nእኔ ክርስቲያን ነኝ ብሎ መሰከረ\nእየሱስ ክርሰቶስ አብዝቶለት ፀጋ\nለነብሱ ተገዛ ሳይሳሳ ለስጋ\n\nሃያሉ ጊዮርጊስ የልዳዉ ገናና\nከጠላት አድነን ፈጥነክ ድረስና\nአዉሬዉ በዙሪያችን ሲዉጠን ሲያደማ\nስምህ ጋሻ ሆነን መከለያ አልማ', 'am', 7, 0),\n(4, 'የክብርን ዘውድ ጭኖ', 'የክብርን ዘውድ ጭኖ\nየክብርን ዘውድ ጭኖ ታየ ካህኑ\nበወርቅ ማዕጠንት ሞልቶ ሲያርግ እጣኑ\nእንደ ሱራፌል መላክ ደራርቦ አክናፋ\nቆመ ተክለ ሀይማኖት ከሳቱ ደጃፍ\n\nነበልባል ተጋረደ ከስላሴ ሰገነት\nባለ ግርማ ሞገስ ነው ሲሰየም ላገልግሎት\n፳፬ ካህናት ተቀላቅሎ ተክልዬ\nሕዝቤን ማርልኝ ይላል አክብርልኝ ጌታዬ\n\nበትረ መስቀሉን ተክሎ ከጭንቻው አመነጨ\nሰላም ለብሶ እንዲሄድ ፀበሉን የተረጨ\nበረገጠው ምድር ላይ ቃልኪዳኑ ፈሰሰ\nየሰማዪን በረከት በኛ ላይ ነሰነሰ\n\nተቀጣጠለ ዝናው ካድማስ ማዶ ተሰማ\nበፀሎቱ ዘለፈ ድፍንፍኑን ጨለማ\nከመናኒያን ጋራ ይመንናል በፍቅር\nአባ ተክለ ሀይማኖት የኢንቲሳው መምህር\n\nአለው ጥዑም መአዛ የእጁ ጠረን ሽታ\nለተሳለመው ሁሉ ይሰጣል ልዪ ደስታ\nገና ከገድሉ መፃፍ ስንኞች ሲበተኑ\nየቤሊሆም ሰራዊት እንደ እንፍሎት ተነኑ', 'am', 8, 0),\n(4, 'መርቆሬዎስ', 'መርቆሬዎስ\nመርቆሬዎስ\nየችግሬ ደራሽ ና በፈረስ\nእንባዬን ልታብስ ፈጥነህ ድረስ\n\nባስልዮስ ጎርጎሪወቀስ ሰምሯል ልመናቸው\nስዕሉ ዘለለ ታምራት አያችሁ\nእናንተን የረዳ መጥቶ በፈረስ\nዛሬም ለኛ ይድረስ ይምጣ መርቆሬዎስ\n\nዑልያኖስ ተገድሏል ሃይማኖት ይስፋፋል\nብሎ መሰከረ መርቆርዮስ ሃያል\nገፀ ከላባቱ ባህርይ ቀየሩ\nእርሱን ለማገልገል ከእግሩ ስር አደሩ\n\nትካዜ ሀዘኔ ይርቃል ጭንቀቴ\nመርቆርዮስ ሲመጣ ሲገባ ከቤቴ\nበፀሊም ፈረሱ እየገሰገሰ\nመርቆሬዎስ ወዳጄ ስጠራው ደረሰ\n\nስቃዩን ሊያረዝም ዳኪዎስ ወደደ\nከጨለማ እስር ቤት ታስሮ ተወሰደ\nበጋለ ሹል ብረት መርቆሬዎስ ተወጋ\nስሙ ተሰየመ ከሰማዕት ጋ\n\nአልፈራም መከራ አልፈራም ችግር\nመፍቅሬ አብ ካለ ያኘሎፓዴር\nቂሳርያ እስር ቤት መርቆሬዎስ ታሰረ\nወህኒ ቤቱ በራ እግዚአብሔር ከበረ', 'am', 9, 0),\n(4, 'የኢቲሳ አንበሳ', 'የኢቲሳ አንበሳ\nየኢቲሳ አንበሳ ተክልዬ ተነሳ\nወገንክን ታደገው ከኃጢአት አበሳ\nተኩላው ለምድ ለብሶ በእርግጥ መቱአልና\nጴጥሮስ ሆይ ዝም አትበል እንደጥንቱ ቅና\nዩሐንስ ሆይ ዝም አትበል እንደጥንቱ ቅና\nጳውሎስ ሆይ ዝም አትበል እንደጥንቱ ቅና\n\nየዓለም ምናምንቴ የተባልከው ቅዱስ\nየዋሁ መነኩሴ አባ ሕርያቆስ\nቅዳሴ ማርያምን ናና ዛሬም ቅደስ\nበዕጣኑ መዓዛ ድዉያንን ፈዉስ\n\nየወንጌል አንበሳ ጎርጎሪዎስ ፍጠን\nምሰሶው ሳይወድቅ መንጋው ሳይበተን\nመብረቁ አትናቴዎስ ሞገዱን ገስፀው\nአፈ ጉባዔያችንን በመስቀልህ ዳኘው\n\nመርከቡአን የሚያውክ ነፋስ ነፍሱአልና\nአምላካችን ፈጥነህ አድነን ቶሎ ና\nጴጥሮስ ሆይ ቀስቅሰው ልንጠፋ ነው ብለህ\nሞገዱ እያየለ ዝም እንዳይል ጌታ\n\nከሳቴ ብርሀን ሰላማ ቶሎ ና\nኖላዊ እረኛ ያስፈልጋልና\nስጋዉን የጎዳ ነፍሱን የጠቀመ\nነቅ ጉድፍ የሌለው ግብሩ የታመ', 'am', 10, 0),\n(4, 'ተክለሃይማኖት', 'ተክለሃይማኖት\nየፀጋ ዘአብ ልዩ ስጦታ\nየተዋህዶ የእምነት አለኝታ\nገፀበረከት የእግዚአርያ\nተክለሃይማኖት ድንቅ ሐዋርያ\n\nየእምነት ፍቅር አሽንፎት\nጌታ መረጠው ከልቡ አምኖት\nአገለገለ አምላኩን\nሕዝቡን ሰበከ ወንጌልን\n\nበደብር አስቦ ተክለሃይማኖት\nበአንድ እግሩ ቆመ ሰባት አመት\nፅናቱን አይቶ ፈጣሪው\nየብርሀን መስቀል ሸለመው\n\nዲያብሎስ ቀንቶጻድቁን\nቀርቦ ቢቆርጠው አንድ እግሩን\nየሚያምነው አምላክ ሳይዘነጋው\nስድስት አክናን አስረከበው\n\nፀጋው ልዩ ነው አባታችን\nጽኑ መሰረት የእምነታችን\nብርቱ ገበሬ የተዋህዶ\nከፍ ያደረገው አምላክ ወዶ', 'am', 11, 0),\n(4, 'ገድሉ ታምራቱ', 'ገድሉ ታምራቱ\nገድሉ ታምራቱ እጅግ ብዙ ነው\nጣዖትን አዋርዶ የተሸለመው\nየተዋህዶ ኮከብ ተክለ ሐዋርያ\nአባ ተክለሃይማኖት ዘኢትዮጵያ\n\nዳግማዊ ዩሐንስ ጠፍር የታጠቀ\nፍፁም ባህታዊ ጠላት ያስጨነቀ\nየፀጋ ዘአብ ፍሬ ዛፍ ሆኖ በቀለ\nበደብረሊባኖስ መናኝ አስከተለ\n\nደካማ መስሏቸው በአንድ እግሩ ቢያዩት\nባለ ስድስት ክንፉ ተክልዬ የእኔ አባት\nእርሱስ አንበሳ ነው ይናገር ደብረ አስቦ\nሌጊዮን ሲዋረድ እፍረት ተከናንቦ\n\nከካህናት መካከል ህሩይ ነው ተክልዬ\nመጣሁ ከገዳምህ ልሳለምህ ብዬ\nኢትዮጵያዊው ቅዱስ አባ ተክለሃይማኖት\nወልድ ዋህድ ብለህ ምድሪቷን ቀደስካት\n\nየባረከው ውሃ የረገጥከው መሬት\nጥላህ ያረፈበት ሆኗል ፀበል እምነት\nኑና ተመልከቱ ድውያን ሲፈቱ\nይሰብካል ተክልዬ ዛሬም እንደ ጥንቱ', 'am', 12, 0),\n(4, 'አባ አባ ተክለ ሃይማኖት', 'አባ አባ ተክለ ሃይማኖት\nአባ አባ ተክለሃይማኖት እቡየ\nበለኒ በለኒ ወልደየ\n\nአባ አባ እንኳን ሰው ምድሪቱ\nአባ አባ ጦም አያሳድርም\nአባ አባ አምላከ ተክልዬ\nአባ አባ ብዬ አፍሬ አላውቅም\nአባ አባ ምድራዊ መልአክነህ\nአባ አባ የእቲሳ አንበሳ\nአባ አባ ለደብረ ሊባኖስ\nአባ አባ አንተነህ ሞገሷ\n\nአባ አባ ስምዓኒ ብያለሁ\nአባ አባ ሳለህ በሰማይ\nአባ አባ ከኪሩቤል ተርታ\nአባ አባ ሆነህ ስትታይ\nአባ አባ ስምህም ሲጠራ\nአባ አባ ገድልህ ሲነገር\nአባ አባ ዕፁብ ድንቅ ያሰኛል\nአባ አባ የተሰጠህ ክብር\n\nአባ አባ አባቴ እልሃለሁ\nአባ አባ ልጄ ሆይ በለኝ\nአባ አባ የአባትና የልጅ\nአባ አባ ፍቅርህ ይፅናልኝ\nአባ አባ ንፍሮ ውሃ ጠጥቼ\nአባ አባ ተአምር አይቻለሁ\nአባ አባ እባብና ጊንጡን\nአባ አባ ተረማምጃለሁ\n\nአባ አባ ዕለት በዕለት ሄጄ\nአባ አባ ደጅ ስጠናው\nአባ አባ ይሰማል ተክልዬ\nአባ አባ ዛሬም ህያው ነው\nአባ አባ እንቆቅልሽ ፈቶ\nአባ አባ ደስ አሰኝቶኛል\nአባ አባ የተክለሃይማኖት\nአባ አባ ቡራኬው ደርሶኛል', 'am', 13, 0),\n(4, 'ተክለ ሃይማኖት ፃድቅ', 'ተክለ ሃይማኖት ፃድቅ\nበኢትዮጲያ ምድር ክብሩ ታላቅ ሆነ\nበኢትዮጵያ ምድር ስሙ ታልቅ ሆነ\nተክለ ሃይማኖት ጻድቅ\nተክለ ሃይማኖት አቡነ\n\nበኢትዮጵያ ምድር ዝናህም ተሰምቷል\nተክልዬ ጸሎትህ ከዓርያም ደርሷል\nየሚሰማ ሁሉ እጅግ ያደንቅሃል\nየዘለዓለም ዝናር ወንጌልን ታጥቀሃል\n\nመንፈስ ቅዱስ በእርሱ ድንቅን ስለሰራ\nየሰማዩ ብርሃን በምድራችን በራ\nብትማርካቸው በዓርያ ክህነቱ\nመጡ ለምነና ደቀ መዛሙርቱ\n\nበስመ አብ ብሎ ሲያነሳው መስቀሉን\nያስጨንቃቸዋል የምድር አጋንትን\nከአፉ ሲወረወር ትምሕርተ ወንጌሉ\nለእግዚአብሔር ተገዙ ነገስታቱ ሁሉ\n\nቅድስና ክብሩ ያበራል ለዛሬም\nምሳሌ ሁነሃል ለጨለማው ዓለም\nምድርን ይባርካል ተክልዬ ጸሎቱ\nእኛም ተጠቅመናል በአማላጅነቱ', 'am', 14, 0),\n(4, 'ገድል በገድል ቤት', 'ገድል በገድል ቤት\nገድል በገድል ቤት ውስጥ ሲነበብ ሲሰማ\nልቤ ተማረከ በተክልዬ ግርማ\nደብረ ሊባኖስ ነው ያየሁት እርሱን\nሊባርክ ሲመጣ ሌት ቀን ገዳሙን\n\nእየባረከ ይባርከናል\nእየቀደሰ ይቀድሰናል\nፀጋው በዝቶለት በአምላካችን\nበክንፍ ይበራል ሊያማልደን\n\nአቤት የተክለ ሐይማኖት ክብሩ\nሱራፌል ሆነ በሰማይ ሀገሩ\nጽንዐ ይዞ ያጠነ ዙፍኑን\nያስታርቀናል ሌልትና ቀን\nያማልደናል ሌልትና ቀን\n\nእንግዶች ሆነን ዋሻ ስንሄድ\nያሳድረናል ትሁት ነው ውድ\nየአምላክ ምስለኒ ሆኖልናል\nልጆቹ ሁሉ ውጡ ምነና\n\nበንፍስ አውታር ዘወትር ይሄዳል\nበወንጌል መረብ ህዝብን ያጠምዳል\nየታመመውን እየፈወሰ\nሙታንን ያስነሳል እየቀደሰ\n\nድካም የለበት ዘወትር ብርቱ\nግዳጅ ፈፃሚ ስውር ፀሎቱ\nተዘከረኒ በባህር ወየብስ\nተክለ ሐይማኖት ስል ድረስ', 'am', 15, 0),\n(4, 'ተክለ ሀይማኖት ባህታዊ', 'ተክለ ሀይማኖት ባህታዊ\nተክለ ሀይማኖት ባህታዊ\nምድራዊ ሲሉህ ሰማያዊ\nበአደባባዩ ተተክለሀል\nተክልዬ መልካሙን ፍሬ አፍርተሀል\n\nቃልኪዳን አለ የገነነ\nምህረት የሚያሰጥ የታመነ\nበስምህ ውሀ አጠጥተን\nዋጋችን በዝቷል አባታችን\n\nእኛም ሆነናል ልጆችህ\nማርኮ አስቀምጦን ምግባርህ\nበምልጃህ ፅሎት ትሩፈት\nቤታችን ሞላ በረከት\n\nምህረት ይዘንባል ከሰማይ\nበአንድ እግርህ ቆመክ ስትፅልይ\nብዙ ተጋድለህ አትርፈካል\nያገለገልከው አክብሮሀል\n\nተሰባበሩ ጣኦታቱ\nአምነው ሰገድ መኳንቱ\nየበረታው ቃል ከአፍህ ወቶ\nየአምላክ አድርጓል ሁሉን ገዝቶ', 'am', 16, 0),\n(4, 'ኢትዮጵያዊው ፃድቅ', 'ኢትዮጵያዊው ፃድቅ\nኢትዮጵያዊው ፃድቅ ማነው ብዬ ጠየኩ\nበረከት ፈልጌ ልሳለመው ናፈኩ\nክብሩን ልመሰክር ተፈታ ምላሴ\nበደጁ ደርሼ ፍቅሩን በመቅመሴ\n\nበኢቲሳ ምድር ዘር ሆነህ በቅለህ\nተለየህ ለአምላክ አለምን ጥለህ\nደብረ ሊባኖስ ህያው ምስክር\nስለአንተ ዝና ስለአንተ ክብር\nተክለሃይማኖት ወዳጄ\nተባርኳል ባንተ ጓዳ ደጄ\n\nአክባሪው አምላክ ስላከበረህ\nዛሬም ከኛ ጋር በመንፈስ አለህ\nደጅ እንጠናለን በትህትና\nየፃድቅ ፀሎት ሀይል አላትና\nተክለሃይማኖት ፀሐይ\nፀጋህ ይውጣልኝ በሰማይ\n\nወደለምለም መስክ ሰብከህ መራህን\nየቃሉን ወተት አጠጥተኽን\nያቀጣጠልከው የወንጌል ችቦ\nየአምላክ አድርጓል ትውልዱን ስቦ\nተክለሃይማኖት ወዳጄ\nተባርኳል ባንተ ቤቴ ደጄ\n\nሰላሳ ስልሳ መቶ ያፈራህ\nበደብረ አስኮ ቆመህ ባንድ እግርህ\nየመተ ሎሚ መሻት ቀረና\nየጌታ መንገድ ጥርጊያውም ቀና\nተክለሃይማኖት ወዳጄ\nተባርኳል ባንተ ጓዳ ደጄ', 'am', 17, 0),\n(4, 'አባ ኪሮስ አባቴ', 'አባ ኪሮስ አባቴ\nአባ ኪሮስ አባቴ ገድልኽ ፍቅር ለቤቴ\nስምኽ ጥኡም ዝማሬ ዉበት ነው ለንደበቴ\nበፊትህ እሰግዳለው ለክብርህ እንደገና\nእያየህ ህልሜ ጭንቀት ዘመኔ አልፏልና\n\nአልችል አለኝ አንጀቴ በቃኝ መሐንነቴ\nአነባው ደጂ ወድቄ ልጅ ማቀፍን ናፍቄ\nአምኜ ቃል ኪዳኑን ሔጄ አዘልኩኝ ገድሉን\nበአመቱ ልጄን አዘልኩ አይኔን በአይኔ አየሁ\n\nያንን የማይገፋ ያንን የማይቻል\nያንን የኃዘን ቅኔ እርሱ ፈታው በፍሬ\nልዩ ነው ለኔስ ልዩ ነው አባ ኪሮስ\nበፍቅር ረማመላው ቤቴን ፍጹም ደስ ደስ\n\nጸበሉ መድኃኒቴ ብታመም ገድሉ ፈውሴ\nምልጀው መታመኛዬ የምድር የሰማይ ዋሴ\nአባት አለኝ ጻድቁ አባት አለኝ እኔስ\nደስታዬ መጽናኛዬ ክብሬ አባ ኪሮስ\n\nጾም ፀሎቱ ማርከው ጌታ ፍቅሩን ሳበው\nዳዊት እየዘመረ ሞቱን በእቅፍ አረገው\nእኔም አከብረዋለው በፊቱ እሰግዳለው\nለስሙ እዘምራለው እልል እልል እላለው', 'am', 18, 0),\n(4, 'ደምቆ እያበራ', 'ደምቆ እያበራ\nደምቆ እያበራ ነጭ ልብሱ\nጊዮርጊስ መጣ በፈረሱ\nእኔን ከክፉ ሊያወጣኝ\nእስሬን ፈቶ ሊያቆመኝ\n\nታግሎ ሲያሸንፍ አለምን\nእስከ ሞት ድረስ ሊታመን\nየክብርን አክሊል ተቀናጀ\nጊዮርጊስ ከአምላኩ ተወዳጀ\n\nግብር ሰተውት ለጠላቴ\nተስፈ ቢስ ስሆን ቀርቦ ሞቴ\nአስጣለኝ ጊዮርጊስ ከሞት አፍ\nከአስፈሪው እሳት እንድተርፍ\n\nሀይሉ ደከመ የጠላቴ\nጊዮርጊስ ሲመጣ እረዳቴ\nየፅሎቱ ሀይል ትሩፈት\nቤቴን ሞላልኝ በረከት\n\nዘንዶውን ገድሎ ጥሎልኛል\nአምላኬን ገልጦ አሳየኝ\nአሁን አዳኜን አውቄአለሁ\nለጊዮርጊስ አምላክ ዘምራለው', 'am', 19, 0),\n(4, 'አባ ኪሮስ', 'አባ ኪሮስ\nአባ ኪሮስ አባታችን\nስምህ ገድል ተነሳ አሁን\nመገለጫ ዘመኑ አሁን ነው\nታምርህን እየሰማን ነው\n\nገንዘብን ስልጣን ንቀህ\nበአምላክ ፍቅር ዋሻ ገባህ\nእረዱ ነህ ለአባ በርኖዳ\nተገዛችልህ ዓለም ተገዳ\n\nዲላሮስ ነበረ ስምህ\nመንፈስ ቅዱስ ኪሮስ አለህ\nለብዙዋች አባት ሆነሀል\nፀሎትህም ሙት አስነስቷል\n\nወገብህን በአጭር ታጥቀህ\nተሰግዳለህ ለፈጣሪህ\nስትራዳ ደካማውን\nተሸከምከው አምላክህን\n\nይሰራል ቃልኪዳን\nአምላክህ የገባልህን\nለመካንዋ ታሰጣለህ ልጅ\nድንቅ ስራ ለአለም ይታወጅ', 'am', 20, 0),\n(4, 'መጥምቀ መለኮት', 'መጥምቀ መለኮት\nመጥመቀ መለኮት ዮሀንስ\nመጣ ከበረሀ ህዝቡን ሊቀድስ\n\nዮሀንስ ሰበከ ስለ ክርስቶስ\nሀጥያት የሰራ ቶሎ እንዲመለስ\nመንገዱ ይጠረግ የጎበጠ ይቅና\nመድሀኒት ክርስቶስ ይገለጣል እና\n\nበሄሮን በረሀ ድመፅ ሲስተጋባ\nቃልህ ውስጤን ነካኝ ምክርህ ልቤ ገባ\nእውነት ነው ስብከት ፍሬ አለው እና\nእጆቼን ልዘርጋ ምህረት ልመና\n\nየዕዳ ፅህፈታችን በአምላክ ሲደመሰስ\nአንተንም አየንህ ቆመህ ከዮርዲያኖስ\nጌታችን ሲጠመቅ ዲያብሎስ ተፈታ\nነፍሳችን ዘመረች ሀሴትን ተመልታ', 'am', 21, 0),\n(4, 'በማህፀን ቅኔ', 'በማህፀን ቅኔ\nበማህፀን ቅኔ ለማርያም ተሰማ\nበተራራማ አገር በኤፍሬም ከተማ\nዮሀንስ ይናገር በረሀ ያደገው\nድንግል ስትናገር ምን እንዳዘለለው\n\nየእናቱ ማህፀን የቅኔ እርስት ሆነች\nድንግል የአምላክ እናት ፊቱ ስለቆመች\nበሀሴት ዘለለ ዘመረ በደስታ\nከድንግል ሲወጣ ታላቁ ሰላምታ\n\nበድንግል ማህፀን ስላየ ጌታሁን\nነገመወለድ ሰማነው መዝሙሩን\nትንቢቱ ሲፈፀም በሆዷዋ ሲስግድ\nሰገደ ለአምላኩ የስድስት ወር ፅንስ\n\nጀመረ ስብከቱን ገና ሳይወለድ\nተፈጥሮ መች አለ ነብዩን ለማገድ\nአፉ ተከፈተ በታላቅ ምስጋና\nበእናቱ ማህፀን ድምፅን እሰማና\n\nየዮሀንስ እናት ኤልሳቤጥ ገረማት\nልጇ በማህፀን ቅኔ ሲቀኝባት\nድምፁን ከፍ አድርጎ ለአለም አወራ\nሞላት መንፈስቅዱስ ለመዝሙር ለዜማ', 'am', 22, 0),\n(4, 'ዜና ማርቆስ', 'ዜና ማርቆስ\nዜና ማርቆስ\nበፀሎት ወድቋል ጠላቴ ዲያብሎስ\n\nምርጫ በማህፀን ስለሆነ\nበተወለድክ ግዜ ስላሴ ጠራህ\nተባርከ መጥተሀል ሄደህ እራስድርያስ\nሀይሉም አድሮ ብሀል የማርቆስ ሀዋርያ\n\nወንጌልን የሰበክምሁር ላይ ስደርስ\nሰዎችን ያሳተው ተሰብሯል ባኮስ\nሁሉም ተመልሰው ተዋህዶ ሆነ\nየዜና ማርቆስን አምላክ እያመኑ\n\nጋራ ሲሄድ ተክለ ሀይማኖት\nዜና ማርቆስ ፀና በደብረ ብስራት\nስርአተ ቅዳሴ ስታከናውን\nጊዜ ሲመሽብ አቆምክ ፀሀይን\n\nድንጋይ ዛፍ ቅጠሉ ሲከተል ተክልዬ\nአየን ልዩ ተአምር ደብረ ብስራት ሆነህ\nገፅፀ አስቀራቸው ምፆዋትን ሁሉ\nእጅ ነስተው ቆመው ዛሬም ይታያሉ', 'am', 23, 0),\n(4, 'ሰማዕቷ ቅድስት', 'ሰማዕቷ ቅድስት\nተባረኩኝ ጠራኝ ፅሎቷ\nልሳለማት ልሒድ ከቤቷ\nፍቅሯ ልዮ ነው ደግነቷ\nእናቴ አርሴማ ሰማዕቷ\n\nየውስጥ ደዌውን ህመሙን ደብቆ\nገስግሶ የመጣ ካለሽበት ዘልቆ\nድኖ ተመለሰ ዝናሽን አሰማ\nሰማዕቷ እናቴ እያለሽ አርሴማ\n\nእግሩ ያነከሰ ክንድ የዛለበት\nደስታ የራቀው ሰው ህመም የፅናበት\nልብ የደከመ መንገድ የጠፈበት\nአፍሮ አይመለስም ደጅሽ የመጣ እለት\n\nላይድን መች ይመጣል ላይለቀው ችግሩ\nአንቺስ መች ልጠሪው ሲነሳ ከሀገሩ\nአቤት ቃልኪዳንሽ እንዴት ይገልፃል\nአምኖ የመጣ ሰው ድኖ ተመልሷል\n\nአንደበትን ስጪኝ እመሰክራለሁ\nበሶስት ፍሬ ቆሎ ስታድኚ እያየው\nነግሬሽ ነበረ ችግሬን በሙሉ\nአላሳፈርሽኝም\n\nያን ሁሉ ቁልቁለት ያን ሁሉ ጋራ\nእንዴት ልጓዝ ብዬ ስፈራ ስፈራ\nድረሺልኝ ብዬ ላንቺ ስናገር\nእንደ አንበሳ ጥጃ እዘለው ጀመረ', 'am', 24, 0),\n(4, 'በተራራማው', 'በተራራማው\nበተራራማው በኤፍሬም ሀገር\nታምር ተሰማ ኤልሳቤት ሰፈር\nመካኗ እናት ነብይ ወለደች\nስትዘምር ሰማን አልል እያለች\n\nየመካንነቷ ስድብ ቀርቶላታል\nጌታ በማህፀን ዮሐንስ ፈጥሯል\nየደስታዋ ሚስጢር የእጅ ስራ ነው\nዘመረች በሀሴት ሁሉ ለሚቻለሁ\n\nገረማት ኤልሳቤት የጌታዋ ስራ\nምን ብላ ትናገር በምን ቋንቋ ታውራ\nእልልታው ደመቀ በኤፍሬም ከተማ\nከፍ አረገች ድምጿ አለም እንዲሰማ\n\nመጣችላት ድንግል ታምሩን ስትስማ\nአናገራት መንፈስ ተሞላች በግርማ\nህፃኑም ዘለለ ድንግልን አየና\nበድንግል ማህፅን ጌታን አይቷልና', 'am', 25, 0),\n(4, 'ገብረ ህይወት', 'ገብረ ህይወት\nገብረ ህይወት\nከነኢሳ መጣ ሊባርካት\nኢትዮጲያ መጣ ሊጠለልባት\n\nገብረ ሕይወት በዝቋላ ምድር\nገብረ ሕይወት መቶ አመት ጸለየ\nገብረ ሕይወት አባታችን ለኛ\nገብረ ሕይወት ጌታን ተማፀነ\nገብረ ሕይወት በባህር ውስጥ ጠልቀህ\nገብረ ሕይወት ማረኝ ብለሀል\nገብረ ሕይወት ለኢትዮጲያን\nገብረ ሕይወት ምህረት ለምነሀል\n\nገብረ ሕይወት አንበሳ ነበር\nገብረ ሕይወት ይከታተሉሀል\nገብረ ሕይወት በፀጋህ ተማርከው\nገብረ ሕይወት ለአንተ ተገዝተዋል\nገብረ ሕይወት የቅዱሳን እራስ\nገብረ ሕይወት ገብረ ሕይወት\nገብረ ሕይወት ቃልኪዳን ተሰጠህ\nገብረ ሕይወት ምድረ ከብድ ስትደርስ\n\nገብረ ሕይወት የእናት ጡት ሳትቀምስ\nገብረ ሕይወት የኖርክ በበረሀ\nገብረ ሕይወት ልብስ ፀጉር ብቻ\nገብረ ሕይወት ግሩም የአምላክ ስራ\nገብረ ሕይወት እንማለላለን\nገብረ ሕይወት ሁላችን በአንድነት\nገብረ ሕይወት ጸሎትህ እንዲያወጣን\nገብረ ሕይወት በኃጢአት በመቅሰፍት', 'am', 26, 0),\n(4, 'ሀና ብሩክት', 'ሀና ብሩክት\nሀና ብሩክት ፀልዪ በእንትያነ\nፀልዪ ለነ ወሰአሊለነ\nምስለ ኢያቄብ አቡነ\n\nመካን ሆና ሳለ ስታዝን ዘወትር\nልመናዋን ሰማ እግዚአብሔር\nበትዕግስት ስትጠብቅ ለሊት እና ቀን\nሀዘኗን ማስረሻ ሰጣት ማርያምን\n\nየሀናን መፅነሷ ታረጋግጥ ዳሳ\nማየት የተሳናት አየች ተፈውሳ\nሰላም ለኪ ሀና እሙ ለሰማይ\nአይተናል ክብርሽን ልትባርኪን ነይ\n\nሙቱን ስታስነሳ እውር ስታበራ\nበቅናት ተነሱ አይሁድ በየተራ\nከእግዚአብሄር ተልኮ ቅዱስ ገብርኤል\nሊባኖስ ወሰዳት እንድትከለል', 'am', 27, 0),\n(4, 'ወንጌላዊ ሐዋርያ', 'ወንጌላዊ ሐዋርያ\nወንጌላዊ ሐዋርያ ተክለሐይማኖት\nልመናዬን ፀሎቴ አድርስ በእግዚአብሔር ፊት\n\nድላልሽ ተወለደ በእቲሳ መንደር\nብርሀን ሆነሀል በኢትዮጵያ ምድር\nተጋድሎህን ላድንቅ ክብር እንዲሆነኝ\nጌታ በፀሎትህ እንዳያሳፍረኝ\n\nበኪደታ እግርህ የተቀደሰ ሁሉ\nመናፍስቱ ጮሁ ተሸነፍን ሲሉ\nየበረታ ፀጋ የገነነ ክብር\nለብሰሀል ተክልዬ በሰማይ በምድር\n\nይወድሀል ልቤ በፅኑ ናፍቆት\nይቸኩላልእግሬ በምትነግስበት\nእምነት ቸርነትህ አብነት ይሁነኝ\nአለም በስጋ ክንድ እንዳያሸንፈኝ\n\nየቀበልክ ነህ ፅኑ ቃልኪዳን\nበአማላጅነት ህዝብ ለማዳን\nትምህርትህ የቀና ስብከት የረታ\nቅዱስ ተብለሀል ተመርጠህ በጌታ', 'am', 28, 0),\n(4, 'ኮከብ ሲወጣ አየን', 'ኮከብ ሲወጣ አየን\nኮከብ ሲወጣ አየን በልዳ ሠማይ\nሐያሉ ጊዮርጊስ ቆሟል ዘንዶው ላይ\nቤሩታዊት ተነሽ አትሞችም ተጽናኝ\nአውሬው ተሸንፏል በአምላክሽ እመኝ\n\nሕዝቡን የሚያስጨንቅ ሠው ገብሩኝ ብሎ\nጊዮርጊስ አደቀቀው በእግሮቹ ሥር ጥሎ\nየንጉሡ ልጅ ቤሩት ዕጣው ለአንቺ ሆኗል\nከግንዱ ሊፈታሽ ፈረሰኛው ቆሟል\n\nበጣዖታት ምድር አዲስ ጸሐይ ወጣ\nበጽድቅ እያበራ ጊዮርጊስ ታጥቆ መጣ\nእንግዲህ አፍጵሎን አቴና ሆይ እፈር\nምድሪቱን ይገዛል የአምላካችን ክብር\n\nዱድያኖስ መንግስቱን አልቻለም ሊያጸና\nታላቁ ሠማዕት ቅጥሩን ሠብሯልና\nበአነገበው መስቀል አምላኩን ገለጸ\nየድል በፍታን ለብሶ ጭፍሮቹን ገሠጸ\n\nበይድራስ ተራራ ቅኔን ያስተማረ\nድንቅ ነው አጥንቱ በሐይል የከበረ\nታምራቱ በዝቶ ገድሉን ደመደመ\nበጸጋው ቃል ኪዳን ትውልዱን ጠቀመ', 'am', 29, 0),\n(4, 'ምህረት ከአምላክህ', 'ምህረት ከአምላክህ\nገና ሕፃን ሳለህ ጌታ መርጦሀል\nተክለ ሐይማኖት ክብር ይገባሀል\nኢትዮጲያ ሀገርህን አትተዋት\nምረት ከአምላክ ለምንላት\n\nአንተ የደከምክበት ተክለ ሐይማኖት\nያ መልካም አዝመራ ተክለ ሐይማኖት\nእንክርርዳድ ሞላበት ተክለ ሐይማኖት\nተክለ ዓብ ቶሎና ተክለ ሐይማኖት\nአውሬው ሰልጥኖብን ተክለ ሐይማኖት\nተፍገምግመናል ተክለ ሐይማኖት\nተክልዬ አትተወን ተክለ ሐይማኖት\nከአምላክ አስታርቀን ተክለ ሐይማኖት\n\nየምንኩስናውን ተክለ ሐይማኖት\nተግባሩን የፈፀምክበት ተክለ ሐይማኖት\nጦኦታትን ሰበረ ተክለ ሐይማኖት\nጠላትን ያሳፈርክ ተክለ ሐይማኖት\nዛሬ በእኛ ጊዜ ተክለ ሐይማኖት\nክደቱ በርትቷል ተክለ ሐይማኖት\nመንጋን የሚጠብቅ ተክለ ሐይማኖት\nአባት ያስፈልጋል ተክለ ሐይማኖት\n\nገልድት ታምራቷን ተክለ ሐይማኖት\nንቀው ሲያቃልሉ ተክለ ሐይማኖት\nስርአቷን ጥሰው ተክለ ሐይማኖት\nእናድሳት ሲሉ ተክለ ሐይማኖት\nለአንዲቷ ሐይማኖት ተክለ ሐይማኖት\nለቀደመቺቱ ተክለ ሐይማኖት\nመከታ ሁንላት ተክለ ሐይማኖት\nዛሬም እንደ ጥንቱ ተክለ ሐይማኖት\n\nተኩላ ቤት ገብቶ ተክለ ሐይማኖት\nከበጎች መሀል ተክለ ሐይማኖት\nክህደቱን ሲያስተምር ተክለ ሐይማኖት\nሕዝብን ሲያታልል ተክለ ሐይማኖት\nዘመኑን ምሰሉ ተክለ ሐይማኖት\nእያለ ሲያባብል ተክለ ሐይማኖት\nቶሎ ድረስልን ተክለ ሐይማኖት\nአንተ ዝም አትበለን ተክለ ሐይማኖት', 'am', 30, 0),\n(4, 'አይነ ከርም', 'አይነ ከርም\nአይነ ከርም መጥቼ ሳየው\nዮሐንስ ብቻውን ነው ያለው\nከቶራ ወተት እየጠባ\nአደገ በዚያ በበረሃ\n\nከዕቃ ቤቱ ከመቅደሱ መሃል\nካህኑ ዘካርያስ ታርዷል\nኤልሳቤጥ ዮሐንስን ይዛ\nተሰደደች ብቻዋን ተጉዛ\n\nሲጣራ በህጻን አንደበቱ\nአትሰማም አርፋለች እናቱ\nሲርበው ጡቶቿን ይጠባል\nማረፏን ዮሐንስ መቼ አውቋል\n\nጌታ ኢየሱስ ከእናቱ ጋር ሆኖ\nመጣለት ደመናን ተጭኖ\nዮሐንስ ፈራ ተሸሸገ\nአያውቅም ሰው ብቻውን ነው ያደገ\n\nድንግል ማርያም ዮሐንስን ልትወስድ\nለመነች ልጇ ልታስፈቅድ\nጌታም አላት በረሃ ነው የሚያድገው\nስራውም መንገድ ጠራጊ ነው', 'am', 31, 0),\n(4, 'ፍቁረ እግዚእ ዮሐንስ', 'ፍቁረ እግዚእ ዮሐንስ\nፍቁረ እግዚእ ዮሐንስ\nምስክሩ ነህ የኢየሱስ\nባማረው ቃልህ ልቤን አድስ\n\nጌታ የሚወደው ትሁት ወንጌላዊ\nምድራዊ አይደለ ክብሩ ሰማያዊ\nበወንጌል የተካ የአሣውን መረብ\nአደገ በፊቱ ተሞልቶ በጥበብ\n\nወንጌል ናት ሕይወቱ የተሰወረባት\nበርሷ እየነደደ ለአለም ያበራባት\nተነጥፎ ያነባ በአምላኩ ፍቅር\nሳለው በውስጣችን የወንጌልን ክብር\n\nየአይሁድ ጭካኔ ቢወራ ቢነገር\nከእራት ብቻ አይደለም ቀራንዮም ነበር\nፊቱን አላዞረም በዚያች የጭንቅ ቀን\nዮሐንስ አልቻለም በጌታው መጨከን\n\nአምደ ቀራንዮ ከአስራ ሁለቱ አንዱ\nአስራ አንዱ ሸሽተው በመንገድ ሲሄዱ\nዮሐንስ ነው ስሙ ጅራፍ ያላሸሸው\nየክርስቶስ ፍቅር ውስጡን ያሸነፈው\n\nከአይሁድ ዛቻ ይልቅ ፍቅሩ ይሰማዋል\nገዳዮቹን ሊያድን ለሚሞተው አዝኗል\nእንዲህ ያለ ፍቅር ለማንም የለውም\nአለና ጻፈለት ብዕር ባይችለውም', 'am', 32, 0),\n(4, 'የተክለ ሀይማኖት ፍቅሩ አደረብኝ', 'የተክለ ሀይማኖት ፍቅሩ አደረብኝ\nየተክለ ሀይማኖት ፍቅሩ አደረብኝ\nገድሉ ተአምራቱን እያሳየኝ\n\nአባ ተክለ ሀይማኖት በገድል በትሩፈቱ\nአባ ተክለ ሀይማኖት አጋንንት ይፈርዳል\nአባ ተክለ ሀይማኖት በተጠራህበተ\nአባ ተክለ ሀይማнот መመኪያ ሆነሀል\nአባ ተክለ ሀይማኖት የእኛ አማላጅ\nአባ ተክለ ሀይማኖት እናከብርሀለን\nአባ ተክለ ሀይማኖት ልጆችህበአዋጅ\n\nአባ ተክለ ሀይማኖት መብረቅም ፅሀይም\nአባ ተክለ ሀይማኖት ቢሆኑም አይመስሉህም\nአባ ተክለ ሀይማኖት ክብርህም ከፍ አድርጓል\nአባ ተክለ ሀይማኖት ጌታ መድኃኔዓለም\nአባ ተክለ ሀይማኖት እኔስ አባት አለኝ\nአባ ተክለ ሀይማኖት ተክለ ሀይማኖት\nአባ ተክለ ሀይማኖት በድካም የሚያነሳኝ\nአባ ተክለ ሀይማኖት ከወደኩበት\n\nአባ ተክለ ሀይማኖት እጨጌ ፊሊጶስ\nአባ ተክለ ሀይማኖት መንበርህ ተከፍቶ\nአባ ተክለ ሀይማኖት ካንተ የተማረውን\nአባ ተክለ ሀይማኖት አይተናል አስፈፍቶ\nአባ ተክለ ሀይማኖት ድንቅ ነገር አየሁ\nአባ ተክለ ሀይማኖት ደብረ ሊባኖስ\nአባ ተክለ ሀይማኖት እርጥብ እንጨት ነዶ\nአባ ተክለ ሀይማኖት ደዌ ሲፈውስ', 'am', 33, 0),\n(4, 'ተነግሮ የማያልቅ', 'ተነግሮ የማያልቅ\nተነግሮ የማያልቅ ነው ፀጋህ\nበፀሎት የተጋህ የሀይማኖት ፍሬ\nተክለ ሀይማኖት የእምነቱ ገበሬ\n\nበወንጌሉ ብርሀን ህዝቡን የመራከው\nየሀጥያትን ባህር ከፍለ ያሻገርከው\nኢትዮጵያዊ ሙሴ በመስቀል ባርከን\nፍሬ እንድናፈራ ንፁ ዘር አድርገን\n\nአዲስ ሀዋሬያ አባ ተክለ ሀይማኖት\nመንአል ያስተማከን ለክርስቶስ መንግስት\nፀበል እንዲምረን ውረድ መሀላችን\nበእጣኑ መአዛ ይፈወስ ደውያችን\n\nለማጠን የበቃ የስላሴን መንበር\nሰይጣን ከቶም አይደርስ ከሄድክበት አገር\nለህሙማን ሁሉ የሆንካቸው ፈውስ\nጠብቀን ተክልዬ በስጋም በነፍስ\n\nበጣም የበዛ ነው ትሩፋት ምግባርህ\nፀሎትን ያልተው ከው ቢቆረጥ አንድግር\nምራፈ ቅዱሳን የወንጌል ገበሬ\nእኛንም አድነን ከዚህ አለም አውሬ', 'am', 34, 0),\n(4, 'ዑራኤል ደረሰ', 'ዑራኤል ደረሰ\nዑራኤል ደረሰ መጣ እረዳቴ\nያሰብኩት ተሳካ ደረሰ ስለቴ\n\nኡራኤል ደረሰ በአለም ፈተና\nጀዌ ፀንቶ ብኝ\nየጠፋችውን ነፍሴን\nሰላም ሊሰጠን\nየአምላክ ባለሟል\nየምረት አባት\nእረፍትን ሰቶኛል\nመራዬ ድነት\n\nኡራኤል ደረሰ ታላቅ ስልጣን ያለህ\nበጌታ መንበር ፊት\nአድነኝ ኡራኤል\nጎብኘኝ በበረከት\nበስምህ ተማፅኖ\nበታምራትህ\nምረት ታሰጣለህ\nመላከ ሰላም\n\nኡራኤል ደረሰ የሀጥያት ቀንበር\nሲከብደኝ ስጨነቅ\nምኞት ሲበዛብኝ\nፈተና ሲያሳምመኝ\nበጨለማ እንዳልወድቅ\nየመላክት አለቃ\nአንተው ብርታት ሁነኝ', 'am', 35, 0),\n(4, 'የተሰጠ ክብር', 'የተሰጠ ክብር\nየተሰጠክብር ግሩም ተክለ ሀይማኖት አቡነ\nተማፅነናል ባንተ በእውነት\nየወንጌል መምህር የፅድቅ አባት ነህ\n\nበገድልህ ብትፀና ተክለ ሀይማኖት\nበፆም በፀሎት\nክንፍን ተጎናፅፈክ\nእንደ መላእክት\nስምህን ስንጠራ\nበፍቅርህ ተጠምደን\nፃድቁ አባታችን\nመተህ እኛን ባርከን\n\nድንቅ እኮነው ምርጫው ተክለ ሀይማኖት\nየተክለሀይማኖት\nየፈፀመው ገድል\nያሳየከው ፅናት\nለአምላክ ያለውን\nእውነተኛ ፍቅር\nገለጠው በህይወት\nበታላቅ እምነት\n\nኢትዮጵያ እልል በይ ተክለሃይማኖት\nእጅግ ደስ ይበልሽ\nየእግዚአብሔር አገልጋይ\nየፅድቅ አባት አለሽ\nምልጃው የሚረዳኝ\nበክንፉ ከልሎኝ\nበችግር ግዜ\nፈጥኖ የሚረዳኝ', 'am', 36, 0),\n(4, 'ብሩሁ ኮከብ', 'ብሩሁ ኮከብ\nብሩ ኮከብ ለኢትዮጲያ ያበራህ\nበወንጌል ቃል መልካሙን ዘር የዘራህ\nተክለ ሐይማኖት ትሩፍትህ\nከእኛ ጋር አለ በረከትህ\n\nጭንቻ ልባችንን በካሉ ነክተሀው\nየኃጢያት ክምር መሠረቱን ናድከው\nባጠጣህን ውሀ ይሀው ለመለምን\nአንተን የሰጠንን አምላክ አከበርን\n\nአለምን ያሸነፍከ ሆነህ በትትና\nለክርስቲያን ወገን አርአያ ነህና\nለፃድቅ ህያው ሆነህ ለኃጢአት ሞተሀል\nየእምነት እሩጫ በድል ፈፀምሀል\n\nየቃልኪዳን ጥላ ጋርዶን ከመከራ\nወደፊት ተጎዝን እንቅፍት ሳንፈራ\nበሀይማኖት ፀንተህ ቆመ ከጉናችን\nእረፍት አግኝተናል በአንተ አማላጅነት\n\nበእሳትና ውሃ መካከል አልፈሀል\nየወንጌልን እውነት በድል መስክረሀል\nፆምና ፀሎትህ ጉልበት አለው\nአይተናል በአይናችን የዛለው ሲቃና', 'am', 37, 0),\n(4, 'መምህረ ወንጌል', 'መምህረ ወንጌል\nመምህረ ወንጌል ምክሐ ምዕመናን\nከሳቴ ብርሃን ሰላማ ከሳቴ ብርሃን\nገናና ስሙን ልትሸከም\nየጠራህ መድኃኔዓለም\n\nፈጣሪ የላከህ ለድኅነታችን\nዓምደ ሃይማኖት ብጹዕ አባታችን\nየወንጌል አርበኛ ሐዋርያ\nሁሌም ታነሳለች ስምህን ኢትዮጵያ\n\nኢትዮጵያን ርስትህ አድርገህ\nለስብከተ ወንጌል በስደት መኖርን መርጠህ\nስላመጣህላት ሥርዐተ ክህነትን\nታወድስሃለች አሐቲ ቤተክርስቲያን\n\nእንደ ጳውሎስ ሐዋርያ\nእንደ ማርቆስ መምህር ዘእስክንድርያ\nደግሞም እንደ ጴጥሮስ መምህረ ሐዲስ\nክብርህ ከፍ ያለ ነው አባ ፍሬምናጦስ', 'am', 38, 0),\n(4, 'ካድ ይሉኛል', 'ካድ ይሉኛል\nእያየሁህ በቀኙ ቆመህ\nካድ ይሉኛል አሁን ሳንገልህ\nተቀበላት ነብሴን በሰማይ\nወርዶብኛል የአይሁድ ድንጋይ\n\nከሰው እንዳሎነ ሲያውቅ ልቦናቸው\nይወግሩኝ ጀመረ በሞት አስፈራርተው\nኢየሱስ ክርስቶስ ጉልበት አምባዬ ነው\nከእርሱ ጋር እያለሁ እንዴትሞትንልፍራው\nየድንጋዩ ናዳ ምንም አልተሰማኝ\nጌታዬን በክብር ሳየው እሱም ሲያየኝ\nከሰባቱ ዲያቆናት መሃል\nአንዱ መሆን አቤት መታደል\nጥበብና ሞገስን ሰቶኛል\nያባቶቼ በረከት ባርኮኛል\nያባቶቼ አምላክ ጠብቆኛል\n\nእንድትሰባ አስበው ትምርተ ኦሪት\nእንድጠፋ ደሞ የወንጌል ብስራት\nአንዱን ጌታ በግፍ ሲገሉ በስቅለት\nመቶ ሃያ ሆነው ተነሱ ለስብከት\nየድንጋዩ ናዳ ምንም አልተሰማኝ\nጌታዬን በክብር ሳየው እሱም ሲያየኝ\nሊቀ ዲያቆን እስጢፋኖስ ገድለው\nክርስትናን ሊያጠፉ አስበው\nስምንት ሺው ባለም ተበተኑ\nኢየሱስን ስሙን አገነኑ\nክርስቶስን ስሙን አገነኑ\n\nከከተማ ውጪ በአፋ አውጥተው\nልብሳቸውን ሁሉ ለጎልማሳው ሰተው\nቋጥኝ የሆነውን ድንጋይ እያነሱ\nሰባበኑት ያኔ አጥንቴን ስለ እርሱ\nየድንጋዩ ናዳ ምንም አልተሰማኝ\nጌታዬን በክብር ሳየው እሱም ሲያየኝ\nሕያው ብሆን ብሞትም ለጌታ\nክርስትና አትጠፋም ላፍታ\nእንሰብካለን ባጥንት በደማችን\nኢየሱስ ነው ፈጣሪ አምላካችን\n\nእንዳትሰብኩ ቢሉን ወታችሁ ሰገነት\nሐሰትን አንሰማም ስንታዘዝ ለውነት\nአብዝተው ሲመቱት ይጠብቃል ሚስማር\nያፀናል መከራ ያደርሳል በክብር\nየድንጋዩ ናዳ ምንም አልተሰማኝ\nጌታዬን በክብር ሳየው እሱም ሲያየኝ\nቢበተንም የእስጢፋኖስ ማህበር\nሊበዛ ነው የክርስቲያን ቁጥር\nአትደንግጡ ደቀ መዛሙርቱ\nቶሎ ያልፋል ወጀቡም ትምክቱ', 'am', 39, 0),\n(4, 'ገብረ መንፈስ ቅዱስ', 'ገብረ መንፈስ ቅዱስ\nገብረ መንፈስ ቅዱስ የዓለም ብርሃን ናቸው\nይህው ለዘላለም ያበራል ስራቸው\n\nነቅዓ በረከት ነህ ገብረመንፈስ ቅዱስ\nየፅድቅ ሐዋርያ የኢየሱስ ክርስቶስ\nመልአኩ ገብርኤል መንገድ እያሳየ\nበተጋድሎ ዘመን ካንተ መች ተለየ\n\nበእግዚአብሔር ተመርጠህ ገና በማህፀን\nገብረ መንፈስ ቅዱስ ፃድቁ አባታችን\nየእናት የአባትህ ምልጃ እና ልመና\nፍፃሜን አገኘ አንተን ወለዱና\n\nተጋድሎ ድንቅ ነው ፅንሰቱ ልደቱ\nበእግዚአብሔር ፊት ክቡር ነው እረፍቱ\nምድራዊውን ምግብ አንዳች አልቀመሰም\nበሰው ያልተሰፋ ልብስም አለበሰም\n\nገብረ መንፈስ ቅዱስ ያበራል ተጋድሎው\nኃይልንም ያደርጋል ፀሎት እና ምልጃው\nአናብስት አናብርት እየተከተሉ\nከእግሮቹ ትቢያ በልተው ይጠግባሉ\n\nዛሬም በእኛ ዘመን በእምነት በፀበሉ\nከህመሙ አልጋ ስንቶቹ ቀና አሉ\nከአምላክ የተሰጠው ቃልኪዳኑ ፅኑ\nበረከት ያድላል በምልጃው ላመኑ', 'am', 40, 0),\n(4, 'እፁብ ነህ ዳንኤል', 'እፁብ ነህ ዳንኤል\nእፁብ ነህ ዳንኤል ማረከኝ እምነትህ\nከአንበሳ መንጋጋ ከሞት ያተረፈህ\n\nእፀናለሁና በነፍሴ ስደክም\nህይወትህ ማረከኝ በርትቼ እንድቆም\nየሃይማኖት ጉዞ ሁሌ አይለሰልስም\nበርታ ጉልበቴ ሆይ መንገድ እንዳትደክም\n\nበጾምና ጸሎት ፊትህ እየበራ\nእምነትህ ተገልጿል በብርቱ መከራ\nበእግዚአብሔር መታመን ሞኝነት አይደለም\nተረድታለች ነፍሴ ይህን ለዘለዓለም\n\nወደምስራቅ ዞረህ ወደሰማይ ስታይ\nየእግዚአብሔር ፀጋ በራ ባቢሎን ላይ\nይታየኛል ዓለም መስኮቴን ስከፍት\nአይኔን ፈውስልኝ ክብርህን ልይበት\n\nዓለምና ክብሯን ወድጃለሁና\nይሄ ክፉ ሥጋ ይስበኛልና\nእንደ ሻማ ልብራ በጨለማ ዓለም\nየዳንኤል አምላክ ደግፈኝ ዘለዓለም', 'am', 41, 0),\n(4, 'ማርቆስ ወንጌላዊ', 'ማርቆስ ወንጌላዊ\nማርቆስ ወንጌላዊ ሐዋርያ\nለግብፅ ወኢትዮጵያ\nማርቆስ ወንጌላዊ ሐዋርያ\n\nግብፅን አቀናሃት ወንጌል ዘራህባት\nየክርስቲያን ሃገር መንበር አደረግሃት\nተሰምቷል ገድልህ ዝናህ በአህጉር\nበምድረ ኢትዮጵያም ከዳር እስከዳር\n\nእንደ ወንጌል ልጅህ እንደ እስክንድርያ\nአባቷ ነህ ማርቆስ ለኢትዮጵያ\nከነጣቂ ተኩላ ሐዝቧን ጠብቅላት\nእንዳሳፈርሃቸው የግብፅን ጣዖታት\n\nጴጥሮስ በክታቡ ልጄ ማርቆስ ያለህ\nለመልእክት መብቃትህን ጳውሎስ ያመነብህ\nከሐዋርያት ጋር ረዳት ሆነህ\nቃለ ክርስቶስን ዞረህ ያስተማርህ\n\nባላመኑት ፊት ስሙን መስክረህ\nየኢየሱስ ክርስቶስ ሰማዕቱ ሆነህ\nወንጌልን የሰበክህ መከራን ሳትፈራ\nአንበሳው ማርቆስ ኢትዮጵያን አደራ', 'am', 42, 0),\n(4, 'ኮብላዩ ነቢይ', 'ኮብላዩ ነቢይ\nስለወደድከኝ አዳንከኝ አንተ\nከአሳ ነባሪው ሆድ ከጥልቁ አውጥተህ\nኮብላዮ ነብይ መባል ይብቃኝ\nአንተን ወዳጄ ለክብር አበቃኝ\n\nጌታዬ የአንተን ቤት እቅፍህን ትቼ\nሰላሜን አጣሁኝ ከአንተ ተለይቼ\nየማላወራው ብዙ ደርሶብኛል\nአምላኬ ይብቃኝ ቤትህ ይሻለኛል\n\nወደተርሴስ ስጓዝ ከፊትህ ኮብልዬ\nለአንተ ለጌታዬ አልታዘዝ ብ\nመንገዴን ሁሉ በንፋስ አጠርከው\nድንቅ ነህ በእውነት ሆኗል አንተ ያልከው\n\nእንደ ንስር ሆኜ ወደላይ ብወጣ\nወደ ጥልቁም ብወርድ ላመልጥ ብቃጣ\nአልቻልኩም ፍጹም አሸንፈኸኛል\nመክረህ ገስህ ያንተ አድርገኸኛል', 'am', 43, 0),\n(4, 'የሚያስፈራኝ ማነው', 'የሚያስፈራኝ ማነው\nየሚያስፈራኝ ማነው የሚያስደነግጠኝ\nየእግዚአብሔር አገልጋይ ጊዮርጊስ ሳለልኝ\n\nፍጡነ ረድኤት ቅዱስ ጊዮርጊስ\nበፀአዳ ፈረስ ወደኔ ገስግስ\nወድቄ አልቀርም አንተ አለኸኝና\nጠላቴም ይፈር ፈጥነህ ወደኔ ና\n\nለተገፋ ሰው አዛኝ ነው ልብህ\nእንደ ማርያም እንደ እመቤትህ\nበሰማይ በምድር ክብርህ የበዛ ነው\nይህንን ዓለም ስላሸነፍከው\n\nታማኝ ምስክር ስለ ሥላሴ\nክብሩዋ ነህ አንተ ዛሬም ለነፍሴ\nየልቤን ሀዘን ቀርቤ ሳዋይህ\nፈጥነህ አርቀው መጽናኛዬ ነህ\n\nየአደራ ልጅህ አገልጋይህ ነኝ\nስምህን ስጠራ ክፉ የሚርቀኝ\nጠላቴ እንዳይስቅ ጥሎኝ እንዳይኮራ\nበቀን በሌሊት ጠብቀኝ አደራ', 'am', 44, 0),\n(4, 'በፍፁም ምግባሩ', 'በፍፁም ምግባሩ\nበፍፁም ምግባሩ የፀና በእምነቱ\nለዓለም የተረፈ ታላቅ በረከቱ\nመድኃኒት የሆነ ለነፍስም ለሥጋ\nአባ ተክለ ሃይማኖት ባለብዙ ፀጋ\n\nወንጌልን ሰባኪ ትሁት አስደናቂ\nፈዋሽ መድኃኒት ነህ ከአምላክ አስታራቂ\nምልጃና ፀሎትህ ተሰሚ ነውና\nምህረትን አሰጠን ለምንልን ለኛ\n\nየጠፉትን በጎች ወደ አምላክ ሊመልስ\nከሃገር ሃገር ዞሮ ወንጌልን ሊያዳርስ\nየቀናውን መንገድ መርቶ እያሳየ\nስንዴውን ከእንክርዳድ በትምህርቱ ለየ\n\nሰማዕት ሐዋርያ ተብለህ ተጠርተሃል\nሁሉን አስተባብረህ በእምነት ሠርተሃል\nጣዖታት ሰባብረህ ጠላትን ያሳፈርክ\nስለተዋህዶ መከራን የታገስክ\n\nለደብረለባኖስ መቀደሻዋ ነህ\nለአስቦ ዋሻህም ክብርና ጌጧ ነህ\nየከበረ ሥጋህ በርሷ አልፏልና\nበረከት የሚሹ ይመጣሉ ገና\nክብር የገባቸው ይመጣሉ ገና', 'am', 45, 0),\n(4, 'ፀበልና እምነትህ ቅዱስ ዮሐንስ', 'ፀበልና እምነትህ ቅዱስ ዮሐንስ\nፀበልና እምነትህ ፍጥረትን ያዳነ\nመጥምቁ ዮሐንስ ስምህ የገነነ\nድውያኑ ሁሉ ወደአንተ ገስግሰው\nድኅነት አግኝተዋል በእጆችሁ ተዳሰው\n\nዝናህን ሰምቼ ብመጣ ከደጅህ\nአንካሶችን አየሁ ቆመው በተአምርህ\nያመነብህ ሁሉ ተመልሷል ድኖ\nየለምፃሙም አካል እንደ ቀድሞ ሆኖ\n\nጉልበቱ የላላ ህመም የፀናበት\nተፈውሷል ደጅህ ፀበልህ ፈሶበት\nበእምነትህ ተሻሽቶ እረግፏል ቁስሉ\nእጅህ የዳሰሰው ታድሷል አካሉ\n\nታላቁን ስምህን በእምነት ተጣርተው\nድነዋል ብዙዎች ባንተ ስም ተጠምቀው\nአፍሮ አልተመለሰም ደጅህ የወደቀ\nበእምነት ተጠግቶህ አንተን የጠበቀ\n\nቁስሉን የሻርክለት በእንባ ሲያወድስህ\nአይቻለሁ በዓይኔ ቆሜ ከደጃፍህ\nየእጣኑ መአዛ ከመቅደሱ ሽቶ\nደስታን ተከልክለው ሀዘን ተለይቶት', 'am', 46, 0),\n(4, 'የቤሩቱ ኮከብ', 'የቤሩቱ ኮከብ\nየቤሩቱ ኮከብ የልዳው አንበሳ\nሶስት ጊዜ ሞቶ ጊዮርጊስ ተነሳ\n\nበተጋድሎ ጸና ቅዱስ ጊዮርጊስ\nበእውነት መሰከረ ቅዱስ ጊዮርጊስ\nሀያሉ ጊዮርጊስ ቅዱስ ጊዮርጊስ\nበሰይፍ ተመተረ ቅዱስ ጊዮርጊስ\nየልዳው አንበሳ ቅዱስ ጊዮርጊስ\nጠላት አይገዛህ ቅዱስ ጊዮርጊስ\nሰይጣንን ተዋጋው ቅዱስ ጊዮርጊስ\nጎልማሳው ስጋህ ቅዱስ ጊዮርጊስ\n\nድዳኖስ ተቆጣ ቅዱስ ጊዮርጊስ\nፅናትህን አይቶ ቅዱስ ጊዮርጊስ\nሊቀጣ ተነሳ ቅዱስ ጊዮርጊስ\nበትቢት ተሞልቶ ቅዱስ ጊዮርጊስ\nባንተላይ ወገኑ ቅዱስ ጊዮርጊስ\nሰባ ነገስታት ቅዱስ ጊዮርጊስ\nከምድረ ገፅ አንተን ቅዱስ ጊዮርጊስ\nፍፁም ለማጥፋት ቅዱስ ጊዮርጊስ\n\nበመበለቶ ቤት ቅዱስ ጊዮርጊስ\nጊዮርጊስ ታምር ሰራ ቅዱስ ጊዮርጊስ\nምሶሶ አለምልሞ ቅዱስ ጊዮርጊስ\nእውራን አበራ ቅዱስ ጊዮርጊስ\nሰባት አክሊላትን ቅዱስ ጊዮርጊስ\nጊዮርጊስ ተቀበለ ቅዱስ ጊዮርጊስ\nስለ ጌታ ፍቅር ቅዱስ ጊዮርጊስ\nባደባባይ ዋለ ቅዱስ ጊዮርጊስ\n\nዝክርህን ዘክሮ ቅዱስ ጊዮርጊስ\nስምህን የጠራ ቅዱስ ጊዮርጊስ\nበነብስም በስጋ ቅዱስ ጊዮርጊስ\nየለበት መከራ ቅዱስ ጊዮርጊስ\nድራገንን አጥፋ ቅዱስ ጊዮርጊስ\nአርቅልን ከኛ ቅዱስ ጊዮርጊስ\nበዝሙት በሀጥያት ቅዱስ ጊዮርጊስ\nደርሶብናልና ቅዱስ ጊዮርጊስ', 'am', 47, 0),\n(4, 'ጽኑ ሰማዕት', 'ጽኑ ሰማዕት\nጽኑ ሰማዕት የእምነት አርበኛ\nአርሴማ ነይ ነይ ወደኛ\n\nነይ ነይ ቅዱስ አትናትዮስ\nነይ ነይ በስዕለት ያገኙሽ\nነይ ነይ ብሉይን ከሀዲስ\nነይ ነይ ጠንቅቀሽ የተማርሽ\nነይ ነይ በፍፁም ትህትና\nነይ ነይ በጸሎት የተጋሽ\nነይ ነይ አርሴማ ልዩ ነሽ\nነይ ነይ አምላክ የመረጠሸ\n\nነይ ነይ ውበትም ሀሰት ነው\nነይ ነይ ደም ግባትም ከንቱ\nነይ ነይ ንብረት ትዳር ሁሉ\nነይ ነይ አላፊ ውዕቱ\nነይ ነይ ንግስት መባልን\nነይ ነይ በፍጹም ሳትሻ\nነይ ነይ አለምን በመናቅ\nነይ ነይ ገባች ወደዋሻ\n\nነይ ነይ አረመኔው ድርጣድስ\nነይ ነይ ቢያሰቃይሽም\nነይ ነይ ውበቴ ክርስቶስ\nነይ ነይ ነው ብለሽ ሰበክሽ\nነይ ነይ አንገትሽን ለሰይፍ\nነይ ነይ አሳልፈሽ ሰጠሸ\nነይ ነይ ክብርሽም ተገልጾ\nነይ ነይ ለአለም አበራሽ\n\nነይ ነይ አርአያ ልትሆኝን\nነይ ነይ ለእኛ ለሁላችን\nነይ ነይ ፈፅመሽ አሳየሽ\nነይ ነይ ታላቅ ተጋድሎሽን\nነይ ነይ ይህን አለም ድል መንሳት\nነይ ነይ አቅቶናል እና\nነይ ነይ አርሴማ አትለይን\nነይ ነይ በእምነት እንድንጸና', 'am', 48, 0),\n(4, 'ምስክርነቱን ገለጻ', 'ምስክርነቱን ገለጻ\nምስክርነቱን ገለጻ ቂርቆስ ህጸን\nበእሳት ተፈትኖ አለፈ ፈተናውን\nበእሳት ተፈትኖ አለፈ\nፈተናውን ደስ ይበለን\n\nቂርቆስ ኢየሉጣ ሁለቱም\nበአንድ ልብ ምንኛ ጨከኑ\nተቃቅፈው ሲገቡ ወደ እሳት ጋኑ\n\nህጻኑና እናቱ በእሳት ውስጥ\nሲዋኙ ያለ ምንም ፍርሃት\nገብርኤል ተላከ እነርሱን ለማውጣት\n\nበርዶ ቀዝቅዞ የእሳቱ\nነበልባል በጌታችን መስቀል\nሁሉቱም ስማእታት ተጎናጸፋ ድል', 'am', 49, 0),\n(4, 'ሐዋርያው መነኩሴ', 'ሐዋርያው መነኩሴ\nሐዋርያው መነኩሴ የመረጡህ ሥላሴ\nዋስ ጠበቃ ሁናት ተክልዬ ለነፍሴ\n\nዳሞት ትናገረው የአንተን ሐዋርያነት\nየወንጌል ገበሬ የጣኦታት ጠላት\nጸሎተኛው ቅዱስ አባ ተክለሐይማኖት\nክንፍን የተሸለምክ እንደ ሰማይ መልአክ\n\nብራናው ሲገለጽ ገድለ ተክለሐይማኖት\nከሰወ ልጅ ልቦና ያወጣል አጋንት\nየቅዳሴው ዕጣን ሲወጣ ከዋሻው\nምድርን ይባርካል ጸሎቱ ምህላው\n\nየኢትዮጵያን ምድር አርስከው በወንጌል\nጭንጫው ፈራረሰ ተዘራበት ወንጌል\nትላንት የዘራኽው ዛሬ ለእኛ ሆኗል\nአምላከ ተክልዬ ብለን ተምረናል\n\nከሱራፌል ተርታ ቆመህ ስታጥን\nቅዱስ ቅዱስ ብለህ ስታመሰግን\nጸሎት ትሩፋትህ ትህትና ስግደትህ\nፆምህ ከፍ አድርጎ ሰማይ አደረሰህ\n\nዛፉ ሲመነገል አምላክ የተባለው\nመቶሎሚ ሲያፍር ትልቅ ሰው ነኝ ያለው\nየተክልዬ ጸሎት ብዙ ነወ ምስጢሩ\nስድስት ክንፍ አወጣ ቢቆረጥ አንድ እግሩ', 'am', 50, 0),\n(4, 'ያንቺን ዝና', 'ያንቺን ዝና\nያንቺን ዝና ያንቺን ክብር\nከቅዱሳን ማኅደር\nስንጠይቅ ስንሰማ\nልዩ ነሽ አርሴማ\n\nከቤተመሳፍንቱ ምቾት ከነገሰበት\nተጠርተሻል አርሴማ ለማይሻረው ሕይወት\nየሥጋ ጦማር ስለወደቀ ከልቦናሽ\nበደም ተፃፈ ዜና እረፍትሽ\n\nከአትናስያ ደስታ ከቴዎድሮስ መፅናናት\nተሻግሯል ያንቺ ዝና ትውልድ እንዲማርበት\nለገብረ ፃድቅ ለዓለሙ ሁሉ ለዘላለሜ\nቅድስት አርሴማ ነይ በሰላሜ\n\nበአርማንያ ንጉሥ ትእዛዝ አለ ተላልፎ\nጤልሜዎስን ሳትፈሪ እምነትሽ ታየ ገዝፎ\nመስተጋድሉን ሰማዕታቱን ነፍስሽ ተጣምራ\nበሠገነት ላይ ገድልሽ አበራ\n\nሰይጣን ተንቀጠቀጠ በስምሽ ሀይሉን አጣ\nየደዌ ጉልበት ታጥፎ የፈውስ ፀሀይ ወጣ\nየእጅሽ ዘንባባ ነክቶናልና አናቃስትም\nቃልኪዳን ሰጠሽ መድኃኔዓለም', 'am', 51, 0),\n(4, 'የዝቋላው ኮከብ', 'የዝቋላው ኮከብ\nየዝቆላው ኮከብ መፋቀሬ ፀሎት ወፆም\nገብረ መንፈስ ቅዱስ እንቁ ለገዳም\nቅረበነ ና በሰላም\n\nእንደ ሰው አይደለም ኑሮነው የመላእክት\nትጉህ መሰተጋድል ገዳማዊ መብራት\nስም የከበረ በፈጣሪ አንደበት\nየገድልህ መዓዛ እንደ ዕጣን የሚሸት\n\nየእሱን ቅድስና ዝቆላ መሰክሪ\nእንደዓሳ በባህረ ኖረ ብለሽ አውሪ\nኢትዮጲያ ትናገረ ያንተን ታላቅነት\nልጆቾን በፀሎት ለምነ ያስማርክላት\n\nበእጅጉ ይበልጣል ከአለም ሁሉ ዜና\nገድልህን ማዳመጥ በእምነት በትህትና\nገብረ መንፈስ ቅዱስየአምላክባለሞሉ\nስምህን በማሰብ ስላንተ ይማራል\n\nጠልፎ ከሚጥለን ሰይጣን መሰናክል\nባንተ አማላጅነት ለማለፋ እንድችል\nአማልደን ስንል ፈጥነ ድረሰልን\nከመውደቅ አድነን በድጋፋ አፅናን', 'am', 52, 0),\n(4, 'አበው ጸልዩ', 'አበው ጸልዩ\nአበው ጸልዩ በእንቲአነ\nጸሎትክሙ ይባርከነ\n\nየቅዱሳን ጸሎት የአባቶች ልመና\nፍቅርና ሰላምን አስገኝቷልና\nየሕዝቦች ስብራት ስለጠገናችሁ\nየቅድስት ኢትዮጲያ አዕማድ ሆናችሁ\nመሠረት ሆናችሁ\n\nየመንፈሱን ድርቀት እንድታስወግዱ\nአባቶች ጸልዩ\nበሐዋርያት ወንበር የተቀመጣችሁ\nሕዝቡን አገልግሉ በመንፈስ ሆናችሁ', 'am', 53, 0),\n(4, 'ነህምያ ነኝ', 'ነህምያ ነኝ\nነህምያ ነኝ ሀገሬን ልስራ\nጦርብያጥልባ ራስ ዝም ብለህ ስማ\nወገኔ ሁሉ እንተባበር ይሰራልናል የቸሩ እግዚአብሄር\nእኛም ባሪያዎችህ እንደክማለን\nየሰማይ አምላክ አከናውንልን\nቁሙ በእምነት ትጉ በጸሎት\nይሰራልናል የቸሩ አባት\n\nየተክለሀይማኖት ትውልድ ሀገር\nፈርሷል ነገሩኝ የሀገሬ ቅጽር\nተቃጥሏል አሉኝ ዙሪው በሮቿ\nጎርፍ ወስዷቸዋል ምስኪን ልጆቿ\nበድለናል እኔና አባቴ ቤት\nለምኝልን ድንግል የአምላክ እናት\nመኃሪ ነው ጌታ ሆይ ስምህ\nይቅር በለን በቃል ኪዳንህ\n\nቅድስት ሀገር ናት ሁሉ ያላት\nከልዑል አባት የተሰጣት\nእጇን ዘርግታ ወደ እግዚአብሄር\nትለምን ነበር ቀድሞ በፍቅር\nማዶ ነው ያለው መጣ እኛም ሀገር\nእግዚኦ እንበል እንዲያየን በፍቅር\nስለምነው ቅድስት ክርስቶስ ሰምራ\nተለመነን አምላክ ሆይ አራራ\n\nየካህኑ ደም የዘካርያስ\nዛሬ ፈሰሰ በቤተ መቅደስ\nበእንግድነት ያሳረፍናቸው\nአርደው ነው የጣሉን በእሳት አቃጥለው\nየእግዚአብሄር እጅ በእውነት ትክበዳችሁ\nጎራዴውም ይግባ ከተገባ\nአህዛብም ስላንተ ይመስክር\nከአንተ ሌላ የለም ጌታ እያሉ\n\nየኢትዮጵያ ልጆች ኑ ተሰብሰቡ\nየቀደመውን ፍቅሯን አስቡ\nለ እልፍ ዘመን ያደረሠንን\nእናመስግነዉ አምላካችንን\nእድል ፈንታዬ ኢትዮጵያ\nሁኝልኝ ሣሌም', 'am', 54, 0),\n(4, 'ተነሳ ከኢቲሳ', 'ተነሳ ከኢቲሳ\nተነሳ ከኢቲሳ ዳሞት ገሰገሰ\nደብረ ዳሞ ወጣ ደብረ አስቦ ደርሰ\nበአራቱም ማዕዘን ወንጌል አዳረሰ\nጻድቅ ተክለ ሃይማኖት ኢትዮጵያን ቀደሰ\n\nጸበል አለ ደጁ ድውይ ይፈውሳል\nሰይጣን ዲያቢሎስን ከሰው ልብ ያርቃል\nትንሹም ትልቁም ጸበሉን ይጠጣል\nኃጢአት ባለችበት ጸጋውም ይበዛል\nጻድቅ በጻድቅ ስም ሊቀበል የተጋ\nበእውነት ይቀበላል የጻድቁን ዋጋ\nአባት የእግዚአብሔር ሰው ተቀብዬዋለው\nወር በገባ በሃያ አራት እዘክርዋለው\nበስሙ ለነዳያን ውሃ አጠጣለው\n\nየድሆች መጠጊያ ለነዳያን ተስፋቸው\nበነፍስም በሥጋ የሚመግባቸው\nጻድቅ አባት እርሱ በረከቱ በዝቷል\nኢትዮጵያን ሁሉ እጅግ ይወዱታል\nጻድቅ በጻድቅ ስም ሊቀበል የተጋ\nበእውነት ይቀበላል የጻድቁን ዋጋ\nአባት የእግዚአብሔር ሰው ተቀብዬዋለው\nወር በገባ በሃያ አራት እዘክርዋለው\nበስሙ ለነዳያን ውሃ አጠጣለው\n\nቅድስት ሥላሴን ሕፃኑ አመሰገነ\nካህነ ሰማይ ሆኖ መንበሩን አጠነ\nለስባረ አጽሙ መባን አስገባለው\nልደቱን ፍልሰቱን እረፋቱን አከብራለው\nጻድቅ በጻድቅ ስም ሊቀበል የተጋ\nበእውነት ይቀበላል የጻድቁን ዋጋ\nአባት የእግዚአብሔር ሰው ተቀብዬዋለው\nወር በገባ በሃያ አራት እዘክርዋለው\nበስሙ ለነዳያን ውሃ አጠጣለው', 'am', 55, 0),\n(4, 'በዕምነታቸው ዳኑ', 'በዕምነታቸው ዳኑ\nበዕምነታቸው ዳኑ ከዚያ ነበልባል\nአናንያ አዛርያ ሚሳኤል\n\nናቡከደነፆር ጨካኙ ንጉስ\nበባቢሎን ሀገር ጣኦት የሚያነግስ\nእያለ ስገዱ አማኙን ሲያምስ\nወጣቶች ተነሱ በቅናት መንፈስ\nአናንያ አዛርያ ሚሳኤል\n\nለሰራኸው ጣኦት አንሰግድም እያሉ\nበመንፈስ ቅዱስ ሀይል ልባቸውን ሞሉ\nየፈጠረን አምላክ ያድነናል ሲሉ\nአናንያ አዛርያ ሚሳኤል\n\nነበልባል ነድዶ እንዲያቃጥላቸው\nበጭካኔ መንፈስ አስወረወራቸው\nገብተው ሲፀልዪ እቶን ሳይነካቸው\nመልአኩን ልኮ አበረደላቸው\nገብርኤል በመስቀል\n\nእንደ ሦስቱ ህፃናት በእምነት ለሚቆመው\nመልአኩን ይልካል እግዚአብሔር ሊረዳው\nእሳቱም ይበርዳል መልአኩ ሲነካው\nገብርኤል በመስቀል', 'am', 56, 0),\n(4, 'አምላክ ባከበራት', 'አምላክ ባከበራት\nአምላክ ባከበራት በተክልዬ ደጄ\nበረከት ይገኛል ከፃድቁ እጅ\n\nበመከራ ጊዜ ተክለሀይማኖት\nበችግሯ ቀን ተክለሀይማኖት\nእንደ ደረስክላት ተክለሀይማኖት\nእግዚአርአያን ተክለሀይማኖት\nእኛንም ታድን ዘንድ ተክለሀይማኖት\nአንተ ደግ አባት ተክለሀይማኖት\nመተናል ከደጅህ ተክለሀይማኖት\nከያለንበት ተክለሀይማኖት\n\nካምላክ በተሰጠህ ተክለሀይማኖት\nበቃልኪዳንህ ተክለሀይማኖት\nህሙማን የሚያድን ተክለሀይማኖት\nግሩም ፅበልህ ተክለሀይማኖት\nድዌን የሚፈውስ ተክለሀይማኖት\nየንፍሮ ወሀህ ተክለሀይማኖት\nዘላለም ይኖራል ተክለሀይማኖት\nበአለም ሲያስጠራህ ተክለሀይማኖት\n\nለሀያ ዘጠኝ አመት ተክለሀይማኖት\nተክሎ ጦሮቹን ተክለሀይማኖት\nለኛ ለልጆቹ ተክለሀይማኖት\nተስፋ ለቆረጥን ተክለሀይማኖት\nደከመኝ አላለም ተክለሀይማኖት\nቆሞ ሲለምን ተክለሀይማኖት\n\nየቅድሳን ሀገር ደብረ ሊባኖስ\nደብረ ሊባኖስ ደብረ ሊባኖስ\nታጥራ ትኖራለች ደብረ ሊባኖስ\nበመንፈስ ቅድስ ደብረ ሊባኖስ\nበፃድቅ ፅሎት ደብረ ሊባኖስ\nስለተቀደሰች ደብረ ሊባኖስ\nከአድባራቱ ሁሉ ደብረ ሊባኖስ\nበክብር ትበልጣለች ደብረ ሊባኖስ', 'am', 57, 0),\n(4, 'ሚናስ ሚናስ ይላል', 'ሚናስ ሚናስ ይላል\nሚናስ ሚናስ ይላል አንደበቴ\nአማልዶኛልና ከሰማዩ አባቴ\nሚናስ ሚናስ ይላል አንደበቴ\n\nአምላከ ሚናስ ደስ ይላል\nየሰማዕቱ ልጆች አርጎናል\nሚናስ ይላል ምድርና ሰማዩ\nሚናስ ይላል ተዓምርህን ይንገሩ\nሚናስ ይላል ፍጥረታት በሙሉ\nሚናስ ይላል ለክብሩ ዘምሩ\n\nአምላከ ሚናስ ደስ ይላል\nየሰማዕቱ ልጆች አርጎናል\nሚናስ ይላል ለእምነትህ መቆምህ\nሚናስ ይላል አድርሶሃል ለሞት\nሚናስ ይላል ሲቆረጥ አንገትህ\nሚናስ ይላል ፈሶሀል ደም ወተት\n\nአምላከ ሚናስ ደስ ይላል\nየሰማዕቱ ልጆች አርጎናል\nሚናስ ይላል በሰራኸው መቅደስ\nሚናስ ይላል በረከት ጠገቡ\nሚናስ ይላል አቡነ ሐራ ድንግል\nሚናስ ይላል ቀድሰው ቆረቡ\n\nአምላከ ሚናስ ደስ ይላል\nየሰማዕቱ ልጆች አርጎናል\nሚናስ ይላል ያከበርከው ጌታ\nሚናስ ይላል ከፍከፍ በልልን\nሚናስ ይላል በአለም አንስቶ\nሚናስ ይላል በሚናስ ባረከን', 'am', 58, 0),\n(4, 'በዙሪያችን ካሉ', 'በዙሪያችን ካሉ\nበዙሪያችን ካሉ ብዙ ምስክሮች፣\nደሞ እንደ ደመና ከበውን አባቶች፣\nበስምህ ቀድሰህ አንተ ያከበርኻቸው፣\nምስክሮችህም ድንቆች ናቸው፣\nነፍሴ ፈለገቻቸው።\n\nቅዱስ ላሊበላን መርጠኸዋል አንተ፣\nከፍልፍል ዐለት ውስጥ ቤትህን ያነፀው፣\nመሠረቱ ከላይ ከጣሪያው ቢጀመር፣\nእርዳታው ከአንተ ነው አይደለም ከምድር፣\nሥፍራን ይቀድሳል የተቀደሰ ሰው፣\nጉልበቱን ትርፍ አርጓል አንተ የባረከው፣\nእጀታ ባይኖረው እጅ ሆነህለታል፣\nለስምህ ቤት ሊያንፅ ቤት ሠርተህለታል።\n\nከሴት ከተገኙ እንደ እርሱ አልተገኘም፣\nየሚያሰክር መጠጥ ፍጹሞ አልቀመሰም፣\nበእናቱ ማሕጸን ለአምላክ የሰገደው፣\nመጥምቀ መለኮት በረሃ የኖረው፣\nዘንባባ ሸንኮራ ዮሐንስ ባለበት፣\nአንዳች ክፉ ደዌ ለምጽ አይታይበት፣\nአምላክ ለዘላለም ለዮሐንስ ያለው፣\nበቤቱ በቅጥሩ የማይጠፋ ስም ነው።\n        \nጣና ቂርቆስ ዘጔ ወይ ጻድቃኔ ማርያም፣\nግሸን ደብረ ከርቤ ወዲ አሰቦት ገዳም፣\nውቅር ቤተክርስቲያን ፀሐይ የወጣባት፣\nጣሪያው ክፍት እያለ ዝናብ የማይገባበት፣\nአርባ አራቱ ታቦት ጎንደር ፋሲለደስ፣\nጽዮንን ፍለጋ አክሱም ላይ ስንደርስ፣\nየኦሪቱ መሥዋእት የተሰዋባቸው፣\nእነ ብርብር ማርያም ድንቅ ድንቅ አላቸው።', 'am', 59, 0),\n(4, 'አለኝ አባት', 'አለኝ አባት\nአለኝ አባት አለኝ ጌታ\nመድኃኔዓለም የኔ አለኝታ\n\nአለኝ አባት ቸርነቱ በዝቶ\nህይወቴን ገዝቶታል\nብበድለው እንኳን\nመቼ ትቶኝ ያውቃል\nዛሬም አተወኝ አትለየኝ\nመድኃኔዓለም ፍቅር አድለኝ\n\nስምሽን ልጥራው ላመስግንሽ\nኪዳነ_ምህረት የእኔ እናት ነሽ\n\nስምሽን ልጥራው በቤትሽ አድጌ\nብሩህ ሰው ሆኛለው\nነፍሴን አድሰሻት\nይኸው እቀኛለሁ\nየኃጥአን ተስፋ አንቺ ነሽና\nኪዳነ_ምህረት የነፍሴ ዝና\n\nተዋሕዶ እምነቴ ናት\nለዘላለም የማከብራት\n             \nተዋህዶ መንገድዋ የቀና\nየማትለወጥ\nእውነተኛ ትምህርተ\nለኛ የምትሰጥ\nየእኔ ህይወት ስለሆንሽ\nተዋህዶ አልከዳሽ አልለይሽ\n\nይሰማኛል በፍጥነት\nሚካኤል ነው የኔ ረዳት\n\nይሰማኛል ልመናዬን አድምጥ\nብዬ ስማፀነው\nከነፋሳት ቀድሞ\nፀሎቴን የሰማው\nአይጠፋም ከቶ ሁሌ በደጄ\nሚካኤል ነው የኔ አማላጄ\n\nነፍሴን አድሳት ዘውትር ጠዋት ማታ\nመላዕኩ ገብርኤል አብስረኝ ደስታ\n\nነፍሴን አድሳት ስእለት ሰሚው መልአክ\nእባክህ ተራዳኝ\nአባቴ ነህና\nልመናዬ ስማኝ\nለሦስቱ ህፃናት እንደደረስክ\nከልቤ አትጥፋ ሆሌ በሠርክ\n\nፀሎተኛው አባት ብዬ እጠራዋለሁ\nቤቱ መጥቼ ክብር አግኝቻለሁ\n\nፀሎተኛው አባት ተክልዬ ተክልዬ\nስምህን ስጠራ\nከቶ አይቀርበኝ\nየዳቢሎስ ጭፍራ\nከልጅነቴ እየጠበከኝ\nተክልዬ አንተ ነህ ለዚህ ያበቃኸኝ\n\nሰማዕቱ ጊዮርጊስ ጠበቃ ሁንላት\nሀገሬ እናቴን አለሁልሽ በላት\n\nሰማዕቱ ጊዮርጊስ የቀድሞውን ዝና\nዘወትር ናፋቂ ነን\nእምዬ ኢትዮጵያ\nአድነኝ እያለች\nፍቅሯን ሊያጠፋ ቆሟል ዲያብሎ斯\nእባክህ አድናት የልዳው ንጉስ', 'am', 60, 0),\n(4, 'ዘርዓ ብሩክ', 'ዘርዓ ብሩክ\nአባ ዘርዓቡሩክ ፃድቁ አባታችን\nክብርህ ይሁነን ግርማ ሞገሳችን\nፀጋህ ይድረሰን በረከት ይሙላብን\nከመድሃኔዓለም በምልጃህ አቅርበን\n\nተግቶ የፀለየ ዘርዓቡሩክ\nገና በህፃንነት ዘርዓቡሩክ\nአይኑን ያሳወረ ዘርዓቡሩክ\nበእምነት በፀሎት ዘርዓቡሩክ\nልዩነው ታምሩ\nልዩ ነው ስራው\n\nባላ አደራ አባይ ዘርዓቡሩክ\nመፃፍህን ተፋ ዘርዓቡሩክ\nዲያቢሎስ በመፍራት ዘርዓቡሩክ\nበፊትህ ተደፋ ዘርዓቡሩክ\nልዩነው ታምሩ\nልዩ ነው ስራው\n\nፀሀይን ያቆመ ዘርዓቡሩክ\nለአምስት አመታት ዘርዓቡሩክ\nየአክናፍ ባለቤት ዘርዓቡሩክ\nየፀጋዎች አባት ዘርዓቡሩክ\nልዩነው ታምሩ\nልዩ ነው ስራው\n\nእንኳን ሰው ይቅርና ዘርዓቡሩክ\nዘንዶ ያስታረቀው ዘርዓቡሩክ\nዘርዓቡሩክ ኃያል ዘርዓቡሩክ\nግሩም ነው ገድላቸው ዘርዓቡሩክ\nልዩነው ታምሩ\nልዩ ነው ስራው\n\nብረር በክንፎችህ ዘርዓቡሩክ\nዙራት ይህቺን አለም ዘርዓቡሩክ\nአማልዳት ኢትዮጵያን ዘርዓቡሩክ\nከመድሃኔዓለም ዘርዓቡሩክ\nልዩነው ታምሩ\nልዩ ነው ስራው', 'am', 61, 0),\n(4, 'ያሬድ ማኅሌታይ', 'ያሬድ ማኅሌታይ\nአንተ ባለቅኔ አንተ ባለዜማ\nድጓ ፆመ ድጓ የሰማህ ከራማ\nየግእዝ የእዝሉ የአራራይ ቀማሪ\nየድፋት የቅናት የጭረት ፈጣሪ\nያሬድ ማኅሌታይ የእግዚአብሔር ዘማሪ\n\nከጥበባት ሁሉ ጥበብ የምስጋና\nከመላእክት ሰምተህ ተቀኝተሀልና\nወጥተን ተከተልንህ ልጆችህ ለዜማ\nበመዝሙር ልንወርሳት ታላቋን ከተማ\n\nነብርም ዥንጉርጉር ኢትዮጵያም ኢትዮጵያ\nዜማህም ውበቷ ጸሎቷ ሃሌሉያ\nየመቅደሱ ጌጥ ነህ የሃገር ግርማ ሞገስ\nነፍስ ያለመልማል ቅኔህ ዜማህ ሲፈስ\n\nመቅደሱን ወረሰ ሰማያዊ ፀጋህ\nየካህናቱን ልብ በዝማሬ ሞልተህ\nልብ እየሰቀለ ሰማይ እየነካ\nዜማህ ምድርን ጥሶ ጸባዖት አንኳኳ', 'am', 62, 0),\n(4, 'ተክለ ሐይማኖት አቡነ', 'ተክለ ሐይማኖት አቡነ\nተክለ ሐይማኖት አቡነ አዲስ ሐዋርያ\nአምነናል እኛ ልጆችህ\nአምላክ በሰጠህ ቃልኪዳንህ\n\nተክለ ሐይማኖት አቡነ ታላቅ ብርታት ሆነን ፅናትህን ስናይ\nተክለ ሐይማኖት አቡነ አለም ያልማረከህ የእግዚአብሔር አገልጋይ\nተክለ ሐይማኖት አቡነ ዝክርህን ዘክረን በስምህ ተማፅነን\nተክለ ሐይማኖት አቡነ ተክለሃይማኖት ብለን እንድናለን\n\nተክለ ሐይማኖት አቡነ ማዕበል ቢነሳ የክህደት ወላፈን\nተክለ ሐይማኖት አቡነ እኛስ አንፈራም አማላጅ ስላለን\nተክለ ሐይማኖት አቡነ ፃድቁ አባታች ይረዳናል እኛን\nተክለ ሐይማኖት አቡነ ተክለሃይማኖት ብለን እንድናለን\n\nተክለ ሐይማኖት አቡነ በእናትህ ማህፀን ሳለህ የተመረጥክ\nተክለ ሐይማኖት አቡነ ምስክር ልትሆን ለፈጠረህ አምላክ\nተክለ ሐይማኖት አቡነ ፀሎት እና ምልጃህ ከእኛ ጋር ስላለ\nተክለ ሐይማኖት አቡነ ተክለሃይማኖት ብለን እንድናለን', 'am', 63, 0),\n(4, 'አረሳት ኢትዮጵያን', 'አረሳት ኢትዮጵያን\nአረሳት ኢትዮጵያን በእርፈ መስቀል\nአባ ተክለኃይማኖት ሰባኪ ወንግል\nየእግዚአብሔር ሰው ነው ተወዳጅ በሠማይ\nየተረማመደ በጽድቅ አደባባይ\n\nፈውስ እና ጸሎቱ ቃሉ የተሰማ\nወንጌል የሰበከ በገጠር ከተማ\nየኤትሳው ኮከብ የደብረ አስቦቱ\nለወንጌል ተዋጋች ንጽሒት ሕይወቱ\n\nፋናው እስከ ዛሬ ሲያበራ የኖረው\nየኢቲሳው አባት ፍስሐ ጽዮን ነው\nእግዚሀረያ እናቱ ማህጸነ ብሩክ\nወለደች ኮከብን ሲኦልን የሚያውክ\n\nዲያቢሎስ እስካሁን ስሙ ሲጠራበት\nሲረገጥ ይኖራል በእሳት ሰንሰለት\nሐዲስ ሐዋርያ የኢትዮጵያ አባት\nደጋና ቆላውን በመስቀል ባረካት\n\nምንጩ እና ፏፏቴው ተራራው ቅዱስ ነው\nየአባታችን መስቀል ጸሎት ስለነካው\nየተራመደበት የዳሰሰው ሁሉ\nድውይ ይፈውሳል ሳር እና ቅጠሉ።', 'am', 64, 0),\n(4, 'ሰማዕታት መስተጋድላን', 'ሰማዕታት መስተጋድላን\nሰዓሉ ለነ ሰዕማታት መስተጋድላን\nከዋክብት ለቤተ-ክርስቲያን\n\nበምድር ሊቪያ ተጣራ እየሱስ\nበተዋህዶ ልጆች ስሙ እንዲ ቀደስ\nእየሱስ አምላክ ነው እያሉ በፅናት\nመንግስተ ሰማይን ህፃናት ተሻሟት\nከዋክብት ለቤተክርስቲያን\n\nበመከራ ጊዜ ሚዛን ላይ ወታቹ\nበክርስቶስ ፀጋ እንደ እንቁ አበራቹ\nእንደ ቅዱስ ጊዮርጊስ ሰይፍን ሳትፈሩ\nእግዚአብሔር ይመስገን በቃቹ ለክብሩ\nሰዓሉ ለነ ሰዕማታት መስተጋድላን\n\nእዮ ሲያንገላቱ ሲያዳፉት ጨክነው\nምንም አልቀመሰም ወንድሜ ፆሙን ነው\nግን እንደ ሰርገኛ በደስታ ይጓዛል\nበሰይፍ ፊት ቆሞ ለወንጌሉ ታምንዋል\nመከራውን ንቆ ለወንጌሉ ታምንዋል\nሰዓሉ ለነ ሰዕማታት መስተጋድላን\n\nግርፋቱን ይስሙ መታረዱን ደግሞ\nከክርስቶስ ፍቅር እኛ የሚለየን\nያመለክ ነው አምላክ የእውነት ስለሆነ\nለክብር ተፋጠኑ ልባቸው ጨከነ\nከዋክብት ለቤተ-ክርስቲያን\n\nየዋልዮሽ ታስረው እንደ በግ ሲነዱ\nይመስሉ ነበረ ለሰርግ የሚሄዱ\nበጉድጓድ ተከተው ለቀናት ቢራብ\nበውሃ ጥም ዝለው አልተለዋውሱም\nሰዓሉ ለነ ሰማዕታት መስተጋድላን\nከዋክብት ለቤተ-ክርስቲያን\n\nገዳይወች ድል ሆኑ ሙታን ሆኑ እነሱ\nየተዋህዶ ልጆች በድል ገሰገሱ\nበደማቸው ፀዳል አለምን ቀየሩ\nየኢትዮጵያ ከዋክብት በሊቪያ አበሩ\nየኢትዮጵያ ከዋክብት በዓለም አበሩ\nከዋክብት ለቤተ-ክርስትያን', 'am', 65, 0),\n(4, 'ምን ሰማህ ዮሐንስ', 'ምን ሰማህ ዮሐንስ\nምን ሰማህ ዮሐንስ በማሕጸን ሳለህ\nህፃን ሆነህ ነቢይ ለክብር የተጠራህ\nእንደ እንቦሳ ጥጃ ያዘለለህ ደስታ\nምን አይነት ድምፅ ነው ምን አይነት ሰላምታ\n\nከተፈጥሮ በላይ ያሰገደህ ክብር    \nእንዴት ቢገባህ ነው የእናታችን ፍቅር    \nሌላ ድምፅ አልሰማም ከእንግዲህ በኋላ    \nለውጦኛልና የሰላምታ ቃሏ\n\nበረሀ ያስገባህ ለብዙ ዘመናት  \nምን ያለ ራዕይ እንዴት ያለ ብሥራት\nአንደ አዲስ ምስጋና ስልቱ የተዋበ  \nተደምጦ የማያውቅ ጭራሽ ያልታሰበ\n\nከሴት ከተገኙ ከደቂቀ አዳም    \nድንግል ስለሆነ በህይወቱ ፍፁም      \nከማህፀን ሳለ ተመርጦ በጌታ      \nለማዳመጥ በቃ የኪዳን ሰላምታ', 'am', 66, 0),\n(4, 'ሥላሴን ከሰማይ', 'ሥላሴን ከሰማይ\nሥላሴን ከሰማይ እስጢፋኖስ አይቶ\nዓይኑ በመገረም ቀረ ተሰክቶ\nየድንጋይ ናዳ ቢወርድበት እንኳ\nሥላሴን በማየት እረስቶታል ለካ\nስብሐት ለእግዚአብሔር\n\nየሰው ልጅ በቀኙ ተቀምጦ ነበር\nእስጢፋኖስ ሲያየው በሚያስፈራ ክብር\nካህናተ ሰማይ ዙፋኑን ከበውት\nቅዱስ ቅዱስ ሲሉ ስብሐት ስብሐት\nስብሐት ለእግዚአብሔር\n\nምሥጢረ ሥጋዌ ተገልጾለት በአካል\nሥጋው ቢታመምም ሐዘኑን ሽሮታል\nነፍሱ ከጸባኦት ስታመሰጥር\nድንጋይ ይለቅማሉ ያልታደሉ በምድር\nስብሐት ለእግዚአብሔር\n\nለፈሪሳውያን ተሰውሮባቸው የሥላሴ ምሥጢር\nድንጋይ ሰበሰቡ ጻድቁን ለመውገር\nእርሱ ግን ከሰማይ ፈጣሪውን አይቶ\nድንጋዩን እረሳው ህሊናው ተነክቶ\nስብሐት ለእግዚአብሔር\n\nየሰማዩ ሥርዓት ልዩ ስለነበር\nምንም አልመሰለው የድንጋዩ ክምር\nየፍጥረታ ሁሉ ፈጣሪ ተገልጠው\nስቃዩን አስረሱት ህሊናውን ፍቀው\nስብሐት ለእግዚአብሔር\n\nልባችሁ ጆሮአችሁ መቼ ተገረዘ\nየጠነከረ ነው ለአምላክ ያልታዘዘ\nመንፈስ ቅዱስን ትቃወማላችሁ\nእንደገዛ ፍቃድ እየተመራችሁ\nስብሐት ለእግዚአብሔር', 'am', 67, 0),\n(4, 'ነገር ግን ያመንነው', 'ነገር ግን ያመንነው\nነገር ግን ያመንነው ያድነናል ብለው\nጸንተው ተሰለፉ ለኃይማኖታቸው\n\nሶስቱ ወጣቶችን ከእሳት ያወጣቸው\nኃይማኖት ነው እኝጂ ሌላ ምን ሊሆን ነው\nናቡከደነፆር በዱራ ሜዳ ላይ\nጣዖቱን አቁሟል እንድንሰግድ እንድናይ\n\nእምቢልታ ሲነፋ መለከት ሲሰማ\nበአንድነት እንዲሰግድ ሰው ሁሉ ተስማማ\nነገር ግን ትእዛዙን የማይቀበው\nከሚነደው እሳት ይጨመራል ወዲያው\n\nሰው ሁሉ ይንበርከክ ለወርቁ ለብሩ\nአምላክ ስለሆነ በአንድነት ያክብሩ\nለግዙፉ ሐውልት ያልሰገደ ቢኖር\nምህረት ሳያገኝ ወደ እሳት ይወርወር\n\nሲድራቅ ሚሳቅ እና አብደናጎም ሆነው\nሳይሰግዱ በድፍረት ቆመው አየናቸው\nንጉሡ ቢቆጣም አልተደናገጡም\nአሉ እንጂ በድፍረት ለጣዖት አንሰግድም\n\nበዚህ አንመስልህም አስፈላጊ አይደለም\nአምላካችን አለ ከእቶን የሚያድነው\nከእቶን ያድነናል ፍዱም እምነት አለን\nባያድነን እንኳን የእሱ ፈቃድ ይሁን\n\nናቡከደነፆር እጅግ ተናደደ\nእቶኑም ሰባት እጅ ከፍ ብሎ ነደደ\nከእሳት ቢከቷቸው ገብርኤል ተላከ\nአህዛብን በድንቅ እግዚአብሔር ማረከ\n\nበእሳት መካከል ሲመላለሱ አይቶ\nንጉሡ አደነቀ ከሥፍራው ተነስቶ\nየአማልክትንም ልጅ አየዋለሁ አለ\nእግዚአብሔር ይመስገን በክብር', 'am', 68, 0),\n(4, 'ሲላስና ጴጥሮስ', 'ሲላስና ጴጥሮስ\nሲላስና ጴጥሮስ ሳሉ ከእስር ቤት\nተሰጣቸውና የመዝሙር በረከት\nሲያወድሱት ሳለ አምላክን አክብረው\nወጡ ከእስር ቤት ሰንሠለቱን ሰብረው\n\nመዶሻ ሆነና የሚፋረድ እሳት\nበመዝሙር ወደቀ የእጃቸው ሰንሠለት\nየእስር ቤቱ በር ተከፋፈተና\nወጡ እየዘመሩ በብርሃን ፋና\n\nመሰረቱ ሁሉ ተናጋ በመዝሙር\nእስር ቤቱን ሻረው የምስጋና ክብር\nልባቸው ተወስዶ ኢዮር ደረሱና\nከመላእክቱ ጋር ዘመሩ ምስጋና\n\nበልዩ ተመስጦ ምስጋና ጀመሩ\nመዝሙር ለውጧቸው በደስታ ሰከሩ\nበምስጋናው ጸጋ ተሰውረው ሳለ\nብርሃን በክፍሉ መጣ እያየለ\n\nአዲስ ቅኔ ፈልቆ በእንባ ሲያወድሱት\nየእስር ቤቱ ግንብ በሙሉ አፈረሱት\nበሮማ ጨካኞች እስር ቤት ተጥለው\nይዘምሩ ነበር መከራውን ሽረው\n\nበሞት ጥላ ሳሉ በጽኑ እስራት\nአያስቡም ነበር ስለ ሞት ፍርሃት\nታላቁ ምስጋና ልባቸውን ሞልቶት\nአስፈሪውን ዓለም በጸሎት ገሰጹት', 'am', 69, 0),\n(4, 'ሰውነቴ ባንተ ፍቅር ተጠምዳለች', 'ሰውነቴ ባንተ ፍቅር ተጠምዳለች\nሰውነቴ ባንተ ፍቅር ተጠምዳለች\nውለታህን እያሰበች ታለቅሳለች\nመከራው ተረሳ ትካዜም ቀረልኝ\nገብረ መንፈስ ቅዱስ ፈጥነህ ደርሰህልኝ\n\nደጅህን ለመርገጥ መንገድ ስጀምር\nተፈቷ አየዋለው የልቤ ችግር\nወዳጄና አባቴ ምስጢር የተስፋዬ\nቀና እንድል አረከኝ በነፍስ በስጋዬ\n\nበሚመጥን ፊደል በሚያምሩ ቃላትህ\nነፍሴ ትጠማለች ስምክን ለመጥራት\nእንባዬ ይፈሳል አንደበት ያጥረኛል\nውለታህን ሳስብ ልቤ ይቀልጥብኛል\n\nልዩ እኮነህ ለእኔ መተኪያ የሌለህ\nልጅህን ሳትሰለች ዛሬም ትሰማለህ\nዚጊቲ ልገስግስ ከደጅህ ልውደቅ\nገብረህይወት እንዳልኩ ዘመኔ ይለቅ\n\nስለቴን ስትሰማ ሲጠብቀኝ ምልጃህ\nሳጉረመርምብህ ትታገሰኛለህ\nየጭንቄ ማረፊያ የህመሜም ፈውስ\nአርከ እግዚአብሔር ገብረመንፈስ ቅዱስ', 'am', 70, 0),\n(4, 'ሰማዕተ ኢየሱስ', 'ሰማዕተ ኢየሱስ\nሰማዕተ ኢየሱስ የእውነት ምስክር\nሕያው ነው በሰማይ ብፁዕ ነው በምድር\nደራጎንን በጦር ወግቶ ገደለና\nከሞት አፍ አዳነኝ ጊዮርጊስ ደረሰና\n\nየኀዘን ማዕበል እንዳያንገላታኝ\nተዓምር ሰሪው ሰማዕት ፈጥኖ አረጋጋኝ\nበእግዚአብሔር ጣዕም በፍቅሩ ተጠምዷል\nይህን ዓለም ንቆ በክብር አጊጧል\nኦ ፍጡነ ረድኤት ቅዱስ ጊዮርጊስ\nፈጥነህ የምትደርስ ከአውሎ ንፋስ\nስምህ የተጠራ የኢትዮጵያ ገበዝ\nአድናት አገሬን ከገጠማት ትካዝ\n\nእርሱን ለምጠራው ሲመሽም ሲነጋ\nዋስ ጠበቃዬ ነው በነፍስም በሥጋ\nድንቅን የሚፈጽም ኃያል ሰማዕት ነው\nበቅድመ እግዚአብሔር ለእኔ የሚቆመው\nኦ ፍጡነ ረድኤት ቅዱስ ጊዮርጊስ\nፈጥነህ የምትደርስ ከአውሎ ንፋስ\nስምህ የተጠራ የኢትዮጵያ ገበዝ\nአድናት አገሬን ከገጠማት ትካዝ\n\nየምስጋናን አውታር የታጠቀ ሰማዕት\nስሙን ተሸክሞ የታመነ እስከ ሞት\nሙታን የሚያስነሳ ስልጣን ተቀብሏል\nበአባቱ መንግስት እንደ ፀሀይ ደምቋል\nኦ ፍጡነ ረድኤት ቅዱስ ጊዮርጊስ\nፈጥነህ የምትደርስ ከአውሎ ንፋስ\nስምህ የተጠራ የኢትዮጵያ ገበዝ\nአድናት አገሬን ከገጠማት ትካዝ', 'am', 71, 0),\n(4, 'አባ ሳሙኤል ዘዋልድባ', 'አባ ሳሙኤል ዘዋልድባ\nአባ ሳሙኤል ዘዋልድባ\nመነኮስ ሃያል ቤቴ ግባ\nታስባርካለህ ሰውን ምድር\nቅርብ ነህ አንተ ለእግዚአብሔር\nየበረሃው መናኝ ግሩም ነው ገድልህ\nምድርን አስባርከሃል ከፍ አድርገህ በእጅህ\nተአምር ነው ገዳምህን ላየ\nረድኤት በረከት ገበየ\nልጆችህ በገዳም ውስጥ ያሉ\nሳሙኤል ሳሙኤል ይላሉ\n\nአይሻገርብሽ እህልም ኃጥአት\nጌታችን ብሏታል ዋልድባን መሬት\nሕርመት ይዘው ልጆቹ በሙሉ\nቋርፍ ነው ዘውትር የሚበሉ\nየጣመ የላመ አጥተን\nዮርዳኖስ ፀበል ምግብ ሆነልን\n\nአስኬማውን ለብሶ በገዳም ሲኖር\nየትሕትና አባት ነው የሕግ መምህር\nሃሌ ሉያን ሄደን አይተን\nአብረን ካንተ እንኑር አልን', 'am', 72, 0),\n(4, 'ቅዱስ ጊዮርጊስ አማለደን', 'ቅዱስ ጊዮርጊስ አማለደን\nቅዱስ ጊዮርጊስ አማለደን አማለደን ከመድኃኔዓለም አስታረቀን\nማረን ይቅር አለን ማረን ይቅር አለን\nአማኑኤል ታረቀን\n\nሹመት ለመፈለግ ቅዱስ ጊዮርጊስ\nነገሥታት ዘንድ ሄዶ ቅዱስ ጊዮርጊስ\nጣዖት ሲያመልኩ አየ ቅዱስ ጊዮርጊስ\nአምላኩ ተክዶ ቅዱስ ጊዮርጊስ\n\nክርስቲያን ነኝ የሚል ቅዱስ ጊዮርጊስ\nበዓለም ሁሉ ጠፍቶ ቅዱስ ጊዮርጊስ\nእኔ አምናለሁ አለ ቅዱስ ጊዮርጊስ\nየአምላኩን ስም ጠርቶ ቅዱስ ጊዮርጊስ\n\nየዓለም ግሳንግሷ ቅዱስ ጊዮርጊስ\nጸባይዋ ሳይገዛህ ቅዱስ ጊዮርጊስ\nስለ ጌታ ፍቅር ቅዱስ ጊዮርጊስ\nከእናትህ ተለየህ ቅዱስ ጊዮርጊስ\n\nየመቅጫው መሳሪያ ቅዱስ ጊዮርጊስ\nበዓይነት ተደቅኖ ቅዱስ ጊዮርጊስ\nእኔ አልፈራም አለ ቅዱስ ጊዮርጊስ\nበአምላኩ ተማምኖ ቅዱስ ጊዮርጊስ\n\nተፈጭቶ ተደቅቆ ቅዱስ ጊዮርጊስ\nደብረ ይድራስ ሳለ ቅዱስ ጊዮርጊስ\nእጽዋቱ ሁሉ ቅዱስ ጊዮርጊስ\nጊዮርጊስ ጊዮርጊስ አለ ቅዱስ ጊዮርጊስ', 'am', 73, 0),\n(4, 'ታላቅ በሆነው እምነትሽ', 'ታላቅ በሆነው እምነትሽ\nታላቅ በሆነው እምነትሽ ታመንኩኝ\nካለሽበት ገስግሼ መጣሁኝ\nእናቴ ክብርሽን አንግሼ\nሆንኩኝ እንደ ህፃን ታድሼ\nእናቴ ቅድስት አርሴማ\nዝናሽ ለዓለም ተሰማ\n     \nስመጣ ባልጋ ነበረ\nተስፋዬም የተሰበረ\nበእምነትሽ በፀበልሽ\nሰው ሆኜ ቆምኩኝ ደጅሽ\n\nልናገር ዝናሽን ላውራ\nይደነቅ የአምላክሽ ሥራ\nተጋድሎሽ የእምነትሽ ፅናት\nሆኖኛል የእምነቴ መብራት\n       \nደምግባት ከንቱ ብለሽ\nለሰማይ ክብር ታጭተሽ\nየእምነቴ አሰረ ፍኖት\nበምልጃሽ አለሁ በህይወት\n      \nየልቡን ለነገረሽ\nፈጥኖ ይደርሳል መልስሽ\nዘንባባሽ ህይወት ይዘራል\nየጠራሽ ማን አፍሮ ያውቃል\n          \nእርዳታሽ የደረሰለት\nያመጣል የልቡን ስለት\nላመኑሽ ፈውስሽ ቅርብ ነው\nባንቺ አፍሮ የሄደው ማነው', 'am', 74, 0),\n(4, 'የፃድቅ ሰው ጸሎት', 'የፃድቅ ሰው ጸሎት\nየጻድቅ ሰው ጸሎት ሐይልን ያደርጋል\nፀሐይን ያቆማል ሙታን ያስነሳል\nከጠላት ዲቢሎስ ነፍሳትን ይነጥቃል\nባዶውን ማድጋ በዘይት ይሞላል\n\nየእያሱ ጸሎት ግዳጅን ፈጽሟል\nበገባኦን ሰማይ ጸሐይን አቁሟል\nማድጋዋ ሞልቷል በኤልሳ በረከት\nከርሃብ ድናለች ሱናማዊቷ ሴት\n\nህያው እንድትሆን ጴጥሮስ ጸለየላት\nጣቢታ ተነሳች ሞት ተሸንፎላት\nከሰገነት ወድቆ ቢሞት አወጣኪስ\nሕይወት ሰጠው አቅፎት ቅዱስ ጳውሎስ\n\nበስሙ መከራን ለተቀበሉት\nይለምናል ጌታ ስለ ሰማእታት\nበፃድቅ ስም ውሀ ለመስጠት የተጋ\nያገኛል ከአምሳሉ የፃድቁን ዋጋ\n\nቃል ኪዳን ስላለው ከመረጣቸው\nስለማለላቸው በፅኑ መሃላው\nጌታ ስለነርሱ እንደሚማለደን\nበመንፈስ ቅዱስ አፍ መጽሀፍ ነገረን', 'am', 75, 0),\n(4, 'እስጢፋኖስ ሰማዕት', 'እስጢፋኖስ ሰማዕት\nእስጢፋኖስ ሰማዕት ሊቀ ዲያቆናት\nለምዕመናን የተሾምክ\nየአምላክህን ትዕዛዝ በስራ የፈጸምክ\n\nየስምህ ትርጓሜ የክብር አክሊል ነው\nእስጢፋኖስ ፀሐይ ገድልህ የሚያበራው\nስድብና ዛቻ በድንጋይ መወገር\nአንተን አይለይህም ከክርስቶስ ፍቅር\n\nሕዝብን እንድትመራ በወንጌሉ ፋና\nየስምንት ሺህ ነፍስ ምግባር ልታቀና\nአምላክ ከፍ አረገህ በከበረው ሹመት\nጸጋን ተጎናጸፍክ መንፈሳዊውን ሀብት\n\nበመንፈስ ቅዱስ ኃይል በጥበብ ተሞልተህ\nአንገትህን በማቅናት ወደ ሰማይ አይተህ\nከሙታን ተነሥቶ በክብር ያረገውን\nበአብ ቀኝ ቆሞ አየህ ኢየሱስ\n\nበኩረ ሰማዕታት ሊቀ ዲያቆናት\nየቤትህ መሰረት ታንጿል በዐለት\nአይፈርስም አይወድቅም በመከራ ዋዕይ\nዋጋውን ስላየ ያለውን በሰማይ\nብድራትን ሁሉ እስጢፋኖስ አይቶ\nለፍቅር የሞተውን አከበረው ሞቶ\nአትቁጠርባቸው ይህን እንደ ኃጢአት\nእያለ ለመነ ለጠላቶች ምህረት', 'am', 76, 0),\n(4, 'ዳዊት መዝሙረኛው', 'ዳዊት መዝሙረኛው\nየሳኦልን ካባ ያልተለማመደው\nበእረኝነት ልብሱ ጎልያድን ገጠመው\nግንባሩን ሲመታው ወድቋል በግንባሩ\nእግዚአብሔር ነበር የወንጭፍ ጠጠሩ\n\nነቢዩን ቢልከው ለበደሉ ቅጣት\nዳዊት ማቅ ለበሰ ዙፋኑን እረሳት\nበትቢያ ላይ ተኛ አመድ ነሰነሰ\nየራቀውን ጸጋ አልቅሶ አስመለሰ\nዳዊት መዝሙረኛው ሲበድል አልቃሻው\nእንደ ልቤ ብሎ እግዚአብሔር ጠራው\n\nየወርቅ ልብስ ለብሶ ቢጨብጥም ጦር\nበቤተ መንግስቱ ቢኖርም በክብር\nእግዚአብሔር ቢቀባው አድርጎት ንጉሥ\nዳዊት መች ተገኘ ሕዝቡን ሲያስለቅስ\nዳዊት መዝሙረኛው ሲበድል አልቃሻው\nእንደ ልቤ ብሎ እግዚአብሔር ጠራው\n\nየዓለምን ጥበብ ፍጹም ለማሳፈር\nከዓለም ሞኝ ነገር መረጠ እግዚአብሔር\nሰው በሃይማኖት እንጂ ከፊቱ የሚቆመው\nየዚህ ዓለም ጥበብ ያለ እምነት ከንቱ ነው\nዳዊት መዝሙረኛው ሲበድል አልቃሻው\nእንደ ልቤ ብሎ እግዚአብሔር ጠራው', 'am', 77, 0),\n(4, 'ብርና ወርቅ ሳይዙ', 'ብርና ወርቅ ሳይዙ\nብርና ወርቅ ሳይዙ ዓለማትን ዞሩ\nቅዱሳን ሐዋርያት ቃሉን እየዘሩ\nሙታን እያስነሡ ድውያን ፈወሱ\nስሙን ብቻ ይዘው ታምነው በንጉሡ\n\nከቀራጩ መደብ ከሐጥያት ገበታ\nከጥብርያዶስ ባሕር ከጠራቸው ጌታ\nስሙን ተሸክመው ቃሉን መሰከሩ\nበመንፈስቅዱስ ኃይል ድንቅን እየሠሩ\n\nየነገስታቱን ቃል ዛቻውን ሳይፈሩ\nየመንግስቱን ወንጌል ለዓለም አስተማሩ\nይሻለናል አሉ ማድላት ለእግዚአብሔር\nለሰው ከመታዘዝ ዘላለም ለማይኖር\n\nቆዳቸው ተገፎ በሰይፍ ተሰየፉ\nስለጌታ ፍቅር በመከራ አለፉ\nየድንጋዩን ናዳ የእሣቱን ነበልባል\nየጀርባን ግርፋት በእምነት ታግሰዋል\n\nስደት ነው መከራ ረሀብ ነው ወይስ ጥም\nከክርስቶስ ወንጌል ከእውነት የሚያስቆም\nበእርሱ ስላመኑ በጽድቅ ተጋደሉ\nደግሞም በእርሱ በላይ እንዳለ በቃሉ\n\nበዙርያችን ከበው ካሉ እንደ ደመና\nእነርሱን እያሰብን በእምነት እንፅና\nበእውነት እንደኖሩ መሥለው ክርስቶስን\nእኛም በኑሮችን እንምሰል እነርሱን', 'am', 78, 0),\n(4, 'የኢዮብ መልሱ', 'የኢዮብ መልሱ\nእንደምነህ ቢሉት ዘመዶች ከድተውት\nሚስቱ ትታው ሄዳ ልጆች ሞተውበት\nዓይኖቹ በምሬት እንባ አላፈሰሱ\nእግዚአብሔር ይመስገን ነበር የኢዮብ መልሱ\n\nበሕይወት ገጥሞት የበረታ ፅልመት\nበአንድ ቀን ሲነጠቅ ልጆችና ንብረት\nአካሉ በቁስል ተይዞ በፀና\nኢዮብ እንዴት ቻለ ለአምላኩ ምስጋና\n\nበሰጠበት መንደር ሲቆም ለልመና\nሚስቱ ሙት ስትለው ጌታን እርገሞ እና\nየስንፍናን ነገር አይሰማም ጆሮዬ\nይክሰኛል እርሱ ይችላል ጌታዬ\n\nቅን ነገር መናገር ለአፌ ከቸገረኝ\nአምላኬ እንዳያዝን ምነው ዝም በአልኩኝ\nልሳኔ እንዳይጠራ ሞት እና መከራ\nለምስጋና ቆሜ ነገን ዛሬ ልስራ\n\nእግዚአብሔር ይመስገን ቢጎድልም ቢሞላም\nለዓይኔ ሽፋሽፍት እንቅልፍ እንኳን ባጣም\nብዙ እንደነበረው ትናንትና ደጄ\nክፉውንም ደግሞ ይቀበላል እጄ', 'am', 79, 0),\n(4, 'አጎንብሼ ሄጄ', 'አጎንብሼ ሄጄ\nአጎንብሼ ሄጄ ቀና ብዬ መጣው\nበዮሐንስ ፀበል ጤናዬን አገኘው\nጌታን ያጠመቁ ክቡራን እጆቹ\nተዓምር ይሰራሉ ዛሬም ለልጆቹ\n\nአልጋዬን አዝዬ በደስታ ዘለልኩኝ\nበመጥምቁ ፀበል በእጁ ተዳሰስኩኝ\nየመራኝን በትር ከእጄ ላይ ጥያለሁ\nበሰባኪው ጸሎት በምልጃው ድኛለሁ\n\nለዓለም ያልተቻላት በእምነቱ ለቆኛል\nአበቃልህ ያሉኝ እጅግ ተደንቀዋል\nበለምጽ የነደድኩት ታደስኩ እንደገና\nአዲስ አካል ይዤ ቆምኩኝ ለምስጋና\n\nያለፍኩባት ሰፈር በእምባ ተሞልቼ\nእልልታዬን ሰማች ድኜ ተደስቼ\nየንዕማን ቁስል ተራግፉአል ከላዬ\nመሞቴን የማይወድ አሰበኝ ጌታዬ\n\nአባናና ፋርፋን አስንቁአል ጸበሉ\nዮርዳኖስ በእምነት ለወረዱ ሁሉ\nዮሐንስ በመንፈስ ሲያጠምቅ አይቻለሁ\nበእጁ ተፈውሼ ምስክር ሆኛለሁ', 'am', 80, 0),\n(4, 'የጫማውን ጠፈር', 'የጫማውን ጠፈር\nየጫማውን ጠፈር መፍታት የማልችል ነኝ\nየጫማውን ጠፈር መፍታት የማልችል ነኝ\nይመጣል በኅላ እኔን የሚበልጠኝ\nይመጣል ጌታዬ እሱን ነው የላከኝ\n\nከአብ ጋር ነበረ አለምን ሲፈጥር\nሁሉ በእርሱ ሆኗል እኔ ነኝ ምስክር\nበስድስት ወር እኔ በልጠዋለው\nበማህፀን ሳለው ለእርሱ ሰግጃለው\nበማህፀን ሳለው ለእርሱ ሰግጃለው\n\nመንገዱን ለመጥረግ እኔ ተልኪያለው\nእርሱ ሊሂድበት አስተካክላለው\nጠማማውም ይቅና ጎባጣው ይቃና\nካልተስተካከለ ድነት የለምና\nካልተስተካከለ ድነት የለምና\n\nየዓለምን በደል የሚያሶግደው\nየዋህ በግ ክርስቶስ በፊታችን ነው\nወደርሱ ለማድረስ እሰብካለው እንጂ\nመንሹ በእጁ የሆነው እርሱ ነው ፈራጅ\nመንሹ በእጁ የሆነው እርሱ ነው ፈራጅ\n\nየአዋጅ ነጋሪው ቃል በበረሀ አየነው\nወልደ ጎለምያው ይመጣል እያለ\nመቶ ሲያጠምቃቹ በእሳት በመንፈስ\nከአብ ጋር እኩል ነው ከመንፈስ ቅዱስ', 'am', 81, 0),\n(5, 'በሚፈርደው ፈረዱበት', 'በሚፈርደው ፈረዱበት\nበሚፈርደው ፈረዱበት\nበሚምረው ጨከኑበት\nበቁጣ ጎተቱት ቀይ ግምጃ አለበሱት\n\nአዳምን የፈጠረ እጅ በመስቀል ቀኖት ተቸነከረ\nቅዱሱ የእግዚአብሔር ልጅ ከወንበዴ ጋር ተቆጠረ\nህይወት እፍ ያለውን አፍ ጨክነው ሀሞት አጠጡት\nበሞቱ ሞትን ይሽር ዘንድ ጌታን በመስቀል ሰቀሉት\n\nይህን ያህል ትህትና ይህን ያህል ትዕግስት\nይህን ያህል ሰው ማፍቀር ይህን ያህል ምህረት\nዝም አለ አማኑኤል በግፍ ለሚሰቅሉት\n\nበመፍራትና በመራድ መላዕክት ፊቱ ለሚሰግዱለት\nየአለሙን ሁሉ ጌታ በአደባባይ ላይ አቆሙት\nለሱራፌል የክብር ዘውድ ያቀዳጃቸውን ጌታ\nፍቅር ያነበብንበት ፊቱን በክፉ ባርያ ተመታ\n\nይህን ያህል ትህትና ይህን ያህል ትዕግስት\nይህን ያህል ሰው ማፍቀር ይህን ያህል ምህረት\nዝም አለ አማኑኤል በግፍ ለሚሰቅሉት\n\nፅድቅና የፀና ሰላም የሀጥያት ስርየት በሰጠን\nእንደ ክፉ ሰው ተቆጥሮ በእሾህ አክሊል አጌጠ\nለኪሩቤል የግርማን ልብስ የሚያለብሳቸውን እርሱን\nርቃኑን ይሰቀል ብለው እጣ ተጣጣሉበት ልብሱን\n\nይህን ያህል ትህትና ይህን ያህል ትዕግስት\nይህን ያህል ሰው ማፍቀር ይህን ያህል ምህረት\nዝም አለ አማኑኤል በግፍ ለሚሰቅሉት\n\nበኢየሱስ መንገላታት አለም እንዲድን ከፍዳ\nቅዱሱ ደምና ውሀ ከአምላካችን ጎን ተቀዳ\nሰላም ለእናንተ ሲለን እጅና እግሩን አየን\nሙስና መቃብር ጠፋ ይኸው በአዲሱ ኪዳን\n\nይህን ያህል ትህትና ይህን ያህል ትዕግስት\nይህን ያህል ሰው ማፍቀር ይህን ያህል ምህረት\nዝም አለ አማኑኤል በግፍ ለሚሰቅሉት', 'am', 1, 0),\n(5, 'አምላኬ መቅደስህን እወደዋለሁ', 'አምላኬ መቅደስህን እወደዋለሁ\nአምላኬ መቅደስህን እወደዋለሁ\nበውስጡ ለመኖር እናፍቃለሁ\nሰላምህ እንድሆን በቤት በደጄ\nወደ ማደሪያህ ልምጣ ማልጄ\nወደ ማደሪያህ ልምጣ ማልጄ\n\nእንድሰለጥን በመላእክት ዜማ\nየህይወትን ቃል ከአፍህ ልስማ\nእንዲቀል ሸክሜ ከትከሻዬ\nወደ ዙፋንህ ልምጣ ጌታዬ\n\nመልካም በሚሏት በመቅደስህ\nሳመልክህ ልኑር ስማጸንህ\n\nተመለሠልኝ ደስታ ሠላሜ\nቤትህ መጥቼ በመሳለሜ\nስጋዬም ዳነ ታደሰች ነፍሴ\nወደ ማደሪያህ በመገስገሴ\n\nመልካም በሚሏት በመቅደስህ\nሳመልክህ ልኑር ስማጸንህ\n\nየተማርኩባት የመላዕክት ቅኔ\nየተባረከው እድሜ ዘመኔ\nየተለወጠው ሞቴ በህይወት\nእናፍቃለሁ የእግዚአብሔርን ቤት\n\nመልካም በሚሏት በመቅደስህ\nሳመልክህ ልኑር ስማጸንህ\n\nየሰማይ ዜማ የሚሰማባት\nሰዎች ከሀዘን የሚጽናኑባት\nየጸሎት ስፍራ የአምልኮ ቦታ\nቤተክርስቲያን ውዷ ስጦታ\n\nመልካም በሚሏት በመቅደስህ\nሳመልክህ ልኑር ስማጸንህ', 'am', 2, 0),\n(5, 'ለአብርሀም እንደማለ', 'ለአብርሀም እንደማለ\nለአብርሀም እንደማለ\nለይስሀቅ እንደተናገረ\nለያዕቆብ እንደመሰከረ\nህዝብን ከሞት አሻገረ\n\nየማለውን መሀላ ሳይረሳ ጌታ\nህዝብን በጽኑ ደዌ በሞት ሳይመታ\nለአባቶች እንደማለላቸው\nቃሉን ፈጸመ በቃልኪዳናቸው\nለአባቶች እንደማለላቸው\nቃሉን ፈጸመ በቃልኪዳናቸው\n\nእግዚአብሔር በሙሴ እጅ ባህርን ከፈለ\nከፈርኦን ሰራዊት ህዝብን ከለለ\nእግዚአብሔር ከኖህ ፈጸመ መሀላ\nምድር እንዳትጠፋ ከእንግዲህ በኃላ\nእግዚአብሔር ከኖህ ፈጸመ መሀላ\nምድር እንዳትጠፋ ከእንግዲህ በኃላ\n\nበጥላ በልብሳቸው ደዌን ፈወሱ\nምስክሮቹ ሆነው ተመላለሱ\nጌታ ስላለ ከቅዱሳን ጋር\nስልጣን ሰጣቸው ከሰማይ በምድር\nጌታ ስላለ ከቅዱሳን ጋር\nስልጣን ሰጣቸው ከሰማይ በምድር\n\nእንደደመና ሰፍረው በዙሪያችን\nስላሉን ምስክሮች ለነብሳችን\nእንድንማጸን በህያው ስማቸው\nአሉ በቀኙ ስላከበራቸው\nእንድንማጸን በህያው ስማቸው\nአሉ በቀኙ ስላከበራቸው', 'am', 3, 0),\n(5, 'ኢየሱስ ልበል ኢየሱስ', 'ኢየሱስ ልበል ኢየሱስ\nኢየሱስ ልበል ኢየሱስ\nእርሱ ነው ህይወቴ\nየምኖርበት ተስፋ እርሱ ነው እረፍቴ\nያለ ጌታ ብኖርማ እንዴት እሆናለሁ\nስለ ስሙ ብነቀፍም ነብሴን እሰጣለሁ\n\nበአይሁድ መንደር ስሄድ\nየቤቱ ቅናት በላኝ\nኢየሱስ የሚሉትን ስሙን አትጥሪ ቢሉኝ\nእምቢ ብያለሁ ያለፍቅሩ አልመላለስም\nያበራልኝ ይታየኛል እኔ አላፍርበትም\n\nበሙሴ ወንበር ሳሉ ጸሀፍቱን ሳነጋግር\nበህጋቸው ኮነኑኝ ለጌታየ ስዘምር\nከሰዎች ይልቅ ክርስቶስን መስማት ስላለብኝ\nበመከራ ተከብቤ ቸዳኜን ገለጥኩኝ\n\nአላስደነገጠኝም የቄሳር ቀጭን ትዛዝ\nበምኩራብ ተፈልጌ በመሰዊያው ፊት ብያዝ\nልቤ አይክድም የተገዛው ለእውነት ነውና\nምንም አይኖር የሚያቆመኝ ከአምላኬ ምስጋና\n\nኢየሱስ በተአምር ሁሉን እየከወነ\nበግንበኞች ከተማ ታላቅ ፍርሀት ሆነ\nበየጥቂቱ እየበዛ ቃሉ እያደገ\nበተፈታ አንደበቴ ምርኮውን ፈለገ', 'am', 4, 0),\n(5, 'እኛን ከወደደበት', 'እኛን ከወደደበት\nእኛን ከወደደበት ከጥልቅ ፍቅሩ የተነሳ\nበደላችን ተሻረ ኃዘናችን ተረሳ\nእኛን ከወደደበት ከጥልቅ ፍቅሩ የተነሳ\nበደላችን ተሻረ ኃዘናችን ተረሳ\n\nጽድቃችን ሆኖ እንደመርገም\nነፍሳችን ዝላ በሞት ሸክም\nስለወደደን ጌታ ፈቅዶ\nይኸው አዳነን እንዲህ ወርዶ\n\nእኛን ከወደደበት ከጥልቅ ፍቅሩ የተነሳ\nበደላችን ተሻረ ኃዘናችን ተረሳ\n\nከጥልቁ ጉድጓድ ተጥለን\nጽኑ መከራ ውስጥ ሳለን\nክርስቶስ በስጋ ተገልጦ\nሕይወትን ሰጠን ሞትን ውጦ\n\nእኛን ከወደደበት ከጥልቅ ፍቅሩ የተነሳ\nበደላችን ተሻረ ኃዘናችን ተረሳ\n\nታስሮ ወረደ በፍቅር\nመዳፉን ሰጠ ለችንካር\nየባዘንነውን ሰበሰበን\nርቀን ነበር አቀረበን\n\nእኛን ከወደደበት ከጥልቅ ፍቅሩ የተነሳ\nበደላችን ተሻረ ኃዘናችን ተረሳ\n\nቁጥር የለውም ለዘመኑ\nድንበር የለውም ለማዳኑ\nይኸው ሞትን አሰናበተ\nሰማይ በደሙ ተከፈተ', 'am', 5, 0),\n(5, 'ከከዋክብት በላይ ደምቃ', 'ከከዋክብት በላይ ደምቃ\nከከዋክብት በላይ ደምቃ\nከፍጥረታት ሁሉ ልቃ\nአየናት በንጉሱ ቀኝ\nማሪያምን በእግዚአብሔር እልፍኝ\nከከዋክብት በላይ ደምቃ\nከፍጥረታት ሁሉ ልቃ\nአየናት በንጉሱ ቀኝ\nማሪያምን በእግዚአብሔር እልፍኝ\n\nአላትና ሞገስ አላትና ግርማ\nአማናዊት ጺዮን የእግዚአብሔር ከተማ\nአምላክን በሆዷ ስላስተናገደች\nከፈጣሪ በታች ከፍጡር በላይ ነች\n\nአንች የገነት ምንጭ የውሀ ጉድጓድ\nየመልከ ግርማ አለሽ ውብ የሚወደድ\nየታተመች ፍሳሽ የተዘጋች በር\nማንም ያልገባባት ከእግዚአብሔር በቀር\n\nትውልድ በፊትሽ ይማልልልሻል\nንጉሰ ነገስት አዳኙን ወልደሻል\nታቦትእዶር ድንግል ስላለች እናቱ\nተላልፎ አይሰጥም አዳም ለጠላቱ\n\nልክ እንደ ጨረቃ ደምቃ እምትታይ\nእንደ ማለዳ ብርሀን የምትጎበኝ\nበንፅህናዋ ወልድን ማረከችው\nበቶም ድንግልና ፀንሳ ወለደችው', 'am', 6, 0),\n(5, 'ተአብዮ ነፍስየ', 'ተአብዮ ነፍስየ\nተአብዮ ነፍስየ ለእግዚአብሔር\nተአብዮ ነፍስየ ለእግዚአብሔር\nተአብዮ ነፍስየ ለእግዚአብሔር\nሰአሊለነ ማርያም\nሰአሊለነ ማርያም\nኀበወልድኪ ኄር መድኃኔዓለም\n\nየአብ ሙሽራ ነሽ የወልድም እናቱ\nለመንፈስ ቅዱስ ነሽ ጽራሃዊቱ\nበፊትሽ ሰገዱ ቅዱሳን መላእክት\n\nለምኝልን ማርያም\nለምኝልን ማርያም\nከቸሩ ልጅሽ ከመድኃኔዓለም\n\nከዋክብት ብርሃናት ሳይታይ ደመና\nታስበሽ ኖረሻል በአምላክ ህሊና\nገብርኤል ነገረሽ የክብርሽን ዜና\n\nለምኝልን ማርያም\nለምኝልን ማርያም\nከቸሩ ልጅሽ ከመድኃኔዓለም\n\nየወርቅ ታቦት ነሽ በሰማይ ያለሽ\nየፅድቅ ንግስት ነሽ የተመሰገንሽ\nበእናትነትሽ ተመካ ልብሽ\n\nለምኝልን ማርያም\nለምኝልን ማርያም\nከቸሩ ልጅሽ ከመድኃኔዓለም\n\nየአለሙን ጌታ በእቅፍሽ አየነው\nበመሀፀንሽ አድሮ ቃል ስጋ የሆነው\nእግዚአብሔር ስላንቺ ምስጋናው ብዙ ነው\n\nለምኝልን ማርያም\nለምኝልን ማርያም\nከቸሩ ልጅሽ ከመድኃኔዓለም\n\nየዳዊት ልጅ ማርያም ትምክህታችን\nየአማኑኤል እናት መሰብሰቢያችን\nየእግዚአብሔር ከተማ መማፀኛችን\n\nለምኝልን ማርያም\nለምኝልን ማርያም\nከቸሩ ልጅሽ ከመድኃኔዓለም\n\nድንግል በክሊሄም በነፍስም በስጋ\nጎዶሎ ይምላል አንቺን የተጠጋ\nክርስቶስ ወልደሽ ክሳችን ተዘጋ\n\nለምኝልን ማርያም\nለምኝልን ማርያም\nከቸሩ ልጅሽ ከመድኃኔዓለም\n\nበፊትሽ ልማፀን ቆምኩኝ ከደጅሽ\nልመናዬ ሁሉ ይግባ ከጆሮሽ\nለሚጠራሽማ ማርያም ቅርብ ነሽ\n\nለምኝልን ማርያም\nለምኝልን ማርያም\nከቸሩ ልጅሽ ከመድሐኒአለም\nሰአሊለነ ማርያም\nሰአሊለነ ማርያም\nሀበወልድክሂር መድኃኔዓለም', 'am', 7, 0),\n(5, 'ይናፍቃል ልቤ በብዙ', 'ይናፍቃል ልቤ በብዙ\nይናፍቃል ልቤ በብዙ\nሊታዘዝህ ሊገዛልህ ሊያገለግልህ\n\nኃጢአትም እንደ ህልም\nውስጤን ሲገዛኝ\nበፍቅርህ ስታየኝ አነባለሁኝ\nበውስጤ ይፈሳል ፍቅርህ እንደዘይት\nእንዴት ልርሳው ቸርነትክን ከተለወጥኩብህ\n\nለፍርድ አትቸኩልም በልጆችህ ላይ ልቦናዬን ማርከኸዋል ከምንም በላይ\nየእኔ አይደለምና የምድር ሰውነቴ\nላገልግልህ ባሪያህ ሆኜ ቸር ነህ መዳኒቴ\n\nአመፅን ለመስራት ስፈጥን ከመንገድ ከአጠገቤ አይሃለሁ እብደቴን ስታግድ እንደምን ወደድከኝ ምን እከፍልሃለሁ\nከሰው ምንም የማትወስድ\nመሆንክን አውቃለሁ\n\nእንግዳ ነህ ለእኔ አዲስ ነህ ለቤቴ\nትልቁ ዘመዴ ለብቸኝነቴ\nዳር ሆነህ አታየኝ ሀዘን ሲገርፈኝ\nለጥያቄዎቼ ሁሉ መልስ የምትሆነኝ', 'am', 8, 0),\n(5, 'ማራኪው እየማረከ', 'ማራኪው እየማረከ\nማራኪው እየማረከ\nባራኪው እየባረከ\nበፍቅሩ ስንቱን ረታ\nሰባሪው የድሉ ጌታ\n\nየሞቴን ወጥመድ ሰባብሮ\nበድምፁ ጥልቁን በርብሮ\nሰደደኝ ማህተብ አትሞ\nየአርነት ግርማ ሸልሞ\n\nሰገባው ያዘንባል ፍቅር\nከአማልክት የለውም ወደር\nተሳስሯል ደሙ ከደሜ\nበሞቱ ሰፍኗል ሰላሜ\n\nምስጉን ነው የተባረከ\nበፍጥረት የተመለከ\nመተኪያ የለው አምሳያ\nለክብሩ እንበል ሀሌሉያ\n\nየጓዳ የእልፍኝ ልቅት\nአንተ ነህ ክብሬ ሰገነት\nከቦኛል በመላዕክቱ\nነጥቆኛል ስቦ ከእሳቱ', 'am', 9, 0),\n(5, 'እንደኔ የማርከው ማንን ነው', 'እንደኔ የማርከው ማንን ነው\nእንደኔ የማርከው ማንን ነው\nእንደኔ ይቅር ያልከው ማንን ነው\nሀጢያቱ በዝቶበት\nበደሉ በዝቶበት\nየማርከው እንደኔ ከቶ ማነው\n\nበሞገስ አስጊጠህ በዜማ ቃኘኸኝ\nፊትህ ምታቆመኝ ጌታየ እኔ ማነኝ\nለኔ ያበዛኸው አቤት ደግነትህ\nምረኸኝ ምረኸኝ አያልቅም ምህረትህ\nአይተኸኝ በምህረት\nአይተኸኝ በምህረት\nዛሬም አለሁኝ በህይወት\n\nየምስጋና መስዋት ማቅረቢያ መሰዊያ\nልቤ ንፁህ ባይሆን ፀጋየን አልቀማህ\nትቀበለኛለህ ምልተህ በጎደለ\nእኔን የወደደ እንዳንተ ማን አለ\nአይተኸኝ በምህረት\nአይተኸኝ በምህረት\nዛሬም አለሁኝ በህይወት\n\nበምኞት ተስቤ ለሀጢያት ተሽጬ\nበመስቀልህ ስራ ከሞት ጣር አምልጬ\nአንተ እንዳዳነከው ሰው መሆን ቢያቅትም\nእኔ ተስፋ ብቆርጥ ተስፋ አትቆርጥብኝም\nአይተኸኝ በምህረት\nአይተኸኝ በምህረት\nዛሬም አለሁኝ በህይወት\n\nየኖርኩበት ዘመን የቁጣ ልጅ ሆኜ\nምዕራፉ ተዘጋ ባንተ በአዳኜ\nከኔ ምንም ሳይኖር አንተ ሁሉን ሆነህ\nሰገነት ታየሁኝ ስለእኔ ተንቀህ\nአይተኸኝ በምህረት\nአይተኸኝ በምህረት\nዛሬም አለሁኝ በህይወት\n\nእኔን ማረኝ ከምል ከፊትህ ወድቄ\nበሌላው ፈራጅ ነኝ እራሴን አፅድቄ\nመመልከት ባልችልም የዓይኔን ምሰሶ\nየሚያኖረኝ ፍቅርህ ነው ይን ሁሉ ታግሶ\nአይተኸኝ በምህረት\nአይተኸኝ በምህረት\nዛሬም አለሁኝ በህይወት', 'am', 10, 0),\n(5, 'የትኛው ስራዬ', 'የትኛው ስራዬ\nየትኛው ስራዬ የትኛው ህይወቴ\nየትኛው ስራዬ የትኛው ህይወቴ\nሞገስ ሆኖኝ እንጂ እግዚአብሔር አባቴ\nሞገስ ሆኖኝ እንጂ እግዚአብሔር አባቴ\n\nልጅዋን ትረሳ ዘንድ እናት እንኳን ብትስት\nአንተ ግን ወደድከኝ ላትረሳኝ በሞት\nበመዳፍህ ቀርፀህ ሁሌ ታየኛለህ\nመድሀኒቴ ኢየሱስ በደሌን እረስተህ\nቢምረኝ ነው ቢምረኝ በመቅደሱ ያቆመኝ\nቢያስበኝ ነው ቢያስበኝ በከፍታው ያኖረኝ\n\nየአብርሀምን ምግባር የዮሴፍን እምነት\nፅድቅን ባልኳለው ባላደርግ መቀነት\nማህተቡን ይዣለሁ የደሙን ጠብታ\nመድሀኒቴ ኢየሱስ አክብሮኛል ጌታ\nቢምረኝ ነው ቢምረኝ በመቅደሱ ያቆመኝ\nቢያስበኝ ነው ቢያስበኝ በከፍታው ያኖረኝ\n\nእንዳልፈው የረዳኝ የእሳቱን ባህር\nምን ምግባር ኖሮኝ ነው ከፅድቅ የሚቆጠር\nየልቤ ኩራት ነው የአይኔ ከፍታ\nመድሀኒቴ ኢየሱስ የሠራዊት ጌታ\nቢምረኝ ነው ቢምረኝ በመቅደሱ ያቆመኝ\nቢያስበኝ ነው ቢያስበኝ በከፍታው ያኖረኝ\n\nዘይቱ እንዴት ፈላ በራሴ ያፈሰስከው\nዙፋን ልታወርሰኝ ልቤን የመረጥከው\nየኔ የተወደደው ከኤልያም ደም ግባት\nመድሀኒቴ ኢየሱስ ሆነኸኝ ነው ውበት\nቢምረኝ ነው ቢምረኝ በመቅደሱ ያቆመኝ\nቢያስበኝ ነው ቢያስበኝ በከፍታው ያኖረኝ\nቢምረኝ ነው ቢምረኝ በመቅደሱ ያቆመኝ\nቢያስበኝ ነው ቢያስበኝ በከፍታው ያኖረኝ', 'am', 11, 0),\n(5, 'ምስጢረኛዬ ነሽ', 'ምስጢረኛዬ ነሽ\nአውቀዋለሁ ደጅሽን የእረፍት ቦታዬን\nጽኑ ሰላም ጸጥታ ማግኛዬን\nየት እሄዳለው አልልም ሲከፋኝ\nኪዳነ ምህረት አንቺ እያለሽልኝ\nኪዳነ ምህረት አንቺ እያለሽልኝ\n\nከአጸደ መቅደስሽ ከስዕልሽ ስር\nእረፍቴ በዚያ ነው በቅዱሱ ደብር\nከተራራው አናት ከደጅሽ መጥቼ\nሰምሮልኛል ስምሽን ጠርቼ\n\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ\n\nየሮማን አበባ መዓዛሽ ተወዳጅ\nበረከትን ልቅሰም ሳልለይ ካንቺ ደጅ\nአስራትሽ አድርጊኝ ጠቅልይኝ እናቴ\nታብብልኝ ትፍካልኝ ሕይወቴ\n\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ\n\nአጠገቤ ጎኔ በዙሪያዬ እንዳለሽ\nእንደርሱ ነው ልቤ እማ የሚያወራሽ\nአልቅሼ ሲቀለኝ ነግሬሽ የውስጤን\nአትዘገይም ስትሠሪልኝ ቤቴን\n\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ\n\nየእንጦጦዋ እናቴ እምዬ የምልሽ\nኪዳንኪ ደጓ የልብን ሰሚ ነሽ\nበሄድኩበት አለሽ ተከትለሽኛል\nስላለሽኝ ሰላም ይሰማኛል\n\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ\nሚስጥረኛዬ ነሽ ሚስጥረኛዬ\nኪዳነ ምህረት መፅናኛዬ', 'am', 12, 0),\n(5, 'ሁሉም ያልፋል', 'ሁሉም ያልፋል\nሁሉም ያልፋል እግዚአብሔር ያሳልፋል\nሁሉም ያልፋል እግዚአብሔር ያሳልፋል\nልጆቹን መቼ ይረሳል\n\nብርሃን ይመጣል ጨለመው ተገፎ\nደስታ ይሆናል መከራው አልፎ\nየምስራች ቃል ይሞላል በአፋችን\nሀዘናችን ጠፍቶ ይፈካል ፊታችን\nየምስራች ቃል ይሞላል በአፋችን\nሀዘናችን ጠፍቶ ይፈካል ፊታችን\n\nሁሉም ያልፋል እግዚአብሔር ያሳልፋል\nልጆቹን መቼ ይረሳል\n\nበትር ነው ምርኩዝ ነው እሱን ላመኑበት\nባህር ውቅያኖሱን ከፍለው የሚያልፉበት\nበእሳት መካከል በግፍ ለተጣሉ\nውሃ እየሆናቸው በድል ይወጣሉ\nበእሳት መካከል በግፍ ለተጣሉ\nውሃ እየሆናቸው በድል ይወጣሉ\n\nሁሉም ያልፋል እግዚአብሔር ያሳልፋል\nልጆቹን መቼ ይረሳል\n\nማስተዋል ጥሩ ነው ትዕዛዛቱን ማክበር\nያኖራል በሕይወት በሰማይ በምድር\nየማያልፍ ቀን የለም ታሪክ የማይሆን\nበአምላክ አንድ ቀን ነው አንድ ሺ ዘመን\nየማያልፍ ቀን የለም ታሪክ የማይሆን\nበአምላክ አንድ ቀን ነው አንድ ሺ ዘመን\n\nሁሉም ያልፋል እግዚአብሔር ያሳልፋል\nልጆቹን መቼ ይረሳል\n\nይቅርታ እንዲሰጠን በደልን ሳይቆጥር\nማረን እንበለው ስለሆነ ፍቅር\nነገ ቀን ሲመጣ ብርሀኑ ሲያበራ\nፊታችን እንዳይዞር ወደ ክፉ ስራ\nነገ ቀን ሲመጣ ብርሀኑ ሲያበራ\nፊታችን እንዳይዞር ወደ ክፉ ስራ', 'am', 13, 0),\n(5, 'ያየህብኝን ያላሳየህብኝ', 'ያየህብኝን ያላሳየህብኝ\nያየህብኝን ያላሳየህብኝ\nደግሞም በደሌን የረሳህልኝ\nአስገረመኝ ለኔ ያለህ\nአስደመመኝ ለኔ ያለህ\nብበድልህ ብበድልህ\nብበድልህ ብበድልህ\nእየቻለኝ ያ ትከሻህ\n\nእጄን ባፌ ያስጫነኝ አስገረመኝ ደጉ ልብህ\nፊትህ አይጠቁር በሀጥያቴ እንዳላየህ ታልፈዋለህ\nሳታሳጣኝ በሰው መሀል የኔ ከዳኝ የልቤ ጥግ\nአላነፅኩም ካየህልኝ ከከፍታ ከዚያ ማይርቅ\n\nአስገረመኝ ለኔ ያለህ\nአስደመመኝ ለኔ ያለህ\nብበድልህ ብበድልህ\nእየቻለኝ ያ ትከሻህ\n\nበርሱ ምህረት ከድቅድቁ ከወጣሁኝ ከጨለማ\nለይሁዳ ክፉ ወሬ ልቤ አይሰጋ ላለም ዜማ\nበነበልባል ሲያቃጥለኝ የስምዖን አንደበቱ\nየሳት ልሳን ሆነኽልኝ ባንተ አለፈ ያ ክረምቱ\n\nአስገረመኝ ለኔ ያለህ\nአስደመመኝ ለኔ ያለህ\nብበድልህ ብበድልህ\nእየቻለኝ ያ ትከሻህ\n\nከበለስ ስር የሰራሁት አለም ተፍቶ ያቃለለው\nእረሳሁት ትቼዋለሁ እንዳንት ያለ ከቶ ማነው\nሰው ሲሸሸኝ የቀረብከኝ አንተ ኦኮ ነህ መድሀኒቴ\nአይንህ አይቶኝ መች አለፍከኝ አነሳኸኝ ቸር አባቴ\n\nአስገረመኝ ለኔ ያለህ\nአስደመመኝ ለኔ ያለህ\nብበድልህ ብበድልህ\nእየቻለኝ ያ ትከሻህ\n\nመክሮ መክሮ ሲታክተው ውጣ ብሎ እየጣለ\nስንቱ አለፈ በመከራ ሰው ወገኑን ስላልቻለ\nየኔ ጌታ ፍቅሩ ችሎኝ ለፊው ክንዱ አሻገረኝ\nለውለታው ከእንባ በላይ የሚያረካው ምን ቃል አለ', 'am', 14, 0),\n(5, 'እኔ ደካማውን', 'እኔ ደካማውን\nእኔን ደካማውን ቀኝህ እያገዘኝ\nእኔን ኃጢአተኛውን ክንድህ እየረዳኝ\nሳትቆጥረው በደሌን ከፊትህ አቆምከኝ\nገበናዬን ከድነህ በከፍታ አዋልከኝ\n\nቀኝህ ባታግዘኝ ባትረዳኝ መድኅኔ\nማነው ሰው እያለ ይቆም ነበር ጎኔ\nመታያ ሆነኸኝ ከፍ ያለ ሰገነት\nሁሌም እደምቃለሁ በእጅህ በረከት\n\nየደማስቆ ብርሃን ሕይወቴን ቀይሮት\nግብሬ መሰደድ ነው ለስምህም መሞት\nአዳፋው ቀጸላ ዛሬ መች ታሰበ\nቤቴ ደምቆ ዋለ ፍቅር እያነበበ\nእልፍ እየበደልኩ በእልፍ ምሕረት\nፊቴን እያዞርኩ ሳይጠላኝ ያንተ ፊት\nአብዝቼ ስርቅህ አጥብቀህ ቀረብከኝ\nየማፍቀርህ ጥጉ መውደድህ አኖረኝ\n\nከበደል በማይርቅ በሥጋ ምኞቱ\nጽድቅን እየሸሸው ብውል ከጥፉቱ\nአቤት የኔ ጌታ አቤት ያንተ ጸጋ\nሁሌም ያኖረኛል ሌቱን እያነጋ\nእልፍ እየበደልኩ በእልፍ ምሕረት\nፊቴን እያዞርኩ ሳይጠላኝ ያንተ ፊት\nአብዝቼ ስርቅህ አጥብቀህ ቀረብከኝ\nየማፍቀርህ ጥጉ መውደድህ አኖረኝ', 'am', 15, 0),\n(5, 'መሸሸጊያዬ ነው', 'መሸሸጊያዬ ነው\nመሸሸጊያዬ ነው ያደረገልኝን ተመልከቱ\nከእንባ ሸለቆ ይህው ወጣው በምህረቱ\nየእግዚአብሔር ልጅ ሆነን ሞገስ\nተመስገን በሉ ይክበር ይንገስ\nየድንግል ማርያም ልጅ ሆነን ሞገስ\n\nብቻዬን ነኝ ብዬ እንባዬን አልዘራም\nማምለጨረ ግንቤ ነው ጌታዬ የአንተ ስም\nማለፍ ሆኖልኛል በስንጥቅ አለት\nአንተ ስላለህኝ ጌታ የኔ አባት\nአንተ ስላለህኝ ጌታ የኔ አባት\n\nይስሃቅ ከእናቱ ሞት በብርቱ ተፅናና\nለኔ የለህ እድል ሰናይት ናትና\nእንደ እናት አጉራሽ ነህ ደግሞም ፅኑ አፍቃሪ\nክንድህ ነው ለቤቴ የመንገዴ መሪ\nክንድህ ነው ለቤቴ የመንገዴ መሪ\n\nአማርሬ አላውቅም በሆነብኝ ሁሉ\nእግዚአብሔር ወዳጄ ታማኝ ነው ለቃሉ\nነገን አይቶልኛል የድሌን ከፍታ\nስሙ ይንገስልኝ የሰራዊትጌታ\nስሙ ይንገስልኝ የሰራዊትጌታ\n\nመንገድ የወደቀ ድጋፍ ያጣውን ሰው\nያላንተ ወዳጄ ተስፋ ማን ሊሆነው\nየደካማው ምርኩዝ የደሃ አደግ አባት\nጣትህ ስትዳሰሰኝ ተነሳው ከውደቀት\nጣትህ ስትዳሰሰኝ ተነሳው ከውደቀት', 'am', 16, 0),\n(5, 'እንደ ምሕረትህ', 'እንደ ምሕረትህ\nእንደ ምህረትህ ብዛት ማረኝ\nመተላለፌን ደምስስልኝ\nአንተን ብቻ በደልኩኝ\nትእዛዝህን ተላለፍኩኝ\n\nእጅግ በዛ የኔ ኃጢያት ከፀጉሬ\nበመቅደስ እጮሀለሁ አቀርቅሬ\nአትቅጸፈኝ በመአትህ አትገስፀኝ\nጌታዬ ሆይ የማዳንህን ደስታ ስጠኝ\nጌታዬ ሆይ የማዳንህን ደስታ ስጠኝ\n\nእንደማውቅህ በአደባባይ ምን ብናገር\nስራዬ ግን ይህን እውነት አይመሰከር\nከእልፍኝህ ብሄድ ርቄ ከአንተ ፍቅር\nሁሉን ከሰርኩ አላተረፍኩ አንዳች ነገር\nከእልፍኝህ ብሄድ ርቄ ከአንተ ፍቅር\nሁሉን ከሰርኩ አላተረፍኩ አንዳች ነገር\n\nማን እንደኔ ከትውልዱ የበደለ\nመኃሪ አምላክ ከአንተ በቀር ወዴት አለ\nየዳዊት ልጅ ማረኝ ብዬ እጮሀለሁ\nእያነባሁ በጉልበቴ እሰግዳለሁ\nእያነባሁ በጉልበቴ እሰግዳለሁ\n\nበመዳፈር እንደ አፍኒንና እንደ ፊንሀስ\nሰውነቴን አቆሸሽኩኝ ያንተን መቅደስ\nአሳልፈህ እንዳትሰጠኝ ለኃጢአቴ\nእንደ ቀድሞ ልጄ በለኝ ደጉ አባቴ\nእንደ ቀድሞ ልጄ በለኝ ደጉ አባቴ', 'am', 17, 0),\n(5, 'ኪዳነ ምህረት የረፍቴ እናት', 'ኪዳነ ምህረት የረፍቴ እናት\nኪዳነ ምህረት የዕረፍቴ እናት\nሰላም ሆነ ባንች አማላጅነት\nንፅህት ድንኳን በእምነት ያጌጥኩብሽ\nሰላም ሆነ በአማኑኤል ልጅሽ\n\nየብርሀን ዝናር ባይኖረኝም\nበንጉስ ፊት ተሸልም ብቆም\nበልጅሽ ነው ውበቴ ማማሩ\nበምልጃሽ ነው ስሜ መቀየሩ\nበልቤ ላይ ተነበበ ልጅሽ\nአሁን ስሜ ተጠርቷል በልጅሽ\nከታች በምድር እስከሰማይ ድረስ\nድርሻየ ነው ስምሽን ማወደስ\nከታች በምድር እስከሰማይ ድረስ\nድርሻየ ነው ስምሽን ማወደስ\n\nኪዳነ ምህረት የእረፍቴ እናት\nሰላም ሆነ ባንች አማላጅነት\nንፅህት ድንኳን በእምነት ያጌጥኩብሽ\nሰላም ሆነ በአማኑኤል ልጅሽ\n\nየከበረ ሁነሽ ንግግሬ\nቅኔ አነሳሁ ለክብርሽ ዘማሬ\nእንደ ዝግባ ከፍ ብየ ብታይ\nወጥቶልኝ ነው በሰማይ ፀሀይ\nስለ ምልጃሽ ዘይቱ ፈሰሰ\nአንቺን ይዤ ሙሽራው ደረሰ\nቀንዲሌ ነሽ ድንግል አዛኝቱ\nበልጅሽ ነው የነፍሴ ፅናቱ\n\nኪዳነ ምህረት የእረፍቴ እናት\nሰላም ሆነ ባንች አማላጅነት\nንፅህት ድንኳን በእምነት ያጌጥኩብሽ\nሰላም ሆነ በአማኑኤል ልጅሽ\n\nከኤልያብ ቢደምቅ ደም ግባቴ\nማን ሊመርጠኝ ያላንች እናቴ\nተዋብኩብሽ ገፄ በአንች አበራ\nአንደበቴ ስምሽን ሲጠራ\nእንደ ሙሴ እንደ አሮን በትር\nማምለጫየ ከፈርዖን ቀንበር\nከእንግዲማ እኔ እንዴት አዝናለሁ\nአማላጀ አንችን ይዠዤሻለሁ', 'am', 18, 0),\n(5, 'መልካም ስሞ ይኑረኝ', 'መልካም ስሞ ይኑረኝ\nጌታ ሆይ በብዙ ስውጠኝ\nጌታ ሆይ በብዙ ስውጠኝ\nከመልካም ሽቱ መልካም ስሞ ይኑረኝ\nከመልካም ሽቱ መልካም ስሞ ይኑረኝ\n\nሞት ሞታለብሰውነ ያቺን ዛፍ ነቅፌ\nያንተን ስሞ ያስጎምዠኝ እርሱ ይሁን ትርፌ\nአንተን ብቻ እንዳይ ዓይኔን ኳስው እምነት\nአስረህ አስቀምጠኝ በፍቅር ሰንሰለት\n\nወንድሙን ሚያታልል ተረከዝ የሚይይዝ\nየያዕቆብ ካባው አይታይ በኔ ወዝ\nይኑረኝ መልካም ስሞ ልትታገለኝ ና\nእስራኤል ሆይ በለኝ ስሜን ስውጥና\n\nበደማስቆ መንገድ አይለቅ ዘመኔ\nከሰማይ ብርሃን ያንጸባርቅ ወደኔ\nየእውነት ለውጠኝ ትችላለህ አንተ\nእንዴት ክፋ ላውጣ አንተ ለኔ ሞተህ\n\nስሜን ባገኘውም ሄጄ ጎልጎታ\nአሁንም እንዲያው ነኝ ለውጥየለኝም ጌታ\nከሚቃጠለው ስብ ይከፋል ስም ሽታው\nአማኝ መባል ብቻ ምንድን ነው የሚጠቅመው\nአማኝ መባል ብቻ ምንድን ነው የሚጠቅመው\n\nበደማስቆ መንገድ አይለቅ ዘመኔ\nከሰማይ ብርሃን ያንጸባርቅ ወደኔ\nየእውነት ለውጠኝ ትችላለህ አንተ\nእንዴት ክፋ ልሁን አንተ ለኔ ሞተህ', 'am', 19, 0),\n(5, 'እንደምታኖረኝ ሳስብ', 'እንደምታኖረኝ ሳስብ\nእንደምታኖረኝ ሳስብ\nማዳንህን ተርቤ\nዘምር አመስግን አለኝ\nየወደደህ ልቤ\nእንደምታኖረኝ ሳስብ\nማዳንህን ተርቤ\nዘምር አመስግን አለኝ\nየወደደህ ልቤ\n\nበቤተልሔም ርሃብ\nብሄድ ብሰደድ ሞዓብ\nበጉድለት ብገባም ቤቴ\nአልተለየኸኝ አባቴ\n\nየዘላለም መኖሪያ ነህ የዘላለሞ\nአንተን ያለ አልተረሳም አልተጣስም\n\nወዳጅነት ዋጋ አቶ\nጊዜውን ልቤ ፈርቶ\nለካስ እኔ የምኖረው\nወዳጄ ሆይ በአንተ ነው\n\nየዘላለም መኖሪያ ነህ የዘላለሞ\nአንተን ያለ አልተረሳም አልተጣስም\n\nሕይወቴ እጅግ ቢመር\nቢከፋኝ የሰው ነገር\nየጨለማውን መንጋ\nተሻገርኩ በአንተ ጸጋ\n\nየዘላለም መኖሪያ ነህ የዘላለሞ\nአንተን ያለ አልተረሳም አልተጣስም\n\nቢሸጡኝ ወንድሞቼ\nቢያርቁኝ ከሳሾቼ\nበሐሰት ሸንጎ ብታሰር\nታነሳኛለህ በክብር', 'am', 20, 0),\n(5, 'ቀራንዮ', 'ቀራንዮ\nቀራንዮ ቀራንዮ ጎልጎታ\nበአንቺ ምድር የዓለም ጌታ\nተጨነቀ ተሰቃየ ተንገላታ\nተጨነቀ ተሰቃየ ተንገላታ\n\nበማዕለ ምድር ዙፋን መስቀል ተክሎ\nልብስን አለበሰን እርቃኑን ተሰቅሎ\nቁስላችን ተሻረ በመከራ ቆስሎ\nቁስላችን ተሻረ በመከራ ቆስሎ\n\nየአማረ ልብስ የለው ደም ሆኗል ቀሚሱ\nየወርቅ ካባ የለው እርቃኑን ነው እርሱ\nበፍቅር ይገዛል ተሰቅሎ ንጉሡ\nበፍቅር ይገዛል ተሰቅሎ ንጉሡ\n\nየስልጣኑን በትር በእጁ የያዘው\nሳዶር እና አላዶር የበትር ሚስማር ነው\nእየቸነከሩት አላማው ፍቅር ነው\nእየቸነከሩት አላማው ፍቅር ነው\n\nሞታችንን ወስዶ ሕይወትን ሸለመ\nሕሙማንን ሊያድን ለፍቅር ታመመ\nከውድቀት ሊያነሳን ወደቀ ደከመ\nከውድቀት ሊያነሳን ወደቀ ደከመ\n\nስለኛ ብለህ ተንገላታህ\nስለኛ ብለህ ተንገላታህ', 'am', 21, 0),\n(5, 'ማረን አምላካችን', 'ማረን አምላካችን\nአንተ የሰላም ንጉስ መልካሙ እረኛ\nእግዚአብሔር ብቻ ነው እውነተኛ ዳኛ\nእንባችንን አብስ ይብቃ ሀዘናችን\nእጃችንን ሰጠን ማረን አምላካችን\n\nየኢትዮጵያን ትንሳኤ ዘመናት ናፍቀናል\nክንዳችንን ሳይሆን ስምህን አምነናል\nበወደድከው ግዜ ሰላም እንደሚሆን\nየቀደመው እባብ ይቀጥቀጥልን\nየቀደመው እባብ ይቀጥቀጥልን\n\nእውነት ነው ጌታችን በዝቷል በደላችን\nአክሊላችን ወድቋል ተገፏል ፀጋችን\nበእርኩሰት ስንጠፋ ተላልፈን ህግህን\nበአባታዊ ፍቅርህ ማረን ልጆችህን\nበአባታዊ ፍቅርህ ማረን ልጆችህን\n\nአንድስንኳ የለም ፅድቅን የሚያወራ\nየገዛ ክንድህ ነው ተአምር የሚሰራ\nእንዳንጠፋፋ እንዳንነቃቀስ\nየእጅህ ስራ ሁሉ በስምህ ይፈወስ\nየእጅህ ስራ ሁሉ በስምህ ይፈወስ\n\nየኢትዮጵያን ትንሳኤ ዘመናት ናፍቀናል\nክንዳችንን ሳይሆን ስምህን አምነናል\nበወደድከው ግዜ ሰላም እንደሚሆን\nየቀደመው እባብ ይቀጥቀጥልን\nየቀደመው እባብ ይቀጥቀጥልን', 'am', 22, 0),\n(5, 'ከመስቀሉ ስር ነው አድራሻዬ', 'ከመስቀሉ ስር ነው አድራሻዬ\nከመስቀሉ ስር ነው አድራሻዬ\nእናቴን ልቀበል ከጌታዬ\nሀዘኔን እንድረሳው ጭንቀቴን\nአማኑኤል ሰጠኝ መጽናኛዬን\nአማኑኤል ሰጠኝ መጽናኛዬን\n\nእርሷ ባለችበት ጌታ ደግሞ አለ የእናቱን ምልጃ እየተቀበለ\nበክንዶቿ ታቅፎ ታዝሏል በጀርባዋ\nእርሱ ይታረቃል ስለ ልመናዋ\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል\n\nቀራንዬ የሄደ መስቀሉ ስር ያለ\nከማይቀበሉት ካይሁድ የተለየ\nታላቃን ስጦታ ከርሱ ይቀበላል\nማርያም ንፅይት ድንግል ሳአሊለነ ይላል\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል\n\nበተጋድሎ አይደለም በብዙ ትሩፋት\nበብርታት አይደለም በእውቀትም ብዛት\nምታስፈልገኝን የሰጠኝ ጌታ ነው\nክብሯን መናገሬ ለራሴም ክብር ነው\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል\n\nእናታችን ጽዮን ሰው ሁሉ ይላታል\nልኡል መስርቷታል ሰው ተወልዶባታል\nጌታዬ ኢየሱስን አምላኬ ነው ያላለ\nእናቱ እንድትሆነው እርሱ መች ታደለ\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል\nየኢየሱስ እናት ማርያም ድንግል\nቆምኩኝ ቀራኒዬ አንችን ልቀበል', 'am', 23, 0),\n(5, 'እንዳላጠፋ ሰው', 'እንዳላጠፋ ሰው\nእንዳላጠፋ ሰው በሰው ፊት ምታየው\nጌታዬ ባንተ ንው ገመናዬ የተሸፈነው\nእንዳላጠፋ ሰው በሰው ፊት ምታየው\nጌታዬ ባንተ ንው ገመናዬ የተሸፈነው\n\nቀራንዮ ቆመህ በመስቀሉ ዙፋን\nበሰው ፊታ ዓለሙን ስታድን\nእርቃንህን ስትሆን ነውሬ ተሸፈነ\nበቆሰልከው ቁሰል ለኔ መዳን ሆነ\n\nሃጢያትን የምትከድን ነህ ከባቴ አበሳ\nየናዝሬቱ መልካም የይሁዳ አንበሳ\nማለዳ ማለዳ ሃጢያቴን ብትቆጥር\nዛሬ እንዴት እቆም ነበር\n\nከሳሾቼ አፈሩ ድንጋይን የያዙ\nአንተ ስትምረኝ ሄዱ እየተከዙ\nበሰላም ሸኘኸኝ አድነኸኝ ከሞት\nበፍቅርህ ሸፍነህ ያለፈውን ሃጢያት\n\nአልፀዱም እጆቼ ከበደል ከጥፋት\nአንደበቴ አብዝቷል ሽንገላና ሃሰት\nእንዳላየህ አለፍክ አንዳች እንዳልሰማ\nቃላት አይገልፀውም ለኔ ያለህማ', 'am', 24, 0),\n(5, 'ያከበርከኝ', 'ያከበርከኝ\nያከበርከኝ እኔ ማነኝ\nያስከበርከኝ እኔ ማነኝ\nውለታህ በዛ አባቴ ውለታህ በዛ\nሞገስ ከበባት ቅጥሬ ሆንከኝ መዓዛ\n\nማዕበሉ አለፈ ባንተ ያለኝ አላሳልፍ\nስኬቴን ጻፈው ጣትህ የመኖሬን መጽሐፍ\nቃልህ ባያዘው ጭንቄን ባያደላድለው\nዓለም ትለኝ ነበር እኔን መድረሻ የሌለው\nዓለም ትለኝ ነበር እኔን መድረሻ የሌለው\n\nያከበርከኝ እኔ ማነኝ\nያስከበርከኝ እኔ ማነኝ\nውለታህ በዛ አባቴ ውለታህ በዛ\nሞገስ ከበባት ቅጥሬ ሆንከኝ መዓዛ\n\nቀን አየች ነፍሴ ባንተ ከመሶብህ በልታ\nከእሳት ማዕበል ነጥቀህ አኖርካት በከፍታ\nቀን በቀን ቅኔን ይዤ በፊትህ የምጓደደው\nሚዛንህ ጸጋ ሞልቶት በፍቅርህ ከብሬ ነው\nሚዛንህ ጸጋ ሞልቶት በፍቅርህ ከብሬ ነው\n\nያከበርከኝ እኔ ማነኝ\nያስከበርከኝ እኔ ማነኝ\nውለታህ በዛ አባቴ ውለታህ በዛ\nሞገስ ከበባት ቅጥሬ ሆንከኝ መዓዛ\n\nበወኅኒ ብርሃን ሞላ ሰንሰለቱ ቀለጠ\nበድካሜ እየራራ ሞት በሞትህ ተዋጠ\nስላንተ ማን አወቀ ጠንቅቆስ ማን ተረዳ\nእኔ ግን ቀምሼ ነው የምለው ማራናታ\nእኔ ግን ቀምሼ ነው የምለው ማራናታ\n\nያከበርከኝ እኔ ማነኝ\nያስከበርከኝ እኔ ማነኝ\nውለታህ በዛ አባቴ ውለታህ በዛ\nሞገስ ከበባት ቅጥሬ ሆንከኝ መዓዛ\n\nመፍረድ የማይሰለቻት ምድሪቱ ከሳሽ ሆና\nሲገርማት ውሎ ያድራል ስሰለፍ ለበገና\nየዘንዶው ጥርሱ ሲፏጭ ጉድጓድ እየተማሰ\nበምሥጋናዬ ብቻ ኑሮዬ ተዳበሰ\nበምሥጋናዬ ብቻ ኑሮዬ ተዳበሰ\n\nያከበርከኝ እኔ ማነኝ\nያስከበርከኝ እኔ ማነኝ\nውለታህ በዛ አባቴ ውለታህ በዛ\nሞገስ ከበባት ቅጥሬ ሆንከኝ መዓዛ\n\nያህዌን ያለ ሲወድቅ ማን አለ የከሰረ\nአያይም ዓይኔ ጉድለት ይኖራል እየዘመረ\nኑሃሚን እንዳየችህ በእንባ ማዕበል ሆና\nማግኘት ይመጣል ፈጥኖ አላዝንም በፈተና\nማግኘት ይመጣል ፈጥኖ አላዝንም በፈተና', 'am', 25, 0),\n(5, 'እኔ አላዝንም', 'እኔ አላዝንም\nእኔ አላዝንም አንተ እያለኸኝ አልከፋም\nእናት አባት ዘመዴ አንተ ነህ የኔ ተስፋ\n\nለሚወድህ ለሚያገለግልህ\nለጠራኸው ጌታዬ እንደሃሳብህ\nቢያስጨንቅም ነገር ለበጎ ነው\nቢያስተክዝም ፍጻሜው መልካም ነው\n\nአሜን ይሁን አንተ የወሰንከው ለእኔ የፈቀድከው\n\nከእናንተ በላይ የምታጽናናኝ\nከአባት በላይ አቅፈህ የምትስመኝ\nየወለድከኝ በጽኑ መከራ\nያሳደከኝ በመስቀልህ ስራ\n\nስላለኸኝ ኢየሱስ ሰላሜ ተጽናናሁ ደግሜ\n\nአላነባም ሰው የለኝም ብዬ\nየሻትከውን ስትሰራው ጌታዬ\nየኔም ጉዞ ወዳንተ ነውና\nመሰብሰቤ ከቶ አይቀርምና\n\nላመስግንህ ስለሆነው ሁሉ እግዚአብሔር ኃያሉ\n\nያጣሁትን በእጥፍ ትተካለህ\nሸለቆዬን ደስታ ትሞላለህ\nየፍቅርህ እጅህ ከዓይኔ በታች አርፏል\nእያበሰ እንባዬን አንጥፏል\n\nዘምራለሁ ይኸው እንደገና ሁሉም አልፏልና', 'am', 26, 0),\n(5, 'የለውም ደም ግባት', 'የለውም ደም ግባት\nየለውም ደም ግባት\nአይተን እንድንወደው\nበሰው የተናቀ\nሆነ የሕማም ሰው\n\nበወዳጆቹ ቤት የቆሰለው\nቁስል ይታያል በእጆቹ\nበገነት መካከል የተመላለሱት ደምተዋል እግሮቹ\nንጉስ ሆይ እያሉ ይዘብቱ ነበር የእሾህ አክሊል ደፍተው\nሁሉን የሚያየውን የአማኑኤልን ዓይኑን በጨርቅ አስረው\n\nበሚሸልቱት ፊት እንደማይናገር\nእንደ የዋሁ በግ ዝም አለ እግዚአብሔር\n\nለማህበረ አይሁድ አሳልፎ ሊሰጥ ጌታውን በብር\nህዝቡ በሌለበት ምቹ ጊዜ ይሁዳ ይፈልግ ነበር\nወርቅ ወይም ብር ነሐስ አትያዙ ብሎ እንዳላስተማረው\nጨካኙ ይሁዳ የዘላለም ምግቡን በገንዘብ ቀየረው\n\nሊቀ ካሕናቱ በካህናቱ\nፊት ቀረበ ለፍርድ\nንጹህ መስዋዕት ሆኖ መስዋዕት ተቀበለ ሞትን ሊያስወግድ\nፍቅር የአምላክን ልጅ ከዙፋኑ ስቦት እስከ ሞት ደረሰ\nወራሽ እንድንሆን ስጋውን ቆረሰ ደሙን አፈሰሰ\n\nሁሉን የሚመግብ ሁሉን የሚያረካ ለሁሉ የሚያዝነው\nበወንበዴ መሐል በመስቀል ላይ ሆኖ ተጠማሁ አላቸው\nሐሞት ለመብሉ ሆምጣጤ ለጥሙ አይሁድ አቀረቡ\nየተጨነቀች ነፍስ የተራቆተች ነፍስ ነበር ጥም ርሃቡ', 'am', 27, 0),\n(5, 'በእምባዬ የማመልክህ', 'በእምባዬ የማመልክህ\nበእንባዬ የማመልክህ ጌታዬ\nከክፋ ቀን መወጫ አንባዬ\nኀዘኔን በደስታ ለውጠው\nአንተን በመታመን ልለፈው\n\nበእናቴ ማህፀን እያለሁኝ ገና\nየተደገፍኩብህ አምላኬ ነህና\nአውጣኝ ከመከራ እያልኩኝ ቀን ሌሊት\nምንጣፌን ዘወትር በአንባዬ አራስኩት\n\nየምትታመነው ሁልጊዜ ምትጠራው\nእያሉ ሲወቅሱኝ አምላክህ ወዴት ነው\nለአፌ ምግብ ሆነኝ የማነባው እንባ\nእባክህ አምላኬ ወደ ረፍቴ ልግባ\n\nእስክትጎበኘኝ ከሰማዩ መቅደስ\nማዳንህን እስካይ እንባዬ እስኪታበስ\nሳታቋርጥ እንባን ታፈሳለች ዐይኔ\nእንደቀድሞ ይሁን ይታደስ ዘመኔ\n\nከአንደበቴ ጠፍቷል የጽዮን ዝማሬ\nበባቢሎን ምርኮ ሳለው አቀርቅሬ\nበዚያ የማረኩን ፈስን እንድንዘምር\nእንዴት ይቻለናል በባዕዳን ምድር', 'am', 28, 0),\n(5, 'ታላቅ መሆን የፈለገ', 'ታላቅ መሆን የፈለገ\nታላቅ መሆን የፈለገ እንደ ታናሽ ይሁን\nእራሱን ከፍ በማድረግ እንዳያጣ ክብሩን\n\nከፊት እኔ ልቅደም አትበል እኔ ብቻ\nዋጋን እንዳታጣ ሮጠህ በጥላቻ\nኢያሱን ተክቷል መሴ በአገልግሎት\nእውነተኛ መሪ እውነተኛ አባት\n\nከሰማይት ወርዶ የሐዋርያትን እግር ያጠበው\nለእኛ አርአያና ትምህርት ምሳሌ ሊሆን ነው\n\nአንድ ሲሆን ጌታ ጸጋው አይቆጠር\nክብሩን እንመስክር በሰላም በፍቅር\nዲያብሎስ ተዋርዶ ከጥልቅ የተጣለው\nከእኔ በላይ ሌላ የለም ስላለ ነው\n\nከሰማይት ወርዶ የሐዋርያትን እግር ያጠበው\nለእኛ አርአያና ትምህርት ምሳሌ ሊሆን ነው\n\nእግዚአብሔር ሲሰጠ ለወንድምህ ጸጋ\nልክ አይደለም አትበል እንዳታጣ ዋጋ\nማታ የመጣውም አገልጋይ ነውና\nከእኔ ተስተካክሏል በማለት አትቅና\n\nከሰማይት ወርዶ የሐዋርያትን እግር ያጠበው\nለእኛ አርአያና ትምህርት ምሳሌ ሊሆን ነው\n\nእንደ ሕጻናት ስንሆን የማንሻ ክብርን\nበደስታ ያወርሰናል ክርስቶስ መንግስቱን\nጠቢብና አስተዋይ ልባም የሚባለው\nወንድሙን የሚያስብ የሚያስበልጥ ሰው ነው\n\nከሰማይት ወርዶ የሐዋርያትን እግር ያጠበው\nለእኛ አርአያና ትምህርት ምሳሌ ሊሆን ነው', 'am', 29, 0),\n(5, 'ምናል ብታስተምረኝ', 'ምናል ብታስተምረኝ\nበክብር በሞገስ በመወደስ ፈንታ\nመቀመጥ እንድችል ከመዋረድ ተርታ\nስድብህን የሰማህ ያላንዳች ሁካታ\nለመቆም እንድችል ልቤ ሳይረታ\nምናል ብታስተምረኝ ምናል ብታስተምረኝ\nብታስችለኝ ጌታ ብታስችለኝ ጌታ\n\nለኔም አስተምረኝ ባላጠፉት ጥፋት\nበፀጋ መቀበል የአይሁድን ትፋት\nእንዴት እንደሚቻል ሳያጉረመርሙ\nንገረኝ ጌታዬ ይረዳኝ ትርጉሙ\nምናል ብታስተምረኝ ምናል ብታስተምረኝ\nብታስችለኝ ጌታ ብታስችለኝ ጌታ\n\nየመናቅን ጥበብ የውርደትን ዘዴ\nእባክህ አስረዳኝ አስተምረኝ አንዴ\nብኤል ዜቡል ተብለህ ያልተበሳጨኸው\nየሀጢያአተኞች ወዳጅ መባል ያልጠላኸው\nጋኔል ይዞታልን የሰማህ በጸጋ\nለኔም አስተምረኝ ለኔም አስተምረኝ\nበቂም አልወጋ በቂም አልወጋ\n\nአልወጋ እባክህ በመራርነት ጦር\nበቁጣ ጥላቻ ልቤ አትሰበር\nእንዴት ነበር ያኔ የይሁዳን እግር\nዝቅ ብለህ ያጠብከው ስታውቅ ሁሉን ነገር\nለኔም አስተምረኝ ለኔም አስተምረኝ\nብዙ ሳልናገር ብዙ ሳልናገር\n\nበችንካር ተጣብቀህ ከመስቀሉ ጋራ\nየደምህ ነጠብጣብ ገና ሳያባራ\nአያውቁትምና የሚያደርጉትን\nይቅርታን የለመንክ ላጠጡህ አሞትን\nምናል ብታስተምረኝ ምናል ብታስተምረኝ\nእንዲህ ያለ ህይወትን እንዲህ ያለ ህይወትን\n\nአሁን ምን ቸገረህ ብትሰጠኝ ለአንድ አፍታ\nየትህትናን ቀሚስ የትዕግስትን ኩታ\nእያየህ አይደል ወይ ነፍሴ እንዲ ተራቁታ\nየመሰደብን ዘውድ የመናቅን ካባ\nምናለ ብትኖር ምናለ ብትኖር\nይህች ልቤ ደርባ ይህች ልቤ ደርባ\n\nትዕቢት ለተሞላው ላትንኩኝ ባይ ልቤ\nለክብሩ ለሚኖር ለኮርማው ሀሣቤ\nምናል ብትቀባው የትህትናን ሽቶ\nእንደዚህ ከሚኖር ሸቶ ተበላሽቶ\nኧረ እኔስ አልቻልኩም አቅቶኛል በጣም\nስድብንም መቀበል ሀሜትን ማጣጣም\nስተርከው እንጂ ስኖረው አቃተኝ\nይህን መራር ኑሮ አንተው ይዘህ ጋተኝ\nይህን መራር ኑሮ አንተው ይዘህ ጋተኝ', 'am', 30, 0),\n(5, 'አትለይኝ', 'አትለይኝ\nአትለይኝ ማንም የለኝም\nከጎኔ ቁሚ ብቻዬን ነኝ\n\nአይቀርም መፈተመከራን መቅመሱ\nለዚህ ዓለም ጣጣ መተከዝ ማልቀሱ\nአምናለሁ እናቴ እንደማትለይኝ\nከአጠገቤ ሆነሽ እንደምት አፅናኚኝ\nከአጠገቤ ሆነሽ እንደምት አፅናኚኝ\n\nእሾህ አሜኬላ ቋያ ነው መንገዱ\nቁሚልኝ እናቴ የልጅሽ ነው ፍርዱ\nአንዴ ሲሞላልኝ ደግሞሞ ሲጎልብኝ\nወዳንቺ እሮጣለሁ እንድታባብይኝ\n\nሲኖረኝ የሳመኝ ሳጣ ነከሰኝነከሰኝ\nየልቤ ያልኩት ሰው ጀርባውን ሰጠኝ\nየቱ ነው ድጋፌ ማንስ ይታመናል\nየልቤን ልንገርሽ ሰውስ ከፍቶብኛል\n\nየጭንቄ መርሻ ነሽ የብቸኝነቴ\nእጽናናለሁ ሳይሽ ድንግል እመቤቴ\nቢበዛም በደሌ ቢከፋም ስራዬ\nበአማላጅነትሽ ሞልቷል ማድጋዬ\n\nነፃነቴ ነሽ ሰላም ፀጥታዬ\nየነፍሴ እረፍት ነሽ የሁለንተናዬ\nረስርሷል ውስጤ በፍቅርሽ ዝናም\nአትወጪም ከውስጤ እስከ ዘላለም', 'am', 31, 0),\n(5, 'ርግብ እና ዋኔን', 'ርግብ እና ዋኔን\nርግብ ዋኔን ዋኔን\nአብረው ዘመቱና ዋኔን\nርግብ ደህና ገባች ዋኔን\nዋኔን ገደሉና ዋኔን\n\nየሌሊቱ ዝናብ ዋኔን\nምንም አላለኝም ዋኔን\nቀን ጥሎኝ ነው እንጂ ዋኔን\nየደበደበኝ ዋኔን\nአዳልጦኝ ወደኩኝ ዋኔን\nትላንትና ቀትር ዋኔን\nእንዴት እደርሳለሁ ዋኔን\nመቼም መመሸቱ አይቀርም ዋኔን\nአየሁት በህልሜ\nአየሁት በህልሜ\nሞት የተባለውን\nስጋ ተሸክሜ\nስጋ ተሸክሜ\nሰማሁት በዝና\nሰማሁት በዝና\nቀጠሮ አክባሪ ነውና\nሞት አይቀርምና\nሞት አይቀርምና\n\nማለዳ ላይ ጤዛ ዋኔን\nበቀትር ሀሩሩ ዋኔን\nምን መኖር ያስመኛል ዋኔን\nእንዲ ሆኖ አገሩ\nእይችልም ብላችሁ ዋኔን\nስትንቁ ሙያዬን ዋኔን\nነገ በመቅደሱ ዋኔን\nታያላቹ ሳጥን ዋኔን\n\nበእጃችሁ ያለው ደም ዋኔን\nውጦታል ጥቀርሻ ዋኔን\nዘርን ስትዘሩ ዋኔን\nገብታቹ ከእርሻ ዋኔን\nማለፍ የግድ ነው ዋኔን\nበከንቱ አትለፋ ዋኔን\nሞት አይፈራም እና ዋኔን\nሰውነት ቢሰፋ ዋኔን\n\nችግሬን ንገሩኝ ዋኔን\nውዳሴን ትታችሁ ዋኔን\nነገ ለመዋረድ ዋኔን\nቃል እንዳያጥራችሁ ዋኔን\nየዳዊቱን ንባብ ዋኔን\nስንቱ ሰው ረሳ ዋኔን\nተነሺውን ጥሎ ዋኔን\nወዳቂ እያነሳ ዋኔን', 'am', 32, 0),\n(5, 'አኑሮኛል ቸርነትህ', 'አኑሮኛል ቸርነትህ\nአኑሮኛል ቸርነትህ\nልክ የሌለዉ ደግነትህ\nእንደአንተ ያለ ከየት ይገኛል\nሁሉም ነገር ትዝ ይለኛል\nሁሉም ነገር ትዝ ይለኛል\n\nያች ፈዋሽ አዳኝ እጅህ\nዛሬም ለኔ ተዘርግታ\nበኃጢአት እርቄ እዳልጓዝ\nአስረህኛል በዉለታ\nደሞስ ህይወት ምርጫ ቢሆን\nካንተ ወዴት ማን ይኬዳል\nአባቴ ፍቅር እኮ\nጌታዬ ፍቅር እኮ\nአለምን ያስክዳል\n\nአኑሮኛል ቸርነትህ\nልክ የሌለዉ ደግነትህ\nእንደአንተ ያለ ከየት ይገኛል\nሁሉም ነገር ትዝ ይለኛል\n\nሞቼ ነበር ተቀብሬ\nጌታ ወደኔ ባትመጣ\nአንተ ሞቴን ባትሞትልኝ\nወዴት ነበር የእኔ እጣ\nከንቱ ነበር ማንነቴ\nተሸናፊ ለዝች አለም\nግን አንተ የያዝከዉ\nአባቴ የያዝከዉ\nይኖራል ዘላለም\n\nአኑሮኛል ቸርነትህ\nልክ የሌለዉ ደግነትህ\nእንደአንተ ያለ ከየት ይገኛል\nሁሉም ነገር ትዝ ይለኛል\n\nመቅደስህን ተጠግቼ\nአይቻለሁ ብዙ ነገር\nበልቤ ዉስጥ ያስቀመጥሁት\nእዲህ ለሰዉ ማይነገር\nግን የሆነዉ ሁሉም ሆኗል\nየለም ዛሬ ያራረፈ\nየመከራዉ እሳት\nየፈተናዉ እሳት ባንተ የታለፈ\n\nአኑሮኛል ቸርነትህ\nልክ የሌለዉ ደግነትህ\nእንደአንተ ያለ ከየት ይገኛል\nሁሉም ነገር ትዝ ይለኛል\n\nአይጠፋኝም ያፈገግታ\nልጄ ብለህ ያሳየኽኝ\nአመፀኛ መጥፎ ሆኜ\nበትከሻህ ላይ ያኖርከኝ\nእዲህም አይነት ወዳጅ አለ\nእየጠሉት የማፈቅር\nስሙም እየሱስ ነዉ\nስሙም እየሱስ ነው\nየፅርቃችን ሚስጥር\n\nአኑሮኛል ቸርነትህ\nልክ የሌለዉ ደግነትህ\nእንደአንተ ያለ ከየት ይገኛል\nሁሉም ነገር ትዝ ይለኛል\n\nስነፈርቅ ሳለቅስብህ እሽ እያልከኝ\nሁሉም ሆነ የማይሆንለት ነገር የለም\nለካስ ባንተ የታመነ መቸኮሌ መጣደፌ\nአምላኬሆይ በከንቱ ነዉ\nመፈጸሙ ላይቀር\nመፈጸሙ ላይቀር\nጌታ አንተ ያልከዉ', 'am', 33, 0),\n(5, 'ሰላሜ ነህ ፀጥታዬ', 'ሰላሜ ነህ ፀጥታዬ\nሰላሜ ነህ ፀጥታዬ\nወደቤ ነህ ማረፊያዬ\nሁን ከእኔ ጋራ አሁን ከጎኔ\nፍቅር እኮ ነህ መድህኔ\nፍቅር እኮ ነህ መድህኔ\n\nየአይሁድ ፉከራ\nየጠላት መከራ\nሁሉን ባንት አልፌአለው\nእንደምችል አምንሃለው\nደጆችህ ሁሉ ተዘግተው\nበፍርሃት ውስጥ ተቀምጠው\nተገኘ ኢየሱስ የአለሙ ንጉስ\nተገኘ ኢየሱስ የአለሙ ንጉስ\n\nአንተን ትቼ ሰላም\nእውነት እውነት አይመስል\nየሰላም ሰጪ አንተ ነህ\nየሞት መውጊያን የሰበርክ\nደጆችህ ሁሉ ተዘግተው\nበፍርሃት ውስጥ ተቀምጠው\nተገኘ ኢየሱስ የአለሙ ንጉስ\nተገኘ ኢየሱስ የአለሙ ንጉስ\n\nሸክም ከብዶኝ ሳነባ\nልቤ ወደ ዓለም ተሰባ\nቀንበር ከላዬ አውርደህ\nቀና አደረከኝ በፊትህ\nደጆችህ ሁሉ ተዘግተው\nበፍርሃት ውስጥ ተቀምጠው\nተገኘ ኢየሱስ የአለሙ ንጉስ\nተገኘ ኢየሱስ የአለሙ ንጉስ\n\nከእኔ ጋር ነህ አምንሃለው\nአልታመንኩም አውቃለው\nየፍቅር አባት የምሕረት\nየምትታደግ ከጠላት\nደጆችህ ሁሉ ተዘግተው\nበፍርሃት ውስጥ ተቀምጠው\nተገኘ ኢየሱስ የአለሙ ንጉስ\nተገኘ ኢየሱስ የአለሙ ንጉስ', 'am', 34, 0),\n(5, 'አማኑኤል ስለኛ ዋጋ ከፍለሃል', 'አማኑኤል ስለኛ ዋጋ ከፍለሃል\nአማኑኤል ስለኛ ዋጋ ከፍለሃል\nአማኑኤል ስለኛ ዋጋ ከፍለሃል\nበአንተ ቁስል እኛ ተፈውሰናል\nበአንተ ቁስል እኛ ተፈውሰናል\n\nማዳንህ መጣልኝ ጽድቅህ ተገለጠ\nየእሳቱ ነበልባል ውብ ቃልህ ቆረጠ\nለዘመንህ አልፋ ኦሜጋ የሌለህ\nታምነህ ምትፈውስ\nጌታዬ አዳኝ ነህ\n\nያንተስ ይለያል ያንተስ\n\nየእኛ ቁስል ህመም\nየአንተ ቁስል ፈዋሽ\nከአንተ ወደየትም አንሄድም በጭራሽ\nየእፎይታ ዘመን ባወጅልክን ባንተ\nወደ ሐይወት መንገድ\nበሩ ተከፈተ\n\nእንደሌዋዊያን በመቅደም አይደለም\nበገዛ ደሙ ነው ያዳነው ይህን ዓለም\nየራቀ ተስፋችን በእጃችን የገባ\nበኢየሱስ ታበሰ የሰቆቃው እንባ\n\nግፍ ያላደረግ ግፍ ተደረገበት\nበተንኮል ተያዘ ተንኮል የሌለበት\nይህ ውሉ ለእኛ ነው\nስቃይ መጨነቁ\nነጭ ልብስ ሆነልን ለይቶን ከማቁ', 'am', 35, 0),\n(5, 'የግብፅን ከተሞች ትተን ወተን', 'የግብፅን ከተሞች ትተን ወተን\nየግብፅን ከተሞች ትተን ወተን\nበበረሀው ስንሄድ ምድርን ሞልተን\nጫማና ልብሳችን አላለቀም\nእርሱ እየቀደመ መድሐኒኒአለም\nታላቁን ቀይ ባህር ስንሻገር\nአስጨንቆን ነበር ብዙ ነገር\nግን ሁሉም ቀለለ ከፊታችን\nእርሱ እየቀደመ አምላካችን\n\nከአለት ላይ ውሀ ጠጥተናል\nየነሃሱም መባ ፈውሶናል\nየምድር ሰልፈኞች ቢነሱብን\nለሞት አሳልፎ መቼ ሰጠን\n\nእስራኤል በክብር ፊቱን ሞልቷል\nሰባቱም ደመና ጋርደውታል\nነፃ ስለወጣን ክሱ ታጥፎ\nማንስ ይነካዋል ክንድን አልፎ\n\nአለም ብትገፋን ብትጨክን\nአንተ ግን እንደሰው መቼ ጣልከን\nከኛጋር ተዋግተሕ ድል ለብሰናል\nየበፍታኤፎዶም አምሮብናል', 'am', 36, 0),\n(5, 'ፃኡ ንኡሰ ክርስትያን', 'ፃኡ ንኡሰ ክርስትያን\nፃኡ ንኡሰ ክርስትያን\nፃኡ ንኡሰ ክርስትያን\n\nዝለዋል ክንዶቼ ሀጢአት አብዝቻለሁ\nየጌታዬን ፊቱን እንዴት አየዋለሁ\nፃኡ እየተባለ ሲታወጅ አዋጁ\nእንደምን ቆማለሁ ደፍሬ ከደጁ\nበቂም በግፍ መንፈስ ተይዟል\nእንዴት ፍፁም ሆኖ ልቤ በአንተ ይገዛል\nየጎሰቆለ ነ በሀጢሀት ሰውነቴ\nበምህረትህ ጎብኘኝ አማኑኤል አባቴ\nአልኖርኩም በቃልህ ግብ ፈትህ ቆማለሁ\nእጅግ ይደንቀኛል ድፍረቴን ሳስበው\nይቅርታሕ በዝቶልኝ ከቤትህ ብገባ\nመታጠብ አቃተኝ በንስሀ እንባ\n\nማረኝ በምህረትህ ጎብኘኝ በይቅርታ\nከመንጋህ አትለየኝ አምላኬ የኔ ጌታ\nየመቅደስህን ደውል እያስደነገጠኝ\nእድሜን ልንስህ ለህይወት ሰጠኝ', 'am', 37, 0),\n(5, 'የኔ ጌታ', 'የኔ ጌታ\nየኔ ጌታ\nሰምቼህ አድምጬህ\nልቀመጥ በእርጋታ\nመንፈሴን አበርታ\nመንፈሴን አበርታ\n\nፈጥኖ ይስማማና ሐሳብህ ከሀሳቤ\nስጋት መከራዬ ይነቀል ከልቤ\nጭንቀትን ይነቅላል እርጋታን ይተክላል\nቃልህ ስልጣን አለው ያፈርሳል ይሰራል\n\nአይወድቅም አንተን የሰማ\nድምጽህን ልጂህ ልጠማ\nበቅዱስ መንፈስህ ይዋሃደኝ ቃልህ\nየኔ ጌታ\n\nችግሬ ታላቅ ነው አይበል ከንፈሬ\nታላቅነትህን ልንገር ለችግሬ\nጠላቴ ፊት ስቆም ፊትህ ተንበርክኬ\nየድል ነው ዘመኔ የድል ነው ታሪኬ\n\nአይወድቅም አንተን የሰማ\nድምጽህን ልጂህ ልጠማ\nበቅዱስ መንፈስህ ይዋሃደኝ ቃልህ\nየኔ ጌታ\n\nዝናብ ታመጣለህ ባይኖርም ደመና\nበረከትን ልጥገብ እሽ ልበልና\nያደረክላትን ልንገራት ለነፍሴ\nልጠማ ጧት ማታ ልሰማ በመንፈሴ\n\nአይወድቅም አንተን የሰማ\nድምጽህን ልጂህ ልጠማ\nበቅዱስ መንፈስህ ይዋሃደኝ ቃልህ\nየኔ ጌታ\n\nበፊትህ ምንድነው የሴረኞች ስራ\nቃልህ ጉልበት አለው ይኖዳል ተራራ\nበእርሱ መዶሻነት በደሌ ሲመታ\nጫጫታው ያልፍና ይሰፍናል ፀጥታ\n\nአይወድቅም አንተን የሰማ\nድምጽህን ልጂህ ልጠማ\nበቅዱስ መንፈስህ ይዋሃደኝ ቃልህ\nየኔ ጌታ\n\nአያፍረኝ አይፈራኝ ቃልህ መስታወቴ\nሁሌ ይነግረኛል ስለማንነቴ\nወዴት እንደወደኩ ወዴትስ እንዳለሁ\nሽንገላን በማያውቅ በቃልህ አውቃለሁ', 'am', 38, 0),\n(5, 'ይደንቀኛል ዘላለም', 'ይደንቀኛል ዘላለም\nይደንቀኛል ዘላለም\nይደንቀኛል ዘላለም የሰለጠነ ስም ሰምቼ\nእኔ ወጣው ከእስራት ይህን ስም ጠርቼ\nኢየሱስ\n\nእስኪ ሞት ይደንግጥ ይህንን ስም ልጥራ\nገዳዬን ላድነው ልውጣ ልሰማራ\nተው አታቅሉልብኝ አትግፏት እውነቴን\nኢየሱስ\n\nማልጄ ልገስግስ ሰልፍ አለብኝ ዛሬ\nወንጨፌ እና ቀስቴ አንተ ነህ ጠጠሬ\nከሞት የዳንኩብህ ማምለጫ አለቴ\nሀይል አስታጣቂዬ ቅደምልኝ ፊቴ\n\nመውጊያው ተናወጠ ወለል አለ ደጁ\nነጻነት ነው ስሙ ጽድቅ ነው አዎጁ\nመታመን በዚህ ስም መደገፍ በጌታ\nእፎይታ ነው ትርፉ የማታ የማታ\n\nየጌታን ስም ጥሩ የጠሩ ድነዎል\nየቀደሙት ሁሉ በዚህ ስም ታምነዎል\nሰማይ እና ምድር ጸኑ ለዘላለም\nኢየሱስ ነው ሁሌም ቤዛዎ ለአለም', 'am', 39, 0),\n(5, 'ትላንትና ካንተ ጋር ዛሬ ደግሞ ከሌላ', 'ትላንትና ካንተ ጋር ዛሬ ደግሞ ከሌላ\nትላንትና ካንተ ጋር ዛሬ ደግሞ ከሌላ\nሰልችቶኛል አባቴ ሆይ ሁሌ መሄድ ወደሁዋላ\nሁሌ መጓዝ ወደሁዋላ\nሁሌ መጓዝ ወደሁዋላ\n\nሰዶምን አልተውኩም ወደሁዋላ አየዋት ደግሜ\nምንኛ ከንቱ ነኝ ሳልለወጥ ባለሁበት ቁሜ\nይነዳል ከተማው ይቃጠላል በቁጣው እሳት\nእጄን ይዘህ አውጣኝ ዞአል ሳልደርስ ጌታዬ እንዳልሞት\nጨው አልጫ ቢሆን በምን ይጣፍጣል\nአጣፍጠኝ በቃልህ ከደጅህ እንዳልወጣ\n\nዴማስን ሆኛለሁ ተሰሎንቄ አስራ ያስቀረችኝ\nስሸሽህ አግኝታ ከባህሩ ከጥልቁ የጣለችኝ\nወፎች ለቅመውታል ቅዱስ ቃልህ በውስጤ የታለ\nአዘገየኝ እንጂ ያጠላቴ እየሸነገለ\nመልሰኝ ልመለስ በሎቅሶ በዕንባ\nአሳንባሪው ይትፋኝ ወደ ቤትህ ልግባ\n\nአለቀ ገንዘቤ የሰጠኸኝ አፍሰህ በችሮታህ\nእራሴን አገኘሁት አመሻሽላይ በተናቀ ቦታ\nጨልሟል ዞሪያዬ ምይዘውን ነገር አጥቻለሁ\nየድሮዋ አደለሁም የኔ ጌታ ዛሬ ደክሜአለሁ\nመንገድ ለጠፋው ሰው ክንድህ ወዴት አለ\nምንድነው ምሬትህ እራሱን ለጣለ\n\nማለዳ ስነቃ ዘምሬልህ ሲመሽግን ሌላ ነኝ\nቃልህ ያልለወጠኝ ያልቀየረኝ ጌታዬ እኔ ማነኝ\nአይወስንም ልቤ ያመነታል ይሸሻል አጥብቆ\nዘላለም ላይደላኝ እስከመቼ ካንተ ተደብቆ\nእንድወስን እርዳኝ ይበርታ ጉልበቴ\nጠላት ጭኑን ይስፋ እቀፈኝ አባቴ', 'am', 40, 0),\n(5, 'በዘላለም ኪዳን', 'በዘላለም ኪዳን\nበዘላለም ኪዳን በደም ሰንሰለት\nበዘላለም ኪዳን በደም ሰንሰለት ይዘኸን\nታስከትለናለህ በልዩ ፍቅር እስከ ሞት ድረስ ወደኸን\n\nየጨለመዉ ለሊት የከበበን መከራ\nያስጨነቀን ጠላት ከእንግዲህ ላያወራ\nየያዘን ላይዘን የደም ነዉ ኪዳናችን\nሁሉን የፈጸምከዉ ተባረክ አምላካችን\n\nእዉነትና መንገድ ሕይወት ነህ የማትጠፋ\nለፍቅርህ መኖሪያ ልባችንን ያሰፋ\nደጃችንን ዘግተን አሜን ነዉ በእንባ ሙላት\nየፍቅርህ ምርኮኞች አድርጎን ያንተ ምህረት\nበማግኘት በማጣት በደስታ በሃዘናችን\nየለንም ሌላ ቃል አንተዉ ነህ አዋጃችን\nአድኖናል ፀጋህ ጽድቃችን ሰማይ ነካ\nኢየሱስ ዉሃ ነዉ ትዉልዱን የሚያረካ\n\nአንተ የሕይወት እራስ የሕይወት ፍጻሜያችን\nየለመለምከዉ መስክ መሰማሪያዉ ቅጥራችን\nቤዛነትህ ሆኖ ኩነኔዉ የለም ዛሬ\nድነናል በፀጋህ አሜን በዝማሬ', 'am', 41, 0),\n(5, 'ማስተዋል ስጥልን', 'ማስተዋል ስጥልን\nማስተዋል ስጥልን አይምሮን ስጥልን\nአከበርንህ ብለው ለጣሉት ክብርህን\n\nአለቱን ፈልፍላ መቅደስ ለተከለች\nሥጋው እና ደሙን ለሕይወት የሰጠች\nበ አምስቱ አዕማድ የጸናችው ቆማ\nየነፍስ እረፍት ነች ያለች አስቀድማ\n\nያላቸው ከሚመስል የአምልኮ መልክ\nሃይልህን ለካዱት ሀሰት በመስበክ\nየሰራሃት ቅፅርህ በፅኑ መሠረት\nከመንጋው ተለዩ በኑፋቄ ትምህርት\n\nማርያም ማርያም ብትል በሠርክ በማለዳ\nሰለሰጠችን ነው መድሃኒትን ወልዳ\nነገረ ቅዱሳን ቢሰበክ በአዋጅ\nመች ጋረዱን እና ገለጡልን እንጂ\n\nከሦስት ሺህ ዘመን ቀድማ ለታነጸች\nአምላክ ወልደ አምላክ መሆኑን ላመነች\nአይሆንም ኢየሱስ እንግዳ ዜናዋ\nእርሱ ነው ያስገኛት እርሱ ነው ሰሪዋ\n\nየሥጋን ነው እንጂ የነፍስን ሳያዩ\nየጸጋው ግምጃ ቤት እርቀው ተለዩ\nሃይማኖት እያለኝ ምግባር ለጎደለኝ\nለእኔም ማስተዋሉን አይምሮን ስጠኝ', 'am', 42, 0),\n(5, 'ለምጠራኝ ላንተ', 'ለምጠራኝ ላንተ\nለምጠራኝ ላንተ እንቢ እንዳልል እኔ\nማስተዋል አድለኝ በሂወት ዘመኔ\nመክረህ አስተምረህ ፍቅር የገለፅክልኝ\nየሰማውትን ቃል ለሂወት አርግልኝ\n\nለምጠራኝ ላንተ ሀጥያቴን በሙሉ\nባንተፊት ጥያለው\nለምጠራኝ ላንተ በደሌን ክፍቴን\nእኔ እናዘዛለው\nለምጠራኝ ላንተ የማዘነጋኝ ነህ\nበዘመኔ ሁሉ\nለምጠራኝ ላንተ ማረኝ ይቅር በለኝ\nይብቃኝ መበደሉ\n\nለምጠራኝ ላንተ ካፍህ የወጣው\nቃል ያረሰርሰኛል\nለምጠራኝ ላንተ ህግህን አድምጬ\nየሂወት ሆኖልኛል\nለምጠራኝ ላንተ እንዳአንበሳ አድብቷል\nያክፉ ጠላቴ\nለምጠራኝ ላንተ ከልቤ እንዳይነቅለው\nጠብቀኝ አባቴ\n\nለምጠራኝ ላንተ ወጀብ ቢያልብኝ\nቢከብደኝ ፈተና\nለምጠራኝ ላንተ አምላኬ ያንተ ምክር\nትፀናለች እና\nለምጠራኝ ላንተ ጌታውን የጠበቀ\nይከብራል ብለሀል\nለምጠራኝ ላንተ ነቅ የሌለው እምነት\nበልቤ ተክለሀል\n\nለምጠራኝ ላንተ ድምፅህን ሰምቼ\nልቤ እንዳይከብድብኝ\nለምጠራኝ ላንተ ያስተማርከኝ ሁሉ\nፍርድ እንዳይሆንብኝ\nለምጠራኝ ላንተ በሰጠኸኝ ፀጋ\nእጠነቀቃለው\nለምጠራኝ ላንተ ከቶ እንዳት ወስድብኝ\nበንባ ደምድሚያለው', 'am', 43, 0),\n(5, 'ለንግስናው ዙፋን', 'ለንግስናው ዙፋን\nለንግስናው ዙፋን መስቀል የመረጠው\nበትረ መንግስት እና የወርቅ ካባ የለው\nእርቃኑን ተሰቅሎ ተጠማው እያለ\nየናዝሪቱ ኢየሱስ እዳዬን ከፈለ\nየናዝሪቱ ኢየሱስ እዳዬን ከፈለ\n\nየእሾህ አክሊሉን ዘውድ አድርጎ በራሱ\nእጆቹን ዘርግቶ ሲጣራ ንጉሡ\nማንስ አስተዋለው ከትውልዱ መሃል\nአምላክ እንደሆነ የዋለው በመስቀል\n\nምድርን በአበባ የሚያስጌጥ በውበት\nበረከት የሚያድል ለፈጠረው ፍጥረት\nሐሞት እና ከርቤ ቢያቀርቡ ለጥሙ\nመራራው ጣፈጠ ተፈወሰ አለሙ\n\nበሸላቾች ፊት ዝም እንደሚል ጠቦት\nአፉን አልከፈተም አልዛተም ስገርፉት\nከዓመፀኞች ጋር እየተቆጠረ\nከቅዱሳኑ ጋር የኛን ስም ደመረ\n\nስቃትት ሲጨነቅ ተራቁቶ ብናየው\nደካማ እንዳይመስለን የጌቶች ጌታ ነው\nዛሬም በምስጋ ብርሃንን ለብሶ\nበፍርድ ወንድበር አለ በሰማያት ነግሶ', 'am', 44, 0),\n(5, 'ሰዎች ፈረዱብኝ', 'ሰዎች ፈረዱብኝ\nሰዎች ፈረዱብኝ\nአንተ ግን አዳንከኝ\nሰዎች ፈረዱብኝ\nአንተ ግን አዳንከኝ\nአምላኬ ሆይ ተመስገንልኝ\nጌታዬ ሆይ ተመስገንልኝ\nሌላ ምን ቃል አለኝ\n\nሊያልፉኝ አልወደዱም ነውሬን ሊሰውሩ\nሰዎች ፈጠኑብኝ በደሌን ሊያወሩ\nአንተ ግን ሰብስበህ በፍቅር ሸፈንከኝ\nበመተላለፌ አዝነህ ሳትለየኝ\nይህ ፍቅርህ ሰበረኝ አጣበቀኝ ካንተ\nደጅህ ያመጣኛል ሁሌ እየጎተተ\nይህ ፍቅርህ ሰበረኝ አጣበቀኝ ካንተ\nደጅህ ያመጣኛል ሁሌ እየጎተተ\n\nመርከሴን አውጀው ሲያነሱብኝ ድንጋይ\nሰወረኝ ተዓምርህ ልጅ ሳልሰቃይ\nወደህ ስለማርከኝ ብዙዎች ተከዙ\nይህ አይደለም ብለው የኃጢአት ደሞዙ\nካነተ በላይ ጌታ ማን ሊያውቀኝ ይችላል\nየፍቅርህን ሚዛን ማንስ ያዛባዋል\nካነተ በላይ ጌታ ማን ሊያውቀኝ ይችላል\nየፍቅርህን ሚዛን ማንስ ያዛባዋል\n\nማዳንህ ይደንቃል ለወደኩት ልጅህ\nምህረትህ ይደፋል ሁሌ በሚዛንህ\nእንደሰው አይታይ ፍርድህም ይለያል\nለባርያህ አርነት በምህረት ፈርደሃል\nፍቅር እየዘረዘርክ መንገዴን የጠረክ\nስለልጅህ ጽድቅን በምህረት የፈረድክ\nፍቅር እየዘረዘርክ መንገዴን የጠረክ\nስለልጅህ ጽድቅን በምህረት የፈረድክ\n\nእኔ አልፈርድብህም በሰላም ሂድ አልከኝ\nዳግም እንዳልበድል በፍቅር እያየኸኝ\nወደፍቅርህ ህጎች ነፍሴን አፈዛለሁ\nእንዲህ ከወደድከኝ ወዴት እሄዳለሁ\nአልለይም ካንተ ከፍቅር መድረኬ\nአመልካለሁ አንተን ፊትህ ተንበርክኬ\nአልለይም ካንተ ከፍቅር መድረኬ\nአመልካለሁ አንተን ፊትህ ተንበርክኬ', 'am', 45, 0),\n(5, 'አትቁረጡ ተስፋ', 'አትቁረጡ ተስፋ\nአትቁረጡ ተስፋ የእግዚአብሔር ልጆቹ\nአትቁረጡ ተስፋ የእግዚአብሔር ልጆቹ\nከናንተ አይለዩም የፍቅር አይኖቹ\nከናንተ አይለዩም የፍቅር አይኖቹ\nምድርና መላዋ ናት እና የእግዚአብሔር\nበሰማያት አለ በቀላይ በባህር\n\nበጥልቁ እንኳን ቢሆን ከናንተ ጋራ ነው\nወገኖቼ አትስጉ ሰልፉ የእግዚአብሔር ነው\nጌታ አይረሳም እና የእጆቹን ስራ\nይኸው በልጆቹ አይተናል ሲስራ\n\nእንደ ጠላት ቢሆን እንደሱ ጉልበት\nማነበር የሚኖር ዛሬ በሂወት\nየሚያኖር ጌታ ነው የሚገልም ጌታ\nብርቱ እሱ ብቻ ነው በሀይል የበረታ\n\nበምስጋና ትጉ ፅኑ በፀሎት\nበስሙ ታመኑ ቁሙ በእምነት\nለናንተ የምትሆን እግዚአብሔር ቀን አለው\nአትቁረጡ ተስፋ ሁሉም አላፊ ነው\n\nብትሆኑም ከ ጉርጓድ እሱ የያቹዃል\nበማዳኑ ጥላ ይጎበኛቹዃል\nገና ያበዛቹዃል ከዚህም በላይ\nሁሉ ይቻለዋል ነውና አዶናይ', 'am', 46, 0),\n(5, 'ሰው ሰውን ተራበ', 'ሰው ሰውን ተራበ\nሰው ሰውን ተራበ የልቡን ለመንገር\nዛሬ ተናፈቀ የተተወው ፍቅር\nክፋቱን ከተወው ወንድም ወንድሙ ላይ\nየእግዚአብሄር ይቅርታ ይመጣል ከሰማይ\n\nይቅር እንድላቹ ይቅር ተባባሉ\nብሎናል ጌታችን በማያልቀው ቃሉ\nይቅርታ ጠያቂ ይቅርታ ተቀባይ\nእንድሆን አድርገኝ ጥፋትን እንዳላይ\n\nወንድሜ በድሎኝ እያለው በእንባ\nተውለት ቢለኝም ሰባት ግዜ ሰባ\nእልከኛ ሆንኩኝ ይቅርታን ፈርቼ\nበአምላኬ ምህረት መኖሬን ዘንግቼ\n\nበእጄ ስንዴ ይዤ እንክርዳድ በልቤ\nጌታዬን ለማምለክ ከደጁ ቀርቤ\nበእጄ ካለው ይልቅ ልቦናዬን አይቶ\nተመለስ ታርቀህ ና አለኝ ቃል አውጥቶ\n\nከመባዬ በላይ እኔን ይፈልጋል\nየቃየል መስዋእት ለእርሱ ምን ያደርጋል\nክርክሬን ልተው ከወንድሜ ጋራ\nመንፈስህ ያሲዘኝ ጨለማዬ ይብራ\n\nወዶ ይቅር ካለ የኔን በደል ጌታ\nእኔ ማነኝ እና የማልል ይቅርታ', 'am', 47, 0),\n(5, 'ለጥያቄዬ መልስ ስላጣሁ', 'ለጥያቄዬ መልስ ስላጣሁ\nለጥያቄዬ መልስ ስላጣሁ\nመጣሁ ከደጅሽ ሱባዔ ገባሁ\nማን አፍሮ ያውቃል ባንቺ ለምኖ\nበኪዳንኪ ተማህጽኖ\n\nየነፍሴ እረፍቷ ታዛ መጠጊያ\nካንቺ ተገኝቷል የሞቴ መውጊያ\nበሰላምታሽ ድምጽ ተባርኳል ቤቴ\nየጌታዬ እናት ለኔም እናቴ\n\nማርያም ኩኒ ለሕይወትየ ጸወኖ\nእስመ ተማኅፀንኩ አንሰ ተማኅፅኖ\nለሥዕልኪ ስዕለ አድኅኖ እሰግድ ለኪ\n(ማርያም የሕይወቴ መጠጊያ ሁኚኝ\nመማጸንን ተማጽኜሻለሁ ለሚያድን ስዕልሽ እሰግድልሻለሁ)\n\nቀንን ስናፍቅ በለሊት ሆኜ\nአላተረፍኩም በሰው ታምኜ\nቁልፉ ልጅሽ ነው ለቋጠሮዬ\nአሳስበሽልኝ አልፏል ስቃዬ\n\nኪዳነ ምሕረት ኩኒ ለልቡናየ ብርሃኖ\nእስመ ተማኅፀንኩ አንሰ ተማኅጽኖ\nለስእልኪ ስዕለ አድኅኖ እሰግድ ለኪ\n(ኪዳነ ምህረት ሁኚ ለልቤ ብርሃን\nመማጸንን ተማጽኜሻለሁ ለሚያድን ስእልሽ እሰግድልሻለሁ)\n\nጉልበቴ ዝሎ ቀልዬ ሳለሁ\nበኪዳን ጥላሽ ተስፋ አግኝቻለሁ\nደጅሽ መጥቼ ኃይሌ ታደሰ\nያሳዳጆቼ ምክር ፈረሰ\n\nወላዲተ አምላክ ኩኒ ለእርቃንየ ክዳኖ\nእስመ ተማህጸንኩ አንሰ ተማህጽኖ\nለሥዕልኪ ስዕለ አድህኖ እሰግድ ለኪ\n(ወላዲተ አምላክ ለመራቆቴ ልብስ ሁኚኝ\nመማጸንን ተማጽኜሻለሁ ለሚያድን ስዕልሽ እሰግድልሻለሁ)\n\nየዝናቡ ምንጭ ፈጣን ደመና\nከሴቶች ሁሉ ክብርሽ ገናና\nአንድያ ልጅሽ ወይን አድርጎኛል\nከትናንት ይልቅ ዛሬ ባርኮኛል', 'am', 48, 0),\n(5, 'እንደበደሌ አልከፈልከኝም', 'እንደበደሌ አልከፈልከኝም\nእንደበደሌ አልከፈልከኝ\nፍቅር ነህና እያለፍከኝ\nምን እከፍላለሁ ላንተ የሚሆን\nታውቀው የለም ወይ ችሎታዬን\n\nሰማይ ከምድር ከፍ እንደሚል\nታረገዋለህ የኔን በደል\nእንደምትወደኝ አዉቃለሁ እኔ\nባስመርርህም እድሜ ዘመኔ\n\nከሰው ሁሉ ጋር ብትፈራረድ\nየትኛዉ ይሆን ፀድቆ የሚሔድ\nያለምን ሃጢያት ደምህ ሸፈነው\nየተፈወስኩት እኔም በእርሱ ነው\n\nዘመኔ እንደ ሳር መሆኑን አስብ\nእድሜዬ ታጥሯል በጊዜ ገደብ\nመልካም ሰርቼ እንዲያልፍ ወራቴ\nበጎውን አብዛ በሰውነቴ\n\nየልጅነቴን አታስብብኝ\nመጨረሻዬን አሳምርልኝ\nበሩን አትዝጋው ያዳራሹን\nዘይቴን ልሙላ የመቅረዙን', 'am', 49, 0),\n(5, 'አትንኩን', 'አትንኩን\nአትንኩን ስትነኩን ቁጥራችን ይበዛል\nአትንኩን ስትነኩን ቁጥራችን ይበዛል\nየቅዱስ ጊዮርጊስ የጳውሎስ ልጆች ነን\nየቅዱስ ጊዮርጊስ የጳውሎስ ልጆች ነን\n\nጥቂቶች ሆነን ተነስተን ነው\nእንዲሁ ምድርን የመላነው\nልጣል ከውሃ ከእሳት\nጽኑ ነው የያዝነው እምነት\n\nአትንኩን ስትነኩን ቁጥራችን ይበዛል\nአትንኩን ስትነኩን ቁጥራችን ይበዛል\nየተክለሃይማኖት የጴጥሮስ ልጆች ነን\nየተክለሃይማኖት የጴጥሮስ ልጆች ነን\n\nድሆች ስንባል ባለጸጋ\nሁሉን የያዘ ነው ከእኛ ጋ\nብርቱውን ጎልያድ የጣለ\nበወንጭፋችን ጠጠር አለ\n\nአትንኩን ስትነኩን ቁጥራችን ይበዛል\nየክርስቶስ ሰምራ የአርሴማ ልጆች ነን\n\nበሕይወት በቃል አስተማረን\nአምላካችን ነው የነገረን\nየዚህ ዓለም ጨው ተብለናል\nአልጫውንም አጣፍጠናል\n\nአትንኩን ስትነኩን ቁጥራችን ይበዛል\nየቅዱስ መርቆሬዎስ የማርቆስ ልጆች ነን\n\nእንደ ደመና የከበቡን\nየእግዚአብሔርን ቃል የነገሩን\nስላሉን ብዙ ምስክሮች\nደካሞች ሲሉን ነን ኃይለኞች\n\nአትንኩን ስትነኩን ቁጥራችን ይበዛል\nየቅዱስ ጊዮርጊስ የጳውሎስ ልጆች ነን\nየተክለሃይማኖት የጴጥሮስ ልጆች ነን\n\nቤተክርቲያን እማማ\nዝናሽ በዓለም ይሰማ\n\nእስካረጅም እስክሸመግልም ድረስ\nለሚመጣ ትውልድም ሁሉ ክንድህን\nኃይልህንም ጽድቅህንም እስክነግር\nድረስ አቤቱ አትተወኝ', 'am', 50, 0),\n(5, 'መከራው ክርስትናዬን አጣፈጠው', 'መከራው ክርስትናዬን አጣፈጠው\nመከራው ክርስትናዬን አጣፈጠው\nስደቱ ማህተቤን አጠበቀው\nበሞት መንደር በሀዘን ውስጥ በመከራ\nአየውት እግዚአብሔርን ከኔ ጋራ\n\nክርስትያን ተብለን በክርስቶስ ስም የተጠራነው\nበጥልቁ ውስጥም በእግዚአብሔር እንድናምን ነው\nለጥቂት ግዜ ቢበረታብን ስደት ሀዘኑ\nአምላክ ግን መውጫ ያዘጋጃል በዚህ ተፅናኑ\n\nበስደት ሳለን ካፋችን ቢደርቅ የፅዮን ዜማ\nከወንዙ አጠገብ ቁጭ ብለን ሰለን ድምፁን ሳንሰማ\nበእግዚአብሔር ጊዜ ከባቢሎን ምድር እንለቃለን\nመሰንቆአችንን ከአርያም ዛፍ ላይ እናወርዳለን\n\nደካሞች ሲሉን በስሙ ያን ጊዜ እንበረታለን\nድሆች ስንባል ባለጠጎች እናደርጋለን\nበምድር ቅዱስ ህዝብ አድርጎ ለእርሱ ለየን\nጨለማው አልፎ በቸርነቱ ብርሀን አሳየን\n\nከፀጋ በላይ እንዳንፈተን ይከልለናል\nበቁስላችን ላይ የፈውስን ዘይት ያፈስልናል\nበጊዜም ቢሆን ያለ ጊዜውም በእርሱ እንፅና\nእንኳን ስደቱን ሞቱን ሊገታው ይችላልና', 'am', 51, 0),\n(5, 'በዙሪያችን ካሉ', 'በዙሪያችን ካሉ\nበዙሪያችን ካሉ ድንቅ ምስክሮች\nበእምነት በምግባር ከፀኑት እናቶች\nከፍ ብላ ታየች በገድሏ ብዛት\nንዕድ ክብርት ነች አርሴማ ቅድስት\nንዕድ ክብርት ነች አርሴማ ሰማዕት\n\nሀብት እና ንብረቷን ውበቷን የናቀች\nንግሥት መባልን በእምነት የተወች\nየኢየሱስ ክርስቶስ የስሙ ምስክር\nየቅድስት አርሴማ እፁብ ነው የእርሷ ክብር\nየቅድስት አርሴማ እፁብ ነው የእርሷ ክብር\n\nእግዚአብሔር ፅናቷን የመሰከረላት\nበቤቱ በቅፅሩ መታሰቢያ አላት\nየወንጌሉን ብርሃን ለዓለም ያበራች\nሰማዕቷ አርሴማ ለእኛም አማላጅ ነች\nሰማዕቷ አርሴማ ለእኛም አማላጅ ነች\n\nይሄው በዚህ ዘመን እግዚአብሔር ገለፃት\nለረድኤት በረከት ምክንያት አደረጋት\nአክሊል ተጎናፅፋ ታይታለች በክብር\nዛሬም ለልጆቿ በረከቷ ይደር\nዛሬም በልጆቿ በረከቷ ይደር\n\nእንደተናገረው ጌታችን በቃሉ\nበእኔ የሚያምኑ ድንቅን ይሰራሉ\nደዌ እንዲርቅለት ፈውስን የተጠማ\nከደጇ ላይ ይውደቅ ይበላት አርሴማ\nከደጇ ላይ ይውደቅ ይበላት አርሴማ', 'am', 52, 0),\n(5, 'እሰይ ነጋ', 'እሰይ ነጋ\nእሰይ ነጋ እሰይ ነጋ ላመሰግንህ ነው\nአይኔን የከደንኩት አንተን አምኜ ነው\nእሰይ ነጋ እሰይ ነጋ ላመሰግንህ ነው\nአይኔን የከደንኩት አንተን አምኜ ነው\n\nበበደሌ ሳትፈርድ ትጠብቀኛለህ\nከእኔ በላይ ለእኔ ታስብልኛለህ\nየማታንቀላፋው ትጉህ እረኛዬ\nብርሃኑን ያየሁት ባንተ ነው ጌታዬ\n\nቀናቶቼን ሰጠሁ ላንተው አሳልፌ\nበሰላም እተኛለሁ በክንድህ አርፌ\nተመስገን ማለትን በብርሃን ጨለማ\nታስተምረኛለህ በወፎቹ ዜማ\n\nትናንትናን ታልፎ ስላየሁ አዲስ ቀን\nከእንቅልፌ ስነቃ እላለሁ ተመስገን\nአንተ ባታነጋው የጨለመውን\nአልኖርም ነበረ ዛሬ ባልኩት ቀን\n\nሁሉም የሚሆነው እንደየ ስርዐቱ\nበአንተ ብቻ እኮ ነው መጨለም መንጋቱ\nስለ አደረክልኝ ምኔን ልክፈልህ\nተመስገን ብቻ ነው ሥላሴ ዋጋህ\n\nበብርሃን ተተካ አስፈሪው ጨለማ\nእንደኔማ ሳይሆን ምህረትህ ቀድማ\nየእኔ ያልኳት ዛሬ ነግታ የምትመሸው\nበጥበቤ አይደለም በበጎነትህ ነው', 'am', 53, 0),\n(5, 'ማርያም ማርያም ብዬ', 'ማርያም ማርያም ብዬ\nማርያም ማርያም ብዬ ስምሽን ልጥራው\nአይደክመኝም እኔ ብደጋግመው\nአሁንም ጠራሁሽ አላስችልህ ቢለኝ\nአውቀዋለሁ ስምሽን እናቴ ስትወልደኝ\nአውቀዋለሁ ስምሽን እናቴ ስትወልደኝ\n\nገና በማህጸን በእናቴ የምጥ ቀን\nደጋግሜ ሰማሁ ሲጠሩ ስምሽን\nበሰከንዳት እድሜ የማውቃት አንዲት ቃል\nልቤ ላይ ያለው ስም ማርያም ማርያም ይላል\nልቤ ላይ ያለው ስም ማርያም ማርያም ይላል\nማርያም ማርያም\n\nሔዋን ምጧ ቀሎ ልጆቿን ታቀፈች\nበአማላጅነትሽ እናቴም ታመነች\nበተወለድኩበት በመጀመሪያው ቀን\nስምሽን እየሰማሁ ወጣሁ ከማህጸን\nስምሽን እየሰማሁ ወጣሁ ከማህጸን\nማርያም ማርያም\n\nከቃልኪዳን ስም ጋር አደግኩኝ አብሬ\nምልጃሽ ሳይለየኝ አለሁ እስከ ዛሬ\nየህይወቴን ፊደል ካንቺ ላይ ቆጠርኩኝ\nበልጅሽ አምኜ ዳግም ተወለድኩኝ\nበልጅሽ አምኜ ዳግም ተወለድኩኝ\nማርያም ማርያም\n\nየክፉ ቀን ስንቄ ያዘልኩሽ በልቤ\nየህይወቴ ምግብ የእንጀራ መሶቤ\nእንደ ትላንትናው ዛሬም እጠራሻለሁ\nየመስቀል ስር ክብሬን እንዴት እረሳለሁ\nየመስቀል ስር ክብሬን እንዴት እተዋለሁ\nየመስቀል ስር ክብሬን እንዴት እተዋለሁ\nማርያም ማርያም', 'am', 54, 0),\n(5, 'ለምን ጠላኸኝ ወንድሜ', 'ለምን ጠላኸኝ ወንድሜ\nለምን ጠላኸኝ ወንድሜ የአንድ አባት ልጆች እኮ ነን\nለምን ጠላኸኝ ወንድሜ የአንድ እናት ልጆች እኮ ነን\nብዙ ነዉ መንግስቱ አብረን እንወርሳለን\nሰፊ ነዉ ግዛቱ አብረን እንወርሳለን\n\nየተካፈልኩትን ንብረት አትፍቼ ብመለስ ዛሬ\nአባቴ ናፍቆኝ ብመጣ ልቤን አንገቴን ሰብሬ\nለሁላችንም ይበቃል ብዙ ነዉ የእርሱ መንግስት\nአይክፋህ እባክህ ወንድሜ ፍቅር ይበልጣል ከሀብት\n\nፊትህ በሀዘን አይጥቆር ድንጋዩን ጣለዉ ወንድሜ\nተቅበዝባዥ እንዳያደርግህ እጅህ ቆሽሾ በደሜ\nልብህን መልካም ብታደርግ የአንተም መስዋዕት ያርጋል\nጌታ ለሁሉም እኩል ነዉ መታዘዝ ንጉስ ያደርጋል\n\nብልጥ ስለሆንኩ አይደለም የተባረኩት በጌታ\nጽኑ መሻቴን አይቶ ነዉ በኩር ያደረገኝ ስመታ\nየበቀል ጦርክን ሸሽቼ በባዕድ ሀገር ብኖርም\nበልጅ በትዳር ባርኮኛል አብረን እንኑር በሰላም\n\nብልጥ ስለሆንኩ አይደለም የተባረኩት በጌታ\nጽኑ መሻቴን አይቶ ነዉ በኩር ያደረገኝ ስመታ\nየበቀል ጦርክን ሸሽቼ በባዕድ ሀገር ብኖርም\nበልጅ በትዳር ባርኮኛል አብረን እንኑር በሰላም', 'am', 55, 0),\n(5, 'ፈቃዴ ይህ ነው', 'ፈቃዴ ይህ ነው\nፈቃዴ ይህ ነው የሠውን ነገር ላልናገር\nፈቃዴ ይህ ነው የሠውን ነገር ላልናገር\nየእኔ ተሽፍኖ ከቆምኩኝ በክብር\nፈቃዴ ይህ ነው የሰውን ነገር ላልናገር\n\nህይወቴ በሙሉ በኃጢአት ተመልታ\nአምላኬ ከማረኝ በፍቅሩ ዝምታ\nየሰው በደል ላላይ በእውነት ምያለው\nእኔን ከታገሰኝ ፍቅር ተምሪያለው\nእኔን ከታገሰኝ ፍቅር ተምሪያለው\n\nባይኔ ፊት ተጋርዶ ያለውን ምሰሶ\nእያየ ካለፈኝ በምህረት ታግሶ\nየሰው ጉድፍ ላላይ በእውነት ምያለው\nእኔን ከታገሰኝ ፍቅር ተምሪያለው\nእኔን ከታገሰኝ ፍቅር ተምሪያለው\n\nአንተ ቀራጩ ሰው ያለህ አቀርቅረህ\nበምህረት ተመለስክ ከኔ ይልቅ ድነህ\nባንተ ላይ ስጠቁም የኔን ጸሎት ትቼ\nየመዳኑ ሰዓት አለፉ ቀኖቼ\nየመዳኑ ሰዓት አለፉ ቀኖቼ\n\nተቆጥሮ የማያልቅ በደሌ ተከድኖ\nበሞትና በደም ሃጥያቴን ሸፍኖ\nሰው አርጎኝ በሰው ፊት አቁሞኝ ጌታዬ\nበማንም አልፈርድም ሀጥያተኛ ብዬ', 'am', 56, 0),\n(5, 'ኪዳነ ምህረት እናቴ', 'ኪዳነ ምህረት እናቴ\nኪዳነ ምህረት እናቴ ምስጢረኛዬ ጓዳዬ\nየጎደለኝን ታውቂያለሽ\nከአፌ ሳይወጣ ሳልነግርሽ\nከአፌ ሳይወጣ ሳልነግርሽ\n\nአልፏል መናኛው ኑሮ\nምልጃሽ ውኃውን ቀይሮ\nመልካሙ ወይን ደረሰ\nእንባዬ ባንቺ ታበሰ\nመልካሙ ወይን ደረሰ\nእንባዬ ባንቺ ታበሰ\n\nልዘምር ልቁም ከፊትሽ\nልምጣ ልንበርከክ ለክብርሽ\nብርቅ ከሀገር ከቤቴ\nከቶ አልረሳሽም እናቴ\nብርቅ ከሀገር ከቤቴ\nከቶ አልረሳሽም እናቴ\n\nአልልም መቼ ነው ቀኑ\nየኔ መጎብኛ ዘመኑ\nእንደሚፈፀም አምናለው\nሁሉን በጊዜው አያለው\nሁሉን በጊዜው አያለው\n\nየልቤን ችግር ላዋይሽ\nከስዕልሽ ፊት ቆሜ\nእንባዬ ቀድሞ ዝም አልኩኝ\nሳልነግርሽ ስለምታውቂ\nሳልነግርሽ ስለምታውቂ', 'am', 57, 0),\n(5, 'እኔ አንተ ቤት', 'እኔ አንተ ቤት\nእኔ አንተ ቤት እኔ አንተ ፊት\nየምቆም ሠው አይደለሁም\nግን ፍቅር ነህ ለዘለዓለም\nየሚመስልህ ማንም የለም\nግን ፍቅር ነህ ለዘለዓለም\nየሚመስልህ ማንም የለም\n\nፀሎቴ ቢሆን ለወረት\nጎዶሎ ቢሆን የኔ እምነት\nባረከኝ እኔን ከሠማይ\nበደል ጥፋቴንም ሳታይ\nቀባኸኝ ጠርተኸኝ ከዱረ\nሠጠኸኝ ከፍ ያለ ወንበር\nሳይኖረኝ አንድም በጎነት\nባረከኝ በእጅህ በረከት\n\nቃልኪዳንህን አክባሪ\nታማኝ ነህ ሁሌም መሀሪ\nየማልከውንም መሀላ\nአትረሣም አትልም ችላ\nመካሪ ድንቅ መምህሬ\nላንተ ነው ዜማ መዝሙሬ\nፍቅር ነህ ከአባትም በላይ የሠማይ የምድር ሲሣይ\n\nመሻቴን ብቻ ስላየህ\nደካማ ልጅክን ጎበኘህ\nብቃቴ መቼ ሆነና\nያቆመኝ ላንተ ምስጋና\nአንኳኩ ስላልክ አንኳኳው\nጠይቁ ስላልክ ጠየኩኝ\nከፍተሃል በርህን ለኔ\nየታተምኩብህ መድህኔ', 'am', 58, 0),\n(5, 'አምላኬ ታሪኬን ለውጠው', 'አምላኬ ታሪኬን ለውጠው\nአምላኬ ታሪኬን ለውጠው\nአምላኬ ታሪኬን ለውጠው\nጌታዬ ታሪኬን ለውጠው\nጌታዬ ታሪኬን ለውጠው\nሠው አርገኝና ሠው ይግረመው\nሠው አርገኝና ሠው ይግረመው\n\nእስከ መቼ በበደል እስከመቼ በኃጥያት\nአስመሳይ ማንነቴ ነፍሴን እያስጨነቃት\nመሸከም ስላቃተኝ የበዛው እዳዬን\nበጽድቅ ልመላለስ ለውጠው መዓዛዬን\nበጽድቅ ልመላለስ ለውጠው መዓዛዬን\n\nቃልህን ልኑረው በእድሜ በዘመኔ\nታስባለህ እና ከእኔ በላይ ለኔ\nየፍቅር ሰው ልሁን ደግሞም የይቅርታ\nየሚሳንህ የለም ታስችላለህ ጌታ\nየፍቅር ሰው ልሁን ደግሞም የይቅርታ\nየሚሳንህ የለም ታስችላለህ ጌታ\n\nበስምህ ይዳሰስ የኃጥያት ለምፄ\nበቃልህ መዶሻ ይስተካከል ቅርፄ\nቀራጩን ለክብርህ ታንበረክካለህ\nሠው ታደርገውና ሠው ታስገርማለህ\nሠው ታደርገውና ሠው ታስገርማለህ\n\nፍሬ እንዳላፈራ በእሾህ መታነቄ\nአጥብቀህ ስጠራኝ አብዝቼ መራቄ\nበቃህ በለኝ ጌታ ልቤን አነሳሳው\nበመንፈስህ ቃኘኝ ኃጥያቴን ድል ልንሳው\nበመንፈስህ ቃኘኝ ኃጥያቴን ድል ልንሳው\n\nየኋላዬን ትቼ ወደፌት ልዘርጋ\nዋጋ እንዳላሳጠው የደምህን ዋጋ\nእንዳሸንፍ እርዳኝ ስምህን ታጥቄ\nዳግም ባሪያ እንዳልሆን ልጅነትን ንቄ', 'am', 59, 0),\n(5, 'ጌታዬ ሆነ', 'ጌታዬ ሆነ\nጌታዬ ሆነ ደም ግባት አልባ\nጀርባዉ በጅራፍ ስለኔ ደማ\nየኔን መገርፍ እርሱ ተገርፎ\nክብር አለበሰኝ እርሱ ተገፎ\nክብር አለበሰኝ እርሱ ተገፎ\n\nበሀሰት ሸንጎ ወጥመድ ተጠምዶ፣\nጌታ ተያዘ ህይወቴን ፈቅዶ\nክፉዎች ቢያዩት እንደ ወንበዴ\nለኔ ግን ሆኗል መዉጫ መንገዴ\nለኔ ግን ሆኗል መዉጫ መንገዴ\nታስረኃል ስለኔ ኢየሱስ መድኅኔ\nታስረኃል ስለኔ ኢየሱስ መድኅኔ\n\nሲዘብቱበት ምራቅ ሲተፉ\nየማይደፈር ደፍረው ሲዘልፉ\nበከበቡት ፊት ቃል ከለከለ\nእኔ እንድናገር እርሱ ዝም አለ\nእኔ እንድናገር እርሱ ዝም አለ\nታርደኃል ስለኔ ኢየሱስ መድኅኔ\nታርደኃል ስለኔ ኢየሱስ መድኅኔ\n\nህይወት መንጭቷል ተወግቶ ጎኑን\nለከሳሾቹ ተርፏል ማዳኑ\nእጅ እግሩን ምስማር ሲቸነክረዉ\nየሞትን እሾህ ከኔ ነቀለዉ\nየሞትን እሾህ ከኔ ነቀለዉ\nተወጋ ስለኔ ኢየሱስ መድኃኔ\nተወጋ ስለኔ ኢየሱስ መድኃኔ\n\nእርቃኑን ሆኖ ፈተለዉ ልብሴን\nአንዲሁ ወዶኝ ጠጣ ቆምጣጤ\nበምህረቱ ጥል ነብሴን አርክቶ\nአለመለመኝ አርሱ ተጠምቶ\nአለመለመኝ አርሱ ተጠምቶ\nተጠማ ስለኔ ኢየሱስ መድኃኔ\nተጠማ ስለኔ ኢየሱስ መድኃኔ', 'am', 60, 0),\n(5, 'የሉም ከሳሾቼ', 'የሉም ከሳሾቼ\nየሉም ከሳሾቼ እነሱም ተከሰው\nየሉም ከሳሾቼ እነሱም ተከሰው\nገመናዬን ሸፋኝ ከቶ እንዳንተ ማን ነው\nገመናዬን ሸፋኝ ከቶ እንዳንተ ማን ነው\n\nገና ሳልፈፅመው ኃጥያቴን ለሚያውቀው\nይነግሩት ጀመረ እንዳላዋቂ ሰው\nወድቀው ተማፀኑት በሞት እንድመታ\nመስሏቸው ሞኝነት የፍቅሩ ዝምታ\nመስሏቸው ሞኝነት የፍቅሩ ዝምታ\n\nእያለ ተጋድሞ ምሰሶው በአይናቸው\nየኔን ጉድፍ ማየት እንዴት ተቻላቸው\nበፈረዱበት ፍርድ እነሱም ወደቁ\nበኔ ላይ በመፍረድ ከቶ መች ፀደቁ\nበኔ ላይ በመፍረድ ከቶ መች ፀደቁ\n\nበሰፈረው መጠን ከሳሽ ይሰፈራል\nከቁጣው እሳት ፊት መች ማምለጥ ይቻላል\nየሁላችን ዋጋ በእጁ ላይ እያለን\nበመንግስቱ ስልጣን ማን ፈራጅ አረገን\nበመንግስቱ ስልጣን ማን ፈራጅ አረገን\n\nመዝገቡ በእጁ ነው አይመረመርም\nሐጥያቴን እንዲያውቀው ነጋሪ አይፈልግም\nከሳሾቼ እመኑ ጌታዬ ምሮኛል\nእግዚአብሔር ሰው ነግሮት መቼ ፈርዶ ያውቃል\nእግዚአብሔር ሰው ነግሮት መቼ ፈርዶ ያውቃል', 'am', 61, 0),\n(5, 'እጠበኝ ቆሽሻለሁ', 'እጠበኝ ቆሽሻለሁ\nእጠበኝ ቆሽሻለሁ አምላኬ በድያለሁ\nያለ እናት ያሳደከኝ ያለ አባት የጠበከኝ\nያን ሁሉ ዛሬ ረሳሁ እጠበኝ ቆሽሻለሁ\nያን ሁሉ ዛሬ ረሳሁ እጠበኝ ቆሽሻለሁ\n\nከድንኳንህ ስታስገባኝ ሞገስ ሰጥተህ\nየአፍኒንን ምግባር ይዤ አስቀየምኩህ\nቅብዓ ሜሮን ያተምክበት ልጅነቴ\nእንዳይጎድፍ ጠብቅልኝ ቸር አባቴ\n\nኃይል አኑረህ እንደ ሶምሶን በፀጉሬ\nጎልያድን አስጥለክኝ በጠጠሬ\nአቅም ቢያንስኝ በሥጋ ጦር ተሸንፌ\nደጅህ መጣሁ የእንባ መባ ባይኔ አቅፌ\n\nእንዳትረሳኝ በመዳፍህ ቀርፀኸኛል\nእንዳተወኝ ያለመጠን ወደኸኛል\nባትሰነዝር ልትቀጣኝ የሞት በትር\nየትግስትህ ስሌዳ ነው የኔ ክብር\n\nከከንፈሬ ጥበብ ፅፌ ቅኔ ቢፈስ\nበመታበይ አሳዘንኩት ያንተን መንፈስ\nፍቅር ግተህ በእቅፍህ ስር ያሳደከኝ\nእባክህን በበደሌ አትቅሰፈኝ', 'am', 62, 0),\n(5, 'እንደምትወደኝ አውቃለሁ', 'እንደምትወደኝ አውቃለሁ\nእንደምትወደኝ አውቃለሁ\nእንደምትወደኝ አውቃለሁ\nሁሌም ስትጠራኝ እሠማለሁ\nየቅጠል ልብስን ብለብስም\nሞቴን አትፈልግም\nሞቴን አትፈልግም\n\nከቤተልሔም ጎልጎታ\nእስከ ቀራንዮ ኮረብታ\nእየተከተልክ ፈለከኝ\nከኃጥያት ቁስሌ ፈወስከኝ\n\nሞቴን አትፈልግም\n\nእረሳው ጌታ ሕግህን\nቀጥፌ በላው በለስን\nከገነት ቤቴ ተሰደድኩኝ\nከፍቅር እጅህ ተለየሁኝ\n\nእንደምትወደኝ አውቃለሁ\n\nተብለህልኝ ወንጀለኛ\nቆመህልኛል ከሃሰት ዳኛ\nአንተ ስትሞት ተሰቅለህ\nክብርን ጠገብኩኝ ከእጅህ\n\nእንደምትወደኝ አውቃለሁ\n\nአሁን የለብኝ ወቀሳ\nከፍለህልኛል ለኔ ካሳ\nመልሰኸኛል ወደ ቤቴ\nአክብረኸኛል ደጉ አባቴ\n\nእንደምትወደኝ አውቃለሁ', 'am', 63, 0),\n(5, 'መርከቧን የሚያውክ', 'መርከቧን የሚያውክ\n\nመርከቧን የሚያውክ ነፋስ መቷል\nአድኅነን ጌታ ሆይ ተጨንቀናል\nአድኅነን ክርስቶስ ተማጽነናል\n\nአንድ እግዚአብሔር ጥላ ተሰብስበው ሳሉ\nበቀለም በጎሳ ይከፋፈላሉ\nእጅግ ተናውጣለች ታንኳችን ተገፍታ\nአውጅልን ደርሰህ ታላቁን ፀጥታ\nአውጅልን ደርሰህ ታላቁን ፀጥታ\n\nየጥፋት እርኩሰት በመርከቧ ነግሶ\nእረኛ ነኝ ይላል ተክሏው ለምድ ለብሶ\nቤተሰቤ ሁሉ ተጨንቋል በነፍሱ\nሞገዱን ገስጸው ፀጥ ይበል ነፋሱ\nሞገዱን ገስጸው ፀጥ ይበል ነፋሱ\n\nእኔ እበልጥ እኔ እበልጥ መባባሉ በዝቷል\nየትህትና መጉደል መርከቧን አውኳል\nስንጠፋ አይገድህም ብለን ስንጣራ\nአንተ ግን አንተ ነህ ዛሬም ለኛ እራራ\nአንተ ግን አንተ ነህ ዛሬም ለኛ እራራ\n\nበቁጥር የበዙ ታንኳዎች እያሉ\nአንተ ባለህበት አይሏል መዕበሉ\nዘንበል በልልን ጌታ ዝም አትበለን\nበእምነት ከመዛል ከመስጠም አድህነን\nበእምነት ከመዛል ከመስጠም አድህነን', 'am', 64, 0),\n(5, 'ሰላም አርጊው', 'ሰላም አርጊው\nሰላም አርጊው ማርያም ስጭን የእጅሽን\nሰላም አርጊው ማርያም ስጭን የእጅሽን\nአንድ መንጋ ሆነን በዛ ቋንቋችን\nናፍቀናል ልጆችሽ ፍቅር አንድነትን\n\nበስንዴው መሀል እንክርዳዱን\nጠላት ዘራና ክፍፍሉን\nየፍቅር ቋንቋ ቀዘቀዘ\nአንድነታችን ደበዘዘ\nእንወድሻለን ማርያም\n\nያስጎነበሰን ሽክም ይቅለል\nበልጅሽ ምህረት ቀና እንበል\nሰላም እንዲሰፍን በምድሪቱ\nንጉሱን ማልጂው ንግስቲቱ\nእንወድሻለን ማርያም\n\nየሽምገላ ቃል ከእኛ አይውጣ\nያክፉ ዘመን እንዳይመጣ\nበመለያየት ተመስርቶ\nየፀና መንግስት የለም ከቶ\nእንወድሻለን ማርያም\n\nበረከት አዞል አምላካችን\nህብረት ባለበት መኖራችን\nክፍፍል ይቅር አሳስቢልን\nበቃል ኪዳንሽ አስጠልይን\nእንወድሻለን ማርያም\n\nክፋትን ተክለን በልባችን\nመልክ ብቻ ነው አምልኳችን\nወድቀን እንዳንቀር እንዳንጠፋ\nፍቅርን ሳይብን የአዳም ተስፋ\nእንወድሻለን ማርያም', 'am', 65, 0),\n(5, 'አትንገሩት ያውቀኛል', 'አትንገሩት ያውቀኛል\nአትንገሩት ያውቀኛል\nአትንገሩት ያውቀኛል\nአትንገሩት ያውቀኛል\nአትንገሩት ያውቀኛል\nስራዬ በፊቱ መቼ ተሰውሯል\nአትንገሩት ያውቀኛል\n\nፊልጶስ ሳይጠራኝ ገና ሳልቆም ፊቱ\nከበለስ ስር ሳለው ያውቀኛል ከጥንቱ\nመካሪ አያሻውም ሁሉን ያውቃልና\nከሳሽ ሆይ ተመለስ ድንጋዩን ጣልና\n\nታናሹ ተቀባ ታላቆቹ ሳሉ\nለምን እንዲህ ሆነ ስህተት ነው አትበሉ\nለክብር የጠራኝ ከባህር ዳር ቆሞ\nሶስቴ እንደምክደው ያውቃል አስቀድሞ\n\nሀጢያተኟነቱን ሳያውቅ ገባ ቤቱ\nብላችሁ አትሙት በዝቶ ነው ምህረቱ\nየአባቴን ንብረት ባባክን ፈጽሜ\nእንዴት ልጅ ይሆናል አትበል ወንድሜ', 'am', 66, 0),\n(5, 'እግዚአብሔርን የምትወዱ', 'እግዚአብሔርን የምትወዱ\nእግዚአብሔርን የምትወዱ\nአምላኬ ነው የምትሉ\nክፋትን ጥሉ\n\nየታተማችሁ በቅዱስ ደሙ\nየተጠራችሁ በሕያው ስሙ\nከፀብ እራቁ ሽሹ ከክፋት\nፍቅንር ልበሱ ቁሙ በእውነት\n\nበቀልን ገንዘብ የምታደርጉ\nከወንድማችሁ የምትዋጉ\nየጠራን በዚህ ስለማይከብር\nእያመለክነው አንከራከር\n\nመገፋት እንጂ የኛ ግብራችን\nእንደተማርነው ከአምላካችን\nአትታወቁ ሰውን በመክሰስ\nበእግረ ስጋ በመመላለስ\n\nማህተብ ያሰረ ከአንገቱ ላይ\nየፍቅር ሰው ነው በምድሪቱ ላይ\nመስቀልን እንጂ ሾተል አይዝም\nየሚያጣፍጥ ነው አልጫን አለም', 'am', 67, 0),\n(5, 'መስቀል ላይ', 'መስቀል ላይ\nመስቀል ላይ ያየሁት ፍቅር\nመስቀል ላይ ያየሁት ፍቅር\nይቀሰቅሰኛል ለስሙ እንድዘምር\nይቀሰቅሰኛል ለስሙ እንድዘምር\n\nፊቱን እየፀፉት እየተንገላታ\nፊቱን እየፀፉት እየተንገላታ\nበጦር እየወጉት ይሰጣል ይቅርታ\nበጦር እየወጉት ይሰጣል ይቅርታ\nእነርሱ እየጠሉት እርሱ ይወዳቸዋል\nእነርሱ እየጠሉት እርሱ ይወዳቸዋል\nአስረው ሲጎትቱት ይከተላቸዋል\nአስረው ሲጎትቱት ይከተላቸዋል\n\nፃድቁን ሃጥእ ነው እውነትን ሃሰት\nፃድቁን ሃጥእ ነው እውነትን ሃሰት\nእያሉ ሲጮሁ ይሰቀል ይሙት\nእያሉ ሲጮሁ ይሰቀል ይሙት\nእየመረመረው ፍጡር ፈጣሪን\nእየመረመረው ፍጡር ፈጣሪን\nክርስቶስን አስሮ ፈታው በርባንን\nክርስቶስን አስሮ ፈታው በርባንን\n\nጀርባውን ሲገርፉት በሚያቃጥል ጅራፍ\nበምህረት ያዛቸው በይቅርታው እቅፍ\nበምህረት ያዛቸው በይቅርታው እቅፍ\nጨክነው ሲያጠጡት መራራ ሃሞት\nጨክነው ሲያጠጡት መራራ ሃሞት\nደሙ ውሃ ፈሰሰ ጎኑን ሲወጉት\nደሙ ውሃ ፈሰሰ ጎኑን ሲወጉት\n\nግምጃን አለበሱት ቀሚሱን ገፈው\nግምጃን አለበሱት ቀሚሱን ገፈው\nበራሱም አኖሩ እሾህ ጎንጉነው\nበራሱም አኖሩ እሾህ ጎንጉነው\nየአይሁድ ንጉስ ሆይ እያሉ ዘበቱ\nየአይሁድ ንጉስ ሆይ እያሉ ዘበቱ\nለህይወት ሆናቸው የክርስቶስ ሞቱ\nለህይወት ሆናቸው የክርስቶስ ሞቱ', 'am', 68, 0),\n(5, 'የራሴን ፀጉር', 'የራሴን ፀጉር\nየራሴን ፀጉር ቁጥሩን ያውቀዋል\nየእጁ ስራነኝ መች ይረሳኛል\nየልቤ መሻት ዛሬ ባይሞላም\nእግዚአብሔር አለ አልጨነቅም\n\nስለምግብና ስለምለብሰው\nብዙ ብጨነቅ ጥቅሙ ምንድነው\nአበባን ለምድር ምግብን ለወፎች\nየሚሰጥ አባት አለኝ ሳይሰለች\n\nየማያምኑትን ስሙን ሳያውቁ\nየሚያገኙትን ሳይጨነቁ\nስለምን ልድከም በከንቱ መሻት\nእያለ ጌታ ያዳነኝ ከሞት\n\nየክፉዎች ሰልፍ ቢሰፍር በላዬ\nዝናሩን ታጥቆ ቢዝት ገዳዬ\nበሞት ጥላ ውስጥ ብጓዝ ብሔድም\nየሚጠብቀኝ አያንቀላፋም\n\nሀሳቤን ልጣል በእረኛዬ\nበሚያሰማራኝ ቸር ጠባቂዬ\nከበረከት ምንጭ አያሳጣኝም\nበግ ስለራሱ ተጨንቆ አያውቅም\n\nመንግስቱን ልሻት ልፈልግ ፅድቁን\nስለሚሰጠኝ ጌታ ሌላውን\nስለሚጨነቅ ነገ ለራሱ\nላመስግን ዛሬ ታምኜ በእርሱ', 'am', 69, 0),\n(5, 'እናቱ ታውቅ ነበር', 'እናቱ ታውቅ ነበር\nእናቱ ታውቅ ነበረ መድኃኒት መሆኑን\nኢየሱስ አለችው ስታወጣ ስሙን\n\nመልዓኩ ገብርኤል ከእግዚአብሔር ተልኮ\nሲታጠቅ ሲፈታ ፊትሽ ተንበርክኮ\nትይዋለሽ አለሽ ልጅሽን ኢየሱስ\nመድኃኒት ነውና ሁሉን የሚፈውስ\n\nከስጋዋ ስጋ ነስቶ ከነፍሷ ነፍስ\nበተዋህዶ ሚስጢር የኛን ስጋ ቢለብስ\nአማኑኤል ተባለ ቢዛመድ ከሰው\nቅዱስ እግዚአብሔር ከኛ ጋር ነው\n\nብላ ሰየመችው መድኃኒአለም\nሰውን ወዷልና እስከዘለዓለም\nልጄ ወዳጄ ሆይ ስትለው ነበር\nእርሱም ለእናቱ ታዟል በፍቅር\n\nየትንቢቱን መጽሐፍ እያነበበች\nሀር ወርቁን አስማምታ እየፈተለች\nዙፋኑ መሆኑን አውቃ ነበርና\nገለጸች እራሷን በፍጹም ትህትና\n\nጨለማን የሚያርቅ ብርሃን ወለዳለች\nእርሷም የብርሃን እናቱ ተባለች\nአምላክን በክንዷ ብትታቀፈው\nወላዲተ አምላክ የእርሷ ስም ነው', 'am', 70, 0),\n(5, 'ከእኔ የበረታችሁ', 'ከእኔ የበረታችሁ\n\nከኔ የበረታችሁ\nከኔ የበረታችሁ\nአስቡኝ በጸሎታችሁ\nአስቡኝ በጸሎታችሁ\n\nየትናንት ትጋቴ ባይኖር ከእኔ ጋራ\nእኔን ባታዩኝም በመልካሙ ስራ\nሸክሜን ተሸክሙ አትፍረዱ በእኔ\nነገ መውደቅ አለ የቆምከው ወገኔ\n\nከበሮ የያዝሺው የሙሴ እህት ማርያም፣\nኃጢእት ያደረገው ሙሴ ቢመስልሽ\nጥቁሪቱን አጋባ ወድቋል አትበዪ ልምጥ እንዳይወጣብሽ ፍርዳን ስአምላክ ተዬ\n\nከትእዛዛቱ አትወድቅም አንዲቱ\nየህግ ትንሽ የለም እኩል ነው ቅጣቱ\nቢመስልም በፊትህ ስራዬ የከፋ\nፍርዱን ተወውና ጸልይ እንዳልጠፋ\n\nአዋቂ ነው ጌታ ሁሉን ይመዝናል\nድካምን ሳይቆጥር በፀጋው ያቆማል\nብርቱ የሆናችሁ ለደካማው ትጉ\nለፍርድ እጅን ሳይሆን ርህራሄን ዘርጉ', 'am', 71, 0),\n(5, 'ፍቅር እንደዚህ ነው', 'ፍቅር እንደዚህ ነው\nፍቅር እንደዚህ ነው\nመዳናችን በነፃ ነው\nከኛ አንዳች ሳይ ጠብቅ\nአንስቶናል ከመውደቅ\n\nእግዚአብሔር ሳንወደው ስለወደደን\nማስተሰርያ እንዲሆን ልጁን ላከልን\nአየን በይቅርታ ተወዳጅ ባንሆንም\nፍቅር እንደዚህ ነው በደልን አይቆጥርም\n\nገንዘቡ ሊያደርገን ሊያነፅን ለራሱ\nስቃይ ተቀብሏል ተጨንቋል በነብሱ\nከአመፅ ሁሉ የተቤዠን ጌታ\nእራሱ ፍቅር ነው ማይ ጠብቅ ውለታ\n\nስናዝን አብሮን ነው ስንደሰት አብሮን\nብንቆረቁረውም መቼ ይሄዳል ጥሎን\nእንደሰው አይደለም ሁሌም ይታመናል\nፍቅር እንደዚ ነው በሁሉ ይፀናል\n\nከኛ ጋር ይሆናል ስንዋደድ እኛ\nበተገደለ ጥል አንኑር ዳግመኛ\nበጉርፍ በንፋስ አይነቃነቅም\nፍቅር እግዚአብሔር ነው ዘወትር አይወድቅም', 'am', 72, 0),\n(5, 'ጌታን ያቀፋት እጆችሽ', 'ጌታን ያቀፋት እጆችሽ\nጌታን ያቀፋት እጆችሽ\nእኔንም በፍቅር አቀፋ\nድንግል ማርያም በምልጃሽ\nክፋ ቀናቶች አስፋ\nየእግዚአብሔር እናት የሆንሽው\nለእኔም ሆነሻል እናቴ\nማርያም ስምሽ ሞገሴ ነው\nውዳሴሽ ጽነ ጉልበቴ\n\nመች ዘምሬልሽ ጠገብኩኝ\nመች ረካሁ አመስግኜ\nስምሽን በለበስኩት\nእንደ አባቶቼ ሆኜ\nልጅሽ የመረጣቸው\nያከበሩሽ ከብረዋል\nበሰማይና በምድር\nየልጅሽ ወዳጅ ሆነዋል\n\nዓይኔ በእንባ ይመላል\nይዘላል ልቤ በደስታ\nየጌታዬ እናት ብዬ\nሳቀርብ ኣንቺ ሰላምታ\nባረገኝ እንደ መልአኩ\nለእኔም አክናፍን በሰጠኝ\nከፊትሽ እንዳደገድግ\nአምላክ ወዳንቺ በላከኝ\n\nየመማጸኛ ጽናዬ\nየጸሎቴ ሙዳይ ነሽ\nየምስጋናዬን መስዋዕት\nስአምላክ የማቀርበብሽ\nየቤትሽ ተክል ነኝና\nእንዳልጠወልግ በከንቱ\nየሕይወት ውኃን አጠጪኝ\nድንግል አማላጂቱ\n\nበቃልኪዳንሽ ታምኜ\nኃጢአቴን እከሳለሁ\nበተወደደው ልጅሽ ፊት\nራሴን እጥላለሁ\nየምስጋና መሰንቆ ነሽ\nየቅዳሴውም እንዚራ\nየዓለሙ ንጉሥ ነውና\nእግዚአብሔር ከአንቺ ጋራ', 'am', 73, 0),\n(5, 'ሀሳብክን ልከተል', 'ሀሳብክን ልከተል\nኃጢአት እንድሰራ አለማመደና\nኃጢአት እንድሰራ አለማመደና\nበአንተ ፊት ከሰሰኝ ጠላቴ እንደገና\nበአንተ ፊት ከሰሰኝ ጠላቴ እንደገና\nሃይልህን አድለኝ ልውደድህ አብዝቼ\nሃሣብክን ልከተል የእሱን ሃሣብ ትቼ\nሃሣብክን ልከተል የእሱን ሃሣብ ትቼ\n\nከመቅበዝበዝ በቀር ምን አትርፌ አውቃለው\nየሳቅኩኝ ሲመስለኝ ዘውትር አለቅሳለው\nበማስመሰል ኑሮ ያለሁኝ ሲመስለኝ\nበቃልህ ስመዘን ባንተ ዘንድ ሞት ነኝ\n\nክፉን እያሳየ መልካም አስመስሎ\nሙሉ የነበርኩት አረገኝ ጎዶሎ\nየድርሻህን ውሰድ ብሎ የመከረ\nየእሪያዎች አሰር ያስበላኝ ጀመረ\n\nከምትሳሳልኝ ከአንተ ከወዳጄ\nጠላትህ ሆኛለሁ ዓለምን ወድጄ\nምኞቴን ስከተል ከአንተ ተለየሁኝ\nፍሬም አላፈራ ቅጠል ብቻ ሆንኩኝ\n\nከቦኝ የነበረው በስልጣን በዝና\nወዳጅ የመሰለኝ ጠላቴ ሆነና\nይካሰሳት ጀመር ነፍሴን ሊናጠቃት\nአድናት ክርስቶስ ወደኸው ሞትክና', 'am', 74, 0),\n(5, 'የማደርገውን አላውቅም', 'የማደርገውን አላውቅም\nየማደርገውን አላውቅም ይቅር በለኝ አባቴ\nየማደርገውን አላውቅም ይቅር በለኝ አባቴ\nቸንክሬሃለሁ በበደሌ ቸንክሬሃለሁ በኃጢአቴ\nቸንክሬሃለሁ በበደሌ ቸንክሬሃለሁ በኃጢአቴ\n\nድምፄን ከፍ አድርጌ እያልኩኝ ተዋጀሁ\nየነገዴ ቋንቋ ወገን ፈልጋለሁ\nአልታረቅ አለኝ ቃልና ተግባሬ\nኃይልህን እክዳለሁ ኃይልህን መስክሬ\nኃይልህን እክዳለሁ ኃይልህን መስክሬ\n\nለኃጢአት ልሞት ነው የሞትክልኝ ለኔ\nጨለማዬን የሻርክ ጌታ ብርሃኔ\nእጠበኝ ቆሸሽኩኝ ሆንኩኝ እንደ እሬያ\nዘመን ጨምርልኝ ይቅርታህን ማያ\nዘመን ጨምርልኝ ይቅርታህን ማያ\n\nህመም የሚነቅዝ መድኃኒት አግኝቼ\nየተሰሎንቄ ድምፅ ማባበል ሰምቼ\nወደፊት ስትጠራኝ ሄድኩኝ ወደኃላ\nማረፍ አቅቶኛል በምህረትህ ጥላ\nማረፍ አቅቶኛል በምህረትህ ጥላ\n\nለእኔ ያሰብካትን ሃሳብህን ትቼ\nማዕረጌ ጥያለሁ ከእቅፍህ ወጥቼ\nበመስቀልህ ስራ ካወረሰከኝ ስፍራ\nእንድኖር አግዘኝ ሁሌ ከአንተ ጋራ\nእንድኖር አግዘኝ ሁሌ ከአንተ ጋራ\n\nፍቅርን ስታጎርሰኝ እጅህን ነክሼ\nለፅድቅ አንፃኸኝ በበደል ፈርሼ\nህያው ነኝ ለኃጢአት ዳግም የሰቀልኩህ\nመራራዬን አጣፍጥ ጌታየማደርገውን ተማፀንኩህ\nመራራዬን አጣፍጥ ጌታየማደርገውን ተማፀንኩህ\n\nወዴት ነህ ስትለኝ በማፍርበት ቦታ\nእንዳልገኝ እርዳኝ ትችላለህ ጌታ\nትልቁም ትንሹም ማንም ወደ እኔ ሲያይ\nአንተ ተንፀባረቅ በማንነቴ ላይ\nአንተ ተንፀባረቅ በማንነቴ ላይ', 'am', 75, 0),\n(5, 'አጎንብሼ ሄጄ', 'አጎንብሼ ሄጄ\nአጎንብሼ ሄጄ ቀና ብዬ መጣው\nበዮሐንስ ፀበል ጤናዬን አገኘው\nጌታን ያጠመቁ ክቡራን እጆቹ\nተዓምር ይሰራሉ ዛሬም ለልጆቹ\n\nአልጋዬን አዝዬ በደስታ ዘለልኩኝ\nበመጥምቁ ፀበል በእጁ ተዳሰስኩኝ\nየመራኝን በትር ከእጄ ላይ ጥያለሁ\nበሰባኪው ጸሎት በምልጃው ድኛለሁ\n\nለዓለም ያልተቻላት በእምነቱ ለቆኛል\nአበቃልህ ያሉኝ እጅግ ተደንቀዋል\nበለምጽ የነደድኩት ታደስኩ እንደገና\nአዲስ አካል ይዤ ቆምኩኝ ለምስጋና\n\nያለፍኩባት ሰፈር በእምባ ተሞልቼ\nእልልታዬን ሰማች ድኜ ተደስቼ\nየንዕማን ቁስል ተራግፉአል ከላዬ\nመሞቴን የማይወድ አሰበኝ ጌታዬ\n\nአባናና ፋርፋን አስንቁአል ጸበሉ\nዮርዳኖስ በእምነት ለወረዱ ሁሉ\nዮሐንስ በመንፈስ ሲያጠምቅ አይቻለሁ\nበእጁ ተፈውሼ ምስክር ሆኛለሁ', 'am', 76, 0),\n(5, 'ስደትሽን ሳስብ', 'ስደትሽን ሳስብ\nስደትሽን ሳስብ ስለአንቺ ልገፋ\nለካስ ስደት አለ ቀን በሰው ሲከፋ\nወስዶ ሳያስቀርሽ ወንዝና ጅረቱ\nምሳሌ ሆነሻል ድንግል ለፍጥረቱ\n\nእንዳልቅበዘበዝ ሁኚ ከአጠገቤ\nድንግል ሆይ ስራሽን መዝግቦታል ልቤ\nበምሕረት ይለፈኝ በፍጹም ይቅርታ\nእሺ ባዩ ልጅሽ የታቀፍሽው ልጅሽ\n\nሱላማጢስ ብሎ ሰለሞን ጠራሽ\nየሰላም መገኛው አንቺ ስለሆንሽ\nእንበረከካለሁ እሰግዳለሁ ለአንቺ\nጠላት እንዳይጥለኝ ጉልበቴን አበርቺ\n\nየኮቲባ ቁጣ ዛቻና ክፋቷ\nአስተናግዳዋለች ምድር አፏን ከፍታ\nበአንቺ ላይ ያመጹት በቁጣው ጠፍተዋል\nከጥቅልሉ መዝገብ ከሱ ተሽረዋል\n\nለተጠሙት ነፍሳት ያጠጣቸው ጌታ\nከጀርባሽ ላይ ሆኖ በዱር ተንገላታ\nየግብጽን ጣዖታት በግርማው መታቸው\nኢየሱስ ክርስቶስ ያለቆች ጌታቸው', 'am', 77, 0),\n(5, 'አማኑኤል ፍቅርህ ይማርካል', 'አማኑኤል ፍቅርህ ይማርካል\nአማኑኤል ፍቅርህ ይማርካል\nአማኑኤል ፍቅርህ ይማርካል\nበመስቀል ተሰቅለህ መድኃኒት ሆነሃል\nአማኑኤል ፍቅርህ ይማርካል\n\nሳታቆስል በፍቅርህ ማረክኸን\nከፊት ቀድመህ በድል አስከተልከን\nበደለኞች እኛ ሆነን ሳለ\nአንተ ከፍለህ ክሳችን ተጣለ\nኪርያላይሶን ኪርያላይሶን\nኪርያላይሶን ኪርያላይሶን\n\nእንደሰማን እንዲሁ አይተናል\nማዳንህን ቀምሰን መስክረናል\nየእግዚአብሔር በግ ቆስለህ የፈወስከን\nወደ ድንቁ ብርሃን ያሻገርከን\nኪርያላይሶን ኪርያላይሶን\nኪርያላይሶን ኪርያላይሶን\n\nአጽናንተኸን ሞትን አስተከዝከው\nወደ ጥልቁ እንዲወርድ አዘዝከው\nበአንተ ፍቅር ምርኮ በዝቶልናል\nማማ ሆነህ ከፍ ከፍ ብለናል\nኪርያላይሶን ኪርያላይሶን\nኪርያላይሶን ኪርያላይሶን\n\nስንሸሽህ እየተከተልከን\nልጆች አርገህ በክብር አስጌጥከን\nተቅበዝባዡን ሰብስበሃልና\nከማደሪያህ ይፈልቃል ምስጋና\nኪርያላይሶን ኪርያላይሶን\nኪርያላይሶን ኪርያላይሶን', 'am', 78, 0),\n(5, 'ወልድን ፍቅር ሳበው', 'ወልድን ፍቅር ሳበው\nወልድን ፍቅር ሳበው ከሰማይ አገሩ\nወልድን ፍቅር ሳበው ከሰማይ አገሩ\nእርሱ ደሃ ሆነ ልጆቹ እንዲከብሩ\nእርሱ ደሃ ሆነ ልጆቹ እንዲከብሩ\n\nየእግዚአብሔር በግ ተገለጠ\nለዘላለም ሞት ተዋጠ\nየእሱን ለእኛ የእኛን ለእርሱ\nክብር ይሁን ለንጉሡ\nየእሱን ለእኛ የእኛን ለእርሱ\nክብር ይሁን ለንጉሡ\n\nጻድቅ ፈራጅ ድንቅ ዳኛ\nክብሩን ጥሎ ግርግም ተኛ\nሳይጎልበት ሆነ ባዶ\nበፍጹም ፍቅር እኛን ወዶ\nበፍጹም ፍቅር እኛን ወዶ\n\nሁለተኛው አዳም መጣ\nየማይጠልቀው ፀሐይ ወጣ\nየዲያብሎስ ስራ ፈርሷል\nመንጋው ሁሉ ጽድቅን ለብሷል\nመንጋው ሁሉ ጽድቅን ለብሷል\n\nስለ ሁሉ አንዱ ሞተ\nእንድንለብስ ተራቆተ\nበከፈለው የደም ዋጋ\nአዲስ ሆንን ባለ ጸጋ\nአዲስ ሆንን ባለ ጸጋ', 'am', 79, 0),\n(5, 'ተስፋ ቆርጠን ነበር', 'ተስፋ ቆርጠን ነበር\nተስፋ ቆርጠን ነበር ኤማሁስ የሄድነው\nበግፍ ስለሞተ ይቤዠናል ያልነው\nስልሳውን ምእራፍ በሓዘን ተራመድን\nየሚያቃጥል ፍቅሩን ሞቱን እያሰብን\nየሚያቃጥል ፍቅሩን ሞቱን እያሰብን\n\nበመንገዳችን ላይ አንድ እንግዳ መጥቶ\nጠየቀን በብርቱ መሃላችን ገብቶ\nዓለም የሰማውን ባያውቀው ደነቀን\nእውነቱን ገለጽነው በእምነት ተናገርን\n\nበስራና በቃል ብርቱ ነብይ ነበር\nበአይሁድ ተገድሎ አደረ መቃብር\nይህ ሁሉ ከሆነ ሶስተኛ ቀን ሆነው\nበምኩራባችን ላይ መምህሩን ካጣነው\n\nዛሬ በማለዳ አዲስ ነገር ሰማን\nበመቃብር የለም ተነስታል ጌታችን\nሴቶች አስገረሙን ስጋው የለም ሲሉ\nመላእክቱም ታዩ ህያው ነው እያሉ\n\nመጻህፍትን ገልጾ በሚነግረን ነገር\nልባችን በሚስጢር ይቀልጥብን ነበር\nአይናችን ተይዞ እኛ መች አወቅነው\nቀኑ መሽታል እና በቤት እደር አልነው\n\nእንጀራውን ቆርሶ በእጃችን ሲሰጠን\nባይናችን ላይ ያለው አዚሙ ለቀቀን\nእንዳላዋቂ ሰው ከኛ ጋራ ያለው\nየትንሳኤው ጌታ ለካስ ኢየሱስ ነው\nየትንሳኤው ጌታ ለካስ ኢየሱስ ነው\nየትንሳኤው ጌታ ለካስ ኢየሱስ ነው', 'am', 80, 0),\n(5, 'እኔስ ብዬ ነበር', 'እኔስ ብዬ ነበር\nእኔስ ብዬ ነበር ተሰጠውኝ ለምት\nእኔስ ብዬ ነበር ተላለፍኩኝ ለምት\nበሚጠሎኝ መሃል የሚወደኝን አገኘውት\nበሚጠሎኝ መሃል የሚወደኝን አገኘውት\n\nወንበዴ ነበርኩኝ በጄ ደም የመላ\nስቀማ ኖርያለው አንገትን ስቀላ\nሞት ይገባኝ ነበረ እንደኔማ በደል\nገነትን ወረስኩኝ አንተ ስትሰቀል\nገነትን ወረስኩኝ አንተ ስትሰቀል\n\nአትጩህ ይሉኛል ስምህን ስጠራ\nአልፈለጉም እና አይኔ እንዲበራ\nጥሩት ስትላቸው ይጠራሃል አሉኝ\nጌታዬ ስትወደኝ ሁሉም አከበሩኝ\nጌታዬ ስትወደኝ ሁሉም አከበሩኝ\n\nአልባስጥሮስ ይዤ የእንባዬን መባ\nስምኦን ከለከለኝ ከቤቱ እንዳልገባ\nእርሱን በይቅርታ በፍቅር እንዳየህ\nተቀበልከኝ ጌታ ሸክሜን አቅልለህ\nተቀበልከኝ ጌታ ሸክሜን አቅልለህ\n\nቸርነት ምህረትህ በዝቷል ይቅርታህ\nለፃድቃን አይደለም ለሀጥአን መጥተህ\nከበጎች መሐል ተለይታ ወጥታ\nአንድዋ እንኳ እንዳትጠፋ ፍቃድህ ነው ጌታ\nአንድዋ እንኳ እንዳትጠፋ ፍቃድህ ነው ጌታ', 'am', 81, 0),\n(5, 'ምሬሀለው በለኝ', 'ምሬሀለው በለኝ\nምሬሀለው በለኝ ስለ ድንግል ማርያም\nምሬሀለው በለኝ ስለ ድንግል ማርያም\nመሀሪው መዳኒአለም ይቅር ባይ እንዳንተ የለም\n\nበሀጥያት ድንኳን ውስጥ ይብቃ መቀመጤ\nየቀናውን መንፋስ አድሰው በውስጤ የምህረት አይኖችህ ይዩኝ በይቅርታ\nስለ ድንግል ማርያም እስራቴን ፍታ\nስለ ድንግል ማርያም እስራቴን ፍታ\n\nቸል በማለቴ የደምህን ዋጋ\nተመልሼ ገባሁ ከጥፋት መንጋጋ\nሰላሜ ደፍርሶ ተቅበዝባዥ ሆኛለው\nስለ እናት ብለህ ማረኝ እልሀለው\nስለ ድንግል ማርያም ማረኝ እልሀለው\n\nበከንቱ መሻቴን ስጋ ነብሴን ቀብሮ\nአቅም አጥቻለው አጥንቴ ተሰብሮ\nከበረዶ ይልቅ ነጭ እንድታደርገኝ\nስለ ድንግል ማርያም ከሀጥያቴ ጠበኝ\nስለ ድንግል ማርያም ከሀጥያቴ ጠበኝ\n\nከንፋሮቼን ከፍተህ ልቁም ለምስጋና\nአንተን የጋረደኝ ጣሪያዬ ይነሳና\nአልብሰኝ ፅድቅህን ይቅር መራቆቴ\nስለድንግል ማርያም መልሰኝ ከቤቴ\nስለድንግል ማርያም መልሰኝ ከቤቴ', 'am', 82, 0),\n(5, 'አድነኝ አምላኬ', 'አድነኝ አምላኬ\nአድነኝ አምላኬ አድነኝ\nአድነኝ ጌታዬ አድነኝ\nአልቋል ከምድር ላይ ደግ ሰው\nእንባዬን ከአይኔ ላይ አብሰው\nእንባዬን ከአይኔ ላይ አብሰው\n\nፍቅር ከሰው ልጆች ቀዝቅዞ\nትዉልዱ በበደል ተይዞ\nወዳጅ በወዳጁ ጨከነ\nወዉደዱ የሽንገላ ሆነ\nወዉደዱ የሽንገላ ሆነ\n\nሆኖበት ክብሩ በነውሩ\nተጣሰ የፍቅር ድንበሩ\nደርቦ የማይሞቀዉ ሆነ\nደስታዉ ከእጁ ላይ ተነነ\nደስታዉ ከእጁ ላይ ተነነ\n\nለቃልህ መታዘዝ ዘነጋ\nተክዞ መሽቶ እየነጋ\nለክፉ አሳልፎ ሰጠ\nወንድሙን በነዋይ ለወጠ\nወንድሙን በነዋይ ለወጠ\n\nትንኝን ያጠራል ከሰው ላይ\nበራሱ ምሶሶዉን ሳያያይ\nይሆናል የወንድሙ ፈራጅ\nተይዞ በእግዚአብሄር እጅ\nተይዞ በእግዚአብሄር እጅ\n\nተሰዶ ሲኖር በባእድ\nሲገባው ሁሉም ሊዋደድ\nአንዱበአንዱ ላይ ይነሳል\nአካሉን ቀኝ እጁን ይንቃል\nወንድሙን እህቱን ይንቃል', 'am', 83, 0),\n(5, 'ብቻዬን ነኝ ብዬ አላውቅም', 'ብቻዬን ነኝ ብዬ አላውቅም\nብቻዬን ነኝ ብዬ አላውቅም\nያመንኩትን እኔ አለቅም\nእግዚአብሔር ነው ጠባቂዬ\nመነሻዬም መድረሻዬ\n\nበማዳኑ ተቀድሼ\nስሙ ሆኗል አዳራሼ\nነብሴ ሌላ አትምረጪ\nህይወት የለም ከርሱ ውጪ\nስላጣሁኝ አይሸሸኝም\nከኔጋር ነው ሳይ ኖረኝም\nየሚያኖረኝ በመንፈሱ\nብሬም እርሱ ወርቄም እርሱ\n\nበእሳት መሐል ሲሆን ጉዞ\nውሃ ሆኖ አቀዝቅዞ\nውሃ መሃል ለወደቀ\nእሳት ሆኖ እያሞቀ\nእጄን ይዞ የሚያሻግር\nማንም የለም እንደ እግዚአብሔር\nእጄን ይዞ የሚያሻግር\nማንም የለም እንደ እግዚአብሔር\n\nመነሻዬ የኔ አልፋ\nኦሜጋዬ የኔ ተስፋ\nከሞት መዳፍ እያስጣለ\nበመንገዴም አብሮኝ አለ\n\nላከበረኝ በዝማሬ\nክብርን ሰጠው በከንፈሬ\nያለወረት ለታመነው\nበዘመኔ እገዛለው\nማይቋረጥ ውዳሴ አለኝ\nከእስትንፋሴ ለቀረበኝ\nእጅን ይዞ የሚያሻግር\nማንም የለም እንደ እግዚአብሔር', 'am', 84, 0),\n(5, 'የመልካሞች መልካም', 'የመልካሞች መልካም\nየመልካሞች መልካም ካህን ለዘላለም\nበልቤ ላይ ንገስ የናዝሬቱ ኢየሱስ\n\nሴኬምን እንዳልናፍቅ ከህግህ እንዳልወጣ\nከፀጋ እንዳልጎድል ብኩርናን እንዳላጣ\nበፍቅር ንገስብኝ በልቤ ሾሜሃለው\nተማምኜ በስምህ ወጣለው እገባለው\n\nደምህን አፍስሰሃል ስለሃጢአቴ ስርየት\nስጋህንም ቆርሰሃል ለነፍሴ አርነት\nአንተ ነህ ሊቀካህን መስዋዕቱን የሰዋህ\nመስዋዕቱንም ተቀበልክ መስዋዕትም ሆነህ\n\nበህግህ እንድፀና ለልቤ ጥበብ ሁነው\nበሰላም እንዲቀና እግሬን በብርሃን ምራው\nካንተ የተቀበልኩትን ልስጥህ በልግስና\nትከለኝ በመቅደስህ እንድኖር በትህትና\n\nከቤተልሄም ግርግም ቀራንዮ ያየውህ\nፍቅርን ያነበብኩብህ የልብ ወዳጄኮ ነህ\nበለምለም የመራኸኝ በፅድቅ ያስማረከኝ\nመልካሙ እረኛዬ ሆይ ከተኩላው የከለልከኝ', 'am', 85, 0),\n(5, 'ኢትዮጵያ እጅሽን ዘርጊ', 'ኢትዮጵያ እጅሽን ዘርጊ\nኢትዮጵያ እጅሽን ዘርጊ ወደ አምላክ ወደ አዶናይ\nህዝብሽን ከሞት የሚያድን ይዉጣልሽ የምህረት ፀሐይ\n\nህጻናት ወላጆች አጥተው በሜዳ ሲበታተኑ\nንስሮችሽ ወጣቶች አልቀው የአፈር ሲሳይ ሲሆኑ\nየሞት መልአክ ተልኮብሽ መሬትሽ አጥታ ፀጥታ\nቁጣዉን እንዲመልሰው ለምኚ ለሰማይ ጌታ\n\nታማሚው እያጣጣረ ጤነኛው ቆሞ ሲሰጋ\nአምላክሽ ይቅር ይበልሽ ይለፍሽ ይሄ መከራ\nአበዉን ይዘሽ ተነሺ ጸሎትሽን ቆመሽ አድርሺ\nያብርደው እሳት ንዳዱን በምልጃሽ በልመናሽ\n\nልጆችሽ ቅጣት ገብቷቸው እንዲያዩ ወደ አምላካቸው\nመከራው ትምህርት ሆኗቸው ይመለስ ታካች ልባቸው\nየበደልነውን ታግሶ ቁጣውን እርሱ መልሶ\nይማረን ይቅር ይበለን ጽኑ ምህረቱን አስታውሶ\n\nአህዛብ ተነጋገሩ አምላክሽ እረሳሽ ብለው\nልጆችሽ ሞት ሲፈጃቸው እያዩ እጅግ ተገርመው\nጉልበትሽ እንዳይሰበር ምርኩዝሽ እርሱ ነውና\nደዌ ቸነፈሩን ያርቅ አቅርቢ ፅኑ ልመና', 'am', 86, 0),\n(5, 'በፍቅር ላዚምህ', 'በፍቅር ላዚምህ\nበፍቅር ላዚምህ ፍቅር ነህ ጌታዬ\nበደም የገዛሀኝ ባለውለታዬ\nበቃዬል ጎዳና እንዳልጓዝ እርዳኝ\nበቀናው መንፈስህ ወደፅድቅህ ምራኝ\n\nበልቤ ትከሻ በቀል ተሸክሜ\nወንድሜን ጠልቼ ካንተ ፊት መቆሜ\nፃድቅ ቢያስመስለኝ በሰዎች እይታ\nጉዴን ስለምታውቅ እስራቴን ፍታ\nጉዴን ስለምታውቅ እስራቴን ፍታ\n\nዙሪያውን ተከቦ በእሾህ ጥላቻ\nስብከቴ መዝሙሬ ሆኗል የቃል ብቻ\nማረኝና ይብቃኝ ለሀጢአት መዝመቱ\nፍቅር የሌለው ሰው ነው የከንቱ ከንቱ\nፍቅር የሌለው ሰው ነው የከንቱ ከንቱ\n\nአሸንፈህልኝ እኔ ግን ተሸነፍኩ\nበጅ የማልነካውን ለሰው እያሸከምኩ\nበቃሌ ጠርቼ በግብሬ ረገምኩህ\nባስመሳይ ማንነት እየሸነገልኩህ\nባስመሳይ ማንነት እየሸነገልኩህ\n\nዙሪያዉን ተከቦ በእሾህ ጥላቻ\nስብከቴ መዝሙሬ ሆኗል የቃል ብቻ\nማረኝና ይብቃኝ ለሀጢያ መዝመቱ\nፍቅር የሌለው ሰው ነው የከንቱ ከንቱ\nፍቅር የሌለው ሰው ነው የከንቱ ከንቱ', 'am', 87, 0),\n(5, 'ያለሽ ልዩ ፀጋ', 'ያለሽ ልዩ ፀጋ\nያለሽ ልዩ ፀጋ ያለሽ ልዪ ክብር\nየሁሉ እመቤት በሰማይ በምድር\nአኩራሪተ መዐልት ምራገ ፀሎት\nሲነግሩሽ ሰሚነሽ ኪዳነምህረት\n\nበመከራ ላለው ሁኝለት መፅናኛ\nዕንባውን አብሺው አይዘን ዳግመኛ\nጉድለቱን ሙይለት በፈረሰው ቆመሽ\nስለምታስምሪ በልዩ ኪዳንሽ\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው\nእናቴ የሚልሽ አምላክሽ ልጅሽ ነው\n\nይበጠሰ ከእጁ የወህኒው ሰንሰለት\nየሞቱ ደብዳቤ ይቀየር በህይወት\nአዲስ ተስፋ ሞልተሽ አዲስ ሰው አድርጊው\nመቅበዝበዙ ይርሳ ድንግል አረጋጊው\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው\nእናቴ የሚልሽ አምላክሽ ልጅሽ ነው\n\nበዕንባ የመጣው ይመለስ በደስታ\nመጠማቱ ይቅር ይሞላ በእርካታ\nስለቱ ሰምሮለት ይቁም ለምስጋና\nየአብራኩን ክፋይ አሳቅፊውና\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው\nእናቴ የሚልሽ አምላክሽ ልጅሽ ነው\n\nተይዞ ለሚኖር በአልጋ ቁራኛ\nአንቺው እመቤቴ የዴውም ዳኛ\nመንገርስ ላንቺ ነው መማፀን ወዳንቺ\nተስፋን ለምትቀጥይ ህልምን ለምትፈቺ\nከኪዳንም በላይ ኪዳንሽ ልዩ ነው\nእናቴ የሚልሽ አምላክሽ ልጅሽ ነው', 'am', 88, 0),\n(5, 'የተሰቀለውን ኢየሱስን ሳየው', 'የተሰቀለውን ኢየሱስን ሳየው\nየተሰቀለውን ኢየሱስን ሳየው\nጎኑን የተዋጋው ክርስቶስን ሳየው\nሀሞት የጠጣውን መድኃኒቴን ሳየው\nአንድ ነገር ገባኝ ይህ ሁሉ ለኔ ነው\nአንድ ነገር ገባኝ ይህ ሁሉ ለኔ ነው\n\nየሚነጠፉለት መላእክት በፊቱ\nምስጋናው አይጎድልም በቀንም በሌሊት\nሁሉ በመዳፉ አልፋና ኦሜጋ\nመጣ ወደ ምድር እኔኑ ፈለጋ\n\nሰለእኔ ተቆጥሮ እንደተረገመ\nጤናዬን ሊመልስ ቤዛዬ ታመመ\nለዛሬ ደስታዬ ለዛሬ መቆሜ\nሕይወት ከፍሎብታል ኢየሱስ ሰላሜ\n\nበጅራፍ ግርፍት ጀርባው የታረሰው\nስጋዬን ሊያቆም ነው ደሙ የፈሰሰው\nፍቅር የሳበችው ሰለፍቅር ብሎ\nአክሊል አቀናጀኝ ምራቅ ተቀብሎ\n\nያጠፉሁት እኔ ተከሳሹ እርሱ\nብርሃን ሊያለብሰኝ ተገፈፈ ልብሱ\nወገን እንደሌለው የሆነው ባይተዋር\nእኔ ሊደምር ነው የእርሱን ከሆኑት ጋር\n\nግልጽና ስውሩን ሁሉን አዋቂ ነው\nቢዘብቱበትም አይኑን በጨርቅ አስረው\nበመንፈስ ደኸየ የባሪያን መልክ ያዘ\nማዕረጌን ሊመልስ ለመስቀል ታዘዘ\n\nአብ አንድያ ልጁን ሰጥቶኛል ሳይራራ\nወልድ ሊታደገኝ ሆኗል ከእኔ ጋራ\nበመከራም ሆኖ ጌታን ያሳሰበው\nየእርሱ ስቃይ ሳይሆን የእኔ እረፍት ነው', 'am', 89, 0),\n(5, 'ፍቅርን ከክርስቶስ', 'ፍቅርን ከክርስቶስ\nፍቅርን ከክርስቶስ ትህትናን ከማርያም\nያልተማረ አገልጋይ አይሆንም ምሳሌ\nይውረድ ከአትሮኖስ ላይ\nይውረድ ከአትሮኖስ ላይ\n\nስለሚያሳድዱት በርሱ ላልጸለየ\nበምንስ ተለየ\nየሚናገረውን በተግባር ካልኖረ\nምኑን አስተማረ\n\nየሚያምነውን ጌታ በህይወት ካልገለጠ\nመቼ ተመረጠ\nእየተበደለ ካላለ ይቅርታ\nአያውቀውም ጌታ\n\nልቡ ሳይሰበር ወንጌሉን ቢዘራ\nአንዳች አያፈራ\nከኔ ይልቅ ወንድሜ ካላለ ብርቱ ነው\nድካሙ ከንቱ ነው\n\nክፉን ተጠይፎ ካልቆመ ለእውነት\nስብከቱ ነው ሐሰት\nብርሃንን ሰብኮ በጨለማ ካለ\nራሱን አታለለ\n\nእርስ በርሷ መንግስት ከተከፋፈለች\nመቼ ትጸናለች\nአባቶች ታረቁ ብኩራናን ትታችሁ\nአንድ ይሁን መንጋችሁ\n\nበጸጋው ስጦታ ራሱን ከካበ\nየጌታው ባርያው ነኝ ብሎ ካላሰበ\nአምላክን ጸንሳ ጌታን የወለደች\nለፍፁም ትህትና ማርያም ምሳሌ ነች', 'am', 90, 0),\n(5, 'ፍቅሯ የበዛለት', 'ፍቅሯ የበዛለት\nፍቅሯ የበዛለት ለክብሯ ይቆማል\nፍቅሯ የበዛለት ለክብሯ ይቆማል\nውድስት አንቲ እያለ ይዘምራላታን\nውድስት አንቲ እያለ ይዘምራላታን\n\nበመንፍስ ቅዱስ ሀይል እንደ ቅድስት ሀና\nእቀኝልሻለሁ በያሬድ ምስጋና\nበስጋሽ ድንግል ነሽ ድንግል በህሊና\nእሳቱን የወሰንሽ እጸ ደብር ሲና\n\nፍቅሯ የበዛለት ያመሰግናታል\nፍቅሯ የበዛለት ለክብሯ ይቆማል\nውድስት አንቲ እያለ ይዘምራላታን\nውድስት አንቲ እያለ ይዘምራላታን\n\nየሰላምታ ቃልሽ ይፍሰስ በጆሮየ\nጽናት ሀይል ሁኖኛል ድምጽሽ ለኑሮየ\nየመንፈስ ቅዱስ ጣት ካልቃኘው ደጋግሞ\nማንስ ይቻለዋል ሊወድስሽ ቁሞ\n\nፍቅሯ የበዛለት ያመሰግናታል\nፍቅሯ የበዛለት ያመሰግናታል\nውድስት አንቲ እያለ ይዘምራላታን\nውድስት አንቲ እያለ ይዘምራላታን\n\nጓዳየን ጎብኝልኝ የወይኑን ማድጋ\nአንች ታውቂውያለሽ ችግሬን በጸጋ\nቀና ብየ ልሂድ ይብቃ ማጎንበሴ\nሰአሊ ለነ ቅድስት በቅድመ ስላሴ\n\nፍቅሯ የበዛለት ለክብሯ ይቆማል\nፍቅሯ የበዛለት ያመሰግናታል\nውድስት አንቲ እያለ ይዘምራላታን\nውድስት አንቲ እያለ ይዘምራላታን\n\nየሰላምታ ቃልሽ ይፍሰስ በጆሮየ\nጽናት ሀይል ሁኖኛል ድምጽሽ ለኑሮየ\nየመንፈስ ቅዱስ ጣት ካልቃኘው ደጋግሞ\nማንስ ይቻለዋል ሊወድስሽ ቁሞ', 'am', 91, 0),\n(5, 'ተግተን እንጸልይ', 'ተግተን እንጸልይ\nተግተን እንጸልይ ወደ ፈተና እንዳንገባ\nበሕይወታችን በመንደራችን እግዚአብሔር ይግባ\nበአባታችን ፊት በጸሎት ወድቀን ኃይል እንታጠቅ\nበጸጋ እንድንኖር የሚቃወመን ጠላትም ይድቀቅ\n\nበጦር ሰፈር ነን ያ ጠላታችን ሌጌዎን ታጥቋል\nመሳሪያ ሳንይዝ የወጣነውን ስንቶቹን ጥሏል\nዘይት አልቆብን የመቅረዛችን መብራት ደብዝዟል\nብርሃኑን ጥለን የጠላት ምሽግ በምን ይታያል\nተንስኡ ለጸሎት\n\nያዘነብላል ጆሮውን ወደኛ ጠላት ይመታል\nወጥመዱን ሰብሮ ያመንንበትን ያሻግረናል\nያሰማራናል በለምለሙ መስክ በተስፋ ሞልቶ\nማን አፍሮ ያውቃል የእግዚአብሔርን ስሙንስ ጠርቶ\nተንስኡ ለጸሎት\n\nየክብር ዘይት በቆሰለው ሰው ቀድተው ቢያፈሱት\nመድኃኒት ነው ለዓለም ኹሉ ዲናር ማይከፍሉት\nየፍቅር አባት ደጁን ስንመታ ይከፍትልናል\nመሻታችንን እየፈጸመ ይባርከናል\nተንስኡ ለጸሎት', 'am', 92, 0),\n(5, 'ድንጋይ ጣሉ', 'ድንጋይ ጣሉ\nድንጋይ ጣሉ ሰይፍን ጣሉ\nበፍቅር ቃል ሰላም በሉ\nኢትዮጵያዊ የሚያምርበት\nይቅር ሲል ነው የሚያምርበት\n\nዘር አጥንትን የማይቆጥር\nየሚኖር ነው ሁሌም በፍቅር\nየሚሰጥ ነው የሱን ትቶ\nለወገኖቹ አድልቶ\nወሰን ድንበር ማይገድበው\nኢትዮጵያዊ ማለት ይህ ነው\n\nየሚያዝን ነው ከሚያዝነውጋር\nደስ የሚለው ደስ ካለውጋር\nእግዚአብሔር የሚፈራ\nየምህረት ሰዉ የሚራራ\nወሰን ድንበር ማይከልለው\nኢትዮጵያዊ ማለት ይህ ነው\n\nየሚያበላ ካለው ቆርሶ\nካለቀሰው አብሮ አልቅሶ\nእርሱ መልኩን አይቀይርም\nካገር በፊት ቅድሚያ አይሰጥም\nወሰን ድንበር ማያግደው\nኢትዮጵያዊ ማለት ይህ ነው\n\nየሚቀበል ሁሌ እንግዳ\nሚያመሰግን በማለዳ\nየሚያምን ነው በአንድነት\nየማይከፋው በልዩነት\nወሰን ድንበር ማይከልለው\nኢትዮጵያዊ ማለት ይህ ነው\n\nሰይፍን መዘን የለም ሠላም\nየቃየል ግብር አይጠቅመንም\nባንድ ማህፀን ይቁም ግፊያ\nበርብቃ ምድር በኢትዮጵያ\nወሰን ድንበር ማይገድበው\nኢትዮጵያዊ ማለት ይህ ነው', 'am', 93, 0),\n(5, 'እግዚአብሔር መልካም ነው', 'እግዚአብሔር መልካም ነው\nእግዚአብሔር መልካም ነው\nበመከራ ቀንም መሸሽጊያ ነው\nእግዚአብሔር መልካም ነው\nበመከራ ቀንም መሸሽጊያ ነው\n\nከገነት ሲሰደድ አዳም አባታችን\nሞት ነግሦብን ሳለ በእኛ በሁላችን\nቃል እንደገባለት ተወልዶ ሊያድነው\nበመከራ ጊዜ መሸሸጊያ ሆነው\nበመከራ ጊዜ መሸሸጊያ ሆነው\n\nአብርሃም ከካራን ከእናት ከአባቱ ቤት\nከነዓን ሲገባ ሲሰደድ በእምነት\nከተሰጠው ተስፋ አንዳች ሳይጎድልበት\nእንደ ምድር አሸዋ ዘሩን አበዛለት\nእንደ ምድር አሸዋ ዘሩን አበዛለት\n\nበሃዘን በችግር በመከራ ጊዜ\nጭንቅን የሚያርቅ ነው የነፍስን ትካዜ\nየቀድመው እባብ ሰላሜን ሲነሳኝ\nእግዚአብሔር መልካም ነው ሃዘኔን አስረሳኝ\nየቀደመው እባብ ሰላሜን ሲነሳኝ\nከርስቶስ ኢየሱስ ሀዘኔን አስረሳኝ', 'am', 94, 0),\n(5, 'ቀራኒዮ አየሁት', 'ቀራኒዮ አየሁት\nቀራንዮ አየሁት ቀራንዮ አየሁት\nየተጠማሁት ጌታን አገኘሁት\nእረፍት ሆኖልኛል ሸክሜን ተሸክሞ\nሕይወቱን በሰጠኝ የኔን ሕይወት ታሞ\nቁስሉ ፈውሶኝ ጌታዬ\nንጹህ ደሙ ነው ዋጋዬ\nየኔ አይደለሁም የራሴ\nለዋጀኝ አለኝ ውዳሴ\n\nልብሴ ነው ለኔ እርቃኑ\nደስታን የሰጠኝ ማዳኑ\nየኔን መሰደድ ተሰዶ\nበክብር አስጌጠኝ ተዋርዶ\n\nየተቀበለው መከራ\nየኔን ጨለማ አበራ\nእንባየን ገድቦት ደሙ\nበልቤ ሞልቷል ሰላሙ\n\nፍቅር ያደከመው ኃይለኛ\nይጠብቀኛል ሳይተኛ\nቀድሞ እየወጣ በሰልፌ\nዛሬም አለሁኝ አትርፌ\n\nበምድረ በዳ መንጭቶ\nውሃ ሆነልኝ ተጠምቶ\nስፍራ አዘጋጄ በሰማይ\nጩኸቴን ጨኸ መስቀል ላይ\n\nሰርጓጉት ሸለቆ ሞልቷል\nአጥፊውም ሳይነካኝ አልፏል\nቀራንዮ ላይ ብቃቴን\nአግኝቸዋለሁ ንጋቴን', 'am', 95, 0),\n(5, 'ሰው ከነድካሙ ይጠቅማል', 'ሰው ከነድካሙ ይጠቅማል\nሰው ከነድካሙ ይጠቅማል\nሰው ከነድካሙ ይጠቅማል\nበከበርው ደሙ በዋጋ ተግዝቷል\nበእግዚአብሔር ምህረት በፍቅር ተከቧል\nሰው ከነድካሙ ይጠቅማል\nሰው ከነድካሙ ይጠቅማል\nበከበርው ደሙ በዋጋ ተግዝቷል\nየበረቱትን ሲያይ ቢወድቅም ይነሳል\nሰው ከነድካሙ ይጠቅማል\n\nከሰፌው አዳራሽ ከአባቱ ኮብልሎ\nከወንድሙ ጋራ ድርሻውን ተካፍሎ\nአንድ ቀን ሲመለስ ወደ ልቦናው\nመሆንን ይመኛል አገልጋይ ባሪያው\nየሀሙስ ማታውን ቃሉን እረሳና\nአላውቀውም ቢለው ዶሮ ሳይጮህ ገና\nበለቅሶ ቢማጽን መበደሉ ገብቶት\nሰማዕትም ሆነ ደረሰ እስከሞት\n\nንጉሱ ሲያጠፋ ፈርቶ ለመገሰጽ\nኢሳያስ ወጣበት በከንፈሩ ላይ ለምጽ\nከንፈሩን ቢነካው መላእክ በጉጠቱ\nለምጡም ተወገደ በዛለት ትንቢቱ\n\nዛሬ ደግ ይሆናል ትናንት የጨከነው\nከእግሩ ስር ይወድቃል ለጊዜው ያመጸው\nዳዊት በአምላኩ ፊት ንስሃ ቢገባ\nተባለ እንደልቤ ባፈሰሰው እንባ', 'am', 96, 0),\n(5, 'እግዚአብሔር ትዝታዬ ነው', 'እግዚአብሔር ትዝታዬ ነው\nእግዚአብሔር ትዝታዬ ነው በልቤ ያኖርኩት\nእኖራለሁ በዘመኔ እየተደገፍኩት\nእወጣለሁ ከመከራ ስሙን ተሸክሜ\nጉልበት ይሆነኛል አልቀረም ደክሜ\n\nየማልረሳውን ቃል አኑሯል በልቤ\nአላፈረም ፊቴ ህጉን በማሰቤ\nየጽድቅን እስትንፋስ ዘርቷል በህይወቴ\nየክብሬ ምስጢር ነው የአገልጋይነቴ\nየክብሬ ምስጢር ነው የአገልጋይነቴ\n\nትላንት የሚወዱኝ ዛሬ ጠልተውኛል\nእርሱ ግን በፍቅሩ ይከታተለኛል\nበጉያው ሸሽጎ አኖረኝ በክብር\nሳወራው እኖራለሁ ፍቅሩን ስዘረዝር\nሳወራው እኖራለሁ ፍቅሩን ስዘረዝር\n\nእንዴት እንዳነሳኝ አስታውሰዋለሁ\nያደረገልኝን መች እረሳዋለሁ\nበዝማሬ ሞልቶ ያበቃኝታ ለእልልታ\nእርሱ ነው ጌታዬ የውስጤ ትዝታ\nእርሱ ነው ጌታዬ የውስጤ ትዝታ\n\nሃዘን ከከበበው ከድቅድቅ ጨለማ\nመቼ ተሻገርኩኝ እያሪኮንማ\nሳምራዊው ደገኛ በዘይት ያከመኝ\nአስታውሰዋለሁ በአህያውን ሲጭነኝ\nአስታውሰዋለሁ በአህያውን ሲጭነኝ', 'am', 97, 0),\n(5, 'መሠረቷ ጉልላቷ እርሱ ነው', 'መሠረቷ ጉልላቷ እርሱ ነው\nመሠረቷ ጉልላቷ እርሱ ነው\nሙሽራዋ መስቀል ላይ የምተው\nዛሬም ነገም ህያው ነው ለዘላለም\nአትንገሩን አዲስ ጌታ የለም\nአትንገሩን አዲስ ጌታ የለም\n\nየእንግዳው ትምርት የጠላት እንክርዳድ\nበመከሩ ጊዜ ይለያል ሲታጨድ\nጌታ ጌታ ያለው እንዲሁ በብልጠት\nአይወርስም ፈፅሞ የሰማዩን እርስት\nአይወርስም ፈፅሞ የሰማዩን እርስት\n\nእራስ ለሆነላት ሆናለች አካሉ\nትታዘዘዋለች ዘወትር ለቃሉ\nየፊት መጨማደድ ሣያገኛት ድካም\nታምና ትኖራለች እስኪመጣ ዳግም\nታምና ትኖራለች እስኪመጣ ዳግም\n\nየሠማይታቱ ደም የከፈሉት ዋጋ\nየመላክቱ ዜማ የሰማዩ ፀጋ\nየሀዋርያት ስብከት የነብያት ትንቢት\nይገኛል በውስጧ በፀጋው ግምጃ ቤት\nይገኛል በውስጧ በፀጋው ግምጃ ቤት\n\nጎዳናውን ጥሰን ብንጋዝ በ ሀሰት\nለ አንደበታችን አውጀን አርነት\nአይዘጋም ደጇ አይጠፋም መብራቷ\nኢየሱስ ነው ክብሯ ጌጥና ውበቷ\nኢየሱስ ነው ክብሯ ጌጥና ውበቷ', 'am', 98, 0),\n(5, 'ትዝ አለኝ በላይሰብ', 'ትዝ አለኝ በላይሰብ\nትዝ አለኝ በላይሰብ ሰምቼ ታምርሽን\nድንግል እሰጣለሁ ለጠራ ስምሽን\nእመጸውታለሁ ለጠራ ስምሽን\n\nከሰው ተገለለ ብዙ ነፍስ አጥፍቶ\nበምልጃሽ ተማረ ጥርኝ ውኃ ሰቶ\nስምሽ ጉልበት አለው ጨካኙን ያራራል\nስለ እማምላክ ብሎ ድኃው ጠግቦ ያድራል\nስለ እማምላክ ብሎ ድኃው ጠግቦ ያድራል\n\nለሲኦል የታጨች ነፍሱ ለፍርድ ቆማ\nበላይሰብ ዳነ አንች ሆንሽው ግርማ\nይህን ያላወቁ ክብርሽን የናቁ\nይስገዱ ለስምሽ ከእግርሽ ስር ይውደቁ\nይስገዱ ለስምሽ ከእግርሽ ስር ይውደቁ\n\nየንጉስ ከተማ አምላክ የኖረብሽ\nነፍሴ ትጠግባለች ማርያም ማርያም ስልሽ\nስምሽ አያሳፍር አንገት አያስደፋ\nአንችን ለሸለመኝ አምላክ ክብሩ ይስፋ\nአንችን ለሸለመኝ አምላክ ክብሩ ይስፋ\n\nአልጠራጠርም ምልጃሽ ይረዳኛል\nካቀረቀርኩበት ቀና ያደርገኛል\nአምላክን ያቀፉ ብሩካን እጆችሽ\nእኔንም ይዳብሱኝ ቆሜያለሁ ከደጂሽ\nእኔንም ይዳብሱኝ ቆሜያለሁ ከደጂሽ', 'am', 99, 0),\n(5, 'ይህ አይገባትም', 'ይህ አይገባትም\nይህ አይገባትም አገር ለሰራችው\nይህ አይገባትም አገር ላቆመችው\nድምጿን ስትቀንስ ዝም ያለች መስሏችሁ\nድምጿን ስትቀንስ ዝም ያለች መስሏችሁ\nየነኳት አልፈዋል እርሷ ግን ፀንታለች\nይህንን አልፋ ገና ትኖራለች\nይህ አይገባትም አገር ለሰራችው አገር ላቆመችው\n\nከአምላክ ተምራ ብዙ ብትታገስ\nጽኑ ናት ኦርቶዶክስ ዘላለም የማትፈርስ\nየማታውቁ እንደሆን መዝገቧን ግለጡ\nመቻል ልማዷ ነው በዓይኗ ግን አትምጡ\n\nአርዮስ እስጥሮስ መች አነቃነቋት\nግራኝ እና ዮዲት መች ቻሉ ሊያጠፏት\nስድባችሁን ችላ ብትመርቃችሁ\nበመንገዷ ላይ ግን አትቁሙ ገብታችሁ\n\nወደኃላ አታይም እርፍን ጨብጣለች\nበስጋ ደም ጥበብ መቼ ትመካለች\nከእርሷ ላይ ውረዱ እጃችሁን አንሱ\nእሳት ለማጥፋት እሳት አትለኩሱ\n\nነፍስን የሚታደግ ጉዞዋ ረጅም ነው\nከምድር ተጀምሮ ሰማይ ነው የሚያልቀው\nስለማትችሉ ይህን ልታስቆሙ\nተዋሕዶን ለማጥፋት በብዙ አትድከሙ', 'am', 100, 0),\n(5, 'የሐሰት ዳኝነት', 'የሐሰት ዳኝነት\nእውነት ስለሆነ እየሱስ ክርስቶስ\nዋለ በአደባባይ ሲሰደብ ሲከሰስ\nየሐሰት ዳኝነት አምላክ ወቀሰው\nሕይወት ሰጠን እንጂ ጥፋቱ ምድነው\n\nከቃሉ ህብሌትም ባያገኙለትም\nዝምታውን አይተው አላዘኑለትም\nባላወቁት መጠን ጠሉት ያለበደል\nጥፋቱ ምን ይሁን የሚያደርስ\nእስከመስቀል\n\nየልቡ ትህትና ፍቅሩን ሳያስተውሉ\nቸሩ ጌታችንን አቻኩለው ሰቀሉት\nእሩሩሁን ጌታ አቻኩለው ገደሉት\nሞትን አስወግዶ ቢሰጣቸው ሕይወት\n\nስለ ቸርነቱ ስድብን ከፈሉት\nስለ እርህራው የሾህ አክሊል ሰጡት\nሃሞት እና ከርቤ ቆምጣጤ ደባቀው\nመራራ አስግነጩት ቸክኖ ልባቸው\n\nሐሰት በሰጣቸው ልባቸውን ሞልተው\nላሉት ወንበዴ ነው ስቀለው ስቀለው\nእጀ በረከትን የተሻሙ ሁሉ\nይጮሁ ነበር ይሰቀል እያሉ', 'am', 101, 0),\n(5, 'አምስቱ ሃዘናት', 'አምስቱ ሃዘናት\nአዘነች ድንግል አለቀሰች ፍጹም አምርራ\nበአንድ ልጇ ምክንያት ደርሶባት መከራ\nበአንድ ልጇ ምክንያት ደርሶባት መከራ\n\nበመንጻቱ ወር በዓርባኛው ቀን\nሥምዖን አረጋዊ ታቀፈ እና ጌታን\nትንቢት ተናገረ ተገልጾለት ሞቱ\nበነፍስሽ ሠይፍ ያልፋል አንቺም እናቲቱ\nይኽንን መከራ ሲሠማ ጆሮዋ\nአምርራ አለቀሰች አልቆም አለ ዕንባዋ\n\nበአሥራ ሁለት ዓመቱ ለማክበር በዓል\nበኢየሩሳሌም ቢገኝ አማኑኤል\nሲጠይቅ ሲሠማ በቤተ መቅደሱ\nየኦሪት ካህናት ሲደነቁ በእርሱ\nእስከ ሦስት ቀን ድረስ ብትልጣው ፈልጋ\nልቧ ተገፈ በሐዘን አለንጋ\n\nጠዋት በማለዳ በጲላጦስ ደጅ\nሲጸናበት አይታ የጨካኞች እጅ\nርቃኑን አድርገው ያለ አንዳች ጥፋት\nከግንድ ጋር አስረው ጀርባውን ሲገርፉት\nእንዴትስ አታለቅስ እንዴት አታነባ\nሲገርፉት ሲያዳፉት ልጇን እንደ ሌባ\n\nየዓለሙን ፈጣሪ የዓለሙን ዳኛ\nንጹሑን ጌታ መሥሏቸው ቀማኛ\nእጁን እና እግሮቹን በችንካр ወጥረው\nበወንበዴ መሐል ሠቅለውት ብታየው\nድንግል አለቀሰች አልቻለች መጽናናት\nዕንባዋ ወረደ እንደ ክረምት ጅረት\n\nዮሴፍ ኒቆዲሞስ በአንድ ሲማከሩ\nቅዱስ ኃያል ብለድ ገንዘው ሊቀብሩ\nበአዲስ መቃብር በአሥራ አንደኛው ሠዓት\nሥጋውን አኑረው በድንጋይ ቢዘጉት\nእያለች አነባች አንድ ልጄ እኮ ነው\nከእርሱ የሚቀድም ተከታይ የሌለው', 'am', 102, 0),\n(5, 'ዘጠኝ ሰዐት ሲሆን', 'ዘጠኝ ሰዐት ሲሆን\nዘጠኝ ሰዓት ሲሆን አባት ሆይ\nበመስቀል ሆነህ አባት ሆይ\nድምፅህን በማሰማት አባት ሆይ\nነፍስህን ሰጠህ አባት ሆይ\n\nከዋክብተ ሰማይበሙሉ ረገፉ\nጨረቃና ፀሐይ ደምን አጎረፉ\nብርሃናት ጨለሙ ጠፍተው ተለያዩ\nሥጋህ በመስቀል ላይ ተጋልጦ ስላዩ\n\nጌታችን ክርስቶስ በመስቀል ላይ ሳለ\nአሰምቶ ጮኸ ተጠማሁ እያለ\nማርና ወተትን ለሚመግበው\nሐሞት አመጡለት ይቅመሰው ብለው\n\nአካሉ ሲወጋ ውኃ ደም ፈሰሰ\nበምድር ተረጭቶ ዓለምን ቀደሰ\nየገሊላ ሴቶች ዋይ ዋይ ሲሉልህ\nለእነርሱ አሰብክ እንጂ ላንተስ አላሰብክ\n\nእናቱ ስታለቅስ በመስቀል ሥር ሆና\nዮሐንስን ሰጣት ጠብቆ አንዲያጽናና\nመላእክትም ታዩ አጋንንትም ሸሹ\nየአይሁድ ሠራዊት ፈርተው ተረበሹ', 'am', 103, 0),\n(5, 'እኔስ በምግባሬ', 'እኔስ በምግባሬ\nእኔስ በምግባሬ ደካማ ሁኛለሁ\nእኔስ በምግባሬ ደካማ ሁኛለሁ\nእዘኝልኝ ድንግል እለምንሻለሁ\nእዘኝልኝ ድንግል እለምንሻለሁ\n\nያንን የእሳት ባሕር እንዳላይ አደራ\nድረሽልኝ ድንግል ስምሽን ስጠራ\nድረሽልኝ ድንግል ስምሽን ስጠራ\n\nየዳዊት መሰንቆ የኤልያስ መና\nየናሆም መድሃኒት ንዒበደመና\nየናሆም መድሃኒት ንዒበደመና\n\nአንቺ ነሽ ጉልበቴ በደከመኝ ጊዜ\nየልቤ መጽናኛ እረዳት ምርኩዜ\nየልቤ መጽናኛ እረዳት ምርኩዜ\n\nአፈሳለሁ እምባ በጣም ተጨንቄ\nእማጽንሻለሁ በደሌን አውቄ\nእማጽንሻለሁ በደሌን አውቄ', 'am', 104, 0),\n(5, 'የልቤን በልቤ ይዤ', 'የልቤን በልቤ ይዤ\nየልቤን በልቤ ይዤ ከፊትሽ ቆሜ አለው\nየሆዴን በሆዴ ይዤ ከፊትሽ ቆሜ አለው\nካለኝ ነገር ሁሉ አንቺን መርጫለሁ\nእናቴ ሆይ ስሚኝ አማልጅኝ እላለሁ\nእናቴ ሆይ ስሚኝ አማልጅኝ እላለሁ\n\nግራኝ ቀኝ ህይወቴ በሾህ ታጥሮብኛል\nበፊት በኋላዬ መሰናክል በዝቷል\nእኔስ ያለ ምርኩዝ ጉዞዬ ከብዶኛል\nእመ አምላክ ደግፊኝ እጄ ተዘርግቷል\nእመ አምላክ ደግፊኝ እጄ ተዘርግቷል\n\nቆሜ ስራመድ ጤነኛ እመስላለሁ\nየውስጤን ጎዶሎ እኔ አውቃለሁ\nድንግል ሆይ ቅረቢኝ አይዞህ ልጄ በይኝ\nየጭንቀቴን ካባ አውልቀሽ ጣይልኝ\nየጭንቀቴን ካባ አውልቀሽ ጣይልኝ\n\nእናት ያለው ሰው ፍጹም አይተክዝም\nአንድ ቀን ይስቃል አልቅሶም አይቀርም\nሀዘኔን በደስታ ለውጪው እናቴ\nበሀሴት ልዘምር በቀረው ሕይወቴ\nበደስታ ልዘምር በቀረው ሕይወቴ\n\nአሁን ጎዶሎ በውስጤ አለና\nድንግል ሆይ ቅረቢኝ ዛሬም እንደገና\nለዚች ለትንሿ ለጥቂቷ እድሜ\nእንደከፋኝ አልኑር ቀና አርጊኝ እናቴ\nእንደከፋኝ አልኑር ቀና አርጊኝ እናቴ', 'am', 105, 0),\n(5, 'እመቤቴ ማርያም', 'እመቤቴ ማርያም\nእመቤቴ ማርያም እለምንሻለሁ\nበለቅሶ በዋይታ ፊትሽ ወድቂያለሁ\nእመቤቴ ስሚኝ ተማጽኜሻለሁ\nእመቤቴ ስሚኝ ተማጽኜሻለሁ\n\nሀዘኔን ጭንቀቴን ለማን እነግራለሁ\nችግሬን ጉዳቴን ለማን አዋያለሁ\nእመቤቴ ስሚኝ ተማጽኜሻለሁ\nእመቤቴ ስሚኝ ተማጽኜሻለሁ\n\nሀዘኑ በዛብኝ መከራው ከበደኝ\nእንደምን ልቻለው እኔ ብቻዬን ነኝ\nያማኑኤል እናት ፈጥነሽ ድረሽልኝ\nያማኑኤል እናት ፈጥነሽ ድረሽልኝ\n\nበጣም ተንገዳገድኩ ልወድቅ ነው እኔ\nእማምላክ ደግፊኝ ቁሚልኝ ከጎኔ\nምንም አጋር የለኝ ካንቺ በቀር ለኔ\nምንም አጋር የለኝ ካንቺ በቀር ለኔ', 'am', 106, 0),\n(5, 'ለመዳኑ ህይወት', 'ለመዳኑ ህይወት\nለመዳኑ ህይወት ለጽድቁ ጠርቼህ\nከዓለም ለይቼ በፍቅሬ መርጬህ\nበረከትና ፍቅር ሰላሜን ወርውረህ\nልጄ የምወድህ እባክህ ወዴት ነህ\nይልሃል እግዚአብሔር እባክህ ወዴት ነህ\n\nከዓለም ጉያ ውስጥ ሽብር ከተሞላው\nከስንጥቅ አለት ውስጥ ጎድጓዳ ከሆነው\nየአራዊቱ ግርማ ያንበሶቹ ግሳት\nየዘንዶው ትርምስምስ የእባቦቹ ፉጨት\nየጨለማው ክብደት የፍጥረት ማዛጋት\nእንዲህ ያለ ስፍራ ተወርውረህ ነወይ\nቀናት ተቆጠሩ አይኖችህን ሳላይ\n\nከቅዳሴው ዕጣን ምስጋና ስቀበል\nጎላ ያለው ድምፅህ ተሰውሮብኛል\nበቅድስቱ በኩል በምትቆምበት በቅዳሴ ጊዜ\nአይኖቼ ስላጡህ ፈልገው ፈልገው ይዞኛል ትካዜ\nአይኖቼ ስላጡህ ፈልገው ፈልገው ይዞኛል ትካዜ\n\nልጄ ምን በደልኩህ ምን አጎደልኩብህ\nትተህኝ የሄድከው እንደዛ ስወድህ\nዘወትር ፊትህን ሳየው ደስ እያለኝ\nደስታዬን በሀዘን ምነው ለወጥክብኝ\nደስታዬን በሀዘን ምነው ለወጥክብኝ', 'am', 107, 0),\n(5, 'በኢያሪኮ መንገድ', 'በኢያሪኮ መንገድ\nበኢያሪኮ መንገድ ጌታ አንተ ስታልፍ\nግፊያ ሆኖ ሳለ ስደነቃቀፍ\nየዳዊት ልጅ ማረኝ ብዬ ተማጸንኩህ\nዓይኔንም ፈወስከኝ ዛሬ ማየት ቻልኩኝ\nዓይኔንም ፈወስከኝ ዛሬ ማየት ቻልኩኝ\n\nአንተን እንዳላይ ቁመቴ አጠረብኝ\nከፊት እየሮጥኩ ከዛፍ ላይ ወጣሁኝ\nጌታ ሆይ ጠራኸኝ ዘኬዎስ ሆይ አልከኝ\nበቤቴ እንድትገባ ፍቃድህ ሆነልኝ\nበቤቴ እንድትገባ ፍቃድህ ሆነልኝ\n\nሐሴትም ሆነልኝ በጣምም ደስ አለኝ\nአንተን በእንግድነት በቤቴ ተቀበልኩኝ\nኃጢአቴን ሁሉ በአንተ ፊት ጥያለሁ\nሀብቴን አካፍል ዘንድ በሚገባ አውቃለሁ\nሀብቴን አካፍል ዘንድ በሚገባ አውቃለሁ\n\nየክፋትን ገንዘብ መስብሰቤን ትቼ\nአንተን ልክተልህ ሁሉን እረስቼ\nኑሮዬንም ባርከው የሕይወት ዘመኔን\nመርጫለሁ አንተን በቤትህ መኖሬን\nመርጫለሁ አንተን በቤትህ መኖሬን', 'am', 108, 0),\n(5, 'በዕጸ መስቀል ላይ', 'በዕጸ መስቀል ላይ\nበዕጸ መስቀል ላይ በዚያ አደባባይ\nአምላክ ሆይ ጌታ ሆይ መከራ አየህ ወይ\nአምላክ ሆይ ጌታ ሆይ ተንገላታህ ወይ\n\nመስቀል አስይዘው ኪራያላይሶን\nወደ ጎልጎታ ኪራያላይሶን\nሲገራፉ ሲዳፉ ኪራያላይሶን\nስትንገላታ ኪራያላይሶን\n\nያንን አቀበት ኪርያላይሶን\nያንን ዳገት ኪርያላይሶን\nጀርባህ ተገርፎ ኪርያላይሶን\nስትቃትት ኪርያላይሶን\n\nአንተን እያዩ ኪርያላይሶን\nሴቶች ሲያለቅሱ ኪርያላይሶን\nእናቶች ቀርበው ኪርያላይሶን\nላብህን ዳበሱ ኪርያላይሶን\n\nመስቀል አስይዘው ኪያላይሶን\nእንዲያ ሲያዳፉህ ኪያላይሶን\nየቀሬናው ሰው ኪያላይሶን\nስምኦን አገዘው ኪያላይሶን', 'am', 109, 0),\n(5, 'ኑ እንቅረብ', 'ኑ እንቅረብ\nኑ እንቅረብ መጠራት ሳይመጣ\nኑ እንቅረብ መጠራት ሳይመጣ\nሥጋውን እንብላ ደሙንም እንጠጣ\nሥጋውን እንብላ ደሙንም እንጠጣ\n\nየቀራንዮ በግ የአምላክ ሥጋው\nተሰውቶልናል እንመገበው\nእድፉን ኃጢአታችን በንስሐ አንጽተን\nእንቀበል አምነን በልጅነታችን\nמቅረብ ወደጌታ በእውነት የሚገባው\nበስተርጅና አይደለም በወጣትነት ነው\n\nጨረቃና ፀሐይ ደም የለበሱለት\nከዋክብት በሰማይ የተነጠፉለት\nይኸው ተፈተተ እሳተ መለኮት\n\nቅድስት እናታችን ቤተክርስቲያን\nትመግበናለች ሥጋና ደሙን\nየአማኑኤል ሥጋ ይኸው ተዘጋጀ\nለግብዣ ተጠራን አዋጁም ታወጀ\n\nמጥቅኡ ተደወለ እንቅረብ በእልልታ\nበኋላ አይረባም ዋይታና ጫጫታ\nይህችን እድል ፈጥነን እንጠቀምበት\nዓለምን አልያዝንም ብዙ ልንቆይበት\n\nካሁኑ ቅረቡ ታውጇል አዋጁ\nየይለፍ ደብዳቤ ስንቅን አዘጋጁ\nይህ ዓለም ጠፊ ነው በሀብት አትመኩ\nብሏል አምላካችን ተስፋችሁን እንኩ', 'am', 110, 0),\n(5, 'አልፋና ኦሜጋ', 'አልፋና ኦሜጋ\nአልፋና ኦሜጋ ፈጣሪ የሆንክ\nበከሃዲዎች እጅ ተይዘህ ቀረብክ\n\nተገፋህ ተደፋህ በጥፊ ተመታህ\nእየደበደቡህ ክርስቶስ ሆይ አሉህ\nጽድቅን ስለሠራህ በወንጀል ከሰሱህ\nለአዳም ቤዛ ብለህ ብዙ ተንገላታህ\n\nቅዱሳን እጆችህ የፊጥኝ ታስረው\nእንደ በግ ተጎተትክ ልትምራቸው\nየትም ቦታ ያለህ ሁሉን የምታውቅ\nፊትህን ሸፈኑህ ለመመጻደቅ\n\nበአውደ ምኩናን ከጲላጦስ ፊት\nአሳልፈው ሰጡህ አጋልጠው ለፍርድ\nከሐና ቀያፋ ከመሳፍንቱ ደጅ\nከነ ሄሮድስ ዘንድ አቀረቡህ በአዋጅ\n\nግርፋት ሕማሙ አልበቃ ብሎህ\nበመስቀል ላይ ልትውል ተፈረደብህ\nየሰላም ባለቤት ደረትህ ተወጋ\nሊያያዝ በችንካር እጅህ ተዘረጋ', 'am', 111, 0),\n(5, 'አቤት የዚያን ግዜ', 'አቤት የዚያን ግዜ\nአቤት የዚያን ጊዜ\nክርስቶስ ሲመጣ\nአቤት የዚያን ጊዜ\nክርስቶስ ሲመጣ\nትንሹም ትልቁም መድረሻውን ሲያጣ\nትንሹም ትልቁም መድረሻውን ሲያጣ\n\nከምስራቅ ከምዕራብ\nከሰሜን ከደቡብ\nከምስራቅ ከምዕራብ\nከሰሜን ከደቡብ\nአየራት/መላእክት/ ሲላኩ መአትን ለማዝነብ\nአየራት/መላእክት/ ሲላኩ መአትን ለማዝነብ\nሰማይና ምድር በአንድ ሲዋሐዱ\nሰማይና ምድር በአንድ ሲዋሐዱ\nየት ይሆን መድረሻው የት ይሆን መንገዱ\nየት ይሆን መድረሻው የት ይሆን መንገዱ\n\nጻድቃን በቀኝ በኩል\nኃጥአን በግራ\nጻድቃን በቀኝ በኩል\nኃጥአን በግራ\nሲነፋ መለከት ሲደለቅም ዕንዚራ\nሲነፋ መለከት ሲደለቅም ዕንዚራ\nምድር ቀውጢ ስትሆን\nአጽም ሲሰበሰብ\nምድር ቀውጢ ስትሆን\nአጽም ሲሰበሰብ\nሐፍረት ይይዘዋል ሰው ለፍርድ ሲቀርብ\nሐፍረት ይይዘዋል ሰው ለፍርድ ሲቀርብ\n\nጩኸት ሲበረታ\nየማይጠቅም ለቅሶ\nጩኸት ሲበረታ\nየማይጠቅም ለቅሶ\nእንደ ቍራ ጠቁሮ ጽልመትን ተላብሶ\nእንደ ቍራ ጠቁሮ ጽልመትን ተላብሶ\nገነትን ሲያገኙ\nጻድቃን በስራቸው\nገነትን ሲያገኙ\nጻድቃን በስራቸው\nኃጥአን ወደ ሲኦል ተፈረደባቸው\nኃጥአን ወደ ሲኦል ተፈረደባቸው', 'am', 112, 0),\n(5, 'አቤቱ ደግሰው', 'አቤቱ ደግሰው\nአቤቱ ደግ ሰው አልቆአልና\nአቤቱ ደግ ሰው አልቆአልና\nከምድርም ፍቅር ጠፍቷልና\nከምድርም ፍቅር ጠፍቷልና\nእንደቸርነትህ አድነን\nእንደቸርነትህ አድነን\nበደላችንን አትቁጠር\nበደላችንን አትቁጠር\n\nየረድኤት አምላክ ፍቅር ስጠን\nየረድኤት አምላክ ፍቅር ስጠን\nእንደ አህዛቡ አታድርገን\nእንደ አህዛቡ አታድርገን\nክርስቲያን ነንና እንዋደድ\nክርስቲያን ነንና እንዋደድ\nእባክህ አንውጣ ከአንተ መንገድ\nእባክህ አንውጣ ከአንተ መንገድ\n\nአቤቱ ንፁህ ልብ ፍጠርልን\nአቤቱ ንፁህ ልብ ፍጠርልን\nሰውን የሚያስወድድ ካለ እንከን\nሰውን የሚያስወድድ ካለ እንከን\nአንደበታችንም እንዲናገር\nአንደበታችንም እንዲናገር\nስለ ሰላም ቋንቋ ስለ ፍቅር\nስለ ሰላም ቋንቋ ስለ ፍቅር\n\nበእግዚአብሔር ፈቃድ የሚመራ\nበእግዚአብሔር ፈቃድ የሚመራ\nትሩፋት ደግነት የሚሰራ\nትሩፋት ደግነት የሚሰራ\nአንደበቱ ሁሉ የታረመ\nአንደበቱ ሁሉ የታረመ\nለቃለ ወንጌሉ የደከመ\nለቃለ ወንጌሉ የደከመ\n\nምግባርና እውነት የተሰጠው\nምግባርና እውነት የተሰጠው\nእባክህን አድለን ሁነኛ ሰው\nእባክህን አድለን ሁነኛ ሰው\nአንተን የሚመስል በሕይወቱ\nአንተን የሚመስል በሕይወቱ\nፍቅርና ትሕትና የግል ሀብቱ\nፍቅርና ትሕትና የግል ሀብቱ\n\nየማስመሰል ፍቅር እየበዛ\nየማስመሰል ፍቅር እየበዛ\nሰው እረክሷልና እንደዋዛ\nሰው እረክሷልና እንደዋዛ\nፍፁም መዋደድን ስጠንና\nፍፁም መዋደድን ስጠንና\nአዲስ ሰው እንሁን እንደገና\nአዲስ ሰው እንሁን እንደገና\n\nደገኛ ሰው ማግኘት አስቸግሯል\nደገኛ ሰው ማግኘት አስቸግሯል\nእስከ መጨረሻው ማን ይፀናል\nእስከ መጨረሻው ማን ይፀናል\nምግባሩ ትክክል እውነተኛ\nምግባሩ ትክክል እውነተኛ\nልቡ የሚፀየፍ ከዳተኛን\nልቡ የሚፀየፍ ከዳተኛን', 'am', 113, 0),\n(5, 'ከንቱ ነኝ', 'ከንቱ ነኝ\nከንቱ ነኝ የከንቱ ከንቱነኝ\nዋስትና መከታ እግዚአብሔር ካልሆነኝ\nተስፋ የሚሆነኝ ሕይወት የሚሰጠኝ\nአምላኬ ብቻ ነው የሚያስተማምነኝ\nእግዚአብሔር ብቻ ነው የሚያስተማምነኝ\n\nእኔ ንጉሥ ነበርኩ በክብር ያጌጥኩኝ\nሁሉን በምድር ላይ በጥበብ ፈጸምኩኝ\nየዚህ ዓለም ደስታ ምንም አላዋጣኝ\nበመጨረሻውም በሞት ተወሰድኩኝ\nበመጨረሻውም በሞት ተወሰድኩኝ\n\nከጣይቱ በታች አዲስ ነገር የለም\nሰዎች ይደክማሉ እስከ ዘለዓለም\nጥበብን ፍለጋ ደክሜ ነበረ\nሁሉም ከንቱ ሆኖ በመቃብር ቀረ\nሁሉም ከንቱ ሆኖ በመቃብር ቀረ\n\nከኔ አስቀድመው የከበሩ ሁሉ\nአፈር ተጭኗቸው በመቃብር አሉ\nእብደትና እውቀት ሁሉን አወኳቸው\nምንም ቋሚ የለም ሁሉም ከንቱ ናቸው\nምንም ቋሚ የለም ሁሉም ከንቱ ናቸው\n\nልቤን የጣልኩበት ተስፋ ያደረኩት\nአልጨበጥ ብሎኝ አለሁኝ ስታክት\nየጥበብም ብዛት ለትካዜ ሰጠኝ\nእኔ በዚህ ምድር ጐስቋላ ፍጥረት ነኝ\nእኔ በዚህ ምድር ጐስቋላ ፍጥረት ነኝ\n\nልቤንም ፈተንኩት በደስታ ብዛት\nየዚህን ዓለም ለውጥ ጣሙን አቀመስኩት\nሳቅም በልቤ ውስጥ ይፍለቀለቅ ነበር\nሁሉም ከንቱ ሆነ ገብቶ ከመቃብር\nሁሉም ከንቱ ሆነ ገብቶ ከመቃብር', 'am', 114, 0),\n(5, 'ዋ ለነፍሴ', 'ዋ ለነፍሴ\nዋ ለነፍሴ\nምንም ስንቅ አልያዝኩኝም\nምንም ስንቅ አልያዝኩኝም\n\nአዬ እኔስ ወዮልኝ\nዋ ለነፍሴ ምንም ስንቅ አልያስኩኝ\nነፍሴን እየጐዳሁ ሳስብ ስለሥጋ\nዓለም ስትስበኝ እንዳላገኝ ዋጋ\nመንፈስህን ስጠኝ ከበደል አንጻኝ\nበቃልህ ልመራ ሕይወት እንዳገኝ\n\nቃልህን እሰማለሁ ማስተዋል የለኝም\nበፅናት ለመቆም ጌታ ሆይ አቃተኝ\nታዲያ እንደፈቃድህ እንዴት ብዬ ልገኝ\nድካሜን ታውቃለህ አምላክ ሆይ አበርታኝ\n\nአለቅሳለሁ ጌታ ከእግርህ ወድቄ\nሕይወቴ ተዛብቶ በኃጢአት ማቅቄ\nዘመኔን ጨረስኩኝ መልካሙን ሳልሰራ\nቸርነትህ ይርዳኝ ልኑር ከአንተ ጋራ\n\nጭንቀቴ እጅግ በዛ የሚያጽናናኝ አጣሁ\nፈተናው ከበደኝ ለነፍሴ ፈራሁ\nደስታ ከእኔ ርቆ በቢዛ ኃዘኔ\nአትተወኝ አንተ ሁንልኝ ከጐኔ', 'am', 115, 0),\n(5, 'ያ ደሃ ተጣራ', 'ያ ደሃ ተጣራ\nያ ደሃ ተጣራ እግዚአብሔርም ሰማው\nደርሶ ስላንኳኳ ከጸባኦት እንባው\nአምላክ በቸርነት በምህረት ጎበኘው\nባለቀሰ ጊዜ ግራ የገባው ሰው\n\nመሻትህ ብቻ ነው የሚፈለግብህ\nእግዚአብሔርን ጥራ እመን ትድናለህ\nእግዚአብሔርን ጥራ እመን ትድናለህ\n\nንገረው ችግርህን የውስጥህን ብሶት\nይሽረዋልና አስፈሪውን ህይወት\nግራ የተጋባው የተከፋው ገጽህ\nይበራል በጸሎት አምላክህን ጠርተህ\n\nለወገን ለዘመድ ያስቸገረው መላ\nሲቀል ታየዋለህ ካነባህ በኋላ\nሳቅና ንዴትህ ይቀራል ይሻራል\nበእርሱ ፈንታ ልብህ በሰላም ይሞላል\n\nበከንቱ መጨነቅ ራስን መጥላቱ\nነውና የአጋንንት መግቢያ ምልክቱ\nሀዘን በህሊናህ በፈሰሰ ጊዜ\nንገረው ለአምላክህ የሆድክን ትካዜ', 'am', 116, 0),\n(5, 'ድንግል ማርያም ብዬ', 'ድንግል ማርያም ብዬ\nድንግል ማርያም ብዬ\nስማጸን በስምሽ\nድንግል ማርያም ብዬ\nስማጸን በስምሽ\nበቅድመ እግዚአብሔር\nልመናዬን አድርሽ\nበቅድመ እግዚአብሔር\nልመናዬን አድርሽ\n\nእኔ ደካማ ነኝ ኃጢአቴ የበዛ\nእኔ ጎስቋላ ነኝ በደሌ የበዛ\nጊዜዬን ያባከንኩ በዋዛ ፈዛዛ\nጊዜዬን ያሳለፍኩ በከንቱ በዋዛ\n\nእመብርሃን ስልሽ ፈጥነሽ ድረሽልኝ\nእመብርሃን ስልሽ ፈጥነሽ ድረሽልኝ\nልመናዬን ሰምተሽ ቆመሽ ለምኝልኝ\nኃጢአቴ ቢበዛም ይዣለሁ አንቺን\nኃጢአቴ ቢበዛም ይዣለሁ አንቺን\nአስምረሻልና በላዒ ሰብን\n\nአንገት የሚያስደፋ በዝቶብኝ ኃጢአቴ\nምልጃሽን ፈለኩኝ ድንግል ሆይ እናቴ\nያን ክፉ ጨለማ እንዳላይ አደራ\nያን ክፉ ጨለማ እንዳላይ አደራ\nድንግል ሆይ ከልይኝ ከዲያብሎስ ጭፍራ\n\nእመብርሃን እያልኩ ቆሜ ከደጅሽ\nበብርሃን እጆችሽ እንባዬን አብሽ\nዓለም አታላይ ነች ወደሷ ተሳብኩኝ\nታማልጂኝ ብዬ አንቺኑ ተራብኩኝ', 'am', 117, 0),\n(5, 'ድንግል ትንሳኤሽን', 'ድንግል ትንሳኤሽን\nድንግል ትንሳኤሽን እስከምናይ ድረስ\nገብተናል ሱባኤ በአንድነት በመንፈስ\nለእኛ እስከሚገለጥ ቶማስ ያየው እውነት\nአንወጣም ከደጅሽ ኪዳነ ምህረት\nአንወጣም ከደጅሽ ኪዳነ ምህረት\n\nሞትን የረገጠ ልጅሽ ካንቺ ጋር ነው\nውጦ የሚያስቀርሽ የቱ መቃብር ነው\nየዕርገትሽን ዜና ከቶማስ ሰምተናል\nትንሳኤሽ እውነት ነው ሰበንሽን አይተናል\nሞትማ በሞት ተሽንፏል\nባንቺ ላይ እንዴት ኃይል ያገኛል\nሞትማ በሞት ተሽንፏል\nባንቺ ላይ እንዴት ኃይል ያገኛል\n\nልናየው ወደድን የቶማስን ክብር\nለምን ተስወረን የትንሳኤሽ ምስጢር\nበራችንን ዘግተን በፀሎት ወድቀናል\nተገልጠሽ አብሪልን ልጆችሽ ናፍቀናል\nሞትማ በሞት ተሽንፏል\nባንቺ ላይ እንዴት ኃይል ያገኛል\nሞትማ በሞት ተሽንፏል\nባንቺ ላይ እንዴት ኃይል ያገኛል\n\nመዝሙረኛ አባትሽ ዳዊት ጽፎልናል\nሞትን የማያይ ስው ማን አለ ብሎናል\nይህ እውነት በዘመን አንቺ ላይ ቢደርስም\nበሞት ተሽንፏል መቃብር አይኖርም\nሞትማ በሞት ተሽንፏል\nባንቺ ላይ እንዴት ኃይል ያገኛል\nሞትማ በሞት ተሽንፏል\nባንቺ ላይ እንዴት ኃይል ያገኛል\n\nቶማስ ከደመናው ወርዶ ሲያናግረን\nስለ ሆነው ነገር እጅጉን ተመሰጥን\nእኛም ይህን ክብር ተመኘን ለማየት\nድንግል አሳስቢልን ኪዳነ ምህረት\nሞትማ በሞት ተሽንፏል\nባንቺ ላይ እንዴት ኃይል ያገኛል\nሞትማ በሞት ተሽንፏል\nባንቺ ላይ እንዴት ኃይል ያገኛል', 'am', 118, 0),\n(5, 'ጊዜዬ እስኪደርስ', 'ጊዜዬ እስኪደርስ\nጊዜዬ እስኪደርስ ወዳንተ መምጫዬ ለንሰሐ አብቃኝ አቤቱ ጌታዬ\nጊዜዬ እስኪደርስ ወዳንተ መምጫዬ ለንሰሐ አብቃኝ አቤቱ ጌታዬ\n\nብርሃኔ መዳሃኒቴ ተስፋዬ መልሰኝ\nክፋቴን ደምስሰው ይቅርታ አድርግልኝ\nተስፋዬ ረዳቴ አንተ አጣለኝ\nአምላኬ አታጥፋኝ ከሲኦል አድነኝ\n\nመሐሪ ይቅር ባይ ምሕረትህ ይጎብኘኝ\nከኀጢአት ፍላጻ ጸጋህ ይታደገኝ\nአዳኜ መድኃኒቴ ሰላምን ላክልኝ\nየድህነት በርህን በፍቅር ክፈትልኝ\n\nአቤቱ ምህረትህ በኔ ላይ ይሁን\nተጨነቅሁ አምላኬ ስጠኝ ሰላምን\nከክፋ እንድሸሽ ጠብቀኝ እኔን\nበጎ እንድሠራ ምራኝ መንገዱን\n\nሕይወት ሞት ድህነት መኖራቸውን ባውቀውም\nሀጢያት ውድቀት ጥፋት አያዘናጋኝም\nስርየት እንደማገኝ ተስፋ ቢኖረኝም\nትምክህቴ አንተ ነህ በሌላ አልመካም\n\nየበደሌ ብዛቱ የሚያስከፋም ቢሆን\nበስጋ በደምህ እጠብ ኃጢአቴን\nወዳንተ እጮኻለሁ አደራ ነፍሴን\nበሰማያዊው ቤት አኑር ሕይወቴን', 'am', 119, 0),\n(5, 'የሲና ሐመልማል', 'የሲና ሐመልማል\nየሲና ሐመልማል የሙሴ ጽላት\nየሲና ሐመልማል የሙሴ ጽላት\nየሲሎንዲስ ጥበብ ዕፀ መድኃኒት\nየሲሎንዲስ ጥበብ ዕፀ መድኃኒት\nአሁን በምን በምን እንመስልሻለን\nዕፁብ ድንቅ እያልን እናወድስሻለን\nያረጁ ፍጥረታት የታደሱብሽ\nያረጁ ፍጥረታት የታደሱብሽ\nየሕይወት መሰላል ማርያም አንቺ ነሽ\nየሕይወት መሰላል ማርያም አንቺ ነሽ\n\nየነቢያት ትንቢት የልባቸው ተስፋ\nየነቢያት ትንቢት የልባቸው ተስፋ\nበአንቺ መመኪያነት ማህበራችን ይስፋ\nበአንቺ መመኪያነት ማህበራችን ይስፋ', 'am', 120, 0),\n(5, 'ይቅር ስላልከኝ ነው', 'ይቅር ስላልከኝ ነው\nይቅር ስላልከኝ ነው የእኔ መቆም፣\nደግሞ እንዳልፈርድ እርዳኝ በሰዎች ድካም።\nደግሞ እንዳልፈርድ እርዳኝ በሰዎች ድካም።\n\nለዛሬ መድረሴ አይደል በጽድቄ፣\nእያነሣኸኝ ነው ዓይተህ ወድቄ፣\nበፈረድኩበት ፍርድ እንዳይፈረድ፣\nአልሁን ፈሪሳዊ ወንድሜን ልውደድ።\nጉድፉን አልይ የወንድሜን በደል፣\nአለ በእኔ ላይ ምሰሶን የሚያህል።\n\nባታለብሰኝ ኖሮ ነውሬን ሸፍነህ፣\nባታቆመኝ ኖሮ በደሌን ከድነህ፣\nበጠፋ ነበር ስም አጠራሬ፣\nድካሜ ብዙ ነው እንደ ራስ ጠጉሬ።\nጉድፉን አልይ የወንድሜን በደል፣\nአለ በእኔ ላይ ምሰሶን የሚያህል።\n\nበምሕረትህ ብዛት ከቤትህ ልግባ፣\nዘወትር ላቅርብልህ የእንባዬን መባ፣\nየውስጤን ማንነት ለአንተ ልግለጥ፣\nለሰው አሳልፈህ ለማትሠጥ።\nጉድፉን አልይ የወንድሜን በደል፣\nአለ በእኔ ላይ ምሰሶን የሚያህል።\n\nዕለት ዕለት ግብሬ ኃጢአቴ መሥራት ነው፣\nአንተ ዕለት ዕለት እኔን መማር ነው፣\nየበደለን መተው የአንተ ነውና፣\nበወንድሜ መማር ቆሜ አልቅና።\nጉድፉን አልይ የወንድሜን በደል፣\nአለ በእኔ ላይ ምሰሶን የሚያህል።', 'am', 121, 0),\n(5, 'ድንግል የዚያን ግዜ', 'ድንግል የዚያን ግዜ\nድንግል የዚያን ጊዜ ሐዘንሽ በረታ\nድንግል የዚያን ጊዜ ሐዘንሽ በረታ\nበመስቀል ላይ ሆኖ ልጅሽ ሲንገለታ\nበመስቀል ላይ ሆኖ ልጅሽ ሲንገለታ\n\nየግፍ ግፍ ደርሶበት የዚያን ጊዜ ተጠማሁ ሲልሽ\nለውሻ ያጠጣሽ በወርቅ ጫማሽ\nለውሻ ያጠጣሽ በወርቅ ጫማሽ\n\nሴቶች ሲያባርሩት የዚያን ጊዜ እራርቶ ሆድሽ\nለፍጡር በማዘን ውኃ ያጠጣሽ\nለፍጡር በማዘን ውኃ ያጠጣሽ\n\nተጠማሁ እያለ የዚያን ጊዜ ሲናገር ልጅሽ\nታዲያ እንደምን ቻለ ድንግል አንጀትሽ\nታዲያ እንደምን ቻለ ድንግል አንጀትሽ\n\nእንደዚያ ስታለቅሽ የዚያን ጊዜ ሐዘን ሲውጥሽ\nእነማን ነበሩ ያስተዛዘኑሽ\nእነማን ነበሩ ያስተዛዘኑሽ\n\nስታለቅሽ በማየት የዚያን ጊዜ እራርቶ ልጅሽ\nዮሐንስን አጽናኝ እንደ ልጅ ሰጠሽ\nዮሐንስን አጽናኝ እንደ ልጅ ሰጠሽ', 'am', 122, 0),\n(5, 'ጌታ ሆይ', 'ጌታ ሆይ\nጌታ ሆይ አይሁድ አማጽያን\nሰቀሉህ ወይ\nየዓለም መድኃኒት የዓለም ሲሳይ\nሰቀሉህ ወይ\nየዓለም መድኃኒት የዓለም ሲሳይ\nሰቀሉህ ወይ\n\nየአዳም በደል አደረሰህ\nአንተን ለመሰቀል\nየሔዋን ስህተት አበቃህ ለሞት\nቸሩ አባት\nየሔዋን ስህተት አበቃህ ለሞት\nቸሩ አባት\n\nንጹሕ ክርስቶስ ሆንክ ወንጀለኛ\nብለህ ስለእኛ\nመሰቀል አሸክመው\nአስረው ገፈፉህ እያዳፉህ\nአስረው ገፈፉህ እያዳፉህ\n\nእጅና እግርህን በብረት ተመታ\nየዓለም ጌታ\nየሾህ አክሊል ደፍተህ\nጎንህን ተወጋህ አልፋ ኦሜጋ\nጎንህን ተወጋህ አልፋ ኦሜጋ\n\nግብዞች እንደራሳቸው መስሏቸው\nምራቅ እየተፉ በፊትህ ቀለዱ\nአንተን ሊጎዱ\nምራቅ እየተፉ በፊትህ ቀለዱ\nአንተን ሊጎዱ\n\nበመሰቀል ላይ ተጠማሁ ስትል\nታላቅ በደል\nሀሞትና ከርቤ ሰጡህ ቀላቅለው\nጠጣ ብለው\nሀሞትና ከርቤ ሰጡህ ቀላቅለው\nጠጣ ብለው\n\nይቅር ባይ ግልጽ በደላችንን ሁሉ ሳታይ\nአንተ ይቅር በለን\nበእኛ ሳትከፋ እንዳንጠፋ\nበእኛ ሳትከፋ እንዳንጠፋ', 'am', 123, 0),\n(5, 'ኦ የማይሞተው ሞተ', 'ኦ የማይሞተው ሞተ\nኦ የማይሞተው ሞተ\nሄደ ቀራንዮ እየተጎተተ\nወድቆ እየተነሳ እንዲያ እየቃተተ\nሞትን ይሽረው ዘንድ የማይሞተው ሞተ\nሞትን ይሽረው ዘንድ የማይሞተው ሞተ\n\nእጅና እግሩን ታስሮ ሄደ አደባባይ\nእየተገረፈ ታግሶ ስቃይ\nአለቀሰች ቆማ ድንግል ማርያም\nተሰቅሎባት ልጅዋ መድኀኔዓለም\n\nበአይሁድ አደባባይ ፍርድ ተንጋደደ\nወንበዴ ተለቆ ንጹህ በግ ታረደ\nየማይሞተው ሞተ ለሰው ፍቅር ብሎ\nዋለ ቀራንዮ በእንጨት ላይ ተሰቅሎ\n\nዮሴፍ ኒቆዲሞስ ስጋውን ለመኑ\nእንዲፈቅድላቸው ሔደው ከመስፍኑ\nገንዘው ቀበሩት በአዲስ መቃብር\nቅዱስ ቅዱስ ቅዱስ ኃያል እያሉ በክብር', 'am', 124, 0);\n\nINSERT INTO mezmurs (category_id, title, content, language, sort_order, sync_version) VALUES\n(5, 'በስራዬ የት ይሆን መግቢያዬ', 'በስራዬ የት ይሆን መግቢያዬ\nበስራዬ የት ይሆን መግቢያዬ\nበስራዬ የት ይሆን መግቢያዬ\nበስራዬ የት ይሆን መግቢያዬ\nበስራዬ የት ይሆን መግቢያዬ\nጨነቀኝ ጠበበኝ ነፍሴ ወዲያልኝ\nጨነቀኝ ጠበበኝ ነፍሴ ወዲያልኝ\n\nተሸክሜ የኃጥያት ክምር\nተሸክሜ የኃጥያት ክምር\nይመሻል ይነጋል በከንቱ ስዞር\nይመሻል ይነጋል በከንቱ ስዞር\nገሰገሰ ቀኑ ጨለመብኝ\nገሰገሰ ቀኑ ጨለመብኝ\nዋ ለነብሴ ምንም ስንቅ አልያዝኩኝ\nዋ ለነብሴ ምንም ስንቅ አልያዝኩኝ\n\nበድያለሁ ወዳንተ ጮሃለሁ\nይቅር በለኝ እማፀንሃለሁ\nችላ አትበለኝ ከፊትህ ቆሜያለሁ\nችላ አትበለኝ ከፊትህ ቆሜያለሁ\n\nአለፈብኝ በከንቱ ጊዜዬ\nአለፈብኝ በከንቱ ጊዜዬ\nእየጓጓሁ ለዚች ለሥጋዬ\nእየጓጓሁ ለዚች ለሥጋዬ\nበንስሐ ሳላጥበው እድፌን\nበንስሐ ሳላጥበው እድፌን\nልትደርስ ነው ያች ፈተና ቀን\nልትደርስ ነው ያች ፈተና ቀን', 'am', 125, 0),\n(5, 'መቼ ነው ጌታ', 'መቼ ነው ጌታ\nመቼ ነው ጌታ አረ መቼ ነው መቼ ነው ጌታዬ\nእንደቃልህ የሚሖን ኑሮዬ\n\nአልተማርኩኝ አልል አስተምረሀኛል\nቃልህን እንደ ወተት አጠጥተሀኛል\n\nየታል አኗኗሬ አንተን የሚመስለው\nበልማድ ህይወት ነው የምመላለሰው\n\nይህ አንደበቴማ በቃልህ ሰልጥኗል\nልቦናዬ ካንተ ከፊትህ ኮብልሏል\n\nአንተን እንደማውቅህ አብዝቼ ባወራ\nየተዘራ ሁሉ ፍሬ አላፈራ\n\nእዘንልኝ እና መንገዴን አቅናልኝ\nየአመጽ ስራዬን በደሌን ተውልኝ\n\nቃልህ እንዳይሰደብ በእኔ ድካም\nአርመው እርሻህን መድኃኔዓለም\n\nእስራቴን ፈተህ ነጻነት ስጠኝ\nበቀኝህ አቁመህ ጌታ ሆይ ባርከኝ\n\nሀጥያት ሞትን ወልዶ እንዳያጠፋኝ\nየብርሀን ፊትህ ይገለጥልኝ', 'am', 126, 0),\n(5, 'እመአምላክ', 'እመአምላክ\nእመአምላክ አስቢኝ በሰርክ\nሀዘኔ ጭንቀቴ በጣም በዛብኝ\nከልጅሽ አስታርቂኝ አንቺ አማልጂኝ\nከመንበሩ ቆመሽ ንገሪው ለልጅሽ\nእናቱ ነሽእና አያሳፍርሽ\n\nእኔ ሀጥያተኛ በደሌን አውቃለሁ\nምርኩዜ ነሽ እና እመካብሻለሁ\nመንገዱ ጠፍቶብኝ የጽድቁ ጎዳና\nመብራቱን አብሪልኝ እመጣለውእና\n\nመመገብ ይቅርብኝ አልራብምና\nስምሽን ስጠራ እጠግባለውና\nአበው ሊቃውንቱ ባንቺ ይመካሉ\nእመአምላክ እያሉ ስምሽን ይጠራሉ\n\nከገሀነም አውጪኝ ከዚያ ከነበልባል\nከሲኦል ወድቄ እንዳልቃጠል\nያየስቃይ ሀገር ባህሩ ያሰምጠኛል\nአንቺ ከለመንሽው ልጅሽ ያዝንልኛል\n\nእኔስ እፈራለሁ ምግባሬን ሳየው\nደካም እምነቴ እየለየኝ ነው\nአረሳሽም ድንግል እማጸንሻለው\nአማላጅነትሽ መድህን ነው አውቃለው', 'am', 127, 0),\n(5, 'ሀጥያቴ በዛ እመቤቴ', 'ሀጥያቴ በዛ እመቤቴ\nሀጥያቴ በዛ እመቤቴ\nምህረት ላኪልኝ ለህይወቴ\nየፈጣሪ እናት አዛኝት\nባንቺ ነው ማግኛ የጽድቅ ህይወት\n\nየሚሰግዱልሽ ጻድቃን ሰማዕታት\nየሚላኩልሽ ቅዱሳን መላዕክት\nከእነሱ ጋር ነኝ እመቤቴ\nእንዲታረቀኝ ሰማያዊ አባቴ\n\nአስታርቂኝ ከልጅሽ\nእማልዳለሁ ከፊትሽ\nስምሽን ጠርቶ ያፈረ ማን ነው\nያዳም ተስፋ ስራሽ ድንቅ ነው\n\nየፍቅር እናት እመቤታችን\nአስታርቂን እኛን ከጌታችን\nዘወትር ነይልኝ እናቴ ማርያም\nላንቺ ቅርብ ነው መድኃኔዓለም', 'am', 128, 0),\n(5, 'ሰው ለሰው', 'ሰው ለሰው\nሰው ለሰው ቢፋቀር ምነው\nይመስለዎል ብዙ የሚቆይ\nግን በድንገት ያልፈዎል ሁሉንም ሳያይ\nግን በድንገት ያልፈዎል ሁሉንም ሳያይ\n\nየሰው ልጅ በተራው መጠራቱ ላይቀር\nምነው አንዱ ለአንዱ መቃብር ባይቆጥር\nምነው አንዱ ለአንዱ መቃብር ባይቆጥር\nአይጠቅምም መጨነቅ እንዲሁ ለውበት\nይረግፋል ይጠፋል ሁሉም ከመሬት\n\nዎ! ቁንጅና ከንቱ ውበትም ብላሽ\nአፈር ትብያ ሲሆን ሲጨልም ሲመሽ\nአፈር ትብያ ሲሆን ሲጨልም ሲመሽ\nድሀ ባለጸጋ አንድ ነው መንገዱ\nበጨርቅ ተገንዞ በሳጥን መሔደለ\n\nሰው ዙሪያውን ቢያጥር መዝጊያውን ቢዘጋ\nበህንጾ ላይ ህንጾ ቢያስመስል ተራራ\nአይቀርም መሔዱ ሁሉም በየተራ', 'am', 129, 0),\n(5, 'አጽናኝኝ እመአምላክ', 'አጽናኝኝ እመአምላክ\nአጽናኝኝ እመአምላክ ነይልኝ ምርኩዜ\nእንደከፋኝ አልኑር በሀዘን ትካዜ\n\nኑሮ ሲያበሳጨኝ ሲረበሽ አንጀቴ\nቤዛዊተ ኩሉ አጽናኝኝ እናቴ\nለተዎህዶ ልጆች መመክያ ዘውዳችን\nድንግል ሆይ አንቺ ነሽ መመክያ ዘውዳችን\n\nልጅሽ ከጎልጎታ አደራ ሰቶናል\nመተናል ከእግርሽ ስር ድንግል ሆይ ወድቀናል\nከቶ ምግባር ሰጣ ስጠፋ ከቤቱ\nትመልሽኛለሽ ድንግል አዛኝቱ\n\nከእንግዲ ይበቃል ማዘን መተከዜ\nመሸሸግያዬ ነይልኝ ምርኩዜ\nከሞት ወዲያ ማዶ ላላችው ህይወቴ\nዎስ ጠበቃዬ ነሽ ድንግል እመቤቴ', 'am', 130, 0),\n(5, 'በእየሩሳሌም', 'በእየሩሳሌም\nበእየሩሳሌም በበጎች በር\nበቤተሳይዳ እኖር ነበር\nማን ያድነኛል እያልኩኝ\nአልጋህን ይዘህ ሒድ አለኝ\nማን ያድነኛል እያልኩኝ\nአምላኬ መቶ ፈወሰኝ\n\nአልጋ ላይ ከዎልኩ ሰንብቻለሁ\nሰውነቴ አልቆ መንምኛለሁ\nውሀውን ሲያማታው ቅዳሜ\nብዙዎች ዳኑ እኔ ቆሜ\nአይዞህ የሚለኝ የሚያጽናናኝ\nደጋፊም የለኝ ብቻ ነኝ\n\nሰላሳ ስምንት አመት ሙሉ\nተሳለቁብኝ መጻጉ እያሉ\nእዘንልኝ አድነኝ\nሙሉ ጤነኛ አድርገኝ\n\nልትድን ትወዳለህ ሲለኝ\nእውነትም እውነት አልመሰለኝ\nአው እወዳለው ስለው ጌታ\nፈወሰኝ አምላክ የኔ አለኝታ\n\nስማኝ አምላኬ እጮሀለው\nሀጥያቴ በዝቶ አለቅሳለው\nበመብል ጠፍቶል ልጅነቴ\nባርያህ አድርገኝ ቸሩ አባቴ\n\nእንደእኔ ታማሚ የሆናችው\nአምናችው ጌታ ያድናቹ\nእንደእኔ ታማሚ የሆናቹ\nየጌታዬ እናት ታማልዳቹ', 'am', 131, 0),\n(5, 'አምላክ ሆይ', 'አምላክ ሆይ\nአምላክሆይ ወደእኛባትመጣ ለብሰህ የማርያምን ስጋ\nባክኖ የነበረው የአዳም ዘር ውጤቱ ነበር የሚያሰጋ\n\nበዚያች ወር በዚያች ለት በዚያች ቀን\nደህንነት ለሰው ልጅ ስለምትሰጥ\nምን የበዛ ነበር ትህትናህ ትዕግስትህ የማይለወጥ\n\nየሾህ አክሊል ደፍተው በራስህ ጎንህን ሲወጉ በጦር\nአንተ ግን ለእነሱ ከአባትህ ምህረትን ትለምን ነበር\n\nግን መቼ አወቁት እነሱ በሀጥያት ደንድኖ ልባቸው\nመድሀኒታቸውን ገረፉት ሰቀሉት አንተም ሞትክላቸው\n\nዳግም ስትመጣ ለፍርድ ከአለም ፍጻሜ በኃላ\nአረ እንዴት እድለኞች ናቸው በፊትህ የሚያገኙ ተድላ\nበዚያች በደብረዘይት ቦታ ደስታ እና ለቅሶ ሲፈልቅ\nከቶ ከየት ይሆን ያን ጊዜ እጣዬ የኔ አወዳደቅ\n\nየጸጸት እሮሮ ከፊትህ እንዳያቃጥለኝ እኔን\nእርዳኝ ፈጣሪዬ ካሁኑ አድሰው የዘጋውን ልቤን', 'am', 132, 0),\n(5, 'ምድረ ቀራንዮ', 'ምድረ ቀራንዮ\nምድረ ቀራንዮ ምድረ ጎልጎታ\nመድሀኒት ክርስቶስ ባንቺ ተንገላታ\n\nመስክሪ አንቺ ምድር ግኡዚቷ ስፍራ\nመስክሪ አንቺ ምድር ግኡዚቷ ስፍራ\nመዳኒት ክርስቶስ ያየብሽ መከራ\nደሙ እንደውሀ ሲፈስ መስቀል ላይ\nበቀራንዮ መሖል መከራውን ሲያይ\n\nጸሀይ ከለከለች ለመስጠት ብርሀን\nጸሀይ ከለከለች ለመስጠት ብርሀን\nለመሸፈን ብላ ያምላኳን እርቃን\nሁሉንም ለማድረግ ስልጣኑ ሲኖረው\nበመስቀል ተገልጠህ ፍቅሩን ገለጠው\n\nመስቀል ላይ ሆኖ ተጠማው እያለ\nየሾህ አክሊል ደፍቆ ቀራንዮ ዎለ\nእጆቹ እና እግሮቹ በችንካር ተወግተው\nይቅርታ አደረገ ለዚህ ሀጥያታቸው\n\nቸሩ መዳንያለም እባክህን ማረኝ\nደካሞች ነን እና እንዳንቀር ወድቀን\nበቆረስከው ስጋ ባፈሰስከው ደም\nአቤቱ ተራዳኝ እስከዘለአለም', 'am', 133, 0),\n(5, 'በጌቴ ሰማኔ', 'በጌቴ ሰማኔ\nበጌቴ ሰማኔ ባታክልቱ ቦታ\nለእኛ ሲል ጌታችን በአለም ተንገላታ\nለእኛ ሲል ጌታችን በአለም ተንገላታ\n\nአዳም እና ሔዎን ባጠፋት ጥፋት\nለኛም ደረሰልን የዘላለም ሞት\nለኛም ደረሰልን የዘላለም ሞት\n\nመስቀል ተሸክሞ ሲወጣ ተራራ\nይገርፋት ነበረ ሁሉም በየተራ\nይገርፋት ነበረ ሁሉም በየተራ\n\nተጠማሁ ተጠማሁ ተጠማሁ ሲላቸው\nሆምጣጤ አመጡለት በሰፍነግም ሞልተው\nሆምጣጤ አመጡለት በሰፍነግም ሞልተው\n\nድንግል አልቻለችም እንባዎን ልትገታ\nእያየች በመስቀል ልጆ ሲንገላታ\nእያየች በመስቀል ልጆ ሲንገላታ\n\nበአምላክነቱ ሳይፈርድባቸው\nእንዲሲል ጸለየ አባት ሆይ ማራቸው\nእንዲሲል ጸለየ አባት ሆይ ማራቸው\n\nበረቂቅ ስልጣኑ ሁሉን የፈጠረ\nበሰው እጅ ተይዞ ሞቶ ተቀበረ\nበሰው እጅ ተይዞ ሞቶ ተቀበረ', 'am', 134, 0),\n(5, 'ተይ ተመከሪ ነብሴ ሆይ', 'ተይ ተመከሪ ነብሴ ሆይ\nተይ ተመከሪ ነብሴ ሆይ ተመከሪ\nበአለም መዳኒት ነብሴ ሆይ በእግዚአብሔር ታመኚ\n\nለስጋ መገዛት ነብሴ ሆይ ምነው ቢቀርብሽ\nውርደት ነው ፍጻሜው ነብሴ ሆይ የሚያከናንብሽ\nመልካም የሖነውን ነብሴ ሆይ ጽድቅን ተከተይ\nክርስቶስን መስለሽ ነብሴ ሆይ ቸርነትን ስሪ\n\nሞትን ማን ይመርጣል ነብሴ ሆይ ህይወትን መጥላት\nከእንግዲ መራቅ ነው ነብሴ ሆይ ከስርቆት ከዝሙት\nጸጋ እንደበዛልሽ ነብሴ ሆይ የቃሉ በረከት\nከቤቱ አትጥፊ ነብሴ ሆይ በረከት ከሞላበት\n\nላንቺ ነበር ጌታ ነብሴ ሆይ ደሙን ያፈሰሰው\nተሰቅሎ ሞቶ ነው ነብሴ ሆይ ፍቅሩን የገለጸው\nበፍቅሩ ላሰበኝ ነብሴ ሆይ ላፈቀረኝ ጌታ\nምስጋና አቀርባለሁ ነብሴ ሆይ ከጠዎት እስከማታ\n\nብወድቅ ምርኩዜ ድጋፍ ጋሻ ይሆነኛል\nለፍርድ አልቻልኩም ነብሴ ሆይ በፍቅር ያየኛል\nማን እንደ እርሱ ነብሴ ሆይ ውለታው በዛ\nመሀሪ ይቅር ባይ ነው ነብሴ ሆይ የህይወቴ ቤዛ', 'am', 135, 0),\n(5, 'ጌታዬ መታመኛዬ', 'ጌታዬ መታመኛዬ\nጌታዬ መታመኛዬ\nጌታዬ መታመኛዬ\nፍቅርህን እኔ አየሁኝ\nማዳንህን ተመለከትኩኝ\n\nናድከው ጌታ\nመጣሁ መግነዜም ተፈታ\nአቀፍከኝ ይሸታል ሳትል\nአቀፍከኝ ይሸታል ሳትል\nአነባህ ስለእኔ ፍቅር\nአነባህ ስለእኔ ፍቅር\n\nአብቅቶል በቃ ተብዬ\nገስግሰህ መጣህ ጌታዬ\nአንከባለልከው ድንጋዮን\nአንከባለልከው ድንጋዮን\nአዮት የጌታ ማዳኑን\nአዮት የጌታ ማዳኑን\n\nአራት ቀን ሞላው እሬሳው\nይሸታል አሉ አትጠጋው\nአላዛር ተነሳ አልከኝ\nአላዛር ተነሳ አልከኝ\nመጣሁ መግነሱ ሳይዘኝ\nመጣሁ መግነሱ ሳይዘኝ', 'am', 136, 0),\n(5, 'ድንግል ሆይ ጠብቂኝ', 'ድንግል ሆይ ጠብቂኝ\nድንግል ሆይ ጠብቂኝ ከፈተና ቦታ\nአድክሞኛል የአለም ሁካታ\n\nዘወትር የምበድል ሁል ጊዜ ወንበዴ\nበሰው ላይ ማልጨክን እያወቀው ሆዴ\nድንግል ሆይ ሰለቸኝ አሁንስ ታከተኝ\nየአማኑኤል እናት ዘወትር አትለይኝ\n\nየሀጥያት ማዕበል እኔን አደንዝዞኝ\nሊያስቀረኝ ነው እና አለም እዛ ስቦኝ\nለኔ ለሀጥያተኛው ድንግል አሳስቢልኝ\nስለ ቃልኪዳንሽ ጌታ እንዲምረኝ\n\nቅድስና አልባ ባዶ ሰው ሆኛለሁ\nበሀጥያት ስራ እኔስ ተውጫለሁ\nበተሰጠሽ ጸጋ ባማላጅነትሽ\nምህረትን አሰጪኝ ከሀያሉ ልጅሽ', 'am', 137, 0),\n(5, 'ልመናዬን ስማኝ', 'ልመናዬን ስማኝ\nልመናዬን ስማኝ ቃሌንም አድምጠኝ\nእውነተኛ አምላክ ሰላምህን ስጠኝ\nእውነተኛ አምላክ ሰላምህን ስጠኝ\n\nክርስትያኖች ሁሉ ትዕዛዙን አክብሩ\nምስጋና አቅርብ ስገዱ ዘምሩ\nየጌታን አመጣጥ ለአለም ንገሩ\nደቀ መዛሙርቱ ወንጌል አስተምሩ\n\nበመልካም የሚሔድ ጽድቅን የሚሰራ\nየፈጣሪውን ስም በከንቱ የማይጠራ\nይጎበኛል በምድር በሰማይ ስፍራ\nበቀኝ ይቀመጣል ከቅዱሳን ጋራ\n\nስለጠላቶቼ ዘጽድቅህ ምራኝ\nበጸብ ቀን ከበበኝ ተሰለፍብኝ\nመሀሪ ይቅር ባይ መጠጊያ ሁንልኝ\nአንተው በቸርነት ይቅርታህን ስጠኝ', 'am', 138, 0),\n(5, 'በመከራ ጽና', 'በመከራ ጽና\nበመከራ ጽና በፈተና ጽና\nለጊዜው ነው እንጂ ሁሉም ያልፋል እና\n\nእዮብ ተጨነቀ በጣም ተማረረ\nከመከራው ብዛት ትዕግስትን ተማረ\nልጅ የሌለው ሆነ አጣ ንብረቱን\nበመከራ ጸና አልካደም አምላኩን\n\nመፈተን መልካም ነው ያነጻል እንደወርቅ\nበመጨረሻው ቀን በክብር እንድንደምቅ\nአንዱን ስትወጣ ሌላው ቢያጋጥምህ\nበህይወት ዘመንህ መከራ ባያጣህ\n\nከአምላክህ ተስማማህ እራስህን አዎርድ\nበቃሉም ተመራ እንደ ፈቃድህ ሒድ\nዎጋ ከአምላክ ዘንድ በሰማይ\nበርታ ክርስትያን ሆይ በመከራ ጽና', 'am', 139, 0),\n(5, 'የኛ ምርኩዝ', 'የኛ ምርኩዝ\nየኛ ምርኩዝ የኛ ተስፋ\nአትለይን እንዳንጠፋ\nአትለይን እንዳንጠፋ የኛ ተስፉ\n\nልቦናዬ አወጣ በጎ በጎ ነገር\nየድንግልን ክብሯን እንዳቅሜ ልናገር\nበማብዛት አደለም በማሳነስ እንጂ\nድንግል አማላጅ\n\nበሀጥያት ፈጽሞ አንቺ አልተጸነስሽም\nበህግ ሩካቤ ከሀና ተወለድሽ\nእንደ እብራውያን ሴቶች መች በዎዛ አደግሽ\nበቤተ መቅደስ ኖርሽ\n\nምድራዊ ህብስት አንቺ አልተመገብሽም\nምድራዊ መጠጥ ፈጽሞ አልጠጣሽም\nከሰማያት ሰማይ ወረደልሽ\nከሰማያት ሰማይ ወረደልሽ\nምግብ እና መጠጥሽ\nምግብ እና መጠጥሽ\n\nይህን ባሰብኩ ጊዜ ፈጽሞ ይደንቀኛል\nየፈጣሪን ስራ ማን ይመረምራል\nየኛ ድንቅ እመቤት አምላክ የመረጠሽ\nየኛ ድንቅ እመቤት አምላክ የመረጠሽ\nገናና ነው ስምሽ\nገናና ነው ስምሽ', 'am', 140, 0),\n(5, 'አለምን ለማዳን', 'አለምን ለማዳን\nአለምን ለማዳን የተሰቀለው\nእየሱስ ክርስቶስ እግዚአብሔር ነው\n\nጌታችን ተሰቅሎ ሲያዩት መላዕክት\nበዝማሬ ፈንታ አለቀሱለት\nሚካኤል ዝም አለ ገብርኤል ገረመው\nአምላኩን እርቃኑ ተሰቅሎ ስላየው\nአምላኩን እርቃኑ ተሰቅሎ ስላየው\n\nነብሱን ለወዳጁ የሚሰጥ ቢገኝም\nለጠላት የሚሞት በጭራሽ አይኖርም\nጠላቶቹ ሳለን ለእኛ የሞተው\nክርስቶስ ልዩ ነው ወደር የሌለው\nክርስቶስ ልዩ ነው ወደር የሌለው\n\nእውራን ቢያበራ የሞተ ቢያስነሳ\nበመመስገን ፈንታ ሆነለት አበሳ\nሰማያዊ ዳኛ ሊፈረድበት\nተከሶ ቀረበ በጲላጦስ ፊት\nተከሶ ቀረበ በጲላጦስ ፊት\n\nበጸሎተ ሀሙስ እለት እራት የሆነው\nአርብን በመስቀል የተሰቀለው\nፍቅር አስገድዶት ለኛ የሞተው\nፍቅር አስገድዶት ለኛ የሞተው\nመልካሙ እረኛችን መድኃኔዓለም ነው\nመልካሙ እረኛችን መድኃኔዓለም ነው', 'am', 141, 0),\n(5, 'ወደ እግርሽ ጭማ', 'ወደ እግርሽ ጭማ\nወደ እግርሽ ጫማ አትዛብ ይወገዳሉ\nየናቁሽ ሰዎች የጠሉሽ በሙሉ\nጸጋሽን አየነው ክብርሽን\nድንግል ሆይ አማልጂን አስታርቂኝ ይላሉ\n\nየቅዱሳን ክብር መገለጫቸው ነሽ\nየሰላም እርግ የወይን ተክል ነሽ\nየአዳም እዳ በደል ፍጹም የሌለብሽ\nየአቀው ውዴሴ የምስጋና ቤት ነሽ\n\nህዝብ እና አህዛብ ስገዱ በፍርሀት\nበጸጋው ስጦታ ድንቅ እና ልዩነት\nየሰው ልጅ መዳኛ የድህነት ምልክት\nየያዕቆብ አምላክ ማደርያው እኳ ናት\n\nጽዮንን ክበቦት እንዳለ አባታችን\nየሾ መሸገስ ግርማ ሁኚ መሀላችን\nጸጋሽን ተረድተን ክብርሽን አወቅን\nሰላም እለኪ እያለን እንሰግድልሻለን', 'am', 142, 0),\n(5, 'እንደ በደሌማ', 'እንደ በደሌማ\nእንደበደሌማ ከሆነ ቅጣቴ\nአያልቅም ተነግሮ ብዙ ነው ቅጣቴ\nእንጃልኝ ፈራሁ እኔስ ሰውነቴ\nእንጃልኝ ፈራሁ እኔስ ሰውነቴ\n\nእመላለሳለው እያልኩ ጠዎት ማታ\nዘመኔን ጨረስኩኝ ሳስብ ሳመነታ\nምን እመልስ ይሆን በተጠራው ለታ\nምን እመልስ ይሆን በተጠራው ለታ\n\nሞት ሲያንዣብብህ ሞት እጁን ሲዘረጋ\nሊውጠው መቃብር ተከፍቶ\nማረፍያ ወዴት ይሁን ከቶ\n\nይቅር ባይ ነህ እና የበደሉህን\nአቤቱ ጌታ ሆይ እኔ ባርያህን\nይቅር በለኝ እና ልየው ፊትህን', 'am', 143, 0),\n(5, 'አማናዊት ኪዳን', 'አማናዊት ኪዳን\nአማናዊት ኪዳን የሰው ልጆች ተስፋ\nድንግል ሆይ አማልጂን በሞት እንዳልጠፋ\n\nየአባቶች ነብያት ተስፋ ምኞታቸው\nየሀዎርያት ጣዕመ ስብከተሠቸው\nየሰማዕታት እናት የጸሠድቃን እመቤት\nደግሞም እህታቸው ከሰማይ መላዕክት\n\nየቅዱስ ኤፍሬም ድንግል ድርሰታቸው\nየነ ቅዱስ ያሬድ ድጎ ዝማሬያቸው\nየእምነታቸው ቅመም አንቺ ነሽ እውነቱ\nለአባ ጊዮርጊስ ጸሎት ሰአታቱ\n\nየአባ ጊዮርጊስ ምስጢረ ስላሴ\nየመነኮሳት ስንቅ የኤፍሬም ውዳሴ\nየሊቃውንት አበው የሚስጥር ቋንቋቸው\nየደናግል ተስፋ የጽድቅ አክሊላቸው\n\nሁኚልኝ መመክያ በሞት እንዳንሰጋ\nበዝች አለም ጣፋጭ ከቶ እንዳይወጋ\nስለሌለኝ ተስፋ በዚ አለም ስኖር\nአስታርቂኝ እመአምላክ ከቸሩ ልጅሽ\n\nጭንቀቴ እጅግ በዛ የሚያጽናናኝ አጣሁ\nፈተናው ከበደኝ ለነብሴ ፈራሁ\nደስታ ከኔ እርቆ ሲበዛ ሰላም\nአትተወኝ አንተ ሁንልኝ ከጎኔ', 'am', 144, 0),\n(5, 'የተናኩኝ ነበርኩ', 'የተናኩኝ ነበርኩ\nየተናኩኝ ነበርኩ ሰው የሚሸሸኝ\nፍጥረትን የማይንቅ እሱ አከበረኝ\n\nለበደልኩት ስርአት ስለሰጠሀኝ ታግለህ\nአይዞህ እንዳላየ ስታልፈኝ በፍቅር\nእንደቃልህ ባልኖር መታመን ቢያቅተኝ\nቅያሜውን ትተህ መልካሙን አሰበልኝ\n\nተስፋዬ መንምኖ ሰላሜን አጥቼ\nበሀዘን በስቃይ አንገቴን ደፍቼ\nሰማያዊ አምላክ አንተ አዳንከኝ\nተስፋዬን ቀጥለህ ደስታን አበሰርከኝ\n\nነብሴ ጸጥ እንድትል ጌታዬ ገሰጸው\nእንዳልጥም እርዳኝ ጉዞዬን ባርከው\nእንድወርስ እርዳኝ ሀይተረኩበ ታረኳ', 'am', 145, 0),\n(5, 'ታናሽ ሆኜ ልኑር', 'ታናሽ ሆኜ ልኑር\nሰው ቢሸሸኝ ሰው ሸሸኝ አልልም እራቀኝ\nሰው ቢጠላኝ ሰው ጠላኝ አልልም ወገን ተወኝ\nአንተ ካለህልኝ ባንተ ከታመንኩኝ\nታናሽ ሆኜ ልኑር በአለም የተናኩኝ\n\nከአጠገቤ ስለ ቸሩ መድኃኔዓለም\nደክሜ እና ዝዬ በሀጥያት ብወድቅም\nሀጥያተኛ ሰው ፈፅሞ ያማትርቅ\nበፍጡራን ዘንድ ከቶ የማትርቅ\n\nእኔስ በአንተ ቤት ብጣል ይሻለኛል\nአለም ብትሰለቸኝ መች ግድ ይለኛል\nአንተ አትሽሸኝ ከክንድህ አታርቀኝ\nከቅዱሳን ማህበር ጌታ ሆይ ደምረኝ\n\nየድንግል ማርያም ልጅ መድህን ክርስቶስ\nየሰማይ የምድር የአለም ሁሉ ንጉስ\nአምላኬም ንጉሴም ገዢዬም አንተ ነህ\nየማመሰግንህ ተስፋ የማደርግህ', 'am', 146, 0),\n(5, 'የብርሀን እናት ነሽና', 'የብርሀን እናት ነሽና\nየብርሀን እናት ነሽ እና\nየብርሀን እናት ነሽ እና\nየብርሀን እናት\nየብርሀን እናት\nለምኚልን ድንግል ለምኚ\nለምኚልን ድንግል ለምኚ\n\nጸጋን እና ክብርን የተመላሽ\nከሴቶች መካከል የተመረጥሽ\nለቃሉ ማደርያ ዙፋኑ ነሽ\nበደመና መንበር የተመሰልሽ\n\nየሽቶ ማደርያ የተቀደስሽ\nመአዛሽ ያማረ ሽቶ ያለሽ\nውዳሴሽ ብዙ ነው እናታችን\nስምሽን ስናስብ ነው መጽናኛችን\n\nበሀሳብ በግብር ፍጹም የሆንሽ\nምነኛ ብሩህ ነው ድንግል ክብርሽ\nአንቺን የሚመስል የለምእና\nይሰማል ምልጃሽ ያንቺ ልመና\n\nየብርሀን መውጫ ምስራቁ ነሽ\nሰውን በለወጠ ድልድይ ሆነሽ\nምስጋናሽ አያልቅም ለዘላለም\nማህሌት ነሽ እና በአርያም\n\nመላዕክት ፍጥረትን ያደንቃሉ\nጌታን በመውለድሽ ይመካሉ\nሰማይ እና ምድር ሳይወስኑት\nባንቺ ተወሰነ እፁብ በእውነት\n\nየሽቶ ማደርያ የቀደሽ\nመአዛው ያማረ ሽቶ ያለሽ\nውዳሴሽ ብዙ ነው እናታችን\nስምሽን እያሰብን መጽናኛችን', 'am', 147, 0),\n(5, 'እመቤታችን ምን ሆናለች', 'እመቤታችን ምን ሆናለች\nእመቤታችን ምን ሖናለች\nእመቤታችን ምን ሖናለች\nዛሬ በገነት ታለቅሳለች\nድንግል ማርያም ምን ሖናለች\nዛሬ በነገት ታነባለች\nእመቤታችን ለዮሐንስ\nሀደራ ሰጣት ጌታ እየሱስ\nሀደራ ሰጣት ጌታ እየሱስ\n\nይለመንሻል ላናቺ ለእናቱ\nእሺ ይልሻል ላንቺ ለእናቱ\nእኛንስ እንቢ አለን ጸናበት አንጀቱ\nእያማነው በገዛ መንግስቱ\n\nድንግል ማርያም ስንል ጊዜ\nድንግል ማርያም ስንል ጊዜ\nውሀው ይቆማል በትካዜ\nእመቤታችን ስትነሳ\nበድር ይሰግዳል ጎሽ አንበሳ\n\nድንግል ማርያም ስንላት\nይደሰታሉ መላዕክት\n\nአይሁድ ሲመቱት ሲሰቅሉት\nእንደምን ቻለ ያንቺ አንጀት\nማን አላቀሰሽ ማን አጽናናሽ\nማን አላቀሰሽ ማን አጽናናሽ\nአንዱ ልጅሽን ሲገሉብሽ', 'am', 148, 0),\n(5, 'ጌታ ሆይ ውለታህ', 'ጌታ ሆይ ውለታህ\nጌታ ሆይ ውለታህ ተአምር ድንቅ ነው\nአምላካዊ ቃልህ ስም ህይወቴ ነው\n\nበሀዎርያት አርገህ ብዙ መክረሀኛል\nስለ ህይወቴ ሞተህ ህይወት ሰተሀኛል\nጌታ ሆይ ውለታህ ተአምር ድንቅ ነው\nአምላካዊ ቃልህ ስምህ ህይወቴ ነው\n\nበሐዘኔ ፈጥነህ እንዳረጋጋሀኝ\nአይዞህ ልጄ ብለህ ስወድቅ ያነሳሀኝ\nከማይጠፋው እሳት ከሞት አወጣሀኝ\nላንተ የምከፍለው ምን ስጦታ አለኝ\n\nእውነተኛ ረዳት ወገኔም አንተ ነህ\nጌታ ሆይ ከእናት ልጅ እጅግ ትበልጣለህ\nመታመን ባንተ ነው ደሞም መመካት\nወቅት የማይለውጥህ የማታውቅ ወረት\n\nስምህ ምግብ ሆኖ ስጠራህ ጠግባለው\nፍቅርህን ቀምሼ ፍጹም እረካለው\nበሰማይ በምድር በነብስም በስጋ\nላንተ እገዛለው አልፋ እና ኦሜጋ', 'am', 149, 0),\n(5, 'የጥበብ ሀገሯ ወዴት ነው', 'የጥበብ ሀገሯ ወዴት ነው\nየጥበብ ሀገሯ ወዴት ነው\nማዳርያውስ ወዴት ነው\n\nቦታ ጎዳናዎ ከወዴት ተቃኘ\nዝናና ወሬዎስ ከወዴት ተገኘ\nፈልጎ የገዛት ማነው በቀይ ወርቅ\nባህሩን ተሻግሮ ስሟን በማወቅ\nባህሩን ተሻግሮ ስሟን በማወቅ\n\nማነው ያወረዳት ከደመና በላይ\nድምጾንስ የሰማ ከላይ ከሰማይ\nእሷን የሚጠሉ ናቸው እና ከንቱ\nአይቀርላቸውም ዎላ የሞት ሞቱ\nአይቀርላቸውም ዎላ የሞት ሞቱ\n\nሁሉንም በሚያውቅ እርሱ ያውቅላታል\nየህይወት ጎዳና ያሳምርላታል\nበክርስቶስ ፍቃድ በምድር ላይ ታየች\nእነሖ ቤት ሰራች ሰባት አምድ አወጣች\n\nጥበብ ግን እርሱ ነው መዳኒታችን\nበስጋ ተገልጦ እኛን አዳነን\nበደሙ ፈውስ የተዎጀን\nለእርሱ የመረጡን ይክበር ይመስገን', 'am', 150, 0),\n(5, 'እጠብቅሀለው', 'እጠብቅሀለው\nእጠብቅሀለው ደጅሽ ላይ ቆሜ\nባለውለታዬ በፍቅር ታምሜ\nእጠብቅሀለው እጆቼን ዘርግቼ\nለእንባ ሸለቆ አይኖቼን ሞልቼ\n\nመልካም በተባለች በሰለሞን መቅደስ\nእጠብቅሀለው ያልከው ቀን እስኪደርስ\nከደጅህ ተጥዬ ብዙ አመት ሆኖኛል\nድምጽህን አሰማኝ ሰላም ይሰማኛል\n\nበበረት ውስጥ መንጋ አንዳች ባይኖረኝ\nጎኔን ማስጠጋበት ዎሻማ ባላገኝ\nስደትም ብወጣ አንተ ከኔ ጋር ነህ\nበዘመኔ ሁሉ ታሪክ እየሰራህ\n\nስለ ተስፋ ቃልህ አይኖቼ ቢፈዙም\nየመከራው ጊዜ ለሊቱ ቢረዝም\nመች ይሰለቸኛል ተስፋ አደርግሀለው\nእንደምትሞላኝ እተማመናለው\n\nበለሱን ጠብቄ ፍሬውን እስካገኝ\nየሆነው እጂ ባንተ እስኪሞላልኝ\nዛሬም ከደጅህ ነኝ ከገራገራሁ\nልጄ ተነስ በለኝ ያኔ እቆማለሁ', 'am', 151, 0),\n(5, 'አቤቱ የሆነብንን አስብ', 'አቤቱ የሆነብንን አስብ\nአቤቱ የሆነብንን አስብ\nእግዚአብሔርን\nእግዚአብሔርን\nእግዚአብሔርን\nእግዚአብሔርን\n\nቅኔ ማህሌቱ በደም ረሰረሰ\nመቅደስህ ተቃጥሎ መሰዊያው ፈረሰ\nጮሁ ደናግላን ደም እንባ አፈሰሱ\nበቅዱሱ ስፍራ ታርጿል ና ቄሱ\n\nሰላም መስሎን ነበር መግባት መውጣታችን\nለካስ በእሾ ታስሯል ዙሪያው ጎዳናችን\nየፅዮን መንገዶች በእንባ ተሞልተዎል\nየሚያምረው ግንቦቿም በለሊትም ፈርሷል\n\nየቁጣህን በትር ማን ይቋቋመዎል\nየሀይልህን ጽናት ማንስ ይችለዎል\nየሽማግሌው ፊት አልታፈረምና\nእንዴት ቀና እንበል እንዴት እንጽናና\n\nእንደዘካርያስ እንደ እግዚአብሔር ወዳጅ\nወደቁ ብዙዎች መጡ ና ከአንተ ደጅ\nህጻን አዛውንቱ ጎበዞቹ ሁሉ\nሰው ለፍቅር አንክድም እያለለ', 'am', 152, 0),\n(5, 'አንድ አድርገን', 'አንድ አድርገን\nአንድ አድርገን ጌታ ሆይ አንድ አድርገን\nሰላምህን ፍቅርህንም ለግሰን\n\nቤተክርስትያን ሆይ ምነው ተረበሽ\nአንድነትሽ ጠፍቶ ሰላምን አጣሽ\nአንድኛው ሲጠቅምሽ ሌላኛው ሲጎዳሽ\nብዙ ልጆች ወልደሽ የወላድ መካን ሆንሽ\n\nበዘር እና ጎሳ ስንከፋፈል\nቅጥራችን ፈረሰ በጠላታችን\nመሳለቅያ ሆነን በየአደባባዮ\nልዮነትን አይተው ብዙዎች ተለዮ\n\nላያችን የሚያምር ልስን መቃብሮች\nአስመስለን ያለን የሀሰት አማኞች\nበመካከላችን ፍቅርን አስወግደን\nእንደ ርብቃ ልጆች እንገፋፋለን\n\nበእምነት ያልቆመው በውሸት ሲከሰን\nአንድነት ሳይኖረን ዘመንን አስቆጠርን\nያ ጥቅም ፈላጊ ስምሽን እያጠፋ\nለስጋው የሚሖን እርስቱን አሰፋ', 'am', 153, 0),\n(5, 'ሐዋርያቲሁ', 'ሐዋርያቲሁ\nሐዋርያቲሁ ከበበ እግረ አርዳኢሁ ሃጸበ\nኮኖሙ አበ ወእመ ወመሃሮሙ ጥበበ\nሃሌ ሉያ\n\nጌታ መሃላቸው ተገኝቷል\nየሐዋርያትን እግር አጥቧል\nአባትና እናት ሆናቸው\nጥበብንም አስተማራቸው\nሃሌ ሉያ\n\nየወደዳቸውን እነሱን ወደዳቸው\nበትህትና ሆኖ ይኸው አጠባቸው\nሰጣቸው ለሕይወት ሥጋውና ደሙን\nእንዲመሰክሩ እስከሞት ስሙን\n\nሥላሴን በቤቱ አስተናግዶ ነበር\nእግራቸውን አጥቦ አብርሃም በፍቅር\nዛሬ መለሰለት ይህንን ውለታ\nዝቅ ብሎ አጠበ አማኑኤል ጌታ\n\nይሁዳም ታጠበ ሳይከራከረው\nአካሉ ከጌታ ልቡ ከአይሁድ ነው\nአሳልፎ ሰጠ ደግ መምህሩን\nታሪኩን ቀይሮ ሰው ያረገውን\nሥላሴን በቤቱ አስተናግዶ ነበር\nእግራቸውን አጥቦ አብርሃም በፍቅር\nዛሬ መለሰለት ይህንን ውለታ\nዝቅ ብሎ አጠበ አማኑኤል ጌታ\n\nራሱን ዝቅ አረገ አምላካቸው ሲሆን\nምሳሌውን ተወ እንዲመስሉ እርሱን\nከእናንተ የሚሻ ታላቅ መሆንን\nበመካከላችሁ ታናሽ ሰው ይሁን\nሥላሴን በቤቱ አስተናግዶ ነበር\nእግራቸውን አጥቦ አብርሃም በፍቅር\nዛሬ መለሰለት ይህንን ውለታ\nዝቅ ብሎ አጠበ አማኑኤል ጌታ\n\nዓለምን የያዘ ፍጥረቱን የፈጠረ\nአሳልፎ የሚኖር ያለ የነበረ\nተገልጦ አየነው ልዑሉ ትሁት\nረቂቁ ገዘፈ ሊያድነን ከሞት\nሥላሴን በቤቱ አስተናግዶ ነበር\nእግራቸውን አጥቦ አብርሃም በፍቅር\nዛሬ መለሰለት ይህንን ውለታ\nዝቅ ብሎ አጠበ አማኑኤል ጌታ', 'am', 154, 0),\n(5, 'ወይን እኮ የላቸውም', 'ወይን እኮ የላቸውም\nወይን እኮ የላቸውም ብለሽ የነገርሽልን\nየቤታችን ውበት ነሽ ማርያም እናታችን\nየሚጎድለን ብዙ ነው ንገሪልን ለልጅሽ\nአንገት አያስቀልስም የእናትነት ልመናሽ\nፊትን አያስመልስም ሀይልን ያደርጋል ጸሎትሽ\n\nበገሊላ ቃና ሰርግ እና ትካዜ\nወይኑ ከዳር ሳይደርስ ባለቀበት ጊዜ\nዶኪማስ በልብ ፍርሀት ነግሶበት\nአማላጂቱ ሆይ ሆንሽለት አንደበት\nየሚላችሁን ስሙ ትይናለሽ በጥበብ\nጋኖች ውሀ ሞልተን ጸጋውን እንድንደርብ\n\nደቀ መዛሙርቱ ካንቺ አይበልጡም እና\nሁሌም ፊተኛ ነሽ በክብር በልመና\nጊዜው ገና ሳይደርስ መሐል ትገቢያለሽ\nየምንለምነውን ስጣቸው ትያለሽ\nእንዴት እንደምንለምንበት አናቅበትም እና\nበረከትን አሰጪኝ ከልጅሽ ፊት ቁሚ እና\n\nየወይን ጠጅ ባይኖር በጋኖቹ ውስጥ\nእጅግ ብንጠማ የህይወት መጠጥ\nየእየሱስ እናት ልመናሽ ተሰምቶል\nመናኛው ሲያበቃ አዲስ ወይን ፈልቋል', 'am', 155, 0),\n(5, 'የሁሉ አይን', 'የሁሉ አይን\nየሁሉ አይን አንተን ተስፋ አድርጎል\nምህረት ቸርነት ይጠባበቃል\nሸክሙ ከብዶል አቅልልን\nያላንተ ጌታ ሌላ ማን አለን\n\nያለው ይመስላል ለብሰው ሲያዩት\nላይ ታች እያለ ይዞት ጭንቀት\nየልጆቹ እንቧ ጭወት ሰልችቶት\nልመና ገባ ሙሁሩ ድንገት\n\nከዛሬ ነገ ይሻላል ስንል\nእየባሰ ሔደ አለመታደል\nአምነ ረሀብ ይሄ ይሰከናት\nብለዎል እና ደቀ መዛሚርት\n\nአሳይተሀኝ ጌታ አታንሳን\nበደል አለብን ይቅር በለን\nበወርቅ ብር ላይ ተቀምጠን\nእንራባለን ፍቅር አተን\n\nእንጨት ለቃሚ ባልቴት ነበረች\nበሰራሀት ድህነት እያለች\nበአክአብ ምክንያት ረሀብ ሆኗል\nወደ ሞት ልንወርድ ተዘጋጅተናል', 'am', 156, 0),\n(5, 'ወደ እኔ ተመልከት', 'ወደ እኔ ተመልከት\nወደ ጎስቋላዎ ወደ እኔ ተመልከት\nወደ ጎስቋላዎ ወደ እኔ ተመልከት\nበአንተ ፊት ምንድነው የኤልያብ ውበት\nበአንተ ፊት ምንድነው የኤልያብ ውበት\n\nየወደቀውን የተረሳውን ሰው\nየድሀአደጉን ልጅ የምታስታውሰው\nአውቃለው አምላኬ ይህን ልብ አድርጌ\nአንተ ነህ ክብር እና ማዕረጌ\nአንተ ነህ ክብር እና ማዕረጌ\n\nበሳሙኤል ፊት አልፋለው ጌታዬ\nበምህረትህ ነው አይደል በስራዬ\nዘይትህ ይፍላ ያንተ ልሁን እኔ\nሳበራ ልኑር ይባረክ ዘመኔ\nሳበራ ልኑር ይባረክ ዘመኔ\n\nአንተ ብቻ ነህ የምስኪኑ ተስፋ\nመግቢያ ለሌለው ቤት እና ማረፍያ\nኤልዛቤል ትፈር ስለረዳሀኝ\nድሀ ብሆንም ባለጸጋ ነኝ\nድሀ ብሆንም ባለጸጋ ነኝ\n\nአበርታው ጌታ ልቤ እንዳይፈራ\nአብረሀኝ ውጣ ትልቁን ተራራ\nአይኖቼን ገልጠህ አንተ ስታበራ\nልዘምርልህ ከልጅህ ጋራ\nልዘምርልህ ከልጅህ ጋራ', 'am', 157, 0),\n(5, 'በሰማያት ከበረ', 'በሰማያት ከበረ\nአምላካችን በሰማያት ከበረ\nበምድርም ለስሙ ተዘመረ\nአለማችን በምስጋና ተመላች\nመድሀኒቴ እየሱስ ነው እያለች\n\nአስቀድሞ በቃልነት የኖረ\nከእግዚአብሔር ጋር በክብሩ የነበረ\nስጋ ሆኖ ሲገለጥ ያ ቃል ዛሬ\nተመልታለች ምድራችን በዝማሬ\n\nጠላታችን በመስቀል ተሸነፈ\nበዙፋኑ ክርስቶስ ስላረፈ\nሰይጣን ሲያፍር እየሱስ ግን በፍቅር\nሰውን ጠራው ወደ ታላቁ ክብር\n\nየሰውን ልጅ በደሙ ዎጋ ገዝቶ\nሞትን ውጦ በመቃብር አጥፍቶ\nበሰማያት ከፍ ከፍ ብሏል እና\nለንጉሱ ይገባዎል ምስጋና\n\nነጩን እጣን በጽናው ላይ ጨምረው\nያነሳሉ ስሙን ከፍ ከፍ አርገው\nለታረደው ለነጩ በግ እያሉ\nቅዱሳኑ ምስጋናን ያቀርባሉ', 'am', 158, 0),\n(5, 'መአዛሽ ያውዳል', 'መአዛሽ ያውዳል\nመአዛሽ ያውዳል ስምሽ ይጣፍጣል\nእመቤቴ ማርያም አንቺን ማን ይመስላል\n\nየበላይ ሰብ እመቤት ነሽ እና\nየቅዱሳን መንደር መኖርያ ነሽ እና\nአሁንም ላነሳሳሽ እመቤቴ ብዬ\nስምሽን እጠራለሁ ይሻለኛል ብዬ\n\nከቤተመቅደሱ ከእጣኑ ሽታ\nመአዛሽ አወደኝ ድንግል የኔ አለኝታ\nሁሉም ይደሰታል ሳሊለነ ሲባል\nለአፍም ይጣፍጣል ማርያም ማርያም ሲባል\n\nየህይወት መቅረዝ ነሽ የብርሀን እናት\nከሁሉም ምትበልጪ ድንግል የኛ እመቤት\nአልሻም ለመኖር ካንቺ ተለይቼ\nእኖራለው እና ጸጋን ተመልቼ\n\nከቅዱሳን አንስት አንቺ ትበልጫለሽ\nከሴቶች ልጆችም የለም የሚመስልሽ\nወልድን በመውለድሽ የአለም እናት ተባልሽ\nስለዚህ ድንግል ሆይ ማነው የሚመስልሽ\nስለዚህ እመቤቴ ማነው የሚመስልሽ', 'am', 159, 0),\n(5, 'ጌታ ብርሀኔ እና መዳኒቴ ነው', 'ጌታ ብርሀኔ እና መዳኒቴ ነው\nጌታ ብርሀኔ እና መድሀኒቴ ነው\nየሚያስደነግጠኝ የሚያስፈራኝ ማነው\n\nአያሳስበኝም የሳኦል ጥላቻ\nልቤ አይደነግጥም በሳልያድ ዛቻ\nየምታመንበት ስሙ ጋሻዬ ነው\nሀይል እና ጉልበቴ ጌታ ጉልበቴ ነህ\n\nሞገስ ይሆነኛል በነገስታቱ ፊት\nእመሰክራለው ስሙን ያለፍርሀት\nአያስጨንቀኝም ሞት እና መከራ\nሁሉን የሚችለው አለ ከኔ ጋራ\n\nፃድቃንን በገዳም የሚያበረታቸው\nሰማዕታትን በጾም እንዲ ያጸናቸው\nአሁንም ይሰራል የብርሀን ጌታ\nስሙን ተሸክሞል በእምነት ለበረታ\n\nከስም ሁሉ በላይ የሚበልጥ ስም ይዞል\nየማመልከው አምላክ ከሁሉ ይበልጣል\nምንስ እሆናለው ስሙን ተደግፎ\nበእየሱስ ክርስቶስ ጥላ ስር አልፎ', 'am', 160, 0),\n(5, 'እጠበኝ ቆሽሻለው', 'እጠበኝ ቆሽሻለው\nእጠበኝ ቆሽሻለው\nአምላኬን በድያለው\nያለ እናት ያሳደከኝ ያለ አባት የጠበከኝ\nያን ሁሉ ዛሬ ረሳው እጠበኝ ቆሽሻለው\n\nከድንኳንህ ብታስገባኝ ሞገስ ሰተህ\nየአፍኒንን ምግባር ይዤ አስቀየምኩህ\nቅባ ሜሮን ያተምክበት ልጅነቴ\nእንዳይጎድል ጠብቅልኝ ቸር አባቴ\n\nሀይል አኑረህ እንደ ሶምሶን በጸጉሬ\nጎልያድን አስጥለሀኝ በጠጠሬ\nአቅም ቢያንሰኝ በስጋ ጦር ተሸንፌ\nደጅህ መጣው የእንባ አይን አቅፌ\n\nእንዳትረሳኝ በመዳፍህ ቀርጸሀኛል\nእንዳተወኝ ያለ መጠን ወደሀኛል\nፍቅር ግተህ በእቅፍህ ስር ያሳደከኝ\nእባክህን በበደሌ አትቅጸፈኝ\n\nከከንፈኔ ጥበብ ጽፈህ ቅኔ ቢፈስ\nእየታበይኩ አሳዘንኩህ ያንተን መንፈስ\nብትዘነዝር ልትቀጣኝ የሞት በትር\nሰሌዳ ነው ለኔ ክብር', 'am', 161, 0),\n(5, 'ለምን ጠላሀኝ', 'ለምን ጠላሀኝ\nለምን ጠላሀኝ ወንድሜ የአንድ አባት ልጆች እኮ ነን\nነው መንግስ አብረን እንወርሳለን\nነው ግዛቱ አብረን እንወርሳለን\n\nየተካፈልኩትን ንብረት አጥፍቼ ብመለስ ዛሬ\nአባቴ ናፍቆኝ ስመጣ ልቤን አንገቴን ሰብሬ\nለሁላችንም ይበቃል ብዙ ነው የእሱ መንግስት\nአይክፋህ ባክህ ወንድሜ ፍቅር ይበልጣል ከሀብት\n\nበሀዘን አይጥቆር ድንጋዮን ጣለው ወንድሜ\nበዝባዥ እንዳያደርግህ እጅህ ቆሽሾ በደሜ\nመልካም ብታደርግ ያንተን መሰዎዕት ያደርጋል\nለሁሉም እኩል ነው መታዘዝ ንጉስ ያደርጋል\n\nብልጥ ስለሆንኩ አደለም የተባረኩ በጌታ\nፁኑ መሻቴን አይቶ ነው በኩር ያደረገኝ ስመታ\nየጠጠር ጦርህን ሸሽቼ በባዕድ ሀገር ብኖርም\nበልጅ በትዳር ባርከኝ አብረን እንኑር በሰላም', 'am', 162, 0),\n(5, 'ቃልኪዳን ግቢልኝ', 'ቃልኪዳን ግቢልኝ\nቃልኪዳን ግቢልኝ እመቤቴ ይቃና መንገዴ\nኑሮዬም ምን ይሰምራል እመቤቴ\nአንቺን በመውደዴ እመቤቴ\nበያሬድ ውዜ እመቤቴ\nሁሌም እጠራሻለው እመቤቴ\nበመዎለ ቅዳሜ እመቤቴ\nእለምንሻለው እመቤቴ\nቃልኪዳን ግብሊኝ እመ እግዚአብሔርን\nየዎህ ልበልሽ ይርዳኝ\nካንቺ ጋር ልኑር\nፈጥነሽ ወደ እኔ ነይ እመቤቴ\nከሰማይ ዳርቻ እመቤቴ\nሚስጥሬን ሰሚ ነሽ እመቤቴ\nድንግል አንቺ ብቻ እመቤቴ\nስላሴ የሰረለሽ እመቤቴ\nየማትፈርሺ መቅረዝ እመቤቴ\nሁሌ ጠዎት ማታ እመቤቴ\nአንቺን ላወድስሽ እመቤቴ\n\nከምድር ብልጽግና እመቤቴ\nአንቺን እመርጣለሁ እመቤቴ\nፍቅርቅን ልቀበል እመቤቴ\nልቤን እሰጣለው እመቤቴ\nእንቁ ስምሽ ለኔ እመቤቴ\nክብሬ ነው እላለው እመቤቴ\nእመቤቴ ብዬ እመቤቴ\nችግሬን አረሳም እመቤቴ\n\nስምሽ ወለላ ነው እመቤቴ\nከማር ይጣፍጣል እመቤቴ\nከጥበብ ሁሉ እመቤቴ\nእጅግ ይደነቃል እመቤቴ\nይታተም ምስጋናሽ እመቤቴ\nበሁለንተናዬ እመቤቴ\nሰአሊለነ ልበል እመቤቴ\nእንዲሰዝም እመቤቴ', 'am', 163, 0),\n(5, 'እኔ እሆንን', 'እኔ እሆንን\nአላውቅህም ብዬ በሰው ፊት የምክድህ\nለጠላት አንስቼ አሳልፎ ምሰጥህ\nእኔ እሆንን ጌታ ሆይ እኔ እሆንን\nእኔ እሆንን አምላክ ሆይ እኔ እሆንን\n\nይሁዳ ነኝ ወይስ ጴጥሮስ ሀሙስ ማታ እኔ ማን ነኝ\nየዛሬን መቆሜን እንጂ አላውቅም መጨረሻዬን\nእወድሀለውኝ ብዬ የዛሬን እናገራለው\nአላውቅልህም እንዳልልህ ስለነገ ግን ፈራለው\n\nስንት ያጥቢያ ኮከቦች ላንተ ዘምረውልህ ወደቁ\nሰማይ መቅደስህን አተው በትዕቢት ረግፈው አለቁ\nእፈራለው እኔም ለራሴ መንገዱን ንገረኝ ጌታ\nጠዎት በዘመርኩበት አፍ እንዳልሳደብ በማታ\n\nሳጥናኤል መልአክ ነበረ ይሁዳም ሀዎርያ\nንስጥሮስም ጳጳስ ነበር አርዮስም ተዎርያ\nእነዚህ ሁሉ ከወጡ ከአምላካቸው ጉያ\nደካማ ለሆንኩት እማ የት ይሖን የኔ መገኛ\n\nታናሹ ጅማሬዬን አንተ ታላቅ አድርግልኝ\nነበረች ከመባል ፈተና አንተ በፍቅር አድነኝ\nያስጀመርከኝ አምላኬ ሆይ እንግዲ መንገዴን አደራ\nበፊትህ ቆሜ ለማመስገን አብቃኝ ከቅዱሳን ጋራ', 'am', 164, 0),\n(5, 'አማኑኤል ሆይ', 'አማኑኤል ሆይ\nአማኑኤል ሆይ መድኃኒቴ ሆይ\nአትተወኝ አንተ ሞትን እንዳላይ\nአትተወኝ አንተ ሞትን እንዳላይ\n\nየግብፅ ከተማ ደምቃ ስትታየኝ\nተሰሎንቄም አድጋ አይኔን ብትስበኝ\nኤልሻዳይ ኢየሱስ ልቤን መልስልኝ\nኤልሻዳይ ኢየሱስ ልቤን መልስልኝ\n\nመታመን በሰዉ ላይ ምንም አይጠቅምም\nመመካትም በሰዉ ለእኔ አይሆንም\nአትተወኝ አንተ አምላክ ዘለዓለም\nአትተወኝ አንተ አምላክ ዘለዓለም\n\nየሚያፅናናኝ የለም እኔ እንዲህ ስከፋ\nህልምም ሆኖብኛል የሰዉ ሁሉ ተስፋ\nቃልህን የማታጥፈዉ አንተ ከእኔ አትጥፋ\nቃልህን የማታጥፈዉ አንተ ከእኔ አትጥፋ', 'am', 165, 0),\n(5, 'በርተሚዮስ ነኝ', 'በርተሚዮስ ነኝ\nበርተሚዮስ ነኝ የአይነ ስውር ምስኪን\nከሩቅ የሰማሁት የጌታዬ ድምፁን\nከብዙ ሁካታ ጉርምርምታ መሃል\nየክርስቶስ ድምፁ በግልፅ ይሰማኛል\nየክርስቶስ ድምፁ በግልፅ ይሰማኛል\n\nየልቦናዬ አይን ፈጽሞ ታውሯል\nአይኔን ፈውስልኝ በርተሚዮስ ይላል\nአብዝቼ እጮሃለሁ ጌታ ማረኝ ብዬ\nበውስጤ እየታየኝ ሲምረኝ ጌታዬ\nበውስጤ እየታየኝ ሲምረኝ ጌታዬ\n\nአንተን አይሰማህም ይሉኛል ብዙዎች\nበሀጢያት ሰንሰለት ታስረሃል እቅተዎች\nስለዚህ አትልፋ ሲኦልን ጠብቃት\nእንደዚህ ቢሉኝም እጮሃለሁ ሳልታክት\nእንደዚህ ቢሉኝም እጮሃለሁ ሳልታክት\n\nየከበበውን ሰው ገለል በሉ እያለ\nበደሌን በደሙ ዋጋ እየከፈለ\nስለኔ የሞተው እየሱስ ይመጣል\nየልቦናዬን አይን ገልጦ ያሳየኛል\nየልቦናዬን አይን ገልጦ ያሳየኛል\n\nአብዝቼ እጮሃለሁ ጌታ ማረኝ ብዬ\nበግልጽ እየታየኝ ሲምረኝ ጌታዬ\nበውስጤ በደልስ ህይወቴ ዝላለች\nበአምላኬ ቸርነት ህይወት ካላገኘች\nበአምላኬ ቸርነት ህይወት ካላገኘች', 'am', 166, 0),\n(5, 'ኃይልህ ሲገለፅ', 'ኃይልህ ሲገለፅ\nኃይልህ ሲገለፅ በሰማይ\nኃይልህ ሲገለፅ በሰማይ\nአቤት ማን ይቆም ይሆን ከፊትህ\nአቤት ማን ይቆም ይሆን ከፊትህ\n\nአቤት ቀንደ መለከት ሲነፋ\nአዋጅ ሲታወጅ በይፋ\nጻድቃን ሲጠሩ ለተድላ\nምን ይሆን የእኛ ተስፋ\nአቤት መላእክት ሰማዩን ሲያርሱት\nቀድመው ሲሰሙ መባርቅት\nያልታየ እና ያልተሰማ\nድምፅ ሲሰማ ከራማ\n\nአቤት ሰባት ንፋሳት ተከፍተው\nምድርን ሲያውኳት ቀስፈው\nሲታዘዝ የባህር ሞገድ\nምድሪቷን ሊከድናት በፍርድ\n\nአቤት ሲጠሩ ጻድቃን ቅዱሳን\nመልካም የሰሩ ብሩካን\nበምድር የሰሩ ትሩፋት\nሲያቀርቡ ለአምላክ ስብሐት\n\nአቤት ኃጥአን ለፍረድ ሲቀርቡ\nከጨለማ አለም ሲገቡ\nየማይጠቅም ዋይታ ሆኖ\nመዋረድ ይሆናል አዝኖ', 'am', 167, 0),\n(5, 'ኪራላይሶን', 'ኪራላይሶን\nኪራላይሶን ኪራላይሶን ኪራላይሶን\nኪራላይሶን አማኑኤል ጌታ\nኪራላይሶን አማኑኤል ጌታ\nኪራላይንሶ በጥፊ ተመታ\nኪራላይንሶ በጥፊ ተመታ\nኪራላይሶ አለምን ሊታደግ\nኪራላይሶ አለምን ሊታደግ\nኪራላይሶን ተነዳ እንደበግ\nኪራላይሶን ተነዳ እንደበግ\nኪራላይሶን አዳምን ሊፈውስ\nኪራላይሶን አዳምን ሊፈውስ\nኪራላይሶን ቆመ ከጵላጦስ\nኪራላይሶን ቆመ ከጵላጦስ\nኪራላይሶን ኪራላይሶን\n\nኪራላይሶን ኪራላይሶን ኪራላይሶን\n\nኪራላይንሶ እጁን ቸነከሩት\nኪራላይንሶ እጁን ቸነከሩት\nኪራላይሶን አጥንቱን ቆጠሩት\nኪራላይሶን አጥንቱን ቆጠሩት\nኪራላይሶን የእሾህ አክሊል ደፍቶ\nኪራላይሶን የእሾህ አክሊል ደፍቶ\nኪራላይሶን ገዳዩን እረቶ\nኪራላይሶን ገዳዩን እረቶ\nኪራላይሶን የሁላችን በደል\nኪራላይሶን የሁላችን በደል\nኪራላይሶን ተሻረ በእርሱ ቁስል\nኪራላይሶን ተሻረ በእርሱ ቁስል\nኪራላይሶን ኪራላይሶን\n\nኪራላይሶን ኪራላይሶን ኪራላይሶን\n\nኪራላይሶን እጣ ተጣጣሉ\nኪራላይሶን እጣ ተጣጣሉ\nኪራላይሶን ልብሱን ተካፈሉ\nኪራላይሶን ልብሱን ተካፈሉ\nኪራላይሶን ለፍርድ ተወሰደ\nኪራላይሶን ለፍርድ ተወሰደ\nኪራላይሶን እንደበግ ታረደ\nኪራላይሶን እንደበግ ታረደ\nኪራላይሶን ለብሶ ከደም ሜዳ\nኪራላይሶን ለብሶ ከደም ሜዳ\nኪራላይሶን ተከፈለ እዳ\nኪራላይሶን ተከፈለ እዳ\nኪራላይሶን ኪራላይሶን ኪራላይሶ\n\nኪራላይንሶ ኪራላይንሶ ኪራላይንሶ\n\nኪራላይንሶ ሆምጣጤ አጠጡት\nኪራላይንሶ ሆምጣጤ አጠጡት\nኪራላይሶን በገመድ ጎተቱት\nኪራላይሶን በገመድ ጎተቱት\nኪራላይሶን በወንበዴው ፈንታ\nኪራላይሶን በወንበዴው ፈንታ\nኪራላይሶን ተሰቀለ ጌታ\nኪራላይሶን ተሰቀለ ጌታ\nኪራላይሶን ሁሉም ዘበቱበተ\nኪራላይሶን ሁሉም ዘበቱበተ\nኪራላይሶን በዘላለም ህየወት\nኪራላይሶን በዘላለም ህየወት\nኪራላይሶን ኪራላይሶን ኪራላይሶን', 'am', 168, 0),\n(6, 'የጥበብ ሁሉ መጀመሪያ', 'የጥበብ ሁሉ መጀመሪያ\nየእውቀት ሁለ መጀመሪያ\nእግዚአብሔርን መፍራት ነው\nይሄ ሰው ነው ትልቅ ሚሆነው\n\nሌቤ ታማኝ ነው በሄድኩበት\nእግዚአብሔርን የምወድበት\nሌቤ ታማኝ ነው በሄድኩበት\nእናት ኣባቴን ማከብርበት\nሌቤ ታማኝ ነው በሄድኩበት\nሰዎችን ሁሉ የማከብርበት\n\nአፌ ታማኝ ነው በሄድኩበት\nየአምላክ ምስጋና የሚቀርብበት\nአፌ ታማኝ ነው በሄድኩበት\nክፉ ንግግር የማይወጣበት\n\nእግሬ ታማኝ ነው በሄድኩበት\nወደ እግዚአብሔር ቤት የምሄድበት\nእግሬ ታማኝ ነው በሄድኩበት\nወደ ትምህርቴ የምሄድበት\n\nእጄ ታማኝ ነው በሄድኩበት\nየሰውን ገንዘብ የማልነካበት\nእጂ ታማኝ ነው በሄድኩበት\nወንድም እህቴን የማልነካበት', 'am', 1, 0),\n(6, 'እግዚአብሔር ይመስገን', 'እግዚአብሔር ይመስገን\nእግዚአብሔር ይመስገን ይህቺን ቀን ቀድሶ\nለሰጠን እኛ\nከያለንበት ሰብስቦ ለዚህ ያደረሰን', 'am', 2, 0),\n(6, 'ልዑል እግዚአብሔር', 'ልዑል እግዚአብሔር\nልዑል እግዚአብሔር ምስጋና ይገባሃል\nለዚቺ እለት ለዚች ሰአት በሰላም በጤና\nኣደረስከን', 'am', 3, 0),\n(6, 'ወደኔ ይመጡ ዘንድ', 'ወደኔ ይመጡ ዘንድ\nወደኔ ይመጡ ዘንድ አትከልክላቸው ሐፃናትን\nየእነርሱ ናትና መንግስተ ሰማያት\n\nእንደ ሕፃናት ካልተመለሳችሁ ተልልቆች\nአይን ያላያት የሰማይ ቤትን አትወርሷትም\nአይን ያላያት መንግስተ ሰማያት\nአትወርሷትም', 'am', 4, 0),\n(6, 'እንሂድ', 'እንሂድ\nእንሂድ ልጆች ቤተክርስቲያን\nሁልጊዜ በሰንበት ልጆች ተሰብስበን\nእንደቅዱስ ዳዊት ሐሴት ደስታን ተሞልተን\nእንሂድ ልጆች ቤተክርስቲያን\n\nቅዱስ መስቀሉና ማደሪያ ታቦቱ\nየዕጣኑ ሽታ ፀበልና እምነቱ\nወደሚገኝበት ወደአምላካችን ቤት\nልጆች ሆይ እንገስግስ ለማግኘት በረከት\n\nድንግል ከነልጇ የምትገኝበት\nመላእክት ዙሪያዋን ሁሌ የሚከቧት\nየቅዱሳን ክብር የሚነገርባት\nየሰማይ ቤታችን ቤተክርሰቲያን ናት\n\nወተት የሆነውን ቃሉን ተመግበን\nበእምነት በሐይማኖት በምግባር ጠንክረን\nእንድናድግ በጥበብ ደግሞም በማስተዋል\nሁልግዜ በቤቱ መገኘት ይገባል', 'am', 5, 0),\n(6, 'ሕፃናትን እንሂድ', 'ሕፃናትን እንሂድ\nሕፃናትን እንሂድ ወደመቅደሱ\nየአምላካችን ቤት ነውና እናቅርብ ምስጋና\n\nኑ ወደኔ ብሎ ጠርቶናልና\nኢየሱስ ክርስቶስ ይወደናል ይጠብቀናል\n\nደሙንም እንጠጣ ስጋውን እንብላ\nእናድጋለን እና በሠላም በሕይወት በጤና\nባርኮ እንዲያሳድገን አምላካችን\nእንዳትከለክሉን እንድንሄድ ወላጆቻችን', 'am', 6, 0),\n(6, 'አምላካችን', 'አምላካችን\nአምላካችን አንዴም ሶስትም ነው\nስሙም እግዚአብሔር ነው\n\nከሶስት አካል አንዱ ከድንግል ተወልዶ\nኢየሱስ ተባለ\nዓለምን አዳነ በመስቀል ተሰቅሎ\n\nበስም በአካል በግብር ሶስትነት ቢኖርም\nበስልጣን በአገዛዝ አንድእግዚአብሔር ነው\n\nቅዱስ ኃያል የተባለ\nለሕጻናት ምስጋና የፈጠረ እርሱ ነው', 'am', 7, 0),\n(6, 'ነይ ነይ ማርያም', 'ነይ ነይ ማርያም\nነይ ነይ ማርያም ወላዲተ አምላክ የፃድቃን\nእመቤት የመላእክት እህት\n\nሁላችሁ እመንዋት ከልብ አማላጅ ናትና\nበእውነት እናመስግናት እናወድሳት አማላጅ\nኪዳነ ምህረት', 'am', 8, 0),\n(6, 'እናክብር ወላጆቻችንን', 'እናክብር ወላጆቻችንን\nእንዱረዝም እድሜያችን ስንኖር በምድር\nበረከት ምርቃት ለእኛ እንዲበዛልን\nማክበር ይገባናል እናት አባትን\nማክበር ይገባናል ወንድም እህትን\nእናክብር ወላጆቻችንን\n\nእናት አባት ማክበር የእግዚአብሔር ሕግነው\nከአስርቱ ትዕዛዛት ሦስተኛው ይሄ ነው\nበዚህ ምድር ሳለ ጌታ ፈፅሞታል\nለድንግል እናቱ በመታዘዝ አድጓል\n\nበፍቅር በትህትና እኛም እንፈፅመው\nየመታዘዝ ፍሬ ዋጋውም ብዙ ነው\nይስሐቅ ቢታዘዝ ነፍሱን እስከ መስጠት\nበእሱ ላይ ኣደረ የአባቱ በረከት\n\nየእናት ምርቃት እድልን ያቃናል\nየአባት ምርቃት እድሜን ያስረዝማል\nእንታዘዝ በቅን ሁላችን ሕጻናት\nእኛም እንድናገኝ የይስሐቅን በረከት', 'am', 9, 0),\n(6, 'ፍልሰታ', 'ፍልሰታ\nየፍቅር የሰላም የደስታ ጾማችን\nከጌታችን እናት በረከት ማግኛችን\nፍልሰታ መታለች እጅግ ደስ ይበለን\nሁላችን እንሂድ ልጆች ተሰብስበው\nፍልሰታ የህፃናት ደስታ\nእንሂድ ቅዳሴ ከቅዱሱቦታ\n\nሐዋርያው ቶማስ ትሳኤዋን አይቶ\nከእመቤታችን ሰበኗን አግኝቶ\nየተደሰተባት የበረከት ጾም ናት\nፍልሰታ መታለች እንሂድ ለፀሎት\n\nመንፈሳዊ ቅናት ሐዋርያት ቀንተው\nእነሱም ለማየት ትንሣኤዋን ሽታው\nበህብረት በመሆን ጠይቀው በእምነት\nትንሣኤዋን አዩ በፆምና ፀሎት\n\nሁልጊዜ በዓመት የምንናፍቃት\nበፍቅር ምንፆማት ለማግኘት በረከት\nፍልሰታ መታለች ኑ እንማርባት\nፍልሰታ መታለች ኑ እንቁረብባት', 'am', 10, 0),\n(6, 'አምስቱ አዕማደ ምስጢር', 'አምስቱ አዕማደ ምስጢር\nአምስቱ አዕማደ ምስጢር እነማን ናቸው\nእንማራቸው እነዚህ ናቸው እንወቃቸው\nምስጢረ ሥላሴ\nምስጢረ ስጋዌ\nምስጢረ ጥምቀት\nምስጢረ ቁርባን\nትንሳኤ ሙታን\n\nምስጢረ ሥላሴ\nየእግዚአብሔርን አንድነትን ደግሞምሶስትነት\nምስጢረ ሥላሴ ነው የምንማርበት\nለአብርሃም አባታችን የተገለፀለት\nበዘፍጥረት ምዕራፍ አስራ ስምንት\n\nምስጢረ ስጋዌ\nአምላክ ወደኛ መጣ ከሰማያት ወርዶ\nአዳነን ሰው ሆኖ ከማርያም ተወልዶ\nይህን ምስጢር አምላክ ሰው ሆነበት\nምስጢረ ስጋዌ ነው የምንማርበት\n\nምስጢረ ጥምቀት\nበኤፌሶን መልክት ምዕራፍ አራት\nእንደተፃፈው ጥምቀት አንዲት ናት\nየእግዚአብሄርን ልጅነት የምናገኝባት\nምስጢረ ጥምቀት ሁለተኛ ልደት\n\nምስጢረ ቁርባን\nደሜን ከጡ ስጋዬንም ብሉ\nብሎ ተናግራል ጌታ በወንጌሉ\nየዘላለም ህይወት ለማግኘት ሁላችን\nምስጢረ ቁርባንን መቀበል አለብን\n\nትንሳኤ ሙታን\nጌታችን ሲመጣ በመጨረሻው ቀን\nፍጥረታት በሙሉ ይነሳል ከሙታን\nእንደማንቀር እኛም ፈርሰን በስብሰን\nበፍፁም እናምናለን ትንሳኤ ሙታንን', 'am', 11, 0),\n(6, 'ሰንበት ትምህርት ቤቴ', 'ሰንበት ትምህርት ቤቴ\nሰንበት ትምህርት ቤቴ ማሪያዬ\nስላንቺ ሳስብልሽ ይመጣል እንባዬ\n\nሰንበት ትምህርት ቤቴ ትዝታሽ አያልቅም\nሳስብሽ እኖራለው እስከ ዘለአለም\n\nማርያም እናቴ አንቺው ነሽ ሐይወቴ\nየምታማልጂኝ ከቸሩ አባቴ\nእኔም ላመስግንሽ ገብቼ ሰንበቴ', 'am', 12, 0),\n(6, 'ማርያም ፊደል', 'ማርያም ፊደል\nማርያም ፊደል የሁሉም መማርያ\nበንፅህና ተፅፋለችና', 'am', 13, 0),\n(6, 'ቅዱሳን መላእክት', 'ቅዱሳን መላእክት\nበእለተ እሁድ ነው የተፈጠሩት\nበኢዮር በራማ በኤረር የሚኖሩት\nእጅግ ብዙ ናቸው የማይቆጠሩ\nቅዱሳን መላእክት ፍፁም የከበሩ\nቅዱሳን መላእክት የእግዚአብሔር ሠራዊት\n\nቅደስ እግዚአብሔር እያሉ\nያለምንም እረፍት ያመሰግናሉ\nምግብና መጠጥ እረፍት ልብሳቸው\nቅዳሴ ዝማሬ ምስጋና ስራቸው\n\nየሰውን ልመና ምስጋናና ጸሎት\nየእግዚአብሔርን ምህረት ይቅርታ ቸርነት\nከእግዚአብሔር ወደ ሰው ከሰው ወደ\nእግዚአብሔር\nመልእክት የሚያደርሱ በፍጥነት በመብረር\nመስጠት ይገባናል ለመላእክት ክብር\n\nየሚፈሯቸውን ሰዎች ሚጠብቁ\nበክፉ መከራ ችግር እንዲይወድቁ\nእንዳይቃጠሉ በነደደ እሳት\nእንዲይነከሱ በተራቡ አናብስት', 'am', 14, 0),\n(6, 'ፊታችንንና መላ ገፃችንን', 'ፊታችንንና መላ ገፃችንን\nፊታችንንና መላ ገፃችንን\nበትምህርተ መስቀል እናማትባለን\nበስመ አብ ወወልድ ወመንፈስ ቅዱስ\nአሐዱ አምላክ አሜን አሜን አሜን\n\nበቤተ ከርስቲያን በፊቱ ቆመን\nምስክር አድርገን ድንግል ማርያምን\nበሥላሴ አምነን እየተማፀንን\nእንክደዋለን ጠላት ሰይጣንን\n\nእናከብርሃለን የሁላችን ጌታ\nላንተ እንገዛለን ከጠዋት እስከ ማታ\nየአምላኮች አምላክ የጌቶችም ጌታ\nየነገስታት ንጉስ ሁሉ አለኝታ\nየነገስታት ንጉስ አልፋና ኦሜጋ', 'am', 15, 0),\n(6, 'የቃልን ወተት', 'የቃልን ወተት\nየቃልን ወተት የምትመግበን\nቅዱስ ሚካኤል ጠባቂችን', 'am', 16, 0),\n(6, 'እግዚአብሔር ይመስገን', 'እግዚአብሔር ይመስገን\nእግዚአብሔር ይመስገን\nማታ ስንተኛ የሚጠብቀን\nእግዚአብሔር ይመስገን\nጠዋት ስንነሳ የሚጠብቀን\nእግዚአብሔር ይመስገን\n\nእንቅልፍን ጨርሰን ስንነሳ\nከአልጋ እግዚአብሔር ይመስገን\nፀሀይ ስትወካ ላሊቱ ሲነጋ\nእግዚኣብሔር ይመስገን\nበዴንበት ሁላ ትጠብቀናለህ\nእግዚአብሔር ይመስገን\nየሕጻናት አምላክ አንተ ብቻ እኮ ነህ\nእግዚአብሔር ይመስገን\n\nስንወጣ ስንጋባ የሚጠብቀን\nእግዚአብሔር ይመስገን\nእውቀት እንዲገባን ልብ የምትሰጠን\nእግዚአብሔር ይመስገን\nበሰላም አውሎ በሰላም ያስሻል\nእግዚአብሔር ይመስገን\nየአምላካችን ማዳን እኛን ይጠብቃል\nእግዚአብሔር ይመስገን', 'am', 17, 0),\n(6, 'ትልቅ እንሆናለን', 'ትልቅ እንሆናለን\nትልቅ እንሆናልን\nእግዚአብሔርን ይዘን\nትልቅ እንሆናለን\nጠንክረን ተምረን\n\nጎበዝ አድርጎ ፈጥሮናልና\nአዕምሮ ኬና ሰጥቶናልና\nሌጆች በሙሉ ስራን ውደዱ\nበሰነፍ መንገዱ እንዳትሄዱ\n\nመሬትን ማረስ ሰውን ማስተማር\nየታመመውን ማከም ማፍቀር\nንብረት መጠበቅ ማደግ ነግዶ\nመስራት ቅዱስ ነው ወጥቶና ወርዶ', 'am', 18, 0),\n(6, 'ሕጻናቶች', 'ሕጻናቶች\nሕጻናቶች ክርስቶስን እንወዳለን\nከፊቱ ለመቅረብ እንፋጠናለን\n\nለሆሳዕና ዕለት ሲዘምሩ ሕጻናት\nበረከት አገኙ ከአምላክ ምርቃት\n\nክርስቶስ ድንግልን ይታዘዛታል\nእናቱን ያከብራል በጣም ይወዳታል\n\nስለዚህ ሕጻናት እኛ ሁላችንም\nእናት አባታችን ማክበር አለብን', 'am', 19, 0),\n(6, 'እኛ የማርያም ልጆች', 'እኛ የማርያም ልጆች\nእኛ የማርያም ልጆች\nዘወትር ሁሌ ሳንሰለች\nእናመሰግናለን\nጌታን እና ድንግልን\n\nእመቤቴ ማርያም ምን ሆናለች\nአንገቷን ደፍታ ታለቅሳለች\nልወስድሽ ነው ብሎ ጌታን ሲነገራት\nመሞት የለብኝም ስትል የእኛ እናት\n\nሲያስጎበኛት የሲኦልን ነፍሳት\nልሂድ አለች ልታማልድ የኛ እናት\nእመቤቴ ማርያም ወዴት አለች\nሞቷስ እንዴት ነው መቼ አረፈች\n\nድንግል በጥር ስትሞት\nአይሁድ ሊያቃጥሏት\nወረዱና መላእክት\nወደ ገነት ወሰዷት\nሐዋርያት በአንድነት\nትንሳኤዋን ለማየት\nበጾም ጸሎት ኣምላክን\nበአንድ ልብ ለኑት\n\nጌታም ተቀብሎ ጾም ጸሎታቸውን\nነሐሴ ሰጣቸው ቅዱስ ስጋዋን\nሞቷ በጥር ነሐሴ መቃብር\nልጆች በአንድነት በእምነት\nእንጠራለን ድንግልን በጸሎት\nእንድትባርከን ከሊጂ ጋር\nነይልን እያልን እንዘምራለን', 'am', 20, 0),\n(6, 'ልጆች ልጆች', 'ልጆች ልጆች\nልጆች ልጆች ደስ ይበለን\nአምላካችን ስለሆን\nሕጻናት ሁላችን ደስ ይበለን\nአምላካችን ስለሚወደን\nየአምላካችን ፍቅሩ በዚሀ ይታወቃል\nከፍጥረታት ሁሉ እኛን ለይቶናል\nግሩም ድንቅ አድርጎ በአምሳሉ ፈጥሮናል\nኋላ ከጠፋንበት ከበለስ ስር ወድቀን\nቸሩ እረኛችን መጣ ሊፈልገን\nፈልጎም አገኘን ሌጆቹ አደረገን\nሕጻናት ወደኔ ቢመጡ መልካም ነው\nመንግሥተ ሰማያት እንዲሁ ላሉቱ ነው\nበማለት ለህዝቡ ጌታ ነራቸው\n\nእርሱ አስቀድሞ ወዶናልና\nሕጻናት ልንሆን መርጦናልና\nእንወደዋለን ሞቶልናልና\nደግሞም አይተነዋል የጌታ ፍቅሩን\nወደ እቅፉ ሲሰበስበን\nክፉ እንዲይነካን ሲጠብቀን\n\nበታላቅ ፍቅሩ ደህንነትን ሰጥቶናል\nከእግዚአብሔር ተወልደን ልጆች ተብለናል\nባሮች አይደለንም ነጻነት ሰጥቶናል\nነጻነት አገኘን እኛ ሁላችን\nለቸሩ ኣምላካችን እንዘምራለን\nበእኛ ደስ እንዲለዉ ዘወትር እንተጋለን', 'am', 21, 0),\n(6, 'ስለዚህ ሁሌ ጊዜ እንመካለን', 'ስለዚህ ሁሌ ጊዜ እንመካለን\nሰዎች ቢያስቀሩንስ መቼ እንቀራለን\nዘለዓለም በቤቱ እንኖራለን', 'am', 22, 0),\n(6, 'ኣምነ እምነ ንኢ', 'ኣምነ እምነ ንኢ\nኣምነ እምነ ንኢ\nበሰላም ንኢ ማርያም', 'am', 23, 0),\n(6, 'አንቲ ውእቱ', 'አንቲ ውእቱ\nአንቲ ውእቱ ተስፋሁ ለአዳም\nሐመ ይሰደድ እምገነት\nትርጉም\nአንቺ ነሽ ተስፋው ለአዳም ኪዳነ ምህረት\nበተሰደደ ጊዜ ከገነት', 'am', 24, 0),\n(6, 'የኪዳን ፅላት', 'የኪዳን ፅላት\nየኪዳን ፅላት የተሰወለ መና ያለብሽ ደብተራ\nድንካን አንቺ ነሽ\nይኃውም መና የተባለው በድንግል ማርያም\nያደረው የእግዚአብሔር ኣብ ልጁ ነው', 'am', 25, 0),\n(6, 'ባርከን ባርከን', 'ባርከን ባርከን\nባርከን ባርከን ልጆችህን ባርከን\nበቅዱሱ ስምህ እኛ ተሰብስበን\nተራዳዩ መላክ ሚካኤል ሆይ ባርከን', 'am', 26, 0),\n(6, 'መድሐኔአለም ወሐቤ ሰላም', 'መድሐኔአለም ወሐቤ ሰላም\nመድሐኔአለም ወሐሴ ሰላም\nይክበር ይመስገን ለዘለአለም', 'am', 27, 0),\n(6, 'እህቴ ሆይ', 'እህቴ ሆይ\nእህቴ ሆይ ስሚኝ ለአንዳፍታ\nስለሰው ልጅ ምን ሆነ ጌታ\nስለስው ልጅ ከሰማይ ወርዶ\nተሰቀለ ክበሩን አዋርዶ\n\nአምላክ ሲሆን ደግሞም ሃያል\nማን ሰቀለው ምን አይነት ሃይል\nበፈቃዱ ሳይገደድ ስጋን ለብሶ\nበመወለድ\n\nበምን ምክንያት በማን ዘመን\nየፈፀመው ጌታ ቃሉን\n\nበሄሮርስ ዘመን በግፍ ተከሶ\nተፈረደበት ለሞት ጨርሶ\nማን ፈረደ ጌታን ወንጅሎ\nበማን ዳኝነት ምንስ ተብሎ\nበጲላጦስ ፊት እንደቀረበ\nከደሙ ንፁሕ ነኝ ብሎ ታጠበ\nበልማዳቸው ጌታን ሲቀጡት\nማን ተፈታ በማን ለወጡት\nተፈርዶበት ሲታሰር ጌታ\nበእርሱ ፈንታ በርባን ተፈታ\nጌታ ተይዞ በወታደር\nሲወድቅ ሲነሳ ሲገፈተር\nአይኑ በእራፊ በጨርቅ ታስሮ\nበአራት መአዘን ተወጥሮ\nስቃይ በዝቶበት የግፍ ግፍ\nጀርባው በጅራፍ ሲገረፍ\nሴቶች በሃዘን ሲያለቅሱ\nአካሉ ዝሎ ሲወድቅ እሱ\nደግሞም ተነስቶ እንደገና\nመስቀሉን አዝሎ ጎንበስ ቀና\nቀራንዮ ላይ እንደወጣ\nተከፋፈሉት ልብሱን በእጣሪ\nበመጨረሻም ተሰቀለ\nቅዱስ መስቀል ላይ ስጋው ዋለ\nጨረቃም ፊታ ደም መሰለ\n\nድንጋይ አለቱ ተከፈለ\nእናቱ ማርያም በሀዘን ኖራ\nዩሃንስ ቆሞ ከእርሳጋራ\nተገኝተው ነበር በዚያ ስፍራ\nተጠማው ብሎ ጥያቄ ስያቀርብ\nቆምጣጤ ሰጡት የአይሁድ ህዝብ\nበስቃይ በጣር እንደቆየ\nነብሱ ከስጋው ተለያ\n\nወዲያው ቀብረውት እንዳበቁ\nመቃብሩንም አስጠበቁ\nሶስት ቀን ሶስት ሌሊት እንዳለፈ\nሞትን መቃብር አሸነፈ\nምስጋና\nለሃያሉ ጌታ ዳቢሎስን ለረታ\nህሙማንን ለፈወሰ ደካሞችን ላበረታ\nምስጋና\nደስታ\nዳቢሎስ ታሰረ አዳም ነፃ ወጣ\nከእግዲህም ሆነ ፍስሐ ወሰላም ደስታ', 'am', 28, 0),\n(6, 'ስለ ጌታ', 'ስለ ጌታ\nስለ ጌታ ሰው መሆን\nየተናገረው ሰው ማን ይሆን\nነብዩ ኢሳያስ በመንፈስ ተሞልቶ\nዘምሮለት ነበር ቃሉን አሰምቶ\n\nስለ ድንግል ንፅህና\nየተናገረው ሰው ማን ይሆን\nነብዩ ሕዝቅኤል ስለሷ\nበድንግልናዋ ስለ መፅነሷ\n\nአዳም በስተቱ ከገነት ተባሮ በረረ ተባረረ\nበምድር ኑር ተባለ\nምድርም ሙት ኣለችው\nእሾህና አሜኬላ ሰጠቸው\nአምስት ሺ አምስት መቶ\nሊያድነው ጊታ ሞቶ\nዘመኑ ተፈፅሞ\nአዳምም እጅግ ታሞ\nአንዲት ንፅህት ተወለደች\nለአዳም ቤዛ የሆነች\nቤተመቅደስ አደገች\nድንግል ዜና ብስራት\nገብርኤል አበሰራት\nድንግልም አመነችው\nይሁንልኝ አለችው\n\nጌታ ከእርሷ ተወለደ\nሰውን ፍጹም ወደደ\nአዳም በድሎ በመጣው ካሳካ\nወልደ እግዚአብሔር ከሰማይ መጣ', 'am', 29, 0),\n(6, 'ስሟ ማነው', 'ስሟ ማነው\nስሟ ማነው\nማርያም ድንግል\nየትኖራለች\nመንግስተ ሰማያት\nውዳሴ ማርያም ማን ፃፈላት\nቅዱስ ኤፍሬም\nቅዳሴ ማርያም ማን ፃፈላት\nአባ ህርያቆስ\nአንቀፀ ብርሃን ማን ፃፈላት\nቅዱስ ያሬድ\nመላእክት በሰማይ ያመሰግኗታል\nምን እያሉ\nይዌድስዋ መላእክት ለማርያም\nበውስተ ውሳጤ መንጦላዕት ወይብልዋ\nበሃኪ ማርያም ዳሴዎ ዕዋ', 'am', 30, 0),\n(6, 'አባቴን ያያችሁ', 'አባቴን ያያችሁ\nጠያቂ: አባቴን ያያችሁ\nተጠያቂ: አላየንም እካችሁ\nአባቱ ዘርዓ እንጦስ\nእናቱ ትዮብስታ\nወንድሞቹን ያያችሁ\nእህቶቹን ያያችሁ\nዱድያኖስ የሰየፈው\nአላየንም መሰየፉን\nሰባት አክሊል ያገኘው\nአላየንም ፅናቱን\nምልክቱ ነጭ ፈረስ\nአውቀነዋል ሰማእቱን\nስሙ ነው\nመክብበ ሰማእት ቅዱስ ጊዮርጊስ ነው', 'am', 31, 0),\n(6, 'መጽሐፍ ቅዱሴን', 'መጽሐፍ ቅዱሴን\nመጽሐፍ ቅዱሴን እወዳታለሁ\nዘወትር ሁሌጊዜ አነባታለሁ\nየአምላኬን ቃል ትነግረኛለች\nሁሉን በዝርዝር ምንም ሳትሰለች\n\nወላጆቼንም እንዳከብራቸው\nትነግረኛለች እንድወዳቸው\nባልእንጀራህን ልክ እንደራስህ\nውደድ ትለኛለች መጽሐፍ ቅዱሴ\n\nክፉን ጠልቼ መልካም እንድወድ\nእንድመላለስ በጽድቅ መንገድ\nጣፋጩን ታሪክ እያስተማረች\nጣፋጭ እንድሆን ታደርገኛለች\n\nየቃልን ወተት እየተመገብን\nመኖር እንድንችል እኛ ሁላችን\nማንበብ ይልመድብን መጽሐፍ ቅዱስን', 'am', 32, 0),\n(6, 'አንቺ ተዋህዶ', 'አንቺ ተዋህዶ\nአንቺ ተዋህዶ ጥንት ነበርሽ አሁንም\nቀደምት ነሽ ከሁሉም የሚመስልሽ የለም\n\nቅዱስ ባኮስ ጃንደረባው\nእልል መፅሃፉን ሲያነበው\nትንቢተ ኢሳያስን አተኩሮ ቢያየው\nቅዱስ ፊሊጶስ ነው ስላንቺ ያስተማረው\nበእውነት\nተዋህዶ ንፅህት እምነቴ አንቺ ነሽ የእውነትቤቴ\n\nእንዲህ እያለ ነው ምስጢርሽን ያብራራው\nየጌታ ህማሙን በእውነት ያስተማረው\nሲሰብክ\nሐዋርያት የሰበኩሽ ያስተማሩሽ\nጠባብ መንገድ የእውነት መንገድ ተጓዝንብሽ\n\nበሸላቾቹ ፊት ዝም ያለ በግ ነው\nያፀናሽ መስርቶ ለኛ ለምናምነው\nመስርቶ ያጸናሽ በደሙ ለቤዠሽ\nእናት ተዋህዶ ያኑረን በቤትሽ', 'am', 33, 0),\n(6, 'ታቦቷ', 'ታቦቷ\nታቦቷ ክርስቶስ ሰምራ አማላጂቱ\nበፀበላ ፈወሰቸኝ በእምነቷ አዳነችኝ\nምእመናን ደስይበላችሁ በጥብብ አደኩላችሁ\nደጋግሜ ቆረብኩላችሁ', 'am', 34, 0),\n(6, 'እንዘምር', 'እንዘምር\nቃለን በአንደበታችን ጽፈን\nትምህርት ሃይማኖት ተማሩ\nየስህተት ሕይወት እትምሩ\n\nበአምላክ ትዕዛዝ ለማደግ\nልቦናችን እውነት ይፈልግ\nዳዊት ይናገር መልካሙን ነገር\nጳውሎስ ይመስክር የእውነት ምስክር\n\nበማውስ መንገዴ የሰው ሌጅ ሲነጉድ\nጌታ በሠለሸ ተመለስ ይላል\nኢየሩሳሌም ኑ ተሰብሰቡ\nየሰላም ኑሮ እንዳለ አስቡ\n\nሆነን በአንድነት በማርያም ቤት\nበፍቅር ከበን መኖር አለብን\nበዛ ከጸናን በረከት አለን\nቢኖሩ ቤቱ ብዙ ነው ሀብቱ\nአያልቅም ሰጥቶን ጸጋና ምህረቱ\n\nበመንፈሱ ስንቅ እንድንሰንቅ\nቃሉን እናውራ የጌታን ስራ\nመዝሙር እንዘምር ለአምላክ ክብር\nዝም አይበል ልሳን መስቀለን ይዘን\nለሰማይ ንጉሥ ለዓለም ጌታ\nምስጋና እናቅርብ ዘወትር ጠዋት ማታ', 'am', 35, 0),\n(6, 'አስርቱ ትዕዛዛት', 'አስርቱ ትዕዛዛት\nአስርቱ ትዕዛዛት እግዚአብሔር የሰጠን\nእኛም እነሱን እንማራለን እንሰራለን\n\nመጀመሪያው ትዕዛዝ - ከኔ በቀር ሌላ አምላክ አታምልክ、\nሁለተኛው ትዕዛዝ - የተቀረፀ ምስሌ ለራስህ አታድርግ 、\nሶስተኛው ትዕዛዝ - የእግዚአብሔርን ስም በከንቱ አትጥራ\n\nአራተኛው ትዕዛዝ - ሰንበትን አክብር、\nአምስተኛው ትዕዛዝ - እናት አባትህን አክብር\nስድስተኛው ትዕዛዝ - አትግደል\n\nሰባተኛው ትዕዛዝ - አታመንዝር፤\nስምንተኛው ትዕዛዝ - አትስረቅ\nዘጠነኛው ትዕዛዝ - በባልንጀራህ ላይ በኀሰት አትመስክር、\nአስረኛው ትዕዛዝ - የባሌንጀራህን ቤት አትመኝ', 'am', 36, 0),\n(6, 'በዚያች ሰዓት', 'በዚያች ሰዓት\nበዚያች ሰዓት በዚያች ሌሊት\nየድንግል ማርያም የኛ እናት\n\nበዛ በበጋ\nመውለጃ ከፍቶ ፍለጋ\nመሸባትና በረት ገባች\nበረት ገባች የአምላክ እናት\n\nህፃን ልጃንም ወለደችው በከብቶቹ ቤት\nየሚለብሰው ልበስም አልነበረም አለቀሰባት\n\nየሰው ልጅማ በካም ጨከነ\nእንስሳት እንኳን ለሰው ተሸለው\nሰቡት ትንፋሻቸውን\n\nእረኞችም እንዲህ አሉ\nበሰማይ ምስጋና ይሁን በምድር እርቅና ስላም\nእርቅና ሰላም በምድር ይሁን', 'am', 37, 0),\n(6, 'በዚያ ተራራ', 'በዚያ ተራራ\nበዚያ ተራራ ማርያም ተወልዳ ከሐና\nሙታን አስነሳች በማሀፀን ሆና\n\nይህንን ስታይ ገረማት ሃና\nየኢያቄም ፀሎት የሐና ልመና\nልጅን ሰጣቸው ጌታ ሰማና\nእልል እሉ በአንድነት\nሰምሮላቸው የእነርሱ ፀሎት\nትንቢት ነበር የነብይ ቃል\nከሊባኖስ ፀሐይ ይወጣል\nተፈፀመ ደርሶ ጊዜው\nይህንን እውነት እኛም እየነው', 'am', 38, 0),\n(6, 'የፅድቅ መንገድ', 'የፅድቅ መንገድ\nየፅድቅ መንገድ ያያችሁ\nቤተክርስቲያን ምን አለ\nየእግዚአብሔር ምህረት አለ\nቤተክርስቲያን ምን ኣለ\nፍቅርና ሰላም አለ\nይቺ ምንድናት\nየእመቤታችን ሰበን ናት\nከላይ ልን ንፁ ለመሆን\nከሕፃናት ማን አለ\nቂርቆስም አለ\nሚናስም አለ\nዳግማዊ ጳውሎስ አለ\nየኛ ልጅ በርቺ በርቺ\nከዲያብሎስ አምልጪ\nልብሽን ለአምላክ ስጪ\nወደጽድቁ ቅረቢ\nበምህረት ቤቱ ግቢ', 'am', 39, 0),\n(6, 'አስር ሰማያዊ ትዕዛዛት', 'አስር ሰማያዊ ትዕዛዛት\nአስር ሰማያዊ ትዕዛዛት\nአሉን ህግጋት\nድንገት አንዱን ስተን ብናፈርስ እንዳንከሰስ\nመማፀን አለብን ፈጣሪን ይቅር እንዲለን\n\nከእግዚአብሔር በቀር አታምልክ ትዕዛዝ አንድ አላህ\nአትጥራ በከንቱ ያምላክን ስም ትዕዛዝ ሁለትም\nይላል የሰንበትን ቀን አክብር ሦስተኛው ምክር\n\nበአራተኝነት የሚገኘው ወላጅ ማክበር ነው\nአምስተኛው ትዕዛዝ የሚለው እንዳትገድል ነው\nማመንዘርን የሚያወግዘው ትዕዛዝ ስድስት ነው\n\nእንዳትሰርቅ በስህተት በትእዛዝ ሰባት\nበሐሰት እንዳትመሰክር ትዕዛዝ ስምንት ስር\nየሰውን ገንዘብ አትመኝ አትመኝ በትእዛዝ ዘጠኝ\nባልንጀራን እንደራስ መውደድ አስረኛው አምድ\nመደምደሚያው የክርስትና ፍቅር ነው', 'am', 40, 0),\n(6, 'ቂርቆስ ህጻን', 'ቂርቆስ ህጻን\nእንደ ሦስቱ ህጻናት ቂርቆስ በረታ\nበእቶን እሳት ውስጥም ገባ\nእናቱንም መራ ወደ ገነት\nየ፫ ዓመት ህጻን ቂርቆስ ሰማዕት\n\nእኛ ልጆቹ ምልጃውን አምነን\nጌታን አክብሮ ለሰበሰበን\nበማኅቶትም በጸዳል ያየው\nበሰረገላ ስጋው ያረገው\nቂርቆስ(3) ህጻን አማልደን እኛን ልጆችህን\n\nአርጌቤናዮን ከሮም ከተማ\nበህጻን አንደበት ድምጽ ተሰማ\nመልክህና ውበትህ ቂርቆስ ደምግባትህ\nበንጉሱ ፊት አንተን ቢያስወድድህ\nልጅ እንድትሆነው ንግስናን ሰጥቶህ\nለጣኦት ስገድ ብሎ ማለደህ\n\nቂርቆስ ከፈጣሪዬ ቂርቆስ\n‹‹ ከከአማላኬ በቀር\n‹‹ አትስገድ ተብሎ\n‹‹ ተጽፎ ነበር\n‹‹ ብለህ ነገርከው\n‹‹ ለእስክንድሮስ\n‹‹ በህጻን አንደበት\n‹‹ ወንጌልን ሰበክ\nቂርቆስ(3) ህጻን አማልደን እኛን ልጆችህን\n\nአትፍሪ አልካት እናትህን\nነጎድጓድ ድምጹ ሲያርድ ልቧን\nጸለይክ ወደ አምላክ በቅን ልቡና\nያበረታት ዘንድ ቀና አልክና\nፍሬ ያለ ግንድ እንዴት ይሆናል\nአንተ አበርታት ልቧ እንዲጸና\n\nቂርቆስ የእናትህን\n‹‹ ጣቶቿን ይዘህ\n‹‹ እየመራሀት\n‹‹ ገባህ ወደ እሳት\n‹‹ ለእናትህም \n‹‹ አባት ሆነሃት\n‹‹ እሳቱ ሳይሆን\n‹‹ ገነትም ታያት\nቂርቆስ(3 ) ህጻን አማልደን እኛን ልጆችህን\n\nየራማው መልአክ ገብርኤል መጣ\nከእቶን እሳት አንተን ሊያወጣ\nየፀጉርህ ጫፎች ሳይቃጠሉ\nገብርኤል ገባ ከነበልባሉ\nነጎድጓድ ዲኑ ስለበረደ\nንጉሱ አፈረ ልብሱን ቀደደ\n\nቂርቆስ የእምነትህ ጽናት\n‹‹ የአንተ ብርታት\n‹‹ ዛሬም ያበራል\n‹‹ በእኛ ህይወት\n‹‹ በቃል ኪዳንህ\n‹‹ በፍቅርህ ቂርቆስ\n‹‹ እንኖራለን\n‹‹ በአንተ ቤተመቅደስ\nቂርቆስ(3) ህጻን አማልደን እኛን ልጆችህን\n\nብላቴናው የ3 ዓመቱ\nሆነ ሰማዕት ቂርቆስ ከነእናቱ\nበሮም ከተማ ገድል ሊፈጽም\nአንገትን ሰጠ እንደ ጳውሎስ\nደምና ውሃ ፈሰሰ ወጣ\nቃሉን በእምነት ፈጽመህ ጸና\n\nቂርቆስ በጥር 15\n‹‹ በባለ እዳው\n‹‹ ስጋህ አረፈ\n‹‹ በሰረገላው\n‹‹ ዕርሃብ ጥማቱን\n‹‹ ክፉ ቁራኛ\n‹‹ እንዳይደርስብን\n‹‹ ለመንክ ስለእኛ\nቂርቆስ(3) ህጻን አማልደን እኛን ልጆችህን', 'am', 41, 0),\n(6, 'የጽድቅን መንገድ', 'የጽድቅን መንገድ\nየጽድቅን መንገድ ያያችሁ ቤተክርስቲያን ነው ባካችሁ (፪)\nቤተክርስቲያን ምን አለ ፍቅርና ሰላም አለ\n‹‹ ‹‹ የእግዚአብሔር ምህረት አለ\nይህች ምንድናት የእመቤታችን ሰበን ናት(፪)\nሳላይ ልመን ብጹዕ ለመሆን(፪)\nከህጻናት ማን አለ ቂርቆስም አለ\nከህጻናት ማን አለ ሚናስም አለ\nከህጻናት ማን አለ ዳግማዊ ጳውሎስም አለ\nሳላይ ልመን ብጹዕ ለመሆን(፪)\nየእኛ ልጅ በርቺ በርቺ ከዲያብሎስ አምልጪ\nልብሽን ለአምላክ ስጪ\nቃሉን ለመስማት ትጊ\nወደ ጽድቁ ቅረቢ (፪)\nበምህረት ቤቱ ግቢ\nአዝ ………\nከጻድቃንስ ማን አለ አቡነ ኪሮስ\nእስትንፋሰ ክርስቶስ ተክለሃይማኖት\nገብረ መንፈስ ቅዱስ ሌሎችም ብዙ አሉ\n\nከሰማዕታት ማን አለ ህጻኑ ቂርቆስ\nቅድስት አርሴማ ጳውሎስ ወጴጥሮስ\nሌሎችም ብዙ አሉ\nሳላይ ልመን ብጹዕ ለመሆን(፪)\nየእኛ ልጅ በርታ በርታ ሰይጣንን እንድትረታ\nልብህን ለእግዚአብሔር ስጥ\nቃሉን በእምነት አድምጥ\nእራስህን አድርገህ መባዕ (፪)\nበምህረት ቤቱ ግባ', 'am', 42, 0),\n(6, 'የእምነታችን መሠረት', 'የእምነታችን መሠረት\nየእምነታችን መሠረት አዕማደ ምስጢራት \n፭ቱንም ተቀብለን በሙሉ ልብ እናምናለን\n\nያለአንዳች ኑፋቄ ያለአንዳች ክፍፍል\nእኛ አናመነታም አምነን ለመቀበል\nየቤተክርስቲያን ታላቅ ምሶሶ ነው\nቅዱሳን አባቶች ያቆዩት አፅንተው\nምስጢረ ሥላሴ ምስጢረ ስጋዌ\nጥምቀትና ቁርባን ትንሳኤ ሙታን\nየተዋህዶ ልጆች ሁላችን በአንድነት\nአምነን ተቀብለን እንቁም በሃይማኖት (፪)\n\nየሥላሴን ምስጢር ስንተነትን\nሦስትነት አንድነት ብለን አምነን \nየእግዚአብሔርን ጥበብ እያደነቅን\nምስጢሩን ተረድተን እንጸናለን\nየእያንዳንዱን ተግባር ስናየው\nበመፍረድ በስልጣን በአገዛዝ \nበጌትነት ክብር አንድ ናቸው\nበስም እና በአካል በግብርም\nሶስትነታቸው ነው በዝርዝር\nያለመነጣጠል በሦስትነት አንድነት \nበአንድነት ሦስትነት \nአብና ወልድ መንፈስ ቅዱስ\nእንላለን ሥሉስ ቅዱስ(፪)\n\nካለእናት በአባቱ ያለ ቅድመ ዓለም \nድኅረ ዓለም ያለአባት ከማርያም\nደካማውን እና ሚራበውን\nሚሞተውን ስጋ መዋሀዱን\nያለመለያየት ያለመቀዳደም\nተዋሕዶ ብለን ብንቀበል\nየወልደ እግዚአብሔርን \nሰው ሲሆን አምላክ \nአምላክ ሲሆን ሰው\nበስጋዌ ብናየው \nጥልቅ የሆነ ምስጢር ነው(፪)\n\nከውሃ ከመንፈስ ዳግም ተወልደን\nየእግዚአብሔርን መንግሥት አግኝተን\nበሚታየው ውሃ ተጠምቀን\nየማይታይ ፀጋ በረከት\nበምናገኘው በምስጢራት በር\nተብሎ የሚጠራው\nየልጅነት ጸጋ ሚስጢረ ጥምቀት ነው\nአምነን እና ተጠምቀን\nእንድናለን ሁላችን (፪)\nዘለዓለም ህይወት እንዲኖረን\nጌታ መድኃኔዓለም የሰጠን\nበምሴተ ሐሙስ ጽዋውን\nህብስቱንም ባርኮ ያደለን\nለሁላችን ድኅነት ሚፈተተው\nህይወቱን ሰውቶ እንኩ ያለን\nየፍቅሩ ማሰሪያ \nቅዱስ ስጋውና ክቡር ደሙ ነው\nየሚስጢረ ቁርባን ትልቁ ዓላማው\nየዘለዓለም ህይወትን \nእንቀበል በቁርባን(፪)\n\nበመጨረሻው ቀን ከሞት በኋላ\nሰው ሁሉ ሲነሳ በጠቅላላ\nበዚያች ፍርድ ሰዓት ጻድቃን ሁሉ\nየክብርን አክሊል ሲቀበሉ\nበግፍ እና በሐጥያት ያለፉት\nበግራ ሚቆሙት በውርደት\nበዚያች ግሩም ቀን ነው \nጌታችን በሚያውቀው በምጽአቱ ሰዓት\nትንሳኤ ሙታንን …….\nበቅዱስ ቃል ታንጸን \nእንዲያወርሰን መንግስቱን\nእንዘጋጅ ሁላችን(፪)', 'am', 43, 0),\n(6, 'ከዓለም መፈጠር በፊት', 'ከዓለም መፈጠር በፊት\nከዓለም መፈጠር በፊት \nየሰማይ ጠፈሮች ሳይቀድሙት\nጥንት የነበረ እግዚአብሔር\nአማካሪ የሌለው ሲፈጥር\n\nሁሉን ያዘጋጀ በስርዓቱ\nአስገኚ የሌለው ለመንግስቱ\nበሦስትነት ውስጥ አንድነት\nበአንድነት ውስጥ ሦስትነት\nአገዛዝ ስልጣን የብቻው \nአነዋወሩ ግሩም ነው (፪)\n\nእርሱ ትልቅ ነው በመንግስቱ\nክብሩን ያወጁ መላእክቱ\nለገናንነቱ የለው አቻ\nአምላክ የሆነው አንዴ ብቻ\nሰማይን የሰራ በጠፈራት\nምድርን ያጸና በማያት\nየእሳት መንጦላዕት መጋረጃው\nበአርያም ነው መገለጫው (፪)\n\nበሰማይ ያሉ ከዋክብቱ\nበአየር የሚበሩ አዕዋፋቱ\nበባህርም ውስጥ የሚኖሩ\nበምድር ላይ በእግር የሚዞሩ\nአኗኗራቸው ይነግረናል\nየአምላክን መኖር ያስረዳናል(፪)\n\nቀናትን በወራት በዓመት\nየሚያፈራርቅ በየወቅት\nየፀሀይ መውጣት ደግሞም መጥለቅ\nየዝናም ወራት መፈራረቅ\nይናገራሉ መኖሩን\nአዛዥ መጋቢ መሆኑን\nደግሞ እናምናለን ፍጥረታቱ\nአምላክ መሆኑን በመንግስቱ\nአለምም ይስማ እውነቱን\nአስገኚው አምላክ መኖሩን(፪)', 'am', 44, 0),\n(6, 'ፍልሰታ', 'ፍልሰታ\nየህጻናቱ ነሽ የሁሉ ደስታ\n16ቷ ጾመ ፍልሰታ\nእንናፍቃለን ጊዜሽ እስኪደርስ\nበበረከትሽ እስክንረሰርስ\nፍቅርን ትህትናን ታስተምሪያለሽ \nበቀና መንገድ ትመሪናለሽ\n\nእናገኛለን ትልቅ ደስታ(2) በ16ቷ በፍልሰታ\n\nዛሬ መጥታለች በረከት ይዛ\nበሰው መካከል ፍቅር\nጥላቻ ቂምን እንዳናፈራ\nበልባችን ውስጥ ፍቅር እንዲጸና(፪)\nእናገኛለን ትልቅ ደስታ(2) በ16ቷ በፍልሰታ\n\nማርና ወተት እየመገብሽን\nየጽድቁን መንገድ እያሳየሽን\nእኛ ሕጻናት እንወድሻለን\nስንቸገርም ትረጂናለሽ(፪)\nእናገኛለን ትልቅ ደስታ(2) በ16ቷ በፍልሰታ\n\nድንግል ማርያም ሆይ ቤትሽ መጥተናል\nበአማላጅነትሽ እምነታችን ጸንቷል\nበላዔ ሰብን ያስማርሽው ከጌታ\nእኛንም አማላደሽ አስታርቂን ከልጅሽ(፪)\nእናገኛለን ትልቅ ደስታ(2) በ16ቷ በፍልሰታ\n\nበአፏ ይዛለች ቄጠማ\nመልካሙን ዜና ልታሰማ\nእርግቤ ሰንብታ (፪)\nመጣች በፍልሰታ\nሀገርሽ የት ነው ኤፍራታ\nአሳድሪን ማታ ማታ\nይናፍቀኛል ሌሊቱ\nመቅደስ ውስጥ ያለው ስርዓቱ\nይናፍቀኛል ሌሊቱ\nየአባቶቻችን ሰዓታቱ', 'am', 45, 0),\n(7, 'እመቤታችን', 'እመቤታችን\n“አለቃ ተሰማ ወ/አማኑኤል በገና ሊያሰሙ ይጀምራሉ።” \nስሙን ሲጠሩት የሚያምር።  \nወልደ አብ ወልደ እግዚአብሔር /፫/  \nስሙን ሲጠሩት የሚያምር።  \nወልደ አብ ወልደ እግዚአብሔር /፫/  \nእመቤታችን የዓለም ቤዛ።  \nተሰዳ ነበር ልጇን ይዛ።  \nከግንድ አገቡት በሰንሰለት። \nሙሉ ዓለም ተገኝቶበት /፫/ \nእመቤታችን በበረሃ።  \nስትለምን አየን መስላ ድሃ። \nበቀኝ ወርቅ ፀሐይ ይዛ አየናት። \nመድኃኒት የወልድ እናት/፫/ \nቅዳሴ ማርያም ቃል ትምህርት። \nእንዳልጠቀመኝ አየሁት። \nበመቁጠሪያዬ ሳንቀላፋ። \nዋ መቋሚያዬ ጠፋ/፫/ \nቅዳሴ ማርያም ስንማር። \nአግኝተን ነበር ደግ ነገር። \nተገደፈና ተሳሳተ። \nኦ አዳም መሬት አንተ/፫/ \nእንቧጮም ቢሆን ድግጣ። \nያገኘኸውን ቆርጠህ አምጣ። \nምን ይሆንሃል ጥሩ እንጨት። \nለመሰንበቻ ቤት/፫/', 'am', 1, 0),\n(7, 'የድሮ ዘመን', 'የድሮ ዘመን\nየድሮ ዘመን ስሕተት። \nበጾም ቀን ዓሣን መብላት። \nያሁን ዘመን ሰው አያውቅ መላ። \nበጾም ሽሮ ነው የሚበላ /፬/ \nየደሃ ድካም በየዓመቱ። \nጥንት የቆየ ነው ከአባቱ። \nአንድ ሐሙስ እንኳ እንዳያርፍ። \nከመ ጽላሎት ይኀልፍ። \nእራሴን ፈትተኽ ፈጥረህ። \nየምትዘጋጋው አዘህ። \nይምጣልህ እንጂ ተሰንጥቆ። \nባንተ ሥራ ማን አውቆ /፫/ \nእዛ ላይ ሆኖ ቢጠራኝ።  \nወይ እንዳልለው ድምጽ የለኝ። \nባልሰማ እንጂ ነው ዝምታዬ። \nአቤት አቤት ጌታዬ /፫/ \nወደ ጌታ ቤት የምትወጡ። \nበቅሎ አለችና ኮርቻ አምጡ። \nመርገፍ አለና እንዳትረሱ። \nሁላችሁም አስታውሱ። \nአባቶቻችን በቅሎ ገዝተው።  \nኮርቻ ነበር ችግራቸው። \nየዛሬ ልጆች ይበልጣሉ።  \nለመርገፍ ይጥራሉ/፪/  \nምድር ለሥጋ ስትሳሺ። \nኃያል ፍሪዳ መጣልሽ/፪/ \nየባልንጀራዬ ኩራቱ። \nበሃብቱ ነው ወይ በጉልበቱ። \nልቀቁትና ይታገለኝ። \nእንዴት ፈጥሮ ሊጥለኝ /፫/ \nእዛ ላይ ያለች ሸክላ ሰሪ። \nድሃ ናት አሉኝ ጾም አዳሪ። \nማን አስተማራት ጥበቡን። \nገል አፈር መሆኑን። \nበአልጋ መኝታ በጠፍር። \nመልካም መስለን ነበር። \nአባቶቻችን ግን ሳያቸው። \nሁሉ በመሬት ናቸው። \nእንግዲህ መሸ ሊጨልም።  \nእንደ ቀን ፀሐይ የለም/፪/ \nእንቧጮም ቢሆን ድግጣ። \nያገኘኸውን ቆርጠህ አምጣ። \nምን ይሆንሃል ጥሩ እንጨት። \nለመሰንበቻ ቤት/፫/ \nወንድሜ ጠፍቶኝ ስሄድ። \nነብር አግኝቶኝ ከመንገድ። \nአልተመለስኩም ወዲያው ሄድኩ። \nእኔን ይብላኝ እያልኩ/፭/', 'am', 2, 0),\n(7, 'ሰላምታ', 'ሰላምታ\nበስመ አብ ወወልድ ወመንፈስ ቅዱስ። \nአሐዱ አምላክ ብዬ ሰላምታ ላድርስ። \nእንዴት አለህ አንተ የላይኛው ንጉሥ። \nእስክትጠራኝ መጥቼ እስካይህ ድረስ። \nያስደንቃል ያኗኗራቸው የጥንቱ። \nየአብ የወልድ የመንፈስ ቅዱስ የሦስቱ። \nሦስት ናቸው በአካል በገጽ በስም። \nአንድ ናቸው በትእዛዝ በክብር ፍጹም። \nሥላሴም እምቅድመ ዓለም ሲኖሩ። \nዓለም መፍጠር እሑድ በሠርክ ጀመሩ። \nያን ጊዜውን ሰባት ፈጠሩ ቅጽበት። \nአስቀድመው ሰማይና ምድርን በፊት። \nአራተኛ መላእክትና ጽልመት። \nሰባተኛ ማይና ነፋስ እሳት። \nበአርምሞ ይህንን ሁሉ ፈጥረው። \nተናገሩ ለይኩን ብርሃን ብለው። \nሰኞ ጧት ውኃን ከፈሉት ከሦስት። \nአንደኛውን አዘቅት አረጉት ከምድር። \nሁለቱን ሰማይ አረጉት ጠፈር። \nማክሰኞም አብቅይ አሏት ምድርን። \nአበቀለች ሳሩን ቅጠሉን እህሉን። \nእሮብም ረቂቅ ሥራን ሲሠሩን። \nከዋክብትን ፀሐይ ጨረቃን ፈጠሩን። \nሐሙስም አልተውምና መፍጠር። \nየሚበሩ የሚሄዱትን በእግር። \nበባሕርም ዓሣ ጉማሬ ሳይቀር \nዓርብ ጧት አዳምን የኛን አባት። \nንግበር ብለው በነሱ አምሳል ሠሩት። \nበሠለስት ሔዋንን ፈጥረው ሰጡት። \nትርዳህ ብለው ብቻውን ሆኖ ቢያዩት። \nየሥላሴም የፍጥረታቸው ፍጻሜ። \nበሰባት ቀን ዳርቻ ሆነች ቅዳሜ። \nለዓለም ወለዓለመ ዓለም። \n፠፠፠ \nየተላከው ቅዱስ ገብርኤል ከጌታ። \nሰላም ለኪ ብሎ በሰጠሽ ሰላምታ። \nእኔ ባሪያሽ ልብሴን ስታጠቅ ስፈታ። \nሰላም ልልሽ ይገባኛል ጧት ማታ። \nማርያም ሆይ እመቤቴ ሆይ ድንግል። \nበሥጋሽም በሕሊናሽም ድንግል። \nየአሸናፊ የእግዚአብሔር እናት ድንግል። \nእንዳለሽ ቅዱስ ገብርኤል ሰላም። \nሰላም ለኪ እንደርሱ ሁሉ እኔም። \nየሌለብሽ የነፍስ የሥጋ መርገም። \nቡሩክ ነው የማሕፀንሽ ፍሬም። \nእንደወትሮው ቡሩክ አምላክ ነው ዛሬም። \nእግዚአብሔር ወልድ በመጣ ጊዜ ለካሣ። \nእንበለ ዘርእ እንደ ንብና እንደ ዓሣ። \nከነፍስሽ ነፍስ ከሥጋሽ ሥጋ ቢነሳ። \nደስ ያለሽ ሆይ ጸጋን አግኝተሽ ከጌታ። \nደስ ይበልሽ በማቀርብልሽ ሰላምታ። \nለምኝልን ሳትሰለቺ ጧት ማታ። \nውድ ልጅሽ እንዲያደርግልን ይቅርታ። \nይቅር ብሎ ኃጢአታችንን ሁሉን። \nእንዲያድነን በአንቺ ተማፅነን አለን። \n፠፠፠ \nበዚያች ዕለት በግርማ ሆኖ ሲወርድ። \nበሙታንም በሕያዋንም ሊፈርድ። \nሲንቀጠቀጥ ፍጥረቱ ሁሉ ሲርድ። \nእንደ ቀድሞው እያንገላቱት አይሁድ። \nጨርቅ ታጥቆ ግንድ ተሸክሞ ያይደለ። \nምን ሠራችሁ የት ነበራችሁ እያለ። \nለቁርጥ ፍርድ ወደዚህ ዓለም ሲመጣ። \nሲንቀጠቀጥ ክፉ በጉዱ ሲወጣ። \nአፍ ሲዘጋ የሚመልሰው እያጣ። \nኃጥኣንም በእሳት ባሕር ሲዋኙ። \nወዳጆቹም እንደ ሥራቸው ሲያገኙ። \nእንድነቱን ሦስትነቱም ጭምር። \nሰው መሆኑን ከማመናችን በቀር። \nሰንፈን ኖረን ምንም ትሩፋት ባንሠራ። \nቀኙን ትቶ እንዳያቆመን በግራ። \nእንዲያድነን ከዚያነለቱ መከራ። \nዐይን ያላያት ዦሮ ያልሰማት ከጥንት። \nለኛ ብሎ ያዘጋጃትን መንግሥት። \nእንዲያወርሰን በቸርነቱ ብዛት። \n፠፠፠ \nአባታችን በሰማዮች ላይ ያለህ። \nተለይቶ ይመስገን ክቡር ስምህ። \nመንግሥትህን የምንፈልጋት ከጥንቱ። \nበልጅነት ትምጣ ትሰጠን አቤቱ። \nፈቃድህም ይህ እንዲደረግ ይሁን። \nበሰማይ ሞተን ተነሥተን ከደይን። \nእንድንኖር ምስጋናህ ሆኖን ምግብ። \nዛሬም በምድር በሥጋ ሕይወት ሳለን። \nምግባችንን በየቀኑ አውቀህ ስጠን። \nይቅር በለን የበደልንህም ቢኖር። \nወንድማችን የበደለንን ነገር። \nእንዳቅማችን እኛም እንድንል ይቅር። \nበገሃነም በክፉው ሁሉ መአት። \nአትጣለን አድነን እንጂ ከሞት። \nይቺን መንግሥት የማያገኛት ኅልፈት። \nጌትነትም ከሃሊነትም ክብርም። \nናቸውና የአንተ ገንዘቦች ሁሉም። \nለዓለም ወለዓለመ ዓለም ። \n፠፠፠ \nድንግልም በምትወልድበት ወራት። \nበሮም ንጉሥ በአውግስጦስ ቄሳር መንግሥት። \nሰው ሁሉ ግብር ሊቆጠር ታዘዘ። \nዮሴፍም ድንግልን ይዞ ተጓዘ። \nከገሊላ ከምትባል መንደር። \nቤተልሔም ወደምትባል ሀገር። \nከኤፍራታ ይወጣል ብሎ ንጉሥ። \nሚክያስ የተናገረው ሊደርስ። \nበታህሳስ ሃያ ዘጠኝ ዕለት። \nሳታፋልስ የወላዶችን ሥርዓት። \nተወለደ ድንግልናዋን ሳይጥስ። \nቤት ባይኖራት መጥታለችና ከሩቅ። \nከበረት ጠቀለለችው በጨርቅ። \nሊፈጸም የኢሳይያስ ነገሩን። \nእንስሳትም ትንፋሻቸውን ገበሩ። \nከዚያ ቦታ ከብት ጠባቂዎች ነበሩ። \nያዩ ነበር ካሉበት ቦታ ድረስ። \nየብርሃን ጎርፍ ከቤተልሔም ሲፈስ። \nኖሎትም የብርሃኑን ጎርፍ አይተው። \nእጅግ ፈሩ ምንድን ነገር ነው ብለው። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ \n፠፠፠ \nድንግልም በልጃገረድ ሥርዓት። \nባጭር ታጥቃ ማድጋ ነጥቃ ከቤት። \nወደ ወንዝ ወኃ ልትቀዳ ሄደች። \nከዚያም ወርዳ የጠማውን ውሻ አየች። \nሲያባርሩት ና ሂድ እያሉ ሴቶች። \nምነው ለርሱስ አታዝኑለትም? አለች። \nቸርናትና ከፈጣሪዋ በታች። \nመለሱላት እንዲህ እያሉ ሴቶች። \nየሥራ ፈት ይመስላልና ትጥቅሽ። \nአንቺ አጠጪው ይኸውልሽ ውኃው ቀድተሽ። \nድንግልም የነሱን ነገር ኣድንቃ። \nለፍጥረቱ ታዝናለችና አጥብቃ። \nወርቅ ጫማ ከተረከዟ አውልቃ። \nአጠጣችው ከማድጋዋ አፍልቃ። \nእኒያም ሴቶች እንዲህ ስታደርግ ቢያይዋት። \nእንዳትቀጂ ወኀው ጉድጓድ ነው አዘቅት። \nማድጋሽን ምን ትሞይው አሏት። \nሃይማኖቷ ፍጹም ነውና ከጥንት። \nአለቻቸው እለዚያን ሴቶች እላንት። \nአታስቡ ምን ትመላው ነው ብላችሁ። \nከወደታች ወኀ የሚገኝ መስሏችሁ። \nይኸን ውሻ ያጠጣው አምላክ የት ሄዶ። \nይሞላዋል ከወደ ሰማይ አውርዶ። \nስትጨርስ ይህን ተናግራ ወዲያው። \nማድጋዋን በተአምራት ሞላው። \nእሊያም ሴቶች እንዲክ ሲደረግ አይተው። \nበዚያ ወራት ጉባኤ አድርገው ለሁሉ። \nይወለዳል አምላክ ከድንግል እያሉ። \nነቢያት ይናገራሉ ትንቢት። \nያምላክ እናት አንችን ትሆኝ አሏት። \nእንዲህ አርገው ሲነጋገሯት ምፀት። \nሳያውቁት ተናገሩላት ትንቢት። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ።  \nለዓለም ወለዓለመ ዓለም። \n፠፠፠ \nጥምቀቱን መርጦ ከብዙ ባሕር። \nበዮርዳኖስ ያረገበትን ምሥጢር። \nየሚጠይቅ የሚመረምር ቢኖር። \nከመምህራን የሰማሁትን እንዳቅሜ። \nለሚሰማኝ እናገራለሁ ተርጒሜ። \nከዲያብሎስ አይጠፋምና ተንኰል። \nአዳም ገብሩ ለዲያብሎስ የሚል። \nበዮርዳኖስ አኑሮ ነበር ደብዳቤ። \nያነን ደብዳቤ በጌታዬ ፊት አንብቤ። \nአዳምን እርሱ በጻፈው ጽሕፈት። \nባሪያ አድርጌ አስቀረዋለሁ መስሎት። \nያን ደብዳቤ በሰውነቱ ረግጦ። \nእንደ ቅቤም ባምላክነቱ አቅልጦ። \nሊያጠፋልን እንዲህ አድርጎ በውነቱ። \nተደረገ በዮርዳኖስ ወንዝ ጥምቀቱ። \nተጠምቆም ከወኃው መሃል ሲወጣ። \nከአብ ዘንድ እንደዚህ የሚል ቃል መጣ። \nየምወደው የምወልደውም ከጥንት። \nልጄ ይህ ነው የሚላችሁን ስሙት። \nአንድ አድርጎ ይህ ልጄ ነው ማለቱ። \nአንድነቱን መሰከረለት አባቱ። \nሲመሰክር መንፈስ ቅዱስም እንደርሱ። \nበርግብ አምሳል ወርዶ አረፈበት ከራሱ። \nሦስቱ ሁሉ እንዲህ ያል ሥራ ሲሠሩ። \nሕዝቡ ሁሉ በዙሪያውም ነበሩ። \nተሰውሮ እስከዚያ ድረስ ሲኖር። \nያንድነትም የሦስትነትም ነገር። \nተገለጠ እጅግ ተረዳ በምድር። \nእኛም ዛሬ እርሱን አብነት አርገን። \nከሥላሴ እንድንወለድ አምነን። \nብንጠመቅ ቄሱ ቢቀባን ሜኖን። \nየሥላሴ የጸጋ ልጆች ሆነን። \nከኃጢኣት ከፍዳ ሁሉ ነጽተን። \nእንሆናለን እንደ አስር ዓመት ሕፃን። \nበሰማንያም በመቶም ዘመን ቢሆን። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ።  \nለዓለም ወለዓለመ ዓለም። \n፠፠፠ \nከዲያብሎስ ከግብር አባቱ ተምሮ። \nበበጎ ቃል ክፋቱን ሁሉ ሰውሮ። \nእንዲህ አርጎ የሐሰት ወሬ አወራ። \nአስቤአለሁ ለንጉሥ ጭፍራ ልሠራ። \nሕፃናቱን መልካም ምግብ መግቤ። \nአሳድጌ በማር በወተት በቅቤ። \nእንዲህ አርጎ ልጆችን ሁሉ ሰብስቦ። \nፈጣሪውን አብሮ ሊገለው አስቦ። \nዐሥራ ዐራት እልፍ ካራት ሽህ ልጅ ገደለ። \nከኚህ ሁሉ አንዱ ይሆናል እያለ። \nየልጆች ደም እንደ ወንዝ ወኃ ፈሰሰ። \nኤርምያስም የተናገረው ደረሰ። \nእንዲህ ብሎ ድምጽ በራማ ተሰማ ። \nራሄልም እያለቀሰች በዜማ። \nሄሮድስም ከዲያብሎስ ጋር በሥራ። \nአንድ ሆኖ ለነጊጋርም ሳይራራ። \nእያሰበ በደጋግ ሰዎች መከራ። \nሰዉን ሁሉ እየገደለ በጭንቅ። \nተቀመጠ ሦስት ዓመትና መንፈቅ። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ።  \n፠፠፠ \nዮሴፍም የመከራውን ፍጻሜ። \nዛሬ ሌሊት መልአክ ነገረኝ በሕልሜ። \nቢላቸው ማርያምና ሰሎሜ። \nከስደት እንረፍ ብለው ጥቂት። \nሕፃኑን ይዘውት ገቡ ናዝሬት።  \nበናዝሬት የሕፃናትን ሥራት። \nሊፈጽም በየጥቂቱ አደገ። \nግብሩን ሁሉ እንደ ሕፃናት አረገ። \nአምላክ ነኝ ዕለቱን ልደግ ሳይል። \nከፍ ከፍ አለ በጥበብና በኃይል። \nዕንጨትን እየሰበረ በጣቱ። \nወኃም ቀድቶ ተሸከመና ባንገቱ። \nእንዲህ አርጎ አገለገለ ለእናቱ። \nዕፁብ ድንቅ የትሕትናው ብዛት። \nግሩም አምላክ የሄሮድስን ፊት መፍራት። \nለሰው ብሎ ሰውን ከስደት ሊምር። \nዓለም ሁሉ በማሃል እጁ ሲኖር። \nካንዱ ሀገር ወደ አንዱ ሀገር መዞር። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ።  \nለዓለም ወለዓለመ ዓለም።', 'am', 3, 0),\n(7, 'ከቶ አይቀርም ሞቱ', 'ከቶ አይቀርም ሞቱ\nከቶ አይቀርም ሞቱ ምን ቢሰነብቱ። ከቶ አይቀርም ሞቱ \nከቶ አይቀርም ሞት ምን ብሰነብት ።ከቶ አይቀርም ሞት \nከቶ አይቀርም ሞት  \nእስከዚያው ድረስ ነው ሲሶ ማረሳችን። \nእንገባው የለም ወይ በየመሬታችን።  \nከቶ አይቀርም ሞቱ ከቶ አይቀርም ሞት  \nምድር እንጋባን ማጪያሽ ምን ያህል ነው/፪/ \nምንም አይወጣልሽ አንድ አንድ ሸማ ነው። \nእረገጡኝ ብለህ ምድር አትቆጣ። \nይህ ኩሉ ያንተ ነው ሸማውን ቢያነጣ። \nምድር እረገጥኩሽ መልሼ መልሼ።  \nእታረቅሻለሁ ሙሉ አካሌን ክሼ። \nከቶ አይቀርም ሞት ምን ብሰነብት።ከቶ አይቀርም ሞት  \nእንካ ብላ ብለህ የሰጠህኝ ጉበት።  \nመልሰህ ውሰደው/፪/ያንን መራራ ሃሞት/፪/ \nፍየሉና በጉ ተጣልተው ሲዋጉ።  \nአምላክ ለማን ረዳ ለሞኙ ለበጉ/፫/ \nከቶ አይቀርም ሞት ምን ብሰነብት። ከቶ አይቀርም ሞት \nከቶ አይቀርም ሞት/፪/  \nየጉሬዛ ሞቱ የግፍ ነው የግፍ።  \nየሚበላው ቅጠል የሚያድረው ከዛፍ። \nከቶ አይቀርም ሞት  \nየምድር አበሳዬን አበሳም አላልኩት። \nአላውቀውምናን ያንን የመራሁት። \nእባክህ አምላኬ ስጠኝ መስታወት።  \nየሰው ሥራ ትቼን የእኔን አይበት። \nከቶ አይቀርም ሞት ምን ብሰነብት። \nየምድር አበሳዬን አበሳም አላልኩት። \nአላውቀውምናን ያንን የመራሁት። \nከቶ አይቀርም ሞት ከቶ አይቀርም ሞቱ/፪/ \nእከድ እከድዬን ነገር ተበላሸ። \nበሥጋ ገበያን ስልከሰከስ መሸ።  \nእንዲህ ስልከሰከስ አያርገኝ እንደሆን። \nአንት መጠየቅ ወዳድ ምን ይመለስ ይሆን/፪/ \nከቶ አይቀርም ሞቱ/፫/ \nከቶ አይቀርም ሞት ከቶ አይቀርም ሞቱ። \nዕፁብ ነው ድንቅ ነው የጌታ ስቅለቱ።  \nእንዲህ በአርምሞን በእንዲህንያል ምክንያት አልቀው ሕፃናቱ። \nየዮሴፍ ሶሎሜን ጌታ ከእነ እናቱ። \nሆረ ደብረ ጉስቋም ምድረ ግብጽ ስደቱ።  \nበዚያ በበረሃን በመንከራተቱ።  \nውኃ እየለመነች እመቤት እናቱ። \nየሄሮድስን ጥፋት ተሰማና ሞቱ።  \nምድረ ናዝሬት ገባች ከሕይወት ርስቱ።  \nወዲያውም ደረሰን ለመምህርነቱ/፪/ \nአርባ ሌሊት መዓልት ጾመ ወጸሎቱ።  \nበእደ ዮሐንስ በባሕረ ዮርዳኖስ የጌታ ጥምቀቱ።  \nተጽዕኖ ገባን በነሃስ እድገቱ። \nሆሣዕና ዳዊት ለዓለም መድኃኒቱ። \nኪራላይሶም ብለው ሰግደዋል ካህናቱ።  \nደቂቀ ሠራዊት አልቀሩም ዓበይቱ።', 'am', 4, 0),\n(7, 'መኑ ተኅሥሡ', 'መኑ ተኅሥሡ\nመኑ ተኅሥሡ ብሎ ጠየቃቸው።  \nኢየሱስ ናዝራዊን ሲሉ ቢሰማቸው። \nአነ ውእቱ ብሎ ይሄን ቢነግራቸው። \nሦስት ጊዜ ረገፉን ሙላው በጀርባቸው። \nበማያልቅ ምሕረቱ ወዲያው አነሳቸው። \nከለሜዳ አስታጥቀው በታጠቁት ዝንቱ። \nወድቆ ተገረፈ ለምለም አካላቱ። \nሰቀሉከ ኢየሱስ ግፍዖሙ ዝንቱ።  \nዘለፌ ወለፌ አዕ በአንተ ማቱ።  \nፀሐይም ጠለቀ ሆነ እንደ ሌሊቱ።  \nጨረቃም ደም ሆነ ሸሸ ብርሃናቱ። \nከዋክብት ረግፈው ታጡ ካሉበቱ። \nሳሩም ደረቀናን ቅጠሉም አትክልቱ።   \nሲገርፉት ሲያዳፉት ሲወድቅ በደረቱ። \nበስተኋላው ቁመው ስበው ወደ አንገቱ። \nበስተፊቱ ቁመው ስበው በደረቱ። \nስቅሎ ስቅሎ አሉት ሲዛበቱ/፪/ \nሲገርፉት ሲያዳፉት ሲወድቅ በደረቱ። \nበከየት ማርያም አዘነች እናቱ። \nምድረ ቀራዮን መስቀል መሰረቱ።  \nጌታችን ተነሣ በዕለተ ሰንበቱ።  \nመጎስቆሉ ቀረ መጣ ጌትነቱ /፪/ \nጽኑ ሽብር ሆነ /፪/ አይሁድ ተፀፀቱ።  \nዲያብሎስ ድል ሆነ ከነ ሠራዊቱን።  \nቁልቁለት ወረደ በመትት ርስቱ። \nአዳምን አወጣው ምስለ ብእሲቱ።   \nወዲያው ገነት መራው ከቀደምት ርስቱ። \nዕፁብ ነው ድንቅ ነው የጌታ ስቅለቱ። \nአንቺ አማልጂን እንጂ መድኃኒት ለዓለሙ። \nወልደ አብ ሲለምን አባ ሥረይ ሎሙ። \nእመቤት እመቤት የዓለም መድኃኒት። \nእንድታማልጂን በዕለተ ምጽአት። \nምንም ክፉ ብንሆን አውቀን ብናጠፋ። \nአዛኝቷ አስምሪን እናት አትገፋ። \nንዑ ና ሑሩ ሲል ሲያደራጅ ልጅሽ። \nእንደ በላዔ ሰብእ ያድነን ጥላሽ/፪/ \nሰአሊ ለነ ቅድስት ይልሻል ተማሪ። \nአንቺ አይደለሽም ወይ የዕውር ድሃ መሪ። \nእባክህ አምላኬ አትመራመረን። \nእንደ በላዔ ሰብእ በጥቂት ነገር ማረን/፫/ \nከቶ አይቀርም ሞት ምን ብሰነብት። \nእከድ እከድዬን ነገር ተበላሸ። \nበሥጋ ገበያን ስልከሰከስ መሸ።  \nእንዲህ ስልከሰከስ አያርገኝ እንደሆን። \nአንት መጠየቅ ወዳድ ምን ይመለስ ይሆን/፬/ \nየኦሪት ቃል ዘሎ ወንጌል ካዘዘው/፪/ \nዋ ጊዜ ደረሰ አንዱን ሳንሠራው/፪/ \nከቶ አይቀርም ሞቱ \nምነው በዓርብ ረቡዕ ጾም የገደፋችሁ። \nእስኪ ፈጠን በሉ ታገኙታላችሁ/፪/ \nመጾሙን ይጾማል ሙላው የሰው ልጅ። \nየጊዜውን መድረስ የሚያውቅ የለም እንጅ። \nከቶ አይቀርም ሞት  \nከቶ አይቀርም ሞቱ ከቶ አይቀርም ሞቱ  \nከቶ አይቀርም ሞት ምን ብሰነብት።ከቶ አይቀርም ሞቱ \nከቶ አይቀርም ሞት  \nከቶ አይቀርም ሞቱ ከቶ አይቀርም ሞቱ \nከቶ አይቀርም ሞት ምን ብሰነብት።ከቶ አይቀርም ሞት', 'am', 5, 0),\n(7, 'አንተ ነህ', 'አንተ ነህ\nአንተ ነህ ይላሉ የዓለም ሁሉ ጌታ። \nሰማይና ምድርን ያቆምክ ያለዋልታ። \nወዴት እንዴት ይሆን ያለህበት ቦታ። \nእነግርህ ነበረ እኔ በቆይታ። \nየሠራችልኝን የእናትህን ወሮታ። \nያንጊዜ አትለይም እሷ ከእኔ እርዳታ። \nመብልና መጠጤን በውል አዘጋጅታ። \nእግሬን አሳጥባ ዙፋን አዘርግታ። \nትከተለኛለች ለእርሷ ልዕልና። \nየለውም ቅርታ ልጇ ፍጹም ንጉሥ። \nየለውም ቅርታ/፪/  \nእኔስ ይገርመኛል ከጧት እስከ ማታ። \nአለሁበት ሀገር አለመለየቷ። \nቀድሞም በበጌምድር በየጁ በላስታ። \nለሁሉም ነው እሷ ርኅሩኅነቷ። \nአይበዛም እንደ እኔ ይህ መልካምነቷ። \nአንቺ አማልጂን እንጂ መድኃኒት ለዓለሙ። \nወልደ አብ ሲለምን አባ ሥረይ ሎሙ። \nእመቤት እመቤት/፪/ \nእመቤት እመቤት የዓለም መድኃኒት። \nእንድታማልጂን በዕለተ ምጽአት። \nምንም ክፉ ብንሆን አውቀን ብናጠፋ። \nአዛኝቷ አስምሪን እናት አትገፋ። \nንዑ ና ሑሩ ሲል ሲያደራጅ ልጅሽ። \nእንደ በላዔ ሰብእ ያድነን ጥላሽ።', 'am', 6, 0),\n(7, 'ማን ይመራመር ቁ ፩', 'ማን ይመራመር ቁ ፩\nማን ይመራመር ማን ይመራመር/፪/ \nያንተን ሥራ ያንተን ግብር ማን ይመራመር። \nአባይ ተሸምቶ ይቀናል በጌምድር። \nእየከዳ እምቢ አለን ወዳጅ እና ምድር። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nአምላኬ ሲ---ተን በዚያ እሳት አንድደው።  \nእንቢ ብሎ አይቀርም አንተ የጠራኸው ሰው። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር። \nማን ይመራመር ማን ይመራመር \nእኔ አውቀው ነበረን የወጥን ጣዕምናን። \nወጡን በጤና አዳም አልተሰራምናን። \nአልበላም አለኝ ወጡ ተበላሽቶ። \nወጡን በጤና አዳም ሳይሰራ ቀርቶ። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር። \nማን ይመራመር ማን ይመራመር/፪/ \nያንተን ሥራ ያንተን ግብር ማን ይመራመር። \nዓለም ማረፊያ ናት መኖሪያ ገነት/፪/ \nተነሡ እንከተል እኛም ከሄዱት። \nአፈር ከሸተተን ከያዘን በሽታ። \nብንቆርብ አንድንም ይህን ጊዜ እንበርታ። \nመቁረብ በሕይወት ነው ንስሐ መግባት \nይህ ኩሉ አይገኝም ከገቡ መሬት/፪/ \nወርቅ የለበሰና ያጌጠ ፍጡር። \nክብሩ ሁሉ ቀረ ደረቀ እንደ ሳር። \nበለስ ለመለመች መኸርም ደረሰ። \nየሰውም ዘመኑ ሄደ ገሰገሰ። \nሁል ጊዜ ይሰማል ቃለ ዮሐንስ። \nዓለሙን ለማዳን ሥጋ በመልበስ/፫/። \nምሳሌ ደረሰ አምላከ ምሕረት። \nገለባና ፍሬው የሚለይበት። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር።', 'am', 7, 0),\n(7, 'ማን ይመራመር ቁ ፪', 'ማን ይመራመር ቁ ፪\nማን ይመራመር ማን ይመራመር/፪/ \nያንተን ግብር ያንተን ሥራ ማን ይመራመር ። \nማን ይመራመር  \nዓባይ ተሸምቶ ይቀናል በጌምድር። \nእየከዳ እንቢ አለ ወዳጅና ምድር ። \nያንተን ግብር ያንተን ሥራ ማን ይመራመር \nማን ይመራመር/፪/ \nእከድ እከድዬ ነገር ተበላሸ። \nበሥጋ ገበያ ስልከሰከስ መሸ። \nያንተን ግብር ያንተን ሥራ ማን ይመራመር \nማን ይመራመር  \nእንዲህ ስልከሰከስ ና ያልከኝ እንደሆን። \nአንት መጠየቅ ወዳድ ምን ይመለስ ይሆን። \nያንተን ግብር ያንተን ሥራ ማን ይመራመር \nእባክህ አምላኬ ስጠኝ መስታወት። \nየሰው ሥራ ጥዬ የእኔን አይበት። \nያንተን ግብር ያንተን ሥራ ማን ይመራመር', 'am', 8, 0),\n(7, 'ማን ይመራመር ቁ ፫', 'ማን ይመራመር ቁ ፫\nማን ይመራመር ማን ይመራመር/፪/ \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nማን ይመራመር/፪/ \nእባክህ አምላኬ ስጠኝ መስታወት። \nየሰው ሥራ ጥዬ የእኔን አይበት። \nያንተን ግብር ያንተን ሥራ ማን ይመራመር \nማን ይመራመር  \nእስከዚያው ድረስ ነው ሲሶ ማረሳችን። \nእንገባ የለም ወይ በየመሬታችን። \nያንተን ግብር ያንተን ሥራ ማን ይመራመር \nማን ይመራመር ማን ይመራመር/፪/ \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nማን ይመራመር ማን ይመራመር/፪/ \nጎድን ከዳቢቱ ጠፍጥፈህ ጥበሰው። \nእኪበላ ሞቱን አያውቅምና ሰው። \nያንተን ግብር ያንተን ሥራ ማን ይመራመር \nማን ይመራመር ማን ይመራመር/፪/ \nያንተን ግብር ያንተን ሥራ ማን ይመራመር \nእኔ አውቀው ነበረ የወጥን ጣዕምና። \nጥንቱን በጤና አዳም አልተሠራምና። \nያንተን ግብር ያንተን ሥራ ማን ይመራመር', 'am', 9, 0),\n(7, 'ይበላሃላ', 'ይበላሃላ\nይበላሃላ ይበላሃላ ። \nይበላሃላ ይበላሃላ። \nይበላሃላ ይበላሃላ። \nአለቃ ተሰማ ይበላሃላ። \nይበላሃላ ይበላሃላ ። \nእኔንም ጎንደር ይሸጡኛላ። \nይበላሃላ ይበላሃላ ። \nይበላሃላ ይበላሃላ። \nአሊ ሲሞት ያለብኝ አሳር። \nበአንድ እጄ ዶማ በአንድ እጄ ምሳር። \nይበላሃላ ይበላሃላ ። \nእኔንም ጎንደር ይሸጡኛላ። \nይበላሃላ ይበላሃላ ። \nእኔንም ጎንደር ይሸጡኛላ። \nይበላሃላ ይበላሃላ ። \nእኔንም ጎንደር ይሸጡኛላ። \nይበላሃላ ይበላሃላ ። \nይበላሃላ ይበላሃላ። \nይበላሃላ ይበላሃላ። \nእኔንም ጎንደር ይሸጡኛላ። \nይበላሃላ ይበላሃላ። \nእኔንም ጎንደር ይሸጡኛላ።', 'am', 10, 0),\n(7, 'በእንተ ፍቅረ አብ', 'በእንተ ፍቅረ አብ\nበእንተ ፍቅረ አብ ወወልድ ወመንፈስ ቅዱስ ኬንያ፣ \nእስእለኪ ማርያም በሃሌ ሉያ፣ \nኃዘና ስምኢ ወብካያ፣  \nለሀገሪትነ ኢትዮጵያ። \nበስመ አብ ወወልድ ወመንፈስ ቅዱስ ሥላሴ፣ \nብሂልየ ወጠንኩ ዘለኪ ውዳሴ፣ \nማርያም እህቱ ለሙሴ። \nእምቅድመ ሰማይ ወምድር ሀልዎትኪ፣  \nፀሐይ ወወርኅ ኢቀደሙኪ፣  \nመላእክተ ሰማይ ይትለአኩኪ። \nንዒ ንዒ ንዒ ማርያም፣  \nዘትነብሪ በአርያም፣  \nወንዒ ሠናይትየ ዘገነት ኤዶም። \nንዒ ንዒ ንዒ ድንግል፣ \nወልድኪ አማኑኤል፣ \nእግዚአ ምሕረት ወሣህል። \nንዒ ንዒ ንዒ ማርያም፣  \nምስለ ሚካኤል ወገብርኤል፣ \nመላእክተ ምሕረት ወሣህል። \nርግብየ ርግብየ ርግብየ ሠናይትየ፣ \nማርያም እሙ ለእግዚእየ፣ \nበቀለመ ወርቅ ጸሐፊ ስምየ። \nብፅዕት አንቲ መንግሥተ ጽድቅ፣ \nዘትመንኒ ማርያም መንበረ ሥላቅ፣ \nታቦትነ አንቲ እንተ ወርቅ። \nርግብየ ርግብየ ርግብየ ናዛዚትየ፣ \nማርያም እሙ ለእግዚእየ፣  \nበቀለመ ወርቅ ጸሐፊ ስምየ። \nርግብየ ርግብየ ርግብየ ሠናይትየ፣ \nማርያም እሙ ለእግዚእየ፣  \nበቀለመ ወርቅ ጸሐፊ ስምየ። \nንትፌሣህ ኵልነ በዝክረ ስምኪ ጥዑም፣ \nወበደመ አስካልኪ መዓድም፣ \nቅድስት ቅድስት ቅድስት ማርያም።  \nቤዛዊተ ኵሉ ዓለም፣ \nንትፌሣህ ኵልነ በዝክረ ስምኪ ጥዑም፣ \nወበደመ አስካልኪ መዓድም። \nቅድስት ቅድስት ቅድስት ማርያም፣  \nቤዛዊተ ኵሉ ዓለም።', 'am', 11, 0),\n(7, 'ቅዱስ', 'ቅዱስ\nቅዱስ ቅዱስ ቅዱስ እግዚአብሔር። \nዘወሀበ ሕገ ለሙሴ።  \nቅዱስ ቅዱስ ቅዱስ እግዚአብሔር። \nዘቀደሰ ክህነቶ ለአሮን። \nቅዱስ ቅዱስ ቅዱስ እግዚአብሔር። \nዘቀብዖ ለዳዊት ቅብዓ ትንቢት ወመንግሥት። \nቅዱስ ቅዱስ ቅዱስ እግዚአብሔር። \nዘበነኒያት አስተንፈሰ ከመ ያስምዕ ቃሉ ለሕዝብ። \nቅዱስ ቅዱስ ቅዱስ እግዚአብሔር  \nዘይሴብሕዎ መላእክት ወየአኵትዎ ሥልጣናት። \nግነዩ ለእግዚአብሔር ወጸውዑ ስሞ ሃሌ ሉያ።  \nወንግርዎሙ ለአሕዛብ ምግባሮ። \nሰላም ለኪ ማርያም ለኖኅ ሐመሩ።  \nሰላም ለኪ ለአሮን በትሩ።  \nሰላም ለኪ ለዳዊት መሰንቆ መዝሙሩ።  \nሰላም ለኪ ለፍሬ ስብሐት መፆሩ።  \nሰላም ለኪ ለጌዴዎን ፀምሩ።  \nሰላም ለኪ ለሰሎሞን መንበረ ክብሩ።  \nሰላም ለኪ ለፍሬ ስብሐት መፆሩ።  \nሰላም ለኪ እንዘ ንሴብህዎ ለበረከትኪ።  \nዘምስለ አምኃ ንስግድ ለኪ። \nበሐኪ ማርያም እምነ ወእግዝእትነ፣  \nትምክሕቶሙ አንቲ ለአዝማዲነ፣ \nበሰይፈ ሙስና ጽብዒ ፀረ ነፍሳቲነ። \nአንሶስዊ ወንዒ ማዕከሌነ፣  \nተሞጢሐኪ ብርሃነ መሐዚለኪ፣  \nሕፃነ ዮም እም ሰላመ ወልድኪ የሃሉ ምስሌነ።', 'am', 12, 0),\n(7, 'እግዚኦ', 'እግዚኦ\nእግዚኦ መሐረነ ክርስቶስ \nእግዚኦ መሐረነ ክርስቶስ \nእግዚኦ መሐረነ ክርስቶስ \nበእንተ ማርያም እግዚኦ መሐረነ ክርስቶስ \nበእንተ ማርያም እግዚኦ መሐረነ ክርስቶስ \nበእንተ ማርያም እግዚኦ መሐረነ ክርስቶስ \nእግዚኦ መሐረነ ክርስቶስ \nእግዚኦ መሐረነ ክርስቶስ \nእግዚኦ መሐረነ ክርስቶስ \nአድኅነነ ከመዓቱ ሰውረነ በምሕረቱ  \nበእንተ ማርያም ወላዲቱ \nአድኅነነ ከመዓቱ ሰውረነ በምሕረቱ  \nበእንተ ማርያም ወላዲቱ \nስምዓነ አምላክነ ወመድኃኒነ \nስምዓነ አምላክነ ወመድኃኒነ \nስምዓነ አምላክነ ወመድኃኒነ \nስምዓነ አምላክነ ወመድኃኒነ', 'am', 13, 0),\n(7, 'ክርስቶስ ተንሥዓ እሙታን', 'ክርስቶስ ተንሥዓ እሙታን\nክርስቶስ ተንሥዓ እሙታን ፤ ሞተ ወኬዶ ለሞት።  \nለእለ ውስተ መቃብር ፤ ወሃበ ሕይወተ ዘለዓለም ዕረፍተ። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ ይእዜኒ ወዘልፈኒ። \nክርስቶስ ተንሥዓ እሙታን ፤ ሞተ ወኬዶ ለሞት።  \nለእለ ውስተ መቃብር ፤ ወሃበ ሕይወተ ዘለዓለም ዕረፍተ። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ ይእዜኒ ወዘልፈኒ።\n ቀዳሚሁ ቃል ውእቱ ቃል ቃለ እግዚአብሔር ውእቱ ቃል ሥጋ \nኮነ።ወኀደረ ላዕሌነ ወርኢነ ስብሐቲሁ ከመ ስብሐት አሐዱ \nዋሕድ ለአቡሁ።ቃል ማሕያዊ ቃለ እግዚአብሔር ተንሥዓ \nወሥጋሁኒ ኢማሰነ።ተሣሀለኒ እግዚኦ በከመ ዕበየ ሣህልከ። \nወበከመ ብዙኀ ምሕረትከ ደምስስ ኃጢአትየ ወእምአበሳየኒ \nአንጽሐኒ።', 'am', 14, 0),\n(7, 'ቀን የጣለ እንደሆን', 'ቀን የጣለ እንደሆን\nዝናቡ መጣ ዳመናው።  \nእጀታ እንኳ የለኝ የምለብሰው።   \nእንዴት አባቴ ልሁን።  \nቀን የጣለ እንደሆን። \nከዚያ ላይ ሆኖ ቢጠራኝ።  \nወይ እንዳልለው ድምጽ የለኝ። \nባልሰማ እንጂ ነው ዝምታዬ። \nአቤት አቤት ጌታዬ።', 'am', 15, 0),\n(7, 'አባታችን', 'አባታችን\nአባታችን በሰማያት ላይ ያለህ። \nተለይቶ ይመስገን ክቡር ስምህ። \nመንግሥትህን የምንፈልጋት ከጥንቱ። \nበልጅነት ትምጣ ትሰጠን አቤቱ። \nፈቃድህም ይህ እንዲደረግ ይሁን። \nበሰማይ ሞተን ተነሥተን ከደይን። \nእንድንኖር ምስጋናህ ምግብ ሆኖን። \nዛሬም በምድር በሥጋ ሕይወት ሳለን። \nምግባችንን በየዕለቱ አውቀህ ስጠን። \nይቅር በለን የበደልንህም ቢኖር። \nወንድማችን የበደለንን ነገር። \nእንዳቅማችን እኛም እንድንል ይቅር። \nበገሃነም በክፉው ሁሉ መአት። \nአትጣለን አድነን እንጂ ከሞት። \nይቺን መንግሥት የማያገኛት ኅልፈት። \nጌትነትም ከሃሊነትም ክብርም። \nናቸውና የአንተ ገንዘቦች ሁሉም። \nለዓለም ወለዓለመ ዓለም አሜን። \nየተላከው ቅዱስ ገብርኤል ከጌታ። \nሰላም ለኪ ብሎ በሰጠሽ ሰላምታ። \nእኔ ባሪያሽ ልብሴን ስታጠቅ ስፈታ። \nሰላም ልልሽ ይገባኛል ጧት ማታ። \nማርያም ሆይ እመቤቴ ሆይ ድንግል። \nበሥጋሽም በሕሊናሽም ድንግል። \nየአሸናፊ የእግዚአብሔር እናት ድንግል። \nእንዳለሽ ቅዱስ ገብርኤል ሰላም። \nሰላም ለኪ እንደርሱ ሁሉ እኔም። \nየሌለብሽ የነፍስ የሥጋ መርገም። \nቡሩክ ነው የማሕፀንሽ ፍሬም። \nእንደቀድሞው ቡሩክ አምላክ ነው ዛሬም። \nእግዚአብሔር ወልድ በመጣ ጊዜ ለካሣ። \nእንበለ ዘርእ እንደ ንብና እንደ ዓሣ። \nከነፍስሽ ነፍስ ከሥጋሽ ሥጋ ቢነሳ። \nደስ ያለሽ ሆይ ጸጋን አግኝተሽ ከጌታ። \nደስ ይበልሽ በማቀርብልሽ ሰላምታ። \nለምኝልን ሳትሰለቺ ጧት ማታ። \nውድ ልጅሽ እንዲያደርግልን ይቅርታ። \nይቅር ብሎ ኃጢአታችንን ሁሉን። \nእንዲያድነን በአንቺ ተማፅነን አለን። \nለዓለም ወለዓለም ዓለም አሜን።', 'am', 16, 0),\n(7, 'እስመ አንተ', 'እስመ አንተ\nበስመ አብ ወወልድ ወመንፈስ ቅዱስ። \nአሐዱ አምላክ ብዬ ሰላምታ ላድርስ። \nእስመ አንተ አምላከ ሰማይ ወምድር። \nእስመ አንተ ምሉዐ ፀጋ ወክብር። \nትባላለህ በነግህ በሰዓት በቀትር። \nኢየሱስ ደግ ባለፀጋ ንጉሥ። \nኢየሱስ በአፈ ኩሉ ውዱስ። \nኢየሱስ ቀዳሴ ሥጋ ወነፍስ። \nወደላይ ልቤን ሰደድኩት እንዲያይ። \nቢያየው ዕፁብ ድንቅ ነው ግሩም። \nመንጦላእቱ የተጋረደው በፊቱ። \nየሚጥለው የሚዘረጋው አሽከር። \nአልታዘዝ ጭራሽ አይልም ፍጡር። \nከአንተ ዘንድ አይኮራም አሉኝ ዘመድ። \nከአንተ ደጅ አይኮራም አሉኝ ወዳጅ። \nከአንተ ሲደርስ አይኮራም አሉኝ ንጉሥ። \nከአንተ ሲደርስ አይኮራም አሉኝ ጳጳስ። \nአንተ እንጂ ነህ የማትዋረድ አታንስ። \nብርቱ ዳኛ ያለ አንተ  የለም ኃይለኛ። \nአንተ ስትወድ ሁሉ ይሆናል ዘመድ። \nብሉ ጠጡ ልበሱ ይላል በግድ። \nአንተ ስትጠላ የሚሆን የለን ከለላ። \nበቀኝ ያለው ዞሮ ይቆማል በግራ። \nስትወድማ ስትመልስማ ፊትህን። \nበመፃጉዕ አይተነው የለ ጉድህን። \nፈጣሪዬ በከንቱ አለቀች እድሜዬ። \nሳልገዛ እያሸነፈኝ ሥጋዬ። \nዳሩ ግና አዛኝ ርኅሩኅ ነህና። \nአደራህን የነፍሴን ነገር አትጥና። \nመበስበስ ደግሞ አለ ገና መፍረስ። \nመነሳት ደግሞ አለ ገና ፍርድ መስማት። \nባሕቲቱ እስመ ለዓለም ምሕረቱ። \nመላእክቱ  አይሸፍቱበት ከቤቱ። \nሌላ ጌታ ያለ አንተ  የለም በከንቱ። \nደህና ዋሉ ደህና ሰንብቱ አርፍዱ። \nየሚያውቅበት አንድም ሰው የለም በፍርዱ። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ። \nለዓለም እስከ ዘለዓለም ድረስ።', 'am', 17, 0),\n(7, 'ሰላም ለኪ ቁ ፩', 'ሰላም ለኪ ቁ ፩\nሰላም ለኪ ማርያም ድንግል ንጽሕት።  \nሰላም ለኪ ማርያም ድንግል ንጽሕት። \nሰላም ለኪ ማርያም ድንግል ንጽሕት። \nያችን ርግብ ያችን ወለላ ፍጥረት። \nበሰላምታ እስኪ እንወዝውዛት ጥቂት። \nየአምላክ እናት የሰማይ የምድር ፈጣሪ። \nየእርሷ አዝማሪ ዕዝራና ዳዊት በባሕሪ። \nቃል ኪዳኗ የማይፈርስባት ነዋሪ። \nእልፍ አእላፍ መላእክት አሉዋት ነባሪ። \nያገልግሉሽ ብሎ የሰጣት ፈጣሪ። \nእኛን ይዛ ፍጥረት ዓለሙን መካሪ። \nወለላዊት ቤዛዊት ዓለም ብፅዕት። \nከወተት ውዳሴሽ ጥዑም በእውነት። \nከወለላ ተአምርሽ ጥዑም ሲበላ። \nየብርሃን ዘውድ የብርሃን አክሊል ደፍተሽ። \nድረሺልን በሠረገላ ሆነሽ። \nይሸሻሉ አጋንንት አንቺን ሲያዩሽ። \nስታገለግል በቤተ መቅደስ ስትሠራ። \nነይ ውጭ አሏት ሊቃውንት መክረው በሴራ። \nተመቅኝተው ምናምን ኃጢአት ሳትሠራ። \nእንደ ፀሐይ ገላዋ እንደ እሳት ሲያበራ። \nትሙት ብለው ማየ ዘለፋን ቢያጠጧት። \nእንደገና ብርሃን መሆኑ ባሰባት። \nያንን ግሩም ያንን ደስ የሚል መዓዛ። \nበንጽሕና ያለ ሩካቤ  አርግዛ። \nወለደችው በቤተልሔም ተጉዛ። \nምጥ የለባት በመልአክ እጅ ተይዛ። \nየታደለች የተባረከች ፍጥረት። \nየበላውን ሰባ ስምንቱን ነፍሳት። \nአስገባችው በጥርኝ ውኃ ገነት። \nከአድማስ አድማስ ወረቀት ቢሆን መሬት። \nቀለም ቢሆን የሦስት ወር ውኃ ክረምት። \nብዕር ቢሆን የዚህ ዓለም ሁሉ ዕፅዋት። \nቢጻፍ አያልቅም የተአምርሽ ብዛት። \nንግበር ብሎ ገና ሲፈጥረን ከጥንት። \nፈጥሮ ሰጠን ድንግል ሕሊና ትሑት። \nበእርስዋ ሰበብ እንገባለን ገነት። \nተመልከቱት የእግዚአብሔርን ምሕረት። \nብንወርድበት መቼ ይወዳል ከእሳት። \nእኛ ግና በኃጢአታችን ብዛት። \nእንወድቃለን ከዚያ ጨለማ ክርፋት። \nአደራሽን ቤዛዊት ዓለም ብፅዕት። \nበማልቀስሽ በመጨነቅሽ ብዛት። \nሑሩ ሲለን እንድታወጪን ከእሳት። \nቃል ኪዳንሽ እጅግ ታላቅ ነው ከጥንት። \nአንቺን አምኖ እንዴት ይጎዳል ፍጥረት። \nማኅደሩ የአምላከ ሰማይ እናት። \nታይቶ አይጠገብ ሁልጊዜ የልጅሽ ምሕረት። \nእኛን በቀኝ እንድታቆሚን ያን ዕለት። \nለዓለም እስከ ዘለዓለም ዓለም።', 'am', 18, 0),\n(7, 'ሰላም ለኪ ቁ ፪', 'ሰላም ለኪ ቁ ፪\nሰላም ለኪ ማርያም ድንግል ንጽሕት።  \nሰላም ለኪ ማርያም ድንግል ንጽሕት። \nሰላም ለኪ ማርያም ድንግል ንጽሕት። \nያችን ርግብ ያችን ወለላ ፍጥረት። \nበሰላምታ እስኪ እንወዝውዛት ጥቂት። \nየአምላክ እናት የሰማይ የምድር ፈጣሪ። \nዕዝራ ዳዊት ሲያመሰግኗት በባሕሪ። \nቃል ኪዳኗ የማይፈርስባት ነባሪ። \nአምስት ሺህ መላእክት አሉዋት ነዋሪ። \nያገልግሉሽ ብሎ የሰጣት ፈጣሪ። \nእኛን ይዛ ፍጥረት ዓለሙን መካሪ።                            \nወለላዊት ቤዛዊት ዓለም ብፅዕት። \nከወተት ውዳሴሽ ጥዑም በእውነት። \nከወለላ ተአምርሽ ግሩም ሲበላ። \nለአፍ ጣፋጭ ላመሰገነሽ ሰው ሁላ። \nየብርሃን ዘውድ የብርሃን አክሊል ደፍተሽ። \nድረሺልን በሠረገላ ሆነሽ። \nይሸሻሉ ሰይጣናት አንቺን ሲያዩሽ። \nነፍሴን አስገቢያት መንግሥተ ሰማያት ነጥቀሽ። \nይባቤ አላት ግሩም የሆነ ደመና። \nላመናት ሰው የምትደርስለት ተጭና። \nዕፁብ ድንቅ ታሪኳ እንዲህ ነው ሲወራ። \nስታገለግል ለቤተ እግዚአብሔር ስትሠራ። \nነይ ውጭ አሏት ሊቃውንት መክረው በሴራ። \nተመቅኝተው ምናምን ኃጢአት ሳትሠራ። \nትሙት ብለው ማየዘለፋ ቢያጠጧት \nእንደገና ብርሃን መሆኑ ባሰሰባት። \nያንን ግሩም ያንን ደስታ መዓዛ። \nበህቡዓን ያለ ሩካቤን አርግዛ። \nወለደችው በቤተልሔም ተጉዛ። \nምጥ የለባት በመልአክ እጅ ተይዛ። \nየታደለች እንደሷ የለም ንጽሕት። \nየበላውን ሰባ ስምንቱን ፍጥረት። \nአስገባችው በጥርኝ ውኃ ገነት። \nግሩም እንበል የርኅሩኅነቷ ብዛት። \nአንቺን አምኖ እንዴት ይጎዳል ፍጥረት። \nከአድማስ አድማስ ወረቀት ቢሆን መሬት። \nብዕር ቢሆን የዚህ ዓለም ሁሉ ዕፅዋት። \nቀለም ቢሆን የሦስት ወር ውኃ ክረምት። \nቢጻፍ አያልቅም የተአምርሽ ብዛት። \nንግበር ብሎ ገና ሲፈጥራት ከጥንት። \nፈጥሮ ሰጠን እንድንገባለት ገነት ። \nእኛ ነና በኃጢአታችን ብዛት። \nእንገባለን ከዚያ ጨለማ ክርፋት። \nመች ትወዳለች ብንወድቅባት ከእሳት። \nአደራሽን ቤዛዊት ዓለም ብፅዕት። \nበመፅነስሽ በመጨነቅሽ ብዛት። \nከዚያ ለቅሶ እንድታወጪን ከሞት። \nሥጋ ለብሶ የማይረክስ የለም ፍጥረት። \nሰማይ ወምድር አንድም አለነበር ሥርዓት። \nእሷን ብቻ በሕሊና አምላክ ፈጥሯት። \nገብርኤልን መልአኩን ጠርቶ ቢያያት። \nበልቦናው አደረችበት ስስት። \nያንጊዜ ነው የተቀበሏት በሥርዓት። \nስትኖር አያሌ ዘመን ትንቢት። \nስትጸነስ በመንፈስ ቅዱስ ሥርዓት። \nስትወለድ ለቤተ እግዚአብሔር ሰጧት። \nእንቆ ባሕሪ ልዑላን መስላ ቢያዩዋት። \nምን እናብላት ይቺን መሳይ ፍጥረት። \nሲጨነቁ ፋኑኤል መጣ ቅጽበት። \nምግቧን ይዞ ኅብስተ መና ሕይወት። \nስቴ ወይኑ በብርሃን ጽዋ ይዞት። \nበታላቅ ክብር በብርሃን መሶብ ይዞት። \nሳያስቡ ደረሰባቸው ድንገት። \nዘካርያስ ለሱ የመጣ መስሎት። \nሊቀበለው እጁን ዘረጋ በፊት። \nመልአኩም ነጠቀ ራቀው ነቅፎት። \nዘካርያስ በልቡ አደረ እውቀት። \nአይታሰብም የእግዚአብሔር ነገር ድንገት። \nይህን ብሎ ሐናን ከሕዝቡ ለያት። \nአልወርድ አለ ከራሷ በላይ ቢያዩት። \nሕፃኒቱን ከእናቲቱ ቢለዩዋት። \nመልአኩ ወርዶ ክንፉን ጋርዶ መገባት። \nተደነቁ ሊቀ ሠራዊት ጠበብት። \nታይቶ አይታወቅ ሐርና ግምጃ አንጥፈው። \nግራና ቀኝ መከዳ ዙፋን ዘርግተው። \nከዚያ አኖሯት ከቤተመቅደስ አግብተው። \nምግቧ አይጎል ከጽርሐ አርያም ዘለለት። \nእልፍ አእላፋት እያጫወቷት መላእክት። \nበገበሬ እጅ ያልታረሰውን አትክልት። \nበቤተሰብ እጅ ያልተሠራውን ቀደምት። \nተመገበችው አሥራ ሁለቱን ዓመት። \nአይሁድንም እጅግ ያዛቸው ቅናት። \nፊት ነግሮናል ሞቶ ሲነሳ ላምናስ። \nትወልዳለች የሰማይ የምድር ንጉሥ። \nይህን ብለው እኒያም አሰቡ ክፋት። \nእንግደላት ብለው ተጓዙ ሌሊት።  \nመቅደሱን እንደ እሳት ሲነድ ቢያዩት። \nየመጡትም ምክንያት አጡ ጥቂት። \nእሳት ፈጃት ብለን እንግባ ከሀገር። \nይህን ብለው እኒያን ገቡ ከመንደር። \nሁለተኛ ደግሞ ቢያስቡ ነገር። \nመንገዳቸው ዱር ገደል ሆነ ባሕር \nተመካክረው ከጠንቋይ ሄዱ ላይሆን። \nምን ትላለህ የነ ኢያቄምን ነገር። \nያሴራሉ ሰማይ ሊገዙ ወምድር። \nከጠንቋይም አይጠፋምና ውሸት። \nለዚችማ ምን ተቸገረህ አሉት። \nእስቲ ለኔ በፊት ዋጋዬን አላቸው። \nአይሁድም እውነት የሚያደርግ መስሏቸው። \nወርቁም ብሩም ከቤት ሞላ ግምጃቸው። \nጠንቋዮቹም አድሮባቸው ኩራት። \nበጥበቡ ገንዘብ ያገኘ መስሎት። \nቁልፉን ከፍተው ከመዛግብቱ ቢያዩት። \nወርቁም ብሩም ገል ድንጋይ ሆነ ቅጽበት። \nላሙም በጉም ፍየል አልቀረም ሲበክት። \nብላን ክቶት ግምጃውን ሁሉ ዱቄት። \nእጁን ደፋ አንገቱን ደፋ መሬት። \nእይልኛ ደቂቀ እስራኤል ኩራት። \nየኢያቄም ልጅ ያረገችኝን በአስማት። \nይህንን ቢል እኒያም አጥብቀው ናቁት። \nእንኳን እግዚአብሔርን እንኳን አምላክን ማጥፋት። \nአንዲት ፍጥረት ግራ ገባችህ ሁከት። \nአሁንም እኛ የመጣን ወደ አንተ። \nከተችገርክ ጠላታችንን ማጥፋት። \nመልስልን ገንዘባችንን አሉት። \nይህን ቢሉት በልቡ አደረ ክፋት። \nከባሕር ሄዶ አጋንንት ሳበ ሌሊት። \nሰውን አርዶ አደረገላቸው መሥዋዕት። \nደጅ ሲጠና ለእመቤታችን ማጥፋት። \nከአጋንንቱም ምንጊዜ አይጠፋም ውሸት። \nሰማዩንም አውርዱ ብትል ዳስ ናት። \nመሬቱንም ጠቅሉ ብትል ነቅ ናት። \nምንቸገረን ለዚችማ አሉት። \nጠንቋዮችም በደስታ ሄዱ ከቤት። \nመክረው ዘክረው አጋንንቱም ቢመጡ። \nከአይሁድ ጋር ከሰባት መቶ በለጡ። \nእነዚህ ሁሉ ደጀ ሰላሙን ሳይረግጡ። \nበአዲስ መብረቅ ያንጊዜውኑ ቀለጡ። \nዳዊት እንኳን ሰማንያ እቁባት ቢከት። \nማርያምን እርሷን ያገኘ መስሎት። \nበየጊዜው ይሠራ ነበር ዝሙት። \nሌት ሌሊት ዐሥራ ሁለቱ መስኮት። \nየሚገባት ለእመቤታችን ትንቢት። \nኢየሱስም እናቱን ሲያከብር ሲላት ። \nወእምዬ ወይን ነው ጡትሽ ሲላት። \nይህን ሲላት ነፍሷ ይወጣል ስስት። \nትበርሂ ማርያም ድንግል ቅድስት። \nደስ እያላቸው የሚጠብቋት ፍጥረት። \nሰብአ ሰገል ሰምተው ነበር ትንቢት። \nሀገረ ፋርስ ሰባቱ ሁሉ ነገሥት። \nዘውድ ደፍተው ጌታን ፈልገው ስግደት። \nሊመጥኑ ሦስት ቀን ተጉዘው ቢያዩት። \nተቸገሩ ውኃና መንገድ ጠፍቷቸው። \nአራቱ ቀሩ በዱር አራዊት ብዛት። \nተመካክረው ሦስቱ ተነሡ ነገሥት። \nብርሃን ኮከብ እየመራቸው በፊት። \nምስለ ፍቁር ጌታን ታቅፋ ቢያዩዋት። \nቡርክት አንቲ የአምላክ ማኅደር እናት። \nይህን ብለው ሰብአ ሰገል ስግደት። \nወርቅና ዕጣን ከርቤም ጨምረው ሰጡት። \nዕጣኑንም አምላከ ልዑል ሲሉት። \nከርቤውንም አትቀርም ብለው ከሞት። \nሰብአ ሰገል በሦስቱ ትንቢት አዩት። \nስንቃቸውን ስግሙን አድርጋ ኅብስት። \nሸኘቻቸው ማርያም ድንግል ንስዑት።                         \nስብሐት ለአብ ለወልድ ለመንፈስ ቅዱስ።          \nአሐዱ አምላክ እስከ ዘለዓለም ድረስ።', 'am', 19, 0),\n(7, 'ይበላሃላ ቁ ፩', 'ይበላሃላ ቁ ፩\nይበላሃላ ይበላሃላ ።                                           \nይበላሃላ ይበላሃላ። \nአንተንም አፈር ይበላሃላ \nእንደሞኝ ሰው እንደተላላ። \nአሊ ሲሞት ያለብኝ አሳር። \nበአንድ እጄ ዶማ በአንድ እጄ ምሳር። \nአሊ ሲሞት መብሌ ጉበት። \nከአሊ በፊት እኔ ልሙት። \nአሊ ሲሞት መጠጤ አተላ። \nአንተንም አፈር ይበላሃላ  \nእኔንም ጎንደር ይሸጡኛላ። \nበላው አፈር በላው አፈር። \nያንን አንገት ያንን እግር። \nአንተንም አፈር ይበላሃላ  \nእንደሞኝ ሰው እንደተላላ። \nበላው አፈር በላው አፈር። \nያስተማረህን ያንን ምሁር። \nበላው መረሬ በላው መረሬ። \nያንን የዋህ ሰው ያንን ገበሬ። \nአንተንም አፈር ይበላሃላ  \nእንደሞኝ ሰው እንደተላላ። \nበላው አፈር በላው አፈር። \nያንን ታሪክ ያንን ዘመን። \nያንን ባሕል ያንን ፍቅር። \nያንን አንድነት ያንን ሕብረት። \nበላው አፈር በላው አፈር። \nአንተንም አፈር ይበላሃላ  \nእንደሞኝ ሰው እንደተላላ።', 'am', 20, 0),\n(7, 'ይበላሃላ ቁ ፪', ' ይበላሃላ ቁ ፪\nይበላሃላ ይበላሃላ። \nአንተንም አፈር ይበላሃላ።  \nእንደሞኝ ሰው እንደተላላ። \nይበላሃላ ይበላሃላ። \nአንተንም አፈር ይበላሃላ። \nእንደሞኝ ሰው እንደተላላ። \nአንተንም አፈር ይበላሃላ። \nበላው አፈር በላው አፈር። \nያንን ጎፈሬ ያንን ከንፈር።  \nይበላሃላ ይበላሃላ።  \nአንተንም አፈር ይበላሃላ። \nይበላሃላ ይበላሃላ። \nአንተንም አፈር ይበላሃላ።  \nእንደሞኝ ሰው እንደተላላ። \nይበላሃላ ይበላሃላ። \nአንተንም አፈር ይበላሃላ።    \nእንደሞኝ ሰው እንደተላላ።    \nአንተንም አፈር ይበላሃላ። \nበላው አፈር በላው አፈር። \nያንን ጎፈሬ ያንን ከንፈር።  \nይበላሃላ ይበላሃላ።   \nአንተንም አፈር ይበላሃላ።    \nእንደሞኝ ሰው እንደተላላ።  ', 'am', 21, 0),\n(7, 'አባ ግራኝ ሞተ ቁ ፩', ' አባ ግራኝ ሞተ ቁ ፩\nአባ ግራኝ ሞተ የሆዴ ወዳጅ/፪/ \nየሚያበላኝ ጮማ የሚያጠጣኝ ጠጅ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nታጠቅ ብሎ ፈረስ ካሳ ብሎ ስም/፪/ \nዓርብ ዓርብ ይሸበራል ኢየሩሳሌም። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nሺህ ገመድ ሺህ ጉራጅ የሸዋ ፈረስ /፪/ \nአንድ ጥርኝ ሆነ ቢዘልቅ ቴዎድሮስ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nፈረሱ አባ ታጠቅ ስሙ ቴዎድሮስ/፪/ \nጠላትን የሚበትን እንደ ዓውሎ ንፋስ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nመቅደላ አፋፉ ላይ ጩኸት በረከተ። \nየሴቱን አናውቅም ወንድ አንድ ሰው ሞተ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nመቅደላ መቅደላ አንቺ ክፉ ጎራ። \nሴቱን ሁሉ ንቆ ሲኮራ ሲኮራ።\nወንዱ አንቺን ወደደ ተኛ ካንቺ ጋራ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nአያችሁት ወይ ያን የአንበሳውን ሞት። \nበሰው እጅ መሞትን ነውር አድርጎት። \nእርሳሱን እንደ ጠጅ ጎርሶ ሲጠጣት። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nአውሮፖም ያውቁሃል አፍሪካም ያውቁሃል እስያም ያውቁሃል \nእንኳን የሰው ንጉሥ ውኃ እንኳን ፈርዶሃል። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ     \nአባትና እናቱ ያለ አንድ አልወለዱ። \nአባ ታጠቅ ካሳ ያ ወንዱ ያ ወንዱ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nየትግሬንም ንጉሥ ሲንቁ ሲንቁ። \nየሸዋንም ንጉሥ ሲንቁ ሲንቁ። \nወንድ ያለ ራስዎ ገድለውም አያውቁ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nገደልን እንዳይሉ ሞተው አገኙዋቸው። \nማረክን እንዳይሉ ሰው የለ በእጃቸው። \nምን አሉ እንግሊዞች ሲገቡ ሀገራቸው። \nመቼም ለወሬ አይመቹም ተንኮለኞች ናቸው። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nእንደ አፄ ቴዎድሮስ አላየሁም ኩሩ። \nቢመጡ እንግሊዞች ምክር ሊማከሩ። \nበአርምሞ ሸኙዋቸው ሳያነጋግሩ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ\n', 'am', 22, 0),\n(7, 'አባግራኝ ሞተ ቁ ፪', ' አባግራኝ ሞተ ቁ ፪\nአባግራኝ ሞተ የሆዴ ወዳጅ /፪/ \nየሚያበላኝ ጮማ የሚያጠጣኝ ጠጅ። \nታጠቅ ብሎ ፈረስ ካሳ ብሎ ስም/፪/ \nዓርብ ዓርብ ይሸበራል ኢየሩሳሌም። \nሺህ ገመድ ሺህ ጉራጅ የሸዋ ፈረስ/፪/ \nአንድ ጥርኝ ሆነ ቢዘልቅ ቴዎድሮስ። \nመቅደላ አፋፉ ላይ ጩኸት በረከተ። \nየሴቱን አናውቅም ወንድ አንድ ሰው ሞተ።  \nየትግሬንም ንጉሥ ሲንቁ ሲንቁ። \nየሸዋንም ንጉሥ ሲንቁ ሲንቁ። \nወንድ ያለ ራስዎ ገድለውም አያውቁ። \nገደልን እንዳይሉ ሞተው አገኙዋቸው። \nማረክን እንዳይሉ ሰው የለ በእጃቸው። \nምን አሉ እንግሊዞች ሲገቡ ሀገራቸው። \nመቼም ለወሬ አይመቹም ተንኮለኞች ናቸው። \nበገና በልደት አያምረኝም ሥጋ።  \nበገና በልደት አያምረኝም ጠጅ። \nኋላ በትንሣኤው አትንፈገኝ እንጅ።  \nአምላኬን አምላኬ ስለው ደስ ይለኛል/፪/ \nበቸገረኝ ጊዜ ከተፍ ይልልኛል። \nእስመ ኃያል አንተ እኩት ወስቡሕ/፪/ \nላመነህማ ሰው አንተ ትበቃለህ። \nእባክህ አምላኬ የምለምንህ/፪/ \nያጣ ሰው ሳያገኝ አይሙት አደራህ።  \nበደመ ነፍስህ እኛን መፍጠርህ/፪/ \nእንዲጠራልህ ነው ቅዱሱ ስምህ። \nመለስ ቀለስ ብላ አየችው ቀሚሷን/፪/ \nእረሳችውና ከአፈር መለወሷን። \nምን ያደርጋል ጠላ ምን ይሆናል ጠጅ/፪/ \nጠላትን መጋበዝ በአንድ እርጎ ነው እንጅ። \nየተጠበሰ ዓሣ ይሸታል እጃችሁ/፪/ \nኧረ እናተ ሰዎች  ዓሣ ማ አበላችሁ።   \nእናንት መኳንንቶች በምን ወጥ በላችሁ/፪/ \nእኛም በሽሯችን እናንተም በዓሣችሁ። \nዓሣ አትብሉ እያለ ቄሱ ሲራገም/፪/ \nዓሣ ማን  ይበላል በኩዳዴ ጾም። \nአብርሃም ቢጣላ ከሳራ ከሚስቱ። \nባርያውን አጋርን አስወጣት ከቤቱ። \nዳኛውም ፈረደ በሁለቱ ላይ። \nአንተም ሰርተህ ብላ አንቺም ሰርተሽ ብይ። \nያለ አጋር እንጀራ አይበላም ወይ። \n', 'am', 23, 0),\n(7, 'አባ ግራኝ ሞተ ቁ ፫', 'አባ ግራኝ ሞተ ቁ ፫\nአባ ግራኝ ሞተ የሆዴ ወዳጅ/፪/ \nየሚያበላኝ ጮማ የሚያጠጣኝ ጠጅ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nታጠቅ ብሎ ፈረስ ካሳ ብሎ ስም/፪/ \nዓርብ ዓርብ ይሸበራል ኢየሩሳሌም። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nሺህ ገመድ ሺህ ጉራጅ የሸዋ ፈረስ /፪/ \nአንድ ጥርኝ ሆነ ቢዘልቅ ቴዎድሮስ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nፈረሱ አባ ታጠቅ ስሙ ቴዎድሮስ/፪/ \nጠላትን የሚበትን እንደ ዓውሎ ንፋስ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nመቅደላ አፋፉ ላይ ጩኸት በረከተ/፪/ \nየሴቱን አናውቅም ወንድ አንድ ሰው ሞተ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nመቅደላ መቅደላ አንቺ ክፉ ጎራ።  \nሴቱን ሁሉ ንቆ ሲኮራ ሲኮራ። \nወንዱ አንቺን ወደደ ተኛ ካንቺ ጋራ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nገደልን እንዳይሉ ሞተው አገኙዋቸው። \nማረክን እንዳይሉ ሰው የለ በእጃቸው። \nምን አሉ እንግሊዞች ሲገቡ ሀገራቸው። \nመቼም ለወሬ አይመቹም ተንኮለኞች ናቸው። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nእንደ አፄ ቴዎድሮስ አላየሁም ኩሩ/፪/ \nቢመጡ እንግሊዞች ምክር ሊማከሩ። \nበአርምሞ ሸኙዋቸው ሳያነጋግሩ። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ\nአፍሪካም ያውቁሃል አውሮፖም ያውቁሃል  እስያም ያውቁሃል \nእንኳን የሰው ንጉሥ ውኃ እንኳን ፈርቶሃል። \nእኔ መዩ ቱርክ ባይ የምሸሽ ነኝ ወይ \nከአንበሳ ከዝሆን ከሰይጣን ከመልአክ አምላክ የሠራው/፪/ \nየአንበሳውም ለታ በጡጫ በእርግጫ ሲያሰኝዎት ዋለ \nየዝሆኑም ለታ ጫካ አውድማውን ሲያስጥስዎት ዋለ \nየሰይጣኑም ለታ ስደደው ግደለው ሲያሰኝዎት ዋለ \nየመልአኩም ለታ በርዶታል አልብሱት   \nእርቦታል አጉርሱት ሲያሰኝዎት ዋለ። \nቆንጥረው ቆንጥረው ሁሉን ያካበቱ። \nመቅደላ አፋፉ ላይ እራስዎን ገለው ሞቱ።', 'am', 24, 0),\n(7, 'ማን ይመራመር ቁ ፩', ' ማን ይመራመር ቁ ፩\nማን ይመራመር ማን ይመራመር/፪/ \nያንተን ሥራ ያንተን ግብር ማን ይመራመር። \nጎጃም ተሸምቶን ይቀናል በጌምድር/፪/ \nእየከዳ እምቢ አለን ወዳጅ እና ምድር። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nአለህም እንዳልል እንዲህ ይደረጋል። \nየለህም እንዳልል ይመሻል ይነጋል። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nእባክህ አምላኬ ስጠኝ መስታወት/፪/ \nየሰው ሥራ ጥዬ የእኔን አይበት።                           \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nእግዚአብሔር  ምን ይበል እኛ ቅጥ ብናጣ/፪/ \nበስምንተኛው ሺህ በቀጠሮው መጣ።  \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nእባክህ አምላኬን አትመራመረኝ/፪/ \nእንደ በላዔ ሰብእ በጥቂት ነገር ማረኝ። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር                 \nአንተ ነህ ይላሉ የዓለም ሁሉ ጌታ። \nሰማይና ምድርን ያቆምክ ያለዋልታ። \nወዴት እንዴት ይሆን ያለህበት ቦታ። \nእነግርህ ነበረ እኔ በቆይታ። \nየሠራችልኝን የእናትህን ወሮታ። \nያንጊዜ አትለይም እሷ ከእኔ እርዳታ። \nምግብና መጠጤን በውል አዘጋጅታ። \nእግሬን አሳጥባ ዙፋን አዘርግታ። \nትከተለኛለች ለእርሷ ልዕልና። \nለእርሷ ልዕልና የለውም ቅሬታ። \nልጇ ፍጹም ንጉሥ የለው ባለ ፋንታ። \nእኔስ ይገርመኛል ከጧት እስከ ማታ። \nካለሁበት ሀገር አለመለየቷ። \nለሁሉ ነው እርሷን ይህ ርኅሩኅነቷ። \nአይበዛም እንደ እኔ ይህ መልካምነቷ። \nአንቺ አማልጂን እንጂ መድኃኒት ለዓለሙ። \nወልደ አብ ሲለምን አባ ሥረይ ሎሙ። \nእመቤት እመቤት የዓለም መድኃኒት። \nእንድታማልጂን በዕለተ ምጽአት። \nምንም ክፉ ብንሆን አውቀን ብናጠፋ። \nአዛኝቷ አስምሪን እናት አትገፋ። \nንዑ ና ሑሩ ሲል ሲያደራጅ ልጅሽ። \nእንደ በላዔ ሰብእ ያድነን ጥላሽ። \nእባክህ አምላኬ አትመራመረኝ/፪/ \nእንደ በላዔ ሰብእ በጥቂት ነገር ማረኝ። \nያንተን ሥራ ያንተን ክብር ማን ይመራመር ', 'am', 25, 0),\n(7, 'ማን ይመራመር ቁ ፪', ' ማን ይመራመር ቁ ፪\nማን ይመራመር ማን ይመራመር/፪/ \nያንተን ሥራ ያንተን ግብር ማን ይመራመር። \nጎጃም ተሸምቶን ይቀናል በጌምድር/፪/ \nእየከዳ እምቢ አለን ወዳጅ እና ምድር። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nአዳምና ሔዋን ጠፍቷቸው መንገዱ/፪/  \nለሰው ልጅ መከራን ትተውለት ሄዱ። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nእስከዚያው ድረስ ነው ሲሶ ማረሳችን/፪/ \nእንገባው የለም ወይ በየመሬታችን። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nእግዚአብሔር ምን ይበል እኛ ቅጥ ብናጣ/፪/ \nበስምንተኛው ሺህ በቀጠሮው መጣ።  \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nአዳም በበደለው ጌታ ለዓለም ክሶ/፪/ \nቆሟል ቀራንዮን ከለሜዳ ለብሶ። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር \nአለህም እንዳልል እንዲህ ይደረጋል። \nየለህም እንዳልል ይመሻል ይነጋል።  \nያንተን ሥራ ያንተን ግብር ማን ይመራመር          \nአንተ ነህ ይላሉ የዓለም ሁሉ ጌታ። \nሰማይና ምድርን ያቆምክ ያለዋልታ። \nወዴት እንዴት ይሆን ያለህበት ቦታ። \nእነግርህ ነበረ እኔ በቆይታ። \nየሠራችልኝን የእናትህን ወሮታ። \nያንጊዜ አትለይም እሷ ከእኔ እርዳታ። \nምግብና መጠጤን በውል አዘጋጅታ። \nእግሬን አሳጥባ ዙፋን አዘርግታ። \nትከተለኛለች ለእርሷ ልዕልና። \nለሷ ልዕልና የለውም ቅሬታ። \nልጇ ፍጹም ንጉሥ የለው ባለ ፋንታ። \nእኔስ ይገርመኛል ከጧት እስከ ማታ። \nካለሁበት ሀገር አለመለየቷ። \nለሁሉም ነው እርሷ ይህ ርኅሩኅነቷ። \nአይበዛም እንደ እኔ ይህ መልካምነቷ። \nአንቺ አማልጂን እንጂ መድኃኒት ለዓለሙ። \nወልደ አብ ሲለምን አባ ሥረይ ሎሙ። \nእመቤት እመቤት የዓለም መድኃኒት። \nእንድታማልጂን በዕለተ ምጽአት። \nምንም ክፉ ብንሆን አውቀን ብናጠፋ። \nአዛኝቷ አስምሪን እናት አትገፋ። \nንዑ ና ሑሩ ሲል ሲያደራጅ ልጅሽ። \nእንደ በላዔ ሰብእ ያድነን ጥላሽ። \nእባክህ አምላኬን አትመራመረኝ/፪/ \nእንደ በላዔ ሰብእ በጥቂት ነገር ማረኝ። \nያንተን ሥራ ያንተን ክብር ማን ይመራመር \nማን ይመራመር ማን ይመራመር። \nያንተን ሥራ ያንተን ግብር ማን ይመራመር።  ', 'am', 26, 0),\n(7, 'የበገና አካላት', '  የበገና አካላት\nሰላም ለኪ እንዘ ንሰግድ ንብለኪ። \nማርያም እምነ በእንተ ሐና እምኪ። \nወኢያቄም ዘምስለ ዳዊት አቡኪ። \nሰአሊ ለነ ኀበ ክርስቶስ ወልድኪ። \nተዓብዮ ለእግዚእየ ነፍስየ። \nያፀግባ ወያለብሳ ፀሐየ። \nውዳሴሽን እናገራለሁ በዜና። \nላመነሽ ለወደደሽ ሰው በበገና። \nበበገና ይገኛል አሉ ትምህርት። \nዐሥሩ ጅማት ዐሥርቱ ቃላተ ኦሪት። \nድምጸ ቃሉ ደስ የሚያሰኘው ለሁሉ። \nተመራምሮ ለደረሰበት ሰው ሁሉ። \nጣቶቹ ግን የዚህ የዐሥሩ ጅማት። \nየኤርሚያስ የዐሥርቱ ነቢያት አይነት። \nጋድሙ ግና ከሁሉ በላይ ያለው። \nእግዚአብሔር  አብ አኃዜ ኩሉ ዓለም ነው። \nምሰሶው በስተቀኝ በኩል ያለው። \nመልአከ ምክሩ ሚካኤል ሊቀ መላእክት ነው \nምሰሶውም በስተግራ በኩል ያለው። \nብስራታዊው ገብርኤል ሊቀ መላእክት ነው። \nማፈኛው ግን የዐሥሩ አውታር በሚል። \nመስሎታል በብሂሞትና በሊዮታን። \nገበታው ግን ከልብሱ ጋራ ያለው።                \nየድንግል ማርያም ቅድስናዋ ነው። \nብርኩማው ግን የዚህ የዐሥሩ አውታር። \nደብረ ሲና የሙሴ የአሮን ሀገር። \nእንዚራው የዚህ የዐሥሩ ጅማት። \nመስሎታል በዐሥርቱ ቃላተ ኦሪት። \nድህንፃውም የዚህ የዐሥሩ አውታር። \nቅዱስ ቅዱስ የሰማይ ጌታ የምድር። \nየታሪኩ የድህንፃው ጠፈር። \nመስሎታል በሂታቸው ወርቅ አምሳል። \nዕፁብ ድንቅ ነው ማንም ለማየት አይችል። \nአውታሩ ግና የያዘውን እንጨት። \nመስሎታል በድንግል መሰረተ ሕይወት። \nየዚህን የመያዣውን ጠፈር። \nመስሎታል በኪሩቤል አምሳል። \nበገናውም ከኋላ የተበሳው። \nዳዊትን ለመግደል ሳኦል የወጋው ጦር ነው። \nሚካኤል ነግሮት በገናው መከተው። \nመታሰቢያ ነው ቀዳዳው የኋላው። \nመቺው ግና የዚህ የዐሥሩ አውታር። \nባለሟል ነው ከሰማይ ጌታ ከምድር። \nየሚሰማው የሚያዳምጠው ፍጥረት። \nጉባኤ ነው የሙሴ የአሮን ትምህርት። \nግሩም እንበል ወደ ላይኛው አባት። \nምሥጢሩ ይህ ነው የበገናው መሰረት።                \nአይገባም ለሳቅ ለዘፈን መምታት። \nእናመስግነው የዘለዓለምን አባት። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ። \nለዓለም እስከ ዘለዓለም ድረስ። ', 'am', 27, 0),\n(7, 'ዋኔን', ' ዋኔን\nምን ያጣላችኋል ዋኔን  \nበመሬት ጉዳይ ዋኔን \nአሁን ዘር ሲጠፋ ዋኔን ይቀር የለም ወይ ዋኔን/፪/ \nምድርን ጠላ መጥመቅ ዋኔን  \nማን አስተማረው ዋኔን \nእየጠራ አጠጣው ዋኔን ያንን ሁሉ ሰው ዋኔን/፪/ \nበል እደር ጆሮዬ ዋኔን \nነገ እቆርጥሃለው ዋኔን \nባንተም ክፉ ነገር ዋኔን ሰምቼብሀለው ዋኔን/፪/ \nወይ አላሳጨድነው ዋኔን \nወይ ከብት አልበላው ዋኔን \nከቶ መቼ ይሆን ዋኔን ያ ሳር ማለቂያው ዋኔን/፪/ \nብላጨው አመመኝ ዋኔን \nብሠራው ከፋኝ ዋኔን \nአንድ ራሴ እኮ ነው ዋኔን የሚያስጨንቀኝ ዋኔን/፪/ \nየሁዳዴውስ ጾም ዋኔን \nምንም አላለው ዋኔን \nሰው ሁሉ ያለቀው ዋኔን በማማቱ ነው ዋኔን/፪/ \nበባላገር ነበር ዋኔን \nኑሮስ የሚሻል ዋኔን \nከተማ ሰው ገብቶ ዋኔን ምን ሰው ይሆናል ዋኔን/፪/ ', 'am', 28, 0),\n(7, 'እራሴን አሞኝ', ' እራሴን አሞኝ\nእራሴን አሞኝ እያያችሁ። \nለምን ሰከረ ትላላችሁ። \nአሁን ማን ሰጠኝ ለኔ ጠጅ። \nእንጀራ አዞረኝ እንጅ። \nአባት ልጁን እረግሞት። \nበጣም አጥብቆ ተጣልቶት። \nይታረቀዋል አሁንም። \nረግሞት አይቀርም። \nከጎረቤቴ ብጣላ። \nሰው ሁሉ ለሷ አደላ።   \nያለ ፈጣሪ ማን አለኝ። \nከሁሉ ባዳ ነኝ። \nመኳንንቶቹ ሰለጠኑ።  \nየእጨጌን ሀገር ለመኑ። \nእኔ ምፈራው ይህንን። \nከአጉል በላይ መሆን። \nየቀድሞ ዘመን ስሕተት። \nበጾም ቀን ዓሣን መብላት። \nያሁን ዘመን ሰው አያውቅ መላ። \nበጦም ሽሮ ነው የሚበላ። \nየዛሬ ዘመን ሰው ትሑት። \nተዋራጅ ሆኗል ለፍጥረት። \nግን አይጠፋም አንዳንድ። \nኮራም እያለ የሚሄድ።  \nአርባ ሁዳዴ መሆደድ። \nአክፍሎት አለ የግድ። \nየሰው ሁሉ መጎጃው። \nበማማት እንጂ ነው። \nእያን እስሚዝ። \nተሰየመ አሉ ቀሲስ። \nበእንግሊዙ ጳጳስ። \nእጁን ዘረጋ ለነጮቹ። \nመስቀሉን ለጥቁሮቹ። \nየዛሬ ዘመን ልጆች። \nእያሉ ነገር ላይ ታች።                                 \nእኖራለሁ ብል በሀገሬ ።  \nምነው ሰው አደነኝ እንደ አውሬ።  \n፲፭. ዓለም ማረፊያ ናት \nዓለም ማረፊያ ናት መኖሪያ ገነት/፪/ \nተነሡ እንከተል እኛም ከሄዱት። \nአፈር ከሸተተን ከያዘን በሽታ።                   \nብንቆርብ አንድንም ይህን ጊዜ እንበርታ። \nመቁረብ በሕይወት ነው ንስሐ መግባት/፪/ \nይህ ኩሉ አይገኝም ከገቡ መሬት። \nቆዳ እየለበሱ ከገዳም ሲኖሩ። \nከእነሱ አይለይም የአምላካችን ፍቅሩ። \nወርቅ የለበሰና ያጌጠ ፍጡር። \nክብሩ ሁሉ ቀረ ደረቀ እንደ ሳር። \nይህን ተመልክቶ ይጠንቀቅ ፍጡር/፪/ \nበለስ ለመለመ መኸርም ደረሰ። \nየሰውም ዘመኑ ሄደ ገሰገሰ። \nሁል ጊዜ ይሰማል ቃለ ዮሐንስ። \nዓለሙን ለማዳን ሥጋ በመልበስ። \nምሳሌ ደረሰ አምላከ ምሕረት። \nገለባና ፍሬን የሚለይበት። \nገለባው ይወድቃል ፈጠኖ ወደ እሳት። \nገለባው ይወድቃል ፈጠኖ ወደ እሳት። \nፍሬው ግን ይገባል ከቅዱሳን ቤት ። \nፍሬው ግን ይገባል ከቅዱሳን ቤት። \nለአብርሃም ለይስሐቅ የሰጠኸውን። \nዛሬም ለሕዝቦችህ ስጠን ሕይወትን/፪/ \nመጣጣር ከንቱ ነው ሁልጊዜ ለሥጋ። \nጾምን ካላወቅን አትገኝም ጸጋን/፪/ \nካለመጾም ሊያገኝ መንፈስ ቅዱስን። \nጸጋ ብሎ ጠራው አንድ ሰው ልጁን።  \nየኦሪት ቃል ዘሎ ወንጌል ካዘዘው። \nዋ ጊዜ ደረሰን አንዱን ሳልሠራው/፪/ \nዋ ጊዜ ደረሰ ሳስብ ሌላ ሌላ። \nእጅግ ያታልላል የዚህ ዓለም ተድላ። \nጥቂት ላይሰነብት ላይቆየን ለኋላ። \nጥቂት ላይሰነብት ላይቆየን ለኋላ። ', 'am', 29, 0),\n(7, 'አላየንም በሉ', ' አላየንም በሉ\nአላየንም በሉ ኧረ አልሰማንም በሉ \nያ ሞት ሲፈልገን ሲሻን ውሏል አሉ። እስቲ አላየንም በሉ \nአላየንም በሉ ኧረ አልሰማንም በሉ \nያ ሞት ሲፈልገን ሲሻን ውሏል አሉ ።እስቲ አላየንም በሉ \nእንዴት እሆናለሁ ኧረ እንዴት እሆናለሁ። \nአሁንም ከፍቶኛል ኋላም እሞታለሁ። እስቲ አላየንም በሉ \nማረፊያዬን አላውቅ ተጉዤ ተጉዤ። \nእስከ መቼ ድረስ እንዲህ ተወዝውዤ። እስቲ አላየንም በሉ \nአላየንም በሉ ኧረ አልሰማንም በሉ \nያ ሞት ሲፈልገን ሲሻን ውሏል አሉ። እስቲ አላየንም በሉ \nአስከሬን አጓዡ አንተ ጥቁር መኪና።                              \nለምን አትሰለችም ማለት ደፋ ቀና። እስቲ አላየንም በሉ \nመውሰድ እንጂ መመለስ አታውቅበትም ከቶ። \nመንጠቅ ልማድህ ነው ጎትቶ ጎትቶ። እስቲ አላየንም በሉ \nእኔማ  ጠጅህን ምን አደርገዋለሁ። \nእኔማ  ጮማህን ምን አደርገዋለሁ። \nበራሴ አዘንብዬ በዐይኔ እቀዳዋለሁ። እስቲ አላየንም በሉ \nአላየንም በሉ ኧረ አልሰማንም በሉ \nያ ሞት ሲፈልገን ሲሻን ውሏል አሉ። እስቲ አላየንም በሉ \nሞት በደጄን መጣ መንገዱ አረገኝ። \nዳግመኛ ቢመጣ ካለ እኔ አያገኝ። እስቲ አላየንም በሉ \nአላየንም በሉ ኧረ አልሰማንም በሉ \nያ ሞት ሲፈልገን ሲሻን ውሏል አሉ። \nእስቲ አላየንም በሉ ', 'am', 30, 0),\n(7, 'ወንድሜ ጠፍቶ', ' ወንድሜ ጠፍቶ\nወንድሜ ጠፍቶኝ ስሄድ።  \nነብር አግኝቶኝ ከመንገድ። \nአልተመለስኩም ወዲያው ሄድኩኝ።  \nእኔን ይብላኝ እያልኩኝ። \nየቀድሞ ዘመን ስሕተት።  \nበጾም ቀን ዓሣን መብላት። \nያሁን ዘመን ሰው አያውቅ መላ።  \nበጦም ሽሮ ነው የሚበላ። \nየኛ መድኃኒት አይነቶች ። \nበብዙ አሉን ቅመሞች። \nነገር ግን እኔ ሳስበው ። \nሥራ ስሩ መልካም ነው። \nያባቶቻችን ውኃ ዋና።  \nላይ ላዩን ነበር በጤና። \nየዛሬ ልጆች ይበልጣሉ።  \nውስጥ ለውስጥም ይሄዳሉ። \nኮሶ ተጣብቶኝ ትላንትና። \nመድኃኒት ስሻን ዋልኩና። \nድንገት ሰማሁኝ አንድ ዜና።  \nየወዲያ ሰዎች ሕግ ደንብ።  \nአይከለክልም ምግብ። \nየኛ ሥርዓት ከባድ።  \nእንዲያው በባዶ ሆድ። \nየጌታችንን ጠባይ።  \nያለ እኔ የሚያውቅ አለ ወይ። \nማታ ለግብር መልካም ሰው።  \nቀን ሲቆጣ ክፉ ሰው። \nአያሳስትም ሰዓት።  \nቀጠሮ ያከብራል ሞት። \nሽማግሌ አይል ሕጻን ። \nሞት ጠያቂ ነው ሁሉን። \nአሁን ይመጣል በእውነት።  \nሙት ብሎ አይቀርም ሞት።     \nእሑድ ቅዳሜ ቢሆን።  \nእበላ ነበር ምሳዬን። \nእንዲህ በጦም ቀን የምዞረው።  \nለጊዜ ማድረሻ ነው። \nትንሽ ቤት ሠራሁኝ እንደ አቅመኛ።  \nሁለት ሦስት ሰው የምታስተኛ። \nአላስገባ አለች እሷው ጠባ።  \nሰው በሰው ላይ እየገባ። \nከታች ጉርጓዱ የጠለቀ።  \nከላይ ጉበኑ የጠበቀ። \nእንዲህም አርገው ቢሠሩት። \nመፍረሱ አይቀርም ቤት። \nየዛሬ ዘመን ሰው ሥራ።  \nሳሩም ቅጠሉም አያኮራ። \nእውቀቱስ ያንተ መሰለኝ።  \nበአብነትህ አድነኝ። \nአባቶቻችን ካህናት።  \nሲጠመጥሙን ከጥንት። \nለስልጣናቸው ለክህነት። \nመለያ ነበር ምልክት። \nአሁንማ ጠምጣሚዎቹ። \nሹሞቹና ጠበቆቹ። \nይች በቅሎዬን ምን ሆነች።  \nአጉል መጥፎ አመል ለመደች። \nየጎረቤቷን እያየች ። \nጭነት መገልበጥ አመጣች። \nየሰሞኑ ጋብቻን ድንቅነቱ።  \nከቀድሞ እጅጉን መለየቱ። \nመሆኑ ቀርቶ እስከ ሞት ። \nተጀመረ ተጧሪ ፈቶ ወጣት ማግባት። \n', 'am', 31, 0),\n(7, 'ተው ስማኝ ሀገሬ', ' ተው ስማኝ ሀገሬ\nተው ስማኝ ሀገሬ  ኧረ ስማኝ ሀገሬ /፪/ \nተው ስማኝ ሀገሬ  ሲከፋኝ ነው መኖሬ ኧረ ስማኝ ሀገሬ  \nየገዳይ አጋዳይ ኧረ ስማኝ ሀገሬ ። \nሆነህ ከመመለስ ኧረ ስማኝ ሀገሬ ። \nእልም ጥርግ በል እስከወዲያው ድረስ ኧረ ስማኝ ሀገሬ/፪/ \nለፍጥረቱ ሁሉ ኧረ ስማኝ ሀገሬ  ። \nባያል ቸረፍ ቸረህ ኧረ ስማኝ ሀገሬ ። \nእኔስ በሀገሬ  ብኖር ምን ቸገረህ ኧረ ስማኝ ሀገሬ /፪/ \nመካሪዬ በዛ ኧረ ስማኝ ሀገሬ ። \nቤት ሥራ የሚለው ኧረ ስማኝ ሀገሬ ። \nምን ያታክተኛል አሁን ላፈርሰው ኧረ ስማኝ ሀገሬ  /፪/ \nአሉባልታ ሰምተው ኧረ ስማኝ ሀገሬ ። \nእውነት ነው ያሉ ኧረ ስማኝ ሀገሬ ። \nያሳባቂ ወሬ ኧረ ስማኝ ሀገሬ ። \nእየተቀበሉ ኧረ ስማኝ ሀገሬ ። \nመግባባት ቀረና ኧረ ስማኝ ሀገሬ ።  \nከረረ ነገሩ ኧረ ስማኝ ሀገሬ ። \nእናትና ልጁ ተቆራርጠው ቀሩ ኧረ ስማኝ ሀገሬ  \nአባትና ልጁ ተቆራርጠው ቀሩ ኧረ ስማኝ ሀገሬ  \nጆሮ ያለው ይስማ ኧረ ስማኝ ሀገሬ ። \nየወንጌሉን ቃል ኧረ ስማኝ ሀገሬ ። \nራሱን ያዋረደ ከፍ ከፍ ይላል ኧረ ስማኝ ሀገሬ  /፪/ \nቁጠባ ሳናደርግ ኧረ ስማኝ ሀገሬ ። \nተሻምተን በልተን ኧረ ስማኝ ሀገሬ ። \nእነኛ ወጥ አጡ እኛ እንጀራ አጣን ኧረ ስማኝ ሀገሬ  /፪/ \nሽምብራውን ዘርተን ኧረ ስማኝ ሀገሬ ።  \nእሸቱን ስንበላ ኧረ ስማኝ ሀገሬ ። \nአወይ የእኛ ነገር ሁልጊዜ ጥርጠራ ኧረ ስማኝ ሀገሬ /፪/   \nሌሊት ከጭቃ ላይ ኧረ ስማኝ ሀገሬ ። \nፈረስ ቢጥልህ ኧረ ስማኝ ሀገሬ ። \nወንድሜ አትናደድ ኧረ ስማኝ ሀገሬ ። \nማንም አላየህ ኧረ ስማኝ ሀገሬ ። \nይልቁን ተጠንቀቅ ቀን እንዳይጥልህ ኧረ ስማኝ ሀገሬ /፪/ \nቀለምና ቀለም ኧረ ስማኝ ሀገሬ  ። \nተጣልተው በቦታ ኧረ ስማኝ ሀገሬ ። \nጊዜ ተሰጥቷቸው ኧረ ስማኝ ሀገሬ ። \nየቀጠሮ ተርታ ኧረ ስማኝ ሀገሬ ። \nነገሩን ብንጠይቅ ኧረ ስማኝ ሀገሬ ።  \nአግድሞ ካለፈ ኧረ ስማኝ ሀገሬ ። \nብለው ገለጹልን ወገን አሸነፈ ኧረ ስማኝ ሀገሬ /፪/ \nለፈረስ ለበቅሎ ኧረ ስማኝ ሀገሬ  ። \nይተርፍ የነበረ ኧረ ስማኝ ሀገሬ ። \nዛሬስ ለሰው ያ እህል ይቸግር ጀመረ ኧረ ስማኝ ሀገሬ /፪/ \nሳጥናኤል ከሚስቱ ኧረ ስማኝ ሀገሬ ። \nተጣልቶ ሲፋታ ኧረ ስማኝ ሀገሬ ። \nዲያቢሎስ ከሚስቱ ኧረ ስማኝ ሀገሬ ።  \nተጣልቶ ሲፋታ ኧረ ስማኝ ሀገሬ ። \nለእሷ የደረሳት ኧረ ስማኝ ሀገሬ ።  \nቀሚስና ኩታ ኧረ ስማኝ ሀገሬ ። \nቀሚስና ኩታ ኧረ ስማኝ ሀገሬ  ። \nለእሷ ቢደርሳት ኧረ ስማኝ ሀገሬ ። \nምን ያሳዝንሃል ኧረ ስማኝ ሀገሬ ። \nብዙ ልባም አለ ላንተም ይደርስሃል ኧረ ስማኝ ሀገሬ  \nግራ አዝማች ሙቀጫ ኧረ ስማኝ ሀገሬ ። \nደጃዝማች ጀበና ኧረ ስማኝ ሀገሬ ። \nፊት አውራሪ ስኒ ኧረ ስማኝ ሀገሬ ። \nቀኝ አዝማቹ ቁርስ ኧረ ስማኝ ሀገሬ ። \nእኒህ በሀገር ሳሉ አትማርም ነፍስ ኧረ ስማኝ ሀገሬ /፪/ \nተው ስማኝ ሀገሬ  ኧረ ስማኝ ሀገሬ ።                     \nተው ስማኝ ሀገሬ  ሲከፋኝ ነው መኖሬ ኧረ ስማኝ ሀገሬ ። \n', 'am', 32, 0),\n(7, 'መዲና እና ዘለሰኛ', ' መዲና እና ዘለሰኛ\nከወዲያ ወዲህ ተጣርተው።  \nሙታን በአንድ ላይ ተሰብስበው። \nያጫውታሉ የሞቱት። \nቁመው ለሚሄዱት። \nየእኛ መድኃኒት አይነቶች ። \nበብዙ አሉን ቅመሞች። \nነገር ግን እኔ ሳስበው ። \nሥራ ስሩ መልካም ነው። \nየዛሬ ዘመን ገረድ ሎሌ። \nአይታዘዝም እንደ አመሌ። \nአንቱም ብለውም ይሄዳል። \nአንተ ያልከው ይኖራል። \n፴፫ \nየዛሬ ዘመን ምላስ ። \nተስማምቷል አሉ ከጥርስ። \nእኔ ሳልሰማው ቢያኝከኝ። \nምንኛ አደቀቀኝ። \nገረዴ ሄዳ በድንገት። \nአሽከሬ ሆኖ ወጥ ቤት። \nየምበላውን ሳይጠይቀኝ። \nሥጋ ሰርቶ አስጨነቀኝ ። \nገረዴ ለምዳ ጨዋታ። \nእኔ ብጠራት ከወዴት ሰምታ። \nአለች ይሉኛል ከዚያ ላይ። \nወይ ብላ አትመጣም ወይ። ', 'am', 33, 0),\n(7, 'አባቶቻችን', '  አባቶቻችን\nአባቶቻችን እየሞቱ።  \nሳይቆረብ ነው የተፈቱ። \nየዛሬ ልጆች ጉድ አፈሉ። \nከቁርባን ውጪም ይፈታሉ። \nየድሀ ድካም በየዓመቱ። \nጥንት የቆየ ነው ከአባቱ። \nሃብታሙስ እንኳ እንዳያርፍ። \nከመ ጽላሎት ይኀልፍ። \nበአልጋ መኝታ በጠፍር። \nመልካም መስለን ነበር። \nአባቶቼን ግን ሳያቸው። \nሁሉም በመሬት ናቸው። \nየበገና መዝሙሮች  \nየተወለደ ከአዳም ። \nመሬት ያልገዛ የለም። \nግብሩን መገበር አቅቷቸው። \nገና ብዙ እዳ አለባቸው። \nየአባቶቼ ርስት ቀርቶብኝ። \nጥቂትስ እንኳን ባልቆጨኝ። \nየሰሞን መሬት ገዝቻለሁ። \nእየቆረብኩ እበላለሁ። \nየአባቶቻችን ፍቅር ። \nበልባቸው ውስጥ ነበር። \nየዘመኑ ልጆች አጎሉት። \nበከናፍር ውሸት።  ', 'am', 34, 0),\n(7, 'ከተለዩት ልዩ', ' ከተለዩት ልዩ\nከተለዩት ልዩ /፪/ ከንጹሐን ንጽሕት ርቱዕ ያረገሽ። \nከተለዩት ልዩ /፪/ ከንጹሐን ንጽሕት ርቱዕ ያረገሽ። \nቅድስት ድንግል ማርያም ፍጥረት አማላጅ ነሽ።  \nቅድስት ድንግል ማርያም ፍጥረት አማላጅ ነሽ። \nየብርሃን መውጫ /፪/ የአምላክ መሰላል ነች። \nየብርሃን መውጫ /፪/ የአምላክ መሰላል ነች። \n______________________________ /፪/ \nእመቤቴ ማርያም /፫/ጠጅ እያማረሽ። \nእመቤቴ ማርያም /፫/ጠጅ እያማረሽ። \nማር አትይውም ወይ ሲቆርጥ ልጅሽ/፪/ \nእመቤቴ ማርያም /፫/ ቆሚያለሁ ተደጅሽ። \nእመቤቴ ማርያም /፫/ ቆሚያለሁ ተደጅሽ። \nታማልጂኝ ብዬ ታንድዬ ተልጅሽ/፪/ \nየአብርሃም እናት የአማኑኤል እናት የመድኃኔዓለም/፪/ \n___________________________________ /፪/ \nእምዬ/፬/እናቴ ማርያም። \nእምዬ/፬/እናቴ ማርያም። \nእንዳንቺ ያዘለኝ ያቀፈኝ የለም/፪/ ', 'am', 35, 0),\n(7, 'ሥነ ፍጥረት', ' ሥነ ፍጥረት\nበስመ አብ ወወልድ ወመንፈስ ቅዱስ። \nአሐዱ አምላክ ብዬ ሰላምታ ላድርስ። \nለፈጠርከኝ ላንተ የላይኛው ንጉሥ። \nእንዴት አለህ መጥቼ እስካይህ ድረስ። \nያስደንቃል ያኗኗራቸው የጥንቱ። \nየአብ የወልድ የመንፈስ ቅዱስ የሦስቱ። \nሦስት ናቸው በአካል በገጽ በስም። \nአንድ ናቸው በትእዛዝ በክብር ፍጹም። \nሥላሴም እምቅድመ ዓለም ሲኖሩ። \nዓለም መፍጠር እሑድ በሠርክ ጀመሩ። \nያን ጊዜውን ሰባት ፈጠሩ ቅጽበት። \nአስቀድመው ሰማይና ምድርን በፊት። \nአራተኛ መላእክትና ጽልመት። \nሰባተኛ ማይና ነፋስ እሳት። \nበአርምሞ ይህንን ሁሉ ፈጥረው።  \nተናገሩ ለይኩን ብርሃን ብለው። \nሰኞ ጧት ውኃን ከፈሉት ከሦስት። \nአንደኛውን አዘቅት አረጉት ከምድር። \nሁለቱን ሰማይ አረጉት ጠፈር። \nማክሰኞም አብቅይ አሏት ምድርን። \nአበቀለች ሳር ቅጠሉን እህሉን። \nእሮብም ረቂቅ ሥራን ሲሠሩን። \nከዋክብትን ፀሐይ ጨረቃን ፈጠሩን። \nሐሙስም አልተውምና መፍጠር። \nየሚበሩ ክንፍ ያላቸውን ነገር። \nየማይበሩ የሚሄዱትን በእግር። \nበባሕርም ዓሣ ጉማሬ ሳይቀር  \nዓርብ ጧት አዳምን የኛን አባት። \nንግበር ብለው በነሱ አምሳል ሠሩት። \nበሠለስት ሔዋንን ፈጥረው ሰጡት። \nትርዳህ ብለው ብቻውን ሆኖ ቢያዩት። \nየሥላሴም የፍጥረታቸው ፍጻሜ። \nበሰባት ቀን ዳርቻ ሆነች ቅዳሜ። \nንግበር ሲባል አዳም ሲፈጠር ከጥንቱ። \nከአብ ከወልድ ከመንፈስ ቅዱስ ከሦስቱ። \nአልተለየም ከሥላሴ አምሳል ፍጥረቱ። \nበአርባ ቀኑ ተከፈተለት ገነቱ። \nከዚያ ገባ ከማትጠገብ መንግሥቱ። \nአፈቀረው አዳምን ጌታ በብርቱ። \nበአዳም ቀንተው መላእክቶቹም ሸፈቱ። \nስሙን ስተው በሚካኤል ሰይፍ ተመቱ። \nተበተኑ ፍጥረት ዓለሙን ሊያስቱ። \nተዋረዱ ቀንድና ጅራት ጎተቱ። \nሳጥናኤልም ምንም አረባው ኩራቱ። \nበምድረ ፋይድ ሲኦል ወረደ ከአዘቅቱ። \nተተብትቦ በእሳት ሰንሰለት አንገቱ። \nተበላሽቶ ዐይንና ጥርሱ ቁመቱ። \nጽልመት ለብሶ ብርሃኑ ቀርቶ ክብረቱ። \nበድንጋጤ ነፍስ የሚያወጣ ክርፋቱ። \nግሩም ነበር የአዳም ከገነት ሕይወቱ። \nላይጠቅመው በለስን በላ በከንቱ። \nየዚያን ጊዜ ጸጋው ሲረግፍ ጩኸቱ። \nተቤሄሞ እስከ ለዩዋታን ድርሰቱ። \nአረገደች ተንቀጠቀጠች ምድሪቱ። \nበዚያች ስፍራ በዚያች በምድረ ገነት። \nእንዳልተመለከተ እንዳላየ በውነት። \nምንተ ኮንኪ ብሎ ጠየቃት ድንገት። \nምንተ ኮንኪ ብሎ ጠየቀው ድንገት ። \nእኒያም አሉ ሰይጣን አሳተን አቤቱ። \nከአዳም ሳይሆን ከሔዋን ሆኖ ጥፋቱ። \nተረገመች ለዘለዓለም ሴቲቱ።  \nደሟ እንዲፊስ በተመተረች ዕፂቱ። \nኑሩ አላቸው እረገማቸው አጥንቶ። \nፈቃድ ጥሰው የሠሩት ኃጢአት በርትቶ። \nሑሩ ብሎ ሲሰደው ያን ቀን ሲኦል። \nተናገረው አዳምን ጌታ በቃል። \nእመጣና አድንሃለሁ አንተን። \nከአምስት ሺህ ተአምስት ቀን ተኩል። \nአማርኛ አያውቅም ነበር እንደኛ። \nየዋህ ነበር የማይመረምር ነገር። \nእሑድ ወርዶ ሐሙስ ጠበቀው በቀትር። \nጌታም አየው እጅግ ሲጨነቅ ሲያዝን። \nመልአክ ጠርቶ ለአዳም ላከበት ቃሉን። \nእመጣና አድንሃለሁ አንተን። \nበአምስት ሺህ ከአምስት መቶ ዘመን። \nተወልጄ ከልጅ ልጆችህ ወገን። \nይህን ወስዶ ከአምላክ ቢነግረው መልአክ። \nደነገጠ ቀኑ የራቀ መስሎት። \nአለቀሰ የሦስት ወር ዝናም ክረምት። \nግሩም እንበል የጌታችንን ምሕረት። \nቃል ወረደ ሥጋ ለበሰ ሊሞት። \nበበደለው አዳም ባጠፋው ስሕተት። \nተወለደ በመልካም በዓል ልደት። \nደስ አላቸው የጠበቁት ሁሉ ፍጥረት። \nበዚያን ጊዜ የሄሮድስ ነበር መንግሥት። \nተመቅኝቶ በልቡ አደረ ቅናት። \nይህን ሰምታ ማርያም ድንግል ንጽሕት። \nልጇን ይዛ ምድረ ግብጽ ሄደች ስደት። \nሄሮድስ ሞተ ሲኦል ወረደ ቢሏት። \nተመለሰች ከዚያው ከሀገሯ ናዝሬት። \nጌታችንም እያስተማረ ቃሉን። \nእየዞረ ሠላሳ ሦስት ዘመን። \nሐዋርያት እየተማሩ ሕጉን። \nተከተሉት እያመኑለት ቃሉን። \nይክደኛል ይላቸው ነበር አንዱን። \nከእኒያ አብልጦ ይወደው ነበር እሱን። \nተገለጠ ይሁዳ ከዳው ወዲያው። \nሐሙስ ማታ ለሠላሳ ብር ሸጠው። \nወርቁን ወስዶ ለሊቀ ካህኑ ቢሰጠው። \nመለሱለት አንቀበልም ብለው። \nተፀፅቶ ታንቆ ወደቀ ከዚያው። \nእሬሳውን አውጥተው ጣሉት ወዲያው። \nከሀዲ ነው እንደ ከልብ ይሁን ብለው። \nጴጥሮስንም እንዲያ ሲወደው ሲያምነው። \nበአራት ሰዓት ሦስት ጊዜ ጌታን ከዳው። \nቢያስጨንቁት ቢያስወተውቱት ይዘው። \nአይሁድም ጌታን መርምረው ያዙት።  \nየእግዚአብሔር ልጅ እውን አንተ ነህ አሉት። \nአልመለሰም ለጠየቁት ቃል አንዲት። \nለጲላጦስ ወስደው ለሹሙ ሰጡት። \nመረመረው ኢየሱስንም በእውነት። \nአልተገኘም አንዲት አበሳ ኃጢአት። \nተፈረደ ከዚያ አደባባይ ሐሰት። \nአላበሳው እንበለ አግባብ ሊሞት። \nጲላጦስም ያንጊዜ አይሁድን ፈርቷቸው። \nስንና ብርት ከፊቱ አቅርቦ ጠራቸው። \nእጁን ታጥቦ ከደሙ ነጻሑ አላቸው። \nጲላጦስም በልቡ አድሮበት እምነት። \nኢየሱስን አስቦት ነበር እውነት። \nአሸነፉት እነዚያ ሁሉ ፈያት። \nተሰቀለ ጊዜ ሰባት ሰዓት። \nበቀትር ተንቀጠቀጠች ምድር። \nበከሰዓት ፀሐይም ሆነች ጽልመት። \nቁርጡን አውቃ በደም ጠለቀች ጨረቃ። \nቢጨነቁ ከዋክብት ሁሉ ወደቁ ። \nአታክልትም ዕፅዋት ሁሉ ደረቁ። \nእውር ነበር እረዥም ዘመን ወራት። \nአፉን አይሁድ ለኢየሱስ ሰጥቶ ልቡን። \nሞተ ብሎ በጦር ቢወጋው ጎኑን ። \nተፈንጥቆ ደሙ ቢነካው ዐይኑን። \nያንጊዜውን ተከሰተለት ብርሃን። \nስቡሕ ብሎ አመሰገነው ጌታን። \nእነ ዮሴፍ በድኑን ለመውሰድ ለመኑ። \nበድኑን ወስደው በነጭ በፍታ ከፈኑ። \nጎልጎታ ወስደው አንጸው ቀብረው። \nአለቀሱ ሐዋርያትም መጥተው። \nቀዳሚት ፍስሐ ኮነ በጧት። \nእሑድ ሌሊት በጊዜ ስድስቱ ሰዓት። \nየጌታችን ትንሣኤ ሆነ በእውነት። \nከመንበሩ ከላይ ሲወጣ መድኅን። \nለሐዋርያት ሹመት ሰጣቸው ሥልጣን። \nሊያስተምሩ አራቱን አሕጉር ሁሉን። \nብንለምነው እንጀራ ስጠን ብለን። \nሥጋዬን ብሉ ደሜንም ጠጡት አለን። \nእንዳናስብ እንዳንቸገር ሲያዝን። \nበሥጋውም አበቀለልን ስንዴን። \nበደሙ አምሳል አበቀለልን ወይንን። \nይህ ይበቃል ላደነቀው ሰው ጌታን። \nስብሐት ለአብ ለወልድ ለመንፈስ ቅዱስ። \nለዓለም እስከ ዘለዓለም ድረስ።  ', 'am', 36, 0),\n(7, 'ልደት', ' ልደት\nድንግልም በምትወልድበት ወራት። \nበሮም ንጉሥ በአውግስጦስ ቄሳር መንግሥት። \nሰው ሁሉ ግብር ሊቆጠር ታዘዘ። \nዮሴፍም ድንግልን ይዞ ተጓዘ። \nከገሊላ ከነበረበት መንደር። \nቤተልሔም ወደምትባል ሀገር። \nከኤፍራታ ይወጣል ብሎ ንጉሥ። \nሚክያስ የተናገረው ሊደርስ። \nሳታፋልስ የወላዶችን ሥርዓት። \nበታህሳስ ሃያ ዘጠኝ ዕለት። \nከዚያው ሳሉ የምትወልድበት ቢደርስ። \nተወለደ ድንግልናዋን ሳይጥስ። \nቤት ባይኖራት መጥታለችና ከሩቅ። \nከበረት ጠቀለለችው በጨርቅ። \nሊፈጸም የኢሳይያስ ነገሩን። \nእንስሳትም ትንፋሻቸውን ገበሩ። \nከዚያ ቦታ ከብት ጠባቂዎች ነበሩ። \nያዩ ነበር ካሉበት ቦታ ድረስ። \nየብርሃን ጎርፍ ከቤተልሔም ሲፈስ። \nእረኞቹም የብርሃኑን ጎርፍ አይተው። \nእጅግ ፈሩ ምን ነገር ነው ብለው። \nመልአኩም ፍርሃታቸውን አርቆ።                     \nነገራቸው ተድላ ደስታውን አድንቆ። \nልዑል አምላክ ለአዳም ብሎ ተዋርዶ። \nከድንግል በዳዊት ባሕርይ ተወልዶ። \nጨርቅ ለብሶ ከበረት መሐል ተጥሎ። \nአለላችሁ ኼዳችሁ እዩት በቶሎ። \nእንዲህ ብሎ ሲናገራቸው በዜና። \nከእርሱ ጋራ ብዙ መላእክት መጡና። \nአቀረቡ ከእረኞች ጋር ምስጋና። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ። \nለዓለም እስከ ዘለዓለም ድረስ። ', 'am', 37, 0),\n(7, 'ሆሣዕና', ' ሆሣዕና\nፋሲካቸው በስምንት ቀን ሊሆን። \nከፋሲካ በሚቀድመው ሰሞን። \nዘካርያስ የሚባል ነብይ ካህን። \nደስ ይበልሽ ኢየሩሳሌም ጽዮን። \nንጉሥሽ ይመጣልና አሁን። \nበአህያ ላይ እንደ አንድ ድሀ ምስኪን። \nእንዲህ ብሎ የተናገረው ቃሉን። \nለመፈጸም በአህያ ሆኖ መድኅን። \nሲመጣ አይታ እርሱ መሆኑን ለይታ። \nሀገሪቱ ተቀበለችው በእልልታ። \nበመንገዱም ቅጠሉን ሁሉ ቆርጠው። \nልብሳቸውን ያነጠፉ አሉ ከሕዝቡ። \nሁለተኛም ዳዊት የአምላክ ልቡና።   \nሲዘምር እያስማማ በገና። \nአስቀድሞ ይቺን ዕለት አየና። \nሲሰብክልን የዚችን ዕለት ዜና። \nአዘጋጀ ከሕፃናት አፍ ምስጋና። \nላለው ትንቢት መፈጸሚያ ቀን ናትና። \nእንዲህ ሆኖ ከቤተ መቅደስ ሲገባ። \nሕፃናቱ እየወረዱ ከጀርባ። \nበጣታቸው እየጨበጡ ዘንባባ። \nበእግዚአብሔር ስም የምትመጣው አምላክ። \nቡሩክ ነህ ለዘለዓለም ቡሩክ። \nየዳዊት ልጅ መድኃኒት ብትሆን ለሁሉ። \nሆሣዕና መባል ተገባህ እያሉ። \nተቀናጡ በፊት በፊቱ ዘለሉ። \nይህን ሰምተው ፈሪሳውያን ጸሐፍት። \nቢናደዱ ቢሞላባቸው ቅናት። \nሕፃናቱን ተዉ በላቸው አሉት። \nእንዲህ አለ ሲመልስላቸው ጌታ። \nከጠላችሁ የሕፃናቱን እልልታ። \nድንጋዮቹ የሚገባቸው ዝምታ። \nያመስግኑ በእናንት በሰዎት ፋንታ። \nበዚህ ጊዜ አምላክነቱን ሊገልጡ። \nድንጋዮቹ በፊት በፊቱ እየሮጡ። \nእንደ ሰዎች የምስጋና ድምጽ ሰጡ። \nስብሐት ለአብ ለወልድ ለመንፈስ ቅዱስ።  \nለዓለም እስከ ዘለዓለም ድረስ። ', 'am', 38, 0),\n(7, 'ሕማማት', ' ሕማማት\nበስመ አብ ወወልድ ወመንፈስ ቅዱስ።  \nአስቀድሞ ዓርብ ሊሰቀል ሐሙስ ። \nግሩም ሥራ ሲሠራ አመሸ ክርስቶስ።  \nበአይሁድም በካህናቱም ልማድ። \nየፋሲካን በዓል ሊያከብር ቢወድ ። \nበጉን አርደው ሊያዘጋጁለት መአድ። \nወደ ሀገር ሁለት ተማሮች ሰደደ ።  \nኦሪትን ሊያሰናብታት ወደደ። \nተማሮቹም አዘጋጁለት ሁሉን። \nመግለምቱን የሚያርዱበት በጉን። \nብርቱንም ሚቀበሉበት ደሙን።  \nሥጋውን ሚቀቅሉበት ድስቱን።  \nጌታም ሄዶ ተማሮቹንም ጨምሮ።  \nሲመገብ የአይሁድን በዓል አክብሮ።  \nዝናር ታጥቆ የለበሰውን አኑሮ።  \nጌታ ሲሆን በኩስኩስት ውኃ አቅርቦ። \nእንደ ሎሌ የተማሮቹን እግር አጥቦ። \nእግራቸውን በታጠቀው ልብስ እያሸ። \nትሕትና ሲያስተምራቸው አመሸ። \nአስቀድሞ እንደ ኦሪት ሥርዓት። \nአበላቸው የተሠዋውን ጠቦት። \nበዚህ ጊዜ ወቅሶ እንደ መሻር ሹምን።  \nአሳለፈው የኦሪትን ሕግ ሁሉን።  \nተቀምጠው በደስታና በተድላ። \nያረዱትን በጉን ከበሉ በኋላ። \nከገባለት ከብዙ ዳቦ ለይቶ። \nአንዱን ዳቦ ያላረረውን አንሥቶ። \nሕዝቡ እያዩ በአደባባይ ላይ በሸንጎ። \nየሚፈተት ፍጹም ሥጋውን አድርጎ። \nበጣቶቹ እየባረከ ገመሰ። \nአጠቃቅኖ ዐሥራ ሦስት አርጎ ቆረሰ።   \nለቀሳውስት መምህር አብነት ሊሆን።  \nመጀመሪያ ተቀበለና አንዱን።  \nነገ በቀትር ለዓለም ቤዛ ሊሆን። \nይህ እንዲደረግ እንዴት ይቻላል ሳትሉ። \nእንኩ ብሉ ብሎ ሰጣቸው ለሁሉ። \nተቀብለው ፍጹም ሥጋውን ሲበሉ። \nእንደ ስንዴ ወይንን ከሁሉ አብልጦ። \nተርታውን ወይን ትኩስ ደም አርጎ ለውጦ። \nአንድ ሐራዊ ለዓለም ቤዛ ሊሆን። \nጎኔን ወግቶ የሚያፈሰውን ይህን። \nእንኩ ጠጡ ብሎ ሰጣቸው ደሙን። \nበዚህ ጊዜ መክሮ እንደመሾም ሹምን። \nሠራላቸው ደገኛይቱን ሕጉን። \nዛሬም እኛ ይህን አብነት አርገን። \nለቀሳውስት ኃጢአታችንን ነግረን።  \nበንስሐ ከኃጢአታችን  ነጽተን። \nተርታው ኅብስት በቀሳውስቱ ሥልጣን። \nተለውጦ ሥጋ መሆኑን አምነን። \nተርታውም ወይን ደም እንደሆነ አውቀን። \nብንቀበል አሜን ወአሜን ብለን። \nያድነናል ያወጣናል ከደይን። \nእንኖራለን ሐዋርያትን መስለን። \nደግሞም በግብር እንደ ይሁዳ ብንሆን።  \nተለውጦ ሥጋ መሆኑን ክደን። \nሥጋውን ብንቀበለው ደፍረን። \nእሳት ሆኖ ያቃጥለናል እኛን። \nደሙንም ብንቀበለው ደፍረን። \nባሕር ሆኖ ያሰጥመናል እኛን። \nያወርሰናል በመዳን ፋንታ ሞትን። \nከተናገርን የሥጋ ደሙን ምሥጢር። \nእንመለስ ወደ ስቅለቱ ነገር። \nእንዲህ አርገው ወደ ደብረ ዘይት ሲወጡ። \nነገራቸው የሞቱን ነገር በቁርጡ። \nበዚች ሌሊት አይሁድ ሊይዙኝ ሲመጡ። \nጥላችሁን ትሄዳላችሁ ከሌላ። \nእኔም ሞቼ ከመነሣቴ በኋላ። \nመታየትን እጀምራለሁ ገሊላ።   \nእንዲህ ብሎ ቢናገራቸው ክርስቶስ። \nሲመልስ እንደዚህ አለ ጴጥሮስ።  \nሁሉ ቢክድ እኔ አልክድህም እያለ። \nቢደነፋ ጥቂት የሚቆይ መሰለ። \nጌታም አለ አይቀርምና መያዜ። \nዶሮ ሳይጮህ ትክደኛለህ ሦስት ጊዜ። \nመለሰለት እንደዚህ ብሎ ጴጥሮስ። \nጨክኛለሁ ከደረስክበት ልደርስ። \nአልክድህም አልለይህም እኔስ። \nእንዲህ ብሎ ሲመካ ሰምተው ለራሱ። \nየቀሩትም ይመኩ ጀመር እንደርሱ። \nከዚያም ወጥተው አብረው ሊሄዱ ተነሡ። \nጌቴሴማን ከሚባል ቦታ ደረሱ። \nጌቴሴማን ስምንቱን ሰዎች አኑሮ። \nወዳጆቹን ሦስቱን ተማሮች ጨምሮ። \nጥቂት አልፎ ያዝን ጀመረ ጠንክሮ።  \nከዱርም ከዚያም እልፍ ብሎ ጥቂት። \nብቻውን ይጸልይ ጀመር ጸሎት። \nግንባሩን ከምድር አድርሶ ሰገደ። \nወዙ በዝቶ እንደ ወንዝ ውኃ ወረደ። \nተመላልሶ ተማሮቹን እያየ። \nሦስት ጊዜ የፍርሃት ጸሎት ጸለየ። \nሲፈራ አይቶ እሩቅ ብእሲ ነው ብሎ። \nዲያብሎስ እንዲቀርብለት በቶሎ። \nበሦስተኛው ጊዜው ነውና ደክሟቸው። \nሲያንቀላፉ ሐዋርያትን ቢያያቸው። \nእንግዲህስ ጥቂት እረፉ አላቸው። \nስብሐት ለአብ ለወልድ ወመንፈስ ቅዱስ። \nለዓለም እስከ ዘለዓለም ድረስ።  ', 'am', 39, 0),\n(7, 'እግዚአብሔርም', ' እግዚአብሔርም\nእግዚአብሔርም አዳም ባጠፋው ጥፋት። \nበተስፋ ቃል አሰናበተው ያን ዕለት። \nለአዳም በገባለት ቃል ኪዳን።                          \nአምስት ሺህ ከአምስት መቶ ዘመን። \nሲፈፀም ያ የተስፋ ቃል ደረሰ። \nየአዳም የስቃይ ዘመን ፈረሰ። \nአዳምም ሲኖር በሲኦል ተቀብሮ። \nአዳነው ሞቱን በሞቱ ቀይሮ። \nአምላክም ወደዚህ ዓለም ሲመጣ። \nቆየችው እመቤታችን ተመርጣ። \nየሌለባት መርገም ፍዳ ከጥንት። \nጸነሰችው በመልአኩ ቃል ብስራት። \nፍቅር ስቦት ወደዚህ ዓለም መጣና። \nለአዳም ምን ያልሆነለት አለና። \nተወለደና ድንግልናዋን ሳይሽር።   \nለሰው ልጅ ሲል ተመላለሰ በምድር። \nበዮርዳኖስ በዮሐንስ እጅ ተጠምቆ። \nበዲያብሎስ የተጻፈውን ተራምዶ። \nአጠፋለት ያንን ደብዳቤ ደምስሶ። \nከባርነት የሚያላቅቀው ጨርሶ። \nበመስቀል ላይ በዕለተ ዓርብ ተወግቶ። \nከሲኦል በደሙ አነጻው አውጥቶ። \nእንዲህ አድርጎ ወደ ጥንት ቦታው መለሰው። \nበምሕረቱ ዳግም ገነትን አሳየው። \nበአባታችን በአዳም ጥፋት በደል። \nገብተን ነበር እኛ ሁላችን ሲኦል። \nበሥራችን በኃጢአታችን እኛማ። \nሆነን ነበር ከመርገም ግዞት ጨለማ። \nግን አዳነን የፍቅር አምላክ ነውና። \nበትሕትና እናቅርብለት ምስጋና። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ። \nለዓለም እስከ ዘለዓለም ድረስ። ', 'am', 40, 0),\n(7, 'ከቶ አይቀርም ሞቱ', 'ከቶ አይቀርም ሞቱ\nከቶ አይቀርም ሞቱ ምንም ቢታክቱ \nከቶ አይቀርም ሞቱ ምንም ቢታክቱን ምን ቢሰነብቱ \nሞት ፊደል ተምሮ ያነባል ስንል። ከቶ አይቀርም ሞቱ \nሞት ፊደል ተምሮ ያነባል ስንል። እንኳን ሊያነብና \nእንኳን ሊያነብና ገና ያግዛል። ከቶ አይቀርም ሞቱ \nእህል ታሟል አሉ በእግሬ ልገስግስ። ከቶ አይቀርም ሞቱ \nእህል ታሟል አሉ በእግሬ ልገስግስ። እሞት የለሁም ወይ \nእሞት የሁለም ወይ በቅሎማ እስኪደርስ። ከቶ አይቀርም ሞቱ \nእኔን መስሎኝ ነበር ድሀ ነው ደካሚ። ከቶ አይቀርም ሞቱ   \nእኔን መስሎኝ ነበር ድሀ ነው ደካሚ። ለካስ ሁሉም ኖሯል \nለካስ ሁሉም ኖሯል አፈር ተሸካሚ። ከቶ አይቀርም ሞቱ \nበሉ እናንተም ሂዱ እኛም ወደዚያው ነው። ከቶ አይቀርም ሞቱ \nበሉ እናንተም ሂዱ እኛም ወደዚያው ነው። ወትሮም መንገደኛ \nወትሮም መንገደኛ ፊትና ኋላ ነው ።ከቶ አይቀርም ሞቱ \nለሠሪው ለመስጠት አፈሩን ይዣለሁ። ከቶ አይቀርም ሞቱ \nለሠሪው ለመስጠት አፈሩን ይዣለሁ። ገል አፈር መሆኑን \nገል አፈር መሆኑን ተረድቼዋለሁ። ከቶ አይቀርም ሞቱ \nእኔስ ፍረድ ቢሉኝ ሞት በደለኛ ነው። ከቶ አይቀርም ሞቱ \nእኔስ ፍረድ ቢሉኝ ሞት በደለኛ ነው። አንድ ሰው ለምስል \nአንድ ሰው ለምስል ቆሞስ ቢቀር ምነው። ከቶ አይቀርም ሞቱ \nሞት ይቅር ይላሉ ሞት ቢቀር አልወድም። ከቶ አይቀርም ሞቱ \nሞት ይቅር ይላሉ ሞት ቢቀር አልወድም። ድንጋዩም አፈሩም \nአፈሩም ድንጋዩም ከሰው ፊት አይከብድም። ከቶ አይቀርም ሞቱ \nሂያጅ ተሳፋሪ ሰዎች ከሆናችሁ። ከቶ አይቀርም ሞቱ \nሂያጅ ተሳፋሪ ሰዎች ከሆናችሁ። ኧረ ለመቼው ቀን \nኧረ ለመቼው ቀን ቤት ትሠራላችሁ። ከቶ አይቀርም ሞቱ \nእረገጡኝ ብለህ ምድር አትቆጣ። ከቶ አይቀርም ሞቱ \nእረገጡኝ ብለህ ምድር አትቆጣ። ይህ ኩሉ ያንተ ነው \nይህ ኩሉ ያንተ ነው ሸማውን ቢያነጣ። ከቶ አይቀርም ሞቱ  \nዲያቆናት ቀሳውስት ደብተሮች በሙሉ። ከቶ አይቀርም ሞቱ \nዲያቆናት ቀሳውስት ደብተሮች በሙሉ። ለመቀደስ ሲሉ \nለመቀደስ ሲሉ መካን ይወዳሉ። ከቶ አይቀርም ሞቱ \nከቶ አይቀርም ሞቱን ምንም ቢታክቱ ምን ቢሰነብቱ \nከቶ አይቀርም ሞቱ ', 'am', 41, 0),\n(7, 'ሞቶ አይቀርም', ' ሞቶ አይቀርም\nከቶ አይቀርም ሞቱ ምንም ቢታክቱ  \nከቶ አይቀርም ሞቱን ምንም ቢታክቱ። ምን ቢሰነብቱ \nዕፁብ ድንቅ እንጂ ነው የጌታ ስቅለቱ። እንዲህ በአርምሞን \nእንዲህ በአርምሞን በእንዲህንያል ምክንያት።አልቀው ሕፃናቱ  \nየዮሴፍ ሶሎሜን ጌታ ከእነ እናቱን። ሆረ ደብረ ጉስቋም \nሆረ ደብረ ጉስቋም ምድረ ግብጽ ስደቱን። በዚያ በበረሃን \nበመንከራተቱን ውኃ እየለመነች። እመቤት እናቱ \nየሄሮድስን ጥፋት ተሰማና ሞቱ። ምድረ ናዝሬት ገባች \nከሕይወት ርስቱን ወዲያውም ደረሰን። ለመምህርነቱ  \nአርባ ሌሊት መዓልት ጾመ ወጸሎቱ። በእደ ዮሐንስ \nበእደ ዮሐንስ በባሕረ ዮርዳኖስ። የጌታ ጥምቀቱ   \nተጽዕኖ ገባን በነአስ እድገቱን። ሆሣዕና ዳዊት  \nለዓለም መድኃኒቱን ኪራላይሶም ብለው። ሰግደዋል ካህናቱ \nደቂቀ ሠራዊት አልቀሩም ዓበይቱ። ጌታችን ተይዞን  \nበጊዜ ሠለስቱን ወድቆ ተገረፈ። ለምለም አካላቱ \nሰቀሉከ ኢየሱስ ግፍዖሙ ዝንቱ። ዘለፌ ወለፌን  \nዘለፌ ወለፌን አዕ በአንተ ማቱ። ፀሐይም ጠለቀች  \nሆነ እንደ ሌሊቱን ጨረቃም ደም ሆነ። ሸሸ ብርሃናቱ  \nሳሩም ደረቀናን ቅጠሉም አትክልቱ። ከዋክብት እረግፈው  \nታጡ ካሉበቱን ሲገርፉት ሲያዳፉት። ሲወድቅ በደረቱ \nበስተኋላው ቁመው ስበው ወደ አንገቱ። በስተፊቱ ቁመው \nስበው በደረቱ ስቅሎ ስቅሎ። አሉት ሲዛበቱ \nሲገርፉት ሲያዳፉት ሲወድቅ በደረቱ። በከየት ማርያም \nበከየት ማርያም አዘነች እናቱ። ጌታችን ተነሣን \nምድረ ቀራዮን መስቀል መሰረቱ። ጌታችን ተነሣን \nበዕለተ ሰንበቱን መጎስቆሉ ቀረ። መጣ ጌትነቱ \nጽኑ ሽብር ሆነን አይሁድ ተፀፀቱ። ዲያብሎስ ድል ሆነ \nከነ ሠራዊቱን ቁልቁለት ወረደን። በመትት እርስቱ \nአዳምን አወጣው ምስለ ብእሲቱ። ወዲያው ገነት መራው \nከቀደምት ርስቱን ዕፁብ ድንቅ እንጂ ነው። የጌታ ስቅለቱ \nከቶ አይቀርም ሞቱን ምንም ቢታክቱ። ምን ቢሰነብቱ \nከቶ አይቀርም ሞቱ ', 'am', 42, 0),\n(7, 'ዕፁብ ድንቅ እንጂ ነው', ' ዕፁብ ድንቅ እንጂ ነው\nዕፁብ ድንቅ እንጂ ነው የጌታ ስቅለቱ \nዕፁብ ድንቅ እንጂ ነው የጌታ ስቅለቱ። እንዲህ በአርምሞ  \nበእንዲህንያል ምክንያት አልቀው ሕፃናቱ። የዮሴፍ ሶሎሜ \nጌታ ከነ እናቱ ሆረ ደብረ ጉስቋም። ምድረ ግብጽ ስደቱ  \nበዚያ በበረሃን በመንከራተቱን። ውኃ እየለመነች \nእመቤት እናቱን የሄሮድስን ጥፋት። ተሰማና ሞቱ \nምድረ ናዝሬት ገባች ከሕይወት ርስቱ። ከቶ አይቀርም ሞቱ \nወዲያውም ደረሰን ለመምህርነቱ። አርባ ሌሊት መዓልት  \nአርባ ሌሊት መዓልት ጾመ ወጸሎቱ። በእደ ዮሐንስ \nበባሕረ ዮርዳኖስ የጌታ ጥምቀቱ። ተጽዕኖ ገባ \nበነአስ እድገቱን ሆሣዕና ዳዊት። ለዓለም መድኃኒቱ \nኪራላይሶም ብለው ሰግደዋል ካህናቱ። ደቂቀ ሠራዊት \nአልቀሩም ዓበይቱ ጌታችን ተይዞ። በጊዜ ሠለስቱ \nወድቆ ተገረፈን ለምለም አካላቱን። ሰቀሉከ ኢየሱስ \nግፍ ዖሙ ዝንቱን ዘለፌ ወለፌ። አዕ በአንተ ማቱ \nፀሐይም ጠለቀች ሆነ እንደ ሌሊቱ። ጨረቃም ደም ሆነ \nሸሸ ብርሃናቱን ከዋክብት ረግፈው። ታጡ ካሉበቱ  \nሲገርፉት ሲያዳፉት ሲወድቅ በደረቱ። ከቶ አይቀርም ሞቱ \nበስተኋላው ቁመው ስበው ወደ አንገቱ። በስተፊቱ ቁመው \nስበው በደረቱ ስቅሎ ስቅሎ። አሉት ሲዛበቱ \nሲገርፉት ሲያዳፉት ሲወድቅ በደረቱ። በከየት ማርያም \nአዘነች እናቱ ከቶ አይቀርም ሞቱ። ምንም ቢታክቱ \nምድረ ቀራንዮ መስቀል መሰረቱ። ጌታችን ተነሣ \nበዕለተ ሰንበቱ መጎስቆሉ ቀረ። መጣ ጌትነቱ \nጽኑ ሽብር ሆነን አይሁድ ተፀፀቱ። ዲያብሎስ ድል ሆነ \nከነ ሠራዊቱ ቁልቁለት ወረደ። በመትህት ርስቱ \nአዳምን አወጣው ምስለ ብእሲቱ። ወዲያው ገነት መራው \nከቀደምት ርስቱን ዕፁብ ድንቅ እንጂ ነው። የጌታ ስቅለቱ \nከቶ አይቀርም ሞቱን ምንም ቢታክቱ። ምን ቢሰነብቱ \nከቶ አይቀርም ሞቱ ', 'am', 43, 0),\n(7, 'አስቀድሞ ትንሣኤ', 'አስቀድሞ ትንሣኤ\nአስቀድሞ ነፍሱ ሳትወጣ በፊት። \nእናቱን ቆማ ስታለቅስ ቢያያት። \nለዮሐንስ አደራ ብሎ ሰጣት። \nይርዳሽ ያጽናሽ ይህ ልጅሽ ነው አላት። \nእርሱንም ቆሞ ሲያለቅስ ቢያየው። \nቢወደው ለእናቱ አደራ ሰጠው። \nዮሐንስም እያለቀሰ በሞቱ።                         \nእናቱን ወስዶ አኖራት ከቤቱ። \nሊፈፀም የተናገረው ዳዊት። \nአይሁድ ጌታን ውኃ ጠማኝ ሲል ሰሙት። \nመጣጣውን ውኃ ቀላቅለው ሰጡት። \nቀመሰና ያን የሰጡትን ሐሞት። \nተፈፀመ ትንቢቱ ሁሉ አሁን። \nይህን ብሎ ዘለፍ አድርጎ ራሱን። \nበሥልጣኑ ከሥጋው ለያት ነፍሱን። \nበነፍስ ወርዶ ነፍሳት ካሉበት አዘቅት። \nነፍሳትን የወረዱትን ከጥንት። \nከዚያ አውጥቶ ወስዶ አገባቸው ገነት። \nተጠራጥሮ አንድ ሐራዊ ሞቱን። \nሞተ ብሎ በጦር ቢወጋው ጎኑን። \nአፈሰሰ ከውኃ ጋራ ደሙን። \nአይሁድም እርግጥ መሞቱን አውቀው።  \nሳያዝኑለት ነገ ሰንበት ነው ብለው። \nአይደር አሉ ከመስቀል ይውረድ ሥጋው። \nኒቆዲሞስ ቀድሞ በሌሊት ያየው። \nዮሴፍም በአርማትያስ ያለው። \nሞት ሳይፈሩ ከጲላጦስ ፊት ቆመው። \nተካሰሱ በድኑን እናውርድ ብለው። \nጲላጦስም ጧት ስላየው ታግሦ። \nትዕግሥቱን ጻድቅነቱን አስታውሶ። \nእንዴት ሞተ ብሎ ጠየቀ መላልሶ። \nሞተ ቢሉት እጅግ አዘነ ተከዘ። \nበድኑን ስጡ ብሎ ጭፍሮቹን አዘዘ። \nከመስቀሉ አወረዱና ሁለቱ። \nገነዙና በድርብ በፍታ በሽቱ። \nከተክል ውስጥ ከአዲስ መቃብር ቀብረውት። \nመቃብሩን በታላቅ ድንጋይ ገጠሙት። \nወልድ ጌታ በተናገረው መሰረት። \nተነሣና ኅቱም መቃብር ሳይከፍት። \nለማርያም ወዶ ተገልጦ ታያት። \nረቢ ብትል አይዞሽ ጠንክሪ አላት። \nእንዲህ ሆኖ ሞቶ ተነሥቶ በፍጥነት። \nአዳምን አገባው ከተድላ ገነት። \nየአዳም ልጆች አሁን ያላችሁ በመሬት። \nአመስግኑት ስላወጣችሁ ከእሳት። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ። \nለዘለዓለም ምስጋናህ ይብዛ ክርስቶስ። \nለዓለም ወለዓለመ ዓለም አሜን፡፡ ', 'am', 44, 0),\n(7, 'ዳግም ምጽአት', 'ዳግም ምጽአት\nእንዲህ አርገን ሥራውን ሁሉ አምነን። \nእናምናለን ዳግም ይመጣል ብለን። \nነገር ግን ዳግም ይመጣል ስላልን።                   \nከጻድቃን ከመላእክትም ቢሆን። \nየሚያውቅ የለም የሚመጣበት ቀኑን። \nባላወቅነው ባልመረመርነው ሰዓት። \nግሩም ሆኖ ይመጣል እንጂ ድንገት። \nመጀመሪያ የአዋጅ ነጋሪት ሲመታ። \nከያለበት ይሰበሰባል በአንድ አፍታ። \nአጥንታችን ትቢያ የሆነው አፈር። \nጅብ የበላው የተበተነው ከዱር። \nየራስ ፀጉር የእግር ጥፍራችን ሳይቀር። \nተሳስቶ የአንዱ ወደ አንዱ ሳይዞር። \nበየራሱ ይሰበሰባል ሁሉም። \nይመታል የአዋጅ ነጋሪት ዳግም። \nነፍስ የሌለው በድን ይሆናል ፍጹም። \nበሦስተኛው የአዋጅ ነጋሪት ሲመታ። \nይነሣሉ መልካም የሠሩ በእልልታ። \nየብርሃን አጽቅ የብርሃን ቀሚስ ለብሰው። \nእንደ ፀሐይ እንደ ጨረቃ ደምቀው። \nእግዚአብሔርን ፈጣሪያቸውን መስለው። \nይሰሙና በቀኙ ቆመው ፍርዱን። \nከማያልፈው ተድላ ደስታ በቀር።   \nጠግቦ ቁንጣን ተርቦ ስስት ሳይኖር። \nገብቶ መውጣት አግኝቶ ማጣት ችጋር። \nየሌለባት ደገኛይቱን ሀገር። \nይወርሳሉ መልካም የሠሩ በምድር። \nኃጥአንም እጅግ ከጭራ ቀጥነው። \nመልካቸውም እጅግ ከቁራ ጠቁረው። \nከላይ ከታች የጨለማ ልብስ ለብሰው። \nዲያብሎስን አለቃቸውን መስለው። \nይነሡና በግራ በኩል ቆመው። \nበመንቀጥቀጥ የሚፈርደውን ሰምተው። \nከለቅሶና ጥርስ ማፋጨት በቀር። \nተድላ ደስታ የሌለባትን ሀገር። \nይወርሳሉ ክፉ የሠሩ በምድር። \nእንዲህ አርገው መጻሕፍት ሁሉ እንዳሉ። \nበየሥራው ይከፍለዋል ለሁሉ። \nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ። \nለዓለም እስከ ዘለዓለም ድረስ። ', 'am', 45, 0),\n(7, 'ጻድቅ ኢትዮጵያ', ' ጻድቅ ኢትዮጵያ\nጻድቅ ኢትዮጵያ/፪/ ታውቋል እምነትሽ። \nየዳዊት ዘር ድጋም ሆኗል ጽሎትሽ።  \nኢትዮጵያ ብፅዕት/፪/ ጸሎት ያርግልሻል። \nእየደረሰልሽ ይኸው ያሳይሻል። \nበተገለጸልኝ /፪/ በደረስኩት ትንቢት። \nእኔን ተመርኩዘሽ ትደግሚያለሽ ዳዊት። \nመንፈሳዊ ምሥጢር/፪/ በገጽ ታስሮብን። \nቀዳማዊ ንጉሥ ተርጉሞ ፈታልን። \nሰው ምሥጢርን ሳያውቅ/፪/ እንደዚሁ እንዳይሞት። \nአትሙት እያለ እውቀት ገለጸለት። \nኢትዮጵያ ፈጭታ/፪/ የሽሮ ስጧን። \nበማይጨው ሰርታለች አጣፍጣ ወጧን። \nእናት በሞያዋ/፪/ ምስጉን የታደለች። \nየጥንስ ቅመሟን አማስላ አዋሃደች። \nከቀድሞውም ዛሬ /፪/ ሕይወት በጣም በልጧል። \nበብዙ ተማስሎ መልካም ሆኖ ጣፍጧል። \nተእሳት ይሁን ለጠብ/፪/ መክደናችኝ ይቅር። \nወጡን የሚያስማማው ማማሰያው ፍቅር። ', 'am', 46, 0),\n(7, 'ወላዲተ አምላክ', ' ወላዲተ አምላክ\nከዘመዶቼ ተጣልቼ። \nከወገኖቼም ተጣልቼ። \nየሚያስታርቀኝ ሰው አጥቼ። \nተቃጥሬያለሁ ለሐሙስ።   \nመድኃኔዓለም ድረስ። \nቅዱስ ቅዱስ ቅዱስ። \nጽላት ዘሙሴ ስልሽ። \nየአክሱም ጽዮን ስልሽ። \nወላዲተ አምላክ ስልሽ። \nእመብርሃን ስልሽ። \nበሠረገላ ሆነሽ። \nሚካኤል ገብርኤልንም ይዘሽ። \nይሸሻሉ አጋንንት አንቺን ሲያዩሽ። ', 'am', 47, 0),\n(7, 'ተውኩት', ' ተውኩት\nለገና ለጥምቀት አልልህም ጠጅ። \nደግሞም ለፋሲካ አልልህም ጠጅ። \nበዳግም ትንሣኤህ እንዳትረሳኝ እንጅ። \nተውኩት ተውኩት ተውኩት \nአምላኬን አንተ አልኩት አንቱ ማለት ጥዬ። \nመውደቅ ላይቀርልኝ ታግዬ ታግዬ። \nተውኩት ተውኩት ተውኩት \nአሁን ምን ቢሆን ነው አንዱ አንዱን አይመስል። \nግማሹ ጥሬ ነው ግማሹ ሲበስል። \nየበሰለው ያራል ጥሬውን ሲያማስል። \nተውኩት ተውኩት ተውኩት ', 'am', 48, 0),\n(7, 'አይቀርም ሞቱ', ' አይቀርም ሞቱ\nአንተ ነህ ይሉኛል/፪/ የዓለም ሁሉ ጌታ። \nሰማይና ምድርን ያቆምክ ያለዋልታ። \nአይቀርም ሞቱ ሰማይና ምድርን ያቆምክ ያለዋልታ/፪/። \nበደመነፍስ ሕይወት/፪/ ሰውን መፍጠርህ። \nእንዲጠራ እኮ ነው ቅዱሱ ስምህ።  \nአይቀርም ሞቱ እንዲጠራ እኮ ነው ቅዱሱ ስምህ/፪/። \nቤት እሠራ ብዬ/፪/ አጣና ቆርጬ መሬቱን ደልድዬ እሠራ \nእሠራ ስል ደከመ ጉልበቴ። \nአለማገር ቀረች ወይ ቤቴ ወይ ቤቴ። \nአይቀርም ሞቱ አለማገር ቀረች ወይ ቤቴ ወይ ቤቴ/፫/። \nጠማማውን እንጨት ወልጋዳውን እንጨት ጠማማውን \nእንጨት እየቆረጣችሁ። \nይህም ማገር ሆኖ ቤት ትሠራላችሁ።  \nአይቀርም ሞቱ ይህም ማገር ሆኖ ቤት ትሠራላችሁ/፪/። \nእኔ/፪/መንገደኛ እኔ መንገደኛ ተሸኝቶ አዳሪ። \nምን ክፉ አናገረኝ እንግዲህ ከቀሪ። \nያለም ሰዎች ሁሉ/፫/ያለም ዳኞች ሁሉ ሁነዋል/፫/ ጉቦኛ። \nሞት አንተ ብቻ ነህ እውነተኛ ዳኛ። ', 'am', 49, 0),\n(7, 'ድጓ ጾመ ድጓ', ' ድጓ ጾመ ድጓ\nድጓ ጾመ ድጓ ተሰቅሎ ከቤቴ። \nእኔስ የሚገርመኝ ሳልማር መቅረቴ።  \nአንተ ነህ ይሉኛል የዓለም ሁሉ ጌታ። \nሰማይና ምድርን ያቆምክ ያለዋልታ/፫/ \nወዴት እንዴት ይሆን ያለህበት ቦታ። \nእነግርህ ነበረ እኔ በቆይታ/፫/ \nየሠራችልኝን የእናትክን ወሮታ/፪/ \nእሷ ጥሩ እመቤት ቤቷ እማይፈታ/፪/ \nልጇ ፍጹም ንጉሥ የለው ባለፋንታ/፪/ \nእስኪ መከራዋን ልሁን ተናጋሪ። \nከበረት ወለደች ሆና መሽ አዳሪ። \nትንፋሽ አመጡላት ላሞች አራስ ጥሪ። \nመሆኑን አውቀውት የእነርሱ ፈጣሪ/፫/ \nእጄ አመድ አፋሽ ነው ሞት ያማኛል አሉ። \nጨርሼ ሰጥቼው ዘመዶቼን ሁሉ ወገኖቼን ሁሉ። \nሞት እንዴት ሰነበትክ እንዴት ሰንብተሃል። \nእግዚአብሔር ይመስገን ወዴት ታውቀኛለህ። \nለምን አላውቅህም አውቅሃልሁ እንጂ። \nየእናቴን የአባቴን ስትዘጋ ደጅ። \nአንተ ሁልጊዜ እንግዳ ሰው አጥፊ ነህ እንጂ/፪/ \nሞት ተመላለሰ መንገዱ አደረገኝ። \nዳግመኛም ቢመጣ ካለ እኔም አያገኝ። ', 'am', 50, 0),\n(7, 'መልካም ቤተልሔም', ' መልካም ቤተልሔም\nመልካም ቤተልሔም/፪/ መልካም ደጀ ሰላም። \nእኔ አምላክን ብሆን በጉልበቴ አልኮራም።  \nላላሰነብተው ላፈርሰው አልሠራም። \nአሸዋው ሲሚንቶው/፪/ ኖራው ተዋሕዶ። \nአጠበቀው ቤቱን እንዳይፈርስ ተንዶ። \nበሦስቱ ህብረ መልክ ጌጡ ስላማረ። \nየገቢው አታክልት ጤናአዳም ነበረ።  \nየክብር መብራቱ እሳቱ ሲቃጠል። \nአየጉድ ወይ ሰይጣን አጠፉት በቅጠል። \nሳጥናኤል ከሚስቱ ዲያብሎስ ከሚስቱ ተጣልቶ ሲፋታ። \nለሷ የደረሳት ቀሚስና ኩታ። \nቀሚስና ኩታ ለሷ ቢደርሳት ምን ያሳዝንሃል። \nብዙ ልብአልባ  አለ ላንተም ይደርስሃል።  \nእህል ታሟል አሉ/፪/ በእግሬ ልገስግስ። \nእሞት የለሁም ወይ በቅሎማ እስኪደርስ። ', 'am', 51, 0),\n(7, 'በዚህ ጊዜ', ' በዚህ ጊዜ\nበዚህ ጊዜ ምክንያት አድርጎ ቃሏን። \nበተከፍሎ ወይም በምትሃት ሳይሆን። \nትንሽ ሆኖ እንደ ሕፃናት መጠን። \nተዋሐደ ፍጹም መለኮት ሥጋን። \nእንደ አካላት የማይከፈል ከሦስት። \nመለኮት አንድ ከሆነ በእውነት። \nነሳ ስንል ፍጹም መለኮት ሥጋን።  \nእንደ አካላት መለኮትን ሦስት ካላልን። \nያሰኘናል ሥጋ ለበሱ ሦስቱም። \nመለኮት አንድ ብቻ ነው ወይም። \nእንዳትል እንዳትሳሳት በዚህም። \nመመልከት ነው የመሰልከውን ቀድመህ። \nይነግርሃል ምሳሌ ሆኖ ፀሐይ።  \nከሱም ጋራ እሳትና ነፋስ ቀላይ። \nየፀሐይ ከክበቡ ጋር ዋዕዩ። \nየእሳትም ከነበልባል ጋር ዋዕዩ። \nከዐይን ጋራ ሳይዋሐዱ ሲለዩ። \nፀሐይ እሳት በብርሃንነት ከዊን። \nለማየት እንዲዋሐዱ ከዐይን። \nልብነቷ ትንፋሽነቷ ሳይሆን። \nነፍስንም በቃልነቷ ከዊን። \nለመናገር እንዲዋሐዳት ልሳን። \nመለኮትም በቃልነቱ ከዊን። \nበልብነት በእስትንፋስነት ሳይሆን። \nተዋሐደ ፍጹም አካሉ ሥጋን። \nተለይቶ ከመንፈስ ቅዱስ ከአብ። \nተጸነሰ በማይታወቅ ጥበብ። \nተቀረጸ በማኅፀኗም አደረ። \nክብር ሳይሻ በተዋሕዶ ከበረ። \nንዴትንም የሥጋን ሁሉ ዘለፋ። \nምንታዌንም በተዋሕዶ አጠፋ። \nመልአኩም እንዲህ ከሆነ በኋላ። \nትቷት ሄደ ባለችበቱ ገሊላ። \nድንግልም ነገሩን ሰምታ በደስታ። \nየመልአኩን ድርስ ነገሩን አግኝታ። \nበዚያ ወራት ካለችበቱ ተነሥታ። \nፈጥና ሄደች ከኤልሳቤጥ ቤት ድረስ።  \nልትጠይቅ የኤልሳቤጥን መፅነስ። \nከዛም ደርሳ የኤልሳቤጥን ፊት አይታ። \nእንዴት አደርሽ ብላ ሰጠቻት ሰላምታ። \nመንፈስ ቅዱስ በኤልሳቤጥ ላይ ወረደ። \nዮሐንስም በማኅፀኗ ሰገደ። \nኤልሳቤጥም ፈጠን ብላ ተነሥታ። \nመሰከረች የመልአኩን ቃል አጉልታ። \nእመቤቴ ስትሆኝ እናቱ ለጌታ። \nበገረድ ወግ እኔ ልምጣ እንጂ ወደ አንች። \nባንቺማ ዘንድ እኔ ምንድነኝ አለች። \nተለይተሽ በዓለም ካሉ ሴቶች። \nየሌለብሽ የነፍስ የሥጋ መርገም። \nቡሩክት ነሽ የማሕፀንሽ ፍሬም። \nቡሩክ ነው መርገሙን ሁሉ ያጠፋል። \nበረከትን ለሰው ሁሉ ያድላል። \nከእግዚአብሔር ዘንድ የነገሩሽን ሰምተሽ። \nይሁንልኝ ይደረግልኝ ብለሽ። \nየምታምኚ ብፅዕት ክብርት ነሽ። \nእሷም ሰምታ የኤልሳቤጥን ነገር። \nአያይዛ ትንቢት ትናገር ጀመር። \n\nእንግዲህ ባንቺ ምስጋና አልቀር። \nተከትሎ መልአኩንና አንቺን። \nፍጥረት ሁሉ ያመሰግናል እኔን። \nሁሉ ነገር የማይሳነው ጌታዬ። \nየባሪያውን ትሕትናዋን ስላየ። ', 'am', 52, 0),\n(7, 'ኧረ ጎዳና ኧረ መንገድ', ' ኧረ ጎዳና ኧረ መንገድ\nኧረ ጎዳና ኧረ መንገድ።  \nሰው እንዳይሄድ የለም ሰው እንዳይሄድ። \nቱርክ ቢመጣ እየፎከረ። \nእንግሊዝ መጥቶ እየፎከረ። \nጣልያን በአድዋ ላይ እየፎከረ። \nጣልያን በማይጨው እየፎከረ። \nውርደቱን ቀምሶ አፍሮ እንደቀረ። \nየኢትዮጵያ ጀግና አስመሰከረ። \nአሁንም ቢሆን አንደፈርም። \nእንዋጋለን ሴቷም አትቀርም።  \nአሁንም ቢሆን የመጣው ይምጣ። \nፍርሃት የለንም ለመጣው ጣጣ። \nየኢትዮጵያ ጀግና ኮምጬ ኮምጣጣ። \nእንቆላዋለን ኣሮ እስኪንጣጣ/፪/ \n', 'am', 53, 0),\n(7, 'አዳም በበደለ', ' አዳም በበደለ\nአዳም በበደለ/፪/ ጌታ ለዓለም ክሶ።\nአዳም በበደለ ጌታ ለዓለም ክሶ።\nቆሟል ቀራንዮ ከለሜዳ ለብሶ/፪/\nቆሟል ቀራንዮ አይቀርም ሞቱ ከለሜዳ ለብሶ\nእኔ ማነው ብዬ እኔ ደሀ መስሎኝ እርቃኑን ባየው።\nየጌታ ልጅ ኖሯል የተሰቀለው የተገረፈው።\nየጌታ ልጅ ኖሯል የተገረፈው\nዘበልአ ሥጋየ ወሰትየ ደምየ ይሄሉ ምስሌኽ ብለህ ተናግረህ\nሥጋዬን የበላ ደሜንም የጠጣ ከእኔ ጋር ይኖራል ብለህ ተናግረህ\nተኮነኝ ብትለኝ ተኮነኝ ብትለኝ\nእንወርዳለን አብረን እኔ ምን ቸገረኝ\nአይቀርም ሞቱ እንወርዳለን አብረን እኔ ምን ቸገረኝ\nዓርብ የታረደውን/፪/ ምነው ባገኘሁት።\nሥጋውን በልቼ ደሙን በጠጣሁት።\nአይቀርም ሞቱ ሥጋውን በልቼ ደሙን በጠጣሁት።\nሲሆን ከሚስቴ ጋር/፪/ ሳይሆን ብቻዬን።\nሳልቀምሰው አልቀርም ሥጋሁ ደሙን/፪/\nሳልቀምሰው አልቀርም አይቀርም ሞቱ ሥጋሁ ደሙን።\nእኔም ሳላስበው እሷም ሳታስበው አየጉድ አየጉድ እንዲህ ተደረገ\nወይ አጅሬ ሰይጣን ቄስ ሆኖ አሳረገ/፪/\nወይ አጅሬ ሰይጣን ቄስ ሆኖ አሳረገ\nሥጋ አማረኝ ብለህ/፪/ አትናገር ለሰው።\nአንተም የጨዋ ልጅ ተው አርደህ ቅመሰው/፪/\nአንተም የጨዋ ልጅ ተው አርደህ ቅመሰው ', 'am', 54, 0),\n(7, 'ያለም ሰዎች ሁሉ', ' ያለም ሰዎች ሁሉ\nያለም ሰዎች ሁሉ/፪/ ሁነዋል ጉቦኛ።\nሞት አንተ ብቻ ነህ እውነተና ዳኛ/፪/\nሞት አንተ ብቻ ነህ እውነተና ዳኛ\nጠማማውን እንጨት ጎባጣውን እንጨት እየቆረጣችሁ።\nአሸዋ ስሚንቶ ደንጋዩን ፈልጣችሁ።\nይህም ማገር ሆኖ ቤት ትሠራላችሁ።\nአይቀርም ሞቱ ይህም ማገር ሆኖ ቤት ትሠራላችሁ\nሥጋዬና ነፍሴ ትግል ገጥመውብኝ ሥጋዬና ነፍሴ\nአዬጉድ አዬጉድ ወየው መከራዬ\nሞት አንተ ነህ አሉኝ መቼም ገላጋዬ።\nአይቀርም ሞቱ ሞት አንተ ነህ አሉኝ መቼም ገላጋዬ። ', 'am', 55, 0),\n(7, 'ይበላሃላ', ' ይበላሃላ\nይበላሃላ ይበላሃላ ።\nይበላሃላ ይበላሃላ።\nይበላሃላ ይበላሃላ።\nአንተንም መሬት ይበላሃላ።\nበላው አፈር በላው አፈር።\nበላው አፈር በላው አፈር።\nበላው አፈር በላው አፈር።\nያንን ጎፈሬ ያንን ከንፈር።\nለኤሊ ድንጋይ ያለበስክ አምላክ።\nለኤሊ ድንጋይ ያለበስክ አምላክ።\nአልሰማም አልከኝ እንዳንላላክ።\nለኤሊ ድንጋይ ያለበስክ አምላክ።\n', 'am', 56, 0),\n(7, 'ይበላሃላ', ' ይበላሃላ\nይበላሃላ\nይበላሃላ\nይበላሃላ\nአንተንም መሬት ይበላሃላ።\nበላው አፈር በላው አፈር።\nበላው አፈር በላው አፈር።\nበላው አፈር በላው አፈር።\nያንን ጎፈሬ ያንን ከንፈር።\n', 'am', 57, 0),\n(7, 'ዋ...እኔን', ' ዋ...እኔን\nዋ እኔን እኔን እኔን እኔን እኔን\nዋ እኔን እኔን ዋኔን እኔን እኔን... ዋ...እኔን\nዋ እኔን ሀገራችን ቆላ እኔን እኔን...\nዋ እኔን ሸንበቆው ማማሩ\nዋ እኔን እኔን እኔን እኔን...\nዋ እኔን እኔን ዋኔን እኔን እኔን... ዋ...እኔን\nዋ እኔን ሀገራችን ቆላ እኔን እኔን....\nዋ እኔን መስክ የለ ከደጅ\nዋ እኔን እንዲሁ አፈር ላፈር\nዋ እኔን እንጫወት እንጅ\nዋ እኔን እኔን ዋኔን እኔን እኔን... ዋ...እኔን\n', 'am', 58, 0),\n(7, 'ዋ...እኔን', 'ዋ...እኔን\nዋ እኔን ቤትን በሸምበቆ እኔን እኔን....\nዋ እኔን ሥራ ያለኝ ማነው\nዋ እኔን ለቆረጠማ ሰው\nዋ እኔን ያ ገዳም መልካም ነው\nዋ እኔን እኔን ዋኔን እኔን እኔን... ዋ...እኔን\nዋ እኔን እኔን እኔን እኔን...\nዋ እኔን የላዩም የታቹም\nዋ እኔን ሁሉም ያንተ ሀገር ነው\nዋ እኔን ልቤ ከወደደው\nዋ እኔን ብሰነብት ምነው\nዋ እኔን እኔን ዋኔን እኔን እኔን... ዋ...እኔን ', 'am', 59, 0),\n(7, 'አንተ ጎዳና', ' አንተ ጎዳና\nአንተ ጎዳና አንተ መንገድ\nአንተ ጎዳና አንተ መንገድ\nተው ጎዳና ኧረ መንገድ\nኧረ ጎዳና ኧረ መንገድ\nሰው እንዳይሄድ የለም ሰው እንዳይሄድ\nአንተ ጎዳና\nአንተ ጎዳና\nተው ጎዳና ተው መንገድ\nሰው እንዳይሄድ የለም ሰው እንዳይሄድ\nአንተ ጎዳና --------------------\nአንተ ጎዳና --------------------\nአንተ ጎዳና --------------------\nተው ጎዳና ተው መንገድ\nሰው እንዳይሄድ የለም ሰው እንዳይሄድ ', 'am', 60, 0),\n(7, 'ርግብና ዋኔን ቁ. ፩', 'ርግብና ዋኔን ቁ. ፩\nርግብና ዋኔን ዋኔን - አብረው ዘመቱና ዋኔን\nርግብ ደህና ገባች ዋኔን - ዋኔን ገደሉና ዋኔን\nእስቲ በስመ አብ ብዩ ዋኔን - ልቀኝ ለእመቤቴ ዋኔን\nማርያም በመሆኗ ዋኔን - ክብሬና ሕይወቴ ዋኔን\nሰላም እልሻለሁ ዋኔን - ጽላተ ጽዮን ዋኔን\nደጅ እጠናሻለሁ ዋኔን - አምኜ አንቺን ዋኔን\nአዛኝቷ እመቤት ዋኔን - ኪዳነ ምሕረት ዋኔን\nአለሁልህ ብለሽ ዋኔን - አውጪኝ ከመአት ዋኔን\nእስቲ ሁላችሁም ዋኔን - ኪዳነ ምሕረት በሉ ዋኔን\nመድኃኒት ናትና ዋኔን - ለሰው ልጆች ሁሉ ዋኔን\nሁሌ እጠራሻለሁ ዋኔን - በቃል ኪዳንሽ ዋኔን\nየምሕረት አማላጅ ዋኔን - ድንግል አንቺው ነሽ ዋኔን\nየዓለም ፈርጥ አንቺ ነሽ ዋኔን - ማርያም እመቤቴ ዋኔን\nእመካብሻለሁ ዋኔን - እስከ ጊዜ ሞቴ ዋኔን\nያንን የእሳት ባሕር ዋኔን - አሻግሪኝ ድንግል ዋኔን\nእንዳልወድቅ አደራ ዋኔን - ከሲኦል ገደል ዋኔን\nየነቢያት ትንቢት ዋኔን - የሰማዕታት አክሊል ዋኔን\nያለ አንቺ ማን አለኝ ዋኔን - እመቤቴ ድንግል ዋኔን\nበአማላጅነትሽ ዋኔን - እንኮራለን እኛ ዋኔን\nየጽድቅ መሰላል ነሽ ዋኔን - የተሰጠሽ ለእኛ ዋኔን\nያዕቆብ በሕልሙ ዋኔን - ያያት መሰላል ዋኔን\nየዓለም አስታራቂ ዋኔን - አንቺ ነሽ ድንግል ዋኔን\nታማልደናለች ዋኔን - እጆቿን ዘርግታ ዋኔን\nከቶ እረፍት የላትም ዋኔን - ከጧት እስከ ማታ ዋኔን\nኪዳነ ምሕረት ነሽ ዋኔን - አንቺ የኛ ተስፋ ዋኔን\nመርቆ የሰጠን ዋኔን - ኦሜጋና አልፋ ዋኔን\nየዓለም ሁሉ መቅረዝ ዋኔን - መንበረ ሥላሴ ዋኔን\nመድኃኒቴ እሷ ነች ዋኔን - ለሥጋም ለነፍሴ ዋኔን\nሁሌ ላመስግናት ዋኔን - ተፈታ ምላሴ ዋኔን\nየምሕረት ቃል ኪዳን ዋኔን - የሰው ልጅ መዳኛ ዋኔን\nእንድታማልደን ዋኔን - የተሰጠች ለኛ ዋኔን\nምላሴ ተናገር ዋኔን - የማርያምን ዝና ዋኔን\nለኛ መሰጠቷን ዋኔን - ሳትፈጠር ገና ዋኔን\nታስባ ስትኖር ዋኔን - በእግዚአብሔር ሕሊና ዋኔን\nተወልዳ አደገች ዋኔን - ጊዜው ደረሰና ዋኔን\nዘመን የማይሽረው ዋኔን -ስላላት ቃልኪዳን ዋኔን\nታማልደናለች ዋኔን - መድኃኒት በመሆን ዋኔን\nምን ቃላት ይገኛል ዋኔን - እርሷን ማመስገኛ ዋኔን\nእነ ሕርያቆስ ዋኔን - ያልቻሉት እነኛ ዋኔን\nከዐይኗ እያዘነበች ዋኔን - የእንባዋን ዘለላ ዋኔን\nወደ ግብጽ በረረች ዋኔን - አንድ ልጇን አዝላ ዋኔን\nፅጌ ፀዐዳ ነች ዋኔን - እመቤቴ ድንግል ዋኔን\nድረሺልኝ ሲሏት ዋኔን - ከተፍ ነው የምትል ዋኔን\nየጻድቃን እመቤት ዋኔን - የኃጥአን ተስፋ ዋኔን\nወዳንቺ እጮሃለሁ ዋኔን - ሳዝንና ስከፋ ዋኔን\nበላዔ ሰብእን ዋኔን - ያዳንሽው ድንግል ዋኔን\nለእኔም አትንፈጊኝ ዋኔን - ይህን ዕድል ዋኔን\nስንቅ የለኝ ለነፍሴ ዋኔን - እንዴት ልሆን ነው ዋኔን\nድንግል እመቤቴ ዋኔን - መግቢኝ አንቺው ዋኔን\nጥላሽን ጣይቢኝ ዋኔን - ኪዳነ ምሕረት ዋኔን\nስጨነቅ ስጠበብ ዋኔን - ሥጋለጥ ያን ዕለት ዋኔን\nድንግል መድኃኒት ነሽ ዋኔን - ለሰው ልጆች ተስፋ ዋኔን\nከጎኔ ቁሚልኝ ዋኔን - ሳዝንና ስከፋ ዋኔን\nየዓለም መድኃኒት ነሽ ዋኔን - ማርያም እመቤቴ ዋኔን\nበረድኤት ግቢልኝ ዋኔን - ነይልኝ ከቤቴ ዋኔን\nአደራሽን ማርያም ዋኔን - ኪዳነ ምሕረት ዋኔን\nፀጋሽን አልብሽኝ ዋኔን - ኋላ ሥራቆት ዋኔን\nዕርቃኔን መሆኔን ዋኔን - አውቀዋለሁና ዋኔን\nአልብሽኝ ፀጋሽን ዋኔን - በኢያቄም በሐና ዋኔን\nእስቲ ሁላችሁም ዋኔን - ኪዳነ ምሕረት በሉ ዋኔን\nመድኃኒት ናትና ዋኔን - ለሰው ልጆች ሁሉ ዋኔን\nአፍሮ አይመለስም ዋኔን - የቆመ ከደጇ ዋኔን\nእመቤቴ ማርያም ዋኔን - የጭንቅ አማላጇ ዋኔን\nየአዳም መድኃኒቱ ዋኔን - አንቺ ነሽ ድንግል ዋኔን\nበኢያቄም በሐና ዋኔን - አውጭኝ ከሲኦል ዋኔን\nአንቺ የኤዶም ገነት ዋኔን - የሰው ልጆች ተስፋ ዋኔን\nመድኃኒት ነሽና ዋኔን -አዝኖ ለተከፋ ዋኔን\nየዓለምን መድኃኒት ዋኔን - በጀርባሽ አዝለሽ ዋኔን\nኧረ ለምን ይሆን ዋኔን - ቁራሽ የለመንሽ ዋኔን\nፍግም ብዬ ልስገድ ዋኔን - ለእመቤቴ ድንግል ዋኔን\nእርሷ በመሆኗ ዋኔን - የሰው ልጆች ዕድል ዋኔን\n', 'am', 61, 0),\n(7, 'ርግብና ዋኔን ቁ. ፪', ' ርግብና ዋኔን ቁ. ፪\nርግብና ዋኔን ዋኔን - አብረው ዘመቱና ዋኔን\nርግብ ደህና ገባች ዋኔን - ዋኔን ገደሉና ዋኔን\nእስቲ በስመ አብ ብዩ ዋኔን - ልቀኝ ለእመቤቴ ዋኔን\nማርያም በመሆኗ ዋኔን - ክብሬና ሕይወቴ ዋኔን\nሰላም እልሻለሁ ዋኔን - ጽላተ ጽዮን ዋኔን\nደጅ እጠናሻለሁ ዋኔን - አምኜ አንቺን ዋኔን\nአዛኝቷ እመቤት ዋኔን - ኪዳነ ምሕረት ዋኔን\nአለሁልህ ብለሽ ዋኔን - አውጪኝ ከመአት ዋኔን\nእስቲ ሁላችሁም ዋኔን - ኪዳነ ምሕረት በሉ ዋኔን\nመድኃኒት ናትና ዋኔን - ለሰው ልጆች ሁሉ ዋኔን\nሁሌ እጠራሻለሁ ዋኔን - በቃል ኪዳንሽ ዋኔን\nየምሕረት አማላጅ ዋኔን - ድንግል አንቺው ነሽ ዋኔን\nየዓለም ፈርጥ አንቺ ነሽ ዋኔን - ማርያም እመቤቴ ዋኔን\nእመካብሻለሁ ዋኔን - እስከ ጊዜ ሞቴ ዋኔን\nያንን የእሳት ባሕር ዋኔን - አሻግሪኝ ድንግል ዋኔን\nእንዳልወድቅ አደራ ዋኔን - ከሲኦል ገደል ዋኔን\nየነቢያት ትንቢት ዋኔን - የሰማዕታት አክሊል ዋኔን\nያለ አንቺ ማን አለኝ ዋኔን - እመቤቴ ድንግል ዋኔን\nበአማላጅነትሽ ዋኔን - እንኮራለን እኛ ዋኔን\nየጽድቅ መሰላል ነሽ ዋኔን - የተሰጠሽ ለእኛ ዋኔን\nያዕቆብ በሕልሙ ዋኔን - ያያት መሰላል ዋኔን\nየዓለም አስታራቂ ዋኔን - አንቺ ነሽ ድንግል ዋኔን\nኪዳነ ምሕረት ነሽ ዋኔን - አንቺ የኛ ተስፋ ዋኔን\nመርቆ የሰጠን ዋኔን - ኦሜጋና አልፋ ዋኔን\nየዓለም ሁሉ መቅረዝ ዋኔን - መንበረ ሥላሴ ዋኔን\nመድኃኒቴ እሷ ነች ዋኔን - ለሥጋም ለነፍሴ ዋኔን\nሁሌ ላመስግናት ዋኔን - ተፈታ ምላሴ ዋኔን\nዘመን የማይሽረው ዋኔን -ስላላት ቃልኪዳን ዋኔን\nታማልደናለች ዋኔን - መድኃኒት በመሆን ዋኔን\nምን ቃላት ይገኛል ዋኔን - እርሷን ማመስገኛ ዋኔን\nእነ ሕርያቆስ ዋኔን - ያልቻሉት እነኛ ዋኔን\nፍግም ብዬ ልስገድ ዋኔን - ለእመቤቴ ድንግል ዋኔን\nእርሷ በመሆኗ ዋኔን - የሰው ልጆች ዕድል ዋኔን\n', 'am', 62, 0),\n(7, 'ርግብና ዋኔን ቁ. ፫', ' ርግብና ዋኔን ቁ. ፫\nርግብና ዋኔን ዋኔን - አብረው ዘመቱና ዋኔን\nርግብ ደህና ገባች ዋኔን - ዋኔን ገደሉና ዋኔን\nሰላምታዬን ላቅርብ ዋኔን - ልውደቅ ከፊትሽ ዋኔን\nወደር ለማይኖረው ዋኔን - ለኃያል ክብርሽ ዋኔን\nየወርቅ መሰላል ዋኔን - የመለኮት ምሥጢር ዋኔን\nየሰው ልጆች ሰላም ዋኔን - የገብርኤል መበስር ዋኔን\nየኤፍራታ አራስ ዋኔን - የበረት እመቤት ዋኔን\nየሲናዋ ድንግል ዋኔን -የእግዚአብሔር ወልድ እናት ዋኔን\nየቀራንዮ ፍሬ ዋኔን - የሥጋ ወደሙ ዋኔን\nየዓለም መዳኛ ዋኔን - የፍጥረት ዓለሙ ዋኔን\nየስንዴ አዝመራ ዋኔን - የወይን ዘለላ ዋኔን\nየምንድንብሽ ዋኔን - እርቦን ስንበላ ዋኔን\nየጎልጎታ አበባ ዋኔን - የቆሮንጦስ ፍሬ ዋኔን\nየአዳም ተስፋነትሽን ዋኔን - ልናገር መስክሬ ዋኔን\nየቅዱሳን ሀገር ዋኔን - የግሁሳን ስፍራ ዋኔን\nበሞታችን ጊዜ ዋኔን - ጨንቆን ስንጣራ ዋኔን\nድንግል ኪዳነ በትር ዋኔን - አድኝን አደራ ዋኔን\nአንቺ ርኅሩኅ እናት ዋኔን - የሁሉ መዲና ዋኔን\nየብቁኣን ምሥጢር ዋኔን - የእስራኤል መና ዋኔን\nግዞት ተፈርዶብን ዋኔን - እስከ ዘለዓለም ዋኔን\nተወልደሽ አዳንሽን ዋኔን - ልደታ ማርያም ዋኔን\nካንቺ ተጠግቼ ዋኔን - ቆሚያለሁ ተደጅሽ ዋኔን\nትባርኪኝ ብዬ ዋኔን - ድንግል ከነ ልጅሽ ዋኔን\nወዳንቺ ያዘነ ዋኔን - ማንም አላፈረ ዋኔን\nበላኤ ሰብእ እንኳን ዋኔን - በውኃ ተማረ ዋኔን\nየሁላችን ድባብ ዋኔን - የሰማይ ደመና ዋኔን\nአዛኝቷ ማርያም ዋኔን - የኢትዮጵያ ገበና ዋኔን\nእባክሽን አውርጂ ዋኔን - ናፍቀንሻልና ዋኔን\nየመናኞች ስንቅ ዋኔን -የቅዱሳን ምሳ ዋኔን\nአዛኝት ፍጥረት ሆይ ዋኔን - የሁሉ ወላንሳ ዋኔን\nብርሃንሽ ይብራልን ዋኔን - ታቦተ ጽዮን ዋኔን\nአደራ ጠብቂያት ዋኔን - ሀገራችንን ዋኔን\nንጽሕተ ንጹሐን ዋኔን - ኪዳነ ምሕረት ዋኔን\nአንቺ በመሆንሽ ዋኔን - የእግዚአብሔር እናት ዋኔን\nቃላት አላገኝም ዋኔን - እነሆ ባርያሽ ዋኔን\nአልቻልኩም ግሩም ሆይ ዋኔን - ላመሰግንሽ ዋኔን\nዝናብ ቀለም ቢሆን ዋኔን - ሰማያት ብራና ዋኔን\nስለክብርሽ ብጽፍ ዋኔን - አይበቃኝምና ዋኔን\nቅዱሳን አባቶች ዋኔን - ጥንት የነበሩት ዋኔን\nአንቺን ለማመስገን ዋኔን - ከልብ የጣሩት ዋኔን\nአላረካቸውም ዋኔን - በቃላት እጥረት ዋኔን\nከሞት ወዲያ ማዶ ዋኔን - ባሻገር ካለው ዋኔን\nተስፋዬን እንዳልቆርጥ ዋኔን - ድንግል ባንቺ ነው ዋኔን\nበሦስት ክንድ መሬት ዋኔን - መተኛት ባይቀርም ዋኔን\nአለኝታዬ አንቺው ነሽ ዋኔን - ምዋጀው አይኖረኝም ዋኔን ', 'am', 63, 0),\n(7, 'ወዳጄ ወዳጄ ቁ. ፩', ' ወዳጄ ወዳጄ ቁ. ፩\nወዳጄ ወዳጄ ወዳጄ ወዳጄ።\nወዳጅ ያዝናል እንጂ መች አብሮ ይሞታል።\nእከድ እከድዬ በዚህ ይጋተታል/፪/\nእስቲ በስመ አብ ብዬ ሰላምታ ላድርስ።\nለአብና ለወልድ ለመንፈስ ቅዱስ/፪/\nደግሞም ላመስግንህ ብዬ ሃሌ ሉያ።\nአቤቱ አድነኝ ከዓለም ገበያ/፪/\nአስረው ደበደቡት መድኃኔዓለምን።\nሰማይና ምድርን ያስታረቀውን/፪/\nተይዞ ታሰረ እንደተራ ሽፍታ።\nእውር ስላበራ ሽባ ስለፈታ/፪/\nልብሱን ተገፈፈ ቁሞ በአደባባይ።\nታስሮ ተገረፈ አጥንቱ እስኪታይ/፪/\nየእሾክ አክሊል ደፍተው ተዘባበቱበት።\nእንደ ወንጀለኛ ጥፋት ሳይኖርበት/፪/\nደብድበው ሰቀሉት መድኃኔዓለምን።\nምንድነው ጥፋቱ ከቶ ምን ይሆን/፪/\nቅዱሳት እጆቹ ተቸንክረው ዋሉ።\nቅዱሳት እግሮቹ ተቸንክረው ዋሉ።\nበጣም አልቅሱለት ሰዎች ወዮ በሉ/፪/\nእስራኤልን መና የመገበ አውርዶ።\nበግፍ ተሰቀለ ለአዳም ሲል ተዋርዶ/፪/\nመቃብር ቻለችው እንደተራ ሰው።\nአወይ መድኃኔዓለም ክርስቶስ ወየው/፪/\nየሕይወት እስትንፋስ እፍ ያለው በአዳም ላይ።\nምድረ ቀራንዮ ዋለ በመስቀል ላይ/፪/\nየተመላለሱ በገነት እግሮቹ።\nበሞት ተወሰደ ተጨፈኑ አይኖቹ/፪/\nሰማይና ምድርን በእጁ የፈጠረ።\nዓለምን ለማዳን ሞቶ ተቀበረ/፪/\nበሦስተኛውም ቀን ብርሃንን ተላብሶ።\nበኃይሉ ተነሣ መቃብር አፍርሶ/፪/\n', 'am', 64, 0),\n(7, 'ወዳጄ ወዳጄ ቁ. ፪', ' ወዳጄ ወዳጄ ቁ. ፪\nወዳጄ ወዳጄ ወዳጄ ወዳጄ።\nወዳጅ ያዝናል እንጂ መች አብሮ ይሞታል።\nእከድ እከድዬ በዚህ ይካተታል/፪/\nአንጋጥጬ ባየው ጠፋብኝ ቦታህ።\nወዴት እንዴት ይሆን መኖሪያ ስፍራህ/፪/\nቧጥጬ ቧጥጬ ወጣሁት ዳገቱን።\nላገኘው አልቻልኩም የአምላክ ማደሪያውን/፪/\nእስቲ ልፈልግህ ልፈልግህ ዞሬ።\nቢጨንቀኝ ቢጠበኝ ቢብስብኝ ዛሬ/፪/\nያልቸገረህ ነገር ሁሉ በእጅህ ሳለ።\nቸር አምላክ ነህና ብትምረኝ ምናለ/፪/\nአንተ በጥበብህ ሁሉን ማዳን ስትችል።\nታዲያ ለምን ይሆን ምሬሃለው ማትል/፪/\nስለዚህ ጌታ ሆይ ፍጥረትህን ማረው።\nእንደ በደሉማ አትመራመረው።\nቀድሞም ስትፍጥረኝ አስቀድሞ ገና።\nበደለኛነቴን ታውቀኛለህና።\nበደለኛነቴን ታውቀኛለህና/፪/\nምንም ባሳዝንህ በኃጢአት እረክሼ።\nመመለስ ታውቃለህ ልምጣ ተመልሼ/፪/\nጥንቱን ስትፈጥረው የሰው ልጅንማ።\nመሆኑን ታውቃለህ ምክር የማይሰማ።\nእኔም ባሳዝንህ ከወሰኑ አልፌ።\nትሩፋት ባልሠራም በሥጋ ሰንፌ።\nአንተ ቸር አምላክ ነህ አትጨክንምና።\nእንድራመድ አድርገኝ በፍቅርህ ጎዳና/፪/\nእኔ አንተን አምኜ ስምህን ስጠራ።\nእባክህ አምላኬ አውጣኝ ከመከራ/፪/\nአጭዶ የሚከምር ሳያበዛ ጣጣ።\nከዚህ ዓለም በሞት መወሰድ ሳይመጣ።\nቁም ነገር እንሥራ ሳለን በሕይወት።\nከቶ የለምና የሚያመልጥ ከሞት።\nሕይወት እንደ ሸክላ ተሰባሪነቱን።\nማን አውቆ ይጓዛል ረጋፊነቱን/፪/\nእንደ ጤዛ እረግፎ መጥፋቱን ቢረዳ።\nምን ጥቅም ያገኛል ሰው ሰውን ቢጎዳ/፪/\nእንደ ሸረሪት ድር እስኪጠፋ ባክኖ።\nይኖራል በጊዜው ባለው ተሸፍኖ/፪/\nዓለም ዘወርዋራ ሁሌም ወረተኛ።\nዛሬ እዚህ ነገ እዚያ ካንዴም አትተኛ/፪/\nእሷ ወረተኛ መሆኗን ሳያውቁ።\nስንት ሊቃውንቶች ጠቢባን አለቁ/፪/\nበዓለም መድረክ ታይተው ወዲያው የጠፉትን።\nቤቱ ይቁጠራቸው በሞት ያለፉትን/፪/\nእንደ ቅጠል እረግፎ የሰው ልጅ ዛላው።\nይጠፋል ከዓለም ላይ ቀኑን ሳያውቀው/፪/\nታይተን እስክንጠፋ እስከዚያው ድረስ።\nበፍቅር በሰላም እድሜ እንጨርስ/፪/\n', 'am', 65, 0),\n(7, 'ወዳጄ ወዳጄ ቁ. ፫', ' ወዳጄ ወዳጄ ቁ. ፫\nወዳጄ ወዳጄ ወዳጄ ወዳጄ።\nወዳጅ ያዝናል እንጂ መች አብሮ ይሞታል።\nእከድ እከድዬ በዚህ ይካተታል/፪/\nእስቲ በስመ አብ ብዬ ሰላምታ ላድርስ።\nለአብና ለወልድ ለመንፈስ ቅዱስ/፪/\nመከራው ሲወሳ የመድኃኔዓለም።\nእጅግ ያስለቅሳል እስከ ዘለዓለም/፪/\nግንድ ተሸክሞ አሸርጦ ጨርቅ።\nመከራው በዝቶበት ሲነሳ ሲወድቅ/፪/\nወጣ ቀራንዮ ከተራራው ላይ።\nመከራ ሊቀበል ለሰው ልጅ ሲሳይ/፪/\nእርቃኑን ሳያፍር በጀርባው ተንጋሎ።\nዋለ ተቸንክሮ ፍጹም ምስኪን መስሎ/፪/\nሰማያት ተናጉ ተናወጸ ምድር።\nአይሁድ ያልጠበቁት ብዙ ታየ ተአምር/፪/\nበጣም ተንቀጥቅጣ ግዑዟ መሬት።\nየኢየሱስን መስቀል መያዝ አቃታት/፪/\nጨረቃና ፀሐይ ደግሞም ከዋክብት።\nመስክሩ በተርታ የጌታን ስቅለት/፪/\nሰማይና ምድር እናንተም መስክሩ።\nየጌታን ትንሣኤ ለዓለም ሁሉ አውሩ/፪/\nአምላክ ለኛ ብሎ በመስቀል ላይ ሞቶ።\nፀሐይ በማየቷ ጌታዋ ተራቁቶ/፪/\nብርሃኗን ነፈገች ተሳቃና ፈርታ።\nተራቁቶ ስላየች ጌታ በአዳም ፋንታ/፪/\nጨረቃም ደም ሆነች ከዋክብት ረገፉ።\nሐሞት ስለጋቱት በከበረ አፉ/፪/\nየከበረ ሥጋው በችንካር ተቆርሶ።\nዓለምን አዳነ ደሙንም አፍስሶ/፪/\nዋለ ቀራንዮ ክርስቶስ ተሰቅሎ።\nእኛኑ ለማዳን ለሰው ልጆች ብሎ/፪/\nቀራንዮ ዋለ ተሰቅሎ እንደዋዛ።\nከኃጢአት አላቆ ነፍሳትን ሊገዛ/፪/\nግንድ ተሸክሞ ሲወድቅ ሲነሳ።\nዓለምን አዳነ ከኃጢአት አበሳ/፪/\nእውራንን ዳሰው ያበሩ ጣቶቹ።\nበደም ተለወሱ ቅዱሳት እጆቹ/፪/\nሁሉን ማድረግ ሲችል ለአዳም ሲል ተዋርዶ።\nተቀበረ ሥጋው ከሰማያት ወርዶ/፪/\nለፍርድ መመለሱን ሰማያት መስክሩ።\nአስጠንቅቁ ለዓለም ለሕዝቡም ንገሩ/፪/\nሕዝቦች ተጠንቀቁ እንዳትታለሉ።\nለፍርድ መምጣቱንም ንገሩ ለሁሉ/፪/\nበግራ እንዳንቆም ተራቁተን ከፀጋ።\nበንስሐ ታጥበን በጸሎት እንትጋ/፪/\nየአዋጅ ድምጽ ሲነገር ፍርድ ሲያስተጋባ።\nበቀኝህ አቁመን በጭንቅ እንዳንገባ/፪/\nወዮ በዚያን ዕለት በክብር ሲገለጥ።\nየት እንገባ ይሆን ወዴትስ ለማምለጥ/፪/\nበስምንተኛው ሺህ ዓለም ሲፈራርስ።\nበጽድቅህ አስበን አቤቱ ክርስቶስ/፪/\nበዳግመኛ ልደት ሙታኖች ሲነሱ።\nበቃልህ ሲገፈፍ የሰማያት ልብሱ/፪/\nምድርና ሰማይ ከቦታው ሲጠፋ።\nአድነን ጌታ ሆይ መለከት ሲነፋ/፪/\nያኔ ስትገለጥ በታላቁ ክብርህ።\nአድነን ክርስቶስ ጌታ ሆይ እባክህ/፪/\nበመንግሥተ ሰማይ በማያልፈው ስፍራ።\nበክብር በደስታ አስቀምጠን አደራ/፪/\nሰማያት ሲናጋ ምድሩ ሲፈራርስ።\nአቤቱ አድነን ጌታ ሆይ ክርስቶስ/፪/\nውጡ ግቡ ብለህ ሁሉን ስታደራጅ።\nቸር አምላክ ነህና አታስቀረን ከደጅ/፪/\nያለ ነው ከጥንትም ዛሬም ቸርነትህ።\nአታሳጣን ስፍራ ከሰፊው መንግሥትህ/፪/\nዋጋ ስትከፍል እንደየሥራችን።\nበግራ አታቁመን አደራ አባታችን/፪/\nነጋሪት ሲጎሰም መለከት ሲነፋ።\nሁሉን ቻይ ነህና በከንቱ እንዳንጠፋ/፪/\nሰማይ ምድር ፈርሶ መድረሻ ሲጠፋን።\nቸር አምላክ ነህና ጨክነህ አታጥፋን/፪/\nከገሃነም ቦታ እጅግ ከሚያስፈራ።\nአድነን ጌታ ሆይ ከእንዲህ ያለ ስፍራ/፪/\nተማፅነን ወድቀናል በቆረስከው ሥጋህ።\nተማፅነን ወድቀናል ባፈሰስከው ደምህ።\nተማፅነን ወድቀናል በማይሻር ቃልህ።\nበቀኝህ አቁመን ክርስቶስ አደራ/፪/\nይህን ጊዜ እንበርታ ሳለን በሕይወት።\nጉድ እንዳያደርገን መቶ በድንገት/፪/\nከደጅሽ ቆሚያለሁ ኪዳነ ምሕረት።\nታማልጂኝ ብዬ ደጅ በመጽናት/፪/\nለፍርድ ሲገለጥ ልጅሽ በዚያን ዕለት።\nእንድታማልጂን አደራሽን እመቤት/፪/\nኪዳነ ምሕረት ነሽ የዓለም ሁሉ ቤዛ።\nሰማይና ምድርን ልጅሽ የሚገዛ/፪/\nበምድራዊም ሆነ በፈተና ቦታ።\nማርያም ትጠብቀን እጆቿን ዘርግታ/፪/\nእንዴት እድናለሁ በየቱ ብልሃቴ።\nአንቺ ካልጠበቅሽኝ ማርያም እመቤቴ/፪/\nእመቤቴ ማርያም ምሥጢሬ ነሽና።\nከሥጋዬ አድኚኝ በረድኤት ነይና/፪/\nክርስቶስ አምላኬ የዓለም ብርሃን።\nበረድኤት ናና ሁልጊዜ ባርከን/፪/\nበመስቀልህ ብርሃን ባርከህ ቀድሰን።\nበሥጋ በደምህ ዘወትር አድሰን/፪/\nበወንጌልህ ፀጋ ሁሌ እንድናበራ።\nመትጋቱን አድለን ጌታ ሆይ አደራ/፪/\n', 'am', 66, 0),\n(7, 'እስመ አንተ', ' እስመ አንተ\nበስመ አብ ወወልድ ወመንፈስ ቅዱስ።\nአሐዱ አምላክ ብዬ ሰላምታ ላድርስ።\nእስመ አንተ አምላከ ሰማይ ወምድር።\nስብሐት ለከ ምሉዕ ፀጋ ወክብር።\nትባላለህ ቀንና ሌሊት ዘወትር።\nክርስቶስ የዓለማት ሁሉ ንጉሥ።\nዘለዓለም ክብርህ ገናና አይቀንስ።\nብርቱ ዳኛ ያለ አንተ የለም ኃይለኛ።\nትገድላለህ ምንም ሳያመው ሳይተኛ።\nስታፈቅር ሁሉ ይሆናል ዘመድ።\nብሉ ጠጡ ልበሱ ይላል የግድ።\nአንተ ስትጠላ ወዳጅ ይሆናል ጠላት።\nይንቁታል ከውጪም ሆነ ከቤት።\nትገድላለህ ጧትና ማታ ሳትል።\nሳይታመም ጤና ሳያጣ ሳይዝል።\nስታድን ስትመልስማ ፊትህን።\nበመፃጉዕ ሰምተነው የለ ልኩን።\nከመቃብር አልዓዛር ውጣ ብለህ።\nስላዘዝከው በመለኮቱ ቃልህ።\nከሙታን በአራተኛው ቀን ተነሥቶ።\nሕያው ሆነ መሞቱን እንኳን ረስቶ።\nእንደዚህ ነው የመድኃኔዓለም ምሕረቱ።\nእንዲጎዳ አይወድምና ፍጥረቱ።\nቀንና ሌት ከቶ ሳይኖረን እረፍት።\nእየሠራን እንደዚህ ሁሉ ኃጢአት።\nተመልከቱ የጌታችንን ምሕረት።\nመቼ ይወዳል ብንወርድበት ከእሳት።\nእኛ ግን ከኃጢአታችን ብዛት።\nእንወርዳለን ከዚያ ጨለማ ክርፋት።\nፈጣሪዬ በከንቱ አለቀች እድሜዬ።\nሳልገዛ እያሸነፈኝ ሥጋዬ።\nጌታ ሆይ አዛኝ ርኅሩኅ ነህና።\nአደራህን በነፍሴ ነገር አትጽና።\nመበስበስ አለብንና መፍረስ።\nመራራው ሞት በድንገት ፈጥኖ ሲደርስ።\nመነሳት አለብን ፍርዱን መስማት።\nየዚያን ዕለት ድብልቅልቅ ሲሆን ጭንቀት።\nአደራህን ነፍሴን አድርጋት ወዳንተ።\nበሐዲቱ እስመ ለዓለም ምሕረቱ።\nማን አለና ያለ አንተ ጌታ በብርቱ።\nይኄይስ እምነ ኩሉ ንጉሥ።\nስብሐት ለአብ ወወልድ ወመንፈስ ቅዱስ።\nለዓለም እስከ ዘለዓለም ድረስ።', 'am', 67, 0),\n(7, 'ገብረ መንፈስ ቅዱስ', ' ገብረ መንፈስ ቅዱስ\nገብረ መንፈስ ቅዱስ አቡዬ ጻድቁ።\nኧረ እንዴት ነሁ አባቴ ኧረ እንዴት ነሁ መድኃኒቴ\nገደል እንደ አክርማ የሚሰነጥቁ።\nኧረ እንዴት ነሁ አባቴ ኧረ እንዴት ነሁ መድኃኒቴ\nገብረ መንፈስ ቅዱስ ተክለሃይማኖት።\nኧረ እንዴት ነሁ አባቴ ኧረ እንዴት ነሁ መድኃኒቴ\nታላቅ ክብር ያገኙ በክርስቶስ ፊት።\nኧረ እንዴት ነሁ አባቴ ኧረ እንዴት ነሁ መድኃኒቴ\nለጌታቸ